'          end d,',
'       e.id r',
'  from imp_entrega e',
' where e.id_tenant = :P429_ID_TENANT',
'   and (:P429_ID_PEDIDOIMPORTACAO is null or e.id_pedidoimportacao = :P429_ID_PEDIDOIMPORTACAO)',
' order by e.num_entrega'))
