 p_id=>wwv_flow_imp.id(187121853409303320)
,p_lov_name=>'R_NG_CIDADE.NOME_CIDADE-ID_ESTADO'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d, r from (',
'    select null d, null r, 0 ordem from dual',
'    union all',
'select ',
'    case ',
'        when a.id_estado is null then    ',
'            pkg_traducao.get_traducao(a.nome_cidade)',
'        else',
'            pkg_traducao.get_traducao(a.nome_cidade) || '' - '' || b.sigla_uf',
'    end, a.id, 1 ',
