prompt --application/shared_components/navigation/search_config/menu
begin
wwv_flow_imp_shared.create_search_config(
 p_id=>wwv_flow_imp.id(185361812919277926)
,p_label=>'Menu'
,p_static_id=>'menu'
,p_search_type=>'SIMPLE'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    1 "level",',
'    pkg_ui.retorna_titulo_menu(a.id) || case when c.codigo_artefato is not null then '' (''||c.codigo_artefato||'')'' else '''' end "label",',
'    case when a.id = b.id_menu then ''f?p=&APP_ID.:''||case when c.tipo = ''CD'' then e.codigo_artefato else c.codigo_artefato end||'':&SESSION.::NO:''||case when c.tipo = ''CD'' then e.codigo_artefato else c.codigo_artefato end||'':A_RESET_BREADCRUMB1,P0_COD'
||'IGO_ARTEFATO,P''||case when c.tipo = ''CD'' then e.codigo_artefato else c.codigo_artefato end||''_CODIGO_ARTEFATO:Y,''||c.codigo_artefato||'',''||c.codigo_artefato',
'    else ''f?p=&APP_ID.:3:&SESSION.::NO::A_RESET_BREADCRUMB1,P0_CODIGO_ARTEFATO,P3_CODIGO_ARTEFATO,P3_MENU_TITULO:Y,''||c.codigo_artefato||'',''||c.codigo_artefato||'',''||a.titulo end as target,    ',
'    case when :P0_CODIGO_ARTEFATO = c.codigo_artefato then ''YES'' else ''NO'' end as is_current,',
'    case when PKG_CONTROLE_ACESSO.retorno_verifica_permissao(:APP_USER,c.codigo_artefato) = ''true'' then a.icone else case when c.codigo_artefato is null then a.icone else ''fa-lock'' end end as image',
'    from mpd_menu a',
'left join mpd_menu_acao b on b.id_menu = a.id',
'left join mpd_funcionalidade c on c.id = b.id_funcionalidade',
'left join mpd_funcionalidade_tela_dinamica d on d.id_funcionalidade = c.id',
'left join mpd_funcionalidade e on e.id = d.id_funcionalidade_base',
'left join srv_menu a1 on a1.id = a.id            ',
'left join srv_sistema_versionado b1 on b1.id = a1.id_sistema_versionado            ',
'left join srv_sistema c1 on c1.id = b1.id_sistema',
'where /*a.id = b.id_menu*/ a.id_nivel_pai in (select id from mpd_menu where lower(titulo) = lower(:P3_MENU_TITULO))',
'and upper(c1.codigo_sistema) = upper(:app_name)',
'start with',
'    id_nivel_pai is null',
'connect by',
'    prior a.id = a.id_nivel_pai ',
'    order by a.ordenacao'))
,p_searchable_columns=>'label'
,p_pk_column_name=>'level'
,p_title_column_name=>'label'
,p_icon_source_type=>'INITIALS'
,p_version_scn=>44589877577907
);
end;
/
