wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(211452890162862601)
,p_event_id=>wwv_flow_imp.id(524964395292301584)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Breadcrumb'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function () {',
'',
'    console.log("[NGBreadcrumb] Page Load iniciado");',
'',
'    const resetBreadcrumb = $v("P0_RESET_BREADCRUMB");',
'',
'    console.log("[NGBreadcrumb] Valor P0_RESET_BREADCRUMB:", resetBreadcrumb);',
'',
'    if (',
'        resetBreadcrumb !== "S" &&',
'        NGBreadcrumb.isNavegacaoHistoricoBrowser &&',
'        NGBreadcrumb.isNavegacaoHistoricoBrowser()',
'    ) {',
unistr('        console.log("[NGBreadcrumb] Navega\00E7\00E3o via hist\00F3rico do navegador detectada.");'),
'',
'        const restaurou = NGBreadcrumb.restaurarSnapshotPaginaAtual();',
'',
'        if (restaurou) {',
'            console.log("[NGBreadcrumb] Snapshot restaurado. Registro normal cancelado.");',
'            return;',
'        }',
'    }',
'',
'    if (resetBreadcrumb === "S") {',
'        console.log("[NGBreadcrumb] Reset solicitado pelo menu");',
'',
'        NGBreadcrumb.limpar();',
'',
'        if (NGBreadcrumb.limparContextoAtual) {',
'            NGBreadcrumb.limparContextoAtual();',
'        }',
'',
'        $s("P0_RESET_BREADCRUMB", "");',
'',
'        apex.server.process(',
'            "LIMPAR_RESET_BREADCRUMB",',
'            {},',
'            {',
'                dataType: "text",',
'                success: function () {',
'                    console.log("[NGBreadcrumb] P0_RESET_BREADCRUMB limpo no Session State");',
'                },',
'                error: function (jqXHR, textStatus, errorThrown) {',
'                    console.error("[NGBreadcrumb] Erro ao limpar P0_RESET_BREADCRUMB no Session State:", {',
'                        textStatus: textStatus,',
'                        errorThrown: errorThrown,',
'                        responseText: jqXHR.responseText',
'                    });',
'                }',
'            }',
'        );',
'',
'        console.log("[NGBreadcrumb] Reset executado e limpeza solicitada ao servidor");',
'    }',
'',
'    const contexto = NGBreadcrumb.getContextoAtual',
'        ? NGBreadcrumb.getContextoAtual()',
'        : null;',
'',
'    const codigoArtefatoUrl = NGBreadcrumb.getCodigoArtefatoDaUrl',
'        ? NGBreadcrumb.getCodigoArtefatoDaUrl()',
'        : null;',
'',
'    const codigoArtefato =',
'        codigoArtefatoUrl ||',
'        (contexto && contexto.codigoArtefato) ||',
'        $v("P0_CODIGO_ARTEFATO");',
'',
'    const tituloArtefato =',
'        (contexto && contexto.tituloArtefato) ||',
'        obterTituloTela() ||',
'        $v("P0_TITULO_TELA") ||',
'        codigoArtefato;',
'',
'    console.log("[NGBreadcrumb] Dados usados no registro:", {',
'        resetBreadcrumb: resetBreadcrumb,',
'        contexto: contexto,',
'        codigoArtefatoUrl: codigoArtefatoUrl,',
'        codigoArtefatoUsado: codigoArtefato,',
'        tituloArtefatoUsado: tituloArtefato,',
'        p0CodigoArtefato: $v("P0_CODIGO_ARTEFATO"),',
'        p0TituloArtefato: $v("P0_TITULO_TELA"),',
'        pageId: "&APP_PAGE_ID.",',
'        url: window.location.href',
'    });',
'',
'    NGBreadcrumb.registrarAtual({',
'        codigoArtefato: codigoArtefato,',
'        titulo: tituloArtefato,',
'        pageId: "&APP_PAGE_ID.",',
'        url: window.location.href',
'    });',
'',
'    function obterTituloTela() {',
'        console.log("[NGBreadcrumb] obterTituloTela() chamado");',
'',
'        const seletores = [',
'            ".t-Body-title h1",',
'            ".t-Body-title",',
'            "h1",',
'            ".t-BreadcrumbRegion-title h1",',
'            ".t-Region-title"',
'        ];',
'',
'        for (const seletor of seletores) {',
'            const el = document.querySelector(seletor);',
'',
'            if (el && el.textContent && el.textContent.trim()) {',
'                const titulo = el.textContent.trim();',
'',
unistr('                console.log("[NGBreadcrumb] T\00EDtulo encontrado:", {'),
'                    seletor: seletor,',
'                    titulo: titulo',
'                });',
'',
'                if (',
unistr('                    titulo !== "T\00EDtulo din\00E2mico" &&'),
unistr('                    titulo !== "Titulo din\00E2mico" &&'),
'                    titulo !== "undefined"',
'                ) {',
'                    return titulo;',
'                }',
'            }',
'        }',
'',
'        return null;',
'    }',
'',
'})();'))
);
