wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(142140826575150722)
,p_plug_name=>'Cards importacao'
,p_region_template_options=>'#DEFAULT#:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529595230508986982)
,p_plug_display_sequence=>90
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH status_base AS (',
'    SELECT 10 ind_status, 1 ordem FROM dual UNION ALL',
'    SELECT 1, 2 FROM dual UNION ALL',
'    SELECT 2, 3 FROM dual UNION ALL',
'    SELECT 3, 4 FROM dual UNION ALL',
'    SELECT 4, 5 FROM dual UNION ALL',
'    SELECT 5, 6 FROM dual UNION ALL',
'    SELECT 6, 7 FROM dual',
'),',
'dominio AS (',
'    SELECT ',
'        r AS ind_status,',
'        d AS label',
'    FROM TABLE(pkg_util.dominio_retorna_lista(''imp_processoimportacao'',''ind_status''))',
')',
'SELECT ',
'    s.ind_status,',
'    d.label,',
'    s.ordem,',
'    COUNT(p.id) quantidade,',
'',
'    CASE s.ordem',
'        WHEN 1 THEN ''card-cor-1''',
'        WHEN 2 THEN ''card-cor-2''',
'        WHEN 3 THEN ''card-cor-3''',
'        WHEN 4 THEN ''card-cor-4''',
'        WHEN 5 THEN ''card-cor-5''',
'        WHEN 6 THEN ''card-cor-6''',
'        WHEN 7 THEN ''card-cor-7''',
'    END AS css_class',
'',
'FROM status_base s',
'',
'LEFT JOIN dominio d ON d.ind_status = s.ind_status',
'',
'LEFT JOIN imp_processoimportacao p ON p.ind_status = s.ind_status',
'',
'GROUP BY s.ind_status, d.label, s.ordem',
'ORDER BY s.ordem'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
);
