,p_plug_display_sequence=>70
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_qtd_firmar NUMBER;',
'    l_qtd_saldo  NUMBER;',
'    l_url_firmar VARCHAR2(4000);',
'    l_url_saldo  VARCHAR2(4000);',
'    l_html       CLOB;',
'    l_label_pedido_importacao varchar2(100);',
'    l_label_aguardando varchar2(100);',
'    l_label_firmar varchar2(100);',
'    l_label_saldo_programar varchar2(100);',
'BEGIN',
'    -- consultas',
'    SELECT COUNT(*) INTO l_qtd_firmar FROM imp_pedidoimportacao WHERE ind_status_pedido_importacao = 2;',
'    SELECT COUNT(*) INTO l_qtd_saldo FROM imp_pedidoimportacao WHERE ind_todos_itens_com_entregas_programadas = ''N'';',
'    l_label_pedido_importacao   := pkg_ui.retorna_label_tela(''pedido_importacao'');',
'    l_label_aguardando          := pkg_ui.retorna_label_tela(''aguardando'');',
'    l_label_firmar              := pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'',''ind_status_pedido_importacao'', 2);',
'    l_label_saldo_programar     := pkg_ui.retorna_label_tela(''saldo_programar'');',
'',
'    -- URL''s',
'    l_url_firmar := apex_page.get_url(',
'        p_page   => 9005,',
'        p_clear_cache => 9005,',
'        p_items  => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_LISTA3,P9005_FILTRO_CARD3'',',
'        p_values => ''Y,TD343,2,2,,''',
'    );',
'    l_url_saldo := apex_page.get_url(',
'        p_page   => 9005,',
'        p_clear_cache => 9005,',
'        p_items  => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_LISTA3,P9005_FILTRO_CARD3'',',
'        p_values => ''Y,TD343,,,N,N''',
'    );',
'',
'    -- html',
'    l_html := q''[',
'        <div class="card-bloco">',
'            <div class="card-titulo">]'' || l_label_pedido_importacao || q''[</div>',
'            <div class="card-subnivel">',
'                <div class="card-subtitulo">]'' || l_label_aguardando || q''[</div>',
'                <div class="card-itens">',
'                    <a class="card-item" ]'' || CASE WHEN l_qtd_firmar > 0 THEN ''href="'' || l_url_firmar || ''"'' ELSE '''' END || q''[>',
'                        <span class="qtd">]'' || l_qtd_firmar || q''[</span>',
'                        <span class="label">]'' || l_label_firmar || q''[</span>',
'                    </a>',
'                    <a class="card-item" ]'' || CASE WHEN l_qtd_saldo > 0 THEN ''href="'' || l_url_saldo || ''"'' ELSE '''' END || q''[>',
'                        <span class="qtd">]'' || l_qtd_saldo || q''[</span>',
'                        <span class="label">]'' || l_label_saldo_programar || q''[</span>',
'                    </a>',
'                </div>',
'            </div>',
'        </div>',
'    ]'';',
'',
'    htp.p(l_html);',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
);
