'--         else',
'--             l_class := ''bloco-alerta-item is-disabled'';',
'--             l_href  := null;',
'--         end if;',
'',
'--         return ''',
'--             <a class="'' || l_class || ''"'' || l_href || ''>',
'--                 <div class="bloco-alerta-info">',
'--                     <span class="bloco-alerta-status">''',
'--                         || apex_escape.html(nvl(p_status, ''Aguardando'')) ||',
'--                     ''</span>',
'',
'--                     <span class="bloco-alerta-label">''',
unistr('--                         || apex_escape.html(nvl(p_label, ''Aprova\00E7\00E3o'')) ||'),
'--                     ''</span>',
'--                 </div>',
'',
'--                 <span class="bloco-alerta-qtd">''',
'--                     || to_char(nvl(p_qtd, 0)) ||',
'--                 ''</span>',
'--             </a>'';',
'--     end render_item_invoice;',
'',
'-- begin',
'--     select count(*)',
'--       into l_qtd_aprovacao',
'--       from imp_invoice',
'--      where ind_status = 2;',
'',
'--     l_label_invoice := pkg_ui.retorna_label_tela(''invoice'');',
'',
'--     l_label_aguardando := pkg_ui.retorna_label_tela(''aguardando'');',
'',
'--     l_label_aprovacao := pkg_ui.retorna_label_tela(''aprovacao'');',
'',
'--     l_url_aprovacao := apex_page.get_url(',
