'--             <div class="alerta-card-header">',
'--                 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'--                      stroke-width="2" stroke-linecap="round" stroke-linejoin="round">',
'--                     <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>',
'--                     <path d="M14 2v6h6"></path>',
'--                     <path d="M8 13h8"></path>',
'--                     <path d="M8 17h5"></path>',
'--                 </svg>',
'',
'--                 <span>''',
'--                     || apex_escape.html(nvl(l_label_invoice, ''Invoice'')) ||',
'--                 ''</span>',
'--             </div>',
'',
'--             <div class="bloco-alerta-body">''',
'--                 || render_item_invoice(',
'--                     p_qtd    => l_qtd_aprovacao,',
'--                     p_status => l_label_aguardando,',
'--                     p_label  => l_label_aprovacao,',
'--                     p_url    => l_url_aprovacao',
'--                 ) ||',
'--             ''</div>',
'--         </div>'';',
'',
'--     return l_html;',
'-- end;',
'',
'declare',
'    l_qtd_aprovacao    number;',
'    l_url_aprovacao    varchar2(4000);',
'    l_html             clob;',
'',
'    l_label_invoice    varchar2(100);',
'    l_label_aguardando varchar2(100);',
'    l_label_aprovacao  varchar2(100);',
'',
'    function render_icone_invoice',
'    return clob',
'    is',
'    begin',
'        return q''~',
'            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                 stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                 aria-hidden="true">',
'                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>',
'                <path d="M14 2v6h6"></path>',
'                <path d="M9 15l2 2 4-4"></path>',
'            </svg>',
'        ~'';',
'    end render_icone_invoice;',
'',
'    function render_card_invoice(',
'        p_qtd    in number,',
'        p_titulo in varchar2,',
'        p_status in varchar2,',
'        p_badge  in varchar2,',
'        p_url    in varchar2',
'    ) return clob',
'    is',
'        l_class varchar2(200);',
'        l_href  varchar2(4000);',
'    begin',
'        if nvl(p_qtd, 0) > 0 then',
'            l_class := ''card-resumo-invoice'';',
'            l_href  := '' href="'' || apex_escape.html_attribute(p_url) || ''"'';',
'        else',
'            l_class := ''card-resumo-invoice is-disabled'';',
'            l_href  := null;',
'        end if;',
'',
'        return ''',
'            <a class="'' || l_class || ''"'' || l_href || ''>',
'                <div class="card-resumo-topo">',
'                    <div class="card-resumo-topo-info">',
'                        <div class="card-resumo-icone">''',
'                            || render_icone_invoice ||',
'                        ''</div>',
'                        <div class="card-resumo-conteudo">',
'                            <h3 class="card-resumo-titulo">''',
'                                || apex_escape.html(nvl(p_titulo, ''Invoice'')) ||',
'                            ''</h3>',
'',
'                            <div class="card-resumo-status">''',
unistr('                                || apex_escape.html(nvl(p_status, ''Aguardando / Aprova\00E7\00E3o'')) ||'),
'                            ''</div>',
'                        </div>',
'                    </div>',
'                </div>',
'',
'',
'                <div class="card-resumo-rodape">',
'                    <span class="card-resumo-qtd">''',
'                        || to_char(nvl(p_qtd, 0)) || '' '' ||',
'                        case',
'                            when nvl(p_qtd, 0) = 1 then ''Invoice''',
'                            else ''Invoices''',
'                        end ||',
'                    ''</span>',
'                </div>',
'            </a>'';',
'    end render_card_invoice;',
'',
'begin',
'    select count(*)',
'      into l_qtd_aprovacao',
'      from imp_invoice',
'     where ind_status = 2;',
'',
'    l_label_invoice    := pkg_ui.retorna_label_tela(''invoice'');',
'    l_label_aguardando := pkg_ui.retorna_label_tela(''aguardando'');',
'    l_label_aprovacao  := pkg_ui.retorna_label_tela(''aprovacao'');',
'',
'    l_url_aprovacao := apex_page.get_url(',
'        p_page        => 2,',
'        p_clear_cache => ''2''',
'    );',
'',
'    l_html := render_card_invoice(',
'        p_qtd    => l_qtd_aprovacao,',
'        p_titulo => l_label_invoice,',
'        p_status => l_label_aguardando || '' / '' || l_label_aprovacao,',
'        p_badge  => ''INVOICE'',',
'        p_url    => l_url_aprovacao',
'    );',
'',
'    return l_html;',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(142141520463150729)
