,p_parent_plug_id=>wwv_flow_imp.id(142141208902150726)
,p_region_template_options=>'#DEFAULT#:margin-bottom-sm'
,p_plug_template=>wwv_flow_imp.id(529588161801986979)
,p_plug_display_sequence=>20
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_qtd_aprovacao              number;',
'    l_url_aprovacao              varchar2(4000);',
'',
'    l_qtd_documento_pedido       number;',
'    l_url_documento_pedido       varchar2(4000);',
'',
'    l_qtd_documento_importacao   number;',
'    l_url_documento_importacao   varchar2(4000);',
'',
'    l_qtd_total                  number;',
'',
'    l_html                       clob;',
'',
'    l_label_anexo                varchar2(100);',
'    l_label_pendente             varchar2(100);',
'    l_label_aprovacao            varchar2(100);',
'    l_label_documento_pedido     varchar2(100);',
'    l_label_documento_importacao varchar2(100);',
'',
'    function render_icone_anexo',
'    return clob',
'    is',
'    begin',
'        return q''~',
'            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                 stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                 aria-hidden="true">',
'                <path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"></path>',
'            </svg>',
'        ~'';',
'    end render_icone_anexo;',
'',
'    function render_indicador(',
'        p_qtd   in number,',
'        p_label in varchar2,',
'        p_url   in varchar2',
'    ) return clob',
'    is',
'        l_class varchar2(200);',
'        l_href  varchar2(4000);',
'    begin',
'        if nvl(p_qtd, 0) > 0 then',
'            l_class := ''card-resumo-indicador'';',
'            l_href  := '' href="'' || apex_escape.html_attribute(p_url) || ''"'';',
'        else',
'            l_class := ''card-resumo-indicador is-disabled'';',
'            l_href  := null;',
'        end if;',
'',
'        return ''',
'            <a class="'' || l_class || ''"'' || l_href || ''>',
'                <span class="card-resumo-indicador-label">''',
unistr('                    || apex_escape.html(nvl(p_label, ''Sem descri\00E7\00E3o'')) ||'),
'                ''</span>',
'                <span class="card-resumo-indicador-qtd">''',
'                    || to_char(nvl(p_qtd, 0)) ||',
'                ''</span>',
'            </a>'';',
'    end render_indicador;',
