'begin',
'    select count(*)',
'      into l_qtd_aprovacao',
'      from ng_anexo a',
'      join ng_documento d',
'        on d.id = a.id_documento',
'     where a.ind_situacao = ''1''',
'       and d.ind_aprovar = ''S'';',
'',
'    select count(*)',
'      into l_qtd_documento_pedido',
'      from imp_pedidoimportacao p',
'     where exists (',
'            select 1',
'              from ng_documento d',
'             where d.id_entidade = 24',
'               and d.ind_obrigatorio = ''S''',
'               and not exists (',
'                    select 1',
'                      from ng_anexo a',
'                     where a.id_documento = d.id',
'                       and a.id_entidade = 3829',
'                       and a.id_referencia = p.id',
'               )',
'       );',
'',
'    select count(*)',
'      into l_qtd_documento_importacao',
'      from imp_processoimportacao p',
'     where exists (',
'            select 1',
'              from ng_documento d',
'             where d.id_entidade = 23',
'               and d.ind_obrigatorio = ''S''',
'               and not exists (',
'                    select 1',
'                      from ng_anexo a',
'                     where a.id_documento = d.id',
'                       and a.id_entidade = 4324',
'                       and a.id_referencia = p.id',
'               )',
'       );',
'',
'    l_qtd_total := nvl(l_qtd_aprovacao, 0)',
'                 + nvl(l_qtd_documento_pedido, 0)',
'                 + nvl(l_qtd_documento_importacao, 0);',
'',
'    l_label_anexo := pkg_ui.retorna_label_tela(''anexo'');',
'',
'    l_label_pendente := pkg_ui.retorna_label_tela(''pendente'');',
'',
'    l_label_aprovacao := pkg_ui.retorna_label_tela(''aprovacao'');',
'',
'    l_label_documento_pedido := pkg_ui.retorna_label_tela(',
'        ''documento_pedido_importacao''',
'    );',
'',
'    l_label_documento_importacao := pkg_ui.retorna_label_tela(',
'        ''documento_importacao''',
'    );',
'',
'    l_url_aprovacao := apex_page.get_url(',
'        p_page        => 2,',
'        p_clear_cache => ''2''',
'    );',
'',
'    l_url_documento_pedido := apex_page.get_url(',
'        p_page        => 2,',
'        p_clear_cache => ''2''',
'    );',
'',
'    l_url_documento_importacao := apex_page.get_url(',
'        p_page        => 2,',
'        p_clear_cache => ''2''',
'    );',
'',
'    l_html := ''',
'        <div class="card-resumo-duplo">',
'            <div class="card-resumo-topo">',
'                <div class="card-resumo-topo-info">',
'                    <div class="card-resumo-icone">''',
'                        || render_icone_anexo ||',
'                    ''</div>',
'                    ',
'                    <h3 class="card-resumo-titulo">''',
'                        || apex_escape.html(nvl(l_label_anexo, ''Anexo'')) ||',
'                    ''</h3>',
'                </div>',
'',
'                <span class="card-resumo-badge">''',
'                    || to_char(l_qtd_total) || '' '' ||',
'                    case',
unistr('                        when l_qtd_total = 1 then ''Pend\00EAncia'''),
unistr('                        else ''Pend\00EAncias'''),
'                    end ||',
'                ''</span>',
'            </div>',
'',
'            <div class="card-resumo-conteudo">',
'',
'            </div>',
'',
'            <div class="card-resumo-indicadores card-resumo-indicadores-3">''',
'                || render_indicador(',
'                    p_qtd   => l_qtd_aprovacao,',
'                    p_label => l_label_aprovacao,',
'                    p_url   => l_url_aprovacao',
'                )',
'                || render_indicador(',
'                    p_qtd   => l_qtd_documento_pedido,',
'                    p_label => l_label_documento_pedido,',
'                    p_url   => l_url_documento_pedido',
'                )',
'                || render_indicador(',
'                    p_qtd   => l_qtd_documento_importacao,',
'                    p_label => l_label_documento_importacao,',
'                    p_url   => l_url_documento_importacao',
'                ) ||',
'            ''</div>',
'        </div>'';',
'',
'    return l_html;',
'end;',
'',
