'declare',
'    l_qtd_titulo_pagamento   number;',
'    l_url_titulo_pagamento   varchar2(4000);',
'    l_html                   clob;',
'',
'    l_label_pagamento        varchar2(100);',
'    l_label_em_atraso        varchar2(100);',
'    l_label_titulo_pagamento varchar2(100);',
'',
'    function render_icone_pagamento',
'    return clob',
'    is',
'    begin',
'        return q''~',
'            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                 stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                 aria-hidden="true">',
'                <path d="M12 1v22"></path>',
'                <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7H14a3.5 3.5 0 0 1 0 7H6"></path>',
'            </svg>',
'        ~'';',
'    end render_icone_pagamento;',
'',
'    function render_card_pagamento(',
'        p_qtd          in number,',
'        p_titulo       in varchar2,',
'        p_status       in varchar2,',
'        p_badge        in varchar2,',
'        p_url          in varchar2',
'    ) return clob',
'    is',
'        l_class varchar2(200);',
'        l_href  varchar2(4000);',
'    begin',
'        if nvl(p_qtd, 0) > 0 then',
'            l_class := ''card-resumo-pagamento'';',
'            l_href  := '' href="'' || apex_escape.html_attribute(p_url) || ''"'';',
'        else',
'            l_class := ''card-resumo-pagamento is-disabled'';',
'            l_href  := null;',
'        end if;',
'',
'        return ''',
'            <a class="'' || l_class || ''"'' || l_href || ''>',
'                <div class="card-resumo-topo">',
'                    <div class="card-resumo-topo-info">',
'                        <div class="card-resumo-icone">''',
'                            || render_icone_pagamento ||',
'                        ''</div>',
'                        <div class="card-resumo-conteudo">',
'                            <h3 class="card-resumo-titulo">''',
'                                || apex_escape.html(nvl(p_titulo, ''Pagamentos'')) ||',
'                            ''</h3>',
'',
'                            <div class="card-resumo-status">''',
'                                || apex_escape.html(nvl(p_status, ''Em atraso'')) ||',
'                            ''</div>',
'                        </div>',
'                    </div>',
'                </div>',
'',
'',
'                <div class="card-resumo-rodape">',
'                    <span class="card-resumo-qtd">''',
'                        || to_char(nvl(p_qtd, 0)) || '' '' ||',
'                        case ',
unistr('                            when nvl(p_qtd, 0) = 1 then ''T\00EDtulo'''),
unistr('                            else ''T\00EDtulos'''),
'                        end ||',
'                    ''</span>',
'                </div>',
'            </a>'';',
'    end render_card_pagamento;',
'',
'begin',
'    select count(*)',
'      into l_qtd_titulo_pagamento',
'      from fin_titulopagamento',
'     where ind_status_pagamento = 1',
'       and data_vencimento is not null',
'       and data_vencimento < trunc(sysdate);',
'',
'    l_label_pagamento        := pkg_ui.retorna_label_tela(''pagamento'');',
'    l_label_em_atraso        := pkg_ui.retorna_label_tela(''em_atraso'');',
'    l_label_titulo_pagamento := pkg_ui.retorna_label_tela(''titulo_pagamento'');',
'',
'    l_url_titulo_pagamento := apex_page.get_url(',
'        p_page        => 2,',
'        p_clear_cache => ''2''',
'    );',
'',
'    l_html := render_card_pagamento(',
'        p_qtd    => l_qtd_titulo_pagamento,',
'        p_titulo => l_label_pagamento,',
'        p_status => l_label_em_atraso,',
'        p_badge  => ''PAGAMENTO'',',
'        p_url    => l_url_titulo_pagamento',
'    );',
'',
'    return l_html;',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
