'    l_label_saldo_programar   varchar2(100);',
'',
'    function render_icone_pedido',
'    return clob',
'    is',
'    begin',
'        return q''~',
'            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                 stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                 aria-hidden="true">',
'                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>',
'                <path d="M14 2v6h6"></path>',
'                <path d="M8 13h8"></path>',
'                <path d="M8 17h5"></path>',
'            </svg>',
'        ~'';',
'    end render_icone_pedido;',
'',
'    function render_indicador(',
'        p_qtd   in number,',
'        p_label in varchar2,',
'        p_url   in varchar2',
'    ) return clob',
'    is',
'        l_class varchar2(200);',
'        l_href  varchar2(4000);',
'    begin',
'        if nvl(p_qtd, 0) > 0 then',
'            l_class := ''card-resumo-indicador'';',
'            l_href  := '' href="'' || apex_escape.html_attribute(p_url) || ''"'';',
'        else',
'            l_class := ''card-resumo-indicador is-disabled'';',
'            l_href  := null;',
'        end if;',
'',
'        return ''',
'            <a class="'' || l_class || ''"'' || l_href || ''>',
'                <span class="card-resumo-indicador-label">''',
unistr('                    || apex_escape.html(nvl(p_label, ''Sem descri\00E7\00E3o'')) ||'),
'                ''</span>',
'',
'                <span class="card-resumo-indicador-qtd">''',
'                    || to_char(nvl(p_qtd, 0)) ||',
'                ''</span>',
'            </a>'';',
'    end render_indicador;',
'',
'begin',
'    select count(*)',
'      into l_qtd_firmar',
'      from imp_pedidoimportacao',
'     where ind_status_pedido_importacao = 2;',
'',
'    select count(*)',
'      into l_qtd_saldo',
'      from imp_pedidoimportacao',
'     where ind_todos_itens_com_entregas_programadas = ''N'';',
'',
'    l_qtd_total := nvl(l_qtd_firmar, 0) + nvl(l_qtd_saldo, 0);',
'',
'    l_label_pedido_importacao := pkg_ui.retorna_label_tela(''pedido_importacao'');',
'    l_label_aguardando        := pkg_ui.retorna_label_tela(''aguardando'');',
'',
'    l_label_firmar := pkg_util.dominio_retorna_tag(',
'        ''imp_pedidoimportacao'',',
'        ''ind_status_pedido_importacao'',',
'        2',
'    );',
'',
'    l_label_saldo_programar := pkg_ui.retorna_label_tela(''saldo_programar'');',
'',
'    l_url_firmar := apex_page.get_url(',
'        p_page        => 9005,',
'        p_clear_cache => ''9005'',',
'        p_items       => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_LISTA3,P9005_FILTRO_CARD3'',',
'        p_values      => ''Y,TD343,2,2,,''',
'    );',
'',
'    l_url_saldo := apex_page.get_url(',
'        p_page        => 9005,',
'        p_clear_cache => ''9005'',',
'        p_items       => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_LISTA3,P9005_FILTRO_CARD3'',',
'        p_values      => ''Y,TD343,,,N,N''',
'    );',
'',
'    l_html := ''',
'        <div class="card-resumo-duplo">',
'            <div class="card-resumo-topo">',
'                <div class="card-resumo-topo-info">',
'                    <div class="card-resumo-icone">''',
'                        || render_icone_pedido ||',
'                    ''</div>',
'',
'                    <div class="card-resumo-conteudo">',
'                        <h3 class="card-resumo-titulo">''',
unistr('                            || apex_escape.html(nvl(l_label_pedido_importacao, ''Pedido de Importa\00E7\00E3o'')) ||'),
'                        ''</h3>',
'',
'                        <div class="card-resumo-status">''',
'                            || apex_escape.html(nvl(l_label_aguardando, ''Aguardando'')) ||',
'                        ''</div>',
'                    </div>',
'                </div>',
'',
'                <span class="card-resumo-badge">''',
'                    || to_char(l_qtd_total) || '' '' ||',
'                    case',
'                        when l_qtd_total = 1 then ''Pedido''',
'                        else ''Pedidos''',
'                    end ||',
'                ''</span>',
'            </div>',
'',
'            <div class="card-resumo-indicadores">''',
'                || render_indicador(',
'                    p_qtd   => l_qtd_firmar,',
'                    p_label => l_label_firmar,',
'                    p_url   => l_url_firmar',
'                )',
'                || render_indicador(',
'                    p_qtd   => l_qtd_saldo,',
'                    p_label => l_label_saldo_programar,',
'                    p_url   => l_url_saldo',
'                ) ||',
'            ''</div>',
'        </div>'';',
'',
'    return l_html;',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
