'    l_label_documento_pedido varchar2(100);',
'    l_label_documento_importacao varchar2(100);',
'BEGIN',
'    -- consultas',
'    SELECT COUNT(*) INTO l_qtd_aprovacao FROM ng_anexo a JOIN ng_documento d ON d.id = a.id_documento WHERE a.ind_situacao = ''1'' AND d.ind_aprovar = ''S'';',
'    SELECT COUNT(*) INTO l_qtd_documento_pedido FROM imp_pedidoimportacao p WHERE EXISTS (SELECT 1 FROM ng_documento d WHERE d.id_entidade = 24 AND d.ind_obrigatorio = ''S'' AND NOT EXISTS (SELECT 1 FROM ng_anexo a WHERE a.id_documento = d.id AND a.id_'
||'entidade = 3829 AND a.id_referencia = p.id));',
'    SELECT COUNT(*) INTO l_qtd_documento_importacao FROM imp_processoimportacao p WHERE EXISTS (SELECT 1 FROM ng_documento d WHERE d.id_entidade = 23 AND d.ind_obrigatorio = ''S'' AND NOT EXISTS (SELECT 1 FROM ng_anexo a WHERE a.id_documento = d.id AND'
||' a.id_entidade = 4324 AND a.id_referencia = p.id));',
'    l_label_anexo                   := pkg_ui.retorna_label_tela(''anexo'');',
'    l_label_aguardando              := pkg_ui.retorna_label_tela(''aguardando'');',
'    l_label_aprovacao               := pkg_ui.retorna_label_tela(''aprovacao'');',
'    l_label_documento_pedido        := pkg_ui.retorna_label_tela(''documento_pedido_importacao'');',
'    l_label_documento_importacao    := pkg_ui.retorna_label_tela(''documento_importacao'');',
'',
'    -- URL''s',
'    l_url_aprovacao := apex_page.get_url(',
'        -- p_page   => 9005,',
'        -- p_clear_cache => 9005,',
'        -- p_items  => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_CARD3'',',
'        -- p_values => ''Y,TD343,3,2,''',
'        ',
unistr('        p_page   => 2,      -- url provis\00F3rio p/ mesma tela'),
'        p_clear_cache => 2',
'    ); ',
'    l_url_documento_pedido := apex_page.get_url(',
'        -- p_page   => 9005,',
'        -- p_clear_cache => 9005,',
'        -- p_items  => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_CARD3'',',
'        -- p_values => ''Y,TD343,3,2,''',
'        ',
unistr('        p_page   => 2,      -- url provis\00F3rio p/ mesma tela'),
'        p_clear_cache => 2',
'    ); ',
'    l_url_documento_importacao := apex_page.get_url(',
'        -- p_page   => 9005,',
'        -- p_clear_cache => 9005,',
'        -- p_items  => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_CARD3'',',
'        -- p_values => ''Y,TD343,3,2,''',
'        ',
unistr('        p_page   => 2,      -- url provis\00F3rio p/ mesma tela'),
'        p_clear_cache => 2',
'    );        ',
'',
'    -- html',
'    l_html := q''[',
'        <div class="card-bloco">',
'            <div class="card-titulo">]'' || l_label_anexo || q''[</div>',
'            <div class="card-subnivel">',
'                <div class="card-subtitulo">]'' || l_label_aguardando || q''[</div>',
'                <div class="card-itens">',
'                    <a class="card-item" ]'' || CASE WHEN l_qtd_aprovacao > 0 THEN ''href="'' || l_url_aprovacao || ''"'' ELSE '''' END || q''[>',
'                        <span class="qtd">]'' || l_qtd_aprovacao || q''[</span>',
'                        <span class="label">]'' || l_label_aprovacao || q''[</span>',
'                    </a>',
'                    <a class="card-item" ]'' || CASE WHEN l_qtd_documento_pedido > 0 THEN ''href="'' || l_url_documento_pedido || ''"'' ELSE '''' END || q''[>',
'                        <span class="qtd">]'' || l_qtd_documento_pedido || q''[</span>',
'                        <span class="label">]'' || l_label_documento_pedido || q''[</span>',
'                    </a>',
'                    <a class="card-item" ]'' || CASE WHEN l_qtd_documento_importacao > 0 THEN ''href="'' || l_url_documento_importacao || ''"'' ELSE '''' END || q''[>',
'                        <span class="qtd">]'' || l_qtd_documento_importacao || q''[</span>',
'                        <span class="label">]'' || l_label_documento_importacao || q''[</span>',
'                    </a>',
'                </div>',
'            </div>',
'        </div>',
'    ]'';',
'',
'    htp.p(l_html);',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
);
