wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(142141789338150731)
,p_plug_name=>'Processo-importacao'
,p_parent_plug_id=>wwv_flow_imp.id(142141632555150730)
,p_region_template_options=>'#DEFAULT#:margin-bottom-sm'
,p_plug_template=>wwv_flow_imp.id(529588161801986979)
,p_plug_display_sequence=>30
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_qtd_firmar number;',
'    l_qtd_saldo  number;',
'',
'    l_total_duimp_exigencia number;',
'    l_total_atraso          number;',
'    l_total_proximos        number;',
'    l_total_aguardando      number;',
'    l_total_geral           number;',
'',
'    l_html       clob;',
'    l_url_padrao varchar2(4000);',
'',
'    function render_icone_processo',
'    return clob',
'    is',
'    begin',
'        return q''~',
'            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                 stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                 aria-hidden="true">',
'                <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path>',
'                <path d="M3.3 7L12 12l8.7-5"></path>',
'                <path d="M12 22V12"></path>',
'            </svg>',
'        ~'';',
'    end render_icone_processo;',
'',
'    function render_indicador(',
'        p_qtd   in number,',
'        p_label in varchar2,',
'        p_url   in varchar2',
'    ) return clob',
'    is',
'        l_class varchar2(200);',
'        l_href  varchar2(4000);',
'    begin',
'        if nvl(p_qtd, 0) > 0 then',
'            l_class := ''card-processo-indicador'';',
'            l_href  := '' href="'' || apex_escape.html_attribute(p_url) || ''"'';',
'        else',
'            l_class := ''card-processo-indicador is-disabled'';',
'            l_href  := null;',
'        end if;',
'',
'        return ''',
'            <a class="'' || l_class || ''"'' || l_href || ''>',
'                <span class="card-processo-indicador-qtd">''',
'                    || to_char(nvl(p_qtd, 0)) ||',
'                ''</span>',
'',
'                <span class="card-processo-indicador-label">''',
unistr('                    || apex_escape.html(nvl(p_label, ''Sem descri\00E7\00E3o'')) ||'),
'                ''</span>',
'            </a>'';',
'    end render_indicador;',
'',
'    function render_grupo(',
'        p_titulo in varchar2,',
'        p_total  in number,',
'        p_tipo   in varchar2,',
'        p_itens  in clob',
'    ) return clob',
'    is',
'        l_class varchar2(200);',
'    begin',
'        l_class := ''card-processo-grupo'';',
'',
'        if p_tipo is not null then',
'            l_class := l_class || '' card-processo-grupo-'' || lower(p_tipo);',
'        end if;',
'',
'        return ''',
'            <div class="'' || l_class || ''">',
'                <div class="card-processo-grupo-header">',
'                    <span class="card-processo-grupo-titulo">''',
'                        || apex_escape.html(nvl(p_titulo, ''Grupo'')) ||',
'                    ''</span>',
'',
'                    <span class="card-resumo-badge">''',
'                        || to_char(nvl(p_total, 0)) ||',
'                    ''</span>',
'                </div>',
'',
'                <div class="card-processo-grupo-itens">''',
'                    || p_itens ||',
'                ''</div>',
'            </div>'';',
'    end render_grupo;',
'',
'begin',
'    select count(*)',
'      into l_qtd_firmar',
'      from imp_pedidoimportacao',
'     where ind_status_pedido_importacao = 2;',
'',
'    select count(*)',
'      into l_qtd_saldo',
'      from imp_pedidoimportacao',
'     where ind_todos_itens_com_entregas_programadas = ''N'';',
'',
'    l_url_padrao := apex_page.get_url(',
'        p_page        => 2,',
'        p_clear_cache => ''2''',
'    );',
'',
'    l_total_duimp_exigencia := nvl(l_qtd_firmar, 0)',
'                             + nvl(l_qtd_saldo, 0)',
'                             + nvl(l_qtd_saldo, 0);',
'',
'    l_total_atraso := nvl(l_qtd_firmar, 0)',
'                    + nvl(l_qtd_saldo, 0);',
'',
'    l_total_proximos := nvl(l_qtd_firmar, 0)',
'                      + nvl(l_qtd_saldo, 0);',
'',
'    l_total_aguardando := nvl(l_qtd_firmar, 0);',
'',
'    l_total_geral := nvl(l_total_duimp_exigencia, 0)',
'                   + nvl(l_total_atraso, 0)',
'                   + nvl(l_total_proximos, 0)',
'                   + nvl(l_total_aguardando, 0);',
'',
'',
'',
'    l_html := ''',
'        <div class="card-resumo-processo">',
'            <div class="card-resumo-topo">',
'                <div class="card-resumo-topo-info">',
'                    <div class="card-resumo-icone">''',
'                       || render_icone_processo ||',
'                    ''</div>',
'                    <div class="card-resumo-conteudo">',
'                        <h3 class="card-resumo-titulo">',
unistr('                            Processo de Importa\00E7\00E3o'),
'                        </h3>',
'                    </div>',
'                </div>',
'',
'                <span class="card-resumo-badge">''',
'                    || to_char(l_total_geral) || '' '' ||',
'                    case',
unistr('                        when l_total_geral = 1 then ''Pend\00EAncia'''),
unistr('                        else ''Pend\00EAncias'''),
'                    end ||',
'                ''</span>',
'            </div>',
'',
'',
'            <div class="card-processo-grupos">''',
'                || render_grupo(',
unistr('                    p_titulo => ''Duimp em exig\00EAncia'','),
'                    p_total  => l_total_duimp_exigencia,',
'                    p_tipo   => ''danger'',',
'                    p_itens  =>',
'                        render_indicador(l_qtd_firmar, ''Canal amarelo'', l_url_padrao) ||',
'                        render_indicador(l_qtd_saldo,  ''Canal vermelho'', l_url_padrao) ||',
'                        render_indicador(l_qtd_saldo,  ''Canal cinza'', l_url_padrao)',
'                )',
'                || render_grupo(',
'                    p_titulo => ''Em atraso'',',
'                    p_total  => l_total_atraso,',
'                    p_tipo   => ''warning'',',
'                    p_itens  =>',
'                        render_indicador(l_qtd_firmar, ''Aguardando embarque'', l_url_padrao) ||',
'                        render_indicador(l_qtd_saldo,  ''Aguardando desembarque'', l_url_padrao)',
'                )',
'                || render_grupo(',
unistr('                    p_titulo => ''Pr\00F3ximos 7 dias'','),
'                    p_total  => l_total_proximos,',
'                    p_tipo   => ''info'',',
'                    p_itens  =>',
'                        render_indicador(l_qtd_firmar, ''Aguardando embarque'', l_url_padrao) ||',
'                        render_indicador(l_qtd_saldo,  ''Embarcado'', l_url_padrao)',
'                )',
'                || render_grupo(',
'                    p_titulo => ''Aguardando'',',
'                    p_total  => l_total_aguardando,',
'                    p_tipo   => ''success'',',
'                    p_itens  =>',
unistr('                        render_indicador(l_qtd_firmar, ''Autoriza\00E7\00E3o para embarque'', l_url_padrao)'),
'                ) ||',
'            ''</div>',
'        </div>'';',
'',
'    return l_html;',
'end;',
'',
'',
'',
