wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(186053414506080735)
,p_plug_name=>'Pagamento'
,p_parent_plug_id=>wwv_flow_imp.id(142141632555150730)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529588161801986979)
,p_plug_display_sequence=>70
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_qtd_titulo_pagamento NUMBER;',
'    l_url_titulo_pagamento VARCHAR2(4000);',
'    l_html       CLOB;',
'    l_label_pagamento varchar2(100);',
'    l_label_em_atraso varchar2(100);',
'    l_label_titulo_pagamento varchar2(100);',
'BEGIN',
'    -- consultas',
'    SELECT COUNT(*) INTO l_qtd_titulo_pagamento FROM fin_titulopagamento WHERE ind_status_pagamento = 1 AND data_vencimento IS NOT NULL AND data_vencimento < TRUNC(SYSDATE);',
'    l_label_pagamento          := pkg_ui.retorna_label_tela(''pagamento'');',
'    l_label_em_atraso          := pkg_ui.retorna_label_tela(''em_atraso'');',
'    l_label_titulo_pagamento   := pkg_ui.retorna_label_tela(''titulo_pagamento'');',
'',
'    -- URL''s',
'    l_url_titulo_pagamento := apex_page.get_url(',
'        -- p_page   => 9005,',
'        -- p_clear_cache => 9005,',
'        -- p_items  => ''A_RESET_BREADCRUMB1,P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,P9005_FILTRO_CARD2,P9005_FILTRO_CARD3'',',
'        -- p_values => ''Y,TD343,3,2,''',
'        ',
unistr('        p_page   => 2,      -- url provis\00F3rio p/ mesma tela'),
'        p_clear_cache => 2',
'    );     ',
'',
'    -- html',
'    l_html := q''[',
'        <div class="card-bloco">',
'            <div class="card-titulo">]'' || l_label_pagamento || q''[</div>',
'            <div class="card-subnivel">',
'                <div class="card-subtitulo-red">]'' || l_label_em_atraso || q''[</div>',
'                <div class="card-itens">',
'                    <a class="card-item" ]'' || CASE WHEN l_qtd_titulo_pagamento > 0 THEN ''href="'' || l_url_titulo_pagamento || ''"'' ELSE '''' END || q''[>',
'                        <span class="qtd">]'' || l_qtd_titulo_pagamento || q''[</span>',
'                        <span class="label">]'' || l_label_titulo_pagamento || q''[</span>',
'                    </a>',
'                </div>',
'            </div>',
'        </div>',
'    ]'';',
'',
'    htp.p(l_html);',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(186053569788080736)
,p_plug_name=>'Processo-importacao'
,p_parent_plug_id=>wwv_flow_imp.id(142141632555150730)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529588161801986979)
,p_plug_display_sequence=>60
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_qtd_firmar NUMBER;',
'    l_qtd_saldo  NUMBER;',
'BEGIN',
'',
'    -- consultas',
'    SELECT COUNT(*) INTO l_qtd_firmar',
'    FROM imp_pedidoimportacao',
'    WHERE ind_status_pedido_importacao = 2;',
'',
'    SELECT COUNT(*) INTO l_qtd_saldo',
'    FROM imp_pedidoimportacao',
'    WHERE ind_todos_itens_com_entregas_programadas = ''N'';',
'',
'    -- HTML',
'    htp.p(''',
'        <div class="card-bloco">',
'',
unistr('            <div class="card-titulo">Processo de importa\00E7\00E3o</div>'),
