wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(186053073324080731)
,p_plug_name=>'KPI'
,p_parent_plug_id=>wwv_flow_imp.id(186053842319080739)
,p_region_template_options=>'#DEFAULT#:t-ButtonRegion--noPadding:t-ButtonRegion--noUI'
,p_plug_template=>wwv_flow_imp.id(529590912278986980)
,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_html clob;',
'    l_url  varchar2(4000);',
'',
'    function retorna_icone_svg(',
'        p_ordem in number',
'    ) return clob',
'    is',
'    begin',
'        return case p_ordem',
'',
'            when 1 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <path d="M12 20h9"></path>',
'                    <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path>',
'                </svg>',
'            ~''',
'',
'            when 2 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>',
'                    <line x1="16" y1="2" x2="16" y2="6"></line>',
'                    <line x1="8" y1="2" x2="8" y2="6"></line>',
'                    <line x1="3" y1="10" x2="21" y2="10"></line>',
'                </svg>',
'            ~''',
'',
'            when 3 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <path d="M2 21c.6.5 1.2 1 2.5 1 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1 .6.5 1.2 1 2.5 1 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1"></path>',
'                    <path d="M19.38 20A11.6 11.6 0 0 0 21 14l-9-4-9 4c0 2.9.94 5.34 2.81 7.76"></path>',
'                    <path d="M19 13V7a2 2 0 0 0-2-2H7a2 2 0 0 0-2 2v6"></path>',
'                    <path d="M12 10v4"></path>',
'                    <path d="M12 2v3"></path>',
'                </svg>',
'            ~''',
'',
'            when 4 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <circle cx="12" cy="5" r="3"></circle>',
'                    <line x1="12" y1="22" x2="12" y2="8"></line>',
'                    <path d="M5 12H2a10 10 0 0 0 20 0h-3"></path>',
'                </svg>',
'            ~''',
'',
'            when 5 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path>',
'                    <rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect>',
'                    <path d="M9 14l2 2 4-4"></path>',
'                </svg>',
'            ~''',
'',
'            when 6 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <circle cx="12" cy="12" r="10"></circle>',
'                    <line x1="2" y1="12" x2="22" y2="12"></line>',
'                    <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path>',
'                </svg>',
'            ~''',
'',
'            when 7 then q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>',
'                    <polyline points="22 4 12 14.01 9 11.01"></polyline>',
'                </svg>',
'            ~''',
'',
'            else q''~',
'                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor"',
'                     stroke-width="2" stroke-linecap="round" stroke-linejoin="round"',
'                     aria-hidden="true">',
'                    <circle cx="12" cy="12" r="10"></circle>',
'                </svg>',
'            ~''',
'        end;',
'    end retorna_icone_svg;',
'',
'    function render_kpi(',
'        p_quantidade in number,',
'        p_label      in varchar2,',
'        p_url        in varchar2,',
'        p_ordem      in number,',
'        p_css_class  in varchar2',
'    ) return clob',
'    is',
'        l_class varchar2(300);',
'        l_href  varchar2(4000);',
'        l_tag   varchar2(30);',
'    begin',
'        l_tag := p_label;',
'',
'        if nvl(p_quantidade, 0) > 0 then',
'            l_class := ''kpi-importacao-card-v2 '' || p_css_class;',
'            l_href  := '' href="'' || apex_escape.html_attribute(p_url) || ''"'';',
'        else',
'            l_class := ''kpi-importacao-card-v2 is-disabled '' || p_css_class;',
'            l_href  := null;',
'        end if;',
'',
'        return ''',
'            <a class="'' || apex_escape.html_attribute(l_class) || ''"'' || l_href || ''>',
'                <div class="kpi-importacao-topo-v2">',
'                    <div class="kpi-importacao-icone-v2">''',
'                        || retorna_icone_svg(p_ordem) ||',
'                    ''</div>',
'                    <span class="kpi-importacao-numero-v2">''',
'                        || to_char(nvl(p_quantidade, 0)) ||',
'                    ''</span>',
'                </div>',
'',
'                <div class="kpi-importacao-conteudo-v2">',
'                    <span class="kpi-importacao-badge-v2">''',
'                        || apex_escape.html(l_tag) ||',
'                    ''</span>',
'',
'                </div>',
'            </a>'';',
'    end render_kpi;',
'',
'begin',
'    l_html := ''<div class="kpi-importacao-container-v2">'';',
'',
'    for r in (',
'        with status_base as (',
'            select 10 ind_status, 1 ordem from dual union all',
'            select 1,  2 from dual union all',
'            select 2,  3 from dual union all',
'            select 3,  4 from dual union all',
'            select 4,  5 from dual union all',
'            select 5,  6 from dual union all',
'            select 6,  7 from dual',
'        ),',
'        dominio as (',
'            select',
'                r as ind_status,',
'                d as label',
'            from table(pkg_util.dominio_retorna_lista(''imp_processoimportacao'',''ind_status''))',
'        )',
'        select',
'            s.ind_status,',
'            d.label,',
'            s.ordem,',
'            count(p.id) quantidade,',
'',
'            case s.ordem',
'                when 1 then ''card-cor-1''',
'                when 2 then ''card-cor-2''',
'                when 3 then ''card-cor-3''',
'                when 4 then ''card-cor-4''',
'                when 5 then ''card-cor-5''',
'                when 6 then ''card-cor-6''',
'                when 7 then ''card-cor-7''',
'            end as css_class',
'',
'        from status_base s',
'',
'        left join dominio d',
'            on d.ind_status = s.ind_status',
'',
'        left join imp_processoimportacao p',
'            on p.ind_status = s.ind_status',
'',
'        group by',
'            s.ind_status,',
'            d.label,',
'            s.ordem',
'',
'        order by',
'            s.ordem',
'    ) loop',
'',
'        l_url := apex_page.get_url(',
'            p_page        => 9005,',
'            p_clear_cache => ''9005'',',
'            p_items       => ''P9005_CODIGO_ARTEFATO,P9005_FILTRO_LISTA2,A_RESET_BREADCRUMB1,P9005_FILTRO_CARD2'',',
'            p_values      => ''TD832,'' || r.ind_status || '',Y,'' || r.ind_status',
'        );',
'',
'        l_html := l_html || render_kpi(',
'            p_quantidade => r.quantidade,',
'            p_label      => r.label,',
'            p_url        => l_url,',
'            p_ordem      => r.ordem,',
'            p_css_class  => r.css_class',
'        );',
'',
'    end loop;',
'',
'    l_html := l_html || ''</div>'';',
'',
'    return l_html;',
'end;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(195713591512854189)
,p_name=>'Menu'
,p_region_name=>'LISTA_MENU'
,p_template=>wwv_flow_imp.id(529623708881986997)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'t-MediaList--showIcons:t-MediaList--showDesc:t-MediaList--showBadges:t-MediaList--cols t-MediaList--2cols:t-MediaList--iconsSquare'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    pkg_ui.retorna_titulo_menu(a.id) LIST_TITLE, ',
'    case ',
'        when a.id = b.id_menu then ',
'            apex_page.get_url( ',
'                    p_page => case when c.tipo = ''CD'' then e.codigo_artefato else c.codigo_artefato end,',
'                    p_items => ''A_RESET_BREADCRUMB1,P0_CODIGO_ARTEFATO,P''||case when c.tipo = ''CD'' then e.codigo_artefato else c.codigo_artefato end||''_CODIGO_ARTEFATO'', ',
'                    p_values => ''Y,''||c.codigo_artefato||'',''||c.codigo_artefato, ',
'                    p_clear_cache => case when c.tipo = ''CD'' then e.codigo_artefato else c.codigo_artefato end)',
'        else ',
'            apex_page.get_url( ',
'                    p_page => 2,',
'                    p_items => ''P2_ITEM_PAI'', ',
'                    p_values => a.id, ',
'                    p_clear_cache => 2) ',
'    end as LINK,',
'    c.codigo_artefato LIST_BADGE,',
'    case when PKG_CONTROLE_ACESSO.retorno_verifica_permissao(:APP_USER,c.codigo_artefato) = ''true'' then a.icone else case when c.codigo_artefato is null then a.icone else ''fa-lock'' end end as ICON_COLOR_CLASS,',
'    case ',
'        when ',
'            ((:P2_ITEM_PAI is null and id_nivel_pai is null)',
'              or id_nivel_pai = :P2_ITEM_PAI) ',
'        then '''' ',
'        else ''oculto''',
'    end as visible_class,',
'    a.id_nivel_pai as id_nivel_pai',
'    from mpd_menu a',
'left join mpd_menu_acao b on b.id_menu = a.id',
'left join mpd_funcionalidade c on c.id = b.id_funcionalidade',
'left join mpd_funcionalidade_tela_dinamica d on d.id_funcionalidade = c.id',
'left join mpd_funcionalidade e on e.id = d.id_funcionalidade_base            ',
'left join srv_menu a1 on a1.id = a.id            ',
'left join srv_sistema_versionado b1 on b1.id = a1.id_sistema_versionado            ',
'left join srv_sistema c1 on c1.id = b1.id_sistema            ',
'where upper(c1.codigo_sistema) = upper(:app_name)',
'order by 1'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_CODIGO_ARTEFATO'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(185416115527242620)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
