wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(163923938150305837)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'retorna_labels'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_sigla_idioma_l varchar2(4000);',
'    l_sigla_idioma_i varchar2(4000);',
'    l_sigla_idioma_h varchar2(4000);',
'    l_descricao_l    varchar2(4000);',
'    l_descricao_i    varchar2(4000);',
'    l_descricao_h    varchar2(4000);',
'    l_codigo_l       varchar2(4000);',
'    l_codigo_i       varchar2(4000);',
'    l_codigo_h       varchar2(4000);',
'    l_proximo_l      varchar2(4000);',
'    l_salvar_l       varchar2(4000);',
'begin',
'    pkg_ui.retorna_coluna(''srv_idioma.sigla_idioma'', l_sigla_idioma_l, l_sigla_idioma_i, l_sigla_idioma_h);',
'    pkg_ui.retorna_coluna(''mpd_descricao.descricao'', l_descricao_l, l_descricao_i, l_descricao_h);',
'    pkg_ui.retorna_coluna(''srv_idioma.codigo'', l_codigo_l, l_codigo_i, l_codigo_h);',
'    select pkg_ui.retorna_label_botao(''proximo'') into l_proximo_l from dual;',
'    select pkg_ui.retorna_label_botao(''salvar'') into l_salvar_l from dual;   ',
'    -- Sigla do Idioma:',
'    :P4_SIGLA_IDIOMA_L := l_sigla_idioma_l;',
'    :P4_SIGLA_IDIOMA_I := l_sigla_idioma_i;',
'    :P4_SIGLA_IDIOMA_H := l_sigla_idioma_h;',
unistr('    -- Descri\00E7\00E3o:'),
'    :P4_DESCRICAO_L := l_descricao_l;',
'    :P4_DESCRICAO_I := l_descricao_i;',
'    :P4_DESCRICAO_H := l_descricao_h;',
unistr('    -- C\00F3digo:'),
'    :P4_CODIGO_L := l_codigo_l;',
'    :P4_CODIGO_I := l_codigo_i;',
'    :P4_CODIGO_H := l_codigo_h;',
unistr('    -- Bot\00E3o Pr\00F3ximo:'),
'    :P4_PROXIMO_L := l_proximo_l; ',
unistr('    -- Bot\00E3o Salvar:'),
'    :P4_SALVAR_L := l_salvar_l;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>78228411259641411
);
end;
