wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(163926133347305859)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'retorna_label'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id_idioma_l varchar2(4000);',
'    l_id_idioma_i varchar2(4000);',
'    l_id_idioma_h varchar2(4000);',
'    l_descricao_l varchar2(4000);',
'    l_descricao_i varchar2(4000);',
'    l_descricao_h varchar2(4000);',
'    l_incluir_l   varchar2(4000);',
'    l_opcao_l     varchar2(4000);',
'    l_anterior_l  varchar2(4000);',
'    l_concluir_l  varchar2(4000);',
'begin',
'    pkg_ui.retorna_coluna(''mpd_descricao.id_idioma'', l_id_idioma_l, l_id_idioma_i, l_id_idioma_h);',
'    pkg_ui.retorna_coluna(''mpd_descricao.descricao'', l_descricao_l, l_descricao_i, l_descricao_h);',
'    select pkg_ui.retorna_label_botao(''incluir'') into l_incluir_l from dual;',
'    select pkg_ui.retorna_label_botao(''opcao'') into l_opcao_l from dual;',
'    select pkg_ui.retorna_label_botao(''anterior'') into l_anterior_l from dual;',
'    select pkg_ui.retorna_label_botao(''concluir'') into l_concluir_l from dual;',
'    -- Id do idioma:',
'    :P5_ID_IDIOMA_L := l_id_idioma_l;',
'    :P5_ID_IDIOMA_I := l_id_idioma_i;',
'    :P5_ID_IDIOMA_H := l_id_idioma_h;',
unistr('    -- Descri\00E7\00E3o:'),
'    :P5_DESCRICAO_L := l_descricao_l;',
'    :P5_DESCRICAO_I := l_descricao_i;',
'    :P5_DESCRICAO_H := l_descricao_h;',
unistr('    -- Bot\00E3o Incluir:'),
'    :P5_INCLUIR_L := l_incluir_l;',
unistr('    -- Bot\00E3o Op\00E7\00F5es:'),
'    :P5_OPCAO_L := l_opcao_l;',
unistr('    -- Bot\00E3o Anterior:'),
'    :P5_ANTERIOR_L := l_anterior_l;',
unistr('    -- Bot\00E3o Concluir:'),
'    :P5_CONCLUIR_L := l_concluir_l;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>78230606456641433
);
end;
