,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_CONFIRM'
,p_attribute_01=>'Deseja alterar a policita de privacidade?'
,p_attribute_03=>'information'
,p_attribute_06=>'Sim, alterar'
