,p_plug_name=>'Informe a quantidade do item abaixo, nesta entrega'
,p_parent_plug_id=>wwv_flow_imp.id(179144394942216813)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--noUI:t-Region--scrollBody:t-Form--large'
,p_plug_template=>wwv_flow_imp.id(529623708881986997)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    a.id,',
'    a.quantidade,',
'    c.codigo_item,',
'    c.descricao_item,',
'    d.codigo_unidademedida,',
'    a.id_tenant,',
'    a.id_entrega,',
'    a.id_pedidoimportacao_item,',
'    a.id_item,',
'    a.id_ncm,',
'    a.id_unidademedida,',
'    a.peso_unitario,',
'    a.peso_liquido_total,',
'    a.valor_unitario,',
'    a.valor_desconto,',
'    a.valor_total_condicao_venda,   ',
'    a.id_naturezaoperacao,',
'    a.id_fabricante,',
'    a.ind_licenca_importacao,',
'    a.data_alteracao',
'from imp_entrega_item a',
'join imp_pedidoimportacao_item b on b.id = a.id_pedidoimportacao_item',
'join ng_item c on c.id = b.id_item',
'join ng_unidademedida d on d.id = b.id_unidademedida',
'where a.id = :P320_ID_ENTREGA_ITEM'))
,p_is_editable=>false
,p_plug_source_type=>'NATIVE_FORM'
,p_ajax_items_to_submit=>'P320_ID_ENTREGA_ITEM'
