 p_id=>wwv_flow_imp.id(147196333300938038)
,p_plug_name=>'Itens saldo + existentens'
,p_region_name=>'ITENS_SALDO_EXISTENTES'
,p_parent_plug_id=>wwv_flow_imp.id(179473274849148292)
,p_region_template_options=>'#DEFAULT#:t-Form--large:margin-top-md'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529621672076986996)
,p_plug_display_sequence=>19
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct    ',
'    b.id ID,',
'    codigo_item,',
'    descricao_item,',
'    num_sequencia_item',
'    --(quantidade - nvl((select sum(ie1.quantidade) from imp_entrega_item ie1 where id_pedidoimportacao_item = b.id),0)) saldo    ',
'from ng_item a ',
'join imp_pedidoimportacao_item b on b.id_item = a.id',
'where b.id_pedidoimportacao = :P320_PARAMETRO',
'and (quantidade - nvl((select sum(ie2.quantidade) from imp_entrega_item ie2 where id_pedidoimportacao_item = b.id),0)) <> 0',
'and b.id not in (select id_pedidoimportacao_item from imp_entrega_item where id_entrega = :P320_ID_IMP_ENTREGA)'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P320_PARAMETRO'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
);
