wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(178854284974794532)
,p_computation_sequence=>150
,p_computation_item=>'P320_ID_ENTREGA_ITEM'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    a.id ',
'from imp_entrega_item a ',
'join imp_entrega b on b.id = a.id_entrega ',
'join imp_pedidoimportacao_item c on c.id = a.id_pedidoimportacao_item',
'where b.id_pedidoimportacao = :P320_PARAMETRO ',
'and a.quantidade = 0 ',
'order by c.num_sequencia_item',
'fetch first 1 rows only'))
);
wwv_flow_imp_page.create_page_computation(
