,p_computation_sequence=>160
,p_computation_item=>'P320_CODIGO_UNIDADEMEDIDA'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    codigo_unidademedida ',
'from imp_entrega_item a',
'join imp_pedidoimportacao_item b on b.id = a.id_pedidoimportacao_item',
'join ng_unidademedida c on c.id = b.id_unidademedida',
'where a.id = :P320_ID_ENTREGA_ITEM   '))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(178854142783794530)
,p_computation_sequence=>170
,p_computation_item=>'P320_QUANTIDADE_1_2'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    (b.quantidade - nvl((select sum(quantidade) from imp_entrega_item where id_pedidoimportacao_item = b.id),0)) ',
'from imp_entrega_item a',
'join imp_pedidoimportacao_item b on b.id = a.id_pedidoimportacao_item',
'where a.id = :P320_ID_ENTREGA_ITEM   '))
);
