'//             valor = valor.replace(/\D/g, '''');',
'//         } else if (tipoDado === ''D'') {',
unistr('//             // Permite d\00EDgitos, ponto e v\00EDrgula, mas n\00E3o outros caracteres'),
'//             valor = valor.replace(/[^0-9.,]/g, '''');',
'',
unistr('//             // Verifica se j\00E1 existe um separador decimal'),
'//             var separador = valor.includes('','') ? '','' : (valor.includes(''.'') ? ''.'' : null);',
'            ',
unistr('//             // Limita o n\00FAmero de casas decimais a 5 ap\00F3s o separador'),
unistr('//             var partes = valor.split(/[\005C.,]/);  // Divide em partes antes e depois do ponto ou v\00EDrgula'),
'',
'//             if (partes.length > 1) {',
'//                 // Se houver casas decimais, limita a 5 casas',
'//                 partes[1] = partes[1].substring(0, 5);',
unistr('//                 valor = partes[0] + separador + partes[1]; // Mant\00E9m o separador original'),
'//             }',
'//         }',
'',
'//         e.target.value = valor;',
'//     });',
'// }',
'var tipoDado = $v(''P320_IND_TIPO_DADO'');',
'var campo = document.getElementById(''P320_QUANTIDADE_1_2''); // Substitua pelo ID real do campo',
'',
'if (campo) {',
'    campo.addEventListener(''input'', function(e) {',
'        let valor = e.target.value;',
'',
'        if (tipoDado === ''I'') {',
unistr('            // Remove tudo que n\00E3o for d\00EDgito (s\00F3 n\00FAmeros inteiros)'),
'            valor = valor.replace(/\D/g, '''');',
'',
unistr('            // Limita a 15 d\00EDgitos'),
'            valor = valor.substring(0, 15);',
'',
'        } else if (tipoDado === ''D'') {',
unistr('            // Remove caracteres inv\00E1lidos (permite apenas d\00EDgitos, ponto e v\00EDrgula)'),
'            valor = valor.replace(/[^0-9.,]/g, '''');',
'',
unistr('            // Detecta qual separador o usu\00E1rio usou primeiro'),
'            let separador = null;',
'            if (valor.includes('','')) {',
'                separador = '','';',
'            } else if (valor.includes(''.'')) {',
'                separador = ''.'';',
'            }',
'',
'            // Se houver separador decimal',
'            if (separador) {',
'                let partes = valor.split(separador);',
'',
unistr('                // Parte inteira limitada a 10 d\00EDgitos'),
'                let parteInteira = partes[0].substring(0, 10);',
'',
unistr('                // Parte decimal limitada a 5 d\00EDgitos'),
'                let parteDecimal = partes[1] ? partes[1].substring(0, 5) : '''';',
'',
'                valor = parteInteira + separador + parteDecimal;',
'            } else {',
unistr('                // Se n\00E3o houver separador, s\00F3 parte inteira (m\00E1x 10 d\00EDgitos)'),
'                valor = valor.substring(0, 10);',
'            }',
'        }',
'',
'        e.target.value = valor;',
'    });',
'}',
''))
);
