wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(647252956280091118)
,p_plug_name=>'Dados Gerais'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529595230508986982)
,p_plug_display_sequence=>20
,p_plug_grid_column_span=>10
,p_plug_display_column=>2
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ',
'    a.id id,',
'    pkg_ui.retorna_label_tela(''dados_gerais'') titulo,    ',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_exportador'', b.nome_fantasia, 3) atributo1,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_importador'', c.nome_fantasia, 3) atributo2,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_adquirente'', d.nome_fantasia, 3) atributo3,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_incoterm'', e.codigo_incoterm, 1) atributo4,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.ind_modalidade_importacao'',',
'        pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'',''ind_modalidade_importacao'',ind_modalidade_importacao), 2',
'    ) atributo5,',
'    ''u-hidden'' class_distintivo',
'from imp_pedidoimportacao a',
'join ng_pessoa_juridica b on b.id_pessoa = a.id_exportador',
