'declare',
'    l_sql clob;',
'    l_parametro varchar2(256) := nvl(:P322_PARAMETRO,:P322_ID);',
'    l_parcela   varchar2(256) := :P322_PARCELA_ATUAL_CONTADOR;',
'begin    ',
'    l_sql := pkg_util.ObterValoresDasColunas (',
'        p_consulta_sql => ''select a.numero_pedido_importacao, ''||l_parcela||'' as numero_parcela from imp_pedidoimportacao a left join ng_condicaopagamento_parcela b on a.id_condicaopagamento = b.id_condicaopagamento where a.id = ''||l_parametro|| ''and'
||' rownum = 1'',',
'        p_tabela => textarray(''imp_pedidoimportacao'',''ng_condicaopagamento_parcela''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'    );',
'    return l_sql;       ',
'end;',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
