wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(170859185204070915)
,p_computation_sequence=>80
,p_computation_item=>'P322_PERCENTUAL'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    c.percentual ',
'from',
'    imp_pedidoimportacao a',
'join ng_condicaopagamento b on b.id = a.id_condicaopagamento',
'join ng_condicaopagamento_parcela c on c.id_condicaopagamento = b.id',
'where a.id = :P322_PARAMETRO',
'and c.numero_parcela = :P322_PARCELA_ATUAL_CONTADOR'))
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(166980286091046526)
,p_computation_sequence=>100
,p_computation_item=>'P322_ID_ENTREGA'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    id    ',
'from imp_entrega',
'where id_pedidoimportacao = :P322_PARAMETRO',
'and id not in (',
'    select ',
'        id_entrega ',
'    from imp_pedidoimportacao_pagamento ',
'    where id_pedidoimportacao = :P322_PARAMETRO ',
'    and numero_parcela = :P322_PARCELA_ATUAL_CONTADOR',
') ',
'order by num_entrega',
'fetch first 1 row only;'))
,p_compute_when=>'P322_IND_BASE_CALCULO'
,p_compute_when_text=>'2'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
);
