,p_computation_item=>'P322_NUM_ENTREGA'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    num_entrega    ',
'from imp_entrega',
'where id_pedidoimportacao = :P322_PARAMETRO',
'and id not in (',
