'declare',
'    l_sql clob;',
'    l_parametro varchar2(256) := nvl(:P323_PARAMETRO,:P323_ID);  ',
'begin',
'    l_sql := pkg_util.ObterValoresDasColunas (',
'        p_consulta_sql => ''',
'        select ',
'            b.numero_pedido_importacao, ',
'            a.num_entrega, ',
'            CASE        ',
'                WHEN a.id_processoimportacao is null THEN',
'                    pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                ELSE',
'                    NULL',
'            END as id_processoimportacao,',
'           pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', a.ind_status_entrega) as ind_status_entrega',
'',
'        from imp_entrega a ',
'        left join imp_pedidoimportacao b ',
'            ON b.id = a.id_pedidoimportacao',
'        where a.id = ''|| l_parametro,',
'        p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega'',''imp_entrega''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'    );',
'    return l_sql;       ',
'end;',
''))
