wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(162928311494331890)
,p_process_sequence=>90
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load labels'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_disponibilidade_l varchar2(4000);',
'    l_disponibilidade_i varchar2(4000);',
'    l_disponibilidade_h varchar2(4000);',
'',
'    l_endereco_origem_l varchar2(4000);',
'    l_endereco_origem_i varchar2(4000);',
'    l_endereco_origem_h varchar2(4000);',
'',
'    l_embarque_l varchar2(4000);',
'    l_embarque_i varchar2(4000);',
'    l_embarque_h varchar2(4000);',
'',
'    l_local_embarque_l varchar2(4000);',
'    l_local_embarque_i varchar2(4000);',
'    l_local_embarque_h varchar2(4000);',
'',
'    l_local_desembarque_l varchar2(4000);',
'    l_local_desembarque_i varchar2(4000);',
'    l_local_desembarque_h varchar2(4000);',
'',
'    l_desembarque_l varchar2(4000);',
'    l_desembarque_i varchar2(4000);',
'    l_desembarque_h varchar2(4000);',
'',
'    l_nacionalizacao_l varchar2(4000);',
'    l_nacionalizacao_i varchar2(4000);',
'    l_nacionalizacao_h varchar2(4000);',
'',
'    l_recebimento_l varchar2(4000);',
'    l_recebimento_i varchar2(4000);',
'    l_recebimento_h varchar2(4000);',
'    ',
'    l_id_endereco_destino_l varchar2(4000);',
'    l_id_endereco_destino_i varchar2(4000);',
'    l_id_endereco_destino_h varchar2(4000);',
'     ',
'    v_new               imp_entrega%rowtype;',
'',
'begin',
'    ',
'    select * into v_new from imp_entrega where id = :P323_ID;       ',
'',
'    if v_new.data_disponivel_real is not null OR (v_new.data_disponivel_informada is null AND v_new.data_disponivel_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_entrega.data_disponivel_real'', l_disponibilidade_l, l_disponibilidade_i, l_disponibilidade_h);',
