'            USING OUT l_sql, IN :P324_PARAMETRO,:P324_PARAMETRO2;',
'    else',
'        l_sql := q''~',
'            select ',
'                null              id,',
'                null              campo1,             ',
'                null              campo2,             ',
'                null              campo3,             ',
'                null              campo4,             ',
