wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(690468091225534393)
,p_plug_name=>'Dados Gerais'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529595230508986982)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ',
'    j.id id,',
'    pkg_ui.retorna_label_tela(''dados_gerais'') titulo,    ',
'    pkg_componentes.retorna_icone_viatransporte_card(v.d,h.descricao_viatransporte) icon,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_exportador'', b.nome_fantasia , 2) atributo1,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_importador'', c.nome_fantasia , 2) atributo2,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_adquirente'', d.nome_fantasia , 2) atributo3,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_incoterm'', e.codigo_incoterm, 2) atributo4,',
'    pkg_componentes.html_card_colunas(''imp_pedidoimportacao.ind_modalidade_importacao'',',
'        pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'',''ind_modalidade_importacao'',j.ind_modalidade_importacao), 2',
'    ) atributo5,',
'    ''u-hidden'' class_distintivo',
'from imp_entrega j',
'join imp_pedidoimportacao a ON a.id = j.id_pedidoimportacao',
'join ng_pessoa_juridica b on b.id_pessoa = a.id_exportador',
'join ng_pessoa_juridica c on c.id_pessoa = a.id_importador',
'left join ng_pessoa_juridica d on d.id_pessoa = a.id_adquirente',
'join ng_incoterm e on e.id = a.id_incoterm',
'JOIN ng_viatransporte             h ON h.id = j.id_viatransporte',
'join vw_dom_ng_viatransporte v on v.r = h.icone_viatransporte',
'where (j.id = :P324_PARAMETRO) OR (j.id = :P324_ID)',
'',
'',
'',
'',
'',
'',
'',
'',
'-- select  ',
'--     j.id id,',
'--     pkg_ui.retorna_label_tela(''dados_gerais'') titulo,    ',
'--     pkg_componentes.retorna_icone_viatransporte_card(v.d,h.descricao_viatransporte) icon,',
'--     pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_exportador'', b.nome_fantasia || '' - '' || b.razao_social, 2) atributo1,',
'--     pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_importador'', c.nome_fantasia || '' - '' || c.razao_social, 2) atributo2,',
'--     pkg_componentes.html_card_colunas(''imp_pedidoimportacao.id_adquirente'', d.nome_fantasia || '' - '' || d.razao_social, 2) atributo3,',
