wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(250555609181175753)
,p_name=>'P324_COLUNAS'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(250470492364175116)
,p_prompt=>'Mova para a direita as colunas que deseja esconder'
,p_display_as=>'NATIVE_SHUTTLE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH colunas AS (',
'    SELECT ''CAMPO1'' id_coluna, :P324_LABEL_COLUNA1 label FROM dual UNION ALL',
'    SELECT ''CAMPO2'', :P324_LABEL_COLUNA2 FROM dual UNION ALL',
'    SELECT ''CAMPO3'', :P324_LABEL_COLUNA3 FROM dual UNION ALL',
'    SELECT ''CAMPO4'', :P324_LABEL_COLUNA4 FROM dual UNION ALL',
'    SELECT ''CAMPO5'', :P324_LABEL_COLUNA5 FROM dual UNION ALL',
'    SELECT ''CAMPO6'', :P324_LABEL_COLUNA6 FROM dual UNION ALL',
'    SELECT ''CAMPO7'', :P324_LABEL_COLUNA7 FROM dual UNION ALL',
'    SELECT ''CAMPO8'', :P324_LABEL_COLUNA8 FROM dual UNION ALL',
'    SELECT ''CAMPO9'', :P324_LABEL_COLUNA9 FROM dual UNION ALL',
'    SELECT ''CAMPO10'', :P324_LABEL_COLUNA10 FROM dual',
')',
'SELECT c.label d, c.id_coluna r',
'FROM colunas c',
'LEFT JOIN MPD_USUARIO_GRID_OCULTA_COLUNA u',
'    ON u.id_usuario = :ID_USUARIO_LOGADO',
'    AND u.codigo_artefato = :P324_CODIGO_ARTEFATO',
'    AND u.id_coluna LIKE ''%'' || c.id_coluna || ''%''',
'WHERE --u.id_coluna IS NULL and ',
'c.label is not null'))
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(529718889303987057)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'show_controls', 'MOVE')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
