'  CASE ',
'    WHEN data_registro_di_real IS NOT NULL THEN data_registro_di_real',
'    WHEN data_registro_di_informada IS NOT NULL THEN data_registro_di_informada',
'    ELSE data_registro_di_calculada',
'  END AS ddata_registro_di',
'',
'FROM imp_processoimportacao',
'',
