wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(187678834294407678)
,p_name=>unistr('P325_01_ID_ENDERE\00C7O_ORIGEM')
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(187675019677407611)
,p_prompt=>'&P325_ENDERECO_ORIGEM_L.'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    REGEXP_REPLACE(',
'        TRIM(',
'            COALESCE(b.logradouro, '''') ||',
'            CASE WHEN b.numero IS NOT NULL THEN '', '' || b.numero ELSE '''' END ||',
'            CASE WHEN b.complemento IS NOT NULL THEN '' - '' || b.complemento ELSE '''' END ||',
'            CASE WHEN b.bairro IS NOT NULL THEN '', '' || b.bairro ELSE '''' END ||',
'            CASE WHEN c.nome_cidade IS NOT NULL THEN '', '' || c.nome_cidade ELSE '''' END ||',
'            CASE WHEN d.sigla_uf IS NOT NULL THEN ''-'' || d.sigla_uf ELSE '''' END ||',
'            CASE WHEN e.nome_pais IS NOT NULL THEN '', '' || e.nome_pais ELSE '''' END',
'        ),',
'        ''^[, -]+|[, -]+$''',
'    ) AS endereco',
'FROM imp_processoimportacao             a',
'LEFT JOIN NG_PESSOA_ENDERECO b ON b.id = a.ID_ENDERECO_ORIGEM',
'LEFT JOIN NG_CIDADE          c ON c.id = b.id_cidade',
'LEFT JOIN NG_ESTADO          d ON d.id = b.id_estado',
'LEFT JOIN NG_PAIS            e ON e.id = b.id_pais',
'WHERE a.id = :P325_id'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_begin_on_new_line=>'N'
,p_field_template=>wwv_flow_imp.id(529718889303987057)
,p_item_css_classes=>'keep-visible'
,p_item_template_options=>'#DEFAULT#'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'VALUE',
  'format', 'PLAIN',
  'send_on_page_submit', 'Y',
  'show_line_breaks', 'Y')).to_clob
);
