,p_name=>'P325_06_DATA_RECEBIMENTO'
,p_item_sequence=>230
,p_item_plug_id=>wwv_flow_imp.id(187675019677407611)
,p_prompt=>'&P325_DATA_RECEBIMENTO_L.'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'  CASE ',
'    WHEN a.data_recebimento_real IS NOT NULL THEN a.data_recebimento_real',
'    WHEN a.data_recebimento_informada IS NOT NULL THEN a.data_recebimento_informada',
'    ELSE a.data_recebimento_calculada',
'  END AS data_recebimento',
'',
'FROM imp_processoimportacao a ',
'',
'WHERE a.id = :P325_ID;'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
