,p_process_name=>'Load labels'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_disponibilidade_l varchar2(4000);',
'    l_disponibilidade_i varchar2(4000);',
'    l_disponibilidade_h varchar2(4000);',
'',
'    l_embarque_l varchar2(4000);',
'    l_embarque_i varchar2(4000);',
'    l_embarque_h varchar2(4000);',
'',
'    l_desembarque_l varchar2(4000);',
'    l_desembarque_i varchar2(4000);',
'    l_desembarque_h varchar2(4000);',
'',
'    l_registro_di_l varchar2(4000);',
'    l_registro_di_i varchar2(4000);',
'    l_registro_di_h varchar2(4000);',
'',
'    l_nacionalizacao_l varchar2(4000);',
'    l_nacionalizacao_i varchar2(4000);',
'    l_nacionalizacao_h varchar2(4000);',
'',
'    l_recebimento_l varchar2(4000);',
'    l_recebimento_i varchar2(4000);',
'    l_recebimento_h varchar2(4000);',
'',
'    l_endereco_origem_l varchar2(4000);',
'    l_endereco_origem_i varchar2(4000);',
'    l_endereco_origem_h varchar2(4000);',
'',
'    l_local_embarque_l varchar2(4000);',
'    l_local_embarque_i varchar2(4000);',
'    l_local_embarque_h varchar2(4000);',
'',
'    l_local_desembarque_l varchar2(4000);',
'    l_local_desembarque_i varchar2(4000);',
'    l_local_desembarque_h varchar2(4000);',
'',
'    l_recinto_alfandegado_l varchar2(4000);',
'    l_recinto_alfandegado_i varchar2(4000);',
'    l_recinto_alfandegado_h varchar2(4000);',
'',
'    l_id_endereco_destino_l varchar2(4000);',
'    l_id_endereco_destino_i varchar2(4000);',
'    l_id_endereco_destino_h varchar2(4000);',
'',
'    v_new   imp_processoimportacao%rowtype;',
'',
'begin',
'    ',
'    select * into v_new from imp_processoimportacao where id = :P325_ID;       ',
'',
'    if v_new.data_disponivel_real is not null OR (v_new.data_disponivel_informada is null AND v_new.data_disponivel_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_disponivel_real'', l_disponibilidade_l, l_disponibilidade_i, l_disponibilidade_h);',
'    elsif v_new.data_disponivel_informada is not null then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_disponivel_informada'', l_disponibilidade_l, l_disponibilidade_i, l_disponibilidade_h);',
'    else',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_disponivel_calculada'', l_disponibilidade_l, l_disponibilidade_i, l_disponibilidade_h);',
'    end if;',
'',
'    if v_new.data_embarque_real is not null OR (v_new.data_embarque_informada is null AND v_new.data_embarque_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_embarque_real'', l_embarque_l, l_embarque_i, l_embarque_h);',
'    elsif v_new.data_embarque_informada is not null then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_embarque_informada'', l_embarque_l, l_embarque_i, l_embarque_h);',
'    else',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_embarque_calculada'', l_embarque_l, l_embarque_i, l_embarque_h);',
'    end if;',
'',
'    if v_new.data_desembarque_real is not null OR (v_new.data_desembarque_informada is null AND v_new.data_desembarque_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_desembarque_real'', l_desembarque_l, l_desembarque_i, l_desembarque_h);',
'    elsif v_new.data_desembarque_informada is not null then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_desembarque_informada'', l_desembarque_l, l_desembarque_i, l_desembarque_h);',
'    else',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_desembarque_calculada'', l_desembarque_l, l_desembarque_i, l_desembarque_h);',
'    end if;',
'',
'    if v_new.data_registro_di_real is not null OR (v_new.data_registro_di_informada is null AND v_new.data_registro_di_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_registro_di_real'', l_registro_di_l, l_registro_di_i, l_registro_di_h);',
'    elsif v_new.data_registro_di_informada is not null then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_registro_di_informada'', l_registro_di_l, l_registro_di_i, l_registro_di_h);',
'    else',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_registro_di_calculada'', l_registro_di_l, l_registro_di_i, l_registro_di_h);',
'    end if;',
'',
'    if v_new.data_nacionalizacao_real is not null OR (v_new.data_nacionalizacao_informada is null AND v_new.data_nacionalizacao_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_entrega.data_nacionalizacao_real'', l_nacionalizacao_l, l_nacionalizacao_i, l_nacionalizacao_h);',
'    elsif v_new.data_nacionalizacao_informada is not null then',
'        pkg_ui.retorna_coluna(''imp_entrega.data_nacionalizacao_informada'', l_nacionalizacao_l, l_nacionalizacao_i, l_nacionalizacao_h);',
'    else',
'        pkg_ui.retorna_coluna(''imp_entrega.data_nacionalizacao_calculada'', l_nacionalizacao_l, l_nacionalizacao_i, l_nacionalizacao_h);',
'    end if;',
'',
'    if v_new.data_recebimento_real is not null OR (v_new.data_recebimento_informada is null AND v_new.data_recebimento_calculada is null) then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_recebimento_real'', l_recebimento_l, l_recebimento_i, l_recebimento_h);',
'    elsif v_new.data_recebimento_informada is not null then',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_recebimento_informada'', l_recebimento_l, l_recebimento_i, l_recebimento_h);',
'    else',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.data_recebimento_calculada'', l_recebimento_l, l_recebimento_i, l_recebimento_h);',
'    end if;',
'',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.id_endereco_origem'', l_endereco_origem_l, l_endereco_origem_i, l_endereco_origem_h);',
'',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.id_local_embarque'', l_local_embarque_l, l_local_embarque_i, l_local_embarque_h);',
'',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.id_local_desembarque'', l_local_desembarque_l, l_local_desembarque_i, l_local_desembarque_h);',
'',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.id_recinto_alfandegado'', l_recinto_alfandegado_l, l_recinto_alfandegado_i, l_recinto_alfandegado_h);',
'',
'        pkg_ui.retorna_coluna(''imp_processoimportacao.id_endereco_destino'', l_id_endereco_destino_l, l_id_endereco_destino_i, l_id_endereco_destino_h);',
'',
'    :P325_DISPONIBILIDADE_PRODUTO_L := l_disponibilidade_l;',
'    :P325_DISPONIBILIDADE_PRODUTO_I := l_disponibilidade_i;',
'    :P325_DISPONIBILIDADE_PRODUTO_H := l_disponibilidade_h;',
'     ',
