,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    b.codigo_item,',
'    to_char(chamar_webservice_traducao(''wksp_teste'',''ng_item'',''descricao_item'',apex_util.get_session_state(''IDIOMA_LOGADO''),b.id)) descricao_item,',
'    c.codigo_unidademedida,',
'    case c.ind_tipo_dado',
'        when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'        when ''I'' then to_char(a.quantidade)',
'    end quantidade_importar,',
'    case c.ind_tipo_dado',
'        when ''D'' then to_char(a.quantidade_programar_entrega, ''FM999G999G990D00000'')',
'        when ''I'' then to_char(a.quantidade_programar_entrega)',
'    end quantidade_programar_entrega,',
'    case when a.id in d.id_pedidoimportacao_item or quantidade_programar_entrega > 0 then',
'        ''<input value="''||',
'        case c.ind_tipo_dado',
'            when ''D'' then to_char(d.quantidade, ''FM999G999G990D00000'')',
'            when ''I'' then to_char(d.quantidade)',
'        end ||''"></input>''',
'    end "INPUT"',
'from imp_pedidoimportacao_item a',
'join ng_item b on b.id = a.id_item',
'join ng_unidademedida c on c.id = a.id_unidademedida',
'left join imp_entrega_item d on d.id_pedidoimportacao_item = a.id',
'   and d.id_entrega = :P330_ID',
'where a.id_pedidoimportacao = :P330_PARAMETRO',
'order by d.quantidade, case when nvl(quantidade_programar_entrega, 0) > 0 then 1 else 2 end, a.num_sequencia_item'))
