'    ''<div id="id_saldo_''||a.id||''" class="arrowLink" title="&P330_LABEL_ATRIBUIR_SALDO." data-saldo="''||case c.ind_tipo_dado when ''D'' then case when a.id in d.id_pedidoimportacao_item then to_char((quantidade_programar_entrega + nvl(d.quantidade,0)),'
||'''FM999999990D00000'') else to_char(quantidade_programar_entrega,''FM999999990D00000'') end else case when a.id in d.id_pedidoimportacao_item then to_char(quantidade_programar_entrega + nvl(d.quantidade,0)) else to_char(quantidade_programar_entrega) end '
||'end||''">',
'        <a><span class="fa fa-long-arrow-right" aria-hidden="true"></span></a></div>'' atribuir,',
'    case when a.id in d.id_pedidoimportacao_item or quantidade_programar_entrega > 0 then',
'        ''<div class"t-form-itemwrapper" style="height:100%;">',
'            <input id="id_item_''||a.id||''" type="text" class="text_field apex-item-text" style="height:100%;" value="''||',
'                case c.ind_tipo_dado',
'                    when ''D'' then to_char(d.quantidade, ''FM999G999G990D00000'')',
'                    when ''I'' then to_char(d.quantidade)',
'                end ||''" maxLength="''||case c.ind_tipo_dado when ''D'' then length(to_char(a.quantidade, ''FM999G999G990D00000'')) when ''I'' then length(to_char(a.quantidade)) end||''"',
'                data-decimal-places="''||case c.ind_tipo_dado when ''D'' then ''5'' else ''0'' end||''" ',
'                data-integer-digits="''||nvl(length(regexp_substr(a.quantidade,''^[^.]+'')),0)||''"                ',
'                data-val-max="''||case c.ind_tipo_dado when ''D'' then case when a.id in d.id_pedidoimportacao_item then to_char((a.quantidade - quantidade_programar_entrega),''FM999G999G990D00000'') else to_char(quantidade_programar_entrega,''FM999G999G99'
||'0D00000'') end else case when a.id in d.id_pedidoimportacao_item then to_char(a.quantidade - quantidade_programar_entrega) else to_char(quantidade_programar_entrega) end end||''"',
'                data-id_entrega_item="''||d.id||''"',
'                onkeypress="return validateMaxValue(event,''||case c.ind_tipo_dado when ''D'' then case when a.id in d.id_pedidoimportacao_item then to_char((quantidade_programar_entrega + nvl(d.quantidade,0)),''FM999999990D00000'') else to_char(quantidad'
||'e_programar_entrega,''FM999999990D00000'') end else case when a.id in d.id_pedidoimportacao_item then to_char(quantidade_programar_entrega + nvl(d.quantidade,0)) else to_char(quantidade_programar_entrega) end end||'');">',
'            </input>',
'        </div>''',
'    end "INPUT"    ',
'from imp_pedidoimportacao_item a',
'join ng_item b on b.id = a.id_item',
'join ng_unidademedida c on c.id = a.id_unidademedida',
'left join imp_entrega_item d on d.id_pedidoimportacao_item = a.id',
'   and d.id_entrega = :P330_ID',
'where a.id_pedidoimportacao = :P330_PARAMETRO',
'--order by case when quantidade is not null then 1 else 2 end, case when nvl(quantidade_programar_entrega, 0) > 0 then 1 else 2 end, a.num_sequencia_item',
'order by',
'    case ',
'        when d.quantidade is not null then 1',
'        when a.quantidade_programar_entrega > 0 then 2',
'        else 3',
'    end,',
'    a.num_sequencia_item'))
