,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_label_codigo_item          varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_item.codigo_item'');',
'    l_label_descricao_item       varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_item.descricao_item'');',
'    l_label_codigo_unidademedida varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_unidademedida.codigo_unidademedida'');',
'    l_label_quantidade_importar  varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.quantidade'');',
'    l_label_saldo                varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.quantidade_programar_entrega'');',
'    l_label_atribuir_saldo_total varchar2(4000) := pkg_ui.retorna_label_tela(''atribuir_saldo_total'');',
'    l_label_atribuir_saldo       varchar2(4000) := pkg_ui.retorna_label_tela(''atribuir_saldo'');',
'    l_label_input                varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega_item.quantidade'');',
'    l_label_pesquisar            varchar2(4000) := pkg_ui.retorna_label_tela(''pesquisar'');',
'begin',
'    :P330_LABEL_CODIGO_ITEM          := l_label_codigo_item;',
'    :P330_LABEL_DESCRICAO_ITEM       := l_label_descricao_item;',
'    :P330_LABEL_CODIGO_UNIDADEMEDIDA := l_label_codigo_unidademedida;',
'    :P330_LABEL_QUANTIDADE_IMPORTAR  := l_label_quantidade_importar;',
'    :P330_LABEL_SALDO                := l_label_saldo;',
'    :P330_LABEL_ATRIBUIR_SALDO_TOTAL := l_label_atribuir_saldo_total;',
'    :P330_LABEL_ATRIBUIR_SALDO       := l_label_atribuir_saldo;',
'    :P330_LABEL_INPUT                := l_label_input;',
'    :P330_LABEL_PESQUISAR            := l_label_pesquisar;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>74284240570211600
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(159982164679876037)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'enviarParamentros'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_param1 varchar2(100) := apex_application.g_x01||''_''||APEX_CUSTOM_AUTH.GET_SESSION_ID;',
'    v_param2 varchar2(100) := apex_application.g_x02;',
'    v_param3 varchar2(100) := apex_application.g_x03;',
'    v_param4 varchar2(100) := apex_application.g_x04;',
'    v_existe number;',
'    v_id number;',
'begin',
unistr('    -- verifica se a cole\00E7\00E3o j\00E1 existe e a exclui para evitar duplica\00E7\00F5es'),
'    -- apex_debug.enable(apex_debug.c_log_level_info);',
'    -- apex_debug.info(''info enviarparamentros v_param1:%s'',v_param1); ',
'    -- apex_debug.info(''info enviarparamentros v_param2:%s'',v_param2); ',
'    -- apex_debug.info(''info enviarparamentros v_param3:%s'',v_param3); ',
'    -- apex_debug.info(''info enviarparamentros APEX_CUSTOM_AUTH.GET_SESSION_ID:%s'',APEX_CUSTOM_AUTH.GET_SESSION_ID); ',
'    if apex_application.g_x01 is not null then',
'        if upper(v_param2) = upper(''id_tenant'') and :P330_ID is null then',
'            :P0_TENANT_INFORMADO := v_param3;',
'        end if;',
'',
'        if not apex_collection.collection_exists(v_param1) then',
'            apex_collection.create_collection(v_param1);',
'        end if;',
'',
'        select count(1) into v_existe ',
'        from apex_collections',
'        where collection_name = v_param1',
'          and c001 = v_param2;',
'        if v_existe > 0 then',
'            select seq_id into v_id ',
'            from apex_collections',
'            where collection_name = v_param1',
'              and c001 = v_param2;',
'',
'            apex_collection.update_member (',
'                p_collection_name => v_param1,',
'                p_seq => v_id,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4);      ',
'        else',
'            apex_collection.add_member(',
'                p_collection_name => v_param1,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4',
'            );',
'        end if;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>74286637789211611
);
wwv_flow_imp_page.create_page_process(
