,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function validateInput(event) {',
'    const charCode = event.which || event.keyCode;',
unistr('    // Permite n\00FAmeros (0-9), ponto (.) e v\00EDrgula (,)'),
'    if (',
unistr('        !(charCode >= 48 && charCode <= 57) &&  // N\00FAmeros de 0 a 9'),
'        charCode !== 46 &&  // Ponto (.)',
unistr('        charCode !== 44     // V\00EDrgula (,)        '),
'    ) {',
unistr('        event.preventDefault();  // Bloqueia caracteres inv\00E1lidos'),
unistr('        return false;  // Impede a digita\00E7\00E3o'),
'    }',
'',
unistr('    return true;  // Permite a digita\00E7\00E3o de n\00FAmeros e caracteres v\00E1lidos'),
'}',
'',
unistr('const LABEL_DESATUALIZADA = "&P331_LABEL_DESATUALIZADA."; // APEX substitui na renderiza\00E7\00E3o'),
'',
'function formatarData(dataIso) {',
'    const IDIOMA_LOGADO = Number($v("IDIOMA_LOGADO"));',
'    if (!dataIso) return "";',
'',
'    const partes = dataIso.substring(0, 10).split("-");',
'    if (partes.length !== 3) return "";',
'',
'    const ano = partes[0];',
'    const mes = partes[1];',
'    const dia = partes[2];',
'',
'    if (IDIOMA_LOGADO === 2) {',
'        // americano',
'        return `${mes}/${dia}/${ano}`;',
'    } else {',
'        // brasileiro',
'        return `${dia}/${mes}/${ano}`;',
'    }',
'}',
'',
'function dataEhHoje(dataIso) {',
'    if (!dataIso) return false;',
'',
'    const hoje = new Date();',
'    const yyyy = hoje.getFullYear();',
'    const mm   = String(hoje.getMonth() + 1).padStart(2, "0");',
'    const dd   = String(hoje.getDate()).padStart(2, "0");',
'',
'    const hojeIso = `${yyyy}-${mm}-${dd}`;',
'    return dataIso.substring(0, 10) === hojeIso;',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
