,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_json                    clob;',
'    l_json_valores            clob;',
'    l_label_moeda             varchar2(4000) := pkg_ui.retorna_label_tela(''moeda'');',
'    l_label_valor_taxa_compra varchar2(4000) := pkg_ui.retorna_label_tela(''taxa_cambio'');',
'    l_label_data_cotacao      varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.data_cotacao'');',
'    l_label_valor             varchar2(4000) := pkg_ui.retorna_label_tela(''valor'');',
'    l_label_imprimir          varchar2(4000) := pkg_ui.retorna_label_botao(''imprimir'');',
'    l_label_desatualizada     varchar2(4000) := pkg_ui.retorna_label_tela(''desatualizada'');',
'    l_label_informada         varchar2(4000) := pkg_ui.retorna_label_tela(''informada'');',
'    l_label_nao_encontrada    varchar2(4000) := pkg_ui.retorna_label_tela(''nao_encontrada'');',
'    l_id_tenant               number;',
'    l_id_moeda_pedido         number;',
'begin    ',
'    select id_tenant, id_moeda into l_id_tenant, l_id_moeda_pedido from imp_pedidoimportacao where id = :P331_ID;',
'    select ',
'        json_arrayagg(',
'            json_object(',
'                ''display''      value a.codigo_moeda||'' - ''||a.simbolo_iso,',
'                ''return''       value a.id,',
'                ''taxa_cambio''  value to_char(bo_ng_moeda_cotacao.retorna_cotacao_compra(l_id_tenant, l_id_moeda_pedido, a.id),''FM999G999G990D000000''),--bo_ng_moeda_cotacao.retorna_cotacao_data((select id_moeda from imp_pedidoimportacao where id =:P33'
||'1_ID),a.id)',
'                ''data_cotacao'' value bo_ng_moeda_cotacao.retorna_cotacao_data_cotacao(l_id_tenant, l_id_moeda_pedido, a.id)',
'            ) order by codigo_moeda',
'        ) ',
'    into l_json',
'    from ng_moeda a;',
'    :P331_JSON_MOEDAS := l_json;',
'',
'    select ',
'        json_arrayagg(',
'            json_object(',
'                ''valor_mercadoria'' value a.valor_total_mercadoria,',
'                ''valor_desconto''   value a.valor_desconto,',
'                ''valor_despesa''    value a.valor_despesa_proforma,',
'                ''valor_total''      value a.valor_total_condicao_venda',
'            )',
'        )',
'    into l_json_valores',
'    from imp_pedidoimportacao a',
'    where a.id = :P331_ID;    ',
'    :P331_JSON_VALORES := l_json_valores;',
'',
'    :P331_LABEL_MOEDA             := l_label_moeda;',
'    :P331_LABEL_VALOR_TAXA_COMPRA := l_label_valor_taxa_compra;',
'    :P331_LABEL_DATA_COTACAO      := l_label_data_cotacao;',
'    :P331_LABEL_VALOR             := l_label_valor;',
'    :P331_LABEL_IMPRIMIR          := l_label_imprimir;',
'    :P331_LABEL_DESATUALIZADA     := l_label_desatualizada;',
'    :P331_LABEL_INFORMADA         := l_label_informada;',
'    :P331_LABEL_NAO_ENCONTRADA    := l_label_nao_encontrada;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>47157786708686635
);
end;
