'',
'    if (!selectMoeda) {',
unistr('        console.warn("Select de moeda n\00E3o encontrado");'),
'        return;',
'    }',
'',
'    // limpa select',
'    selectMoeda.innerHTML = "";',
'',
'    // cria options',
