'//                 <span style="color: #d00000; font-weight: 600;">',
'//                     <span ',
'//                         class="fa fa-exclamation-triangle"',
'//                         title="${LABEL_DESATUALIZADA}"',
'//                         style="margin-right: 4px;"',
'//                     ></span>',
'//                     ${dataFormatada}',
'//                 </span>',
'//             `;',
