'    var valorCbsFormatado = formatarValor(novoValorCbs);',
'    var valorAntidumpingFormatado = formatarValor(novoValorAntidumping);',
'    var valorIcmsFormatado = formatarValor(novoValorIcms);',
'    var valorIcmsStFormatado = formatarValor(novoValorIcmsSt);',
