wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(157281045825124831)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_json clob;',
'    l_json_valores clob;',
'    l_label_moeda              varchar2(4000) := pkg_ui.retorna_label_tela(''moeda'');',
'    l_label_valor_taxa_compra  varchar2(4000) := pkg_ui.retorna_label_tela(''taxa_cambio'');',
'    l_label_data_cotacao       varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.data_cotacao'');',
'    l_label_valores            varchar2(4000) := pkg_ui.retorna_label_tela(''valores'');',
'    l_label_valor              varchar2(4000) := pkg_ui.retorna_label_tela(''valor'');',
'    l_label_consultar_despesas varchar2(4000) := pkg_ui.retorna_label_tela(''consultar_despesas'');',
'    l_label_tributos           varchar2(4000) := pkg_ui.retorna_label_tela(''tributos'');',
'    l_label_consultar_tributos varchar2(4000) := pkg_ui.retorna_label_tela(''consultar_tributos'');',
'    l_label_despesas           varchar2(4000) := pkg_ui.retorna_label_tela(''despesas'');',
'    l_label_totais             varchar2(4000) := pkg_ui.retorna_label_tela(''totais'');',
'    l_label_imprimir           varchar2(4000) := pkg_ui.retorna_label_botao(''imprimir'');',
'    l_label_desatualizada      varchar2(4000) := pkg_ui.retorna_label_tela(''desatualizada'');',
'    l_label_informada          varchar2(4000) := pkg_ui.retorna_label_tela(''informada'');',
'    l_label_nao_encontrada     varchar2(4000) := pkg_ui.retorna_label_tela(''nao_encontrada'');',
'    l_id_tenant                number;',
'    l_id_moeda_pedido          number;',
'begin ',
'    select a.id_tenant, b.id_moeda into l_id_tenant, l_id_moeda_pedido from imp_entrega a join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao where a.id = :P332_ID;',
'    select ',
'        json_arrayagg(',
'            json_object(',
'                ''display''      value a.codigo_moeda||'' - ''||a.simbolo_iso,',
'                ''return''       value a.id,',
'                ''taxa_cambio''  value bo_ng_moeda_cotacao.retorna_cotacao_compra(l_id_tenant, l_id_moeda_pedido, a.id/*, :P332_MOEDA_PADRAO_TENANT*/),',
'                ''data_cotacao'' value bo_ng_moeda_cotacao.retorna_cotacao_data_cotacao(l_id_tenant, l_id_moeda_pedido, a.id/*, :P332_MOEDA_PADRAO_TENANT*/)',
'            ) order by codigo_moeda',
'        ) ',
'    into l_json',
'    from ng_moeda a;    ',
'    :P332_JSON_MOEDAS := l_json;',
'    ',
'    select ',
'        json_arrayagg(',
'            json_object(',
'                ''vmle'' ',
'                    value (',
'                        select ',
'                            sum(d.vmle)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_item c on c.id_entrega = b.id',
'                        left join imp_entrega_item_tributo d on d.id_entrega_item = c.id',
'                        where b.id = :P332_ID',
'                    ),',
'                ''frete'' ',
'                    value nvl((',
'                        select',
'                            (bo_ng_moeda_cotacao.retorna_cotacao_compra(a.id_tenant, c.id_moeda, a.id_moeda) * c.valor)',
'                            --(bo_ng_moeda_cotacao.retorna_cotacao_data(c.id_moeda,:P332_MOEDA_PADRAO_TENANT) * c.valor)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_despesa c on c.id_entrega = b.id',
'                        left join ng_despesa d on d.id = c.id_despesa',
'                        where b.id = :P332_ID',
'                        and d.ind_tipo_despesa = 9',
'                    ), 0),',
'                ''seguro'' ',
'                    value nvl((',
'                        select ',
'                            (bo_ng_moeda_cotacao.retorna_cotacao_compra(a.id_tenant, c.id_moeda, a.id_moeda) * c.valor)',
'                            --(bo_ng_moeda_cotacao.retorna_cotacao_data(c.id_moeda,:P332_MOEDA_PADRAO_TENANT) * c.valor)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_despesa c on c.id_entrega = b.id',
'                        left join ng_despesa d on d.id = c.id_despesa',
'                        where b.id = :P332_ID',
'                        and d.ind_tipo_despesa = 10',
'                    ), 0),',
'                ''acrescimo'' ',
'                    value nvl((',
'                        select',
'                            (bo_ng_moeda_cotacao.retorna_cotacao_compra(a.id_tenant, c.id_moeda, a.id_moeda) * c.valor) ',
'                            --(bo_ng_moeda_cotacao.retorna_cotacao_data(c.id_moeda,:P332_MOEDA_PADRAO_TENANT) * c.valor)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_despesa c on c.id_entrega = b.id',
'                        left join ng_despesa d on d.id = c.id_despesa',
'                        where b.id = :P332_ID',
'                        and d.ind_tipo_despesa = 16',
'                    ), 0),',
'                ''vmld'' ',
'                    value nvl((',
'                        select ',
'                            sum(d.vmld)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_item c on c.id_entrega = b.id',
'                        left join imp_entrega_item_tributo d on d.id_entrega_item = c.id',
'                        where b.id = :P332_ID',
'                    ), 0),                ',
'                ''valor_ii'' ',
'                    value (',
'                        select',
'                            sum(d.valor_ii)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_item c on c.id_entrega = b.id',
'                        left join imp_entrega_item_tributo d on d.id_entrega_item = c.id',
'                        where b.id = :P332_ID',
'                    ),',
'                ''valor_ipi'' ',
'                    value (',
'                        select ',
'                            sum(d.valor_ipi)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_item c on c.id_entrega = b.id',
'                        left join imp_entrega_item_tributo d on d.id_entrega_item = c.id',
'                        where b.id = :P332_ID',
'                    ),',
'                ''valor_pis'' ',
'                    value (',
'                        select',
'                            sum(d.valor_pis)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_item c on c.id_entrega = b.id',
'                        left join imp_entrega_item_tributo d on d.id_entrega_item = c.id',
'                        where b.id = :P332_ID',
'                    ),',
'                ''valor_cofins'' ',
'                    value (',
'                        select ',
'                            sum(d.valor_cofins)',
'                        from imp_pedidoimportacao a',
'                        join imp_entrega b on b.id_pedidoimportacao = a.id',
'                        left join imp_entrega_item c on c.id_entrega = b.id',
'                        left join imp_entrega_item_tributo d on d.id_entrega_item = c.id',
'                        where b.id = :P332_ID',
'                    ),',
'                ''valor_cbs'' ',
'                    value (',
'                        select ',
