,p_plug_name=>'Itens'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529595230508986982)
,p_plug_display_sequence=>50
,p_plug_grid_column_span=>10
,p_plug_display_column=>2
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    pkg_ui.retorna_label_tela(''itens'') titulo,',
'',
'    pkg_componentes.html_card_colunas(',
'        pkg_ui.retorna_label_tela(''quantidade_itens_processo''),',
'        count(a.id),',
'        2,',
'        ''s''',
'    ) atributo1,',
'',
'    pkg_componentes.html_card_colunas(',
'        ''imp_processoimportacao_item.peso_liquido_total'',',
'        to_char(nvl(sum(a.peso_liquido_total),0),''FM999G999G990D000''),',
'        2',
'    ) atributo2,',
'',
'    case',
'        when lower(b.ind_itens_vinculado_invoice) = ''n'' then',
'            pkg_componentes.html_card_colunas(',
'                ''imp_processoimportacao.ind_itens_vinculado_invoice'',',
'                pkg_componentes.html_cor_texto(',
'                    pkg_util.dominio_retorna_tag(',
'                        ''imp_processoimportacao'',',
'                        ''ind_itens_vinculado_invoice'',',
'                        b.ind_itens_vinculado_invoice',
'                    )',
'                ),',
'                2',
'            )',
'        else',
'            pkg_componentes.html_card_colunas(',
'                ''imp_processoimportacao.ind_itens_vinculado_invoice'',',
'                pkg_util.dominio_retorna_tag(',
'                    ''imp_processoimportacao'',',
'                    ''ind_itens_vinculado_invoice'',',
'                    b.ind_itens_vinculado_invoice',
'                ),',
'                2',
'            )',
'    end atributo3,',
'',
'    pkg_componentes.html_card_colunas('''', '''', 2, ''s'') atributo4,',
'    pkg_componentes.html_card_colunas('''', '''', 2, ''s'') atributo5,',
'',
'    ''u-hidden'' class_distintivo',
'',
'from imp_processoimportacao b',
'left join imp_processoimportacao_item a',
'    on a.id_processoimportacao = b.id',
'',
'where b.id = :P333_PARAMETRO',
'',
'group by',
'    b.ind_itens_vinculado_invoice,',
'    pkg_util.dominio_retorna_tag(',
'        ''imp_processoimportacao'',',
'        ''ind_itens_vinculado_invoice'',',
'        b.ind_itens_vinculado_invoice',
'    )',
'-- select',
'--     pkg_ui.retorna_label_tela(''itens'') titulo,    ',
'--     pkg_componentes.html_card_colunas(pkg_ui.retorna_label_tela(''quantidade_itens_processo''), count(a.id), 2, ''s'') atributo1,',
'--     pkg_componentes.html_card_colunas(''imp_processoimportacao_item.peso_liquido_total'',',
'--         to_char(nvl(sum(a.peso_liquido_total),0), ''FM999G999G990D000''), 2',
'--     ) atributo2,',
'--     case ',
'--         when lower(b.ind_itens_vinculado_invoice) = ''n'' then',
'--             pkg_componentes.html_card_colunas(''imp_processoimportacao.ind_itens_vinculado_invoice'',',
'--                 pkg_componentes.html_cor_texto(',
'--                     pkg_util.dominio_retorna_tag(''imp_processoimportacao'', ''ind_itens_vinculado_invoice'', b.ind_itens_vinculado_invoice)',
'--                 ), 2',
'--             ) ',
'--         else',
'--             pkg_componentes.html_card_colunas(''imp_processoimportacao.ind_itens_vinculado_invoice'',',
'--                 pkg_util.dominio_retorna_tag(''imp_processoimportacao'', ''ind_itens_vinculado_invoice'', b.ind_itens_vinculado_invoice), 2)',
'--     end atributo3,',
'--     pkg_componentes.html_card_colunas('''', '''', 2, ''s'') atributo4,',
'--     pkg_componentes.html_card_colunas('''', '''', 2, ''s'') atributo5,',
'--     ''u-hidden'' class_distintivo',
'-- from imp_processoimportacao b',
'-- left join imp_processoimportacao_item a on b.id = a.id_processoimportacao',
'-- where a.id_processoimportacao = :P333_PARAMETRO',
'-- group by b.ind_itens_vinculado_invoice, pkg_util.dominio_retorna_tag(''imp_processoimportacao'', ''ind_itens_vinculado_invoice'', b.ind_itens_vinculado_invoice)'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P333_PARAMETRO'
,p_plug_query_num_rows=>15
