,p_plug_name=>'Valores'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529595230508986982)
,p_plug_display_sequence=>70
,p_plug_grid_column_span=>10
,p_plug_display_column=>2
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    a.id id,    ',
'    pkg_ui.retorna_label_tela(''valores'') titulo,    ',
'    pkg_componentes.html_card_colunas(''imp_processoimportacao.id_moeda_tenant'', ',
'        b.codigo_moeda||'' - ''||b.simbolo_iso, 2',
'    ) atributo1,    ',
'    pkg_componentes.html_card_colunas(''imp_processoimportacao.vmle'',         ',
'        to_char((select ',
'            sum(c1.vmle)',
'        from imp_processoimportacao a1                        ',
'        join imp_processoimportacao_item b1 on b1.id_processoimportacao = a1.id',
'        join imp_processoimportacao_item_tributo c1 on c1.id_processoimportacao_item = b1.id',
'        where a1.id = :P333_PARAMETRO), ''FM999G999G990D00''), 2',
'    ) atributo2,',
'    pkg_componentes.html_card_colunas(''imp_processoimportacao.vmld'', ',
'        to_char((select ',
'            sum(c1.vmle) + bo_imp_processoimportacao_item_tributo.calcula_total_despesa_base_calculo_processo(:P333_PARAMETRO,10,''s'')',
'        from imp_processoimportacao a1                        ',
'        join imp_processoimportacao_item b1 on b1.id_processoimportacao = a1.id',
'        join imp_processoimportacao_item_tributo c1 on c1.id_processoimportacao_item = b1.id',
'        where a1.id = :P333_PARAMETRO), ''FM999G999G990D00''), 2',
'    ) atributo3,',
'    pkg_componentes.html_card_colunas(pkg_ui.retorna_label_tela(''total_tributos''), ',
'        to_char(bo_imp_processoimportacao.retorna_total_tributos(a.id, ''s''), ''FM999G999G990D00''), 2, ''s''',
'    ) atributo4,',
'    pkg_componentes.html_card_colunas(pkg_ui.retorna_label_tela(''despesa_nao_inclusa_vmld''), ',
'        to_char(bo_imp_processoimportacao.retorna_total_despesas(a.id, ''s''), ''FM999G999G990D00''), 2, ''s''',
'    ) atributo5,',
'    pkg_componentes.html_card_colunas(pkg_ui.retorna_label_tela(''total_importacao''), ',
'        to_char(',
'        (select ',
'            sum(c1.vmle) + bo_imp_processoimportacao_item_tributo.calcula_total_despesa_base_calculo_processo(:P333_PARAMETRO,10,''s'')',
'        from imp_processoimportacao a1                        ',
'        join imp_processoimportacao_item b1 on b1.id_processoimportacao = a1.id',
'        join imp_processoimportacao_item_tributo c1 on c1.id_processoimportacao_item = b1.id',
'        where a1.id = :P333_PARAMETRO) ',
'      + nvl(bo_imp_processoimportacao.retorna_total_tributos(a.id),0) ',
'      + nvl(bo_imp_processoimportacao.retorna_total_despesas(a.id, ''s''),0), ''FM999G999G990D00''), 2, ''s''',
'    ) atributo6,',
'    ''u-hidden'' class_distintivo',
'from imp_processoimportacao a',
'join ng_moeda b on b.id = a.id_moeda_tenant',
'where a.id = :P333_PARAMETRO'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P333_PARAMETRO'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_plug_display_when_condition=>'P333_CARD_OU_LISTA'
,p_plug_display_when_cond2=>'CARD'
,p_ai_enabled=>false
);
