wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(194979277054629126)
,p_plug_name=>unistr('Hist\00F3rico')
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529595230508986982)
,p_plug_display_sequence=>80
,p_plug_grid_column_span=>10
,p_plug_display_column=>2
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'return q''[',
'with dados_auditoria as (',
'    select ',
'        case',
'            when ',
'                (',
'                (json_exists(l.dados_novos, ''$[*].ind_status'') and nome_entidade = ''imp_processoimportacao'') or',
'                json_exists(l.dados_novos, ''$[*].ind_modalidade_importacao'') or',
'                json_exists(l.dados_novos, ''$[*]?(@.id_endereco_origem != null)'') or',
'                json_exists(l.dados_novos, ''$[*]?(@.id_local_embarque != null)'') or',
'                json_exists(l.dados_novos, ''$[*]?(@.id_local_desembarque != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.id_local_armazenagem != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.id_endereco_destino != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*].id_viatransporte'') or                ',
'                json_exists(l.dados_novos, ''$[*].ind_itens_vinculado_invoice'') or',
'                json_exists(l.dados_novos, ''$[*].ind_autorizacao_embarque'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.data_disponivel_real != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.data_embarque_real != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.data_desembarque_real != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.data_registro_di_real != null)'') or',
'                json_exists(l.dados_novos, ''$[*]?(@.data_nacionalizacao_real != null)'') or                ',
'                json_exists(l.dados_novos, ''$[*]?(@.data_recebimento_real != null)'') or',
'                (json_exists(l.dados_novos, ''$[*].ind_status'') and nome_entidade = ''imp_invoice'')',
'                )',
'            then to_char(l.data_operacao, ''dd/mm/yyyy hh24:mi:ss'')                    ',
'        end as data_operacao,',
'        case ',
'            when l.nome_entidade = ''imp_invoice'' ',
'                 and (                     ',
'                     json_exists(l.dados_novos, ''$[*]?(@.ind_status != null && @.ind_status != "")'')',
'                 )',
'                then',
'                     (select num_invoice from imp_invoice e where e.id = l.id_registro)',
'            else '''' ',
'        end invoice,',
'        case',
'            when json_exists(l.dados_novos, ''$[*].ind_status'') and nome_entidade = ''imp_processoimportacao'' ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_status'')',
'            when json_exists(l.dados_novos, ''$[*].ind_modalidade_importacao'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_modalidade_importacao'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_endereco_origem != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_endereco_origem'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_local_embarque != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_local_embarque'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_local_desembarque != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_local_desembarque'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_local_armazenagem != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_local_armazenagem'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_endereco_destino != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_endereco_destino'')',
'            when json_exists(l.dados_novos, ''$[*].id_viatransporte'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_viatransporte'')',
'            when json_exists(l.dados_novos, ''$[*].ind_itens_vinculado_invoice'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_itens_vinculado_invoice'')',
'            when json_exists(l.dados_novos, ''$[*].ind_autorizacao_embarque'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_autorizacao_embarque'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_disponivel_real != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.data_disponivel_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_embarque_real != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.data_embarque_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_desembarque_real != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.data_desembarque_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_registro_di_real != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.data_registro_di_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_nacionalizacao_real != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.data_nacionalizacao_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_recebimento_real != null)'') ',
'                then pkg_ui.retorna_label_coluna(''imp_processoimportacao.data_recebimento_real'')',
'            when json_exists(l.dados_novos, ''$[*].ind_status'') and nome_entidade = ''imp_invoice'' ',
'                then pkg_ui.retorna_label_coluna(''imp_invoice.ind_status'')',
'        end campo,',
'        case',
'            when json_exists(l.dados_novos, ''$[*].ind_status'') and nome_entidade = ''imp_processoimportacao''',
'                then pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_status'',',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''ind_status''))',
'            when json_exists(l.dados_novos, ''$[*].ind_modalidade_importacao'') ',
'                then pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_modalidade_importacao'',',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''ind_modalidade_importacao''))',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_endereco_origem != null)'') ',
'                then (select titulo_endereco from ng_pessoa_endereco where id = bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''id_endereco_origem''))',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_local_embarque != null)'') ',
'                then to_char(chamar_webservice_traducao(''wksp_teste'',''ng_localembarquedesembarque'',''nome_local'',',
'                     apex_util.get_session_state(''IDIOMA_LOGADO''),',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''id_local_embarque'')))',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_local_desembarque != null)'') ',
'                then to_char(chamar_webservice_traducao(''wksp_teste'',''ng_localembarquedesembarque'',''nome_local'',',
'                     apex_util.get_session_state(''IDIOMA_LOGADO''),',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''id_local_desembarque'')))',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_local_armazenagem != null)'') ',
'                then (select titulo_endereco from ng_pessoa_endereco where id = bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''id_local_armazenagem''))',
'            when json_exists(l.dados_novos, ''$[*]?(@.id_endereco_destino != null)'') ',
'                then (select titulo_endereco from ng_pessoa_endereco where id = bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''id_endereco_destino''))',
'            when json_exists(l.dados_novos, ''$[*].id_viatransporte'') ',
'                then to_char(chamar_webservice_traducao(''wksp_teste'',''ng_viatransporte'',''descricao_viatransporte'',',
'                     apex_util.get_session_state(''IDIOMA_LOGADO''),',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''id_viatransporte'')))',
'            when json_exists(l.dados_novos, ''$[*].ind_itens_vinculado_invoice'') ',
'                then pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_itens_vinculado_invoice'',',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''ind_itens_vinculado_invoice''))',
'            when json_exists(l.dados_novos, ''$[*].ind_autorizacao_embarque'') ',
'                then pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_autorizacao_embarque'',',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''ind_autorizacao_embarque''))',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_disponivel_real != null)'') ',
'                then bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''data_disponivel_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_embarque_real != null)'') ',
'                then bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''data_embarque_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_desembarque_real != null)'') ',
'                then bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''data_desembarque_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_registro_di_real != null)'') ',
'                then bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''data_registro_di_real'')            ',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_nacionalizacao_real != null)'') ',
'                then bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''data_nacionalizacao_real'')',
'            when json_exists(l.dados_novos, ''$[*]?(@.data_recebimento_real != null)'') ',
'                then bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''data_recebimento_real'')',
'            when json_exists(l.dados_novos, ''$[*].ind_status'') and nome_entidade = ''imp_invoice''',
'                then pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_status'',',
'                     bo_imp_pedidoimportacao.retorna_auditoria_log(l.dados_novos,''ind_status''))',
'        end valor',
'    from srv_auditoria_log l',
'    where (',
'        (l.nome_entidade = ''imp_processoimportacao'' and l.id_registro = :P333_ID)',
'        or',
'        (l.nome_entidade = ''imp_invoice'' and l.id_registro in ',
'            (select id from imp_invoice where id_processoimportacao = :P333_ID))',
'    )    ',
'    and ',
'        (',
'            (json_exists(l.dados_novos, ''$[*]?(@.ind_status != null && @.ind_status != "")'') and nome_entidade = ''imp_processoimportacao'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.ind_modalidade_importacao != null && @.ind_modalidade_importacao != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.id_endereco_origem != null && @.id_endereco_origem != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.id_local_embarque != null && @.id_local_embarque != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.id_local_desembarque != null && @.id_local_desembarque != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.id_local_armazenagem != null && @.id_local_armazenagem != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.id_endereco_destino != null && @.id_endereco_destino != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.id_viatransporte != null && @.id_viatransporte != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.ind_itens_vinculado_invoice != null && @.ind_itens_vinculado_invoice != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.ind_autorizacao_embarque != null && @.ind_autorizacao_embarquee != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.data_disponivel_real != null && @.data_disponivel_real != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.data_embarque_real != null && @.data_embarque_real != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.data_desembarque_real != null && @.data_desembarque_real != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.data_registro_di_real != null && @.data_registro_di_real != "")'') or            ',
'            json_exists(l.dados_novos, ''$[*]?(@.data_nacionalizacao_real != null && @.data_nacionalizacao_real != "")'') or',
'            json_exists(l.dados_novos, ''$[*]?(@.data_recebimento_real != null && @.data_recebimento_real != "")'') or',
'            (json_exists(l.dados_novos, ''$[*]?(@.ind_status != null && @.ind_status != "")'') and nome_entidade = ''imp_invoice'')',
'        )    ',
'',
'    union all    ',
'',
'    select ',
'        to_char(o.data_alteracao, ''dd/mm/yyyy hh24:mi:ss'') data_operacao,',
'        case when e.num_invoice is not null ',
'             then e.num_invoice',
'             else '''' end invoice,',
'        pkg_ui.retorna_label_tela(''observacao'') campo,',
'        to_char(chamar_webservice_traducao(''wksp_teste'',''imp_observacao'',''observacao'',',
'             apex_util.get_session_state(''IDIOMA_LOGADO''),o.id)) valor',
'    from imp_observacao o',
'    left join imp_processoimportacao p on p.id = o.id_referencia',
'    left join imp_invoice e on e.id = o.id_referencia',
'    where (p.id = :P333_ID or e.id_processoimportacao = :P333_ID)',
')',
'select ',
'    pkg_ui.retorna_label_tela(''historico'') titulo,',
'',
'    -- pkg_componentes.html_card_colunas(',
'    --     ''srv_auditoria_log.data_operacao'',',
'    --     (select data_operacao ',
'    --      from dados_auditoria ',
'    --      order by to_timestamp(data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc, pkg_ui.retorna_label_coluna(campo)',
'    --      fetch first 1 rows only), 3',
'    -- ) atributo1,',
'',
'    -- pkg_componentes.html_card_colunas(',
'    --     pkg_ui.retorna_label_coluna(''imp_invoice.num_invoice''),',
'    --     coalesce(',
'    --         (select invoice',
'    --          from dados_auditoria ',
'    --          where invoice is not null ',
'    --          order by to_timestamp(data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc, pkg_ui.retorna_label_coluna(campo)',
'    --          fetch first 1 rows only),',
'    --         (select '''' from dual)',
'    --     ), 3, ''s''',
'    -- ) atributo2,',
'',
'    pkg_componentes.html_card_colunas(',
'        pkg_ui.retorna_label_botao(''campo''),',
'        coalesce(',
'            (select campo ',
'             from dados_auditoria ',
'             where campo is not null ',
'             order by to_timestamp(data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc, pkg_ui.retorna_label_coluna(campo)',
'             fetch first 1 rows only),',
'            (select campo ',
'             from dados_auditoria ',
'             order by to_timestamp(data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc, pkg_ui.retorna_label_coluna(campo)',
'             fetch first 1 rows only)',
'        ), 3, ''s''',
'    ) atributo3,',
'',
'    pkg_componentes.html_card_colunas(',
'        pkg_ui.retorna_label_tela(''valor''),',
'        coalesce(',
'            (select valor ',
'             from dados_auditoria ',
'             where valor is not null ',
'             order by to_timestamp(data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc, pkg_ui.retorna_label_coluna(campo)',
'             fetch first 1 rows only),',
'            (select valor ',
'             from dados_auditoria ',
'             order by to_timestamp(data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc, pkg_ui.retorna_label_coluna(campo)',
'             fetch first 1 rows only)',
'        ), 9, ''s''',
'    ) atributo4,',
'',
'    ''u-hidden'' class_distintivo',
'from imp_processoimportacao a',
'where a.id = :P333_PARAMETRO',
']'';'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P333_PARAMETRO'
