,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_ind_status number;',
'    l_html clob;',
'begin',
'    select ind_status into l_ind_status from imp_processoimportacao where id = :P333_PARAMETRO;',
'    if l_ind_status in (6,7,8) then',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                    b.numero_duimp',
'                from imp_processoimportacao a ',
'                left join imp_declaracaoimportacao b on b.id_processoimportacao = a.id',
'                where a.id = ''||nvl(:P333_PARAMETRO, :P333_ID),',
'            p_tabela => textarray(''imp_processoimportacao'', ''imp_processoimportacao'',''imp_declaracaoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'    else',
'    l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''', ''''ind_status'''', a.ind_status) ind_status',
'                from imp_processoimportacao a ',
'                left join imp_declaracaoimportacao b on b.id_processoimportacao = a.id',
'                where a.id = ''||nvl(:P333_PARAMETRO, :P333_ID),',
'            p_tabela => textarray(''imp_processoimportacao'', ''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'    end if;',
'    return l_html;',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P333_PARAMETRO'
,p_ai_enabled=>false
);
