prompt --application/pages/page_00334
begin
wwv_flow_imp_page.create_page(
 p_id=>334
,p_name=>unistr('Valores do processo de importa\00E7\00E3o')
,p_alias=>unistr('VALORES-DO-PROCESSO-DE-IMPORTA\00C7\00C3O')
,p_page_mode=>'MODAL'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function validateInput(event) {',
'    const charCode = event.which || event.keyCode;',
unistr('    // Permite n\00FAmeros (0-9), ponto (.) e v\00EDrgula (,)'),
'    if (',
unistr('        !(charCode >= 48 && charCode <= 57) &&  // N\00FAmeros de 0 a 9'),
'        charCode !== 46 &&  // Ponto (.)',
unistr('        charCode !== 44     // V\00EDrgula (,)        '),
'    ) {',
unistr('        event.preventDefault();  // Bloqueia caracteres inv\00E1lidos'),
unistr('        return false;  // Impede a digita\00E7\00E3o'),
'    }',
'',
unistr('    return true;  // Permite a digita\00E7\00E3o de n\00FAmeros e caracteres v\00E1lidos'),
'}',
'',
unistr('const LABEL_DESATUALIZADA = "&P334_LABEL_DESATUALIZADA."; // APEX substitui na renderiza\00E7\00E3o'),
'',
'function formatarData(dataIso) {',
'    const IDIOMA_LOGADO = Number($v("IDIOMA_LOGADO"));',
'    if (!dataIso) return "";',
'',
'    const partes = dataIso.substring(0, 10).split("-");',
'    if (partes.length !== 3) return "";',
'',
'    const ano = partes[0];',
'    const mes = partes[1];',
'    const dia = partes[2];',
'',
'    if (IDIOMA_LOGADO === 2) {',
'        // americano',
'        return `${mes}/${dia}/${ano}`;',
'    } else {',
'        // brasileiro',
'        return `${dia}/${mes}/${ano}`;',
'    }',
'}',
'',
'function dataEhHoje(dataIso) {',
'    if (!dataIso) return false;',
'',
'    const hoje = new Date();',
'    const yyyy = hoje.getFullYear();',
'    const mm   = String(hoje.getMonth() + 1).padStart(2, "0");',
'    const dd   = String(hoje.getDate()).padStart(2, "0");',
'',
'    const hojeIso = `${yyyy}-${mm}-${dd}`;',
'    return dataIso.substring(0, 10) === hojeIso;',
'}',
'',
'function formatarValor(valor) {',
'    if (isNaN(valor)) return '''';',
'',
'    var partes = valor.toFixed(6).split(''.'');',
'    var inteiro = partes[0];',
'    var decimal = partes[1];',
'',
'    inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, ''.'');',
'',
'    return inteiro + '','' + decimal;',
'}',
'',
'function formatarValor2(valor) {',
'    if (isNaN(valor)) return '''';',
'',
'    var partes = valor.toFixed(2).split(''.'');',
'    var inteiro = partes[0];',
'    var decimal = partes[1];',
'',
'    inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, ''.'');',
'',
'    return inteiro + '','' + decimal;',
'}',
'',
'function atualizarDataMoeda(dataEl, moeda) {',
'',
'    if (!dataEl || !moeda || !moeda.data_cotacao) {',
'        var naoEncontrada = $v(''P334_LABEL_NAO_ENCONTRADA'');',
'',
'        dataEl.innerHTML = `',
'            <span style="color: #d00000; font-weight: 600;">',
'                <span ',
'                    class="fa fa-exclamation-triangle"',
'                    title="${naoEncontrada}"',
'                    style="margin-right: 4px;"',
'                ></span>',
'                ${naoEncontrada}',
'            </span>',
'        `;',
'        return;',
'    }',
'',
'    const dataFormatada = formatarData(moeda.data_cotacao);',
'    const ehHoje = dataEhHoje(moeda.data_cotacao);',
'',
'    if (ehHoje) {',
'        dataEl.innerHTML = `<span>${dataFormatada}</span>`;',
'    } else {',
'        // dataEl.innerHTML = `',
'        //     <span style="color: #d00000; font-weight: 600;">',
'        //         <span ',
'        //             class="fa fa-exclamation-triangle"',
'        //             title="${LABEL_DESATUALIZADA}"',
'        //             style="margin-right: 4px;"',
'        //         ></span>',
'        //         ${dataFormatada}',
'        //     </span>',
'        // `;',
'        dataEl.innerHTML = `',
'            <span>',
'                ${dataFormatada}',
'            </span>',
'        `;',
'    }',
'}',
'',
'function parseNumero(valor) {',
'  if (!valor) return 0;',
'',
'  valor = valor.trim();',
'',
unistr('  // Se tem v\00EDrgula e ponto \2192 detecta qual \00E9 decimal (\00FAltimo separador)'),
'  if (valor.includes(",") && valor.includes(".")) {',
'    if (valor.lastIndexOf(",") > valor.lastIndexOf(".")) {',
'      // formato BR: 1.234,56',
'      valor = valor.replace(/\./g, "").replace(",", ".");',
'    } else {',
'      // formato EN: 1,234.56',
'      valor = valor.replace(/,/g, "");',
'    }',
'  } else if (valor.includes(",")) {',
unistr('    // pode ser decimal com v\00EDrgula'),
'    valor = valor.replace(",", ".");',
'  }',
'',
'  return parseFloat(valor) || 0;',
'}',
'',
'function formatarNumero(numero) {',
'  return new Intl.NumberFormat().format(numero);',
'}',
'',
'function calcularTotalVMLD() {',
'  function getVal(id) {',
'    let v = $("#" + id).text();',
'    return parseNumero(v);',
'  }',
'',
'  let total =',
'    getVal("vmle") +',
'    getVal("frete") +',
'    getVal("seguro") +',
'    getVal("acrescimo");',
'',
'  $("#vmld").text(formatarValor2(total));  ',
'}',
'',
'function calcularTotalTributos() {',
'  function getVal(id) {',
'    let v = $("#" + id).text();',
'    return parseNumero(v);',
'  }',
'',
'  let total =',
'    getVal("valor_ii") +',
'    getVal("valor_ipi") +',
'    getVal("valor_pis") +',
'    getVal("valor_cofins") +',
'    getVal("valor_cbs") +',
'    getVal("antidumping") +',
'    getVal("valor_icms") +',
'    getVal("valor_icms_st") +',
'    getVal("valor_ibs") +',
'    getVal("multa")',
'',
'  $("#total_tributos").text(formatarValor2(total));  ',
'}',
'',
'function calcularTotalDespesas() {',
'  let total = 0;',
'',
'  $("[id^=''despesa_outras_despesas_'']").each(function () {',
'    let valorTexto = $(this).text();',
'',
unistr('    // sua fun\00E7\00E3o que converte texto para n\00FAmero'),
'    let valor = parseNumero(valorTexto);',
'',
'    total += valor || 0;',
'  });',
'',
'  $("#total_despesas").text(formatarValor2(total));',
'}'))
