'function atualizarData() {',
'        const moeda = moedas.find(',
'            m => String(m.return) === String(selectMoeda.value)',
'        );',
'',
'        if (!dataEl || !moeda || !moeda.data_cotacao) {',
'',
'            $("#taxa_cambio_moeda_pedido").val("1,000000");',
'            //$("#taxa_cambio_moeda_pedido").val(taxaDeCambio).trigger(''change'');',
'            $("#taxa_cambio_moeda_pedido").trigger(''change'');',
'',
'            var naoEncontrada = $v(''P334_LABEL_NAO_ENCONTRADA'');',
'            if (dataEl) dataEl.innerHTML = `',
'                <span style="color: #d00000; font-weight: 600;">',
'                    <span ',
'                        class="fa fa-exclamation-triangle"',
'                        title="${naoEncontrada}"',
'                        style="margin-right: 4px;"',
'                    ></span>',
'                    ${naoEncontrada}',
'                </span>',
'            `;',
'            return;',
'        }',
'',
'        const dataFormatada = formatarData(moeda.data_cotacao);',
'        const ehHoje = dataEhHoje(moeda.data_cotacao);',
'',
'        if (ehHoje) {',
unistr('            // data atual \2192 normal'),
'            dataEl.innerHTML = `<span>${dataFormatada}</span>`;',
'        } else {',
unistr('            // desatualizada \2192 vermelho + \00EDcone + tooltip'),
