'            //             style="margin-right: 4px;"',
'            //         ></span>',
'            //         ${dataFormatada}',
'            //     </span>',
'            // `;',
'            dataEl.innerHTML = `',
'                <span>',
'                    ${dataFormatada}',
'                </span>',
'            `;',
'        }        ',
'    }',
'',
'    // inicial',
'    atualizarData();',
'',
'    // troca de moeda',
'    selectMoeda.addEventListener("change", atualizarData);',
'',
'} catch (e) {',
'    console.warn("Erro ao montar seletor de moedas", e);',
'}',
