'select ',
'    a.id id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.vmle'')) valores,    ',
'    ''<span id="vmle">''||to_char(sum(c.vmle), ''FM999G999G990D00'')||''</span>'' valor',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P334_ID',
'group by ',
'    a.id,',
'    pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.vmle'')--, a.id_moeda_tenant, b.id_moeda',
'union all',
'select',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.frete'')) valores,',
'    ''<span id="frete">''||to_char(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(a.id_tenant, b.id_moeda_prevista, a.id_moeda_tenant) * b.valor_previsto)), ''FM999G999G990D00'')||''</span>'' valor',
'from imp_processoimportacao a',
'join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'join ng_despesa c on c.id = b.id_despesa',
'where a.id = :P334_ID',
'and c.ind_tipo_despesa = 9',
'group by ',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.frete''))',
'union all',
'select ',
'    to_number(:P334_ID), ',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.frete'')),',
'    ''0,00000''',
'from dual',
'where not exists (',
'    select 1',
'    from imp_processoimportacao a',
'    left join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'    left join ng_despesa c on c.id = b.id_despesa',
'    where a.id = :P334_ID',
'    and (c.ind_tipo_despesa = 9)',
')',
'union all',
'select',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.seguro'')),',
'    ''<span id="seguro">''||to_char(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(a.id_tenant, b.id_moeda_prevista, a.id_moeda_tenant) * b.valor_previsto)), ''FM999G999G990D00'')||''</span>'' valor',
'from imp_processoimportacao a',
'join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'join ng_despesa c on c.id = b.id_despesa',
'where a.id = :P334_ID',
'and c.ind_tipo_despesa = 10',
'group by ',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.seguro''))',
'union all',
'select ',
'    to_number(:P334_ID), ',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.seguro'')),',
'    ''0,00000''',
'from dual',
'where not exists (',
'    select 1',
'    from imp_processoimportacao a',
'    left join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'    left join ng_despesa c on c.id = b.id_despesa',
'    where a.id = :P334_ID',
'    and (c.ind_tipo_despesa = 10)',
')',
'union all',
