'-- from imp_processoimportacao a ',
'-- where a.id = :P334_ID',
'select',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.acrescimo'')),',
'    ''<span id="acrescimo">''||to_char(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(a.id_tenant, b.id_moeda_prevista, a.id_moeda_tenant) * b.valor_previsto)), ''FM999G999G990D00'')||''</span>'' valor',
