,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function formatarValor(valor) {',
'    if (isNaN(valor)) return '''';',
'',
'    var partes = valor.toFixed(2).split(''.'');',
'    var inteiro = partes[0];',
'    var decimal = partes[1];',
'',
'    inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, ''.'');',
'',
'    return inteiro + '','' + decimal;',
'}',
'var novaTaxa = parseFloat($("#taxa_cambio_moeda_pedido").val().replace('','', ''.''));',
unistr('// Obt\00E9m o JSON do item P334_JSON_VALORES'),
'var jsonValores = JSON.parse($("#P334_JSON_VALORES").val());',
'',
'// Itera sobre o array de valores no JSON',
'jsonValores.forEach(function(item) {',
unistr('    // Pega cada valor do item do JSON e multiplica pela taxa de c\00E2mbio'),
'    var novoValorVmle = item.vmle * novaTaxa;',
'    var novoValorFrete = item.frete * novaTaxa;',
'    var novoValorSeguro = item.seguro * novaTaxa;',
'    var novoValorAcrescimo = item.acrescimo * novaTaxa;',
'    var novoValorVmld = item.vmld * novaTaxa;',
'    var novoValorIi = item.valor_ii * novaTaxa;',
'    var novoValorIpi = item.valor_ipi * novaTaxa;',
'    var novoValorPis = item.valor_pis * novaTaxa;',
'    var novoValorCofins = item.valor_cofins * novaTaxa;',
'    var novoValorCofins = item.valor_cofins * novaTaxa;',
'    var novoValorCbs = item.valor_cbs * novaTaxa;',
'    var novoValorAntidumping = item.antidumping * novaTaxa;',
'    var novoValorIcms = item.valor_icms * novaTaxa;',
'    var novoValorIcmsSt = item.valor_icms_st * novaTaxa;',
'    var novoValorIbs = item.valor_ibs * novaTaxa;',
'    var novoValorMulta = item.multa * novaTaxa;',
'    var novoValorTotalTributos = item.total_tributos * novaTaxa;    ',
'',
unistr('    // Aplicaa a formata\00E7\00E3o        '),
'    var valorVmleFormatado = formatarValor(novoValorVmle);',
'    var valorFreteFormatado = formatarValor(novoValorFrete);',
'    var valorSeguroFormatado = formatarValor(novoValorSeguro);',
'    var valorAcrescimoFormatado = formatarValor(novoValorAcrescimo);',
'    var valorVmldFormatado = formatarValor(novoValorVmld);',
'    var valorIiFormatado = formatarValor(novoValorIi);',
'    var valorIpiFormatado = formatarValor(novoValorIpi);',
'    var valorPisFormatado = formatarValor(novoValorPis);',
'    var valorCofinsFormatado = formatarValor(novoValorCofins);',
'    var valorCbsFormatado = formatarValor(novoValorCbs);',
'    var valorAntidumpingFormatado = formatarValor(novoValorAntidumping);',
'    var valorIcmsFormatado = formatarValor(novoValorIcms);',
'    var valorIcmsStFormatado = formatarValor(novoValorIcmsSt);',
'    var valorIbsFormatado = formatarValor(novoValorIbs);',
'    var valorMultaFormatado = formatarValor(novoValorMulta);',
'    var valorTotalTributosFormatado = formatarValor(novoValorTotalTributos);    ',
'',
'    // Atualiza os valores formatados no item',
'    $("#vmle").text(valorVmleFormatado);',
'    $("#frete").text(valorFreteFormatado);',
'    $("#seguro").text(valorSeguroFormatado);',
'    $("#acrescimo").text(valorAcrescimoFormatado);',
'    $("#vmld").text(valorVmldFormatado);',
'    $("#valor_ii").text(valorIiFormatado);',
'    $("#valor_ipi").text(valorIpiFormatado);',
'    $("#valor_pis").text(valorPisFormatado);',
'    $("#valor_cofins").text(valorCofinsFormatado);',
'    $("#valor_cbs").text(valorCbsFormatado);',
'    $("#antidumping").text(valorAntidumpingFormatado);',
'    $("#valor_icms").text(valorIcmsFormatado);',
'    $("#valor_icms_st").text(valorIcmsStFormatado);',
'    $("#valor_ibs").text(valorIbsFormatado);',
'    $("#multa").text(valorMultaFormatado);',
'    $("#total_tributos").text(valorTotalTributosFormatado);',
'    ',
'    var labelInformada = $v(''P334_LABEL_INFORMADA'');',
'    const dataEl = document.getElementById("data_cotacao");',
'    // dataEl.innerHTML = `',
'    //             <span style="color: #d00000; font-weight: 600;">',
'    //                 <span ',
'    //                     class="fa fa-exclamation-triangle"',
'    //                     title="${labelInformada}"',
'    //                     style="margin-right: 4px;"',
'    //                 ></span>',
'    //                 ${labelInformada}',
'    //             </span>',
'    //         `;',
'    dataEl.innerHTML = `',
'                <span>',
'                    ${labelInformada}',
'                </span>',
'            `;',
'});'))
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(168071331599775426)
,p_event_id=>wwv_flow_imp.id(168070852054775424)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Fun\00E7\00E3o para formatar n\00FAmeros para o padr\00E3o ''FM999G999G990D00000'''),
'function formatarValor(valor) {',
unistr('    // Garante que o valor seja um n\00FAmero v\00E1lido'),
'    if (isNaN(valor)) return '''';',
'',
unistr('    // Formata o n\00FAmero com separadores de milhar (pontos) e v\00EDrgula como separador decimal'),
'    //var partes = valor.toFixed(2).split(''.'');',
'    var partes = valor.toFixed(2).split(''.'');',
'    var inteiro = partes[0];',
'    var decimal = partes[1];',
'',
'    // Adiciona separadores de milhar (pontos)',
'    inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, ''.'');',
'',
unistr('    // Une novamente inteiro e decimal com v\00EDrgula'),
'    return inteiro + '','' + decimal;',
'}',
unistr('// Obt\00E9m valor da taxa de c\00E2mbio'),
'var novaTaxa = parseFloat($("#taxa_cambio_moeda_pedido").val().replace('','', ''.''));',
unistr('// Obt\00E9m o JSON do item P334_JSON_VALORES'),
'var jsonValores = JSON.parse($("#P334_JSON_VALORES").val());',
unistr('// Obt\00E9m o JSON dentro de despesa_outras_despesas'),
'var jsonDespesas = jsonValores[0].despesa_outras_despesas;',
'// Cria um objeto para armazenar os valores convertidos',
'var novoValorDespesa = {};',
'',
'if (jsonDespesas) {',
'    // Itera sobre as despesas e preenche o objeto',
'    jsonDespesas.forEach(function(despesa) {',
'        var id = despesa.id;',
'        var valorOriginal = parseFloat(despesa.valor) || 0;',
'        var valorConvertido = valorOriginal * novaTaxa;',
'',
'        novoValorDespesa[id] = formatarValor(valorConvertido);    ',
'',
'        // Atualiza os valores formatados no item',
'        $(`#despesa_outras_despesas_${id}`).text(novoValorDespesa[id]);',
'    });',
'};',
'',
'// Itera sobre o JSON principal',
'jsonValores.forEach(function(item) {',
unistr('    // Pega cada valor do item do JSON e multiplica pela taxa de c\00E2mbio    '),
'    var novoValorTotalDespesas = item.total_despesas * novaTaxa;',
'    var novoValorTotalCustoImportacao = item.total_custo_importacao * novaTaxa;',
