wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(168066914723775409)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_json clob;',
'    l_json_valores clob;',
'    l_label_moeda              varchar2(4000) := pkg_ui.retorna_label_tela(''moeda'');',
'    l_label_valor_taxa_compra  varchar2(4000) := pkg_ui.retorna_label_tela(''taxa_cambio'');',
'    l_label_data_cotacao       varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.data_cotacao'');',
'    l_label_valores            varchar2(4000) := pkg_ui.retorna_label_tela(''valores'');',
'    l_label_valor              varchar2(4000) := pkg_ui.retorna_label_tela(''valor'');',
'    l_label_consultar_despesas varchar2(4000) := pkg_ui.retorna_label_tela(''consultar_despesas'');',
'    l_label_tributos           varchar2(4000) := pkg_ui.retorna_label_tela(''tributos'');',
'    l_label_consultar_tributos varchar2(4000) := pkg_ui.retorna_label_tela(''consultar_tributos'');',
'    l_label_despesas           varchar2(4000) := pkg_ui.retorna_label_tela(''despesas'');',
'    l_label_totais             varchar2(4000) := pkg_ui.retorna_label_tela(''totais'');',
'    l_label_imprimir           varchar2(4000) := pkg_ui.retorna_label_botao(''imprimir'');',
'    l_label_desatualizada      varchar2(4000) := pkg_ui.retorna_label_tela(''desatualizada'');',
'    l_label_informada          varchar2(4000) := pkg_ui.retorna_label_tela(''informada'');',
'    l_label_nao_encontrada     varchar2(4000) := pkg_ui.retorna_label_tela(''nao_encontrada'');',
'    l_id_tenant                number;',
'    l_id_moeda_pedido          number;',
'    l_label_recalcular_valores varchar2(4000) := pkg_ui.retorna_label_botao(''recalcular_valores'');',
'    l_verifica_nacionalizacao  number;',
'    l_label_calculando         varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_calculando_valores'');',
'    l_data_hora_ultimo_calculo varchar2(4000);',
'    l_msg_ultimo_calculo       varchar2(4000);',
'begin',
'    select count(1) into l_verifica_nacionalizacao from imp_processoimportacao where id = :P334_ID and data_nacionalizacao_real is null;',
'    select id_tenant, pkg_data.fmt(data_hora_ultimo_calculo, ''DATA'') into l_id_tenant, :P334_DATA_HORA_ULTIMO_CALCULO from imp_processoimportacao where id = :P334_ID;',
'    select id_moeda_tenant into :P334_ID_MOEDA_TENANT from imp_processoimportacao where id = :P334_ID;',
'    select id_moeda into :P334_ID_MOEDA_ITENS from imp_processoimportacao_item where id_processoimportacao = :P334_ID group by id_moeda fetch first 1 row only;',
'    select ',
'        json_arrayagg(',
'            json_object(',
'                ''display''     value a.codigo_moeda||'' - ''||a.simbolo_iso,',
'                ''return''      value a.id,',
'                --''taxa_cambio'' value bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, :P334_MOEDA_PADRAO_TENANT, a.id),',
'                ''taxa_cambio'' value to_char(bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, :P334_MOEDA_PADRAO_TENANT, a.id), ''FM999G999G990D000000''),',
'                ''data_cotacao'' value bo_ng_moeda_cotacao.retorna_cotacao_data_cotacao(l_id_tenant, :P334_MOEDA_PADRAO_TENANT, a.id)',
