'                    value (select a.valor_ibs from imp_processoimportacao a where a.id = :P334_ID),',
'                ''multa'' ',
'                    value nvl((',
'                        select ',
'                            (bo_ng_moeda_cotacao.retorna_cotacao_venda(a.id_tenant, b.id_moeda_prevista, :P334_MOEDA_PADRAO_TENANT) * b.valor_previsto)',
'                        from imp_processoimportacao a',
'                        join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'                        join ng_despesa c on c.id = b.id_despesa',
