,p_process_name=>'COTACAO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id_tenant number;',
'    l_id_moeda_origem number := apex_application.g_x01;',
'    l_id_moeda_destino number := apex_application.g_x02;',
'    l_cotacao number;',
'    l_data_cotacao date;',
'begin',
'    select id_tenant into l_id_tenant from imp_processoimportacao where id = :P334_ID;',
'    l_cotacao := bo_ng_moeda_cotacao.retorna_cotacao_venda/*compra*/(l_id_tenant, l_id_moeda_origem, l_id_moeda_destino);',
'    l_data_cotacao := bo_ng_moeda_cotacao.retorna_cotacao_data_cotacao(l_id_tenant, l_id_moeda_origem, l_id_moeda_destino);',
'',
'    apex_json.open_object;',
'    apex_json.write(''cotacao'', l_cotacao);',
'    apex_json.write(''data_cotacao'', l_data_cotacao);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>140897325346637217
);
