,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ',
'    a.id id,',
'    pkg_ui.retorna_label_tela(''dados_gerais'') titulo,    ',
'    pkg_componentes.html_card_colunas(''imp_invoice.id_exportador'', b.nome_fantasia/* || '' - '' || b.razao_social*/, 2) atributo1,',
'    pkg_componentes.html_card_colunas(''imp_invoice.id_importador'', c.nome_fantasia/* || '' - '' || c.razao_social*/, 2) atributo2,',
'    pkg_componentes.html_card_colunas(''imp_invoice.id_adquirente'', d.nome_fantasia/* || '' - '' || d.razao_social*/, 2) atributo3,    ',
'    pkg_componentes.html_card_colunas(''imp_invoice.id_incoterm'', e.codigo_incoterm, 2) atributo4,',
'    pkg_componentes.html_card_colunas(''imp_invoice.id_moeda'', f.codigo_moeda||'' - ''||f.simbolo_iso, 2) atributo5,',
'    case when data_invoice is not null then',
'        to_char(a.data_invoice, ''dd/mm/yyyy'')',
'    end distintivo,',
'    case when data_invoice is null then',
'        ''u-hidden''',
'    end class_distintivo',
'from imp_invoice a',
'join ng_pessoa_juridica b on b.id_pessoa = a.id_exportador',
'join ng_pessoa_juridica c on c.id_pessoa = a.id_importador',
'left join ng_pessoa_juridica d on d.id_pessoa = a.id_adquirente',
'join ng_incoterm e on e.id = a.id_incoterm',
'join ng_moeda f on f.id = a.id_moeda',
'where a.id = :P337_PARAMETRO'))
