 p_id=>338
,p_name=>'Valores da invoice'
,p_alias=>'VALORES-DA-INVOICE'
,p_page_mode=>'MODAL'
,p_step_title=>'Valores da invoice'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function validateInput(event) {',
'    const charCode = event.which || event.keyCode;',
unistr('    // Permite n\00FAmeros (0-9), ponto (.) e v\00EDrgula (,)'),
'    if (',
unistr('        !(charCode >= 48 && charCode <= 57) &&  // N\00FAmeros de 0 a 9'),
'        charCode !== 46 &&  // Ponto (.)',
unistr('        charCode !== 44     // V\00EDrgula (,)        '),
'    ) {',
unistr('        event.preventDefault();  // Bloqueia caracteres inv\00E1lidos'),
unistr('        return false;  // Impede a digita\00E7\00E3o'),
'    }',
'',
unistr('    return true;  // Permite a digita\00E7\00E3o de n\00FAmeros e caracteres v\00E1lidos'),
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'tituloTela($v("P338_TELA_TITULO")+'' (''+$v("P338_CODIGO_ARTEFATO")+'')'');',
'',
'const jsonData = apex.item("P338_JSON_MOEDAS").getValue();',
'try {    ',
'    const moedas = JSON.parse(jsonData);',
'    const tbody = document.getElementById("seletor_moeda");   ',
'',
'    moedas.forEach(item => {',
'    const row = document.createElement("option");',
'    row.setAttribute(''value'',item.return);',
'    row.innerText = item.display;',
'    ',
'    tbody.appendChild(row);      ',
'    });    ',
'    ',
'    const valorSelecionado = $v(''P338_ID_MOEDA_TENANT'');',
'    tbody.value = valorSelecionado;',
'',
'} catch (e) {',
'    //console.warn("Erro ao interpretar JSON de moedas");',
'}',
'',
'$("#taxa_cambio_moeda_pedido").trigger(''change'');'))
