'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P338_ID ',
'group by a.id, pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_calculado_ii'')',
'union all',
'select ',
'    a.id,',
