'    ''<span id="valor_pis">''||to_char(sum(c.valor_pis), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'left join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P338_ID',
'group by a.id, pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_pis'')',
'union all',
'select ',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_cofins'')),',
'    ''<span id="valor_cofins">''||to_char(sum(c.valor_cofins), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'left join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P338_ID',
'group by a.id, pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_cofins'')',
'union all',
'select ',
'    a.id,',
'    to_char(pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'', 8)),',
'    ''<span id="antidumping">''||to_char(sum(b.valor * bo_ng_moeda_cotacao.retorna_cotacao_data(b.id_moeda, :P338_ID_MOEDA_ITENS)), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'left join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'left join ng_despesa c on c.id = b.id_despesa',
'where a.id = :P338_ID',
'and c.ind_tipo_despesa = 8',
'group by a.id, pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'', 8)',
'union all',
'select ',
'    to_number(:P338_ID), ',
'    to_char(pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'', 8)),',
'    ''0,00''',
'from dual',
'where not exists (',
'    select 1',
'    from imp_processoimportacao a',
'    left join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'    left join ng_despesa c on c.id = b.id_despesa',
'    where a.id = :P338_ID',
'    and c.ind_tipo_despesa = 8',
')',
'union all',
'select ',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_icms'')),',
'    ''<span id="valor_icms">''||to_char(sum(c.valor_icms), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'left join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P338_ID',
'group by a.id, pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_icms'')',
'union all',
'select ',
'    a.id,',
'    to_char(pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_icms_st'')),',
'    ''<span id="valor_icms_st">''||to_char(sum(c.valor_icms_st), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'left join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P338_ID',
'group by a.id, pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.valor_icms_st'')',
'union all',
'select ',
'    a.id,',
'    to_char(pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'', 17)),',
'    ''<span id="multa">''||to_char(sum(b.valor * bo_ng_moeda_cotacao.retorna_cotacao_data(b.id_moeda, :P338_ID_MOEDA_ITENS)), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'left join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'left join ng_despesa c on c.id = b.id_despesa',
'where a.id = :P338_ID',
'and c.ind_tipo_despesa = 17',
'group by a.id, pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'', 17)',
'union all',
'select ',
'    a.id,',
'    to_char(pkg_ui.retorna_label_tela(''total_tributos'')),',
'    ''<span id="total_tributos">''||to_char(bo_imp_processoimportacao.calcula_total_tributos(a.id, ''s''), ''FM999G999G990D00'')||''</span>''',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'left join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'where a.id = :P338_ID',
'group by a.id, pkg_ui.retorna_label_tela(''total_tributos''), bo_imp_processoimportacao.calcula_total_tributos(a.id, ''s'')'))
