'    to_char(c.codigo_moeda||'' - ''||c.simbolo_iso) moeda,',
'    ''<input type="text" id="taxa_cambio_moeda_pedido" class="number_field apex-item-text" style="width: 100%;" value="''||to_char(bo_ng_moeda_cotacao.retorna_cotacao_data(b.id_moeda, a.id_moeda_tenant), ''FM999G999G990D000000'')||''" data-enter-submit="f'
||'alse" data-is-page-item-type="false" onKeyPress="return validateInput(event);" onKeyDown="if(event.key === ''''Enter'''') { event.preventDefault(); }">'' valor_taxa_compra',
'from imp_processoimportacao a',
'join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'join ng_moeda c on c.id = b.id_moeda',
'where a.id = :P338_ID',
'union all',
'select distinct',
'    c.id id,',
'    to_char(b.codigo_moeda||'' - ''||b.simbolo_iso) moeda,',
'    ''<input type="text" id="taxa_cambio_moeda_pedido" class="number_field apex-item-text" style="width: 100%;" value="''||to_char(bo_ng_moeda_cotacao.retorna_cotacao_data(a.id_moeda, c.id_moeda_tenant), ''FM999G999G990D000000'')||''" data-enter-submit="f'
||'alse" data-is-page-item-type="false" onKeyPress="return validateInput(event);" onKeyDown="if(event.key === ''''Enter'''') { event.preventDefault(); }">'' valor_taxa_compra',
'from imp_processoimportacao_despesa a',
'join ng_moeda b on b.id = a.id_moeda',
'join imp_processoimportacao c on c.id = a.id_processoimportacao',
'where c.id = :P338_ID',
'and a.id_moeda not in (',
