wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(178065613869429951)
,p_event_id=>wwv_flow_imp.id(178065094351429953)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Fun\00E7\00E3o para formatar n\00FAmeros para o padr\00E3o ''FM999G999G990D00'''),
'function formatarValor(valor) {',
unistr('    // Garante que o valor seja um n\00FAmero v\00E1lido'),
'    if (isNaN(valor)) return '''';',
'',
unistr('    // Formata o n\00FAmero com separadores de milhar (pontos) e v\00EDrgula como separador decimal'),
'    var partes = valor.toFixed(2).split(''.'');',
'    var inteiro = partes[0];',
'    var decimal = partes[1];',
'',
'    // Adiciona separadores de milhar (pontos)',
'    inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, ''.'');',
'',
unistr('    // Une novamente inteiro e decimal com v\00EDrgula'),
'    return inteiro + '','' + decimal;',
'}',
unistr('// Obt\00E9m valor da taxa de c\00E2mbio'),
'var novaTaxa = parseFloat($("#taxa_cambio_moeda_pedido").val().replace('','', ''.''));',
unistr('// Obt\00E9m o JSON do item P338_JSON_VALORES'),
'var jsonValores = JSON.parse($("#P338_JSON_VALORES").val());',
unistr('// Obt\00E9m o JSON dentro de despesa_outras_despesas'),
'var jsonDespesas = jsonValores[0].despesa_outras_despesas;',
'// Cria um objeto para armazenar os valores convertidos',
'var novoValorDespesa = {};',
'',
'if (jsonDespesas) {',
'    // Itera sobre as despesas e preenche o objeto',
'    jsonDespesas.forEach(function(despesa) {',
'        var id = despesa.id;',
'        var valorOriginal = parseFloat(despesa.valor) || 0;',
'        var valorConvertido = valorOriginal * novaTaxa;',
'',
'        novoValorDespesa[id] = formatarValor(valorConvertido);    ',
'',
'        // Atualiza os valores formatados no item',
'        $(`#despesa_outras_despesas_${id}`).text(novoValorDespesa[id]);',
'    });',
'};',
'',
'// Itera sobre o JSON principal',
'jsonValores.forEach(function(item) {',
unistr('    // Pega cada valor do item do JSON e multiplica pela taxa de c\00E2mbio    '),
'    var novoValorTotalDespesas = item.total_despesas * novaTaxa;',
'    var novoValorTotalCustoImportacao = item.total_custo_importacao * novaTaxa;',
'    var novoValorTotalImportacao = item.total_importacao * novaTaxa;',
'',
unistr('    // Aplicaa a formata\00E7\00E3o    '),
'    var valorTotalDespesasFormatado = formatarValor(novoValorTotalDespesas);',
'    var valorTotalCustoImportacaoFormatado = formatarValor(novoValorTotalCustoImportacao);',
'    var valorTotalImportacaoFormatado = formatarValor(novoValorTotalImportacao);',
'',
'    // Atualiza os valores formatados no item',
'    $("#total_despesas").text(valorTotalDespesasFormatado);',
'    $("#total_custo_importacao").text(valorTotalCustoImportacaoFormatado);',
'    $("#total_importacao").text(valorTotalImportacaoFormatado);',
'});'))
);
