'        <tr style="background-color: #f0f0f0;">',
'          <th style="text-align: left; border-bottom: 1px solid #ccc; padding: 5px;">&P340_LABEL_CODIGO_ITEM.</th>',
'          <th style="text-align: left; border-bottom: 1px solid #ccc; padding: 5px;">&P340_LABEL_DESCRICAO_ITEM.</th>',
'          <th style="text-align: left; border-bottom: 1px solid #ccc; padding: 5px;">&P340_LABEL_UNIDADE_MEDIDA.</th>',
'          <th style="text-align: left; border-bottom: 1px solid #ccc; padding: 5px;">&P340_LABEL_QUANTIDADE.</th>',
'          <th style="text-align: left; border-bottom: 1px solid #ccc; padding: 5px;">&P340_LABEL_VALOR_UNITARIO.</th>',
'          <th style="text-align: left; border-bottom: 1px solid #ccc; padding: 5px;">&P340_LABEL_VALOR_TOTAL.</th>',
'        </tr>',
'      </thead>',
'      <tbody id="itens-tabela">',
'        <!-- Preenchido dinamicamente pelo JavaScript -->',
'      </tbody>',
'      <tfoot>        ',
'        <tr>',
'          <td colspan="5" style="text-align: right; padding-top: 1rem;">&P340_LABEL_VALOR_DESCONTO.</td>',
'          <td style="text-align: right; padding-top: 1rem;">&P340_VALOR_DESCONTO.</td>',
'        </tr>',
'        <tr>',
'          <td colspan="5" style="text-align: right;">&P340_LABEL_VALOR_DESPESA_PROFORMA.</td>',
'          <td style="text-align: right;">&P340_VALOR_DESPESA_PROFORMA.</td>',
'        </tr>',
'        <tr>',
'          <td colspan="5" style="text-align: right; font-weight: bold;">&P340_LABEL_TOTAL.</td>',
'          <td style="text-align: right; font-weight: bold;">&P340_VALOR_TOTAL_CONDICAO_VENDA.</td>',
'        </tr>',
'      </tfoot>',
'    </table>',
'  </div>',
'',
'</div>',
'',
'<script>',
'  document.addEventListener("DOMContentLoaded", function () {',
'    const jsonData = apex.item("P340_JSON_ITENS").getValue();',
'',
'    try {',
'        //console.log("JSON bruto:", jsonData);',
'      const itens = JSON.parse(jsonData);',
'      const tbody = document.getElementById("itens-tabela");',
'      let totalGeral = 0;',
'',
'      itens.forEach(item => {',
'        const row = document.createElement("tr");',
'        row.innerHTML = `',
'          <td style="padding: 5px;">${item.code}</td>',
'          <td style="padding: 5px;">${item.description}</td>',
'          <td style="padding: 5px;">${item.measure}</td>',
'          <td style="padding: 5px;">${item.quantity}</td>',
'          <td style="text-align: end; padding: 5px;">${item.unit_price}</td>',
'          <td style="text-align: end; padding: 5px;">${item.total_price}</td>          ',
'        `;',
'        tbody.appendChild(row);',
'        totalGeral += parseFloat(item.total_price);',
'      });',
'',
'      document.getElementById("total-geral").textContent = totalGeral.toLocaleString("en-US", {',
'        minimumFractionDigits: 2,',
'        maximumFractionDigits: 2',
'      });',
'',
'    } catch (e) {',
'      //console.warn("Erro ao interpretar JSON de itens");',
'    }',
'  });',
'</script>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
