wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(161138065926588308)
,p_event_id=>wwv_flow_imp.id(161138179187588310)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var $btn = $(''#SALVAR_PDF'');',
'',
'if ($btn.prop("disabled")) return;',
'',
'$btn.prop("disabled", true).text("Gerando PDF...");',
'',
'var conteudo = $(''#documento'')[0];',
'var doc_number = $(''#doc-number'').text();',
'',
'html2pdf()',
'  .set({',
'    margin: 10,',
'    filename: ''purchase-order['' + doc_number + ''].pdf'',',
'    image: { type: ''jpeg'', quality: 0.98 },',
'    html2canvas: { scale: 2 },',
'    jsPDF: { unit: ''mm'', format: ''a4'', orientation: ''portrait'' }',
'  })',
'  .from(conteudo)',
'  .outputPdf(''blob'')',
'  .then(function(pdfBlob) {',
'      var reader = new FileReader();',
'      reader.readAsDataURL(pdfBlob);',
'      reader.onloadend = function () {',
'          var base64Data = reader.result.split('','')[1];  ',
'          $s(''P340_CLOB'',base64Data);',
'',
'          apex.server.process(',
'            "SALVA_ANEXO",',
'            {',
'                x01: ''purchase-order['' + doc_number + ''].pdf'',                ',
'                pageItems: "#P340_CLOB",',
'            },',
'            {',
'                dataType: "json",',
'                success: function(pData) {',
'                    if (pData.status === "OK") {',
'                        apex.message.showPageSuccess("PDF salvo com sucesso!");',
'                        setTimeout(function() {',
'                            apex.navigation.dialog.close(true);',
'                        }, 2000);',
'                    } else {',
'                        apex.message.alert("Erro ao salvar: " + (pData.msg || "Sem detalhe"));',
'                    }',
'                },',
'                error: function(err) {',
unistr('                    console.error("Erro t\00E9cnico:", err);'),
unistr('                    apex.message.alert("Erro t\00E9cnico ao salvar PDF.");                    '),
'                }',
'            }',
'          );',
'      };',
'  });',
''))
);
