wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(166765124008763098)
,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    -- Labels',
'    l_pedido_importacao            varchar2(4000) := retorna_texto(''tela.pedido_importacao.l'', :P340_IDIOMA_SELECIONADO);',
'    l_numero_documento             varchar2(4000) := retorna_texto(''tela.numero_documento.l'', :P340_IDIOMA_SELECIONADO);',
'    l_importador                   varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.id_importador.l'', :P340_IDIOMA_SELECIONADO);',
'    l_notify                       varchar2(4000) := retorna_texto(''tela.notify.l'', :P340_IDIOMA_SELECIONADO);',
'    l_incoterm                     varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.id_incoterm.l'', :P340_IDIOMA_SELECIONADO);',
'    l_via_transporte               varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.id_viatransporte.l'', :P340_IDIOMA_SELECIONADO);',
'    l_condicao_pagamento           varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.id_condicaopagamento.l'', :P340_IDIOMA_SELECIONADO);',
'    l_local_desembarque            varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.id_local_desembarque.l'', :P340_IDIOMA_SELECIONADO);',
'    l_observacao                   varchar2(4000) := retorna_texto(''coluna.ng_anexo.observacao.l'', :P340_IDIOMA_SELECIONADO);',
'    l_itens                        varchar2(4000) := retorna_texto(''tela.itens.l'', :P340_IDIOMA_SELECIONADO);',
'    l_codigo_item                  varchar2(4000) := retorna_texto(''coluna.ng_item.codigo_item.l'', :P340_IDIOMA_SELECIONADO);',
'    l_descricao_item               varchar2(4000) := retorna_texto(''coluna.ng_item.descricao_item.l'', :P340_IDIOMA_SELECIONADO);',
'    l_unidade_medida               varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao_item.id_unidademedida.l'', :P340_IDIOMA_SELECIONADO);',
'    l_quantidade                   varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao_item.quantidade.l'', :P340_IDIOMA_SELECIONADO);',
'    l_valor_unitario               varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao_item.valor_unitario.l'', :P340_IDIOMA_SELECIONADO);',
'    l_valor_total                  varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao_item.valor_total.l'', :P340_IDIOMA_SELECIONADO);',
'    l_total                        varchar2(4000) := retorna_texto(''tela.total.l'', :P340_IDIOMA_SELECIONADO);',
'    l_label_salvar                 varchar2(4000) := pkg_ui.retorna_label_botao(''salvar'');',
'    l_label_valor_desconto         varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.valor_desconto.l'', :P340_IDIOMA_SELECIONADO);',
'    l_label_valor_despesa_proforma varchar2(4000) := retorna_texto(''coluna.imp_pedidoimportacao.valor_despesa_proforma.l'', :P340_IDIOMA_SELECIONADO);',
'    -- Dados',
'    l_numero_pedido_importacao     varchar2(4000);',
'    l_importador_razao_social      varchar2(4000);',
'    l_importador_inscricao_federal varchar2(4000);',
'    l_importador_etiqueta_endereco varchar2(4000);',
'    l_notify_razao_social          varchar2(4000);',
'    l_notify_inscricao_federal     varchar2(4000);',
'    l_notify_etiqueta_endereco     varchar2(4000);',
'    l_codigo_incoterm              varchar2(4000);',
'    l_descricao_viatransporte      varchar2(4000);',
'    l_descricao_condicaopagamento  varchar2(4000);',
'    l_nome_local                   varchar2(4000);',
'    l_valor_total_condicao_venda   varchar2(4000);',
'    l_valor_desconto               varchar2(4000);',
'    l_valor_despesa_proforma       varchar2(4000);',
'    -- JSON',
'    l_json clob;',
'begin',
'    -- Atribui caba retorno aos itens correspondentes',
'    :P340_LABEL_PEDIDO_IMPORTACAO      := l_pedido_importacao;',
'    :P340_LABEL_NUMERO_DOCUMENTO       := l_numero_documento;',
'    :P340_LABEL_IMPORTADOR             := l_importador;',
'    :P340_LABEL_NOTIFY                 := l_notify;',
'    :P340_LABEL_INCOTERM               := l_incoterm;',
'    :P340_LABEL_VIA_TRANSPORTE         := l_via_transporte;',
'    :P340_LABEL_CONDICAO_PAGAMENTO     := l_condicao_pagamento;',
'    :P340_LABEL_LOCAL_DESEMBARQUE      := l_local_desembarque;',
'    :P340_LABEL_OBSERVACAO             := l_observacao;',
'    :P340_LABEL_ITENS                  := l_itens;',
'    :P340_LABEL_CODIGO_ITEM            := l_codigo_item;',
'    :P340_LABEL_DESCRICAO_ITEM         := l_descricao_item;',
'    :P340_LABEL_UNIDADE_MEDIDA         := l_unidade_medida;',
'    :P340_LABEL_QUANTIDADE             := l_quantidade;',
'    :P340_LABEL_VALOR_UNITARIO         := l_valor_unitario;',
'    :P340_LABEL_VALOR_TOTAL            := l_valor_total;',
'    :P340_LABEL_TOTAL                  := l_total;',
'    :P340_LABEL_SALVAR                 := l_label_salvar;',
'    :P340_LABEL_VALOR_DESCONTO         := l_label_valor_desconto;',
'    :P340_LABEL_VALOR_DESPESA_PROFORMA := l_label_valor_despesa_proforma;',
'',
'    -- Conulta para retorna os dados do documento',
'    select ',
'        a.numero_pedido_importacao,',
'        b.razao_social,',
'        b.inscricao_federal,',
'        c.etiqueta_endereco,',
'        d.razao_social,',
'        d.inscricao_federal,',
'        e.etiqueta_endereco,',
'        f.codigo_incoterm,',
'        to_char(chamar_webservice_traducao(''wksp_teste'',''ng_viatransporte'',''descricao_viatransporte'',:P340_IDIOMA_SELECIONADO,a.id_viatransporte)),',
'        to_char(chamar_webservice_traducao(''wksp_teste'',''ng_condicaopagamento'',''descricao_condicaopagamento'',:P340_IDIOMA_SELECIONADO,a.id_condicaopagamento)),',
'        to_char(chamar_webservice_traducao(''wksp_teste'',''ng_localembarquedesembarque'',''nome_local'',:P340_IDIOMA_SELECIONADO,a.id_local_desembarque)),',
'        to_char(valor_total_condicao_venda, ''FM999G999G990D00''),',
'        to_char(nvl(valor_desconto, 0), ''FM999G999G990D00''),',
'        to_char(nvl(valor_despesa_proforma, 0), ''FM999G999G990D00'')',
'    into ',
'        l_numero_pedido_importacao, ',
'        l_importador_razao_social, ',
'        l_importador_inscricao_federal,',
'        l_importador_etiqueta_endereco,',
'        l_notify_razao_social,',
'        l_notify_inscricao_federal,',
'        l_notify_etiqueta_endereco,',
'        l_codigo_incoterm,',
'        l_descricao_viatransporte,',
'        l_descricao_condicaopagamento,',
'        l_nome_local,',
'        l_valor_total_condicao_venda,',
'        l_valor_desconto,',
'        l_valor_despesa_proforma',
'    from imp_pedidoimportacao a ',
'    join ng_pessoa_juridica b on b.id_pessoa = a.id_importador',
'    left join ng_pessoa_endereco c on c.id_pessoa = a.id_importador',
'    left join ng_pessoa_juridica d on d.id_pessoa = a.id_adquirente',
'    left join ng_pessoa_endereco e on e.id_pessoa = a.id_adquirente',
'    join ng_incoterm f on f.id = a.id_incoterm    ',
'    where a.id = :P340_ID',
'    and lower(c.ind_endereco_principal) = ''s''',
'    and (lower(e.ind_endereco_principal) = ''s'' or e.ind_endereco_principal is null);',
'    ',
'    -- Atribui cada retorno da consulta acima aos itens correspondentes',
'    :P340_NUMERO_PEDIDO_IMPORTACAO     := l_numero_pedido_importacao;',
'    :P340_IMPORTADOR_RAZAO_SOCIAL      := l_importador_razao_social;',
'    :P340_IMPORTADOR_INSCRICAO_FEDERAL := l_importador_inscricao_federal;',
'    :P340_IMPORTADOR_ETIQUETA_ENDERECO := l_importador_etiqueta_endereco;',
'    :P340_NOTIFY_RAZAO_SOCIAL          := l_notify_razao_social;',
'    :P340_NOTIFY_INSCRICAO_FEDERAL     := l_notify_inscricao_federal;',
'    :P340_NOTIFY_ETIQUETA_ENDERECO     := l_notify_etiqueta_endereco;',
'    :P340_CODIGO_INCOTERM              := l_codigo_incoterm;',
'    :P340_DESCRICAO_VIATRANSPORTE      := l_descricao_viatransporte;',
'    :P340_DESCRICAO_CONDICAOPAGAMENTO  := l_descricao_condicaopagamento;',
'    :P340_NOME_LOCAL                   := l_nome_local;',
'    :P340_VALOR_TOTAL_CONDICAO_VENDA   := l_valor_total_condicao_venda;',
'    :P340_VALOR_DESCONTO               := l_valor_desconto;',
'    :P340_VALOR_DESPESA_PROFORMA       := l_valor_despesa_proforma;',
'',
'    -- Monta o JSON para buscar os itens do pedido',
'    select ',
'        json_arrayagg(',
'            json_object(',
'                ''code''        value b.codigo_item,',
'                ''description'' value to_char(chamar_webservice_traducao(''wksp_teste'',''ng_item'',''descricao_item'',:P340_IDIOMA_SELECIONADO,a.id_item)),',
'                ''measure''     value c.codigo_unidademedida,',
'                ''quantity''    value case c.ind_tipo_dado when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'') when ''I'' then to_char(a.quantidade) end,',
'                ''unit_price''  value to_char(a.valor_unitario - a.valor_desconto_unitario, ''FM999G999G990D00''),',
'                ''total_price'' value to_char(a.valor_total, ''FM999G999G990D00'')',
'            ) order by a.num_sequencia_item',
'        ) ',
'    into l_json',
'    from imp_pedidoimportacao_item a',
'    join ng_item b on b.id = a.id_item',
'    left join ng_unidademedida c on c.id = a.id_unidademedida',
'    where a.id_pedidoimportacao = :P340_ID;    ',
'    -- Atribui o resultado do JSON ao item correspondente',
'    :P340_JSON_ITENS := l_json;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>38952151558149440
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(161137964209588307)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SALVA_ANEXO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id_pedidoimportacao number := :P340_ID;',
'    l_id_tenant number;',
'    l_id_documento number;',
'    l_id_entidade number;',
'    l_ind_situacao varchar2(1);',
'    l_anexo blob;',
'    l_anexo_name varchar2(4000) := apex_application.g_x01;',
'    l_id_anexo number;    ',
'    l_base64 clob := :P340_CLOB;',
'    l_sucesso clob;',
'    l_messages pkg_mensagem.message_record_table;',
'    l_raw    raw(32767);',
'    l_pos    integer := 1;',
'    l_len    integer := dbms_lob.getlength(l_base64);',
'    l_amount integer := 32767;',
'begin',
'    l_messages := pkg_mensagem.message_record_table();    ',
'',
'    select id_tenant into l_id_tenant from imp_pedidoimportacao where id = l_id_pedidoimportacao;',
'    ',
'    select ',
'        id, ',
'        case ind_aprovar ',
'            when ''S'' then ''P''',
'            when ''N'' then ''A''',
'        end',
'    into ',
'        l_id_documento, ',
'        l_ind_situacao ',
'    from ng_documento ',
unistr('    where lower(nome_documento) = ''pedido de importa\00E7\00E3o'';'),
'',
'    select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
'    dbms_lob.createtemporary(l_anexo, true);',
'    ',
'    while l_pos <= l_len loop',
'        l_raw := utl_encode.base64_decode(',
'                    utl_raw.cast_to_raw(',
'                        dbms_lob.substr(l_base64, least(2000, l_len - l_pos + 1), l_pos)',
'                    )',
'                 );',
'        dbms_lob.writeappend(l_anexo, utl_raw.length(l_raw), l_raw);',
'        l_pos := l_pos + 2000;',
'    end loop;',
'',
'    if l_anexo is null or dbms_lob.getlength(l_anexo) = 0 then',
unistr('        raise_application_error(-20001, ''PDF enviado est\00E1 vazio.'');'),
'    end if;',
'',
'    bo_ng_anexo.inclui_registro(',
'        p_id_usuario_revisou => null,',
'        p_data_hora_revisao => null,',
'        p_observacao => :P340_OBSERVACAO,',
'        p_ind_situacao => l_ind_situacao,',
'        p_id_tenant => l_id_tenant,',
'        p_id_documento => l_id_documento,',
'        p_id_entidade => l_id_entidade,',
'        p_id_referencia => l_id_pedidoimportacao,',
'        p_numero_documento => :P340_NUMERO_PEDIDO_IMPORTACAO,',
'        p_versao_documento => bo_ng_anexo.gera_versao(l_id_entidade, l_id_pedidoimportacao),',
'        p_data_documento => :P340_DATA_SELECIONADA,',
'        p_anexo => l_anexo,',
'        p_anexo_name => l_anexo_name,',
'        p_anexo_mimetype => ''application/pdf'',',
'        p_anexo_charset => null,',
'        p_id => l_id_anexo,',
'        p_sucesso => l_sucesso,',
'        p_messages => l_messages',
'    );',
'',
'    DBMS_LOB.FREETEMPORARY(l_anexo);',
'',
'    apex_json.open_object;',
'    apex_json.write(''status'', ''OK'');',
'    apex_json.write(''id_anexo'', l_id_anexo);',
'    apex_json.write(''nome'', l_anexo_name);',
'    apex_json.close_object;',
'',
'exception',
'    when others then',
'        if dbms_lob.istemporary(l_anexo) = 1 then',
'            DBMS_LOB.FREETEMPORARY(l_anexo);',
'        end if;',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''ERRO'');',
'        apex_json.write(''msg'', sqlerrm);',
'        apex_json.close_object;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_success_message=>'&P340_SUCESSO.'
,p_internal_uid=>44579311357324231
);
end;
