'function toNumber(valorStr) {',
'',
'    var sepDecimal  = $(''#P341_SEPARADOR_DECIMAL'').val();',
'    var sepMilhar   = $(''#P341_SEPARADOR_NUMERICO'').val();',
'',
'    if (!valorStr) return 0;',
'',
'    // Remove separadores de milhar',
'    var clean = valorStr.split(sepMilhar).join("");',
'',
'    // Troca separador decimal por ponto',
'    clean = clean.replace(sepDecimal, ".");',
'',
'    var n = parseFloat(clean);',
'',
'    return isNaN(n) ? 0 : n;',
'}',
'',
'function toDate(dateStr) {',
'    if (!dateStr) return "";',
'    const parts = dateStr.split(''/'');',
'    if (parts.length !== 3) return dateStr; // caso venha algo inesperado',
'    return `${parts[1]}/${parts[0]}/${parts[2]}`; ',
'}',
'',
'function calcularSaldo(idLinha) {',
'',
'    let $base  = $("#valor_parcela_" + idLinha);',
'    let $comp  = $("#valor_compensar_" + idLinha);',
'    let $gerar = $("#valor_gerar_titulo_" + idLinha);',
'',
'    if ($base.length === 0 || $comp.length === 0 || $gerar.length === 0)',
'        return;',
'',
'    let baseNum = toNumber($base.text() || $base.val() || "0");',
'    let compNum = toNumber($comp.val() || "0");',
'',
'    if (compNum > baseNum) {',
'        compNum = baseNum;',
'        $comp.val(formatarValor(compNum));',
'    }',
'',
'    let saldo = baseNum - compNum;',
'    $gerar.text(formatarValor(saldo));',
'}',
