'function distribuirSaldo() {',
'',
unistr('    // 1 - L\00EA saldo total do item de p\00E1gina'),
'    let saldoTotalStr = $("#P341_SALDO_COMPENSAR").text() || $("#P341_SALDO_COMPENSAR").val();',
'    let saldoRestante = toNumber(saldoTotalStr);',
'',
'    if (saldoRestante <= 0) return;',
'',
unistr('    // 2 - Percorre as linhas do relat\00F3rio'),
'    $(".valor-compensar").each(function () {',
'',
'        let $input = $(this);',
'        let idLinha = $input.data("id");',
'',
unistr('        // Valor j\00E1 informado anteriormente pelo usu\00E1rio'),
'        let valorCompensado = toNumber($input.data("valor-compensar"));',
'',
'        // NOVA REGRA:',
unistr('        // Se j\00E1 existe valor compensado > 0, n\00E3o redistribui'),
'        if (valorCompensado > 0) {',
unistr('            return; // continua para a pr\00F3xima linha'),
'        }',
'',
'        // Valor base da linha',
'        let baseStr = $("#valor_parcela_" + idLinha).text() || $("#valor_parcela_" + idLinha).val();',
'        let valorBase = toNumber(baseStr);',
'',
'        if (saldoRestante <= 0 || valorBase <= 0) {',
'            return;',
'        }',
'',
unistr('        // Determina quanto ser\00E1 compensado'),
'        let valorCompensar = saldoRestante >= valorBase',
'            ? valorBase',
'            : saldoRestante;',
'',
'        // Atualiza os campos',
'        $("#valor_compensar_" + idLinha).val(formatarValor(valorCompensar));',
'',
'        let valorGerar = valorBase - valorCompensar;',
'        $("#valor_gerar_titulo_" + idLinha).text(formatarValor(valorGerar));',
'',
'        // Atualiza saldo restante',
'        saldoRestante -= valorCompensar;',
'',
'    });',
'}',
'',
'function getMaxPermitidoParaLinha(idLinha) {',
'',
'    // Valor da parcela da linha',
'    let baseStr = $("#valor_parcela_" + idLinha).text() || $("#valor_parcela_" + idLinha).val();',
'    let valorBase = toNumber(baseStr);',
'',
unistr('    // Saldo livre do item de p\00E1gina'),
'    let saldoItemStr = $("#P341_SALDO_COMPENSAR").text() || $("#P341_SALDO_COMPENSAR").val();',
'    let saldoItem = toNumber(saldoItemStr);',
'',
'    let totalDataCompensar = 0;',
'    let totalDigitadoOutras = 0;',
'',
'    $(".valor-compensar").each(function () {',
'',
'        let $input = $(this);',
'        let otherId = $input.data("id");',
'',
unistr('        // Soma do saldo originalmente dispon\00EDvel'),
'        totalDataCompensar += toNumber($input.data("valor-compensar"));',
'',
unistr('        // Soma do que j\00E1 foi usado nas outras linhas'),
'        if (otherId != idLinha) {',
'            totalDigitadoOutras += toNumber($input.val());',
'        }',
'    });',
'',
'    // Saldo TOTAL do sistema',
'    let saldoTotal = saldoItem + totalDataCompensar;',
'',
unistr('    // Saldo dispon\00EDvel para esta linha'),
'    let saldoDisponivel = saldoTotal - totalDigitadoOutras;',
'',
'    if (saldoDisponivel < 0) saldoDisponivel = 0;',
'',
unistr('    // M\00E1ximo permitido respeitando a parcela'),
'    return Math.min(valorBase, saldoDisponivel);',
'}',
