'function aplicarConfiguracoesDeEntrada() {',
'',
'    $("[id^=''valor_compensar_'']").each(function () {',
'',
'        const inputId = this.id;',
'        const $input = $(''#'' + inputId);',
'',
'        // BLOQUEIO DE PASTE E DRAG&DROP ANTES DO AutoNumeric',
'        $input.off("paste drop dragover") // remove handlers antigos, se houver',
'              .on("paste drop dragover", function(e) {',
'                  e.preventDefault();',
'                  e.stopImmediatePropagation();',
'                  return false;',
'              });',
'',
unistr('        // Agora aplica a m\00E1scara'),
'        const integerDigits = parseInt($input.data(''integer-digits'')) || 10;',
'        const prefix = '''';',
'        const groupSeparatorType = $(''#P341_SEPARADOR_NUMERICO'').val();',
'        const decimalSeparatorType = $(''#P341_SEPARADOR_DECIMAL'').val();',
'        const allowNegative = false;',
'',
'        applyAutoNumericMask(',
'            ''#'' + inputId,',
'            2,',
'            prefix,',
'            groupSeparatorType,',
'            decimalSeparatorType,',
'            allowNegative,',
'            integerDigits',
'        );',
'    });',
'}',
