wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(195539721748473441)
,p_plug_name=>'Lista numerarios'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529621672076986996)
,p_plug_display_sequence=>50
,p_plug_grid_row_css_classes=>'#ROW_CLASS#'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select *',
'from (',
'    select distinct',
'        pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'',''ind_tipo_movimento'',a.ind_tipo_movimento) campo1,',
unistr('        -- Botei Null aqui porque n\00E3o sei de onde vai vir o documento_numerario,Joniclei'),
'        null campo2,',
'        -- a.documento_numerario campo2,',
'        a.data_documento campo3,',
unistr('        -- Botei Null aqui porque n\00E3o sei de onde vai vir o data_previsao_pagamento,Joniclei'),
'        null campo4,',
'        -- a.data_previsao_pagamento campo4,',
'        pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'',''ind_status'',a.ind_status) campo5,',
'        b.codigo_moeda||'' - ''||b.simbolo_iso campo6,',
unistr('        -- Botei Null aqui porque n\00E3o sei de onde vai vir o valor,Joniclei'),
'        null campo7,',
'        -- to_char(a.valor_moeda_nacional,''FM999G999G990D00'',''NLS_NUMERIC_CHARACTERS='''',.'''''') campo7,',
'        pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''342'', p_param1 => a.id_titulo_pagamento) opcao,',
'        1 ordem',
'    from imp_processoimportacao_numerario a',
'    --Alteirei de id_moeda_nacional para ID_MOEDA_NUMERARIO,JONICLEI',
'    join ng_moeda b on b.id = a.ID_MOEDA_NUMERARIO ',
'    -- join ng_moeda b on b.id = a.id_moeda_nacional ',
'    where a.id_processoimportacao = :P342_PARAMETRO',
'',
'    union all',
'',
'    select',
'        null,',
'        null,',
'        null,',
'        null,',
'        null,',
'        null,',
'        null,',
'        ''style="display:none"'',',
'        1.5',
'    from dual',
'    where exists (',
'        select 1 from imp_processoimportacao_numerario x where x.id_processoimportacao = :P342_PARAMETRO',
'    )',
'',
'    union all',
'',
'    select',
'        ''<strong>'' || :P342_LABEL_SALDO || ''</strong>'',',
'        null,',
'        null,',
'        null,',
'        null,',
'        case',
'            when saldo_pendente >= 0',
'            then ''<strong>'' || :P342_LABEL_VALOR_A_RECEBER || ''</strong>''',
'            else ''<strong>'' || :P342_LABEL_VALOR_A_PAGAR || ''</strong>''',
'        end,',
'        case',
'            when saldo_pendente >= 0',
'            then ''<span style="color:#2b9ecc;font-weight:bold">''',
'            else ''<span style="color:red;font-weight:bold">''',
'        end ||',
'        to_char(abs(saldo_pendente), ''FM999G999G990D00'', ''NLS_NUMERIC_CHARACTERS='''',.'''''') || ''</span>'',',
'        pkg_componentes.html_botao_opcao(p_id => :P342_PARAMETRO, p_pagina => ''342'', p_param1 => ''0''),',
'        2',
'    from (',
'        select',
'',
'            a.id_processoimportacao,',
'            sum(',
'                case',
'                    --Alteirei de valor_moeda_nacional para ID_MOEDA_NUMERARIO,JONICLEI',
'                    when a.ind_tipo_movimento = 1 then a.ID_MOEDA_NUMERARIO',
'                    when a.ind_tipo_movimento = 2 then -a.ID_MOEDA_NUMERARIO',
'                    when a.ind_tipo_movimento = 4 then -a.ID_MOEDA_NUMERARIO',
'                    when a.ind_tipo_movimento = 3 then a.ID_MOEDA_NUMERARIO',
'                    ',
'                    -- when a.ind_tipo_movimento = 1 then a.valor_moeda_nacional',
'                    -- when a.ind_tipo_movimento = 2 then -a.valor_moeda_nacional',
'                    -- when a.ind_tipo_movimento = 4 then -a.valor_moeda_nacional',
'                    -- when a.ind_tipo_movimento = 3 then a.valor_moeda_nacional',
'                    else 0',
'                end',
'            ) as saldo_pendente',
'        from imp_processoimportacao_numerario a',
'        where a.id_processoimportacao = :P342_PARAMETRO',
'        group by a.id_processoimportacao',
'        having count(*) > 0',
'    )',
')',
'order by ordem, campo3',
'',
'',
'',
'',
'',
'',
'-------------------- QUERY ANTES DE EXISTIR ind_tipo_movimento = 3 E ind_tipo_movimento = 4:',
'-- select distinct',
'--     pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'',''ind_tipo_movimento'',a.ind_tipo_movimento) campo1,',
