'--     a.data_documento campo3,',
'--     a.data_previsao_pagamento campo4,',
'--     pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'',''ind_status'',a.ind_status) campo5,',
'--     b.codigo_moeda||'' - ''||b.simbolo_iso campo6,',
'--     to_char(a.valor_moeda_nacional,''FM999G999G990D00'',''NLS_NUMERIC_CHARACTERS='''',.'''''') campo7,',
'--     pkg_componentes.html_botao_opcao(a.id,''342'') opcao,',
'--     1 ordem',
'-- from imp_processoimportacao_numerario a',
'-- join ng_moeda b on b.id = a.id_moeda_nacional',
'-- where a.id_processoimportacao = :P342_PARAMETRO',
'',
'-- union all',
'',
'-- select',
'--     null campo1,',
'--     null campo2,',
'--     null campo3,',
'--     null campo4,',
'--     null campo5,',
'--     null campo6,',
'--     null campo7,',
'--     ''style="display:none"'' opcao,',
'--     1.5 ordem',
'-- from dual',
'-- where exists (select 1 from imp_processoimportacao_numerario x where x.id_processoimportacao = :P342_PARAMETRO)',
'',
'-- union all',
'',
'-- select',
'--     ''<strong>'' || :P342_LABEL_SALDO || ''</strong>'' campo1,',
'--     null campo2,',
'--     null campo3,',
'--     null campo4,',
'--     null campo5,',
'--     case',
'--         when sum(',
'--             case',
