 p_id=>wwv_flow_imp.id(632817326871975657)
,p_plug_name=>'Header'
,p_region_template_options=>'#DEFAULT#:t-ButtonRegion--noPadding:t-ButtonRegion--noUI'
,p_plug_template=>wwv_flow_imp.id(529590912278986980)
,p_plug_display_sequence=>20
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_html clob;',
'begin    ',
'    l_html := pkg_util.ObterValoresDasColunas(',
'        p_consulta_sql => ''',
'            select distinct',
'                case ',
'                    when exists (select 1 from imp_processoimportacao_numerario n where n.id_processoimportacao = c.id) then',
'                        nvl(b.nome_fantasia, ''''&nbsp;'''')',
'                    else',
'                        ''''&nbsp;''''',
'                end as id_fornecedor,',
'                c.num_processoimportacao',
'            from imp_processoimportacao c',
'            left join imp_processoimportacao_numerario a on a.id_processoimportacao = c.id',
'            left join ng_pessoa_juridica b on b.id_pessoa = a.id_fornecedor',
'            where c.id = '' || :P342_PARAMETRO,',
'        p_tabela => textarray(''imp_processoimportacao_numerario'',''imp_processoimportacao''),',
'        p_formato => ''pequeno'',',
'        p_tipo_label => ''coluna'',',
'        p_classe => ''st-back-transparente''',
'    );',
'    return l_html;',
'end;',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P342_ID,P342_PARAMETRO,P342_PARAMETRO2,P342_PARAMETRO3'
,p_ai_enabled=>false
);
