'    SELECT ''CAMPO3'', :P342_LABEL_COLUNA3 FROM dual UNION ALL',
'    SELECT ''CAMPO4'', :P342_LABEL_COLUNA4 FROM dual UNION ALL',
'    SELECT ''CAMPO5'', :P342_LABEL_COLUNA5 FROM dual UNION ALL',
'    SELECT ''CAMPO6'', :P342_LABEL_COLUNA6 FROM dual UNION ALL',
'    SELECT ''CAMPO7'', :P342_LABEL_COLUNA7 FROM dual UNION ALL',
'    SELECT ''CAMPO8'', :P342_LABEL_COLUNA8 FROM dual UNION ALL',
'    SELECT ''CAMPO9'', :P342_LABEL_COLUNA9 FROM dual UNION ALL',
'    SELECT ''CAMPO10'', :P342_LABEL_COLUNA10 FROM dual',
')',
'SELECT c.label d, c.id_coluna r',
'FROM colunas c',
'LEFT JOIN MPD_USUARIO_GRID_OCULTA_COLUNA u',
'    ON u.id_usuario = :ID_USUARIO_LOGADO',
'    AND u.codigo_artefato = :P342_CODIGO_ARTEFATO',
'    AND u.id_coluna LIKE ''%'' || c.id_coluna || ''%''',
'WHERE --u.id_coluna IS NULL and ',
'c.label is not null'))
