wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(483157579136608411)
,p_plug_name=>unistr('Cota\00E7\00F5es de moeda')
,p_region_name=>'ENTREGA_ITENS'
,p_region_template_options=>'#DEFAULT#:t-Form--stretchInputs'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(529621672076986996)
,p_plug_display_sequence=>70
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'    c.codigo_moeda || '' - '' || c.simbolo_iso AS id_moeda,',
'    ''<div class="t-form-itemwrapper" style="height:100%;">',
'        <input',
'            id="taxa_cambio_'' || a.id || ''"',
'            type="text"',
'            class="text_field apex-item-text js-valor-cotacao"',
'            style="height:100%;"',
'            value="'' || TO_CHAR(a.taxa_cambio, ''FM999G999G990D00'') || ''"',
'            data-decimal-places="2"',
'            data-integer-digits="10"',
'            data-id-numerario="'' || a.id_numerario || ''"',
'            data-id-moeda="'' || a.id_moeda || ''"',
'            data-id-cotacao="'' || a.id || ''"',
'        />',
'     </div>'' AS "INPUT"',
'FROM (',
'    SELECT a.*,',
'           ROW_NUMBER() OVER (PARTITION BY a.id_moeda ORDER BY a.id) AS rn',
'    FROM imp_processoimportacao_numerario_cotacao a',
'    JOIN imp_processoimportacao_numerario b ',
'        ON b.id = a.id_numerario',
'    WHERE b.ind_status = 1',
'    AND b.id = :P344_PARAMETRO',
') a',
'JOIN ng_moeda c ON c.id = a.id_moeda',
'WHERE a.rn = 1',
'ORDER BY id_moeda',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
