'<div id="dev-loading" class="loading-text"></div>',
'',
'<style>',
'    .loading-text {',
'        font-size: 18px;',
'        font-weight: bold;',
'        font-family: Arial, sans-serif;',
'        padding: 10px;',
'        transition: opacity 0.3s ease-in-out;',
'    }',
'</style>',
'',
'<script>',
'(function() {',
'    const element = document.getElementById("dev-loading");',
'    let maxDots = 5;',
'    let dots = 0;',
'',
'    function animate() {',
'        dots++;',
'',
'        if (dots <= maxDots) {',
'            element.style.opacity = 1;',
'            element.textContent = "Em desenvolvimento" + ".".repeat(dots);',
'        } else {',
'            // Ao final, some com o texto',
'            element.style.opacity = 0;',
'        }',
'',
unistr('        // Reiniciar anima\00E7\00E3o'),
'        if (dots > maxDots + 1) {',
'            dots = 0;',
'        }',
'    }',
'',
'    setInterval(animate, 500);',
'})();',
'</script>',
''))
