,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct',
'    d.numero_pedido_importacao,',
'    case ',
'        when c.id_entrega is null then',
'            pkg_ui.retorna_label_tela(''parcela_pedido'')',
'        else',
'            to_char(e.num_entrega)',
'    end num_entrega,',
'    c.numero_parcela,',
'    to_char(a.valor_titulo, ''FM999G999G990D00'') valor_titulo',
'from fin_titulopagamento a',
'join srv_entidade b on b.id = a.id_entidade',
'join imp_pedidoimportacao_pagamento c on c.id = a.id_referencia',
'join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'join imp_entrega e on e.id_pedidoimportacao = d.id',
'join imp_invoice f on f.id = e.id_invoice',
'where lower(b.nome_entidade) = ''imp_pedidoimportacao''',
'and f.id = :P346_PARAMETRO',
'order by numero_pedido_importacao, numero_parcela, num_entrega'))
