wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(213662367183255491)
,p_computation_sequence=>10
,p_computation_item=>'P346_ID'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id number;',
'    l_pagina varchar2(256) := nvl(:P346_CODIGO_ARTEFATO,''TD452'');',
'begin',
'    EXECUTE IMMEDIATE',
'        ''BEGIN :l_id := UI_MPD_''||l_pagina||''.busca_id_etapa(:param1); END;''',
'        USING OUT l_id, IN :P346_PARAMETRO;',
'',
'    return l_id;       ',
'end;',
''))
,p_compute_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'from all_procedures',
'where upper(object_name) = upper(''ui_mpd_''||:p346_codigo_artefato)',
'and upper(procedure_name) = upper(''BUSCA_ID_ETAPA'')',
'and upper(object_type) = upper(''package'');'))
,p_compute_when_type=>'EXISTS'
);
