,p_computation_sequence=>60
,p_computation_item=>'P346_QUANTIDADE_PARCELAS'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>'select max(numero_parcela) from ng_condicaopagamento_parcela a join imp_invoice b on b.id_condicaopagamento = a.id_condicaopagamento where b.id = :P346_PARAMETRO'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(213660805564255495)
,p_computation_sequence=>70
,p_computation_item=>'P346_SALDO_COMPENSAR'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select to_char(nvl(sum(a.saldo_compensar), 0), ''FM999G999G990D00'')',
'from fin_titulopagamento a',
'join srv_entidade b on b.id = a.id_entidade',
'where lower(b.nome_entidade) = ''imp_pedidoimportacao''',
'  and exists (',
'        select 1',
'        from imp_pedidoimportacao_pagamento c',
'        join imp_entrega d ',
'          on d.id_pedidoimportacao = c.id_pedidoimportacao',
'        join imp_invoice_item e ',
'          on e.id_entrega = d.id',
'        where c.id = a.id_referencia',
'          and e.id_invoice = :P346_PARAMETRO',
'      )'))
);
