wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(213679104697255449)
,p_event_id=>wwv_flow_imp.id(213678554768255450)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var value = apex.item("id_tenant").getValue();',
'apex.item("id_idioma_empresa").setValue(value)',
'',
'window.naoAtualizar = ''true''',
'',
'var tenantValue = apex.item("id_tenant").getValue();',
'',
'apex.server.process(',
'    "SET_TENANT_GLOBAL",',
'    { x01: tenantValue },',
'    {',
'        success: function(pData) {',
unistr('            console.log("Sess\00E3o atualizada com sucesso:", pData);'),
'',
unistr('            // Atualiza o item global da sess\00E3o'),
'            apex.item("P0_TENANT_INFORMADO").setValue(pData);',
'',
unistr('            // Escuta o t\00E9rmino do refresh da regi\00E3o'),
