,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function getElValue($el) {',
'    if ($el.length === 0) return "";',
'',
'    // Se for um wrapper de datepicker: pega o input interno (*_input)',
'    if ($el.is(''a-date-picker'')) {',
'        let internal = $(''#'' + $el.attr(''id'') + ''_input'');',
'        return internal.length ? internal.val().trim() : "";',
'    }',
'',
'    // Se for input/select/textarea',
'    if ($el.is(''input, select, textarea'')) {',
'        return ($el.val() || "").trim();',
'    }',
'',
unistr('    // Caso contr\00E1rio, pega texto'),
'    return ($el.text() || "").trim();',
'}',
'',
'let configuracaoParcela = [];',
'',
'$(''[id^="valor_parcela_"]'').each(function () {',
'    let idFull = this.id;  ',
'    let idParcela = idFull.replace(''valor_parcela_'', '''');',
'',
'    //let $valorParcela     = $(''#valor_parcela_''      + idParcela);',
'    let $dataVencimento   = $(''#DATA_VENCIMENTO_''    + idParcela);',
'    let $valorCompensar   = $(''#valor_compensar_''    + idParcela);',
'    //let $valorGerarTitulo = $(''#valor_gerar_titulo_'' + idParcela);',
'',
'    configuracaoParcela.push({',
'        id: idParcela,        ',
'        data_vencimento: toDate(getElValue($dataVencimento)),',
'        valor_compensar: toNumber(getElValue($valorCompensar))',
'    });',
'});',
'',
'apex.item("P346_CONFIGURACAO_TITULOS").setValue(JSON.stringify(configuracaoParcela));',
''))
);
