,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_condicaopagamento_l                varchar2(4000);',
'    l_condicaopagamento_i                varchar2(4000);',
'    l_condicaopagamento_h                varchar2(4000);',
'    l_quantidade_parcelas_l              varchar2(4000);',
'    l_quantidade_parcelas_i              varchar2(4000);',
'    l_quantidade_parcelas_h              varchar2(4000);',
'    l_saldo_compensar_l                  varchar2(4000);',
'    l_saldo_compensar_i                  varchar2(4000);',
'    l_saldo_compensar_h                  varchar2(4000);    ',
'    l_titulo_report_l                    varchar2(4000) := retorna_texto(''msg.111.l'');',
'    l_label_numero_parcela               varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.numero_parcela'');',
'    l_label_percentual                   varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.percentual'');',
'    l_label_ind_evento_gerador_pagamento varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.ind_evento_gerador_pagamento'');',
'    l_label_valor                        varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.valor'');',
'    l_label_ind_status_pagamento         varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.ind_status_pagamento'');',
'    l_label_data_vencimento_prevista     varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.data_vencimento_prevista'');',
'    l_label_valor_a_compensar            varchar2(4000) := pkg_ui.retorna_label_tela(''valor_a_compensar'');',
'    l_label_valor_a_gerar_titulo         varchar2(4000) := pkg_ui.retorna_label_tela(''valor_a_gerar_titulo'');',
'    l_label_proximo                      varchar2(4000) := pkg_ui.retorna_label_botao(''proximo'');',
'    l_label_origem_saldo                 varchar2(4000) := pkg_ui.retorna_label_tela(''origem_saldo'');',
'    l_label_numero_pedido_importacao     varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao'');',
'    l_label_num_entrega                  varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'');',
'    l_label_valor_titulo                 varchar2(4000) := pkg_ui.retorna_label_coluna(''fin_titulopagamento.valor_titulo'');',
'begin',
'    pkg_ui.retorna_coluna(''imp_invoice.id_condicaopagamento'', l_condicaopagamento_l, l_condicaopagamento_i, l_condicaopagamento_h);',
'    pkg_ui.retorna_coluna(''imp_pedidoimportacao.quantidade_parcelas_pagamento'', l_quantidade_parcelas_l, l_quantidade_parcelas_i, l_quantidade_parcelas_h);',
'    pkg_ui.retorna_coluna(''fin_titulopagamento.saldo_compensar'', l_saldo_compensar_l, l_saldo_compensar_i, l_saldo_compensar_h);',
'',
'    :P346_CONDICAOPAGAMENTO_L                := l_condicaopagamento_l;',
'    :P346_CONDICAOPAGAMENTO_I                := l_condicaopagamento_i;',
'    :P346_CONDICAOPAGAMENTO_H                := l_condicaopagamento_h;',
'    :P346_QUANTIDADE_PARCELAS_L              := l_quantidade_parcelas_l;',
'    :P346_QUANTIDADE_PARCELAS_I              := l_quantidade_parcelas_i;',
'    :P346_QUANTIDADE_PARCELAS_H              := l_quantidade_parcelas_h;',
'    :P346_SALDO_COMPENSAR_L                  := l_saldo_compensar_l;',
'    :P346_SALDO_COMPENSAR_I                  := l_saldo_compensar_i;',
'    :P346_SALDO_COMPENSAR_H                  := l_saldo_compensar_h;',
'    :P346_TITULO_REPORT                      := l_titulo_report_l;',
'    :P346_LABEL_NUMERO_PARCELA               := l_label_numero_parcela;',
'    :P346_LABEL_PERCENTUAL                   := l_label_percentual;',
'    :P346_LABEL_IND_EVENTO_GERADOR_PAGAMENTO := l_label_ind_evento_gerador_pagamento;',
'    :P346_LABEL_VALOR                        := l_label_valor;',
'    :P346_LABEL_IND_STATUS_PAGAMENTO         := l_label_ind_status_pagamento;',
'    :P346_LABEL_DATA_VENCIMENTO_PREVISTA     := l_label_data_vencimento_prevista;',
'    :P346_LABEL_VALOR_A_COMPENSAR            := l_label_valor_a_compensar;',
'    :P346_LABEL_VALOR_A_GERAR_TITULO         := l_label_valor_a_gerar_titulo;',
'    :P346_LABEL_PROXIMO                      := l_label_proximo;',
'    :P346_LABEL_ORIGEM_SALDO                 := l_label_origem_saldo;',
'    :P346_LABEL_NUMERO_PEDIDO_IMPORTACAO     := l_label_numero_pedido_importacao;',
'    :P346_LABEL_NUM_ENTREGA                  := l_label_num_entrega;',
'    :P346_LABEL_VALOR_TITULO                 := l_label_valor_titulo;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>127981707824591030
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(213667144344255473)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'enviarParamentros'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_param1 varchar2(100) := apex_application.g_x01||''_''||APEX_CUSTOM_AUTH.GET_SESSION_ID;',
'    v_param2 varchar2(100) := apex_application.g_x02;',
'    v_param3 varchar2(100) := apex_application.g_x03;',
'    v_param4 varchar2(100) := apex_application.g_x04;',
'    v_existe number;',
'    v_id number;',
'begin',
unistr('    -- verifica se a cole\00E7\00E3o j\00E1 existe e a exclui para evitar duplica\00E7\00F5es'),
'    -- apex_debug.enable(apex_debug.c_log_level_info);',
'    -- apex_debug.info(''info enviarparamentros v_param1:%s'',v_param1); ',
'    -- apex_debug.info(''info enviarparamentros v_param2:%s'',v_param2); ',
'    -- apex_debug.info(''info enviarparamentros v_param3:%s'',v_param3); ',
'    -- apex_debug.info(''info enviarparamentros APEX_CUSTOM_AUTH.GET_SESSION_ID:%s'',APEX_CUSTOM_AUTH.GET_SESSION_ID); ',
'    if apex_application.g_x01 is not null then',
'        if upper(v_param2) = upper(''id_tenant'') and :P9010_ID is null then',
'            :P0_TENANT_INFORMADO := v_param3;',
'        end if;',
'',
'        if not apex_collection.collection_exists(v_param1) then',
'            apex_collection.create_collection(v_param1);',
'        end if;',
'',
'        select count(1) into v_existe ',
'        from apex_collections',
'        where collection_name = v_param1',
'          and c001 = v_param2;',
'        if v_existe > 0 then',
'            select seq_id into v_id ',
'            from apex_collections',
'            where collection_name = v_param1',
'              and c001 = v_param2;',
'',
'            -- if v_param4 is null then',
unistr('            --     RAISE_APPLICATION_ERROR(-20001, ''Paramentro ID n\00E3o informado para o campo:''||v_param2);'),
'            -- end if;',
'',
'            apex_collection.update_member (',
'                p_collection_name => v_param1,',
'                p_seq => v_id,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4);      ',
'        else',
'            apex_collection.add_member(',
'                p_collection_name => v_param1,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4',
'            );',
'        end if;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
,p_internal_uid=>127971617453591047
);
