,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    f.id,',
'    c.numero_pedido_importacao,',
'    b.num_entrega,',
'    d.codigo_item,',
'    pkg_traducao.get_traducao(d.descricao_item) descricao_item,',
'    e.codigo_unidademedida,',
'    case e.ind_tipo_dado',
'        when ''D'' then to_char(f.quantidade_saldo, ''FM999G999G990D00000'')',
'        when ''I'' then to_char(f.quantidade_saldo)',
'    end quantidade_saldo,',
'    f.ind_tratamento_saldo,',
'    case when f.ind_tratamento_saldo = ''1'' then ''selected'' end as SEL1,',
'    case when f.ind_tratamento_saldo = ''2'' then ''selected'' end as SEL2',
'from imp_invoice_item a',
'join imp_entrega b on b.id = a.id_entrega',
'join imp_pedidoimportacao c on c.id = b.id_pedidoimportacao',
'join ng_item d on d.id = a.id_item',
'join ng_unidademedida e on e.id = a.id_unidademedida',
'join imp_entrega_item f on f.id_entrega = b.id and f.id = a.id_entrega_item',
'where a.id_invoice = :P347_ID',
'and f.quantidade_saldo > 0',
'order by c.numero_pedido_importacao, b.num_entrega, f.id_pedidoimportacao_item'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P347_CODIGO_ARTEFATO,P347_ID,P347_COPIA,P347_PARAMETRO,P347_PARAMETRO2,P347_VISUALIZAR'
