wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(214036456126557835)
,p_plug_name=>'Em desenvolvimento'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(529623708881986997)
,p_plug_display_sequence=>230
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="dev-overlay">',
'  <div class="dev-box">',
'    ',
'    <div class="gears">',
'      <div class="gear gear1"></div>',
'      <div class="gear gear2"></div>',
'      <div class="gear gear3"></div>',
'    </div>',
'',
'    <h1 class="title">Em Desenvolvimento</h1>',
unistr('    <p class="subtitle">Estamos preparando algo incr\00EDvel \D83D\DE80</p>'),
'',
'    <div class="loading-bar">',
'      <div class="progress"></div>',
'    </div>',
'',
'  </div>',
'</div>',
'',
'<style>',
'.dev-overlay {',
'  position: fixed;',
'  top: 0;',
'  left: 0;',
'  width: 100%;',
'  height: 100%;',
'  background: linear-gradient(135deg, #0f2027, #203a43, #2c5364);',
'  display: flex;',
'  justify-content: center;',
'  align-items: center;',
'  z-index: 9999;',
'  font-family: Arial, sans-serif;',
'  color: #fff;',
'}',
'',
'.dev-box {',
'  text-align: center;',
'  animation: fadeIn 1.5s ease-in-out;',
'}',
'',
unistr('/* T\00EDtulo */'),
'.title {',
'  font-size: 42px;',
'  margin-top: 20px;',
'  text-shadow: 0 0 15px #00c6ff;',
'  animation: pulse 2s infinite;',
'}',
'',
'.subtitle {',
'  margin: 10px 0 30px;',
'  opacity: 0.8;',
'}',
'',
'/* Barra de loading */',
'.loading-bar {',
'  width: 300px;',
'  height: 8px;',
'  background: rgba(255,255,255,0.2);',
'  border-radius: 10px;',
'  overflow: hidden;',
'  margin: 0 auto;',
'}',
'',
'.progress {',
'  height: 100%;',
'  width: 0;',
'  background: linear-gradient(90deg, #00c6ff, #0072ff);',
'  animation: loading 3s infinite;',
'}',
'',
'/* Engrenagens */',
'.gears {',
'  position: relative;',
'  width: 120px;',
'  height: 120px;',
'  margin: 0 auto;',
'}',
'',
'.gear {',
'  width: 40px;',
'  height: 40px;',
'  border: 4px solid #00c6ff;',
'  border-radius: 50%;',
'  position: absolute;',
'}',
'',
'.gear1 {',
'  top: 0;',
'  left: 40px;',
'  animation: spin 4s linear infinite;',
'}',
'',
'.gear2 {',
'  bottom: 0;',
'  left: 0;',
'  animation: spinReverse 3s linear infinite;',
'}',
'',
'.gear3 {',
'  bottom: 0;',
'  right: 0;',
'  animation: spin 5s linear infinite;',
'}',
'',
unistr('/* Anima\00E7\00F5es */'),
'@keyframes spin {',
'  from { transform: rotate(0deg); }',
'  to { transform: rotate(360deg); }',
'}',
'',
'@keyframes spinReverse {',
'  from { transform: rotate(360deg); }',
'  to { transform: rotate(0deg); }',
'}',
'',
'@keyframes loading {',
'  0% { width: 0; }',
'  50% { width: 100%; }',
'  100% { width: 0; }',
'}',
'',
'@keyframes pulse {',
'  0%, 100% { opacity: 1; }',
'  50% { opacity: 0.6; }',
'}',
'',
'@keyframes fadeIn {',
'  from { opacity: 0; transform: translateY(20px);}',
'  to { opacity: 1; transform: translateY(0);}',
'}',
'</style>'))
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
