wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(375077001245709460)
,p_plug_name=>'Header'
,p_region_template_options=>'#DEFAULT#:t-ButtonRegion--noPadding:t-ButtonRegion--noUI'
,p_plug_template=>wwv_flow_imp.id(529590912278986980)
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_sql clob;',
'    l_pagina varchar2(256) := nvl(:P347_CODIGO_ARTEFATO,''TD452'');',
'begin',
'    l_sql := pkg_util.ObterValoresDasColunas (',
'        p_consulta_sql => ''',
'            select',
'                a.num_invoice,',
'                pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,',
'                case ',
'                    when a.id_processoimportacao is null then',
'                        pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                    else ',
'                        b.num_processoimportacao',
'                end id_processoimportacao',
'            from imp_invoice a',
'            left join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            where a.id =  ''||:P347_ID,',
'        p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'        p_formato => ''pequeno'',',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'    );',
'    return l_sql;',
'end;',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P347_ID,P347_PARAMETRO,P9010_PARAMETRO2'
,p_ai_enabled=>false
);
