wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(214036372621557834)
,p_computation_sequence=>50
,p_computation_item=>'P347_SALDO'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    case',
'        when exists (',
'            select 1 ',
'            from imp_invoice_item a',
'            join imp_entrega b on b.id = a.id_entrega',
'            join imp_entrega_item c on c.id_entrega = b.id and c.id = a.id_entrega_item',
'            where a.id_invoice = :P347_ID',
'            and c.quantidade_saldo > 0',
'        ) then',
'        2',
'    else',
'        1',
'    end as ind_tratameto_saldo',
'from dual '))
);
