,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_titulo_sem_saldo               varchar2(4000) := retorna_texto(''msg.144.l'');',
'    l_label_ind_saldo_todos          varchar2(4000) := retorna_texto(''msg.143.l'');',
'    l_label_aplicar_todos            varchar2(4000) := pkg_ui.retorna_label_botao(''aplicar_todos'');',
'    l_label_numero_pedido_importacao varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao'');',
'    l_label_num_entrega              varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'');',
'    l_label_codigo_item              varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_item.codigo_item'');',
'    l_label_descricao_item           varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_item.descricao_item'');',
'    l_label_codigo_unidademedida     varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_unidademedida.codigo_unidademedida'');',
'    l_label_quantidade_saldo         varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega_item.quantidade_saldo'');',
'    l_label_ind_tratamento_saldo     varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega_item.ind_tratamento_saldo'');',
'    l_instrucao_ind_tratamento_saldo varchar2(4000) := retorna_texto(''coluna.imp_entrega_item.ind_tratamento_saldo.i'');',
'    l_ind_tratamento_saldo_1         varchar2(4000) := pkg_util.dominio_retorna_tag(''imp_entrega_item'',''ind_tratamento_saldo'',''1'');',
'    l_ind_tratamento_saldo_2         varchar2(4000) := pkg_util.dominio_retorna_tag(''imp_entrega_item'',''ind_tratamento_saldo'',''2'');',
'begin',
'    :P347_TITULO_SEM_SALDO               := l_titulo_sem_saldo;',
'    :P347_LABEL_IND_SALDO_TODOS          := l_label_ind_saldo_todos;',
'    :P347_LABEL_APLICAR_TODOS            := l_label_aplicar_todos;',
