'    :P347_LABEL_NUM_ENTREGA              := l_label_num_entrega;',
'    :P347_LABEL_CODIGO_ITEM              := l_label_codigo_item;',
'    :P347_LABEL_DESCRICAO_ITEM           := l_label_descricao_item;',
'    :P347_LABEL_CODIGO_UNIDADEMEDIDA     := l_label_codigo_unidademedida;',
'    :P347_LABEL_QUANTIDADE_SALDO         := l_label_quantidade_saldo;',
'    :P347_LABEL_IND_TRATAMENTO_SALDO     := l_label_ind_tratamento_saldo;',
'    :P342_INSTRUCAO_IND_TRATAMENTO_SALDO := l_instrucao_ind_tratamento_saldo;',
'    :P342_IND_TRATAMENTO_SALDO_1         := l_ind_tratamento_saldo_1;',
'    :P342_IND_TRATAMENTO_SALDO_2         := l_ind_tratamento_saldo_2;',
'end;'))
