prompt --application/pages/page_00348
begin
wwv_flow_imp_page.create_page(
 p_id=>348
,p_name=>unistr('Compensar t\00EDtulos de pagamentos')
,p_alias=>unistr('COMPENSAR-T\00CDTULOS-DE-PAGAMENTOS')
,p_page_mode=>'MODAL'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'https://cdnjs.cloudflare.com/ajax/libs/jquery.inputmask/5.0.9/jquery.inputmask.min.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function somarInputsTitulo() {',
'    var total = 0;',
'',
'    $("input[id^=''id_titulo_'']").each(function() {',
'        var id = $(this).attr("id");',
'',
'        if (id !== "id_titulo_0") {',
'            var valor = $(this).val() || "0";',
'',
'            // trata formato brasileiro (1.234,56)',
'            valor = valor.replace(/\./g, "").replace(",", ".");',
'',
'            var numero = parseFloat(valor);',
'',
'            if (!isNaN(numero)) {',
'                total += numero;',
'            }',
'        }',
'    });',
'',
unistr('    // pega valor do item de p\00E1gina (sem formata\00E7\00E3o)'),
'    var valorPagina = $v("P348_PARCELA_VALOR") || "0";',
'    var valorReferencia = parseFloat(valorPagina);',
'',
'    // atualiza total formatado',
'    var totalFormatado = total.toLocaleString("pt-BR", {',
'        minimumFractionDigits: 2,',
'        maximumFractionDigits: 2',
'    });',
'',
'    $("#id_titulo_0").val(totalFormatado);',
'',
'    // remove antes',
'    $("#id_titulo_0").removeClass("erro-total");',
'',
'    if (Math.abs(total - valorReferencia) > 0.009) {',
'        $("#id_titulo_0").addClass("erro-total");',
'    }',
'',
unistr('    // salva no item de p\00E1gina (sem formata\00E7\00E3o)'),
'    $s("P348_TOTAL_VALOR_COMPENSADO", formatarValor(total));',
'}',
'',
'function limitarValor(input) {',
'    var max = parseFloat($(input).attr(''max'').replace('','',''.'')) || 0;',
'',
'    var val = $(input).val()',
'        .replace(/\./g,'''')',
'        .replace('','', ''.'');',
'',
'    var num = parseFloat(val);',
'',
'    if (!isNaN(num)) {',
'        if (num > max) num = max;',
'        if (num < 0) num = 0; // opcional',
'',
'        $(input).val(',
'            num.toLocaleString(''pt-BR'', {',
'                minimumFractionDigits: 2,',
'                maximumFractionDigits: 2',
'            })',
'        );',
'    }',
'',
'    console.log(''max: '' + max);',
'    console.log(''val: '' + val);',
'    console.log(''num: '' + num);',
'',
'}',
'',
'function normalizarNumero(valor, sepDecimal, sepMilhar) {',
'    if (!valor) return 0;',
'',
'    return parseFloat(',
'        valor',
'            .replace(new RegExp(''\\'' + sepMilhar, ''g''), '''') // remove milhar',
'            .replace(sepDecimal, ''.'') // troca decimal por ponto',
'    ) || 0;',
'}',
'',
'//-----------------------------------------------------------------------------------------------------------------------------------------------------------//',
unistr('// Fun\00E7\00E3o para formatar n\00FAmeros com o padr\00E3o ''FM999G999G990D00'''),
'function formatarValor(valor) {',
unistr('    // Garante que o valor seja um n\00FAmero v\00E1lido'),
'    if (isNaN(valor)) return '''';',
'',
unistr('    // Obt\00E9m os valores dos itens de p\00E1gina (separadores decimal e num\00E9rico)'),
unistr('    var separadorDecimal = $(''#P348_SEPARADOR_DECIMAL'').val(); // Item de p\00E1gina para o separador decimal'),
unistr('    var separadorNumerico = $(''#P348_SEPARADOR_NUMERICO'').val(); // Item de p\00E1gina para o separador num\00E9rico    '),
'',
'    // Separa a parte inteira e decimal',
unistr('    var partes = valor.toFixed(2).split(''.''); // Formata o n\00FAmero com 2 casas decimais fixas'),
'    var inteiro = partes[0];',
'    var decimal = partes[1];',
'',
unistr('    // Adiciona separadores de milhar (utilizando o separador num\00E9rico)'),
unistr('    // A regex abaixo insere o separador de milhar a cada 3 d\00EDgitos da parte inteira'),
'    inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, separadorNumerico);',
'',
'    // Une a parte inteira e decimal com o separador decimal',
'    return inteiro + separadorDecimal + decimal;',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'tituloTela($v("P348_TELA_TITULO")+'' (''+$v("P348_CODIGO_ARTEFATO")+'')'');',
'',
'$(''input[id^="id_titulo_"]'').on(''input'', function() {',
'    var max = parseFloat($(this).attr(''max'').replace('','',''.'')) || 0;',
'    var val = $(this).val().replace(/\./g,'''').replace('','', ''.'');',
'    var num = parseFloat(val);',
'',
'    if (!isNaN(num) && num > max) {',
'        $(this).val(max.toLocaleString(''pt-BR'', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));',
'    }',
'',
'});',
'',
unistr('// Executa no carregamento da p\00E1gina'),
'$(document).ready(function() {',
'    $(''input[id^="id_titulo_"]'').each(function() {',
'        limitarValor(this);',
'    });',
'    ',
unistr('    // ao carregar a p\00E1gina'),
'    somarInputsTitulo();',
'});',
'',
'// ao digitar em qualquer input',
'$(document).on("input", "input[id^=''id_titulo_'']", function() {',
'    somarInputsTitulo();',
'});',
'',
unistr('// ap\00F3s refresh do relat\00F3rio'),
'$("#TITULO_PAGAMENTO").on("apexafterrefresh", function() {',
'    somarInputsTitulo();',
'});',
'',
'/************************************************************************************** */',
'',
'',
unistr('// Armazena os valores digitados \2014 persiste mesmo entre pesquisas'),
'var cacheValores = {};',
'',
'// function aplicarConfiguracoesDeEntrada() { ',
'//     // Aplica AutoNumeric e outros ajustes ',
'//     $("[id^=''id_item_'']").each(function () { ',
'//         const inputId = $(this).attr(''id''); ',
'//         const $input = $(''#'' + inputId);',
'//         const integerDigits = parseInt($input.data(''integer-digits'')) || 10; ',
'//         const prefix = '''';         ',
'//         const decimalPlaces = parseInt($input.data(''decimal-places'')) || 0;',
'//         const groupSeparatorType = $(''#P348_SEPARADOR_NUMERICO'').val();',
'//         const decimalSeparatorType = $(''#P348_SEPARADOR_DECIMAL'').val();',
'',
'//         const allowNegative = false;',
'        ',
'//         applyAutoNumericMask(''#'' + inputId, decimalPlaces, prefix, groupSeparatorType, decimalSeparatorType, allowNegative, integerDigits);        ',
'',
'//         // Se existir valor no cache, reaplica ',
'//         if (cacheValores[inputId] !== undefined) { ',
'//             $input.val(cacheValores[inputId]); ',
'//         } ',
'//     });',
'',
'function aplicarConfiguracoesDeEntrada() { ',
'    $("[id^=''id_titulo_'']").each(function () { ',
'        const $input = $(this);',
'        const inputId = $input.attr(''id''); // <- adiciona aqui',
'        const integerDigits = parseInt($input.data(''integer-digits'')) || 10;',
'        const decimalPlaces = parseInt($input.data(''decimal-places'')) || 2;',
'        const groupSeparator = $(''#P348_SEPARADOR_NUMERICO'').val() || ''.'';',
'    ',
'        if (decimalPlaces === 0) {',
'            // Remove qualquer AutoNumeric previamente aplicado',
'            const an = AutoNumeric.getAutoNumericElement($input[0]);',
'            if (an) an.remove();',
'',
unistr('            // Bloqueia tudo que n\00E3o for n\00FAmero'),
'            $input.off(''input.integerMask'').on(''input.integerMask'', function () {',
unistr('                let val = $input.val().replace(/\005CD/g,''''); // mant\00E9m s\00F3 n\00FAmeros'),
'                if (val.length > integerDigits) val = val.slice(0, integerDigits);',
'                val = val.replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);',
'                $input.val(val);',
'            });',
'',
unistr('            // Impede digitar caracteres n\00E3o num\00E9ricos'),
'            $input.off(''keypress.integerMask'').on(''keypress.integerMask'', function(e){',
'                if (!/[0-9]/.test(e.key)) e.preventDefault();',
'            });',
'        } else {',
'            // Para decimais, continua usando AutoNumeric normalmente',
'            const prefix = '''';',
'            const allowNegative = false;',
'            applyAutoNumericMask(''#'' + inputId, decimalPlaces, prefix, groupSeparator, $(''#P348_SEPARADOR_DECIMAL'').val(), allowNegative, integerDigits);',
'        }',
'',
'        // --- Reaplica valor do cache ---',
'        if (cacheValores[inputId] !== undefined) {',
'            let val = cacheValores[inputId];',
'',
'            if (decimalPlaces === 0) {',
'                // Para inteiros, aplica separador de milhar manual',
unistr('                val = val.replace(/\005CD/g,''''); // mant\00E9m s\00F3 n\00FAmeros'),
'                if (val.length > integerDigits) val = val.slice(0, integerDigits);',
'                val = val.replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);',
'            }',
'            $input.val(val);',
'        }',
'    })',
'    ',
unistr('    // Captura altera\00E7\00F5es e atualiza cache global'),
'    $(document).off(''input.cacheValores'').on(''input.cacheValores'', ''[id^="id_item_"]'', function () {',
'        const id = $(this).attr(''id'');',
'        cacheValores[id] = $(this).val();',
'    });',
'',
'    // Clique individual de saldo',
'    $(document).off(''click.saldoSimples'').on(''click.saldoSimples'', ''[id^="id_saldo_"]'', function () {',
'        atribuiSaldoSimples(this);',
'    });',
'',
'    // Reaplica estilo para linhas sem input (mantendo .slice(1))',
'    // apex.jQuery(document).ready(function () {',
'    //     var $linhas = apex.jQuery("#ENTREGA_ITENS tbody tr");',
'',
'    //     $linhas.slice(1).each(function () {',
'    //         var $row = apex.jQuery(this);',
'    //         if ($row.find("input").length === 0) {',
'    //             $row.addClass("apex_disabled");',
'    //         }',
'    //     });',
'    // });',
'',
unistr('    // Impede ativa\00E7\00E3o de filtro por teclado, exceto no cabe\00E7alho "atribuir_saldo_total" e elementos com id come\00E7ando com "id_item_"'),
'    $(document).on("keydown", "#ENTREGA_ITENS .a-IRR-headerLink", function(e) {',
'        const $header = $(this);',
'        const id = $header.attr("id") || "";',
'',
unistr('        // Permite se for o \00EDcone do cabe\00E7alho ou algum elemento din\00E2mico de item'),
'        const isExcecao = id === "atribuir_saldo_total" || id.startsWith("id_item_");',
'',
'        if (!isExcecao && (e.key === "Enter" || e.key === " " || e.key === "Spacebar")) {',
'            e.preventDefault();',
'            e.stopPropagation();',
'        }',
'    });',
'',
'}',
'',
unistr('// Executa ao carregar a p\00E1gina'),
'aplicarConfiguracoesDeEntrada();',
'',
'// Antes do refresh, salva todos os valores digitados',
'$("#ENTREGA_ITENS").on("apexbeforerefresh", function () {',
'    $("[id^=''id_item_'']").each(function () {',
'        const id = $(this).attr(''id'');',
'        cacheValores[id] = $(this).val();',
'    });',
'});',
'',
unistr('// Ap\00F3s o refresh, reaplica configura\00E7\00F5es e restaura valores do cache'),
'$("#ENTREGA_ITENS").on("apexafterrefresh", function () {',
'    aplicarConfiguracoesDeEntrada();',
'});',
'',
unistr('// Clique atribui\00E7\00E3o total de saldo'),
'$(document).on(''click'', ''#atribuir_saldo_total'', function() {    ',
'    var $icones = $(''[id^="id_item_"]'');',
'',
'    if ($icones.length === 0) {',
unistr('        apex.message.alert("Nenhum item dispon\00EDvel para atribui\00E7\00E3o de saldo.");'),
'        return;',
'    }',
'',
'    apex.message.confirm("Deseja realmente atribuir o saldo total a todos os itens?", function(okPressed) {',
'        if (okPressed) {',
'            atribuiSaldoTotal();',
'        }        ',
'    });',
'});'))
