,p_plug_template=>wwv_flow_imp.id(529621672076986996)
,p_plug_display_sequence=>320
,p_plug_item_display_point=>'BELOW'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct',
'    a.id,',
'    d.numero_pedido_importacao,',
'    c.numero_parcela,',
'    to_char(a.saldo_compensar, ''FM999G999G990D00'') saldo_compensar,',
'    to_char(nvl(f.valor_compensado, bo_fin_titulopagamento.valor_compensado_sugerido(a.id,:P348_NUMERO_PARCELA)), ''FM999G999G990D00'') valor_compensado,',
'    null APEX_ATTRIBUTE,',
'    a.saldo_compensar saldo_bruto',
'from fin_titulopagamento a',
'join srv_entidade b on b.id = a.id_entidade',
'join imp_pedidoimportacao_pagamento c on c.id = a.id_referencia',
'join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'join imp_entrega e on e.id_pedidoimportacao = d.id',
'left join imp_titulo_compensado f on f.id_titulopagamento = a.id and f.id_invoice_parcela = :P348_ID',
'where to_char(a.id) in (',
'    select column_value from apex_string.split(bo_imp_invoice_pagamento.retorna_saldo_compensar(:P348_PARAMETRO, 1), '','')    ',
')',
'and a.saldo_compensar > 0',
'and b.nome_entidade = ''imp_pedidoimportacao''',
'and e.id_invoice = :P348_PARAMETRO',
'',
'union all',
'select ',
'    0,',
'    null,',
'    null,',
'    pkg_ui.retorna_label_tela(''total_compensar''),',
'    null,',
'    ''disabled'' APEX_ATTRIBUTE,',
'    null',
'from dual',
'',
'order by numero_pedido_importacao, numero_parcela'))
,p_plug_source_type=>'NATIVE_IR'
