wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(220366926275323332)
,p_event_id=>wwv_flow_imp.id(220366366879323333)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'somarInputsTitulo();',
'',
'let titulos = [];',
'',
'var separadorDecimal = $(''#P348_SEPARADOR_DECIMAL'').val();',
'var separadorNumerico = $(''#P348_SEPARADOR_NUMERICO'').val();',
'',
'$(''input[id^="id_titulo_"]'').each(function() {',
'    var $el = $(this);',
'    var idTitulo = $el.attr(''id'').replace(''id_titulo_'', '''');',
'',
'    if (idTitulo === "0") return; ',
'',
'    var valorCompensarRaw = $el.val().trim();',
'',
'    var valorCompensar = normalizarNumero(',
'        valorCompensarRaw,',
'        separadorDecimal,',
'        separadorNumerico',
'    );',
'',
'    titulos.push({ ',
'        id: idTitulo, ',
'        valor_compensado: valorCompensar',
'    });',
'});',
'',
'apex.item("P348_JSON").setValue(JSON.stringify(titulos));'))
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(214039932376557870)
,p_event_id=>wwv_flow_imp.id(220366366879323333)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_CONFIRM'
,p_attribute_01=>'&P348_MSG_CONFIRMACAO.'
,p_attribute_02=>'&P348_TITULO_CONFIRMACAO.'
,p_attribute_03=>'warning'
,p_attribute_04=>'fa-lg fa-exclamation-triangle'
,p_attribute_06=>'&P348_LABEL_ACAO.'
,p_client_condition_type=>'JAVASCRIPT_EXPRESSION'
,p_client_condition_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function() {',
'    var total = 0;',
'',
'    $("input[id^=''id_titulo_'']").each(function() {',
'        var id = $(this).attr("id");',
'',
'        if (id !== "id_titulo_0") {',
'            var valor = $(this).val() || "0";',
'',
'            valor = valor.replace(/\./g, "").replace(",", ".");',
'            var numero = parseFloat(valor);',
'',
'            if (!isNaN(numero)) {',
'                total += numero;',
'            }',
'        }',
'    });',
'',
'    var valorPagina = $v("P348_PARCELA_VALOR") || "0";',
'    var valorReferencia = parseFloat(valorPagina);',
'',
'    return Math.abs(total - valorReferencia) > 0.009;',
'})();'))
);
