,p_plug_display_sequence=>370
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- select ',
'--     c.descricao_despesa,',
'--     e.codigo_moeda || '' - '' || e.simbolo_iso as "MOEDA PREVISTA",',
'--     b.valor_previsto,',
'--     d.codigo_moeda || '' - '' || d.simbolo_iso as "MOEDA REALIZADA",',
'--     ''<input type="text"',
'--             class="apex-item-text"',
'--             value="'' || to_char(b.valor_realizado ,''FM999G999G990D00000'') || ''"',
'--             id="valor_realizado_'' || b.id || ''"',
'--             data-id="'' || b.id || ''"',
'--             style="width:100%;">',
'--     </input>'' valor_realizado,',
'--     pkg_componentes.html_botao_opcao_com_icone(p_id => b.id, p_pagina => ''350'', p_param1 => :ID_PROCESSOIMPORTACAO) opcao',
'',
'-- from imp_declaracaoimportacao a',
'-- left join imp_processoimportacao_despesa b',
'--        on a.id_processoimportacao = b.id_processoimportacao',
'-- left join ng_despesa c',
'--        on c.id = b.id_despesa',
'-- left join ng_moeda d',
'--      on d.id = b.id_moeda_realizada',
'-- left join ng_moeda e',
'--      on e.id = b.id_moeda_prevista',
'-- where a.id = :P350_PARAMETRO',
'--   and c.ind_tipo_despesa in (7, 8, 9, 10, 11, 16, 17)',
'  ',
'',
'',
'',
'  select ',
'    c.descricao_despesa,',
'    e.codigo_moeda || '' - '' || e.simbolo_iso as "MOEDA_PREVISTA",',
'    b.valor_previsto,',
'    ''<select id="id_moeda_realizada_'' || b.id || ''"',
'             data-id="'' || b.id || ''"',
'             data-sugerido="'' || b.id_moeda_prevista || ''"',
'             class="apex-item-select"',
'             style="width:100%;">''',
'    || (select listagg(',
'            ''<option value="'' || m.id || ''"''',
'            || case when m.id = nvl(b.id_moeda_realizada, b.id_moeda_prevista)',
'                    then '' selected="selected"'' else '''' end',
'            || ''>'' || m.codigo_moeda || '' - '' || m.simbolo_iso || ''</option>'', '''')',
'        within group (order by m.codigo_moeda)',
'        from ng_moeda m)',
'    || ''</select>'' as "MOEDA_REALIZADA",',
'    ''<input type="text"',
'            class="apex-item-text"',
'            value="'' || to_char(b.valor_realizado, ''FM999G999G990D00000'') || ''"',
'            id="valor_realizado_'' || b.id || ''"',
'            data-id="'' || b.id || ''"',
'            style="width:100%;">',
'    </input>'' valor_realizado,',
'    pkg_componentes.html_botao_opcao_com_icone(p_id => b.id, p_pagina => ''350'', p_param1 => :ID_PROCESSOIMPORTACAO) opcao',
'',
'from imp_declaracaoimportacao a',
'left join imp_processoimportacao_despesa b',
'       on a.id_processoimportacao = b.id_processoimportacao',
'left join ng_despesa c',
'       on c.id = b.id_despesa',
'left join ng_moeda e',
'       on e.id = b.id_moeda_prevista',
'where a.id = :P350_PARAMETRO',
'  and c.ind_tipo_despesa in (7, 8, 9, 10, 11, 16, 17)',
'  ',
''))
,p_plug_source_type=>'NATIVE_IR'
