,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_numero_pedidoimportacao varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega.id_pedidoimportacao'');',
'    l_num_entrega varchar2(4000)             := pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'');',
'    l_codigo_item varchar2(4000)             := pkg_ui.retorna_label_coluna(''imp_entrega_item.id_item'');',
'    l_descricao_item varchar2(4000)          := pkg_ui.retorna_label_coluna(''imp_entrega_item.id_item'');',
'    l_unidademedida varchar2(4000)           := pkg_ui.retorna_label_coluna(''imp_entrega_item.id_unidademedida'');',
'    l_entrega_quantidade varchar2(4000)      := pkg_ui.retorna_label_coluna(''imp_entrega_item.quantidade_saldo'');',
'    l_invoice_quantidade varchar2(4000)      := pkg_ui.retorna_label_coluna(''imp_invoice_item.quantidade'');',
'begin',
'    :P350_LABEL_NUMERO_PEDIDOIMPORTACAO := l_numero_pedidoimportacao;',
'    :P350_LABEL_NUM_ENTREGA             := l_num_entrega;',
'    :P350_LABEL_CODIGO_ITEM             := l_codigo_item;',
'    :P350_LABEL_DESCRICAO_ITEM          := l_descricao_item;',
'    :P350_LABEL_UNIDADEMEDIDA           := l_unidademedida;',
'    :P350_LABEL_ENTREGA_QUANTIDADE      := l_entrega_quantidade;',
'    :P350_LABEL_INVOICE_QUANTIDADE      := l_invoice_quantidade;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>202464516755799666
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(202469440513799676)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'enviarParamentros'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_param1 varchar2(100) := apex_application.g_x01||''_''||APEX_CUSTOM_AUTH.GET_SESSION_ID;',
'    v_param2 varchar2(100) := apex_application.g_x02;',
'    v_param3 varchar2(100) := apex_application.g_x03;',
'    v_param4 varchar2(100) := apex_application.g_x04;',
'    v_existe number;',
'    v_id number;',
'begin',
unistr('    -- verifica se a cole\00E7\00E3o j\00E1 existe e a exclui para evitar duplica\00E7\00F5es'),
'    -- apex_debug.enable(apex_debug.c_log_level_info);',
'    -- apex_debug.info(''info enviarparamentros v_param1:%s'',v_param1); ',
'    -- apex_debug.info(''info enviarparamentros v_param2:%s'',v_param2); ',
'    -- apex_debug.info(''info enviarparamentros v_param3:%s'',v_param3); ',
'    -- apex_debug.info(''info enviarparamentros APEX_CUSTOM_AUTH.GET_SESSION_ID:%s'',APEX_CUSTOM_AUTH.GET_SESSION_ID); ',
'    if apex_application.g_x01 is not null then',
'        if upper(v_param2) = upper(''id_tenant'') and :P350_ID is null then',
'            :P0_TENANT_INFORMADO := v_param3;',
'        end if;',
'',
'        if not apex_collection.collection_exists(v_param1) then',
'            apex_collection.create_collection(v_param1);',
'        end if;',
'',
'        select count(1) into v_existe ',
'        from apex_collections',
'        where collection_name = v_param1',
'          and c001 = v_param2;',
'        if v_existe > 0 then',
'            select seq_id into v_id ',
'            from apex_collections',
'            where collection_name = v_param1',
'              and c001 = v_param2;',
'',
'            apex_collection.update_member (',
'                p_collection_name => v_param1,',
'                p_seq => v_id,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4);      ',
'        else',
'            apex_collection.add_member(',
