,p_plug_template=>wwv_flow_imp.id(529623708881986997)
,p_plug_display_sequence=>370
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct',
'    (e.codigo_moeda|| '' - '' || e.simbolo_iso) as "MOEDA",',
'    ''<input type="text"',
'            class="apex-item-text"',
'            value="'' || to_char(d.taxa_cambio ,''FM999G999G990D00000'') || ''"',
'            id="taxa_cambio_'' || e.id || ''"',
'            data-id="'' || e.id || ''"',
'            style="width:100%;">',
'    </input>'' taxa_cambio',
'from imp_declaracaoimportacao    a',
'left join imp_processoimportacao_item f on f.id_processoimportacao = a.id_processoimportacao',
'left join imp_processoimportacao_despesa b      on a.id_processoimportacao = b.id_processoimportacao',
'left join ng_despesa c                          on c.id = b.id_despesa',
'join ng_moeda e     on e.id = f.id_moeda or e.id = b.id_moeda_realizada',
'left join imp_declaracaoimportacao_cotacao d',
'    on d.id_declaracaoimportacao = a.id',
'   and d.id_moeda               = e.id  ',
'where a.id = :P351_PARAMETRO',
'and c.ind_tipo_despesa in (7, 8, 9, 10, 11, 16, 17)',
'',
''))
