,p_client_condition_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function() {',
'    var total = 0;',
'',
'    $("input[id^=''id_titulo_'']").each(function() {',
'        var id = $(this).attr("id");',
'',
'        if (id !== "id_titulo_0") {',
