wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(228322761339116083)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_msg_valor_compensado       varchar2(4000) := retorna_texto(''msg.148.l'');',
'    l_msg_confirmacao            varchar2(4000) := retorna_texto(''msg.151.l'');',
'    l_titulo_confirmacao         varchar2(4000) := retorna_texto(''msg.151.h'');',
'    l_label_atribuir_saldo       varchar2(4000) := pkg_ui.retorna_label_tela(''atribuir_saldo'');',
'    l_label_input                varchar2(4000) := pkg_ui.retorna_label_coluna(''imp_entrega_item.quantidade'');',
'    l_label_pesquisar            varchar2(4000) := pkg_ui.retorna_label_tela(''pesquisar'');',
'begin',
'    :P352_LABEL_NUM_ENTREGA            := pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'');',
'    :P352_LABEL_ID_EXPORTADOR          := pkg_ui.retorna_label_coluna(''imp_entrega.id_exportador'');',
'    :P352_LABEL_ID_IMPORTADOR          := pkg_ui.retorna_label_coluna(''imp_entrega.id_importador'');',
'    :P352_LABEL_ID_ADQUIRENTE          := pkg_ui.retorna_label_coluna(''imp_entrega.id_adquirente'');',
'    :P352_LABEL_NUM_PROCESSOIMPORTACAO := pkg_ui.retorna_label_coluna(''imp_processoimportacao.num_processoimportacao'');',
'',
'    :P352_MSG_VALOR_COMPENSADO       := l_msg_valor_compensado;',
'    :P352_MSG_CONFIRMACAO            := l_msg_confirmacao;',
'    :P352_TITULO_CONFIRMACAO         := l_titulo_confirmacao;',
'    :P352_LABEL_ATRIBUIR_SALDO       := l_label_atribuir_saldo;',
'    :P352_LABEL_INPUT                := l_label_input;',
'    :P352_LABEL_PESQUISAR            := l_label_pesquisar;',
'    --',
'    :P352_LABEL_NUMERO_PEDIDO_IMPORTACAO := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao'');',
'    :P352_LABEL_IND_TODOS_ITENS_COM_ENTREGAS_PROGRAMADAS := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.ind_todos_itens_com_entregas_programadas'');',
'    select ',
'        numero_pedido_importacao,',
'        pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'', ''ind_todos_itens_com_entregas_programadas'', ind_todos_itens_com_entregas_programadas),',
'        ind_todos_itens_com_entregas_programadas',
'    into',
'        :P352_NUMERO_PEDIDO_IMPORTACAO,',
'        :P352_IND_TODOS_ITENS_COM_ENTREGAS_PROGRAMADAS,',
'        :P352_INDICADOR',
'    from imp_pedidoimportacao',
'    where id = :P352_ID;',
'',
'    pkg_ui.retorna_coluna(',
'        ''imp_pedidoimportacao.data_confirmacao_pedido'',',
'        :P352_LABEL_DATA_CONFIRMACAO_PEDIDO,',
'        :P352_INSTRUCAO_DATA_CONFIRMACAO_PEDIDO,',
'        :P352_HELP_DATA_CONFIRMACAO_PEDIDO',
'    );',
'',
'    :P352_LABEL_GERA_PROCESSO := pkg_ui.retorna_label_tela(''gera_processo'');',
'    :P352_HELP_GERA_PROCESSO  := retorna_texto(''tela.gera_processo.h'');',
'',
'    select count(1) into :P352_QTD_ENTREGA from imp_entrega where id_pedidoimportacao = :P352_ID;',
'',
'    select ',
'        case when codigo_dominio = 2 then ''S'' else ''N'' end',
'    into',
'        :P352_IMP_NG',
'    from mpd_configuracao_ng a ',
'    join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id',
'    left join imp_pedidoimportacao c on c.id_tenant = a.id_tenant',
'    where a.codigo_configuracao = 7 ',
'    and b.id = a.valor_dominio',
'    and c.id = :P352_ID;',
'',
'    :P352_LABEL_FIRMAR := pkg_ui.retorna_label_botao(''firmar'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>228322761339116083
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(228324699810116088)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'enviarParamentros'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_param1 varchar2(100) := apex_application.g_x01||''_''||APEX_CUSTOM_AUTH.GET_SESSION_ID;',
'    v_param2 varchar2(100) := apex_application.g_x02;',
'    v_param3 varchar2(100) := apex_application.g_x03;',
'    v_param4 varchar2(100) := apex_application.g_x04;',
'    v_existe number;',
'    v_id number;',
'begin',
unistr('    -- verifica se a cole\00E7\00E3o j\00E1 existe e a exclui para evitar duplica\00E7\00F5es'),
'    -- apex_debug.enable(apex_debug.c_log_level_info);',
'    -- apex_debug.info(''info enviarparamentros v_param1:%s'',v_param1); ',
'    -- apex_debug.info(''info enviarparamentros v_param2:%s'',v_param2); ',
'    -- apex_debug.info(''info enviarparamentros v_param3:%s'',v_param3); ',
'    -- apex_debug.info(''info enviarparamentros APEX_CUSTOM_AUTH.GET_SESSION_ID:%s'',APEX_CUSTOM_AUTH.GET_SESSION_ID); ',
'    if apex_application.g_x01 is not null then',
'        if upper(v_param2) = upper(''id_tenant'') and :P352_ID is null then',
'            :P0_TENANT_INFORMADO := v_param3;',
'        end if;',
'',
'        if not apex_collection.collection_exists(v_param1) then',
'            apex_collection.create_collection(v_param1);',
'        end if;',
'',
'        select count(1) into v_existe ',
'        from apex_collections',
'        where collection_name = v_param1',
'          and c001 = v_param2;',
'        if v_existe > 0 then',
'            select seq_id into v_id ',
'            from apex_collections',
'            where collection_name = v_param1',
'              and c001 = v_param2;',
'',
'            apex_collection.update_member (',
'                p_collection_name => v_param1,',
'                p_seq => v_id,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4);      ',
'        else',
'            apex_collection.add_member(',
'                p_collection_name => v_param1,',
'                p_c001 => v_param2,',
'                p_c002 => v_param3,',
'                p_c003 => v_param4',
'            );',
'        end if;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
,p_internal_uid=>228324699810116088
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(228322363907116082)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'atribuiValorAJAX'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json CLOB;',
'BEGIN',
'    l_json := pkg_formulario_dinamico.executa_sql_parametrizado(',
'        p_param1 => apex_application.g_x01,',
'        p_sql    => apex_application.g_x02',
'    );',
'    sys.htp.init;   -- limpa buffer anterior',
'    owa_util.mime_header(''application/json'', FALSE);',
'    htp.p(''Cache-Control: no-cache'');',
'    owa_util.http_header_close;',
'    htp.prn(l_json); -- imprime exatamente o JSON',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
,p_internal_uid=>228322363907116082
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(228323164291116084)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'VALIDAR_SENHA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_result BOOLEAN;',
'BEGIN',
'    v_result := PKG_SEGURANCA.auth(apex_custom_auth.get_username, apex_application.g_x01);',
'    -- Retorna o resultado como JSON',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''success'', CASE WHEN v_result THEN ''true'' ELSE ''false'' END);',
'    APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
,p_internal_uid=>228323164291116084
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(228323598978116085)
,p_process_sequence=>40
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'VALIDAR'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_clob clob;',
'    v_messages pkg_mensagem.message_record_table;',
'    l_pagina varchar2(256) := nvl(:p352_codigo_artefato,''td452'');',
'begin',
'    execute immediate',
'        ''begin :v_messages := ui_mpd_''||l_pagina||''.valida(:p_id); end;''',
'        using out v_messages, in apex_application.g_x01;',
'',
'    -- Monta JSON de retorno',
'    apex_json.initialize_clob_output;',
'    apex_json.open_array;',
'',
'    if v_messages.count > 0 then',
'        for i in 1 .. v_messages.count loop',
'            apex_json.open_object;',
'            apex_json.write(''mensagem'',       v_messages(i).mensagem);',
'            apex_json.write(''instrucao'',      v_messages(i).instrucao);',
'            apex_json.write(''help'',           v_messages(i).help);',
'            apex_json.write(''local_exibicao'', v_messages(i).local_exibicao);',
'            apex_json.write(''nome_item'',      v_messages(i).nome_item);',
'            apex_json.write(''tipo'',           v_messages(i).tipo);',
'            apex_json.close_object;',
'        end loop;',
'    end if;',
'',
'    apex_json.close_array;',
'    l_clob := apex_json.get_clob_output;',
'    apex_json.free_output;    ',
'    sys.htp.prn(l_clob);     ',
'',
'    exception',
'        when others then',
'        -- Monta JSON de erro consistente',
'        apex_json.initialize_clob_output;',
'        apex_json.open_array;',
'        apex_json.open_object;',
'        apex_json.write(''semValidacao'', ''sim'');',
'        apex_json.close_object;',
'        apex_json.close_array;',
'',
'        l_clob := apex_json.get_clob_output;',
'        apex_json.free_output;    ',
'        sys.htp.prn(l_clob);     ',
'    ',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(529550877024986936)
,p_internal_uid=>228323598978116085
);
end;
