prompt --application/pages/page_00429
begin
wwv_flow_imp_page.create_page(
 p_id=>429
,p_name=>unistr('Importa\00E7\00E3o de invoice via PDF')
,p_alias=>unistr('IMPORTA\00C7\00C3O-DE-INVOICE-VIA-PDF')
,p_step_title=>unistr('Importa\00E7\00E3o de invoice via PDF')
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function (apex, $) {',
'    "use strict";',
'',
'    const regionSelector = "#invoiceReconciliationRegion";',
'',
'    function itemContainer(itemName) {',
'        const element = document.getElementById(itemName);',
'        if (!element) return null;',
'',
'        return element.closest(".t-Form-fieldContainer")',
'            || element.closest(".t-Form-inputContainer")',
'            || element.parentElement;',
'    }',
'',
'    function moveItems() {',
'        document.querySelectorAll(regionSelector + " [data-item-slot]").forEach(function (slot) {',
'            const itemName = slot.dataset.itemSlot;',
'            const container = itemContainer(itemName);',
'',
'            if (!container || slot.contains(container)) return;',
'',
'            container.classList.remove("col", "col-1", "col-2", "col-3", "col-4", "col-5", "col-6",',
'                "col-7", "col-8", "col-9", "col-10", "col-11", "col-12");',
'            slot.appendChild(container);',
'        });',
'    }',
'',
'    function updateEmptySlots() {',
'        document.querySelectorAll(regionSelector + " [data-item-slot]").forEach(function (slot) {',
'            const itemName = slot.dataset.itemSlot;',
'            const itemElement = itemName ? document.getElementById(itemName) : null;',
'            const value = itemElement ? apex.item(itemName).getValue() : slot.textContent;',
'            const isEmpty = value === null || value === undefined || String(value).trim() === "";',
'',
'            slot.classList.toggle("is-empty", isEmpty);',
'            if (slot.parentElement && slot.parentElement.classList.contains("irc-party__document")) {',
'                slot.parentElement.classList.toggle("is-empty", isEmpty);',
'            }',
'        });',
'    }',
'',
'    function errorSet() {',
'        const value = apex.item("P429_ITENS_COM_ERRO").getValue() || "";',
'        return new Set(value.split(":").filter(Boolean));',
'    }',
'',
'    function hasValue(itemName) {',
'        const value = apex.item(itemName).getValue();',
'        return value !== null && value !== undefined && String(value).trim() !== "";',
'    }',
'',
'    function itemValue(itemName) {',
'        if (!itemName || !apex.item(itemName)) return "";',
'        return apex.item(itemName).getValue() || "";',
'    }',
'',
'    function confidenceLabel(score, status) {',
'        const numericScore = Number(score || 0);',
'        const normalizedStatus = String(status || "").toUpperCase();',
'',
unistr('        if (!numericScore) return "N\00E3o encontrado";'),
'        if (normalizedStatus === "CONFIRMADO" || numericScore >= 95) return numericScore + "% Confirmado";',
unistr('        if (normalizedStatus === "ALTA_CONFIANCA" || numericScore >= 70) return numericScore + "% Alta confian\00E7a";'),
'        if (normalizedStatus === "MEDIA_CONFIANCA" || numericScore >= 40) return numericScore + "% Conferir";',
unistr('        return numericScore + "% Baixa confian\00E7a";'),
'    }',
'',
'    function confidenceClass(score, status) {',
'        const numericScore = Number(score || 0);',
'        const normalizedStatus = String(status || "").toUpperCase();',
'',
'        if (!numericScore) return "irc-status--error";',
'        if (normalizedStatus === "CONFIRMADO" || numericScore >= 95) return "irc-status--ok";',
'        if (normalizedStatus === "ALTA_CONFIANCA" || numericScore >= 70) return "irc-status--trust";',
'        if (normalizedStatus === "MEDIA_CONFIANCA" || numericScore >= 40) return "irc-status--review";',
'        return "irc-status--low";',
'    }',
'',
'    function methodLabel(method) {',
'        if (!method) return "";',
'        return String(method).toLowerCase().replace(/_/g, " ");',
'    }',
'',
'    function removeFromErrorList(itemName) {',
'        const errorItem = apex.item("P429_ITENS_COM_ERRO");',
'        const remaining = (errorItem.getValue() || "")',
'            .split(":")',
'            .filter(Boolean)',
'            .filter(function (name) { return name !== itemName; });',
'',
'        errorItem.setValue(remaining.join(":"), null, true);',
'    }',
'',
'    function updateStatus() {',
'        let resolved = 0;',
'        let pending = 0;',
'',
'        document.querySelectorAll(regionSelector + " .irc-row[data-system-item]").forEach(function (row) {',
'            const itemName = row.dataset.systemItem;',
'            const isReview = row.dataset.review === "S";',
'            const score = itemValue(row.dataset.scoreItem);',
'            const confidence = itemValue(row.dataset.statusItem);',
'            const method = itemValue(row.dataset.methodItem);',
'            /*',
'             * P429_ITENS_COM_ERRO representa o resultado inicial da validacao.',
'             * Depois de uma escolha manual, o valor atual do Popup LOV prevalece.',
'             */',
'            const itemHasValue = hasValue(itemName);',
'            const scoreNumber = Number(score || 0);',
'            const useConfidence = !!row.dataset.scoreItem;',
'            const isError = !itemHasValue || (useConfidence && scoreNumber === 0);',
'            const status = row.querySelector(".irc-status");',
'            const message = row.querySelector(".irc-message");',
'',
'            row.classList.toggle("is-error", isError);',
'            row.classList.toggle("is-review", !isError && (isReview || (useConfidence && scoreNumber < 70)));',
'            status.className = "irc-status";',
'',
'            if (useConfidence) {',
'                status.classList.add(confidenceClass(score, confidence));',
'                status.textContent = confidenceLabel(score, confidence);',
'',
'                if (isError) {',
'                    pending += 1;',
'                    message.textContent = "Use a busca para localizar o cadastro correto.";',
'                } else if (isReview || scoreNumber < 70) {',
'                    pending += 1;',
unistr('                    message.textContent = "Confirme a correspond\00EAncia sugerida.";'),
'                } else {',
'                    resolved += 1;',
'                    message.textContent = method ? "Vinculado por " + methodLabel(method) + "." : "Cadastro vinculado.";',
'                }',
'            } else if (isError) {',
'                pending += 1;',
'                status.classList.add("irc-status--error");',
unistr('                status.textContent = "N\00E3o encontrado";'),
'                message.textContent = "Use a busca para localizar o cadastro correto.";',
'            } else if (isReview) {',
'                pending += 1;',
'                status.classList.add("irc-status--review");',
'                status.textContent = "Revisar";',
unistr('                message.textContent = "Confirme a correspond\00EAncia sugerida.";'),
'            } else {',
'                resolved += 1;',
'                status.classList.add("irc-status--ok");',
'                status.textContent = "Encontrado";',
'                message.textContent = "Cadastro vinculado.";',
'            }',
'        });',
'',
'        $("#ircResolvedCount").text(resolved);',
'        $("#ircPendingCount").text(pending);',
'        updateEmptySlots();',
'    }',
'',
'    function bindChanges() {',
'        document.querySelectorAll(regionSelector + " .irc-row[data-system-item]").forEach(function (row) {',
'            const itemName = row.dataset.systemItem;',
'            $(document).off("change.irc", "#" + itemName).on("change.irc", "#" + itemName, function () {',
'                if (hasValue(itemName)) {',
'                    removeFromErrorList(itemName);',
'                    row.dataset.review = "N";',
'                    if (row.dataset.scoreItem && apex.item(row.dataset.scoreItem)) {',
'                        apex.item(row.dataset.scoreItem).setValue("100", null, true);',
'                    }',
'                    if (row.dataset.statusItem && apex.item(row.dataset.statusItem)) {',
'                        apex.item(row.dataset.statusItem).setValue("CONFIRMADO", null, true);',
'                    }',
'                    if (row.dataset.methodItem && apex.item(row.dataset.methodItem)) {',
'                        apex.item(row.dataset.methodItem).setValue("USUARIO", null, true);',
'                    }',
'                }',
'                updateStatus();',
'            });',
'        });',
'    }',
'',
'    function init() {',
'        if (!document.querySelector(regionSelector)) return;',
'        moveItems();',
'        updateEmptySlots();',
'        bindChanges();',
'        updateStatus();',
'    }',
'',
'    window.invoiceReconciliationRegion = { init: init, refresh: init };',
'    $(init);',
'    $(document).on("apexafterrefresh", init);',
'})(apex, apex.jQuery);',
''))
