,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select i.codigo_item',
unistr('       || '' \00B7 '' || substr(i.descricao_item, 1, 80)'),
unistr('       || '' \00B7 NCM '' || n.codigo_ncm'),
