'  from imp_entrega_item ei',
'  join ng_item i',
'    on i.id_tenant = ei.id_tenant',
'   and i.id = ei.id_item',
'  join ng_ncm n',
'    on n.id_tenant = ei.id_tenant',
'   and n.id = ei.id_ncm',
' where ei.id_tenant = :P429_ID_TENANT',
'   and (:ID_ENTREGA is null or ei.id_entrega = :ID_ENTREGA)',
' order by i.codigo_item'))
