wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(225900735893178228)
,p_name=>'P429_ID_PEDIDOIMPORTACAO'
,p_item_sequence=>70
,p_prompt=>unistr('Pedido de importa\00E7\00E3o')
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.numero_pedido_importacao d,',
'       a.id r',
'  from imp_pedidoimportacao a',
' where a.id_tenant = :P429_ID_TENANT',
'   and (',
'         (',
'           :P429_NUM_PEDIDO_IMPORTACAO is not null',
'           and upper(trim(a.numero_pedido_importacao)) like ''%'' || upper(trim(:P429_NUM_PEDIDO_IMPORTACAO)) || ''%''',
'         )',
'      or (',
'           (:P429_ID_IMPORTADOR is not null or :P429_ID_EXPORTADOR is not null)',
'           and (:P429_ID_IMPORTADOR is null or a.id_importador = :P429_ID_IMPORTADOR)',
'           and (:P429_ID_EXPORTADOR is null or a.id_exportador = :P429_ID_EXPORTADOR)',
'         )',
'       )',
' order by d'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_display_when=>'P429_JSON_RETORNADO_API'
,p_display_when_type=>'ITEM_IS_NOT_NULL'
,p_field_template=>wwv_flow_imp.id(529718863311987057)
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--xlarge'
,p_lov_display_extra=>'YES'
