'    p_id_exportador              => :P429_ID_EXPORTADOR,',
'    p_id_importador              => :P429_ID_IMPORTADOR,',
'    p_id_adquirente              => :P429_ID_ADQUIRENTE,',
'    p_id_condicaopagamento       => :P429_ID_CONDICAOPAGAMENTO,',
'    p_id_incoterm                => :P429_ID_INCOTERM,',
'    p_id_moeda                   => :P429_ID_MOEDA,',
'    p_peso_liquido               => :P429_PESO_LIQUIDO,',
'    p_peso_bruto                 => :P429_PESO_BRUTO,',
'    p_valor_total_mercadoria     => :P429_VALOR_MERCADORIA,',
