'    p_valor_invoice_informado    => :P429_VALOR_INVOICE,',
'    p_nome_exportador            => :P429_NOME_EXPORTADOR,',
'    p_doc_exportador             => :P429_DOCUMENTO_EXPORTADOR,',
'    p_nome_importador            => :P429_NOME_IMPORTADOR,',
'    p_doc_importador             => :P429_DOCUMENTO_IMPORTADOR,',
'    p_nome_adquirente            => :P429_NOME_ADQUIRENTE,',
'    p_codigo_incoterm            => :P429_CODIGO_INCOTERM,',
'    p_codigo_moeda               => :P429_CODIGO_MOEDA,',
'    p_desc_condpagto             => :P429_DESC_CONDICAOPAGAMENTO,',
'    p_num_pedido_importacao      => :P429_NUM_PEDIDO_IMPORTACAO,',
'    p_referencia_pedido_original => :P429_REFERENCIA_PEDIDO_ORIGINAL,',
