'',
'  :P429_RESULTADO_IMPORTACAO := l_result;',
'',
'  select json_value(l_result, ''$.status'' returning varchar2(50) null on error),',
'         json_value(l_result, ''$.invoice_id'' returning number null on error)',
'    into l_status,',
'         l_invoice_id',
'    from dual;',
'',
'  :P429_STATUS_IMPORTACAO := l_status;',
'',
'  if l_status = ''IMPORTED'' then',
'',
'    apex_application.g_print_success_message :=',
