'                    unsafe: false',
'                }]);',
'            }',
'        },',
'        error: function() {',
unistr('            console.error("Erro na requisi\00E7\00E3o AJAX");'),
unistr('            apex.item(botaoId).disable(); // Habilita o bot\00E3o'),
'        }',
'    });',
'',
'',
''))
