'',
'const toggleCardBody = (header) => {',
'  const card = header.closest(''.a-CardView'');',
'  if (!card) return;',
'  const body = card.querySelector(''.a-CardView-body'');',
'  if (!body) return;',
'',
'  body.style.display = (body.style.display === ''none'' || !body.style.display) ? ''block'' : ''none'';',
'};',
'',
'(function(){',
'    // Tempo inicial',
'    // console.log(''Log start:''+start);',
'',
unistr('    // Quando a p\00E1gina estiver completamente carregada'),
'    window.addEventListener("load", function(){',
'        var start = window.tempoInicio;',
'        var end = performance.now();',
'        var tempoTotal = Math.round(end - start); // em ms',
'',
'        console.log(''Log end:''+end);',
'        console.log(''Log tempoTotal:''+tempoTotal);',
'',
'        // Envia para o processo Ajax',
'        apex.server.process(',
'            "LOGAR_TEMPO_TELA",',
'            { x01: tempoTotal },',
'            { dataType: "text" }',
'        );',
'    });',
'})();',
'',
'',
'document.querySelectorAll(".progress-bar-cell").forEach(function(el) {',
'  var value = parseFloat(el.dataset.value) || 0;',
'  var total = parseFloat(el.dataset.value1) || 0;',
'  ',
unistr('  // Evita criar barra duplicada (se j\00E1 tiver um SVG dentro, pula)'),
'  if (el.querySelector("svg")) return;',
'',
'  var bar = new ProgressBar.Line(el, {',
'    strokeWidth: 4,',
'    color: ''#4caf50'',',
'    trailColor: ''#eee'',',
'    trailWidth: 4,',
'    svgStyle: {width: ''100%'', height: ''100%''}',
'  });',
'',
unistr('  bar.animate(value / total); // de 0\2013100 para 0\20131'),
'});',
'',
'// Aguarde o carregamento completo',
'window.addEventListener(''load'', function () {',
unistr('  // Finalmente, exibe a p\00E1gina'),
'    document.body.classList.remove(''apex-hide-until-ready'');',
'});',
'',
unistr('//Essa fun\00E7\00E3o verifica se a tela normal esta abrindo dentro de uma modal'),
unistr('//Sendo assim esconde o cabe\00E7alho'),
unistr('//Solu\00E7\00E3o2-'),
unistr('if (window.self === window.top) { // Se N\00C3O for MODAL'),
'    document.body.classList.add(''not-in-iframe'');',
'    apex.item("P9005_TIPO_PESQUISA").setValue(''1'');',
'} else {',
'    $("#BTN_BACK").hide(); // Se for MODAL',
'    $("#BTN_CLOSE").removeClass("u-hidden");    ',
'    apex.item("P9005_TIPO_PESQUISA").setValue(''2'');',
'}',
'',
'$(''#PAINEL_MODAL'')',
'    .closest(''.ui-dialog'')',
'    .find(''.ui-dialog-title'')',
'    .append($(''#BTN_DESFIXAR''));',
'',
'document.addEventListener("DOMContentLoaded", function () {',
'    setTimeout(function () {',
'        var reportTable = document.querySelector("table.a-IRR-table"); // Localiza a tabela do IR',
'        if (reportTable) {',
'            var rows = reportTable.querySelectorAll("tr");',
'            ',
'            rows.forEach(function (row) {',
