,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_sql clob;',
'    l_pagina varchar2(256) := nvl(:P9005_CODIGO_ARTEFATO,''TD367'');',
'begin',
'    EXECUTE IMMEDIATE',
'        ''BEGIN :l_sql := UI_MPD_''||l_pagina||''.sql_cabecalho(:param1,:param2,:param3); END;''',
'        USING OUT l_sql, IN nvl(:P9005_PARAMETRO, 0), nvl(:P9005_PARAMETRO2, 0), :P9005_PARAMETRO3;',
'',
