prompt --application/pages/page_09006
begin
wwv_flow_imp_page.create_page(
 p_id=>9006
,p_name=>'Template - Cards simples'
,p_alias=>'TEMPLATE-CARDS-SIMPLES'
,p_step_title=>'Template - Cards simples'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#APP_FILES#ordenacao#MIN#.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function seleciona(item) {',
'  var id = item.value;',
'',
'  var item = apex.item("P9006_ITENS_SELECIONADOS");',
'  var currentValue = item.getValue(); // string tipo "123,456"',
'',
'  // Transforma em array',
'  var valores = currentValue ? currentValue.split(",") : [];',
'',
'  var index = valores.indexOf(id);',
'  if (index > -1) {',
unistr('    // Remove se j\00E1 existir'),
'    valores.splice(index, 1);',
'  } else {',
unistr('    // Adiciona se n\00E3o existir'),
'    valores.push(id);',
'  }',
'',
'  // Atualiza o item com nova string',
'  item.setValue(valores.join(","));',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.pageSort = SortComponent.create({',
'  columnsItem: ''P9006_SORT_JSON'',',
'  defaultSortItem: ''P9006_SORT_JSON_DEFAULT'',',
'  outputJsonItem: ''P9006_SORT_JSON'',',
'  outputOrderItem: ''P9006_ORDER'',',
'  selectItem: ''P9006_SORT_COLUMN'',',
'  listElementId: ''SORT_LIST'',',
'  viewModeItem: ''P9006_CARD_OU_LISTA'',',
'  cardRegion: ''CARD'',',
'  listRegion: ''LISTA''',
'});',
'',
'',
'$(''.ui-dialog-title'').append($(''#BTN_DESFIXAR''));',
'',
'const toggleCardBody = (header) => {',
'  const card = header.closest(''.a-CardView'');',
'  if (!card) return;',
'  const body = card.querySelector(''.a-CardView-body'');',
'  if (!body) return;',
'',
'  body.style.display = (body.style.display === ''none'' || !body.style.display) ? ''block'' : ''none'';',
'};',
'',
'(function(){',
'    // Tempo inicial',
'    // console.log(''Log start:''+start);',
'',
unistr('    // Quando a p\00E1gina estiver completamente carregada'),
'    window.addEventListener("load", function(){',
'        var start = window.tempoInicio;',
'        var end = performance.now();',
'        var tempoTotal = Math.round(end - start); // em ms',
'',
'        console.log(''Log end:''+end);',
'        console.log(''Log tempoTotal:''+tempoTotal);',
'',
'        // Envia para o processo Ajax',
'        apex.server.process(',
'            "LOGAR_TEMPO_TELA",',
'            { x01: tempoTotal },',
'            { dataType: "text" }',
'        );',
'    });',
'})();',
'',
'',
'document.querySelectorAll(".progress-bar-cell").forEach(function(el) {',
