wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(175464229426892421)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_formato varchar2(3);',
'    l_id number;',
'    l_data_alteracao timestamp;',
'begin    ',
'    begin',
'        select formato into l_formato from mpd_usuario_artefato_formato ',
'        where upper(login) = upper(apex_custom_auth.get_username) ',
'        and upper(codigo_artefato) = upper(:P9006_CODIGO_ARTEFATO)',
'        and aplicacao = apex_application.g_flow_id;',
'        exception',
'            when no_data_found then',
'                l_formato := null;',
'    end;',
'',
'    :P9006_CARD_OU_LISTA := l_formato;',
'    if :P9006_CARD_OU_LISTA is null then',
'        :P9006_CARD_OU_LISTA := ''GRI'';',
'    end if;',
'',
'    PKG_UI.prc_configurar_filtros(',
'        p_id_usuario => :ID_USUARIO_LOGADO ,',
'        p_codigo_artefato => :P9006_CODIGO_ARTEFATO,',
'        p_app_page_id => :app_page_id   ',
'    );',
'',
'    bo_mpd_usuario_artefato_favorito.retorna_registro( ',
'        p_login => upper(apex_custom_auth.get_username),',
'        p_codigo_artefato => :P9006_CODIGO_ARTEFATO,',
'        p_aplicacao => apex_application.g_flow_id,',
'        p_id => l_id,',
'        p_data_alteracao => l_data_alteracao',
'    );    ',
'    if l_id is not null then',
'        :P9006_FAVORITO := 1;',
'    else',
'        :P9006_FAVORITO := 0;',
'    end if;      ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>89768702536227995
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(181788562646139237)
,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load default order'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_order         varchar2(2000);',
'    l_json          clob;',
'    l_pagina        varchar2(256) := nvl(:P9006_CODIGO_ARTEFATO, ''TD150'');',
'    l_card_ou_lista varchar2(10)  := :P9006_CARD_OU_LISTA;',
'begin',
'    l_pagina := upper(trim(l_pagina));',
'',
'    if not regexp_like(l_pagina, ''^[A-Z0-9_]+$'') then',
'        raise_application_error(-20001, ''Codigo de artefato invalido.'');',
'    end if;',
'',
'    execute immediate',
'        ''begin ui_mpd_'' || l_pagina || ''.campos_ordenacao_default(:card_ou_grid, :order, :json); end;''',
'        using in l_card_ou_lista, out l_order, out l_json;',
'',
'    :P9006_ORDER := l_order;',
'    ',
'    exception',
'        when others then',
'            :P9006_ORDER := null;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>181788562646139237
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(211453163819862604)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Verifica auto refresh'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_package varchar2(200);',
'    l_modo    varchar2(30);',
'begin',
'    l_package := ''UI_MPD_'' || :P0_CODIGO_ARTEFATO;',
'',
'    if pkg_ui.existe_funcao_package(',
'        p_package_name  => l_package,',
'        p_function_name => ''SQL_AUTO_REFRESH''',
'    ) then',
'        :P0_AUTO_REFRESH_ATIVO := ''S'';',
'',
'        if pkg_ui.existe_funcao_package(',
'            p_package_name  => l_package,',
'            p_function_name => ''MODO_AUTO_REFRESH''',
'        ) then',
'            execute immediate',
'                ''begin :ret := '' || dbms_assert.simple_sql_name(l_package) || ''.modo_auto_refresh; end;''',
'                using out l_modo;',
'',
'            :P0_AUTO_REFRESH_MODO := upper(nvl(l_modo, ''ONCE''));',
'        else',
'            :P0_AUTO_REFRESH_MODO := ''ONCE'';',
'        end if;',
'',
'    else',
'        :P0_AUTO_REFRESH_ATIVO := ''N'';',
'        :P0_AUTO_REFRESH_MODO  := null;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>211453163819862604
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(175469002265892434)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GETIMAGE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    ',
'',
'    for c1 in (select *',
'               from   MPD_USUARIO',
'               where  id = :P9006_ID) loop',
'        sys.htp.init;',
'        sys.owa_util.Mime_header(c1.foto_mimetype, false);',
'        sys.htp.P(''Content-length: ''|| sys.dbms_lob.Getlength(c1.foto));',
'        sys.htp.P(''Content-Disposition: attachment; filename="''|| c1.foto_name|| ''"'');',
'        sys.htp.P(''Cache-Control: max-age=1'');',
'        sys.owa_util.http_header_close;',
'        sys.wpg_docload.Download_file(c1.foto);',
'        apex_application.stop_apex_engine;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>89773475375228008
);
