wwv_flow_imp_page.create_page(
 p_id=>9007
,p_name=>'Template - Grid selecao'
,p_alias=>'TEMPLATE-GRID-SELECAO'
,p_step_title=>'Template - Grid selecao'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function seleciona(item) {',
'  var id = item.value;',
'',
'  var item = apex.item("P9007_ITENS_SELECIONADOS");',
'  var currentValue = item.getValue(); // string tipo "123,456"',
'',
'  // Transforma em array',
unistr('  var valores = currentValue ? currentValue.split("||''_''||") : []; // L\00E9o(31/07/25) \00DAnico separador que funcionou (||''||''||)'),
'',
'  var index = valores.indexOf(id);',
'  if (index > -1) {',
unistr('    // Remove se j\00E1 existir'),
'    valores.splice(index, 1);',
'  } else {',
unistr('    // Adiciona se n\00E3o existir'),
'    valores.push(id);',
'  }',
'',
'  // Atualiza o item com nova string',
'    item.setValue(valores.join("||''_''||"));',
'    $s("P9007_ITENS_SELECIONADOS", valores.join("||''_''||"));',
'',
'    apex.server.process(',
'    "SETITEM", // Nome do processo PL/SQL definido no APEX',
'    {',
'      x01: apex.item("P9007_ITENS_SELECIONADOS").getValue()',
'',
'    },',
'    {',
'      dataType: ''text'',',
'      success: function(pData) {',
'        console.log("SETITEM com sucesso:", pData);',
'      }',
'    }',
'  );',
'',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
' $(''.ui-dialog-title'').append($(''#BTN_DESFIXAR''));',
'',
'document.addEventListener("DOMContentLoaded", function () {',
'    setTimeout(function () {',
'        var reportTable = document.querySelector("table.a-IRR-table"); // Localiza a tabela do IR',
'        if (reportTable) {',
'            var rows = reportTable.querySelectorAll("tr");',
'            ',
'            rows.forEach(function (row) {',
'                var cells = row.children;',
'                if (cells.length > 2) { ',
unistr('                    row.insertBefore(cells[2], cells[0]); // Move a terceira coluna para a primeira posi\00E7\00E3o'),
'                }',
'            });',
'        }',
unistr('    }, 1000); // Aguarda o carregamento do relat\00F3rio'),
'});',
'',
'// $(document).on(''click'', ''#checkAll'', function () {',
'//     $(''input:checkbox'').prop(''checked'', this.checked);',
'//     seleciona($(''input:checkbox''));',
'// });',
'',
'$(document).on(''click'', ''#checkAll'', function () {',
'  const check = this.checked;',
'',
'  $(''input[name="f01"]'').each(function () {',
unistr('    // S\00F3 atualiza se o estado for diferente (evita repeti\00E7\00E3o desnecess\00E1ria)'),
'    if (this.checked !== check) {',
'      this.checked = check;',
'      seleciona(this);',
'    }',
'  });',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
