wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(156316023350186931)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_prefixo_itens varchar2(32);',
'    l_label_confirmar varchar2(2000);',
'    l_label_senha_incorreta varchar2(2000);',
'    l_label_confirmar_simples_l varchar2(2000);',
'    l_label_confirmar_simples_i varchar2(2000);',
'    l_label_confirmar_simples_h varchar2(2000);',
'    l_label_confirmar_senha_l varchar2(2000);',
'    l_label_confirmar_senha_i varchar2(2000);',
'    l_label_confirmar_senha_h varchar2(2000);',
'    l_label_mensagem_confirmacao varchar2(2000);',
'    l_tipo_confirmacao number;',
'begin',
'    l_prefixo_itens := ''P'' || :app_page_id  ;',
'    select pkg_ui.retorna_label_botao(''senha-incorreta'') into l_label_senha_incorreta from dual;',
'    ',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_SENHA_INCORRETA'', l_label_senha_incorreta);',
'',
'    pkg_ui.retorna_label_tela(''confirmar-simples'',l_label_confirmar_simples_l,l_label_confirmar_simples_i,l_label_confirmar_simples_h);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_CONFIRMAR_SIMPLES_L'', l_label_confirmar_simples_l);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_CONFIRMAR_SIMPLES_I'', l_label_confirmar_simples_i);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_CONFIRMAR_SIMPLES_H'', l_label_confirmar_simples_h);',
'',
'    pkg_ui.retorna_label_tela(''confirmar-senha'',l_label_confirmar_senha_l,l_label_confirmar_senha_i,l_label_confirmar_senha_h);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_CONFIRMAR_SENHA_L'', l_label_confirmar_senha_l);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_CONFIRMAR_SENHA_I'', l_label_confirmar_senha_i);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_CONFIRMAR_SENHA_H'', l_label_confirmar_senha_h);',
'',
'    select nvl(tipo_confirmacao,0), pkg_ui.retorna_label_tela(tag_mensagem_confirmacao) ',
'    into l_tipo_confirmacao, l_label_mensagem_confirmacao',
'    from mpd_funcionalidade_tela_dinamica a',
'    join mpd_funcionalidade b on b.id = a.id_funcionalidade',
'    where upper(codigo_artefato) = upper(:P9010_CODIGO_ARTEFATO);',
'',
'    apex_util.set_session_state(l_prefixo_itens || ''_TIPO_CONFIRMACAO'', l_tipo_confirmacao);',
'    apex_util.set_session_state(l_prefixo_itens || ''_LABEL_MENSAGEM_CONFIRMAR'', l_label_mensagem_confirmacao);',
'',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>49401252216725607
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(214111793637297201)
,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Verifica auto refresh'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_package varchar2(200);',
'    l_modo    varchar2(30);',
'begin',
'    l_package := ''UI_MPD_'' || :P0_CODIGO_ARTEFATO;',
'',
'    if pkg_ui.existe_funcao_package(',
'        p_package_name  => l_package,',
'        p_function_name => ''SQL_AUTO_REFRESH''',
'    ) then',
'        :P0_AUTO_REFRESH_ATIVO := ''S'';',
'',
'        if pkg_ui.existe_funcao_package(',
'            p_package_name  => l_package,',
'            p_function_name => ''MODO_AUTO_REFRESH''',
'        ) then',
'            execute immediate',
'                ''begin :ret := '' || dbms_assert.simple_sql_name(l_package) || ''.modo_auto_refresh; end;''',
'                using out l_modo;',
'',
'            :P0_AUTO_REFRESH_MODO := upper(nvl(l_modo, ''ONCE''));',
'        else',
'            :P0_AUTO_REFRESH_MODO := ''ONCE'';',
'        end if;',
'',
'    else',
'        :P0_AUTO_REFRESH_ATIVO := ''N'';',
'        :P0_AUTO_REFRESH_MODO  := null;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>214111793637297201
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(190291804237165499)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'enviarParamentros'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_param1 varchar2(100) := upper(apex_application.g_x01) || ''_'' || apex_custom_auth.get_session_id;',
'    v_param2 varchar2(100) := apex_application.g_x02;',
'    v_param3 varchar2(4000) := apex_application.g_x03;',
'    v_param4 varchar2(4000) := apex_application.g_x04;',
'',
'    v_seq_id number;',
'begin',
'    if apex_application.g_x01 is not null then',
'',
'        if upper(v_param2) = upper(''id_tenant'') and :P9010_ID is null then',
'            :P0_TENANT_INFORMADO := v_param3;',
'        end if;',
'',
'        if not apex_collection.collection_exists(v_param1) then',
'            apex_collection.create_collection(v_param1);',
'        end if;',
'',
'        begin',
'            select seq_id',
'              into v_seq_id',
'              from apex_collections',
'             where collection_name = v_param1',
'               and upper(c001) = upper(v_param2)',
'               and rownum = 1;',
'',
'            apex_collection.update_member(',
'                p_collection_name => v_param1,',
'                p_seq             => v_seq_id,',
'                p_c001            => v_param2,',
'                p_c002            => v_param3,',
'                p_c003            => v_param4',
'            );',
'',
'        exception',
'            when no_data_found then',
'                apex_collection.add_member(',
'                    p_collection_name => v_param1,',
'                    p_c001            => v_param2,',
'                    p_c002            => v_param3,',
'                    p_c003            => v_param4',
'                );',
'        end;',
'',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', true);',
'    apex_json.write(''collection_name'', v_param1);',
'    apex_json.write(''campo'', v_param2);',
'    apex_json.write(''valor'', v_param3);',
'    apex_json.write(''valor_hidden'', v_param4);',
'    apex_json.close_object;',
'',
'exception',
'    when others then',
'        apex_json.open_object;',
'        apex_json.write(''success'', false);',
'        apex_json.write(''message'', sqlerrm);',
'        apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>44585403008377017
);
