 p_id=>wwv_flow_imp.id(167337776461768029)
,p_event_id=>wwv_flow_imp.id(162398933558956651)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//async function getData() {',
'//let afetch await fetch(''https://geae26552a5af32-dbng.adb.sa-vinhedo-1.oraclecloudapps.com/ords/teste/demopdfviewer/examplepdf/'' + $v("P9011_ID"));',
'//let blob await afetch.blob();',
'//let blobUrl = URL.createObjectURL(blob);',
'//let pdfContainer = document.getElementById(''pdfViewer'');',
'//pdfContainer.getElementsByTagName(''iframe'')[0].src = blobUrl;}',
'//getData();',
'',
'',
'(async function() {',
'  try {',
'    var region = $("#painelpdfViewer");',
'    const id = $v("P9011_ID");',
'    const url = ''https://geae26552a5af32-dbng.adb.sa-vinhedo-1.oraclecloudapps.com/ords/teste/demopdfviewer/examplepdf/'' + id;',
'',
'    const response = await fetch(url, { credentials: ''include'' });',
'',
'    if (!response.ok) {',
'      throw new Error(''Erro ao buscar arquivo: '' + response.statusText);',
'    }',
'',
unistr('    // \2705 Verifica o tipo MIME retornado'),
'    const contentType = response.headers.get(''Content-Type'');',
'',
unistr('    // Se n\00E3o for PDF, n\00E3o abre a regi\00E3o'),
'    if (!contentType || !contentType.includes(''pdf'')) {',
unistr('      // Esconde a regi\00E3o do APEX'),
'      region.hide();',
'',
unistr('      // (opcional) Exibe alerta ao usu\00E1rio'),
'      return;',
'    }',
'',
unistr('    // Caso seja PDF, exibe a regi\00E3o e mostra o conte\00FAdo'),
'    const blob = await response.blob();',
'    const blobUrl = URL.createObjectURL(blob);',
'',
'    const pdfContainer = document.getElementById(''pdfViewer'');',
'    let iframe = pdfContainer.querySelector(''iframe'');',
'',
'    if (!iframe) {',
'      iframe = document.createElement(''iframe'');',
'      iframe.style.width = "100%";',
'      iframe.style.height = "800px";',
'      pdfContainer.appendChild(iframe);',
'    }',
'',
'    iframe.src = blobUrl;',
'',
unistr('    // \2705 Mostra a regi\00E3o do APEX (caso estivesse oculta)'),
'    region.show();',
'',
'  } catch (e) {',
'    console.error(''Erro ao carregar PDF:'', e);',
'    apex.message.alert("Erro ao carregar PDF: " + e.message);',
'  }',
'})();',
''))
,p_server_condition_type=>'ITEM_IS_NOT_NULL'
,p_server_condition_expr1=>'P9011_ID'
);
