prompt --application/deployment/install/install_pkg_mensagem
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(184981467485878779)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'PKG_MENSAGEM'
,p_sequence=>9
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "PKG_MENSAGEM" as',
'',
'    -- Definir o tipo de registro',
'    TYPE message_record IS RECORD (',
'        mensagem VARCHAR2(4000),',
'        instrucao VARCHAR2(4000),',
'        help VARCHAR2(4000),',
'        local_exibicao VARCHAR2(100),',
'        nome_item VARCHAR2(100),',
'        tipo VARCHAR2(2)',
'    );',
'    ',
unistr('    -- Definir a cole\00E7\00E3o para armazenar os registros'),
'    TYPE message_record_table IS TABLE OF message_record;  ',
'    type paramentros is table of varchar2(4000) index by pls_integer;  ',
'    v_parametro paramentros;',
'',
'    v_messages message_record_table;',
'    v_message message_record;',
'',
'    c_tag_concatena constant varchar2(50) := ''[CONCATENA_TEXTO]'';',
'    c_tag_nao_fechar constant varchar2(50) := ''[NAO_AUTO_FECHAR]'';  ',
'',
'    c_tipo_alerta constant number := 1;',
'    c_tipo_informacao constant number := 2;',
'    c_tipo_pergunta constant number := 3;',
'',
'    c_operacao_sucesso_incluir constant number := 1;',
'    c_operacao_sucesso_alterar constant number := 2;',
'    c_operacao_sucesso_excluir constant number := 3;',
'',
'    c_operacao_erro_incluir constant number := 4;',
'    c_operacao_erro_alterar constant number := 5;',
'    c_operacao_erro_excluir constant number := 6;',
'',
'    c_operacao_erro_id constant number := 7;',
'    c_operacao_erro_data_alteracao constant number := 8;',
'    c_operacao_sucesso_acao constant number := 9;',
'    c_operacao_erro_acao constant number := 10;',
'    c_operacao_erro_dependencia constant number := 11;',
'',
'    c_codigo_mensagem_sucesso_incluir constant varchar2(32) := 3;',
'    c_codigo_mensagem_sucesso_alterar constant varchar2(32) := 4;',
'    c_codigo_mensagem_sucesso_excluir constant varchar2(32) := 5;',
'',
'    c_codigo_mensagem_erro_incluir constant varchar2(32) := 6;',
'    c_codigo_mensagem_erro_alterar constant varchar2(32) := 7;',
'    c_codigo_mensagem_erro_excluir constant varchar2(32) := 8;',
'',
'    c_codigo_mensagem_erro_id constant varchar2(32) := 9;',
'    c_codigo_mensagem_erro_data_alteracao constant varchar2(32) := 10;',
'    c_codigo_mensagem_sucesso_acao constant varchar2(32) := 1;',
'    c_codigo_mensagem_erro_acao constant varchar2(32) := 2;',
'    c_codigo_mensagem_erro_dependencia constant varchar2(32) := 30;    ',
'',
'    c_tipo_mensagem_erro constant clob := ''<style>.a-Button--notification{display: none;} .t-Form-error{color: var(--ut-palette-danger);}</style>'';',
'    -- c_tipo_mensagem_erro constant clob := ''<style>.a-Button--notification{display: none;} .t-Alert--warning{background-color: var(--ut-palette-danger);}.t-Form-error{color: var(--ut-palette-danger);}</style>'';',
'    c_tipo_mensagem_alerta constant clob := ''<style>.a-Button--notification{display: none;} .t-Alert--warning{background-color: var(--ut-palette-warning);}.t-Form-error{color: var(--ut-palette-warning);}</style>'';',
'    c_tipo_mensagem_informacao constant clob := ''<style>.a-Button--notification{display: none;}.t-Alert--warning{background-color: var(--ut-palette-primary-alt);}.t-Form-error{color: var(--ut-palette-primary-alt);}</style>'';',
'    c_tipo_mensagem_questionamento constant clob := ''<style>.a-Button--notification{display: none;} .t-Alert--warning{background-color: var(--ut-palette-info);}.t-Form-error{color: var(--ut-palette-info);}</style>'';',
'',
'    c_texto constant clob := ''<details><summary style="font-weight: bold; outline: none; overflow: hidden; cursor: pointer;">#MENSAGEM#<span class="a-Icon icon-info"style="padding-left: 2px;"></span></summary><div><p style="color: inherit;margin-bott'
||'om: 10px;">#help#</p></div></details>'';   ',
'    c_texto_com_instrucao constant clob := ''<details><summary style="font-weight: bold; outline: none; overflow: hidden; cursor: pointer;">#MENSAGEM#<span class="a-Icon icon-info"style="padding-left: 2px;"></span></summary><div><p style="color: inher'
||unistr('it;margin-bottom: 10px;">#help#</p><div style="color: inherit;"><b>Instru\00E7\00E3o interna</b></div><p style="color: inherit;">#instrucao#</p></div></details>'';   '),
'',
'    procedure exibe_mensagem(',
