'        p_operacao number',
'    ) return varchar2;',
'',
'    function retorna_item_pagina(',
'        p_nome_campo varchar2,',
'        p_pagina number',
'    ) return varchar2;',
'',
'    procedure modelo_mensagem(',
'        p_nome_campo varchar2 default null,',
'        p_pagina number default null,',
'        p_nome_item out varchar2,',
'        p_local_exibicao out varchar2',
'    );    ',
'',
'    function substitui_paramentro(',
'        p_mensagem varchar2,',
'        p_parametro paramentros',
'    ) return varchar2;   ',
'',
'    procedure retorna_mensagem (',
'        p_codigo_mensagem in varchar2,',
'        p_mensagem        out mpd_traducao.texto_traduzido%type,',
'        p_instrucao       out mpd_traducao.texto_traduzido%type,',
'        p_help            out mpd_traducao.texto_traduzido%type',
'    );',
'',
'    function tag_mensagem(',
'        p_mensagem        in clob,',
'        p_concatena_texto in boolean default true,',
'        p_nao_auto_fechar in boolean default true',
'    ) return clob;    ',
'',
'end "PKG_MENSAGEM";',
'/',
'create or replace package body "PKG_MENSAGEM" as',
'    -- apex_debug.error(''mensagem_campo_obrigatorio p_nome_campo:%s'',p_nome_campo); ',
unistr('    -- Exibe a modal de erro de uma forma customizada. Por exemplo, a modal ser\00E1 azul caso tipo de mensagem seja informa\00E7\00E3o.'),
'    procedure exibe_mensagem(',
'        p_tabela_mensagem in message_record_table,',
'        p_api boolean default false',
'    ) is',
'        l_HTML CLOB;',
'        l_msg_final varchar2(4000);',
'    begin   ',
'        for i in p_tabela_mensagem.first .. p_tabela_mensagem.last loop        ',
'',
'            if BO_MPD_USUARIO.usuario_administrador then',
'                l_HTML := replace(c_texto_com_instrucao,''#MENSAGEM#'',p_tabela_mensagem(i).mensagem);',
'                l_HTML := replace(l_HTML,''#instrucao#'',p_tabela_mensagem(i).instrucao);',
'            else',
'                l_HTML := replace(c_texto,''#MENSAGEM#'',p_tabela_mensagem(i).mensagem);',
'            end if;',
'            ',
'            l_HTML := replace(l_HTML,''#help#'',p_tabela_mensagem(i).help);            ',
'            l_msg_final := retorna_tipo_mensagem(p_tabela_mensagem(i).tipo) || l_HTML;',
'            ',
'            if p_api then',
'                null;',
'            elsif not executando_em_apex then',
'                raise_application_error(',
'                    -20101,',
'                    substr(l_msg_final, 1, 2000)',
'                );',
'            else',
'                if p_tabela_mensagem(i).local_exibicao = apex_error.c_inline_in_notification then',
'                    apex_error.add_error(',
'                        p_message          => l_msg_final,',
'                        p_display_location => p_tabela_mensagem(i).local_exibicao',
'                    );',
'                else',
'                    apex_error.add_error(',
'                        p_message          => l_msg_final,',
'                        p_display_location => p_tabela_mensagem(i).local_exibicao,',
'                        p_page_item_name   => p_tabela_mensagem(i).nome_item',
'                    );',
'                end if;',
'                rollback;',
'            end if;  ',
'        end loop;',
'    end exibe_mensagem;',
'',
unistr('    -- Retorna a mensagem e a help dentro do HTML para ser usada em modais de alerta e confirma\00E7\00E3o do APEX.'),
'    procedure mensagem(',
'        p_codigo_mensagem in varchar2,',
'        p_parametro in paramentros,',
'        p_mensagem_html out clob',
'    )is     ',
'        l_mensagem clob; ',
'        l_instrucao clob; ',
'        l_help clob; ',
'    begin   ',
'        -- select mensagem, help into l_mensagem, l_help from srv_aplicacao_mensagem where lower(codigo_mensagem) = lower(p_codigo_mensagem); ',
'        retorna_mensagem(p_codigo_mensagem,l_mensagem,l_instrucao,l_help);',
'        l_mensagem := substitui_paramentro(l_mensagem,p_parametro); ',
'        l_instrucao := substitui_paramentro(l_instrucao,p_parametro); ',
'        l_help := substitui_paramentro(l_help,p_parametro); ',
'        p_mensagem_html := replace(c_texto,''#MENSAGEM#'',l_mensagem);',
'        p_mensagem_html := replace(p_mensagem_html,''#instrucao#'',l_instrucao);',
'        p_mensagem_html := replace(p_mensagem_html,''#help#'',l_help);',
'        exception            ',
'            when others THEN',
unistr('                raise_application_error(-20111,''Erro na fun\00E7\00E3o pkg_mensagem.mensagem para codigo_mensagem: '' ||p_codigo_mensagem ||'' para o erro :''||sqlerrm);'),
'',
'    end mensagem;    ',
'',
'    procedure mensagem_original(',
'        p_codigo_mensagem in varchar2,',
'        p_parametro in paramentros,',
'        p_mensagem out clob',
'    )is     ',
'        l_mensagem clob; ',
'        l_instrucao clob; ',
'        l_help clob; ',
'    begin   ',
'        -- select mensagem, help into l_mensagem, l_help from srv_aplicacao_mensagem where lower(codigo_mensagem) = lower(p_codigo_mensagem); ',
'        retorna_mensagem(p_codigo_mensagem,l_mensagem,l_instrucao,l_help);',
'        l_mensagem := substitui_paramentro(l_mensagem,p_parametro); ',
'        l_instrucao := substitui_paramentro(l_instrucao,p_parametro); ',
'        l_help := substitui_paramentro(l_help,p_parametro); ',
'       ',
'        p_mensagem :=',
'            l_mensagem ||',
'            case ',
unistr('                when  instr(l_instrucao, ''Texto indispon\00EDvel tag'') = 0 then'),
'                    chr(10) || l_instrucao',
'                else',
'                    null',
'            end       || ',
'            case ',
unistr('                when instr(l_help, ''Texto indispon\00EDvel tag'') = 0 then'),
'                    chr(10) || l_help',
'                else',
'                    null',
'            end;',
'',
'        exception            ',
'            when others THEN',
unistr('                raise_application_error(-20111,''Erro na fun\00E7\00E3o pkg_mensagem.mensagem para codigo_mensagem: '' ||p_codigo_mensagem ||'' para o erro :''||sqlerrm);'),
'',
'    end mensagem_original;  ',
'',
unistr('    -- Retorna apenas a mensagem e a help em variaives de texto separadas puramente, neste caso n\00E3o realiza a substitui\00E7\00E3o dos paramentros'),
'    procedure mensagem_operacao(',
'        p_operacao in number,',
'        p_parametro in paramentros,',
'        p_mensagem in out varchar2',
'    )is       ',
'        l_codigo_mensagem varchar2(32);',
'        l_instrucao       clob;',
'        l_help            clob;',
'        l_mensagem_antiga clob;',
'        l_mensagem_padrao clob;',
'        l_concatena       boolean := false;',
'    begin   ',
'        l_mensagem_antiga := p_mensagem;',
'',
'        l_codigo_mensagem := retorna_operacao_mensagem(p_operacao);',
'',
'        retorna_mensagem(',
'            l_codigo_mensagem,',
'            l_mensagem_padrao,',
'            l_instrucao,',
'            l_help',
'        );',
'',
'        l_mensagem_padrao := substitui_paramentro(l_mensagem_padrao, p_parametro);',
'',
'        if l_mensagem_antiga is not null then',
'            if instr(l_mensagem_antiga, c_tag_concatena) > 0 then',
'                l_concatena := true;',
'',
'                l_mensagem_antiga :=',
'                    replace(l_mensagem_antiga, c_tag_concatena, null);',
'',
'                l_mensagem_antiga := trim(l_mensagem_antiga);',
'            end if;',
'        end if;',
'',
'        if l_concatena and l_mensagem_antiga is not null then',
'            p_mensagem := l_mensagem_padrao || chr(10) || l_mensagem_antiga;',
'        else',
'            p_mensagem := l_mensagem_padrao;',
'        end if;',
'',
'    exception            ',
'        when others then',
'            raise_application_error(',
'                -20111,',
unistr('                ''Erro na fun\00E7\00E3o pkg_mensagem.mensagem_operacao para codigo_mensagem: '' ||'),
'                l_codigo_mensagem ||',
'                '' para o erro: '' ||',
'                sqlerrm',
'            );',
'    end mensagem_operacao;',
'',
'    procedure mensagem_operacao(',
'        p_operacao in number,',
'        p_parametro in paramentros,',
'        p_objeto_mensagem out message_record',
'    )is       ',
'        l_codigo_mensagem varchar2(32);',
'    begin   ',
'        p_objeto_mensagem.local_exibicao := apex_error.c_inline_in_notification;',
'        l_codigo_mensagem := retorna_operacao_mensagem(p_operacao);',
'        retorna_mensagem(l_codigo_mensagem,p_objeto_mensagem.mensagem,p_objeto_mensagem.instrucao,p_objeto_mensagem.help);',
'        p_objeto_mensagem.mensagem := substitui_paramentro(p_objeto_mensagem.mensagem,p_parametro); ',
'        p_objeto_mensagem.instrucao := substitui_paramentro(p_objeto_mensagem.instrucao,p_parametro); ',
'        p_objeto_mensagem.help := substitui_paramentro(p_objeto_mensagem.help,p_parametro);                 ',
'        exception            ',
'            when others THEN',
unistr('                raise_application_error(-20111,''Erro na fun\00E7\00E3o pkg_mensagem.mensagem_operacao assinatura 2 para codigo_mensagem: '' ||l_codigo_mensagem ||'' para o erro :''||sqlerrm);'),
'',
'    end mensagem_operacao; ',
'',
'',
'    procedure titulo_notificao(',
'        p_alerta_ou_notificacao in number,',
'        p_parametro in paramentros,',
'        p_titulo out clob',
'    )is',
'        l_codigo_mensagem varchar2(32); ',
'        l_mensagem clob; ',
'        l_instrucao clob; ',
'        l_help clob; ',
'    begin',
'        if p_alerta_ou_notificacao = c_tipo_alerta then',
'            l_codigo_mensagem := ''12'';',
'        elsif p_alerta_ou_notificacao = c_tipo_informacao then   ',
'            l_codigo_mensagem := ''13'';',
'        elsif p_alerta_ou_notificacao = c_tipo_pergunta then     ',
'            l_codigo_mensagem := '''';',
'        end if;',
'',
'        retorna_mensagem(l_codigo_mensagem,l_mensagem,l_instrucao,l_help);',
'        p_titulo := substitui_paramentro(l_mensagem,p_parametro); ',
'        exception            ',
'            when others THEN',
unistr('                raise_application_error(-20111,''Erro na fun\00E7\00E3o pkg_mensagem.titulo_notificao para codigo_mensagem: '' ||l_codigo_mensagem ||'' para o erro :''||sqlerrm);'),
'',
'    end titulo_notificao;',
'',
unistr('    -- Retorna o objeto mensagem com todos os campos preechidos para uma notifica\00E7\00E3o no campo'),
'    procedure mensagem_campo(',
'        p_codigo_mensagem in varchar2,',
'        p_nome_campo in varchar2,',
'        p_parametro in paramentros,',
'        p_pagina in number,',
'        p_objeto_mensagem out message_record',
'    )is',
'    begin',
'        modelo_mensagem(p_nome_campo,p_pagina,p_objeto_mensagem.nome_item,p_objeto_mensagem.local_exibicao);',
'        p_objeto_mensagem.tipo := 1;',
'        retorna_mensagem(p_codigo_mensagem,p_objeto_mensagem.mensagem,p_objeto_mensagem.instrucao,p_objeto_mensagem.help);',
'        p_objeto_mensagem.mensagem := substitui_paramentro(p_objeto_mensagem.mensagem,p_parametro);         ',
'        p_objeto_mensagem.instrucao := substitui_paramentro(p_objeto_mensagem.instrucao,p_parametro);         ',
'        p_objeto_mensagem.help := substitui_paramentro(p_objeto_mensagem.help,p_parametro);                 ',
'        -- exception            ',
'        --     when others THEN',
unistr('        --         raise_application_error(-20111,''Erro na fun\00E7\00E3o pkg_mensagem.mensagem_campo para codigo_mensagem: '' ||p_codigo_mensagem ||'' para o erro :''||sqlerrm);'),
'',
'    end mensagem_campo;',
'',
'    procedure mensagem_campo_obrigatorio(',
'        p_codigo_mensagem in varchar2 default ''11'',',
'        p_nome_campo in varchar2,',
'        p_parametro in paramentros,',
'        p_pagina in number,',
'        p_objeto_mensagem out message_record',
'    )is',
'    begin',
'        modelo_mensagem(p_nome_campo,p_pagina,p_objeto_mensagem.nome_item,p_objeto_mensagem.local_exibicao);',
'        p_objeto_mensagem.tipo := 1;',
'        retorna_mensagem(p_codigo_mensagem,p_objeto_mensagem.mensagem,p_objeto_mensagem.instrucao,p_objeto_mensagem.help);',
'        p_objeto_mensagem.mensagem := substitui_paramentro(p_objeto_mensagem.mensagem,p_parametro);                 ',
'        p_objeto_mensagem.instrucao := substitui_paramentro(p_objeto_mensagem.instrucao,p_parametro);                 ',
'        p_objeto_mensagem.help := substitui_paramentro(p_objeto_mensagem.help,p_parametro);                                 ',
'    end mensagem_campo_obrigatorio;',
'',
'    procedure mensagem_cadastro(',
'        p_codigo_mensagem in varchar2 default ''42'',',
'        p_nome_campo in varchar2,',
'        p_parametro in paramentros,',
'        p_pagina in number,',
'        p_objeto_mensagem out message_record',
'    )is',
'    begin',
'        modelo_mensagem(p_nome_campo,p_pagina,p_objeto_mensagem.nome_item,p_objeto_mensagem.local_exibicao);',
'        p_objeto_mensagem.tipo := 1;',
'        retorna_mensagem(p_codigo_mensagem,p_objeto_mensagem.mensagem,p_objeto_mensagem.instrucao,p_objeto_mensagem.help);',
'        p_objeto_mensagem.mensagem := substitui_paramentro(p_objeto_mensagem.mensagem,p_parametro);                 ',
'        p_objeto_mensagem.instrucao := substitui_paramentro(p_objeto_mensagem.instrucao,p_parametro);                 ',
'        p_objeto_mensagem.help := substitui_paramentro(p_objeto_mensagem.help,p_parametro);                                 ',
'    end mensagem_cadastro;',
'',
'    procedure mensagem_dominio(',
'        p_codigo_mensagem in varchar2 default ''41'',',
'        p_nome_campo in varchar2,',
'        p_parametro in paramentros,',
'        p_pagina in number,',
'        p_objeto_mensagem out message_record',
'    )is',
'    begin',
'        modelo_mensagem(p_nome_campo,p_pagina,p_objeto_mensagem.nome_item,p_objeto_mensagem.local_exibicao);',
'        p_objeto_mensagem.tipo := 1;',
'        retorna_mensagem(p_codigo_mensagem,p_objeto_mensagem.mensagem,p_objeto_mensagem.instrucao,p_objeto_mensagem.help);',
'        p_objeto_mensagem.mensagem := substitui_paramentro(p_objeto_mensagem.mensagem,p_parametro);                 ',
'        p_objeto_mensagem.instrucao := substitui_paramentro(p_objeto_mensagem.instrucao,p_parametro);                 ',
'        p_objeto_mensagem.help := substitui_paramentro(p_objeto_mensagem.help,p_parametro);                                 ',
'    end mensagem_dominio;',
'',
'    procedure mensagem_campo_unico(',
'        p_codigo_mensagem in varchar2 default ''16'',',
'        p_nome_campo in varchar2,',
'        p_parametro in paramentros,',
'        p_pagina in number,',
'        p_objeto_mensagem out message_record',
'    )is',
'    begin',
'        modelo_mensagem(p_nome_campo,p_pagina,p_objeto_mensagem.nome_item,p_objeto_mensagem.local_exibicao);',
'        p_objeto_mensagem.tipo := 1;',
'        retorna_mensagem(p_codigo_mensagem,p_objeto_mensagem.mensagem,p_objeto_mensagem.instrucao,p_objeto_mensagem.help);',
'        p_objeto_mensagem.mensagem := substitui_paramentro(p_objeto_mensagem.mensagem,p_parametro);                 ',
'        p_objeto_mensagem.instrucao := substitui_paramentro(p_objeto_mensagem.instrucao,p_parametro);                 ',
'        p_objeto_mensagem.help := substitui_paramentro(p_objeto_mensagem.help,p_parametro);                                 ',
'    end mensagem_campo_unico;    ',
'',
'    procedure modelo_mensagem(',
'        p_nome_campo varchar2 default null,',
'        p_pagina number default null,',
'        p_nome_item out varchar2,',
'        p_local_exibicao out varchar2',
'    )is',
'    begin',
'        -- Se a pagina e o nome do campo foram informados,',
unistr('        -- ent\00E3o a fun\00E7\00E3o vai procurar pelo item da pagina para fazer referencia'),
unistr('        -- caso contr\00E1rio a mensagem ser\00E1 exibida apenas no topo da tela'),
'        if p_pagina is not null and p_nome_campo is not null then',
'            p_nome_item := retorna_item_pagina(p_nome_campo,p_pagina);',
'            if p_nome_item is not null then',
'                p_local_exibicao := apex_error.c_inline_with_field; ',
'            else',
'                p_local_exibicao := apex_error.c_inline_in_notification;',
'            end if;',
'        else          ',
'            p_local_exibicao := apex_error.c_inline_in_notification;',
'        end if;  ',
'    end modelo_mensagem;',
'',
'    function retorna_tipo_mensagem(',
'        p_tipo in number default 1 ',
'    ) return varchar2 is',
'        l_resultado clob;',
'        l_tipo number;',
'    begin',
'        if p_tipo is null then',
'            l_tipo := 1;',
'        else',
'            l_tipo := p_tipo;    ',
'        end if;    ',
'        case l_tipo ',
'            when 1 then l_resultado := c_tipo_mensagem_erro;',
'            when 2 then l_resultado := c_tipo_mensagem_alerta;',
'            when 3 then l_resultado := c_tipo_mensagem_informacao;',
'            when 4 then l_resultado := c_tipo_mensagem_questionamento;',
'        end case;',
'        return l_resultado;    ',
'    end retorna_tipo_mensagem;    ',
'',
'    function retorna_operacao_mensagem(',
'        p_operacao in number',
'    ) return varchar2 is',
'        l_resultado varchar2(32);',
'    begin',
'        case p_operacao ',
'            when c_operacao_sucesso_incluir then l_resultado := c_codigo_mensagem_sucesso_incluir;',
'            when c_operacao_sucesso_alterar then l_resultado := c_codigo_mensagem_sucesso_alterar;',
'            when c_operacao_sucesso_excluir then l_resultado := c_codigo_mensagem_sucesso_excluir;',
'            when c_operacao_erro_incluir then l_resultado := c_codigo_mensagem_erro_incluir;',
'            when c_operacao_erro_alterar then l_resultado := c_codigo_mensagem_erro_alterar;',
'            when c_operacao_erro_excluir then l_resultado := c_codigo_mensagem_erro_excluir;',
'            when c_operacao_erro_id then l_resultado := c_codigo_mensagem_erro_id;',
'            when c_operacao_erro_data_alteracao then l_resultado := c_codigo_mensagem_erro_data_alteracao;',
'            when c_operacao_sucesso_acao then l_resultado := c_codigo_mensagem_sucesso_acao;',
'            when c_operacao_erro_acao then l_resultado := c_codigo_mensagem_erro_acao;',
'            when c_operacao_erro_dependencia then l_resultado := c_codigo_mensagem_erro_dependencia;            ',
'        end case;',
'        return l_resultado;    ',
'    end retorna_operacao_mensagem;    ',
'',
'    function retorna_item_pagina(',
'        p_nome_campo varchar2,',
'        p_pagina number',
'    ) return varchar2 is',
'        l_item_pagina varchar2(256);',
'        l_existe_item number;        ',
'    begin        ',
'        l_item_pagina := upper(''P'')||upper(p_pagina)||''_''||upper(p_nome_campo); ',
'        select count(1) into l_existe_item from apex_application_page_items where lower(item_name) = lower(l_item_pagina) and DISPLAY_AS != ''Hidden'';           ',
'        if l_existe_item > 0 then ',
'            select item_name into l_item_pagina from apex_application_page_items where rownum = 1 and lower(item_name) = lower(l_item_pagina);                       ',
'            return l_item_pagina;            ',
'        else',
'            return null;',
'        end if;    ',
'    end retorna_item_pagina;        ',
'',
'    function substitui_paramentro(',
'        p_mensagem varchar2,',
'        p_parametro paramentros',
'    ) return varchar2 is',
'        v_resultado varchar2(4000);',
'        v_param_tag varchar2(100);',
'        i PLS_INTEGER := 0;',
'    begin',
'        v_resultado := p_mensagem;',
'        while instr(v_resultado, ''$param'') >= 0 and i < 20 loop',
'            v_param_tag := ''$param'' || i;',
'',
'            if p_parametro.exists(i) then',
'                -- apex_debug.error(''retorna_mensagem p_parametro%s: %s'',i,p_parametro(i));     ',
'                v_resultado := replace(v_resultado, v_param_tag, p_parametro(i));',
'            else',
'                v_resultado := replace(v_resultado, v_param_tag, '''');',
'            end if;            ',
'            -- v_resultado := replace(v_resultado, v_param_tag, p_parametro(i));',
'            i := i + 1;',
'        end loop;',
'        return v_resultado;',
'        exception            ',
'            when others THEN',
unistr('                raise_application_error(-20111,''Erro na fun\00E7\00E3o pkg_mensagem.substitui_paramentro para p_mensagem: '' ||p_mensagem ||'' para o erro :''||sqlerrm);'),
'',
'    end substitui_paramentro;',
'',
'    procedure retorna_mensagem (',
'        p_codigo_mensagem in varchar2,',
'        p_mensagem        out mpd_traducao.texto_traduzido%type,',
'        p_instrucao       out mpd_traducao.texto_traduzido%type,        ',
'        p_help            out mpd_traducao.texto_traduzido%type',
'    )is',
'    begin',
'        p_mensagem := retorna_texto(''msg.''||p_codigo_mensagem||''.l'');',
'        p_instrucao := retorna_texto(''msg.''||p_codigo_mensagem||''.i'');',
'        p_help := retorna_texto(''msg.''||p_codigo_mensagem||''.h'');',
'    end retorna_mensagem; ',
'',
'    function tag_mensagem(',
'        p_mensagem        in clob,',
'        p_concatena_texto in boolean default true,',
'        p_nao_auto_fechar in boolean default true',
'    ) return clob is',
'        l_mensagem clob;',
'    begin',
'        l_mensagem := p_mensagem;',
'',
'        if p_concatena_texto then',
'            l_mensagem := c_tag_concatena || l_mensagem;',
'        end if;',
'',
'        if p_nao_auto_fechar then',
'            l_mensagem := c_tag_nao_fechar || l_mensagem;',
'        end if;',
'',
'        return l_mensagem;',
'    end tag_mensagem;    ',
'',
'end "PKG_MENSAGEM";',
'/'))
);
end;
/
