'--         EXECUTE IMMEDIATE ''ALTER TABLE LOG_PROJETO DROP COLUMN DATA_CRIACAO'';',
'--     END IF;',
'-- END;',
'-- /',
'',
unistr('-- -- 5. DELE\00C7\00C3O DE TABELA (Apenas se existir)'),
unistr('-- -- Nota: Use com extrema cautela em scripts de upgrade para n\00E3o perder dados de produ\00E7\00E3o.'),
'-- DECLARE',
'--     v_count NUMBER;',
'-- BEGIN',
'--     SELECT count(*) INTO v_count FROM user_tables WHERE table_name = ''TABELA_OBSOLETA'';',
'--     IF v_count > 0 THEN',
'--         EXECUTE IMMEDIATE ''DROP TABLE TABELA_OBSOLETA'';',
'--     END IF;',
'-- END;'))
);
end;
