,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_SRV_MENU'
,p_sequence=>30
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package            bo_srv_menu ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old srv_menu%rowtype;',
'    v_new srv_menu%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao srv_menu.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
