unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_menu'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_menu'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_menu'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_menu'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_menu'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_menu'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in srv_menu%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_menu_pai'', p_rec.id_menu_pai, true);',
'        apex_json.write(''id_sistema_versionado'', p_rec.id_sistema_versionado, true);',
'        apex_json.write(''titulo'', p_rec.titulo, true);',
'        apex_json.write(''ordenacao'', p_rec.ordenacao, true);',
'        apex_json.write(''icone'', p_rec.icone, true);',
'        apex_json.write(''ind_sincronizar'', p_rec.ind_sincronizar, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        inclui_srv_texto(',
'            p_encadeado          => p_encadeado,',
'            p_sucesso            => p_sucesso,',
'            p_messages           => p_messages',
'        );',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        altera_srv_texto(',
'            p_encadeado          => p_encadeado,',
'            p_sucesso            => p_sucesso,',
'            p_messages           => p_messages',
'        );',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        exclui_srv_texto(',
'            p_encadeado          => p_encadeado,',
'            p_sucesso            => p_sucesso,',
'            p_messages           => p_messages',
'        );',
'    end; ',
'    --',
unistr('    -- Fun\00E7\00F5es complementares'),
'    --',
'    procedure inclui_srv_texto(',
'            p_encadeado in boolean default false,',
'            p_sucesso out clob,',
'            p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_texto number;',
'    begin',
'        bo_srv_texto.inclui_registro(',
'            p_id_tenant               => v_new.id_tenant,',
'            p_id_sistema_versionado   => v_new.id_sistema_versionado,',
'            p_id_aplicacao_versionada => null,',
'            p_tag                     => v_new.id,',
'            p_necessita_revisao       => 1, -- Sim',
unistr('            p_apex_traduzira          => 2, -- N\00E3o'),
unistr('            p_tipo_texto              => 7, -- 7=Menu (t\00F3picos);'),
'            p_id                      => l_id_texto,',
'            p_label                   => v_new.titulo,',
'            p_instrucao               => null,',
'            p_help                    => null,',
'            -- p_pagina                  => v_pagina,',
'            p_encadeado               => p_encadeado,',
'            p_sucesso                 => p_sucesso,',
'            p_messages                => p_messages',
'        );',
'    end inclui_srv_texto;        ',
'',
'    procedure altera_srv_texto(',
'            p_encadeado in boolean default false,',
'            p_sucesso out clob,',
'            p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_texto number;',
'    begin',
'        bo_srv_texto.altera_registro_por_tag(',
'            p_id_tenant               => v_new.id_tenant,',
'            p_id_sistema_versionado   => v_new.id_sistema_versionado,',
'            p_id_aplicacao_versionada => null,',
'            p_tag_old                 => v_old.id,',
'            p_tag                     => v_new.id,',
'            p_necessita_revisao       => 1, -- Sim',
unistr('            p_apex_traduzira          => 2, -- N\00E3o'),
unistr('            p_tipo_texto_old          => 7, -- 7=Menu (t\00F3picos);'),
unistr('            p_tipo_texto              => 7, -- 7=Menu (t\00F3picos);      '),
'            p_label                   => v_new.titulo,',
'            p_instrucao               => null,',
'            p_help                    => null,',
'            p_data_alteracao          => null,',
'            -- p_pagina                  => v_pagina,',
'            p_encadeado               => p_encadeado,',
'            p_sucesso                 => p_sucesso,',
'            p_messages                => p_messages',
'        );',
'    end altera_srv_texto;        ',
'',
'    procedure exclui_srv_texto(',
'            p_encadeado in boolean default false,',
'            p_sucesso out clob,',
'            p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_texto number;',
'    begin',
'        bo_srv_texto.exclui_registro_por_tag(',
'            p_tag                     => v_old.id,',
unistr('            p_tipo_texto              => 7, -- 7=Menu (t\00F3picos);'),
'            p_encadeado               => p_encadeado,',
'            p_sucesso                 => p_sucesso,',
'            p_messages                => p_messages',
'        );',
'    end exclui_srv_texto;     ',
'',
'    procedure altera_titulo(  ',
'        p_titulo in srv_menu.titulo%type,',
'        p_id in srv_menu.id%type, ',
'        p_data_alteracao in srv_menu.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_menu.altera_titulo_ordenacao_icone'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'',
'        select * into v_old from srv_menu where id = p_id;        ',
'        v_new := v_old;',
'',
'        /* Seta valores passados por parametros */ ',
'        v_new.titulo := p_titulo;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate; ',
'',
'        /* Executa rotinas antes de alterar */ ',
'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'',
'        /* Executa update */ ',
'        update srv_menu set  ',
'            id_tenant = v_new.id_tenant,',
'            id_menu_pai = v_new.id_menu_pai,',
'            id_sistema_versionado = v_new.id_sistema_versionado,',
'            titulo = v_new.titulo,',
'            ordenacao = v_new.ordenacao,',
'            icone = v_new.icone, ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(',
'            p_encadeado          => true,',
'            p_sucesso            => p_sucesso,',
'            p_messages           => v_messages',
'        ); ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_titulo; ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_srv_menu; ',
'/'))
);
end;
