'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_titulo(p_titulo in mpd_menu.titulo%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_titulo;     ',
'',
'    procedure hook_valida_ordenacao(p_ordenacao in mpd_menu.ordenacao%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ordenacao;     ',
'',
'    procedure hook_valida_icone(p_icone in mpd_menu.icone%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_icone;     ',
'',
'    procedure hook_valida_id_nivel_pai(p_id_nivel_pai in mpd_menu.id_nivel_pai%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_nivel_pai;     ',
'',
'    procedure hook_valida_ind_sincronizar(p_ind_sincronizar in mpd_menu.ind_sincronizar%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_sincronizar;     ',
'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''mpd_menu'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mpd_menu'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''mpd_menu'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mpd_menu'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''mpd_menu'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''mpd_menu'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => null,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in mpd_menu%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''titulo'', p_rec.titulo, true);',
'        apex_json.write(''ordenacao'', p_rec.ordenacao, true);',
'        apex_json.write(''icone'', p_rec.icone, true);',
'        apex_json.write(''id_nivel_pai'', p_rec.id_nivel_pai, true);',
'        apex_json.write(''ind_sincronizar'', p_rec.ind_sincronizar, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    procedure inclui_registro(  ',
'        p_titulo in mpd_menu.titulo%type,',
'        p_ordenacao in mpd_menu.ordenacao%type,',
'        p_icone in mpd_menu.icone%type,',
'        p_id_nivel_pai in mpd_menu.id_nivel_pai%type, ',
'        p_ind_sincronizar in mpd_menu.ind_sincronizar%type, ',
'        p_id in mpd_menu.id%type, ',
'        p_id_out out mpd_menu.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        v_parametro(0) := ''bo_mpd_menu.inclui_registro'';   ',
'        v_pagina := p_pagina; ',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id := p_id;',
'        v_new.titulo := p_titulo;',
'        v_new.ordenacao := p_ordenacao;',
'        v_new.icone := p_icone;',
'        v_new.id_nivel_pai := p_id_nivel_pai; ',
'        v_new.ind_sincronizar := p_ind_sincronizar; ',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao := sysdate; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate; ',
'        --',
'        cria(p_encadeado,p_sucesso,p_messages,p_id_out);                         ',
'    end inclui_registro; ',
'',
'    procedure verifica_registro( ',
'        p_id in mpd_menu.id%type, ',
'        p_data_alteracao out mpd_menu.data_alteracao%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select data_alteracao into p_data_alteracao from mpd_menu where id = p_id; ',
'        exception',
'            when no_data_found then',
'                p_data_alteracao := null; ',
'    end verifica_registro;   ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_mpd_menu;',
'/'))
);
end;
