 p_id=>wwv_flow_imp.id(231232681542956299)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'icone is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''mpd_menu.icone''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''icone'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
