'    procedure sincroniza_mpd_funcionalidade_regra_execucao (',
'        p_id                 in srv_sistema_versionado.id%type default null,',
'        p_encadeado          in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_funcionalidade_regra_execucao mpd_funcionalidade_regra_execucao.id%type;',
'        l_data_alteracao mpd_funcionalidade_regra_execucao.data_alteracao%type;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_artefato in (',
'            select',
'                f.id,',
'                j1.id as id_funcionalidade,',
'                f.metodo_validacao,',
'                f.sql_validacao',
'            from',
'                     srv_sistema_versionado a',
'                join srv_aplicacao_versionada    b on b.id_sistema_versionado = a.id',
'                join srv_artefato_versionado     c on c.id_aplicacao_versionada = b.id',
'                join srv_artefato                d on d.id = c.id_artefato',
'                join srv_artefato_versionado     e on e.id_artefato = d.id',
'                join srv_artefato_regra_execucao f on f.id_artefato_versionado = e.id',
'                join srv_artefato_versionado     i on i.id = f.id_artefato_versionado',
'                join srv_artefato                j on j.id = i.id_artefato',
'                join mpd_funcionalidade          j1 on j1.codigo_artefato = j.codigo_artefato',
'            where',
'                    a.id = p_id',
'                and e.situacao = pkg_util.dominio_retorna_valor(''srv_artefato_versionado'', ''situacao'', ''ativo'')',
'                and f.data_alteracao > v_data_alteracao',
'        ) loop',
'            bo_mpd_funcionalidade_regra_execucao.verifica_registro(c_artefato.id,l_data_alteracao);',
'            if l_data_alteracao is not null then',
'                bo_mpd_funcionalidade_regra_execucao.altera_registro(',
'                    p_id_funcionalidade => c_artefato.id_funcionalidade, ',
'                    p_metodo_validacao => c_artefato.metodo_validacao, ',
'                    p_sql_validacao => c_artefato.sql_validacao, ',
'                    p_id => c_artefato.id, ',
'                    p_data_alteracao=> l_data_alteracao, ',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso, ',
'                    p_messages => v_messages);',
'            else',
'                bo_mpd_funcionalidade_regra_execucao.inclui_registro(',
'                    p_id_funcionalidade => c_artefato.id_funcionalidade, ',
'                    p_metodo_validacao => c_artefato.metodo_validacao, ',
'                    p_sql_validacao => c_artefato.sql_validacao, ',
'                    p_id => c_artefato.id, ',
'                    p_id_out => l_id_funcionalidade_regra_execucao, ',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso, ',
'                    p_messages => v_messages);',
'            end if;',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;    ',
'        end loop;',
'        apaga_mpd_funcionalidade_regra_execucao(',
'            p_sucesso,',
'            p_messages',
'        );              ',
'        p_messages := v_messages;',
'    end sincroniza_mpd_funcionalidade_regra_execucao;',
'',
'    procedure apaga_mpd_funcionalidade_regra_execucao (',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
