'    procedure sincroniza_mpd_cadastro_compartilhavel_entidade (',
'        p_id_cadastro_compartilhavel in srv_cadastro_compartilhavel_entidade.id_cadastro_compartilhavel%type default null,',
'        p_id                         in mpd_cadastro_compartilhavel.id%type default null,',
'        p_encadeado                  in boolean default false,',
'        p_sucesso                    out clob,',
'        p_messages                   out pkg_mensagem.message_record_table',
'    ) is',
'    begin ',
'        merge into mpd_cadastro_compartilhavel_entidade dst',
'        using (',
'            select id,',
'                   nome_entidade,',
'                   id_cadastro_compartilhavel,',
'                   id_usuario_incluiu,',
'                   data_inclusao,',
'                   id_usuario_alterou,',
'                   data_alteracao',
'              from srv_cadastro_compartilhavel_entidade',
'             where id_cadastro_compartilhavel = p_id_cadastro_compartilhavel',
'        ) src',
unistr('           on (dst.id = src.id)   -- chave de correspond\00EAncia'),
'         when matched then',
'              update set',
'                  dst.id_cadastro_compartilhavel = src.id_cadastro_compartilhavel,',
'                  dst.nome_entidade              = src.nome_entidade,',
'                  dst.id_usuario_alterou         = src.id_usuario_alterou,',
'                  dst.data_alteracao             = src.data_alteracao',
'         when not matched then',
'              insert (',
'                  id,',
'                  id_cadastro_compartilhavel,',
'                  nome_entidade,',
'                  id_usuario_incluiu,',
'                  data_inclusao,',
'                  id_usuario_alterou,',
'                  data_alteracao',
'              ) values (',
'                  src.id,',
'                  src.id_cadastro_compartilhavel,',
'                  src.nome_entidade,',
'                  src.id_usuario_incluiu,',
'                  src.data_inclusao,',
'                  src.id_usuario_alterou,',
'                  src.data_alteracao',
'              );    ',
'                            ',
'        apaga_mpd_cadastro_compartilhavel_entidade(',
'            p_sucesso,',
'            p_messages',
'        );',
'',
