unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_sistema_versionado'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_sistema_versionado'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_sistema_versionado'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_sistema_versionado'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_sistema_versionado'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_sistema_versionado'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in srv_sistema_versionado%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_sistema'', p_rec.id_sistema, true);',
'        apex_json.write(''id_menu'', p_rec.id_menu, true);',
'        apex_json.write(''id_grupo_funcionalidade'', p_rec.id_grupo_funcionalidade, true);',
'        apex_json.write(''versao'', p_rec.versao, true);',
'        apex_json.write(''situacao'', p_rec.situacao, true);',
'        apex_json.write(''data_descontinuidade'', p_rec.data_descontinuidade, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    procedure sincroniza_versao (',
'        p_id in srv_sistema_versionado.id%type default 0,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_funcionalidade mpd_funcionalidade.id%type;',
'        p_encadeado         boolean default false;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();        ',
'        v_parametro(0) := ''BO_SRV_SISTEMA_VERSIONADO.sincroniza_versao'';   ',
unistr('        v_parametro(1) := ''Sincronizar vers\00E3o'';   '),
'',
'        for c_sistema in (',
'            select b.id,b.data_alteracao',
'            from srv_sistema a join srv_sistema_versionado b on b.id_sistema = a.id',
'            where lower(b.situacao) = lower(''a'') AND (',
'                CASE ',
'                  WHEN p_id != 0 AND a.id = p_id THEN 1',
'                  WHEN p_id = 0 THEN 1',
'                  ELSE 0',
'                END = 1',
'              )',
'        ) loop',
unistr('            -- Chama a fun\00E7\00E3o para propular as tabelas MDP_FUNCIONALIDADE a partir das tabelas de SRV_ARTEFATO'),
'            v_data_alteracao := c_sistema.data_alteracao;',
'            if c_sistema.id is not null then',
'                sincroniza_mpd_dominio_valor(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',11);     ',
'                sincroniza_mpd_entidade(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                sincroniza_mpd_entidade_coluna(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                sincroniza_mpd_funcionalidade(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'',
'                apex_debug.error(''sincroniza_versao Linha:%s'',11);     ',
'                sincroniza_mpd_funcionalidade_wizard(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then ',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'',
'                apex_debug.error(''sincroniza_versao Linha:%s'',12);     ',
'                sincroniza_mpd_funcionalidade_botao_acao(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then ',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',13);     ',
'                sincroniza_mpd_funcionalidade_tela_dinamica(p_id => c_sistema.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then ',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',14);     ',
'                sincroniza_mpd_funcionalidade_acao_dinamica(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then ',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',15);     ',
'                sincroniza_mpd_funcionalidade_regra_execucao(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then ',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',16);     ',
'                sincroniza_mpd_funcionalidade_zoom_dinamico(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',17);     ',
'                sincroniza_mpd_menu(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',18);     ',
'                sincroniza_mpd_grupo_funcionalidade(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',19);     ',
'                sincroniza_mpd_cadastro_compartilhavel(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',20);     ',
'                sincroniza_mpd_entidade_ng_permite_anexo(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'',
'                if v_messages.count > 0 then',
'                    raise pk_exceptions.e_erro;',
'                end if;',
'                apex_debug.error(''sincroniza_versao Linha:%s'',21);     ',
'                sincroniza_mpd_configuracao_ng(p_id => c_sistema.id, p_encadeado => TRUE, p_sucesso => p_sucesso, p_messages => v_messages);',
'',
'            end if;',
'',
'            update srv_sistema_versionado',
'            set',
'                id_usuario_alterou = pkg_util.retorna_id_usuario_logado,',
'                data_alteracao = sysdate',
'            where',
'                id = c_sistema.id; ',
'',
'        end loop;',
'',
'        if v_messages.count > 0 then',
'            apex_debug.error(''sincroniza_versao erro1'');     ',
'            raise pk_exceptions.e_erro;',
'        else',
'            apex_debug.error(''sincroniza_versao sucesso'');     ',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao => pkg_mensagem.c_operacao_sucesso_acao, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                apex_debug.error(''sincroniza_versao erro2'');     ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                apex_debug.error(''sincroniza_versao erro3'');     ',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'            ',
'    end sincroniza_versao;',
'',
'    procedure sincroniza_mpd_dominio_valor (',
'        p_id                 in srv_sistema_versionado.id%type,',
'        p_encadeado          in boolean default false,',
'        p_sucesso            out clob,',
'        p_messages           out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade mpd_dominio_valor.id%type;',
'        l_data_alteracao mpd_dominio_valor.data_alteracao%type;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_dominio_valor in (',
'            select',
'                a.id,',
'                a.id_dominio,',
'                a.valor,',
'                a.tag',
'            from',
'                srv_dominio_valor a',
'            where a.data_alteracao > v_data_alteracao',
'        ) loop',
'            bo_mpd_dominio_valor.verifica_registro(c_dominio_valor.id,l_data_alteracao);',
'            if l_data_alteracao is not null then',
'                bo_mpd_dominio_valor.altera_registro(',
'                    p_id_dominio => c_dominio_valor.id_dominio,',
'                    p_valor => c_dominio_valor.valor,',
'                    p_tag => c_dominio_valor.tag,',
'                    p_id => c_dominio_valor.id, --Mesmo ID do artefato',
'                    p_data_alteracao => l_data_alteracao, ',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso,',
'                    p_messages => v_messages);                  ',
'            else',
'                bo_mpd_dominio_valor.inclui_registro(',
'                    p_id_dominio => c_dominio_valor.id_dominio,',
'                    p_valor => c_dominio_valor.valor,',
'                    p_tag => c_dominio_valor.tag,',
'                    p_id => c_dominio_valor.id, --Mesmo ID do artefato',
'                    p_id_out => l_id_entidade, ',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso,',
'                    p_messages => v_messages);      ',
'            end if;',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;    ',
'        end loop; ',
'        apaga_mpd_dominio_valor(',
'            p_sucesso,',
'            p_messages',
'        );',
'        p_messages := v_messages;     ',
'    end sincroniza_mpd_dominio_va'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(231232863548949097)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'lor;',
'',
'    procedure apaga_mpd_dominio_valor(',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c in (',
'            select id from mpd_dominio_valor a',
'            where not exists (select id from srv_dominio_valor b where b.id = a.id)',
'        ) ',
'        loop',
