'    procedure sincroniza_mpd_funcionalidade_wizard (',
'        p_id                 in srv_sistema_versionado.id%type default null,',
'        p_encadeado          in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_funcionalidade_wizard mpd_funcionalidade_wizard.id%type;',
'        l_data_alteracao mpd_funcionalidade_wizard.data_alteracao%type;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_artefato in (',
'            select',
'                f.id,',
'                f.ordem,',
'                f.etapa,',
'                f.id_tenant,',
'                f.parametro_anterior,',
'                f.parametro_proximo,',
'                d.id id_funcionalidade,',
'                h.id id_funcionalidade_base,',
'                h1.id id_funcionalidade_anterior,',
'                h2.id id_funcionalidade_proximo',
'            from',
'                     srv_sistema_versionado a',
'                join srv_aplicacao_versionada b on b.id_sistema_versionado = a.id',
'                join srv_artefato_versionado  c on c.id_aplicacao_versionada = b.id',
'                join srv_artefato             d on d.id = c.id_artefato',
'                join srv_artefato_versionado  e on e.id_artefato = d.id',
'                join srv_artefato_wizard      f on f.id_artefato_versionado = e.id',
'                join srv_artefato_versionado  g on g.id = f.id_artefato_versionado_base',
'                join srv_artefato             h on h.id = g.id_artefato',
'                left join srv_artefato_versionado  g1 on g1.id = f.id_artefato_versionado_anterior',
'                left join srv_artefato             h1 on h1.id = g1.id_artefato',
'                left join srv_artefato_versionado  g2 on g2.id = f.id_artefato_versionado_proximo',
'                left join srv_artefato             h2 on h2.id = g2.id_artefato',
'            where',
'                    a.id = p_id',
'                and e.situacao = pkg_util.dominio_retorna_valor(''srv_artefato_versionado'', ''situacao'', ''ativo'')',
'                and f.data_alteracao > v_data_alteracao',
'        ) loop',
'            bo_mpd_funcionalidade_wizard.verifica_registro(c_artefato.id,l_data_alteracao);',
'            if l_data_alteracao is not null then',
'                bo_mpd_funcionalidade_wizard.altera_registro(',
'                    p_id_tenant => c_artefato.id_tenant, ',
'                    p_ordem => c_artefato.ordem, ',
'                    p_etapa => c_artefato.etapa, ',
'                    p_id_funcionalidade => c_artefato.id_funcionalidade, ',
'                    p_id_funcionalidade_base => c_artefato.id_funcionalidade_base, ',
'                    p_id_funcionalidade_anterior => c_artefato.id_funcionalidade_anterior, ',
'                    p_parametro_anterior => c_artefato.parametro_anterior, ',
'                    p_id_funcionalidade_proximo => c_artefato.id_funcionalidade_proximo, ',
'                    p_parametro_proximo => c_artefato.parametro_proximo,                                          ',
'                    p_id => c_artefato.id, ',
'                    p_data_alteracao => l_data_alteracao, ',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso,',
'                    p_messages => v_messages);',
'            else',
'                bo_mpd_funcionalidade_wizard.inclui_registro(',
'                    p_ordem => c_artefato.ordem, ',
'                    p_id_tenant => c_artefato.id_tenant, ',
'                    p_id_funcionalidade_proximo => c_artefato.id_funcionalidade_proximo, ',
'                    p_parametro_anterior => c_artefato.parametro_anterior, ',
'                    p_id_funcionalidade => c_artefato.id_funcionalidade, ',
'                    p_id_funcionalidade_base => c_artefato.id_funcionalidade_base, ',
'                    p_parametro_proximo => c_artefato.parametro_proximo,                                          ',
'                    p_id_funcionalidade_anterior => c_artefato.id_funcionalidade_anterior, ',
'                    p_etapa => c_artefato.etapa, ',
'                    p_id => c_artefato.id, ',
'                    p_id_out => l_id_funcionalidade_wizard, ',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso,',
'                    p_messages => v_messages);',
'            end if;',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;        ',
'        end loop;',
'        apaga_mpd_funcionalidade_wizard(',
'            p_sucesso,',
'            p_messages',
'        );        ',
'        p_messages := v_messages;     ',
'    end sincroniza_mpd_funcionalidade_wizard;',
'',
'    procedure apaga_mpd_funcionalidade_wizard (',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_botao_acao in (',
'            select id from mpd_funcionalidade_wizard',
'            where not exists (select id from srv_artefato_wizard where srv_artefato_wizard.id = mpd_funcionalidade_wizard.id)',
'        ) loop',
