'                    p_parametro => c_artefato.parametro,',
'                    p_valor => c_artefato.valor,',
'                    p_tipo_acao => c_artefato.tipo_acao,',
'                    p_titulo => c_artefato.titulo,',
'                    p_help => c_artefato.help,',
'                    p_icone => c_artefato.icone,',
'                    p_ind_nao_envia_id_registro => c_artefato.ind_nao_envia_id_registro,',
'                    p_id => c_artefato.id, ',
'                    p_data_alteracao => l_data_alteracao, ',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso,',
'                    p_messages => v_messages);                    ',
'            else',
'                bo_mpd_funcionalidade_botao_acao.inclui_registro(',
'                    p_id_funcionalidade => c_artefato.id_funcionalidade, ',
'                    p_id_funcionalidade_exibir => c_artefato.id_funcionalidade_exibir, ',
'                    p_parametro => c_artefato.parametro,',
'                    p_valor => c_artefato.valor,',
'                    p_tipo_acao => c_artefato.tipo_acao,',
'                    p_titulo => c_artefato.titulo,',
'                    p_help => c_artefato.help,',
'                    p_icone => c_artefato.icone,',
'                    p_ind_nao_envia_id_registro => c_artefato.ind_nao_envia_id_registro,',
