'    ) is',
'        l_id_funcionalidade_crud_dinamico mpd_funcionalidade_tela_dinamica.id%type;',
'        l_data_alteracao mpd_funcionalidade_tela_dinamica.data_alteracao%type;',
'    begin         ',
