'    procedure sincroniza_mpd_menu (',
'        p_id                 in srv_sistema_versionado.id%type default null,',
'        p_encadeado          in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_menu mpd_menu.id%type;',
'        l_id_menu_fiho mpd_menu.id%type;',
'        l_data_alteracao mpd_menu.data_alteracao%type;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_menu in (',
'            select a.id, a.id_menu_pai, a.titulo, a.ordenacao, a.icone, a.ind_sincronizar',
'            from srv_menu a left join srv_menu_acao b on b.id_menu = a.id',
'            where id_sistema_versionado = p_id --and id_menu_pai is null',
'            and (a.data_alteracao > v_data_alteracao',
'            or b.data_alteracao > v_data_alteracao)',
'        ) loop',
'            bo_mpd_menu.verifica_registro(c_menu.id,l_data_alteracao);',
'            if l_data_alteracao is not null then',
'                bo_mpd_menu.altera_registro(',
'                    p_id_nivel_pai => c_menu.id_menu_pai, ',
'                    p_titulo => c_menu.titulo, ',
'                    p_ordenacao => c_menu.ordenacao, ',
'                    p_icone => c_menu.icone, ',
'                    p_id => c_menu.id,',
'                    p_ind_sincronizar => c_menu.ind_sincronizar,',
'                    p_data_alteracao => l_data_alteracao,',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso, ',
'                    p_messages => v_messages);',
'            else',
'                bo_mpd_menu.inclui_registro(',
'                    p_id_nivel_pai => c_menu.id_menu_pai, ',
'                    p_titulo => c_menu.titulo, ',
'                    p_ordenacao => c_menu.ordenacao, ',
'                    p_icone => c_menu.icone, ',
'                    p_id => c_menu.id,',
'                    p_ind_sincronizar => c_menu.ind_sincronizar,',
'                    p_id_out => l_id_menu,',
'                    p_encadeado => true, ',
'                    p_sucesso => p_sucesso, ',
'                    p_messages => v_messages);',
'            end if;',
'            if not v_messages.count > 0 then',
'                sincroniza_mpd_menu_acao(p_id => c_menu.id, p_id_mpd_menu => c_menu.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => p_messages);',
'            end if;        ',
'',
'            for c_menu_filho in (',
'                select id, id_menu_pai, titulo, ordenacao, icone, ind_sincronizar from srv_menu a',
'                where id_menu_pai = c_menu.id               ',
'            ) loop',
'                bo_mpd_menu.verifica_registro(c_menu_filho.id,l_data_alteracao);',
'                if l_data_alteracao is not null then',
'                    bo_mpd_menu.altera_registro(',
'                        p_id_nivel_pai => c_menu_filho.id_menu_pai, ',
'                        p_titulo => c_menu_filho.titulo, ',
'                        p_ordenacao => c_menu_filho.ordenacao, ',
'                        p_icone => c_menu_filho.icone, ',
'                        p_id => c_menu_filho.id,',
'                        p_ind_sincronizar => c_menu.ind_sincronizar,',
'                        p_data_alteracao => l_data_alteracao,',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => v_messages);',
'                else',
'                    bo_mpd_menu.inclui_registro(',
'                        p_id_nivel_pai => c_menu_filho.id_menu_pai, ',
'                        p_titulo => c_menu_filho.titulo, ',
'                        p_ordenacao => c_menu_filho.ordenacao, ',
'                        p_icone => c_menu_filho.icone, ',
'                        p_id => c_menu_filho.id,',
'                        p_ind_sincronizar => c_menu.ind_sincronizar,',
'                        p_id_out => l_id_menu_fiho,',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => v_messages);',
'                end if;',
'                if not v_messages.count > 0 then',
'                    sincroniza_mpd_menu_acao(',
'                        p_id => c_menu_filho.id, ',
'                        p_id_mpd_menu => c_menu_filho.id, ',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => p_messages);',
'                end if;',
'            end loop;',
'        end loop;',
'         apaga_mpd_menu(',
'             p_sucesso,',
'             p_messages',
'         );        ',
'        p_messages := v_messages;',
'    end sincroniza_mpd_menu;',
'',
'    procedure apaga_mpd_menu (',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_mpd_menu in (',
'            select id from mpd_menu',
'            where not exists (select id from srv_menu where srv_menu.id = mpd_menu.id)',
'        ) loop',
'            bo_mpd_menu.exclui_registro(',
'                p_id => c_mpd_menu.id, ',
'                p_encadeado => true, ',
'                p_sucesso => p_sucesso, ',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;',
'        end loop;',
'        p_messages := v_messages;',
'    end apaga_mpd_menu;',
'',
'    procedure sincroniza_mpd_menu_acao (',
'        p_id                 in srv_menu.id%type default null,',
'        p_id_mpd_menu        in mpd_menu.id%type default null,',
'        p_encadeado          in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_menu_acao      mpd_menu_acao.id%type;',
'        l_data_alteracao      mpd_menu_acao.data_alteracao%type;',
'        l_id_funcionalidade mpd_funcionalidade.id%type;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_menu_acao in (',
'            select id, id_artefato_versionado, ordenacao from srv_menu_acao where id_menu = p_id',
'            and data_alteracao > v_data_alteracao',
'        ) loop',
'            if c_menu_acao.id_artefato_versionado is not null then',
'                -- Procura o id da funcionalidade de acordo com o id do artefato versionado',
'                begin',
'                    select a.id into l_id_funcionalidade from mpd_funcionalidade a',
'                        join srv_artefato            b on b.codigo_artefato = a.codigo_artefato',
'                        join srv_artefato_versionado c on c.id_artefato = b.id',
'                    where rownum <= 1 and c.id = c_menu_acao.id_artefato_versionado;',
'                exception',
'                    when others then',
'                        raise_application_error(-20002, ''erro em sincroniza_mpd_menu_acao: c_menu_acao.id_artefato_versionado:''||c_menu_acao.id_artefato_versionado ||'' - Erro original:''|| sqlerrm);',
'                end;',
'                bo_mpd_menu_acao.verifica_registro(c_menu_acao.id,l_data_alteracao);',
'                if l_data_alteracao is not null then',
'                    bo_mpd_menu_acao.altera_registro(',
'                        p_id_menu => p_id_mpd_menu, ',
'                        p_id_funcionalidade => l_id_funcionalidade, ',
'                        p_ordenacao => c_menu_acao.ordenacao, ',
'                        p_id => c_menu_acao.id, ',
'                        p_data_alteracao => l_data_alteracao, ',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => v_messages);',
'                else',
'                    bo_mpd_menu_acao.inclui_registro(',
'                        p_id_menu => p_id_mpd_menu, ',
'                        p_id_funcionalidade => l_id_funcionalidade, ',
'                        p_ordenacao => c_menu_acao.ordenacao, ',
'                        p_id => c_menu_acao.id, ',
'                        p_id_out => l_id_menu_acao, ',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => v_messages);',
'                end if;',
'                if v_messages.count > 0 then',
'                    exit;',
'                end if;',
'            end if;',
'        end loop;',
'        apaga_mpd_menu_acao(',
'            p_sucesso,',
'            p_messages',
'        );           ',
'        p_messages := v_messages;',
'    end sincroniza_mpd_menu_acao;',
'',
'    procedure apaga_mpd_menu_acao (',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_menu_acao in (',
'            select id from mpd_menu_acao',
'            where not exists (select id from srv_menu_acao where srv_menu_acao.id = mpd_menu_acao.id)',
'        ) loop',
'            bo_mpd_menu_acao.exclui_registro(',
'                p_id => c_menu_acao.id, ',
'                p_encadeado => true, ',
'                p_sucesso => p_sucesso, ',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;',
'        end loop;',
'        p_messages := v_messages;',
'    end apaga_mpd_menu_acao;',
'',
