'    --     p_messages := v_messages;',
'    -- end sincroniza_mpd_grupo_funcionalidade;',
'',
'    procedure sincroniza_mpd_grupo_funcionalidade (',
'        p_id        in srv_sistema_versionado.id%type default null,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        l_data_alteracao               mpd_grupo_funcionalidade.data_alteracao%type;',
'        l_id_grupo_funcionalidade_out mpd_grupo_funcionalidade.id%type;',
'        v_messages pkg_mensagem.message_record_table;',
'',
unistr('        -- Fun\00E7\00E3o recursiva que processa qualquer n\00EDvel da \00E1rvore'),
'        procedure processa_grupo_funcionalidade (',
'            p_id_grupo_pai in srv_grupo_funcionalidade.id%type,',
'            p_id_nivel_pai in mpd_grupo_funcionalidade.id%type',
'        ) is',
'        begin',
'            for rec in (',
'                select id, id_tenant, id_sistema_versionado, id_grupo_pai, titulo, ordenacao, data_alteracao',
'                from srv_grupo_funcionalidade',
'                where id_sistema_versionado = p_id and ',
'                      (id_grupo_pai = p_id_grupo_pai or (p_id_grupo_pai is null and id_grupo_pai is null))',
'            ) loop',
'                bo_mpd_grupo_funcionalidade.verifica_registro(rec.id, l_data_alteracao);',
'                if l_data_alteracao is not null then',
'                    bo_mpd_grupo_funcionalidade.altera_registro(',
'                        p_id => rec.id,',
'                        p_id_tenant => rec.id_tenant, ',
'                        p_id_nivel_pai => p_id_nivel_pai, ',
'                        p_titulo => rec.titulo, ',
'                        p_ordenacao => rec.ordenacao, ',
'                        p_data_alteracao => l_data_alteracao,',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => v_messages);',
'                    l_id_grupo_funcionalidade_out := rec.id;',
'                else',
'                    bo_mpd_grupo_funcionalidade.inclui_registro(',
'                        p_id => rec.id,',
'                        p_id_tenant => rec.id_tenant, ',
'                        p_id_nivel_pai => p_id_nivel_pai, ',
'                        p_titulo => rec.titulo, ',
'                        p_ordenacao => rec.ordenacao, ',
'                        p_id_out => l_id_grupo_funcionalidade_out,',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso, ',
'                        p_messages => v_messages);',
'                end if;',
'',
unistr('                -- Se ocorreram erros, interrompe a recurs\00E3o'),
'                if v_messages.count > 0 then',
'                    exit;',
'                end if;',
'',
'                -- Sincroniza funcionalidades do grupo',
'                sincroniza_mpd_grupo_funcionalidade_funcionalidade(',
'                    p_id => rec.id,',
'                    p_id_grupo_funcionalidade => l_id_grupo_funcionalidade_out,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => v_messages);',
'',
'                if v_messages.count > 0 then',
'                    exit;',
'                end if;',
'',
'                -- Chamada recursiva para os filhos do grupo atual',
'                processa_grupo_funcionalidade(',
'                    p_id_grupo_pai => rec.id,',
'                    p_id_nivel_pai => l_id_grupo_funcionalidade_out',
'                );',
'            end loop;',
'        end;',
'',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
unistr('        -- Come\00E7a o processamento com os grupos raiz (pai nulo)'),
'        processa_grupo_funcionalidade(p_id_grupo_pai => null, p_id_nivel_pai => null);',
'',
unistr('        -- Atualiza os par\00E2metros de sa\00EDda'),
'        p_messages := v_messages;',
'    end sincroniza_mpd_grupo_funcionalidade;    ',
'',
'    procedure apaga_mpd_grupo_funcionalidade (',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_mpd_grupo_funcionalidade in (',
'            select id from mpd_grupo_funcionalidade',
'            where not exists (select id from srv_grupo_funcionalidade where srv_grupo_funcionalidade.id = mpd_grupo_funcionalidade.id)',
'        ) loop',
'            bo_mpd_grupo_funcionalidade.exclui_registro(p_id => c_mpd_grupo_funcionalidade.id, p_encadeado => true, p_sucesso => p_sucesso, p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;',
'        end loop;',
'        p_messages := v_messages;',
'    end apaga_mpd_grupo_funcionalidade;',
'',
'    procedure sincroniza_mpd_grupo_funcionalidade_funcionalidade (',
'        p_id                      in srv_grupo_funcionalidade.id%type default null,',
'        p_id_grupo_funcionalidade in mpd_grupo_funcionalidade.id%type default null,',
'        p_encadeado               in boolean default false,',
'        p_sucesso                 out clob,',
'        p_messages                out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_grupo_funcionalidade_funcionalidade mpd_grupo_funcionalidade_funcionalidade.id%type;',
'        l_data_alteracao mpd_grupo_funcionalidade_funcionalidade.data_alteracao%type;',
'        l_id_funcionalidade                      mpd_funcionalidade.id%type;',
'        l_existe number;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_grupo_funcionalidade_funcionalidade in (',
'            select id, id_grupo_funcionalidade, id_artefato_versionado from srv_grupo_funcionalidade_artefato where id_grupo_funcionalidade = p_id',
'            --and data_alteracao > v_data_alteracao',
'        ) loop',
'            if c_grupo_funcionalidade_funcionalidade.id_artefato_versionado is not null then',
'                -- Procura o id da funcionalidade de acordo com o id do artefato versionado',
'                -- apex_debug.enable(apex_debug.c_log_level_info);',
'                -- apex_debug.info(''info sincroniza_mpd_grupo_funcionalidade_funcionalidade c_grupo_funcionalidade_funcionalidade.id_artefato_versionado:%s'',c_grupo_funcionalidade_funcionalidade.id_artefato_versionado);                   ',
'',
'                select count(1) into l_existe from mpd_funcionalidade a',
'                    join srv_artefato            b on b.codigo_artefato = a.codigo_artefato',
'                    join srv_artefato_versionado c on c.id_artefato = b.id',
'                where rownum <= 1 and c.id = c_grupo_funcionalidade_funcionalidade.id_artefato_versionado;',
'',
'',
'                if l_existe > 0 then',
'                    select a.id into l_id_funcionalidade from mpd_funcionalidade a',
'                        join srv_artefato            b on b.codigo_artefato = a.codigo_artefato',
'                        join srv_artefato_versionado c on c.id_artefato = b.id',
'                    where rownum <= 1 and c.id = c_grupo_funcionalidade_funcionalidade.id_artefato_versionado;',
'                    bo_mpd_grupo_funcionalidade_funcionalidade.verifica_registro(c_grupo_funcionalidade_funcionalidade.id,l_data_alteracao);',
'                    if l_data_alteracao is not null then',
'                        bo_mpd_grupo_funcionalidade_funcionalidade.altera_registro(',
'                            p_id => c_grupo_funcionalidade_funcionalidade.id,',
'                            p_id_grupo_funcionalidade => c_grupo_funcionalidade_funcionalidade.id_grupo_funcionalidade, ',
'                            p_id_funcionalidade => l_id_funcionalidade, ',
'                            p_data_alteracao => l_data_alteracao, ',
'                            p_sucesso => p_sucesso, ',
'                            p_messages => v_messages);',
'                    else               ',
'                        bo_mpd_grupo_funcionalidade_funcionalidade.inclui_registro(',
'                            p_id => c_grupo_funcionalidade_funcionalidade.id,',
'                            p_id_grupo_funcionalidade => c_grupo_funcionalidade_funcionalidade.id_grupo_funcionalidade, ',
'                            p_id_funcionalidade => l_id_funcionalidade, ',
'                            p_id_out => l_id_grupo_funcionalidade_funcionalidade, ',
'                            p_sucesso => p_sucesso, ',
'                            p_messages => v_messages);',
'                    end if;',
'                    if v_messages.count > 0 then',
'                        exit;',
'                    end if;',
'                end if;',
'            end if;',
'        end loop;',
'        apaga_mpd_grupo_funcionalidade_funcionalidade(',
'            p_sucesso,',
'            p_messages',
'        );',
'        p_messages := v_messages;',
'    end sincroniza_mpd_grupo_funcionalidade_funcionalidade;',
'',
'    procedure apaga_mpd_grupo_funcionalidade_funcionalidade (',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_mpd_grupo_funcionalidade_funcionalidade in (',
'            select id from mpd_grupo_funcionalidade_funcionalidade a',
'            where not exists (select id from srv_grupo_funcionalidade_artefato b where b.id = a.id)',
'        ) loop',
'            bo_mpd_grupo_funcionalidade_funcionalidade.exclui_registro(',
'                p_id => c_mpd_grupo_funcionalidade_funcionalidade.id, ',
'                p_encadeado => true, ',
'                p_sucesso => p_sucesso, ',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;',
'        end loop;',
'        p_messages := v_messages;',
'    end apaga_mpd_grupo_funcionalidade_funcionalidade;',
'',
'    procedure sincroniza_mpd_entidade_ng_permite_anexo (',
'        p_id          in srv_sistema_versionado.id%type,',
'        p_encadeado   in boolean default false,',
'        p_sucesso     out clob,',
'        p_messages    out pkg_mensagem.message_record_table',
'    ) is',
'        l_id                       mpd_entidade_ng_permite_anexo.id%type;',
'        l_data_alteracao           mpd_entidade_ng_permite_anexo.data_alteracao%type;',
'        v_messages                 pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'',
'    begin ',
unistr('        -- 1. Loop principal de configura\00E7\00F5es (Filtro otimizado)'),
'        for c_registro in (',
'            select * from srv_entidade_ng_permite_anexo ',
'        ) loop',
'            ',
'            -- 2. Loop de Tenancy',
'            for c_tenant in (select id from mpd_tenant) loop',
'                ',
unistr('                -- Verifica exist\00EAncia para decidir entre inclus\00E3o ou altera\00E7\00E3o'),
'                bo_mpd_entidade_ng_permite_anexo.verifica_registro(c_tenant.id, c_registro.id_entidade, l_id, l_data_alteracao);',
'                ',
'                if l_data_alteracao is not null then',
'                    bo_mpd_entidade_ng_permite_anexo.altera_registro(',
'                        p_id_tenant => c_tenant.id,',
'                        p_id_entidade => c_registro.id_entidade,',
'                        p_lista_referencia_documento => c_registro.lista_referencia_documento, ',
'',
unistr('                        p_id => l_id, --id retornado da fun\00E7\00E3o'),
'                        p_data_alteracao => l_data_alteracao, ',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    );   ',
'                else',
'                    l_id := null;',
'                    bo_mpd_entidade_ng_permite_anexo.inclui_registro(',
'                        p_id_tenant => c_tenant.id,',
'                        p_id_entidade => c_registro.id_entidade,',
'                        p_lista_referencia_documento => c_registro.lista_referencia_documento, ',
'',
'                        p_id => l_id, ',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    ); ',
'                end if;',
'',
unistr('                -- Interrompe o processamento do tenant se houver erro cr\00EDtico'),
'                exit when v_messages.count > 0;',
'            end loop; ',
'            ',
'            exit when v_messages.count > 0;',
'        end loop; ',
'',
unistr('        -- 4. Finaliza\00E7\00E3o'),
'        if v_messages.count = 0 then',
'            apaga_mpd_entidade_ng_permite_anexo(p_sucesso, v_messages);',
'        end if;',
'',
'        p_messages := v_messages;     ',
'    end sincroniza_mpd_entidade_ng_permite_anexo; ',
'',
'    procedure apaga_mpd_entidade_ng_permite_anexo (',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_mpd_entidade_ng_permite_anexo in (',
'            select id from mpd_entidade_ng_permite_anexo a',
'            where not exists (select id from srv_entidade_ng_permite_anexo b where a.id_entidade = b.id_entidade)',
'        ) loop',
'            bo_mpd_entidade_ng_permite_anexo.exclui_registro(',
'                p_id => c_mpd_entidade_ng_permite_anexo.id, ',
'                p_encadeado => true, ',
'                p_sucesso => p_sucesso, ',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;',
'        end loop;',
'        p_messages := v_messages;',
'    end apaga_mpd_entidade_ng_permite_anexo;',
'',
'    procedure sincroniza_mpd_configuracao_ng (',
'        p_id          in srv_sistema_versionado.id%type,',
'        p_encadeado   in boolean default false,',
'        p_sucesso     out clob,',
'        p_messages    out pkg_mensagem.message_record_table',
'    ) is',
'        l_id                       mpd_configuracao_ng.id%type;',
'        l_data_alteracao           mpd_configuracao_ng.data_alteracao%type;',
'        l_id_dominio               mpd_configuracao_ng_dominio.id%type;',
'        l_data_alteracao_dominio   mpd_configuracao_ng_dominio.data_alteracao%type;',
'        v_messages                 pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'',
unistr('        -- Sub-procedure para evitar repeti\00E7\00E3o da l\00F3gica de dom\00EDnio'),
'        procedure sincroniza_dominios_internos(',
'            p_id_tenant       in mpd_tenant.id%type,',
'            p_id_config_pai   in mpd_configuracao_ng.id%type,',
'            p_id_srv_pai      in srv_configuracao_ng.id%type',
'        ) is',
'        begin',
'            for c_dominio in (',
'                select * from srv_configuracao_ng_dominio where id_configuracao = p_id_srv_pai',
'            ) loop   ',
'                bo_mpd_configuracao_ng_dominio.verifica_registro(p_id_tenant, p_id_config_pai, c_dominio.codigo_dominio, l_id_dominio, l_data_alteracao_dominio);',
'                ',
'                if l_data_alteracao_dominio is not null then',
'                    bo_mpd_configuracao_ng_dominio.altera_registro(',
'                        p_id_tenant         => p_id_tenant,',
'                        p_id_configuracao   => p_id_config_pai,',
'                        p_codigo_dominio    => c_dominio.codigo_dominio,',
'                        p_descricao_dominio => c_dominio.descricao_dominio, ',
'                        p_id                => l_id_dominio, ',
'                        p_data_alteracao    => l_data_alteracao_dominio,                               ',
'                        p_encadeado         => true, ',
'                        p_sucesso           => p_sucesso,',
'                        p_messages          => v_messages',
'                    );                                      ',
'                else',
'                    l_id_dominio := null;',
'                    bo_mpd_configuracao_ng_dominio.inclui_registro(',
'                        p_id_tenant         => p_id_tenant,',
'                        p_id_configuracao   => p_id_config_pai,',
'                        p_codigo_dominio    => c_dominio.codigo_dominio,',
'                        p_descricao_dominio => c_dominio.descricao_dominio, ',
'                        p_id                => l_id_dominio, ',
'                        p_encadeado         => true, ',
'                        p_sucesso           => p_sucesso,',
'                        p_messages          => v_messages',
'                    );                                      ',
'                end if;',
'                ',
'                -- exit when v_messages.count > 0;',
'            end loop;',
'        end sincroniza_dominios_internos;',
'',
'    begin ',
unistr('        -- 1. Loop principal de configura\00E7\00F5es (Filtro otimizado)'),
'        for c_registro in (',
'            select * from srv_configuracao_ng ',
unistr('            where ind_situacao = ''D'' -- Removido upper desnecess\00E1rio se o padr\00E3o for conhecido'),
'        ) loop',
'            ',
'            -- 2. Loop de Tenancy',
'            for c_tenant in (select id from mpd_tenant) loop',
'                ',
unistr('                -- Verifica exist\00EAncia para decidir entre inclus\00E3o ou altera\00E7\00E3o'),
'                bo_mpd_configuracao_ng.verifica_registro(c_tenant.id, c_registro.codigo_configuracao, l_id, l_data_alteracao);',
'                ',
'                if l_data_alteracao is not null then',
'                    bo_mpd_configuracao_ng.altera_registro(',
'                        p_id_tenant => c_tenant.id,',
'                        p_ind_grupo_funcionalidade => c_registro.ind_grupo_funcionalidade,',
'                        p_codigo_configuracao => c_registro.codigo_configuracao,',
'                        p_descricao_configuracao => c_registro.descricao_configuracao,',
'                        p_ind_tipo_dado => c_registro.ind_tipo_dado,',
'                        p_id_entidade => c_registro.id_entidade,',
'                        p_quantidade_decimal => c_registro.quantidade_decimal,',
'',
unistr('                        p_id => l_id, --id retornado da fun\00E7\00E3o'),
'                        p_data_alteracao => l_data_alteracao, ',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    );   ',
'                else',
'                    l_id := null;',
'                    bo_mpd_configuracao_ng.inclui_registro(',
'                        p_id_tenant => c_tenant.id,',
'                        p_ind_grupo_funcionalidade => c_registro.ind_grupo_funcionalidade,',
'                        p_codigo_configuracao => c_registro.codigo_configuracao,',
'                        p_descricao_configuracao => c_registro.descricao_configuracao,',
'                        p_ind_tipo_dado => c_registro.ind_tipo_dado,',
'                        p_id_entidade => c_registro.id_entidade,',
'                        p_quantidade_decimal => c_registro.quantidade_decimal,',
'',
'                        p_valor_inteiro => null,',
'                        p_valor_decimal => null,',
'                        p_valor_string => null,',
'                        p_valor_data => null,',
'                        p_valor_data_hora => null,',
'                        p_id_registro => null,',
'                        p_valor_dominio => null, ',
'',
'                        p_id => l_id, ',
'                        p_encadeado => true, ',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    ); ',
'                end if;',
'',
'                commit;',
'',
unistr('                -- 3. Sincroniza dom\00EDnios apenas se n\00E3o houve erro no pai'),
'                if v_messages.count = 0 then',
'                    sincroniza_dominios_internos(c_tenant.id, l_id, c_registro.id);',
'                end if;',
'',
unistr('                -- Interrompe o processamento do tenant se houver erro cr\00EDtico'),
'                exit when v_messages.count > 0;',
'            end loop; ',
'            ',
'            exit when v_messages.count > 0;',
'        end loop; ',
'',
unistr('        -- 4. Finaliza\00E7\00E3o'),
'        if v_messages.count = 0 then',
'            apaga_mpd_configuracao_ng(p_sucesso, v_messages);',
'        end if;',
'',
'        p_messages := v_messages;     ',
'    end sincroniza_mpd_configuracao_ng; ',
'',
'    procedure apaga_mpd_configuracao_ng (',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        for c_mpd_configuracao_ng in (',
'            select id from mpd_configuracao_ng a',
'            where not exists (select id from srv_configuracao_ng b where a.codigo_configuracao = b.codigo_configuracao)',
'        ) loop',
'            bo_mpd_configuracao_ng.exclui_registro(',
'                p_id => c_mpd_configuracao_ng.id, ',
'                p_encadeado => true, ',
'                p_sucesso => p_sucesso, ',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                exit;',
'            end if;',
'        end loop;',
'        p_messages := v_messages;',
'    end apaga_mpd_configuracao_ng;   ',
'',
'    /* ******** ******** ******** ******** ******** */',
'    /* ******** FIM SINCRONIZACAO          ******** */',
'    /* ******** ******** ******** ******** ******** */',
'    procedure descontinuar_versao (',
'        p_id        in srv_sistema_versionado.id%type,',
'        p_pagina    in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        p_data_alteracao srv_sistema_versionado.data_alteracao%type;',
'    begin',
'        /* Verifica se o id informado existe */',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(1) := ''Registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if; ',
' ',
'        /* Seta valores passados por parametros */',
'        v_new.situacao := ''d'';',
'        v_new.data_descontinuidade := sysdate;',
'        v_new.id := p_id;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate; ',
' ',
'        /* Executa rotinas antes de alterar */',
'        -- p_messages := antes_alterar;',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if;',
'',
'        /* Executa o update */',
'        update srv_sistema_versionado',
'        set',
'            situacao = v_new.situacao,',
'            data_descontinuidade = v_new.data_descontinuidade',
'        where',
'            id = p_id;',
'',
'        /* Executa rotinas depois de alterar */',
'        -- p_messages := depois_alterar;',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_sucesso := pk_constants.c_msg_success;',
'            if not p_encadeado then',
'                p_messages := v_messages;',
'                pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'            end if;',
'        end if;',
'',
'    exception ',
'            when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                v_parametro(2) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        if not p_encadeado then',
'            pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'        end if;',
'    end descontinuar_versao;',
'',
'    procedure ativar_versao (',
'        p_id        in srv_sistema_versionado.id%type,',
'        p_pagina    in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        p_data_alteracao srv_sistema_versionado.data_alteracao%type;',
'    begin',
'        /* Verifica se o id informado existe */',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(1) := ''Registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if; ',
' ',
'        /* Seta valores passados por parametros */',
'        v_new.situacao := ''a'';',
'        v_new.data_descontinuidade := null;',
'        v_new.id := p_id;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate; ',
' ',
'        /* Executa rotinas antes de alterar */',
'        -- p_messages := antes_alterar;',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if;',
'',
'        /* Executa o update */',
'        update srv_sistema_versionado',
'        set',
'            situacao = v_new.situacao,',
'            data_descontinuidade = v_new.data_descontinuidade,',
'            id_usuario_alterou = v_new.id_usuario_alterou,',
'            data_alteracao = v_new.data_alteracao',
'        where',
'            id = p_id;',
'',
'        /* Executa rotinas depois de alterar */',
'        -- p_messages := depois_alterar;',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_sucesso := pk_constants.c_msg_success;',
'            if not p_encadeado then',
'                p_messages := v_messages;',
'                pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'            end if;',
'        end if;',
'',
'    exception ',
'            when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                v_parametro(2) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        if not p_encadeado then',
'            pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'        end if;',
'    end ativar_versao;',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_srv_sistema_versionado;',
'/'))
);
end;
/
