prompt --application/deployment/install/install_bo_srv_texto
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(149414424854590823)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_SRV_TEXTO'
,p_sequence=>80
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package            bo_srv_texto ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old srv_texto%rowtype;',
'    v_new srv_texto%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao srv_texto.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out srv_texto.id%type',
'    );',
'    procedure grava(',
'        p_id in srv_texto.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(  ',
'        p_id_tenant in srv_texto.id_tenant%type,',
'        p_id_sistema_versionado in srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type,',
'        p_tag in srv_texto.tag%type,',
'        p_Necessita_revisao in srv_texto.Necessita_revisao%type,',
'        p_apex_traduzira in srv_texto.apex_traduzira%type,',
'        p_tipo_texto in srv_texto.tipo_texto%type, ',
'        p_id out srv_texto.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );   ',
'    procedure altera_registro(  ',
'        p_id_tenant in srv_texto.id_tenant%type,',
'        p_id_sistema_versionado in srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type,',
'        p_tag in srv_texto.tag%type,',
'        p_Necessita_revisao in srv_texto.Necessita_revisao%type,',
'        p_apex_traduzira in srv_texto.apex_traduzira%type,',
'        p_tipo_texto in srv_texto.tipo_texto%type, ',
'        p_id in srv_texto.id%type, ',
'        p_data_alteracao in srv_texto.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure copia_registro(  ',
'        p_id_tenant out srv_texto.id_tenant%type,',
'        p_id_sistema_versionado out srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada out srv_texto.id_aplicacao_versionada%type,',
'        p_tag out srv_texto.tag%type,',
'        p_Necessita_revisao out srv_texto.Necessita_revisao%type,',
'        p_apex_traduzira out srv_texto.apex_traduzira%type,',
'        p_tipo_texto out srv_texto.tipo_texto%type, ',
'        p_id in out srv_texto.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure exclui_registro(  ',
'        p_id in srv_texto.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos padr\00E3o'),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in srv_texto.id%type ',
'    );    ',
'    function verifica_registro( ',
'        p_id in srv_texto.id%type ',
'    ) return boolean;    ',
'    procedure verifica_registro_em_uso( ',
'        p_id in srv_texto.id%type ',
'    );    ',
'    procedure verifica_data_alteracao ( ',
'        p_data_alteracao in srv_texto.data_alteracao%type ',
'    ); ',
'    procedure valida;     ',
'    procedure valida_id_tenant(p_id_tenant in srv_texto.id_tenant%type); ',
'    procedure valida_id_sistema_versionado(p_id_sistema_versionado in srv_texto.id_sistema_versionado%type); ',
'    procedure valida_id_aplicacao_versionada(p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type); ',
'    procedure valida_tag(p_tag in srv_texto.tag%type); ',
'    procedure valida_Necessita_revisao(p_Necessita_revisao in srv_texto.Necessita_revisao%type); ',
'    procedure valida_apex_traduzira(p_apex_traduzira in srv_texto.apex_traduzira%type); ',
'    procedure valida_tipo_texto(p_tipo_texto in srv_texto.tipo_texto%type); ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'    procedure hook_valida_id_tenant(p_id_tenant in srv_texto.id_tenant%type); ',
'    procedure hook_valida_id_sistema_versionado(p_id_sistema_versionado in srv_texto.id_sistema_versionado%type); ',
'    procedure hook_valida_id_aplicacao_versionada(p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type); ',
'    procedure hook_valida_tag(p_tag in srv_texto.tag%type); ',
'    procedure hook_valida_Necessita_revisao(p_Necessita_revisao in srv_texto.Necessita_revisao%type); ',
'    procedure hook_valida_apex_traduzira(p_apex_traduzira in srv_texto.apex_traduzira%type); ',
'    procedure hook_valida_tipo_texto(p_tipo_texto in srv_texto.tipo_texto%type); ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir;',
'    procedure grava_log_alterar;',
'    procedure grava_log_excluir;',
'    function row_to_json(p_rec in srv_texto%rowtype) return clob;  ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    v_new_srv_texto_traduzido srv_texto_traduzido%rowtype;',
'    v_old_srv_texto_traduzido srv_texto_traduzido%rowtype;',
'    v_operacao varchar2(256);     ',
'',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
'    -- ',
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
