'            p_encadeado => true,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''EXCLUI_REGISTRO_POR_TAG'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o por tag. TAG='' || p_tag'),
