'    procedure inclui_srv_texto_traduzido(',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
unistr('        -- Vari\00E1vel para armazenar o ID do registro inserido'),
'        l_id_texto_traduzido number;',
'',
unistr('        -- Cursor para buscar todos os idiomas dispon\00EDveis na tabela srv_idioma'),
'        cursor c_idiomas is',
'            select id, codigo',
