'    function retorna_id_tag_origem(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return number is',
'        l_tag       varchar2(4000);',
'        p_id_origem number;        ',
'        l_count     number;',
'        l_valor_1   varchar2(4000);',
'        l_valor_2   varchar2(4000);        ',
'        l_sql       varchar2(4000); ',
'    begin',
'        l_tag := trim(p_tag);',
'        l_count := regexp_count(l_tag, ''\.'');',
'',
'        if l_count > 0 then',
'            l_valor_1 := lower(regexp_substr(l_tag, ''[^.]+'', 1, 2));',
'        end if;',
'',
'        if l_count > 1 then',
'            l_valor_2 := lower(substr(l_tag, instr(l_tag, ''.'', 1, 2) + 1));',
'        end if;',
'',
'        if p_tipo_texto in (1, 3) then',
'            l_valor_1 := lower(regexp_substr(l_tag, ''\.(.*)'', 1, 1, null, 1));',
'            l_sql := ''select id from srv_aplicacao_texto where lower(tag) = :1'';',
'            execute immediate l_sql into p_id_origem using l_valor_1;  ',
'        elsif p_tipo_texto = 2 then',
'            l_sql := ''select a.id from srv_entidade_coluna a '' ||',
'                     ''join srv_entidade b on b.id = a.id_entidade '' ||',
'                     ''where lower(nome_entidade) = :1 and lower(trim(nome_coluna)) = :2'';',
'            execute immediate l_sql into p_id_origem using l_valor_1, l_valor_2;',
'        elsif p_tipo_texto = 4 then',
'            l_sql := ''select a.id from srv_artefato_versionado a ''||',
'                     ''join srv_artefato b on b.id = a.id_artefato ''||',
'                     ''where lower(b.codigo_artefato) = :1 and a.situacao = ''''A'''' fetch first 1 rows only'';',
'            execute immediate l_sql into p_id_origem using l_valor_1;',
'        elsif p_tipo_texto = 5 then',
'            l_sql := ''select id from srv_aplicacao_mensagem where lower(codigo_mensagem) = :1'';',
'            execute immediate l_sql into p_id_origem using l_valor_1;            ',
'        elsif p_tipo_texto = 6 then',
'            l_sql := ''select b.id from srv_dominio a '' ||',
'                     ''join srv_dominio_valor b on b.id_dominio = a.id '' || ',
'                     ''where b.id_dominio = :1 and lower(b.valor) = :2'';',
'            execute immediate l_sql into p_id_origem using l_valor_1, l_valor_2;',
'        elsif p_tipo_texto = 7 then',
'            p_id_origem := l_valor_1;            ',
'        elsif p_tipo_texto = 8 then',
'            p_id_origem := l_valor_1;            ',
'        end if;',
'',
'        return p_id_origem;',
'',
'    end retorna_id_tag_origem;',
'',
'    function retorna_pagina_id_origem(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return number is',
'        l_tag     varchar2(4000);',
'        l_retorno number;',
'    begin',
'        if p_tipo_texto in (1, 3) then',
'            l_retorno := ''229'';',
'        elsif p_tipo_texto = 2 then',
'            l_retorno := ''145'';',
'        elsif p_tipo_texto = 4 then',
'            l_retorno := ''150'';',
'        elsif p_tipo_texto = 5 then',
'            l_retorno := ''161'';',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := ''227'';',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := ''115'';',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := ''152'';',
'        end if;    ',
'        l_tag := retorna_id_tag_origem(p_tag, p_tipo_texto);',
'        if l_tag is not null then',
'            return l_retorno;',
'        else',
'           null;',
'        end if;',
'    end retorna_pagina_id_origem;',
'',
'    function retorna_pagina_opcoes_id_origem(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return number is',
'        l_tag     varchar2(4000);',
'        l_retorno number;',
'    begin',
'        if p_tipo_texto in (1, 3) then',
'            l_retorno := ''228'';',
'        elsif p_tipo_texto = 2 then',
'            l_retorno := ''143'';',
'        elsif p_tipo_texto = 4 then',
'            l_retorno := ''149'';',
'        elsif p_tipo_texto = 5 then',
'            l_retorno := ''160'';',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := ''227'';',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := ''114'';',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := ''104'';',
'        end if;    ',
'        l_tag := retorna_id_tag_origem(trim(p_tag), p_tipo_texto);',
'        if l_tag is not null then',
'            return l_retorno;',
'        else',
'           null;',
'        end if;',
'    end retorna_pagina_opcoes_id_origem;   ',
'',
'    procedure gerar_mpd_traducao(',
'        p_pagina in number default 0,         ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is    ',
'    begin',
