'',
'    procedure gerar_mpd_traducao(',
'        p_esquema in varchar2,',
'        p_pagina in number default 0,         ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
'        l_maior_data_alteracao mpd_traducao.data_alteracao%type;',
'        l_retorno clob;',
'        l_sql clob;',
'        l_new_id mpd_traducao.id%type;',
'        l_conta number;',
'        i number := 0;',
'',
'        procedure processa_traducao(',
'            p_texto in varchar2, ',
'            p_tag_suffix in varchar2, ',
'            p_id_sistema_versionado in number, ',
'            p_id_aplicacao_versionada in number, ',
'            p_tag in varchar2, ',
'            p_id_idioma in number, ',
'            p_apex_traduzira in number',
'        ) is',
'            l_id_mpd_traducao number;',
'            l_id_mpd_traducao_apex number;',
'            l_data_alteracao mpd_traducao.data_alteracao%type;',
'            l_data_alteracao_apex mpd_traducao_apex.data_alteracao%type;',
'        begin',
'            if p_texto is not null then',
'                bo_mpd_traducao.retorna_id(p_tag || p_tag_suffix, p_id_idioma, l_id_mpd_traducao, l_data_alteracao);                ',
'                if l_id_mpd_traducao is not null then',
'                    bo_mpd_traducao.altera_registro(',
'                        p_id_sistema_versionado => p_id_sistema_versionado,',
'                        p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                        p_tag => p_tag || p_tag_suffix,',
'                        p_id_idioma => p_id_idioma,',
'                        p_texto_traduzido => p_texto, ',
'                        p_id => l_id_mpd_traducao, ',
'                        p_data_alteracao => l_data_alteracao,',
'                        p_esquema => p_esquema, ',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    );',
'                else',
'                    bo_mpd_traducao.inclui_registro(',
'                        p_id_sistema_versionado => p_id_sistema_versionado,',
'                        p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                        p_tag => p_tag || p_tag_suffix,',
'                        p_id_idioma => p_id_idioma,',
'                        p_texto_traduzido => p_texto, ',
'                        p_id => l_new_id, ',
'                        p_esquema => p_esquema, ',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    );',
'                end if;  ',
'                if p_apex_traduzira = 1 then  ',
'                    bo_mpd_traducao_apex.retorna_id(p_tag || p_tag_suffix, p_id_idioma, l_id_mpd_traducao_apex, l_data_alteracao_apex);                ',
'                    if l_id_mpd_traducao_apex is not null then',
'                        bo_mpd_traducao_apex.altera_registro(',
'                            p_id_sistema_versionado => p_id_sistema_versionado,',
'                            p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                            p_tag => p_tag || p_tag_suffix,',
'                            p_id_idioma => p_id_idioma,',
'                            p_texto_traduzido => p_texto, ',
'                            p_id => l_id_mpd_traducao_apex, ',
'                            p_data_alteracao => l_data_alteracao_apex,',
'                            p_esquema => p_esquema, ',
'                            p_encadeado => true,',
'                            p_sucesso => p_sucesso,',
'                            p_messages => v_messages',
'                        );                ',
'                    else',
'                        bo_mpd_traducao_apex.inclui_registro(',
'                            p_id_sistema_versionado => p_id_sistema_versionado,',
'                            p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                            p_tag => p_tag || p_tag_suffix,',
'                            p_id_idioma => p_id_idioma,',
'                            p_texto_traduzido => p_texto, ',
'                            p_id => l_new_id, ',
'                            p_esquema => p_esquema, ',
'                            p_encadeado => true,',
'                            p_sucesso => p_sucesso,',
'                            p_messages => v_messages',
'                        );',
'                    end if;    ',
'                end if;    ',
'            end if;',
'        end processa_traducao;',
'',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''GERAR_MPD_TRADUCAO'',',
unistr('            p_ds_mensagem => ''In\00EDcio da gera\00E7\00E3o de MPD tradu\00E7\00E3o. ESQUEMA='' || p_esquema'),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''exportar textos'';   ',
'        v_pagina := p_pagina; ',
'        valida_esquema(p_esquema);',
'',
'        if v_messages.coun'))
);
