'',
'        --Gerar srv_texto a partir da varredura da tabela srv_grupo_funcionalidade',
'        for c_cursor in (select * from srv_grupo_funcionalidade) loop',
'            bo_srv_grupo_funcionalidade.altera_registro(',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_id_grupo_pai => c_cursor.id_grupo_pai,',
'                p_titulo => c_cursor.titulo,',
'                p_ordenacao => c_cursor.ordenacao,',
'                p_id_artefato_versionado => c_cursor.id_artefato_versionado,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;    ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_menu',
'        for c_cursor in (select * from srv_menu) loop',
'            bo_srv_menu.altera_registro(',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_menu_pai => c_cursor.id_menu_pai,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_titulo => c_cursor.titulo,',
'                p_ordenacao => c_cursor.ordenacao,',
'                p_icone => c_cursor.icone,',
'                p_ind_sincronizar => c_cursor.ind_sincronizar,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;    ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_artefato_versionado',
'        for c_cursor in (select * from srv_artefato_versionado) loop',
'            bo_srv_artefato_versionado.altera_registro(',
'                p_id_aplicacao_versionada => c_cursor.id_aplicacao_versionada,',
'                p_especificacao_tecnica => c_cursor.especificacao_tecnica,',
'                p_situacao => c_cursor.situacao,',
'                p_data_checkin => c_cursor.data_checkin,',
'                p_id_usuario_checkin => c_cursor.id_usuario_checkin,',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_artefato => c_cursor.id_artefato,',
'                p_titulo => c_cursor.titulo,',
'                p_help => c_cursor.help,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;    ',
'',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_acao, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('            p_ds_mensagem => ''Fim da gera\00E7\00E3o de srv_texto'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('                    p_ds_mensagem => ''Erro de neg\00F3cio na gera\00E7\00E3o de srv_texto'''),
'                );',
'',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na gera\00E7\00E3o de srv_texto'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);  ',
'',
'    end gerar_srv_texto;',
'',
'    procedure altera_registro_necessita_revisao(',
'        p_id                in srv_texto.id%type,',
'        p_necessita_revisao in srv_texto.necessita_revisao%type,',
'        p_encadeado         in boolean default false,',
'        p_sucesso           out clob,',
'        p_messages          out pkg_mensagem.message_record_table    ',
'    ) is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_NECESSITA_REVISAO'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o de necessita_revisao. ID='' || p_id'),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_texto.altera_registro_necessita_revisao''; ',
'        v_operacao := ''altera_registro_necessita_revisao'';',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from srv_texto where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_data_alteracao := v_new.data_alteracao;',
'        v_new.Necessita_revisao := p_Necessita_revisao;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_NECESSITA_REVISAO'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o de necessita_revisao. ID='' || p_id'),
'        );',
'    exception',
'        when others then',
'            pkg_log_execucao.log_erro(',
'                p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                p_nm_rotina   => ''ALTERA_REGISTRO_NECESSITA_REVISAO'',',
unistr('                p_ds_mensagem => ''Erro na altera\00E7\00E3o de necessita_revisao. ID='' || p_id,'),
'                p_ds_erro     => sqlerrm',
'            );',
'            raise;',
'    end altera_registro_necessita_revisao;',
'',
'    function url_com_parametro (',
'        p_id varchar2,',
'        p_pagina number,',
'        p_parametro varchar2 default null',
'    ) return varchar2 is',
'    begin',
'        return APEX_UTIL.PREPARE_URL(',
'            p_url => ''f?p=''||APEX_APPLICATION.g_flow_id||'':''||p_pagina||'':''||APEX_CUSTOM_AUTH.GET_SESSION_ID||''::NO::P''||p_pagina||''_ID,P''||p_pagina||''_CODIGO_ARTEFATO:''||p_id||'',''||p_parametro,',
'            p_checksum_type => ''SESSION'');',
'    end url_com_parametro;',
'',
'    function url_mais_detalhes (',
'        p_id varchar2,',
'        p_pagina number,',
'        p_parametro varchar2 default null',
'    ) return varchar2 is',
'    begin',
'        return APEX_UTIL.PREPARE_URL(',
'            p_url => ''f?p=''||APEX_APPLICATION.g_flow_id||'':''||p_pagina||'':''||APEX_CUSTOM_AUTH.GET_SESSION_ID||''::NO:''||p_pagina||'':P''||p_pagina||''_PARAMETRO,P''||p_pagina||''_CODIGO_ARTEFATO:''||p_id||'',''||p_parametro,',
'            p_checksum_type => ''SESSION'');',
'    end url_mais_detalhes;',
'',
'    function retorna_codigo_artefato(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return varchar2 is',
'        l_tag     varchar2(4000);',
'        l_retorno varchar2(4000);',
'    begin',
'        if p_tipo_texto in (1) then',
'            l_retorno := ''TD287'';',
'        elsif p_tipo_texto = 2 then',
'            l_retorno := ''TD294'';',
'        elsif p_tipo_texto = 3 then',
'            l_retorno := ''TD287'';',
'        elsif p_tipo_texto = 4 then',
'            l_retorno := ''TD295'';',
'        elsif p_tipo_texto = 5 then',
'            l_retorno := ''TD296'';',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := ''TD297'';',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := ''TD298'';',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := ''TD299'';',
'        end if;    ',
'        l_tag := retorna_id_tag_origem(p_tag, p_tipo_texto);',
'        if l_tag is not null then',
'            return l_retorno;',
'        else',
'           null;',
'        end if;',
'    end retorna_codigo_artefato;',
'',
'    function botao_opcao(',
'        p_url in varchar2',
'    ) return varchar2 is',
'        l_html varchar2(10000);',
'        l_url  varchar2(10000) := p_url;',
'    begin',
'        l_html := ''<div style="display: flex;align-items: center; justify-content: flex-end; flex-grow: 1;"><a href="''||l_url||''" style="color: var(--a-button-state-text-color, var(--a-button-type-text-color, var(--a-button-text-color, inherit)));" c'
||'lass="fa fa-edit"></a></div>'';',
'        return l_html;',
'    end botao_opcao;',
'',
'    procedure valida_esquema(p_esquema in varchar2) ',
'    is ',
'        l_label_item pkg_mensagem.paramentros;',
'    begin ',
'        if p_esquema is null then ',
'            l_label_item(1) := pkg_ui.retorna_label_coluna(''campo.154.esquema.l''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''esquema'',',
'                p_parametro => l_label_item,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'    end valida_esquema; ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_srv_texto;',
'/'))
);
end;
/
