'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_srv_texto'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_texto.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            id_sistema_versionado,',
'            id_aplicacao_versionada,',
'            tag,',
'            Necessita_revisao,',
'            apex_traduzira,',
'            tipo_texto, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_id_sistema_versionado,',
'            p_id_aplicacao_versionada,',
'            p_tag,',
'            p_Necessita_revisao,',
'            p_apex_traduzira,',
'            p_tipo_texto, ',
'            p_id ',
'        from srv_texto ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_srv_texto'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_srv_texto'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in srv_texto.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_srv_texto'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_texto.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from srv_texto where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from srv_texto where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_srv_texto'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_srv_texto'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
' '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(231233347283933450)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'               );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_srv_texto'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in srv_texto.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from srv_texto where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in srv_texto.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from srv_texto where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in srv_texto.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''srv_texto'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''srv_texto'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in srv_texto.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_sistema_versionado */ '),
'        valida_id_sistema_versionado(v_new.id_sistema_versionado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_aplicacao_versionada */ '),
'        valida_id_aplicacao_versionada(v_new.id_aplicacao_versionada);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo tag */ '),
'        valida_tag(v_new.tag);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo Necessita_revisao */ '),
'        valida_Necessita_revisao(v_new.Necessita_revisao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo apex_traduzira */ '),
'        valida_apex_traduzira(v_new.apex_traduzira);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo tipo_texto */ '),
'        valida_tipo_texto(v_new.tipo_texto);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in srv_texto.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_id_sistema_versionado(p_id_sistema_versionado in srv_texto.id_sistema_versionado%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_sistema_versionado is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.id_sistema_versionado''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_sistema_versionado(p_id_sistema_versionado);',
'    end valida_id_sistema_versionado;    ',
'',
'    procedure valida_id_aplicacao_versionada(p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_aplicacao_versionada is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.id_aplicacao_versionada''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_aplicacao_versionada(p_id_aplicacao_versionada);',
'    end valida_id_aplicacao_versionada;    ',
'',
'    procedure valida_tag(p_tag in srv_texto.tag%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_tag is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.tag''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''tag'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from srv_texto where lower(trim(tag)) = lower(trim(p_tag)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from srv_texto where lower(trim(tag)) = lower(trim(p_tag)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.tag'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''tag'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_tag(p_tag);',
'    end valida_tag;     ',
'',
'    procedure valida_Necessita_revisao(p_Necessita_revisao in srv_texto.Necessita_revisao%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_Necessita_revisao is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.Necessita_revisao''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''Necessita_revisao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_Necessita_revisao(p_Necessita_revisao);',
'    end valida_Necessita_revisao;     ',
'',
'    procedure valida_apex_traduzira(p_apex_traduzira in srv_texto.apex_traduzira%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_apex_traduzira is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.apex_traduzira''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''apex_traduzira'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_apex_traduzira(p_apex_traduzira);',
'    end valida_apex_traduzira;     ',
'',
'    procedure valida_tipo_texto(p_tipo_texto in srv_texto.tipo_texto%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_tipo_texto is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''srv_texto.tipo_texto''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''tipo_texto'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_tipo_texto(p_tipo_texto);',
'    end valida_tipo_texto;     ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
