'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_texto'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_texto'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_texto'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_texto'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''srv_texto'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''srv_texto'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in srv_texto%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_sistema_versionado'', p_rec.id_sistema_versionado, true);',
'        apex_json.write(''id_aplicacao_versionada'', p_rec.id_aplicacao_versionada, true);',
'        apex_json.write(''tag'', p_rec.tag, true);',
'        apex_json.write(''Necessita_revisao'', p_rec.Necessita_revisao, true);',
'        apex_json.write(''apex_traduzira'', p_rec.apex_traduzira, true);',
'        apex_json.write(''tipo_texto'', p_rec.tipo_texto, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        inclui_srv_texto_traduzido(',
'            p_encadeado => true,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        if v_operacao is null then',
'            altera_srv_texto_traduzido(',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure inclui_registro(  ',
'        p_id_tenant in srv_texto.id_tenant%type,',
'        p_id_sistema_versionado in srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type,',
'        p_tag in srv_texto.tag%type,',
'        p_necessita_revisao in srv_texto.necessita_revisao%type,',
'        p_apex_traduzira in srv_texto.apex_traduzira%type,',
'        p_tipo_texto in srv_texto.tipo_texto%type, ',
'        p_id out srv_texto.id%type, ',
'        p_id_idioma in srv_texto_traduzido.id_idioma%type default null,',
'        p_label in srv_texto_traduzido.label%type,',
'        p_instrucao in srv_texto_traduzido.instrucao%type,',
'        p_help in srv_texto_traduzido.help%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is  ',
'        l_id_idioma srv_texto_traduzido.id_idioma%type := p_id_idioma;',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''INCLUI_REGISTRO2'',',
unistr('            p_ds_mensagem => ''In\00EDcio da inclus\00E3o de srv_texto com tradu\00E7\00E3o'''),
'        );',
'',
'        v_parametro(0) := ''bo_srv_texto.inclui_registro2'';   ',
'        v_pagina := p_pagina; ',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_sistema_versionado := p_id_sistema_versionado;',
'        v_new.id_aplicacao_versionada := p_id_aplicacao_versionada;',
'        v_new.tag := retorna_tag(p_tag,p_tipo_texto);',
'        v_new.necessita_revisao := p_necessita_revisao;',
'        v_new.apex_traduzira := p_apex_traduzira;',
'        v_new.tipo_texto := p_tipo_texto; ',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao := sysdate; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate; ',
'        --',
'        if l_id_idioma is null then',
'            select id into l_id_idioma from srv_idioma where upper(codigo) = upper(''pt-br'');',
'        end if;    ',
'        v_new_srv_texto_traduzido.id_tenant := v_new.id_tenant;',
'        v_new_srv_texto_traduzido.id_texto := p_id;',
'        v_new_srv_texto_traduzido.id_idioma := l_id_idioma;',
'        v_new_srv_texto_traduzido.label := p_label;',
'        v_new_srv_texto_traduzido.instrucao := p_instrucao;',
'        v_new_srv_texto_traduzido.help := p_help;',
'        v_new_srv_texto_traduzido.necessita_revisao := 1;        ',
'        --',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''INCLUI_REGISTRO2'',',
unistr('            p_ds_mensagem => ''Fim da inclus\00E3o de srv_texto com tradu\00E7\00E3o. ID='' || p_id'),
'        );',
'    exception',
'        when others then',
'            pkg_log_execucao.log_erro(',
'                p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                p_nm_rotina   => ''INCLUI_REGISTRO2'',',
unistr('                p_ds_mensagem => ''Erro na inclus\00E3o de srv_texto com tradu\00E7\00E3o'','),
'                p_ds_erro     => sqlerrm',
'            );',
'            raise;',
'    end;',
'    --',
'    procedure altera_registro(  ',
'        p_id_tenant in srv_texto.id_tenant%type,',
'        p_id_sistema_versionado in srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type,',
'        p_tag in srv_texto.tag%type,',
'        p_necessita_revisao in srv_texto.necessita_revisao%type,',
'        p_apex_traduzira in srv_texto.apex_traduzira%type,',
'        p_tipo_texto in srv_texto.tipo_texto%type, ',
'        p_id in srv_texto.id%type, ',
'        p_id_idioma in srv_texto_traduzido.id_idioma%type default null,',
'        p_label in srv_texto_traduzido.label%type,',
'        p_instrucao in srv_texto_traduzido.instrucao%type,',
'        p_help in srv_texto_traduzido.help%type,',
'        p_data_alteracao in srv_texto.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'        l_id_idioma srv_texto_traduzido.id_idioma%type := p_id_idioma;',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO2'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o de srv_texto com tradu\00E7\00E3o. ID='' || p_id'),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_texto.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from srv_texto where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_sistema_versionado := p_id_sistema_versionado;',
'        v_new.id_aplicacao_versionada := p_id_aplicacao_versionada;',
'        v_new.tag := retorna_tag(p_tag,p_tipo_texto);',
'        v_new.Necessita_revisao := p_Necessita_revisao;',
'        v_new.apex_traduzira := p_apex_traduzira;',
'        v_new.tipo_texto := p_tipo_texto; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        /* Carrega as variaveis da tabelas srv_texto_traduzido*/',
'        if l_id_idioma is null then',
'            select id into l_id_idioma from srv_idioma where upper(codigo) = upper(''pt-br'');',
'        end if;    ',
'        v_new_srv_texto_traduzido.id_tenant := v_new.id_tenant;',
'        v_new_srv_texto_traduzido.id_texto := p_id;',
'        v_new_srv_texto_traduzido.id_idioma := l_id_idioma;',
'        v_new_srv_texto_traduzido.label := p_label;',
'        v_new_srv_texto_traduzido.instrucao := p_instrucao;',
'        v_new_srv_texto_traduzido.help := p_help;',
'        v_new_srv_texto_traduzido.necessita_revisao := 1;           ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO2'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o de srv_texto com tradu\00E7\00E3o. ID='' || p_id'),
'        );',
'    exception',
'        when others then',
'            pkg_log_execucao.log_erro(',
'                p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                p_nm_rotina   => ''ALTERA_REGISTRO2'',',
unistr('                p_ds_mensagem => ''Erro na altera\00E7\00E3o de srv_texto com tradu\00E7\00E3o. ID='' || p_id,'),
'                p_ds_erro     => sqlerrm',
'            );',
'            raise;',
'    end;    ',
'    --    ',
'    procedure altera_registro_srv_texto(  ',
'        p_id_tenant in srv_texto.id_tenant%type,',
'        p_id_sistema_versionado in srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type,',
'        p_tag in srv_texto.tag%type,',
'        p_necessita_revisao in srv_texto.necessita_revisao%type,',
'        p_apex_traduzira in srv_texto.apex_traduzira%type,',
'        p_tipo_texto in srv_texto.tipo_texto%type, ',
'        p_id in srv_texto.id%type, ',
'        p_data_alteracao in srv_texto.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is        ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_SRV_TEXTO'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o direta de srv_texto. ID='' || p_id'),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_texto.altera_registro_srv_texto'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'',
'        --select * into v_old from srv_texto where id = p_id;        ',
'        --v_new := v_old;',
'        v_new.necessita_revisao := p_necessita_revisao;',
'',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_sistema_versionado := p_id_sistema_versionado;',
'        v_new.id_aplicacao_versionada := p_id_aplicacao_versionada;',
'        v_new.tag := retorna_tag(p_tag,p_tipo_texto); ',
'        v_new.necessita_revisao := p_necessita_revisao;',
'        v_new.apex_traduzira := p_apex_traduzira;',
'        v_new.tipo_texto := p_tipo_texto; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate; ',
'',
'        /* Executa rotinas antes de alterar */ ',
'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'',
'        /* Executa update */ ',
'        update srv_texto set  ',
'            id_tenant = v_new.id_tenant,',
'            id_sistema_versionado = v_new.id_sistema_versionado,',
'            id_aplicacao_versionada = v_new.id_aplicacao_versionada,',
'            tag = v_new.tag,',
'            necessita_revisao = v_new.necessita_revisao,',
'            apex_traduzira = v_new.apex_traduzira,',
'            tipo_texto = v_new.tipo_texto, ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_SRV_TEXTO'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o direta de srv_texto. ID='' || p_id'),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''ALTERA_REGISTRO_SRV_TEXTO'',',
unistr('                    p_ds_mensagem => ''Erro de neg\00F3cio na altera\00E7\00E3o direta de srv_texto. ID='' || p_id'),
'                );',
'',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''ALTERA_REGISTRO_SRV_TEXTO'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o direta de srv_texto. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro_srv_texto;',
'',
'    procedure altera_registro_por_tag (',
'        p_id_tenant in srv_texto.id_tenant%type,',
'        p_id_sistema_versionado in srv_texto.id_sistema_versionado%type,',
'        p_id_aplicacao_versionada in srv_texto.id_aplicacao_versionada%type,',
'        p_tag_old in srv_texto.tag%type,',
'        p_tag in srv_texto.tag%type,',
'        p_necessita_revisao in srv_texto.necessita_revisao%type,',
'        p_apex_traduzira in srv_texto.apex_traduzira%type,',
'        p_tipo_texto_old in srv_texto.tipo_texto%type,',
'        p_tipo_texto in srv_texto.tipo_texto%type, ',
'        p_label in srv_texto_traduzido.label%type,',
'        p_instrucao in srv_texto_traduzido.instrucao%type,',
'        p_help in srv_texto_traduzido.help%type,',
'        p_data_alteracao in srv_texto.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id srv_texto.id%type;',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_POR_TAG'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o por tag. TAG_OLD='' || p_tag_old || '' TAG='' || p_tag'),
'        );',
'',
'        l_id := retorna_id_por_tag(p_tag_old,p_tipo_texto_old);',
'        if l_id is not null then ',
'            altera_registro (',
'                p_id_tenant               => p_id_tenant,',
'              '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(231233347283933450)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  p_id_sistema_versionado   => p_id_sistema_versionado,',
'                p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                p_tag                     => p_tag,',
'                p_necessita_revisao       => p_necessita_revisao,',
'                p_apex_traduzira          => p_apex_traduzira,',
'                p_tipo_texto              => p_tipo_texto,',
'                p_id                      => l_id,',
'                p_label                   => p_label,',
'                p_instrucao               => p_instrucao,',
'                p_help                    => p_help,',
'                p_data_alteracao          => v_data_alteracao,',
'                p_pagina                  => p_pagina,',
'                p_encadeado               => p_encadeado,',
'                p_sucesso                 => p_sucesso,',
'                p_messages                => p_messages);',
'        else',
'            inclui_registro(',
'                p_id_tenant               => p_id_tenant,',
'                p_id_sistema_versionado   => p_id_sistema_versionado,',
'                p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                p_tag                     => p_tag,',
'                p_necessita_revisao       => p_necessita_revisao,',
'                p_apex_traduzira          => p_apex_traduzira,',
