'        when others then',
'            pkg_log_execucao.log_erro(',
'                p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                p_nm_rotina   => ''EXCLUI_REGISTRO_POR_TAG'',',
unistr('                p_ds_mensagem => ''Erro na exclus\00E3o por tag. TAG='' || p_tag,'),
'                p_ds_erro     => sqlerrm',
'            );',
'            raise;',
