'',
'    function retorna_tag (',
'         p_tag in srv_texto.tag%type,',
'         p_tipo_texto in srv_texto.tipo_texto%type',
'    ) return varchar2 is',
'        l_prefixo srv_texto.tag%type;',
'        l_tag srv_texto.tag%type;',
'    begin',
'        case p_tipo_texto ',
'            when 1 then l_prefixo := ''botao.'';',
'            when 2 then l_prefixo := ''coluna.'';',
'            when 3 then l_prefixo := ''tela.'';',
'            when 4 then l_prefixo := ''artefato.'';',
'            when 5 then l_prefixo := ''msg.'';',
'            when 6 then l_prefixo := ''dominio.'';',
'            when 7 then l_prefixo := ''menu.'';',
'            when 8 then l_prefixo := ''grupofuncionalidades.'';',
'            when 9 then l_prefixo := ''etapa.'';',
'           when 10 then l_prefixo := ''atalho.'';',
'        end case;',
'',
'        return adicionar_prefixo(p_tag,l_prefixo);',
unistr('        -- 1=Bot\00E3o de tela (label, help), '),
unistr('        -- 2=Coluna de tabela (label, instru\00E7\00E3o, Help), '),
unistr('        -- 3=Campo de tela (label, instru\00E7\00E3o, help), '),
unistr('        -- 4=Artefato (t\00EDtulo e help), '),
'        -- 5=Mensagem, ',
unistr('        -- 6=Dom\00EDnio (valores), '),
unistr('        -- 7=Menu (t\00F3picos); '),
unistr('        -- 8=Grupo de funcionalidades (t\00F3picos)'),
'    end retorna_tag;',
'',
'    function retorna_id_por_tag (',
'         p_tag in srv_texto.tag%type,',
'         p_tipo_texto in srv_texto.tipo_texto%type',
'    ) return srv_texto.id%type is',
'        l_id srv_texto.id%type;',
'    begin',
'        select id, data_alteracao into l_id, v_data_alteracao from srv_texto where tag = retorna_tag(p_tag,p_tipo_texto);',
'        return l_id;',
'',
'        exception',
'            when others then',
'                return null;',
unistr('                --raise_application_error(-20111,''N\00E3o foi possivel encontra da TAG: ''||retorna_tag(p_tag,p_tipo_texto));'),
'',
'    end retorna_id_por_tag;     ',
