'    function retorna_id_tag_origem(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return number is',
'        l_tag       varchar2(4000);',
'        p_id_origem number;        ',
'        l_count     number;',
'        l_valor_1   varchar2(4000);',
'        l_valor_2   varchar2(4000);        ',
'        l_sql       varchar2(4000); ',
'    begin',
'        l_tag := trim(p_tag);',
'        l_count := regexp_count(l_tag, ''\.'');',
'',
'        if l_count > 0 then',
'            l_valor_1 := lower(regexp_substr(l_tag, ''[^.]+'', 1, 2));',
'        end if;',
'',
'        if l_count > 1 then',
'            l_valor_2 := lower(substr(l_tag, instr(l_tag, ''.'', 1, 2) + 1));',
'        end if;',
'',
'        if p_tipo_texto in (1, 3) then',
'            l_valor_1 := lower(regexp_substr(l_tag, ''\.(.*)'', 1, 1, null, 1));',
'            l_sql := ''select id from srv_aplicacao_texto where lower(tag) = :1'';',
'            execute immediate l_sql into p_id_origem using l_valor_1;  ',
'        elsif p_tipo_texto = 2 then',
'            l_sql := ''select a.id from srv_entidade_coluna a '' ||',
'                     ''join srv_entidade b on b.id = a.id_entidade '' ||',
'                     ''where lower(nome_entidade) = :1 and lower(trim(nome_coluna)) = :2'';',
'            execute immediate l_sql into p_id_origem using l_valor_1, l_valor_2;',
'        elsif p_tipo_texto = 4 then',
'            l_sql := ''select a.id from srv_artefato_versionado a ''||',
'                     ''join srv_artefato b on b.id = a.id_artefato ''||',
'                     ''where lower(b.codigo_artefato) = :1 and a.situacao = ''''A'''' fetch first 1 rows only'';',
'            execute immediate l_sql into p_id_origem using l_valor_1;',
'        elsif p_tipo_texto = 5 then',
'            l_sql := ''select id from srv_aplicacao_mensagem where lower(codigo_mensagem) = :1'';',
'            execute immediate l_sql into p_id_origem using l_valor_1;            ',
'        elsif p_tipo_texto = 6 then',
'            l_sql := ''select b.id from srv_dominio a '' ||',
'                     ''join srv_dominio_valor b on b.id_dominio = a.id '' || ',
'                     ''where b.id_dominio = :1 and lower(b.valor) = :2'';',
'            execute immediate l_sql into p_id_origem using l_valor_1, l_valor_2;',
'        elsif p_tipo_texto = 7 then',
'            p_id_origem := l_valor_1;            ',
'        elsif p_tipo_texto = 8 then',
'            p_id_origem := l_valor_1;            ',
'        end if;',
'',
'        return p_id_origem;',
'',
'    end retorna_id_tag_origem;',
'',
'    function retorna_pagina_id_origem(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return number is',
'        l_tag     varchar2(4000);',
'        l_retorno number;',
'    begin',
'        if p_tipo_texto in (1, 3) then',
'            l_retorno := ''229'';',
'        elsif p_tipo_texto = 2 then',
'            l_retorno := ''145'';',
'        elsif p_tipo_texto = 4 then',
'            l_retorno := ''150'';',
'        elsif p_tipo_texto = 5 then',
'            l_retorno := ''161'';',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := ''227'';',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := ''115'';',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := ''152'';',
'        end if;    ',
'        l_tag := retorna_id_tag_origem(p_tag, p_tipo_texto);',
'        if l_tag is not null then',
'            return l_retorno;',
'        else',
'           null;',
'        end if;',
'    end retorna_pagina_id_origem;',
'',
'    function retorna_pagina_opcoes_id_origem(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return number is',
'        l_tag     varchar2(4000);',
'        l_retorno number;',
'    begin',
'        if p_tipo_texto in (1, 3) then',
'            l_retorno := ''228'';',
'        elsif p_tipo_texto = 2 then',
'            l_retorno := ''143'';',
'        elsif p_tipo_texto = 4 then',
'            l_retorno := ''149'';',
'        elsif p_tipo_texto = 5 then',
'            l_retorno := ''160'';',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := ''227'';',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := ''114'';',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := ''104'';',
'        end if;    ',
'        l_tag := retorna_id_tag_origem(trim(p_tag), p_tipo_texto);',
'        if l_tag is not null then',
'            return l_retorno;',
'        else',
'           null;',
'        end if;',
'    end retorna_pagina_opcoes_id_origem;   ',
'',
'    procedure gerar_mpd_traducao(',
'        p_esquema in varchar2,',
'        p_pagina in number default 0,         ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
'        l_maior_data_alteracao mpd_traducao.data_alteracao%type;',
'        l_retorno clob;',
'        l_sql clob;',
'        l_new_id mpd_traducao.id%type;',
'        l_conta number;',
'        i number := 0;',
'',
'        procedure processa_traducao(',
'            p_texto in varchar2, ',
'            p_tag_suffix in varchar2, ',
'            p_id_sistema_versionado in number, ',
'            p_id_aplicacao_versionada in number, ',
'            p_tag in varchar2, ',
'            p_id_idioma in number, ',
'            p_apex_traduzira in number',
'        ) is',
'            l_id_mpd_traducao number;',
'            l_id_mpd_traducao_apex number;',
'            l_data_alteracao mpd_traducao.data_alteracao%type;',
'            l_data_alteracao_apex mpd_traducao_apex.data_alteracao%type;',
'        begin',
'            if p_texto is not null then',
'                bo_mpd_traducao.retorna_id(p_tag || p_tag_suffix, p_id_idioma, l_id_mpd_traducao, l_data_alteracao);                ',
'                if l_id_mpd_traducao is not null then',
'                    bo_mpd_traducao.altera_registro(',
'                        p_id_sistema_versionado => p_id_sistema_versionado,',
'                        p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                        p_tag => p_tag || p_tag_suffix,',
'                        p_id_idioma => p_id_idioma,',
'                        p_texto_traduzido => p_texto, ',
'                        p_id => l_id_mpd_traducao, ',
'                        p_data_alteracao => l_data_alteracao,',
'                        p_esquema => p_esquema, ',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    );',
'                else',
'                    bo_mpd_traducao.inclui_registro(',
'                        p_id_sistema_versionado => p_id_sistema_versionado,',
'                        p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                        p_tag => p_tag || p_tag_suffix,',
'                        p_id_idioma => p_id_idioma,',
'                        p_texto_traduzido => p_texto, ',
'                        p_id => l_new_id, ',
'                        p_esquema => p_esquema, ',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => v_messages',
'                    );',
'                end if;  ',
'                if p_apex_traduzira = 1 then  ',
'                    bo_mpd_traducao_apex.retorna_id(p_tag || p_tag_suffix, p_id_idioma, l_id_mpd_traducao_apex, l_data_alteracao_apex);                ',
'                    if l_id_mpd_traducao_apex is not null then',
'                        bo_mpd_traducao_apex.altera_registro(',
'                            p_id_sistema_versionado => p_id_sistema_versionado,',
'                            p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                            p_tag => p_tag || p_tag_suffix,',
'                            p_id_idioma => p_id_idioma,',
'                            p_texto_traduzido => p_texto, ',
'                            p_id => l_id_mpd_traducao_apex, ',
'                            p_data_alteracao => l_data_alteracao_apex,',
'                            p_esquema => p_esquema, ',
'                            p_encadeado => true,',
'                            p_sucesso => p_sucesso,',
'                            p_messages => v_messages',
'                        );                ',
'                    else',
'                        bo_mpd_traducao_apex.inclui_registro(',
'                            p_id_sistema_versionado => p_id_sistema_versionado,',
'                            p_id_aplicacao_versionada => p_id_aplicacao_versionada,',
'                            p_tag => p_tag || p_tag_suffix,',
'                            p_id_idioma => p_id_idioma,',
'                            p_texto_traduzido => p_texto, ',
'                            p_id => l_new_id, ',
'                            p_esquema => p_esquema, ',
'                            p_encadeado => true,',
'                            p_sucesso => p_sucesso,',
'                            p_messages => v_messages',
'                        );',
'                    end if;    ',
'                end if;    ',
'            end if;',
'        end processa_traducao;',
'',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''GERAR_MPD_TRADUCAO'',',
unistr('            p_ds_mensagem => ''In\00EDcio da gera\00E7\00E3o de MPD tradu\00E7\00E3o. ESQUEMA='' || p_esquema'),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''exportar textos'';   ',
'        v_pagina := p_pagina; ',
'        valida_esquema(p_esquema);',
'',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if;                  ',
'',
'        select count(1) into l_conta',
'        from srv_texto a ',
'        join srv_texto_traduzido b on id_texto = a.id',
'        where b.data_alteracao > (select max(data_alteracao) from mpd_traducao);',
'',
'        for c_texto in (select * ',
'                        from srv_texto a ',
'                        join srv_texto_traduzido b on id_texto = a.id ',
'                        where b.data_alteracao > (select max(data_alteracao) from mpd_traducao)',
'        ) loop',
'            i := i + 1;',
'            apex_background_process.set_status(',
unistr('                p_message => ''Realizando a sincroniza\00E7\00E3o para o MPD (''||i||''/''||l_conta||'')'''),
'            );',
'            apex_background_process.set_progress(',
'                p_totalwork => l_conta,',
'                p_sofar => i',
'            );',
'',
'            processa_traducao(c_texto.label, ''.l'', c_texto.id_sistema_versionado, c_texto.id_aplicacao_versionada, c_texto.tag, c_texto.id_idioma, c_texto.apex_traduzira);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'            processa_traducao(c_texto.instrucao, ''.i'', c_texto.id_sistema_versionado, c_texto.id_aplicacao_versionada, c_texto.tag, c_texto.id_idioma, c_texto.apex_traduzira);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'            processa_traducao(c_texto.help, ''.h'', c_texto.id_sistema_versionado, c_texto.id_aplicacao_versionada, c_texto.tag, c_texto.id_idioma, c_texto.apex_traduzira);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;',
'',
'        apex_background_process.set_status(',
unistr('            p_message => ''Sincroniza\00E7\00E3o concl\00EDda com sucesso'''),
'        );',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''GERAR_MPD_TRADUCAO'',',
unistr('            p_ds_mensagem => ''Fim da gera\00E7\00E3o de MPD tradu\00E7\00E3o. ESQUEMA='' || p_esquema'),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''GERAR_MPD_TRADUCAO'',',
unistr('                    p_ds_mensagem => ''Erro de neg\00F3cio na gera\00E7\00E3o de MPD tradu\00E7\00E3o. ESQUEMA='' || p_esquema'),
'                );',
'',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''GERAR_MPD_TRADUCAO'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na gera\00E7\00E3o de MPD tradu\00E7\00E3o. ESQUEMA='' || p_esquema,'),
'                   '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(231233347283933450)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' p_ds_erro     => sqlerrm',
'                );',
'',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);  ',
'    end gerar_mpd_traducao;    ',
'',
'    procedure gerar_mpd_traducao2(',
'        p_esquema in varchar2,',
'        p_pagina in number default 0,         ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is ',
'        l_origem clob;       ',
'        l_condicao clob;       ',
'        l_update clob;       ',
'        l_campos clob;       ',
'        l_valores clob;       ',
'    begin',
'        l_origem := ''select a.id_sistema_versionado, a.id_aplicacao_versionada,a.tag,a.id_usuario_incluiu,a.data_inclusao,a.id_usuario_alterou,b.id_idioma,b.label from srv_texto a join srv_texto_traduzido b on id_texto = a.id'';',
'        l_condicao := ''d.tag = o.tag||''''.l'''''';',
'        l_update := '' d.id_sistema_versionado = o.id_sistema_versionado,''||',
'                    '' d.id_aplicacao_versionada = o.id_aplicacao_versionada,''||',
'                    '' d.id_idioma = o.id_idioma,''||',
'                    '' d.texto_traduzido = o.label'';',
'        l_campos := ''d.id_sistema_versionado, d.id_aplicacao_versionada, d.tag, d.id_idioma, d.texto_traduzido,d.id_usuario_incluiu,d.data_inclusao,d.data_alteracao,d.id_usuario_alterou'';',
'        l_valores := ''o.id_sistema_versionado, o.id_aplicacao_versionada, o.tag||''''.l'''', o.id_idioma, o.label,o.id_usuario_incluiu,o.data_inclusao,o.data_inclusao,o.id_usuario_alterou'';',
'        pkg_util.merge_tabelas(',
'            p_esquema => p_esquema,',
'            p_tabela_origem => l_origem,',
'            p_tabela_destino => ''mpd_traducao'',',
'            p_condicao => l_condicao,',
'            p_update => l_update,',
'            p_campos => l_campos,',
'            p_valores => l_valores',
'        );',
'    end gerar_mpd_traducao2;',
'',
'    procedure gerar_srv_texto(',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('            p_ds_mensagem => ''In\00EDcio da gera\00E7\00E3o de srv_texto'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''BO_SRV_TEXTO.gerar_srv_texto'';   ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_aplicacao_texto',
'        for c_cursor in (select * from srv_aplicacao_texto) loop',
'            bo_srv_aplicacao_texto.altera_registro(',
'                p_id_tenant  => c_cursor.id_tenant,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_id_aplicacao_versionada => c_cursor.id_aplicacao_versionada,',
'                p_tag => c_cursor.tag,',
'                p_label => c_cursor.label,',
'                p_tipo_texto => c_cursor.tipo_texto,',
'                p_instrucao => c_cursor.instrucao,',
'                p_help => c_cursor.help,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_aplicacao_mensagem',
'        for c_cursor in (select * from srv_aplicacao_mensagem) loop',
'            bo_srv_aplicacao_mensagem.altera_registro(',
'                p_id_tenant  => c_cursor.id_tenant,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_id_aplicacao_versionada => c_cursor.id_aplicacao_versionada,',
'                p_tipo_mensagem => c_cursor.tipo_mensagem,',
'                p_codigo_mensagem => c_cursor.codigo_mensagem,',
'                p_mensagem => c_cursor.mensagem,',
'                p_help => c_cursor.help,',
'                p_situacao => c_cursor.situacao,',
'                p_data_descontinuidade => c_cursor.data_descontinuidade,',
'                p_instrucao_interna => c_cursor.instrucao_interna,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;     ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_dominio_valor',
'        for c_cursor in (select * from srv_dominio_valor) loop',
'            bo_srv_dominio_valor.altera_registro(',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_dominio => c_cursor.id_dominio,',
'                p_titulo => c_cursor.titulo,',
'                p_valor => c_cursor.valor,',
'                p_tag => c_cursor.tag,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_entidade_coluna',
'        for c_cursor in (select * from srv_entidade_coluna) loop',
'            bo_srv_entidade_coluna.altera_registro(',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_entidade => c_cursor.id_entidade,',
'                p_ordenacao => c_cursor.ordenacao,',
'                p_descricao => c_cursor.descricao,',
'                p_nome_coluna => c_cursor.nome_coluna,',
'                p_tipo_dado => c_cursor.tipo_dado,',
'                p_tamanho => c_cursor.tamanho,',
'                p_qtd_casas_decimais => c_cursor.qtd_casas_decimais,',
'                p_edicao => c_cursor.edicao,',
'                p_valor_default => c_cursor.valor_default,',
'                p_eh_coluna_obrigatoria => c_cursor.eh_coluna_obrigatoria,',
'                p_eh_valor_unico => c_cursor.eh_valor_unico,',
'                p_referencia => c_cursor.referencia,',
'                p_chave_primaria => c_cursor.chave_primaria,',
'                p_label => c_cursor.label,',
'                p_instrucao => c_cursor.instrucao,',
'                p_help => c_cursor.help,',
'                p_descricao_complementar => c_cursor.descricao_complementar,',
'                p_id_dominio => c_cursor.id_dominio,',
'                p_tipo_interacao => c_cursor.tipo_interacao, ',
'                p_nome_consulta => c_cursor.nome_consulta,',
'                p_id_artefato_versionado_novo => c_cursor.id_artefato_versionado_novo,',
'                p_ind_negativo => c_cursor.ind_negativo,',
'                p_ind_formato_texto => c_cursor.ind_formato_texto,',
'                p_id_artefato_versionado_zoom => c_cursor.id_artefato_versionado_zoom,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;        ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_grupo_funcionalidade',
'        for c_cursor in (select * from srv_grupo_funcionalidade) loop',
'            bo_srv_grupo_funcionalidade.altera_registro(',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_id_grupo_pai => c_cursor.id_grupo_pai,',
'                p_titulo => c_cursor.titulo,',
'                p_ordenacao => c_cursor.ordenacao,',
'                p_id_artefato_versionado => c_cursor.id_artefato_versionado,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;    ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_menu',
'        for c_cursor in (select * from srv_menu) loop',
'            bo_srv_menu.altera_registro(',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_menu_pai => c_cursor.id_menu_pai,',
'                p_id_sistema_versionado => c_cursor.id_sistema_versionado,',
'                p_titulo => c_cursor.titulo,',
'                p_ordenacao => c_cursor.ordenacao,',
'                p_icone => c_cursor.icone,',
'                p_ind_sincronizar => c_cursor.ind_sincronizar,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;    ',
'',
'        --Gerar srv_texto a partir da varredura da tabela srv_artefato_versionado',
'        for c_cursor in (select * from srv_artefato_versionado) loop',
'            bo_srv_artefato_versionado.altera_registro(',
'                p_id_aplicacao_versionada => c_cursor.id_aplicacao_versionada,',
'                p_especificacao_tecnica => c_cursor.especificacao_tecnica,',
'                p_situacao => c_cursor.situacao,',
'                p_data_checkin => c_cursor.data_checkin,',
'                p_id_usuario_checkin => c_cursor.id_usuario_checkin,',
'                p_id_tenant => c_cursor.id_tenant,',
'                p_id_artefato => c_cursor.id_artefato,',
'                p_titulo => c_cursor.titulo,',
'                p_help => c_cursor.help,',
'                p_id => c_cursor.id,',
'                p_data_alteracao => c_cursor.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => v_messages);',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;                  ',
'        end loop;    ',
'',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_acao, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('            p_ds_mensagem => ''Fim da gera\00E7\00E3o de srv_texto'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('                    p_ds_mensagem => ''Erro de neg\00F3cio na gera\00E7\00E3o de srv_texto'''),
'                );',
'',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                    p_nm_rotina   => ''GERAR_SRV_TEXTO'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na gera\00E7\00E3o de srv_texto'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);  ',
'',
'    end gerar_srv_texto;',
'',
'    procedure altera_registro_necessita_revisao(',
'        p_id                in srv_texto.id%type,',
'        p_necessita_revisao in srv_texto.necessita_revisao%type,',
'        p_encadeado         in boolean default false,',
'        p_sucesso           out clob,',
'        p_messages          out pkg_mensagem.message_record_table    ',
'    ) is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_NECESSITA_REVISAO'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o de necessita_revisao. ID='' || p_id'),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_srv_texto.altera_registro_necessita_revisao''; ',
'        v_operacao := ''altera_registro_necessita_revisao'';',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from srv_texto where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_data_alteracao := v_new.data_alteracao;',
'        v_new.Necessita_revisao := p_Necessita_revisao;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''BO_SRV_TEXTO'',',
'            p_nm_rotina   => ''ALTERA_REGISTRO_NECESSITA_REVISAO'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o de necessita_revisao. ID='' || p_id'),
'        );',
'    exception',
'        when others then',
'            pkg_log_execucao.log_erro(',
'                p_nm_modulo   => ''BO_SRV_TEXTO'',',
'                p_nm_rotina   => ''ALTERA_REGISTRO_NECESSITA_REVISAO'',',
unistr('                p_ds_mensagem => ''Erro na altera\00E7\00E3o de necessita_revisao. ID='' || p_id,'),
'                p_ds_erro     => sqlerrm',
'            );',
'            raise;',
'    end altera_registro_necessita_revisao;',
'',
'    function url_com_parametro (',
'        p_id varchar2,',
'        p_pagina number,',
'        p_parametro varchar2 default null',
'    ) return varchar2 is',
'    begin',
'        return APEX_UTIL.PREPARE_URL(',
'            p_url => ''f?p=''||APEX_APPLICATION.g_flow_id||'':''||p_pagina||'':''||APEX_CUSTOM_AUTH.GET_SESSION_ID||''::NO::P''||p_pagina||''_ID,P''||p_pagina||''_CODIGO_ARTEFATO:''||p_id||'',''||p_parametro,',
'            p_checksum_type => ''SESSION'');',
'    end url_com_parametro;',
'',
'    function url_mais_detalhes (',
'        p_id varchar2,',
'        p_pagina number,',
'        p_parametro varchar2 default null',
'    ) return varchar2 is',
'    begin',
'        return APEX_UTIL.PREPARE_URL(',
'            p_url => ''f?p=''||APEX_APPLICATION.g_flow_id||'':''||p_pagina||'':''||APEX_CUSTOM_AUTH.GET_SESSION_ID||''::NO:''||p_pagina||'':P''||p_pagina||''_PARAMETRO,P''||p_pagina||''_CODIGO_ARTEFATO:''||p_id||'',''||p_parametro,',
'            p_checksum_type => ''SESSION'');',
'    end url_mais_detalhes;',
'',
'    function retorna_codigo_artefato(',
'        p_tag        in varchar2,',
'        p_tipo_texto in number',
'    ) return varchar2 is',
'        l_tag     varchar2(4000);',
'        l_retorno varchar2(4000);',
'    begin',
'        if p_tipo_texto in (1) then',
'            l_retorno := ''TD287'';',
'        elsif p_tipo_texto = 2 then',
'            l_retorno := ''TD294'';',
'        elsif p_tipo_texto = 3 then',
'            l_retorno := ''TD287'';',
'        elsif p_tipo_texto = 4 then',
'            l_retorno := ''TD295'';',
'        elsif p_tipo_texto = 5 then',
'            l_retorno := ''TD296'';',
'        elsif p_tipo_texto = 6 then',
'            l_retorno := ''TD297'';',
'        elsif p_tipo_texto = 7 then',
'            l_retorno := ''TD298'';',
'        elsif p_tipo_texto = 8 then',
'            l_retorno := ''TD299'';',
'        end if;    ',
'        l_tag := retorna_id_tag_origem(p_tag, p_tipo_texto);',
'        if l_tag is not null then',
'            return l_retorno;',
'        else',
'           null;',
'        end if;',
'    end retorna_codigo_artefato;',
'',
'    function botao_opcao(',
'        p_url in varchar2',
'    ) return varchar2 is',
'        l_html varchar2(10000);',
'        l_url  varchar2(10000) := p_url;',
'    begin',
'        l_html := ''<div style="display: flex;align-items: center; justify-content: flex-end; flex-grow: 1;"><a href="''||l_url||''" style="color: var(--a-button-state-text-color, var(--a-button-type-text-color, var(--a-button-text-color, inherit)));" c'
||'lass="fa fa-edit"></a></div>'';',
'        return l_html;',
'    end botao_opcao;',
'',
'    procedure valida_esquema(p_esquema in varchar2) ',
'    is ',
'        l_label_item pkg_mensagem.paramentros;',
'    begin ',
'        if p_esquema is null then ',
'            l_label_item(1) := pkg_ui.retorna_label_coluna(''campo.154.esquema.l''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''esquema'',',
'                p_parametro => l_label_item,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'    end valida_esquema; ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_srv_texto;',
'/'))
);
end;
/
