prompt --application/deployment/install/upgrade_ui_mpd_td832
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(148586155971634526)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD832'
,p_sequence=>100
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD832',
'-- Data: 15/04/2026',
'-- Motivo: Desenvolvidos novos filtros de pesquisa facetada',
'-- Jira: PEDITEM-72 - IMP00085_importacao_listar',
'',
'create or replace package "UI_MPD_TD832" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD832";',
'/',
'create or replace package body "UI_MPD_TD832" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.data_alteracao,',
'                a.num_processoimportacao titulo,  ',
'                b.nome_fantasia subtitulo,                ',
'                bo_ng_viatransporte.retorna_icone_viatransporte_card(a.id_viatransporte) icon,                ',
'                pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_status'',a.ind_status) distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao.id_importador'', c.nome_fantasia, 2) atributo1,                ',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao.id_local_embarque'', pkg_traducao.get_traducao(d.nome_local), 2) atributo2,',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao.id_local_desembarque'',pkg_traducao.get_traducao(e.nome_local), 2) atributo3,',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao.ind_itens_vinculado_invoice'',',
'                    CASE a.ind_itens_vinculado_invoice WHEN ''N'' THEN',
'                        ''<span style="color:red;">'' || pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_itens_vinculado_invoice'',a.ind_itens_vinculado_invoice) || ''</span>''',
'                    ELSE',
'                        pkg_util.dominio_retorna_tag(''imp_processoimportacao'',''ind_itens_vinculado_invoice'',a.ind_itens_vinculado_invoice)',
'                    END, 2',
'                ) atributo4, ',
'                pkg_componentes.html_card_colunas(',
'                    CASE',
'                        WHEN a.data_recebimento_real IS NOT NULL THEN ''imp_processoimportacao.data_recebimento_real''',
'                        WHEN a.data_nacionalizacao_real IS NOT NULL THEN ''imp_processoimportacao.data_nacionalizacao_real''',
'                        WHEN a.data_registro_di_real IS NOT NULL THEN ''imp_processoimportacao.data_registro_di_real''',
'                        WHEN a.data_desembarque_real IS NOT NULL THEN ''imp_processoimportacao.data_desembarque_real''',
'                        WHEN a.data_embarque_real IS NOT NULL THEN ''imp_processoimportacao.data_embarque_real''',
'                        WHEN a.data_disponivel_real IS NOT NULL THEN ''imp_processoimportacao.data_disponivel_real''',
'                        WHEN a.data_disponivel_informada IS NOT NULL THEN ''imp_processoimportacao.data_disponivel_informada''',
'                        WHEN a.data_disponivel_calculada IS NOT NULL THEN ''imp_processoimportacao.data_disponivel_calculada''',
'                    ELSE',
'                        ''imp_processoimportacao.data_recebimento_real''',
'                    END,',
'                    TO_CHAR(',
'                        COALESCE(',
'                            a.data_recebimento_real,',
'                            a.data_nacionalizacao_real,',
'                            a.data_registro_di_real,',
'                            a.data_desembarque_real,',
'                            a.data_embarque_real,',
'                            a.data_disponivel_real,',
'                            a.data_disponivel_informada,',
'                            a.data_disponivel_calculada',
'                        ),',
'                        ''DD/MM/YYYY''',
'                    ), 2',
'                ) atributo5,',
'                pkg_componentes.html_card_colunas( ',
'                    CASE',
'                        -- regra 1',
'                        WHEN a.data_embarque_real IS NOT NULL THEN ''imp_processoimportacao.data_desembarque_real''',
'                        -- regra 2',
'                        WHEN a.data_embarque_real IS NULL AND a.data_embarque_informada IS NOT NULL THEN ''imp_processoimportacao.data_embarque_informada''',
'                        -- regra 3',
'                        WHEN a.data_embarque_real IS NULL AND a.data_embarque_informada IS NULL AND a.data_embarque_calculada IS NOT NULL THEN ''imp_processoimportacao.data_embarque_calculada''',
'                        -- regra 4',
'                        WHEN a.data_desembarque_real IS NOT NULL THEN ''imp_processoimportacao.data_registro_di_real''',
'                        -- regra 5',
'                        WHEN a.data_desembarque_real IS NULL AND a.data_desembarque_informada IS NOT NULL THEN ''imp_processoimportacao.data_desembarque_informada''',
'                        -- regra 6',
'                        WHEN a.data_desembarque_real IS NULL AND a.data_desembarque_informada IS NULL AND a.data_desembarque_calculada IS NOT NULL THEN ''imp_processoimportacao.data_desembarque_calculada''',
'                        -- regra 7',
'                        WHEN a.data_registro_di_real IS NOT NULL THEN ''imp_processoimportacao.data_nacionalizacao_real''',
'                        -- regra 8',
'                        WHEN a.data_registro_di_real IS NULL AND a.data_registro_di_informada IS NOT NULL THEN ''imp_processoimportacao.data_registro_di_informada''',
'                        -- regra 9',
'                        WHEN a.data_registro_di_real IS NULL AND a.data_registro_di_informada IS NULL AND a.data_registro_di_calculada IS NOT NULL THEN ''imp_processoimportacao.data_registro_di_calculada''',
'                        -- regra 10',
'                        WHEN a.data_nacionalizacao_real IS NOT NULL THEN ''imp_processoimportacao.data_recebimento_real''',
'                        -- regra 11',
'                        WHEN a.data_nacionalizacao_real IS NULL AND a.data_nacionalizacao_informada IS NOT NULL THEN ''imp_processoimportacao.data_nacionalizacao_informada''',
'                        -- regra 12',
'                        WHEN a.data_nacionalizacao_real IS NULL AND a.data_nacionalizacao_informada IS NULL AND a.data_nacionalizacao_calculada IS NOT NULL THEN ''imp_processoimportacao.data_nacionalizacao_calculada''',
'                        -- regra 13',
'                        WHEN a.data_recebimento_real IS NULL AND a.data_recebimento_informada IS NOT NULL THEN ''imp_processoimportacao.data_recebimento_informada''',
'                        -- regra 14',
'                        WHEN a.data_recebimento_real IS NULL AND a.data_recebimento_informada IS NULL AND a.data_recebimento_calculada IS NOT NULL THEN ''imp_processoimportacao.data_recebimento_calculada''',
'                    ELSE ''imp_processoimportacao.data_embarque_real''',
'                END,',
'                    TO_CHAR(',
'                        CASE',
'                            -- regra 1:',
'                            WHEN a.data_embarque_real IS NOT NULL THEN a.data_desembarque_real ',
'                            -- regra 2: ',
'                            WHEN a.data_embarque_real IS NULL AND a.data_embarque_informada IS NOT NULL THEN a.data_embarque_informada ',
'                            -- regra 3: ',
'                            WHEN a.data_embarque_real IS NULL AND a.data_embarque_informada IS NULL AND a.data_embarque_calculada IS NOT NULL THEN a.data_embarque_calculada ',
'                            -- regra 4: ',
