'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then            ',
'            return q''~select * from pkg_util.dominio_retorna_lista(''imp_processoimportacao'',''ind_status'')~'';',
'        elsif campo = ''3'' then',
'            return q''~select pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',descricao_viatransporte) d, a.id r from ng_viatransporte a~'';',
'        elsif campo = ''4'' then',
'            return q''~select pkg_traducao.get_traducao(nome_local) d, id r from ng_localembarquedesembarque~'';',
'        elsif campo = ''5'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''imp_declaracaoimportacao'', ''ind_canal_parametrizado'')~'';',
'        elsif campo = ''6'' then',
'            return q''~',
'                select pkg_ui.retorna_label_coluna(t.r) d, t.r from (',
'                    select ''imp_processoimportacao.data_disponivel_real'' r from dual union all',
