'                    select ''imp_processoimportacao.data_desembarque_real'' from dual union all',
'                    select ''imp_processoimportacao.data_nacionalizacao_real'' from dual union all',
'                    select ''imp_processoimportacao.data_recebimento_real'' from dual',
'                ) t',
