'                select pkg_ui.retorna_label_coluna(t.r) d, t.r from (',
'                    select ''imp_processoimportacao.data_disponivel_real'' r from dual union all',
'                    select ''imp_processoimportacao.data_embarque_real'' from dual union all',
'                    select ''imp_processoimportacao.data_desembarque_real'' from dual union all',
'                    select ''imp_processoimportacao.data_nacionalizacao_real'' from dual union all',
'                    select ''imp_processoimportacao.data_recebimento_real'' from dual',
'                ) t',
'            ~'';',
'        elsif campo = ''8'' then',
'            return q''~select d, r from table(pkg_util.dominio_retorna_lista(''imp_processoimportacao'', ''ind_autorizacao_embarque''))~'';',
'        else',
