'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao.num_processoimportacao'') into l_campo from dual;',
'        elsif campo in (''2'',''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_status'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao.id_embarcador'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
