'        elsif campo = ''F8'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao.ind_autorizacao_embarque'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
