'        v_new.valor_despesa_invoice := nvl(p_valor_despesa_invoice,0);',
'        v_new.valor_total_condicao_venda := nvl(p_valor_total_condicao_venda,0);',
'        v_new.valor_compensado := nvl(p_valor_compensado,0);',
'        v_new.ind_situacao_titulo_pagamento := nvl(p_ind_situacao_titulo_pagamento,''N'');',
'        v_new.ind_divergencia := p_ind_divergencia;',
'        v_new.ind_tratamento_saldo := p_ind_tratamento_saldo;',
'        v_new.valor_invoice_informado := p_valor_invoice_informado; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_motivo_desconto out imp_invoice.motivo_desconto%type,',
'        p_valor_total_financeiro out imp_invoice.valor_total_financeiro%type,',
'        p_id_tenant out imp_invoice.id_tenant%type,',
'        p_id_processoimportacao out imp_invoice.id_processoimportacao%type,',
'        p_num_invoice out imp_invoice.num_invoice%type,',
'        p_data_invoice out imp_invoice.data_invoice%type,',
'        p_ind_status out imp_invoice.ind_status%type,',
'        p_id_exportador out imp_invoice.id_exportador%type,',
'        p_id_importador out imp_invoice.id_importador%type,',
'        p_id_adquirente out imp_invoice.id_adquirente%type,',
'        p_id_condicaopagamento out imp_invoice.id_condicaopagamento%type,',
'        p_id_incoterm out imp_invoice.id_incoterm%type,',
'        p_id_moeda out imp_invoice.id_moeda%type,',
'        p_ind_forma_pagamento out imp_invoice.ind_forma_pagamento%type,',
'        p_peso_liquido out imp_invoice.peso_liquido%type,',
'        p_peso_bruto out imp_invoice.peso_bruto%type,',
'        p_valor_total_mercadoria out imp_invoice.valor_total_mercadoria%type,',
'        p_valor_desconto out imp_invoice.valor_desconto%type,',
'        p_valor_despesa_invoice out imp_invoice.valor_despesa_invoice%type,',
'        p_valor_total_condicao_venda out imp_invoice.valor_total_condicao_venda%type,',
'        p_valor_compensado out imp_invoice.valor_compensado%type,',
'        p_ind_situacao_titulo_pagamento out imp_invoice.ind_situacao_titulo_pagamento%type,',
'        p_ind_divergencia out imp_invoice.ind_divergencia%type,',
'        p_ind_tratamento_saldo out imp_invoice.ind_tratamento_saldo%type,',
'        p_valor_invoice_informado out imp_invoice.valor_invoice_informado%type, ',
'        p_id in out imp_invoice.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            motivo_desconto,',
'            valor_total_financeiro,',
'            id_tenant,',
'            id_processoimportacao,',
'            num_invoice,',
'            data_invoice,',
'            ind_status,',
'            id_exportador,',
'            id_importador,',
'            id_adquirente,',
'            id_condicaopagamento,',
'            id_incoterm,',
'            id_moeda,',
'            ind_forma_pagamento,',
'            peso_liquido,',
'            peso_bruto,',
'            valor_total_mercadoria,',
'            valor_desconto,',
'            valor_despesa_invoice,',
'            valor_total_condicao_venda,',
'            valor_compensado,',
'            ind_situacao_titulo_pagamento,',
'            ind_divergencia,',
'            ind_tratamento_saldo,',
'            valor_invoice_informado, ',
'            id ',
'            into ',
'            p_motivo_desconto,',
'            p_valor_total_financeiro,',
'            p_id_tenant,',
'            p_id_processoimportacao,',
'            p_num_invoice,',
'            p_data_invoice,',
'            p_ind_status,',
'            p_id_exportador,',
'            p_id_importador,',
'            p_id_adquirente,',
'            p_id_condicaopagamento,',
'            p_id_incoterm,',
'            p_id_moeda,',
'            p_ind_forma_pagamento,',
'            p_peso_liquido,',
'            p_peso_bruto,',
'            p_valor_total_mercadoria,',
'            p_valor_desconto,',
'            p_valor_despesa_invoice,',
'            p_valor_total_condicao_venda,',
'            p_valor_compensado,',
'            p_ind_situacao_titulo_pagamento,',
'            p_ind_divergencia,',
'            p_ind_tratamento_saldo,',
'            p_valor_invoice_informado, ',
'            p_id ',
'        from imp_invoice ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in imp_invoice.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from imp_invoice where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from imp_invoice where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in imp_invoice.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in imp_invoice.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in imp_invoice.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_invoice'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''imp_invoice'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in imp_invoice.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo motivo_desconto */ '),
'        valida_motivo_desconto(v_new.motivo_desconto);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_total_financeiro */ '),
'        valida_valor_total_financeiro(v_new.valor_total_financeiro);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_processoimportacao */ '),
'        valida_id_processoimportacao(v_new.id_processoimportacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo num_invoice */ '),
'        valida_num_invoice(v_new.num_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_invoice */ '),
'        valida_data_invoice(v_new.data_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_status */ '),
'        valida_ind_status(v_new.ind_status);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_exportador */ '),
'        valida_id_exportador(v_new.id_exportador);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_importador */ '),
'        valida_id_importador(v_new.id_importador);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_adquirente */ '),
'        valida_id_adquirente(v_new.id_adquirente);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_condicaopagamento */ '),
'        valida_id_condicaopagamento(v_new.id_condicaopagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_incoterm */ '),
'        valida_id_incoterm(v_new.id_incoterm);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_moeda */ '),
'        valida_id_moeda(v_new.id_moeda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_forma_pagamento */ '),
'        valida_ind_forma_pagamento(v_new.ind_forma_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo peso_liquido */ '),
'        valida_peso_liquido(v_new.peso_liquido);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo peso_bruto */ '),
'        valida_peso_bruto(v_new.peso_bruto);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_total_mercadoria */ '),
'        valida_valor_total_mercadoria(v_new.valor_total_mercadoria);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_desconto */ '),
'        valida_valor_desconto(v_new.valor_desconto);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_despesa_invoice */ '),
'        valida_valor_despesa_invoice(v_new.valor_despesa_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_total_condicao_venda */ '),
'        valida_valor_total_condicao_venda(v_new.valor_total_condicao_venda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_compensado */ '),
'        valida_valor_compensado(v_new.valor_compensado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_situacao_titulo_pagamento */ '),
'        valida_ind_situacao_titulo_pagamento(v_new.ind_situacao_titulo_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_divergencia */ '),
'        valida_ind_divergencia(v_new.ind_divergencia);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_tratamento_saldo */ '),
'        valida_ind_tratamento_saldo(v_new.ind_tratamento_saldo);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_invoice_informado */ '),
'        valida_valor_invoice_informado(v_new.valor_invoice_informado);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_motivo_desconto(p_motivo_desconto in imp_invoice.motivo_desconto%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_motivo_desconto is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.motivo_desconto''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_motivo_desconto(p_motivo_desconto);',
'    end valida_motivo_desconto;    ',
'',
'    procedure valida_valor_total_financeiro(p_valor_total_financeiro in imp_invoice.valor_total_financeiro%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_valor_total_financeiro is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.valor_total_financeiro''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_valor_total_financeiro(p_valor_total_financeiro);',
'    end valida_valor_total_financeiro;    ',
'',
'    procedure valida_id_tenant(p_id_tenant in imp_invoice.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
