'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from imp_invoice where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(num_invoice)) = lower(trim(v_new.num_invoice)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from imp_invoice where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(num_invoice)) = lower(trim(v_new.num_invoice)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.num_invoice'');             ',
