unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_invoice%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''motivo_desconto'', p_rec.motivo_desconto, true);',
'        apex_json.write(''valor_total_financeiro'', p_rec.valor_total_financeiro, true);',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_processoimportacao'', p_rec.id_processoimportacao, true);',
'        apex_json.write(''num_invoice'', p_rec.num_invoice, true);',
'        apex_json.write(''data_invoice'', p_rec.data_invoice, true);',
'        apex_json.write(''ind_status'', p_rec.ind_status, true);',
'        apex_json.write(''id_exportador'', p_rec.id_exportador, true);',
'        apex_json.write(''id_importador'', p_rec.id_importador, true);',
'        apex_json.write(''id_adquirente'', p_rec.id_adquirente, true);',
'        apex_json.write(''id_condicaopagamento'', p_rec.id_condicaopagamento, true);',
'        apex_json.write(''id_incoterm'', p_rec.id_incoterm, true);',
'        apex_json.write(''id_moeda'', p_rec.id_moeda, true);',
'        apex_json.write(''ind_forma_pagamento'', p_rec.ind_forma_pagamento, true);',
'        apex_json.write(''peso_liquido'', p_rec.peso_liquido, true);',
'        apex_json.write(''peso_bruto'', p_rec.peso_bruto, true);',
'        apex_json.write(''valor_total_mercadoria'', p_rec.valor_total_mercadoria, true);',
'        apex_json.write(''valor_desconto'', p_rec.valor_desconto, true);',
'        apex_json.write(''valor_despesa_invoice'', p_rec.valor_despesa_invoice, true);',
'        apex_json.write(''valor_total_condicao_venda'', p_rec.valor_total_condicao_venda, true);',
'        apex_json.write(''valor_compensado'', p_rec.valor_compensado, true);',
'        apex_json.write(''ind_situacao_titulo_pagamento'', p_rec.ind_situacao_titulo_pagamento, true);',
'        apex_json.write(''ind_divergencia'', p_rec.ind_divergencia, true);',
'        apex_json.write(''ind_tratamento_saldo'', p_rec.ind_tratamento_saldo, true);',
'        apex_json.write(''valor_invoice_informado'', p_rec.valor_invoice_informado, true);',
'        apex_json.write(''data_coleta_local_origem_real'', p_rec.data_coleta_local_origem_real, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    function detalhe_registro (',
'        p_id in imp_invoice.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''[',
'            select ',
'                b.nome_fantasia as imp_invoice$id_tenant,',
'                a.num_invoice as imp_invoice$num_invoice, ',
'                bo_ng_pessoa.retorna_pessoa(a.id_exportador) as imp_invoice$id_exportador, ',
'                bo_ng_pessoa.retorna_pessoa(a.id_importador) as imp_invoice$id_importador, ',
'                to_char(a.valor_total_condicao_venda, ''FM999G999G990D00'') as imp_invoice$valor_total_condicao_venda',
'            from imp_invoice a ',
'            join mpd_tenant b on b.id = a.id_tenant',
'            where a.id = ]''||p_id);',
'    end detalhe_registro;',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        v_new.valor_total_condicao_venda := nvl(v_new.valor_total_mercadoria,0) - nvl(v_new.valor_desconto,0) + nvl(v_new.valor_despesa_invoice,0);',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'',
'        pkg_traducao.grava_traducao(v_new.motivo_desconto,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'        if v_operacao = ''INCLUI_INVOICE_ENTREGA'' then',
'            bo_imp_processoimportacao.gerencia_invoice_entrega_item(''entrega'', v_id_entrega, v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
'        v_new.valor_total_condicao_venda := nvl(v_new.valor_total_mercadoria,0) - nvl(v_new.valor_desconto,0) + nvl(v_new.valor_despesa_invoice,0);',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id number;',
'    begin ',
'        --pkg_traducao.grava_traducao(v_new.motivo_desconto,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'        if v_operacao in (''ALTERA_DESCONTO'',''ATUALIZA_VALORES'',''ALTERA_VALORES'') then',
'            if v_old.valor_total_financeiro != v_new.valor_total_financeiro then',
'                gerar_parcelas_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            end if;',
'            if v_operacao = ''ALTERA_DESCONTO'' then',
'                --altera_valor_desconto_invoice_item(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                --Chama o maestro',
'                l_id := pkg_maestro_api.postar_requisicao(',
'                    p_codigo_artefato => ''PR3'', --altera_valor_desconto_invoice_item',
'                    p_id_tenant       => v_old.id_tenant,',
'                    p_id_usuario      => v_old.id_usuario_alterou,',
'                    p_id_negocio      => v_old.id,',
'                    p_payload         => ''{"id_invoice":"''||v_new.id||''"}'',',
'                    p_prioridade      => 0,',
'                    p_tipo_acao       => ''Origem: BO_IMP_INVOICE.hook_depois_alterar'',',
'                    p_id_correlation  => null',
'                );',
'',
'            end if;',
'        elsif v_operacao = ''CONCLUI_INVOICE'' and v_new.ind_status = 3 then',
'            aprova_invoice(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            bo_fin_titulopagamento.gerencia_titulo_invoice(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            altera_ind_divergencia(''N'',v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            trata_saldo_entrega_item(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        elsif v_operacao = ''ALTERA_ID_CONDICAOPAGAMENTO'' then',
'            gerar_parcelas_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao in (''ALTERA_DADOS_GERAIS'',''ALTERA_ID_CONDICAOPAGAMENTO'') then',
'            gerencia_divergencias(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
unistr('        -- Deve excluir os itens da invoice antes de excluir a pr\00F3pria invoice para evitar conflitos com os gatilhos do banco relacionados as FKs:'),
'        exclui_invoice_item(v_old.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'        ',
unistr('        -- Descompensa os t\00EDtulos compensados, se houver:'),
'        descompensa_pagamento_excluir_invoice(v_old.id, v_pagina, p_encadeado, p_sucesso, p_messages);        ',
'        --',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
'        altera_entrega_id_invoice(v_old.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'    end;',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
