'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.data_coleta_local_origem_real''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''data_coleta_local_origem_real'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;',
'    end hook_valida_data_coleta_local_origem_real;',
'    --',
'    procedure cancela_saldo(',
'        p_id in imp_invoice.id%type,',
'        p_ind_saldo in varchar2,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        if p_ind_saldo is null then',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_codigo_mensagem => ''102'',',
'                p_nome_campo => ''saldo_invoice'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;       ',
'        elsif p_ind_saldo = ''1'' then',
'            null;',
unistr('            --L\00F3gica para cancelar o saldo:'),
'        end if;',
'        if v_messages.count > 0 then',
'            RAISE pk_exceptions.e_erro;',
'        else',
'            altera_ind_tratamento_saldo(',
'                p_id => p_id,',
'                p_ind_tratamento_saldo => p_ind_saldo,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end cancela_saldo;',
'    --',
'    procedure altera_dados_gerais(',
'        p_num_invoice in imp_invoice.num_invoice%type,',
'        p_data_invoice in imp_invoice.data_invoice%type,',
'        p_id_incoterm in imp_invoice.id_incoterm%type,',
'        p_id_moeda in imp_invoice.id_moeda%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_dados_gerais'';        ',
'',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.num_invoice := p_num_invoice;',
'        v_new.data_invoice := p_data_invoice;',
'        v_new.id_incoterm := p_id_incoterm;',
'        v_new.id_moeda := p_id_moeda;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_DADOS_GERAIS'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
'    end altera_dados_gerais;',
'    --',
'    procedure atualiza_valores(        ',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_invoice_existe number;',
'        l_verifica_itens number;',
'        l_verifica_despesas number;',
'        l_peso_liquido number;',
'        l_peso_bruto number;',
'        l_valor_total_mercadoria number;',
'        l_valor_desconto number;',
'        l_valor_despesa_invoice number;',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.atualiza_valores'';',
'',
'        select count(1) into l_invoice_existe from imp_invoice where id = p_id;',
'        if l_invoice_existe > 0 then',
'            select * into v_old from imp_invoice where id = p_id;        ',
'            v_new := v_old;',
'',
'            select count(1) into l_verifica_itens from imp_invoice_item where id_invoice = p_id;',
'            if l_verifica_itens > 0 then',
'                select ',
'                    sum(nvl(peso_liquido_total,0)),',
'                    sum(nvl(peso_bruto_total,0)),',
'                    sum(nvl(quantidade,0) * (nvl(valor_unitario,0) - nvl(valor_desconto,0))),',
'                    sum(nvl(quantidade,0) * nvl(valor_desconto,0))',
'                into',
'                    l_peso_liquido,',
'                    l_peso_bruto,',
'                    l_valor_total_mercadoria,',
'                    l_valor_desconto',
'                from imp_invoice_item',
'                where id_invoice = p_id;',
'            else',
'                l_peso_liquido := 0;',
'                l_peso_bruto := 0;',
'                l_valor_total_mercadoria := 0;',
'                l_valor_desconto := 0;',
'            end if;',
'',
'            select count(1) into l_verifica_despesas from imp_invoice_despesa where id_invoice = p_id and lower(ind_incluso_valor_mercadoria) = ''n'';',
'            if l_verifica_despesas > 0 then',
'                select sum(nvl(valor,0)) into l_valor_despesa_invoice from imp_invoice_despesa where id_invoice = p_id and lower(ind_incluso_valor_mercadoria) = ''n'';',
'            else',
'                l_valor_despesa_invoice := 0;',
'            end if;',
'',
'            v_new.peso_liquido := l_peso_liquido;',
'            v_new.peso_bruto := l_peso_bruto;',
'            v_new.valor_total_mercadoria := l_valor_total_mercadoria;',
'            --v_new.valor_desconto := l_valor_desconto;',
'            v_new.valor_despesa_invoice := l_valor_despesa_invoice;',
'            v_new.valor_total_condicao_venda := (l_valor_total_mercadoria - v_new.valor_desconto + l_valor_despesa_invoice);',
'',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'            --v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''ATUALIZA_VALORES'';',
'            grava(p_id,p_encadeado,p_sucesso,p_messages);',
'        end if;',
'    end atualiza_valores;',
'    --',
'    procedure altera_desconto(',
'        p_valor_desconto in imp_invoice.valor_desconto%type,',
'        p_motivo_desconto in imp_invoice.motivo_desconto%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_valor_desconto number;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice.altera_desconto'';',
'',
'        select * into v_old from imp_invoice where id = p_id;',
'        v_new := v_old;',
'        ',
'        if nvl(p_valor_desconto,0) > 0 and p_motivo_desconto is null then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.motivo_desconto''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''motivo_desconto'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        elsif (v_new.valor_total_condicao_venda + nvl(v_new.valor_desconto,0) - nvl(p_valor_desconto,0)) <> v_new.valor_invoice_informado then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''117'',',
'                p_nome_campo => ''valor_total_condicao_venda'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        elsif p_valor_desconto <> v_new.valor_desconto then',
'            v_new.valor_desconto := p_valor_desconto;',
'            v_new.motivo_desconto := p_motivo_desconto;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'            v_new.valor_total_financeiro := (nvl(v_old.valor_total_financeiro,0) + nvl(v_old.valor_desconto,0) - nvl(v_new.valor_desconto,0));',
'',
'            v_operacao := ''ALTERA_DESCONTO'';',
'',
'            grava(p_id, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_messages.count = 0 then',
unistr('            -- Verificar melhores op\00E7\00F5es(fluxo) para tratar diverg\00EAncias:'),
'            gerencia_divergencias(p_id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_desconto;',
'    --',
'    procedure gerencia_divergencias(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant number;',
'        l_existe_divergencia number;',
'        l_id number;',
'        cursor c_divergencia is',
'            select distinct',
'                a.id                   as inv_id,',
'                a.id_exportador        as inv_exportador,',
'                a.id_importador        as inv_importador,',
'                a.id_adquirente        as inv_adquirente,',
'                a.id_condicaopagamento as inv_condicaopagamento,',
'                a.id_incoterm          as inv_incoterm,',
'                a.id_moeda             as inv_moeda,',
'                c.id                   as entrega_id,',
'                c.id_exportador        as ent_exportador,',
'                c.id_importador        as ent_importador,',
'                c.id_adquirente        as ent_adquirente,',
'                d.id_condicaopagamento as ped_condicaopagamento,',
'                c.id_incoterm          as ent_incoterm,',
'                d.id_moeda             as ped_moeda',
'            from imp_invoice a',
'            join imp_invoice_item b on b.id_invoice = a.id',
'            join imp_entrega c on c.id = b.id_entrega',
'            join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'            where a.id = p_id',
'              and (',
'                    nvl(a.id_exportador, -1)        <> nvl(c.id_exportador, -1)        or',
'                    nvl(a.id_importador, -1)        <> nvl(c.id_importador, -1)        or',
'                    nvl(a.id_adquirente, -1)        <> nvl(c.id_adquirente, -1)        or',
'                    nvl(a.id_condicaopagamento, -1) <> nvl(d.id_condicaopagamento, -1) or',
'                    nvl(a.id_incoterm, -1)          <> nvl(c.id_incoterm, -1)          or ',
'                    nvl(a.id_moeda, -1)             <> nvl(d.id_moeda, -1)',
'                  );',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.gerencia_divergencias'';',
'        select id_tenant into l_id_tenant from imp_invoice where id = p_id;',
'',
unistr('        -- Exclui todas as diverg\00EAncias existentes da invoice:'),
'        for divergencia in (',
'            select id from imp_invoice_divergencia where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_divergencia.exclui_registro(',
'                p_id => divergencia.id,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'',
unistr('        -- Verifica e inclui diverg\00EAncias entre as entregas e a invoice:'),
'        for r in c_divergencia loop',
unistr('            -- Diverg\00EAncia entre exportador da entrega e exportador da invoice:'),
'            if nvl(r.inv_exportador, -1) <> nvl(r.ent_exportador, -1) then',
'                select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id and ind_divergencia = 1 and conteudo_pedido = r.ent_exportador;',
'                if l_existe_divergencia = 0 then',
'                    bo_imp_invoice_divergencia.inclui_registro(',
'                        p_id_tenant => l_id_tenant,',
'                        p_id_invoice => p_id,',
'                        p_id_invoice_item => null,',
'                        p_ind_divergencia => 1,',
'                        p_conteudo_invoice => r.inv_exportador,',
'                        p_conteudo_pedido => r.ent_exportador,',
'                        p_ind_status => 1,',
'                        p_observacao => null,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'',
unistr('            -- Diverg\00EAncia entre importador da entrega e importador da invoice:'),
'            if nvl(r.inv_importador, -1) <> nvl(r.ent_importador, -1) then',
'                select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id and ind_divergencia = 2 and conteudo_pedido = r.ent_importador;',
'                if l_existe_divergencia = 0 then',
'                    bo_imp_invoice_divergencia.inclui_registro(',
'                        p_id_tenant => l_id_tenant,',
'                        p_id_invoice => p_id,',
'                        p_id_invoice_item => null,',
'                        p_ind_divergencia => 2,',
'                        p_conteudo_invoice => r.inv_importador,',
'                        p_conteudo_pedido => r.ent_importador,',
'                        p_ind_status => 1,',
'                        p_observacao => null,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'',
unistr('            -- Diverg\00EAncia entre adquirente da entrega e adquirente da invoice:'),
'            if nvl(r.inv_adquirente, -1) <> nvl(r.ent_adquirente, -1) then',
'                select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id and ind_divergencia = 3 and conteudo_pedido = r.ent_adquirente;',
'                if l_existe_divergencia = 0 then',
'                    bo_imp_invoice_divergencia.inclui_registro(',
'                        p_id_tenant => l_id_tenant,',
'                        p_id_invoice => p_id,',
'                        p_id_invoice_item => null,',
'                        p_ind_divergencia => 3,',
'                        p_conteudo_invoice => nvl(r.inv_adquirente, -1),',
'                        p_conteudo_pedido => nvl(r.ent_adquirente, -1),',
'                        p_ind_status => 1,',
'                        p_observacao => null,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'',
unistr('            -- Diverg\00EAncia entre condi\00E7\00E3o de pagamento do pedido e condi\00E7\00E3o de pagamento da invoice:'),
'            if nvl(r.inv_condicaopagamento, -1) <> nvl(r.ped_condicaopagamento, -1) then',
'                select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id and ind_divergencia = 4 and conteudo_pedido = r.ped_condicaopagamento;',
'                if l_existe_divergencia = 0 then',
'                    bo_imp_invoice_divergencia.inclui_registro(',
'                        p_id_tenant => l_id_tenant,',
'                        p_id_invoice => p_id,',
'                        p_id_invoice_item => null,',
'                        p_ind_divergencia => 4,',
'                        p_conteudo_invoice => r.inv_condicaopagamento,',
'                        p_conteudo_pedido => r.ped_condicaopagamento,',
'                        p_ind_status => 1,',
'                        p_observacao => null,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'',
unistr('            -- Diverg\00EAncia entre incoterm da entrega e incoterm da invoice:'),
'            if nvl(r.inv_incoterm, -1) <> nvl(r.ent_incoterm, -1) then',
'                select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id and ind_divergencia = 5 and conteudo_pedido = r.ent_incoterm;',
'                if l_existe_divergencia = 0 then',
'                    bo_imp_invoice_divergencia.inclui_registro(',
'                        p_id_tenant => l_id_tenant,',
'                        p_id_invoice => p_id,',
'                        p_id_invoice_item => null,',
'                        p_ind_divergencia => 5,',
'                        p_conteudo_invoice => r.inv_incoterm,',
'                        p_conteudo_pedido => r.ent_incoterm,',
'                        p_ind_status => 1,',
'                        p_observacao => null,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'',
unistr('            -- Diverg\00EAncia entre moeda do pedido e moeda da invoice:'),
'            if nvl(r.inv_moeda, -1) <> nvl(r.ped_moeda, -1) then',
'                select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id and ind_divergencia = 6 and conteudo_pedido = r.ped_moeda;',
'                if l_existe_divergencia = 0 then',
'                    bo_imp_invoice_divergencia.inclui_registro(',
'                        p_id_tenant => l_id_tenant,',
'                        p_id_invoice => p_id,',
'                        p_id_invoice_item => null,',
'                        p_ind_divergencia => 6,',
'                        p_conteudo_invoice => r.inv_moeda,',
'                        p_conteudo_pedido => r.ped_moeda,',
'                        p_ind_status => 1,',
'                        p_observacao => null,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;            ',
'        end loop;',
'',
unistr('        -- Verifica e inclui diverg\00EAncias entre os itens da entrega e os itens da invoice:'),
'        for item in (',
'            select id from imp_invoice_item where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_item.gerencia_divergencias(',
'                p_id => item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'',
'        -- Verifica e atualiza imp_invoice.ind_divergencia:',
'        select count(1) into l_existe_divergencia from imp_invoice_divergencia where id_invoice = p_id;',
'        if l_existe_divergencia > 0 then',
'            altera_ind_divergencia(',
'                p_ind_divergencia => ''S'',',
'                p_id => p_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        else',
'            altera_ind_divergencia(',
'                p_ind_divergencia => ''N'',',
'                p_id => p_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'',
'    end gerencia_divergencias;',
'    --',
'    procedure altera_ind_divergencia(',
'        p_ind_divergencia in imp_invoice.ind_divergencia%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table       ',
'    ) is',
'    begin        ',
'        v_parametro(0) := ''bo_imp_invoice.altera_ind_divergencia'';',
'',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.ind_divergencia := p_ind_divergencia; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_IND_DIVERGENCIA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_ind_divergencia;',
'    --',
'    procedure conclui_invoice(',
'        p_ind_status in imp_invoice.ind_status%type,',
'        p_observacao in imp_observacao.observacao%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade number;',
'        l_id number;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();        ',
'        v_parametro(0) := ''bo_imp_invoice.conclui_invoice'';',
'',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        if v_new.valor_total_condicao_venda <> v_new.valor_invoice_informado /*and p_ind_status = 3*/ then            ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice.valor_invoice_informado'');',
'            v_parametro(2) := lower(pkg_ui.retorna_label_coluna(''imp_invoice.valor_total_condicao_venda'')); ',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''112'',',
'                p_nome_campo => ''valor_invoice_informado'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        else    ',
'            v_new.ind_status := p_ind_status;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'            v_new.data_alteracao := sysdate;  ',
'',
'            v_operacao := ''CONCLUI_INVOICE'';',
'            grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
unistr('            -- Inclui a observa\00E7\00E3o se n\00E3o houver erros:'),
'            if v_messages.count = 0 then',
'                if p_observacao is not null then',
'                    select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_invoice'';',
'                    bo_imp_observacao.inclui_registro(',
'                        p_id_tenant => v_new.id_tenant,',
'                        p_id_entidade => l_id_entidade,',
'                        p_observacao => p_observacao,',
'                        p_id_referencia => v_new.id,',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end conclui_invoice;',
'    --',
'    procedure gerar_parcelas_pagamento(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_data_confirmacao_pedido imp_pedidoimportacao.data_confirmacao_pedido%type;',
'        l_id number;        ',
'        l_verifica_parcelas number;',
'    begin',
unistr('        -- Verifica data de confirma\00E7\00E3o do pedido'),
'        select distinct ',
'            data_confirmacao_pedido',
'        into',
'            l_data_confirmacao_pedido',
'        from imp_invoice a',
'        join imp_invoice_item b on b.id_invoice = a.id                ',
'        join imp_entrega c on c.id = b.id_entrega',
'        join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'        where a.id = p_id',
'        fetch first 1 row only;',
'',
'        -- Verifica se existem parcelas:',
'        select count(1) into l_verifica_parcelas from imp_invoice_pagamento where id_invoice = p_id;',
'        if l_verifica_parcelas > 0 then',
unistr('            -- OBS. VERIFICAR COMPORTAMENTO DEFINIDO PARA ESSA SITUA\00C7\00C3O:'),
unistr('            -- Definido pelo prot\00F3tipo IMP000190 em 13/02/2026'),
'',
'            -- Exclui as parcelas antigas',
'            for old_parcela in (',
'                select id from im'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(149415029355581434)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'p_invoice_pagamento where id_invoice = p_id',
'            ) loop',
'                bo_imp_invoice_pagamento.exclui_registro(old_parcela.id, p_encadeado, p_sucesso, p_messages);',
'            end loop;',
unistr('            -- -- Repete a chamada para garantir consist\00EAncia entre exclus\00E3o e descompensa\00E7\00E3o:'),
'            -- for old_parcela in (',
'            --     select id from imp_invoice_pagamento where id_invoice = p_id',
'            -- ) loop',
'            --     bo_imp_invoice_pagamento.exclui_registro(old_parcela.id, p_encadeado, p_sucesso, p_messages);',
'            -- end loop;',
'        end if;',
'',
'        -- Gera as novas parcelas',
'        for parcela in (',
'            select ',
'                distinct c.id,                ',
'                a.id_tenant,',
'                c.numero_parcela,',
'                c.percentual,                    ',
'                nvl(((c.percentual / 100) * a.valor_total_financeiro/*a.valor_total_condicao_venda*/),0) valor,',
'                c.qtd_dias_evento,',
'                c.ind_evento_gerador_pagamento,',
'                case when c.ind_evento_gerador_pagamento = 1 then 2 else 1 end status',
'            from imp_invoice a',
'            join ng_condicaopagamento b on b.id = a.id_condicaopagamento',
'            join ng_condicaopagamento_parcela c on c.id_condicaopagamento = b.id',
'            where a.id = p_id',
'            order by numero_parcela',
'        ) loop            ',
'            bo_imp_invoice_pagamento.inclui_registro(',
'                p_id_tenant => parcela.id_tenant,',
'                p_id_invoice => p_id,',
'                p_id_entrega => null,',
'                p_numero_parcela => parcela.numero_parcela,',
'                p_percentual => parcela.percentual,',
'                p_valor => parcela.valor,',
'                p_data_vencimento_prevista => (l_data_confirmacao_pedido + parcela.qtd_dias_evento),',
'                p_data_vencimento_real => null,',
'                p_ind_status_pagamento => 1,--parcela.status,(?)',
'                p_ind_multa_atraso_pagamento => ''N'',',
'                p_valor_multa => null,',
'                p_valor_compensado => null,',
'                p_percentual_multa => null,',
'                p_periodo_multa => null,',
'                p_ind_bloqueado => ''N'',',
'                p_condicao_desbloqueio => null,',
'                p_data_desbloqueio => null,',
'                p_id_usuario_desbloqueio => null,',
'                p_instrucao_contas_pagar => null,',
'                p_id => l_id,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end gerar_parcelas_pagamento;',
'    --',
'    procedure inclui_invoice_entrega(',
'        p_id_entrega in varchar2,',
'        p_id_tenant in imp_invoice.id_tenant%type,',
'        p_id_processoimportacao in imp_invoice.id_processoimportacao%type,',
'        p_num_invoice in imp_invoice.num_invoice%type,',
'        p_data_invoice in imp_invoice.data_invoice%type,',
'        p_id_exportador in imp_invoice.id_exportador%type,',
'        p_id_importador in imp_invoice.id_importador%type,',
'        p_id_adquirente in imp_invoice.id_adquirente%type,',
'        p_id_condicaopagamento in imp_invoice.id_condicaopagamento%type,',
'        p_id_incoterm in imp_invoice.id_incoterm%type,',
'        p_id_moeda in imp_invoice.id_moeda%type,',
'        p_valor_invoice_informado in imp_invoice.valor_invoice_informado%type,',
'        p_id out imp_invoice.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin ',
'        v_parametro(0) := ''bo_imp_invoice.inclui_invoice_entrega'';   ',
'        v_pagina := p_pagina; ',
'        v_id_entrega := p_id_entrega;',
'',
'        v_new.id := p_id;',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_processoimportacao := p_id_processoimportacao;',
'        v_new.num_invoice := p_num_invoice;',
'        v_new.data_invoice := p_data_invoice;',
'        v_new.id_exportador := p_id_exportador;',
'        v_new.id_importador := p_id_importador;',
'        v_new.id_adquirente := p_id_adquirente;',
'        v_new.id_condicaopagamento := p_id_condicaopagamento;',
'        v_new.id_incoterm := p_id_incoterm;',
'        v_new.id_moeda := p_id_moeda;',
'        v_new.valor_invoice_informado := p_valor_invoice_informado;',
'        v_new.ind_divergencia := ''N'';',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao := sysdate; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;',
'        -- Colunas com valor_default:',
'        v_new.valor_total_financeiro := 0;',
'        v_new.ind_status := 1;',
'        v_new.ind_forma_pagamento := 1;',
'        v_new.peso_liquido := 0;',
'        v_new.peso_bruto := 0;',
'        v_new.valor_total_mercadoria := 0;',
'        v_new.valor_desconto := 0;',
'        v_new.valor_despesa_invoice := 0;',
'        v_new.valor_total_condicao_venda := 0;',
'        v_new.valor_compensado := 0;',
'        v_new.ind_situacao_titulo_pagamento := ''N'';',
'        ',
'        v_operacao := ''INCLUI_INVOICE_ENTREGA'';',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);',
'    end inclui_invoice_entrega;',
'    --    ',
'    function retorna_valor_total_desconto_invoice_item(',
'        p_id in imp_invoice.id%type,',
'        p_id_invoice_item in imp_invoice_item.id%type',
'    ) return number is',
'        l_valor_total_mercadoria number;',
'        l_valor_desconto_total   number;',
'        l_resultado number;',
'        l_base_int  number;',
'        l_soma_base_int number;',
'        l_total_int     number;',
'        l_resto         number;',
'        l_item_ajuste number;',
'    begin',
'        -- Total da mercadoria:',
'        select sum(a.valor_total_mercadoria)',
'        into l_valor_total_mercadoria',
'        from imp_invoice_item a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where a.id_invoice = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Valor total desconto:',
'        select nvl(valor_desconto, 0)',
'        into l_valor_desconto_total',
'        from imp_invoice',
'        where id = p_id;',
'',
'        -- Valor proporcional do item:',
'        select ',
'            (l_valor_desconto_total * (a.valor_total_mercadoria / l_valor_total_mercadoria))',
'        into l_resultado',
'        from imp_invoice_item a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where a.id = p_id_invoice_item',
'        and a.id_invoice = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Base em 5 casas (inteiro):',
'        l_base_int := trunc(l_resultado * 100000);',
'',
'        -- Soma total truncada:',
'        select sum(trunc(',
'            (l_valor_desconto_total * (a.valor_total_mercadoria / l_valor_total_mercadoria)) * 100000',
'        ))',
'        into l_soma_base_int',
'        from imp_invoice_item a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where a.id_invoice = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Total correto:',
'        l_total_int := trunc(l_valor_desconto_total * 100000);',
'',
unistr('        -- Diferen\00E7a (res\00EDduo):'),
'        l_resto := l_total_int - l_soma_base_int;',
'',
'        -- Item que recebe ajuste(menor id):',
'        select min(a.id)',
'        into l_item_ajuste',
'        from imp_invoice_item a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where a.id_invoice = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Aplica ajuste:',
'        if p_id_invoice_item = l_item_ajuste then',
'            l_base_int := l_base_int + l_resto;',
'        end if;',
'',
'        -- Retorno final:',
'        return l_base_int / 100000;',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_valor_total_desconto_invoice_item;',
'    --',
'    procedure altera_valor_desconto_invoice_item(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_valor_desconto_invoice_item'';',
'        for item in (',
'            select id from imp_invoice_item where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_item.altera_valor_total_desconto_invoice_item(',
'                p_valor_total_desconto_invoice_item => retorna_valor_total_desconto_invoice_item(p_id, item.id),',
'                p_id => item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_valor_desconto_invoice_item;',
'    --',
'    procedure aprova_invoice(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.aprova_invoice'';',
'',
'        for divergencia in (',
'            select id from imp_invoice_divergencia where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_divergencia.altera_ind_status(',
'                p_ind_status => 2,',
'                p_id => divergencia.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end aprova_invoice;',
'    --',
'    procedure desaprova_invoice(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin        ',
'        v_parametro(0) := ''bo_imp_invoice.desaprova_invoice'';',
'',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.ind_status := 2;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''DESAPROVA_INVOICE'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
unistr('        -- Exclui os t\00EDtulos de pagamento (data_vencimento > current_date):'),
'        if v_messages.count = 0 then',
'            for titulopagamento in (',
'                select ',
'                    a.id',
'                from fin_titulopagamento a ',
'                join srv_entidade b on b.id = a.id_entidade',
'                join imp_invoice_pagamento c on c.id = a.id_referencia',
'                where lower(b.nome_entidade) = ''imp_invoice'' ',
'                and c.id_invoice = p_id',
'                and a.data_vencimento > current_date',
'            ) loop',
'                bo_fin_titulopagamento.altera_ind_status_pagamento(  ',
'                    p_ind_status_pagamento => 3,',
'                    p_id                   => titulopagamento.id,',
'                    p_pagina               => p_pagina,',
'                    p_encadeado            => p_encadeado,',
'                    p_sucesso              => p_sucesso,',
'                    p_messages             => p_messages',
'                );',
'            end loop;',
'        end if;',
'    end desaprova_invoice;',
'    --',
'    procedure altera_ind_tratamento_saldo(',
'        p_id in imp_invoice.id%type,',
'        p_ind_tratamento_saldo in imp_invoice.ind_tratamento_saldo%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_ind_tratamento_saldo'';   ',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.ind_tratamento_saldo := p_ind_tratamento_saldo;        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_IND_TRATAMENTO_SALDO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_ind_tratamento_saldo;',
'    --    ',
'    procedure altera_id_condicaopagamento(        ',
'        p_id_condicaopagamento in imp_invoice.id_condicaopagamento%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_id_condicaopagamento'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_invoice where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.id_condicaopagamento := p_id_condicaopagamento;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_ID_CONDICAOPAGAMENTO'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_id_condicaopagamento;',
'    --',
'    procedure altera_ind_status(',
'        p_ind_status in imp_invoice.ind_status%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_ind_status'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.ind_status := p_ind_status;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_IND_STATUS'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_ind_status;',
'    --',
'',
'    procedure altera_id_processoimportacao(',
'        p_id_processoimportacao in imp_invoice.id_processoimportacao%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_pagina := p_pagina; ',
'        select * into v_old from imp_invoice where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.id_processoimportacao := p_id_processoimportacao;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        grava(p_id,p_encadeado,p_sucesso,p_messages); ',
'',
'    end altera_id_processoimportacao;',
'    --',
'    procedure altera_entrega_id_invoice(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin ',
'        for entrega in (',
'            select id from imp_entrega where id_invoice = p_id',
'        ) loop',
'            bo_imp_entrega.altera_id_invoice(',
'                p_id_invoice => null,',
'                p_id => entrega.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_entrega_id_invoice;',
'    --    ',
'    procedure exclui_invoice_item(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for invoice_item in (',
'            select id from imp_invoice_item where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_item.exclui_invoice_item(',
'                p_id => invoice_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end exclui_invoice_item;',
'    --',
'    procedure trata_saldo_entrega_item(',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table ',
'    ) is',
'        l_ids_entrega_item number;',
'    begin',
'        -- Tratamento (1 - Cancelar o saldo no pedido):',
'        for pedidoimportacao_item in (',
'            select sum(a.quantidade_saldo) saldo_cancelar, d.id, d.quantidade, a.id id_entrega_item',
'            from imp_entrega_item a',
'            join imp_invoice_item b on b.id_entrega_item = a.id',
'            join imp_entrega c on c.id = a.id_entrega ',
'            join imp_pedidoimportacao_item d on d.id = a.id_pedidoimportacao_item',
'            where c.id_invoice = p_id',
'            and a.quantidade_saldo > 0',
'            and a.ind_tratamento_saldo = 1',
'            group by d.id, d.quantidade, a.id',
'        ) loop',
'            -- Atualiza as quantidades e valores do item da entrega:',
'            bo_imp_entrega_item.altera_registro_ind_tratamento_saldo(',
'                p_id => pedidoimportacao_item.id_entrega_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
unistr('            -- Atualiza as quantidade e valores do item do pedido de importa\00E7\00E3o:'),
'            bo_imp_pedidoimportacao_item.altera_registro_ind_tratamento_saldo(',
'                p_quantidade => (pedidoimportacao_item.quantidade - pedidoimportacao_item.saldo_cancelar),',
'                p_id => pedidoimportacao_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );            ',
'        end loop;',
'',
'        -- Tratamento (2- Vincular o saldo a proxima entrega):',
'        for entrega in (',
'            select id_pedidoimportacao ',
'            from imp_entrega ',
'            where id_invoice = p_id ',
'            group by id_pedidoimportacao ',
'            order by id_pedidoimportacao',
'        ) loop        ',
'            select listagg(a.id,'','') within group (order by a.id) ',
'            into l_ids_entrega_item',
'            from imp_entrega_item a',
'            join imp_entrega b on b.id = a.id_entrega',
'            join imp_invoice c on c.id = b.id_invoice',
'            where a.quantidade_saldo > 0',
'            and a.ind_tratamento_saldo = 2',
'            and b.id_pedidoimportacao = entrega.id_pedidoimportacao',
'            and c.id = p_id;',
'            ',
'            if l_ids_entrega_item is not null then',
unistr('                -- Vincula em pr\00F3xima entrega ou gera nova entrega:'),
'                bo_imp_entrega_item.tratamento_saldo_vincular(',
'                    p_ids => l_ids_entrega_item,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end if;',
'        end loop;',
'    end trata_saldo_entrega_item;',
'    --',
'    procedure altera_valores(  ',
'        p_valor_total_mercadoria in imp_invoice.valor_total_mercadoria%type,',
'        p_valor_total_financeiro in imp_invoice.valor_total_financeiro%type,',
'        p_id in imp_invoice.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_valores'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_invoice where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.valor_total_mercadoria := p_valor_total_mercadoria;',
'        v_new.valor_total_financeiro := p_valor_total_financeiro;        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_VALORES'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_valores;',
'    --',
'    function retorna_valor_total_financeiro(',
'        p_id in imp_invoice.id%type',
'    ) return number is',
'        l_valor_total_financeiro number;',
'    begin',
'        select (nvl(sum(b.valor_total_mercadoria), 0) - a.valor_desconto + a.valor_despesa_invoice)',
'        into l_valor_total_financeiro',
'        from imp_invoice a ',
'        join imp_invoice_item b on b.id_invoice = a.id',
'        join imp_entrega_item c on c.id = b.id_entrega_item',
'        join imp_naturezaoperacao_parametro d on d.id_naturezaoperacao = c.id_naturezaoperacao',
'        where b.id_invoice = p_id',
'        and d.ind_gera_financeiro = ''S''',
'        group by a.valor_desconto, a.valor_despesa_invoice;',
'',
'        return trunc(l_valor_total_financeiro, 2);',
'    end retorna_valor_total_financeiro;',
'    --',
'    procedure descompensa_pagamento_excluir_invoice(',
'        p_id        in imp_invoice.id%type,',
'        p_pagina    in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for invoice_pagamento in (',
'            select id from imp_invoice_pagamento where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_pagamento.descompensa_pagamento(',
'                p_id        => invoice_pagamento.id,',
'                p_pagina    => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso   => p_sucesso,',
'                p_messages  => p_messages',
'            );',
'        end loop;',
'    end descompensa_pagamento_excluir_invoice;',
'    --',
'    procedure aprova_todas_divergencias(',
'        p_id in imp_invoice.id%type,',
'        --p_pagina in number default 0, ',
'        --p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for divergencia in (',
'            select id from imp_invoice_divergencia where id_invoice = p_id',
'        ) loop',
'            bo_imp_invoice_divergencia.altera_ind_status(',
'                p_ind_status => 2,',
'                p_id         => divergencia.id,',
'                --p_pagina     => p_pagina,',
'                --p_encadeado  => p_encadeado,',
'                p_sucesso    => p_sucesso,',
'                p_messages   => p_messages',
'            );',
'        end loop;',
'    end aprova_todas_divergencias;',
'    --',
'    procedure altera_data_coleta_local_origem_real(',
'        p_data_coleta_local_origem_real in imp_invoice.data_coleta_local_origem_real%type,',
'        p_id                            in imp_invoice.id%type,',
'        p_pagina                        in number default 0,',
'        p_encadeado                     in boolean default false,',
'        p_sucesso                       out clob,',
'        p_messages                      out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice.altera_data_coleta_local_origem_real'';',
'        v_pagina       := p_pagina;',
'        --',
'        select * into v_old from imp_invoice where id = p_id;',
'        v_new := v_old;',
'        --',
'        v_new.data_coleta_local_origem_real := p_data_coleta_local_origem_real;',
'        v_new.id_usuario_alterou            := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao                := sysdate;  ',
'        --',
'        v_operacao := ''ALTERA_DATA_COLETA_LOCAL_ORIGEM_REAL'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_data_coleta_local_origem_real;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_invoice;',
'/'))
);
end;
/
