unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_invoice_pagamento.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into imp_invoice_pagamento (  ',
'            id_tenant,',
'            id_invoice,',
'            id_entrega,',
'            numero_parcela,',
'            percentual,',
'            valor,',
'            data_vencimento_prevista,',
'            data_vencimento_real,',
'            ind_status_pagamento,',
'            ind_multa_atraso_pagamento,',
'            valor_multa,',
'            percentual_multa,',
'            periodo_multa,',
'            ind_bloqueado,',
'            condicao_desbloqueio,',
'            data_desbloqueio,',
'            id_usuario_desbloqueio,',
'            instrucao_contas_pagar,',
'            valor_compensar, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_tenant,',
'            v_new.id_invoice,',
'            v_new.id_entrega,',
'            v_new.numero_parcela,',
'            v_new.percentual,',
'            v_new.valor,',
'            v_new.data_vencimento_prevista,',
'            v_new.data_vencimento_real,',
'            v_new.ind_status_pagamento,',
'            v_new.ind_multa_atraso_pagamento,',
'            v_new.valor_multa,',
'            v_new.percentual_multa,',
'            v_new.periodo_multa,',
'            v_new.ind_bloqueado,',
'            v_new.condicao_desbloqueio,',
'            v_new.data_desbloqueio,',
'            v_new.id_usuario_desbloqueio,',
'            v_new.instrucao_contas_pagar,',
'            v_new.valor_compensar, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in imp_invoice_pagamento.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''In\00EDcio da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de alterar */ ',
'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update imp_invoice_pagamento set  ',
'            id_tenant = v_new.id_tenant,',
'            id_invoice = v_new.id_invoice,',
'            id_entrega = v_new.id_entrega,',
'            numero_parcela = v_new.numero_parcela,',
'            percentual = v_new.percentual,',
'            valor = v_new.valor,',
'            data_vencimento_prevista = v_new.data_vencimento_prevista,',
'            data_vencimento_real = v_new.data_vencimento_real,',
'            ind_status_pagamento = v_new.ind_status_pagamento,',
'            ind_multa_atraso_pagamento = v_new.ind_multa_atraso_pagamento,',
'            valor_multa = v_new.valor_multa,',
'            percentual_multa = v_new.percentual_multa,',
'            periodo_multa = v_new.periodo_multa,',
'            ind_bloqueado = v_new.ind_bloqueado,',
'            condicao_desbloqueio = v_new.condicao_desbloqueio,',
'            data_desbloqueio = v_new.data_desbloqueio,',
'            id_usuario_desbloqueio = v_new.id_usuario_desbloqueio,',
'            instrucao_contas_pagar = v_new.instrucao_contas_pagar,',
'            valor_compensar = v_new.valor_compensar, ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'        --',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''Fim da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end grava;',
'    --',
'    procedure inclui_registro(  ',
'        p_id_tenant in imp_invoice_pagamento.id_tenant%type,',
'        p_id_invoice in imp_invoice_pagamento.id_invoice%type,',
'        p_id_entrega in imp_invoice_pagamento.id_entrega%type,',
'        p_numero_parcela in imp_invoice_pagamento.numero_parcela%type,',
'        p_percentual in imp_invoice_pagamento.percentual%type,',
'        p_valor in imp_invoice_pagamento.valor%type,',
'        p_data_vencimento_prevista in imp_invoice_pagamento.data_vencimento_prevista%type,',
'        p_data_vencimento_real in imp_invoice_pagamento.data_vencimento_real%type,',
'        p_ind_status_pagamento in imp_invoice_pagamento.ind_status_pagamento%type,',
'        p_ind_multa_atraso_pagamento in imp_invoice_pagamento.ind_multa_atraso_pagamento%type,',
'        p_valor_multa in imp_invoice_pagamento.valor_multa%type,',
'        p_percentual_multa in imp_invoice_pagamento.percentual_multa%type,',
'        p_periodo_multa in imp_invoice_pagamento.periodo_multa%type,',
'        p_ind_bloqueado in imp_invoice_pagamento.ind_bloqueado%type,',
'        p_condicao_desbloqueio in imp_invoice_pagamento.condicao_desbloqueio%type,',
'        p_data_desbloqueio in imp_invoice_pagamento.data_desbloqueio%type,',
'        p_id_usuario_desbloqueio in imp_invoice_pagamento.id_usuario_desbloqueio%type,',
'        p_instrucao_contas_pagar in imp_invoice_pagamento.instrucao_contas_pagar%type,',
'        p_valor_compensar in imp_invoice_pagamento.valor_compensar%type, ',
'        p_id out imp_invoice_pagamento.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''inclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da inclus\00E3o de registro'''),
'        );',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.inclui_registro'';   ',
'        v_pagina := p_pagina; ',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_invoice := p_id_invoice;',
'        v_new.id_entrega := p_id_entrega;',
'        v_new.numero_parcela := p_numero_parcela;',
'        v_new.percentual := p_percentual;',
'        v_new.valor := nvl(p_valor,0);',
'        v_new.data_vencimento_prevista := p_data_vencimento_prevista;',
'        v_new.data_vencimento_real := p_data_vencimento_real;',
'        v_new.ind_status_pagamento := nvl(p_ind_status_pagamento,1);',
'        v_new.ind_multa_atraso_pagamento := nvl(p_ind_multa_atraso_pagamento,''N'');',
'        v_new.valor_multa := nvl(p_valor_multa,0);',
'        v_new.percentual_multa := nvl(p_percentual_multa,0);',
'        v_new.periodo_multa := p_periodo_multa;',
'        v_new.ind_bloqueado := nvl(p_ind_bloqueado,''N'');',
'        v_new.condicao_desbloqueio := p_condicao_desbloqueio;',
'        v_new.data_desbloqueio := p_data_desbloqueio;',
'        v_new.id_usuario_desbloqueio := p_id_usuario_desbloqueio;',
'        v_new.instrucao_contas_pagar := p_instrucao_contas_pagar;',
'        v_new.valor_compensar := nvl(p_valor_compensar,0); ',
