unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_pagamento'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_pagamento'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_pagamento'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_pagamento'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_pagamento'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_pagamento'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_invoice_pagamento%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_invoice'', p_rec.id_invoice, true);',
'        apex_json.write(''id_entrega'', p_rec.id_entrega, true);',
'        apex_json.write(''numero_parcela'', p_rec.numero_parcela, true);',
'        apex_json.write(''percentual'', p_rec.percentual, true);',
'        apex_json.write(''valor'', p_rec.valor, true);',
'        apex_json.write(''data_vencimento_prevista'', p_rec.data_vencimento_prevista, true);',
'        apex_json.write(''data_vencimento_real'', p_rec.data_vencimento_real, true);',
'        apex_json.write(''ind_status_pagamento'', p_rec.ind_status_pagamento, true);',
'        apex_json.write(''ind_multa_atraso_pagamento'', p_rec.ind_multa_atraso_pagamento, true);',
'        apex_json.write(''valor_multa'', p_rec.valor_multa, true);',
'        apex_json.write(''percentual_multa'', p_rec.percentual_multa, true);',
'        apex_json.write(''periodo_multa'', p_rec.periodo_multa, true);',
'        apex_json.write(''ind_bloqueado'', p_rec.ind_bloqueado, true);',
'        apex_json.write(''condicao_desbloqueio'', p_rec.condicao_desbloqueio, true);',
'        apex_json.write(''data_desbloqueio'', p_rec.data_desbloqueio, true);',
'        apex_json.write(''id_usuario_desbloqueio'', p_rec.id_usuario_desbloqueio, true);',
'        apex_json.write(''instrucao_contas_pagar'', p_rec.instrucao_contas_pagar, true);',
'        apex_json.write(''valor_compensar'', p_rec.valor_compensar, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
