'    --',
'    procedure altera_data_vencimento_real(',
'        p_data_vencimento_real in imp_invoice_pagamento.data_vencimento_real%type,',
'        p_ind_status_pagamento in imp_invoice_pagamento.ind_status_pagamento%type,',
'        p_id in imp_invoice_pagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.altera_data_vencimento_real'';   ',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_invoice_pagamento where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.data_vencimento_real := p_data_vencimento_real;',
'        v_new.ind_status_pagamento := nvl(p_ind_status_pagamento, v_new.ind_status_pagamento);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_DATA_VENCIMENTO_REAL'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);       ',
'    end altera_data_vencimento_real;',
'    --',
'    procedure altera_valor_compensar(        ',
'        p_json in clob,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_json clob;',
'        l_invoice_pagamento imp_invoice_pagamento%rowtype;',
'    begin ',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.altera_valor_compensar'';',
'        v_pagina := p_pagina;',
'        v_operacao := ''ALTERA_VALOR_COMPENSAR'';',
'',
'        l_json := p_json;',
'        for pagamento in (',
'            select json_parcela.id, json_parcela.data_vencimento, json_parcela.valor_compensar',
'              from json_table(l_json, ''$[*]''',
'                columns',
'                    id number path ''$.id'',',
'                    valor_compensar number path ''$.valor_compensar'',',
'                    data_vencimento varchar2(50) path ''$.data_vencimento''',
'              ) json_parcela',
'        ) loop ',
'            -- Tratamento alterar:           ',
'            select * into l_invoice_pagamento from imp_invoice_pagamento where id = pagamento.id;',
'            altera_registro(',
'                p_id_tenant => l_invoice_pagamento.id_tenant,',
'                p_id_invoice => l_invoice_pagamento.id_invoice,',
'                p_id_entrega => l_invoice_pagamento.id_entrega,',
'                p_numero_parcela => l_invoice_pagamento.numero_parcela,',
'                p_percentual => l_invoice_pagamento.percentual,',
'                p_valor => l_invoice_pagamento.valor,',
'                p_data_vencimento_prevista => to_date(pagamento.data_vencimento,''mm/dd/yyyy''),',
'                p_data_vencimento_real => l_invoice_pagamento.data_vencimento_real,',
'                p_ind_status_pagamento => l_invoice_pagamento.ind_status_pagamento,',
'                p_ind_multa_atraso_pagamento => l_invoice_pagamento.ind_multa_atraso_pagamento,',
'                p_valor_multa => l_invoice_pagamento.valor_multa,',
'                p_valor_compensar => pagamento.valor_compensar,',
'                p_percentual_multa => l_invoice_pagamento.percentual_multa,',
'                p_periodo_multa => l_invoice_pagamento.periodo_multa,',
'                p_ind_bloqueado => l_invoice_pagamento.ind_bloqueado,',
'                p_condicao_desbloqueio => l_invoice_pagamento.condicao_desbloqueio,',
'                p_data_desbloqueio => l_invoice_pagamento.data_desbloqueio,',
'                p_id_usuario_desbloqueio => l_invoice_pagamento.id_usuario_desbloqueio,',
'                p_instrucao_contas_pagar => l_invoice_pagamento.instrucao_contas_pagar,',
'                p_data_alteracao => l_invoice_pagamento.data_alteracao,',
'                p_id => l_invoice_pagamento.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_valor_compensar;',
'    --',
'    procedure gerencia_compensacao(  ',
'        p_json in clob,',
'        p_valor_compensar in varchar2,',
'        p_id in imp_invoice_pagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_valor_compensar number := to_number(p_valor_compensar);',
'        l_inconsistencia_valores number;',
'        l_saldo_compensar_maximo number;',
'        l_json clob := p_json;',
'        l_id number;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.gerencia_compensacao'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_invoice_pagamento where id = p_id;        ',
'        v_new := v_old;',
'',
'        select case when (sum(a.valor_compensar) + l_valor_compensar) > b.valor_total_financeiro then 1 else 0 end',
'        into l_inconsistencia_valores',
'        from imp_invoice_pagamento a ',
'        join imp_invoice b on b.id = a.id_invoice',
'        where b.id = v_new.id_invoice',
'        group by b.valor_total_financeiro;',
'',
'        if l_inconsistencia_valores > 0 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''152'',',
'                p_nome_campo => ''valor_compensar'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        else',
'            for titulo in (',
'                select json_titulo.id, json_titulo.valor_compensar',
'                  from json_table(l_json, ''$[*]''',
'                    columns',
'                        id varchar2(50) path ''$.id'',',
'                        valor_compensar number path ''$.valor_compensar''',
'                  ) json_titulo',
'            ) loop',
'                select saldo_compensar into l_saldo_compensar_maximo from fin_titulopagamento where id = titulo.id;',
'                if titulo.valor_compensar > l_saldo_compensar_maximo then',
'                    v_parametro(1) := pkg_ui.retorna_label_coluna(''fin_titulopagamento.valor_compensado'');',
'                    v_parametro(2) := lower(pkg_ui.retorna_label_coluna(''fin_titulopagamento.saldo_compensar''));',
'                    pkg_mensagem.mensagem_campo(',
'                        p_codigo_mensagem => ''77'',',
'                        p_nome_campo => ''valor_compensado'',',
'                        p_parametro => v_parametro,',
'                        p_pagina => v_pagina,',
'                        p_objeto_mensagem => v_message',
'                    );',
'                    v_messages.EXTEND;',
'                    v_messages(v_messages.LAST) := v_message;           ',
'                    if v_messages.count > 0 then',
'                        raise pk_exceptions.e_erro;',
'                    end if;',
'                end if;',
'                if titulo.valor_compensar > 0 then',
'                    bo_imp_titulo_compensado.inclui_registro(',
'                        p_id_tenant => v_new.id_tenant,',
'                        p_id_titulopagamento => titulo.id,',
'                        p_id_invoice_parcela => p_id,',
'                        p_valor_compensado => to_number(titulo.valor_compensar),',
'                        p_id => l_id,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end loop;',
'',
'            if p_messages.count = 0 then',
'                v_new.valor := l_valor_compensar;',
'                v_new.ind_status_pagamento := 4;',
'                v_new.valor_compensar := l_valor_compensar;         ',
'                v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'                v_new.data_alteracao := sysdate;',
'',
'                v_saldo := (v_old.valor - l_valor_compensar);',
'                v_operacao := ''GERENCIA_COMPENSACAO'';',
'                grava(p_id,p_encadeado,p_sucesso,p_messages);',
'            end if;',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end gerencia_compensacao;',
'    --',
'    procedure ajusta_parcelas(',
'        p_saldo in number,',
'        p_id in imp_invoice_pagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_saldo number := p_saldo;',
'        l_id_atual number := p_id;',
'        l_id_anterior number;',
'        l_valor_atual number;',
'        l_id number;',
'        l_id_tenant number;',
'        l_id_invoice number;',
'    begin',
'        -- Dados base da invoice:',
'        select id_tenant, id_invoice into l_id_tenant, l_id_invoice from imp_invoice_pagamento where id = p_id;',
'',
'        loop',
'            exit when l_saldo = 0;',
'            l_id_anterior := l_id_atual;',
'',
unistr('            -- Pr\00F3xima parcela eleg\00EDvel:'),
'            l_id_atual := retorna_proxima_parcela(l_id_atual);',
unistr('            -- Sem mais parcelas eleg\00EDveis:'),
'            exit when l_id_atual = 0;',
unistr('            -- Prote\00E7\00E3o loop infinito:'),
'            if l_id_atual = l_id_anterior then',
'                exit;',
'            end if;',
'            -- Valor atual:',
'            select valor into l_valor_atual from imp_invoice_pagamento where id = l_id_atual;',
'',
'            -- Tratamento remover:',
'            if l_saldo < 0 then',
'                if l_valor_atual + l_saldo >= 0 then',
'                    altera_valor(',
'                        p_valor => l_valor_atual + l_saldo,',
'                        p_id => l_id_atual,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                    l_saldo := 0;',
'                else',
'                    l_saldo := l_saldo + l_valor_atual;',
'                    altera_valor(',
'                        p_valor => 0,',
'                        p_id => l_id_atual,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            -- Tratamento adicionar:',
'            else',
'                altera_valor(',
'                    p_valor => l_valor_atual + l_saldo,',
'                    p_id => l_id_atual,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'                l_saldo := 0;',
'            end if;',
'        end loop;',
'        -- Se sobrou saldo positivo, cria nova parcela:',
'        if l_saldo > 0 then',
'            inclui_registro( ',
'                p_id_tenant => l_id_tenant,',
'                p_id_invoice => l_id_invoice,',
'                p_id_entrega => null,',
'                p_numero_parcela => gera_sequencia(l_id_invoice),',
'                p_percentual => calcula_percentual_valor_parcela(l_id_invoice, l_saldo),',
'                p_valor => l_saldo,',
'                p_data_vencimento_prevista => null,',
'                p_data_vencimento_real => null,',
'                p_ind_status_pagamento => 1,',
'                p_ind_multa_atraso_pagamento => ''N'',',
'                p_valor_multa => null,',
'                p_percentual_multa => null,',
'                p_periodo_multa => null,',
'                p_ind_bloqueado => ''N'',',
'                p_condicao_desbloqueio => null,',
'                p_data_desbloqueio => null,',
'                p_id_usuario_desbloqueio => null,',
'                p_instrucao_contas_pagar => null,',
'                p_valor_compensar => 0,',
'                p_id => l_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end ajusta_parcelas;',
'    --',
'    procedure altera_valor(  ',
'        p_valor in imp_invoice_pagamento.valor%type,',
'        p_id in imp_invoice_pagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.altera_valor'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_invoice_pagamento where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor := p_valor;        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        if v_new.valor = 0 then',
'            v_new.ind_status_pagamento := 4;',
'        end if;',
'',
'        v_operacao := ''ALTERA_VALOR'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_valor;',
'    --',
'    function retorna_proxima_parcela(',
'        p_id in imp_invoice_pagamento.id%type',
'    ) return number is',
'        l_id number;',
'    begin',
'        select id',
'        into l_id',
'        from (',
'            select p.id,',
'                   p.numero_parcela,',
'                   case ',
'                     when p.numero_parcela > atual.numero_parcela then 1',
'                     else 2',
'                   end as prioridade',
'            from imp_invoice_pagamento p',
'            join imp_invoice_pagamento atual',
'              on atual.id = p_id',
'             and p.id_invoice = atual.id_invoice',
'            where p.ind_status_pagamento = 1',
'              and p.id <> p_id',
'        )',
'        order by prioridade,',
'                 case when prioridade = 1 then numero_parcela end asc,',
'                 case when prioridade = 2 then numero_parcela end desc',
'        fetch first 1 row only;',
'',
'        return l_id;',
'',
'    exception',
'        when no_data_found then',
'            return 0;',
'    end;',
'    --',
'    function gera_sequencia (',
'        p_id_invoice in imp_invoice_pagamento.id_invoice%type',
'    ) return number is',
'        l_contador number := 0;',
'    begin',
'        select nvl(max(numero_parcela), 0) into l_contador from imp_invoice_pagamento where id_invoice = p_id_invoice;',
'        return l_contador + 1;',
'    end gera_sequencia;',
'    --',
'    function calcula_percentual_valor_parcela(',
'        p_id_invoice in imp_invoice_pagamento.id_invoice%type,',
'        p_valor in imp_invoice_pagamento.valor%type',
'    ) return number is',
'        l_valor_total_financeiro number;',
'        l_percentual number; ',
'    begin',
'        select valor_total_financeiro into l_valor_total_financeiro from imp_invoice where id = p_id_invoice;',
'        l_percentual := ((p_valor / l_valor_total_financeiro) * 100);',
'',
'        return round(l_percentual, 2);',
'    end calcula_percentual_valor_parcela;',
'    --',
'    function retorna_saldo_compensar(',
'        p_id_invoice in imp_invoice_pagamento.id_invoice%type,',
'        p_tipo in varchar2 default null',
'    ) return varchar2 is',
'        l_ids_entrega varchar2(4000);',
'        l_ids_pedidoimportacao varchar2(4000);',
'        l_ids_pedidoimportacao_pagamento varchar2(4000);',
'        l_resultado varchar2(4000);',
'    begin',
'        select ',
'            listagg(b.id,'',''),',
'            listagg(b.id_pedidoimportacao,'','')',
'        into',
'            l_ids_entrega,',
'            l_ids_pedidoimportacao',
'        from imp_invoice a ',
'        join imp_entrega b on b.id_invoice = a.id',
'        where a.id = p_id_invoice;',
'',
'        select listagg(id,'','')',
'        into l_ids_pedidoimportacao_pagamento',
'        from imp_pedidoimportacao_pagamento ',
'        where to_char(id_pedidoimportacao) in (',
'            select column_value from apex_string.split(l_ids_pedidoimportacao, '','')',
'        )',
'        and (id_entrega is null or to_char(id_entrega) in (',
'            select column_value from apex_string.split(l_ids_entrega, '','')',
'        ));',
'',
'        if p_tipo is null then',
'            select',
'                nvl(sum(saldo_compensar), 0)',
'            into',
'                l_resultado',
'            from fin_titulopagamento ',
'            where to_char(id_pagamento) in (',
'                select column_value from apex_string.split(l_ids_pedidoimportacao_pagamento, '','')',
'            );',
'        else',
'            select',
'                listagg(id,'','')',
'            into',
'                l_resultado',
'            from fin_titulopagamento ',
'            where to_char(id_pagamento) in (',
'                select column_value from apex_string.split(l_ids_pedidoimportacao_pagamento, '','')',
'            );',
'        end if;',
'',
'        return l_resultado;',
'    end retorna_saldo_compensar;',
'    --',
'    procedure descompensa_pagamento(',
'        p_id in imp_invoice_pagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for titulo_compensado in (',
'            select id from imp_titulo_compensado where id_invoice_parcela = p_id',
'        ) loop',
'            bo_imp_titulo_compensado.exclui_registro(',
'                p_id => titulo_compensado.id,',
'                p_sucesso => p_sucesso,',
'              '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(149390671976922604)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  p_messages => p_messages',
'            );',
'        end loop;',
'    end descompensa_pagamento;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_invoice_pagamento;',
'/'))
);
end;
/
