'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out imp_invoice_pagamento.id_tenant%type,',
'        p_id_invoice out imp_invoice_pagamento.id_invoice%type,',
'        p_id_entrega out imp_invoice_pagamento.id_entrega%type,',
'        p_numero_parcela out imp_invoice_pagamento.numero_parcela%type,',
'        p_percentual out imp_invoice_pagamento.percentual%type,',
'        p_valor out imp_invoice_pagamento.valor%type,',
'        p_data_vencimento_prevista out imp_invoice_pagamento.data_vencimento_prevista%type,',
'        p_data_vencimento_real out imp_invoice_pagamento.data_vencimento_real%type,',
'        p_ind_status_pagamento out imp_invoice_pagamento.ind_status_pagamento%type,',
'        p_ind_multa_atraso_pagamento out imp_invoice_pagamento.ind_multa_atraso_pagamento%type,',
'        p_valor_multa out imp_invoice_pagamento.valor_multa%type,',
'        p_percentual_multa out imp_invoice_pagamento.percentual_multa%type,',
'        p_periodo_multa out imp_invoice_pagamento.periodo_multa%type,',
'        p_ind_bloqueado out imp_invoice_pagamento.ind_bloqueado%type,',
'        p_condicao_desbloqueio out imp_invoice_pagamento.condicao_desbloqueio%type,',
'        p_data_desbloqueio out imp_invoice_pagamento.data_desbloqueio%type,',
'        p_id_usuario_desbloqueio out imp_invoice_pagamento.id_usuario_desbloqueio%type,',
'        p_instrucao_contas_pagar out imp_invoice_pagamento.instrucao_contas_pagar%type,',
'        p_valor_compensado out imp_invoice_pagamento.valor_compensado%type, ',
'        p_id in out imp_invoice_pagamento.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            id_invoice,',
'            id_entrega,',
'            numero_parcela,',
'            percentual,',
'            valor,',
'            data_vencimento_prevista,',
'            data_vencimento_real,',
'            ind_status_pagamento,',
'            ind_multa_atraso_pagamento,',
'            valor_multa,',
'            percentual_multa,',
'            periodo_multa,',
'            ind_bloqueado,',
'            condicao_desbloqueio,',
'            data_desbloqueio,',
'            id_usuario_desbloqueio,',
'            instrucao_contas_pagar,',
'            valor_compensado, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_id_invoice,',
'            p_id_entrega,',
'            p_numero_parcela,',
'            p_percentual,',
'            p_valor,',
'            p_data_vencimento_prevista,',
'            p_data_vencimento_real,',
'            p_ind_status_pagamento,',
'            p_ind_multa_atraso_pagamento,',
'            p_valor_multa,',
'            p_percentual_multa,',
'            p_periodo_multa,',
'            p_ind_bloqueado,',
'            p_condicao_desbloqueio,',
'            p_data_desbloqueio,',
'            p_id_usuario_desbloqueio,',
'            p_instrucao_contas_pagar,',
'            p_valor_compensado, ',
'            p_id ',
'        from imp_invoice_pagamento ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in imp_invoice_pagamento.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice_pagamento.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from imp_invoice_pagamento where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from imp_invoice_pagamento where id = p_id;',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_pagamento'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in imp_invoice_pagamento.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice_pagamento where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in imp_invoice_pagamento.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice_pagamento where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in imp_invoice_pagamento.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_invoice_pagamento'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''imp_invoice_pagamento'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in imp_invoice_pagamento.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_invoice */ '),
'        valida_id_invoice(v_new.id_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_entrega */ '),
'        valida_id_entrega(v_new.id_entrega);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo numero_parcela */ '),
'        valida_numero_parcela(v_new.numero_parcela);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo percentual */ '),
'        valida_percentual(v_new.percentual);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor */ '),
'        valida_valor(v_new.valor);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_vencimento_prevista */ '),
'        valida_data_vencimento_prevista(v_new.data_vencimento_prevista);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_vencimento_real */ '),
'        valida_data_vencimento_real(v_new.data_vencimento_real);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_status_pagamento */ '),
'        valida_ind_status_pagamento(v_new.ind_status_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_multa_atraso_pagamento */ '),
'        valida_ind_multa_atraso_pagamento(v_new.ind_multa_atraso_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_multa */ '),
'        valida_valor_multa(v_new.valor_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo percentual_multa */ '),
'        valida_percentual_multa(v_new.percentual_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo periodo_multa */ '),
'        valida_periodo_multa(v_new.periodo_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_bloqueado */ '),
'        valida_ind_bloqueado(v_new.ind_bloqueado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo condicao_desbloqueio */ '),
'        valida_condicao_desbloqueio(v_new.condicao_desbloqueio);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_desbloqueio */ '),
'        valida_data_desbloqueio(v_new.data_desbloqueio);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_usuario_desbloqueio */ '),
'        valida_id_usuario_desbloqueio(v_new.id_usuario_desbloqueio);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo instrucao_contas_pagar */ '),
'        valida_instrucao_contas_pagar(v_new.instrucao_contas_pagar);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_compensado */ '),
'        valida_valor_compensado(v_new.valor_compensado);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in imp_invoice_pagamento.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_id_invoice(p_id_invoice in imp_invoice_pagamento.id_invoice%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_invoice is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.id_invoice''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_invoice'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_invoice(p_id_invoice);',
'    end valida_id_invoice;     ',
'',
'    procedure valida_id_entrega(p_id_entrega in imp_invoice_pagamento.id_entrega%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_entrega is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.id_entrega''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_entrega(p_id_entrega);',
'    end valida_id_entrega;    ',
'',
'    procedure valida_numero_parcela(p_numero_parcela in imp_invoice_pagamento.numero_parcela%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_numero_parcela is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.numero_parcela''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''numero_parcela'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from imp_invoice_pagamento where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_invoice)) = lower(trim(v_new.id_invoice)) and lower(trim(id_entrega)) = lower(trim(v_new.'
||'id_entrega)) and lower(trim(numero_parcela)) = lower(trim(v_new.numero_parcela)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from imp_invoice_pagamento where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_invoice)) = lower(trim(v_new.id_invoice)) and lower(trim(id_entrega)) = lower(trim(v_new.'
