'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
'        if v_operacao = ''ALTERA_valor_compensado'' then',
'            bo_fin_titulopagamento.compensa_saldo(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            bo_imp_invoice.gerencia_divergencias(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''GERENCIA_COMPENSACAO'' and v_old.valor <> v_new.valor then',
'            ajusta_parcelas(v_saldo, v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        -- Altera imp_pedidoimportacao_pagamento.ind_status_pagamento para o mesmo valor de imp_invoice_pagamento.ind_status_pagamento, na parcela correspondente:',
'        altera_pedidoimportacao_pagamento_ind_status_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
