unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_fornecedor_contabancaria */ '),
'        valida_id_fornecedor_contabancaria(v_new.id_fornecedor_contabancaria);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_centrocusto */ '),
'        valida_id_centrocusto(v_new.id_centrocusto);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_vencimento */ '),
'        valida_data_vencimento(v_new.data_vencimento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_pagamento */ '),
'        valida_data_pagamento(v_new.data_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_compensacao */ '),
'        valida_data_compensacao(v_new.data_compensacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_moeda */ '),
'        valida_id_moeda(v_new.id_moeda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_titulo */ '),
'        valida_valor_titulo(v_new.valor_titulo);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_pago */ '),
'        valida_valor_pago(v_new.valor_pago);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo saldo_pagar */ '),
'        valida_saldo_pagar(v_new.saldo_pagar);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo taxa_cambio */ '),
'        valida_taxa_cambio(v_new.taxa_cambio);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_moeda_nacional */ '),
'        valida_valor_moeda_nacional(v_new.valor_moeda_nacional);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo observacao */ '),
'        valida_observacao(v_new.observacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_multa_atraso_pagamento */ '),
'        valida_ind_multa_atraso_pagamento(v_new.ind_multa_atraso_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_multa */ '),
'        valida_valor_multa(v_new.valor_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo percentual_multa */ '),
'        valida_percentual_multa(v_new.percentual_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo periodo_multa */ '),
