'    --',
'    procedure altera_ind_status_pagamento(',
'        p_id_entidade in fin_titulopagamento.id_entidade%type,',
'        p_id_pagamento in fin_titulopagamento.id_pagamento%type,',
'        p_data_vencimento in fin_titulopagamento.data_vencimento%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_entidade varchar2(4000);',
'    begin',
'        select lower(nome_entidade) into l_entidade from srv_entidade where id = p_id_entidade;',
'',
'        if l_entidade = ''imp_pedidoimportacao'' then',
'            bo_imp_pedidoimportacao_pagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => 2,',
'                p_data_vencimento_real => p_data_vencimento,',
'                p_id => p_id_pagamento,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        elsif l_entidade = ''imp_invoice'' then',
'            bo_imp_invoice_pagamento.altera_data_vencimento_real(',
'                p_data_vencimento_real => p_data_vencimento,',
'                p_ind_status_pagamento => 2,',
'                p_id => p_id_pagamento,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        elsif l_entidade = ''imp_processoimportacao_despesa'' then',
'            bo_imp_processoimportacao_despesa.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => 2,',
'                p_id => p_id_pagamento,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'',
'    end altera_ind_status_pagamento;',
'    --',
'    procedure gerencia_titulo_invoice(',
'        p_id_invoice in imp_invoice.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_invoice imp_invoice%rowtype;',
'        l_id_entidade number;',
'        l_json clob;',
'        l_invoice_pagamento imp_invoice_pagamento%rowtype;',
'        l_id number;',
'    begin',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_invoice'';',
'',
'        for pagamento in (',
'            select ',
'                a.*, ',
'                b.id_exportador, ',
'                b.id_moeda ',
'            from imp_invoice_pagamento a ',
'            join imp_invoice b on b.id = a.id_invoice ',
'            where a.id_invoice = p_id_invoice ',
'            and valor > valor_compensar',
'        ) loop ',
'            -- Tratamento incluir:            ',
'            inclui_registro(',
'                p_id_tenant => pagamento.id_tenant,',
'                p_id_entidade => l_id_entidade,',
'                p_id_pagamento => pagamento.id,',
'                p_num_documento => null,',
'                p_serie_nf => null,',
'                p_data_documento => null,',
'                p_ind_status_pagamento => 1,',
'                p_id_fornecedor => pagamento.id_exportador,',
unistr('                p_id_fornecedor_contabancaria => 1,--fun\00E7\00E3o para retornar conta banc\00E1ria?'),
'                p_id_centrocusto => null,',
'                p_data_vencimento => pagamento.data_vencimento_prevista,',
'                p_data_pagamento => null,',
'                p_data_compensacao => null,',
'                p_id_moeda => pagamento.id_moeda,',
'                p_valor_titulo => (pagamento.valor - pagamento.valor_compensar),',
'                p_valor_pago => null,',
'                p_saldo_pagar => null,',
'                p_taxa_cambio => null,',
'                p_valor_moeda_nacional => null,',
'                p_observacao => null,',
'                p_ind_multa_atraso_pagamento => pagamento.ind_multa_atraso_pagamento,',
'                p_valor_multa => pagamento.valor_multa,',
'                p_percentual_multa => pagamento.percentual_multa,',
'                p_periodo_multa => pagamento.periodo_multa,',
'                p_valor_compensado => null,',
'                p_saldo_compensar => null,',
'                p_id => l_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end gerencia_titulo_invoice;',
'    --',
'    procedure altera_saldo_compensar(',
'        p_saldo_compensar in fin_titulopagamento.saldo_compensar%type, ',
'        p_id in fin_titulopagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_parametro(0) := ''bo_fin_titulopagamento.altera_saldo_compensar'';   ',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from fin_titulopagamento where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.data_compensacao := sysdate;',
'        v_new.valor_compensado := (v_new.valor_titulo - p_saldo_compensar);',
'        v_new.saldo_compensar := p_saldo_compensar; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_SALDO_COMPENSAR'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_saldo_compensar;',
'    --',
'    procedure compensa_saldo(',
'        p_id_invoice in imp_invoice.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_total_compensar number;',
'    begin',
'        -- select sum(a.valor_titulo) into l_total_compensar',
'        -- from fin_titulopagamento a',
'        -- join srv_entidade b on b.id = a.id_entidade',
'        -- where lower(b.nome_entidade) = ''imp_pedidoimportacao''',
'        -- and exists (',
'        --     select 1 from imp_pedidoimportacao_pagamento c',
'        --     join imp_entrega d on d.id_pedidoimportacao = c.id_pedidoimportacao',
'        --     join imp_invoice_item e on e.id_entrega = d.id',
'        --     where c.id = a.id_pagamento',
'        --     and e.id_invoice = p_id_invoice',
'        -- );',
'',
'        select sum(valor_compensar) into l_total_compensar from imp_invoice_pagamento where id_invoice = p_id_invoice;',
'',
'        for r in (',
'            select a.id, a.valor_titulo',
'            from fin_titulopagamento a',
'            join srv_entidade b on b.id = a.id_entidade',
'            where lower(b.nome_entidade) = ''imp_pedidoimportacao''',
'            and exists (',
'                select 1 from imp_pedidoimportacao_pagamento c',
'                join imp_entrega d on d.id_pedidoimportacao = c.id_pedidoimportacao',
'                join imp_invoice_item e on e.id_entrega = d.id',
'                where c.id = a.id_pagamento',
'                and e.id_invoice = p_id_invoice',
'            )',
'            --and saldo_compensar > 0',
'            order by id',
'            for update',
'        ) loop',
'            exit when l_total_compensar <= 0;',
'',
'            if r.valor_titulo <= l_total_compensar then                ',
'                altera_saldo_compensar(',
'                    p_saldo_compensar => 0,',
'                    p_id => r.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'                l_total_compensar := (l_total_compensar - r.valor_titulo);',
'            else',
'                altera_saldo_compensar(',
'                    p_saldo_compensar => (r.valor_titulo - l_total_compensar),',
'                    p_id => r.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'                l_total_compensar :='))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(149390817670911244)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' 0;',
'            end if;',
'        end loop;',
'    end compensa_saldo;',
