'    --',
'    procedure confirma_pagamento_titulo(',
'        p_id in fin_titulopagamento.id%type,',
'        p_data_pagamento in fin_titulopagamento.data_pagamento%type,',
'        p_observacao in fin_titulopagamento.observacao%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        select * into v_old from fin_titulopagamento where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.ind_status_pagamento := 2;',
'        v_new.data_pagamento := p_data_pagamento;',
'        v_new.observacao := p_observacao;',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''CONFIRMA_PAGAMENTO_TITULO'';',
'',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end confirma_pagamento_titulo;',
'    --',
'    procedure altera_valor_compensado(',
'        p_valor_compensado in fin_titulopagamento.valor_compensado%type, ',
'        p_id in fin_titulopagamento.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_fin_titulopagamento.altera_valor_compensado'';   ',
'        v_pagina := p_pagina;',
'        select * into v_old from fin_titulopagamento where id = p_id;        ',
'        v_new := v_old;',
'',
'        if p_valor_compensado > nvl(v_old.saldo_compensar,0) then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''fin_titulopagamento.valor_compensado'');',
'            v_parametro(2) := lower(pkg_ui.retorna_label_coluna(''fin_titulopagamento.saldo_compensar''));',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''77'',',
'                p_nome_campo => ''valor_compensado'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        else        ',
'            v_new.data_compensacao := sysdate;',
'            v_new.valor_compensado := p_valor_compensado;',
'            v_new.saldo_compensar := (v_new.valor_titulo - nvl(p_valor_compensado,0));',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'            v_new.data_alteracao := sysdate;  ',
'',
'            v_operacao := ''ALTERA_VALOR_COMPENSADO'';',
'            grava(p_id,p_encadeado,p_sucesso,p_messages);',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_valor_compensado;',
'    --',
'    function valor_compensado_sugerido(',
'        p_id in fin_titulopagamento.id%type,',
'        p_numero_parcela in imp_invoice_pagamento.numero_parcela%type',
'    ) return number is',
'        l_ind_evento_gerador_pagamento number;',
'        l_percentual number;',
'        l_valor_compensado_sugerido number;',
'    begin',
'        select e.ind_evento_gerador_pagamento, e.percentual',
'        into l_ind_evento_gerador_pagamento, l_percentual',
'        from fin_titulopagamento a ',
'        join srv_entidade b on b.id = a.id_entidade',
'        join imp_pedidoimportacao_pagamento c on c.id = a.id_pagamento ',
'        join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'        join ng_condicaopagamento_parcela e on e.id_condicaopagamento = d.id_condicaopagamento and e.numero_parcela = c.numero_parcela',
'        where a.id = p_id ',
'        and lower(b.nome_entidade) = ''imp_pedidoimportacao''',
'        and c.numero_parcela = p_numero_parcela;',
'',
'        if l_ind_evento_gerador_pagamento in (2,5,6,7) then',
'            select (valor_titulo - nvl(valor_compensado,0)) into l_valor_compensado_sugerido from fin_titulopagamento where id = p_id;',
'        -- Verificar o comportamento correto para os casos abaixo:',
'        elsif l_ind_evento_gerador_pagamento in (1,8) then            ',
'            select (valor_titulo - nvl(valor_compensado,0)) into l_valor_compensado_sugerido from fin_titulopagamento where id = p_id;',
'        end if;',
'',
'        return nvl(l_valor_compensado_sugerido,0);',
'    exception',
'        when no_data_found then',
'            return 0;',
'    end valor_compensado_sugerido;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_fin_titulopagamento;',
'/'))
);
end;
/
