'        v_new.id_fornecedor_contabancaria := p_id_fornecedor_contabancaria;',
'        v_new.data_vencimento := p_data_vencimento;',
'        v_new.data_pagamento := p_data_pagamento;',
'        v_new.data_compensacao := p_data_compensacao;',
'        v_new.id_moeda := p_id_moeda;',
'        v_new.valor_titulo := p_valor_titulo;',
'        v_new.valor_pago := nvl(p_valor_pago,0);',
'        v_new.saldo_pagar := nvl(p_saldo_pagar,0);',
'        v_new.taxa_cambio := nvl(p_taxa_cambio,0);',
'        v_new.valor_moeda_nacional := nvl(p_valor_moeda_nacional,0);',
'        v_new.observacao := p_observacao;',
'        v_new.ind_multa_atraso_pagamento := nvl(p_ind_multa_atraso_pagamento,''N'');',
'        v_new.valor_multa := nvl(p_valor_multa,0);',
'        v_new.percentual_multa := nvl(p_percentual_multa,0);',
'        v_new.periodo_multa := p_periodo_multa;',
'        v_new.valor_compensado := nvl(p_valor_compensado,0);',
'        v_new.saldo_compensar := nvl(p_saldo_compensar,0); ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_fin_titulopagamento'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulopagamento'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out fin_titulopagamento.id_tenant%type,',
'        p_id_entidade out fin_titulopagamento.id_entidade%type,',
'        p_id_referencia out fin_titulopagamento.id_referencia%type,',
'        p_ind_status_pagamento out fin_titulopagamento.ind_status_pagamento%type,',
'        p_id_fornecedor out fin_titulopagamento.id_fornecedor%type,',
'        p_id_fornecedor_contabancaria out fin_titulopagamento.id_fornecedor_contabancaria%type,',
'        p_data_vencimento out fin_titulopagamento.data_vencimento%type,',
'        p_data_pagamento out fin_titulopagamento.data_pagamento%type,',
'        p_data_compensacao out fin_titulopagamento.data_compensacao%type,',
'        p_id_moeda out fin_titulopagamento.id_moeda%type,',
'        p_valor_titulo out fin_titulopagamento.valor_titulo%type,',
'        p_valor_pago out fin_titulopagamento.valor_pago%type,',
'        p_saldo_pagar out fin_titulopagamento.saldo_pagar%type,',
'        p_taxa_cambio out fin_titulopagamento.taxa_cambio%type,',
'        p_valor_moeda_nacional out fin_titulopagamento.valor_moeda_nacional%type,',
'        p_observacao out fin_titulopagamento.observacao%type,',
'        p_ind_multa_atraso_pagamento out fin_titulopagamento.ind_multa_atraso_pagamento%type,',
'        p_valor_multa out fin_titulopagamento.valor_multa%type,',
'        p_percentual_multa out fin_titulopagamento.percentual_multa%type,',
'        p_periodo_multa out fin_titulopagamento.periodo_multa%type,',
'        p_valor_compensado out fin_titulopagamento.valor_compensado%type,',
'        p_saldo_compensar out fin_titulopagamento.saldo_compensar%type, ',
'        p_id in out fin_titulopagamento.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_fin_titulopagamento'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_fin_titulopagamento.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            id_entidade,',
'            id_referencia,',
'            ind_status_pagamento,',
'            id_fornecedor,',
'            id_fornecedor_contabancaria,',
'            data_vencimento,',
'            data_pagamento,',
'            data_compensacao,',
'            id_moeda,',
'            valor_titulo,',
'            valor_pago,',
'            saldo_pagar,',
'            taxa_cambio,',
'            valor_moeda_nacional,',
'            observacao,',
'            ind_multa_atraso_pagamento,',
'            valor_multa,',
'            percentual_multa,',
'            periodo_multa,',
'            valor_compensado,',
'            saldo_compensar, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_id_entidade,',
'            p_id_referencia,',
'            p_ind_status_pagamento,',
'            p_id_fornecedor,',
'            p_id_fornecedor_contabancaria,',
'            p_data_vencimento,',
'            p_data_pagamento,',
'            p_data_compensacao,',
'            p_id_moeda,',
'            p_valor_titulo,',
'            p_valor_pago,',
'            p_saldo_pagar,',
'            p_taxa_cambio,',
'            p_valor_moeda_nacional,',
'            p_observacao,',
'            p_ind_multa_atraso_pagamento,',
'            p_valor_multa,',
'            p_percentual_multa,',
'            p_periodo_multa,',
'            p_valor_compensado,',
'            p_saldo_compensar, ',
'            p_id ',
'        from fin_titulopagamento ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_fin_titulopagamento'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulopagamento'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in fin_titulopagamento.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_fin_titulopagamento'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_fin_titulopagamento.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from fin_titulopagamento where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from fin_titulopagamento where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_fin_titulopagamento'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulopagamento'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulopagamento'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in fin_titulopagamento.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from fin_titulopagamento where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in fin_titulopagamento.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from fin_titulopagamento where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in fin_titulopagamento.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''fin_titulopagamento'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''fin_titulopagamento'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in fin_titulopagamento.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_entidade */ '),
'        valida_id_entidade(v_new.id_entidade);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_referencia */ '),
'        valida_id_referencia(v_new.id_referencia);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_status_pagamento */ '),
'        valida_ind_status_pagamento(v_new.ind_status_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_fornecedor */ '),
'        valida_id_fornecedor(v_new.id_fornecedor);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_fornecedor_contabancaria */ '),
'        valida_id_fornecedor_contabancaria(v_new.id_fornecedor_contabancaria);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_vencimento */ '),
'        valida_data_vencimento(v_new.data_vencimento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_pagamento */ '),
'        valida_data_pagamento(v_new.data_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_compensacao */ '),
'        valida_data_compensacao(v_new.data_compensacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_moeda */ '),
'        valida_id_moeda(v_new.id_moeda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_titulo */ '),
'        valida_valor_titulo(v_new.valor_titulo);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_pago */ '),
'        valida_valor_pago(v_new.valor_pago);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo saldo_pagar */ '),
'        valida_saldo_pagar(v_new.saldo_pagar);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo taxa_cambio */ '),
'        valida_taxa_cambio(v_new.taxa_cambio);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_moeda_nacional */ '),
'        valida_valor_moeda_nacional(v_new.valor_moeda_nacional);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo observacao */ '),
'        valida_observacao(v_new.observacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_multa_atraso_pagamento */ '),
'        valida_ind_multa_atraso_pagamento(v_new.ind_multa_atraso_pagamento);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_multa */ '),
'        valida_valor_multa(v_new.valor_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo percentual_multa */ '),
'        valida_percentual_multa(v_new.percentual_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo periodo_multa */ '),
'        valida_periodo_multa(v_new.periodo_multa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_compensado */ '),
'        valida_valor_compensado(v_new.valor_compensado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo saldo_compensar */ '),
'        valida_saldo_compensar(v_new.saldo_compensar);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in fin_titulopagamento.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''fin_titulopagamento.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_id_entidade(p_id_entidade in fin_titulopagamento.id_entidade%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_entidade is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''fin_titulopagamento.id_entidade''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_entidade'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_entidade(p_id_entidade);',
