unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''fin_titulopagamento'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''fin_titulopagamento'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''fin_titulopagamento'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''fin_titulopagamento'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''fin_titulopagamento'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''fin_titulopagamento'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in fin_titulopagamento%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_entidade'', p_rec.id_entidade, true);',
'        apex_json.write(''id_referencia'', p_rec.id_referencia, true);',
'        apex_json.write(''ind_status_pagamento'', p_rec.ind_status_pagamento, true);',
'        apex_json.write(''id_fornecedor'', p_rec.id_fornecedor, true);',
'        apex_json.write(''id_fornecedor_contabancaria'', p_rec.id_fornecedor_contabancaria, true);',
'        apex_json.write(''data_vencimento'', p_rec.data_vencimento, true);',
'        apex_json.write(''data_pagamento'', p_rec.data_pagamento, true);',
'        apex_json.write(''data_compensacao'', p_rec.data_compensacao, true);',
'        apex_json.write(''id_moeda'', p_rec.id_moeda, true);',
'        apex_json.write(''valor_titulo'', p_rec.valor_titulo, true);',
'        apex_json.write(''valor_pago'', p_rec.valor_pago, true);',
'        apex_json.write(''saldo_pagar'', p_rec.saldo_pagar, true);',
'        apex_json.write(''taxa_cambio'', p_rec.taxa_cambio, true);',
'        apex_json.write(''valor_moeda_nacional'', p_rec.valor_moeda_nacional, true);',
'        apex_json.write(''observacao'', p_rec.observacao, true);',
'        apex_json.write(''ind_multa_atraso_pagamento'', p_rec.ind_multa_atraso_pagamento, true);',
'        apex_json.write(''valor_multa'', p_rec.valor_multa, true);',
'        apex_json.write(''percentual_multa'', p_rec.percentual_multa, true);',
'        apex_json.write(''periodo_multa'', p_rec.periodo_multa, true);',
'        apex_json.write(''valor_compensado'', p_rec.valor_compensado, true);',
'        apex_json.write(''saldo_compensar'', p_rec.saldo_compensar, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.observacao,v_new.id_tenant,p_sucesso,p_messages);',
'        altera_dependentes_ind_status_pagamento(v_new.id_entidade, v_new.id_referencia, v_new.data_vencimento, 2, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        v_new.id := null;',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.observacao,v_new.id_tenant,p_sucesso,p_messages);',
'        ',
unistr('        -- Ap\00F3s cancelar o t\00EDtulo de pagamento na interface TD968:'),
'        if v_operacao = ''ALTERA_IND_STATUS_PAGAMENTO'' and v_new.ind_status_pagamento = 3 then',
'            altera_dependentes_ind_status_pagamento(',
'                p_id_entidade => v_new.id_entidade,',
'                p_id_referencia => v_new.id_referencia,',
'                p_data_vencimento => null,',
'                p_ind_status_pagamento => 1,',
'                p_pagina => v_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
