'    procedure hook_valida_valor_compensado(p_valor_compensado in fin_titulopagamento.valor_compensado%type) ',
'    is ',
'    begin ',
'        if nvl(v_operacao, ''-200001'') != ''ALTERA_IND_STATUS_PAGAMENTO'' then',
'            if p_valor_compensado is not null and p_valor_compensado > v_old.saldo_compensar then',
'                v_parametro(1) := pkg_ui.retorna_label_coluna(''fin_titulopagamento.valor_compensado'');',
'                v_parametro(2) := lower(pkg_ui.retorna_label_coluna(''fin_titulopagamento.saldo_compensar''));',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''77'',',
'                    p_nome_campo => ''valor_compensado'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );            ',
unistr('                -- Inserir o registro na cole\00E7\00E3o'),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;',
'            end if;',
'        end if;',
'    end hook_valida_valor_compensado;     ',
