'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        altera_titulopagamento_valor_compensado(v_new.id_titulopagamento, v_pagina, p_encadeado, p_sucesso, p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
'        altera_titulopagamento_valor_compensado(v_old.id_titulopagamento, v_pagina, p_encadeado, p_sucesso, p_messages);',
'    end;',
'    --',
'    procedure altera_titulopagamento_valor_compensado(',
'        p_id_titulopagamento in imp_titulo_compensado.id_titulopagamento%type,     ',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_valor_total_compensado number;',
'    begin',
'        select sum(valor_compensado) into l_valor_total_compensado from imp_titulo_compensado where id_titulopagamento = p_id_titulopagamento;',
'',
'        bo_fin_titulopagamento.altera_valor_compensado(',
'            p_valor_compensado => l_valor_total_compensado,',
'            p_id => p_id_titulopagamento,',
'            p_pagina => p_pagina,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    exception',
'        when no_data_found then',
'            bo_fin_titulopagamento.altera_valor_compensado(',
'                p_valor_compensado => 0,',
'                p_id => p_id_titulopagamento,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'    end altera_titulopagamento_valor_compensado;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_titulo_compensado;',
'/'))
);
end;
