prompt --application/deployment/install/upgrade_ui_mpd_td869
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(149391089913888211)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD869'
,p_sequence=>150
,p_script_type=>'UPGRADE'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD869',
'-- Data: 16/04/2026',
'-- Motivo: UI Incluir invoice (Etapa Pagamento)',
'-- Jira: PEDITEM-175',
'',
'create or replace package "UI_MPD_TD869" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null',
'    );',
'',
'    function sql_report(',
'        p_param1 in varchar2',
'    ) return clob;',
'',
'    function label_coluna(',
'        campo in varchar2',
'    ) return clob;',
'    ',
'    procedure esconde_incluir;',
'',
'    function mostra_opcao(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'',
'end "UI_MPD_TD869";',
'/',
'',
'create or replace package body "UI_MPD_TD869" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select num_invoice from imp_invoice where id = '' || p_param1,',
'            p_tabela => textarray(''imp_invoice''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    ) is',
'        l_condicaopagamento   varchar2(4000);',
'        l_quantidade_parcelas varchar2(4000);',
'        l_saldo_compensar     varchar2(4000);',
'        l_titulo_grid         varchar2(4000);',
'    begin',
'        select ',
'            pkg_traducao.get_traducao(b.descricao_condicaopagamento),',
'            count(c.id)',
'        into ',
'            l_condicaopagamento, ',
'            l_quantidade_parcelas',
'        from imp_invoice a ',
'        join ng_condicaopagamento b on b.id = a.id_condicaopagamento',
'        join ng_condicaopagamento_parcela c on c.id_condicaopagamento = b.id',
'        where a.id = p_param1',
'        group by pkg_traducao.get_traducao(b.descricao_condicaopagamento);',
'        ',
'        select to_char(nvl(sum(bo_imp_invoice_pagamento.retorna_saldo_compensar(p_param1)), 0), ''FM999G999G990D00'') into l_saldo_compensar from dual;',
'',
'        l_titulo_grid := ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding-top: 1.5rem; padding-left: 1rem;"><h3 class="a-CardView-title">''||retorna_texto(''msg.111.l'')||''</h3></div>'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_condicaopagamento'' AS nome_coluna, 1 AS indice, ''TXT'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, l_condicaopagamento AS valor, ''imp_invoice.i'
||'d_condicaopagamento'' AS tag_campo, null AS html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas'', 2, ''TXT'', null, ''S'', ''N'', l_quantidade_parcelas valor, ''imp_pedidoimportacao.quantidade_parcelas_pagamento'' tag_campo, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''saldo_compensar'',     3, ''TXT'', null, ''S'', ''N'', l_saldo_compensar valor, ''fin_titulopagamento.saldo_compensar'' tag_campo, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''l_titulo_grid'',       4, ''HTM'', null, ''N'', ''N'', null valor, null tag_campo, l_titulo_grid html FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.html);',
'    end formulario;    ',
'',
'    function sql_report(',
'        p_param1 in varchar2',
'    ) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.numero_parcela campo1,',
'                case',
'                    when bo_imp_invoice_pagamento.calcula_percentual_valor_parcela(a.id_invoice, a.valor) <> a.percentual then',
'                    pkg_componentes.html_cor_texto(a.percentual||''%'')',
'                else',
'                    a.percentual||''%'' ',
'                end campo2,',
'                pkg_util.dominio_retorna_tag(''ng_condicaopagamento_parcela'', ''ind_evento_gerador_pagamento'',     ',
'                    bo_ng_condicaopagamento_parcela.retorna_ind_evento_gerador_pagamento(b.id_condicaopagamento, a.numero_parcela)',
'                ) campo3,',
'                to_char(a.valor, ''FM999G999G990D00'') campo4,',
'                pkg_util.dominio_retorna_tag(''imp_invoice_pagamento'', ''ind_status_pagamento'', a.ind_status_pagamento) campo5,',
'                to_char(a.valor_compensar, ''FM999G999G990D00'') campo6,',
'                to_char(a.valor - nvl(a.valor_compensar,a.valor),''FM999G999G990D00'') campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD869'', p_param1 => b.id) opcao',
'            from imp_invoice_pagamento a',
'            left join imp_invoice b on b.id = a.id_invoice',
'            where a.id_invoice = #PARAM1#',
'            order by a.numero_parcela',
'        ~'';',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;',
'    end sql_report;    ',
'',
'    function label_coluna(',
'        campo in varchar2',
'    ) return clob is',
'        l_campo clob;',
'    begin ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.numero_parcela'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.percentual'') into l_campo from dual;',
'        elsif campo = ''3'' then                        ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.ind_evento_gerador_pagamento'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.valor'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.ind_status_pagamento'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.valor_compensar'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_tela(''valor_a_gerar_titulo'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure esconde_incluir is',
'    begin',
'        null;',
'    end esconde_incluir;',
'',
'    function mostra_opcao(',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9000,',
'            p_items=> ''P9000_ID,P9000_PAGINA,P9000_PARAMETRO'',',
'            p_values => p_param1||'',TD869,0'',',
'            p_triggering_element => ''apex.jQuery("#NEW")''',
'        );',
'',
'        return l_url;',
'    end mostra_opcao;',
'',
'end "UI_MPD_TD869";',
'/'))
);
end;
/
