'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.valor'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.ind_status_pagamento'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_pagamento.valor_compensado'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_tela(''valor_a_gerar_titulo'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
