'        l_html clob;',
'        l_status varchar2(50);',
'    begin               ',
'        l_status := ''"''||pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'',''ind_status_pedido_importacao'',2)||''"'';',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.numero_pedido_importacao,',
'                    bo_ng_pessoa.retorna_pessoa(id_exportador) id_exportador,',
'                    bo_ng_pessoa.retorna_pessoa(id_importador) id_importador',
'                from imp_pedidoimportacao a',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.76.l'')||''</h3></div>''||',
'        ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        replace(retorna_texto(''msg.76.h''),''$param1'',l_status)||''</h3></div>'';',
'        return l_html;',
'    end;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'    begin        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_pedido_importacao'',                  2, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',                 3, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_exportador'',                             4, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                             6, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                             8, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_comprador'',                             10, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_vendedor'',                            12, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_proforma'',                          14, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                                 15, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_viatransporte'',                         19, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_incoterm'',                              20, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_listapreco'',                            22, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_origem'',                       24, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_embarque'',                        26, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_desembarque'',                     28, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_destino'',                      30, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_entrega'',                       32, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_condicaopagamento'',                     33, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas_pagamento'',            35, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_mercadoria'',                   37, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto'',                           38, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesa_proforma'',                   39, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_condicao_venda'',               40, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_confirmacao_pedido'',                  41, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_todos_itens_com_entregas_programadas'', 42, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                           43, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pedido_importacao'',             44, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao_parcela_pagamento'',           45, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''motivo_desconto'',                          46, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_financeiro'',                   47, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is ',
'    begin',
'        bo_imp_pedidoimportacao.altera_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_numero_pedido_importacao => apex_application.g_f02(1),',
'            p_ind_modalidade_importacao => apex_application.g_f03(1),',
'            p_id_exportador => apex_application.g_f04(1),',
'            p_id_importador => apex_application.g_f06(1),',
'            p_id_adquirente => apex_application.g_f08(1),',
'            p_id_comprador => apex_application.g_f10(1),',
'            p_nome_vendedor => apex_application.g_f12(1),            ',
'            p_numero_proforma => apex_application.g_f14(1),            ',
'            p_id_moeda => apex_application.g_f15(1),            ',
'            p_id_viatransporte => apex_application.g_f19(1),',
'            p_id_incoterm => apex_application.g_f20(1),',
'            p_id_listapreco => apex_application.g_f22(1),',
'            p_id_endereco_origem => apex_application.g_f24(1),',
'            p_id_local_embarque => apex_application.g_f26(1),',
'            p_id_local_desembarque => apex_application.g_f28(1),',
'            p_id_endereco_destino => apex_application.g_f30(1),',
