prompt --application/deployment/install/install_ui_mpd_td1003
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(150278191047187706)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1003'
,p_sequence=>180
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD1003',
'-- Data: 17/04/2026',
unistr('-- Motivo: Corre\00E7\00E3o na regra da consulta exibida no grid'),
'-- Jira: PEDITEM-237',
'',
'create or replace package "UI_MPD_TD1003" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in varchar2,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function esconder_opcao return varchar2;',
'    ',
'end "UI_MPD_TD1003";',
'/',
'create or replace package body "UI_MPD_TD1003" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin  ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select',
'                    b.num_processoimportacao, ',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''',a.ind_tipo_movimento) ind_tipo_movimento,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_fornecedor) id_fornecedor',
'                from imp_processoimportacao_numerario a ',
'                join imp_processoimportacao b on b.id = a.id_processoimportacao',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        ) || ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||retorna_texto(''msg.133.l'')||''</h3></div>'';',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'        l_id_processoimportacao number;',
'    begin',
'        if p_param1 is not null then',
'            select n.id_processoimportacao into l_id_processoimportacao from imp_processoimportacao_numerario n where n.id = p_param1;',
'        end if;',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO'',',
'            p_values => ''TD738,TD738,''||l_id_processoimportacao,',
'            p_triggering_element => ''apex.jQuery("#NEW")'',',
'            p_clear_cache => 9010',
'        );',
'        return l_url;',
'    end;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                -- apex_item.checkbox(1,a.id,''onclick="seleciona(this);"'') selected,',
'                apex_item.checkbox(',
'                    p_idx => 1,',
'                    p_value => a.id,',
'                    p_checked_values => (select nvl(listagg(to_char(nd.id_despesa), '':'') within group (order by nd.id_despesa), ''0'') from imp_processoimportacao_numerario_despesa nd where nd.id_numerario = #param1#),',
'                    p_attributes => ''onclick="seleciona(this);"''',
'                ) selected,',
'                a.id,',
'                pkg_traducao.get_traducao(c.descricao_despesa) campo1,                ',
'                null campo2,',
'                null campo3,',
'                null campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,                ',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD999'', p_param1 => a.id) opcao',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa c on c.id = a.id_despesa',
'            join imp_processoimportacao_numerario b on b.id = #param1#',
'            where a.id_processoimportacao = b.id_processoimportacao',
'            and not exists (select 1 from imp_processoimportacao_numerario_despesa nd join imp_processoimportacao_numerario n on n.id = nd.id_numerario where nd.id_despesa = a.id and n.ind_tipo_movimento = b.ind_tipo_movimento and n.id_processoimport'
||'acao = b.id_processoimportacao)',
'            order by campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_numerario_despesa.id_despesa'') into l_campo from dual; ',
'        elsif campo = ''SEL'' then',
'            l_campo := ''sel'';',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure post(',
'        p_id in varchar2,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_numerario imp_processoimportacao_numerario.id%type;',
'    begin',
'        l_id_numerario := to_number(apex_util.get_session_state(''P9016_PARAMETRO''));',
'',
'        bo_imp_processoimportacao_numerario_despesa.inclui_novas_despesas_ao_numerario(',
'            p_ids_despesas_selecionadas => p_id,',
'            p_id_numerario              => l_id_numerario,',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end post;',
'',
'    function esconder_opcao return varchar2 is',
'    begin',
'        return ''true'';',
'    end;',
'    ',
'end "UI_MPD_TD1003";',
'/'))
);
end;
