'        return l_html;',
'    end sql_cabecalho;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'        l_id_processoimportacao number;',
'    begin',
'        if p_param1 is not null then',
'            select n.id_processoimportacao into l_id_processoimportacao from imp_processoimportacao_numerario n where n.id = p_param1;',
'        end if;',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO'',',
'            p_values => ''TD738,TD738,''||l_id_processoimportacao,',
'            p_triggering_element => ''apex.jQuery("#NEW")'',',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
