'                    p_idx => 1,',
'                    p_value => a.id,',
'                    p_checked_values => (select nvl(listagg(to_char(nd.id_despesa), '':'') within group (order by nd.id_despesa), ''0'') from imp_processoimportacao_numerario_despesa nd where nd.id_numerario = #param1#),',
'                    p_attributes => ''onclick="seleciona(this);"''',
'                ) selected,',
'                a.id,',
'                pkg_traducao.get_traducao(c.descricao_despesa) campo1,                ',
'                to_char(d.codigo_moeda||'' - ''||d.simbolo_iso) campo2,',
'                to_char(a.valor_previsto, ''FM999G999G990D00'') campo3,',
'                null campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,                ',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD999'', p_param1 => a.id) opcao',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa c on c.id = a.id_despesa',
'            left join ng_moeda d on d.id = a.id_moeda',
'            join imp_processoimportacao_numerario b on b.id_processoimportacao = a.id_processoimportacao',
'            where b.id = #param1#',
'            order by campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_numerario_despesa.id_despesa'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_numerario_despesa.id_moeda_despesa'') into l_campo from dual; ',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_numerario_despesa.valor_despesa_numerario'') into l_campo from dual;  ',
'        elsif campo = ''SEL'' then',
'            l_campo := ''sel'';',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure post(',
'        p_id in varchar2,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_numerario imp_processoimportacao_numerario.id%type;',
'    begin --null;',
'        l_id_numerario := to_number(apex_util.get_session_state(''P9014_PARAMETRO''));',
'',
'        bo_imp_processoimportacao_numerario_despesa.vincula_despesas_ao_numerario(',
'            p_ids_despesas_selecionadas => p_id,',
'            p_id_numerario              => l_id_numerario,',
'            p_pagina                    => 0,',
'            p_encadeado                 => false,',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end post;',
'',
'    -- function esconder_opcao return varchar2 is',
'    -- begin',
'    --     return ''true'';',
'    -- end;',
'',
'end "UI_MPD_TD999";',
'/'))
);
end;
/
