'    function verifica_registro(',
'        p_id in imp_minutanotafiscal_entrada.id%type',
'    ) return boolean is',
'        l_existe_registro number;',
'    begin',
'        select count(1) into l_existe_registro from imp_minutanotafiscal_entrada where id = p_id;',
'        return l_existe_registro > 0;',
