'        p_id_importador           in imp_minutanotafiscal_entrada.id_importador%type,',
'        p_id_destinatario         in imp_minutanotafiscal_entrada.id_destinatario%type,',
'        p_id_endereco_destino     in imp_minutanotafiscal_entrada.id_endereco_destino%type,',
'        p_id_recinto_alfandegado  in imp_minutanotafiscal_entrada.id_recinto_alfandegado%type,',
'        p_id_uf_nacionalizacao    in imp_minutanotafiscal_entrada.id_uf_nacionalizacao%type,',
'        p_dados_complementares    in imp_minutanotafiscal_entrada.dados_complementares%type,',
'        p_id                      out imp_minutanotafiscal_entrada.id%type,',
