'        v_new.id_uf_nacionalizacao   							 := p_id_uf_nacionalizacao;',
'        v_new.dados_complementares    						 := p_dados_complementares;',
'        v_new.ind_status_minuta                    := 1;',
unistr('        v_new.ind_status_transmiss\00E3o               := 1;'),
