'',
unistr('		-- Atribui valores n\00E3o tras todas as regras da planilha porque o 1021 tem regras que s\00E3o executardas em tela'),
'  	procedure atribui_valores is',
'        v_di  imp_declaracaoimportacao%rowtype;',
'        v_pi  imp_processoimportacao%rowtype;',
'    begin',
'        select *',
'          into v_di',
'          from imp_declaracaoimportacao',
'         where id_processoimportacao = v_new.id_processoimportacao;',
'',
'        select *',
'          into v_pi',
'          from imp_processoimportacao',
'         where id = v_new.id_processoimportacao;',
'',
'        v_new.numero_duimp                       := v_di.numero_duimp;',
'        v_new.data_registro                      := v_di.data_registro;',
'        v_new.volume                             := v_di.volume;',
'        v_new.peso_liquido_carga                 := v_di.peso_liquido_carga;',
'        v_new.peso_bruto_carga                   := v_di.peso_bruto_carga;',
'        -- v_new.id_recinto_alfandegado             := nvl(v_new.id_recinto_alfandegado, v_di.id_recinto_alfandegado);',
'        -- v_new.id_uf_nacionalizacao               := nvl(v_new.id_uf_nacionalizacao, v_di.id_uf_nacionalizacao);',
'        -- v_new.data_nacionalizacao_real           := v_di.data_nacionalizacao_real;',
'        -- v_new.frete_internacional_moedanacional  := v_di.frete_real;',
'        -- v_new.seguro_internacional_moedanacional := v_di.seguro_real;',
'',
'        v_new.id_exportador                      := nvl(v_new.id_exportador, v_pi.id_embarcador);',
'        v_new.id_importador                      := v_pi.id_importador;',
'        v_new.id_adquirente                      := v_pi.id_adquirente;',
'        v_new.id_local_desembarque               := v_pi.id_local_desembarque;',
'        v_new.id_transportador_internacional     := v_pi.id_transportador_internacional;',
'        v_new.navio                              := v_pi.navio;',
'        v_new.acrescimo_moedanacional            := v_pi.acrescimo;',
'',
'        select',
'            nvl(sum(valor_total_mercadoria_moedanacional), 0),',
'            nvl(sum(valor_desconto_moedanacional),         0),',
'            nvl(sum(base_calculo_icms),                    0),',
'            nvl(sum(base_calculo_icms_st),                 0),',
'            nvl(sum(valor_icms),                           0),',
'            nvl(sum(valor_icms_st),                        0),',
'            nvl(sum(valor_ipi),                            0)',
'          into',
'            v_new.valor_total_mercadoria_moedanacional,',
'            v_new.valor_desconto_moedanacional,',
'            v_new.base_calculo_icms,',
'            v_new.base_calculo_icms_st,',
'            v_new.valor_icms,',
'            v_new.valor_icms_st,',
'            v_new.valor_ipi',
'          from imp_minutanotafiscal_entrada_item',
'         where id_minuta = v_new.id;',
'',
'        select nvl(sum(valor_moeda_nacional), 0)',
'          into v_new.despesa_acessoria',
'          from imp_minutanotafiscal_entrada_despesa',
'         where id_minuta = v_new.id',
'           and ind_despesa_tributada = ''S'';',
'',
'        v_new.valor_total_notafiscal :=',
'            nvl(v_new.valor_total_mercadoria_moedanacional, 0)',
'            + nvl(v_new.frete_internacional_moedanacional,  0)',
'            + nvl(v_new.seguro_internacional_moedanacional, 0)',
'            + nvl(v_new.valor_ipi,                         0)',
'            + nvl(v_new.valor_icms_st,                     0);',
'',
'    end atribui_valores;',
'',
'    procedure preenche_itens_minuta is',
'        v_id_item  number;',
'        v_sucesso  clob;',
'        v_messages pkg_mensagem.message_record_table;',
'        v_seq      number := 0;',
'    begin',
'        for r in (',
'            select *',
'              from imp_processoimportacao_item',
'             where id_processoimportacao = v_new.id_processoimportacao',
'               and id_minutanotafiscal is null',
'        ) loop',
'            v_seq := v_seq + 1;',
'            bo_imp_minutanotafiscal_entrada_item.inclui_registro_vindo_minuta_entrada(',
'                p_id_tenant                               => r.id_tenant,',
