'        p_id_tenant out imp_minutanotafiscal_entrada_despesa.id_tenant%type,',
'        p_id_minuta out imp_minutanotafiscal_entrada_despesa.id_minuta%type,',
'        p_id_despesa out imp_minutanotafiscal_entrada_despesa.id_despesa%type,',
'        p_valor_moeda_nacional out imp_minutanotafiscal_entrada_despesa.valor_moeda_nacional%type,',
'        p_ind_despesa_tributada out imp_minutanotafiscal_entrada_despesa.ind_despesa_tributada%type, ',
'        p_id in out imp_minutanotafiscal_entrada_despesa.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
