'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_minuta */ '),
'        valida_id_minuta(v_new.id_minuta);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_despesa */ '),
'        valida_id_despesa(v_new.id_despesa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_moeda_nacional */ '),
'        valida_valor_moeda_nacional(v_new.valor_moeda_nacional);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_despesa_tributada */ '),
