'',
'    procedure valida_id_tenant(p_id_tenant in imp_minutanotafiscal_entrada_despesa.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_despesa.id_tenant''); ',
