unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_id_minuta(p_id_minuta in imp_minutanotafiscal_entrada_despesa.id_minuta%type) ',
'    is ',
