'',
'    procedure valida_id_despesa(p_id_despesa in imp_minutanotafiscal_entrada_despesa.id_despesa%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_despesa is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_despesa.id_despesa''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
