unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from imp_minutanotafiscal_entrada_despesa where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_minuta)) = lower(trim(v_new.id_minuta)) and lower(trim(id_despesa)) = lowe'
||'r(trim(v_new.id_despesa)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from imp_minutanotafiscal_entrada_despesa where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_minuta)) = lower(trim(v_new.id_minuta)) and lower(trim(id_despesa)) = lowe'
||'r(trim(v_new.id_despesa)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_despesa.id_despesa'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''id_despesa'',',
