'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_id_despesa(p_id_despesa);',
'    end valida_id_despesa;     ',
'',
'    procedure valida_valor_moeda_nacional(p_valor_moeda_nacional in imp_minutanotafiscal_entrada_despesa.valor_moeda_nacional%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_valor_moeda_nacional is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_despesa.valor_moeda_nacional''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_valor_moeda_nacional(p_valor_moeda_nacional);',
'    end valida_valor_moeda_nacional;    ',
'',
'    procedure valida_ind_despesa_tributada(p_ind_despesa_tributada in imp_minutanotafiscal_entrada_despesa.ind_despesa_tributada%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ind_despesa_tributada is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_despesa.ind_despesa_tributada''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ind_despesa_tributada'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_ind_despesa_tributada(p_ind_despesa_tributada);',
'    end valida_ind_despesa_tributada;     ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_id_tenant(p_id_tenant in imp_minutanotafiscal_entrada_despesa.id_tenant%type) ',
'    is ',
'    begin ',
'        null;',
