'',
'    procedure hook_valida_valor_moeda_nacional(p_valor_moeda_nacional in imp_minutanotafiscal_entrada_despesa.valor_moeda_nacional%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_valor_moeda_nacional;     ',
'',
'    procedure hook_valida_ind_despesa_tributada(p_ind_despesa_tributada in imp_minutanotafiscal_entrada_despesa.ind_despesa_tributada%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_despesa_tributada;     ',
'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_minutanotafiscal_entrada_despesa'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_minutanotafiscal_entrada_despesa'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_minutanotafiscal_entrada_despesa'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_minutanotafiscal_entrada_despesa'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_minutanotafiscal_entrada_despesa'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_minutanotafiscal_entrada_despesa'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_minutanotafiscal_entrada_despesa%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_minuta'', p_rec.id_minuta, true);',
'        apex_json.write(''id_despesa'', p_rec.id_despesa, true);',
'        apex_json.write(''valor_moeda_nacional'', p_rec.valor_moeda_nacional, true);',
'        apex_json.write(''ind_despesa_tributada'', p_rec.ind_despesa_tributada, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'',
'    --<CUSTOMIZADO_INICIO>',
'    function detalhe_registro (',
'        p_id in imp_minutanotafiscal_entrada_despesa.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                pkg_traducao.get_traducao(c.descricao_despesa ) as imp_minutanotafiscal_entrada_despesa$id_despesa,',
'                a.valor_moeda_nacional as imp_minutanotafiscal_entrada_despesa$valor_moeda_nacional,',
'                pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada_despesa'', ''ind_despesa_tributada'', a.ind_despesa_tributada) as imp_minutanotafiscal_entrada_despesa$ind_despesa_tributada',
'            from imp_minutanotafiscal_entrada_despesa a',
'            join imp_processoimportacao_despesa b on b.id = a.id_despesa',
'            join ng_despesa 				  c on c.id = b.id_despesa',
'            where a.id = ~''||p_id);',
'    end detalhe_registro; ',
'    --<CUSTOMIZADO_FIM>   ',
'',
'',
'',
'end bo_imp_minutanotafiscal_entrada_despesa;',
'/'))
);
end;
/
