'',
'    --<CUSTOMIZADO_INICIO>',
'',
'    procedure atribui_valores_item is',
'        v_pi               imp_processoimportacao_item%rowtype;',
'        v_pit              imp_processoimportacao_item_tributo%rowtype;',
'        v_di               imp_declaracaoimportacao%rowtype;',
'        v_mn               imp_minutanotafiscal_entrada%rowtype;',
'        v_ei               imp_entrega_item%rowtype;',
'        v_entrega          imp_entrega%rowtype;',
'        v_not              imp_naturezaoperacao_tributo%rowtype;',
'        v_taxa_cambio      number := 1;',
'        v_total_valor      number := 0;',
'        v_id_invoice       number;',
'        v_num_invoice      varchar2(40);',
'        v_id_moeda_invoice number;',
'    begin',
'        -- 0. Defaults',
'        v_new.origem := nvl(v_new.origem, 1);',
'',
'        -- 1. Dados do processo_item e tributos',
'        select * into v_pi  from imp_processoimportacao_item         where id = v_new.id_processo_item;',
'        select * into v_pit from imp_processoimportacao_item_tributo  where id_processoimportacao_item = v_new.id_processo_item;',
'',
'        -- 2. DI do processo',
'        select * into v_di from imp_declaracaoimportacao where id_processoimportacao = v_pi.id_processoimportacao;',
'',
'        -- 3. Minuta',
'        select * into v_mn from imp_minutanotafiscal_entrada where id = v_new.id_minuta;',
'',
unistr('        -- 4. Entrega item \2192 Entrega \2192 Invoice'),
'        select * into v_ei    from imp_entrega_item where id = v_new.id_entrega_item;',
'        select * into v_entrega from imp_entrega    where id = v_ei.id_entrega;',
'        v_id_invoice := v_entrega.id_invoice;',
'        select num_invoice, id_moeda',
'          into v_num_invoice, v_id_moeda_invoice',
'          from imp_invoice',
'         where id = v_id_invoice;',
'',
unistr('        -- 5. Natureza de opera\00E7\00E3o tributo'),
'        select * into v_not',
'          from imp_naturezaoperacao_tributo',
'         where id_naturezaoperacao = v_pi.id_naturezaoperacao;',
'',
unistr('        -- 6. Taxa de c\00E2mbio'),
'        select c.taxa_cambio into v_taxa_cambio',
'          from imp_processoimportacao_numerario n',
'          join imp_processoimportacao_numerario_cotacao c on c.id_numerario = n.id',
'         where n.id_processoimportacao = v_pi.id_processoimportacao',
'           and c.id_moeda              = v_id_moeda_invoice',
'           and rownum = 1;',
'',
unistr('        -- 7. Campos de identifica\00E7\00E3o'),
'        v_new.id_duimp            := v_di.id;',
'        v_new.id_invoice          := v_id_invoice;',
'        v_new.id_moeda_invoice    := v_id_moeda_invoice;',
'        v_new.num_invoice         := v_num_invoice;',
'        v_new.id_naturezaoperacao := nvl(v_new.id_naturezaoperacao, v_pi.id_naturezaoperacao);',
'        v_new.id_fabricante       := nvl(v_new.id_fabricante,       v_pi.id_fabricante);',
'',
unistr('        -- 8. Sequ\00EAncia do item na invoice'),
'        select sequencia_item_invoice into v_new.sequencia_item_invoice',
'          from imp_invoice_item',
'         where id_invoice      = v_id_invoice',
'           and id_entrega_item = v_new.id_entrega_item;',
'',
unistr('        -- 9. Valores monet\00E1rios'),
'        v_new.valor_unitario_mercadoria_moedanacional :=',
'            round(nvl(v_pi.valor_unitario, 0) * v_taxa_cambio, 5);',
'',
'        v_new.valor_desconto_moedanacional :=',
'            round(nvl(v_pi.valor_total_desconto_invoice_item, 0) * v_taxa_cambio, 5);',
'',
'        v_new.valor_total_mercadoria_moedanacional :=',
'            round(nvl(v_pi.valor_unitario, 0) * nvl(v_new.quantidade, 0) * v_taxa_cambio',
'                  - v_new.valor_desconto_moedanacional, 2);',
'',
'        -- 10. Valores diretos do processo_item_tributo',
'        -- v_new.valor_aduaneiro_moedanacional := round(nvl(v_pit.vmld,        0) * v_taxa_cambio, 5);',
'        -- v_new.frete_moedanacional           := nvl(v_pit.frete,       0);',
'        -- v_new.seguro_moedanacional          := nvl(v_pit.seguro,      0);',
'        -- v_new.acrescimo_moedanacional       := nvl(v_pit.acrescimo,   0);',
'        -- v_new.afrmm                         := nvl(v_pit.afrmm,       0);',
'        -- v_new.antidumping                   := nvl(v_pit.antidumping, 0);',
'',
'        -- 11. Rateio despesa_acessoria por valor_total_mercadoria',
'        select nvl(sum(valor_total_mercadoria_moedanacional), 0) into v_total_valor',
'          from imp_minutanotafiscal_entrada_item',
'         where id_minuta = v_new.id_minuta',
'           and id != nvl(v_new.id, -1);',
'        v_total_valor := v_total_valor + nvl(v_new.valor_total_mercadoria_moedanacional, 0);',
'        if v_total_valor > 0 then',
'            v_new.despesa_acessoria := round(nvl(v_mn.despesa_acessoria, 0) * nvl(v_new.valor_total_mercadoria_moedanacional, 0) / v_total_valor, 2);',
'        else',
'            v_new.despesa_acessoria := 0;',
'        end if;',
'',
unistr('        -- 12. Regimes de tributa\00E7\00E3o'),
'        v_new.ind_regime_tributacao_ii     := v_not.ind_aplicacao_ii;',
'        v_new.ind_regime_tributacao_ipi    := v_not.ind_aplicacao_ipi;',
'        v_new.ind_regime_tributacao_pis    := v_not.ind_aplicacao_pis_cofins;',
'        v_new.ind_regime_tributacao_cofins := v_not.ind_aplicacao_pis_cofins;',
'        v_new.ind_regime_tributacao_cbs    := v_not.ind_aplicacao_cbs;',
'        v_new.ind_regime_tributacao_icms   := v_not.ind_aplicacao_icms;',
'        v_new.ind_regime_tributacao_ibs    := v_not.ind_aplicacao_ibs;',
'',
'        -- 13. II',
'        -- v_new.aliquota_ii := nvl(v_pit.aliquota_ii, 0);',
'        -- v_new.valor_ii    := case when nvl(v_pit.valor_informado_ii, 0) != 0',
'        --                           then v_pit.valor_informado_ii',
'        --                           else nvl(v_pit.valor_calculado_ii, 0) end;',
'',
'        -- 14. IPI',
'        -- v_new.base_calculo_ipi := nvl(v_pit.base_calculo_ipi, 0);',
'        -- v_new.aliquota_ipi     := nvl(v_pit.aliquota_ipi,     0);',
'        -- v_new.valor_ipi        := nvl(v_pit.valor_ipi,        0);',
'',
'        -- -- 15. PIS',
'        -- v_new.base_calculo_pis := nvl(v_pit.base_calculo_pis_cofins, 0);',
'        -- v_new.aliquota_pis     := nvl(v_pit.aliquota_pis,            0);',
'        -- v_new.valor_pis        := nvl(v_pit.valor_pis,               0);',
'',
'        -- -- 16. COFINS',
'        -- v_new.base_calculo_cofins := nvl(v_pit.base_calculo_pis_cofins, 0);',
'        -- v_new.aliquota_cofins     := nvl(v_pit.aliquota_cofins,         0);',
'        -- v_new.valor_cofins        := nvl(v_pit.valor_cofins,            0);',
'',
'        -- -- 17. CBS',
'        -- v_new.base_calculo_cbs := nvl(v_pit.base_calculo_cbs, 0);',
'        -- v_new.aliquota_cbs     := nvl(v_pit.aliquota_cbs,     0);',
'        -- v_new.valor_cbs        := nvl(v_pit.valor_cbs,        0);',
'',
'        -- -- 18. ICMS',
'        -- v_new.base_calculo_icms    := nvl(v_pit.base_calculo_icms,    0);',
'        -- v_new.base_calculo_icms_st := nvl(v_pit.base_calculo_icms_st, 0);',
'        -- v_new.aliquota_icms        := nvl(v_pit.aliquota_icms,        0);',
'        -- v_new.valor_icms           := nvl(v_pit.valor_icms,           0);',
'        -- v_new.valor_icms_st        := nvl(v_pit.valor_icms_st,        0);',
'',
'        -- -- 19. IBS',
'        -- v_new.base_calculo_ibs := nvl(v_pit.base_calculo_ibs, 0);',
'        -- v_new.aliquota_ibs     := nvl(v_pit.aliquota_ibs,     0);',
'        -- v_new.valor_ibs        := nvl(v_pit.valor_ibs,        0);',
'',
'    end atribui_valores_item;',
'',
'    procedure altera_minuta_item(',
'        p_cst                 in imp_minutanotafiscal_entrada_item.cst%type,',
'        p_cfop                in imp_minutanotafiscal_entrada_item.cfop%type,',
'        p_cclasstrib          in imp_minutanotafiscal_entrada_item.cclasstrib%type,',
'        p_id_naturezaoperacao in imp_minutanotafiscal_entrada_item.id_naturezaoperacao%type,',
'        p_id                  in imp_minutanotafiscal_entrada_item.id%type,',
'        p_encadeado           in boolean default false,',
'        p_sucesso             out clob,',
'        p_messages            out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_minutanotafiscal_entrada_item.altera_minuta_item'';',
'',
'        verifica_registro(p_id);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if;',
'',
'        select * into v_old from imp_minutanotafiscal_entrada_item where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.cst                 := p_cst;',
'        v_new.cfop                := p_cfop;',
'        v_new.cclasstrib          := p_cclasstrib;',
'        v_new.id_naturezaoperacao := p_id_naturezaoperacao;',
'        v_new.id_usuario_alterou  := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao      := sysdate;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'',
'    end altera_minuta_item;',
'',
'    procedure inclui_registro_vindo_minuta_entrada(',
'        p_id_tenant                               in imp_minutanotafiscal_entrada_item.id_tenant%type,',
'        p_id_minuta                               in imp_minutanotafiscal_entrada_item.id_minuta%type,',
'        p_sequencia_item_minuta                   in imp_minutanotafiscal_entrada_item.sequencia_item_minuta%type,',
'        p_id_processo_item                        in imp_minutanotafiscal_entrada_item.id_processo_item%type,',
'        p_id_entrega_item                         in imp_minutanotafiscal_entrada_item.id_entrega_item%type,',
'        p_id_item                                 in imp_minutanotafiscal_entrada_item.id_item%type,',
'        p_id_ncm                                  in imp_minutanotafiscal_entrada_item.id_ncm%type,',
'        p_id_unidademedida                        in imp_minutanotafiscal_entrada_item.id_unidademedida%type,',
'        p_quantidade                              in imp_minutanotafiscal_entrada_item.quantidade%type,',
'        p_peso_liquido_total                      in imp_minutanotafiscal_entrada_item.peso_liquido_total%type,',
'        p_peso_bruto_total                        in imp_minutanotafiscal_entrada_item.peso_bruto_total%type,',
'        p_valor_unitario_mercadoria_moedanacional in imp_minutanotafiscal_entrada_item.valor_unitario_mercadoria_moedanacional%type,',
'        p_id                                      out imp_minutanotafiscal_entrada_item.id%type,',
'        p_encadeado                               in boolean default false,',
'        p_sucesso                                 out clob,',
'        p_messages                                out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_minutanotafiscal_entrada_item.inclui_registro_vindo_minuta_entrada'';',
'        --',
'        v_new.id_tenant                               := p_id_tenant;',
'        v_new.id_minuta                               := p_id_minuta;',
'        v_new.sequencia_item_minuta                   := p_sequencia_item_minuta;',
'        v_new.id_processo_item                        := p_id_processo_item;',
'        v_new.id_entrega_item                         := p_id_entrega_item;',
'        v_new.id_item                                 := p_id_item;',
'        v_new.id_ncm                                  := p_id_ncm;',
'        v_new.id_unidademedida                        := p_id_unidademedida;',
'        v_new.quantidade                              := p_quantidade;',
'        v_new.peso_liquido_total                      := p_peso_liquido_total;',
'        v_new.peso_bruto_total                        := p_peso_bruto_total;',
'        v_new.valor_unitario_mercadoria_moedanacional := p_valor_unitario_mercadoria_moedanacional;',
'        v_new.id_usuario_incluiu                      := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_inclusao                           := sysdate;',
'        v_new.id_usuario_alterou                      := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao                          := sysdate;',
'        v_new.id                                      := null;',
'        --',
'        -- Calcula todos os campos fiscais antes de cria (valida roda antes do hook)',
'        atribui_valores_item;',
'        --',
'        cria(p_encadeado, p_sucesso, p_messages, p_id);',
'    end inclui_registro_vindo_minuta_entrada;',
'',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false, p_sucesso out clob, p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        atribui_valores_item;',
'    end hook_antes_incluir;',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        bo_imp_processoimportacao_item.vincula_minutanotafiscal(',
'            p_id                  => v_new.id_processo_item,',
'            p_id_minutanotafiscal => v_new.id_minuta,',
'            p_encadeado           => true,',
'            p_sucesso             => p_sucesso,',
'            p_messages            => p_messages',
'        );',
'    end;',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false, p_sucesso out clob, p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        atribui_valores_item;',
'    end hook_antes_alterar;',
'    --',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        null;',
'    end;',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        null;',
'    end;',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        null;',
'    end;',
'',
'    --',
'',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_minutanotafiscal_entrada_item;',
'/'))
);
end;
