'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;',
'    --',
'    function row_to_json(p_rec in imp_minutanotafiscal_entrada_item_atributo%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_item_minuta'', p_rec.id_item_minuta, true);',
'        apex_json.write(''id_atributoitem'', p_rec.id_atributoitem, true);',
'        apex_json.write(''valor_atributo_dominio'', p_rec.valor_atributo_dominio, true);',
