'        apex_json.write(''valor_atributo_valor'', p_rec.valor_atributo_valor, true);',
'        apex_json.write(''valor_atributo_texto'', p_rec.valor_atributo_texto, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;',
'',
'',
'',
'end bo_imp_minutanotafiscal_entrada_item_atributo;',
'/'))
);
