'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_minutanotafiscal_entrada_transporte'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_minutanotafiscal_entrada_transporte'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_minutanotafiscal_entrada_transporte'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_minutanotafiscal_entrada_transporte'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_minutanotafiscal_entrada_transporte'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_minutanotafiscal_entrada_transporte%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_minuta'', p_rec.id_minuta, true);',
'        apex_json.write(''id_transportador'', p_rec.id_transportador, true);',
'        apex_json.write(''placa_veiculo'', p_rec.placa_veiculo, true);',
'        apex_json.write(''chassi_do_transporte_rodovario'', p_rec.chassi_do_transporte_rodovario, true);',
'        apex_json.write(''id_acondicionamento_carga'', p_rec.id_acondicionamento_carga, true);',
'        apex_json.write(''quantidade_acondicionamento'', p_rec.quantidade_acondicionamento, true);',
'        apex_json.write(''container'', p_rec.container, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'',
'',
'end bo_imp_minutanotafiscal_entrada_transporte;',
'/'))
);
end;
