'        --     join imp_entrega b on b.id_pedidoimportacao = a.id',
'        --     where b.id = l_id_entrega;',
'',
'        --     select',
'        --         id_tenant,',
'        --         id_exportador,',
'        --         id_importador,',
'        --         id_adquirente,',
'        --         id_incoterm',
'        --     into',
'        --         l_id_tenant,',
'        --         l_id_exportador,',
'        --         l_id_importador,',
'        --         l_id_adquirente,',
'        --         l_id_incoterm',
'        --     from imp_entrega',
'        --     where id = l_id_entrega;',
'        -- elsif apex_util.get_session_state(''P9000_PAGINA'') = ''TD677'' then',
'        --     l_id_entrega := apex_util.get_session_state(''P9000_ID'');',
'        --     select',
'        --         a.id_condicaopagamento,',
'        --         a.id_moeda',
'        --     into',
'        --         l_id_condicaopagamento,',
'        --         l_id_moeda',
'        --     from imp_pedidoimportacao a',
'        --     join imp_entrega b on b.id_pedidoimportacao = a.id',
'        --     where b.id = l_id_entrega;',
'',
'        --     select',
'        --         id_tenant,',
'        --         id_exportador,',
'        --         id_importador,',
'        --         id_adquirente,',
'        --         id_incoterm',
'        --     into',
'        --         l_id_tenant,',
'        --         l_id_exportador,',
'        --         l_id_importador,',
'        --         l_id_adquirente,',
'        --         l_id_incoterm',
'        --     from imp_entrega',
'        --     where id = l_id_entrega;',
'        -- elsif apex_util.get_session_state(''P9005_CODIGO_ARTEFATO'') = ''TD846'' then',
'        --     l_id_processoimportacao := apex_util.get_session_state(''P9005_PARAMETRO'');',
'        --     select count(1) into l_verifica_entrega from imp_entrega where id_processoimportacao = l_id_processoimportacao;',
'        --     if l_verifica_entrega > 0 then',
'        --         select',
'        --             a.id_condicaopagamento,',
'        --             b.id_incoterm,',
'        --             a.id_moeda',
'        --         into',
'        --             l_id_condicaopagamento,',
'        --             l_id_incoterm,',
'        --             l_id_moeda',
'        --         from imp_pedidoimportacao a',
'        --         join imp_entrega b on b.id_pedidoimportacao = a.id',
'        --         where id_processoimportacao = l_id_processoimportacao',
'        --         fetch first 1 row only;',
'        --     end if;',
'        --     select id_tenant into l_id_tenant from imp_processoimportacao where id = l_id_processoimportacao;',
'        --     select id_embarcador into l_id_exportador from imp_processoimportacao where id = l_id_processoimportacao;',
'        --     select id_importador into l_id_importador from imp_processoimportacao where id = l_id_processoimportacao;',
'        --     select id_adquirente into l_id_adquirente from imp_processoimportacao where id = l_id_processoimportacao;',
'        -- end if;',
'',
'				select count(distinct id_exportador) into v_count_id_exportador from imp_processoimportacao_item where id_processoimportacao = p_param2;',
'',
'				if v_count_id_exportador < 1 then',
'			  	v_id_exportador := null;',
'				elsif v_count_id_exportador = 1 then',
'					select id_exportador into v_id_exportador from imp_processoimportacao_item where id_processoimportacao = p_param2 AND rownum = 1;',
'				else',
'					 select id_exportador',
'						into v_id_exportador',
'						from (',
'						    select distinct i.id_exportador',
'						    from imp_processoimportacao_item i',
'						    where i.id_processoimportacao = p_param2',
'						      and not exists (',
'						            select 1',
'						            from imp_minutanotafiscal_entrada m',
'						            where m.id_processoimportacao = i.id_processoimportacao',
'						              and m.id_exportador = i.id_exportador',
'						      )',
'						)',
'						where rownum = 1;',
'		 		end if;',
'',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from imp_processoimportacao wher'
||'e id = p_param2)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor'',         									 2, ''HID'', null, ''S'', ''N'', p_param2 valor FROM dual UNION ALL',
'	       			 SELECT p_codigo_artefato, ''minuta'',          								 4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''ind_natureza_notafiscal'',          6, '''', null, ''N'', ''S'', to_char((1)) valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_processoimportacao'',            8, '''', null, ''S'', ''S'', to_char((select num_processoimportacao from imp_processoimportacao where id = p_param2)) valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''numero_duimp'',           					10, '''', null, ''S'', ''S'', to_char((select a.numero_duimp from imp_declaracaoimportacao a left join imp_processoimportacao b on b.id = a.id_processoimportacao where b.id = p_param2)) val'
||'or FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_exportador'',           			  12, '''', null, ''N'', ''S'', to_char(v_id_exportador) valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_importador'',           			  14, '''', null, ''S'', ''S'', to_char((select b.id_importador from imp_processoimportacao b where b.id = p_param2)) valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_destinatario'',           			16, '''', null, ''N'', ''S'', to_char((select b.id_importador from imp_processoimportacao b where b.id = p_param2)) valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_endereco_destino'',             18, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_recinto_alfandegado'',          20, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''id_uf_nacionalizacao'',            22, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'					     SELECT p_codigo_artefato, ''dados_complementares'',            24, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'				     SELECT p_codigo_artefato, ''id_processoimportacao_hid'',       26, ''HID'', null, ''S'', ''N'', p_param2 valor FROM dual',
'',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'',
'    function where_dinamico(p_campo in varchar2)',
'        return clob',
'        is',
' ',
'        begin',
'',
'',
'            if upper(p_campo) = upper(''id_endereco_destino'') then',
'	    					return q''~',
' 								where (b.data_fim_vigencia is null',
'                        or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                    )',
'                and b.id in (        ',
'                        select c003 from apex_collections where collection_name = ''TD1021_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f17_0000'')',
'                    )     ',
'                ~'';',
'                -- return q''~',
'                --     where b.id in (select c003 from apex_collections where collection_name = ''TD1021_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f16_0000'')',
'                -- ~'';',
'            else',
'                return '''';',
'            end if;',
'    end;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'         bo_imp_minutanotafiscal_entrada.inclui_registro_e_preenche_itens(',
'            p_id_tenant               => pkg_util.retorna_number(apex_application.g_f01(1)),',
