'            p_messages                => p_messages',
'        );',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        v_rec imp_minutanotafiscal_entrada%rowtype;',
'    begin',
'        select * into v_rec from imp_minutanotafiscal_entrada where id = p_id;',
'',
'        bo_imp_minutanotafiscal_entrada.altera_registro(',
'            p_id_tenant                            => pkg_util.retorna_number(apex_application.g_f01(1)),',
'            p_minuta                               => pkg_util.retorna_number(apex_application.g_f04(1)),',
'            p_ind_natureza_notafiscal              => pkg_util.retorna_number(apex_application.g_f06(1)),',
