'            p_data_nacionalizacao_real             => v_rec.data_nacionalizacao_real,',
'            p_ind_status_minuta                    => NVL(v_rec.ind_status_minuta, 1),',
unistr('            p_ind_status_transmiss\00E3o               => NVL(v_rec.ind_status_transmiss\00E3o, 1),'),
'            p_id_exportador                        => pkg_util.retorna_number(apex_application.g_f12(1)),',
'            p_id_importador                        => pkg_util.retorna_number(apex_application.g_f14(1)),',
'            p_id_adquirente                        => v_rec.id_adquirente,',
'            p_id_destinatario                      => pkg_util.retorna_number(apex_application.g_f16(1)),',
'            p_id_local_desembarque                 => v_rec.id_local_desembarque,',
'            p_id_endereco_destino                  => pkg_util.retorna_number(apex_application.g_f18(1)),',
'            p_id_recinto_alfandegado               => pkg_util.retorna_number(apex_application.g_f20(1)),',
'            p_id_uf_nacionalizacao                 => pkg_util.retorna_number(apex_application.g_f22(1)),',
'            p_id_condicaopagamento                 => v_rec.id_condicaopagamento,',
'            p_id_incoterm                          => v_rec.id_incoterm,',
'            p_id_transportador_internacional       => v_rec.id_transportador_internacional,',
'            p_navio                                => v_rec.navio,',
'            p_volume                               => NVL(v_rec.volume, 0),',
'            p_peso_liquido_carga                   => NVL(v_rec.peso_liquido_carga, 0),',
'            p_peso_bruto_carga                     => NVL(v_rec.peso_bruto_carga, 0),',
'            p_valor_total_mercadoria_moedanacional => NVL(v_rec.valor_total_mercadoria_moedanacional, 0),',
'            p_frete_internacional_moedanacional    => NVL(v_rec.frete_internacional_moedanacional, 0),',
'            p_seguro_internacional_moedanacional   => NVL(v_rec.seguro_internacional_moedanacional, 0),',
'            p_acrescimo_moedanacional              => NVL(v_rec.acrescimo_moedanacional, 0),',
'            p_valor_desconto_moedanacional         => NVL(v_rec.valor_desconto_moedanacional, 0),',
'            p_base_calculo_icms                    => NVL(v_rec.base_calculo_icms, 0),',
'            p_base_calculo_icms_st                 => NVL(v_rec.base_calculo_icms_st, 0),',
'            p_valor_icms                           => NVL(v_rec.valor_icms, 0),',
'            p_valor_icms_st                        => NVL(v_rec.valor_icms_st, 0),',
'            p_valor_ipi                            => NVL(v_rec.valor_ipi, 0),',
'            p_despesa_acessoria                    => NVL(v_rec.despesa_acessoria, 0),',
'            p_valor_total_notafiscal               => NVL(v_rec.valor_total_notafiscal, 0),',
