'            p_ind_minuta_integrada                 => v_rec.ind_minuta_integrada,',
'            p_ind_notafiscal_emitida               => v_rec.ind_notafiscal_emitida,',
'            p_nf_emitida                           => v_rec.nf_emitida,',
'            p_id                                   => p_id,',
'            p_data_alteracao                       => v_rec.data_alteracao,',
'            p_sucesso                              => p_sucesso,',
