prompt --application/deployment/install/install_ui_mpd_td1022
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(150330849246107046)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1022'
,p_sequence=>270
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1022" as',
'',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'',
'end "UI_MPD_TD1022";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD1022" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
' ',
'    begin    ',
'   ',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null dependencia, null atribuir_valor, null calcul'
||'ar_valor FROM dual ',
'',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, calcular_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.calcular_valor);',
'    end formulario;',
'',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                b.codigo_item campo1,                ',
'                corta_texto(pkg_traducao.get_traducao(b.descricao_item)) campo2,',
'								d.descricao_ncm  campo3,',
'                a.cst 			 		 campo4,',
'                a.cfop 			 		 campo5,                ',
'                a.cclasstrib 		 campo6,',
'                e.descricao  		 campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao_com_icone(p_id => a.id, p_pagina => ''TD1022'', p_param1 => a.id) opcao',
'            from imp_minutanotafiscal_entrada_item a',
'            join ng_item 				 			b on b.id = a.id_item',
'	    			join ng_item_produto 		  c on c.id_item = a.id_item',
'						join ng_ncm 						  d on d.id = c.id_ncm',
'						join imp_naturezaoperacao e on e.id = a.id_naturezaoperacao',
'						join imp_minutanotafiscal_entrada f on f.id = a.id_minuta',
'            where f.id = #param1#',
'            order by a.sequencia_item_minuta',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                apex_item.checkbox(1,a.id,''onclick="seleciona(this);"'') selected,',
'                 a.id,',
'                b.codigo_item campo1,                ',
'                corta_texto(pkg_traducao.get_traducao(b.descricao_item)) campo2,',
'                d.descricao_ncm  campo3,',
'                a.cst 			 		 campo4,',
'                a.cfop 			 		 campo5,                ',
'                a.cclasstrib 		 campo6,',
'                e.descricao  		 campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD1022'', p_param1 => a.id) opcao',
'            from imp_minutanotafiscal_entrada_item a',
'            join ng_item 				 			b on b.id = a.id_item',
'	    			join ng_item_produto 		  c on c.id_item = a.id_item',
'						join ng_ncm 						  d on d.id = c.id_ncm',
'						join imp_naturezaoperacao e on e.id = a.id_naturezaoperacao',
'						join imp_minutanotafiscal_entrada f on f.id = a.id_minuta',
'            where f.id = #param1#',
'            order by a.sequencia_item_minuta',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item_produto.id_ncm'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_item.cst'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_item.cfop'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_item.cclasstrib'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_item.id_naturezaoperacao'') into l_campo from dual;',
'        elsif campo = ''0'' then                     ',
'            l_campo := '''';        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'',
'end "UI_MPD_TD1022";',
'/'))
);
end;
/
