'',
'end "UI_MPD_TD1023";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD1023" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'    begin    ',
'     ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null dependencia, null atribuir_valor, null calcular_'
||'valor FROM dual ',
'',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, calcular_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.calcular_valor);',
'    end formulario;',
'',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                c.descricao_despesa      campo1,                ',
'                a.valor_moeda_nacional   campo2,',
'								pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada_despesa'', ''ind_despesa_tributada'', a.ind_despesa_tributada) campo3,',
'                null campo4,',
'                null campo5,                ',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao_com_icone(p_id => a.id, p_pagina => ''TD1023'', p_param1 => a.id) opcao',
'            from imp_minutanotafiscal_entrada_despesa a',
'            join imp_processoimportacao_despesa b on b.id = a.id_despesa',
'            join ng_despesa 				  c on c.id = b.id_despesa',
'            where a.id_minuta = #param1#',
'            order by c.descricao_despesa',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                null selected,',
'                a.id,',
'                c.descricao_despesa      campo1,                ',
'                a.valor_moeda_nacional   campo2,',
'			    pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada_despesa'', ''ind_despesa_tributada'', a.ind_despesa_tributada) campo3,',
