'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD1023'', p_param1 => a.id) opcao',
'            from imp_minutanotafiscal_entrada_despesa a',
'            join imp_processoimportacao_despesa b on b.id = a.id_despesa',
'            join ng_despesa 				  c on c.id = b.id_despesa',
'            where a.id_minuta = #param1#',
'            order by c.descricao_despesa',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
