prompt --application/deployment/install/install_ui_mpd_td1024
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(150331061321100818)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1024'
,p_sequence=>290
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1024" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD1024";',
'/',
'',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD1024" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        v_count_id_exportador number;',
'        v_id_exportador       number;',
'        v_json_dep_ind_container CLOB;',
'        v_atribuir_valor_acond   CLOB;',
'        v_condicoes    array_varchar := array_varchar(''IND_CONTAINER == %S%'', ''IND_CONTAINER == %N%'');',
'        v_colunas_alvo array_varchar := array_varchar(''container'', ''quantidade_acondicionamento'');',
'        v_comportamentos array_varchar := array_varchar(''vis'', ''vis'');',
'        l_campos apex_t_varchar2 := apex_t_varchar2(''IND_CONTAINER'');',
'        v_trans imp_minutanotafiscal_entrada_transporte%rowtype;',
'',
'    begin',
'',
'        select count(distinct id_exportador) into v_count_id_exportador from imp_processoimportacao_item where id_processoimportacao = p_param2;',
'',
'        if v_count_id_exportador < 1 then',
'            v_id_exportador := null;',
'        elsif v_count_id_exportador = 1 then',
'            select id_exportador into v_id_exportador from imp_processoimportacao_item where id_processoimportacao = p_param2 AND rownum = 1;',
'        else',
'            select id_exportador',
'            into v_id_exportador',
'            from (',
'                select distinct i.id_exportador',
'                from imp_processoimportacao_item i',
'                where i.id_processoimportacao = p_param2',
'                  and not exists (',
'                        select 1',
'                        from imp_minutanotafiscal_entrada m',
'                        where m.id_processoimportacao = i.id_processoimportacao',
'                          and m.id_exportador = i.id_exportador',
'                  )',
'            )',
'            where rownum = 1;',
'        end if;',
'',
'        begin',
'            select * into v_trans',
'              from imp_minutanotafiscal_entrada_transporte',
'             where id_minuta = to_number(p_param1)',
'               and rownum = 1;',
'        exception',
'            when no_data_found then v_trans := null;',
'        end;',
'',
'        v_json_dep_ind_container := gerar_json_dependencias_array(v_condicoes, v_colunas_alvo, v_comportamentos);',
'        v_atribuir_valor_acond   := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_valor'', l_campos);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_transportador'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char(v_trans.id_transportador) valor, null depen'
||'dencia, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''placa_veiculo'',                       4, '''', null, ''N'', ''S'', v_trans.placa_veiculo valor, null dependencia, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''chassi_do_transporte_rodovario'',      6, '''', null, ''N'', ''S'', v_trans.chassi_do_transporte_rodovario valor, null dependencia, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_acondicionamento_carga'',          10, '''', null, ''N'', ''S'', to_char(v_trans.id_acondicionamento_carga) valor, null dependencia, v_atribuir_valor_acond atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_acondicionamento'',        12, '''', null, ''N'', ''S'', to_char(v_trans.quantidade_acondicionamento) valor, null dependencia, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''container'',                          14, '''', null, ''N'', ''S'', v_trans.container valor, null dependencia, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''IND_CONTAINER'',                      15, ''HID'', null, ''N'', ''N'', null valor, v_json_dep_ind_container dependencia, null atribuir_valor FROM dual',
'               ) new_data',
'        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)',
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor);',
'    end formulario;',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'                    select ind_container',
'                    from ng_acondicionamentocarga',
'                    where id = #ID#',
'               ~'';',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end sql_atribuir_valor;',
'',
'    function where_dinamico(p_campo in varchar2)',
'        return clob',
'        is',
'        begin',
'            if upper(p_campo) = upper(''id_endereco_destino'') then',
'                return q''~',
'                    where b.id in (select c003 from apex_collections where collection_name = ''TD1021_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f16_0000'')',
'                ~'';',
'            else   ',
'                return '''';',
'            end if;',
'    end;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'        v_minuta        imp_minutanotafiscal_entrada%rowtype;',
'        v_rec           imp_minutanotafiscal_entrada_transporte%rowtype;',
'        v_id_minuta     imp_minutanotafiscal_entrada.id%type;',
'        v_id_transporte imp_minutanotafiscal_entrada_transporte.id%type;',
'    begin',
'        v_id_minuta := to_number(apex_util.get_session_state(''P9012_PARAMETRO''));',
'',
'        select * into v_minuta from imp_minutanotafiscal_entrada where id = v_id_minuta;',
'',
'        begin',
'            select id into v_id_transporte',
'              from imp_minutanotafiscal_entrada_transporte',
'             where id_minuta = v_id_minuta',
'               and rownum = 1;',
'        exception',
'            when no_data_found then v_id_transporte := null;',
'        end;',
'',
'        if v_id_transporte is null then',
'            bo_imp_minutanotafiscal_entrada_transporte.inclui_registro(',
'                p_id_tenant                      => v_minuta.id_tenant,',
'                p_id_minuta                      => v_minuta.id,',
'                p_id_transportador               => apex_application.g_f01(1),',
'                p_placa_veiculo                  => apex_application.g_f04(1),',
'                p_chassi_do_transporte_rodovario => apex_application.g_f06(1),',
'                p_id_acondicionamento_carga      => apex_application.g_f10(1),',
'                p_quantidade_acondicionamento    => apex_application.g_f12(1),',
'                p_container                      => apex_application.g_f14(1),',
'                p_id                             => p_id,',
'                p_sucesso                        => p_sucesso,',
'                p_messages                       => p_messages',
'            );',
'        else',
'            select * into v_rec from imp_minutanotafiscal_entrada_transporte where id = v_id_transporte;',
'            bo_imp_minutanotafiscal_entrada_transporte.altera_registro(',
'                p_id_tenant                      => v_rec.id_tenant,',
'                p_id_minuta                      => v_rec.id_minuta,',
'                p_id_transportador               => apex_application.g_f01(1),',
'                p_placa_veiculo                  => apex_application.g_f04(1),',
'                p_chassi_do_transporte_rodovario => apex_application.g_f06(1),',
'                p_id_acondicionamento_carga      => apex_application.g_f10(1),',
'                p_quantidade_acondicionamento    => apex_application.g_f12(1),',
'                p_container                      => apex_application.g_f14(1),',
'                p_id                             => v_id_transporte,',
'                p_data_alteracao                 => v_rec.data_alteracao,',
'                p_sucesso                        => p_sucesso,',
'                p_messages                       => p_messages',
'            );',
'            p_id := v_id_transporte;',
'        end if;',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'        v_rec imp_minutanotafiscal_entrada_transporte%rowtype;',
'    begin',
'        select * into v_rec from imp_minutanotafiscal_entrada_transporte where id = p_id;',
'',
'        bo_imp_minutanotafiscal_entrada_transporte.altera_registro(',
'            p_id_tenant                      => v_rec.id_tenant,',
'            p_id_minuta                      => v_rec.id_minuta,',
'            p_id_transportador               => apex_application.g_f01(1),',
'            p_placa_veiculo                  => apex_application.g_f04(1),',
'            p_chassi_do_transporte_rodovario => apex_application.g_f06(1),',
'            p_id_acondicionamento_carga      => apex_application.g_f10(1),',
'            p_quantidade_acondicionamento    => apex_application.g_f12(1),',
'            p_container                      => apex_application.g_f14(1),',
'            p_id                             => p_id,',
'            p_data_alteracao                 => v_rec.data_alteracao,',
'            p_sucesso                        => p_sucesso,',
'            p_messages                       => p_messages',
'        );',
'    end post_save;',
'',
'end "UI_MPD_TD1024";',
'/'))
);
end;
