'        v_executa_js_maximo CLOB;',
'        v_json_dependecia_ind_valor CLOB;',
'        v_condicoes_ind_valor      array_varchar := array_varchar(''IND_VALOR == %L%'', ''IND_VALOR == %D%'', ''IND_VALOR == %T%'', ''IND_VALOR == %N%'');',
'        v_colunas_alvo_ind_valor   array_varchar := array_varchar(''VALOR_ATRIBUTO_DOMINIO'', ''VALOR_ATRIBUTO_DATA'', ''VALOR_ATRIBUTO_TEXTO'', ''VALOR_ATRIBUTO_VALOR'');',
'        v_comportamentos_ind_valor array_varchar := array_varchar(''vis'', ''vis'', ''vis'', ''vis'');',
'    begin',
'        v_json_dependecia_ind_valor := gerar_json_dependencias_array(v_condicoes_ind_valor, v_colunas_alvo_ind_valor, v_comportamentos_ind_valor);',
'',
'        prc_enviar_parametros(''TD651'',''id_atributoitem'',p_param1);',
'        v_executa_js_digito := ''atualizarDigitsCampo("VALOR_ATRIBUTO_VALOR","QTD_DECIMAIS","VALOR_INICIAL","VALOR_FINAL");'';',
'',
'',
'',
'        l_consulta :=',
'            ''select',
'                d, r',
'             from (',
'                select',
'                    pkg_traducao.get_traducao(descricao_dominio) d,',
'                    a.id r',
'                from ng_atributoitem_dominio a',
'                where a.id_atributoitem = (',
'                    select id',
'                    from ng_atributoitem',
'                    where descricao_atributoitem = (',
'                        select c002',
'                        from apex_collections',
'                        where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||''''''',
'                          and upper(c001) = upper(''''f05_0000'''')',
'                    )',
'                )',
'             )',
'             order by d'';',
'        l_atribuir_valor_ind_valor := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor'',',
'            l_campos',
'        );',
'',
'',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''codigo_item'' AS nome_coluna, 2 AS indice, ''TXT'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' as coluna_tabela, to_char((select a.codigo_item from ng_item a join IMP'
||'_MINUTANOTAFISCAL_ENTRADA_ITEM b on b.id_item = a.id where b.id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom,''ng_item.codigo_item'' tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_item'',                3, ''TXT'', null, ''S'', ''N'', to_char((select a.descricao_item from ng_item a join IMP_MINUTANOTAFISCAL_ENTRADA_ITEM b on b.id_item = a.id where b.id = p_param1)) valor, null depen'
||'dencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom ,''ng_item.descricao_item'' tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_atributoitem'',               4, '''',null, ''N'', ''S'', null , null, l_atribuir_valor_ind_valor atribuir_valor, null executa_js, 6025 id_artefato_versionado_zoom, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''IND_VALOR'',                     8, ''HID'',null, ''N'', ''N'', null , v_json_dependecia_ind_valor dependencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION '
||'ALL',
'               SELECT p_codigo_artefato, ''QTD_DECIMAIS'',                  12,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoo, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_INICIAL'',                 14,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_FINAL'',                   16,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_DATA'',           9, '''', null, ''N'', ''S'', null ,  null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_VALOR'',          10, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_TEXTO'',          11, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_minuta_item'',                40, ''HID'', null, ''N'', ''N'', p_param1 valor , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_DOMINIO'',        6, ''POP1'',to_char(l_consulta), ''N'', ''S'', null , null, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom, null tag_campo from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js, id_artefato_versionado_zoom, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js, new_data.id_artefato_versionado_zoom, new_data.tag_campo);',
'    end formulario;',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'                    select ind_valor, qtd_decimais, valor_inicial, valor_final',
'                    from ng_atributoitem',
'                    where id = #ID#',
'               ~'';',
'        return replace(l_sql,''#ID#'',p_param1);',
'    end sql_atribuir_valor;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'            v_rec       imp_minutanotafiscal_entrada_item%rowtype;',
'            v_id        imp_minutanotafiscal_entrada_item_atributo.id%type;',
'            v_ind_valor ng_atributoitem.ind_valor%type;',
'    begin',
'            select * into v_rec from imp_minutanotafiscal_entrada_item where id = apex_util.get_session_state(''P9010_PARAMETRO'');',
'',
'            select ind_valor into v_ind_valor from ng_atributoitem where id = apex_application.g_f04(1);',
'',
'    bo_imp_minutanotafiscal_entrada_item_atributo.inclui_registro(',
'        p_id_tenant              => v_rec.id_tenant,',
'        p_id_item_minuta         => v_rec.id,',
'        p_id_atributoitem        => apex_application.g_f04(1),',
'        p_valor_atributo_dominio => case when v_ind_valor = ''L'' then apex_application.g_f06(1) else null end,',
'        p_valor_atributo_data    => case when v_ind_valor = ''D'' then apex_application.g_f09(1) else null end,',
'        p_valor_atributo_valor   => case when v_ind_valor = ''N'' then replace(apex_application.g_f10(1), separador_numerico, '''') else 0 end,',
'        p_valor_atributo_texto   => case when v_ind_valor = ''T'' then apex_application.g_f11(1) else null end,',
'        p_id                     => v_id,',
'        p_sucesso                => p_sucesso,',
'        p_messages               => p_messages',
'    );',
'',
'    end;',
'',
'end "UI_MPD_TD1033";',
'/'))
);
end;
