prompt --application/deployment/install/install_static_349
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(150331654755066681)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'STATIC_349'
,p_sequence=>350
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "STATIC_349" as',
'    procedure render(p_id in number);',
'end "STATIC_349";',
'/',
'',
'',
'create or replace package body "STATIC_349" as',
'',
'    procedure render(p_id in number) is',
'',
'        v_minuta    imp_minutanotafiscal_entrada%rowtype;',
'        v_transporte imp_minutanotafiscal_entrada_transporte%rowtype;',
'',
'        -- Emitente (importador)',
'        v_emit_razao       ng_pessoa_juridica.razao_social%type;',
'        v_emit_cnpj        ng_pessoa_juridica.inscricao_federal%type;',
'        v_emit_ie          ng_pessoa_juridica.inscricao_estadual%type;',
'        v_emit_endereco    ng_pessoa_endereco.etiqueta_endereco%type;',
'',
unistr('        -- Destinat\00E1rio'),
'        v_dest_razao       ng_pessoa_juridica.razao_social%type;',
'        v_dest_cnpj        ng_pessoa_juridica.inscricao_federal%type;',
'        v_dest_ie          ng_pessoa_juridica.inscricao_estadual%type;',
'        v_dest_endereco    ng_pessoa_endereco.etiqueta_endereco%type;',
'',
'        -- Transportador',
'        v_transp_razao     ng_pessoa_juridica.razao_social%type;',
'        v_acond_descricao  ng_acondicionamentocarga.descricao_acondicionamento_carga%type;',
'',
unistr('        -- Natureza opera\00E7\00E3o'),
'        v_natureza_nf      varchar2(200);',
'',
'    begin',
'',
'        -- Carrega minuta principal',
'        select * into v_minuta from imp_minutanotafiscal_entrada where id = p_id;',
'',
'        -- Emitente (importador)',
'        begin',
'            select pj.razao_social, pj.inscricao_federal, pj.inscricao_estadual,',
'                   pe.etiqueta_endereco',
'              into v_emit_razao, v_emit_cnpj, v_emit_ie, v_emit_endereco',
'              from ng_pessoa_juridica pj',
'              join ng_pessoa_endereco pe on pe.id_pessoa = pj.id_pessoa',
'             where pj.id_pessoa = v_minuta.id_importador',
'               and rownum = 1;',
'        exception when no_data_found then null;',
'        end;',
'',
unistr('        -- Destinat\00E1rio'),
'        begin',
'            select pj.razao_social, pj.inscricao_federal, pj.inscricao_estadual',
'              into v_dest_razao, v_dest_cnpj, v_dest_ie',
'              from ng_pessoa_juridica pj',
'             where pj.id_pessoa = v_minuta.id_destinatario;',
'        exception when no_data_found then null;',
'        end;',
'',
'        begin',
'            select etiqueta_endereco into v_dest_endereco',
'              from ng_pessoa_endereco',
'             where id = v_minuta.id_endereco_destino;',
'        exception when no_data_found then null;',
'        end;',
'',
'        -- Transporte',
'        begin',
'            select * into v_transporte',
'              from imp_minutanotafiscal_entrada_transporte',
'             where id_minuta = p_id and rownum = 1;',
'        exception when no_data_found then null;',
'        end;',
'',
'        if v_transporte.id_transportador is not null then',
'            begin',
'                select pj.razao_social into v_transp_razao',
'                  from ng_pessoa_juridica pj',
'                 where pj.id_pessoa = v_transporte.id_transportador;',
'            exception when no_data_found then null;',
'            end;',
'        end if;',
'',
'        if v_transporte.id_acondicionamento_carga is not null then',
'            begin',
'                select descricao_acondicionamento_carga into v_acond_descricao',
'                  from ng_acondicionamentocarga',
'                 where id = v_transporte.id_acondicionamento_carga;',
'            exception when no_data_found then null;',
'            end;',
'        end if;',
'',
unistr('        -- Natureza NF (dom\00EDnio)'),
'        v_natureza_nf := pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_natureza_notafiscal'', v_minuta.ind_natureza_notafiscal);',
'',
'        -- ======================================================',
'        -- CSS',
'        -- ======================================================',
'        htp.p(''<style>',
'            .mnf-doc { font-family: Arial, Helvetica, sans-serif; font-size: 10px; color: #000; width: 100%; box-sizing: border-box; }',
'            .mnf-doc *, .mnf-doc *::before, .mnf-doc *::after { box-sizing: border-box; }',
