prompt --application/deployment/install/install_ui_mpd_td1005
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(153343150192761184)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1005'
,p_sequence=>360
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD1005',
'-- Data: 20/04/2026',
unistr('-- Motivo: Ajustes de convers\00E3o de valores despesa numer\00E1rio'),
'-- Jira: PEDITEM-236',
'',
'-- Objeto: UI_MPD_TD1005',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Northonn Oliveira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD1005" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'    ',
'    function sql_atribuir_valor_moeda_nacional(p_param1 in varchar2) return clob;',
'',
'    function sql_atribuir_valor_realizado_moeda_nacional(p_param1 in varchar2) return clob;',
'',
'    function sql_buscar_taxa_1(p_param1 in varchar2) return clob;',
'',
'    function sql_buscar_taxa_2(p_param1 in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    ',
'end "UI_MPD_TD1005";',
'/',
'',
'create or replace package body "UI_MPD_TD1005" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => q''~',
'                select ',
'                    c.nome_fantasia as id_tenant,',
'                    b.num_processoimportacao, ',
'                    pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'',''ind_tipo_movimento'',d.ind_tipo_movimento) as ind_tipo_movimento',
'                from imp_processoimportacao_numerario_despesa a ',
'                join imp_processoimportacao_numerario d on d.id = a.id_numerario',
'                join imp_processoimportacao b on b.id = d.id_processoimportacao',
'                join mpd_tenant c on c.id = a.id_tenant',
'                where a.id = ~''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'        l_ind_tipo_movimento imp_processoimportacao_numerario.ind_tipo_movimento%type; ',
'        l_id_tenant number;',
'        l_id_moeda_nacional number;',
'        l_atribuir_valor_moeda_nacional clob;',
'        l_atribuir_valor_realizado_moeda_nacional clob;',
'        l_atribuir_taxa_1 clob;',
'        l_atribuir_taxa_2 clob;',
'        l_JSON_calcular_valor_moeda_nacional clob;',
'        l_JSON_calcular_valor_despesa clob;',
'        l_JSON_calcular_valor_realizado_moeda_nacional clob;',
'        l_JSON_calcular_valor_realizado clob;',
'        l_campos_calcular_valor_moeda_nacional varchar2(128) := ''VALOR_NUMERARIO_MOEDA_NACIONAL'';',
'        v_condicoes_taxa_1        array_varchar := array_varchar(''ID_MOEDA_DESPESA != %% && TAXA_CAMBIO_1 == %%'');',
'        v_colunas_alvo_taxa_1     array_varchar := array_varchar(''TAXA_CAMBIO_1'');',
'        v_comportamentos_taxa_1   array_varchar := array_varchar(''atr'');',
'        v_json_dependencia_taxa_1 clob;',
'        v_condicoes_taxa_2        array_varchar := array_varchar(''ID_MOEDA_DESPESA != %% && TAXA_CAMBIO_2 == %%'');',
'        v_colunas_alvo_taxa_2     array_varchar := array_varchar(''TAXA_CAMBIO_2'');',
'        v_comportamentos_taxa_2   array_varchar := array_varchar(''atr'');',
'        v_json_dependencia_taxa_2 clob;',
'    begin ',
'        select n.ind_tipo_movimento into l_ind_tipo_movimento from imp_processoimportacao_numerario_despesa nd join imp_processoimportacao_numerario n on n.id = nd.id_numerario where nd.id = p_param1;',
'        SELECT id_tenant INTO l_id_tenant FROM imp_processoimportacao_numerario_despesa WHERE id = p_param1;',
'        select max(id_registro) into l_id_moeda_nacional from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 13 and ind_tipo_dado = ''ID'';',
'        ',
'        l_JSON_calcular_valor_moeda_nacional := gerar_json_calcular_valor(',
'            '' VALOR_DESPESA_NUMERARIO * TAXA_CAMBIO_1'',',
'            l_campos_calcular_valor_moeda_nacional',
'        );',
'',
'        l_JSON_calcular_valor_despesa := gerar_json_calcular_valor(',
'            '' VALOR_NUMERARIO_MOEDA_NACIONAL / TAXA_CAMBIO_1'',',
'            ''VALOR_DESPESA_NUMERARIO''',
'        );',
'',
'        l_atribuir_taxa_1 := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_buscar_taxa_1'',',
'            apex_t_varchar2(''TAXA_CAMBIO_1'')',
'        );',
'',
'        l_atribuir_taxa_2 := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_buscar_taxa_2'',',
'            apex_t_varchar2(''TAXA_CAMBIO_2'')',
'        );',
'',
'        l_atribuir_valor_moeda_nacional := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_moeda_nacional'',',
'            apex_t_varchar2(''VALOR_NUMERARIO_MOEDA_NACIONAL'')',
'        );',
'',
'        v_json_dependencia_taxa_1 := gerar_json_dependencias_array(',
'            v_condicoes_taxa_1,',
'            v_colunas_alvo_taxa_1,',
'            v_comportamentos_taxa_1',
'        );',
'',
'        v_json_dependencia_taxa_2 := gerar_json_dependencias_array(',
'            v_condicoes_taxa_2,',
'            v_colunas_alvo_taxa_2,',
'            v_comportamentos_taxa_2',
'        );',
'',
'        l_JSON_calcular_valor_realizado_moeda_nacional := gerar_json_calcular_valor(',
'            '' VALOR_REALIZADO * TAXA_CAMBIO_2'',',
'            ''VALOR_REALIZADO_MOEDA_NACIONAL''',
'        );',
'',
'        l_JSON_calcular_valor_realizado := gerar_json_calcular_valor(',
'            '' VALOR_REALIZADO_MOEDA_NACIONAL / TAXA_CAMBIO_2'',',
'            ''VALOR_REALIZADO''',
'        );',
'',
'        l_atribuir_valor_realizado_moeda_nacional := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_realizado_moeda_nacional'',',
'            apex_t_varchar2(''VALOR_REALIZADO_MOEDA_NACIONAL'')',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from I'
||'MP_PROCESSOIMPORTACAO_NUMERARIO where id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js from dual union all',
'               SELECT p_codigo_artefato, ''id_despesa'',                          3, '''',null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js from dual union all',
'               SELECT p_codigo_artefato, ''ID_MOEDA_DESPESA'',                    5, '''',null, ''N'', ''S'', null valor, null dependencia, case when l_ind_tipo_movimento = 1 then l_atribuir_taxa_1  else l_atribuir_taxa_2 end atribuir_valor, null calcular_va'
||'lor, null executa_js from dual union all',
'               ',
unistr('               --se ind_tipo_movimento = 1 (Adiantamento de numer\00E1rio):'),
'               SELECT p_codigo_artefato, ''VALOR_DESPESA_NUMERARIO'',            11, case when l_ind_tipo_movimento = 1 then '''' else ''HID'' end, null, ''N'', ''S'', null, null, null, l_JSON_calcular_valor_moeda_nacional calcular_valor, null executa_js from '
||'dual union all',
'               SELECT p_codigo_artefato, ''VALOR_NUMERARIO_MOEDA_NACIONAL'',     13, case when l_ind_tipo_movimento = 1 then '''' else ''HID'' end, null, ''N'', ''S'', null, null, l_atribuir_valor_moeda_nacional, l_JSON_calcular_valor_despesa calcular_valor, n'
||'ull executa_js from dual union all',
'               ',
unistr('               --se ind_tipo_movimento = 2 (Comprova\00E7\00E3o das despesas):'),
'               SELECT p_codigo_artefato, ''VALOR_REALIZADO'',                     7, case when l_ind_tipo_movimento = 2 then '''' else ''HID'' end, null, ''N'', ''S'', null, null, null, l_JSON_calcular_valor_realizado_moeda_nacional calcular_valor, null execut'
||'a_js from dual union all',
'               SELECT p_codigo_artefato, ''VALOR_REALIZADO_MOEDA_NACIONAL'',      9, case when l_ind_tipo_movimento = 2 then '''' else ''HID'' end, null, ''N'', ''S'', null, null, l_atribuir_valor_realizado_moeda_nacional, l_JSON_calcular_valor_realizado calcu'
||'lar_valor, null executa_js from dual union all',
'               SELECT p_codigo_artefato, ''id_moeda_nacional'',                   8, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''S'', ''S'', to_char((l_id_moeda_nacional)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_'
||'js from dual union all',
'               ',
'               -- coluna TAXA_CAMBIO_1 para ind_tipo_movimento = 1',
'               SELECT p_codigo_artefato, ''TAXA_CAMBIO_1'',                      12, ''HID'',null, ''N'', ''N'', null valor, v_json_dependencia_taxa_1 dependencia, l_atribuir_taxa_1 atribuir_valor, null calcular_valor, null executa_js from dual union all',
'               -- coluna TAXA_CAMBIO_2 para ind_tipo_movimento = 2',
'               SELECT p_codigo_artefato, ''TAXA_CAMBIO_2'',                      12, ''HID'',null, ''N'', ''N'', null valor, v_json_dependencia_taxa_2 dependencia, l_atribuir_taxa_2 atribuir_valor, null calcular_valor, null executa_js from dual union all',
'               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',                     10, ''HID'',null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from IMP_PROCESSOIMPORTACAO_NUMERARIO_DESPESA where id = p_param1), ''DATA_SEGUNDO'') valor, null dependencia, '
||'null atribuir_valor, null calcular_valor, null executa_js from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,calcular_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.calcular_valor, new_data.executa_js);',
'    end formulario;',
'',
'    function sql_buscar_taxa_1(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'        l_id_despesa number;',
'        l_id_moeda number;',
'        l_id_moeda_nacional number;',
'    begin',
'        l_id_despesa := to_number(apex_util.get_session_state(''P9010_PARAMETRO''));',
'',
'        select to_number(c002) into l_id_moeda from apex_collections where collection_name = ''TD1005_'' || apex_custom_auth.get_session_id and c001 = ''ID_MOEDA_DESPESA'';',
'        -- ERRO 1:',
'        --select id_moeda_nacional into l_id_moeda_nacional from imp_processoimportacao_numerario_despesa where id = l_id_despesa;',
'        -- ',
'',
'        if l_id_moeda = l_id_moeda_nacional then',
'            l_sql := q''~select 1 as TAXA_CAMBIO_1 from dual~'';',
'        else',
'            l_sql := q''~',
'                select coalesce((',
'                    select cot.taxa_cambio from imp_processoimportacao_numerario_cotacao cot where cot.id_numerario = (',
'                        select id_numerario from imp_processoimportacao_numerario_despesa where id = ~'' || l_id_despesa || q''~',
'                    )',
'                    and cot.id_moeda = ~'' || l_id_moeda || q''~',
'                ), 0) TAXA_CAMBIO_1',
'                from dual~'';',
'        end if;',
'',
'        return l_sql;',
'    end sql_buscar_taxa_1;',
'',
'    function sql_buscar_taxa_2(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'        l_id_despesa number;',
'        l_id_moeda number;',
'        l_id_moeda_nacional number;',
'    begin',
'        l_id_despesa := to_number(apex_util.get_session_state(''P9010_PARAMETRO''));',
'',
'        select to_number(c002) into l_id_moeda from apex_collections where collection_name = ''TD1005_'' || apex_custom_auth.get_session_id and c001 = ''ID_MOEDA_DESPESA'';',
'        -- ERRO 2:',
'        --select id_moeda_nacional into l_id_moeda_nacional from imp_processoimportacao_numerario_despesa where id = l_id_despesa;',
'        --',
'',
'        if l_id_moeda = l_id_moeda_nacional then',
'            l_sql := ''select 1 as TAXA_CAMBIO_2 from dual'';',
'        else',
'            l_sql := q''~',
'                select coalesce((',
'                    select cot.taxa_cambio from imp_processoimportacao_numerario_cotacao cot where cot.id_numerario = (',
'                        select id_numerario from imp_processoimportacao_numerario_despesa where id = ~''||l_id_despesa|| q''~',
'                    )',
'                    and cot.id_moeda = ~'' ||l_id_moeda|| q''~',
'                ), 0) TAXA_CAMBIO_2',
'                from dual ~'';',
'        end if;',
'        return l_sql;',
'    end sql_buscar_taxa_2;',
'',
'    function sql_atribuir_valor_moeda_nacional(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin ',
'        l_sql := q''~',
'            select ',
'                (~'' || apex_application.g_f11(1) || q''~ * nvl(cot.taxa_cambio,0)) as VALOR_NUMERARIO_MOEDA_NACIONAL',
'            from dual',
'            left join imp_processoimportacao_numerario_cotacao cot',
'                on cot.id_numerario = (',
'                    select id_numerario from imp_processoimportacao_numerario_despesa where id = ~'' || p_param1 || q''~',
'                )',
'               and cot.id_moeda = to_number(',
'                    substr(''~'' || apex_application.g_f06(1) || q''~'',1,instr(''~'' || apex_application.g_f06(1) || q''~'','' -'')-1)',
'               )',
'        ~'';',
'        return l_sql;',
'    end sql_atribuir_valor_moeda_nacional;',
'',
'    function sql_atribuir_valor_realizado(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin ',
'        l_sql := q''~',
'            select ',
'                (',
'                    to_number(replace((',
'                        select c002 from apex_collections where collection_name = ''TD1005_'' || apex_custom_auth.get_session_id and upper(c001) = ''VALOR_REALIZADO_MOEDA_NACIONAL''',
'                    ), '','', ''.'')) ',
'                    / nullif((',
'                        select c002 from apex_collections where collection_name = ''TD1005_'' || apex_custom_auth.get_session_id and c001 = ''TAXA_CAMBIO_2''',
'                    ), 0)',
'                ) as VALOR_REALIZADO',
'            from dual',
'        ~'';',
'        return l_sql;',
'    end sql_atribuir_valor_realizado;',
'',
'    function sql_atribuir_valor_realizado_moeda_nacional(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin ',
'        l_sql := q''~',
'            select ',
'                (',
'                    to_number(replace((',
'                        select c002 from apex_collections where collection_name = ''TD1005_'' || apex_custom_auth.get_session_id and upper(c001) = ''VALOR_REALIZADO''',
'                    ), '','', ''.'')) ',
'                    * nvl((',
'                        select c002 from apex_collections where collection_name = ''TD1005_'' || apex_custom_auth.get_session_id and c001 = ''TAXA_CAMBIO_2''',
'                    ), 0)',
'                ) as VALOR_REALIZADO_MOEDA_NACIONAL',
'            from dual',
'        ~'';',
'        return l_sql;',
'    end sql_atribuir_valor_realizado_moeda_nacional;',
'    ',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_id number;',
'    begin',
'        -- ERRO 3:',
'            NULL;',
'            -- bo_imp_processoimportacao_numerario_despesa.altera_despesa_numerario(',
'            --     p_id                                => apex_util.get_session_state(''P9010_PARAMETRO''),',
'            --     p_id_despesa                        => apex_application.g_f03(1),',
'            --     p_id_moeda_despesa                  => apex_application.g_f05(1),',
'            --     p_id_moeda_nacional                 => apex_application.g_f08(1),',
'            --     p_valor_despesa_numerario           => pkg_util.retorna_number(apex_application.g_f11(1)),',
'            --     p_valor_numerario_moeda_nacional    => pkg_util.retorna_number(apex_application.g_f13(1)),',
'            --     p_valor_realizado                   => pkg_util.retorna_number(apex_application.g_f07(1)),',
'            --     p_valor_realizado_moeda_nacional    => pkg_util.retorna_number(apex_application.g_f09(1)),',
'            --     p_sucesso                           => p_sucesso,',
'            --     p_messages                          => p_messages',
'            -- );',
'        --',
'    end;',
'',
'end "UI_MPD_TD1005";',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_imp_processoimportacao_numerario_despesa
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(153343448575747223)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_IMP_PROCESSOIMPORTACAO_NUMERARIO_DESPESA'
,p_sequence=>370
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 24/06/2026',
unistr('-- Motivo: Inclus\00E3o da coluna id_numerario_despesa na entidade imp_pedidoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade imp_processoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 25/05/2026',
unistr('-- Motivo: Ajustes nas chamadas do bo_imp_processoimportacao_despesa devido adi\00E7\00E3o de novas colunas'),
'-- Jira: PEDITEM-162',
'',
'-- Objeto: BO_IMP_PROCESSOIMPORTACAO_NUMERARIO_DESPESA',
'-- Data: 20/04/2026',
'-- Motivo: Ajuste na procedure altera_despesa_numerario',
'-- Jira: PEDITEM-236',
'',
'create or replace package            bo_imp_processoimportacao_numerario_despesa ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old imp_processoimportacao_numerario_despesa%rowtype;',
'    v_new imp_processoimportacao_numerario_despesa%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao imp_processoimportacao_numerario_despesa.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_processoimportacao_numerario_despesa.id%type',
'    );',
'    procedure grava(',
'        p_id in imp_processoimportacao_numerario_despesa.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(  ',
'        p_ind_status in imp_processoimportacao_numerario_despesa.ind_status%type,',
'        p_id_tenant in imp_processoimportacao_numerario_despesa.id_tenant%type,',
'        p_id_numerario in imp_processoimportacao_numerario_despesa.id_numerario%type,',
'        p_id_despesa in imp_processoimportacao_numerario_despesa.id_despesa%type,',
'        p_id_moeda_despesa in imp_processoimportacao_numerario_despesa.id_moeda_despesa%type,',
'        p_valor_moeda_da_despesa in imp_processoimportacao_numerario_despesa.valor_moeda_da_despesa%type,',
'        p_valor_despesa_moeda_numerario in imp_processoimportacao_numerario_despesa.valor_despesa_moeda_numerario%type,',
'        p_num_documento in imp_processoimportacao_numerario_despesa.num_documento%type,',
'        p_serie_nf in imp_processoimportacao_numerario_despesa.serie_nf%type,',
'        p_data_nf in imp_processoimportacao_numerario_despesa.data_nf%type,',
'        p_id_comprovacao_despesa in imp_processoimportacao_numerario_despesa.id_comprovacao_despesa%type, ',
'        p_id out imp_processoimportacao_numerario_despesa.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );   ',
'    procedure altera_registro(  ',
'        p_ind_status in imp_processoimportacao_numerario_despesa.ind_status%type,',
'        p_id_tenant in imp_processoimportacao_numerario_despesa.id_tenant%type,',
'        p_id_numerario in imp_processoimportacao_numerario_despesa.id_numerario%type,',
