'        p_id in imp_processoimportacao_numerario_despesa.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_processoimportacao_numerario_despesa'', p_id) then ',
