'                bo_ng_pessoa.retorna_pessoa(b.id_fornecedor) as imp_processoimportacao_numerario$id_fornecedor,',
'                pkg_traducao.get_traducao(d.descricao_despesa) as imp_processoimportacao_numerario_despesa$id_despesa,',
'                e.codigo_moeda||'''' - ''''||e.simbolo_iso as imp_processoimportacao_numerario_despesa$id_moeda_despesa,',
'                to_char(a.valor_moeda_da_despesa, ''''FM999G999G990D00'''') as imp_processoimportacao_numerario_despesa$valor_moeda_da_despesa,',
'                to_char(a.valor_despesa_moeda_numerario, ''''FM999G999G990D00'''') as imp_processoimportacao_numerario_despesa$valor_despesa_moeda_numerario',
'            from imp_processoimportacao_numerario_despesa a',
'            left join imp_processoimportacao_despesa c on c.id = a.id_despesa',
'            left join imp_processoimportacao_numerario b on b.id = a.id_numerario',
'            left join ng_despesa d on d.id = c.id_despesa',
'            join ng_moeda e on e.id = a.id_moeda_despesa',
'            left join imp_processoimportacao f on f.id = c.id_processoimportacao',
'            where a.id = ''||p_id);',
'    end detalhe_registro;',
'',
'    procedure vincula_despesas_ao_numerario(',
'        p_ids_despesas_selecionadas in varchar2,',
'        p_id_numerario              in number,',
'        p_pagina                    in number default 0,',
'        p_encadeado                 in boolean default false,',
'        p_sucesso                   out clob,',
'        p_messages                  out pkg_mensagem.message_record_table',
'    ) is',
'        l_ids             apex_t_varchar2;',
'        l_id              number;',
'        l_count           number;',
'        l_sucesso_local   clob;',
'        l_messages_local  pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'        l_total_reais     number := 0;',
'    begin',
'        p_messages := pkg_mensagem.message_record_table();',
'',
unistr('        -- remove TODAS as despesas do numer\00E1rio'),
'        for r in (',
'            select id from imp_processoimportacao_numerario_despesa where id_numerario = p_id_numerario',
'        ) loop',
'            l_messages_local.delete;',
'',
'            bo_imp_processoimportacao_numerario_despesa.exclui_registro(',
'                p_id        => r.id,',
'                p_encadeado => true,',
'                p_sucesso   => l_sucesso_local,',
'                p_messages  => l_messages_local',
'            );',
'',
'            if l_messages_local.count > 0 then',
'                for i in 1 .. l_messages_local.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(i);',
'                end loop;',
'            end if;',
'        end loop;',
'',
'        l_ids := apex_string.split(p_ids_despesas_selecionadas, '','');',
'',
'        -- inclui despesas no numerario',
'        for i in 1 .. l_ids.count loop',
'            l_id := to_number(l_ids(i)); -- id_despesa',
'',
'            declare',
'                l_novo_id imp_processoimportacao_numerario_despesa.id%type;',
'                l_rec     imp_processoimportacao_despesa%rowtype;',
'                l_taxa_cambio     number;',
'                l_valor_reais     number;',
'                l_valor_numerario number;',
'            begin',
'                -- carrega dados da despesa',
'                select * into l_rec from imp_processoimportacao_despesa where id = l_id;',
'',
'                -- busca taxa conforme moeda da despesa',
'                select max(c.taxa_cambio) into l_taxa_cambio from imp_processoimportacao_numerario_cotacao c where c.id_tenant = l_rec.id_tenant and c.id_numerario = p_id_numerario and c.id_moeda = l_rec.id_moeda_prevista;',
'',
'                if l_taxa_cambio is null or l_taxa_cambio = 0 then',
'                    l_messages_local.extend;',
'                    pkg_mensagem.mensagem_campo(',
'                        p_codigo_mensagem => ''139'',',
'                        p_nome_campo      => ''taxa_cambio'',',
'                        p_parametro       => v_parametro,',
'                        p_pagina          => p_pagina,',
'                        p_objeto_mensagem => l_messages_local(l_messages_local.last)',
'                    );',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(l_messages_local.last);',
'                    pkg_mensagem.exibe_mensagem(p_messages);',
'                    return;',
'                end if;',
'',
'                l_valor_reais     := l_rec.valor_previsto;',
'                l_valor_numerario := l_valor_reais / l_taxa_cambio;',
'',
'                l_total_reais := l_total_reais + l_valor_reais;',
'',
'                bo_imp_processoimportacao_numerario_despesa.inclui_registro(',
'                    p_id_tenant                         => l_rec.id_tenant,',
'                    p_id_numerario                      => p_id_numerario,',
'                    p_id_despesa                        => l_rec.id,',
'                    p_id_moeda_despesa                  => l_rec.id_moeda_prevista,',
'                    p_id_comprovacao_despesa          => null,',
'                    p_valor_moeda_da_despesa           => l_valor_numerario,',
'                    p_ind_status                 => l_rec.id_moeda_documento,',
'                    p_valor_despesa_moeda_numerario    => l_valor_reais,',
'                    p_num_documento                     => null,',
'                    p_serie_nf                          => null,',
'                    p_data_nf                           => null,',
'                    p_id                                => l_novo_id,',
'                    p_pagina                            => p_pagina,',
'                    p_encadeado                         => p_encadeado,',
'                    p_sucesso                           => l_sucesso_local,',
'                    p_messages                          => l_messages_local',
'                );',
'',
'                if l_messages_local.count > 0 then',
'                    for j in 1 .. l_messages_local.count loop',
'                        p_messages.extend;',
'                        p_messages(p_messages.last) := l_messages_local(j);',
'                    end loop;',
'                end if;',
'            end;',
'        end loop;',
'',
'        -- Alterar valor_total_despesas_reais de imp_processoimportacao_numerario',
'        declare',
'            l_num           imp_processoimportacao_numerario%rowtype;',
'            l_sucesso_alt   clob;',
'            l_messages_alt  pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'        begin',
'            select * into l_num from imp_processoimportacao_numerario where id = p_id_numerario;',
'',
'            -- Total calculado',
'            l_num.valor_total_despesas_numerario := l_total_reais;',
'',
'            bo_imp_processoimportacao_numerario.altera_registro(',
'                p_id_tenant                         => l_num.id_tenant,',
'                p_id_processoimportacao             => l_num.id_processoimportacao,',
'                p_id_titulo_pagamento               => l_num.id_titulo_pagamento,',
'                p_ind_status                        => l_num.ind_status,',
'                p_ind_tipo_movimento                => l_num.ind_tipo_movimento,',
'                p_id_fornecedor                     => l_num.id_fornecedor,',
'                p_id_conta_bancaria                 => l_num.id_conta_bancaria,',
'                p_referencia_fornecedor               => l_num.referencia_fornecedor,',
'                p_data_documento                    => l_num.data_documento,',
'                p_data_vencimento           => l_num.data_vencimento,',
'                p_id_moeda_numerario                 => l_num.id_moeda_numerario,',
'                p_valor_numerario_informado    => l_num.valor_numerario_informado,',
'                p_valor_total_despesas_numerario              => l_total_reais,',
'                p_observacao                        => l_num.observacao,',
'                p_id                                => l_num.id,',
'                p_data_alteracao                    => l_num.data_alteracao,',
'                p_pagina                            => p_pagina,',
'                p_encadeado                         => p_encadeado,',
'                p_sucesso                           => l_sucesso_alt,',
'                p_messages                          => l_messages_alt',
'            );',
'',
'            if l_messages_alt.count > 0 then',
'                for i in 1 .. l_messages_alt.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_alt(i);',
'                end loop;',
'            end if;',
'        end;',
'    end vincula_despesas_ao_numerario;',
'',
'    procedure atualizar_despesas_json (',
'        p_json      in clob,',
'        p_pagina    in number default null,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        l_count        number;',
'        l_id           number;',
'        l_valor_reais  number;',
'        l_valor_calc   number;',
'        l_reg          imp_processoimportacao_numerario_despesa%rowtype;',
'        l_sucesso_aux  clob;',
'        l_messages_aux pkg_mensagem.message_record_table;',
'    begin',
'        p_sucesso  := null;',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        -- Parse do JSON',
'        apex_json.parse(p_json);',
'        l_count := apex_json.get_count(p_path => ''.'');',
'',
'        -- if l_count = 0 then',
'        --     raise_application_error(-20002, ''Nenhuma despesa encontrada para processamento.'');',
'        -- end if;',
'',
'        -- Loop nas despesas',
'        for i in 1 .. l_count loop',
'            l_id := apex_json.get_number(p_path => ''[''||i||''].id'');',
'            l_valor_reais := apex_json.get_number(p_path => ''[''||i||''].valor_reais'');',
'',
'            if l_id is null then',
unistr('                raise_application_error(-20003, ''ID da despesa n\00E3o informado no JSON.'');'),
'            end if;',
'',
'            -- Busca registro atual',
'            select * into l_reg from imp_processoimportacao_numerario_despesa where id = l_id;',
'',
unistr('            -- Valida\00E7\00E3o da taxa'),
'            -- * VERIFICAR REGRA DE ACORDO COM NOVAS COLUNAS',
'            -- if l_reg.taxa_cambio_numerario is null or l_reg.taxa_cambio_numerario = 0 then',
unistr('            --     raise_application_error(-20004, ''Taxa de c\00E2mbio inv\00E1lida para a despesa ID '' || l_id);'),
'            -- end if;',
'',
unistr('            -- C\00E1lculo'),
'            l_valor_calc := l_valor_reais; --/ l_reg.taxa_cambio_numerario;',
'',
unistr('            -- Chamada da regra de altera\00E7\00E3o'),
'            altera_registro(',
'                p_id_tenant                     => l_reg.id_tenant,',
'                p_id_numerario                  => l_reg.id_numerario,',
'                p_id_despesa                    => l_reg.id_despesa,',
'                p_id_moeda_despesa              => l_reg.id_moeda_despesa,',
'                p_id_comprovacao_despesa      => l_reg.id_comprovacao_despesa,',
'                p_valor_moeda_da_despesa       => l_valor_calc,',
'                p_ind_status             => l_reg.ind_status,',
'                p_valor_despesa_moeda_numerario => l_valor_reais,',
'                p_num_documento                 => l_reg.num_documento,',
'                p_serie_nf                      => l_reg.serie_nf,',
'                p_data_nf                       => l_reg.data_nf,',
'                p_id                            => l_reg.id,',
'                p_data_alteracao                => l_reg.data_alteracao,',
'                p_pagina                        => p_pagina,',
'                p_encadeado                     => true,',
'                p_sucesso                       => l_sucesso_aux,',
'                p_messages                      => l_messages_aux',
'            );',
'        end loop;',
'',
'    exception',
unistr('        when no_data_found then raise_application_error(-20005, ''Despesa n\00E3o encontrada para o ID informado.'');'),
'        when others then',
'    raise;',
'    end atualizar_despesas_json;',
'',
'',
'    procedure altera_despesa_numerario(',
'        p_id                                in imp_processoimportacao_numerario_despesa.id%type,',
'        p_id_despesa                        in imp_processoimportacao_numerario_despesa.id_despesa%type,',
'        p_id_moeda_despesa                  in imp_processoimportacao_numerario_despesa.id_moeda_despesa%type,',
'        p_ind_status                 in imp_processoimportacao_numerario_despesa.ind_status%type,',
'        p_valor_moeda_da_despesa           in imp_processoimportacao_numerario_despesa.valor_moeda_da_despesa%type,',
'        p_valor_despesa_moeda_numerario    in imp_processoimportacao_numerario_despesa.valor_despesa_moeda_numerario%type,',
'        p_pagina                            in number default null,',
'        p_sucesso                           out clob,',
'        p_messages                          out pkg_mensagem.message_record_table',
'    ) is',
'        l_reg_nd                    imp_processoimportacao_numerario_despesa%rowtype;',
'        l_reg_desp                  imp_processoimportacao_despesa%rowtype;',
'        l_reg_num                   imp_processoimportacao_numerario%rowtype;',
'        l_total_despesas_reais      number := 0;',
'        l_sucesso_aux               clob;',
'        l_valor_utilizado           number;',
'        l_valor_utilizado_reais     number;',
'        l_taxa                      number;',
'        l_messages_local            pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select * into l_reg_nd from imp_processoimportacao_numerario_despesa where id = p_id for update;',
'        select * into l_reg_num from imp_processoimportacao_numerario where id = l_reg_nd.id_numerario for update;',
'',
'        if p_id_moeda_despesa != p_ind_status then',
'            begin',
'                select c.taxa_cambio into l_taxa from imp_processoimportacao_numerario_cotacao c where c.id_numerario = l_reg_nd.id_numerario and c.id_moeda = p_id_moeda_despesa and rownum = 1;',
'            exception',
'                when no_data_found then',
'                    l_taxa := null;',
'            end;',
'',
'            if l_taxa is null or l_taxa = 0 then',
'                if p_messages is null then',
'                    p_messages := pkg_mensagem.message_record_table();',
'                end if;',
'                l_messages_local.extend;',
'',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''139'',',
'                    p_nome_campo      => ''ID_MOEDA_DESPESA'',',
'                    p_parametro       => v_parametro,',
'                    p_pagina          => p_pagina,',
'                    p_objeto_mensagem => l_messages_local(l_messages_local.last)',
'                );',
'',
'                p_messages.extend;',
'                p_messages(p_messages.last) := l_messages_local(l_messages_local.last);',
'                pkg_mensagem.exibe_mensagem(p_messages);',
'                return;',
'            end if;',
'        end if;',
'',
'',
'',
'        -- * VERIFICAR REGRAS DE ACORDO COM NOVAS COLUNAS',
'        -- if l_reg_num.ind_tipo_movimento = 2 then',
'        --     l_valor_utilizado        := p_valor_realizado;',
'        --     l_valor_utilizado_reais  := p_valor_realizado_moeda_nacional;',
'        -- elsif l_reg_num.ind_tipo_movimento = 1 then',
'        --     l_valor_utilizado        := p_valor_moeda_da_despesa;',
'        --     l_valor_utilizado_reais  := p_valor_despesa_moeda_numerario;',
'        -- end if;',
'',
'        -- ATUALIZA NUMERARIO_DESPESA',
'        bo_imp_processoimportacao_numerario_despesa.altera_registro(',
'            p_id_tenant                         => l_reg_nd.id_tenant,',
'            p_id_numerario                      => l_reg_nd.id_numerario,',
'            p_id_despesa                        => p_id_despesa,',
'            p_id_moeda_despesa                  => p_id_moeda_despesa,',
'            p_id_comprovacao_despesa          => l_reg_nd.id_comprovacao_despesa,',
'            p_valor_moeda_da_despesa           =>',
'                                                    case when l_reg_num.ind_tipo_movimento = 1',
'                                                         then p_valor_moeda_da_despesa',
'                                                         else l_reg_nd.valor_moeda_da_despesa',
'                                                    end,',
'            p_ind_status                 => l_reg_nd.ind_status,',
'            p_valor_despesa_moeda_numerario    =>',
'                                                    case when l_reg_num.ind_tipo_movimento = 1',
'                                                         then p_valor_despesa_moeda_numerario',
'                                                         else l_reg_nd.valor_despesa_moeda_numerario',
'                                                    end,',
'            p_num_documento                     => l_reg_nd.num_documento,',
'            p_serie_nf                          => l_reg_nd.serie_nf,',
'            p_data_nf                           => l_reg_nd.data_nf,',
'            p_id                                => l_reg_nd.id,',
'            p_data_alteracao                    => l_reg_nd.data_alteracao,',
'            p_pagina                            => p_pagina,',
'            p_sucesso                           => l_sucesso_aux,',
'            p_messages                          => p_messages',
'        );',
'',
'        -- ATUALIZA PROCESSOIMPORTACAO_DESPESA',
'        select * into l_reg_desp from imp_processoimportacao_despesa where id = l_reg_nd.id_despesa for update;',
'        bo_imp_processoimportacao_despesa.altera_registro(',
'            p_id_tenant                 => l_reg_desp.id_tenant,',
'            p_id_documento_despesa      => l_reg_desp.id_documento_despesa,',
'            p_id_processoimportacao     => l_reg_desp.id_processoimportacao,',
'            p_id_numerario_despesa      => l_reg_desp.id_numerario_despesa, --?',
'            p_id_despesa                => l_reg_desp.id_despesa,',
'            p_id_moeda_prevista         => l_reg_desp.id_moeda_prevista,',
'            p_valor_previsto            => l_reg_desp.valor_previsto,',
'            p_id_moeda_realizada        => l_reg_desp.id_moeda_realizada,',
'            p_valor_realizado           => l_valor_utilizado,            ',
'            p_taxa_cambio               => l_reg_desp.taxa_cambio,',
'            p_ind_status_despesa        => l_reg_desp.ind_status_despesa,',
'            p_ind_status_pagamento      => l_reg_desp.ind_status_pagamento,',
'            p_id_moeda_documento        => l_reg_desp.id_moeda_documento,',
'            p_valor_moeda_documento     => l_valor_utilizado_reais,',
'            p_valor_moeda_nacional      => l_valor_utilizado_reais,',
'            p_ind_forma_rateio          => null,',
'            p_ind_compoe_custo_operacao => null,',
'            p_ind_participa_nfe         => null,',
'            p_ind_despesa_base_calculo  => null,',
'            p_ind_tipo_despesa          => null,',
'            p_id                        => l_reg_desp.id,',
'            p_data_alteracao            => l_reg_desp.data_alteracao,',
'            p_pagina                    => p_pagina,',
'            p_sucesso                   => l_sucesso_aux,',
'            p_messages                  => p_messages',
'        );',
'',
unistr('        -- RECALCULA TOTAL DO NUMER\00C1RIO         * VERIFICAR REGRAS DE ACORDO COM NOVAS COLUNAS'),
'        -- if l_reg_num.ind_tipo_movimento = 2 then',
'        --     select nvl(sum(valor_realizado_moeda_nacional),0) into l_total_despesas_reais from imp_processoimportacao_numerario_despesa where id_numerario = l_reg_nd.id_numerario;',
'        -- elsif l_reg_num.ind_tipo_movimento = 1 then',
'        --     select nvl(sum(valor_despesa_moeda_numerario),0) into l_total_despesas_reais from imp_processoimportacao_numerario_despesa where id_numerario = l_reg_nd.id_numerario;',
'        -- end if;',
'',
'        -- ATUALIZA NUMERARIO',
'        select * into l_reg_num from imp_processoimportacao_numerario where id = l_reg_nd.id_numerario for update;',
'        bo_imp_processoimportacao_numerario.altera_registro(',
'            p_id_tenant                         => l_reg_num.id_tenant,',
'            p_id_processoimportacao             => l_reg_num.id_processoimportacao,',
'            p_id_titulo_pagamento               => l_reg_num.id_titulo_pagamento,',
'            p_ind_status                        => l_reg_num.ind_status,',
'            p_ind_tipo_movimento                => l_reg_num.ind_tipo_movimento,',
'            p_id_fornecedor                     => l_reg_num.id_fornecedor,',
'            p_id_conta_bancaria                 => l_reg_num.id_conta_bancaria,',
'            p_referencia_fornecedor               => l_reg_num.referencia_fornecedor,',
'            p_data_documento                    => l_reg_num.data_documento,',
'            p_data_vencimento           => l_reg_num.data_vencimento,',
'            p_id_moeda_numerario                 => l_reg_num.id_moeda_numerario,',
'            p_valor_numerario_informado    => l_reg_num.valor_numerario_informado,',
'            p_valor_total_despesas_numerario              => l_total_despesas_reais,',
'            p_observacao                        => l_reg_num.observacao,',
'            p_id                                => l_reg_num.id,',
'            p_data_alteracao                    => l_reg_num.data_alteracao,',
'            p_pagina                            => p_pagina,',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );',
'',
'    exception',
'        when others then',
'            apex_debug.error(''BO_NUMERARIO.ERRO | ID=%s ERRO=%s'', p_id, sqlerrm);',
'            raise;',
'    end altera_despesa_numerario;',
'    --',
'    procedure gerar_comprovacao_despesas_json (',
'        p_id_numerario_comprovacao  in number,',
'        p_json                      in clob,',
'        p_pagina                    in number,',
'        p_sucesso                   out clob,',
'        p_messages                  out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant number;',
'        type t_despesa is record (',
'            id_despesa                      number,',
'            id_moeda_despesa                number,',
'            taxa_cambio_numerario           number,',
'            valor_numerario                 number,',
'            valor_reais                     number,',
'            id_antecipacao                  number,',
'            ind_status               number',
'        );',
'        type t_tab_despesa is table of t_despesa index by pls_integer;',
'        l_tab t_tab_despesa;',
'        l_index number := 0;',
'        l_novo_id number;',
'        l_messages_local pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'        type t_ids is table of number index by pls_integer;',
'        l_ids_antecipacao t_ids;',
'        l_idx number := 0;',
'        l_num_row imp_processoimportacao_numerario%rowtype;',
'    begin',
'        p_messages := pkg_mensagem.message_record_table();',
'        select id_tenant into l_id_tenant from imp_processoimportacao_numerario where id = p_id_numerario_comprovacao;',
'',
unistr('        -- Carregar JSON em mem\00F3ria'),
'        for r in (',
'            select jt.id, jt.valor_numerario, jt.valor_reais',
'            from json_table(',
'                    p_json,',
'                    ''$[*]''',
'                    columns (',
'                        id              number path ''$.id'',',
'                        valor_numerario number path ''$.valor_numerario'',',
'                        valor_reais     number path ''$.valor_reais''',
'                    )',
'            ) jt',
'        ) loop',
'            l_index := l_index + 1;',
'            declare',
'                l_taxa number;',
'            begin',
'                select a.id_despesa, a.id_moeda_despesa, case when n.ind_tipo_movimento = 1 then n.id else a.id_comprovacao_despesa end, a.ind_status into l_tab(l_index).id_despesa, l_tab(l_index).id_moeda_despesa, l_tab(l_index).id_antecipacao, l_ta'
||'b(l_index).ind_status from imp_processoimportacao_numerario_despesa a join imp_processoimportacao_numerario n on n.id = a.id_numerario where a.id = r.id;',
'',
'                l_tab(l_index).valor_numerario := r.valor_numerario;',
'                l_tab(l_index).valor_reais     := r.valor_reais;',
'',
unistr('                -- taxa de c\00E2mbio'),
'                begin',
'                    select c.taxa_cambio into l_taxa from imp_processoimportacao_numerario_cotacao c where c.id_numerario = p_id_numerario_comprovacao and c.id_moeda = l_tab(l_index).id_moeda_despesa and rownum = 1;',
'                exception',
'                    when no_data_found then',
'                        l_taxa := null;',
'                end;',
'',
'                if l_taxa is null or l_taxa = 0 then',
'                    l_messages_local.extend;',
'                    pkg_mensagem.mensagem_campo(',
'                        p_codigo_mensagem => ''139'',',
'                        p_nome_campo      => ''taxa_cambio'',',
'                        p_parametro       => v_parametro,',
'                        p_pagina          => p_pagina,',
'                        p_objeto_mensagem => l_messages_local(l_messages_local.last)',
'                    );',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(l_messages_local.last);',
'                    pkg_mensagem.exibe_mensagem(p_messages);',
'                    return;',
'                end if;',
'',
'                l_tab(l_index).taxa_cambio_numerario := l_taxa;',
'',
'            exception',
'                when no_data_found then',
unistr('                    raise_application_error(-20012, ''Despesa do JSON n\00E3o encontrada.'');'),
'            end;',
'        end loop;',
'',
'        if l_tab.count = 0 then',
'            raise_application_error(-20010, ''Nenhuma despesa enviada.'');',
'        end if;',
'',
unistr('        -- Coletar antecipa\00E7\00F5es envolvidas'),
'        for i in 1 .. l_tab.count loop',
'            if l_tab(i).id_antecipacao is not null then',
'                l_idx := l_idx + 1;',
'                l_ids_antecipacao(l_idx) := l_tab(i).id_antecipacao;',
'            end if;',
'        end loop;',
'',
'        -- Apagar despesas antigas',
'        delete from imp_processoimportacao_numerario_despesa where id_numerario = p_id_numerario_comprovacao;',
'',
'        -- Inserir novas despesas',
'        for i in 1 .. l_tab.count loop',
'            bo_imp_processoimportacao_numerario_despesa.inclui_registro(',
'                p_id_tenant                     => l_id_tenant,',
'                p_id_numerario                  => p_id_numerario_comprovacao,',
'                p_id_despesa                    => l_tab(i).id_despesa,',
'                p_id_moeda_despesa              => l_tab(i).id_moeda_despesa,',
'                p_id_comprovacao_despesa      => l_tab(i).id_antecipacao,',
'                p_valor_moeda_da_despesa       => l_tab(i).valor_numerario,',
'                p_ind_status             => l_tab(i).ind_status,',
'                p_valor_despesa_moeda_numerario=> l_tab(i).valor_reais,',
'                p_num_documento                 => null,',
'                p_serie_nf                      => null,',
'                p_data_nf                       => null,',
'                p_id                            => l_novo_id,',
'                p_pagina                        => p_pagina,',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'            );',
'        end loop;',
'',
unistr('        -- Recalcular valor das antecipa\00E7\00F5es'),
'        for r in (',
'            select distinct id_comprovacao_despesa from imp_processoimportacao_numerario_despesa where id_numerario = p_id_numerario_comprovacao and id_comprovacao_despesa is not null',
'        ) loop',
'',
'            declare',
'                l_total number;',
'            begin',
'                --select nvl(sum(valor_realizado_moeda_nacional),0) into l_total from imp_processoimportacao_numerario_despesa where id_comprovacao_despesa = r.id_comprovacao_despesa;',
'                select * into l_num_row from imp_processoimportacao_numerario where id = r.id_comprovacao_despesa;',
'',
'                bo_imp_processoimportacao_numerario.altera_registro(',
'                    p_id_tenant                  => l_num_row.id_tenant,',
'                    p_id_processoimportacao      => l_num_row.id_processoimportacao,',
'                    p_id_titulo_pagamento        => null,',
'                    p_ind_status                 => l_num_row.ind_status,',
'                    p_ind_tipo_movimento         => l_num_row.ind_tipo_movimento,',
'                    p_id_fornecedor              => l_num_row.id_fornecedor,',
'                    p_id_conta_bancaria          => l_num_row.id_conta_bancaria,',
'                    p_referencia_fornecedor        => l_num_row.referencia_fornecedor,',
'                    p_data_documento             => l_num_row.data_documento,',
'                    p_data_vencimento    => l_num_row.data_vencimento,',
'                    p_id_moeda_numerario          => l_num_row.id_moeda_numerario,',
'                    p_valor_numerario_informado => l_num_row.valor_numerario_informado,',
'                    p_valor_total_despesas_numerario       => l_total,',
'                    p_observacao                 => l_num_row.observacao,',
'                    p_data_alteracao        '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(153343448575747223)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'     => l_num_row.data_alteracao,',
'                    p_id                         => l_num_row.id,',
'                    p_sucesso                    => p_sucesso,',
'                    p_messages                   => p_messages',
'                );',
'            end;',
'        end loop;',
'    end gerar_comprovacao_despesas_json;',
'',
'',
'    procedure confirma_comprovacao_despesas(',
'        p_id_numerario  in imp_processoimportacao_numerario.id%type,',
'        p_ind_status    in imp_processoimportacao_numerario.ind_status%type,',
'        p_sucesso       out clob,',
'        p_messages      out pkg_mensagem.message_record_table',
'    ) is',
'        l_valor_total_despesas number;',
'        l_num_row imp_processoimportacao_numerario%rowtype;',
'    begin',
'        select * into l_num_row from imp_processoimportacao_numerario where id = p_id_numerario;',
'',
unistr('        -- Atualizar despesas do numer\00E1rio e dos adiantamentos'),
'        for rec in (',
'            select * from imp_processoimportacao_numerario_despesa where id_numerario = p_id_numerario or id_comprovacao_despesa = p_id_numerario',
'        )',
'        loop',
'            bo_imp_processoimportacao_numerario_despesa.altera_registro(',
'                p_id_tenant                     => rec.id_tenant,',
'                p_id_numerario                  => rec.id_numerario,',
'                p_id_despesa                    => rec.id_despesa,',
'                p_id_moeda_despesa              => rec.id_moeda_despesa,',
'                p_id_comprovacao_despesa      => rec.id_comprovacao_despesa,',
'                p_valor_moeda_da_despesa       => rec.valor_moeda_da_despesa,',
'                p_ind_status             => rec.ind_status,',
'                p_valor_despesa_moeda_numerario => rec.valor_despesa_moeda_numerario,',
'                p_num_documento                 => rec.num_documento,',
'                p_serie_nf                      => rec.serie_nf,',
'                p_data_nf                       => rec.data_nf,',
'                p_id                            => rec.id,',
'                p_data_alteracao                => rec.data_alteracao,',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'            );',
'        end loop;',
'',
unistr('        -- Somar o total das despesas comprovadas do numer\00E1rio principal'),
'        --select nvl(sum(valor_realizado_moeda_nacional),0) into l_valor_total_despesas from imp_processoimportacao_numerario_despesa where id_numerario = p_id_numerario;',
'',
unistr('        -- Atualizar o numer\00E1rio principal'),
'        bo_imp_processoimportacao_numerario.altera_registro(',
'            p_id_tenant                  => l_num_row.id_tenant,',
'            p_id_processoimportacao      => l_num_row.id_processoimportacao,',
'            p_id_titulo_pagamento        => null,',
'            p_ind_status                 => p_ind_status,',
'            p_ind_tipo_movimento         => l_num_row.ind_tipo_movimento,',
'            p_id_fornecedor              => l_num_row.id_fornecedor,',
'            p_id_conta_bancaria          => l_num_row.id_conta_bancaria,',
'            p_referencia_fornecedor        => l_num_row.referencia_fornecedor,',
'            p_data_documento             => l_num_row.data_documento,',
'            p_data_vencimento    => l_num_row.data_vencimento,',
'            p_id_moeda_numerario                 => l_num_row.id_moeda_numerario,',
'            p_valor_numerario_informado    => l_num_row.valor_numerario_informado,',
'            p_valor_total_despesas_numerario              => l_valor_total_despesas,',
'            p_observacao                 => l_num_row.observacao,',
'            p_data_alteracao             => l_num_row.data_alteracao,',
'            p_id                         => p_id_numerario,',
'            p_sucesso                    => p_sucesso,',
'            p_messages                   => p_messages',
'        );',
'    end confirma_comprovacao_despesas;',
'',
'    procedure inclui_novas_despesas_ao_numerario(',
'        p_ids_despesas_selecionadas in varchar2,',
'        p_id_numerario              in number,',
'        p_sucesso                   out clob,',
'        p_messages                  out pkg_mensagem.message_record_table',
'    ) is',
'        l_sucesso_local   clob;',
'        l_messages_local  pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'        l_total_reais     number := 0;',
'    begin',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        for r in (',
'                select d.* from imp_processoimportacao_despesa d where d.id in (select to_number(column_value) from table(apex_string.split(p_ids_despesas_selecionadas, '',''))',
'            )',
'            and not exists (',
'                select 1 from imp_processoimportacao_numerario_despesa nd where nd.id_numerario = p_id_numerario and nd.id_despesa = d.id',
'            )',
'        ) loop',
'            l_messages_local.delete;',
'',
'            declare',
'                l_novo_id        imp_processoimportacao_numerario_despesa.id%type;',
'                l_taxa_cambio    number;',
'                l_valor_reais    number;',
'                l_valor_numerario number;',
'            begin',
'',
unistr('                -- Busca taxa de c\00E2mbio da moeda da despesa'),
'                select max(c.taxa_cambio) into l_taxa_cambio from imp_processoimportacao_numerario_cotacao c where c.id_tenant = r.id_tenant and c.id_numerario = p_id_numerario and c.id_moeda = r.id_moeda_prevista;',
'',
'                if l_taxa_cambio is null or l_taxa_cambio = 0 then',
'                    l_messages_local.extend;',
'                    pkg_mensagem.mensagem_campo(',
'                        p_codigo_mensagem => ''139'',',
'                        p_nome_campo      => ''taxa_cambio'',',
'                        p_parametro       => v_parametro,',
'                        p_pagina          => 0,',
'                        p_objeto_mensagem => l_messages_local(l_messages_local.last)',
'                    );',
'',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(l_messages_local.last);',
'',
'                    pkg_mensagem.exibe_mensagem(p_messages);',
'                    return;',
'                end if;',
'',
'                l_valor_reais     := r.valor_previsto;',
'                l_valor_numerario := l_valor_reais / l_taxa_cambio;',
'',
'                bo_imp_processoimportacao_numerario_despesa.inclui_registro(',
'                    p_id_tenant                         => r.id_tenant,',
'                    p_id_numerario                      => p_id_numerario,',
'                    p_id_despesa                        => r.id,',
'                    p_id_moeda_despesa                  => r.id_moeda_prevista,',
'                    p_id_comprovacao_despesa            => null,',
'                    p_valor_moeda_da_despesa            => l_valor_numerario,',
unistr('                    p_ind_status                        => 1,   -- ajustar conforme especifica\00E7\00E3o'),
'                    p_valor_despesa_moeda_numerario     => l_valor_reais,',
'                    p_num_documento                     => null,',
'                    p_serie_nf                          => null,',
'                    p_data_nf                           => null,',
'                    p_id                                => l_novo_id,',
'                    p_sucesso                           => l_sucesso_local,',
'                    p_messages                          => l_messages_local',
'                );',
'',
'                if l_messages_local.count > 0 then',
'                    for j in 1 .. l_messages_local.count loop',
'                        p_messages.extend;',
'                        p_messages(p_messages.last) := l_messages_local(j);',
'                    end loop;',
'                end if;',
'',
'            end;',
'',
'        end loop;',
'',
'        -- Recalcula valor_despesa_moeda_numerario',
'        select nvl(sum(valor_despesa_moeda_numerario), 0) into l_total_reais from imp_processoimportacao_numerario_despesa where id_numerario = p_id_numerario;',
'',
unistr('        -- Atualiza total numer\00E1rio'),
'        declare',
'            l_num           imp_processoimportacao_numerario%rowtype;',
'            l_sucesso_alt   clob;',
'            l_messages_alt  pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'        begin',
'            select * into l_num from imp_processoimportacao_numerario where id = p_id_numerario;',
'',
'            l_num.valor_total_despesas_numerario := l_total_reais;',
'',
'            bo_imp_processoimportacao_numerario.altera_registro(',
'                p_id_tenant                         => l_num.id_tenant,',
'                p_id_processoimportacao             => l_num.id_processoimportacao,',
'                p_id_titulo_pagamento               => l_num.id_titulo_pagamento,',
'                p_ind_status                        => l_num.ind_status,',
'                p_ind_tipo_movimento                => l_num.ind_tipo_movimento,',
'                p_id_fornecedor                     => l_num.id_fornecedor,',
'                p_id_conta_bancaria                 => l_num.id_conta_bancaria,',
'                p_referencia_fornecedor               => l_num.referencia_fornecedor,',
'                p_data_documento                    => l_num.data_documento,',
'                p_data_vencimento           => l_num.data_vencimento,',
'                p_id_moeda_numerario                 => l_num.id_moeda_numerario,',
'                p_valor_numerario_informado    => l_num.valor_numerario_informado,',
'                p_valor_total_despesas_numerario              => l_num.valor_total_despesas_numerario,',
'                p_observacao                        => l_num.observacao,',
'                p_id                                => l_num.id,',
'                p_data_alteracao                    => l_num.data_alteracao,',
'                p_sucesso                           => l_sucesso_alt,',
'                p_messages                          => l_messages_alt',
'            );',
'',
'            if l_messages_alt.count > 0 then',
'                for i in 1 .. l_messages_alt.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_alt(i);',
'                end loop;',
'            end if;',
'        end;',
'    end inclui_novas_despesas_ao_numerario;',
'',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_processoimportacao_numerario_despesa;',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_fin_titulorecebimento
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(153944483962573167)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_FIN_TITULORECEBIMENTO'
,p_sequence=>380
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: BO_FIN_TITULORECEBIMENTO',
'-- Data: 23/06/2026',
unistr('-- Motivo: Exclus\00E3o das colunas num_documento e data_documento'),
'-- Jira: PEDITEM-264',
'',
'-- Objeto: BO_FIN_TITULORECEBIMENTO',
'-- Data: 22/04/2026',
unistr('-- Motivo: Altera\00E7\00E3o de coluna De: data_lancamento, Para: data_documento'),
'-- Jira: PEDITEM-264',
'',
'create or replace package            bo_fin_titulorecebimento ',
'is  ',
