unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out fin_titulorecebimento.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into fin_titulorecebimento (  ',
'            id_moeda_nacional,',
'            valor_moeda_nacional,',
'            observacao,',
'            ind_multa_atraso_pagamento,',
'            valor_multa,',
'            percentual_multa,',
'            periodo_multa,',
'            id_tenant,',
'            id_entidade,',
'            id_referencia,',
'            ind_status_recebimento,',
'            id_fornecedor,',
'            id_centrocusto,',
'            data_vencimento,',
'            data_pagamento,',
'            id_moeda,',
'            valor_titulo,',
'            valor_pago,',
'            saldo_pagar, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_moeda_nacional,',
'            nvl(v_new.valor_moeda_nacional,0),',
'            v_new.observacao,',
'            nvl(v_new.ind_multa_atraso_pagamento,''N''),',
'            nvl(v_new.valor_multa,0),',
'            nvl(v_new.percentual_multa,0),',
'            v_new.periodo_multa,',
'            v_new.id_tenant,',
'            v_new.id_entidade,',
'            v_new.id_referencia,',
'            nvl(v_new.ind_status_recebimento,1),',
'            v_new.id_fornecedor,',
'            v_new.id_centrocusto,',
'            v_new.data_vencimento,',
'            v_new.data_pagamento,',
'            v_new.id_moeda,',
'            nvl(v_new.valor_titulo,0),',
'            nvl(v_new.valor_pago,0),',
'            nvl(v_new.saldo_pagar,0), ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_incluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in fin_titulorecebimento.id%type,',
