'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update fin_titulorecebimento set  ',
'            id_moeda_nacional = v_new.id_moeda_nacional,',
'            valor_moeda_nacional = nvl(v_new.valor_moeda_nacional,0),',
'            observacao = v_new.observacao,',
