'            valor_multa = nvl(v_new.valor_multa,0),',
'            percentual_multa = nvl(v_new.percentual_multa,0),',
'            periodo_multa = v_new.periodo_multa,',
'            id_tenant = v_new.id_tenant,',
'            id_entidade = v_new.id_entidade,',
'            id_referencia = v_new.id_referencia,',
'            ind_status_recebimento = nvl(v_new.ind_status_recebimento,1),',
'            id_fornecedor = v_new.id_fornecedor,',
'            id_centrocusto = v_new.id_centrocusto,',
'            data_vencimento = v_new.data_vencimento,',
'            data_pagamento = v_new.data_pagamento,',
'            id_moeda = v_new.id_moeda,',
'            valor_titulo = nvl(v_new.valor_titulo,0),',
'            valor_pago = nvl(v_new.valor_pago,0),',
'            saldo_pagar = nvl(v_new.saldo_pagar,0), ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'        --',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''Fim da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_fin_titulorecebimento'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
