'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(''select valor_moeda_nacional as fin_titulorecebimento$valor_moeda_nacional, observacao as fin_titulorecebimento$observacao, ind_multa_atraso_pagamento as fin_titulorecebimento$ind_multa_atraso_pagamento, valor_mu'
||'lta as fin_titulorecebimento$valor_multa, percentual_multa as fin_titulorecebimento$percentual_multa, periodo_multa as fin_titulorecebimento$periodo_multa, id_tenant as fin_titulorecebimento$id_tenant, id_entidade as fin_titulorecebimento$id_entidade'
||', id_referencia as fin_titulorecebimento$id_referencia, ind_status_recebimento as fin_titulorecebimento$ind_status_recebimento, id_fornecedor as fin_titulorecebimento$id_fornecedor, id_centrocusto as fin_titulorecebimento$id_centrocusto, data_vencime'
||'nto as fin_titulorecebimento$data_vencimento, id_moeda as fin_titulorecebimento$id_moeda, valor_titulo as fin_titulorecebimento$valor_titulo, valor_pago as fin_titulorecebimento$valor_pago, saldo_pagar as fin_titulorecebimento$saldo_pagar from fin_ti'
||'tulorecebimento where id = ''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure confirma_pagamento_titulo(',
'        p_id in fin_titulorecebimento.id%type,',
'        p_data_pagamento in fin_titulorecebimento.data_pagamento%type,',
'        p_observacao in fin_titulorecebimento.observacao%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        select * into v_old from fin_titulorecebimento where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.ind_status_recebimento := 2;',
'        v_new.data_pagamento := p_data_pagamento;',
'        v_new.observacao := p_observacao;',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''CONFIRMA_PAGAMENTO_TITULO'';',
'',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end confirma_pagamento_titulo;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_fin_titulorecebimento;',
'/'))
