prompt --application/deployment/install/install_ui_mpd_td1007
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(153945588502561968)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1007'
,p_sequence=>390
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD1007',
'-- Data: 22/04/2026',
unistr('-- Motivo: Ajustes para atender novas regras de Conta corrente numer\00E1rio'),
'-- Jira: PEDITEM-226 ',
'',
'create or replace package "UI_MPD_TD1007" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD1007";',
'/',
'create or replace package body "UI_MPD_TD1007" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_entidade number;',
'        l_id_fornecedor number;',
'        l_processoimportacao_numerario imp_processoimportacao_numerario%rowtype;',
'        l_codigo_artefato_origem varchar2(50) := apex_util.get_session_state(''P9000_PAGINA'');',
'        l_valor_moeda_nacional fin_titulopagamento.valor_moeda_nacional%type;',
'        l_id_despesa number;',
'        l_id_moeda_nacional number;',
'        l_gera_numerario varchar2(1) default ''N'';',
'    begin',
'        if l_codigo_artefato_origem = ''342'' then',
'            select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_processoimportacao'';',
'            select * into l_processoimportacao_numerario from imp_processoimportacao_numerario where id_processoimportacao = p_param1 and rownum = 1;',
'            l_id_fornecedor := l_processoimportacao_numerario.id_fornecedor;',
'            select max(id_registro) into l_id_moeda_nacional from mpd_configuracao_ng where id_tenant = l_processoimportacao_numerario.id_tenant and codigo_configuracao = 13 and ind_tipo_dado = ''ID'';',
'',
'            -- * VERIFICAR CONDICAO PARA GERAR NUMERARIO DE ACORDO COM NOVAS COLUNAS ',
'            -- select nvl(sum(case when n.ind_tipo_movimento = 1 then nvl(nd.valor_numerario_moeda_nacional,0) when n.ind_tipo_movimento = 2 then -nvl(nd.valor_realizado_moeda_nacional,0) when n.ind_tipo_movimento = 4 then -nvl(nd.valor_realizado_moe'
||'da_nacional,0) when n.ind_tipo_movimento = 3 then nvl(nd.valor_numerario_moeda_nacional,0) else 0 end),0) into l_valor_moeda_nacional from imp_processoimportacao_numerario n join imp_processoimportacao_numerario_despesa nd on nd.id_numerario = n.id w'
||'here n.id_processoimportacao = p_param1;',
unistr('            -- l_gera_numerario := ''S'';    -- l_gera_numerario = ''S''-> ao incluir titulo de recebimento tamb\00E9m gera numer\00E1rio "Saldo a receber" (ind_tipo_movimento = 4)'),
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char(l_processoimportacao_numerario.id_tenant) valor FR'
||'OM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entidade'',                  2, ''HID'', null, ''S'',''S'', to_char(l_id_entidade) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_referencia'',                4, ''HID'', null, ''S'',''S'', p_param1 valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor'',                9, '''', null, ''N'',''S'', to_char(l_id_fornecedor) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_centrocusto'',              13, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento'',             15, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                    16, '''', null, ''N'',''S'', to_char(l_id_moeda_nacional) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_nacional'',           18, '''', null, ''N'',''S'', to_char(l_id_moeda_nacional) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_moeda_nacional'',        20, '''', null, ''N'',''S'', to_char(l_valor_moeda_nacional) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_multa_atraso_pagamento'',  21, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_multa'',                 22, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''percentual_multa'',            23, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''periodo_multa'',               24, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                  25, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''GERA_NUMERARIO'',              26, ''HID'', null, ''S'',''N'', to_char(l_gera_numerario) valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);        ',
'    end formulario;',
'   ',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_periodo_multa varchar2(1);',
'        l_id number;        ',
'    begin',
'        if apex_application.g_f21(1) = ''S'' then',
'            l_periodo_multa := apex_application.g_f22(1);',
'        end if;',
'',
'        if apex_application.g_f26(1) = ''S'' then',
unistr('            -- se GERA_NUMERARIO = ''S'', ent\00E3o deve criar titulo de recebimento e numerario:'),
'            BO_IMP_PROCESSOIMPORTACAO_NUMERARIO.inclui_numerario_e_titulorecebimento(',
'                p_id_tenant                     => apex_application.g_f01(1),',
'                p_id_entidade                   => apex_application.g_f02(1),',
'                p_id_referencia                 => apex_application.g_f04(1),',
'                p_id_fornecedor                 => apex_application.g_f09(1),',
'                p_id_centrocusto                => apex_application.g_f13(1),',
'                p_data_vencimento               => apex_application.g_f15(1),',
'                p_id_moeda                      => apex_application.g_f16(1),',
'                p_id_moeda_nacional             => apex_application.g_f16(1),',
'                p_valor_moeda_nacional          => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_ind_multa_atraso_pagamento    => apex_application.g_f21(1),',
'                p_valor_multa                   => pkg_util.retorna_number(apex_application.g_f22(1)),',
'                p_percentual_multa              => pkg_util.retorna_number(apex_application.g_f23(1)),',
'                p_periodo_multa                 => apex_application.g_f24(1),',
'                p_observacao                    => apex_application.g_f25(1),',
'                p_id                            => l_id,',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'            );',
'        else',
'            -- criar apenas titulo de recebimento:',
'            bo_fin_titulorecebimento.inclui_registro(',
'                p_id_tenant                     => apex_application.g_f01(1),',
'                p_id_entidade                   => apex_application.g_f02(1),',
'                p_id_referencia                 => apex_application.g_f04(1),',
'                p_id_fornecedor                 => apex_application.g_f09(1),',
'                p_id_centrocusto                => apex_application.g_f13(1),',
'                p_data_vencimento               => apex_application.g_f15(1),',
'                p_id_moeda                      => apex_application.g_f16(1),',
'                p_id_moeda_nacional             => apex_application.g_f16(1),',
'                p_valor_moeda_nacional          => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_ind_multa_atraso_pagamento    => apex_application.g_f21(1),',
'                p_valor_multa                   => pkg_util.retorna_number(apex_application.g_f22(1)),',
'                p_percentual_multa              => pkg_util.retorna_number(apex_application.g_f23(1)),',
'                p_periodo_multa                 => apex_application.g_f24(1),',
'                p_observacao                    => apex_application.g_f25(1),',
unistr('                -- campos n\00E3o exibidos no formulario:'),
'                p_valor_titulo                  => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_data_pagamento                => null,',
'                p_ind_status_recebimento        => 1,',
'                p_valor_pago                    => 0,',
'                p_saldo_pagar                   => 0,',
'                p_id                            => l_id, ',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'            );',
'        end if;',
'    end;',
'',
'end "UI_MPD_TD1007";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td940
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(154722994743732104)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD940'
,p_sequence=>400
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Jonathan',
'-- Data: 29/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es nos campos que aparecem na inclus\00E3o de t\00EDtulos'),
'-- Jira: PEDITEM-216',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 15/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es nos campos que aparecem na inclus\00E3o de t\00EDtulos'),
'-- Jira: PEDITEM-216',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade imp_processoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Objeto: UI_MPD_TD940',
'-- Data: 24/04/2026',
unistr('-- Motivo: Ajustes para adequar novas regras de Conta corrente numer\00E1rio'),
'-- Jira: PEDITEM-226',
'',
'create or replace package "UI_MPD_TD940" as   ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'   ',
'end "UI_MPD_TD940";',
'/',
'',
'create or replace package body "UI_MPD_TD940" as    ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_entidade number;',
'        l_id_exportador number;',
'        l_num_documento varchar2(40);',
'        l_serie_nf varchar2(3);',
'        l_data_documento date;',
'        l_id_moeda number;',
'        l_taxa_cambio number;',
'        l_pedidoimportacao_pagamento imp_pedidoimportacao_pagamento%rowtype;',
'        l_codigo_artefato_origem varchar2(50) := apex_util.get_session_state(''P9000_PAGINA'');',
'        l_data_vencimento fin_titulopagamento.data_vencimento%type;',
'        l_valor_titulo fin_titulopagamento.valor_titulo%type;',
'        l_ind_multa_atraso_pagamento fin_titulopagamento.ind_multa_atraso_pagamento%type;',
'        l_valor_multa fin_titulopagamento.valor_multa%type;',
'        l_percentual_multa fin_titulopagamento.percentual_multa%type;',
'        l_periodo_multa fin_titulopagamento.periodo_multa%type;',
'        l_id_tenant number;',
'        l_id_despesa number;',
'        l_id_conta_bancaria number;',
'        l_id_centrocusto number;',
'        l_num_entrega number;',
'        l_gera_numerario varchar2(1) default ''N'';',
'        l_referencia varchar2(4000);',
'    begin',
'        if l_codigo_artefato_origem in (''TD638'',''TD784'') then',
'            select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'            select a.id_exportador, a.numero_pedido_importacao, a.id_moeda into l_id_exportador, l_num_documento, l_id_moeda from imp_pedidoimportacao a join imp_pedidoimportacao_pagamento b on b.id_pedidoimportacao = a.id where b.id = p_param1;',
'            select * into l_pedidoimportacao_pagamento from imp_pedidoimportacao_pagamento where id = p_param1;                        ',
'            if l_pedidoimportacao_pagamento.id_entrega is not null then',
'                select num_entrega into l_num_entrega from imp_entrega where id = l_pedidoimportacao_pagamento.id_entrega;',
'                l_num_documento := l_num_documento||l_num_entrega;',
'            end if;            ',
'            l_data_vencimento := l_pedidoimportacao_pagamento.data_vencimento_prevista;',
'            l_valor_titulo := l_pedidoimportacao_pagamento.valor;',
'            l_ind_multa_atraso_pagamento := l_pedidoimportacao_pagamento.ind_multa_atraso_pagamento;',
'            l_valor_multa := l_pedidoimportacao_pagamento.valor_multa;',
'            l_percentual_multa := l_pedidoimportacao_pagamento.percentual_multa;',
'            l_periodo_multa := l_pedidoimportacao_pagamento.periodo_multa;',
'        elsif l_codigo_artefato_origem = ''TD591'' then',
'            select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_processoimportacao_despesa'';',
'            select a.id_embarcador, b.id_moeda_prevista, a.num_processoimportacao into l_id_exportador, l_id_moeda, l_num_documento from imp_processoimportacao a join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id where b.id = p_p'
||'aram1;',
'            select valor_previsto, taxa_cambio into l_valor_titulo, l_taxa_cambio from imp_processoimportacao_despesa where id = p_param1;',
'        elsif l_codigo_artefato_origem = ''TD939'' then',
'            select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_invoice'';',
'            select ',
'                b.id_exportador, a.data_vencimento_prevista, b.id_moeda, a.valor, a.valor_multa, a.percentual_multa, a.periodo_multa, b.num_invoice',
'            into ',
'                l_id_exportador, l_data_vencimento, l_id_moeda, l_valor_titulo, l_valor_multa, l_percentual_multa, l_periodo_multa, l_num_documento',
'            from imp_invoice_pagamento a join imp_invoice b on b.id = a.id_invoice where a.id = p_param1;        ',
'        elsif l_codigo_artefato_origem = ''342'' then',
'            -- select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_processoimportacao_numerario'';',
'            -- select abs(nvl(sum(case when n.ind_tipo_movimento = 1 then n.valor_moeda_nacional when n.ind_tipo_movimento = 2 then -n.valor_moeda_nacional when n.ind_tipo_movimento = 4 then -n.valor_moeda_nacional when n.ind_tipo_movimento = 3 then '
||'n.valor_moeda_nacional else 0 end),0)) into l_valor_titulo from imp_processoimportacao_numerario n where n.id_processoimportacao = p_param1;',
'            -- if l_valor_titulo > 0 then',
'            --     select',
'            --         n.id_fornecedor, n.id_conta_bancaria, n.id_centrocusto, bo_mpd_configuracao_ng.retorna_id_moeda_tenant(n.id_tenant)',
'            --     into',
'            --         l_id_exportador, l_id_conta_bancaria, l_id_centrocusto, l_id_moeda',
'            --     from imp_processoimportacao_numerario n',
'            --     where n.id_processoimportacao = p_param1',
'            --     order by n.data_inclusao desc',
'            --     fetch first 1 row only;',
'            -- end if;',
unistr('            l_gera_numerario := ''S'';    -- l_gera_numerario = ''S''-> ao incluir titulo de pagamento tamb\00E9m gera numer\00E1rio "Saldo a pagar" (ind_tipo_movimento = 3)'),
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char(l_pedidoimportacao_pagamento.id_tenant) valor, nul'
||'l tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entidade'',                  2,    '''', null, ''S'',''S'', to_char(l_id_entidade) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_referencia'',                4, ''HID'', null, ''S'',''S'', p_param1 valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_referencia_'',               7, ''TXT'', null, ''S'',''N'', l_num_documento valor, ''fin_titulopagamento.id_referencia'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor'',                9,    '''', null, ''S'',''S'', to_char(l_id_exportador) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor_contabancaria'', 11, ''POP'', null, ''N'',''S'',to_char(l_id_conta_bancaria) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento'',             15, '''', null, ''N'',''S'', to_char(l_data_vencimento) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                    16, '''', null, ''S'',''S'', to_char(l_id_moeda) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_titulo'',                18, '''', null, ''N'',''S'', to_char(l_valor_titulo) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_multa_atraso_pagamento'',  19, '''', null, ''N'',''S'', to_char(l_ind_multa_atraso_pagamento) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_multa'',                 20, '''', null, ''N'',''S'', to_char(l_valor_multa) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''percentual_multa'',            21, '''', null, ''N'',''S'', to_char(l_percentual_multa) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''periodo_multa'',               22, '''', null, ''N'',''S'', to_char(l_periodo_multa) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                  23, '''', null, ''N'',''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''taxa_cambio'',                 24, ''HID'', null, ''N'',''S'', to_char(l_taxa_cambio) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''GERA_NUMERARIO'',              26, ''HID'', null, ''S'',''N'', to_char(l_gera_numerario) valor, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_fornecedor_contabancaria'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.id_pessoa in (',
'                    select c003 from apex_collections where collection_name = ''TD940_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f10_0000'')',
'                )',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'    ',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_periodo_multa varchar2(1);',
'        l_id number;        ',
'    begin',
'        if apex_application.g_f19(1) = ''S'' then',
'            l_periodo_multa := apex_application.g_f22(1);',
'        end if;',
'',
'        if apex_application.g_f26(1) = ''S'' then null;',
unistr('            -- se GERA_NUMERARIO = ''S'', ent\00E3o deve criar titulo de pagamento e numerario:'),
'            -- bo_imp_processoimportacao_numerario.inclui_numerario_e_titulopagamento(',
'            --     p_id_tenant                     => apex_application.g_f01(1),',
'            --     p_id_entidade                   => apex_application.g_f02(1),',
'            --     p_id_referencia                 => apex_application.g_f04(1),',
'            --     p_num_documento                 => apex_application.g_f06(1),',
'            --     -- p_serie_nf                      => apex_application.g_f07(1),',
'            --     -- p_data_documento                => apex_application.g_f08(1),',
'            --     p_id_fornecedor                 => apex_application.g_f09(1),',
'            --     p_id_conta_bancaria             => apex_application.g_f11(1),',
'            --     p_id_centrocusto                => apex_application.g_f13(1),',
'            --     p_data_vencimento               => apex_application.g_f15(1),',
'            --     p_id_moeda                      => apex_application.g_f16(1),',
'            --     p_valor_titulo                  => pkg_util.retorna_number(apex_application.g_f18(1)),',
'            --     p_ind_multa_atraso_pagamento    => apex_application.g_f19(1),',
'            --     p_valor_multa                   => pkg_util.retorna_number(apex_application.g_f20(1)),',
'            --     p_percentual_multa              => apex_application.g_f21(1),',
'            --     p_periodo_multa                 => l_periodo_multa,',
'            --     p_observacao                    => apex_application.g_f23(1),',
'            --     p_taxa_cambio                   => pkg_util.retorna_number(apex_application.g_f24(1)),',
'            --     p_id                            => l_id,',
'            --     p_sucesso                       => p_sucesso,',
'            --     p_messages                      => p_messages',
'            -- );',
'        else',
'            -- criar apenas titulo de pagamento:',
'            bo_fin_titulopagamento.inclui_registro(',
'                p_id_tenant => apex_application.g_f01(1),',
'                p_id_entidade => apex_application.g_f02(1),',
'                p_id_referencia => apex_application.g_f04(1),',
'                p_id_fornecedor => apex_application.g_f09(1),',
'                p_id_fornecedor_contabancaria => apex_application.g_f11(1),',
'                p_data_vencimento => apex_application.g_f15(1),            ',
'                p_id_moeda => apex_application.g_f16(1),',
'                p_valor_titulo => pkg_util.retorna_number(apex_application.g_f18(1)),',
'                p_ind_multa_atraso_pagamento => apex_application.g_f19(1),',
'                p_valor_multa => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_percentual_multa => apex_application.g_f21(1),',
'                p_periodo_multa => l_periodo_multa,',
'                p_observacao => apex_application.g_f23(1),',
'                p_taxa_cambio => pkg_util.retorna_number(apex_application.g_f24(1)),',
'                p_ind_status_pagamento => 1,',
'                p_valor_pago => null,',
'                p_saldo_pagar => null,            ',
'                p_valor_moeda_nacional => null,',
'                p_valor_compensado => null,',
'                p_saldo_compensar => pkg_util.retorna_number(apex_application.g_f18(1)), --?',
'                p_data_pagamento => null,',
'                p_data_compensacao => null,',
'                p_id => l_id, ',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end;    ',
'',
'end "UI_MPD_TD940";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td942
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(154724155900717718)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD942'
,p_sequence=>410
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 15/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es nos campos de consulta do prot\00F3tipo'),
'-- Jira: PEDITEM-217',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Objeto: UI_MPD_TD942',
'-- Data: 04/05/2026',
'-- Motivo: Adicionado novas colunas na consulta (ind_status_pagamento)',
'-- Jira: PEDITEM-217',
'',
'-- Objeto: UI_MPD_TD942',
'-- Data: 29/04/2026',
'-- Motivo: Adicionado novas colunas na consulta',
'-- Jira: PEDITEM-217',
'',
'-- Objeto: UI_MPD_TD942',
'-- Data: 24/04/2026',
unistr('-- Motivo: Ajustes para adequar novas regras de Conta corrente numer\00E1rio'),
'-- Jira: PEDITEM-226',
'',
'create or replace package "UI_MPD_TD942" as   ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'end "UI_MPD_TD942";',
'/',
'',
'create or replace package body "UI_MPD_TD942" as    ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_codigo_artefato_origem varchar2(50) := apex_util.get_session_state(''P9000_PAGINA'');',
'        l_fin_titulopagamento fin_titulopagamento%rowtype;',
'        l_entidade varchar2(4000);',
'        l_referencia varchar2(4000);',
'    begin',
'        if l_codigo_artefato_origem in (''TD638'',''TD784'') then',
'            select * into l_fin_titulopagamento from fin_titulopagamento where id = p_param1;',
'            select a.numero_pedido_importacao into l_referencia from imp_pedidoimportacao a join imp_pedidoimportacao_pagamento b on b.id_pedidoimportacao = a.id where b.id = l_fin_titulopagamento.id_referencia;',
'        elsif l_codigo_artefato_origem = ''TD591'' then',
'            select a.* into l_fin_titulopagamento from fin_titulopagamento a join imp_processoimportacao_despesa b on b.id = a.id_referencia join srv_entidade c on c.id = a.id_entidade where b.id = p_param1 and lower(nome_entidade) = ''imp_processoimp'
||'ortacao_despesa'';',
'            select a.num_processoimportacao into l_referencia from imp_processoimportacao a join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id where b.id = l_fin_titulopagamento.id_referencia;',
'        elsif l_codigo_artefato_origem = ''TD939'' then',
'            select a.* into l_fin_titulopagamento from fin_titulopagamento a join imp_invoice_pagamento b on b.id = a.id_referencia join srv_entidade c on c.id = a.id_entidade where b.id = p_param1 and lower(nome_entidade) = ''imp_invoice'';        ',
'            select a.num_invoice into l_referencia from imp_invoice a join imp_invoice_pagamento b on b.id_invoice = a.id where b.id = l_fin_titulopagamento.id_referencia;',
'        elsif l_codigo_artefato_origem = ''TD976'' then',
'            select * into l_fin_titulopagamento from fin_titulopagamento where id = p_param1;',
'        elsif l_codigo_artefato_origem = ''342'' then',
'            select * into l_fin_titulopagamento from fin_titulopagamento where id = p_param1;',
'        end if;',
'',
'        select nome_leitura into l_entidade from srv_entidade where id = l_fin_titulopagamento.id_entidade;',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.NOME_FANTASIA'' AS nome_consulta, ''S'' AS somente_leitura, ''N'' as coluna_tabela, to_char(l_fin_titulopagamento.i'
||'d_tenant) valor, ''fin_titulopagamento.id_tenant'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pagamento'',         2, ''SEL'', ''D_FIN_TITULOPAGAMENTO.IND_STATUS_PAGAMENTO'', ''S'',''N'', to_char(l_fin_titulopagamento.ind_status_pagamento) valor, ''fin_titulopagamento.ind_status_pagamento'' tag_campo '
||'FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entidade'',                  3, ''TXT'', null, ''S'',''N'', to_char(l_entidade) valor, ''fin_titulopagamento.id_entidade'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_referencia'',                4, ''TXT'', null, ''S'',''N'', to_char(l_referencia) valor, ''fin_titulopagamento.id_referencia'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor'',                9, ''POP'', ''R_NG_PESSOA_JURIDICA.NOME_FANTASIA'', ''S'',''N'', to_char(l_fin_titulopagamento.id_fornecedor) valor, ''fin_titulopagamento.id_fornecedor'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor_contabancaria'', 11, ''POP'', ''R_NG_PESSOA_CONTABANCARIA.DESCRICAO_CONTA_BANCARIA'', ''S'',''N'', to_char(l_fin_titulopagamento.id_fornecedor_contabancaria) valor, ''fin_titulopagamento.id_fornecedor_con'
||'tabancaria'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento'',             15, ''DAT'', null, ''S'',''N'', to_char(l_fin_titulopagamento.data_vencimento) valor, ''fin_titulopagamento.data_vencimento'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                    16, ''POP'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''S'',''N'', to_char(l_fin_titulopagamento.id_moeda) valor, ''fin_titulopagamento.id_moeda'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_titulo'',                18, ''TXT'', null, ''S'',''N'', to_char(l_fin_titulopagamento.valor_titulo, ''FM999G999G990D00'') valor, ''fin_titulopagamento.valor_titulo'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_multa_atraso_pagamento'',  19, ''SEL'', ''D_FIN_TITULOPAGAMENTO.IND_MULTA_ATRASO_PAGAMENTO'', ''S'',''N'', to_char(l_fin_titulopagamento.ind_multa_atraso_pagamento) valor, ''fin_titulopagamento.ind_multa_atraso_pag'
||'amento'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_multa'',                 20, ''TXT'', null, ''S'',''N'', to_char(l_fin_titulopagamento.valor_multa, ''FM999G999G990D00'') valor, ''fin_titulopagamento.valor_multa'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''percentual_multa'',            21, ''TXT'', null, ''S'',''N'', to_char(l_fin_titulopagamento.percentual_multa) valor, ''fin_titulopagamento.percentual_multa'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''periodo_multa'',               22, ''SEL'', ''D_FIN_TITULOPAGAMENTO.PERIODO_MULTA'', ''S'',''N'', to_char(l_fin_titulopagamento.periodo_multa) valor, ''fin_titulopagamento.periodo_multa'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_compensado'',            23, ''TXT'', null, ''S'',''N'', to_char(l_fin_titulopagamento.valor_compensado, ''FM999G999G990D00'') valor, ''fin_titulopagamento.valor_compensado'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''saldo_compensar'',             24, ''TXT'', null, ''S'',''N'', to_char(l_fin_titulopagamento.saldo_compensar, ''FM999G999G990D00'') valor, ''fin_titulopagamento.saldo_compensar'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                  25, ''TEX'', null, ''S'',''N'', to_char(l_fin_titulopagamento.observacao) valor, ''fin_titulopagamento.observacao'' tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'end "UI_MPD_TD942";',
'/'))
);
end;
/
