'            id_conta_bancaria,',
'            referencia_fornecedor,',
'            data_documento,',
'            data_vencimento,',
'            valor_numerario_informado,',
'            valor_total_despesas_numerario,',
'            observacao,',
'            id',
'            into',
'            p_id_moeda_numerario,',
'            p_id_tenant,',
'            p_id_processoimportacao,',
'            p_id_titulo_pagamento,',
'            p_ind_status,',
'            p_ind_tipo_movimento,',
'            p_id_fornecedor,',
