unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_numerario'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_numerario'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_numerario'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_numerario'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_numerario'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_numerario'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;',
'    --',
'    function row_to_json(p_rec in imp_processoimportacao_numerario%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_moeda_numerario'', p_rec.id_moeda_numerario, true);',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_processoimportacao'', p_rec.id_processoimportacao, true);',
'        apex_json.write(''id_titulo_pagamento'', p_rec.id_titulo_pagamento, true);',
'        apex_json.write(''ind_status'', p_rec.ind_status, true);',
'        apex_json.write(''ind_tipo_movimento'', p_rec.ind_tipo_movimento, true);',
'        apex_json.write(''id_fornecedor'', p_rec.id_fornecedor, true);',
'        apex_json.write(''id_conta_bancaria'', p_rec.id_conta_bancaria, true);',
'        apex_json.write(''referencia_fornecedor'', p_rec.referencia_fornecedor, true);',
'        apex_json.write(''data_documento'', p_rec.data_documento, true);',
'        apex_json.write(''data_vencimento'', p_rec.data_vencimento, true);',
'        apex_json.write(''valor_numerario_informado'', p_rec.valor_numerario_informado, true);',
'        apex_json.write(''valor_total_despesas_numerario'', p_rec.valor_total_despesas_numerario, true);',
'        apex_json.write(''observacao'', p_rec.observacao, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;',
'',
'    --<CUSTOMIZADO_INICIO>',
'    function detalhe_registro (',
'        p_id in imp_processoimportacao_numerario.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                b.num_processoimportacao as imp_processoimportacao_numerario$id_processoimportacao,',
'                pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'', ''ind_tipo_movimento'', a.ind_tipo_movimento) as imp_processoimportacao_numerario$ind_tipo_movimento,',
'                pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'', ''ind_status'', a.ind_status) as imp_processoimportacao_numerario$ind_status,',
'                bo_ng_pessoa.retorna_pessoa(a.id_fornecedor) as imp_processoimportacao_numerario$id_fornecedor,',
'                a.referencia_fornecedor as imp_processoimportacao_numerario$referencia_fornecedor,',
'                c.codigo_moeda || '' - '' || c.simbolo_iso as imp_processoimportacao_numerario$id_moeda_numerario,',
'                to_char(a.valor_total_despesas_numerario, ''FM999G999G999G990D00'') as imp_processoimportacao_numerario$valor_total_despesas_numerario',
'            from imp_processoimportacao_numerario a',
'            join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_moeda c on c.id = a.id_moeda_numerario',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'',
