'',
'    procedure altera_numerario_gera_titulo (',
'        p_id_tenant                         in number,',
'        p_id_processoimportacao             in number,',
'        p_ind_status                        in number,',
'        p_ind_tipo_movimento                in number,',
'        p_id_fornecedor                     in number,',
'        p_id_conta_bancaria                 in number,',
'        p_referencia_fornecedor             in varchar2,',
'        p_data_documento                    in date,',
'        p_data_vencimento                   in date,',
'        p_id_moeda_numerario                in number,',
'        p_valor_numerario_informado         in number,',
'        p_valor_total_despesas_numerario    in number,',
'        p_observacao                        in varchar2,',
'        p_data_alteracao                    in date,',
'        p_id                                in number,',
'        p_sucesso                           out clob,',
'        p_messages                          out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_titulo                         number;',
'        l_mensagem                          clob;',
'        l_paramentros                       pkg_mensagem.paramentros;',
'    begin',
unistr('        -- Verifica se j\00E1 existe t\00EDtulo vinculado'),
'        select id_titulo_pagamento into l_id_titulo_exist from imp_processoimportacao_numerario where id = p_id;',
'',
'        v_operacao := ''altera_numerario_gera_titulo'';',
'',
'        if l_id_titulo_exist is not null then',
'            l_id_titulo := l_id_titulo_exist;',
'        elsif p_ind_tipo_movimento = 1 and p_ind_status = 3 then',
unistr('            -- Cria t\00EDtulo antes do altera_registro para que id_titulo_pagamento seja gravado corretamente'),
'            bo_fin_titulopagamento.inclui_registro(',
'                p_id_tenant                   => p_id_tenant,',
'                p_id_entidade                 => 4733,',
'                p_id_referencia               => p_id,',
'                p_ind_status_pagamento        => 1,',
'                p_id_fornecedor               => p_id_fornecedor,',
'                p_id_fornecedor_contabancaria => p_id_conta_bancaria,',
'                p_data_vencimento             => p_data_vencimento,',
'                p_data_pagamento              => null,',
'                p_data_compensacao            => null,',
'                p_id_moeda                    => 1,',
'                p_valor_titulo                => p_valor_total_despesas_numerario,',
'                p_valor_pago                  => null,',
'                p_saldo_pagar                 => p_valor_total_despesas_numerario,',
'                p_taxa_cambio                 => null,',
'                p_valor_moeda_nacional        => p_valor_total_despesas_numerario,',
'                p_observacao                  => p_observacao,',
'                p_ind_multa_atraso_pagamento  => ''N'',',
'                p_valor_multa                 => null,',
'                p_percentual_multa            => null,',
'                p_periodo_multa               => null,',
'                p_valor_compensado            => null,',
'                p_saldo_compensar             => null,',
'                p_id                          => l_id_titulo,',
'                p_pagina                      => 0,',
'                p_encadeado                   => true,',
'                p_sucesso                     => p_sucesso,',
'                p_messages                    => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'',
'            l_paramentros(1) := p_referencia_fornecedor;',
'            l_paramentros(2) := to_char(p_data_vencimento, ''DD/MM/YYYY'');',
'            l_paramentros(3) := to_char(p_valor_total_despesas_numerario);',
'            pkg_mensagem.mensagem_original(297, l_paramentros, l_mensagem);',
'            p_sucesso := l_mensagem || ''[NAO_AUTO_FECHAR]'';',
'        end if;',
'',
unistr('        -- Atualiza numer\00E1rio'),
'        altera_registro(',
'            p_id_tenant                         => p_id_tenant,',
'            p_id_processoimportacao             => p_id_processoimportacao,',
'            p_id_titulo_pagamento               => l_id_titulo,',
'            p_ind_status                        => p_ind_status,',
'            p_ind_tipo_movimento                => p_ind_tipo_movimento,',
'            p_id_fornecedor                     => p_id_fornecedor,',
'            p_id_conta_bancaria                 => p_id_conta_bancaria,',
'            p_referencia_fornecedor             => p_referencia_fornecedor,',
'            p_data_documento                    => p_data_documento,',
'            p_data_vencimento                   => p_data_vencimento,',
'            p_id_moeda_numerario                => p_id_moeda_numerario,',
'            p_valor_numerario_informado         => p_valor_numerario_informado,',
'            p_valor_total_despesas_numerario    => p_valor_total_despesas_numerario,',
'            p_observacao                        => p_observacao,',
'            p_data_alteracao                    => p_data_alteracao,',
'            p_id                                => p_id,',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );',
'',
'    exception',
'        when others then',
'            apex_debug.error(''BO_NUMERARIO.ERRO | ID=%s ERRO=%s'', p_id, sqlerrm);',
'        raise;',
'',
'    end altera_numerario_gera_titulo;',
'',
'',
'    procedure altera_numerario_cancela_titulo (',
'        p_id_tenant                         in number,',
'        p_id_processoimportacao             in number,',
'        p_ind_status                        in number,',
'        p_ind_tipo_movimento                in number,',
