'        p_id                                in number,',
'        p_sucesso                           out clob,',
'        p_messages                          out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_titulo                         number;',
'    begin',
unistr('        -- Verifica se j\00E1 existe t\00EDtulo vinculado-l_id_titulo_exist declarado globalmente'),
'        select id_titulo_pagamento into l_id_titulo_exist from imp_processoimportacao_numerario where id = p_id;',
'',
'        --adiciona valores do fin_titulopagamento para uso la na frente',
'        if l_id_titulo_exist is not null then',
'           l_id_titulo := l_id_titulo_exist;',
'           select * into v_new_fin from fin_titulopagamento where id = l_id_titulo_exist;',
'        end if;',
'',
'        v_operacao := ''altera_numerario_cancela_titulo'';',
unistr('        -- Atualiza numer\00E1rio'),
'',
'        altera_registro(',
'            p_id_tenant                         => p_id_tenant,',
'            p_id_processoimportacao             => p_id_processoimportacao,',
'            p_id_titulo_pagamento               => l_id_titulo,',
'            p_ind_status                        => p_ind_status,',
'            p_ind_tipo_movimento                => p_ind_tipo_movimento,',
'            p_id_fornecedor                     => p_id_fornecedor,',
'            p_id_conta_bancaria                 => p_id_conta_bancaria,',
'            p_referencia_fornecedor             => p_referencia_fornecedor,',
'            p_data_documento                    => p_data_documento,',
'            p_data_vencimento                   => p_data_vencimento,',
'            p_id_moeda_numerario                => p_id_moeda_numerario,',
'            p_valor_numerario_informado         => p_valor_numerario_informado,',
'            p_valor_total_despesas_numerario    => p_valor_total_despesas_numerario,',
'            p_observacao                        => p_observacao,',
'            p_data_alteracao                    => p_data_alteracao,',
'            p_id                                => p_id,',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );',
'',
'    exception',
'        when others then',
'            apex_debug.error(''BO_NUMERARIO.ERRO | ID=%s ERRO=%s'', p_id, sqlerrm);',
'        raise;',
'',
'    end altera_numerario_cancela_titulo;',
'',
'    function calcula_valor_total_despesas_numerario(',
'        p_id_numerario in imp_processoimportacao_numerario.id%type',
'    ) return number',
'    is',
'        l_valor number;',
'    begin',
'        select nvl(sum(',
'                case',
'                    when n.ind_tipo_movimento = 1 then d.valor_despesa_moeda_numerario',
'                    when n.ind_tipo_movimento = 2 then d.valor_despesa_moeda_numerario',
'                    else 0',
'                end',
'            ),0)',
'        into l_valor',
'        from imp_processoimportacao_numerario n',
'        left join imp_processoimportacao_numerario_despesa d on d.id_numerario = n.id',
'        where n.id = p_id_numerario;',
'',
'        return l_valor;',
'    end;',
'',
'    procedure atualiza_valor_total_despesas_numerario(',
'        p_id in imp_processoimportacao_numerario.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'    begin',
'        select * into v_old from imp_processoimportacao_numerario where id = p_id;',
'',
'        v_new := v_old;',
'',
'        v_new.valor_total_despesas_numerario := calcula_valor_total_despesas_numerario(p_id);',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ATUALIZA_VALOR_TOTAL_DESPESAS_NUMERARIO'';',
'',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end atualiza_valor_total_despesas_numerario;',
'    --',
'    procedure inclui_numerario_e_titulorecebimento(',
'        p_id_tenant                     in fin_titulorecebimento.id_tenant%type,',
'        p_id_entidade                   in fin_titulorecebimento.id_entidade%type,',
'        p_id_referencia                 in fin_titulorecebimento.id_referencia%type,',
'        p_id_fornecedor                 in fin_titulorecebimento.id_fornecedor%type,',
'        p_id_centrocusto                in fin_titulorecebimento.id_centrocusto%type,',
'        p_data_vencimento               in fin_titulorecebimento.data_vencimento%type,',
'        p_id_moeda                      in fin_titulorecebimento.id_moeda%type,',
'        p_id_moeda_nacional             in fin_titulorecebimento.id_moeda_nacional%type,',
'        p_valor_moeda_nacional          in fin_titulorecebimento.valor_moeda_nacional%type,',
'        p_ind_multa_atraso_pagamento    in fin_titulorecebimento.ind_multa_atraso_pagamento%type,',
'        p_valor_multa                   in fin_titulorecebimento.valor_multa%type,',
'        p_percentual_multa              in fin_titulorecebimento.percentual_multa%type,',
'        p_periodo_multa                 in fin_titulorecebimento.periodo_multa%type,',
'        p_observacao                    in fin_titulorecebimento.observacao%type,',
'        p_id                            out fin_titulorecebimento.id%type,',
'        p_sucesso                       out clob,',
'        p_messages                      out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_titulo fin_titulorecebimento.id%type;',
'        l_id_numerario imp_processoimportacao_numerario.id%type;',
'    begin',
'',
unistr('        -- cria t\00EDtulo de recebimento'),
'        bo_fin_titulorecebimento.inclui_registro(',
'            p_id_tenant                     => p_id_tenant,',
'            p_id_entidade                   => p_id_entidade,',
'            p_id_referencia                 => p_id_referencia,',
'            p_id_fornecedor                 => p_id_fornecedor,',
'            p_id_centrocusto                => p_id_centrocusto,',
'            p_data_vencimento               => p_data_vencimento,',
'            p_id_moeda                      => p_id_moeda,',
'            p_id_moeda_nacional             => p_id_moeda_nacional,',
'            p_valor_moeda_nacional          => p_valor_moeda_nacional,',
'            p_ind_multa_atraso_pagamento    => p_ind_multa_atraso_pagamento,',
'            p_valor_multa                   => p_valor_multa,',
'            p_percentual_multa              => p_percentual_multa,',
'            p_periodo_multa                 => p_periodo_multa,',
'            p_observacao                    => p_observacao,',
unistr('            -- campos ocultos no formul\00E1rio:'),
'            p_valor_titulo                  => p_valor_moeda_nacional,',
'            p_data_pagamento                => null,',
'            p_ind_status_recebimento        => 1,',
'            p_valor_pago                    => 0,',
'            p_saldo_pagar                   => 0,',
'            p_id                            => l_id_titulo,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'',
'        -- se deu algum erro, para e exibe a mensagem:',
'        if p_messages.count > 0 then',
'            return;',
'        end if;',
'',
unistr('        -- cria numer\00E1rio a partir do titulo de recebimento:'),
'        bo_imp_processoimportacao_numerario.inclui_registro(',
'            p_id_moeda_numerario             => p_id_moeda_nacional,',
'            p_id_tenant                      => p_id_tenant,',
'            p_id_processoimportacao          => p_id_referencia,',
'            p_id_titulo_pagamento            => null,',
'            p_ind_status                     => 3,',
'            p_ind_tipo_movimento             => 4,',
'            p_id_fornecedor                  => p_id_fornecedor,',
'            p_id_conta_bancaria              => null,',
'            p_referencia_fornecedor          => p_id_referencia,',
'            p_data_documento                 => trunc(sysdate),',
'            p_data_vencimento                => p_data_vencimento,',
'            p_valor_numerario_informado      => p_valor_moeda_nacional,',
'            p_valor_total_despesas_numerario => p_valor_moeda_nacional,',
'            p_observacao                     => p_observacao,',
'            p_id                             => l_id_numerario,',
'            p_sucesso                        => p_sucesso,',
'            p_messages                       => p_messages',
'        );',
'',
'        p_id := l_id_titulo;',
'    end inclui_numerario_e_titulorecebimento;',
'    --',
'    procedure inclui_numerario_e_titulopagamento(',
'        p_id_tenant                     in fin_titulopagamento.id_tenant%type,',
'        p_id_entidade                   in fin_titulopagamento.id_entidade%type,',
'        p_id_referencia                 in fin_titulopagamento.id_referencia%type,',
'        p_num_documento                 in imp_processoimportacao_numerario.referencia_fornecedor%type,',
'        p_id_fornecedor                 in fin_titulopagamento.id_fornecedor%type,',
'        p_id_conta_bancaria             in fin_titulopagamento.id_fornecedor_contabancaria%type,',
'        p_data_vencimento               in fin_titulopagamento.data_vencimento%type,',
'        p_id_moeda                      in fin_titulopagamento.id_moeda%type,',
'        p_valor_titulo                  in fin_titulopagamento.valor_titulo%type,',
'        p_ind_multa_atraso_pagamento    in fin_titulopagamento.ind_multa_atraso_pagamento%type,',
'        p_valor_multa                   in fin_titulopagamento.valor_multa%type,',
'        p_percentual_multa              in fin_titulopagamento.percentual_multa%type,',
'        p_periodo_multa                 in fin_titulopagamento.periodo_multa%type,',
'        p_observacao                    in fin_titulopagamento.observacao%type,',
'        p_taxa_cambio                   in fin_titulopagamento.taxa_cambio%type,',
'        p_id                            out fin_titulopagamento.id%type,',
'        p_sucesso                       out clob,',
'        p_messages                      out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_titulo     fin_titulopagamento.id%type;',
'        l_id_numerario  imp_processoimportacao_numerario.id%type;',
'        l_id_moeda_numerario number;',
'    begin',
'        l_id_moeda_numerario := bo_mpd_configuracao_ng.retorna_id_moeda_tenant(p_id_tenant);',
'',
unistr('        -- cria t\00EDtulo de pagamento'),
'        bo_fin_titulopagamento.inclui_registro(',
'            p_id_tenant                     => p_id_tenant,',
'            p_id_entidade                   => p_id_entidade,',
'            p_id_referencia                 => p_id_referencia,',
'            p_id_fornecedor                 => p_id_fornecedor,',
'            p_id_fornecedor_contabancaria   => p_id_conta_bancaria,',
'            p_data_vencimento               => p_data_vencimento,',
'            p_id_moeda                      => p_id_moeda,',
'            p_valor_titulo                  => p_valor_titulo,',
'            p_ind_multa_atraso_pagamento    => p_ind_multa_atraso_pagamento,',
'            p_valor_multa                   => p_valor_multa,',
'            p_percentual_multa              => p_percentual_multa,',
'            p_periodo_multa                 => p_periodo_multa,',
'            p_observacao                    => p_observacao,',
'            p_taxa_cambio                   => p_taxa_cambio,',
'            p_ind_status_pagamento          => 1,',
'            p_valor_pago                    => 0,',
'            p_saldo_pagar                   => p_valor_titulo,',
'            p_valor_moeda_nacional          => null,',
'            p_valor_compensado              => null,',
'            p_saldo_compensar               => p_valor_titulo,',
'            p_data_pagamento                => null,',
'            p_data_compensacao              => null,',
'            p_id                            => l_id_titulo,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'',
'        -- se deu algum erro, para e exibe a mensagem:',
'        if p_messages.count > 0 then',
'            return;',
'        end if;',
'',
unistr('        -- cria numer\00E1rio a partir do titulo de pagamento:'),
'        bo_imp_processoimportacao_numerario.inclui_registro(',
'            p_id_moeda_numerario             => l_id_moeda_numerario,',
'            p_id_tenant                      => p_id_tenant,',
'            p_id_processoimportacao          => p_id_referencia,',
'            p_id_titulo_pagamento            => l_id_titulo,',
'            p_ind_status                     => 3,',
'            p_ind_tipo_movimento             => 3,',
'            p_id_fornecedor                  => p_id_fornecedor,',
'            p_id_conta_bancaria              => p_id_conta_bancaria,',
'            p_referencia_fornecedor          => p_num_documento,',
'            p_data_documento                 => trunc(sysdate),',
'            p_data_vencimento                => p_data_vencimento,',
'            p_valor_numerario_informado      => p_valor_titulo,',
'            p_valor_total_despesas_numerario => p_valor_titulo,',
'            p_observacao                     => p_observacao,',
'            p_id                             => l_id_numerario,',
'            p_sucesso                        => p_sucesso,',
'            p_messages                       => p_messages',
'        );',
'',
'        p_id := l_id_titulo;',
'    end inclui_numerario_e_titulopagamento;',
'    --',
'    procedure cancela_titulo_pagamento(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        v_novo_status fin_titulopagamento.ind_status_pagamento%type;',
'    begin',
'        if v_new_fin.ind_status_pagamento = 1 then',
'            v_novo_status := 3;',
'        elsif v_new_fin.ind_status_pagamento = 2 then',
'            v_novo_status := 4;',
'        end if;',
'',
'        if v_novo_status is not null then',
'            bo_fin_titulopagamento.altera_registro(',
'                p_id_tenant                   => v_new_fin.id_tenant,',
'                p_id_entidade                 => v_new_fin.id_entidade,',
'                p_id_referencia               => v_new_fin.id_referencia,',
'                p_ind_status_pagamento        => v_novo_status,',
'                p_id_fornecedor               => v_new_fin.id_fornecedor,',
'                p_id_fornecedor_contabancaria => v_new_fin.id_fornecedor_contabancaria,',
'                p_data_vencimento             => v_new_fin.data_vencimento,',
'                p_data_pagamento              => v_new_fin.data_pagamento,',
'                p_data_compensacao            => v_new_fin.data_compensacao,',
'                p_id_moeda                    => v_new_fin.id_moeda,',
'                p_valor_titulo                => v_new_fin.valor_titulo,',
'                p_valor_pago                  => v_new_fin.valor_pago,',
'                p_saldo_pagar                 => v_new_fin.saldo_pagar,',
'                p_taxa_cambio                 => v_new_fin.taxa_cambio,',
'                p_valor_moeda_nacional        => v_new_fin.valor_moeda_nacional,',
'                p_observacao                  => v_new_fin.observacao,',
'                p_ind_multa_atraso_pagamento  => v_new_fin.ind_multa_atraso_pagamento,',
'                p_valor_multa                 => v_new_fin.valor_multa,',
'                p_percentual_multa            => v_new_fin.percentual_multa,',
'                p_periodo_multa               => v_new_fin.periodo_multa,',
'                p_valor_compensado            => v_new_fin.valor_compensado,',
'                p_saldo_compensar             => v_new_fin.saldo_compensar,',
'                p_id                          => v_new_fin.id,',
'                p_data_alteracao     '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154725314076695335)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'         => null,',
'                p_pagina                      => 0,',
'                p_encadeado                   => false,',
'                p_sucesso                     => p_sucesso,',
'                p_messages                    => p_messages',
'            );',
'        end if;',
'    end cancela_titulo_pagamento;',
'    --',
'    procedure aprova_numerario(',
'        p_id             in imp_processoimportacao_numerario.id%type,',
'        p_data_alteracao in imp_processoimportacao_numerario.data_alteracao%type default null,',
'        p_pagina         in number default 0,',
'        p_encadeado      in boolean default false,',
'        p_sucesso        out clob,',
'        p_messages       out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_operacao       := ''altera_numerario_cancela_titulo'';',
'        v_messages       := pkg_mensagem.message_record_table();',
'        v_parametro(0)   := ''bo_imp_processoimportacao_numerario.aprova_numerario'';',
'        v_pagina         := p_pagina;',
'        v_data_alteracao := p_data_alteracao;',
'',
'        select * into v_old',
'          from imp_processoimportacao_numerario',
'         where id = p_id;',
'',
'        v_new            := v_old;',
'        v_new.ind_status := 2;',
'',
'        if v_new.id_titulo_pagamento is not null then',
'            select * into v_new_fin',
'              from fin_titulopagamento',
'             where id = v_new.id_titulo_pagamento;',
'        end if;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end aprova_numerario;',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_processoimportacao_numerario;',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_imp_pedidoimportacao
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(154767291109620274)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_IMP_PEDIDOIMPORTACAO'
,p_sequence=>430
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 23/06/2026',
unistr('-- Motivo: Inclus\00E3o das colunas ind_finalidade e numero_ato_concessorio na entidade imp_pedidoimportacao_item'),
'-- Jira: PEDITEM-330',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Objeto: BO_IMP_PEDIDOIMPORTACAO',
'-- Data: 05/05/2026',
'-- Motivo: Ajustes para retornar corretamente o valor_total_financeiro ',
'-- Jira: PEDITEM-25/PEDITEM-26/PEDITEM-27',
'',
'-- Objeto: BO_IMP_PEDIDOIMPORTACAO',
'-- Data: 30/04/2026',
'-- Motivo: Ajustes para cancelar saldo de itens',
'-- Jira: PEDITEM-14',
'',
'-- Objeto: BO_IMP_PEDIDOIMPORTACAO',
'-- Data: 24/04/2026',
'-- Motivo: Desenvolvimentos da invoice',
'-- Jira: IMP00176_invoice_aprovar',
'',
'create or replace package            bo_imp_pedidoimportacao ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old imp_pedidoimportacao%rowtype;',
'    v_new imp_pedidoimportacao%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao imp_pedidoimportacao.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_pedidoimportacao.id%type',
'    );',
'    procedure grava(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(  ',
'        p_id_tenant in imp_pedidoimportacao.id_tenant%type,',
'        p_numero_pedido_importacao in imp_pedidoimportacao.numero_pedido_importacao%type,',
'        p_ind_status_pedido_importacao in imp_pedidoimportacao.ind_status_pedido_importacao%type,',
'        p_ind_modalidade_importacao in imp_pedidoimportacao.ind_modalidade_importacao%type,',
'        p_id_exportador in imp_pedidoimportacao.id_exportador%type,',
'        p_id_importador in imp_pedidoimportacao.id_importador%type,',
'        p_id_adquirente in imp_pedidoimportacao.id_adquirente%type,',
'        p_id_comprador in imp_pedidoimportacao.id_comprador%type,',
'        p_numero_proforma in imp_pedidoimportacao.numero_proforma%type,',
'        p_id_viatransporte in imp_pedidoimportacao.id_viatransporte%type,',
'        p_id_incoterm in imp_pedidoimportacao.id_incoterm%type,',
'        p_id_local_embarque in imp_pedidoimportacao.id_local_embarque%type,',
'        p_id_local_desembarque in imp_pedidoimportacao.id_local_desembarque%type,',
'        p_id_endereco_destino in imp_pedidoimportacao.id_endereco_destino%type,',
'        p_quantidade_entrega in imp_pedidoimportacao.quantidade_entrega%type,',
'        p_id_condicaopagamento in imp_pedidoimportacao.id_condicaopagamento%type,',
'        p_valor_total_mercadoria in imp_pedidoimportacao.valor_total_mercadoria%type,',
'        p_valor_desconto in imp_pedidoimportacao.valor_desconto%type,',
'        p_valor_despesa_proforma in imp_pedidoimportacao.valor_despesa_proforma%type,',
