'',
'create or replace package body            bo_imp_pedidoimportacao ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_pedidoimportacao.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_pedidoimportacao'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into imp_pedidoimportacao (  ',
'            id_tenant,',
'            numero_pedido_importacao,',
'            ind_status_pedido_importacao,',
'            ind_modalidade_importacao,',
'            id_exportador,',
'            id_importador,',
'            id_adquirente,',
'            id_comprador,',
'            numero_proforma,',
'            id_viatransporte,',
'            id_incoterm,',
'            id_local_embarque,',
'            id_local_desembarque,',
'            id_endereco_destino,',
'            quantidade_entrega,',
'            id_condicaopagamento,',
'            valor_total_mercadoria,',
'            valor_desconto,',
'            valor_despesa_proforma,',
'            valor_total_condicao_venda,',
'            ind_todos_itens_com_entregas_programadas,',
'            nome_vendedor,',
'            id_endereco_origem,',
'            ind_situacao_parcela_pagamento,',
'            id_listapreco,',
'            data_confirmacao_pedido,',
'            id_moeda,',
'            quantidade_parcelas_pagamento,',
'            motivo_desconto,',
'            valor_total_financeiro, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_tenant,',
'            v_new.numero_pedido_importacao,',
'            v_new.ind_status_pedido_importacao,',
'            v_new.ind_modalidade_importacao,',
'            v_new.id_exportador,',
'            v_new.id_importador,',
'            v_new.id_adquirente,',
'            v_new.id_comprador,',
'            v_new.numero_proforma,',
'            v_new.id_viatransporte,',
'            v_new.id_incoterm,',
'            v_new.id_local_embarque,',
'            v_new.id_local_desembarque,',
'            v_new.id_endereco_destino,',
'            v_new.quantidade_entrega,',
'            v_new.id_condicaopagamento,',
'            v_new.valor_total_mercadoria,',
'            v_new.valor_desconto,',
'            v_new.valor_despesa_proforma,',
'            v_new.valor_total_condicao_venda,',
'            v_new.ind_todos_itens_com_entregas_programadas,',
'            v_new.nome_vendedor,',
'            v_new.id_endereco_origem,',
'            v_new.ind_situacao_parcela_pagamento,',
'            v_new.id_listapreco,',
'            v_new.data_confirmacao_pedido,',
'            v_new.id_moeda,',
'            v_new.quantidade_parcelas_pagamento,',
'            v_new.motivo_desconto,',
'            v_new.valor_total_financeiro, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_pedidoimportacao'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_pedidoimportacao'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_pedidoimportacao'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
