'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in imp_pedidoimportacao.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_numero_pedido_importacao(p_numero_pedido_importacao in imp_pedidoimportacao.numero_pedido_importacao%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_numero_pedido_importacao is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''numero_pedido_importacao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from imp_pedidoimportacao where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(numero_pedido_importacao)) = lower(trim(v_new.numero_pedido_importacao)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from imp_pedidoimportacao where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(numero_pedido_importacao)) = lower(trim(v_new.numero_pedido_importacao)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''numero_pedido_importacao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_numero_pedido_importacao(p_numero_pedido_importacao);',
'    end valida_numero_pedido_importacao;     ',
'',
'    procedure valida_ind_status_pedido_importacao(p_ind_status_pedido_importacao in imp_pedidoimportacao.ind_status_pedido_importacao%type) ',
'    is ',
