unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_pedidoimportacao'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_pedidoimportacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_pedidoimportacao'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_pedidoimportacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_pedidoimportacao'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_pedidoimportacao'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_pedidoimportacao%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''numero_pedido_importacao'', p_rec.numero_pedido_importacao, true);',
'        apex_json.write(''ind_status_pedido_importacao'', p_rec.ind_status_pedido_importacao, true);',
'        apex_json.write(''ind_modalidade_importacao'', p_rec.ind_modalidade_importacao, true);',
'        apex_json.write(''id_exportador'', p_rec.id_exportador, true);',
'        apex_json.write(''id_importador'', p_rec.id_importador, true);',
'        apex_json.write(''id_adquirente'', p_rec.id_adquirente, true);',
'        apex_json.write(''id_comprador'', p_rec.id_comprador, true);',
'        apex_json.write(''numero_proforma'', p_rec.numero_proforma, true);',
'        apex_json.write(''id_viatransporte'', p_rec.id_viatransporte, true);',
'        apex_json.write(''id_incoterm'', p_rec.id_incoterm, true);',
'        apex_json.write(''id_local_embarque'', p_rec.id_local_embarque, true);',
'        apex_json.write(''id_local_desembarque'', p_rec.id_local_desembarque, true);',
'        apex_json.write(''id_endereco_destino'', p_rec.id_endereco_destino, true);',
'        apex_json.write(''quantidade_entrega'', p_rec.quantidade_entrega, true);',
'        apex_json.write(''id_condicaopagamento'', p_rec.id_condicaopagamento, true);',
'        apex_json.write(''valor_total_mercadoria'', p_rec.valor_total_mercadoria, true);',
'        apex_json.write(''valor_desconto'', p_rec.valor_desconto, true);',
'        apex_json.write(''valor_despesa_proforma'', p_rec.valor_despesa_proforma, true);',
'        apex_json.write(''valor_total_condicao_venda'', p_rec.valor_total_condicao_venda, true);',
'        apex_json.write(''ind_todos_itens_com_entregas_programadas'', p_rec.ind_todos_itens_com_entregas_programadas, true);',
'        apex_json.write(''nome_vendedor'', p_rec.nome_vendedor, true);',
'        apex_json.write(''id_endereco_origem'', p_rec.id_endereco_origem, true);',
'        apex_json.write(''ind_situacao_parcela_pagamento'', p_rec.ind_situacao_parcela_pagamento, true);',
'        apex_json.write(''id_listapreco'', p_rec.id_listapreco, true);',
'        apex_json.write(''data_confirmacao_pedido'', p_rec.data_confirmacao_pedido, true);',
'        apex_json.write(''id_moeda'', p_rec.id_moeda, true);',
'        apex_json.write(''quantidade_parcelas_pagamento'', p_rec.quantidade_parcelas_pagamento, true);',
'        apex_json.write(''motivo_desconto'', p_rec.motivo_desconto, true);',
'        apex_json.write(''valor_total_financeiro'', p_rec.valor_total_financeiro, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    --',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
'        v_new.valor_total_condicao_venda := nvl(v_new.valor_total_mercadoria,0) - nvl(v_new.valor_desconto,0) + nvl(v_new.valor_despesa_proforma,0);',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
'        pkg_traducao.grava_traducao(v_new.motivo_desconto,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'',
'        bo_ng_pessoa_juridica.atualiza_perfil (',
'            p_id => v_new.id_exportador,',
'            p_ind_perfil => ''E'',',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'        bo_ng_pessoa_juridica.atualiza_perfil (',
'            p_id => v_new.id_importador,',
'            p_ind_perfil => ''I'',',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        altera_mpd_configuracao_ng(',
'            p_id => v_new.id,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        v_new.valor_total_condicao_venda := nvl(v_new.valor_total_mercadoria,0) - nvl(v_new.valor_desconto,0) + nvl(v_new.valor_despesa_proforma,0);',
'        v_new.ind_todos_itens_com_entregas_programadas := verifica_saldo(v_new.id);',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.motivo_desconto,v_new.id_tenant,p_sucesso,p_messages,true,false); ',
'        bo_ng_pessoa_juridica.atualiza_perfil (',
'            p_id => v_new.id_exportador,',
'            p_ind_perfil => ''E'',',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'        bo_ng_pessoa_juridica.atualiza_perfil (',
'            p_id => v_new.id_importador,',
'            p_ind_perfil => ''I'',',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'        if v_operacao = ''GERAR_PARCELAS'' then            ',
'            gerar_parcelas_pagamento(v_new.id, true, p_sucesso, p_messages);            ',
unistr('            -- Ao firmar o pedido na etapa de conclus\00E3o do wizard, gera os t\00EDtulos de pagamento das parcelas do pedido resultantes de ng_condicaopagamento_parcela.ind_evento_gerador_pagamento = 1:'),
'            if v_new.ind_status_pedido_importacao = 3 then',
'                gera_titulo_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                altera_pedidoimportacao_item_quantidade_firmada(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            end if;',
'        elsif v_operacao = ''ALTERA_REGISTRO_RETOMAR_DIGITACAO'' then',
'            altera_entregas_retormar_digitacao(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        elsif v_operacao = ''ALTERA_REGISTRO_DADOS_GERAIS'' then',
'            altera_dependentes_pedido(v_new.id, true, p_sucesso, p_messages);',
'        elsif v_operacao in (''FIRMAR_OU_DESCONFIRMAR'',''FIRMAR_PEDIDO_COM_PROCESSO'') then',
'            altera_entrega_data_disponivel_calculada(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            altera_data_vencimento_parcelas(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            if v_new.ind_status_pedido_importacao = 2 then',
'                altera_titulopagamento_ind_status_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                --altera_invoice_ind_status(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                --altera_processoimportacao_ind_status(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                altera_pedidoimportacao_pagamento_ind_status_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
unistr('            -- Ao firmar/reafirmar o pedido, gera os t\00EDtulos de pagamento das parcelas do pedido resultantes de ng_condicaopagamento_parcela.ind_evento_gerador_pagamento = 1:'),
'            elsif v_new.ind_status_pedido_importacao = 3 then',
'                gerar_parcelas_pagamento(v_new.id, true, p_sucesso, p_messages);',
'                gera_titulo_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                altera_pedidoimportacao_item_quantidade_firmada(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            end if;',
'        elsif v_operacao = ''ALTERA_DESCONTO'' then',
'            altera_valor_desconto_pedido_item(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        elsif v_operacao = ''CANCELA_PEDIDO'' then',
'            altera_titulopagamento_ind_status_pagamento(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            --altera_invoice_ind_status(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            --altera_processoimportacao_ind_status(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
unistr('        -- Tratamento diverg\00EAncias de quantidade nos itens, deve recalcular valor da parcela de pagamento:'),
'        if v_old.valor_total_financeiro != v_new.valor_total_financeiro then',
'            altera_pedidoimportacao_pagamento_valor(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end; ',
