'            select ',
'                b.nome_fantasia as imp_pedidoimportacao$id_tenant, ',
'                a.numero_pedido_importacao as imp_pedidoimportacao$numero_pedido_importacao, ',
'                pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'',''ind_modalidade_importacao'',a.ind_modalidade_importacao) as imp_pedidoimportacao$ind_modalidade_importacao, ',
