' '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767291109620274)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'               a.numero_proforma as imp_pedidoimportacao$numero_proforma                ',
'            from imp_pedidoimportacao a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_exportador',
'            join ng_pessoa_juridica d on d.id_pessoa = a.id_importador',
'            left join ng_pessoa_juridica e on e.id_pessoa = a.id_adquirente',
'            left join ng_pessoa_fisica f on f.id_pessoa = a.id_comprador',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --',
'    function retorna_icone_viatransporte(',
'        p_id in imp_pedidoimportacao.id%type',
'    ) return varchar2 is',
'        l_id_viatransporte number;',
'        l_codigo_siscomex varchar2(50);',
'        l_icone varchar2(4000);',
'        l_title varchar2(4000);',
'    begin',
'        select id_viatransporte into l_id_viatransporte from imp_pedidoimportacao where id = p_id;',
'        select codigo_siscomex into l_codigo_siscomex from ng_viatransporte where id = l_id_viatransporte;',
'        l_title := retorna_texto(''coluna.imp_pedidoimportacao.id_viatransporte.l'');',
'        l_title := l_title || '': '' || to_char(chamar_webservice_traducao (esquema_corrente,''ng_viatransporte'',''descricao_viatransporte'',apex_util.get_session_state(''IDIOMA_LOGADO''),l_id_viatransporte));',
'        if l_codigo_siscomex = ''1'' then',
'            l_icone := ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon fa fa-ship" aria-hidden="true" title="''||l_title||''"></span></div>'';            ',
'        elsif l_codigo_siscomex = ''2'' then',
'            l_icone := ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon fa fa-plane" aria-hidden="true" title="''||l_title||''"></span></div>'';',
'        elsif l_codigo_siscomex = ''3'' then',
'            l_icone := ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon fa fa-bus" aria-hidden="true" title="''||l_title||''"></span></div>'';',
'        elsif l_codigo_siscomex = ''4'' then',
'            l_icone := ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon fa fa-train" aria-hidden="true" title="''||l_title||''"></span></div>'';',
'        else',
'            l_icone := '''';',
'        end if;',
'        return l_icone;',
'    end;',
'    --',
'    procedure reinicia_entregas(',
'        p_id in imp_pedidoimportacao.id%type',
'    ) is',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;        ',
'    begin        ',
'        for entrega_item in (',
'            select a.id from imp_entrega_item a join imp_entrega b on b.id = a.id_entrega where b.id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_entrega_item.exclui_registro(',
'                p_id => entrega_item.id,',
'                p_sucesso => l_sucesso,',
'                p_messages => l_messages',
'            );',
'        end loop;',
'',
'        for entrega in (',
'            select id from imp_entrega where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_entrega.exclui_registro(',
'                p_id => entrega.id,',
'                p_sucesso => l_sucesso,',
'                p_messages => l_messages',
'            );',
'        end loop;        ',
'    end;',
'    --',
'    function verifica_saldo(',
'        p_id in imp_pedidoimportacao.id%type',
'    ) return varchar2 is',
'        l_verifica_itens number;        ',
'        l_verifica_itens_entrega number;        ',
'        l_qtd_item number;',
'        l_qtd_item_entrega number;',
'        l_saldo varchar2(1) := ''N'';',
'    begin',
'        select count(id) into l_verifica_itens from imp_pedidoimportacao_item where id_pedidoimportacao = p_id;',
'        if l_verifica_itens > 0 then',
'            select count(a.id) into l_verifica_itens_entrega from imp_entrega_item a join imp_entrega b on b.id = a.id_entrega where b.id_pedidoimportacao = p_id;',
'            if l_verifica_itens_entrega > 0 then',
'                select sum(quantidade) /*- nvl(sum(quantidade_cancelada),0)*/ into l_qtd_item from imp_pedidoimportacao_item where id_pedidoimportacao = p_id;',
'                select sum(quantidade) /*- nvl(sum(qtd_cancelada),0)*/ into l_qtd_item_entrega from imp_entrega_item a join imp_entrega b on b.id = a.id_entrega where b.id_pedidoimportacao = p_id;',
'                if l_qtd_item = l_qtd_item_entrega then',
'                    l_saldo := ''S'';',
'                end if;',
'            end if;',
'        end if;',
'        return l_saldo;',
'    end;',
'    --',
'    procedure executa_altera_registro(',
'        p_id in imp_pedidoimportacao.id%type',
'    ) is',
'        v_imp_pedidoimportacao imp_pedidoimportacao%rowtype;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        --p_messages := pkg_mensagem.message_record_table();',
'        l_messages := pkg_mensagem.message_record_table();    ',
'',
'        v_operacao := ''EXECUTA_ALTERA_REGISTRO'';   ',
'',
'        select * into v_imp_pedidoimportacao from imp_pedidoimportacao where id = p_id;        ',
'        altera_registro(',
'            p_id_tenant => v_imp_pedidoimportacao.id_tenant,',
'            p_numero_pedido_importacao => v_imp_pedidoimportacao.numero_pedido_importacao,',
'            p_ind_status_pedido_importacao => v_imp_pedidoimportacao.ind_status_pedido_importacao,',
'            p_ind_modalidade_importacao => v_imp_pedidoimportacao.ind_modalidade_importacao,',
'            p_id_exportador => v_imp_pedidoimportacao.id_exportador,',
'            p_id_importador => v_imp_pedidoimportacao.id_importador,',
'            p_id_adquirente => v_imp_pedidoimportacao.id_adquirente,',
'            p_id_comprador => v_imp_pedidoimportacao.id_comprador,',
'            p_nome_vendedor => v_imp_pedidoimportacao.nome_vendedor,            ',
'            p_numero_proforma => v_imp_pedidoimportacao.numero_proforma,',
'            p_id_moeda => v_imp_pedidoimportacao.id_moeda,            ',
'            p_id_viatransporte => v_imp_pedidoimportacao.id_viatransporte,',
'            p_id_incoterm => v_imp_pedidoimportacao.id_incoterm,',
'            p_id_listapreco => v_imp_pedidoimportacao.id_listapreco,',
'            p_id_endereco_origem => v_imp_pedidoimportacao.id_endereco_origem,',
'            p_id_local_embarque => v_imp_pedidoimportacao.id_local_embarque,',
'            p_id_local_desembarque => v_imp_pedidoimportacao.id_local_desembarque,',
'            p_id_endereco_destino => v_imp_pedidoimportacao.id_endereco_destino,',
'            p_quantidade_entrega => v_imp_pedidoimportacao.quantidade_entrega,',
'            p_id_condicaopagamento => v_imp_pedidoimportacao.id_condicaopagamento,',
'            p_quantidade_parcelas_pagamento => v_imp_pedidoimportacao.quantidade_parcelas_pagamento,',
'            p_valor_total_mercadoria => v_imp_pedidoimportacao.valor_total_mercadoria,',
'            p_valor_desconto => v_imp_pedidoimportacao.valor_desconto,',
'            p_valor_despesa_proforma => v_imp_pedidoimportacao.valor_despesa_proforma,',
'            p_valor_total_condicao_venda => v_imp_pedidoimportacao.valor_total_condicao_venda,',
'            p_valor_total_financeiro => v_imp_pedidoimportacao.valor_total_financeiro,',
'            p_data_confirmacao_pedido => v_imp_pedidoimportacao.data_confirmacao_pedido,',
'            p_ind_todos_itens_com_entregas_programadas => verifica_saldo(v_imp_pedidoimportacao.id),',
'            p_ind_situacao_parcela_pagamento => retorna_ind_situacao_parcela_pagamento(v_imp_pedidoimportacao.id),--v_imp_pedidoimportacao.ind_situacao_parcela_pagamento,',
'            p_motivo_desconto => v_imp_pedidoimportacao.motivo_desconto,',
'            p_id => v_imp_pedidoimportacao.id,',
'            p_data_alteracao => v_imp_pedidoimportacao.data_alteracao,            ',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
'        );',
'    end;   ',
'    --',
'    function atualiza_qtd_entregas(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_quantidade_entrega in imp_pedidoimportacao.quantidade_entrega%type',
'    ) return number is',
'        l_verifica_entregas number;',
'        l_qtd_entregas number;',
'        l_qtd_entregas_pedido number;',
'        l_retorno number;',
'    begin',
'        select count(1) into l_verifica_entregas from imp_entrega where id_pedidoimportacao = p_id;',
'        if l_verifica_entregas > 0 then',
'            select max(num_entrega) into l_qtd_entregas from imp_entrega where id_pedidoimportacao = p_id;            ',
'            l_retorno := greatest(l_qtd_entregas, p_quantidade_entrega);',
'        else            ',
'            l_retorno := p_quantidade_entrega;',
'        end if;',
'        return l_retorno;',
'    end atualiza_qtd_entregas;',
'    --',
'    procedure altera_registro_data_alteracao(  ',
'        p_id_tenant in imp_pedidoimportacao.id_tenant%type,',
'        p_numero_pedido_importacao in imp_pedidoimportacao.numero_pedido_importacao%type,',
'        p_ind_status_pedido_importacao in imp_pedidoimportacao.ind_status_pedido_importacao%type,',
'        p_ind_modalidade_importacao in imp_pedidoimportacao.ind_modalidade_importacao%type,',
'        p_id_exportador in imp_pedidoimportacao.id_exportador%type,',
'        p_id_importador in imp_pedidoimportacao.id_importador%type,',
'        p_id_adquirente in imp_pedidoimportacao.id_adquirente%type,',
'        p_id_comprador in imp_pedidoimportacao.id_comprador%type,',
'        p_nome_vendedor in imp_pedidoimportacao.nome_vendedor%type,        ',
'        p_numero_proforma in imp_pedidoimportacao.numero_proforma%type,',
'        p_id_moeda in imp_pedidoimportacao.id_moeda%type,        ',
'        p_id_viatransporte in imp_pedidoimportacao.id_viatransporte%type,',
'        p_id_incoterm in imp_pedidoimportacao.id_incoterm%type,',
'        p_id_listapreco in imp_pedidoimportacao.id_listapreco%type,        ',
'        p_id_endereco_origem in imp_pedidoimportacao.id_endereco_origem%type,',
'        p_id_local_embarque in imp_pedidoimportacao.id_local_embarque%type,',
'        p_id_local_desembarque in imp_pedidoimportacao.id_local_desembarque%type,',
'        p_id_endereco_destino in imp_pedidoimportacao.id_endereco_destino%type,',
'        p_quantidade_entrega in imp_pedidoimportacao.quantidade_entrega%type,',
'        p_id_condicaopagamento in imp_pedidoimportacao.id_condicaopagamento%type,',
'        p_quantidade_parcelas_pagamento in imp_pedidoimportacao.quantidade_parcelas_pagamento%type,',
'        p_valor_total_mercadoria in imp_pedidoimportacao.valor_total_mercadoria%type,',
'        p_valor_desconto in imp_pedidoimportacao.valor_desconto%type,',
'        p_valor_despesa_proforma in imp_pedidoimportacao.valor_despesa_proforma%type,',
'        p_valor_total_condicao_venda in imp_pedidoimportacao.valor_total_condicao_venda%type,',
'        p_data_confirmacao_pedido in imp_pedidoimportacao.data_confirmacao_pedido%type,',
'        p_ind_todos_itens_com_entregas_programadas in imp_pedidoimportacao.ind_todos_itens_com_entregas_programadas%type, ',
'        p_ind_situacao_parcela_pagamento in imp_pedidoimportacao.ind_situacao_parcela_pagamento%type,',
'        p_motivo_desconto in imp_pedidoimportacao.motivo_desconto%type,        ',
'        p_id in imp_pedidoimportacao.id%type,         ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin ',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_registro'';   ',
'        v_pagina := p_pagina;',
'        v_operacao := ''ALTERA_REGISTRO_DATA_ALTERACAO'';',
'        --',
'        select * into v_old from imp_pedidoimportacao where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.numero_pedido_importacao := p_numero_pedido_importacao;',
'        v_new.ind_status_pedido_importacao := p_ind_status_pedido_importacao;',
'        v_new.ind_modalidade_importacao := p_ind_modalidade_importacao;',
'        v_new.id_exportador := p_id_exportador;',
'        v_new.id_importador := p_id_importador;',
'        v_new.id_adquirente := p_id_adquirente;',
'        v_new.id_comprador := p_id_comprador;',
'        v_new.nome_vendedor := p_nome_vendedor;        ',
'        v_new.numero_proforma := p_numero_proforma;',
'        v_new.id_moeda := p_id_moeda;        ',
'        v_new.id_viatransporte := p_id_viatransporte;',
'        v_new.id_incoterm := p_id_incoterm;',
'        v_new.id_listapreco := p_id_listapreco;        ',
'        v_new.id_endereco_origem := p_id_endereco_origem;',
'        v_new.id_local_embarque := p_id_local_embarque;',
'        v_new.id_local_desembarque := p_id_local_desembarque;',
'        v_new.id_endereco_destino := p_id_endereco_destino;',
'        v_new.quantidade_entrega := p_quantidade_entrega;',
'        v_new.id_condicaopagamento := p_id_condicaopagamento;',
'        v_new.quantidade_parcelas_pagamento := p_quantidade_parcelas_pagamento;',
'        v_new.valor_total_mercadoria := p_valor_total_mercadoria;',
'        v_new.valor_desconto := p_valor_desconto;',
'        v_new.valor_despesa_proforma := p_valor_despesa_proforma;',
'        v_new.valor_total_condicao_venda := p_valor_total_condicao_venda;',
'        v_new.data_confirmacao_pedido := p_data_confirmacao_pedido;',
'        v_new.ind_todos_itens_com_entregas_programadas := p_ind_todos_itens_com_entregas_programadas; ',
'        v_new.ind_situacao_parcela_pagamento := p_ind_situacao_parcela_pagamento;',
'        v_new.motivo_desconto := p_motivo_desconto;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de alterar */ ',
'        --antes_alterar;',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update imp_pedidoimportacao set  ',
'            id_tenant = v_new.id_tenant,',
'            numero_pedido_importacao = v_new.numero_pedido_importacao,',
'            ind_status_pedido_importacao = v_new.ind_status_pedido_importacao,',
'            ind_modalidade_importacao = v_new.ind_modalidade_importacao,',
'            id_exportador = v_new.id_exportador,',
'            id_importador = v_new.id_importador,',
'            id_adquirente = v_new.id_adquirente,',
'            id_comprador = v_new.id_comprador,',
'            nome_vendedor = v_new.nome_vendedor,            ',
'            numero_proforma = v_new.numero_proforma,',
'            id_moeda = v_new.id_moeda,            ',
'            id_viatransporte = v_new.id_viatransporte,',
'            id_incoterm = v_new.id_incoterm,',
'            id_listapreco = v_new.id_listapreco,            ',
'            id_endereco_origem = v_new.id_endereco_origem,',
'            id_local_embarque = v_new.id_local_embarque,',
'            id_local_desembarque = v_new.id_local_desembarque,',
'            id_endereco_destino = v_new.id_endereco_destino,',
'            quantidade_entrega = atualiza_qtd_entregas(p_id,v_new.quantidade_entrega),',
'            id_condicaopagamento = v_new.id_condicaopagamento,',
'            quantidade_parcelas_pagamento = v_new.quantidade_parcelas_pagamento,',
'            valor_total_mercadoria = v_new.valor_total_mercadoria,',
'            valor_desconto = v_new.valor_desconto,',
'            valor_despesa_proforma = v_new.valor_despesa_proforma,',
'            valor_total_condicao_venda = v_new.valor_total_condicao_venda,',
'            data_confirmacao_pedido = v_new.data_confirmacao_pedido,',
'            ind_todos_itens_com_entregas_programadas = verifica_saldo(p_id),',
'            ind_situacao_parcela_pagamento = v_new.ind_situacao_parcela_pagamento, ',
'            motivo_desconto = v_new.motivo_desconto,',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'        --',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(',
'            p_encadeado => true,',
'            p_sucesso => p_sucesso,',
'            p_messages => v_messages',
'        );',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        exception ',
'            when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);       ',
'        --',
'    end altera_registro_data_alteracao;    ',
'    --',
'    procedure altera_registro_dados_gerais(',
'        p_ind_modalidade_importacao in imp_pedidoimportacao.ind_modalidade_importacao%type,',
'        p_id_exportador in imp_pedidoimportacao.id_exportador%type,',
'        p_id_importador in imp_pedidoimportacao.id_importador%type,',
'        p_id_adquirente in imp_pedidoimportacao.id_adquirente%type,        ',
'        p_id_incoterm in imp_pedidoimportacao.id_incoterm%type,',
'        p_id_viatransporte in imp_pedidoimportacao.id_viatransporte%type,',
'        p_id_moeda in imp_pedidoimportacao.id_moeda%type,        ',
'        p_id_comprador in imp_pedidoimportacao.id_comprador%type,',
'        p_id_listapreco in imp_pedidoimportacao.id_listapreco%type,        ',
'        p_nome_vendedor in imp_pedidoimportacao.nome_vendedor%type,        ',
'        p_numero_proforma in imp_pedidoimportacao.numero_proforma%type,',
'        p_id in imp_pedidoimportacao.id%type,         ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin ',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_registro_dados_gerais'';   ',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;        ',
'        v_new := v_old;        ',
'',
'        v_new.ind_modalidade_importacao := p_ind_modalidade_importacao;',
'        v_new.id_exportador := p_id_exportador;',
'        v_new.id_importador := p_id_importador;',
'        v_new.id_adquirente := p_id_adquirente;        ',
'        v_new.id_incoterm := p_id_incoterm;',
'        v_new.id_viatransporte :=p_id_viatransporte;',
'        v_new.id_moeda := p_id_moeda;',
'        v_new.id_comprador := p_id_comprador;',
'        v_new.id_listapreco := p_id_listapreco;',
'        v_new.nome_vendedor := p_nome_vendedor;        ',
'        v_new.numero_proforma := p_numero_proforma;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_REGISTRO_DADOS_GERAIS'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_registro_dados_gerais;',
'    --',
'    procedure cancela_registro(  ',
'        p_id in imp_pedidoimportacao.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is        ',
'        v_qtd_status number;',
'        v_imp_pedidoimportacao imp_pedidoimportacao%rowtype; ',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.cancela_registro'';',
'        v_operacao := ''CANCELA_PEDIDO'';',
'',
'        select * into v_imp_pedidoimportacao from imp_pedidoimportacao where id = p_id;        ',
'        select count(*) into v_qtd_status from imp_entrega where id_pedidoimportacao = p_id and ind_status_entrega = 4;',
'        /* Executa rotinas antes de cancelar */   ',
'        if v_qtd_status > 0 then ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_codigo_mensagem => ''65'',',
'                p_nome_campo => ''data_confirmacao_pedido'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        else',
'            altera_registro(',
'            p_id_tenant => v_imp_pedidoimportacao.id_tenant,',
'            p_numero_pedido_importacao => v_imp_pedidoimportacao.numero_pedido_importacao,',
'            p_ind_status_pedido_importacao => 5,',
'            p_ind_modalidade_importacao => v_imp_pedidoimportacao.ind_modalidade_importacao,',
'            p_id_exportador => v_imp_pedidoimportacao.id_exportador,',
'            p_id_importador => v_imp_pedidoimportacao.id_importador,',
'            p_id_adquirente => v_imp_pedidoimportacao.id_adquirente,',
'            p_id_comprador => v_imp_pedidoimportacao.id_comprador,',
'            p_nome_vendedor => v_imp_pedidoimportacao.nome_vendedor,            ',
'            p_numero_proforma => v_imp_pedidoimportacao.numero_proforma,',
'            p_id_moeda => v_imp_pedidoimportacao.id_moeda,            ',
'            p_id_viatransporte => v_imp_pedidoimportacao.id_viatransporte,',
'            p_id_incoterm => v_imp_pedidoimportacao.id_incoterm,',
'            p_id_listapreco => v_imp_pedidoimportacao.id_listapreco,            ',
'            p_id_endereco_origem => v_imp_pedidoimportacao.id_endereco_origem,',
'            p_id_local_embarque => v_imp_pedidoimportacao.id_local_embarque,',
'            p_id_local_desembarque => v_imp_pedidoimportacao.id_local_desembarque,',
'            p_id_endereco_destino => v_imp_pedidoimportacao.id_endereco_destino,',
'            p_quantidade_entrega => v_imp_pedidoimportacao.quantidade_entrega,',
'            p_id_condicaopagamento => v_imp_pedidoimportacao.id_condicaopagamento,',
'            p_quantidade_parcelas_pagamento => v_imp_pedidoimportacao.quantidade_parcelas_pagamento,',
'            p_valor_total_mercadoria => v_imp_pedidoimportacao.valor_total_mercadoria,',
'            p_valor_desconto => v_imp_pedidoimportacao.valor_desconto,',
'            p_valor_despesa_proforma => v_imp_pedidoimportacao.valor_despesa_proforma,',
'            p_valor_total_condicao_venda => v_imp_pedidoimportacao.valor_total_condicao_venda,',
'            p_valor_total_financeiro => v_imp_pedidoimportacao.valor_total_financeiro,',
'            p_data_confirmacao_pedido => v_imp_pedidoimportacao.data_confirmacao_pedido,',
'            p_ind_todos_itens_com_entregas_programadas => verifica_saldo(v_imp_pedidoimportacao.id),',
'            p_ind_situacao_parcela_pagamento => v_imp_pedidoimportacao.ind_situacao_parcela_pagamento,',
'            p_motivo_desconto => v_imp_pedidoimportacao.motivo_desconto,',
'            p_id => v_imp_pedidoimportacao.id,',
'            p_data_alteracao => v_imp_pedidoimportacao.data_alteracao,            ',
'            p_encadeado => true,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'            );',
'        end if;   ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        exception ',
'            when pk_exceptions.e_erro then',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);   ',
'    end cancela_registro;',
'    --',
'    procedure conclui_pedido(        ',
'        p_ind_status_pedido_importacao in imp_pedidoimportacao.ind_status_pedido_importacao%type,',
'        p_data_confirmacao_pedido in imp_pedidoimportacao.data_confirmacao_pedido%type,',
'        p_ind_situacao_parcela_pagamento in imp_pedidoimportacao.ind_situacao_parcela_pagamento%type,',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.conclui_pedido'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.ind_status_pedido_importacao := p_ind_status_pedido_importacao;',
'        v_new.data_confirmacao_pedido := p_data_confirmacao_pedido;',
'        v_new.ind_situacao_parcela_pagamento:= p_ind_situacao_parcela_pagamento;        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''GERAR_PARCELAS'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end conclui_pedido;',
'    --',
'    procedure gerar_parcelas_pagamento(',
'        p_id in imp_pedidoimportacao.id%type,        ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_ind_status_pedido_importacao number;',
'        l_data_confirmacao_pedido imp_pedidoimportacao.data_confirmacao_pedido%type;        ',
'        l_verifica_parcelas_existentes number;',
'        l_id_pedidoimportacao_pagamento number;        ',
'        l_data_vencimento_prevista imp_pedidoimportacao_pagamento.data_vencimento_prevista%type;',
'    begin',
unistr('        -- Verifica status e data de confirma\00E7\00E3o do pedido'),
'        select ',
'            ind_status_pedido_importacao, ',
'            data_confirmacao_pedido ',
'        into ',
'            l_ind_status_pedido_importacao,',
'            l_data_confirmacao_pedido',
'        from imp_pedidoimportacao where id = p_id;',
'',
unistr('        -- Gerencia as parcelas somente para pedido que n\00E3o estejam em digita\00E7\00E3o'),
'        if l_ind_status_pedido_importacao <> 1 then',
'            -- Verifica se existem parcelas antigas geradas para este pedido',
'            select count(1) into l_verifica_parcelas_existentes from imp_pedidoimportacao_pagamento where id_pedidoimportacao = p_id;',
'            if l_verifica_parcelas_existentes > 0 then',
'                -- Exclui as parcelas antigas',
'                for old_parcela in (',
'                    select id from imp_pedidoimportacao_pagamento where id_pedidoimportacao = p_id',
'                ) loop',
'                    bo_imp_pedidoimportacao_pagamento.exclui_registro(old_parcela.id, true, p_sucesso, p_messages);',
'                end loop;',
'            end if;',
'',
'            -- Gera as novas parcelas com base no valor do pedido',
'            for parcela_pedido in (',
'                select ',
'                    distinct d.id,                ',
'                    a.id_tenant,',
'                    d.numero_parcela,',
'                    d.percentual,                    ',
'                    nvl(((d.percentual / 100) * a.valor_total_financeiro),0) valor,',
'                    d.qtd_dias_evento',
'                from imp_pedidoimportacao a ',
'                join imp_entrega b on b.id_pedidoimportacao = a.id',
'                join ng_condicaopagamento c on c.id = a.id_condicaopagamento',
'                join ng_condicaopagamento_parcela d on d.id_condicaopagamento = c.id',
'                where a.id = p_id',
'                and d.ind_evento_gerador_pagamento = 1',
'            ) loop                ',
'                bo_imp_pedidoimportacao_pagamento.inclui_registro(',
'                    p_id_tenant => parcela_pedido.id_tenant,',
'                    p_id_pedidoimportacao => p_id,',
'                    p_id_entrega => null,',
'                    p_numero_parcela => parcela_pedido.numero_parcela,',
'                    p_percentual => parcela_pedido.percentual,',
'                    p_valor => parcela_pedido.valor,',
'                    p_data_vencimento_prevista => (l_data_confirmacao_pedido + parcela_pedido.qtd_dias_evento),',
'                    p_data_vencimento_real => null,',
'                    p_ind_status_pagamento => 1,',
'                    p_ind_multa_atraso_pagamento => ''N'',',
'                    p_valor_multa => null,',
'                    p_percentual_multa => null,',
'                    p_periodo_multa => null,',
'                    p_ind_bloqueado => ''N'',',
'                    p_condicao_desbloqueio => null,',
'                    p_data_desbloqueio => null,',
'                    p_id_usuario_desbloqueio => null,',
'                    p_instrucao_contas_pagar => null,',
'                    p_id => l_id_pedidoimportacao_pagamento,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'',
'            -- Gera as novas parcelas com base nos valores das entregas',
'            for parcela_entrega in (',
'                select ',
'                    distinct d.id,                ',
'                    a.id_tenant,',
'                    b.id id_entrega,',
'                    d.numero_parcela,',
'                    d.percentual,                    ',
'                    nvl(((d.percentual / 100) * b.valor_total_financeiro),0) valor,',
'                    ind_evento_gerador_pagamento,',
'                    qtd_dias_evento,',
'                    b.id_inv'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767291109620274)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'oice,',
'                    coalesce(data_disponivel_real, data_disponivel_informada, data_disponivel_calculada) data_disponivel,',
'                    coalesce(data_embarque_real, data_embarque_informada, data_embarque_calculada) data_embarque,',
'                    coalesce(data_desembarque_real, data_desembarque_informada, data_desembarque_calculada) data_desembarque',
'                from imp_pedidoimportacao a ',
'                join imp_entrega b on b.id_pedidoimportacao = a.id',
'                join ng_condicaopagamento c on c.id = a.id_condicaopagamento',
'                join ng_condicaopagamento_parcela d on d.id_condicaopagamento = c.id',
'                where a.id = p_id',
'                and d.ind_evento_gerador_pagamento <> 1',
'            ) loop                ',
'                -- Executa as regras para atribuir corretamente a data de vencimento prevista',
'                if parcela_entrega.ind_evento_gerador_pagamento = 1 then',
'                    l_data_vencimento_prevista := l_data_confirmacao_pedido + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 2 and parcela_entrega.id_invoice is not null then',
'                    select data_invoice into l_data_vencimento_prevista from imp_invoice where id = parcela_entrega.id_invoice;',
'                    if l_data_vencimento_prevista is not null then',
'                        l_data_vencimento_prevista := l_data_vencimento_prevista + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                    else',
'                        l_data_vencimento_prevista := null;',
'                    end if;',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 5 and parcela_entrega.data_disponivel is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_disponivel + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 6 and parcela_entrega.data_embarque is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_embarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 7 and parcela_entrega.data_desembarque is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_desembarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                else',
'                    l_data_vencimento_prevista := null;',
'                end if;',
'',
'                bo_imp_pedidoimportacao_pagamento.inclui_registro(',
'                    p_id_tenant => parcela_entrega.id_tenant,',
'                    p_id_pedidoimportacao => p_id,',
'                    p_id_entrega => parcela_entrega.id_entrega,',
'                    p_numero_parcela => parcela_entrega.numero_parcela,',
'                    p_percentual => parcela_entrega.percentual,',
'                    p_valor => parcela_entrega.valor,',
'                    p_data_vencimento_prevista => l_data_vencimento_prevista,',
'                    p_data_vencimento_real => null,',
'                    p_ind_status_pagamento => 1,',
'                    p_ind_multa_atraso_pagamento => ''N'',',
'                    p_valor_multa => null,',
'                    p_percentual_multa => null,',
'                    p_periodo_multa => null,',
'                    p_ind_bloqueado => ''N'',',
'                    p_condicao_desbloqueio => null,',
'                    p_data_desbloqueio => null,',
'                    p_id_usuario_desbloqueio => null,',
'                    p_instrucao_contas_pagar => null,',
'                    p_id => l_id_pedidoimportacao_pagamento,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'    end gerar_parcelas_pagamento;',
'    --',
'    procedure altera_id_condicaopagamento(        ',
'        p_id_condicaopagamento in imp_pedidoimportacao.id_condicaopagamento%type,',
'        p_quantidade_parcelas_pagamento in imp_pedidoimportacao.quantidade_parcelas_pagamento%type,',
'        p_ind_situacao_parcela_pagamento in imp_pedidoimportacao.ind_situacao_parcela_pagamento%type,',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_id_condicaopagamento'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.id_condicaopagamento := p_id_condicaopagamento;',
'        v_new.quantidade_parcelas_pagamento := p_quantidade_parcelas_pagamento;',
'        v_new.ind_situacao_parcela_pagamento:= p_ind_situacao_parcela_pagamento;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''GERAR_PARCELAS'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_id_condicaopagamento;',
'    --',
'    procedure altera_quantidade_entrega(',
'        p_quantidade_entrega in imp_pedidoimportacao.quantidade_entrega%type default null,',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_quantidade_entrega imp_pedidoimportacao.quantidade_entrega%type;',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_quantidade_entrega'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        if p_quantidade_entrega is null then',
'            select count(1) into l_quantidade_entrega from imp_entrega where id_pedidoimportacao = p_id;',
'        else',
'            l_quantidade_entrega := p_quantidade_entrega;',
'        end if;',
'',
'        v_new.quantidade_entrega:= l_quantidade_entrega;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_QUANTIDADE_ENTREGA'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_quantidade_entrega;',
'    --',
'    procedure repetir_pedido(',
'        p_numero_pedido_importacao in imp_pedidoimportacao.numero_pedido_importacao%type,',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_new_id_pedidoimportacao number;',
'        l_id_item number;',
'    begin        ',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.repetir_pedido'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.id := null;',
'        v_new.numero_pedido_importacao:= p_numero_pedido_importacao;',
'        v_new.ind_status_pedido_importacao := 1;',
'        v_new.ind_situacao_parcela_pagamento := ''N'';',
'        v_new.ind_todos_itens_com_entregas_programadas := ''N'';',
'        v_new.quantidade_entrega := 0;',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_inclusao := sysdate;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''REPETIR_PEDIDO'';',
'',
'        cria(p_encadeado, p_sucesso, p_messages, l_new_id_pedidoimportacao);',
'',
'        for item in (',
'            select * from imp_pedidoimportacao_item where id_pedidoimportacao = p_id',
'        ) loop            ',
'            bo_imp_pedidoimportacao_item.inclui_registro(                ',
'                p_id_tenant => item.id_tenant,',
'                p_id_pedidoimportacao => l_new_id_pedidoimportacao,',
'                p_id_item => item.id_item,',
'                p_num_sequencia_item => item.num_sequencia_item,',
'                p_id_unidademedida => item.id_unidademedida,',
'                p_quantidade_firmada => item.quantidade_firmada,',
'                p_quantidade => item.quantidade,',
'                p_peso_unitario => item.peso_unitario,',
'                p_peso_liquido_total => item.peso_liquido_total,',
'                p_valor_unitario => item.valor_unitario,',
'                p_valor_desconto_unitario => item.valor_desconto_unitario,',
'                p_valor_total => item.valor_total,',
'                p_valor_desconto_pedido_item => item.valor_desconto_pedido_item,',
'                p_valor_desconto_pedido_item_unitario => item.valor_desconto_pedido_item_unitario,',
'                p_valor_despesaproforma => item.valor_despesaproforma,',
'                p_valor_despesaproforma_unitario => item.valor_despesaproforma_unitario,',
'                p_id_naturezaoperacao => item.id_naturezaoperacao,',
'                p_num_solicitacao_compra => item.num_solicitacao_compra,',
'                p_nome_solicitante => item.nome_solicitante,',
'                p_quantidade_programada_entrega => 0,--item.quantidade_programada_entrega,',
'                p_quantidade_programar_entrega => item.quantidade,--item.quantidade_programar_entrega,',
'                p_quantidade_cancelada => 0,--item.quantidade_cancelada,',
'                p_quantidade_faturada => 0,--item.quantidade_faturada,',
'                p_quantidade_faturar => 0,--item.quantidade_faturar,',
'                p_id_fabricante => item.id_fabricante,',
'                p_id_ncm => item.id_ncm,',
'                p_ind_bloqueio_embarque_ate_deferimento_li => item.ind_bloqueio_embarque_ate_deferimento_li,',
'                p_ind_licenca_importacao => item.ind_licenca_importacao,',
'                p_id_centrocusto => item.id_centrocusto,',
'                p_ind_finalidade => item.ind_finalidade,',
'                p_numero_ato_concessorio => item.numero_ato_concessorio,',
'                p_data_entrega_desejada => item.data_entrega_desejada,                ',
'                p_id => l_id_item,                ',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'',
'    end repetir_pedido;',
'    --',
'    function retorna_ind_situacao_parcela_pagamento(',
'        p_id in imp_pedidoimportacao.id%type',
'    ) return varchar2 is ',
'        l_verifica_parcelas number;',
'    begin',
'        select count(1) into l_verifica_parcelas from imp_pedidoimportacao_pagamento where id_pedidoimportacao = p_id;',
'        if l_verifica_parcelas > 0 then',
'            return ''S'';',
'        else',
'            return ''N'';',
'        end if;',
'    end retorna_ind_situacao_parcela_pagamento;',
'    --',
'    procedure altera_dependentes_pedido(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
'    begin  ',
'        -- Verificar necessidade de alterar os itens do pedido com os mesmos valores(?):',
'        -- for item in (',
'        --     select * from imp_pedidoimportacao_item where id_pedidoimportacao = p_id',
'        -- ) loop',
'        --     bo_imp_pedidoimportacao_item.altera_registro(',
'        --         p_id_tenant => item.id_tenant,',
'        --         p_id_pedidoimportacao => item.id_pedidoimportacao,',
'        --         p_id_item => item.id_item,',
'        --         p_num_sequencia_item => item.num_sequencia_item,',
'        --         p_id_unidademedida => item.id_unidademedida,',
'        --         p_quantidade_firmada => item.quantidade_firmada,',
'        --         p_quantidade => item.quantidade,',
'        --         p_peso_unitario => item.peso_unitario,',
'        --         p_peso_liquido_total => item.peso_liquido_total,',
'        --         p_valor_unitario => item.valor_unitario,',
'        --         p_valor_desconto_unitario => item.valor_desconto_unitario,',
'        --         p_valor_total => item.valor_total,',
'        --         p_valor_desconto_pedido_item => item.valor_desconto_pedido_item,',
'        --         p_valor_desconto_pedido_item_unitario => item.valor_desconto_pedido_item_unitario,',
'        --         p_valor_despesaproforma => item.valor_despesaproforma,',
'        --         p_valor_despesaproforma_unitario => item.valor_despesaproforma_unitario,',
'        --         p_id_fabricante => item.id_fabricante,',
'        --         p_id_ncm => item.id_ncm,',
'        --         p_ind_licenca_importacao => item.ind_licenca_importacao,',
'        --         p_ind_bloqueio_embarque_ate_deferimento_li => item.ind_bloqueio_embarque_ate_deferimento_li,',
'        --         p_id_naturezaoperacao => item.id_naturezaoperacao,',
'        --         p_id_centrocusto => item.id_centrocusto,',
'        --         p_num_solicitacao_compra => item.num_solicitacao_compra,',
'        --         p_nome_solicitante => item.nome_solicitante,',
'        --         p_data_entrega_desejada => item.data_entrega_desejada,',
'        --         p_quantidade_programada_entrega => item.quantidade_programada_entrega,',
'        --         p_quantidade_programar_entrega => item.quantidade_programar_entrega,',
'        --         p_quantidade_faturada => item.quantidade_faturada,',
'        --         p_quantidade_cancelada => item.quantidade_cancelada,',
'        --         p_quantidade_faturar => item.quantidade_faturar,',
'        --         p_id => item.id,',
'        --         p_data_alteracao => item.data_alteracao,',
'        --         p_encadeado => true,',
'        --         p_sucesso => p_sucesso,',
'        --         p_messages => p_messages',
'        --     );',
'        -- end loop;',
'',
'        for entrega in (',
'            select * from imp_entrega where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_entrega.altera_registro(',
'                p_id_tenant => entrega.id_tenant,',
'                p_id_pedidoimportacao => entrega.id_pedidoimportacao,',
'                p_num_entrega => entrega.num_entrega,',
'                p_id_processoimportacao => entrega.id_processoimportacao,',
'                p_ind_modalidade_importacao => v_new.ind_modalidade_importacao,--entrega.ind_modalidade_importacao,',
'                p_id_exportador => v_new.id_exportador,--entrega.id_exportador,',
'                p_id_importador => v_new.id_importador,--entrega.id_importador,',
'                p_id_adquirente => v_new.id_adquirente,--entrega.id_adquirente,',
'                p_id_endereco_origem => entrega.id_endereco_origem,',
'                p_id_local_embarque => entrega.id_local_embarque,',
'                p_id_local_desembarque => entrega.id_local_desembarque,',
'                p_id_endereco_destino => entrega.id_endereco_destino,',
'                p_id_viatransporte => v_new.id_viatransporte,--entrega.id_viatransporte,',
'                p_id_incoterm => v_new.id_incoterm,--entrega.id_incoterm,',
'                p_ind_status_entrega => entrega.ind_status_entrega,',
'                p_data_disponivel_calculada => entrega.data_disponivel_calculada,',
'                p_data_disponivel_informada => entrega.data_disponivel_informada,',
'                p_data_disponivel_real => entrega.data_disponivel_real,',
'                p_data_embarque_calculada => entrega.data_embarque_calculada,',
'                p_data_embarque_informada => entrega.data_embarque_informada,',
'                p_data_embarque_real => entrega.data_embarque_real,',
'                p_data_desembarque_calculada => entrega.data_desembarque_calculada,',
'                p_data_desembarque_informada => entrega.data_desembarque_informada,',
'                p_data_desembarque_real => entrega.data_desembarque_real,',
'                p_data_nacionalizacao_calculada => entrega.data_nacionalizacao_calculada,',
'                p_data_nacionalizacao_informada => entrega.data_nacionalizacao_informada,',
'                p_data_nacionalizacao_real => entrega.data_nacionalizacao_real,',
'                p_data_recebimento_calculada => entrega.data_recebimento_calculada,',
'                p_data_recebimento_informada => entrega.data_recebimento_informada,',
'                p_data_recebimento_real => entrega.data_recebimento_real,',
'                p_valor_total_condicao_venda => entrega.valor_total_condicao_venda,',
'                p_valor_total_financeiro => entrega.valor_total_financeiro,',
'                p_id_invoice => entrega.id_invoice,',
'                p_id => entrega.id,',
'                p_data_alteracao => entrega.data_alteracao,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_dependentes_pedido;',
'    --',
'    procedure popula_pedido_importacao (',
'        p_qtd_registros in number,        -- quantidade de registros a gerar',
unistr('        p_sufixo        in varchar2,      -- sufixo para o c\00F3digo do pedido'),
'        p_situacao      in number          -- 1-em digitacao / 2-A firmar / 3-Firmado / 4-Finalizado / 5-Cancelado',
'    ) is',
'        v_id         number;',
'        v_sucesso    clob;',
'        v_messages   pkg_mensagem.message_record_table;',
'    begin',
'        for i in 1 .. p_qtd_registros loop',
'            inclui_registro(',
'                p_id_tenant                       => 43,',
'                p_numero_pedido_importacao        => ''PI'' || lpad(i, 5, ''0'') || ''/'' || p_sufixo,',
'                p_ind_modalidade_importacao       => 1,',
'                p_id_exportador                   => 901,',
'                p_id_importador                   => 697,',
'                p_id_adquirente                   => null,',
'                p_id_comprador                    => null,',
'                p_nome_vendedor                   => p_sufixo,                ',
'                p_numero_proforma                 => null,            ',
'                p_id_moeda                        => 1,            ',
'                p_id_viatransporte                => 124,',
'                p_id_incoterm                     => 21,',
'                p_id_condicaopagamento            => 282,',
'                p_quantidade_parcelas_pagamento   => 2,',
'                p_id_listapreco                   => 203,',
'                p_id_endereco_origem              => null,',
'                p_id_local_embarque               => null,',
'                p_id_local_desembarque            => null,',
'                p_id_endereco_destino             => null,',
'                p_quantidade_entrega              => 1,            ',
'                p_valor_total_mercadoria          => 6010,',
'                p_valor_desconto                  => 10200,',
'                p_valor_despesa_proforma          => null,',
'                p_valor_total_condicao_venda      => 6010,',
'                p_valor_total_financeiro          => 6010,',
'                p_data_confirmacao_pedido         => null,',
'                p_ind_todos_itens_com_entregas_programadas => ''N'',',
'                p_ind_status_pedido_importacao    => p_situacao,',
'                p_ind_situacao_parcela_pagamento  => ''N'',',
'                p_motivo_desconto                 => null,',
'                p_id                              => v_id, ',
'                p_sucesso                         => v_sucesso,',
'                p_messages                        => v_messages             ',
'            );',
'',
'            -- Log opcional',
'            if mod(i, 1000) = 0 then',
'                dbms_output.put_line(''Inseridos: '' || i);',
'            end if;',
'        end loop;',
'',
'        dbms_output.put_line(''Carga finalizada com '' || p_qtd_registros || '' registros. Sufixo usado: '' || p_sufixo);',
'    end;',
'    --',
'    function retorna_auditoria_log(',
'        p_dados_novos in srv_auditoria_log.dados_novos%type,',
'        p_nome_coluna in varchar2',
'    ) return varchar2 is',
'        l_resultado varchar2(32000);',
'        l_sql       varchar2(32000);',
'    begin',
'        l_sql := ''',
'            select jt."'' || p_nome_coluna || ''"',
'            from json_table(:1, ''''$[*]''''',
'                columns (',
'                    "'' || p_nome_coluna || ''" varchar2(32000) path ''''$.'' || p_nome_coluna || ''''''',
'                )',
'            ) jt',
'        '';',
'',
'        execute immediate l_sql into l_resultado using p_dados_novos;',
'',
'        return l_resultado;',
'    exception',
'        when no_data_found then',
'            return null;',
'    end retorna_auditoria_log;',
'    --',
'    procedure altera_mpd_configuracao_ng(',
'        p_id in imp_pedidoimportacao.id%type,        ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant number;',
'        l_numero_pedido_importacao varchar2(20);',
'        l_configuracao mpd_configuracao_ng%rowtype;',
'        l_aux_prefixo varchar2(20);',
'        l_aux_quantidade_digitos number;',
'        l_aux_sufixo varchar2(20);',
'        l_novo_numero_pedido_importacao varchar2(20);',
'    begin',
'        select id_tenant, numero_pedido_importacao into l_id_tenant, l_numero_pedido_importacao from imp_pedidoimportacao where id = p_id;        ',
'        select * into l_configuracao from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 4;',
'',
'        select valor_string into l_aux_prefixo from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 3;        ',
'        select valor_inteiro into l_aux_quantidade_digitos from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 5;',
'        select valor_string into l_aux_sufixo from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 6;',
'',
'        l_novo_numero_pedido_importacao := l_aux_prefixo || lpad(to_char(l_configuracao.valor_inteiro + 1), l_aux_quantidade_digitos,''0'')||l_aux_sufixo;        ',
'        if l_novo_numero_pedido_importacao = l_numero_pedido_importacao then',
'            bo_mpd_configuracao_ng.altera_registro(',
'                p_id_tenant => l_configuracao.id_tenant,',
'                p_id_entidade => l_configuracao.id_entidade,',
'                p_id_registro => l_configuracao.id_registro,',
'                p_descricao_configuracao => l_configuracao.descricao_configuracao,',
'                p_codigo_configuracao => l_configuracao.codigo_configuracao,',
'                p_ind_tipo_dado => l_configuracao.ind_tipo_dado,',
'                p_valor_inteiro => (l_configuracao.valor_inteiro + 1),',
'                p_valor_decimal => l_configuracao.valor_decimal,',
'                p_quantidade_decimal => l_configuracao.quantidade_decimal,',
'                p_valor_string => l_configuracao.valor_string,',
'                p_valor_data => l_configuracao.valor_data,',
'                p_valor_data_hora => l_configuracao.valor_data_hora,',
'                p_valor_dominio => l_configuracao.valor_dominio,',
'                p_ind_grupo_funcionalidade => l_configuracao.ind_grupo_funcionalidade,',
'                p_id => l_configuracao.id,',
'                p_data_alteracao => l_configuracao.data_alteracao,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end altera_mpd_configuracao_ng;',
'    --',
'    function retorna_numero_pedido_importacao(',
'        p_id_tenant in imp_pedidoimportacao.id_tenant%type',
'    ) return varchar2 is',
'        l_verifica_configuracao number;',
'        l_configuracao number;',
'        l_aux_prefixo varchar2(20);',
'        l_aux_numero varchar2(20);',
'        l_aux_quantidade_digitos number;',
'        l_aux_sufixo varchar2(20);',
'        l_numero_pedido_importacao varchar2(20);',
'    begin',
'        select count(1) into l_verifica_configuracao',
'        from mpd_configuracao_ng a join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id ',
'        where a.id_tenant = p_id_tenant and a.codigo_configuracao = 2 and b.id = a.valor_dominio;',
'',
'        if l_verifica_configuracao > 0 then',
'            select codigo_dominio into l_configuracao ',
'            from mpd_configuracao_ng a join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id ',
'            where a.id_tenant = p_id_tenant and a.codigo_configuracao = 2 and b.id = a.valor_dominio;',
'',
'            if l_configuracao = 2 then',
'                select valor_string into l_aux_prefixo from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 3;',
'                select (valor_inteiro + 1) into l_aux_numero from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 4;',
'                select valor_inteiro into l_aux_quantidade_digitos from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 5;',
'                select valor_string into l_aux_sufixo from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 6;            ',
'',
'                l_numero_pedido_importacao := l_aux_prefixo||lpad(l_aux_numero, l_aux_quantidade_digitos, ''0'')||l_aux_sufixo;            ',
'            end if;',
'        end if;',
'        return l_numero_pedido_importacao;',
'    exception ',
'        when others then',
'            return '''';',
'    end retorna_numero_pedido_importacao;',
'    --',
'    procedure firmar_pedido(        ',
'        p_data_confirmacao_pedido in imp_pedidoimportacao.data_confirmacao_pedido%type,        ',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.firmar_pedido'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.data_confirmacao_pedido := p_data_confirmacao_pedido;        ',
'        v_new.ind_status_pedido_importacao := 3; --(Firmado)',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''FIRMAR_OU_DESCONFIRMAR'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end firmar_pedido;',
'    --',
'    procedure desconfirmar_pedido(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_verifica_invoice number;',
'        l_verifica_processo number;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.desconfirmar_pedido'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        select count(1) into l_verifica_invoice from imp_entrega where id_pedidoimportacao = p_id and id_invoice is not null;',
'        select count(1) into l_verifica_processo from imp_entrega a join imp_processoimportacao b on b.id = a.id_processoimportacao ',
'        where a.id_pedidoimportacao = p_id and b.ind_status not in (1,2);',
'',
'        if l_verifica_invoice > 0 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''126'',',
'                p_nome_campo => ''ind_status_pedido_importacao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        elsif l_verifica_processo > 0 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''128'',',
'                p_nome_campo => ''ind_status_pedido_importacao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        else',
'            v_new.data_confirmacao_pedido := null;        ',
'            v_new.ind_status_pedido_importacao := 2; --(A firmar)',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''FIRMAR_OU_DESCONFIRMAR'';',
'',
'            grava(p_id, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end desconfirmar_pedido;',
'    --',
'    procedure altera_entrega_data_disponivel_calculada(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        if v_new.data_confirmacao_pedido is not null then',
'            for entrega in (',
'                select ',
'                    a.id, b.data_confirmacao_pedido, bo_ng_leadtime.retorna_quantidade_dias(a.id_tenant, 1, a.id_endereco_origem) quantidade_dias',
'                from imp_entrega a',
'      '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767291109620274)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'          join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
