'',
'        if nvl(p_valor_desconto,0) > 0 and p_motivo_desconto is null then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.motivo_desconto''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''motivo_desconto'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        else',
'            v_new.valor_desconto := p_valor_desconto;',
'            v_new.motivo_desconto := p_motivo_desconto;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''ALTERA_DESCONTO'';',
'',
'            grava(p_id, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_desconto;',
'    --',
'    procedure altera_data_vencimento_parcelas(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_data_vencimento_prevista imp_pedidoimportacao_pagamento.data_vencimento_prevista%type;',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_data_vencimento_parcelas'';',
'',
'        for parcela in (',
'            select id from imp_pedidoimportacao_pagamento where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_pedidoimportacao_pagamento.altera_data_vencimento_prevista(',
'                p_data_vencimento_prevista => bo_imp_pedidoimportacao_pagamento.retorna_data_vencimento_prevista(parcela.id),',
'                p_id => parcela.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
