'    --',
'    function retorna_valor_desconto_pedido_item(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_id_pedidoimportacao_item in imp_pedidoimportacao_item.id%type',
'    ) return number is',
'        l_valor_total_mercadoria number;',
'        l_valor_desconto_total   number;',
'        l_resultado number;',
'        l_base_int  number;',
'        l_soma_base_int number;',
'        l_total_int     number;',
'        l_resto         number;',
'        l_item_ajuste number;',
'    begin',
'        -- Total da mercadoria:',
'        select sum(a.valor_total)',
'        into l_valor_total_mercadoria',
'        from imp_pedidoimportacao_item a',
'        join imp_naturezaoperacao_parametro b on b.id_naturezaoperacao = a.id_naturezaoperacao',
'        where a.id_pedidoimportacao = p_id',
'        and b.ind_gera_financeiro = ''S'';',
'',
'        -- Valor total desconto:',
'        select nvl(valor_desconto, 0)',
'        into l_valor_desconto_total',
'        from imp_pedidoimportacao',
'        where id = p_id;',
'',
'        -- Valor proporcional do item:',
'        select ',
'            (l_valor_desconto_total * (b.valor_total / l_valor_total_mercadoria))',
'        into l_resultado',
'        from imp_pedidoimportacao_item b',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where b.id = p_id_pedidoimportacao_item',
'        and b.id_pedidoimportacao = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Base em 5 casas (inteiro):',
'        l_base_int := trunc(l_resultado * 100000);',
'',
'        -- Soma total truncada:',
'        select sum(trunc(',
'            (l_valor_desconto_total * (b.valor_total / l_valor_total_mercadoria)) * 100000',
'        ))',
'        into l_soma_base_int',
'        from imp_pedidoimportacao_item b',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where b.id_pedidoimportacao = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Total correto:',
'        l_total_int := trunc(l_valor_desconto_total * 100000);',
'',
unistr('        -- Diferen\00E7a (res\00EDduo):'),
'        l_resto := l_total_int - l_soma_base_int;',
'',
'        -- Item que recebe ajuste(menor id):',
'        select min(b.id)',
'        into l_item_ajuste',
'        from imp_pedidoimportacao_item b',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where b.id_pedidoimportacao = p_id',
'        and c.ind_gera_financeiro = ''S'';',
'',
'        -- Aplica ajuste:',
'        if p_id_pedidoimportacao_item = l_item_ajuste then',
'            l_base_int := l_base_int + l_resto;',
'        end if;',
'',
'        -- Retorno final:',
'        return l_base_int / 100000;',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_valor_desconto_pedido_item;',
'    --',
'    procedure altera_valor_desconto_pedido_item(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_valor_desconto_pedido_item'';',
'',
'        for item in (',
'            select id from imp_pedidoimportacao_item where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_pedidoimportacao_item.altera_valor_desconto_pedido_item(',
'                p_valor_desconto_pedido_item => retorna_valor_desconto_pedido_item(p_id,item.id),',
'                p_id => item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_valor_desconto_pedido_item;',
'    --',
'    procedure altera_titulopagamento_ind_status_pagamento(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade number;',
'        l_ind_status_pagamento number;',
'    begin',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'        for titulopagamento in (',
'            select ',
'                a.id,',
'                a.ind_status_pagamento',
'            from fin_titulopagamento a',
'            join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'            where a.id_entidade = l_id_entidade',
unistr('            and a.ind_status_pagamento in (1,2) -- 1=Em aberto, 2=Pago, 3=Cancelado, 4=Cr\00E9dito'),
'            and b.id_pedidoimportacao = p_id',
'        ) loop',
'            if titulopagamento.ind_status_pagamento = 1 then',
'                l_ind_status_pagamento := 3;',
'            elsif titulopagamento.ind_status_pagamento = 2 then',
'                l_ind_status_pagamento := 4;',
'            end if;',
'',
'            bo_fin_titulopagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => l_ind_status_pagamento,',
'                p_id => titulopagamento.id,',
'                p_pagina => v_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_titulopagamento_ind_status_pagamento;',
'    --',
'    procedure gera_titulo_pagamento(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade number;',
'        l_id_fin_titulopagamento number;',
'    begin',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
'        for pedidoimportacao_pagamento in (',
'            select distinct',
'                a.id,',
'                a.id_tenant,',
'                a.valor,',
'                b.numero_proforma,',
'                b.id_exportador,',
'                a.data_vencimento_prevista,',
'                b.id_moeda,',
'                a.ind_multa_atraso_pagamento,',
'                a.valor_multa,',
'                a.percentual_multa,',
'                a.periodo_multa',
'            from imp_pedidoimportacao_pagamento a',
'            join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'            join ng_condicaopagamento c on c.id = b.id_condicaopagamento',
'            join ng_condicaopagamento_parcela d on d.id_condicaopagamento = c.id',
'            where b.id = p_id',
'            and d.ind_evento_gerador_pagamento = 1',
'            and a.numero_parcela = d.numero_parcela',
'        ) loop',
'            bo_fin_titulopagamento.inclui_registro(                ',
'                p_id_entidade => l_id_entidade,',
'                p_id_referencia => pedidoimportacao_pagamento.id,                ',
'                p_id_tenant => pedidoimportacao_pagamento.id_tenant,',
'                p_valor_titulo => pedidoimportacao_pagamento.valor,',
'                p_id_fornecedor => pedidoimportacao_pagamento.id_exportador,',
'                p_id_fornecedor_contabancaria => bo_ng_pessoa.retorna_id_conta_bancaria(pedidoimportacao_pagamento.id_exportador),',
'                p_data_vencimento => pedidoimportacao_pagamento.data_vencimento_prevista,',
'                p_id_moeda => pedidoimportacao_pagamento.id_moeda,',
'                p_ind_multa_atraso_pagamento => pedidoimportacao_pagamento.ind_multa_atraso_pagamento,',
'                p_valor_multa => pedidoimportacao_pagamento.valor_multa,',
'                p_percentual_multa => pedidoimportacao_pagamento.percentual_multa,',
'                p_periodo_multa => pedidoimportacao_pagamento.periodo_multa,',
'                p_ind_status_pagamento => 1,',
unistr('                p_saldo_pagar => pedidoimportacao_pagamento.valor, -- saldo=valor na inclus\00E3o(?)'),
unistr('                p_saldo_compensar => pedidoimportacao_pagamento.valor, -- saldo_compensar=valor na inclus\00E3o(?)'),
'',
'                p_data_pagamento => null,',
'                p_data_compensacao => null,',
'                p_valor_pago => null,',
'                p_taxa_cambio => null,',
'                p_valor_moeda_nacional => null,',
'                p_observacao => null,',
'                p_valor_compensado => null,',
'',
'                p_id => l_id_fin_titulopagamento,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end gera_titulo_pagamento;',
'    --',
'    procedure altera_invoice_ind_status(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for invoice in(',
'            select id_invoice from imp_entrega where id_pedidoimportacao = p_id and id_invoice is not null',
'        ) loop',
'            bo_imp_invoice.altera_ind_status(',
'                p_ind_status => 4,',
'                p_id => invoice.id_invoice,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_invoice_ind_status;',
'    --',
'    procedure altera_processoimportacao_ind_status(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_verifica_processoimportacao_ind_status number;',
'    begin',
'        select count(1) into l_verifica_processoimportacao_ind_status',
'        from imp_entrega a',
'        join imp_processoimportacao b on b.id = a.id_processoimportacao',
'        where a.id_pedidoimportacao = p_id',
'        and b.ind_status not in (1,2);',
'',
'        if l_verifica_processoimportacao_ind_status > 0 then            ',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''128'',',
'                p_nome_campo => ''ind_status_pedido_importacao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;           ',
'        else',
'            for processoimportacao in(',
'                select id_processoimportacao from imp_entrega where id_pedidoimportacao = p_id and id_processoimportacao is not null',
'            ) loop',
'                bo_imp_processoimportacao.altera_ind_status(',
'                    p_ind_status => 9,',
'                    p_id => processoimportacao.id_processoimportacao,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_processoimportacao_ind_status;',
'    --',
'    procedure altera_registro_retomar_digitacao(',
'        p_id_tenant in imp_pedidoimportacao.id_tenant%type,',
'        p_numero_pedido_importacao in imp_pedidoimportacao.numero_pedido_importacao%type,',
'        p_ind_status_pedido_importacao in imp_pedidoimportacao.ind_status_pedido_importacao%type,',
'        p_ind_modalidade_importacao in imp_pedidoimportacao.ind_modalidade_importacao%type,',
'        p_id_exportador in imp_pedidoimportacao.id_exportador%type,',
'        p_id_importador in imp_pedidoimportacao.id_importador%type,',
'        p_id_adquirente in imp_pedidoimportacao.id_adquirente%type,',
'        p_id_comprador in imp_pedidoimportacao.id_comprador%type,        ',
'        p_numero_proforma in imp_pedidoimportacao.numero_proforma%type,        ',
'        p_id_viatransporte in imp_pedidoimportacao.id_viatransporte%type,',
'        p_id_incoterm in imp_pedidoimportacao.id_incoterm%type,',
'        p_id_listapreco in imp_pedidoimportacao.id_listapreco%type,',
'        p_id_local_embarque in imp_pedidoimportacao.id_local_embarque%type,',
'        p_id_local_desembarque in imp_pedidoimportacao.id_local_desembarque%type,',
'        p_id_endereco_destino in imp_pedidoimportacao.id_endereco_destino%type,',
'        p_quantidade_entrega in imp_pedidoimportacao.quantidade_entrega%type,',
'        p_id_condicaopagamento in imp_pedidoimportacao.id_condicaopagamento%type,',
'        p_valor_total_mercadoria in imp_pedidoimportacao.valor_total_mercadoria%type,',
'        p_valor_desconto in imp_pedidoimportacao.valor_desconto%type,',
'        p_valor_despesa_proforma in imp_pedidoimportacao.valor_despesa_proforma%type,',
'        p_valor_total_condicao_venda in imp_pedidoimportacao.valor_total_condicao_venda%type,',
'        p_ind_todos_itens_com_entregas_programadas in imp_pedidoimportacao.ind_todos_itens_com_entregas_programadas%type,',
'        p_nome_vendedor in imp_pedidoimportacao.nome_vendedor%type,',
'        p_id_endereco_origem in imp_pedidoimportacao.id_endereco_origem%type,',
'        p_ind_situacao_parcela_pagamento in imp_pedidoimportacao.ind_situacao_parcela_pagamento%type,',
'        p_data_confirmacao_pedido in imp_pedidoimportacao.data_confirmacao_pedido%type,',
'        p_id_moeda in imp_pedidoimportacao.id_moeda%type,',
'        p_quantidade_parcelas_pagamento in imp_pedidoimportacao.quantidade_parcelas_pagamento%type, ',
'        p_motivo_desconto in imp_pedidoimportacao.motivo_desconto%type,',
'        p_valor_total_financeiro in imp_pedidoimportacao.valor_total_financeiro%type,',
'        p_id in imp_pedidoimportacao.id%type, ',
'        p_data_alteracao in imp_pedidoimportacao.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin ',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_registro_retomar_digitacao'';   ',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.numero_pedido_importacao := p_numero_pedido_importacao;',
'        v_new.ind_status_pedido_importacao := p_ind_status_pedido_importacao;',
'        v_new.ind_modalidade_importacao := p_ind_modalidade_importacao;',
'        v_new.id_exportador := p_id_exportador;',
'        v_new.id_importador := p_id_importador;',
'        v_new.id_adquirente := p_id_adquirente;',
'        v_new.id_comprador := p_id_comprador;        ',
'        v_new.numero_proforma := p_numero_proforma;        ',
'        v_new.id_viatransporte := p_id_viatransporte;',
'        v_new.id_incoterm := p_id_incoterm;',
'        v_new.id_listapreco := p_id_listapreco;',
'        v_new.id_local_embarque := p_id_local_embarque;',
'        v_new.id_local_desembarque := p_id_local_desembarque;',
'        v_new.id_endereco_destino := p_id_endereco_destino;',
'        v_new.quantidade_entrega := p_quantidade_entrega;',
'        v_new.id_condicaopagamento := p_id_condicaopagamento;',
'        v_new.valor_total_mercadoria := p_valor_total_mercadoria;',
'        v_new.valor_desconto := p_valor_desconto;',
'        v_new.valor_despesa_proforma := p_valor_despesa_proforma;',
'        v_new.valor_total_condicao_venda := p_valor_total_condicao_venda;',
'        v_new.ind_todos_itens_com_entregas_programadas := p_ind_todos_itens_com_entregas_programadas;',
'        v_new.nome_vendedor := p_nome_vendedor;',
'        v_new.id_endereco_origem := p_id_endereco_origem;',
'        v_new.ind_situacao_parcela_pagamento := p_ind_situacao_parcela_pagamento;',
'        v_new.data_confirmacao_pedido := p_data_confirmacao_pedido;',
'        v_new.id_moeda := p_id_moeda;',
'        v_new.quantidade_parcelas_pagamento := p_quantidade_parcelas_pagamento; ',
'        v_new.motivo_desconto := p_motivo_desconto;',
'        v_new.valor_total_financeiro := p_valor_total_financeiro;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_REGISTRO_RETOMAR_DIGITACAO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_registro_retomar_digitacao;',
'    --',
'    procedure altera_entregas_retormar_digitacao(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for entrega in (',
'            select * from imp_entrega where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_entrega.altera_registro(',
'                p_id_tenant => entrega.id_tenant,',
'                p_id_pedidoimportacao => entrega.id_pedidoimportacao,',
'                p_num_entrega => entrega.num_entrega,',
'                p_id_processoimportacao => entrega.id_processoimportacao,',
'                p_ind_modalidade_importacao => v_new.ind_modalidade_importacao,--entrega.ind_modalidade_importacao,',
'                p_id_exportador => v_new.id_exportador,--entrega.id_exportador,',
'                p_id_importador => v_new.id_importador,--entrega.id_importador,',
'                p_id_adquirente => v_new.id_adquirente,--entrega.id_adquirente,',
'                p_id_endereco_origem => v_new.id_endereco_origem,--entrega.id_endereco_origem,',
'                p_id_local_embarque => v_new.id_local_embarque,--entrega.id_local_embarque,',
'                p_id_local_desembarque => v_new.id_local_desembarque,--entrega.id_local_desembarque,',
'                p_id_endereco_destino => v_new.id_endereco_destino,--entrega.id_endereco_destino,',
'                p_id_viatransporte => v_new.id_viatransporte,--entrega.id_viatransporte,',
'                p_id_incoterm => v_new.id_incoterm,--entrega.id_incoterm,',
'                p_ind_status_entrega => entrega.ind_status_entrega,',
'                p_data_disponivel_calculada => entrega.data_disponivel_calculada,',
'                p_data_disponivel_informada => entrega.data_disponivel_informada,',
'                p_data_disponivel_real => entrega.data_disponivel_real,',
'                p_data_embarque_calculada => entrega.data_embarque_calculada,',
'                p_data_embarque_informada => entrega.data_embarque_informada,',
'                p_data_embarque_real => entrega.data_embarque_real,',
'                p_data_desembarque_calculada => entrega.data_desembarque_calculada,',
'                p_data_desembarque_informada => entrega.data_desembarque_informada,',
'                p_data_desembarque_real => entrega.data_desembarque_real,',
'                p_data_nacionalizacao_calculada => entrega.data_nacionalizacao_calculada,',
'                p_data_nacionalizacao_informada => entrega.data_nacionalizacao_informada,',
'                p_data_nacionalizacao_real => entrega.data_nacionalizacao_real,',
'                p_data_recebimento_calculada => entrega.data_recebimento_calculada,',
'                p_data_recebimento_informada => entrega.data_recebimento_informada,',
'                p_data_recebimento_real => entrega.data_recebimento_real,',
'                p_valor_total_condicao_venda => entrega.valor_total_condicao_venda,',
'                p_valor_total_financeiro => entrega.valor_total_financeiro,',
'                p_id_invoice => entrega.id_invoice,',
'                p_id => entrega.id,',
'                p_data_alteracao => entrega.data_alteracao,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );           ',
'        end loop;',
'    end altera_entregas_retormar_digitacao;',
'    --',
'    procedure altera_pedidoimportacao_item_quantidade_firmada(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is ',
'    begin',
'        for pedidoimportacao_item in (',
'            select id, quantidade from imp_pedidoimportacao_item where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_pedidoimportacao_item.altera_quantidade_firmada(',
'                p_quantidade_firmada => pedidoimportacao_item.quantidade,',
'                p_id => pedidoimportacao_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_pedidoimportacao_item_quantidade_firmada;',
'    --',
'    procedure altera_pedidoimportacao_pagamento_ind_status_pagamento(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is ',
'    begin',
'        for pedidoimportacao_pagamento in (',
'            select id from imp_pedidoimportacao_pagamento where id_pedidoimportacao = p_id',
'        ) loop',
'            bo_imp_pedidoimportacao_pagamento.altera_ind_status_pagamento(',
unistr('                p_ind_status_pagamento => 1, -- A gerar t\00EDtulo'),
'                p_data_vencimento_real => null,',
'                p_id => pedidoimportacao_pagamento.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_pedidoimportacao_pagamento_ind_status_pagamento;',
'    --',
'    procedure altera_valores(  ',
'        p_valor_total_mercadoria in imp_pedidoimportacao.valor_total_mercadoria%type,',
'        p_valor_total_financeiro in imp_pedidoimportacao.valor_total_financeiro%type,',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.altera_valores'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_total_mercadoria := p_valor_total_mercadoria;',
'        v_new.valor_total_financeiro := p_valor_total_financeiro;        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_REGISTRO_DATA_ALTERACAO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_valores;',
'    --',
'    function retorna_valor_total_financeiro(',
'        p_id in imp_pedidoimportacao.id%type',
'    ) return number is',
'        l_valor_total_financeiro number;',
'    begin',
'        -- select nvl(sum(a.valor_total), 0) ',
'        -- into l_valor_total_financeiro',
'        -- from imp_pedidoimportacao_item a',
'        -- join imp_naturezaoperacao_parametro b on b.id_naturezaoperacao = a.id_naturezaoperacao',
'        -- where a.id_pedidoimportacao = p_id',
'        -- and b.ind_gera_financeiro = ''S'';',
'        select (nvl(sum(b.valor_total), 0) - a.valor_desconto + a.valor_despesa_proforma)',
'        into l_valor_total_financeiro',
'        from imp_pedidoimportacao a ',
'        join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id',
'        join imp_naturezaoperacao_parametro c on c.id_naturezaoperacao = b.id_naturezaoperacao',
'        where b.id_pedidoimportacao = p_id',
'        and c.ind_gera_financeiro = ''S''',
'        group by a.valor_desconto, a.valor_despesa_proforma;',
'',
'        return trunc(l_valor_total_financeiro, 2);',
'    exception ',
'        when no_data_found then',
'            return 0;',
'    end retorna_valor_total_financeiro;',
'    --',
'    procedure altera_pedidoimportacao_pagamento_valor(',
'        p_id in imp_pedidoimportacao.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for pedidoimportacao_pagamento in (',
'            select',
'                a.id,',
'                trunc(((d.percentual / 100) * b.valor_total_financeiro),2) valor,',
'                a.data_vencimento_prevista',
'            from imp_pedidoimportacao_pagamento a',
'            join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'            jo'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767291109620274)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'in ng_condicaopagamento c on c.id = b.id_condicaopagamento',
'            join ng_condicaopagamento_parcela d on d.id_condicaopagamento = c.id and d.numero_parcela = a.numero_parcela',
'            where a.id_pedidoimportacao = p_id',
'            and ind_evento_gerador_pagamento = 1',
'        ) loop',
'            bo_imp_pedidoimportacao_pagamento.altera_valor_e_data_vencimento_prevista(',
'                p_valor => pedidoimportacao_pagamento.valor,',
'                p_data_vencimento_prevista => pedidoimportacao_pagamento.data_vencimento_prevista,',
'                p_id => pedidoimportacao_pagamento.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_pedidoimportacao_pagamento_valor;',
'    --',
'    procedure firmar_pedido_com_processo(        ',
'        p_data_confirmacao_pedido in imp_pedidoimportacao.data_confirmacao_pedido%type,',
'        p_gerar_processo          in varchar2,',
'        p_json                    in clob,        ',
'        p_id                      in imp_pedidoimportacao.id%type,',
'        p_pagina                  in number default 0,',
'        p_encadeado               in boolean default false,',
'        p_sucesso                 out clob,',
'        p_messages                out pkg_mensagem.message_record_table',
'    ) is',
'        l_json                      clob;',
'        l_imp_entrega               imp_entrega%rowtype;',
'        l_num_processoimportacao_ng varchar2(20);        ',
'        l_id_processoimportacao     number;',
'        l_parametros                pkg_mensagem.paramentros;',
'        l_mensagem                  clob;',
'        l_id                        number;',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao.firmar_pedido_com_processo'';',
'        v_pagina       := p_pagina;',
'        v_messages     := pkg_mensagem.message_record_table();',
'        p_messages     := pkg_mensagem.message_record_table();',
'',
'        if p_gerar_processo is null then',
'            v_parametro(1) := pkg_ui.retorna_label_tela(''gera_processo'');',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''11'',',
'                p_nome_campo => ''gera_processo'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        elsif p_gerar_processo = ''S'' then',
'            l_json := p_json;',
'            for entrega in (',
'                select json_entrega.id, json_entrega.num_processoimportacao',
'                  from json_table(l_json, ''$[*]''',
'                    columns',
'                        id                     varchar2(20) path ''$.id'',',
'                        num_processoimportacao varchar2(20) path ''$.num_processoimportacao''',
'                  ) json_entrega',
'            ) loop',
'                -- Tratamento incluir: ',
'                select * into l_imp_entrega from imp_entrega where id = entrega.id;',
'                l_num_processoimportacao_ng := bo_imp_processoimportacao.retorna_numero_processoimportacao(l_imp_entrega.id_tenant);',
'',
'                if entrega.num_processoimportacao is null and l_num_processoimportacao_ng is null then',
'                    v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_processoimportacao.num_processoimportacao'');',
'                    pkg_mensagem.mensagem_campo(',
'                        p_codigo_mensagem => ''11'',',
'                        p_nome_campo => ''num_processoimportacao'',',
'                        p_parametro => v_parametro,',
'                        p_pagina => v_pagina,',
'                        p_objeto_mensagem => v_message',
'                    );            ',
unistr('                    -- Inserir o registro na cole\00E7\00E3o'),
'                    v_messages.EXTEND;',
'                    v_messages(v_messages.LAST) := v_message;           ',
'                    if v_messages.count > 0 then',
'                        raise pk_exceptions.e_erro;',
'                    end if;',
'                end if;',
'',
'                -- CHAMADA PARA O MAESTRO:',
'                l_id := pkg_maestro_api.postar_requisicao(',
'                    p_codigo_artefato => ''PR10'',',
'                    p_id_tenant       => l_imp_entrega.id_tenant,',
'                    p_id_usuario      => pkg_util.retorna_id_usuario_logado,',
'                    p_id_negocio      => l_imp_entrega.id,',
'                    p_payload         => ''{',
'                        "id_tenant":"''||l_imp_entrega.id_tenant||''",',
'                        "num_processoimportacao":"''||nvl(l_num_processoimportacao_ng, entrega.num_processoimportacao)||''",',
'                        "ind_modalidade_importacao":"''||l_imp_entrega.ind_modalidade_importacao||''",',
'                        "id_embarcador":"''||l_imp_entrega.id_exportador||''",',
'                        "id_importador":"''||l_imp_entrega.id_importador||''",',
'                        "id_adquirente":"''||l_imp_entrega.id_adquirente||''",',
'                        "id_viatransporte":"''||l_imp_entrega.id_viatransporte||''",',
'                        "id_endereco_origem":"''||l_imp_entrega.id_endereco_origem||''",',
'                        "id_local_embarque":"''||l_imp_entrega.id_local_embarque||''",',
'                        "id_local_desembarque":"''||l_imp_entrega.id_local_desembarque||''",',
'                        "id_endereco_destino":"''||l_imp_entrega.id_endereco_destino||''",',
'                        "id_entrega":"''||entrega.id||''" ',
'                    }'',',
'                    p_prioridade      => 0,',
'                    p_tipo_acao       => ''BO_IMP_PEDIDOIMPORTACAO.FIRMAR_PEDIDO_COM_PROCESSO'',',
'                    p_id_correlation  => null',
'                );',
'                -- Original:',
'                -- bo_imp_processoimportacao.inclui_registro_ao_firmar_pedido(',
'                --     p_id_tenant                 => l_imp_entrega.id_tenant,',
'                --     p_num_processoimportacao    => nvl(l_num_processoimportacao_ng, entrega.num_processoimportacao),',
'                --     p_ind_modalidade_importacao => l_imp_entrega.ind_modalidade_importacao,',
'                --     p_id_embarcador             => l_imp_entrega.id_exportador,',
'                --     p_id_importador             => l_imp_entrega.id_importador,',
'                --     p_id_adquirente             => l_imp_entrega.id_adquirente,',
'                --     p_id_viatransporte          => l_imp_entrega.id_viatransporte,',
'                --     p_id_endereco_origem        => l_imp_entrega.id_endereco_origem,',
'                --     p_id_local_embarque         => l_imp_entrega.id_local_embarque,',
'                --     p_id_local_desembarque      => l_imp_entrega.id_local_desembarque,',
'                --     p_id_endereco_destino       => l_imp_entrega.id_endereco_destino,',
'                --     p_id_entrega                => entrega.id,',
'                --     p_id                        => l_id_processoimportacao,',
'                --     p_pagina                    => p_pagina,',
'                --     p_encadeado                 => p_encadeado,',
'                --     p_sucesso                   => p_sucesso,',
'                --     p_messages                  => p_messages',
'                -- );',
'            end loop;',
'        end if;',
'        ',
'        if p_messages.count = 0 then',
'            select * into v_old from imp_pedidoimportacao where id = p_id;',
'            v_new := v_old;',
'',
'            v_new.data_confirmacao_pedido      := p_data_confirmacao_pedido;        ',
'            v_new.ind_status_pedido_importacao := 3; --(Firmado)',
'            v_new.id_usuario_alterou           := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao               := sysdate;',
'',
'            -- v_operacao := ''FIRMAR_OU_DESCONFIRMAR'';',
'            v_operacao := ''FIRMAR_PEDIDO_COM_PROCESSO'';',
'',
'            grava(p_id, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        l_parametros(1) := v_new.numero_pedido_importacao;',
'        if p_gerar_processo = ''S'' then',
'            l_parametros(2) := retorna_texto(''msg.165.l'');',
'        end if;',
'        pkg_mensagem.mensagem_original(164, l_parametros, l_mensagem);',
'        p_sucesso := pkg_mensagem.tag_mensagem(l_mensagem);',
'        p_sucesso := replace(p_sucesso, ''[CONCATENA_TEXTO]'');',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end firmar_pedido_com_processo;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_pedidoimportacao;',
'/'))
);
end;
