unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_pedidoimportacao_item'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_pedidoimportacao_item'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_pedidoimportacao_item'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_pedidoimportacao_item'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_pedidoimportacao_item'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_pedidoimportacao_item'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_pedidoimportacao_item%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''ind_bloqueio_embarque_ate_deferimento_li'', p_rec.ind_bloqueio_embarque_ate_deferimento_li, true);',
'        apex_json.write(''ind_licenca_importacao'', p_rec.ind_licenca_importacao, true);',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_pedidoimportacao'', p_rec.id_pedidoimportacao, true);',
'        apex_json.write(''id_item'', p_rec.id_item, true);',
'        apex_json.write(''num_sequencia_item'', p_rec.num_sequencia_item, true);',
'        apex_json.write(''id_unidademedida'', p_rec.id_unidademedida, true);',
'        apex_json.write(''quantidade'', p_rec.quantidade, true);',
'        apex_json.write(''peso_unitario'', p_rec.peso_unitario, true);',
'        apex_json.write(''peso_liquido_total'', p_rec.peso_liquido_total, true);',
'        apex_json.write(''valor_unitario'', p_rec.valor_unitario, true);',
'        apex_json.write(''valor_desconto_unitario'', p_rec.valor_desconto_unitario, true);',
'        apex_json.write(''valor_total'', p_rec.valor_total, true);',
'        apex_json.write(''id_naturezaoperacao'', p_rec.id_naturezaoperacao, true);',
'        apex_json.write(''num_solicitacao_compra'', p_rec.num_solicitacao_compra, true);',
'        apex_json.write(''nome_solicitante'', p_rec.nome_solicitante, true);',
'        apex_json.write(''quantidade_programada_entrega'', p_rec.quantidade_programada_entrega, true);',
'        apex_json.write(''quantidade_programar_entrega'', p_rec.quantidade_programar_entrega, true);',
'        apex_json.write(''quantidade_faturada'', p_rec.quantidade_faturada, true);',
'        apex_json.write(''quantidade_faturar'', p_rec.quantidade_faturar, true);',
'        apex_json.write(''id_fabricante'', p_rec.id_fabricante, true);',
'        apex_json.write(''id_centrocusto'', p_rec.id_centrocusto, true);',
'        apex_json.write(''ind_finalidade'', p_rec.ind_finalidade, true);',
'        apex_json.write(''numero_ato_concessorio'', p_rec.numero_ato_concessorio, true);',
'        apex_json.write(''data_entrega_desejada'', p_rec.data_entrega_desejada, true);',
'        apex_json.write(''quantidade_cancelada'', p_rec.quantidade_cancelada, true);',
'        apex_json.write(''valor_desconto_pedido_item'', p_rec.valor_desconto_pedido_item, true);',
'        apex_json.write(''valor_despesaproforma'', p_rec.valor_despesaproforma, true);',
'        apex_json.write(''valor_despesaproforma_unitario'', p_rec.valor_despesaproforma_unitario, true);',
'        apex_json.write(''valor_desconto_pedido_item_unitario'', p_rec.valor_desconto_pedido_item_unitario, true);',
'        apex_json.write(''quantidade_firmada'', p_rec.quantidade_firmada, true);',
'        apex_json.write(''id_ncm'', p_rec.id_ncm, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    --',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
unistr('        -- Garantir c\00E1lculos corretos:'),
'        v_new.peso_liquido_total := (v_new.quantidade * v_new.peso_unitario);',
'        v_new.valor_total        := (v_new.quantidade * (v_new.valor_unitario - v_new.valor_desconto_unitario));',
'    end hook_antes_incluir; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        bo_ng_pessoa_juridica.atualiza_perfil (',
'            p_id => v_new.id_fabricante,',
'            p_ind_perfil => ''F'',',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        ); ',
'        altera_pedidoimportacao_valores(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        if nvl(v_operacao, ''-20001'') != ''ATUALIZA_QUANTIDADES_PROGRAMADAS'' then',
'            recalcula_rateio_despesaproforma(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        altera_registros_valor_desconto_pedido_item(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'        --bo_imp_pedidoimportacao.altera_valor_desconto_pedido_item(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'    end hook_depois_incluir; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
unistr('        -- Garantir c\00E1lculos corretos:'),
'        v_new.peso_liquido_total := (v_new.quantidade * v_new.peso_unitario);',
'        v_new.valor_total        := (v_new.quantidade * (v_new.valor_unitario - v_new.valor_desconto_unitario));',
'    end hook_antes_alterar; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
unistr('        -- Altera\00E7\00E3o simples de quantidade_firmada disparada pelo a\00E7\00E3o de firmar o pedido, n\00E3o precisa executar demais gatilhos:'),
'        if v_operacao = ''ALTERA_QUANTIDADE_FIRMADA'' then',
'            return;',
'        end if;',
'',
'        bo_ng_pessoa_juridica.atualiza_perfil (',
'            p_id => v_new.id_fabricante,',
'            p_ind_perfil => ''F'',',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'        altera_pedidoimportacao_valores(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        if v_operacao in (''ALTERA_PEDIDOIMPORTACAO_ITEM'',''ALTERA_DIVERGENCIA_PEDIDOIMPORTACAO_ITEM'') then',
'            recalcula_rateio_despesaproforma(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            if v_operacao = ''ALTERA_PEDIDOIMPORTACAO_ITEM'' then',
'                bo_imp_pedidoimportacao.altera_valor_desconto_pedido_item(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'                altera_entrega_item(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            end if;',
'            altera_registros_valor_desconto_pedido_item(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        if v_operacao = ''ALTERA_VALOR_DESCONTO_PEDIDO_ITEM'' then',
'            altera_entrega_item_valor_desconto_pedido_item_unitario(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        if nvl(v_operacao, ''-20001'') not in (''ALTERA_VALOR_DESPESAPROFORMA'',''EXECUTA_ALTERA_REGISTRO'',''ALTERA_VALOR_DESCONTO_PEDIDO_ITEM'',''ATUALIZA_QUANTIDADES_PROGRAMADAS'',''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'') then',
'            recalcula_rateio_despesaproforma(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        if v_operacao = ''ALTERA_VALOR_DESPESAPROFORMA'' then',
'            altera_entrega_item_valor_despesaproforma_unitario(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        ',
unistr('        -- Tratamento de diverg\00EAncias:'),
'        if v_operacao in (''ATUALIZA_QUANTIDADES_PROGRAMADAS'',''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'') and v_old.quantidade != v_new.quantidade then            ',
'            recalcula_rateio_despesaproforma(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            altera_registros_valor_desconto_pedido_item(v_new.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            -- altera_entrega_item_rateios(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end hook_depois_alterar; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end hook_antes_excluir; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        altera_pedidoimportacao_valores(v_old.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        if nvl(v_operacao, ''-20001'') != ''ATUALIZA_QUANTIDADES_PROGRAMADAS'' then',
'            recalcula_rateio_despesaproforma(v_old.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        altera_registros_valor_desconto_pedido_item(v_old.id_pedidoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'    end hook_depois_excluir;',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
