'    procedure hook_valida_quantidade(p_quantidade in imp_pedidoimportacao_item.quantidade%type) ',
'    is ',
'    begin',
'        -- Verificar impacto de item com quantidade=0:',
'        --if p_quantidade <= 0 then ',
'        if p_quantidade < 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.quantidade''); ',
