'    procedure hook_valida_valor_unitario(p_valor_unitario in imp_pedidoimportacao_item.valor_unitario%type) ',
'    is ',
'    begin ',
'        if p_valor_unitario <= 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.valor_unitario''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
