'',
'    procedure hook_valida_valor_desconto_unitario(p_valor_desconto_unitario in imp_pedidoimportacao_item.valor_desconto_unitario%type) ',
'    is',
'        l_verifica_listapreco number;',
'        l_preco_unitario_minimo number;',
'        l_verifica_valor_unico number;        ',
'    begin',
'        --select count(1) into l_verifica_listapreco from imp_pedidoimportacao where id = v_new.id_pedidoimportacao and id_listapreco is not null;',
'        select count(1) into l_verifica_listapreco',
'        from imp_pedidoimportacao a ',
'        join ng_listapreco b on b.id = a.id_listapreco',
'        join ng_listapreco_item c on c.id_lista_preco = b.id',
'        where a.id = v_new.id_pedidoimportacao',
'        and c.id_item_produto = v_new.id_item',
'        and c.id_unidademedida = v_new.id_unidademedida',
'        and qtd_minima <= v_new.quantidade',
'        order by qtd_minima desc;        ',
'',
'        if l_verifica_listapreco > 0 then',
'            select c.preco_unitario_minimo ',
'            into l_preco_unitario_minimo',
'            from imp_pedidoimportacao a ',
'            join ng_listapreco b on b.id = a.id_listapreco',
'            join ng_listapreco_item c on c.id_lista_preco = b.id',
'            where a.id = v_new.id_pedidoimportacao',
'            and c.id_item_produto = v_new.id_item',
'            and c.id_unidademedida = v_new.id_unidademedida',
'            and qtd_minima <= v_new.quantidade',
'            order by qtd_minima desc',
'            fetch first 1 row only;',
'',
'            if (v_new.valor_unitario - p_valor_desconto_unitario) < l_preco_unitario_minimo then',
'                v_parametro(1) := l_preco_unitario_minimo;',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => 75,',
'                    p_nome_campo => ''valor_desconto_unitario'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );            ',
unistr('                -- Inserir o registro na cole\00E7\00E3o'),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;',
'            --Verifica formato se houver',
'            end if;   ',
'        end if;        ',
'        if p_valor_desconto_unitario > v_new.valor_unitario then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.valor_desconto_unitario'');',
'            v_parametro(2) := lower(pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.valor_unitario''));',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => 77,',
'                    p_nome_campo => ''valor_desconto_unitario'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );            ',
unistr('                -- Inserir o registro na cole\00E7\00E3o'),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;',
'        end if;',
unistr('        --Verifica valor \00FAnico se houver'),
'    end hook_valida_valor_desconto_unitario;     ',
