'    --',
'    function detalhe_registro (',
'        p_id in imp_pedidoimportacao_item.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                a.num_sequencia_item as imp_pedidoimportacao_item$num_sequencia_item,',
'                c.codigo_item || '' - '' ||',
'                pkg_traducao.get_traducao(c.descricao_item) as imp_pedidoimportacao_item$id_item,                 ',
'                e.codigo_unidademedida as imp_pedidoimportacao_item$id_unidademedida, ',
'                case e.ind_tipo_dado ',
'                    when ''D'' then',
'                        to_char(a.quantidade, ''FM999G999G990D00000'')',
'                    when ''I'' then',
'                        to_char(a.quantidade) ',
'                end as imp_pedidoimportacao_item$quantidade,                 ',
'                to_char(a.peso_liquido_total, ''FM999G999G990D00000'') as imp_pedidoimportacao_item$peso_liquido_total, ',
'                f.codigo_moeda||'' - ''||f.simbolo_iso as imp_pedidoimportacao$id_moeda,',
'                to_char(a.valor_total, ''FM999G999G990D00'') as imp_pedidoimportacao_item$valor_total',
'            from imp_pedidoimportacao_item a',
'            left join ng_pessoa_juridica b on b.id_pessoa = a.id_fabricante',
'            join ng_item c on c.id = a.id_item',
'            join imp_pedidoimportacao d on d.id = a.id_pedidoimportacao',
'            join ng_unidademedida e on e.id = a.id_unidademedida',
'            join ng_moeda f on f.id = d.id_moeda',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure altera_registro_quantidade_programar_entrega(  ',
'        p_quantidade_programar_entrega in imp_pedidoimportacao_item.quantidade_programar_entrega%type,',
'        p_quantidade_cancelada in imp_pedidoimportacao_item.quantidade_cancelada%type,',
'        p_id in imp_pedidoimportacao_item.id%type, ',
'        p_data_alteracao in imp_pedidoimportacao_item.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_registro_quantidade_programar_entrega'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        --',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.quantidade_programar_entrega := p_quantidade_programar_entrega;',
'        v_new.quantidade_cancelada := p_quantidade_cancelada;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_registro_quantidade_programar_entrega;',
'    --',
'    function gera_sequencia (',
'        p_id_pedidoimportacao in imp_pedidoimportacao.id%TYPE',
'    ) return number is',
'        l_contador number := 0;',
'    begin',
'        select nvl(max(num_sequencia_item), 0) into l_contador from imp_pedidoimportacao_item where id_pedidoimportacao = p_id_pedidoimportacao;',
'        return l_contador + 1;',
'    end gera_sequencia;',
'    --',
'    procedure altera_pedidoimportacao_valores(',
'        p_id_pedidoimportacao in imp_pedidoimportacao_item.id_pedidoimportacao%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_valor_total_mercadoria number;        ',
'    begin',
'        select nvl(sum(valor_total), 0) into l_valor_total_mercadoria from imp_pedidoimportacao_item where id_pedidoimportacao = p_id_pedidoimportacao;',
'        ',
'        bo_imp_pedidoimportacao.altera_valores(',
'            p_valor_total_mercadoria => l_valor_total_mercadoria,            ',
'            p_valor_total_financeiro => bo_imp_pedidoimportacao.retorna_valor_total_financeiro(p_id_pedidoimportacao),',
'            p_id => p_id_pedidoimportacao,',
'            p_pagina => p_pagina,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end altera_pedidoimportacao_valores;',
'    --',
'    function atualiza_quantidade_programada_entrega(',
'        p_id in imp_pedidoimportacao_item.id%type',
'    ) return number is',
'        l_verifica_entrega_item number;',
'        l_quantidade_programada_entrega number;',
'    begin',
'        select count(1) into l_verifica_entrega_item from imp_entrega_item where id_pedidoimportacao_item = p_id and quantidade is not null and quantidade <> 0;',
'        if l_verifica_entrega_item > 0 then',
'            select ',
'                nvl(sum(a.quantidade), 0)',
'            into l_quantidade_programada_entrega',
'            from imp_entrega_item a             ',
'            where a.id_pedidoimportacao_item = p_id;',
'        else',
'            l_quantidade_programada_entrega := 0;',
'        end if;',
'        return l_quantidade_programada_entrega;',
'    end atualiza_quantidade_programada_entrega;',
'    --',
'    function atualiza_quantidade_programar_entrega(',
'        p_id in imp_pedidoimportacao_item.id%type',
'    ) return number is',
'        l_verifica_entrega_item number;',
'        l_quantidade number;',
'        l_quantidade_programada_entrega number;',
'        l_quantidade_programar_entrega number;',
'    begin',
'        select count(1) into l_verifica_entrega_item from imp_entrega_item where id_pedidoimportacao_item = p_id and quantidade is not null and quantidade <> 0;',
'        if l_verifica_entrega_item > 0 then',
'            select nvl(sum(quantidade), 0) into l_quantidade_programar_entrega from imp_entrega_item where id_pedidoimportacao_item = p_id;',
'        else',
'            select quantidade into l_quantidade from imp_pedidoimportacao_item where id = p_id;            ',
'            select ',
'                nvl(sum(a.quantidade), 0)',
'            into l_quantidade_programada_entrega',
'            from imp_entrega_item a ',
'            where a.id_pedidoimportacao_item = p_id;',
'            l_quantidade_programar_entrega := (l_quantidade - l_quantidade_programada_entrega);',
'        end if;',
'        return l_quantidade_programar_entrega;',
'    end atualiza_quantidade_programar_entrega;',
'    --    ',
'    procedure executa_altera_registro(',
'        p_id in imp_pedidoimportacao_item.id%type',
'    ) is',
'        l_imp_pedidoimportacao_item imp_pedidoimportacao_item%rowtype;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        --p_messages := pkg_mensagem.message_record_table();',
'        l_messages := pkg_mensagem.message_record_table();        ',
'        select * into l_imp_pedidoimportacao_item from imp_pedidoimportacao_item where id = p_id;',
'',
'        v_operacao := ''EXECUTA_ALTERA_REGISTRO'';',
'        grava(p_id,true,l_sucesso,l_messages);',
'    end executa_altera_registro;',
'    --',
'    procedure cancela_saldo(',
'        p_ids in varchar2,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_ids apex_t_varchar2;',
'        l_imp_pedidoimportacao_item imp_pedidoimportacao_item%rowtype;',
'    begin',
'        -- v_messages := pkg_mensagem.message_record_table(); ',
'        -- p_messages := pkg_mensagem.message_record_table();',
'        -- l_messages := pkg_mensagem.message_record_table();',
'',
'        l_ids := apex_string.split(p_ids, ''_'');',
'        for i in 1..l_ids.count loop ',
'           select * into l_imp_pedidoimportacao_item from imp_pedidoimportacao_item where id = l_ids(i);',
'            -- altera_registro_quantidade_programar_entrega(  ',
'            --     p_quantidade_programar_entrega => 0,',
'            --     p_quantidade_cancelada => l_imp_pedidoimportacao_item.quantidade_programar_entrega,',
'            --     p_id => l_imp_pedidoimportacao_item.id,',
'            --     p_data_alteracao => l_imp_pedidoimportacao_item.data_alteracao,                ',
'            --     p_encadeado => true,',
'            --     p_sucesso => l_sucesso,',
'            --     p_messages => l_messages',
'            -- );',
'            altera_quantidade_cancelada(',
'                p_quantidade_cancelada => l_imp_pedidoimportacao_item.quantidade_programar_entrega,',
'                p_id => l_imp_pedidoimportacao_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end cancela_saldo;',
'    --',
'    function tipo_execucao_td648 return varchar2 is',
'        l_resultado      varchar2(4000);',
'        l_artefato_atual varchar2(4000);',
'    begin',
'        l_artefato_atual := apex_util.get_session_state(''P9005_CODIGO_ARTEFATO'');',
'        if l_artefato_atual = ''TD635'' then',
'            l_resultado := ''select 1 from dual where #ID# = 0'';',
'        else',
'            l_resultado := ''select 1 from imp_pedidoimportacao where id = #ID# and ind_status_pedido_importacao = 3'';',
'        end if;',
'        return l_resultado;',
'    end tipo_execucao_td648;',
'    --',
'    function retorna_valor_unitario(',
'        p_id_pedidoimportacao in imp_pedidoimportacao.id%type,',
'        p_id_item in imp_pedidoimportacao_item.id_item%type,',
'        p_id_unidademedida in imp_pedidoimportacao_item.id_unidademedida%type,',
'        p_quantidade in imp_pedidoimportacao_item.quantidade%type',
'    ) return number is',
'        l_verifica_id_listapreco number;',
'        l_id_listapreco number;',
'        l_resultado number := 0;',
'    begin',
'        select count(1) into l_verifica_id_listapreco from imp_pedidoimportacao where id = p_id_pedidoimportacao and id_listapreco is not null;',
'        if l_verifica_id_listapreco > 0 then',
'            select id_listapreco into l_id_listapreco from imp_pedidoimportacao where id = p_id_pedidoimportacao;',
'            select ',
'                preco_unitario ',
'            into ',
'                l_resultado ',
'            from ng_listapreco_item ',
'            where id_lista_preco = l_id_listapreco ',
'            and id_item_produto = p_id_item',
'            and id_unidademedida = p_id_unidademedida',
'            and qtd_minima <= p_quantidade',
'            order by qtd_minima desc',
'            fetch first 1 row only;',
'        end if;',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end retorna_valor_unitario;',
'    --',
'    procedure atualiza_quantidades_programadas(        ',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_quantidade_programada_entrega imp_pedidoimportacao_item.quantidade_programada_entrega%type;',
'        l_quantidade_programar_entrega imp_pedidoimportacao_item.quantidade_programar_entrega%type;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.atualiza_quantidades_programadas'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;',
'        v_new := v_old;',
'',
'        select nvl(sum(quantidade),0) into l_quantidade_programada_entrega from imp_entrega_item where id_pedidoimportacao_item = p_id;',
'        l_quantidade_programar_entrega := (v_new.quantidade - nvl(v_new.quantidade_cancelada,0)) - l_quantidade_programada_entrega;',
'',
'        v_new.quantidade_programada_entrega := l_quantidade_programada_entrega;',
'        v_new.quantidade_programar_entrega := l_quantidade_programar_entrega;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        --v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ATUALIZA_QUANTIDADES_PROGRAMADAS'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);    ',
'    end atualiza_quantidades_programadas;',
'    --    ',
'    procedure altera_id_naturezaoperacao_todos_itens(',
'        p_id_naturezaoperacao in imp_pedidoimportacao_item.id_naturezaoperacao%type,',
'        p_id_pedidoimportacao in imp_pedidoimportacao_item.id_pedidoimportacao%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
