'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_id_naturezaoperacao_todos_itens'';',
'        v_pagina := p_pagina;',
'',
'        for item in (',
'            select * from imp_pedidoimportacao_item where id_pedidoimportacao = p_id_pedidoimportacao',
'        ) loop',
'            select * into v_old from imp_pedidoimportacao_item where id = item.id;',
'            v_new := v_old;',
'',
'            v_new.id_naturezaoperacao := p_id_naturezaoperacao;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''ALTERA_ID_NATUREZAOPERACAO_TODOS_ITENS'';',
'',
'            grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'        end loop;',
'    end altera_id_naturezaoperacao_todos_itens;',
'    --',
'    procedure altera_valor_desconto_pedido_item(',
'        p_valor_desconto_pedido_item in imp_pedidoimportacao_item.valor_desconto_pedido_item%type,',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_valor_desconto_pedido_item'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_desconto_pedido_item := p_valor_desconto_pedido_item;',
'        v_new.valor_desconto_pedido_item_unitario := trunc((p_valor_desconto_pedido_item / nullif(v_new.quantidade,0)), 5);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := v_data_alteracao;',
'        --v_new.data_alteracao := sysdate;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_VALOR_DESCONTO_PEDIDO_ITEM'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);        ',
'    end altera_valor_desconto_pedido_item;',
'    --',
'    procedure altera_valor_despesaproforma(',
'        p_valor_despesaproforma in imp_pedidoimportacao_item.valor_despesaproforma%type,',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_valor_despesaproforma'';   ',
'        v_pagina := p_pagina;        ',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_data_alteracao := v_new.data_alteracao;',
'        v_new.valor_despesaproforma := p_valor_despesaproforma;',
'        v_new.valor_despesaproforma_unitario := trunc((p_valor_despesaproforma / nullif(v_new.quantidade,0)), 5);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_VALOR_DESPESAPROFORMA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_valor_despesaproforma;',
'    --',
'    procedure recalcula_rateio_despesaproforma(',
'        p_id_pedidoimportacao in imp_pedidoimportacao_item.id_pedidoimportacao%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id number;',
'        l_id_tenant number;',
'        l_existe_item_despesaproforma number;',
'        l_id_item_despesaproforma number;',
'    begin',
'        select count(1) into l_existe_item_despesaproforma from imp_pedidoimportacao_item_despesaproforma where id_pedidoimportacao = p_id_pedidoimportacao;',
'        if l_existe_item_despesaproforma > 0 then',
unistr('            -- Tratamento exclus\00E3o:'),
'            for item_despesaproforma in (',
'                select id from imp_pedidoimportacao_item_despesaproforma where id_pedidoimportacao = p_id_pedidoimportacao',
'            ) loop',
'                bo_imp_pedidoimportacao_item_despesaproforma.exclui_registro_por_recalculo(item_despesaproforma.id, p_encadeado, p_sucesso, p_messages);',
'            end loop;',
'',
unistr('            -- Tratamento inclus\00E3o:'),
'            for despesaproforma in (',
'                select a.*, b.id id_pedidoimportacao_item from imp_pedidoimportacao_despesaproforma a join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id_pedidoimportacao where a.id_pedidoimportacao = p_id_pedidoimportacao and lower(ind_'
||'incluso_valor_mercadoria) = ''n''',
'            ) loop',
'                bo_imp_pedidoimportacao_item_despesaproforma.inclui_registro_por_recalculo(',
'                    p_id_tenant => despesaproforma.id_tenant,',
'                    p_id_pedidoimportacao => despesaproforma.id_pedidoimportacao,',
'                    p_id_pedidoimportacao_item => despesaproforma.id_pedidoimportacao_item,',
'                    p_id_despesa => despesaproforma.id_despesa,',
'                    p_valor => bo_imp_pedidoimportacao_item_despesaproforma.calcula_rateio(despesaproforma.valor, despesaproforma.id_pedidoimportacao_item, despesaproforma.id_despesa),',
'                    p_id => l_id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'',
unistr('            -- Atualiza valor_despesaproforma ap\00F3s incluir despesas:'),
'            for item_despesaproforma in (',
'                select ',
'                    id_pedidoimportacao_item, ',
'                    nvl(sum(valor), 0) as total_valor',
'                from imp_pedidoimportacao_item_despesaproforma ',
'                where id_pedidoimportacao = p_id_pedidoimportacao',
'                group by id_pedidoimportacao_item',
'            ) loop',
'                altera_valor_despesaproforma(',
'                    p_valor_despesaproforma => item_despesaproforma.total_valor,',
'                    p_id => item_despesaproforma.id_pedidoimportacao_item,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        else',
'            for item in (',
'                select id from imp_pedidoimportacao_item where id_pedidoimportacao = p_id_pedidoimportacao',
'            ) loop',
'                altera_valor_despesaproforma(',
'                    p_valor_despesaproforma => 0,',
'                    p_id => item.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'    end recalcula_rateio_despesaproforma;',
'    --    ',
'    procedure altera_quantidade_faturada(',
'        p_quantidade_faturada in imp_pedidoimportacao_item.quantidade_faturada%type,',
