'    --',
'    procedure altera_pedidoimportacao_item(  ',
'        p_ind_bloqueio_embarque_ate_deferimento_li in imp_pedidoimportacao_item.ind_bloqueio_embarque_ate_deferimento_li%type,',
'        p_ind_licenca_importacao in imp_pedidoimportacao_item.ind_licenca_importacao%type,',
'        p_id_tenant in imp_pedidoimportacao_item.id_tenant%type,',
'        p_id_pedidoimportacao in imp_pedidoimportacao_item.id_pedidoimportacao%type,',
'        p_id_item in imp_pedidoimportacao_item.id_item%type,',
'        p_num_sequencia_item in imp_pedidoimportacao_item.num_sequencia_item%type,',
'        p_id_unidademedida in imp_pedidoimportacao_item.id_unidademedida%type,',
'        p_quantidade_firmada in imp_pedidoimportacao_item.quantidade_firmada%type,',
'        p_quantidade in imp_pedidoimportacao_item.quantidade%type,',
'        p_peso_unitario in imp_pedidoimportacao_item.peso_unitario%type,',
'        p_peso_liquido_total in imp_pedidoimportacao_item.peso_liquido_total%type,',
'        p_valor_unitario in imp_pedidoimportacao_item.valor_unitario%type,',
'        p_valor_desconto_unitario in imp_pedidoimportacao_item.valor_desconto_unitario%type,',
'        p_valor_total in imp_pedidoimportacao_item.valor_total%type,',
'        p_id_naturezaoperacao in imp_pedidoimportacao_item.id_naturezaoperacao%type,',
'        p_num_solicitacao_compra in imp_pedidoimportacao_item.num_solicitacao_compra%type,',
'        p_nome_solicitante in imp_pedidoimportacao_item.nome_solicitante%type,',
'        p_quantidade_programada_entrega in imp_pedidoimportacao_item.quantidade_programada_entrega%type,',
'        p_quantidade_programar_entrega in imp_pedidoimportacao_item.quantidade_programar_entrega%type,',
'        p_quantidade_faturada in imp_pedidoimportacao_item.quantidade_faturada%type,',
'        p_quantidade_faturar in imp_pedidoimportacao_item.quantidade_faturar%type,',
'        p_id_fabricante in imp_pedidoimportacao_item.id_fabricante%type,',
'        p_id_ncm in imp_pedidoimportacao_item.id_ncm%type,',
'        p_id_centrocusto in imp_pedidoimportacao_item.id_centrocusto%type,',
'        p_ind_finalidade in imp_pedidoimportacao_item.ind_finalidade%type,',
'        p_numero_ato_concessorio in imp_pedidoimportacao_item.numero_ato_concessorio%type,',
'        p_data_entrega_desejada in imp_pedidoimportacao_item.data_entrega_desejada%type,',
'        p_quantidade_cancelada in imp_pedidoimportacao_item.quantidade_cancelada%type,',
'        p_valor_desconto_pedido_item in imp_pedidoimportacao_item.valor_desconto_pedido_item%type,',
'        p_valor_despesaproforma in imp_pedidoimportacao_item.valor_despesaproforma%type,',
'        p_valor_despesaproforma_unitario in imp_pedidoimportacao_item.valor_despesaproforma_unitario%type,',
'        p_valor_desconto_pedido_item_unitario in imp_pedidoimportacao_item.valor_desconto_pedido_item_unitario%type, ',
'        p_id in imp_pedidoimportacao_item.id%type, ',
'        p_data_alteracao in imp_pedidoimportacao_item.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_pedidoimportacao_item'';   ',
'        v_pagina := p_pagina;',
'',
'        if nvl(p_quantidade,0) < nvl(p_quantidade_programada_entrega,0) then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''125'',',
'                p_nome_campo => ''quantidade'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;           ',
'            if v_messages.count > 0 then',
'                raise pk_exceptions.e_erro;',
'            end if;',
'        else',
'            select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'            v_new := v_old;',
'',
'            v_new.ind_bloqueio_embarque_ate_deferimento_li := p_ind_bloqueio_embarque_ate_deferimento_li;',
'            v_new.ind_licenca_importacao := p_ind_licenca_importacao;',
'            v_new.id_tenant := p_id_tenant;',
'            v_new.id_pedidoimportacao := p_id_pedidoimportacao;',
'            v_new.id_item := p_id_item;',
'            v_new.num_sequencia_item := p_num_sequencia_item;',
'            v_new.id_unidademedida := p_id_unidademedida;',
'            v_new.quantidade_firmada := p_quantidade_firmada;',
'            v_new.quantidade := p_quantidade;',
'            v_new.peso_unitario := p_peso_unitario;',
'            v_new.peso_liquido_total := p_peso_liquido_total;',
'            v_new.valor_unitario := p_valor_unitario;',
'            v_new.valor_desconto_unitario := p_valor_desconto_unitario;',
'            v_new.valor_total := p_valor_total;',
'            v_new.id_naturezaoperacao := p_id_naturezaoperacao;',
'            v_new.num_solicitacao_compra := p_num_solicitacao_compra;',
'            v_new.nome_solicitante := p_nome_solicitante;',
'            v_new.quantidade_programada_entrega := p_quantidade_programada_entrega;',
'            v_new.quantidade_programar_entrega := p_quantidade_programar_entrega;',
'            v_new.quantidade_faturada := p_quantidade_faturada;',
'            v_new.quantidade_faturar := p_quantidade_faturar;',
'            v_new.id_fabricante := p_id_fabricante;',
'            v_new.id_ncm := p_id_ncm;',
'            v_new.id_centrocusto := p_id_centrocusto;',
'            v_new.ind_finalidade := p_ind_finalidade;',
'            v_new.numero_ato_concessorio := p_numero_ato_concessorio;',
'            v_new.data_entrega_desejada := p_data_entrega_desejada;',
'            v_new.quantidade_cancelada := p_quantidade_cancelada;',
'            v_new.valor_desconto_pedido_item := p_valor_desconto_pedido_item;',
'            v_new.valor_despesaproforma := p_valor_despesaproforma;',
'            v_new.valor_despesaproforma_unitario := p_valor_despesaproforma_unitario;',
'            v_new.valor_desconto_pedido_item_unitario := p_valor_desconto_pedido_item_unitario; ',
'            v_new.id := p_id; ',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'            v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''ALTERA_PEDIDOIMPORTACAO_ITEM'';',
'            grava(p_id,p_encadeado,p_sucesso,p_messages);',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_pedidoimportacao_item;   ',
'    --',
'    procedure altera_entrega_item(',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_qtd_entregas_possue'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767422221613320)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'm_este_item number;',
'        l_entrega_item_quantidade number;',
'    begin',
'        select count(1) into l_qtd_entregas_possuem_este_item from imp_entrega_item where id_pedidoimportacao_item = p_id;',
'',
'        if l_qtd_entregas_possuem_este_item = 1 then',
'            l_entrega_item_quantidade := v_new.quantidade;',
'        end if;',
'',
'        for entrega_item in (',
'            select * from imp_entrega_item where id_pedidoimportacao_item = p_id',
'        ) loop',
'            bo_imp_entrega_item.altera_registro(',
'                p_id_unidademedida => v_new.id_unidademedida,',
'                p_id_ncm => v_new.id_ncm,',
'                p_id_naturezaoperacao => v_new.id_naturezaoperacao,',
'                p_peso_unitario => v_new.peso_unitario,',
'                p_valor_unitario => v_new.valor_unitario,',
'                p_valor_desconto_unitario => v_new.valor_desconto_unitario,',
'                p_valor_desconto_pedido_item_unitario => v_new.valor_desconto_pedido_item_unitario,',
'                p_id_fabricante => v_new.id_fabricante,',
'                p_ind_licenca_importacao => v_new.ind_licenca_importacao,',
'                p_ind_bloqueio_embarque_ate_deferimento_li => v_new.ind_bloqueio_embarque_ate_deferimento_li,',
'',
'                p_quantidade => nvl(l_entrega_item_quantidade, entrega_item.quantidade),',
'',
'                p_peso_liquido_total => (nvl(l_entrega_item_quantidade, entrega_item.quantidade) * v_new.peso_unitario),',
'                p_valor_total_condicao_venda => ((nvl(l_entrega_item_quantidade, entrega_item.quantidade) * (v_new.valor_unitario - v_new.valor_desconto_unitario)) + v_new.valor_despesaproforma),',
'                p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(v_new.id_fabricante),',
'                p_valor_despesaproforma => (nvl(l_entrega_item_quantidade, entrega_item.quantidade) * v_new.valor_despesaproforma_unitario),--v_new.valor_despesaproforma,',
'                p_valor_despesaproforma_unitario => v_new.valor_despesaproforma_unitario,',
'                --',
'                p_id_tenant => entrega_item.id_tenant,',
'                p_id_entrega => entrega_item.id_entrega,',
'                p_id_pedidoimportacao_item => entrega_item.id_pedidoimportacao_item,',
'                p_id_item => entrega_item.id_item,',
'                p_quantidade_faturada => entrega_item.quantidade_faturada,',
'                p_quantidade_saldo => entrega_item.quantidade_saldo,',
'                p_peso_bruto_unitario => entrega_item.peso_bruto_unitario,',
'                p_peso_bruto_total => entrega_item.peso_bruto_total,',
'                p_valor_total_desconto_invoice_item => entrega_item.valor_total_desconto_invoice_item,',
'                p_valor_total_despesa_invoice_item => entrega_item.valor_total_despesa_invoice_item,',
'                p_ind_tratamento_saldo => entrega_item.ind_tratamento_saldo,',
'                p_id => entrega_item.id,',
'                p_data_alteracao => entrega_item.data_alteracao,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_entrega_item;',
'    --',
'    procedure altera_quantidade_firmada(',
'        p_quantidade_firmada in imp_pedidoimportacao_item.quantidade_firmada%type,',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_quantidade_firmada'';   ',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.quantidade_firmada := p_quantidade_firmada;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_QUANTIDADE_FIRMADA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);       ',
'    end altera_quantidade_firmada;',
'    --',
'    procedure altera_entrega_item_valor_desconto_pedido_item_unitario(',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_pedidoimportacao number;',
'    begin',
'        for entrega_item in (',
'            select id from imp_entrega_item where id_pedidoimportacao_item = p_id',
'        ) loop',
'            bo_imp_entrega_item.altera_valor_desconto_pedido_item_unitario(',
'                p_valor_desconto_pedido_item_unitario => v_new.valor_desconto_pedido_item_unitario,',
'                p_id => entrega_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;        ',
'    end altera_entrega_item_valor_desconto_pedido_item_unitario;',
'    --',
'    procedure altera_registros_valor_desconto_pedido_item(',
'        p_id_pedidoimportacao in imp_pedidoimportacao_item.id_pedidoimportacao%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_valor_desconto number;',
'        l_motivo_desconto varchar2(4000);',
'    begin',
'        for pedidoimportacao_item in (',
'            select id from imp_pedidoimportacao_item where id_pedidoimportacao = p_id_pedidoimportacao',
'        ) loop',
'            altera_valor_desconto_pedido_item(',
'                p_valor_desconto_pedido_item => bo_imp_pedidoimportacao.retorna_valor_desconto_pedido_item(p_id_pedidoimportacao, pedidoimportacao_item.id),',
'                p_id => pedidoimportacao_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_registros_valor_desconto_pedido_item;',
'    --',
'    procedure altera_entrega_item_valor_despesaproforma_unitario(',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for entrega_item in (',
'            select id from imp_entrega_item where id_pedidoimportacao_item = p_id',
'        ) loop',
'            bo_imp_entrega_item.altera_valor_despesaproforma_unitario(',
'                p_valor_despesaproforma_unitario => v_new.valor_despesaproforma_unitario,',
'                p_id => entrega_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_entrega_item_valor_despesaproforma_unitario;',
'    --',
'    procedure altera_divergencia_pedidoimportacao_item(  ',
'        p_id_unidademedida in imp_pedidoimportacao_item.id_unidademedida%type,',
'        p_id_ncm in imp_pedidoimportacao_item.id_ncm%type, ',
'        p_quantidade in imp_pedidoimportacao_item.quantidade%type,',
'        p_peso_unitario in imp_pedidoimportacao_item.peso_unitario%type,',
'        p_peso_liquido_total in imp_pedidoimportacao_item.peso_liquido_total%type,',
'        p_valor_unitario in imp_pedidoimportacao_item.valor_unitario%type,',
'        p_valor_desconto_unitario in imp_pedidoimportacao_item.valor_desconto_unitario%type,',
'        p_valor_total in imp_pedidoimportacao_item.valor_total%type,',
'        p_quantidade_programada_entrega in imp_pedidoimportacao_item.quantidade_programada_entrega%type,',
'        p_quantidade_programar_entrega in imp_pedidoimportacao_item.quantidade_programar_entrega%type,',
'        p_quantidade_faturada in imp_pedidoimportacao_item.quantidade_faturada%type,',
'        p_quantidade_faturar in imp_pedidoimportacao_item.quantidade_faturar%type,',
'        p_quantidade_cancelada in imp_pedidoimportacao_item.quantidade_cancelada%type,        ',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin        ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_divergencia_pedidoimportacao_item'';   ',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.id_unidademedida := p_id_unidademedida;',
'        v_new.id_ncm := p_id_ncm;',
'        v_new.quantidade := p_quantidade;',
'        v_new.peso_unitario := p_peso_unitario;',
'        v_new.peso_liquido_total := p_peso_liquido_total;',
'        v_new.valor_unitario := p_valor_unitario;',
'        v_new.valor_desconto_unitario := p_valor_desconto_unitario;',
'        v_new.valor_total := p_valor_total;',
'        v_new.quantidade_programada_entrega := p_quantidade_programada_entrega;',
'        v_new.quantidade_programar_entrega := p_quantidade_programar_entrega;',
'        v_new.quantidade_faturada := p_quantidade_faturada;',
'        v_new.quantidade_faturar := p_quantidade_faturar;',
'        v_new.quantidade_cancelada := p_quantidade_cancelada;         ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_DIVERGENCIA_PEDIDOIMPORTACAO_ITEM'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);        ',
'    exception ',
'        when pk_exceptions.e_erro then                ',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end altera_divergencia_pedidoimportacao_item;',
'    --',
'    procedure altera_registro_ind_tratamento_saldo(',
'        p_quantidade in imp_pedidoimportacao_item.quantidade%type,',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_registro_ind_tratamento_saldo'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.quantidade := p_quantidade;',
'        v_new.peso_liquido_total := (p_quantidade * v_new.peso_unitario);        ',
'        v_new.valor_total := (p_quantidade * (v_new.valor_unitario - v_new.valor_desconto_unitario));',
'        v_new.quantidade_programada_entrega := (v_old.quantidade_programada_entrega - (v_old.quantidade - p_quantidade));',
'        v_new.quantidade_programar_entrega := (v_new.quantidade - v_new.quantidade_programada_entrega);',
'        --v_new.quantidade_faturada := p_quantidade_faturada;',
'        --v_new.quantidade_faturar := p_quantidade_faturar;',
'        v_new.quantidade_cancelada := (nvl(v_old.quantidade_cancelada, 0) + (v_old.quantidade - p_quantidade));',
'        --v_new.valor_desconto_pedido_item := p_valor_desconto_pedido_item;',
'        v_new.valor_desconto_pedido_item_unitario := (v_new.valor_desconto_pedido_item / p_quantidade);',
'        --v_new.valor_despesaproforma := p_valor_despesaproforma;',
'        v_new.valor_despesaproforma_unitario := (v_new.valor_despesaproforma / p_quantidade);',
'        --v_new.quantidade_firmada := p_quantidade_firmada;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);        ',
'    end altera_registro_ind_tratamento_saldo;',
'    --',
'    procedure altera_entrega_item_rateios(',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for entrega_item in (',
'            select id from imp_entrega_item where id_pedidoimportacao_item = p_id',
'        ) loop',
'            bo_imp_entrega_item.altera_rateios(',
'                p_valor_despesaproforma_unitario => v_new.valor_despesaproforma_unitario,',
'                p_valor_desconto_pedido_item_unitario => v_new.valor_desconto_pedido_item_unitario,',
'                p_id => entrega_item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_entrega_item_rateios;',
'    --',
'    procedure altera_quantidade_tratamento_saldo(',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_quantidade_programada_entrega imp_pedidoimportacao_item.quantidade_programada_entrega%type;',
'        l_quantidade_programar_entrega imp_pedidoimportacao_item.quantidade_programar_entrega%type;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_quantidade_tratamento_saldo'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;',
'        v_new := v_old;',
'',
'        select nvl(sum(quantidade),0) into l_quantidade_programada_entrega from imp_entrega_item where id_pedidoimportacao_item = p_id;',
'        ',
'        if l_quantidade_programada_entrega > v_new.quantidade_programada_entrega then            ',
'            v_new.quantidade := (v_new.quantidade + (l_quantidade_programada_entrega - v_new.quantidade_programada_entrega));',
'            l_quantidade_programar_entrega := v_new.quantidade_programar_entrega;',
'        else',
'            v_new.quantidade := (v_new.quantidade + (l_quantidade_programada_entrega - v_new.quantidade_programada_entrega));',
'            l_quantidade_programar_entrega := (v_new.quantidade /*- nvl(v_new.quantidade_cancelada,0)*/) - l_quantidade_programada_entrega;            ',
'        end if;',
'',
'        v_new.quantidade_programada_entrega := l_quantidade_programada_entrega;',
'        v_new.quantidade_programar_entrega:= l_quantidade_programar_entrega;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        --v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ATUALIZA_QUANTIDADES_PROGRAMADAS'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);    ',
'    end altera_quantidade_tratamento_saldo;',
'    --',
'    procedure altera_quantidade_cancelada(  ',
'        p_quantidade_cancelada in imp_pedidoimportacao_item.quantidade_cancelada%type,',
'        p_id in imp_pedidoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_pedidoimportacao_item.altera_quantidade_cancelada'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_pedidoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'        ',
'        v_new.quantidade_cancelada := (nvl(v_old.quantidade_cancelada,0) + nvl(p_quantidade_cancelada,0));',
'        v_new.quantidade := (nvl(v_old.quantidade,0) - nvl(p_quantidade_cancelada,0));',
'        v_new.quantidade_programar_entrega := 0;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_QUANTIDADE_CANCELADA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_quantidade_cancelada;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_pedidoimportacao_item;',
'/'))
);
end;
/
