'',
'-- Objeto: BO_IMP_ENTREGA',
'-- Data: 24/04/2026',
'-- Motivo: Desenvolvimentos da invoice',
'-- Jira: IMP00176_invoice_aprovar',
'',
'create or replace package            bo_imp_entrega',
'is',
