'    --',
'    procedure cria(',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_entrega.id%type',
'    );',
'    procedure grava(',
'        p_id in imp_entrega.id%type,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(',
'        p_id_tenant in imp_entrega.id_tenant%type,',
'        p_id_pedidoimportacao in imp_entrega.id_pedidoimportacao%type,',
'        p_num_entrega in imp_entrega.num_entrega%type,',
'        p_id_processoimportacao in imp_entrega.id_processoimportacao%type,',
'        p_ind_modalidade_importacao in imp_entrega.ind_modalidade_importacao%type,',
'        p_id_exportador in imp_entrega.id_exportador%type,',
'        p_id_adquirente in imp_entrega.id_adquirente%type,',
'        p_id_endereco_origem in imp_entrega.id_endereco_origem%type,',
'        p_id_local_embarque in imp_entrega.id_local_embarque%type,',
'        p_id_local_desembarque in imp_entrega.id_local_desembarque%type,',
'        p_id_endereco_destino in imp_entrega.id_endereco_destino%type,',
'        p_id_incoterm in imp_entrega.id_incoterm%type,',
'        p_ind_status_entrega in imp_entrega.ind_status_entrega%type,',
'        p_data_disponivel_calculada in imp_entrega.data_disponivel_calculada%type,',
'        p_data_disponivel_informada in imp_entrega.data_disponivel_informada%type,',
'        p_data_disponivel_real in imp_entrega.data_disponivel_real%type,',
'        p_data_embarque_calculada in imp_entrega.data_embarque_calculada%type,',
'        p_data_embarque_informada in imp_entrega.data_embarque_informada%type,',
'        p_data_embarque_real in imp_entrega.data_embarque_real%type,',
'        p_data_desembarque_calculada in imp_entrega.data_desembarque_calculada%type,',
'        p_data_desembarque_informada in imp_entrega.data_desembarque_informada%type,',
'        p_data_desembarque_real in imp_entrega.data_desembarque_real%type,',
'        p_data_nacionalizacao_calculada in imp_entrega.data_nacionalizacao_calculada%type,',
'        p_data_nacionalizacao_informada in imp_entrega.data_nacionalizacao_informada%type,',
'        p_data_nacionalizacao_real in imp_entrega.data_nacionalizacao_real%type,',
'        p_data_recebimento_calculada in imp_entrega.data_recebimento_calculada%type,',
'        p_data_recebimento_informada in imp_entrega.data_recebimento_informada%type,',
'        p_data_recebimento_real in imp_entrega.data_recebimento_real%type,',
'        p_valor_total_condicao_venda in imp_entrega.valor_total_condicao_venda%type,',
'        p_id_importador in imp_entrega.id_importador%type,',
'        p_id_viatransporte in imp_entrega.id_viatransporte%type,',
'        p_id_invoice in imp_entrega.id_invoice%type,',
'        p_valor_total_financeiro in imp_entrega.valor_total_financeiro%type,',
'        p_id out imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure altera_registro(',
