'        apex_json.write(''data_embarque_informada'', p_rec.data_embarque_informada, true);',
'        apex_json.write(''data_embarque_real'', p_rec.data_embarque_real, true);',
'        apex_json.write(''data_desembarque_calculada'', p_rec.data_desembarque_calculada, true);',
'        apex_json.write(''data_desembarque_informada'', p_rec.data_desembarque_informada, true);',
'        apex_json.write(''data_desembarque_real'', p_rec.data_desembarque_real, true);',
'        apex_json.write(''data_nacionalizacao_calculada'', p_rec.data_nacionalizacao_calculada, true);',
'        apex_json.write(''data_nacionalizacao_informada'', p_rec.data_nacionalizacao_informada, true);',
'        apex_json.write(''data_nacionalizacao_real'', p_rec.data_nacionalizacao_real, true);',
'        apex_json.write(''data_recebimento_calculada'', p_rec.data_recebimento_calculada, true);',
'        apex_json.write(''data_recebimento_informada'', p_rec.data_recebimento_informada, true);',
'        apex_json.write(''data_recebimento_real'', p_rec.data_recebimento_real, true);',
'        apex_json.write(''valor_total_condicao_venda'', p_rec.valor_total_condicao_venda, true);',
'        apex_json.write(''id_importador'', p_rec.id_importador, true);',
'        apex_json.write(''id_viatransporte'', p_rec.id_viatransporte, true);',
'        apex_json.write(''id_invoice'', p_rec.id_invoice, true);',
'        apex_json.write(''valor_total_financeiro'', p_rec.valor_total_financeiro, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;',
