'    --<CUSTOMIZADO_INICIO>',
'    --',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
unistr('    -- Faz altera\00E7\00E3o de status generalista'),
'        if v_new.id_processoimportacao is not null then',
'                v_new.ind_status_entrega := 4;',
'    --          "id_processoimportacao",                "data_disponivel_real"                 "data_disponivel_informada"                  "data_disponivel_calculada"                  "data_embarque_real",                "data_embarque_informada",  '
||'              "data_embarque_calculada"',
'        elsif v_new.id_processoimportacao is null AND v_new.data_embarque_real is null AND v_new.data_disponivel_real is not null  then',
'                v_new.ind_status_entrega := 3;',
'    --              id_processoimportacao"                 data_embarque_real"                  "data_disponivel_real"',
'',
'        elsif (v_new.id_processoimportacao is null AND v_new.data_disponivel_real is null AND v_new.data_embarque_real is null AND v_new.data_disponivel_informada is not null) OR (v_new.data_disponivel_calculada is not null) then',
'                v_new.ind_status_entrega := 2;',
'',
'        elsif v_new.id_processoimportacao is null AND v_new.data_disponivel_real is null AND v_new.data_disponivel_informada is  null AND v_new.data_disponivel_calculada is  null AND v_new.data_embarque_real is null AND v_new.data_embarque_informada '
||'is  null AND v_new.data_embarque_calculada is null then',
'                v_new.ind_status_entrega := 1;',
'    --             "id_processoimportacao"                 "data_disponivel_real"                  data_embarque_real"                 "data_disponivel_informada"",            ou      ""data_disponivel_calculada"", diferente de null"',
'        end if;',
'',
'        configura_datas_calculadas;',
'',
'',
'    end;',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        if v_operacao = ''saldo_nova_entrega'' then',
'            v_id_itens := apex_string.split(l_id_itens, ''_'');',
'            /* Executa insert imp_entrega_item */',
'            for i in 1..v_id_itens.count loop',
'                for rec in (',
'                    select',
'                        a.id_item,',
'                        b.id_ncm,',
'                        a.id_unidademedida,',
'                        a.quantidade_programar_entrega,',
'                        a.peso_unitario,',
'                        a.valor_unitario,',
'                        a.valor_desconto_unitario,',
'                        a.valor_desconto_pedido_item_unitario,',
'                        a.valor_despesaproforma_unitario,',
'                        a.id_naturezaoperacao,',
'                        a.id_fabricante,',
'                        a.ind_licenca_importacao,',
'                        a.ind_bloqueio_embarque_ate_deferimento_li',
'                from imp_pedidoimportacao_item a',
'                join ng_item_produto b on b.id_item = a.id_item',
'                where a.id = v_id_itens(i))',
'                loop',
'                    bo_imp_entrega_item.inclui_registro(',
'                        p_id_tenant => v_new.id_tenant,',
'                        p_id_entrega => v_new.id,',
'                        p_id_pedidoimportacao_item => v_id_itens(i),',
'                        p_id_item => rec.id_item,',
'                        p_id_ncm => rec.id_ncm,',
'                        p_id_unidademedida => rec.id_unidademedida,',
'                        p_quantidade => rec.quantidade_programar_entrega,',
'                        p_quantidade_faturada => null,',
'                        p_quantidade_saldo => rec.quantidade_programar_entrega,',
'                        p_peso_unitario => rec.peso_unitario,',
'                        p_peso_liquido_total => rec.quantidade_programar_entrega * rec.peso_unitario,',
'                        p_peso_bruto_unitario => null,',
'                        p_peso_bruto_total => null,',
'                        p_valor_unitario => rec.valor_unitario,',
'                        p_valor_desconto_unitario => rec.valor_desconto_unitario,',
'                        p_valor_desconto_pedido_item_unitario => rec.valor_desconto_pedido_item_unitario,',
'                        p_valor_despesaproforma => (rec.quantidade_programar_entrega * rec.valor_despesaproforma_unitario),',
'                        p_valor_despesaproforma_unitario => rec.valor_despesaproforma_unitario,',
'                        p_valor_total_condicao_venda => rec.quantidade_programar_entrega * (rec.valor_unitario - rec.valor_desconto_unitario),',
'			 									p_valor_total_desconto_invoice_item => null,',
'			 									p_valor_total_despesa_invoice_item => null,',
'                        p_id_naturezaoperacao => rec.id_naturezaoperacao,',
'                        p_id_fabricante => rec.id_fabricante,',
'                        p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(rec.id_fabricante),',
'                        p_ind_licenca_importacao => rec.ind_licenca_importacao,',
'                        p_ind_bloqueio_embarque_ate_deferimento_li => rec.ind_bloqueio_embarque_ate_deferimento_li,',
'                        p_ind_tratamento_saldo => null,',
'                        p_id => v_new.id,',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'',
'                    bo_imp_entrega_item.atualiza_qtd_programada(',
'                        p_id => v_new.id,',
'                        p_quantidade => rec.quantidade_programar_entrega,',
'                        p_encadeado => true,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end loop;',
'            end loop;',
'            bo_imp_pedidoimportacao.altera_quantidade_entrega(',
'                p_id => v_new.id_pedidoimportacao,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'',
'            gera_parcelas_entrega(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        else',
'            inclui_itens_saldo(v_new.id);',
'        end if;',
'        altera_quantidade_entrega_pedido (v_new.id_pedidoimportacao,true,p_sucesso,p_messages);',
'    end;',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        -- Verificar momento exato que este gatilho deve ser chamado:',
'		-- if (v_old.id_exportador != v_new.id_exportador) OR (v_old.id_importador != v_new.id_importador) OR (v_old.id_adquirente != v_new.id_adquirente) OR (v_old.id_incoterm != v_new.id_incoterm) then',
'        -- 	hook_valida_vinculo_invoice;',
'		-- end if;',
'',
unistr('    --     -- Faz altera\00E7\00E3o de status generalista'),
'    --     if v_new.id_processoimportacao is not null then',
'    --             v_new.ind_status_entrega := 4;',
'    -- --          "id_processoimportacao",                "data_disponivel_real"                 "data_disponivel_informada"                  "data_disponivel_calculada"                  "data_embarque_real",                "data_embarque_informada"'
||',                "data_embarque_calculada"',
'    --     elsif v_new.id_processoimportacao is null AND v_new.data_embarque_real is null AND v_new.data_disponivel_real is not null  then',
'    --             v_new.ind_status_entrega := 3;',
'    -- --              id_processoimportacao"                 data_embarque_real"                  "data_disponivel_real"',
'',
'    --     elsif (v_new.id_processoimportacao is null AND v_new.data_disponivel_real is null AND v_new.data_embarque_real is null AND v_new.data_disponivel_informada is not null) OR (v_new.data_disponivel_calculada is not null) then',
'    --             v_new.ind_status_entrega := 2;',
'',
'    --     elsif v_new.id_processoimportacao is null AND v_new.data_disponivel_real is null AND v_new.data_disponivel_informada is  null AND v_new.data_disponivel_calculada is  null AND v_new.data_embarque_real is null AND v_new.data_embarque_informa'
||'da is  null AND v_new.data_embarque_calculada is null then',
'    --             v_new.ind_status_entrega := 1;',
'    -- --             "id_processoimportacao"                 "data_disponivel_real"                  data_embarque_real"                 "data_disponivel_informada"",            ou      ""data_disponivel_calculada"", diferente de null"',
'    --     end if;',
unistr('    -- --altera o id_processo na invoice se id_processo e id_invoice tamb\00E9m nao'),
'    --     if v_new.id_processoimportacao is not null AND v_new.id_invoice is NOT null then',
'    --             altera_idprocesso_invoice (v_new.id_pedidoimportacao,true,p_sucesso,p_messages);',
'    --     end if;',
'',
'        configura_datas_calculadas;',
'    end;',
'    --',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        if v_operacao = ''atualiza_natureza_operacao'' then',
'            for item in (',
'                select * from imp_entrega_item where id_entrega = v_new.id',
'            ) loop',
'                bo_imp_entrega_item.altera_registro(',
'                    p_id_tenant                           => item.id_tenant,',
'                    p_id_entrega                          => item.id_entrega,',
'                    p_id_pedidoimportacao_item            => item.id_pedidoimportacao_item,',
'                    p_id_item                             => item.id_item,',
'                    p_id_ncm                              => item.id_ncm,',
'                    p_id_unidademedida                    => item.id_unidademedida,',
'                    p_quantidade                          => item.quantidade,',
'                    p_quantidade_faturada                 => item.quantidade_faturada,',
'                    p_quantidade_saldo                    => item.quantidade_saldo,',
'                    p_peso_unitario                       => item.peso_unitario,',
'                    p_peso_liquido_total                  => item.peso_liquido_total,',
'                    p_peso_bruto_unitario                 => item.peso_bruto_unitario,',
'                    p_peso_bruto_total                    => item.peso_bruto_total,',
'                    p_valor_unitario                      => item.valor_unitario,',
'                    p_valor_desconto_unitario             => item.valor_desconto_unitario,',
'                    p_valor_desconto_pedido_item_unitario => item.valor_desconto_pedido_item_unitario,',
'                    p_valor_despesaproforma               => item.valor_despesaproforma,',
'                    p_valor_despesaproforma_unitario      => item.valor_despesaproforma_unitario,',
'                    p_valor_total_condicao_venda          => item.valor_total_condicao_venda,',
'		                p_valor_total_desconto_invoice_item   => item.valor_total_desconto_invoice_item,',
'                    p_valor_total_despesa_invoice_item    => item.valor_total_despesa_invoice_item,',
'                    p_id_naturezaoperacao                 => item.id_naturezaoperacao,',
'                    p_id_fabricante                       => item.id_fabricante,',
'                    p_id_pais_origem                      => item.id_pais_origem,',
'                    p_ind_licenca_importacao              => item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo                => item.ind_tratamento_saldo,',
'                    p_id                                  => item.id,',
'                    p_encadeado                           => true,',
'                    p_data_alteracao                      => item.data_alteracao,',
'                    p_sucesso                             => p_sucesso,',
'                    p_messages                            => p_messages',
'                );',
'            end loop;',
'        end if;',
'        altera_pedidoimportacao_pagamento_data_vencimento_prevista(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
unistr('        -- Tratameto diverg\00EAncias id_incoterm:'),
'        if v_operacao = ''ALTERA_DIVERGENCIAS'' and v_old.id_incoterm != v_new.id_incoterm then',
'            altera_entrega_item_tributos(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''CONFIRMAR_DISPONIBILIDADE'' then',
'            gera_titulos_confirmacao_disponibilidade(p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''DESCONFIRMAR_DISPONIBILIDADE'' then',
'            cancela_titulos_desconfirmacao_disponibilidade(p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''ALTERA_REGISTRO_ID_PROCESSOIMPORTACAO'' then',
'            atualiza_processo_apos_vincular_entrega(p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end;',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'        v_qtd_entrega number;',
'    begin',
'        select count(*) into v_qtd_entrega from imp_entrega where id_pedidoimportacao = v_old.id_pedidoimportacao;',
'',
'        if v_qtd_entrega < 1 then',
'            pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => 95,',
'                    p_nome_campo => ''num_entrega'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'            );',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        else',
'                -- Deve-se excluir os itens da entrega antes de excluir a entrega, pois assim facilita o controle das colunas de quantidade dos itens do pedido:',
'                exclui_entrega_item(',
'                    p_id => v_old.id,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'',
'                bo_imp_pedidoimportacao.altera_quantidade_entrega(',
'                    p_quantidade_entrega => null,',
'                    p_id => v_old.id_pedidoimportacao,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'        end if;',
'',
'    end;',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        altera_quantidade_entrega_pedido (v_old.id_pedidoimportacao,true,p_sucesso,p_messages);',
'    end;',
'    --',
