'',
'    function gera_sequencia (',
'        p_id_pedidoimportacao in imp_pedidoimportacao.id%TYPE',
'    ) return number is',
'        l_contador number := 0;',
'    begin',
'        select nvl(max(num_entrega), 0) into l_contador from imp_entrega where id_pedidoimportacao = p_id_pedidoimportacao;',
'        return l_contador + 1;',
'    end gera_sequencia;',
'    --',
'    procedure inclui_itens_saldo (',
'        p_id in imp_entrega.id%type',
'    ) is',
'        l_id_pedidoimportacao number;',
'        l_qtd_entregas number;',
'        l_id_entrega_item number;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega.inclui_itens_saldo'';',
'        select id_pedidoimportacao into l_id_pedidoimportacao from imp_entrega where id = p_id;',
'        select count(1) into l_qtd_entregas from imp_entrega where id_pedidoimportacao = l_id_pedidoimportacao;        ',
'        if v_quantidade_entrega = 1 then',
'        APEX_DEBUG.ERROR(''Encontrou 1 entrega!'');',
'            for item in (',
'                select',
'                    a.id,',
'                    a.id_tenant,',
'                    a.id_item,',
'                    b.id_ncm,',
'                    a.id_unidademedida,',
'                    a.quantidade_programar_entrega,',
'                    a.peso_unitario,',
'                    a.valor_unitario,',
'                    a.valor_desconto_unitario,',
'                    a.valor_desconto_pedido_item_unitario,',
'                    a.valor_despesaproforma_unitario,',
'                    a.id_naturezaoperacao,',
'                    a.id_fabricante,',
'                    a.ind_licenca_importacao,',
'                    a.ind_bloqueio_embarque_ate_deferimento_li',
'                from imp_pedidoimportacao_item a',
'                join ng_item_produto b on b.id_item = a.id_item',
'                where id_pedidoimportacao = l_id_pedidoimportacao',
'            ) loop',
'                bo_imp_entrega_item.inclui_registro(',
'                    p_id_tenant => item.id_tenant,',
'                    p_id_entrega => p_id,',
'                    p_id_pedidoimportacao_item => item.id,',
'                    p_id_item => item.id_item,',
'                    p_id_ncm => item.id_ncm,',
'                    p_id_unidademedida => item.id_unidademedida,',
'                    p_quantidade => item.quantidade_programar_entrega,',
'                    p_quantidade_faturada => null,',
'                    p_quantidade_saldo => item.quantidade_programar_entrega,',
'                    p_peso_unitario => item.peso_unitario,',
'                    p_peso_liquido_total => (item.quantidade_programar_entrega * item.peso_unitario),',
'                    p_peso_bruto_unitario => null,',
'                    p_peso_bruto_total => null,',
'                    p_valor_unitario => item.valor_unitario,',
'                    p_valor_desconto_unitario => item.valor_desconto_unitario,',
'                    p_valor_desconto_pedido_item_unitario => item.valor_desconto_pedido_item_unitario,',
'                    p_valor_despesaproforma => (item.quantidade_programar_entrega * item.valor_despesaproforma_unitario),',
'                    p_valor_despesaproforma_unitario => item.valor_despesaproforma_unitario,',
'                    p_valor_total_condicao_venda => (item.quantidade_programar_entrega * (item.valor_unitario - item.valor_desconto_unitario)),',
'		    		p_valor_total_desconto_invoice_item => null,',
'                    p_valor_total_despesa_invoice_item => null,',
'                    p_id_naturezaoperacao => item.id_naturezaoperacao,',
'                    p_id_fabricante => item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(item.id_fabricante),',
'                    p_ind_licenca_importacao => item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo => null,',
'                    p_id => l_id_entrega_item,',
'                    p_encadeado => true,',
'                    p_sucesso => l_sucesso,',
'                    p_messages => l_messages',
'                );',
'            end loop;',
'        end if;',
'    end;',
'    --',
'    procedure atualiza_quantidades_pedidoimportacao_item(',
'        p_id_pedidoimportacao imp_pedidoimportacao.id%type',
'    ) is',
'    begin',
'        for itens in (',
'            select id from imp_pedidoimportacao_item where id_pedidoimportacao = p_id_pedidoimportacao',
'        ) loop',
'            bo_imp_pedidoimportacao_item.executa_altera_registro(itens.id);',
'        end loop;',
'    end;',
'    --',
'    procedure saldo_nova_entrega(',
'        p_id_tenant in imp_entrega.id_tenant%type,',
'        p_id_pedidoimportacao in imp_entrega.id_pedidoimportacao%type,',
'        p_num_entrega in imp_entrega.num_entrega%type,',
'        p_id_processoimportacao in imp_entrega.id_processoimportacao%type,',
'        p_ind_modalidade_importacao in imp_entrega.ind_modalidade_importacao%type,',
'        p_id_exportador in imp_entrega.id_exportador%type,',
'        p_id_importador in imp_entrega.id_importador%type,',
'        p_id_adquirente in imp_entrega.id_adquirente%type,',
'        p_id_endereco_origem in imp_entrega.id_endereco_origem%type,',
'        p_id_local_embarque in imp_entrega.id_local_embarque%type,',
'        p_id_local_desembarque in imp_entrega.id_local_desembarque%type,',
'        p_id_endereco_destino in imp_entrega.id_endereco_destino%type,',
'        p_id_viatransporte in imp_entrega.id_viatransporte%type,',
'        p_id_incoterm in imp_entrega.id_incoterm%type,',
'        p_ind_status_entrega in imp_entrega.ind_status_entrega%type,',
'        p_data_disponivel_calculada in imp_entrega.data_disponivel_calculada%type,',
'        p_data_disponivel_informada in imp_entrega.data_disponivel_informada%type,',
'        p_data_disponivel_real in imp_entrega.data_disponivel_real%type,',
'        p_data_embarque_calculada in imp_entrega.data_embarque_calculada%type,',
'        p_data_embarque_informada in imp_entrega.data_embarque_informada%type,',
'        p_data_embarque_real in imp_entrega.data_embarque_real%type,',
'        p_data_desembarque_calculada in imp_entrega.data_desembarque_calculada%type,',
'        p_data_desembarque_informada in imp_entrega.data_desembarque_informada%type,',
'        p_data_desembarque_real in imp_entrega.data_desembarque_real%type,',
'        p_data_nacionalizacao_calculada in imp_entrega.data_nacionalizacao_calculada%type,',
'        p_data_nacionalizacao_informada in imp_entrega.data_nacionalizacao_informada%type,',
'        p_data_nacionalizacao_real in imp_entrega.data_nacionalizacao_real%type,',
'        p_data_recebimento_calculada in imp_entrega.data_recebimento_calculada%type,',
'        p_data_recebimento_informada in imp_entrega.data_recebimento_informada%type,',
'        p_data_recebimento_real in imp_entrega.data_recebimento_real%type,',
'        p_valor_total_condicao_venda in imp_entrega.valor_total_condicao_venda%type,',
'				p_valor_total_financeiro in imp_entrega.valor_total_financeiro%type,',
'        p_id out imp_entrega.id%type,',
'        p_id_itens in varchar2,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        v_id_itens apex_t_varchar2;',
'        l_id number;',
'        --',
'        l_id_item imp_pedidoimportacao_item.id_item%type;',
'        l_id_ncm ng_item_produto.id_ncm%type;',
'        l_id_unidademedida imp_pedidoimportacao_item.id_unidademedida%type;',
'        l_quantidade_programar_entrega imp_pedidoimportacao_item.quantidade_programar_entrega%type;',
'        l_peso_unitario imp_pedidoimportacao_item.peso_unitario%type;',
'        l_valor_unitario imp_pedidoimportacao_item.valor_unitario%type;',
'        l_valor_desconto_unitario imp_pedidoimportacao_item.valor_desconto_unitario%type;',
'        l_id_naturezaoperacao imp_pedidoimportacao_item.id_naturezaoperacao%type;',
'        l_id_fabricante imp_pedidoimportacao_item.id_fabricante%type;',
'        --l_ind_licenca_importacao imp_pedidoimportacao_item.ind_licenca_importacao%type;',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega.saldo_nova_entrega'';',
'        v_pagina := p_pagina;',
'        l_id_itens := p_id_itens;',
'        v_operacao := ''saldo_nova_entrega'';',
'        --',
'        --',
'        /* Seta valores passados por parametros */',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_pedidoimportacao := p_id_pedidoimportacao;',
'        v_new.num_entrega := p_num_entrega;',
'        v_new.id_processoimportacao := p_id_processoimportacao;',
'        v_new.ind_modalidade_importacao := p_ind_modalidade_importacao;',
'        v_new.id_exportador := p_id_exportador;',
'        v_new.id_importador := p_id_importador;',
'        v_new.id_adquirente := p_id_adquirente;',
'        v_new.id_endereco_origem := p_id_endereco_origem;',
