'    --',
'    function calcula_total_tributos(',
'        p_id in imp_entrega.id%type',
'    ) return number is',
'        l_id_moeda_pedido number;',
'        l_total_tributo number := 0;',
'        l_valor_antidumping number := 0;',
'        l_valor_multa number := 0;',
'    begin',
'        select a.id_moeda into l_id_moeda_pedido from imp_pedidoimportacao a join imp_entrega b on b.id_pedidoimportacao = a.id where b.id = p_id;',
'',
'        select',
'            sum(valor_ii) +',
'            sum(valor_ipi) +',
'            sum(valor_pis) +',
'            sum(valor_cofins) +',
'            sum(valor_cbs) +',
'            sum(valor_icms) +',
'            sum(nvl(valor_icms_st, 0)) +',
'            sum(valor_ibs)',
'        into',
'            l_total_tributo',
'        from imp_entrega_item_tributo a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_entrega c on c.id = b.id_entrega',
'        where c.id = p_id;',
'',
'        select nvl(sum(nvl((bo_ng_moeda_cotacao.retorna_cotacao_compra(b1.id_tenant, a1.id_moeda, l_id_moeda_pedido) * a1.valor), 0)), 0)',
'        into l_valor_antidumping',
'        from imp_entrega_despesa a1',
'        join imp_entrega b1 on b1.id = a1.id_entrega',
'        join ng_despesa c1 on c1.id = a1.id_despesa',
'        where b1.id = p_id',
'        and c1.ind_tipo_despesa = 8;',
'',
'        select nvl(sum(nvl((bo_ng_moeda_cotacao.retorna_cotacao_compra(b2.id_tenant, a2.id_moeda, l_id_moeda_pedido) * a2.valor), 0)), 0)',
'        into l_valor_multa',
'        from imp_entrega_despesa a2',
'        join imp_entrega b2 on b2.id = a2.id_entrega',
'        join ng_despesa c2 on c2.id = a2.id_despesa',
'        where b2.id = p_id',
'        and c2.ind_tipo_despesa = 17;',
'',
'        return(l_total_tributo + nvl(l_valor_antidumping, 0) + nvl(l_valor_multa, 0));',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_tributos;',
'    --',
'    function calcula_total_despesas(',
'        p_id in imp_entrega.id%type',
'    ) return number is',
'        l_id_moeda_pedido number;',
'        l_resultado number;',
'    begin',
'        select id_moeda into l_id_moeda_pedido from imp_pedidoimportacao a join imp_entrega b on b.id_pedidoimportacao = a.id where b.id = p_id;',
'',
'        select',
'            sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(b.id_tenant, a.id_moeda, l_id_moeda_pedido) * a.valor))',
'        into',
'            l_resultado',
'        from imp_entrega_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        where a.id_entrega = p_id',
'        and b.ind_tipo_despesa in (0,7,11,12,13,14,15);',
'',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_despesas;',
'    --',
'    function calcula_total_custos_importacao(',
'        p_id in imp_entrega.id%type',
'    ) return number is',
'        l_id_moeda_pedido number;',
'        l_total_tributos number;',
'        l_total_despesas number;',
'        l_resultado number;',
'    begin',
'        select id_moeda into l_id_moeda_pedido from imp_pedidoimportacao a join imp_entrega b on b.id_pedidoimportacao = a.id where b.id = p_id;',
'',
'        select',
'            sum(valor_ii) +',
'            sum(valor_ipi) +',
'            sum(valor_pis) +',
'            sum(valor_cofins) +',
'            sum(valor_icms)',
'        into',
'            l_total_tributos',
'        from imp_entrega_item_tributo a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_entrega c on c.id = b.id_entrega',
'        where c.id = p_id;',
'',
'        select nvl(sum(nvl((bo_ng_moeda_cotacao.retorna_cotacao_compra(b1.id_tenant, a1.id_moeda, l_id_moeda_pedido) * a1.valor), 0)), 0)',
'        into l_total_despesas',
'        from imp_entrega_despesa a1',
'        join imp_entrega b1 on b1.id = a1.id_entrega',
'        where b1.id = p_id;',
'',
'        l_resultado := nvl(l_total_tributos, 0) + nvl(l_total_despesas, 0);',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_custos_importacao;',
'    --',
'    function calcula_total_importacao(',
'        p_id in imp_entrega.id%type',
'    ) return number is',
'        l_total_custos_importacao number;',
'        l_total_vmle number;',
'        l_resultado number;',
'    begin',
'        l_total_custos_importacao := calcula_total_custos_importacao(p_id);',
'',
'        select sum(a.vmle) into l_total_vmle',
'        from imp_entrega_item_tributo a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_entrega c on c.id = b.id_entrega',
'        where c.id = p_id;',
'',
'        l_resultado := nvl(l_total_custos_importacao, 0) + nvl(l_total_vmle, 0);',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_importacao;',
'    --',
