'    --',
'    procedure altera_datas_informadas(',
'        p_data_disponivel_informada in imp_entrega.data_disponivel_informada%type,',
'        p_data_embarque_informada in imp_entrega.data_embarque_informada%type,',
'        p_data_desembarque_informada in imp_entrega.data_desembarque_informada%type,',
'        p_id in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega.altera_datas_informadas'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_entrega where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.data_disponivel_informada := p_data_disponivel_informada;',
'        v_new.data_embarque_informada := p_data_embarque_informada;',
'        v_new.data_desembarque_informada:= p_data_desembarque_informada;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        -- Tratamento para calcular data_embarque_calculada:',
'        if v_new.data_disponivel_real is null then',
'            if p_data_disponivel_informada is not null then',
'                v_new.data_embarque_calculada := (p_data_disponivel_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 2, v_new.id_endereco_origem, v_new.id_local_embarque));',
'            else',
'                if v_new.data_disponivel_calculada is not null then',
'                    v_new.data_embarque_calculada := (v_new.data_disponivel_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 2, v_new.id_endereco_origem, v_new.id_local_embarque));',
'                else',
'                    v_new.data_embarque_calculada := null;',
'                end if;',
'            end if;',
'        end if;',
'',
'        -- Tratamento para calcular data_desembarque_calculada:',
'        if v_new.data_embarque_real is null then',
'            if p_data_embarque_informada is not null then',
'                v_new.data_desembarque_calculada := (p_data_embarque_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque));',
'            else',
'                if v_new.data_embarque_calculada is not null then',
'                    v_new.data_desembarque_calculada := (v_new.data_embarque_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque));',
'                else',
'                    v_new.data_desembarque_calculada := null;',
'                end if;',
'            end if;',
'        end if;',
'',
'        -- Tratamento para calcular data_nacionalizacao_calculada:',
'        if v_new.data_desembarque_real is null then',
'            if p_data_desembarque_informada is not null then',
'                v_new.data_nacionalizacao_calculada := (p_data_desembarque_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque));',
'            else',
'                if v_new.data_desembarque_calculada is not null then',
'                    v_new.data_nacionalizacao_calculada := (v_new.data_desembarque_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque));',
'                else',
'                    v_new.data_nacionalizacao_calculada := null;',
'                end if;',
'            end if;',
'        end if;',
'',
'        -- Tratamento para calcular data_recebimento_calculada:',
'        if v_new.data_nacionalizacao_real is null then',
'            if v_new.data_nacionalizacao_informada is not null then',
'                v_new.data_recebimento_calculada := (v_new.data_nacionalizacao_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino));',
'            else',
'                if v_new.data_nacionalizacao_calculada is not null then',
'                    v_new.data_recebimento_calculada := (v_new.data_nacionalizacao_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino));',
'                else',
'                    v_new.data_recebimento_calculada := null;',
'                end if;',
'            end if;',
'        end if;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_datas_informadas;',
'    --',
'    procedure gerencia_entregas(',
'        p_quantidade_entrega in imp_pedidoimportacao.quantidade_entrega%type,',
'        p_id_pedidoimportacao in imp_entrega.id_pedidoimportacao%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_pedidoimportacao imp_pedidoimportacao%rowtype;',
'        l_verifica_quantidade_entrega number;',
'        l_saldo_nova_entrega number;',
'        l_id number := null;',
'    begin',
unistr('        -- Atribui a quantidade de entregas na vari\00E1vel global:'),
'        v_quantidade_entrega := p_quantidade_entrega;',
'',
unistr('        -- Atribui o nome da procedure como opera\00E7\00E3o:'),
'        v_operacao := ''gerencia_entregas'';',
'',
unistr('        -- Recupera o registro completo do pedido de importa\00E7\00E3o:'),
'        select * into l_pedidoimportacao from imp_pedidoimportacao where id = p_id_pedidoimportacao;',
'',
'        -- Verifica quantas entregas existem:',
'        select count(1) into l_verifica_quantidade_entrega from imp_entrega where id_pedidoimportacao = p_id_pedidoimportacao;',
'',
'        -- Se existe pelo menos uma entrega faz o gerenciamento:',
'        if l_verifica_quantidade_entrega > 0 then',
'            -- Verifica o "saldo" entre a nova quantidade de entregas e a quantidade existente:',
