'   function detalhe_registro (',
'       p_id in imp_entrega.id%type',
'    ) return varchar2 is',
'    begin',
'        return',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;">''||',
'        ''<h3 class="a-CardView-title">''||retorna_texto(''msg.60.l'')||''</h3></div>''||',
'        ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;">''||',
'        ''<h3 class="a-CardView-title">''||replace(retorna_texto(''msg.60.h''),''$param1'')||''</h3></div>''||',
'        pkg_ui.campos_detalhes(''',
'            select',
'                b.nome_fantasia                 as imp_entrega$id_tenant,',
'                c.numero_pedido_importacao      as imp_pedidoimportacao$numero_pedido_importacao,',
'                a.num_entrega                   as imp_entrega$num_entrega,',
'                pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', a.ind_status_entrega) AS imp_entrega$ind_status_entrega,',
'                e.razao_social                  as imp_entrega$id_exportador,',
'                g.razao_social                  as imp_entrega$id_importador,',
'                h.razao_social                  as imp_entrega$id_adquirente',
'            from imp_entrega a',
'            left join mpd_tenant b on b.id = a.id_tenant',
'            left join imp_pedidoimportacao c ON c.id = a.id_pedidoimportacao',
'            left join ng_pessoa_juridica e ON e.id_pessoa = a.id_exportador',
'            left join ng_pessoa_juridica g ON g.id_pessoa = a.id_importador',
'            left join ng_pessoa_juridica h ON h.id_pessoa = a.id_adquirente',
'            where a.id = ''||p_id',
'        );',
'    end detalhe_registro;',
