'        -- Tratamento para calcular data_desembarque_calculada:',
'        if v_new.data_embarque_real is not null then',
'            v_new.data_desembarque_calculada := (v_new.data_embarque_real + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque));',
'        elsif v_new.data_embarque_informada is not null then',
'            v_new.data_desembarque_calculada := (v_new.data_embarque_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque));',
'        elsif v_new.data_embarque_calculada is not null then',
'            v_new.data_desembarque_calculada := (v_new.data_embarque_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque));',
'        else',
'            v_new.data_desembarque_calculada := null;',
'        end if;',
'',
'        -- Tratamento para calcular data_nacionalizacao_calculada:',
'        if v_new.data_desembarque_real is not null then',
'            v_new.data_nacionalizacao_calculada := (v_new.data_desembarque_real + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque));',
'        elsif v_new.data_desembarque_informada is not null then',
'            v_new.data_nacionalizacao_calculada := (v_new.data_desembarque_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque));',
'        elsif v_new.data_desembarque_calculada is not null then',
'            v_new.data_nacionalizacao_calculada := (v_new.data_desembarque_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque));',
'        else',
'            v_new.data_nacionalizacao_calculada := null;',
'        end if;',
'',
'        -- Tratamento para calcular data_recebimento_calculada:',
'        if v_new.data_nacionalizacao_real is not null then',
'            v_new.data_recebimento_calculada := (v_new.data_nacionalizacao_real + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino));',
'        elsif v_new.data_nacionalizacao_informada is not null then',
'            v_new.data_recebimento_calculada := (v_new.data_nacionalizacao_informada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino));',
'        elsif v_new.data_nacionalizacao_calculada is not null then',
'            v_new.data_recebimento_calculada := (v_new.data_nacionalizacao_calculada + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino));',
'        else',
'            v_new.data_recebimento_calculada := null;',
'        end if;',
'    end configura_datas_calculadas;',
'    --',
'    procedure vincula_entregas_ao_processo(',
'        p_ids_entregas_selecionadas in varchar2,',
'        p_id_processoimportacao     in imp_processoimportacao.id%type,',
'        p_pagina                   in number default 0,',
'        p_encadeado                in boolean default false,',
'        p_sucesso                  out clob,',
'        p_messages                 out pkg_mensagem.message_record_table',
'    ) is',
'        l_ids      apex_t_varchar2 := null;',
'        l_first_id imp_entrega.id%type;',
'        l_id       imp_entrega.id%type;',
'        l_count    number;',
'        l_sucesso_local clob;',
'        l_messages_local pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega.vincula_entregas_ao_processo'';',
'        v_pagina := p_pagina;',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        -- Se nenhuma entrega selecionada, exibe msg',
'        if p_ids_entregas_selecionadas is null or trim(p_ids_entregas_selecionadas) = '''' then',
'            apex_error.add_error(',
'                    p_message => retorna_texto(''msg.74.l''),',
'                    p_display_location => apex_error.c_inline_in_notification',
'                );',
'            return;',
'        end if;',
'',
'        -- transforma em array',
'        l_ids := apex_string.split(p_ids_entregas_selecionadas, '','');',
'',
'        -- pega primeiro id para atualizar datas do processo',
'        if l_ids.count >= 1 then',
'            l_first_id := to_number(l_ids(1));',
'        end if;',
'',
'        l_messages_local := pkg_mensagem.message_record_table();',
'        -- Atualiza datas do processo com base na primeira entrega',
'        bo_imp_processoimportacao.atualizar_datas_processo_com_base_entrega(',
'            p_id        => p_id_processoimportacao,',
'            p_id_entrega=> l_first_id,',
'            p_pagina    => p_pagina,',
'            p_encadeado => true,',
'            p_sucesso   => l_sucesso_local,',
'            p_messages  => l_messages_local',
'        );',
'',
'        if l_messages_local.count > 0 then',
'            for i in 1..l_messages_local.count loop',
'                --apex_debug.message(''MSG atualizar_datas: '' || l_messages_local(i).mensagem);',
'                p_messages.extend;',
'                p_messages(p_messages.last) := l_messages_local(i);',
'            end loop;',
'        end if;',
'',
'        -- Retira entregas que foram desmarcadas',
'        for r in (',
'            select e.id from imp_entrega e where e.id_processoimportacao = p_id_processoimportacao and e.id not in (select to_number(column_value) from table(apex_string.split(p_ids_entregas_selecionadas, '','')))',
'        ) loop',
'            for it in (',
'                select ipi.id from imp_processoimportacao_item ipi where ipi.id_processoimportacao = p_id_processoimportacao and ipi.id_entrega = r.id',
'            ) loop',
'                l_messages_local := pkg_mensagem.message_record_table();',
'',
'                bo_imp_processoimportacao_item.exclui_registro(',
'                    p_id        => it.id,',
'                    p_encadeado => true,',
'                    p_sucesso   => l_sucesso_local,',
'                    p_messages  => l_messages_local',
'                );',
'',
'                if l_messages_local.count > 0 then',
'                    for j in 1 .. l_messages_local.count loop',
'                        p_messages.extend;',
'                        p_messages(p_messages.last) := l_messages_local(j);',
'                    end loop;',
'                end if;',
'',
'            end loop;',
'',
'            -- Desvincula entrega do processo',
'            l_messages_local := pkg_mensagem.message_record_table();',
'',
'            bo_imp_entrega.altera_registro_id_processoimportacao(',
'                p_id_processoimportacao => null,',
'                p_id                    => r.id,',
'                p_pagina                => p_pagina,',
'                p_encadeado             => true,',
'                p_sucesso               => l_sucesso_local,',
'                p_messages              => l_messages_local',
'            );',
'',
'            if l_messages_local.count > 0 then',
'                for i in 1..l_messages_local.count loop',
'                    --apex_debug.error(''MSG remove entrega: '' || l_messages_local(i).mensagem);',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(i);',
'                end loop;',
'            end if;',
'        end loop;',
'',
'        -- Loop por cada entrega selecionada: vincula e inclui itens no processo',
'        for i in 1..l_ids.count loop',
'            l_id := to_number(l_ids(i));',
'',
unistr('            -- Vincula entrega ao processo (se ainda n\00E3o vinculada)'),
'            select count(*) into l_count from imp_entrega where id = l_id and id_processoimportacao = p_id_processoimportacao;',
'',
'            if l_count = 0 then',
'                l_messages_local := pkg_mensagem.message_record_table();',
'',
'                bo_imp_entrega.define_processo_importacao(',
'                    p_id_entrega            => l_id,',
'                    p_id_processoimportacao => p_id_processoimportacao,',
'                    p_pagina                => p_pagina,',
'                    p_encadeado             => true,',
'                    p_sucesso               => l_sucesso_local,',
'                    p_messages              => l_messages_local',
'                );',
'',
'                if l_messages_local.count > 0 then',
'                    for j in 1 .. l_messages_local.count loop',
'                        p_messages.extend;',
'                        p_messages(p_messages.last) := l_messages_local(j);',
'                    end loop;',
'                end if;',
'',
'            end if;',
'',
'            -- inclui itens da entrega no processo',
'            for rec in (',
'                select',
'                    e.id_tenant,',
'                    ei.id_entrega,',
'                    ei.id as id_entrega_item,',
'                    ei.id_pedidoimportacao_item,',
'                    pii.id_item as id_item,',
'                    ei.id_ncm,',
'                    nvl(pii.id_unidademedida, ei.id_unidademedida) as id_unidademedida,',
'                    nvl(ei.quantidade, 0) as quantidade,',
'                    nvl(ei.peso_unitario, pii.peso_unitario) as peso_unitario,',
'                    nvl(ei.peso_liquido_total, 0) as peso_liquido_total,',
'                    nvl(ei.peso_bruto_unitario, 0) as peso_bruto_unitario,',
'                    nvl(ei.peso_bruto_total, 0) as peso_bruto_total,',
'                    ei.id_pais_origem,',
'                    pi.id_moeda,',
'                    e.id_incoterm,',
'                    nvl(ei.valor_unitario, pii.valor_unitario) as valor_unitario,',
'                    nvl(ei.valor_desconto_unitario, pii.valor_desconto_unitario) as valor_desconto,',
'                    nvl(ei.valor_total_condicao_venda, pii.valor_total) as valor_total,',
'                    ei.valor_total_desconto_invoice_item,',
'                    ei.valor_total_despesa_invoice_item,',
'                    pii.id_naturezaoperacao,',
'                    e.id_exportador,',
'                    pii.id_fabricante,',
'                    ei.ind_licenca_importacao,',
'                    pii.ind_bloqueio_embarque_ate_deferimento_li,',
'                    pii.id_centrocusto,',
'                    pii.num_solicitacao_compra,',
'                    pii.nome_solicitante,',
'                    pii.data_entrega_desejada,',
'                    pii.ind_finalidade,',
'                    pii.numero_ato_concessorio',
'                  from imp_entrega_item ei',
'                  join imp_entrega e on e.id = ei.id_entrega',
'                  join imp_pedidoimportacao_item pii on pii.id = ei.id_pedidoimportacao_item',
'                  join imp_pedidoimportacao pi on pi.id = pii.id_pedidoimportacao',
'                 where ei.id_entrega = l_id',
'            ) loop',
'                declare',
'                    l_novo_item_id imp_processoimportacao_item.id%type;',
'                    l_cst        imp_processoimportacao_item.cst%type;',
'                    l_id_cfop    imp_processoimportacao_item.id_cfop%type;',
'                    l_cclasstrib imp_processoimportacao_item.cclasstrib%type;',
'                begin',
'                    select count(*) into l_count from imp_processoimportacao_item where id_processoimportacao = p_id_processoimportacao and id_entrega_item = rec.id_entrega_item;',
'',
'                    if l_count = 0 then',
'                        l_messages_local := pkg_mensagem.message_record_table();',
unistr('                    -- Busca informa\00E7\00F5es da natureza da opera\00E7\00E3o:'),
'                    select cst, id_cfop, cclasstrib',
'                    into l_cst, l_id_cfop, l_cclasstrib',
'                    from imp_naturezaoperacao_parametro',
'                    where id_naturezaoperacao = rec.id_naturezaoperacao;',
'                    --',
'                        bo_imp_processoimportacao_item.inclui_registro(',
'                            p_id_tenant                                     => rec.id_tenant,',
'                            p_id_processoimportacao                         => p_id_processoimportacao,',
'                            p_id_entrega                                    => rec.id_entrega,',
'                            p_id_entrega_item                               => rec.id_entrega_item,',
'                            p_id_item                                       => rec.id_item,',
'                            p_id_ncm                                        => rec.id_ncm,',
'                            p_id_unidademedida                              => rec.id_unidademedida,',
'                            p_quantidade                                    => rec.quantidade,',
'                            p_peso_unitario                                 => rec.peso_unitario,',
'                            p_peso_liquido_total                            => rec.peso_liquido_total,',
'                            p_peso_bruto_unitario                           => rec.peso_bruto_unitario,',
'                            p_peso_bruto_total                              => rec.peso_bruto_total,',
'                            p_id_pais_origem                                => rec.id_pais_origem,',
'                            p_id_moeda                                      => rec.id_moeda,',
'                            p_id_incoterm                                   => rec.id_incoterm,',
'                            p_valor_unitario                                => rec.valor_unitario,',
'                            p_valor_desconto                                => rec.valor_desconto,',
'                            p_valor_total_condicao_venda                    => rec.valor_total,',
'				            p_valor_total_desconto_invoice_item             => rec.valor_total_desconto_invoice_item,',
'							p_valor_total_despesa_invoice_item              => rec.valor_total_despesa_invoice_item,',
'                            p_id_naturezaoperacao                           => rec.id_naturezaoperacao,',
'                            p_id_exportador                                 => rec.id_exportador,',
'                            p_id_fabricante                                 => rec.id_fabricante,',
'                            p_ind_licenca_importacao                        => rec.ind_licenca_importacao,',
'                            p_ind_bloqueio_embarque_ate_deferimento_li      => rec.ind_bloqueio_embarque_ate_deferimento_li,',
'                            p_id_centrocusto                                => rec.id_centrocusto,',
'                            p_num_solicitacao_compra                        => rec.num_solicitacao_compra,',
'                            p_nome_solicitante                              => rec.nome_solicitante,',
'                            p_data_entrega_desejada                         => rec.data_entrega_desejada,',
'							p_id_minutanotafiscal						    => null,',
'							p_valor_total_mercadoria				        => 0,',
'                            p_quantidade_faturada                           => 0,',
'                            p_quantidade_saldo                              => rec.quantidade,',
'                            p_ind_finalidade                                => rec.ind_finalidade,',
'                            p_numero_ato_concessorio                        => rec.numero_ato_concessorio,',
'                            p_valor_total_mercadoria_moeda_nacional         => 0,',
'                            p_valor_unitario_mercadoria_moeda_nacional      => 0,',
'                            p_cst                                           => l_cst,',
'                            p_id_cfop                                       => l_id_cfop,',
'                            p_cclasstrib                                    => l_cclasstrib,',
'                            p_id                                            => l_novo_item_id,',
'                            p_pagina                                        => p_pagina,',
'                            p_encadeado                                     => true,',
'                            p_sucesso                                       => l_sucesso_local,',
'                            p_messages                                      => l_messages_local',
'                        );',
'',
'                        if l_messages_local.count > 0 then',
'                            for i in 1..l_messages_local.count loop',
'                                p_messages.extend;',
'                                p_messages(p_messages.last) := l_messages_local(i);',
'                            end loop;',
'                        end if;',
'                    end if;',
'                end;',
'            end loop;',
'',
'            if l_messages_local.count > 0 then',
'                for i in 1..l_messages_local.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(i);',
'                end loop;',
'            end if;',
'        end loop;',
'',
unistr('        -- Remove v\00EDnculo de invoices que n\00E3o possuem mais entregas neste processo'),
'        for r_invoice in (',
'            select i.id from imp_invoice i where i.id_processoimportacao = p_id_processoimportacao and not exists (select 1 from imp_entrega e where e.id_invoice = i.id and e.id_processoimportacao = p_id_processoimportacao)',
'        )',
'        loop',
'            l_messages_local := pkg_mensagem.message_record_table();',
'',
'            bo_imp_invoice.altera_id_processoimportacao(',
'                p_id_processoimportacao => null,',
'                p_id                    => r_invoice.id,',
'                p_pagina                => p_pagina,',
'                p_encadeado             => true,',
'                p_sucesso               => l_sucesso_local,',
'                p_messages              => l_messages_local',
'            );',
'',
'            if l_messages_local.count > 0 then',
'                for j in 1 .. l_messages_local.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(j);',
'                end loop;',
'            end if;',
'        end loop;',
'',
'        -- vincula invoice e processo de importacao',
'        for r_invoice in (',
'            select distinct ie.id_invoice from imp_entrega ie where ie.id_processoimportacao = p_id_processoimportacao and ie.id_invoice is not null',
'        )',
'        loop',
'            l_messages_local := pkg_mensagem.message_record_table();',
'',
'            bo_imp_invoice.altera_id_processoimportacao(',
'                p_id_processoimportacao => p_id_processoimportacao,',
'                p_id                    => r_invoice.id_invoice,',
'                p_pagina                => p_pagina,',
'                p_encadeado             => true,',
'                p_sucesso               => l_sucesso_local,',
'                p_messages              => l_messages_local',
'            );',
'',
'            if l_messages_local.count > 0 then',
'                for j in 1 .. l_messages_local.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(j);',
'                end loop;',
'            end if;',
'        end loop;',
'',
'        if apex_util.get_session_state(''P9014_CODIGO_ARTEFATO'') = ''TD868'' then',
'            l_messages_local := pkg_mensagem.message_record_table();',
'',
'            bo_imp_processoimportacao.concluir_processo_e_gerar_despesas(',
'                p_id         => p_id_processoimportacao,',
'                p_pagina     => p_pagina,',
'                p_encadeado  => true,',
'                p_sucesso    => l_sucesso_local,',
'                p_messages   => l_messages_local',
'            );',
'',
'            if l_messages_local.count > 0 then',
'                for i in 1 .. l_messages_local.count loop',
'                    p_messages.extend;',
'                    p_messages(p_messages.last) := l_messages_local(i);',
'                end loop;',
'            end if;',
'        end if;',
'    end vincula_entregas_ao_processo;',
'',
'    procedure define_processo_importacao(',
'        p_id_entrega            in imp_entrega.id%type,',
'        p_id_processoimportacao in imp_entrega.id_processoimportacao%type,',
'        p_pagina                in number default 0,',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_entrega.define_processo_importacao'';',
'        v_pagina := p_pagina;',
'',
'        -- carrega registro',
'        select * into v_old from imp_entrega where id = p_id_entrega;',
'',
'        v_new := v_old;',
'',
'        v_new.id_processoimportacao := p_id_processoimportacao;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        grava(p_id => p_id_entrega, p_encadeado  => p_encadeado, p_sucesso => p_sucesso, p_messages => p_messages);',
'    end define_processo_importacao;',
'    --',
'    procedure altera_divergencias(',
'        p_id_exportador in imp_entrega.id_exportador%type default null,',
'        p_id_importador in imp_entrega.id_importador%type default null,',
'        p_id_adquirente in imp_entrega.id_adquirente%type default 0,',
'        p_id_incoterm in imp_entrega.id_incoterm%type default null,',
'        p_id in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega.altera_divergencias'';',
'',
'        select * into v_old from imp_entrega where id = p_id;',
'        v_new := v_old;',
'',
'        if p_id_exportador is not null then',
'            v_new.id_exportador := p_id_exportador;',
'        end if;',
'        if p_id_importador is not null then',
'            v_new.id_importador := p_id_importador;',
'        end if;',
'        if p_id_adquirente <> 0 then',
'            if p_id_adquirente = -1 then',
'                v_new.id_adquirente := null;',
'            else',
'                v_new.id_adquirente := p_id_adquirente;',
'            end if;',
'        end if;',
'        if p_id_incoterm is not null then',
'            v_new.id_incoterm := p_id_incoterm;',
'        end if;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_DIVERGENCIAS'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_divergencias;',
'    --',
'',
'	procedure hook_valida_vinculo_invoice',
'	is',
'	    v_status number;',
'	begin',
unistr('        -- Alterado regra :Quando "imp_entrega.id" = "imp_invoice_item.id_entrega", e imp_invoice.ind_status = 3.Em outras palavras, verificar se h\00E1 item da invoice vinculado a essa entrega. Se sim, verificar o status da invoice, se aprovado (3).'),
'	    -- Por :Quando "id_invoice" diferente de null',
'        -- select min(c.ind_status)',
'	    --       into v_status',
'	    --       from imp_invoice_item a',
'	    --       join imp_entrega b on b.id = a.id_entrega',
'	    --       join imp_invoice c on c.id = a.id_invoice',
'	    --where b.id = v_old.id;',
'	    --if v_status = 3 then',
'        --         pkg_mensagem.mensagem_campo(',
'        --             p_codigo_mensagem => 131,',
'        --             p_nome_campo => ''data_nacionalizacao_informada'',',
'        --             p_parametro => v_parametro,',
'        --             p_pagina => v_pagina,',
'        --             p_objeto_mensagem => v_message',
'        --         );',
'        -- end if;',
'        select 1 into v_status from imp_entrega where id = v_new.id AND  id_invoice is not null;',
'        if v_status = 1 then',
'                     pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => 131,',
'                    p_nome_campo => ''data_nacionalizacao_informada'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );',
'        end if;',
'				v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;',
'	end hook_valida_vinculo_invoice;',
'',
'',
