'           );',
'    end;',
'',
'    procedure atualiza_processo_apos_vincular_entrega(',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_processoimportacao.altera_datas_processoimporatacao(',
'            p_id_entrega => v_new.id,',
'            p_id         => v_new.id_processoimportacao,',
'            p_sucesso    => p_sucesso,',
'            p_messages   => p_messages',
'        );',
'        if v_new.id_processoimportacao is not null and v_new.id_invoice is not null then',
'            altera_idprocesso_invoice(v_new.id_processoimportacao, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end atualiza_processo_apos_vincular_entrega;',
'    --',
'    procedure altera_pedidoimportacao_pagamento_data_vencimento_prevista(',
'        p_id in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_data_vencimento_prevista date;',
'    begin',
'        for parcela_entrega in (',
'            select',
'                a.id,',
'                trunc(((e.percentual / 100) * b.valor_total_financeiro/*valor_total_condicao_venda*/),2) valor,',
'                e.ind_evento_gerador_pagamento,',
'                e.qtd_dias_evento,',
'                b.id_invoice,',
'                coalesce(data_disponivel_real, data_disponivel_informada, data_disponivel_calculada) data_disponivel,',
'                coalesce(data_embarque_real, data_embarque_informada, data_embarque_calculada) data_embarque,',
'                coalesce(data_desembarque_real, data_desembarque_informada, data_desembarque_calculada) data_desembarque,',
'                a.ind_status_pagamento,',
'                a.data_vencimento_prevista',
'            from imp_pedidoimportacao_pagamento a',
'            join imp_entrega b on b.id = a.id_entrega',
'            join imp_pedidoimportacao c on c.id = b.id_pedidoimportacao',
'            join ng_condicaopagamento d on d.id = c.id_condicaopagamento',
'            join ng_condicaopagamento_parcela e on e.id_condicaopagamento = d.id and e.numero_parcela = a.numero_parcela',
'            where a.id_entrega = p_id',
'            --and a.ind_status_pagamento = 1',
'            and ind_evento_gerador_pagamento <> 1',
'        ) loop',
'            if parcela_entrega.ind_status_pagamento = 1 then',
'                if parcela_entrega.ind_evento_gerador_pagamento = 2 and parcela_entrega.id_invoice is not null then',
'                    select data_invoice into l_data_vencimento_prevista from imp_invoice where id = parcela_entrega.id_invoice;',
'                    if l_data_vencimento_prevista is not null then',
'                        l_data_vencimento_prevista := l_data_vencimento_prevista + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                    end if;',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 5 and parcela_entrega.data_disponivel is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_disponivel + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 6 and parcela_entrega.data_embarque is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_embarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 7 and parcela_entrega.data_desembarque is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_desembarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                else',
'                    l'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767669647598447)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'_data_vencimento_prevista := null;',
'                end if;',
'            else',
'                l_data_vencimento_prevista := parcela_entrega.data_vencimento_prevista;',
'            end if;',
'',
'            bo_imp_pedidoimportacao_pagamento.altera_valor_e_data_vencimento_prevista(',
'                p_valor => parcela_entrega.valor,',
'                p_data_vencimento_prevista => l_data_vencimento_prevista,',
'                p_id => parcela_entrega.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_pedidoimportacao_pagamento_data_vencimento_prevista;',
'    --',
'    procedure gera_parcelas_entrega(',
'        p_id in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_pedidoimportacao number;',
'        l_ind_status_pedido_importacao number;',
'        l_data_vencimento_prevista date;',
'        l_id_pedidoimportacao_pagamento number;',
'    begin',
'        select a.id, a.ind_status_pedido_importacao',
'        into l_id_pedidoimportacao, l_ind_status_pedido_importacao',
'        from imp_pedidoimportacao a',
'        join imp_entrega b on b.id_pedidoimportacao = a.id',
'        where b.id = p_id;',
'',
'        if l_ind_status_pedido_importacao in (2,3) then',
'            for parcela_entrega in (',
'                select',
'                    distinct d.id,',
'                    a.id_tenant,',
'                    b.id id_entrega,',
'                    d.numero_parcela,',
'                    d.percentual,',
'                    nvl(((d.percentual / 100) * b.valor_total_condicao_venda),0) valor,',
'                    ind_evento_gerador_pagamento,',
'                    qtd_dias_evento,',
'                    b.id_invoice,',
'                    coalesce(data_disponivel_real, data_disponivel_informada, data_disponivel_calculada) data_disponivel,',
'                    coalesce(data_embarque_real, data_embarque_informada, data_embarque_calculada) data_embarque,',
'                    coalesce(data_desembarque_real, data_desembarque_informada, data_desembarque_calculada) data_desembarque',
'                from imp_pedidoimportacao a',
'                join imp_entrega b on b.id_pedidoimportacao = a.id',
'                join ng_condicaopagamento c on c.id = a.id_condicaopagamento',
'                join ng_condicaopagamento_parcela d on d.id_condicaopagamento = c.id',
'                where b.id = p_id',
'                and d.ind_evento_gerador_pagamento <> 1',
'            ) loop',
'                -- Executa as regras para atribuir corretamente a data de vencimento prevista',
'                if parcela_entrega.ind_evento_gerador_pagamento = 2 and parcela_entrega.id_invoice is not null then',
'                    select data_invoice into l_data_vencimento_prevista from imp_invoice where id = parcela_entrega.id_invoice;',
'                    if l_data_vencimento_prevista is not null then',
'                        l_data_vencimento_prevista := l_data_vencimento_prevista + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                    end if;',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 5 and parcela_entrega.data_disponivel is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_disponivel + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 6 and parcela_entrega.data_embarque is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_embarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                elsif parcela_entrega.ind_evento_gerador_pagamento = 7 and parcela_entrega.data_desembarque is not null then',
'                    l_data_vencimento_prevista := parcela_entrega.data_desembarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                else',
'                    l_data_vencimento_prevista := null;',
'                end if;',
'',
'                bo_imp_pedidoimportacao_pagamento.inclui_registro(',
'                    p_id_tenant => parcela_entrega.id_tenant,',
'                    p_id_pedidoimportacao => l_id_pedidoimportacao,',
'                    p_id_entrega => parcela_entrega.id_entrega,',
'                    p_numero_parcela => parcela_entrega.numero_parcela,',
'                    p_percentual => parcela_entrega.percentual,',
'                    p_valor => parcela_entrega.valor,',
'                    p_data_vencimento_prevista => l_data_vencimento_prevista,',
'                    p_data_vencimento_real => null,',
'                    p_ind_status_pagamento => 1,',
'                    p_ind_multa_atraso_pagamento => ''N'',',
'                    p_valor_multa => null,',
'                    p_percentual_multa => null,',
'                    p_periodo_multa => null,',
'                    p_ind_bloqueado => ''N'',',
'                    p_condicao_desbloqueio => null,',
'                    p_data_desbloqueio => null,',
'                    p_id_usuario_desbloqueio => null,',
'                    p_instrucao_contas_pagar => null,',
'                    p_id => l_id_pedidoimportacao_pagamento,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'    end gera_parcelas_entrega;',
'    --',
'    procedure altera_id_invoice(',
'        p_id_invoice in imp_entrega.id_invoice%type,',
'        p_id in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega.altera_id_invoice'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_entrega where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.id_invoice := p_id_invoice;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        --v_new.data_alteracao := sysdate;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_ID_INVOICE'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_id_invoice;',
'    --',
'',
'    procedure desvincular_processo(',
'        p_id        in imp_entrega.id%type,',
'        p_pagina    in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_entrega.desvincular_processo'';',
'        v_pagina := p_pagina;',
'',
'        -- Busca do registro original',
'        select * into v_old from imp_entrega where id = p_id;',
'        v_new := v_old;',
'',
unistr('        -- Atribui\00E7\00E3o de valores'),
'        v_new.id_processoimportacao  := null;',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao     := sysdate;',
'',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end desvincular_processo;',
'',
'    procedure atualiza_valor_total_financeiro(',
'        p_id_entrega in imp_entrega.id%type',
'    ) is',
'        l_valor_total_financeiro number;',
'        l_sucesso                clob;',
'        l_messages               pkg_mensagem.message_record_table;',
'    begin',
'        l_messages := pkg_mensagem.message_record_table();',
'',
'        -- Calcula a soma apenas dos itens com ind_gera_financeiro = S',
'        select sum(a.valor_total_condicao_venda)',
'          into l_valor_total_financeiro',
'          from imp_entrega_item a',
'          join imp_naturezaoperacao_parametro c on a.id_naturezaoperacao = c.id_naturezaoperacao',
'         where a.id_entrega = p_id_entrega',
'           and c.ind_gera_financeiro = ''S'';',
'',
'        -- Carrega todos os dados da entrega em v_new',
'        select * into v_new from imp_entrega where id = p_id_entrega;',
'',
'        -- Atualiza apenas o campo desejado',
'        v_new.valor_total_financeiro := nvl(l_valor_total_financeiro, 0);',
'',
unistr('        -- Grava usando o padr\00E3o do BO'),
'        grava(p_id_entrega, true, l_sucesso, l_messages);',
'    end atualiza_valor_total_financeiro;',
'    --',
'    procedure altera_entrega_item_tributos(',
'        p_id in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        for entrega_item in (',
'            select id from imp_entrega_item where id_entrega = p_id',
'        ) loop',
'            bo_imp_entrega_item_tributo.altera_tributos(',
'                p_id_entrega_item => entrega_item.id,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_entrega_item_tributos;',
'    --',
'    function proxima_entrega_elegivel(',
'        p_id in imp_entrega.id%type',
'    ) return number is',
'        l_id_pedidoimportacao number;',
'        l_id_entrega number;',
'    begin',
'        select id_pedidoimportacao into l_id_pedidoimportacao from imp_entrega where id = p_id;',
'',
'        select a.id into l_id_entrega',
'        from imp_entrega a',
'        left join imp_processoimportacao b on b.id = a.id_processoimportacao',
'        where a.id != p_id',
'        and a.id_pedidoimportacao = l_id_pedidoimportacao',
'        and a.id_invoice is null',
'        and (b.ind_status in (1,2)',
'            or b.ind_status is null)',
'        order by a.num_entrega',
'        fetch first 1 row only;',
'',
'        return l_id_entrega;',
'    exception',
'        when no_data_found then',
'            return 0;',
'    end proxima_entrega_elegivel;',
'    --',
'    procedure gera_titulos_confirmacao_disponibilidade(',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade     number;',
'        l_id_titulo       number;',
'        l_mensagem        clob;',
'        l_paramentros     pkg_mensagem.paramentros;',
'        l_data_vencimento fin_titulopagamento.data_vencimento%type;',
'        l_valor_titulo    fin_titulopagamento.valor_titulo%type;',
'    begin',
'        select id into l_id_entidade',
'          from srv_entidade',
'         where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
'        for pag in (',
'            select pag.id,',
'                   pag.numero_parcela,',
'                   pag.data_vencimento_prevista,',
'                   pag.valor,',
'                   ped.id_exportador,',
'                   ped.id_moeda,',
'                   ped.numero_pedido_importacao',
'              from imp_pedidoimportacao_pagamento pag',
'              join imp_pedidoimportacao ped   on ped.id   = pag.id_pedidoimportacao',
'              join ng_condicaopagamento cond  on cond.id  = ped.id_condicaopagamento',
'              join ng_condicaopagamento_parcela parc',
'                   on parc.id_condicaopagamento      = cond.id',
'                  and parc.numero_parcela            = pag.numero_parcela',
'             where pag.id_entrega                   = v_new.id',
'               and pag.ind_status_pagamento         = 1',
'               and parc.ind_evento_gerador_pagamento = 5',
'               and not exists (',
'                   select 1',
'                     from fin_titulopagamento t',
'                    where t.id_referencia          = pag.id',
'                      and t.id_entidade            = l_id_entidade',
'                      and t.ind_status_pagamento not in (3, 4)',
'               )',
'        ) loop',
'            bo_fin_titulopagamento.inclui_registro(',
'                p_id_tenant                   => v_new.id_tenant,',
'                p_id_entidade                 => l_id_entidade,',
'                p_id_referencia               => pag.id,',
'                p_ind_status_pagamento        => 1,',
'                p_id_fornecedor               => pag.id_exportador,',
'                p_id_fornecedor_contabancaria => null,',
'                p_data_vencimento             => pag.data_vencimento_prevista,',
'                p_data_pagamento              => null,',
'                p_data_compensacao            => null,',
'                p_id_moeda                    => pag.id_moeda,',
'                p_valor_titulo                => pag.valor,',
'                p_valor_pago                  => 0,',
'                p_saldo_pagar                 => pag.valor,',
'                p_taxa_cambio                 => 0,',
'                p_valor_moeda_nacional        => 0,',
'                p_observacao                  => null,',
'                p_ind_multa_atraso_pagamento  => ''N'',',
'                p_valor_multa                 => 0,',
'                p_percentual_multa            => 0,',
'                p_periodo_multa               => null,',
'                p_valor_compensado            => 0,',
'                p_saldo_compensar             => pag.valor,',
'                p_id                          => l_id_titulo,',
'                p_pagina                      => v_pagina,',
'                p_encadeado                   => true,',
'                p_sucesso                     => p_sucesso,',
'                p_messages                    => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'',
'            select data_vencimento, valor_titulo',
'              into l_data_vencimento, l_valor_titulo',
'              from fin_titulopagamento',
'             where id = l_id_titulo;',
'            l_paramentros(2) := to_char(l_data_vencimento, ''DD/MM/YYYY'');',
'            l_paramentros(3) := ''R$ '' || to_char(l_valor_titulo, ''FM999G999G990D00'', ''NLS_NUMERIC_CHARACTERS=,.'');',
'            pkg_mensagem.mensagem_original(555, l_paramentros, l_mensagem);',
'            p_sucesso := PKG_MENSAGEM.tag_mensagem(l_mensagem);',
'            -- grava_log2(''BO_IMP_PROCESSOIMPORTACAO p_sucesso:''||p_sucesso);',
'',
'        end loop;',
'    end gera_titulos_confirmacao_disponibilidade;',
'    --',
'    procedure cancela_titulos_desconfirmacao_disponibilidade(',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade number;',
'    begin',
'        select id into l_id_entidade',
'          from srv_entidade',
'         where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
'        for tit in (',
'            select t.id,',
'                   t.ind_status_pagamento',
'              from fin_titulopagamento t',
'              join imp_pedidoimportacao_pagamento pag on pag.id = t.id_referencia',
'              join imp_pedidoimportacao ped   on ped.id   = pag.id_pedidoimportacao',
'              join ng_condicaopagamento cond  on cond.id  = ped.id_condicaopagamento',
'              join ng_condicaopagamento_parcela parc',
'                   on parc.id_condicaopagamento    = cond.id',
'                  and parc.numero_parcela          = pag.numero_parcela',
'             where pag.id_entrega                 = v_new.id',
'               and pag.ind_status_pagamento       = 2',
'               and parc.ind_evento_gerador_pagamento = 5',
'               and t.id_entidade                  = l_id_entidade',
'               and t.ind_status_pagamento         in (1, 2)',
'        ) loop',
'            bo_fin_titulopagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => case tit.ind_status_pagamento when 1 then 3 else 4 end,',
'                p_id                   => tit.id,',
'                p_pagina               => v_pagina,',
'                p_encadeado            => true,',
'                p_sucesso              => p_sucesso,',
'                p_messages             => p_messages',
'            );',
'        end loop;',
'    end cancela_titulos_desconfirmacao_disponibilidade;',
'    --',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_entrega;',
'/'))
);
end;
/
