'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into imp_entrega_item (  ',
'            id_pais_origem,',
'            valor_total_desconto_invoice_item,',
'            id_fabricante,',
'            id_tenant,',
'            id_entrega,',
'            id_pedidoimportacao_item,',
'            id_item,',
'            id_ncm,',
'            id_unidademedida,',
'            quantidade,',
'            peso_unitario,',
'            peso_liquido_total,',
'            valor_unitario,',
'            valor_desconto_unitario,',
'            valor_total_condicao_venda,',
'            id_naturezaoperacao,',
'            ind_licenca_importacao,',
'            quantidade_faturada,',
'            quantidade_saldo,',
'            peso_bruto_unitario,',
'            peso_bruto_total,',
'            ind_bloqueio_embarque_ate_deferimento_li,',
'            valor_despesaproforma,',
'            valor_despesaproforma_unitario,',
'            valor_desconto_pedido_item_unitario,',
'            ind_tratamento_saldo,',
'            valor_total_despesa_invoice_item, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_pais_origem,',
'            v_new.valor_total_desconto_invoice_item,',
'            v_new.id_fabricante,',
'            v_new.id_tenant,',
'            v_new.id_entrega,',
'            v_new.id_pedidoimportacao_item,',
'            v_new.id_item,',
'            v_new.id_ncm,',
'            v_new.id_unidademedida,',
'            v_new.quantidade,',
'            v_new.peso_unitario,',
'            v_new.peso_liquido_total,',
'            v_new.valor_unitario,',
'            v_new.valor_desconto_unitario,',
'            v_new.valor_total_condicao_venda,',
'            v_new.id_naturezaoperacao,',
'            v_new.ind_licenca_importacao,',
'            v_new.quantidade_faturada,',
'            v_new.quantidade_saldo,',
'            v_new.peso_bruto_unitario,',
'            v_new.peso_bruto_total,',
'            v_new.ind_bloqueio_embarque_ate_deferimento_li,',
'            v_new.valor_despesaproforma,',
'            v_new.valor_despesaproforma_unitario,',
'            v_new.valor_desconto_pedido_item_unitario,',
'            v_new.ind_tratamento_saldo,',
'            v_new.valor_total_despesa_invoice_item, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
