unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'		v_id_processo	 number;',
'		v_id_moeda       imp_pedidoimportacao.id_moeda%type;',
'		v_id_incoterm 	 imp_entrega.id_incoterm%type;',
'        v_id_exportador 	 imp_entrega.id_exportador%type;',
'		l_novo_item_id imp_processoimportacao_item.id%type;',
'        p_pagina                    number default 0;',
'	    v_pedidoimportacao_item imp_pedidoimportacao_item%rowtype;',
'    begin',
unistr('        -- Garante o c\00E1lculo correto para colunas c\00E1lculadas:'),
'        v_new.valor_despesaproforma := (nvl(v_new.quantidade,0) * nvl(v_new.valor_despesaproforma_unitario,0));',
'        v_new.valor_total_condicao_venda := (v_new.quantidade * (v_new.valor_unitario - nvl(v_new.valor_desconto_unitario, 0) - nvl(v_new.valor_desconto_pedido_item_unitario,0))) + nvl(v_new.valor_despesaproforma, 0);',
'        v_new.peso_liquido_total := nvl(v_new.quantidade * v_new.peso_unitario, 0);',
'        v_new.quantidade_saldo := (nvl(v_new.quantidade,0) - nvl(v_new.quantidade_faturada,0));',
'        --',
'',
'		select a.id_processoimportacao,',
'			   b.id_moeda,',
'               a.id_exportador,',
'               a.id_incoterm',
'	    into v_id_processo, ',
'	    	 v_id_moeda,',
'             v_id_exportador,',
'             v_id_incoterm',
'	    from imp_entrega 	      a ',
'	    join imp_pedidoimportacao b on a.id_pedidoimportacao = b.id',
'	    where a.id = v_new.id_entrega;',
'',
'	    select * into v_pedidoimportacao_item from imp_pedidoimportacao_item where id = v_new.id_pedidoimportacao_item;',
'		if v_id_processo is not null then',
'			bo_imp_processoimportacao_item.inclui_registro(',
'			    p_id_tenant                                     => v_new.id_tenant,',
'			    p_id_processoimportacao                         => v_id_processo,',
'			    p_id_entrega                                    => v_new.id_entrega,',
'			    p_id_entrega_item                               => v_new.id,',
'			    p_id_minutanotafiscal                           => null,  ',
'                p_id_item                                       => v_new.id_item,',
'			    p_id_ncm                                        => v_new.id_ncm,',
'			    p_id_unidademedida                              => v_new.id_unidademedida,',
'			    p_quantidade                                    => v_new.quantidade,',
'			    p_peso_unitario                                 => v_new.peso_unitario,',
'			    p_peso_liquido_total                            => v_new.peso_liquido_total,',
'			    p_peso_bruto_unitario                           => v_new.peso_bruto_unitario,',
'			    p_peso_bruto_total                              => v_new.peso_bruto_total,',
'			    p_id_pais_origem                                => v_new.id_pais_origem,',
'			    p_id_moeda                                      => v_id_moeda,',
'			    p_id_incoterm                                   => v_id_incoterm,',
'			    p_valor_unitario                                => v_new.valor_unitario,',
'			    p_valor_desconto                                => v_new.valor_desconto_unitario,',
'			    p_valor_total_mercadoria                        => null,',
'                p_valor_total_condicao_venda                    => v_new.valor_total_condicao_venda,',
'			    p_valor_total_desconto_invoice_item             => null,',
'                p_valor_total_despesa_invoice_item              => null,   ',
'			    p_id_naturezaoperacao                           => v_new.id_naturezaoperacao,',
'			    p_id_exportador                                 => v_id_exportador,',
'                p_id_fabricante                                 => v_new.id_fabricante,',
'			    p_ind_licenca_importacao                        => v_new.ind_licenca_importacao,',
'			    p_ind_bloqueio_embarque_ate_deferimento_li      => v_pedidoimportacao_item.ind_bloqueio_embarque_ate_deferimento_li,',
'			    p_id_centrocusto                                => v_pedidoimportacao_item.id_centrocusto,',
'			    p_num_solicitacao_compra                        => v_pedidoimportacao_item.num_solicitacao_compra,',
'			    p_nome_solicitante                              => v_pedidoimportacao_item.nome_solicitante,',
'			    p_data_entrega_desejada                         => v_pedidoimportacao_item.data_entrega_desejada,',
'			    p_quantidade_faturada                           => v_new.quantidade_faturada,',
'			    p_quantidade_saldo                              => v_new.quantidade,',
'                p_ind_finalidade                                => v_pedidoimportacao_item.ind_finalidade,',
'                p_numero_ato_concessorio                        => v_pedidoimportacao_item.numero_ato_concessorio,',
'                p_valor_total_mercadoria_moeda_nacional         => 0,',
'                p_valor_unitario_mercadoria_moeda_nacional      => 0,',
'                p_cst                                           => null,',
'                p_id_cfop                                       => null,',
'                p_cclasstrib                                    => null,',
'			    p_id                                            => l_novo_item_id,',
'			    p_encadeado                                     => true,',
'			    p_sucesso                                       => p_sucesso,',
'			    p_messages                 	                    => p_messages',
'			);',
'		end if;',
'        --',
'        verifica_vinculo_invoice(v_new.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
unistr('        -- Necess\00E1rio limpar qualquer valor em v_new.id para garantir que procedure/fun\00E7\00F5es de inclus\00E3o/altera\00E7\00E3o em massa funcionem corretamente:'),
'        v_new.id := null;',
'    end hook_antes_incluir; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id_pedidoimportacao number;',
'    begin ',
'		bo_imp_entrega.atualiza_valor_total_financeiro(v_new.id_entrega);',
'        bo_imp_pedidoimportacao_item.atualiza_quantidades_programadas(v_new.id_pedidoimportacao_item, v_pagina, true, p_sucesso, p_messages);',
'        select id_pedidoimportacao into l_id_pedidoimportacao from imp_entrega where id = v_new.id_entrega fetch first 1 row only;',
'        atualiza_valor_total_entrega;',
'        atualiza_saldo(l_id_pedidoimportacao);        ',
'        bo_imp_pedidoimportacao_item.executa_altera_registro(v_new.id_pedidoimportacao_item); ',
'        inclui_entrega_item_tributo;',
unistr('        -- Altera status dos t\00EDtulos de pagamento gerados:'),
'        altera_titulopagamento_ind_status_pagamento(v_new.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'        -- Altera status das parcelas de pagamento geradas:',
'        altera_registros_pedidoimportacao_pagamento(v_new.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'        v_new.id := null;',
'    end hook_depois_incluir; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'	    v_id_processo	 			number;',
'		v_id_moeda       			imp_pedidoimportacao.id_moeda%type;',
'		v_id_incoterm 	 			imp_entrega.id_incoterm%type;',
'		l_novo_item_id 				imp_processoimportacao_item.id%type;',
'        p_pagina                    number default 0;',
'	    v_processoimportacao_item 	imp_processoimportacao_item%rowtype;',
'',
'    begin',
unistr('        -- Garante o c\00E1lculo correto para colunas c\00E1lculadas:'),
'        v_new.valor_despesaproforma := (nvl(v_new.quantidade,0) * nvl(v_new.valor_despesaproforma_unitario,0));',
'        v_new.valor_total_condicao_venda := (v_new.quantidade * (v_new.valor_unitario - nvl(v_new.valor_desconto_unitario, 0) - nvl(v_new.valor_desconto_pedido_item_unitario,0))) + nvl(v_new.valor_despesaproforma, 0);',
'        v_new.peso_liquido_total := nvl(v_new.quantidade * v_new.peso_unitario, 0);',
'        v_new.quantidade_saldo := (nvl(v_new.quantidade,0) - nvl(v_new.quantidade_faturada,0));        ',
'        -- 		',
'        if v_operacao = ''ALTERA_REGISTRO_PAGAMENTOS_TITULOS'' then',
'            verifica_vinculo_invoice(v_new.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        --',
'	    -- select a.id_processoimportacao',
'	    -- into v_id_processo',
'	    -- from imp_entrega 	             a ',
'	    -- join imp_pedidoimportacao        b on a.id_pedidoimportacao = b.id',
'	    -- where a.id = v_new.id_entrega;',
'',
'	    -- select * into v_processoimportacao_item from imp_processoimportacao_item where id_pedidoimportacao_item = v_new.id_pedidoimportacao_item;',
'',
'	    -- v_new.valor_total_desconto_invoice_item := v_processoimportacao_item.valor_total_desconto_invoice_item;',
'',
'	    -- if (v_old.id_unidademedida != v_new.id_unidademedida) OR (v_old.quantidade != v_new.quantidade) OR (v_old.valor_unitario != v_new.valor_unitario)then',
'        -- 	hook_valida_vinculo_invoice;',
'		-- end if;',
'',
'		-- if v_id_processo is not null then ',
'		-- 	bo_imp_processoimportacao_item.altera_registro(',
'		-- 	    p_id_tenant                      => v_processoimportacao_item.id_tenant,',
'		-- 	    p_id_processoimportacao          => v_processoimportacao_item.id_processoimportacao,',
'		-- 	    p_id_entrega                     => v_processoimportacao_item.id_entrega,',
'		-- 	    p_id_pedidoimportacao_item       => v_processoimportacao_item.id_pedidoimportacao_item,',
'		-- 	    p_id_item                        => v_processoimportacao_item.id_item,',
'		-- 	    p_id_ncm                         => v_new.id_ncm,',
'		-- 	    p_id_unidademedida               => v_new.id_unidademedida,',
'		-- 	    p_quantidade                     => v_new.quantidade,',
'		-- 	    p_peso_unitario                  => v_new.peso_unitario,',
'		-- 	    p_peso_liquido_total             => v_processoimportacao_item.peso_liquido_total,',
'		-- 	    p_peso_bruto_unitario            => v_new.peso_bruto_unitario,',
'		-- 	    p_peso_bruto_total               => v_processoimportacao_item.peso_bruto_total,',
'		-- 	    p_id_pais_origem                 => v_new.id_pais_origem,',
'		-- 	    p_id_moeda                       => v_processoimportacao_item.id_moeda,',
'		-- 	    p_id_incoterm                    => v_processoimportacao_item.id_incoterm,',
'		-- 	    p_valor_unitario                 => v_new.valor_unitario,',
'		-- 	    p_valor_desconto                 => v_new.valor_desconto,',
'		-- 	    p_valor_total_condicao_venda     => v_processoimportacao_item.valor_total_condicao_venda,',
'		-- 	    p_valor_total_desconto_invoice_item    => v_processoimportacao_item.valor_total_desconto_invoice_item,',
'		-- 	    p_id_naturezaoperacao            => v_new.id_naturezaoperacao,',
'		-- 	    p_id_fabricante                  => v_new.id_fabricante,',
'		-- 	    p_ind_licenca_importacao         => v_new.ind_licenca_importacao,',
'		-- 	    p_ind_bloqueio_embarque_lpco     => v_processoimportacao_item.ind_bloqueio_embarque_lpco,',
'		-- 	    p_id_centrocusto                 => v_processoimportacao_item.id_centrocusto,',
'		-- 	    p_num_solicitacao_compra         => v_processoimportacao_item.num_solicitacao_compra,',
'		-- 	    p_nome_solicitante               => v_processoimportacao_item.nome_solicitante,',
'		-- 	    p_data_entrega_desejada          => v_processoimportacao_item.data_entrega_desejada,',
'		-- 	    p_quantidade_faturada            => v_processoimportacao_item.quantidade_faturada,',
'		-- 	    p_quantidade_cancelada           => v_processoimportacao_item.quantidade_cancelada,',
'		-- 	    p_quantidade_saldo               => v_processoimportacao_item.quantidade_saldo,',
'		-- 	    p_id                             => v_processoimportacao_item.id,',
'		-- 	    p_data_alteracao				 => null,',
'		-- 	    p_sucesso                        => p_sucesso,',
