'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id_pedidoimportacao number;',
'    begin',
'		bo_imp_entrega.atualiza_valor_total_financeiro(v_new.id_entrega);',
'        if v_operacao is null ',
'            or v_operacao not in (''ALTERA_VALOR_DESCONTO_PEDIDO_ITEM_UNITARIO'',''ALTERA_VALOR_DESPESAPROFORMA_UNITARIO'',''ALTERA_IND_TRATAMENTO_SALDO'',''ALTERA_DIVERGENCIAS'',''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'',''TRATAMENTO_SALDO_VINCULAR'') ',
'        then',
'            bo_imp_pedidoimportacao_item.atualiza_quantidades_programadas(v_new.id_pedidoimportacao_item, v_pagina, p_encadeado, p_sucesso, p_messages);        ',
'            select id_pedidoimportacao into l_id_pedidoimportacao from imp_entrega where id = v_new.id_entrega fetch first 1 row only;                            ',
'            atualiza_saldo(l_id_pedidoimportacao);',
'            bo_imp_pedidoimportacao_item.executa_altera_registro(v_new.id_pedidoimportacao_item);',
'        end if;',
'        atualiza_valor_total_entrega;',
'',
'        if v_operacao = ''ALTERA_REGISTRO_PAGAMENTOS_TITULOS'' then',
unistr('            -- Altera status dos t\00EDtulos de pagamento gerados:'),
'            altera_titulopagamento_ind_status_pagamento(v_new.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            -- Altera status das parcelas de pagamento geradas:',
'            altera_registros_pedidoimportacao_pagamento(v_new.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);        ',
'        end if;',
'',
'        if v_operacao = ''ALTERA_DIVERGENCIAS'' then',
'            --bo_imp_pedidoimportacao_item.atualiza_quantidades_programadas(v_new.id_pedidoimportacao_item, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            bo_imp_pedidoimportacao_item.altera_quantidade_tratamento_saldo(v_new.id_pedidoimportacao_item, v_pagina, p_encadeado, p_sucesso, p_messages);            ',
'        end if;',
'',
'        altera_entrega_item_tributo;',
'    end hook_depois_alterar; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_vinculo_invoice(v_old.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'    end hook_antes_excluir; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id_pedidoimportacao number;',
'    begin ',
'		bo_imp_entrega.atualiza_valor_total_financeiro(v_old.id_entrega);',
'        bo_imp_pedidoimportacao_item.atualiza_quantidades_programadas(v_old.id_pedidoimportacao_item, v_pagina, true, p_sucesso, p_messages);',
'        select id_pedidoimportacao into l_id_pedidoimportacao from imp_entrega where id = v_old.id_entrega fetch first 1 row only;',
'        atualiza_saldo(l_id_pedidoimportacao);',
'        bo_imp_pedidoimportacao_item.executa_altera_registro(v_old.id_pedidoimportacao_item);',
'        atualiza_valor_total_entrega;',
'',
unistr('        -- Altera status dos t\00EDtulos de pagamento gerados:'),
'        altera_titulopagamento_ind_status_pagamento(v_old.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'        -- Altera status das parcelas de pagamento geradas:',
'        altera_registros_pedidoimportacao_pagamento(v_old.id_entrega, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'    end hook_depois_excluir;',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'    procedure hook_valida_id_tenant(p_id_tenant in imp_entrega_item.id_tenant%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_tenant;     ',
'',
