'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_entrega;     ',
'',
'    procedure hook_valida_id_pedidoimportacao_item(p_id_pedidoimportacao_item in imp_entrega_item.id_pedidoimportacao_item%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_pedidoimportacao_item;     ',
'',
'    procedure hook_valida_id_item(p_id_item in imp_entrega_item.id_item%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_item;     ',
'',
