'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_ncm;     ',
'',
'    procedure hook_valida_id_unidademedida(p_id_unidademedida in imp_entrega_item.id_unidademedida%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_unidademedida;     ',
'',
'    procedure hook_valida_quantidade(p_quantidade in imp_entrega_item.quantidade%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'        l_qtd_total number;',
'        l_qtd_programada number;',
'        l_qtd_disponivel number;',
'    begin',
'        if nvl(v_operacao, ''-20001'') not in (''ALTERA_DIVERGENCIAS'',''ALTERA_VALOR_DESCONTO_PEDIDO_ITEM_UNITARIO'',''ALTERA_VALOR_DESPESAPROFORMA_UNITARIO'',''TRATAMENTO_SALDO_VINCULAR'',''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'') then',
'            if p_quantidade < 0 then ',
'                v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_entrega_item.quantidade''); ',
'                pkg_mensagem.mensagem_campo_obrigatorio(',
'                    p_nome_campo => ''quantidade'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );            ',
unistr('                -- Inserir o registro na cole\00E7\00E3o'),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;        ',
'            end if;',
'',
'            if v_new.id is not null then ',
'                select (quantidade - nvl(quantidade_cancelada, 0)) into l_qtd_total from imp_pedidoimportacao_item where id = v_new.id_pedidoimportacao_item;',
'                select (nvl(sum(quantidade),0)) into l_qtd_programada from imp_entrega_item where id_pedidoimportacao_item = v_new.id_pedidoimportacao_item and id <> v_new.id;',
'                l_qtd_disponivel := l_qtd_total - l_qtd_programada;',
'                if p_quantidade is not null and ((l_qtd_programada + p_quantidade) > l_qtd_total) then',
'                    l_verifica_valor_unico := 1; ',
'                end if;',
'            else',
'                select (quantidade - nvl(quantidade_cancelada, 0)) into l_qtd_total from imp_pedidoimportacao_item where id = v_new.id_pedidoimportacao_item;',
'                select (p_quantidade + nvl(sum(quantidade),0)) into l_qtd_programada from imp_entrega_item where id_pedidoimportacao_item = v_new.id_pedidoimportacao_item;',
'                l_qtd_disponivel := l_qtd_total - (l_qtd_programada - nvl(p_quantidade,0));            ',
'                if p_quantidade is not null and l_qtd_programada > l_qtd_total then',
'                    l_verifica_valor_unico := 1;',
'                end if;',
'            end if; ',
'            if l_verifica_valor_unico > 0 then ',
'                v_parametro(1) := l_qtd_disponivel;',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => ''52'',',
'                    p_nome_campo => ''quantidade'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );            ',
unistr('                -- Inserir o registro na cole\00E7\00E3o'),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;',
'            end if;  ',
'        end if;',
'    end hook_valida_quantidade;    ',
'',
'    procedure hook_valida_quantidade_faturada(p_quantidade_faturada in imp_entrega_item.quantidade_faturada%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_quantidade_faturada;  ',
'',
