'    --',
'    function detalhe_registro (',
'    p_id in imp_entrega_item.id%type',
'    ) return varchar2 is',
'        l_html varchar2(32767);',
'    begin',
'        return ( pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'            select',
'                a.numero_pedido_importacao,',
'                d.num_entrega,',
'                CASE        ',
'                WHEN d.id_processoimportacao is null THEN',
'                    pkg_componentes.html_cor_texto(''''''||',
'                    retorna_texto(''msg.93.l'')||'''''')',
'                ELSE',
'                    e.num_processoimportacao',
'            END as id_processoimportacao',
'            from imp_pedidoimportacao a ',
'            join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id ',
'            join imp_entrega_item c on c.id_pedidoimportacao_item = b.id ',
'            join imp_entrega d on d.id = c.id_entrega ',
'            left join imp_processoimportacao e on e.id = d.id_processoimportacao      ',
'            where c.id = ''||p_id,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'                )',
'            || pkg_ui.campos_detalhes(q''~',
'            select',
'            d.num_sequencia_item  as imp_pedidoimportacao_item$num_sequencia_item,',
'            c.codigo_item || '' - '' ||',
'            pkg_traducao.get_traducao(c.descricao_item) as imp_entrega_item$id_item,                               ',
'            pkg_traducao.get_traducao(j.CODIGO_UNIDADEMEDIDA) as imp_entrega_item$id_unidademedida, ',
'            case j.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade)',
'            end as imp_entrega_item$quantidade,',
'            to_char(a.peso_liquido_total, ''FM999G999G990D00000'') as imp_entrega_item$peso_liquido_total, ',
'            (h.CODIGO_MOEDA|| '' - '' || h.SIMBOLO_ISO) as imp_pedidoimportacao$id_moeda,',
'            to_char(a.valor_total_condicao_venda, ''FM999G999G990D00'') as imp_entrega_item$valor_total_condicao_venda                                              ',
'        from imp_entrega_item          a',
'        left join ng_pessoa_juridica   b on b.id_pessoa = a.id_fabricante',
'        join ng_item                   c on c.id = a.id_item',
'        join imp_pedidoimportacao_item d on d.id = a.id_pedidoimportacao_item',
'        join imp_pedidoimportacao      e on e.id = d.id_pedidoimportacao',
'        left join ng_unidademedida     j on j.id = a.id_unidademedida',
'        left join ng_moeda             h on h.id = e.id_moeda',
'        where a.id = ~'' || p_id',
'    ));',
'    end detalhe_registro;',
'    --',
'    procedure inclui_registros(  ',
'        p_id_tenant in imp_entrega_item.id_tenant%type,',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_id_pedidoimportacao_item in varchar2,',
'        p_id_item in imp_entrega_item.id_item%type,',
'        p_id_ncm in imp_entrega_item.id_ncm%type,',
'        p_id_unidademedida in imp_entrega_item.id_unidademedida%type,',
'        p_quantidade in imp_entrega_item.quantidade%type,',
'        p_quantidade_faturada in imp_entrega_item.quantidade_faturada%type,',
'        p_quantidade_saldo in imp_entrega_item.quantidade_saldo%type,',
'        p_peso_unitario in imp_entrega_item.peso_unitario%type,',
'        p_peso_liquido_total in imp_entrega_item.peso_liquido_total%type,',
'        p_peso_bruto_unitario in imp_entrega_item.peso_bruto_unitario%type,',
'        p_peso_bruto_total in imp_entrega_item.peso_bruto_total%type,',
'        p_valor_unitario in imp_entrega_item.valor_unitario%type,',
'        p_valor_desconto_unitario in imp_entrega_item.valor_desconto_unitario%type,',
'        p_valor_desconto_pedido_item_unitario in imp_entrega_item.valor_desconto_pedido_item_unitario%type,',
'        p_valor_despesaproforma in imp_entrega_item.valor_despesaproforma%type,',
'        p_valor_despesaproforma_unitario in imp_entrega_item.valor_despesaproforma_unitario%type,',
'        p_valor_total_condicao_venda in imp_entrega_item.valor_total_condicao_venda%type,',
'        p_valor_total_despesa_invoice_item in imp_entrega_item.valor_total_despesa_invoice_item%type,',
'	    p_valor_total_desconto_invoice_item in imp_entrega_item.valor_total_desconto_invoice_item%type,',
'        p_id_naturezaoperacao in imp_entrega_item.id_naturezaoperacao%type,',
'        p_id_fabricante in imp_entrega_item.id_fabricante%type,',
'        p_id_pais_origem in imp_entrega_item.id_pais_origem%type,',
'        p_ind_licenca_importacao in imp_entrega_item.ind_licenca_importacao%type,',
'        p_ind_bloqueio_embarque_ate_deferimento_li in imp_entrega_item.ind_bloqueio_embarque_ate_deferimento_li%type,',
'        p_id out imp_entrega_item.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is  ',
'        l'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767770699593166)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'_id number;',
'        l_verifica_entrega_item number;',
'    begin',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        for rec in (',
'            select to_number(regexp_substr(p_id_pedidoimportacao_item, ''[^:]+'', 1, level)) as id_pedidoimportacao_item',
'            from dual',
'            connect by level <= regexp_count(p_id_pedidoimportacao_item, '':'') + 1',
'        ) loop',
'            declare',
'                l_item imp_pedidoimportacao_item%rowtype;',
'                l_id_ncm ng_item_produto.id_ncm%type;',
'            begin',
'                select *',
'                into l_item',
'                from imp_pedidoimportacao_item',
'                where id = rec.id_pedidoimportacao_item;',
'                select id_ncm into l_id_ncm from ng_item_produto where id_item = l_item.id_item;',
'                inclui_registro(',
'                    p_id_tenant => p_id_tenant,',
'                    p_id_entrega => p_id_entrega,',
'                    p_id_pedidoimportacao_item => rec.id_pedidoimportacao_item,                ',
'                    p_id_item => l_item.id_item,',
'                    p_id_ncm => l_id_ncm,',
'                    p_id_unidademedida => l_item.id_unidademedida,',
'                    p_quantidade => p_quantidade,',
'                    p_quantidade_faturada => l_item.quantidade_faturada,',
'                    p_quantidade_saldo => l_item.quantidade_faturar,',
'                    p_peso_unitario => l_item.peso_unitario,',
'                    p_peso_liquido_total => (p_quantidade * l_item.peso_unitario),',
'                    p_peso_bruto_unitario => null,',
'                    p_peso_bruto_total => null,',
'                    p_valor_unitario => l_item.valor_unitario,',
'                    p_valor_desconto_unitario => l_item.valor_desconto_unitario,',
'                    p_valor_desconto_pedido_item_unitario => l_item.valor_desconto_pedido_item_unitario,',
'                    p_valor_despesaproforma => (p_quantidade * l_item.valor_despesaproforma_unitario),',
'                    p_valor_despesaproforma_unitario => l_item.valor_despesaproforma_unitario,',
'                    p_valor_total_condicao_venda => (p_quantidade * (l_item.valor_unitario - l_item.valor_desconto_unitario)) + (p_quantidade * l_item.valor_despesaproforma_unitario),',
'		            p_valor_total_despesa_invoice_item => null,',
'                    p_valor_total_desconto_invoice_item => null,',
'                    p_id_naturezaoperacao => l_item.id_naturezaoperacao,',
'                    p_id_fabricante => l_item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(l_item.id_fabricante),',
'                    p_ind_licenca_importacao => l_item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => l_item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo => null,',
'                    p_id => l_id,                ',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );            ',
'            end;',
'        end loop;',
'    end;',
'    --',
'    procedure atualiza_qtd_programada(',
'        p_id in imp_entrega_item.id%type,',
'        p_quantidade in imp_entrega_item.quantidade%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_imp_entrega_item imp_entrega_item%rowtype; ',
'        l_valor_unitario number;               ',
'        l_valor_desconto_unitario number;',
'    begin        ',
'        p_messages := pkg_mensagem.message_record_table();',
'        select * into l_imp_entrega_item from imp_entrega_item where id = p_id;',
'        select nvl(valor_unitario,0), nvl(valor_desconto_unitario,0) into l_valor_unitario, l_valor_desconto_unitario from imp_pedidoimportacao_item where id = l_imp_entrega_item.id_pedidoimportacao_item;        ',
'        altera_registro(',
'            p_id_tenant => l_imp_entrega_item.id_tenant,',
'            p_id_entrega => l_imp_entrega_item.id_entrega,',
'            p_id_pedidoimportacao_item => l_imp_entrega_item.id_pedidoimportacao_item,',
'            p_id_item => l_imp_entrega_item.id_item,',
'            p_id_ncm => l_imp_entrega_item.id_ncm,',
'            p_id_unidademedida => l_imp_entrega_item.id_unidademedida,',
'            p_quantidade => p_quantidade,',
'            p_quantidade_faturada => l_imp_entrega_item.quantidade_faturada,',
'            p_quantidade_saldo => l_imp_entrega_item.quantidade_saldo,',
'            p_peso_unitario => l_imp_entrega_item.peso_unitario,',
'            p_peso_liquido_total => (p_quantidade * l_imp_entrega_item.peso_unitario),',
'            p_peso_bruto_unitario => null,',
'            p_peso_bruto_total => null,',
'            p_valor_unitario => l_imp_entrega_item.valor_unitario,',
'            p_valor_desconto_unitario => l_imp_entrega_item.valor_desconto_unitario,',
'            p_valor_desconto_pedido_item_unitario => l_imp_entrega_item.valor_desconto_pedido_item_unitario,',
'            p_valor_despesaproforma => l_imp_entrega_item.valor_despesaproforma,',
'            p_valor_despesaproforma_unitario => l_imp_entrega_item.valor_despesaproforma_unitario,',
'            p_valor_total_condicao_venda => (p_quantidade * (l_imp_entrega_item.valor_unitario - l_imp_entrega_item.valor_desconto_unitario)) + l_imp_entrega_item.valor_despesaproforma,',
'	        p_valor_total_despesa_invoice_item => l_imp_entrega_item.valor_total_despesa_invoice_item,',
'            p_valor_total_desconto_invoice_item => l_imp_entrega_item.valor_total_desconto_invoice_item,',
'            p_id_naturezaoperacao => l_imp_entrega_item.id_naturezaoperacao,',
'            p_id_fabricante => l_imp_entrega_item.id_fabricante,',
'            p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(l_imp_entrega_item.id_fabricante),',
'            p_ind_licenca_importacao => l_imp_entrega_item.ind_licenca_importacao,',
'            p_ind_bloqueio_embarque_ate_deferimento_li => l_imp_entrega_item.ind_bloqueio_embarque_ate_deferimento_li,',
'            p_ind_tratamento_saldo => l_imp_entrega_item.ind_tratamento_saldo,',
'            p_id => l_imp_entrega_item.id,',
'            p_data_alteracao => l_imp_entrega_item.data_alteracao,',
'            p_pagina => p_pagina,',
'            p_encadeado => true,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );        ',
'    end;',
'    --',
'    procedure atualiza_valor_total_entrega is',
'        l_valor_total number;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        --p_messages := pkg_mensagem.message_record_table();',
'        l_messages := pkg_mensagem.message_record_table();',
'',
'        select sum(valor_total_condicao_venda) into l_valor_total from imp_entrega_item where id_entrega = nvl(v_new.id_entrega, v_old.id_entrega);',
'        select * into v_old_imp_entrega from imp_entrega where id = nvl(v_new.id_entrega, v_old.id_entrega);',
'        v_new_imp_entrega := v_old_imp_entrega;',
'        bo_imp_entrega.altera_registro(',
'            p_id_tenant => v_new_imp_entrega.id_tenant,',
'            p_id_pedidoimportacao => v_new_imp_entrega.id_pedidoimportacao,',
'            p_num_entrega => v_new_imp_entrega.num_entrega,',
'            p_id_processoimportacao => v_new_imp_entrega.id_processoimportacao,',
'            p_ind_modalidade_importacao => v_new_imp_entrega.ind_modalidade_importacao,',
'            p_id_exportador => v_new_imp_entrega.id_exportador,',
'            p_id_importador => v_new_imp_entrega.id_importador,',
'            p_id_adquirente => v_new_imp_entrega.id_adquirente,',
'            p_id_endereco_origem => v_new_imp_entrega.id_endereco_origem,            ',
'            p_id_local_embarque => v_new_imp_entrega.id_local_embarque,',
'            p_id_local_desembarque => v_new_imp_entrega.id_local_desembarque,',
