'            p_data_disponivel_calculada => v_new_imp_entrega.data_disponivel_calculada,',
'            p_data_disponivel_real => v_new_imp_entrega.data_disponivel_real,',
'            p_data_embarque_real => v_new_imp_entrega.data_embarque_real,',
'            p_data_embarque_informada => v_new_imp_entrega.data_embarque_informada,',
'            p_data_embarque_calculada => v_new_imp_entrega.data_embarque_calculada,',
