'            p_data_recebimento_informada => v_new_imp_entrega.data_recebimento_informada,',
'            p_data_recebimento_calculada => v_new_imp_entrega.data_recebimento_calculada,',
'            p_data_recebimento_real => v_new_imp_entrega.data_recebimento_real,',
'            p_valor_total_condicao_venda => l_valor_total,   ',
'            p_id_invoice => v_new_imp_entrega.id_invoice,   ',
'            p_valor_total_financeiro => v_new_imp_entrega.valor_total_financeiro,',
'            p_id => v_new_imp_entrega.id,',
'            p_data_alteracao => v_new_imp_entrega.data_alteracao,              ',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
