'    --',
'    procedure atualiza_saldo(',
'        p_id_pedidoimportacao in imp_pedidoimportacao.id%type',
'    ) is',
'    begin',
'        bo_imp_pedidoimportacao.executa_altera_registro(p_id_pedidoimportacao);',
'    end;',
'    --',
'    procedure atualizar_saldo_item(',
'        p_id_pedidoimportacao_item in imp_pedidoimportacao_item.id%type',
'    ) is',
'        l_imp_pedidoimportacao_item imp_pedidoimportacao_item%rowtype;',
'        l_qtd_programada number;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        --p_messages := pkg_mensagem.message_record_table();',
'        l_messages := pkg_mensagem.message_record_table();',
'',
unistr('        -- Atualizando qtd_programada e qtd_programar_entrega do item do pedido de importa\00E7\00E3o'),
'        select * into l_imp_pedidoimportacao_item from imp_pedidoimportacao_item where id = p_id_pedidoimportacao_item;',
'        select nvl(sum(quantidade), 0) into l_qtd_programada from imp_entrega_item where id_pedidoimportacao_item = l_imp_pedidoimportacao_item.id;',
'        bo_imp_pedidoimportacao_item.altera_registro(',
'            p_id_tenant => l_imp_pedidoimportacao_item.id_tenant,',
'            p_id_pedidoimportacao => l_imp_pedidoimportacao_item.id_pedidoimportacao,',
'            p_id_item => l_imp_pedidoimportacao_item.id_item,',
'            p_num_sequencia_item => l_imp_pedidoimportacao_item.num_sequencia_item,',
'            p_id_unidademedida => l_imp_pedidoimportacao_item.id_unidademedida,',
'            p_quantidade_firmada => l_imp_pedidoimportacao_item.quantidade_firmada,',
'            p_quantidade => l_imp_pedidoimportacao_item.quantidade,',
'            p_peso_unitario => l_imp_pedidoimportacao_item.peso_unitario,',
'            p_peso_liquido_total => l_imp_pedidoimportacao_item.peso_liquido_total,',
'            p_valor_unitario => l_imp_pedidoimportacao_item.valor_unitario,',
'            p_valor_desconto_unitario => l_imp_pedidoimportacao_item.valor_desconto_unitario,',
'            p_valor_despesaproforma => l_imp_pedidoimportacao_item.valor_despesaproforma,',
'            p_valor_despesaproforma_unitario => l_imp_pedidoimportacao_item.valor_despesaproforma_unitario,',
'            p_valor_total => l_imp_pedidoimportacao_item.valor_total,',
'            p_valor_desconto_pedido_item => l_imp_pedidoimportacao_item.valor_desconto_pedido_item,',
'            p_valor_desconto_pedido_item_unitario => l_imp_pedidoimportacao_item.valor_desconto_pedido_item_unitario,',
'            p_id_fabricante => l_imp_pedidoimportacao_item.id_fabricante,',
'            p_id_ncm => l_imp_pedidoimportacao_item.id_ncm,',
'            p_ind_licenca_importacao => l_imp_pedidoimportacao_item.ind_licenca_importacao,',
'            p_ind_bloqueio_embarque_ate_deferimento_li => l_imp_pedidoimportacao_item.ind_bloqueio_embarque_ate_deferimento_li,',
'            p_id_naturezaoperacao => l_imp_pedidoimportacao_item.id_naturezaoperacao,',
'            p_id_centrocusto => l_imp_pedidoimportacao_item.id_centrocusto,',
'            p_ind_finalidade => l_imp_pedidoimportacao_item.ind_finalidade,',
'            p_numero_ato_concessorio => l_imp_pedidoimportacao_item.numero_ato_concessorio,',
'            p_num_solicitacao_compra => l_imp_pedidoimportacao_item.num_solicitacao_compra,',
'            p_nome_solicitante => l_imp_pedidoimportacao_item.nome_solicitante,',
'            p_data_entrega_desejada => l_imp_pedidoimportacao_item.data_entrega_desejada,',
'            p_quantidade_programada_entrega => l_qtd_programada,',
'            p_quantidade_programar_entrega => (l_imp_pedidoimportacao_item.quantidade_programar_entrega - l_qtd_programada),',
'            p_quantidade_faturada => l_imp_pedidoimportacao_item.quantidade_faturada,',
'            p_quantidade_cancelada => l_imp_pedidoimportacao_item.quantidade_cancelada,',
'            p_quantidade_faturar => l_imp_pedidoimportacao_item.quantidade_faturar,',
'            p_id => l_imp_pedidoimportacao_item.id,',
'            p_data_alteracao => l_imp_pedidoimportacao_item.data_alteracao,            ',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
'        );',
'    end;    ',
'    --',
'    procedure inclui_entrega_item_tributo',
'    is ',
'        l_id number;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        l_messages := pkg_mensagem.message_record_table();',
'        bo_imp_entrega_item_tributo.inclui_tributos(',
'            p_id_tenant => v_new.id_tenant,',
'            p_id_entrega_item => v_new.id,            ',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
'        );',
'    exception ',
'        when others then',
'            raise_application_error(-20001, ''Erro!'');',
'    end;',
'    --',
'    procedure altera_entrega_item_tributo',
'    is ',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table(); ',
'        --p_messages := pkg_mensagem.message_record_table();',
'        l_messages := pkg_mensagem.message_record_table();        ',
'',
'        bo_imp_entrega_item_tributo.altera_tributos(        ',
'            p_id_entrega_item => v_new.id,',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
'        );',
'    end altera_entrega_item_tributo;',
'',
'',
'    --',
'    procedure vincula_itens_em_entrega_existente(',
'        p_id_pedidoimportacao_itens in varchar2,',
'        p_id_entrega in imp_entrega.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_pedidoimportacao_itens apex_t_varchar2 := null;',
'        l_id_tenant number;        ',
'        l_pedidoimportacao_item imp_pedidoimportacao_item%rowtype;        ',
'        l_id_ncm number;',
'        l_id number;',
'        l_verifica_entrega_ja_possui_o_item number;',
'        l_entrega_item imp_entrega_item%rowtype;',
'    begin',
'        l_id_pedidoimportacao_itens := apex_string.split(p_id_pedidoimportacao_itens, ''_'');',
'        select id_tenant into l_id_tenant from imp_entrega where id = p_id_entrega;',
'',
'        for i in 1..l_id_pedidoimportacao_itens.count loop',
'            select * into l_pedidoimportacao_item from imp_pedidoimportacao_item where id = l_id_pedidoimportacao_itens(i);',
'            select id_ncm into l_id_ncm from ng_item_produto where id_item = l_pedidoimportacao_item.id_item;',
'',
unistr('            -- Verifica se a entrega selecionada para vincular os itens, j\00E1 possui algum dos itens selecionados:'),
'            select count(1) into l_verifica_entrega_ja_possui_o_item from imp_entrega_item where id_entrega = p_id_entrega and id_pedidoimportacao_item = l_id_pedidoimportacao_itens(i);',
'',
unistr('            -- Se n\00E3o possui, ent\00E3o deve apenas inseri-los:'),
'            if l_verifica_entrega_ja_possui_o_item = 0 then',
'                inclui_registro(',
'                    p_id_tenant => l_id_tenant,',
'                    p_id_entrega => p_id_entrega,',
'                    p_id_pedidoimportacao_item => l_id_pedidoimportacao_itens(i),',
'                    p_id_item => l_pedidoimportacao_item.id_item,',
'                    p_id_ncm => l_pedidoimportacao_item.id_ncm,--l_id_ncm,',
'                    p_id_unidademedida => l_pedidoimportacao_item.id_unidademedida,',
'                    p_quantidade => l_pedidoimportacao_item.quantidade_programar_entrega,',
'                    p_quantidade_faturada => l_pedidoimportacao_item.quantidade_faturada,',
'                    p_quantidade_saldo => l_pedidoimportacao_item.quantidade_faturar,',
'                    p_peso_unitario => l_pedidoimportacao_item.peso_unitario,',
'                    p_peso_liquido_total => (l_pedidoimportacao_item.quantidade_programar_entrega * l_pedidoimportacao_item.peso_unitario),',
'                    p_peso_bruto_unitario => null,',
'                    p_peso_bruto_total => null,',
'                    p_valor_unitario => l_pedidoimportacao_item.valor_unitario,',
'                    p_valor_desconto_unitario => l_pedidoimportacao_item.valor_desconto_unitario,',
'                    p_valor_desconto_pedido_item_unitario => l_pedidoimportacao_item.valor_desconto_pedido_item_unitario,',
'                    p_valor_despesaproforma => (l_pedidoimportacao_item.quantidade_programar_entrega * l_pedidoimportacao_item.valor_despesaproforma_unitario),',
'                    p_valor_despesaproforma_unitario => l_pedidoimportacao_item.valor_despesaproforma_unitario,',
'                    p_valor_total_condicao_venda => (l_pedidoimportacao_item.quantidade_programar_entrega * (l_pedidoimportacao_item.valor_unitario - l_pedidoimportacao_item.valor_desconto_unitario)) + (l_pedidoimportacao_item.quantidade_programar_en'
||'trega * l_pedidoimportacao_item.valor_despesaproforma_unitario),',
'    		        p_valor_total_despesa_invoice_item => null,',
'                    p_valor_total_desconto_invoice_item => null,',
'                    p_id_naturezaoperacao => l_pedidoimportacao_item.id_naturezaoperacao,',
'                    p_id_fabricante => l_pedidoimportacao_item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(l_pedidoimportacao_item.id_fabricante),',
'                    p_ind_licenca_importacao => l_pedidoimportacao_item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => l_pedidoimportacao_item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo => null,',
'                    p_id => l_id,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'',
unistr('            -- Se j\00E1 possui ent\00E3o deve apenas atualizar a quantidade e n\00E3o duplicar o item na entrega:'),
'            else',
'                select * into l_entrega_item from imp_entrega_item where id_entrega = p_id_entrega and id_pedidoimportacao_item = l_id_pedidoimportacao_itens(i);',
'                --altera_registro(',
'                altera_registro_pagamentos_titulos(',
'                    p_id_tenant => l_entrega_item.id_tenant,',
'                    p_id_entrega => l_entrega_item.id_entrega,',
'                    p_id_pedidoimportacao_item => l_entrega_item.id_pedidoimportacao_item,',
'                    p_id_item => l_entrega_item.id_item,',
'                    p_id_ncm => l_entrega_item.id_ncm,',
'                    p_id_unidademedida => l_entrega_item.id_unidademedida,',
'                    p_quantidade => (l_entrega_item.quantidade + l_pedidoimportacao_item.quantidade_programar_entrega),',
'                    p_quantidade_faturada => nvl(l_entrega_item.quantidade_faturada, 0),',
'                    p_quantidade_saldo => nvl(l_entrega_item.quantidade_saldo, 0),',
'                    p_peso_unitario => nvl(l_entrega_item.peso_unitario, 0),',
'                    p_peso_liquido_total => ((l_entrega_item.quantidade + l_pedidoimportacao_item.quantidade_programar_entrega) * nvl(l_entrega_item.peso_unitario, 0)),',
'                    p_peso_bruto_unitario => nvl(l_entrega_item.peso_bruto_unitario, 0),',
'                    p_peso_bruto_total => ((l_entrega_item.quantidade + l_pedidoimportacao_item.quantidade_programar_entrega) * nvl(l_entrega_item.peso_bruto_unitario, 0)),',
'                    p_valor_unitario => l_entrega_item.valor_unitario,',
'                    p_valor_desconto_unitario => nvl(l_entrega_item.valor_desconto_unitario, 0),',
'                    p_valor_desconto_pedido_item_unitario => nvl(l_entrega_item.valor_desconto_pedido_item_unitario, 0),',
'                    p_valor_despesaproforma => ((l_entrega_item.quantidade + l_pedidoimportacao_item.quantidade_programar_entrega) * nvl(l_entrega_item.valor_despesaproforma_unitario, 0)),',
'                    p_valor_despesaproforma_unitario => nvl(l_entrega_item.valor_despesaproforma_unitario, 0),',
'                    p_valor_total_condicao_venda => ((l_entrega_item.quantidade + l_pedidoimportacao_item.quantidade_programar_entrega) * (l_entrega_item.valor_unitario - nvl(l_entrega_item.valor_desconto_unitario, 0))) + ((l_entrega_item.quantidade '
||'+ l_pedidoimportacao_item.quantidade_programar_entrega) * nvl(l_entrega_item.valor_despesaproforma_unitario, 0)),',
'		    		p_valor_total_desconto_invoice_item => nvl(l_entrega_item.valor_total_desconto_invoice_item, 0),',
'                    p_id_naturezaoperacao => l_entrega_item.id_naturezaoperacao,',
'                    p_id_fabricante => l_entrega_item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(l_entrega_item.id_fabricante),',
'                    p_ind_licenca_importacao => l_entrega_item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => l_entrega_item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo => l_entrega_item.ind_tratamento_saldo,',
'                    p_id => l_entrega_item.id,',
'                    p_data_alteracao => l_entrega_item.data_alteracao,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end if;',
'        end loop; ',
'    end vincula_itens_em_entrega_existente;',
'    --',
'    procedure gerencia_entrega_item(',
'        p_json_importacaoitem in clob,',
'        p_id_entrega in imp_entrega_item.id_entrega%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant number;',
'        l_json clob;',
'        l_item imp_pedidoimportacao_item%rowtype;',
'        l_id_ncm number;',
'        l_id number;',
'        l_imp_entrega_item imp_entrega_item%rowtype;',
'    begin',
'        select id_tenant into l_id_tenant from imp_entrega where id = p_id_entrega;',
'        l_json := p_json_importacaoitem;',
'        for item in (',
'            select json_item.id, pkg_util.retorna_number(json_item.qtd) qtd, json_item.id_ei',
'              from json_table(l_json, ''$[*]''',
'                columns',
'                    id    varchar2(50) path ''$.id'',',
'                    qtd   varchar2(50) path ''$.qtd'',',
'                    id_ei varchar2(50) path ''$.id_ei''',
'              ) json_item',
'        ) loop ',
'            -- Tratamento incluir:           ',
'            if item.id_ei = 0 and item.qtd > 0 then                ',
'                select * into l_item from imp_pedidoimportacao_item where id = item.id;',
'                select id_ncm into l_id_ncm from ng_item_produto where id_item = l_item.id_item;',
'                v_new.id := null;',
'                inclui_registro(',
'                    p_id_tenant => l_id_tenant,',
'                    p_id_entrega => p_id_entrega,',
'                    p_id_pedidoimportacao_item => l_item.id,',
'                    p_id_item => l_item.id_item,',
'                    p_id_ncm => l_id_ncm,',
'                    p_id_unidademedida => l_item.id_unidademedida,',
'                    p_quantidade => item.qtd,',
'                    p_quantidade_faturada => null,',
'                    p_quantidade_saldo => item.qtd,',
'                    p_peso_unitario => l_item.peso_unitario,',
'                    p_peso_liquido_total => (item.qtd * nvl(l_item.peso_unitario, 0)),',
'                    p_peso_bruto_unitario => null,',
'                    p_peso_bruto_total => null,',
'                    p_valor_unitario => l_item.valor_unitario,',
'                    p_valor_desconto_unitario => l_item.valor_desconto_unitario,',
'                    p_valor_desconto_pedido_item_unitario => l_item.valor_desconto_pedido_item_unitario,',
'                    p_valor_despesaproforma => (item.qtd * nvl(l_item.valor_despesaproforma_unitario, 0)),',
'                    p_valor_despesaproforma_unitario => l_item.valor_despesaproforma_unitario,',
'                    p_valor_total_condicao_venda => (item.qtd * (l_item.valor_unitario - nvl(l_item.valor_desconto_unitario, 0))) + (item.qtd * nvl(l_item.valor_despesaproforma_unitario, 0)),',
'		    		p_valor_total_despesa_invoice_item => null,',
'                    p_valor_total_desconto_invoice_item => null,',
'                    p_id_naturezaoperacao => l_item.id_naturezaoperacao,',
'                    p_id_fabricante => l_item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(l_item.id_fabricante),',
'                    p_ind_licenca_importacao => l_item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => l_item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo => null,',
'                    p_id => l_id,                ',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages                ',
'                );',
'',
'            -- Tratamento alterar:',
'            elsif item.id_ei <> 0 and item.qtd > 0 then',
'                select * into l_imp_entrega_item from imp_entrega_item where id = item.id_ei;',
'                altera_registro(',
'                    p_id_tenant => l_imp_entrega_item.id_tenant,',
'                    p_id_entrega => l_imp_entrega_item.id_entrega,',
'                    p_id_pedidoimportacao_item => l_imp_entrega_item.id_pedidoimportacao_item,',
'                    p_id_item => l_imp_entrega_item.id_item,',
'                    p_id_ncm => l_imp_entrega_item.id_ncm,',
'                    p_id_unidademedida => l_imp_entrega_item.id_unidademedida,',
'                    p_quantidade => item.qtd,',
'                    p_quantidade_faturada => null,',
'                    p_quantidade_saldo => item.qtd,',
'                    p_peso_unitario => l_imp_entrega_item.peso_unitario,',
'                    p_peso_liquido_total => (item.qtd * nvl(l_imp_entrega_item.peso_unitario, 0)),',
'                    p_peso_bruto_unitario => null,',
'                    p_peso_bruto_total => null,',
'                    p_valor_unitario => l_imp_entrega_item.valor_unitario,',
'                    p_valor_desconto_unitario => l_imp_entrega_item.valor_desconto_unitario,',
'                    p_valor_desconto_pedido_item_unitario => l_imp_entrega_item.valor_desconto_pedido_item_unitario,',
'                    p_valor_despesaproforma => (item.qtd * nvl(l_imp_entrega_item.valor_despesaproforma_unitario, 0)),',
'                    p_valor_despesaproforma_unitario => l_imp_entrega_item.valor_despesaproforma_unitario,',
'                    p_valor_total_condicao_venda => (item.qtd * (l_imp_entrega_item.valor_unitario - nvl(l_imp_entrega_item.valor_desconto_unitario, 0))) + (item.qtd * nvl(l_imp_entrega_item.valor_despesaproforma_unitario, 0)),',
'		    		p_valor_total_desconto_invoice_item => l_imp_entrega_item.valor_total_desconto_invoice_item,',
'                    p_valor_total_despesa_invoice_item => l_imp_entrega_item.valor_total_despesa_invoice_item,',
'                    p_id_naturezaoperacao => l_imp_entrega_item.id_naturezaoperacao,',
'                    p_id_fabricante => l_imp_entrega_item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(l_imp_entrega_item.id_fabricante),',
'                    p_ind_licenca_importacao => l_imp_entrega_item.ind_licenca_importacao,',
'                    p_ind_bloqueio_embarque_ate_deferimento_li => l_imp_entrega_item.ind_bloqueio_embarque_ate_deferimento_li,',
'                    p_ind_tratamento_saldo => l_imp_entrega_item.ind_tratamento_saldo,',
'                    p_id => l_imp_entrega_item.id,',
'                    p_data_alteracao => l_imp_entrega_item.data_alteracao,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => true,',
'              '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154767770699593166)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'      p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'',
'            -- Tratamento excluir:',
'            elsif item.id_ei <> 0 and item.qtd = 0 then',
'                select * into l_imp_entrega_item from imp_entrega_item where id = item.id_ei;',
'                exclui_registro(',
'                    p_id => l_imp_entrega_item.id,',
'                    p_encadeado => true,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end if;            ',
'        end loop;',
'    end gerencia_entrega_item;',
'    --',
'    procedure altera_id_naturezaoperacao_todos_itens(',
'        p_id_naturezaoperacao in imp_entrega_item.id_naturezaoperacao%type,',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_id_naturezaoperacao_todos_itens'';',
'        v_pagina := p_pagina;',
'',
'        for item in (',
'            select * from imp_entrega_item where id_entrega = p_id_entrega',
'        ) loop',
'            select * into v_old from imp_entrega_item where id = item.id;',
'            v_new := v_old;',
'	    	v_new.valor_total_condicao_venda := (v_new.quantidade * (v_new.valor_unitario - v_new.valor_desconto_unitario)) + v_new.valor_despesaproforma;',
'',
'            v_new.id_naturezaoperacao := p_id_naturezaoperacao;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''ALTERA_ID_NATUREZAOPERACAO_TODOS_ITENS'';',
'',
'            grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'        end loop;',
'    end altera_id_naturezaoperacao_todos_itens;',
'    --',
'    procedure altera_quantidade_faturada(',
'        p_quantidade_faturada in imp_entrega_item.quantidade_faturada%type,',
'        p_id in imp_entrega_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_quantidades'';',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'        v_new.valor_total_condicao_venda := (v_new.quantidade * (v_new.valor_unitario - v_new.valor_desconto_unitario)) + v_new.valor_despesaproforma;',
'',
'        v_new.quantidade_faturada := nvl(p_quantidade_faturada,0);',
'        v_new.quantidade_saldo := nvl(v_new.quantidade,0) - nvl(p_quantidade_faturada,0);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_QUANTIDADE_FATURADA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);           ',
'    end altera_quantidade_faturada;',
'    --',
'    procedure altera_divergencias(',
'        p_quantidade in imp_entrega_item.quantidade%type default null,',
'        p_id_unidademedida in imp_entrega_item.id_unidademedida%type default null,',
'        p_id_ncm in imp_entrega_item.id_ncm%type default null,',
'        p_valor_unitario in imp_entrega_item.valor_unitario%type default null,',
'        p_id in imp_entrega_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_divergencias'';',
'',
'        select * into v_old from imp_entrega_item where id = p_id;',
'        v_new := v_old;',
'        if p_quantidade is not null then',
unistr('            -- p_quantidade \00E9 a diferen\00E7a, ou seja, deve somar \00E0 quantidade antiga:'),
'            v_new.quantidade := v_new.quantidade + p_quantidade;',
'        end if;',
'        if p_id_unidademedida is not null then',
'            v_new.id_unidademedida := p_id_unidademedida;',
'        end if;',
'        if p_id_ncm is not null then',
'            v_new.id_ncm := p_id_ncm;',
'        end if;',
'        if p_valor_unitario is not null then',
'            v_new.valor_unitario := p_valor_unitario;',
'        end if;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_DIVERGENCIAS'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_divergencias;',
'    --',
'    procedure hook_valida_vinculo_invoice',
'	is ',
'	    v_status number;',
'	begin ',
'	    select min(c.ind_status)',
'	      into v_status',
'	      from imp_invoice_item a',
'	      join imp_entrega b on b.id = a.id_entrega',
'	      join imp_invoice c on c.id = a.id_invoice',
'	     where b.id = v_old.id_entrega;',
'',
'	    if v_status = 3 then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => 131,',
'                    p_nome_campo => ''data_nacionalizacao_informada'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                ); 	    end if;',
'				v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;',
'	end hook_valida_vinculo_invoice;',
'    --',
'    procedure altera_valor_desconto_pedido_item_unitario(  ',
'        p_valor_desconto_pedido_item_unitario in imp_entrega_item.valor_desconto_pedido_item_unitario%type, ',
'        p_id in imp_entrega_item.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_valor_desconto_pedido_item_unitario'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_desconto_pedido_item_unitario := p_valor_desconto_pedido_item_unitario; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_VALOR_DESCONTO_PEDIDO_ITEM_UNITARIO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_valor_desconto_pedido_item_unitario;',
'    --',
'    procedure altera_valor_despesaproforma_unitario(  ',
'        p_valor_despesaproforma_unitario in imp_entrega_item.valor_despesaproforma_unitario%type, ',
'        p_id in imp_entrega_item.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_valor_despesaproforma_unitario'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_despesaproforma_unitario := p_valor_despesaproforma_unitario; ',
'        v_new.valor_despesaproforma := (v_new.quantidade * p_valor_despesaproforma_unitario);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_VALOR_DESPESAPROFORMA_UNITARIO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_valor_despesaproforma_unitario;',
'    --',
'    procedure altera_titulopagamento_ind_status_pagamento(',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade number;',
'        l_ind_status_pagamento number;',
'    begin',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'        for titulopagamento in (',
'            select ',
'                a.id,',
'                a.ind_status_pagamento',
'            from fin_titulopagamento a',
'            join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'            where a.id_entidade = l_id_entidade',
unistr('            and a.ind_status_pagamento in (1,2) -- 1=Em aberto, 2=Pago, 3=Cancelado, 4=Cr\00E9dito'),
'            and b.id_entrega = p_id_entrega',
'        ) loop',
'            if titulopagamento.ind_status_pagamento = 1 then',
'                l_ind_status_pagamento := 3;',
'            elsif titulopagamento.ind_status_pagamento = 2 then',
'                l_ind_status_pagamento := 4;',
'            end if;',
'',
'            bo_fin_titulopagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => l_ind_status_pagamento,',
'                p_id => titulopagamento.id,',
'                p_pagina => v_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_titulopagamento_ind_status_pagamento;',
'    --',
'    procedure altera_registros_pedidoimportacao_pagamento(',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_data_vencimento_prevista date;',
'    begin',
'        for parcela_entrega in (',
'            select',
'                a.id,',
'                trunc(((e.percentual / 100) * b.valor_total_condicao_venda),2) valor,',
'                e.ind_evento_gerador_pagamento,',
'                e.qtd_dias_evento,',
'                b.id_invoice,',
'                coalesce(data_disponivel_real, data_disponivel_informada, data_disponivel_calculada) data_disponivel,',
'                coalesce(data_embarque_real, data_embarque_informada, data_embarque_calculada) data_embarque,',
'                coalesce(data_desembarque_real, data_desembarque_informada, data_desembarque_calculada) data_desembarque',
'            from imp_pedidoimportacao_pagamento a',
'            join imp_entrega b on b.id = a.id_entrega',
'            join imp_pedidoimportacao c on c.id = b.id_pedidoimportacao',
'            join ng_condicaopagamento d on d.id = c.id_condicaopagamento',
'            join ng_condicaopagamento_parcela e on e.id_condicaopagamento = d.id and e.numero_parcela = a.numero_parcela',
'            where a.id_entrega = p_id_entrega',
'            --and a.ind_status_pagamento = 1',
'            and ind_evento_gerador_pagamento <> 1',
'        ) loop            ',
'            if parcela_entrega.ind_evento_gerador_pagamento = 2 and parcela_entrega.id_invoice is not null then',
'                select data_invoice into l_data_vencimento_prevista from imp_invoice where id = parcela_entrega.id_invoice;',
'                if l_data_vencimento_prevista is not null then',
'                    l_data_vencimento_prevista := l_data_vencimento_prevista + nvl(parcela_entrega.qtd_dias_evento, 0);',
'                end if;',
'            elsif parcela_entrega.ind_evento_gerador_pagamento = 5 and parcela_entrega.data_disponivel is not null then',
'                l_data_vencimento_prevista := parcela_entrega.data_disponivel + nvl(parcela_entrega.qtd_dias_evento, 0);',
'            elsif parcela_entrega.ind_evento_gerador_pagamento = 6 and parcela_entrega.data_embarque is not null then',
'                l_data_vencimento_prevista := parcela_entrega.data_embarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'            elsif parcela_entrega.ind_evento_gerador_pagamento = 7 and parcela_entrega.data_desembarque is not null then',
'                l_data_vencimento_prevista := parcela_entrega.data_desembarque + nvl(parcela_entrega.qtd_dias_evento, 0);',
'            else',
'                l_data_vencimento_prevista := null;',
'            end if;',
'',
'            bo_imp_pedidoimportacao_pagamento.altera_valor_e_data_vencimento_prevista(',
'                p_valor => parcela_entrega.valor,',
'                p_data_vencimento_prevista => l_data_vencimento_prevista,',
'                p_id => parcela_entrega.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'',
'            bo_imp_pedidoimportacao_pagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => 1,',
'                p_data_vencimento_real => null,',
'                p_id => parcela_entrega.id,',
'                p_pagina => v_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end altera_registros_pedidoimportacao_pagamento;',
'    --',
'    procedure altera_registro_pagamentos_titulos(  ',
'        p_id_pais_origem in imp_entrega_item.id_pais_origem%type,',
'        p_valor_total_desconto_invoice_item in imp_entrega_item.valor_total_desconto_invoice_item%type,',
'        p_id_fabricante in imp_entrega_item.id_fabricante%type,',
'        p_id_tenant in imp_entrega_item.id_tenant%type,',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_id_pedidoimportacao_item in imp_entrega_item.id_pedidoimportacao_item%type,',
'        p_id_item in imp_entrega_item.id_item%type,',
'        p_id_ncm in imp_entrega_item.id_ncm%type,',
'        p_id_unidademedida in imp_entrega_item.id_unidademedida%type,',
'        p_quantidade in imp_entrega_item.quantidade%type,',
'        p_peso_unitario in imp_entrega_item.peso_unitario%type,',
'        p_peso_liquido_total in imp_entrega_item.peso_liquido_total%type,',
'        p_valor_unitario in imp_entrega_item.valor_unitario%type,',
'        p_valor_desconto_unitario in imp_entrega_item.valor_desconto_unitario%type,',
'        p_valor_total_condicao_venda in imp_entrega_item.valor_total_condicao_venda%type,',
'        p_id_naturezaoperacao in imp_entrega_item.id_naturezaoperacao%type,',
'        p_ind_licenca_importacao in imp_entrega_item.ind_licenca_importacao%type,',
'        p_ind_bloqueio_embarque_ate_deferimento_li in imp_entrega_item.ind_bloqueio_embarque_ate_deferimento_li%type,',
'        p_quantidade_faturada in imp_entrega_item.quantidade_faturada%type,',
'        p_quantidade_saldo in imp_entrega_item.quantidade_saldo%type,',
'        p_peso_bruto_unitario in imp_entrega_item.peso_bruto_unitario%type,',
'        p_peso_bruto_total in imp_entrega_item.peso_bruto_total%type,',
'        p_valor_despesaproforma in imp_entrega_item.valor_despesaproforma%type,',
'        p_valor_despesaproforma_unitario in imp_entrega_item.valor_despesaproforma_unitario%type,',
'        p_valor_desconto_pedido_item_unitario in imp_entrega_item.valor_desconto_pedido_item_unitario%type, ',
'        p_ind_tratamento_saldo in imp_entrega_item.ind_tratamento_saldo%type,',
'        p_id in imp_entrega_item.id%type, ',
'        p_data_alteracao in imp_entrega_item.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_registro_pagamentos_titulos'';   ',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.id_pais_origem := p_id_pais_origem;',
'        v_new.valor_total_desconto_invoice_item := p_valor_total_desconto_invoice_item;',
'        v_new.id_fabricante := p_id_fabricante;',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_entrega := p_id_entrega;',
'        v_new.id_pedidoimportacao_item := p_id_pedidoimportacao_item;',
'        v_new.id_item := p_id_item;',
'        v_new.id_ncm := p_id_ncm;',
'        v_new.id_unidademedida := p_id_unidademedida;',
'        v_new.quantidade := p_quantidade;',
'        v_new.peso_unitario := p_peso_unitario;',
'        v_new.peso_liquido_total := p_peso_liquido_total;',
'        v_new.valor_unitario := p_valor_unitario;',
'        v_new.valor_desconto_unitario := p_valor_desconto_unitario;',
'        v_new.valor_total_condicao_venda := p_valor_total_condicao_venda;',
'        v_new.id_naturezaoperacao := p_id_naturezaoperacao;',
'        v_new.ind_licenca_importacao := p_ind_licenca_importacao;',
'        v_new.ind_bloqueio_embarque_ate_deferimento_li := p_ind_bloqueio_embarque_ate_deferimento_li;',
'        v_new.quantidade_faturada := p_quantidade_faturada;',
'        v_new.quantidade_saldo := p_quantidade_saldo;',
'        v_new.peso_bruto_unitario := p_peso_bruto_unitario;',
'        v_new.peso_bruto_total := p_peso_bruto_total;',
'        v_new.valor_despesaproforma := p_valor_despesaproforma;',
'        v_new.valor_despesaproforma_unitario := p_valor_despesaproforma_unitario;',
'        v_new.valor_desconto_pedido_item_unitario := p_valor_desconto_pedido_item_unitario; ',
'        v_new.ind_tratamento_saldo := p_ind_tratamento_saldo;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_REGISTRO_PAGAMENTOS_TITULOS'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_registro_pagamentos_titulos;',
'    --',
'    procedure verifica_vinculo_invoice(',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_existe_vinculo_invoice number;',
'    begin',
'        select count(1) into l_existe_vinculo_invoice from imp_entrega where id = p_id_entrega and id_invoice is not null;',
'',
'        if l_existe_vinculo_invoice > 0 then',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''142'',',
'                p_nome_campo => ''num_entrega'',',
'                p_parametro => v_parametro,',
'                p_pagina => p_pagina,',
'                p_objeto_mensagem => v_message',
'            );    ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;',
'    end verifica_vinculo_invoice;',
'    --',
'    procedure altera_ind_tratamento_saldo(  ',
'        p_ind_tratamento_saldo in imp_entrega_item.ind_tratamento_saldo%type,',
'        p_id in imp_entrega_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_ind_tratamento_saldo'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.ind_tratamento_saldo := p_ind_tratamento_saldo;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_IND_TRATAMENTO_SALDO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_ind_tratamento_saldo;',
'    --',
'    procedure gerencia_ind_tratamento_saldo(',
'        p_json_entrega_item in clob,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_json clob;',
'    begin        ',
'        l_json := p_json_entrega_item;',
'        for item in (',
'            select json_item.id, json_item.ind_tratamento_saldo',
'              from json_table(l_json, ''$[*]''',
'                columns',
'                    id varchar2(50) path ''$.id'',',
'                    ind_tratamento_saldo varchar2(50) path ''$.ind_tratamento_saldo''',
'              ) json_item',
'        ) loop',
'            altera_ind_tratamento_saldo(',
'                p_ind_tratamento_saldo => item.ind_tratamento_saldo,',
'                p_id => item.id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end gerencia_ind_tratamento_saldo;',
'    --',
'    procedure altera_registro_ind_tratamento_saldo(',
'        p_id in imp_entrega_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_registro_ind_tratamento_saldo'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_entrega_item where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.quantidade := (v_old.quantidade - v_old.quantidade_saldo);',
'        v_new.peso_liquido_total := (v_new.quantidade * v_new.peso_unitario);',
'        v_new.peso_bruto_total := (v_new.quantidade * v_new.peso_bruto_unitario);',
'        v_new.quantidade_saldo := 0;',
'        v_new.ind_tratamento_saldo := null;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_registro_ind_tratamento_saldo;',
'    --',
'    function retorna_id(',
'        p_id_entrega in imp_entrega_item.id_entrega%type,',
'        p_id_pedidoimportacao_item in imp_entrega_item.id_pedidoimportacao_item%type',
'    ) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from imp_entrega_item where id_entrega = p_id_entrega and id_pedidoimportacao_item = p_id_pedidoimportacao_item fetch first 1 row only;',
'        return l_id;',
'    end retorna_id;',
'    --',
'    procedure altera_quantidade_bo_imp_processoimportacao_item(',
'        p_diferenca in number,',
'        p_id in imp_entrega_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_quantidade_bo_imp_processoimportacao_item'';',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.quantidade := nvl(v_old.quantidade,0) - nvl(p_diferenca,0);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_QUANTIDADE_BO_IMP_PROCESSOIMPORTACAO_ITEM'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);           ',
'    end altera_quantidade_bo_imp_processoimportacao_item;',
'    --',
'    procedure altera_rateios(',
'        p_valor_despesaproforma_unitario in imp_entrega_item.valor_despesaproforma_unitario%type,',
'        p_valor_desconto_pedido_item_unitario in imp_entrega_item.valor_desconto_pedido_item_unitario%type,',
'        p_id in imp_entrega_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_entrega_item.altera_rateios'';',
'',
'        select * into v_old from imp_entrega_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_despesaproforma_unitario := p_valor_despesaproforma_unitario;',
'        v_new.valor_despesaproforma := (v_new.quantidade * nvl(v_new.valor_despesaproforma_unitario,0));',
'        v_new.valor_desconto_pedido_item_unitario := p_valor_desconto_pedido_item_unitario;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;  ',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_REGISTRO_IND_TRATAMENTO_SALDO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);           ',
'    end altera_rateios;',
'    --',
'    procedure tratamento_saldo_vincular(',
'        p_ids in varchar2,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_ids_entrega_item apex_t_varchar2 := null;',
'        l_id_entrega_atual number;',
'        l_id_entrega_nova number;        ',
'        l_old_entrega_item imp_entrega_item%rowtype;        ',
'        l_id number;',
'        l_verifica_entrega_ja_possui_o_item number;',
'        l_entrega_item imp_entrega_item%rowtype;',
'        l_entrega_atual imp_entrega%rowtype;',
'        l_id_entrega number;',
'        l_id_entrega_item_saldo_tratato number;',
'        l_id_pedidoimportacao_item number;',
'    begin',
'        v_operacao := ''TRATAMENTO_SALDO_VINCULAR'';',
'        l_ids_entrega_item := apex_string.split(p_ids, '','');',
'        ',
'        select id_entrega into l_id_entrega_atual from imp_entrega_item where id = l_ids_entrega_item(1);',
'        l_id_entrega_nova := bo_imp_entrega.proxima_entrega_elegivel(l_id_entrega_atual);',
'',
'        if l_id_entrega_nova != 0 then',
'            for i in 1..l_ids_entrega_item.count loop',
'                select * into l_old_entrega_item from imp_entrega_item where id = l_ids_entrega_item(i);',
'',
unistr('                -- Verifica se a entrega selecionada para vincular os itens, j\00E1 possui algum dos itens selecionados:'),
'                select count(1) ',
'                into l_verifica_entrega_ja_possui_o_item ',
'                from imp_entrega_item ',
'                where id_entrega = l_id_entrega_nova',
'                and id_pedidoimportacao_item = l_old_entrega_item.id_pedidoimportacao_item;',
'',
unistr('                -- Se n\00E3o possui, ent\00E3o deve apenas inseri-los:'),
'                if l_verifica_entrega_ja_possui_o_item = 0 then',
'                    inclui_registro(',
'                        p_id_tenant => l_old_entrega_item.id_tenant,',
'                        p_id_entrega => l_id_entrega_nova,',
'                        p_id_pedidoimportacao_item => l_old_entrega_item.id_pedidoimportacao_item,',
'                        p_id_item => l_old_entrega_item.id_item,',
'                        p_id_ncm => l_old_entrega_item.id_ncm,',
'                        p_id_unidademedida => l_old_entrega_item.id_unidademedida,',
'                        p_quantidade => l_old_entrega_item.quantidade_saldo,',
'                        p_quantidade_faturada => 0,',
'                        p_quantidade_saldo => l_old_entrega_item.quantidade_saldo,',
'                        p_peso_unitario => l_old_entrega_item.peso_unitario,',
'                        p_peso_liquido_total => (l_old_entrega_item.quantidade_saldo * l_old_entrega_item.peso_unitario),',
'                        p_peso_bruto_unitario => l_old_entrega_item.peso_bruto_unitario,',
'                        p_peso_bruto_total => (l_old_entrega_item.quantidade_saldo * l_old_entrega_item.peso_bruto_unitario),',
'                        p_valor_unitario => l_old_entrega_item.valor_unitario,',
'                        p_valor_desconto_unitario => l_old_entrega_item.valor_desconto_unitario,',
'                        p_valor_desconto_pedido_item_unitario => l_old_entrega_item.valor_desconto_pedido_item_unitario,',
'                        p_valor_despesaproforma => (l_old_entrega_item.quantidade_saldo * l_old_entrega_item.valor_despesaproforma_unitario),',
'                        p_valor_despesaproforma_unitario => l_old_entrega_item.valor_despesaproforma_unitario,',
'                        p_valor_total_condicao_venda => (l_old_entrega_item.quantidade_saldo * ((l_old_entrega_item.valor_unitario - l_old_entrega_item.valor_desconto_unitario) - l_old_entrega_item.valor_desconto_pedido_item_unitario)) + (l_old_entre'
||'ga_item.quantidade_saldo * l_old_entrega_item.valor_despesaproforma_unitario),',
'                        p_valor_total_despesa_invoice_item => l_old_entrega_item.valor_total_despesa_invoice_item,',
'                        p_valor_total_desconto_invoice_item => l_old_entrega_item.valor_total_desconto_invoice_item,',
'                        p_id_naturezaoperacao => l_old_entrega_item.id_naturezaoperacao,',
'                        p_id_fabricante => l_old_entrega_item.id_fabricante,',
'                        p_id_pais_origem => l_old_entrega_item.id_pais_origem,',
'                        p_ind_licenca_importacao => l_old_entrega_item.ind_licenca_importacao,',
'                        p_ind_bloqueio_embarque_ate_deferimento_li => l_old_entrega_item.ind_bloqueio_embarque_ate_deferimento_li,',
'                        p_ind_tratamento_saldo => null,',
'                        p_id => l_id,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'',
unistr('                -- Se j\00E1 possui ent\00E3o deve apenas atualizar a quantidade e n\00E3o duplicar o item na entrega:'),
'                else',
'                    select * into l_entrega_item ',
'                    from imp_entrega_item ',
'                    where id_entrega = l_id_entrega_nova',
'                    and id_pedidoimportacao_item = l_old_entrega_item.id_pedidoimportacao_item',
'                    order by id desc',
'                    fetch first 1 row only;',
'',
'                    --altera_registro(',
'                    altera_registro_pagamentos_titulos(',
'                        p_id_tenant => l_entrega_item.id_tenant,',
'                        p_id_entrega => l_entrega_item.id_entrega,',
'                        p_id_pedidoimportacao_item => l_entrega_item.id_pedidoimportacao_item,',
'                        p_id_item => l_entrega_item.id_item,',
'                        p_id_ncm => l_entrega_item.id_ncm,',
''))
);
