unistr('            p_ds_mensagem => ''Fim da inclus\00E3o de registro'''),
'        );',
'    end inclui_registro; ',
'    --',
'    procedure altera_registro(  ',
'        p_id_tenant in imp_invoice_divergencia.id_tenant%type,',
'        p_id_invoice in imp_invoice_divergencia.id_invoice%type,',
'        p_id_invoice_item in imp_invoice_divergencia.id_invoice_item%type,',
'        p_ind_divergencia in imp_invoice_divergencia.ind_divergencia%type,',
'        p_conteudo_invoice in imp_invoice_divergencia.conteudo_invoice%type,',
'        p_conteudo_pedido in imp_invoice_divergencia.conteudo_pedido%type,',
'        p_ind_status in imp_invoice_divergencia.ind_status%type,',
'        p_observacao in imp_invoice_divergencia.observacao%type, ',
'        p_id in imp_invoice_divergencia.id%type, ',
'        p_data_alteracao in imp_invoice_divergencia.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_divergencia'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        v_messages := pkg_mensagem.message_record_table();',
