 p_id=>wwv_flow_imp.id(154768047993576434)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in imp_invoice_divergencia.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice_divergencia where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in imp_invoice_divergencia.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice_divergencia where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in imp_invoice_divergencia.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_invoice_divergencia'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''imp_invoice_divergencia'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in imp_invoice_divergencia.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_invoice */ '),
'        valida_id_invoice(v_new.id_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_invoice_item */ '),
'        valida_id_invoice_item(v_new.id_invoice_item);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_divergencia */ '),
'        valida_ind_divergencia(v_new.ind_divergencia);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo conteudo_invoice */ '),
'        valida_conteudo_invoice(v_new.conteudo_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo conteudo_pedido */ '),
'        valida_conteudo_pedido(v_new.conteudo_pedido);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_status */ '),
'        valida_ind_status(v_new.ind_status);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo observacao */ '),
'        valida_observacao(v_new.observacao);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in imp_invoice_divergencia.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_id_invoice(p_id_invoice in imp_invoice_divergencia.id_invoice%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_invoice is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.id_invoice''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
