'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_invoice(p_id_invoice);',
'    end valida_id_invoice;     ',
'',
'    procedure valida_id_invoice_item(p_id_invoice_item in imp_invoice_divergencia.id_invoice_item%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_invoice_item is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.id_invoice_item''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_invoice_item(p_id_invoice_item);',
'    end valida_id_invoice_item;    ',
'',
'    procedure valida_ind_divergencia(p_ind_divergencia in imp_invoice_divergencia.ind_divergencia%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ind_divergencia is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.ind_divergencia''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ind_divergencia'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from imp_invoice_divergencia where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_invoice)) = lower(trim(v_new.id_invoice)) and lower(trim(id_invoice_item)) = lower(trim'
||'(v_new.id_invoice_item)) and lower(trim(ind_divergencia)) = lower(trim(v_new.ind_divergencia)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from imp_invoice_divergencia where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_invoice)) = lower(trim(v_new.id_invoice)) and lower(trim(id_invoice_item)) = lower(trim'
||'(v_new.id_invoice_item)) and lower(trim(ind_divergencia)) = lower(trim(v_new.ind_divergencia)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.ind_divergencia'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''ind_divergencia'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_ind_divergencia(p_ind_divergencia);',
'    end valida_ind_divergencia;     ',
'',
'    procedure valida_conteudo_invoice(p_conteudo_invoice in imp_invoice_divergencia.conteudo_invoice%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_conteudo_invoice is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.conteudo_invoice''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''conteudo_invoice'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_conteudo_invoice(p_conteudo_invoice);',
'    end valida_conteudo_invoice;     ',
