unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_divergencia'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_divergencia'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_divergencia'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_divergencia'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_divergencia'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_divergencia'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_invoice_divergencia%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_invoice'', p_rec.id_invoice, true);',
'        apex_json.write(''id_invoice_item'', p_rec.id_invoice_item, true);',
'        apex_json.write(''ind_divergencia'', p_rec.ind_divergencia, true);',
'        apex_json.write(''conteudo_invoice'', p_rec.conteudo_invoice, true);',
'        apex_json.write(''conteudo_pedido'', p_rec.conteudo_pedido, true);',
'        apex_json.write(''ind_status'', p_rec.ind_status, true);',
'        apex_json.write(''observacao'', p_rec.observacao, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.observacao,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'        v_new.id := null;',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.observacao,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'        ',
unistr('        -- Rejeita invoice ao rejeitar diverg\00EAncia:'),
'        if v_new.ind_status = 3 then',
'            bo_imp_invoice.altera_ind_status(5, v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure aprova_divergencia(',
'        p_id in imp_invoice_divergencia.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entrega_item number;',
'        l_old_ind_status number := v_old.ind_status;',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice_divergencia.aprova_divergencia'';',
'',
'        select * into v_old from imp_invoice_divergencia where id = p_id;        ',
'        v_new := v_old;',
'        ',
unistr('        -- Aprova diverg\00EAncias na entrega/pedido (Exportador)'),
'        if v_new.ind_divergencia = 1 and v_new.ind_status = 2 then',
'            for entrega in (',
'                select ',
'                    id_entrega',
'                from imp_invoice a',
'                join imp_invoice_item b on b.id_invoice = a.id',
'                join imp_entrega c on c.id = b.id_entrega',
'                where a.id = v_new.id_invoice and c.id_exportador = v_new.conteudo_pedido',
'            ) loop',
'                bo_imp_entrega.altera_divergencias(',
'                    p_id_exportador => v_new.conteudo_invoice,',
'                    p_id => entrega.id_entrega,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        elsif v_new.ind_divergencia = 2 and v_new.ind_status = 2 then',
'            for entrega in (',
'                select ',
'                    id_entrega',
'                from imp_invoice a',
'                join imp_invoice_item b on b.id_invoice = a.id',
'                join imp_entrega c on c.id = b.id_entrega',
'                where a.id = v_new.id_invoice and c.id_importador = v_new.conteudo_pedido',
'            ) loop',
'                bo_imp_entrega.altera_divergencias(',
'                    p_id_importador => v_new.conteudo_invoice,',
'                    p_id => entrega.id_entrega,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        elsif v_new.ind_divergencia = 3 and v_new.ind_status = 2 then',
'            for entrega in (',
'                select ',
'                    id_entrega',
'                from imp_invoice a',
'                join imp_invoice_item b on b.id_invoice = a.id',
'                join imp_entrega c on c.id = b.id_entrega',
'                where a.id = v_new.id_invoice and c.id_adquirente = v_new.conteudo_pedido',
'            ) loop',
'                bo_imp_entrega.altera_divergencias(',
'                    p_id_adquirente => v_new.conteudo_invoice,',
'                    p_id => entrega.id_entrega,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
unistr('        -- Diverg\00EAncia entre condi\00E7\00E3o de pagamento no pedido e na invoice:'),
'        elsif v_new.ind_divergencia = 4 then',
unistr('            -- De "Em An\00E1lise" para "Aprovada", ou de "Aprovada" para "Em An\00E1lise":'),
'            if (l_old_ind_status = 1 and v_new.ind_status = 2) or',
'               (l_old_ind_status = 2 and v_new.ind_status = 1) then',
unistr('               -- N\00E3o altera no pedido:'),
'                null;',
unistr('            -- De "Em An\00E1lise" ou "Aprovada" para "Rejeitada":'),
'            elsif (l_old_ind_status in (1,2) and v_new.ind_status = 3) then',
'                bo_imp_invoice.altera_id_condicaopagamento(',
'                    p_id_condicaopagamento => v_new.conteudo_pedido,',
'                    p_id => v_new.id_invoice,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
unistr('            -- De "Rejeitada" para "Em An\00E1lise" ou "Aprovada":'),
'            elsif (l_old_ind_status = 3 and v_new.ind_status in (1,2)) then',
'                bo_imp_invoice.altera_id_condicaopagamento(',
'                    p_id_condicaopagamento => v_new.conteudo_invoice,',
'                    p_id => v_new.id_invoice,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end if;',
'        elsif v_new.ind_divergencia = 5 and v_new.ind_status = 2 then',
'            for entrega in (',
'                select ',
'                    id_entrega',
'                from imp_invoice a',
'                join imp_invoice_item b on b.id_invoice = a.id',
'                join imp_entrega c on c.id = b.id_entrega',
'                where a.id = v_new.id_invoice and c.id_incoterm = v_new.conteudo_pedido',
'            ) loop',
'                bo_imp_entrega.altera_divergencias(',
'                    p_id_incoterm => v_new.conteudo_invoice,',
'                    p_id => entrega.id_entrega,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        elsif v_new.ind_divergencia = 6 and v_new.ind_status = 2 then',
'            for processoimportacao_item in (',
'                select a.id',
'                from imp_processoimportacao_item a',
'                join imp_entrega_item b on b.id = a.id_entrega_item',
'                join imp_entrega c on c.id = b.id_entrega',
'                join imp_invoice d on d.id = c.id_invoice',
'                where d.id = v_new.id_invoice',
'            ) loop',
'                bo_imp_processoimportacao_item.altera_id_moeda(',
'                    p_id_moeda => v_new.conteudo_invoice,',
'                    p_id => processoimportacao_item.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
unistr('        -- Aprova diverg\00EAncias no item (Quantidade)'),
'        elsif v_new.ind_divergencia = 7 and v_new.id_invoice_item is not null then',
'            if l_old_ind_status = 1 then',
'                if v_new.ind_status = 2 then',
unistr('                    -- De "Em an\00E1lise" para "Aprovada":'),
'                    select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item where a.id = v_new.id_invoice_item;',
'                    bo_imp_entrega_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_invoice - v_new.conteudo_pedido),',
'                        p_id => l_id_entrega_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                elsif v_new.ind_status = 3 then',
unistr('                    -- De "Em an\00E1lise" para "Rejeitada":'),
'                        bo_imp_invoice_item.altera_divergencias(',
'                            p_quantidade => (v_new.conteudo_pedido - v_new.conteudo_invoice),',
'                            p_id => v_new.id_invoice_item,',
'                            p_pagina => p_pagina,',
'                            p_encadeado => p_encadeado,',
'                            p_sucesso => p_sucesso,',
'                            p_messages => p_messages',
'                        );',
'                end if;',
'            elsif l_old_ind_status = 2 then',
'                if v_new.ind_status = 1 then',
unistr('                -- De "Aprovada" para "Em an\00E1lise":'),
'                    select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item where a.id = v_new.id_invoice_item;',
'                    bo_imp_entrega_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_pedido - v_new.conteudo_invoice),',
'                        p_id => l_id_entrega_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                elsif v_new.ind_status = 3 then',
'                -- De "Aprovada" para "Rejeitada":',
'                    select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item where a.id = v_new.id_invoice_item;',
'                    bo_imp_entrega_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_pedido - v_new.conteudo_invoice),',
'                        p_id => l_id_entrega_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                    bo_imp_invoice_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_pedido - v_new.conteudo_invoice),',
'                        p_id => v_new.id_invoice_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            elsif l_old_ind_status = 3 then',
'                if v_new.ind_status = 1 then',
unistr('                -- De "Rejeitada" para "Em an\00E1lise":'),
'                    bo_imp_invoice_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_invoice - v_new.conteudo_pedido),',
'                        p_id => v_new.id_invoice_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                elsif v_new.ind_status = 2 then',
'                -- De "Rejeitada" para "Aprovada":',
'                    bo_imp_invoice_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_invoice - v_new.conteudo_pedido),',
'                        p_id => v_new.id_invoice_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                    select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item where a.id = v_new.id_invoice_item;',
'                    bo_imp_entrega_item.altera_divergencias(',
'                        p_quantidade => (v_new.conteudo_invoice - v_new.conteudo_pedido),',
'                        p_id => l_id_entrega_item,',
'                        p_pagina => p_pagina,',
'                        p_encadeado => p_encadeado,',
'                        p_sucesso => p_sucesso,',
'                        p_messages => p_messages',
'                    );',
'                end if;',
'            end if;',
'        elsif v_new.ind_divergencia = 8 and v_new.ind_status = 2 and v_new.id_invoice_item is not null then',
'            select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item /*b.id_entrega = a.id_entrega and b.id_pedidoimportacao_item = a.id_pedidoimportacao_item*/ where a.id = v_new.id_invoice_item;',
'            bo_imp_entrega_item.altera_divergencias(',
'                p_id_unidademedida => v_new.conteudo_invoice,',
'                p_id => l_id_entrega_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        elsif v_new.ind_divergencia = 9 and v_new.ind_status = 2 and v_new.id_invoice_item is not null then',
'            select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item /*b.id_entrega = a.id_entrega and b.id_pedidoimportacao_item = a.id_pedidoimportacao_item*/ where a.id = v_new.id_invoice_item;',
'            bo_imp_entrega_item.altera_divergencias(',
'                p_id_ncm => v_new.conteudo_invoice,',
'                p_id => l_id_entrega_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154768047993576434)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' => p_messages',
'            );',
'        elsif v_new.ind_divergencia = 10 and v_new.ind_status = 2 and v_new.id_invoice_item is not null then',
'            select b.id into l_id_entrega_item from imp_invoice_item a join imp_entrega_item b on b.id = a.id_entrega_item /*b.id_entrega = a.id_entrega and b.id_pedidoimportacao_item = a.id_pedidoimportacao_item*/ where a.id = v_new.id_invoice_item;',
'            bo_imp_entrega_item.altera_divergencias(',
'                p_valor_unitario => v_new.conteudo_invoice,',
'                p_id => l_id_entrega_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );            ',
'        end if;',
'    end aprova_divergencia;',
'    --',
'    procedure altera_ind_status(        ',
'        p_ind_status in imp_invoice_divergencia.ind_status%type,',
'        p_id in imp_invoice_divergencia.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice_divergencia.altera_ind_status'';   ',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_invoice_divergencia where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.ind_status := p_ind_status;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);    ',
'    end altera_ind_status;',
'    --',
'    function descricao_divergencia(',
'        p_id in imp_invoice_divergencia.id%type,',
'        p_conteudo in varchar2 default null ',
'    ) return varchar2 is',
'        l_ind_divergencia number;',
'        l_descricao_divergencia varchar2(4000);',
'    begin',
'        if p_conteudo is null then',
'            select',
'                case',
'                    when ind_divergencia in (1,2,3) and conteudo_pedido <> -1 then',
'                        bo_ng_pessoa.retorna_pessoa(a.conteudo_invoice)                        ',
'                    when ind_divergencia = 4 then',
'                        pkg_traducao.get_traducao((select descricao_condicaopagamento from ng_condicaopagamento where id = conteudo_invoice))',
'                    when ind_divergencia = 5 then',
'                        (select codigo_incoterm from ng_incoterm where id = conteudo_invoice)',
'                    when ind_divergencia = 6 then',
'                        (select codigo_moeda||'' - ''||simbolo_iso from ng_moeda where id = conteudo_invoice)',
'                    when ind_divergencia = 7 and ind_tipo_dado = ''D'' then',
'                        to_char(replace(a.conteudo_invoice, ''.'', '',''),''FM999G999G990D00000'')',
'                    when ind_divergencia = 8 then',
'                        (select codigo_unidademedida from ng_unidademedida where id = conteudo_invoice)',
'                    when ind_divergencia = 9 then',
'                        (select codigo_ncm from ng_ncm where id = conteudo_invoice)',
'                    when ind_divergencia = 10 then                            ',
'                        to_char(replace(a.conteudo_invoice, ''.'', '',''),''FM999G999G990D00000'')',
'                    else',
'                        a.conteudo_invoice',
'                end ',
'            into l_descricao_divergencia',
'            from imp_invoice_divergencia a',
'            left join imp_invoice_item b on b.id = a.id_invoice_item',
'            left join ng_unidademedida c on c.id = b.id_unidademedida',
'            where a.id = p_id;',
'        else            ',
'            select',
'                case',
'                    when ind_divergencia in (1,2,3) and conteudo_pedido <> -1 then',
'                        bo_ng_pessoa.retorna_pessoa(a.conteudo_pedido)        ',
'                    when ind_divergencia = 4 then',
'                        pkg_traducao.get_traducao((select descricao_condicaopagamento from ng_condicaopagamento where id = conteudo_pedido))',
'                    when ind_divergencia = 5 then',
'                        (select codigo_incoterm from ng_incoterm where id = conteudo_pedido)',
'                    when ind_divergencia = 6 then',
'                        (select codigo_moeda||'' - ''||simbolo_iso from ng_moeda where id = conteudo_pedido)',
'                    when ind_divergencia = 7 and ind_tipo_dado = ''D'' then',
'                        to_char(replace(a.conteudo_pedido, ''.'', '',''),''FM999G999G990D00000'')',
'                    when ind_divergencia = 8 then',
'                        (select codigo_unidademedida from ng_unidademedida where id = conteudo_pedido)',
'                    when ind_divergencia = 9 then',
'                        (select codigo_ncm from ng_ncm where id = conteudo_pedido)',
'                    when ind_divergencia = 10 then',
'                        to_char(replace(a.conteudo_pedido, ''.'', '',''),''FM999G999G990D00000'')',
'                    else',
'                        a.conteudo_pedido',
'                end',
'            into l_descricao_divergencia',
'            from imp_invoice_divergencia a',
'            left join imp_invoice_item b on b.id = a.id_invoice_item',
'            left join ng_unidademedida c on c.id = b.id_unidademedida',
'            where a.id = p_id;',
'        end if;',
'',
'        return l_descricao_divergencia;',
'    end descricao_divergencia;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_invoice_divergencia;',
'/'))
);
end;
/
