'    end;',
'    --',
'    function calcula_rateio(',
'        p_valor           in imp_invoice_despesa.valor%type,',
'        p_id_invoice_item in imp_invoice_item_despesa.id_invoice_item%type,',
'        p_id_despesa      in imp_invoice_despesa.id_despesa%type',
'    ) return number is',
'        l_id_invoice               number;',
'        l_peso_unitario            number;',
'        l_quantidade               number;',
'        l_invoice_item_valor_total number;',
'        l_peso_liquido_total       number;',
'        l_quantidade_total         number;',
'        l_valor_total_mercadoria   number;',
'        l_ind_forma_rateio         number;',
'        l_resultado                number;',
'        l_base_cent                number;',
'        l_soma_base_cent           number;',
'        l_total_cent               number;',
'        l_resto                    number;',
'        l_item_ajuste              number;',
'    begin',
'        -- Dados do item',
'        select id_invoice,',
'               peso_liquido_total,',
'               quantidade,',
'               valor_total_mercadoria',
'          into l_id_invoice,',
'               l_peso_unitario,',
'               l_quantidade,',
'               l_invoice_item_valor_total',
'          from imp_invoice_item',
'         where id = p_id_invoice_item;',
'',
'        -- Forma de rateio',
'        select ind_forma_rateio',
'          into l_ind_forma_rateio',
'          from ng_despesa',
'         where id = p_id_despesa;',
'',
unistr('        -- C\00E1lculo proporcional:'),
'        if l_ind_forma_rateio = 1 then',
'            -- Por peso',
'            select sum(peso_liquido_total)',
'            into l_peso_liquido_total',
'            from imp_invoice_item',
'            where id_invoice = l_id_invoice;',
'',
'            l_resultado := (p_valor * l_peso_unitario) / l_peso_liquido_total;',
'',
'        elsif l_ind_forma_rateio = 2 then',
'            -- Por quantidade',
'            select sum(quantidade)',
'            into l_quantidade_total',
'            from imp_invoice_item',
'            where id_invoice = l_id_invoice;',
'',
'            l_resultado := (p_valor * l_quantidade) / l_quantidade_total;',
'',
'        elsif l_ind_forma_rateio = 3 then',
'            -- Por valor',
'            select valor_total_mercadoria',
'            into l_valor_total_mercadoria',
'            from imp_invoice',
'            where id = l_id_invoice;',
'',
'            l_resultado := (p_valor * l_invoice_item_valor_total) / l_valor_total_mercadoria;',
'',
'        else',
'            return 0;',
'        end if;',
'',
'        -- Ajuste de arredondamento:',
'        l_base_cent  := trunc(l_resultado * 100);',
'        l_total_cent := trunc(p_valor * 100);',
'',
'        -- Soma dos itens truncados:',
'        select ',
'            sum(',
'               trunc(',
'                   case',
'                       when l_ind_forma_rateio = 1 then',
'                           (p_valor * peso_liquido_total) / l_peso_liquido_total',
'                       when l_ind_forma_rateio = 2 then',
'                           (p_valor * quantidade) / l_quantidade_total',
'                       when l_ind_forma_rateio = 3 then',
'                           (p_valor * valor_total_mercadoria) /',
'                           (select valor_total_mercadoria from imp_invoice where id = l_id_invoice)',
'                   end * 100',
'               )',
'           )',
'        into l_soma_base_cent',
'        from imp_invoice_item',
'        where id_invoice = l_id_invoice;',
'',
'        l_resto := l_total_cent - l_soma_base_cent;',
'',
'        -- Item de ajuste (menor ID):',
'        select min(id)',
'        into l_item_ajuste',
'        from imp_invoice_item',
'        where id_invoice = l_id_invoice;',
'',
'        if p_id_invoice_item = l_item_ajuste then',
'            l_base_cent := l_base_cent + l_resto;',
'        end if;',
'',
'        return l_base_cent / 100;',
'    end calcula_rateio;',
'    --',
'    function calcula_rateio_unitario(',
'        p_valor in imp_invoice_despesa.valor%type,',
'        p_id_invoice_item in imp_invoice_item_despesa.id_invoice_item%type,',
'        p_id_despesa in imp_invoice_despesa.id_despesa%type',
'    ) return number is',
'        l_quantidade number;',
'        l_resultado number;',
'    begin',
'        select quantidade into l_quantidade from imp_invoice_item where id = p_id_invoice_item;',
'',
'        l_resultado := (calcula_rateio(p_valor, p_id_invoice_item, p_id_despesa) / l_quantidade);',
'',
'        return trunc(l_resultado, 2);',
'    end calcula_rateio_unitario;',
'    --',
'    procedure altera_invoice_item_valor_despesa_invoice_item(',
'        p_id_invoice_item in imp_invoice_item_despesa.id_invoice_item%type,        ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_existe_invoice_item_despesa number;',
'    begin                ',
'        select count(1) into l_existe_invoice_item_despesa from imp_invoice_item_despesa where id_invoice_item = p_id_invoice_item;',
'        if l_existe_invoice_item_despesa > 0 then            ',
'            for invoice_item_despesa in (',
'                select',
'                    --nvl(sum(valor_unitario_despesa_item), 0) as total_valor_despesa_unitario',
'                    nvl(sum(valor_total_despesa_item), 0) as total_valor_despesa_unitario',
'                from imp_invoice_item_despesa',
'                where id_invoice_item = p_id_invoice_item',
'            ) loop',
'                bo_imp_invoice_item.altera_valor_total_despesa_invoice_item(',
'                    p_valor_total_despesa_invoice_item => invoice_item_despesa.total_valor_despesa_unitario,',
'                    p_id => p_id_invoice_item,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        else',
'            for invoice_item in (',
'                select id from imp_invoice_item where id = p_id_invoice_item',
'            ) loop',
'                bo_imp_invoice_item.altera_valor_total_despesa_invoice_item(',
'                    p_valor_total_despesa_invoice_item => 0,',
'                    p_id => invoice_item.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'    end altera_invoice_item_valor_despesa_invoice_item;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_invoice_item_despesa;',
'/'))
);
end;
/
