'/',
'',
'create or replace package body                      bo_imp_processoimportacao_item ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_processoimportacao_item.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into imp_processoimportacao_item (  ',
'            peso_bruto_unitario,',
'            peso_bruto_total,',
'            id_pais_origem,',
'            id_exportador,',
'            id_tenant,',
'            id_processoimportacao,',
'            id_entrega_item,',
'            id_item,',
'            id_ncm,',
'            id_unidademedida,',
'            quantidade,',
'            peso_unitario,',
'            peso_liquido_total,',
'            id_moeda,',
'            id_incoterm,',
'            valor_unitario,',
'            valor_desconto,',
'            valor_total_condicao_venda,',
'            id_naturezaoperacao,',
'            id_fabricante,',
'            id_centrocusto,',
'            num_solicitacao_compra,',
'            nome_solicitante,',
'            data_entrega_desejada,',
'            quantidade_faturada,',
'            quantidade_saldo,',
'            ind_licenca_importacao,',
'            ind_bloqueio_embarque_ate_deferimento_li,',
'            id_entrega,',
'            valor_total_desconto_invoice_item,',
'            id_minutanotafiscal,',
'            valor_total_mercadoria,',
'            valor_total_despesa_invoice_item,',
'            valor_unitario_mercadoria_moeda_nacional,',
'            numero_ato_concessorio,',
'            cst,',
'            id_cfop,',
'            ind_finalidade,',
'            valor_total_mercadoria_moeda_nacional,',
'            cclasstrib, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.peso_bruto_unitario,',
'            v_new.peso_bruto_total,',
'            v_new.id_pais_origem,',
'            v_new.id_exportador,',
'            v_new.id_tenant,',
'            v_new.id_processoimportacao,',
'            v_new.id_entrega_item,',
'            v_new.id_item,',
'            v_new.id_ncm,',
'            v_new.id_unidademedida,',
'            v_new.quantidade,',
'            v_new.peso_unitario,',
'            v_new.peso_liquido_total,',
'            v_new.id_moeda,',
'            v_new.id_incoterm,',
'            v_new.valor_unitario,',
'            v_new.valor_desconto,',
'            v_new.valor_total_condicao_venda,',
'            v_new.id_naturezaoperacao,',
'            v_new.id_fabricante,',
'            v_new.id_centrocusto,',
'            v_new.num_solicitacao_compra,',
'            v_new.nome_solicitante,',
'            v_new.data_entrega_desejada,',
'            v_new.quantidade_faturada,',
'            v_new.quantidade_saldo,',
'            v_new.ind_licenca_importacao,',
'            v_new.ind_bloqueio_embarque_ate_deferimento_li,',
'            v_new.id_entrega,',
'            v_new.valor_total_desconto_invoice_item,',
'            v_new.id_minutanotafiscal,',
'            v_new.valor_total_mercadoria,',
'            v_new.valor_total_despesa_invoice_item,',
'            v_new.valor_unitario_mercadoria_moeda_nacional,',
'            v_new.numero_ato_concessorio,',
'            v_new.cst,',
'            v_new.id_cfop,',
'            v_new.ind_finalidade,',
'            v_new.valor_total_mercadoria_moeda_nacional,',
'            v_new.cclasstrib, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
