'        p_numero_ato_concessorio out imp_processoimportacao_item.numero_ato_concessorio%type,',
'        p_cst out imp_processoimportacao_item.cst%type,',
'        p_id_cfop out imp_processoimportacao_item.id_cfop%type,',
'        p_ind_finalidade out imp_processoimportacao_item.ind_finalidade%type,',
'        p_valor_total_mercadoria_moeda_nacional out imp_processoimportacao_item.valor_total_mercadoria_moeda_nacional%type,',
'        p_cclasstrib out imp_processoimportacao_item.cclasstrib%type, ',
