'            peso_liquido_total,',
'            id_moeda,',
'            id_incoterm,',
'            valor_unitario,',
'            valor_desconto,',
'            valor_total_condicao_venda,',
'            id_naturezaoperacao,',
'            id_fabricante,',
'            id_centrocusto,',
'            num_solicitacao_compra,',
'            nome_solicitante,',
'            data_entrega_desejada,',
'            quantidade_faturada,',
'            quantidade_saldo,',
'            ind_licenca_importacao,',
'            ind_bloqueio_embarque_ate_deferimento_li,',
'            id_entrega,',
'            valor_total_desconto_invoice_item,',
'            id_minutanotafiscal,',
'            valor_total_mercadoria,',
'            valor_total_despesa_invoice_item,',
'            valor_unitario_mercadoria_moeda_nacional,',
'            numero_ato_concessorio,',
'            cst,',
'            id_cfop,',
'            ind_finalidade,',
'            valor_total_mercadoria_moeda_nacional,',
'            cclasstrib, ',
'            id ',
'            into ',
'            p_peso_bruto_unitario,',
'            p_peso_bruto_total,',
'            p_id_pais_origem,',
'            p_id_exportador,',
'            p_id_tenant,',
'            p_id_processoimportacao,',
'            p_id_entrega_item,',
'            p_id_item,',
'            p_id_ncm,',
'            p_id_unidademedida,',
'            p_quantidade,',
'            p_peso_unitario,',
'            p_peso_liquido_total,',
'            p_id_moeda,',
'            p_id_incoterm,',
'            p_valor_unitario,',
'            p_valor_desconto,',
'            p_valor_total_condicao_venda,',
'            p_id_naturezaoperacao,',
'            p_id_fabricante,',
'            p_id_centrocusto,',
'            p_num_solicitacao_compra,',
'            p_nome_solicitante,',
'            p_data_entrega_desejada,',
'            p_quantidade_faturada,',
'            p_quantidade_saldo,',
'            p_ind_licenca_importacao,',
'            p_ind_bloqueio_embarque_ate_deferimento_li,',
'            p_id_entrega,',
'            p_valor_total_desconto_invoice_item,',
'            p_id_minutanotafiscal,',
'            p_valor_total_mercadoria,',
'            p_valor_total_despesa_invoice_item,',
'            p_valor_unitario_mercadoria_moeda_nacional,',
'            p_numero_ato_concessorio,',
'            p_cst,',
'            p_id_cfop,',
'            p_ind_finalidade,',
'            p_valor_total_mercadoria_moeda_nacional,',
'            p_cclasstrib, ',
'            p_id ',
'        from imp_processoimportacao_item ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
