'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin',
unistr('        -- Mant\00E9m atribui\00E7\00E3o correta de valores:'),
'        atribui_valores;',
'        -- ',
'        calcula_valor_total_mercadoria;',
'        calcula_valor_total_condicao_venda;',
'',
'        -- sempre recalcula no insert',
'        v_recalcula_rateio := true;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        recalcula_despesas_item(',
'            --p_id_processoimportacao_item    => v_new.id,',
'            p_id_processoimportacao         => v_new.id_processoimportacao,',
'            --p_id_tenant                     => v_new.id_tenant,',
'            p_pagina                        => v_pagina,',
'            p_encadeado                     => p_encadeado,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'        v_recalcula_rateio := false;',
'',
'        inclui_processoimportacao_item_tributo;',
'',
'        bo_imp_processoimportacao.atualiza_ind_itens_vinculado_invoice( ',
'            p_id            => v_new.id_processoimportacao, ',
'            p_pagina        => v_pagina, ',
'            p_encadeado     => p_encadeado, ',
'            p_sucesso       => p_sucesso, ',
'            p_messages      => p_messages ',
'        );',
'',
'        bo_imp_processoimportacao.atualiza_valor_total_condicao_venda( ',
'            p_id            => v_new.id_processoimportacao, ',
'            p_pagina        => v_pagina, ',
'            p_encadeado     => p_encadeado, ',
'            p_sucesso       => p_sucesso, ',
'            p_messages      => p_messages ',
'        );',
'',
'        -- Verifica necessidade de atualizar os tributos do processo:',
'        if recalcula_processo(v_new.id) then',
'            bo_imp_processoimportacao.gerencia_tributos(v_new.id_processoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        --',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
unistr('        -- Mant\00E9m atribui\00E7\00E3o correta de valores:'),
'        atribui_valores;',
'        -- ',
'        calcula_valor_total_mercadoria;',
'        calcula_valor_total_condicao_venda;',
'',
unistr('        -- detectar mudan\00E7a para recalcular rateio:'),
'        if nvl(v_old.quantidade, -1) != nvl(v_new.quantidade, -1) ',
'        or nvl(v_old.peso_unitario, -1) != nvl(v_new.peso_unitario, -1) ',
'        or nvl(v_old.valor_unitario, -1) != nvl(v_new.valor_unitario, -1) ',
'        or nvl(v_old.valor_desconto, -1) != nvl(v_new.valor_desconto, -1)',
'        or nvl(v_old.id_ncm, -1) != nvl(v_new.id_ncm, -1)',
'        or nvl(v_old.id_naturezaoperacao, -1) != nvl(v_new.id_naturezaoperacao, -1)',
'        then',
'            v_recalcula_rateio := true;',
'        end if;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        if v_recalcula_rateio then',
'            recalcula_despesas_item(',
'                --p_id_processoimportacao_item    => v_new.id,',
'                p_id_processoimportacao         => v_new.id_processoimportacao,',
'                --p_id_tenant                     => v_new.id_tenant,',
'                p_pagina                        => v_pagina,',
'                p_encadeado                     => p_encadeado,',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'            );',
'        end if;',
'        v_recalcula_rateio := false;',
'',
'        if nvl(v_operacao,''ALTERA_REGISTRO'') <> ''ALTERA_ID_NCM'' then',
'            altera_processoimportacao_item_tributo;',
'        end if;',
'',
'        bo_imp_processoimportacao.atualiza_ind_itens_vinculado_invoice( ',
'            p_id            => v_new.id_processoimportacao, ',
'            p_pagina        => v_pagina, ',
'            p_encadeado     => p_encadeado, ',
'            p_sucesso       => p_sucesso, ',
'            p_messages      => p_messages ',
'        );',
'',
'        bo_imp_processoimportacao.atualiza_valor_total_condicao_venda( ',
'            p_id            => v_new.id_processoimportacao, ',
'            p_pagina        => v_pagina, ',
'            p_encadeado     => p_encadeado, ',
'            p_sucesso       => p_sucesso, ',
'            p_messages      => p_messages ',
'        );',
'',
'        tratar_reducao_quantidade_de_item(p_pagina => v_pagina, p_encadeado => p_encadeado, p_sucesso   => p_sucesso, p_messages  => p_messages);',
'',
'        if v_operacao = ''ALTERA_ID_NCM'' and v_old.id_ncm <> v_new.id_ncm then',
'            bo_imp_processoimportacao.concluir_processo_e_gerar_despesas(',
'                p_id                            => v_new.id_processoimportacao,',
'                p_pagina                        => v_pagina,',
'                p_encadeado                     => p_encadeado,',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages,',
'                p_altera_status                 => ''N''',
'            );',
'        end if;',
'',
'        -- Verifica necessidade de atualizar os tributos do processo:',
'        if recalcula_processo(v_new.id) then',
'            bo_imp_processoimportacao.gerencia_tributos(v_new.id_processoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        --',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_ind_status        imp_processoimportacao.ind_status%type;',
'    begin ',
'        bo_imp_processoimportacao.atualiza_ind_itens_vinculado_invoice( ',
'            p_id            => v_old.id_processoimportacao, ',
'            p_pagina        => v_pagina, ',
'            p_encadeado     => p_encadeado, ',
'            p_sucesso       => p_sucesso, ',
'            p_messages      => p_messages ',
'        );',
'',
'        bo_imp_processoimportacao.atualiza_valor_total_condicao_venda( ',
'            p_id            => v_old.id_processoimportacao, ',
'            p_pagina        => v_pagina, ',
'            p_encadeado     => p_encadeado, ',
'            p_sucesso       => p_sucesso, ',
'            p_messages      => p_messages ',
'        );',
'',
'        -- PEDITEM-114: Ao excluir o item do processo, deve excluir o item da entrega',
unistr('        -- Somente quando o processo N\00C3O estiver com status 10'),
'        select a.ind_status into l_ind_status from imp_processoimportacao a where a.id = v_old.id_processoimportacao;',
'        if l_ind_status <> 10 then',
'            bo_imp_entrega_item.exclui_registro(v_old.id_entrega_item, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        --',
'        -- Recalcular o rateio das despesas do processo: ',
'        recalcula_despesas_item(',
'            --p_id_processoimportacao_item    => v_new.id,',
'            p_id_processoimportacao         => v_old.id_processoimportacao,',
'            --p_id_tenant                     => v_new.id_tenant,',
'            p_pagina                        => v_pagina,',
'            p_encadeado                     => p_encadeado,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'        --',
'        -- Verifica necessidade de atualizar os tributos do processo:',
'        if recalcula_processo(v_old.id) then',
'            bo_imp_processoimportacao.gerencia_tributos(v_new.id_processoimportacao, v_pagina, p_encade'))
);
