'    --',
'    function detalhe_registro (',
'        p_id in imp_processoimportacao_item.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(''',
'            select',
'                b.num_processoimportacao as imp_processoimportacao_item$id_processoimportacao,',
'                c.codigo_item as imp_processoimportacao_item$id_item,',
'                pkg_traducao.get_traducao(c.descricao_item) as ng_item$descricao_item,',
'                d.codigo_unidademedida as imp_processoimportacao_item$id_unidademedida,',
'                case d.ind_tipo_dado',
'                    when ''''D'''' then ',
'                        to_char(a.quantidade, ''''FM999G999G990D00000'''')',
'                    when ''''I'''' then ',
'                        to_char(a.quantidade)',
'                end as imp_processoimportacao_item$quantidade',
'            from imp_processoimportacao_item a',
'            join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_item c on c.id = a.id_item',
'            join ng_unidademedida d on d.id = a.id_unidademedida',
'            where a.id = ''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure altera_entrega_item(',
'        p_id in imp_processoimportacao_item.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'        l_id_entrega_item number;',
'        l_entrega_item imp_entrega_item%rowtype;',
'    begin ',
'        select * into v_old from imp_processoimportacao_item where id = p_id;',
'        v_new := v_old;',
'',
'        l_id_entrega_item := v_new.id_entrega_item;',
'        select * into l_entrega_item from imp_entrega_item where id = l_id_entrega_item;',
'',
'        bo_imp_entrega_item.altera_registro(',
'            p_id_tenant                         => l_entrega_item.id_tenant,',
'            p_id_entrega                        => l_entrega_item.id_entrega,',
'            p_id_pedidoimportacao_item          => l_entrega_item.id_pedidoimportacao_item,',
'            p_id_item                           => l_entrega_item.id_item,',
'            p_id_ncm                            => v_new.id_ncm,',
'            p_id_unidademedida                  => l_entrega_item.id_unidademedida,',
'            p_quantidade                        => v_new.quantidade,',
'            p_peso_unitario                     => v_new.peso_unitario,',
'            p_peso_liquido_total                => v_new.peso_liquido_total,',
'            p_peso_bruto_unitario               => v_new.peso_bruto_unitario,',
'            p_peso_bruto_total                  => v_new.peso_bruto_total,',
'            p_valor_unitario                    => l_entrega_item.valor_unitario,',
'            p_valor_desconto_unitario           => l_entrega_item.valor_desconto_unitario,',
'            p_valor_desconto_pedido_item_unitario => l_entrega_item.valor_desconto_pedido_item_unitario,',
'            p_valor_despesaproforma             => l_entrega_item.valor_despesaproforma,',
'            p_valor_despesaproforma_unitario    => l_entrega_item.valor_despesaproforma_unitario,',
'            p_valor_total_condicao_venda        => l_entrega_item.valor_total_condicao_venda,',
'            p_valor_total_despesa_invoice_item  => l_entrega_item.valor_total_despesa_invoice_item, -- valor_total_despesa_invoice_item',
'            p_id_naturezaoperacao               => v_new.id_naturezaoperacao,',
'            p_id_fabricante                     => v_new.id_fabricante,',
'            p_id_pais_origem                    => v_new.id_pais_origem,',
'            p_ind_licenca_importacao            => l_entrega_item.ind_licenca_importacao, ',
'            p_ind_bloqueio_embarque_ate_deferimento_li => l_entrega_item.ind_bloqueio_embarque_ate_deferimento_li,',
'            p_quantidade_faturada               => l_entrega_item.quantidade_faturada,',
'            p_quantidade_saldo                  => l_entrega_item.quantidade_saldo,',
'            p_valor_total_desconto_invoice_item => l_entrega_item.valor_total_desconto_invoice_item,  -- valor_total_desconto_invoice_item',
'            p_ind_tratamento_saldo              => l_entrega_item.ind_tratamento_saldo,',
'            p_id                                => l_entrega_item.id,',
'            p_data_alteracao                    => l_entrega_item.data_alteracao, ',
'            p_encadeado                         => p_encadeado,',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );        ',
'    end altera_entrega_item; ',
'    --',
'    procedure exclui_entrega_item(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'        l_id_entrega_item number;',
'    begin ',
'        l_id_entrega_item := v_old.id_entrega_item;',
'',
'        bo_imp_entrega_item.exclui_registro(',
'            p_id => l_id_entrega_item,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end exclui_entrega_item;',
'    --',
'    procedure altera_id_naturezaoperacao_todos_itens(',
'        p_id_naturezaoperacao in imp_processoimportacao_item.id_naturezaoperacao%type,',
'        p_id_processoimportacao in imp_processoimportacao_item.id_processoimportacao%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item.altera_id_naturezaoperacao_todos_itens'';',
'        v_pagina := p_pagina;',
'',
'        for item in (',
'            select * from imp_processoimportacao_item where id_processoimportacao = p_id_processoimportacao',
'        ) loop',
'            select * into v_old from imp_processoimportacao_item where id = item.id;',
'            v_new := v_old;',
'',
'            v_new.id_naturezaoperacao := p_id_naturezaoperacao;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'',
'            v_operacao := ''ALTERA_ID_NATUREZAOPERACAO_TODOS_ITENS'';',
'',
'            grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'        end loop;',
'    end altera_id_naturezaoperacao_todos_itens;',
'    --',
'    procedure inclui_processoimportacao_item_tributo',
'    is',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        l_messages := pkg_mensagem.message_record_table();',
'',
'        bo_imp_processoimportacao_item_tributo.inclui_tributos(',
'            p_id_tenant => v_new.id_tenant,',
'            p_id_processoimportacao_item => v_new.id,',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
'        );',
'    end inclui_processoimportacao_item_tributo;',
'    --',
'    procedure altera_processoimportacao_item_tributo',
'    is ',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin        ',
'        l_messages := pkg_mensagem.message_record_table();        ',
'',
'        bo_imp_processoimportacao_item_tributo.altera_tributos(        ',
'            p_id_processoimportacao_item => v_new.id,',
'            p_encadeado => true,',
'            p_sucesso => l_sucesso,',
'            p_messages => l_messages',
'        );',
'    end altera_processoimportacao_item_tributo;',
'    --',
'    procedure exclui_processoimportacao_item(',
'        p_id in imp_processoimportacao_item.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_operacao := ''EXCLUI_PROCESSOIMPORTACAO_ITEM'';',
'        exclui_registro(p_id, p_encadeado, p_sucesso, p_messages);',
'    end exclui_processoimportacao_item;',
'    --',
'    procedure altera_quantidade_faturada(',
'        p_quantidade_faturada in imp_processoimportacao_item.quantidade_faturada%type,',
'        p_id in imp_processoimportacao_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item.altera_quantidades'';',
'',
'        select * into v_old from imp_processoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.quantidade_faturada := p_quantidade_faturada;',
'        v_new.quantidade_saldo := nvl(v_new.quantidade,0) - nvl(p_quantidade_faturada,0);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_QUANTIDADE_FATURADA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);           ',
'    end altera_quantidade_faturada;',
'    --',
'    procedure altera_valor_total_despesa_invoice_item(  ',
'        p_valor_total_despesa_invoice_item in imp_processoimportacao_item.valor_total_despesa_invoice_item%type, ',
'        p_id in imp_processoimportacao_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item.altera_valor_total_despesa_invoice_item'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_processoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_total_despesa_invoice_item := p_valor_total_despesa_invoice_item; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'',
'        v_operacao := ''ALTERA_VALOR_TOTAL_DESPESA_INVOICE_ITEM'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_valor_total_despesa_invoice_item;',
'    --',
'    procedure calcula_valor_total_mercadoria is',
'    begin',
'        v_new.valor_total_mercadoria := (nvl(v_new.valor_unitario, 0) - nvl(v_new.valor_desconto, 0)) * nvl(v_new.quantidade, 0);',
'    end;',
'    --',
'    procedure calcula_valor_total_condicao_venda is',
'    begin',
'        v_new.valor_total_condicao_venda := nvl(v_new.valor_total_mercadoria, 0) + nvl(v_new.valor_total_despesa_invoice_item, 0) - nvl(v_new.valor_total_desconto_invoice_item, 0);',
'    end;',
'    --',
