'    --',
'    procedure vincula_minutanotafiscal(',
'        p_id                  in imp_processoimportacao_item.id%type,',
'        p_id_minutanotafiscal in imp_processoimportacao_item.id_minutanotafiscal%type,',
'        p_encadeado           in boolean default false,',
'        p_sucesso             out clob,',
'        p_messages            out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao_item.vincula_minutanotafiscal'';',
'        --',
'        select * into v_new',
'          from imp_processoimportacao_item',
'         where id = p_id;',
'        --',
'        v_new.id_minutanotafiscal := p_id_minutanotafiscal;',
'        --',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end vincula_minutanotafiscal;',
'    --',
'    function calcular_diferenca_quantidade return number is',
'    begin',
'        return nvl(v_old.quantidade,0) - nvl(v_new.quantidade,0);',
'    end;',
'    --',
'    procedure tratar_reducao_quantidade_de_item(',
'        p_pagina in number default 0,',
'        p_encadeado           in boolean default false,',
'        p_sucesso             out clob,',
'        p_messages            out pkg_mensagem.message_record_table',
'    ) is',
'        l_diferenca number;',
'    begin',
'        l_diferenca := calcular_diferenca_quantidade;',
'',
'        if l_diferenca > 0 then',
'            bo_imp_entrega_item.altera_quantidade_bo_imp_processoimportacao_item(',
'                p_diferenca => l_diferenca,',
'                p_id => v_new.id_entrega_item,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end tratar_reducao_quantidade_de_item;',
'    --',
'    procedure altera_id_moeda(',
'        p_id_moeda in imp_processoimportacao_item.id_moeda%type,',
'        p_id in imp_processoimportacao_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item.altera_id_moeda'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_processoimportacao_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.id_moeda := p_id_moeda;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_ID_MOEDA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_id_moeda;',
'    --',
'    procedure altera_id_ncm(',
'        p_id_processoimportacao_item    in imp_processoimportacao_item.id%type,',
'        p_id_ncm                        in imp_processoimportacao_item.id_ncm%type,',
'        p_data_alteracao                in imp_processoimportacao_item.data_alteracao%type,',
'        p_encadeado                     in boolean default false,',
'        p_sucesso                       out clob,',
'        p_messages                      out pkg_mensagem.message_record_table',
'    )',
'    is',
'    begin',
'        v_operacao := ''ALTERA_ID_NCM'';',
'        v_data_alteracao := p_data_alteracao;',
'',
'        -- imp_processoimportacao_item',
'        select * into v_old from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'',
'        v_new := v_old;',
'        v_new.id_ncm := p_id_ncm;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        grava(p_id => p_id_processoimportacao_item, p_encadeado  => p_encadeado, p_sucesso    => p_sucesso, p_messages   => p_messages);',
'    end altera_id_ncm;',
'    --',
'    procedure atribui_valores is',
'    begin',
'        -- Valores referentes a moeda naciopnal sempre atualizados:',
'        v_new.valor_total_mercadoria_moeda_nacional    := (nvl(v_new.valor_total_mercadoria,0) * bo_imp_processoimportacao_item_tributo.cotacao_item_real(v_new.id));',
'        v_new.valor_unitario_mercadoria_moeda_nacional := (v_new.valor_total_mercadoria_moeda_nacional / nvl(nullif(v_new.quantidade,0),1));',
'        --',
unistr('        -- Busca refer\00EAncia nos par\00E2metros da natureza da opera\00E7\00E3o do item:'),
'        select ',
'            cst,',
'            id_cfop,',
'            cclasstrib',
'        into',
'            v_new.cst,',
'            v_new.id_cfop,',
'            v_new.cclasstrib',
'        from imp_naturezaoperacao_parametro ',
'        where id_naturezaoperacao = v_new.id_naturezaoperacao;',
'        --',
'    end atribui_valores;',
'    --',
'    function recalcula_processo(',
'        p_id in imp_processoimportacao_item.id%type',
'    ) return boolean is',
'        l_item_tributos number;',
'    begin',
'        select count(1) into l_item_tributos',
'        from imp_processoimportacao_item_despesa a',
'        left join imp_processoimportacao_despesa b on b.id = a.id_processoimportacao_despesa',
'        join ng_despesa c on c.id = a.id_despesa',
'        where a.id_processoimportacao_item = p_id',
'        and nvl(b.ind_tipo_despesa, c.ind_tipo_despesa) in (1,2,3,4,5,6,18,19);',
'            ',
'        if l_item_tributos > 0 then',
'            return true;',
'        else',
'            return false;',
'        end if;',
'    exception ',
'        when no_data_found then',
'            return true;',
'        when others then',
'            return false;',
'    end recalcula_processo;',
'    --',
