'        v_new.aliquota_cofins := nvl(p_aliquota_cofins,0);',
'        v_new.base_calculo_icms := nvl(p_base_calculo_icms,0);',
'        v_new.base_calculo_icms_st := nvl(p_base_calculo_icms_st,0);',
'        v_new.aliquota_icms := nvl(p_aliquota_icms,0);',
'        v_new.base_calculo_cbs := nvl(p_base_calculo_cbs,0);',
'        v_new.aliquota_cbs := nvl(p_aliquota_cbs,0);',
'        v_new.base_calculo_ibs := nvl(p_base_calculo_ibs,0);',
'        v_new.aliquota_ibs := nvl(p_aliquota_ibs,0);',
'        v_new.base_calculo_pis := nvl(p_base_calculo_pis,0);',
'        v_new.base_calculo_cofins := nvl(p_base_calculo_cofins,0); ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out imp_processoimportacao_item_tributo.id_tenant%type,',
'        p_id_processoimportacao_item out imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
'        p_vmle out imp_processoimportacao_item_tributo.vmle%type,',
'        p_vmld out imp_processoimportacao_item_tributo.vmld%type,',
'        p_base_calculo_ii out imp_processoimportacao_item_tributo.base_calculo_ii%type,',
'        p_aliquota_ii out imp_processoimportacao_item_tributo.aliquota_ii%type,',
'        p_base_calculo_ipi out imp_processoimportacao_item_tributo.base_calculo_ipi%type,',
'        p_aliquota_ipi out imp_processoimportacao_item_tributo.aliquota_ipi%type,',
'        p_aliquota_pis out imp_processoimportacao_item_tributo.aliquota_pis%type,',
'        p_aliquota_cofins out imp_processoimportacao_item_tributo.aliquota_cofins%type,',
'        p_base_calculo_icms out imp_processoimportacao_item_tributo.base_calculo_icms%type,',
'        p_base_calculo_icms_st out imp_processoimportacao_item_tributo.base_calculo_icms_st%type,',
'        p_aliquota_icms out imp_processoimportacao_item_tributo.aliquota_icms%type,',
'        p_base_calculo_cbs out imp_processoimportacao_item_tributo.base_calculo_cbs%type,',
'        p_aliquota_cbs out imp_processoimportacao_item_tributo.aliquota_cbs%type,',
'        p_base_calculo_ibs out imp_processoimportacao_item_tributo.base_calculo_ibs%type,',
'        p_aliquota_ibs out imp_processoimportacao_item_tributo.aliquota_ibs%type,',
'        p_base_calculo_pis out imp_processoimportacao_item_tributo.base_calculo_pis%type,',
'        p_base_calculo_cofins out imp_processoimportacao_item_tributo.base_calculo_cofins%type, ',
'        p_id in out imp_processoimportacao_item_tributo.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao_item_tributo.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            id_processoimportacao_item,',
'            vmle,',
'            vmld,',
'            base_calculo_ii,',
'            aliquota_ii,',
'            base_calculo_ipi,',
'            aliquota_ipi,',
'            aliquota_pis,',
'            aliquota_cofins,',
'            base_calculo_icms,',
'            base_calculo_icms_st,',
'            aliquota_icms,',
'            base_calculo_cbs,',
'            aliquota_cbs,',
'            base_calculo_ibs,',
'            aliquota_ibs,',
'            base_calculo_pis,',
'            base_calculo_cofins, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_id_processoimportacao_item,',
'            p_vmle,',
'            p_vmld,',
'            p_base_calculo_ii,',
'            p_aliquota_ii,',
'            p_base_calculo_ipi,',
'            p_aliquota_ipi,',
'            p_aliquota_pis,',
'            p_aliquota_cofins,',
'            p_base_calculo_icms,',
'            p_base_calculo_icms_st,',
'            p_aliquota_icms,',
'            p_base_calculo_cbs,',
'            p_aliquota_cbs,',
'            p_base_calculo_ibs,',
'            p_aliquota_ibs,',
'            p_base_calculo_pis,',
'            p_base_calculo_cofins, ',
'            p_id ',
'        from imp_processoimportacao_item_tributo ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in imp_processoimportacao_item_tributo.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao_item_tributo.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from imp_processoimportacao_item_tributo where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from imp_processoimportacao_item_tributo where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_processoimportacao_item_tributo'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in imp_processoimportacao_item_tributo.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_processoimportacao_item_tributo where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in imp_processoimportacao_item_tributo.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_processoimportacao_item_tributo where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in imp_processoimportacao_item_tributo.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_processoimportacao_item_tributo'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''imp_processoimportacao_item_tributo'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in imp_processoimportacao_item_tributo.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_processoimportacao_item */ '),
'        valida_id_processoimportacao_item(v_new.id_processoimportacao_item);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo vmle */ '),
'        valida_vmle(v_new.vmle);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo vmld */ '),
'        valida_vmld(v_new.vmld);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_ii */ '),
'        valida_base_calculo_ii(v_new.base_calculo_ii);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_ii */ '),
'        valida_aliquota_ii(v_new.aliquota_ii);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_ipi */ '),
'        valida_base_calculo_ipi(v_new.base_calculo_ipi);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_ipi */ '),
'        valida_aliquota_ipi(v_new.aliquota_ipi);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_pis */ '),
'        valida_aliquota_pis(v_new.aliquota_pis);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_cofins */ '),
'        valida_aliquota_cofins(v_new.aliquota_cofins);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_icms */ '),
'        valida_base_calculo_icms(v_new.base_calculo_icms);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_icms_st */ '),
'        valida_base_calculo_icms_st(v_new.base_calculo_icms_st);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_icms */ '),
'        valida_aliquota_icms(v_new.aliquota_icms);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_cbs */ '),
'        valida_base_calculo_cbs(v_new.base_calculo_cbs);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_cbs */ '),
'        valida_aliquota_cbs(v_new.aliquota_cbs);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_ibs */ '),
'        valida_base_calculo_ibs(v_new.base_calculo_ibs);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo aliquota_ibs */ '),
'        valida_aliquota_ibs(v_new.aliquota_ibs);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_pis */ '),
'        valida_base_calculo_pis(v_new.base_calculo_pis);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo base_calculo_cofins */ '),
'        valida_base_calculo_cofins(v_new.base_calculo_cofins);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in imp_processoimportacao_item_tributo.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_id_processoimportacao_item(p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_processoimportacao_item is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_processoimportacao_item_tributo.id_processoimportacao_item''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_processoimportacao_item'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_processoimportacao_item(p_id_processoimportacao_item);',
'    end valida_id_processoimportacao_item;     ',
'',
'    procedure valida_vmle(p_vmle in imp_processoimportacao_item_tributo.vmle%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
