'    --',
'    function cotacao_item_real(',
'        p_id_processoimportacao_item imp_processoimportacao_item_tributo.id_processoimportacao_item%type',
'    ) return number is',
'        l_id_tenant              number;',
'        l_id_moeda_nacional      number;',
'        l_id_moeda_item          number;',
'        l_verifica_duimp_cotacao number;',
'        l_resultado              number;',
'    begin',
'        -- Busca tenant, moeda nacional do processo e moeda do item:',
'        select ',
'            a.id_tenant, a.id_moeda_nacional, b.id_moeda ',
'        into    ',
'            l_id_tenant, l_id_moeda_nacional, l_id_moeda_item',
'        from imp_processoimportacao a',
'        join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'        where b.id = p_id_processoimportacao_item;',
'        --',
unistr('        -- Verifica se existe uma cota\00E7\00E3o da moeda do item cadastrada na DUIMP:'),
'        select count(1) into l_verifica_duimp_cotacao',
'        from imp_processoimportacao_item a',
'        join imp_declaracaoimportacao b on b.id_processoimportacao = a.id_processoimportacao',
'        join imp_declaracaoimportacao_cotacao c on c.id_declaracaoimportacao = b.id and c.id_moeda = a.id_moeda',
'        where a.id = p_id_processoimportacao_item;',
'        --',
unistr('        -- Se existe a cota\00E7\00E3o deve utiliz\00E1-la:'),
'        if l_verifica_duimp_cotacao > 0 then',
'            select c.taxa_cambio into l_resultado',
'            from imp_processoimportacao_item a',
'            join imp_declaracaoimportacao b on b.id_processoimportacao = a.id_processoimportacao',
'            join imp_declaracaoimportacao_cotacao c on c.id_declaracaoimportacao = b.id and c.id_moeda = a.id_moeda',
'            where a.id = p_id_processoimportacao_item;',
'        --',
unistr('        -- Se n\00E3o existe, deve utilizar a API de cota\00E7\00E3o do sistema:'),
'        else',
'            l_resultado := bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, l_id_moeda_item, l_id_moeda_nacional);',
'        end if;',
'        --',
'        -- Retorna valor encontrado:',
'        return l_resultado;',
'        --',
unistr('    -- Se der qualquer erro, retorna 1 para n\00E3o quebrar os c\00E1lculos:'),
'    exception',
'        when others then',
'            return 1;',
'    --',
'    end cotacao_item_real;',
'    --',
'    function cotacao_despesa_real(',
'        p_id_processoimportacao_despesa imp_processoimportacao_despesa.id%type',
'    ) return number is',
'        l_id_tenant              number;',
'        l_id_moeda_nacional      number;',
'        l_id_moeda_despesa       number;',
'        l_verifica_duimp_cotacao number;',
'        l_resultado              number;',
'    begin',
'        -- Busca tenant, moeda nacional do processo e moeda da despesa:',
'        select ',
'            a.id_tenant, a.id_moeda_nacional, nvl(b.id_moeda_realizada, b.id_moeda_prevista) ',
'        into    ',
'            l_id_tenant, l_id_moeda_nacional, l_id_moeda_despesa',
'        from imp_processoimportacao a',
'        join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'        where b.id = p_id_processoimportacao_despesa;',
'        --',
unistr('        -- Verifica se existe uma cota\00E7\00E3o da moeda da despesa cadastrada na DUIMP:'),
'        select count(1) into l_verifica_duimp_cotacao',
'        from imp_processoimportacao_despesa a',
'        join imp_declaracaoimportacao b on b.id_processoimportacao = a.id_processoimportacao',
'        join imp_declaracaoimportacao_cotacao c on c.id_declaracaoimportacao = b.id and c.id_moeda = nvl(a.id_moeda_realizada, a.id_moeda_prevista)',
'        where a.id = p_id_processoimportacao_despesa;',
'        --',
unistr('        -- Se existe a cota\00E7\00E3o deve utiliz\00E1-la:'),
'        if l_verifica_duimp_cotacao > 0 then',
'            select c.taxa_cambio into l_resultado',
'            from imp_processoimportacao_despesa a',
'            join imp_declaracaoimportacao b on b.id_processoimportacao = a.id_processoimportacao',
'            join imp_declaracaoimportacao_cotacao c on c.id_declaracaoimportacao = b.id and c.id_moeda = nvl(a.id_moeda_realizada, a.id_moeda_prevista)',
'            where a.id = p_id_processoimportacao_despesa;',
'        --',
unistr('        -- Se n\00E3o existe, deve utilizar a API de cota\00E7\00E3o do sistema:'),
'        else',
'            l_resultado := bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, l_id_moeda_despesa, l_id_moeda_nacional);',
'        end if;',
'        --',
'        -- Retorna valor encontrado:',
'        return l_resultado;',
'        --',
unistr('    -- Se der qualquer erro, retorna 1 para n\00E3o quebrar os c\00E1lculos:'),
'    exception',
'        when others then',
'            return 1;',
'    --',
'    end cotacao_despesa_real;',
'    --',
'    function calcula_tributo_por_tipo(',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
'        p_ind_tipo_despesa           in ng_despesa.ind_tipo_despesa%type',
'    ) return number is',
'        l_resultado number;',
'    begin',
unistr('        -- Busca o valor total do tributo do item j\00E1 na moeda nacional:'),
'        select ',
'            nvl(sum(nvl(nullif(a.valor_total_despesa_realizado_item,0), a.valor_total_despesa_previsto_item)),0)',
'        into',
'            l_resultado',
'        from imp_processoimportacao_item_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        where a.id_processoimportacao_item = p_id_processoimportacao_item',
'        and b.ind_tipo_despesa = p_ind_tipo_despesa;',
'        --',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end calcula_tributo_por_tipo;',
'    --',
'    function calcula_total_despesa_por_tipo(',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
'        p_ind_tipo_despesa           in ng_despesa.ind_tipo_despesa%type',
'    ) return number is',
'        l_id_tenant                                     number;',
'        l_id_processoimportacao                         number;',
'        l_valor                                         number;',
'        l_ind_forma_rateio                              number;',
'        l_peso_liquido_total_processoimportacao         number;',
'        l_peso_liquido_total                            number;',
'        l_quantidade_processoimportacao                 number;',
'        l_quantidade                                    number;',
'        l_valor_total_condicao_venda_processoimportacao number;',
'        l_valor_total_condicao_venda                    number;',
'        l_moeda_despesa                                 number;',
'        l_moeda_processoimportacao_item                 number;',
'        l_resultado                                     number := 0;',
unistr('        -- Vari\00E1veis para tratamento do resto:'),
'        l_base_5      number;',
'        l_soma_base_5 number;',
'        l_total_5     number;',
'        l_resto       number;',
'        l_item_ajuste number;',
'    begin',
unistr('        -- Busca informa\00E7\00F5es do item:'),
'        select ',
'            id_tenant, ',
'            id_processoimportacao,',
'            peso_liquido_total,',
'            quantidade,',
'            (valor_total_condicao_venda * cotacao_item_real(id))',
'        into ',
'            l_id_tenant, ',
'            l_id_processoimportacao,',
'            l_peso_liquido_total,',
'            l_quantidade,',
'            l_valor_total_condicao_venda',
'        from imp_processoimportacao_item',
'        where id = p_id_processoimportacao_item;',
'        --',
'        -- Busca valor convertido das despesas:',
'        select ',
'            nvl(sum(nvl(nullif(a.valor_realizado, 0), a.valor_previsto) * cotacao_despesa_real(a.id)),0)',
'        into',
'            l_valor',
'        from imp_processoimportacao_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        join imp_processoimportacao c on c.id = a.id_processoimportacao',
'        where b.ind_tipo_despesa = p_ind_tipo_despesa',
'        and c.id = l_id_processoimportacao;',
'        --',
unistr('        -- Busca informa\00E7\00F5es para c\00E1lcular rateio:'),
'        select ',
'            nvl(a.ind_forma_rateio, b.ind_forma_rateio)',
'        into',
'            l_ind_forma_rateio',
'        from imp_processoimportacao_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        where a.id_processoimportacao = l_id_processoimportacao',
'        and b.ind_tipo_despesa = p_ind_tipo_despesa',
'        order by a.data_inclusao',
'        fetch first 1 row only;',
'        --',
unistr('        -- Busca totais do processo para c\00E1lcular rateio:'),
'        select ',
'            sum(peso_liquido_total),',
'            sum(quantidade),',
'            sum(valor_total_condicao_venda * cotacao_item_real(id))',
'        into ',
'            l_peso_liquido_total_processoimportacao,',
'            l_quantidade_processoimportacao,',
'            l_valor_total_condicao_venda_processoimportacao',
'        from imp_processoimportacao_item',
'        where id_processoimportacao = l_id_processoimportacao;',
'        --',
'        -- Verifica formas de rateio:',
'        if l_ind_forma_rateio = 1 then',
unistr('            -- Rateio por peso l\00EDquido:'),
'            l_resultado := (l_valor / l_peso_liquido_total) * l_peso_liquido_total_processoimportacao;',
'            --',
'            -- Tratamento do resto:',
'            select sum(trunc(((l_valor / l_peso_liquido_total) * peso_liquido_total) * 100000))',
'            into l_soma_base_5',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'            --            ',
'        elsif l_ind_forma_rateio = 2 then',
'            -- Rateio por quantidade:',
'            l_resultado := (l_valor / l_quantidade) * l_quantidade_processoimportacao;',
'            --',
'            -- Tratamento do resto:',
'            select sum(trunc(((l_valor / l_quantidade) * quantidade) * 100000))',
'            into l_soma_base_5',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'            --',
'        elsif l_ind_forma_rateio = 3 then',
unistr('            -- Rateio por valor total na condi\00E7\00E3o de venda:'),
'            l_resultado := (l_valor / l_valor_total_condicao_venda) * l_valor_total_condicao_venda_processoimportacao;',
'            --',
'            -- Tratamento do resto:',
'            select sum(trunc(((l_valor / l_valor_total_condicao_venda) * (valor_total_condicao_venda * cotacao_item_real(id))) * 100000))',
'   '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154768709889544372)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'         into l_soma_base_5',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'            --',
'        elsif l_ind_forma_rateio = 5 then',
unistr('            -- N\00E3o se aplica rateio:'),
'            null;',
'            --',
'        end if;',
'        --',
'        -- Base truncada em 5 casas:',
'        l_base_5 := trunc(l_resultado * 100000);',
'        --',
'        -- Total esperado:',
'        l_total_5 := trunc(l_valor * 100000);',
'        --',
unistr('        -- Diferen\00E7a:'),
'        l_resto := l_total_5 - l_soma_base_5;',
'        --',
unistr('        -- Item que receber\00E1 o ajuste:'),
'        select min(id)',
'        into l_item_ajuste',
'        from imp_processoimportacao_item',
'        where id_processoimportacao = l_id_processoimportacao;',
'        --',
'        -- Aplica no item correto:',
'        if p_id_processoimportacao_item = l_item_ajuste then',
'            l_base_5 := l_base_5 + l_resto;',
'        end if;',
'        --',
'        -- Resultado para retorno:',
'        l_resultado := l_base_5 / 100000;',
'        --',
'        return trunc(l_resultado, 5);',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_despesa_por_tipo;',
'    --',
'    function calcula_total_despesa_base_calculo(',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
'        p_ind_despesa_base_calculo in ng_despesa.ind_despesa_base_calculo%type',
'    ) return number is',
'        l_despesas_previstas number;',
'        l_despesas_realizadas number;',
'        l_resultado number := 0;',
'    begin',
'        -- Despesas previstas:        ',
'        select ',
'            nvl(sum(nvl(a.valor_total_despesa_previsto_item,0) * cotacao_despesa_real(b.id)),0)            ',
'        into ',
'            l_despesas_previstas',
'        from imp_processoimportacao_item_despesa a        ',
'        left join imp_processoimportacao_despesa b on b.id = a.id_processoimportacao_despesa',
'        left join ng_despesa c on c.id =b.id_despesa',
'        where a.id_processoimportacao_item = p_id_processoimportacao_item',
'        and b.ind_status_despesa = 1',
'        and '':''||c.ind_despesa_base_calculo||'':'' like ''%:''||p_ind_despesa_base_calculo||'':%'';',
'',
'        -- Despesas realizadas:        ',
'        select ',
'            nvl(sum(nvl(a.valor_total_despesa_realizado_item,0) * cotacao_despesa_real(b.id)),0)            ',
'        into ',
'            l_despesas_realizadas',
'        from imp_processoimportacao_item_despesa a        ',
'        left join imp_processoimportacao_despesa b on b.id = a.id_processoimportacao_despesa',
'        left join ng_despesa c on c.id =b.id_despesa',
'        where a.id_processoimportacao_item = p_id_processoimportacao_item',
'        and b.ind_status_despesa = 2',
'        and '':''||c.ind_despesa_base_calculo||'':'' like ''%:''||p_ind_despesa_base_calculo||'':%'';',
'        ',
'        l_resultado := l_despesas_previstas + l_despesas_realizadas;',
'        return trunc(l_resultado, 5);',
'    exception ',
'        when others then ',
'            return 0;',
'    end calcula_total_despesa_base_calculo;',
'    --',
'    function calcula_total_despesa_base_calculo_processo(',
'        p_id_processoimportacao    in imp_processoimportacao_despesa.id_processoimportacao%type,',
'        p_ind_despesa_base_calculo in ng_despesa.ind_despesa_base_calculo%type,',
'        p_converter_valor          in varchar2 default null',
'    ) return number is',
'        l_id_tenant       number;',
'        l_id_moeda_tenant number;',
'        l_resultado       number := 0;',
'    begin       ',
'        if p_converter_valor is null then',
'            select',
'                case',
'                    when a.ind_status_despesa = 1 then',
'                        nvl(sum(nvl(a.valor_previsto,0)),0)',
'                    else',
'                        nvl(sum(nvl(a.valor_realizado,0)),0)',
'                end',
'            into ',
'                l_resultado',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id_processoimportacao = p_id_processoimportacao',
'            and '':''||b.ind_despesa_base_calculo||'':'' like ''%:''||p_ind_despesa_base_calculo||'':%''',
'            group by a.ind_status_despesa;',
'        else',
'            select id_tenant, id_moeda_tenant into l_id_tenant, l_id_moeda_tenant from imp_processoimportacao where id = p_id_processoimportacao;',
'            select',
'                case',
'                    when a.ind_status_despesa = 1 then',
'                        nvl(sum(nvl(a.valor_previsto * (bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, a.id_moeda_prevista, l_id_moeda_tenant)),0)),0)',
'                    else',
'                        nvl(sum(nvl(a.valor_realizado * (bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, a.id_moeda_prevista, l_id_moeda_tenant)),0)),0)',
'                end',
'            into ',
'                l_resultado',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id_processoimportacao = p_id_processoimportacao',
'            and '':''||b.ind_despesa_base_calculo||'':'' like ''%:''||p_ind_despesa_base_calculo||'':%''',
'            group by a.ind_status_despesa;',
'        end if;',
'',
'        return trunc(l_resultado, 2);        ',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_despesa_base_calculo_processo;',
'    --',
'    function calcula_vmle(',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type',
'    ) return number is',
'        l_id_processoimportacao number;',
'        l_id_incoterm number;',
'        l_valor_total_condicao_venda number;        ',
'        l_ind_responsavel_despesa_origem ng_incoterm.ind_responsavel_despesa_origem%type;',
'        l_ind_responsavel_frete  ng_incoterm.ind_responsavel_frete%type;',
'        l_ind_responsavel_seguro ng_incoterm.ind_responsavel_seguro%type;',
'        l_resultado number := 0;',
'    begin',
'        select',
'            a.id_incoterm, ',
'            case when a.id_moeda = b.id_moeda_nacional then',
'                a.valor_total_condicao_venda ',
'            else',
'                (a.valor_total_condicao_venda  * cotacao_item_real(p_id_processoimportacao_item))',
'            end valor_convertido',
'        into ',
'            l_id_incoterm,',
'            l_valor_total_condicao_venda',
'        from imp_processoimportacao_item a',
'        join imp_processoimportacao b on b.id = a.id_processoimportacao',
'        where a.id = p_id_processoimportacao_item;',
'',
'        select ',
'            lower(ind_responsavel_despesa_origem), lower(ind_responsavel_frete), lower(ind_responsavel_seguro) ',
'        into ',
'            l_ind_responsavel_despesa_origem, l_ind_responsavel_frete, l_ind_responsavel_seguro ',
'        from ng_incoterm ',
'        where id = l_id_incoterm;',
'',
'        if l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''i'' then     -- iii',
'            l_resultado := l_valor_total_condicao_venda;',
'        elsif l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''e'' then  -- iie',
'            l_resultado := l_valor_total_condicao_venda;',
'        elsif l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''i'' then  -- iei',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 10);',
'        elsif l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''e'' then  -- iee',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 10);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''i'' then  -- eii',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 9);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''i'' then  -- eei',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 10) - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 9);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''e'' then  -- eie',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 9);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''e'' then  -- eee',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 10) - calcula_total_despesa_por_tipo(p_id_processoimportacao_item, 9);',
'        end if;',
'        return trunc(l_resultado,5);',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_vmle;',
'    --    ',
'    function calcula_vmld(',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type',
'    ) return number is',
'        l_resultado number := 0;',
'    begin',
'        l_resultado := calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 10);',
'        return trunc(l_resultado,5);',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_vmld;',
'    --',
'    function retorna_base_calculo_ii(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is',
'        l_resultado number;',
'    begin',
'        l_resultado := calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 1);',
'        return trunc(l_resultado,5);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_ii;',
'    --',
'    function retorna_aliquota_ii(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_ind_aplicacao_ii number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm into l_id_naturezaoperacao, l_id_ncm from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_ii) into l_ind_aplicacao_ii from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ii = 1 then',
'            select aliquota_ii into l_resultado from ng_ncm a join imp_ncm_tributo b on b.id_ncm = a.id where a.id = l_id_ncm;',
'        elsif l_ind_aplicacao_ii = 2 then',
'            select aliquota_ii into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_ii = 3 then',
'            l_resultado := 0;',
'        end if;',
'        return trunc(l_resultado,2);',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_ii;',
'    --',
'    function retorna_base_calculo_ipi(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_ipi number;',
'        l_percentual_reducao_base_ipi number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_ipi) into l_ind_aplicacao_ipi from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ipi in (1,2,4) then',
'            l_resultado := calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 2);',
'        elsif l_ind_aplicacao_ipi = 3 then',
'            select percentual_reducao_base_ipi into l_percentual_reducao_base_ipi from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;            ',
'            l_resultado := ((calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 2)) * (1 - (l_percentual_reducao_base_ipi / 100)));',
'        end if;',
'        return trunc(l_resultado,5);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_ipi;',
