'        when others then',
'            return 0;',
'    end retorna_base_calculo_ibs;',
'    --',
'    function retorna_aliquota_ibs(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_id_adquirente number;',
'        l_ind_aplicacao_ibs number;',
'        l_aliquota_ibu number;',
'        l_aliquota_ibm number;',
'        l_resultado number;',
'    begin',
'        select a.id_naturezaoperacao, a.id_ncm, nvl(b.id_adquirente, b.id_importador) into l_id_naturezaoperacao, l_id_ncm, l_id_adquirente from imp_processoimportacao_item a join imp_entrega b on b.id = a.id_entrega where a.id = p_id_processoimporta'
||'cao_item;',
'        select ind_aplicacao_ibs into l_ind_aplicacao_ibs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ibs in (1, 3) then',
'            select ',
'                bo_ng_ibu.retorna_aliquota_ibu(id_estado), ',
'                bo_ng_ibm.retorna_aliquota_ibm(id_cidade) ',
'            into ',
'                l_aliquota_ibu, ',
'                l_aliquota_ibm ',
'            from ng_pessoa_endereco ',
'            where id = bo_ng_pessoa_endereco.retorna_id_pessoa_endereco(l_id_adquirente);',
'',
'            l_resultado := l_aliquota_ibu + l_aliquota_ibm;',
'        elsif l_ind_aplicacao_ibs = 2 then',
'            select aliquota_ibs into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_ibs = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return trunc(l_resultado,2);',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_ibs;',
'    --',
'    function retorna_base_calculo_icms(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_icms number;',
'        l_ind_ipi_suspenso_base_icms varchar2(1);',
'        l_ind_integra_propria_base_icms varchar2(1);',
'        l_percentual_reducao_base_icms number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_icms), lower(ind_ipi_suspenso_base_icms), lower(ind_integra_propria_base_icms) into l_ind_aplicacao_icms, l_ind_ipi_suspenso_base_icms, l_ind_integra_propria_base_icms from imp_naturezaoperacao_tributo where id_natu'
||'rezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_icms in (1,2,4) and l_ind_ipi_suspenso_base_icms = ''n'' and l_ind_integra_propria_base_icms = ''n'' then',
'            l_resultado := calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 5);',
'        elsif l_ind_aplicacao_icms in (1,2,4) and l_ind_ipi_suspenso_base_icms = ''n'' and l_ind_integra_propria_base_icms = ''s'' then',
'            l_resultado := ((calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 5)) * (1 - (retorna_aliquota_icms(p_id_processoimportacao_item) / 100)));',
'        elsif l_ind_aplicacao_icms in (1,2,4) and l_ind_ipi_suspenso_base_icms = ''s'' and l_ind_integra_propria_base_icms = ''n'' then',
'            l_resultado := ((calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 5)) - calcula_tributo_por_tipo(p_id_processoimportacao_item,2));',
'        elsif l_ind_aplicacao_icms in (1,2,4) and l_ind_ipi_suspenso_base_icms = ''s'' and l_ind_integra_propria_base_icms = ''s'' then',
'            l_resultado := (((calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 5)) - calcula_tributo_por_tipo(p_id_processoimportacao_item,2)) * (1 - (retorna_aliquota_icms(p_id_processoimp'
||'ortacao_item) / 100)));',
'        elsif l_ind_aplicacao_icms = 3 then',
'            select percentual_reducao_base_icms into l_percentual_reducao_base_icms from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'            l_resultado := ((calcula_vmle(p_id_processoimportacao_item) + calcula_total_despesa_base_calculo(p_id_processoimportacao_item, 5)) * (1 - (l_percentual_reducao_base_icms / 100)));',
'        end if;',
'        return trunc(l_resultado, 2);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_icms;',
'    --',
'    function retorna_base_calculo_icms_st(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is  ',
'        l_ind_icms_st varchar2(1);',
'        l_percentual_mva_icms_st number;      ',
'        l_resultado number := 0;',
'    begin        ',
'        select nvl(b.percentual_mva_icms_st, 0)',
'        into l_percentual_mva_icms_st ',
'        from imp_processoimportacao_item a ',
'        join imp_naturezaoperacao_tributo b on b.id_naturezaoperacao = a.id_naturezaoperacao ',
'        where a.id = p_id_processoimportacao_item;',
'',
'        l_resultado := retorna_base_calculo_icms(p_id_processoimportacao_item) * (l_percentual_mva_icms_st / 100);',
'',
'        return trunc(l_resultado, 2);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_icms_st;',
'    --',
'    function retorna_aliquota_icms(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type',
'    ) return number is',
'        l_verifica_duimp number;',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_id_processoimportacao number;',
'        l_id_importador number;',
'        l_ind_aplicacao_icms number;        ',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm, id_processoimportacao into l_id_naturezaoperacao, l_id_ncm, l_id_processoimportacao from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_icms) into l_ind_aplicacao_icms from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_icms in (1, 3) then',
'            select count(1) into l_verifica_duimp',
'            from imp_declaracaoimportacao',
'            where id_processoimportacao = l_id_processoimportacao;',
'',
'            if l_verifica_duimp > 0 then',
'                select f.perc_icms',
'                into l_resultado',
'                from imp_processoimportacao a',
'                join ng_recinto_alfandegado b on b.id = a.id_recinto_alfandegado',
'                join ng_unidadelocalrfb c on c.id = b.id_unidade_local_rfb',
'                join ng_cidade d on d.id = c.id_cidade',
'                join ng_estado e on e.id = d.id_estado',
'                join ng_icms f on f.id_uf_origem = e.id',
'                where a.id = l_id_processoimportacao;',
'            else',
'                select e.perc_icms',
'                into l_resultado',
'                from imp_processoimportacao a',
'                join ng_localembarquedesembarque b on b.id = a.id_local_desembarque',
'                join ng_cidade c on c.id = b.id_cidade',
'                join ng_estado d on d.id = c.id_estado',
'              '))
);
