 p_id=>wwv_flow_imp.id(154768709889544372)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  join ng_icms e on e.id_uf_destino = d.id',
'                where a.id = l_id_processoimportacao;',
'            end if;',
'        elsif l_ind_aplicacao_icms = 2 then',
'            select aliquota_icms into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_icms = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return trunc(nvl(l_resultado,0),2);',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_icms;',
'    --',
'    procedure inclui_tributos(',
'        p_id_tenant in imp_processoimportacao_item_tributo.id_tenant%type,',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
