'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id number;',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item_tributo.inclui_tributos'';',
'        v_pagina := p_pagina;',
'',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_processoimportacao_item := p_id_processoimportacao_item;',
'        --',
unistr('        -- Fun\00E7\00F5es para calcular cada tributo        '),
'        --',
'        v_new.vmle                 := calcula_vmle(v_new.id_processoimportacao_item);',
'        v_new.vmld                 := calcula_vmld(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_ii      := retorna_base_calculo_ii(v_new.id_processoimportacao_item);',
'        v_new.aliquota_ii          := retorna_aliquota_ii(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_ipi     := retorna_base_calculo_ipi(v_new.id_processoimportacao_item);',
'        v_new.aliquota_ipi         := retorna_aliquota_ipi(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_pis     := retorna_base_calculo_pis(v_new.id_processoimportacao_item);',
'        v_new.aliquota_pis         := retorna_aliquota_pis(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_cofins  := retorna_base_calculo_cofins(v_new.id_processoimportacao_item);',
'        v_new.aliquota_cofins      := retorna_aliquota_cofins(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_cbs     := retorna_base_calculo_cbs(v_new.id_processoimportacao_item);',
'        v_new.aliquota_cbs         := retorna_aliquota_cbs(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_ibs     := retorna_base_calculo_ibs(v_new.id_processoimportacao_item);',
'        v_new.aliquota_ibs         := retorna_aliquota_ibs(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_icms    := retorna_base_calculo_icms(v_new.id_processoimportacao_item);',
'        v_new.base_calculo_icms_st := retorna_base_calculo_icms_st(v_new.id_processoimportacao_item);',
'        v_new.aliquota_icms        := retorna_aliquota_icms(v_new.id_processoimportacao_item);',
'        --',
'        v_new.id_usuario_incluiu   := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao        := sysdate; ',
'        v_new.id_usuario_alterou   := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao       := sysdate;',
'        --',
'        v_operacao := ''INCLUI_TRIBUTOS'';',
'        cria(p_encadeado, p_sucesso, p_messages, l_id);',
'    end inclui_tributos;',
'    --',
'    procedure altera_tributos(        ',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
'        p_pagina                     in number default 0,',
'        p_encadeado                  in boolean default false,',
'        p_sucesso                    out clob,',
'        p_messages                   out pkg_mensagem.message_record_table',
'    ) is',
'        l_verifica_registro_existe number;',
'        l_id_tenant                number;',
'        l_id                       number;',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item_tributo.inclui_tributos'';',
'        v_pagina       := p_pagina;',
'',
'        select count(1) into l_verifica_registro_existe from imp_processoimportacao_item_tributo where id_processoimportacao_item = p_id_processoimportacao_item;',
'',
'        if l_verifica_registro_existe > 0 then',
'            select * into v_old from imp_processoimportacao_item_tributo where id_processoimportacao_item = p_id_processoimportacao_item;',
'            v_new := v_old;',
'        else',
'            select id_tenant into l_id_tenant from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        end if;',
'        --',
unistr('        -- Fun\00E7\00F5es para calcular cada tributo        '),
'        --',
'        v_new.vmle                 := calcula_vmle(p_id_processoimportacao_item);',
'        v_new.vmld                 := calcula_vmld(p_id_processoimportacao_item);',
'        v_new.base_calculo_ii      := retorna_base_calculo_ii(p_id_processoimportacao_item);',
'        v_new.aliquota_ii          := retorna_aliquota_ii(p_id_processoimportacao_item);',
'        v_new.base_calculo_ipi     := retorna_base_calculo_ipi(p_id_processoimportacao_item);',
'        v_new.aliquota_ipi         := retorna_aliquota_ipi(p_id_processoimportacao_item);',
'        v_new.base_calculo_pis     := retorna_base_calculo_pis(p_id_processoimportacao_item);',
'        v_new.aliquota_pis         := retorna_aliquota_pis(p_id_processoimportacao_item);',
'        v_new.base_calculo_cofins  := retorna_base_calculo_cofins(p_id_processoimportacao_item);',
'        v_new.aliquota_cofins      := retorna_aliquota_cofins(p_id_processoimportacao_item);',
'        v_new.base_calculo_cbs     := retorna_base_calculo_cbs(p_id_processoimportacao_item);',
'        v_new.aliquota_cbs         := retorna_aliquota_cbs(p_id_processoimportacao_item);',
'        v_new.base_calculo_ibs     := retorna_base_calculo_ibs(p_id_processoimportacao_item);',
'        v_new.aliquota_ibs         := retorna_aliquota_ibs(p_id_processoimportacao_item);',
'        v_new.base_calculo_icms    := retorna_base_calculo_icms(p_id_processoimportacao_item);',
'        v_new.base_calculo_icms_st := retorna_base_calculo_icms_st(p_id_processoimportacao_item);',
'        v_new.aliquota_icms        := retorna_aliquota_icms(p_id_processoimportacao_item);',
'        --',
'        v_new.id_usuario_alterou   := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao       := sysdate;',
'        --',
'        if l_verifica_registro_existe > 0 then',
'            v_operacao := ''ALTERA_TRIBUTOS'';',
'            grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'        else',
'            inclui_tributos(',
'                p_id_tenant                  => l_id_tenant,',
'                p_id_processoimportacao_item => p_id_processoimportacao_item,',
'                p_pagina                     => p_pagina,',
'                p_encadeado                  => p_encadeado,',
'                p_sucesso                    => p_sucesso,',
'                p_messages                   => p_messages',
'            );',
'        end if;',
'    end altera_tributos;',
'    --',
'    procedure altera_processoimportacao_ind_calculando_valores(',
'        p_id_processoimportacao_item in imp_processoimportacao_item_tributo.id_processoimportacao_item%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao number;',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        bo_imp_processoimportacao.altera_ind_calculando_valores(',
'            p_ind_calculando_valores => ''N'', ',
'            p_data_hora_ultimo_calculo => sysdate, ',
'            p_id => l_id_processoimportacao,',
'            p_pagina => p_pagina,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end altera_processoimportacao_ind_calculando_valores;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_processoimportacao_item_tributo;',
'/'))
);
end;
