'        p_cnh in ng_pessoa_fisica.cnh%type,',
'        p_passaporte in ng_pessoa_fisica.passaporte%type,',
'        p_data_aniversario in ng_pessoa_fisica.data_aniversario%type,',
'        p_data_integracao in ng_pessoa_fisica.data_integracao%type,',
'        p_id_tenant in ng_pessoa_fisica.id_tenant%type, ',
'        p_id in ng_pessoa_fisica.id%type, ',
'        p_data_alteracao in ng_pessoa_fisica.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_pessoa_fisica.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_pessoa_fisica where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_pessoa := p_id_pessoa;',
'        v_new.nome := p_nome;',
'        v_new.nome_abreviado := p_nome_abreviado;',
'        v_new.observacao := p_observacao;',
'        v_new.rg := p_rg;',
'        v_new.cpf := p_cpf;',
'        v_new.cnh := p_cnh;',
'        v_new.passaporte := p_passaporte;',
'        v_new.data_aniversario := p_data_aniversario;',
'        v_new.data_integracao := p_data_integracao;',
'        v_new.id_tenant := p_id_tenant; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_pessoa out ng_pessoa_fisica.id_pessoa%type,',
'        p_nome out ng_pessoa_fisica.nome%type,',
'        p_nome_abreviado out ng_pessoa_fisica.nome_abreviado%type,',
'        p_observacao out ng_pessoa_fisica.observacao%type,',
'        p_rg out ng_pessoa_fisica.rg%type,',
'        p_cpf out ng_pessoa_fisica.cpf%type,',
'        p_cnh out ng_pessoa_fisica.cnh%type,',
'        p_passaporte out ng_pessoa_fisica.passaporte%type,',
'        p_data_aniversario out ng_pessoa_fisica.data_aniversario%type,',
'        p_data_integracao out ng_pessoa_fisica.data_integracao%type,',
'        p_id_tenant out ng_pessoa_fisica.id_tenant%type, ',
'        p_id in out ng_pessoa_fisica.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_pessoa_fisica.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_pessoa,',
'            nome,',
'            nome_abreviado,',
'            observacao,',
'            rg,',
'            cpf,',
'            cnh,',
'            passaporte,',
'            data_aniversario,',
'            data_integracao,',
'            id_tenant, ',
'            id ',
'            into ',
'            p_id_pessoa,',
'            p_nome,',
'            p_nome_abreviado,',
'            p_observacao,',
'            p_rg,',
'            p_cpf,',
'            p_cnh,',
'            p_passaporte,',
'            p_data_aniversario,',
'            p_data_integracao,',
'            p_id_tenant, ',
'            p_id ',
'        from ng_pessoa_fisica ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in ng_pessoa_fisica.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_pessoa_fisica.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_pessoa_fisica where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from ng_pessoa_fisica where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_pessoa_fisica'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154769275206507221)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in ng_pessoa_fisica.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from ng_pessoa_fisica where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in ng_pessoa_fisica.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from ng_pessoa_fisica where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in ng_pessoa_fisica.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''ng_pessoa_fisica'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''ng_pessoa_fisica'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in ng_pessoa_fisica.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_pessoa */ '),
'        valida_id_pessoa(v_new.id_pessoa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo nome */ '),
'        valida_nome(v_new.nome);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo nome_abreviado */ '),
'        valida_nome_abreviado(v_new.nome_abreviado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo observacao */ '),
'        valida_observacao(v_new.observacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo rg */ '),
'        valida_rg(v_new.rg);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cpf */ '),
'        valida_cpf(v_new.cpf);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo cnh */ '),
'        valida_cnh(v_new.cnh);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo passaporte */ '),
'        valida_passaporte(v_new.passaporte);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_aniversario */ '),
'        valida_data_aniversario(v_new.data_aniversario);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_integracao */ '),
'        valida_data_integracao(v_new.data_integracao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_pessoa(p_id_pessoa in ng_pessoa_fisica.id_pessoa%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_pessoa is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.id_pessoa''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_pessoa'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_pessoa(p_id_pessoa);',
'    end valida_id_pessoa;     ',
'',
'    procedure valida_nome(p_nome in ng_pessoa_fisica.nome%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_nome is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.nome''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''nome'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_nome(p_nome);',
'    end valida_nome;     ',
'',
'    procedure valida_nome_abreviado(p_nome_abreviado in ng_pessoa_fisica.nome_abreviado%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_nome_abreviado is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.nome_abreviado''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''nome_abreviado'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from ng_pessoa_fisica where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(nome)) = lower(trim(v_new.nome)) and lower(trim(nome_abreviado)) = lower(trim(v_new.nome_abreviad'
||'o)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from ng_pessoa_fisica where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(nome)) = lower(trim(v_new.nome)) and lower(trim(nome_abreviado)) = lower(trim(v_new.nome_abreviad'
||'o)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.nome_abreviado'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''nome_abreviado'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_nome_abreviado(p_nome_abreviado);',
'    end valida_nome_abreviado;     ',
'',
'    procedure valida_observacao(p_observacao in ng_pessoa_fisica.observacao%type) ',
'    is ',
