unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_pessoa_fisica'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_pessoa_fisica'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_pessoa_fisica'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_pessoa_fisica'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_pessoa_fisica'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_pessoa_fisica'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_pessoa_fisica%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_pessoa'', p_rec.id_pessoa, true);',
'        apex_json.write(''nome'', p_rec.nome, true);',
'        apex_json.write(''nome_abreviado'', p_rec.nome_abreviado, true);',
'        apex_json.write(''observacao'', p_rec.observacao, true);',
'        apex_json.write(''rg'', p_rec.rg, true);',
'        apex_json.write(''cpf'', p_rec.cpf, true);',
'        apex_json.write(''cnh'', p_rec.cnh, true);',
'        apex_json.write(''passaporte'', p_rec.passaporte, true);',
'        apex_json.write(''data_aniversario'', p_rec.data_aniversario, true);',
'        apex_json.write(''data_integracao'', p_rec.data_integracao, true);',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'         pkg_traducao.grava_traducao(v_new.observacao,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.observacao,v_new.id_tenant,p_sucesso,p_messages,true,false);',
'        ajusta_vigencia_contato(',
'            p_id => v_new.id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages    ',
'        );',
'        ajusta_titulo_endereco(',
'            p_id => v_new.id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages    ',
'        );',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_pessoa_registro_em_uso(v_old.id_pessoa);',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        bo_ng_pessoa.exclui_registro(',
'            p_id => v_old.id_pessoa,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'        bo_ng_traducaotexto.exclui_registros(',
'            p_nome_entidade => ''ng_pessoa_fisica'',',
'            p_id_origem => v_old.id,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end; ',
'    --',
unistr('    -- Fun\00E7\00F5es complementares'),
'    --',
'    function detalhe_registro (',
'        p_id in ng_pessoa_fisica.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select ',
'                c.nome_fantasia as ng_pessoa$id_tenant,                ',
'                a.nome as ng_pessoa_fisica$nome, ',
'                a.nome_abreviado as ng_pessoa_fisica$nome_abreviado, ',
'                pkg_traducao.get_traducao(a.observacao) as ng_pessoa_fisica$observacao, ',
'                a.rg as ng_pessoa_fisica$rg, ',
'                a.cpf as ng_pessoa_fisica$cpf, ',
'                a.cnh as ng_pessoa_fisica$cnh, ',
'                a.passaporte as ng_pessoa_fisica$passaporte, ',
'                to_char(a.data_aniversario, ''dd/mm/yyyy'') as ng_pessoa_fisica$data_aniversario, ',
'                case',
'                    when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_cor_texto(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''))',
'                    else',
'                        to_char(b.data_fim_vigencia, ''dd/mm/yyyy'') ',
'                end as ng_pessoa$data_fim_vigencia',
'            from ng_pessoa_fisica a',
'            join ng_pessoa b on b.id = a.id_pessoa',
'            join mpd_tenant c on c.id = b.id_tenant',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --',
'    function sql_cabecalho_externo(p_param1 in varchar2 default null, p_param2 in varchar2 default null)',
'    return clob is  ',
'        l_nome_coluna varchar2(255);     ',
'        l_html clob;',
'    begin        ',
'        select lower(nome_coluna) into l_nome_coluna from srv_entidade_coluna where id = p_param2;',
'        l_html := to_clob(pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select ',
'                    b.''||l_nome_coluna||'',',
'                    pkg_traducao.get_traducao(d.descricao_idioma) as id_idioma',
'                from ng_pessoa a',
'                join ng_pessoa_fisica b on b.id_pessoa = a.id',
'                join mpd_tenant c on c.id = a.id_tenant',
'                join srv_idioma d on d.id = c.id_idioma ',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''ng_pessoa_fisica'',''mpd_tenant''),',
'            p_formato => ''pequeno'',',
'            --p_icones => textarray(/*''fa-database'', ''fa-database'',*/ ''fa-user'', ''fa-calendar fam-clock fam-is-success'', ''fa-calendar fam-clock fam-is-warning'', ''fa-flag''),',
unistr('            --p_label_fixo => textarray(''Workspace'', ''Aplica\00E7\00F5es'', ''P\00E1ginas'', ''Usu\00E1rios APEX''),'),
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        ));',
'        return l_html;',
'    end;',
'    --',
'    procedure ajusta_vigencia_contato(',
'        p_id in ng_pessoa_fisica.id%type,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_pessoa_contato number;   ',
'        l_verifica_vigencia_contato number;     ',
'        l_vigencia_contato varchar2(4000);',
'        l_controle number;                ',
'    begin ',
'        p_messages := pkg_mensagem.message_record_table();               ',
'        if v_new_pessoa.data_fim_vigencia is not null then',
'            select count(1) into l_verifica_vigencia_contato from ng_pessoa_contato a join ng_pessoa_fisica b on b.id_pessoa = a.id_pessoa where b.id = p_id and a.data_fim_vigencia is not null;',
unistr('            if l_verifica_vigencia_contato > 0 then -- n\00E3o \00E9 nulo'),
'                select a.data_fim_vigencia into l_vigencia_contato from ng_pessoa_contato a join ng_pessoa_fisica b on b.id_pessoa = a.id_pessoa where b.id = p_id;',
'                if to_date(l_vigencia_contato, ''dd/mm/yyyy'') > to_date(v_new_pessoa.data_fim_vigencia, ''dd/mm/yyyy'') then',
'                    l_controle := 1;',
'                end if;',
unistr('            else -- \00E9 nulo'),
'                l_controle := 1;',
'            end if;',
'        end if;',
'',
'        if l_controle = 1 then   ',
'            select a.id into l_id_pessoa_contato from ng_pessoa_contato a join ng_pessoa_fisica b on b.id_pessoa = a.id_pessoa where b.id = p_id;',
'            select * into v_new_pessoa_contato from ng_pessoa_contato where id = l_id_pessoa_contato;',
'            bo_ng_pessoa_contato.altera_registro(',
'                p_id_tenant => v_new_pessoa_contato.id_tenant,',
'                p_id_pessoa => v_new_pessoa_contato.id_pessoa,',
'                p_id_pessoa_fisica => v_new_pessoa_contato.id_pessoa_fisica,',
'                p_id_departamento => v_new_pessoa_contato.id_departamento,',
'                p_id_cargo => v_new_pessoa_contato.id_cargo,',
'                p_data_fim_vigencia => v_new_pessoa.data_fim_vigencia,',
'                p_data_integracao => v_new_pessoa_contato.data_integracao,',
'                p_id => v_new_pessoa_contato.id, ',
'                p_data_alteracao => v_new_pessoa_contato.data_alteracao,',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages                ',
'            );',
'        end if;        ',
'    end;',
'    --',
'    procedure ajusta_titulo_endereco(',
'        p_id in ng_pessoa_fisica.id%type,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
