'        p_messages := pkg_mensagem.message_record_table(); ',
'        select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_id;',
'        for endereco in (',
'            select * from ng_pessoa_endereco where id_pessoa = l_id_pessoa',
'        ) loop',
'            bo_ng_pessoa_endereco.altera_registro(',
'                p_id_tenant => endereco.id_tenant,',
'                p_id_pessoa => endereco.id_pessoa,',
'                p_titulo_endereco => endereco.titulo_endereco, ',
'                p_codigo_postal => endereco.codigo_postal,',
'                p_id_pais => endereco.id_pais,',
'                p_id_estado => endereco.id_estado,',
'                p_id_cidade => endereco.id_cidade,',
'                p_bairro => ende'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(154769275206507221)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'reco.bairro,',
'                p_logradouro => endereco.logradouro,',
'                p_numero => endereco.numero,',
'                p_complemento => endereco.complemento,',
'                p_etiqueta_endereco => endereco.etiqueta_endereco,',
'                p_ind_endereco_principal => endereco.ind_endereco_principal,',
'                p_data_integracao => endereco.data_integracao,',
'                p_id => endereco.id,',
'                p_data_alteracao => endereco.data_alteracao,            ',
'                p_encadeado => true,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;        ',
'    end;',
'    --',
'    procedure inclui_pessoa_fisica(',
'        p_id_tenant in ng_pessoa_fisica.id_tenant%type,',
'        p_nome in ng_pessoa_fisica.nome%type,',
'        p_nome_abreviado in ng_pessoa_fisica.nome_abreviado%type,',
'        p_observacao in ng_pessoa_fisica.observacao%type,',
'        p_rg in ng_pessoa_fisica.rg%type,',
'        p_cpf in ng_pessoa_fisica.cpf%type,',
'        p_cnh in ng_pessoa_fisica.cnh%type,',
'        p_passaporte in ng_pessoa_fisica.passaporte%type,',
'        p_data_aniversario in ng_pessoa_fisica.data_aniversario%type,',
'        p_data_integracao in ng_pessoa_fisica.data_integracao%type,',
'        p_data_fim_vigencia in ng_pessoa.data_fim_vigencia%type,',
'        p_id out ng_pessoa_fisica.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_pessoa_contato number;',
'    begin',
'        v_parametro(0) := ''bo_ng_pessoa_fisica.inclui_pessoa_fisica'';   ',
'        v_pagina := p_pagina;',
'',
'        -- Cria o registro em ng_pessoa:',
'        bo_ng_pessoa.inclui_registro(',
'            p_id_tenant => p_id_tenant,',
'            p_nome_completo => p_nome,',
'            p_nome_resumido => p_nome_abreviado,',
'            p_data_integracao => p_data_integracao,',
'            p_data_fim_vigencia => p_data_fim_vigencia,',
'            p_id => v_new_pessoa.id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        if v_new_pessoa.id is not null then',
'            -- Cria o registro em ng_pessoa_contato:',
'            bo_ng_pessoa_contato.inclui_registro(',
'                p_id_pessoa => v_new_pessoa.id,',
'                p_id_pessoa_fisica => v_new_pessoa.id,',
'                p_id_departamento => null,',
'                p_id_cargo => null,',
'                p_data_fim_vigencia => p_data_fim_vigencia,',
'                p_data_integracao => p_data_integracao,',
'                p_id_tenant => p_id_tenant,',
'                p_id => l_id_pessoa_contato,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'',
'            v_new.id_tenant := p_id_tenant; ',
'            v_new.id_pessoa := v_new_pessoa.id;',
'            v_new.nome := p_nome;',
'            v_new.nome_abreviado := p_nome_abreviado;',
'            v_new.observacao := p_observacao;',
'            v_new.rg := p_rg;',
'            v_new.cpf := p_cpf;',
'            v_new.cnh := p_cnh;',
'            v_new.passaporte := p_passaporte;',
'            v_new.data_aniversario := p_data_aniversario;',
'            v_new.data_integracao := p_data_integracao;        ',
'            v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'            v_new.data_inclusao := sysdate; ',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'            v_new.data_alteracao := sysdate; ',
'',
'            v_operacao := ''INCLUI_PESSOA_FISICA'';',
'            cria(p_encadeado,p_sucesso,p_messages,p_id);',
'        end if;',
'',
'    end inclui_pessoa_fisica;',
'    --',
'    procedure altera_pessoa_fisica(',
'        p_id_tenant in ng_pessoa_fisica.id_tenant%type,        ',
'        p_nome in ng_pessoa_fisica.nome%type,',
'        p_nome_abreviado in ng_pessoa_fisica.nome_abreviado%type,',
'        p_observacao in ng_pessoa_fisica.observacao%type,',
'        p_rg in ng_pessoa_fisica.rg%type,',
'        p_cpf in ng_pessoa_fisica.cpf%type,',
'        p_cnh in ng_pessoa_fisica.cnh%type,',
'        p_passaporte in ng_pessoa_fisica.passaporte%type,',
'        p_data_aniversario in ng_pessoa_fisica.data_aniversario%type,',
'        p_data_integracao in ng_pessoa_fisica.data_integracao%type,        ',
'        p_data_fim_vigencia in ng_pessoa.data_fim_vigencia%type,',
'        p_id in ng_pessoa_fisica.id%type, ',
'        p_data_alteracao in ng_pessoa_fisica.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is         ',
'    begin        ',
'        v_parametro(0) := ''bo_ng_pessoa_fisica.altera_pessoa_fisica'';   ',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from ng_pessoa_fisica where id = p_id;        ',
'        v_new := v_old;',
'',
'        -- Altera o registro em ng_pessoa:        ',
'        bo_ng_pessoa.altera_registro(',
'            p_id_tenant => p_id_tenant,',
'            p_nome_completo => p_nome,',
'            p_nome_resumido => p_nome_abreviado,',
'            p_data_integracao => p_data_integracao,',
'            p_data_fim_vigencia => p_data_fim_vigencia,',
'            p_id => v_new.id_pessoa,',
'            p_data_alteracao => p_data_alteracao,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        if p_id_tenant is not null then',
'            v_new.nome := p_nome;',
'            v_new.nome_abreviado := p_nome_abreviado;',
'            v_new.observacao := p_observacao;',
'            v_new.rg := p_rg;',
'            v_new.cpf := p_cpf;',
'            v_new.cnh := p_cnh;',
'            v_new.passaporte := p_passaporte;',
'            v_new.data_aniversario := p_data_aniversario;',
'            v_new.data_integracao := p_data_integracao;',
'            v_new.id_tenant := p_id_tenant; ',
'            v_new.id := p_id; ',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'            v_new.data_alteracao := sysdate;  ',
'',
'            v_operacao := ''ALTERA_PESSOA_FISICA'';',
'            grava(p_id,p_encadeado,p_sucesso,p_messages);',
'        end if;',
'',
'    end altera_pessoa_fisica;',
'    --',
'    procedure verifica_pessoa_registro_em_uso( ',
'        p_id_pessoa in ng_pessoa_fisica.id_pessoa%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''ng_pessoa'', p_id_pessoa) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''ng_pessoa'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end verifica_pessoa_registro_em_uso;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_pessoa_fisica;',
'/'))
);
end;
