prompt --application/deployment/install/install_ui_mpd_td933
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(154769617455473871)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD933'
,p_sequence=>520
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD933',
'-- Data: 24/04/2026',
unistr('-- Motivo: Altera\00E7\00E3o nome de coluna'),
'-- Jira: PEDITEM-254',
'',
'create or replace package "UI_MPD_TD933" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'',
'end "UI_MPD_TD933";',
'/',
'',
'create or replace package body "UI_MPD_TD933" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    b.num_invoice id_invoice,                    ',
'                    a.numero_parcela                ',
'                from imp_invoice_pagamento a',
'                join imp_invoice b on b.id = a.id_invoice',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice_pagamento'', ''imp_invoice_pagamento''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is        ',
'    begin        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_invoice'',                  2, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entrega'',                  3, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_parcela'',              4, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''percentual'',                  5,    '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor'',                       6,    '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento_prevista'',    7,    '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento_real'',        8, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pagamento'',        9, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_multa_atraso_pagamento'', 10,    '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_multa'',                11,    '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_compensado'',           12, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''percentual_multa'',           13,    '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''periodo_multa'',              14,    '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_bloqueado'',              15, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''condicao_desbloqueio'',       16, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_desbloqueio'',           17, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_desbloqueio'',     18, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL     ',
'               SELECT p_codigo_artefato, ''instrucao_contas_pagar'',     19, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL          ',
'               SELECT p_codigo_artefato, ''data_alteracao'',             20, ''HID'', null, ''S'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'        l_valor_multa imp_pedidoimportacao_pagamento.valor_multa%type;',
'        l_percentual_multa imp_pedidoimportacao_pagamento.percentual_multa%type;',
'        l_periodo_multa imp_pedidoimportacao_pagamento.periodo_multa%type;',
'    begin',
'        if apex_application.g_f10(1) = ''S'' then',
'            l_valor_multa := pkg_util.retorna_number(apex_application.g_f11(1));',
'            l_percentual_multa := pkg_util.retorna_number(apex_application.g_f13(1));',
'            l_periodo_multa := apex_application.g_f14(1);',
'        end if;',
'',
'        bo_imp_invoice_pagamento.altera_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_invoice => apex_application.g_f02(1),',
'            p_id_entrega => apex_application.g_f03(1),            ',
'            p_numero_parcela => apex_application.g_f04(1),            ',
'            p_percentual => pkg_util.retorna_number(apex_application.g_f05(1)),',
'            p_valor => pkg_util.retorna_number(apex_application.g_f06(1)),',
'            p_data_vencimento_prevista => apex_application.g_f07(1),',
'            p_data_vencimento_real => apex_application.g_f08(1),',
'            p_ind_status_pagamento => apex_application.g_f09(1),',
'            p_ind_multa_atraso_pagamento => apex_application.g_f10(1),',
'            p_valor_multa => l_valor_multa,',
'            p_valor_compensado => pkg_util.retorna_number(apex_application.g_f12(1)),',
'            p_percentual_multa => l_percentual_multa,',
'            p_periodo_multa => l_periodo_multa, ',
'            p_ind_bloqueado => apex_application.g_f15(1),',
'            p_condicao_desbloqueio => apex_application.g_f16(1),',
'            p_data_desbloqueio => apex_application.g_f17(1),',
'            p_id_usuario_desbloqueio => apex_application.g_f18(1),                        ',
'            p_instrucao_contas_pagar => apex_application.g_f19(1),',
'            p_data_alteracao => to_timestamp(apex_application.g_f20(1), ''dd-mon-rr hh:mi:ss:ff am''),',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD933";',
'/'))
);
end;
/
