prompt --application/deployment/install/install_ui_mpd_td1017
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155755225918298332)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1017'
,p_sequence=>540
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Northonn Oliveira',
'-- Jira: ',
'create or replace package "UI_MPD_TD1017" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'end "UI_MPD_TD1017";',
'/',
'create or replace package body "UI_MPD_TD1017" as',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'        l_label_titulo varchar2(4000);',
'        l_label_subtitulo varchar2(4000);',
'        l_label_distintivo varchar2(4000);        ',
'    begin   ',
'        l_label_titulo := pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'');',
'        l_label_subtitulo := pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'');',
'        l_label_distintivo := pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'');',
'        l_sql := q''~',
'            select ',
'               a.id_log id,',
'               null id_tenant,',
'               bo_srv_entidade.retorna_nome_leitura_bo(a.nm_modulo) titulo,',
'               a.nm_rotina subtitulo,',
'               null distintivo,',
'               a.ds_mensagem ajuda,',
'               ''u-hidden'' class_distintivo,',
'               a.tp_evento filtro1,',
'               a.id_usuario filtro2,',
'               a.nm_modulo filtro3,',
'               a.nm_rotina filtro4,',
'               a.num_sessao_apex filtro5,',
'               ''#LABEL_TITULO#''  label_titulo,',
'               ''#LABEL_SUBTITULO#''  label_subtitulo,',
'               ''#LABEL_DISTINTIVO#'' label_distintivo,               ',
'               a.dt_log data_inclusao,',
'               null nome_aplicacao, ',
'               case ',
'                   when upper(a.tp_evento) = ''ERRO'' then',
'                       ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-danger fa fa-times-circle" aria-hidden="true"></span></div>''',
'                   when upper(a.tp_evento) = ''FIM'' then',
'                       ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-success fa fa-check-circle" aria-hidden="true"></span></div>''',
'                   else',
'                       ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-warning fa fa-play-circle" aria-hidden="true"></span></div>''',
'               end icon,',
'               pkg_componentes.html_card_colunas(',
'                    ''sis_log_execucao.id_transacao_oracle'',',
'                    a.id_transacao_oracle,',
'                    4',
'               ) as atributo1,',
'               pkg_componentes.html_card_colunas(',
'                    ''sis_log_execucao.dt_log'',',
'                    pkg_data.fmt(a.dt_log,''DATA_SEGUNDO''),',
'                    4',
'               ) as atributo2,',
'               pkg_componentes.html_card_colunas(',
'                    ''sis_log_execucao.nm_usuario'',',
'                    a.nm_usuario,',
'                    4',
'               ) as atributo3,',
'               null lista_distintivo,',
'               pkg_ui.url_mais_detalhes(''TD1017'',a.id_log) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(a.id_log,''TD1017'') as opcao                ',
'            from (',
'                select a.*,',
'                       row_number() over (',
'                           partition by a.id_transacao_oracle',
'                           order by a.dt_log',
'                       ) rn',
'                  from sis_log_execucao a',
'            ) a',
'            where a.rn = 1',
'            order by dt_log desc',
'            ~'';',
'        l_sql := replace(l_sql, ''#LABEL_TITULO#'', l_label_titulo);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO#'', l_label_subtitulo);',
'        l_sql := replace(l_sql, ''#LABEL_DISTINTIVO#'', l_label_distintivo);',
'',
'        l_sql := replace(l_sql,''#PARAM4#'',aspas(nvl(p_param4,''S''))); ',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_param3,''1 desc''));',
'',
'        return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id_log id,',
'            a.id_transacao_oracle campo1,',
'            pkg_data.fmt(a.dt_log,''DATA_SEGUNDO'') campo2,',
'            a.nm_usuario campo3,',
'            bo_srv_entidade.retorna_nome_leitura_bo(a.nm_modulo) campo4,',
'            a.nm_rotina campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            dt_log campo10,',
'            a.tp_evento filtro1,',
'            a.id_usuario filtro2,',
'            a.nm_modulo filtro3,',
'            a.nm_rotina filtro4,',
'            a.num_sessao_apex filtro5,',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                  ',
'            null opcao',
'            from (',
'                select a.*,',
'                       row_number() over (',
'                           partition by a.id_transacao_oracle',
'                           order by a.dt_log',
'                       ) rn',
'                  from sis_log_execucao a',
'            ) a',
'            where a.rn = 1',
'            order by dt_log desc',
'        ~'';   ',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin   ',
'        return q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD1017'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''sis_log_execucao'')) a',
'            order by campo10 desc',
'            ~'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        if campo = ''1'' then      ',
'            return q''~',
'                select distinct tp_evento d, tp_evento r',
'                  from sis_log_execucao',
'                 where tp_evento is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select distinct nm_usuario d, id_usuario r',
'                  from sis_log_execucao',
'                 where id_usuario is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''3'' then',
'            return q''~',
'                select distinct bo_srv_entidade.retorna_nome_leitura_bo(nm_modulo) d, nm_modulo r',
'                  from sis_log_execucao',
'                 where nm_modulo is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''4'' then',
'            return q''~',
'                select distinct nm_rotina d, nm_rotina r',
'                  from sis_log_execucao',
'                 where nm_rotina is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''5'' then',
'            return q''~',
'                select distinct num_sessao_apex d, num_sessao_apex r',
'                  from sis_log_execucao',
'                 where num_sessao_apex is not null',
'                 order by 1',
'            ~'';',
'        else',
'            return null;        ',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.id_transacao_oracle'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.dt_log'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_usuario'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'') into l_campo from dual;',
'        elsif campo = ''F1'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'') into l_campo from dual;',
'        elsif campo = ''F2'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.id_usuario'') into l_campo from dual;',
'        elsif campo = ''F3'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'') into l_campo from dual;',
'        elsif campo = ''F4'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'') into l_campo from dual;',
'        elsif campo = ''F5'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.num_sessao_apex'') into l_campo from dual;',
'        end if;',
'',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    ) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''dt_log desc,nm_modulo,nm_rotina,tp_evento'';',
'        else',
'            campos := ''campo5 desc,campo3,campo4,campo1'';',
'        end if;',
'',
'        select pkg_ui.retorna_label_coluna(''sis_log_execucao.dt_log'') || '','' ||',
'               pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'') || '','' ||',
'               pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'') || '','' ||',
'               pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'')',
'          into labels',
'          from dual;',
'    end campos_ordenacao;  ',
'',
'end "UI_MPD_TD1017";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1018
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155768003607762750)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1018'
,p_sequence=>550
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD1018" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_tree(p_param1 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'end "UI_MPD_TD1018";',
'/',
'create or replace package body "UI_MPD_TD1018" as',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'        l_label_titulo varchar2(4000);',
'        l_label_subtitulo varchar2(4000);',
'        l_label_distintivo varchar2(4000);        ',
'        l_id_transacao_oracle varchar2(4000);',
'    begin   ',
'        l_label_titulo := pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'');',
'        l_label_subtitulo := pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'');',
'        l_label_distintivo := pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'');',
'        select max(id_transacao_oracle) into l_id_transacao_oracle from sis_log_execucao where id_log = p_param1;',
'        l_sql := q''~',
'            select ',
'               a.id_log id,',
'               null id_tenant,',
'               bo_srv_entidade.retorna_nome_leitura_bo(a.nm_modulo)||'' (''||id_log||'')'' titulo,',
'               a.nm_rotina subtitulo,',
'               a.tp_evento distintivo,',
'               a.ds_mensagem ajuda,',
'               case ',
'                   when upper(a.tp_evento) = ''ERRO'' then ''u-danger''',
'                   when upper(a.tp_evento) = ''FIM'' then ''u-success''',
'                   else ''u-warning''',
'               end class_distintivo,',
'               a.tp_evento filtro1,',
'               a.id_usuario filtro2,',
'               a.nm_modulo filtro3,',
'               a.nm_rotina filtro4,',
'               a.num_sessao_apex filtro5,',
'               ''#LABEL_TITULO#''  label_titulo,',
'               ''#LABEL_SUBTITULO#''  label_subtitulo,',
'               ''#LABEL_DISTINTIVO#'' label_distintivo,               ',
'               a.dt_log data_inclusao,',
'               null nome_aplicacao, ',
'               case ',
'                   when upper(a.tp_evento) = ''ERRO'' then',
'                       ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-danger fa fa-times-circle" aria-hidden="true"></span></div>''',
'                   when upper(a.tp_evento) = ''FIM'' then',
'                       ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-success fa fa-check-circle" aria-hidden="true"></span></div>''',
'                   else',
'                       ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start"><span class="a-CardView-icon u-warning fa fa-play-circle" aria-hidden="true"></span></div>''',
'               end icon,',
'               pkg_componentes.html_card_colunas(',
'                    ''sis_log_execucao.dt_log'',',
'                    pkg_data.fmt(a.dt_log,''DATA_MILESIMO''),',
'                    2',
'               ) as atributo1,',
'               pkg_componentes.html_card_colunas(',
'                    ''sis_log_execucao.ds_mensagem'',',
'                    a.ds_mensagem,',
'                    5',
'               ) as atributo2,',
'               pkg_componentes.html_card_colunas(',
'                    ''sis_log_execucao.ds_erro'',',
'                    a.ds_erro,',
'                    5',
'               ) as atributo3,',
'               null lista_distintivo,',
'               pkg_ui.url_mais_detalhes(''TD1017'',a.id_log) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(a.id_log,''TD1017'') as opcao                ',
'            from sis_log_execucao a',
'            where id_transacao_oracle = #PARAM#',
'            order by id_log ',
'            ~'';',
'        l_sql := replace(l_sql, ''#LABEL_TITULO#'', l_label_titulo);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO#'', l_label_subtitulo);',
'        l_sql := replace(l_sql, ''#LABEL_DISTINTIVO#'', l_label_distintivo);',
'',
'        l_sql := replace(l_sql,''#PARAM#'',aspas(l_id_transacao_oracle)); ',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_param3,''1 desc''));',
'',
'        grava_log2(''UI_MPD_TD1017 l_sql:''||l_sql);',
'        return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'        l_id_transacao_oracle varchar2(4000);',
'    begin   ',
'        select max(id_transacao_oracle) into l_id_transacao_oracle from sis_log_execucao where id_log = p_param1;',
'        l_sql := q''~',
'        select ',
'            a.id_log id,',
'            bo_srv_entidade.retorna_nome_leitura_bo(a.nm_modulo)||'' (''||id_log||'')'' campo1,',
'            a.nm_rotina campo2,',
'            a.tp_evento campo3,',
'            pkg_data.fmt(a.dt_log,''DATA_MILESIMO'') campo4,',
'            ds_mensagem campo5,',
'            ds_erro campo6,',
'            ds_erro campo7,',
'            null campo8,',
'            null campo9,',
'            dt_log campo10,',
'            a.tp_evento filtro1,',
'            a.id_usuario filtro2,',
'            a.nm_modulo filtro3,',
'            a.nm_rotina filtro4,',
'            a.num_sessao_apex filtro5,',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                  ',
'            null opcao',
'            from sis_log_execucao a',
'            where id_transacao_oracle = #PARAM#',
'            order by id_log ',
'        ~'';   ',
'        l_sql := replace(l_sql,''#PARAM#'',aspas(l_id_transacao_oracle)); ',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin   ',
'        return q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD1017'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''sis_log_execucao'')) a',
'            order by campo10 desc',
'            ~'';',
'    end sql_report;',
'',
'    function sql_tree(p_param1 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select id,',
'                   titulo,',
'                   id_menu_pai chave_pai',
'              from srv_menu',
'              order by ordenacao            ',
'        ~'';',
'        -- return replace(l_sql,''#CODIGO_ARTEFAT'',p_codigo_artefato);',
'        return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_tree;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        if campo = ''1'' then      ',
'            return q''~',
'                select distinct tp_evento d, tp_evento r',
'                  from sis_log_execucao',
'                 where tp_evento is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select distinct nm_usuario d, id_usuario r',
'                  from sis_log_execucao',
'                 where id_usuario is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''3'' then',
'            return q''~',
'                select distinct bo_srv_entidade.retorna_nome_leitura_bo(nm_modulo) d, nm_modulo r',
'                  from sis_log_execucao',
'                 where nm_modulo is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''4'' then',
'            return q''~',
'                select distinct nm_rotina d, nm_rotina r',
'                  from sis_log_execucao',
'                 where nm_rotina is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''5'' then',
'            return q''~',
'                select distinct num_sessao_apex d, num_sessao_apex r',
'                  from sis_log_execucao',
'                 where num_sessao_apex is not null',
'                 order by 1',
'            ~'';',
'        else',
'            return null;        ',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.dt_log'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.ds_mensagem'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.ds_erro'') into l_campo from dual;',
'        elsif campo = ''F1'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'') into l_campo from dual;',
'        elsif campo = ''F2'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.id_usuario'') into l_campo from dual;',
'        elsif campo = ''F3'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'') into l_campo from dual;',
'        elsif campo = ''F4'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'') into l_campo from dual;',
'        elsif campo = ''F5'' then',
'            select pkg_ui.retorna_label_coluna(''sis_log_execucao.num_sessao_apex'') into l_campo from dual;',
'        end if;',
'',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    ) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''dt_log desc,nm_modulo,nm_rotina,tp_evento'';',
'        else',
'            campos := ''campo5 desc,campo3,campo4,campo1'';',
'        end if;',
'',
'        select pkg_ui.retorna_label_coluna(''sis_log_execucao.dt_log'') || '','' ||',
'               pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_modulo'') || '','' ||',
'               pkg_ui.retorna_label_coluna(''sis_log_execucao.nm_rotina'') || '','' ||',
'               pkg_ui.retorna_label_coluna(''sis_log_execucao.tp_evento'')',
'          into labels',
'          from dual;',
'    end campos_ordenacao;  ',
'',
'end "UI_MPD_TD1018";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1019
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155768722847757568)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1019'
,p_sequence=>560
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD1019" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'end "UI_MPD_TD1019";',
'/',
'create or replace package body "UI_MPD_TD1019" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'               a.id,',
'               a.usuario titulo,',
'               a.perfil subtitulo,',
'               a.id distintivo,',
'               null class_distintivo,',
'',
'               null filtro1,',
'               null filtro2,',
'               null filtro3,',
'               null filtro4,',
'               null filtro5,',
'               null filtro6,',
'               null filtro7,',
'',
'               pkg_ui.retorna_label_coluna(''mae_admin_operador.usuario'') label_titulo,',
'               pkg_ui.retorna_label_coluna(''mae_admin_operador.perfil'') label_subtitulo,',
'               pkg_ui.retorna_label_coluna(''mae_admin_operador.id'') label_distintivo,',
'',
'               case when a.ativo = ''S'' then  ',
'                   ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">',
'                        <span class="a-CardView-icon u-color fa fa-check" aria-hidden="true" title="Ativo"></span>',
'                    </div>''',
'               else ',
'                   ''<div class="a-CardView-iconWrap a-CardView-iconWrap--start">',
'                        <span class="a-CardView-icon u-color fa fa-ban" aria-hidden="true" title="Inativo"></span>',
'                    </div>''',
'               end icon,',
'',
'               pkg_componentes.html_card_colunas(',
'                    ''mae_admin_operador.ativo'',',
'                    pkg_util.dominio_retorna_tag(''mae_admin_operador'',''ativo'',a.ativo),',
'                    4',
'               ) as atributo1,',
'',
'               pkg_componentes.html_card_colunas(',
'                    ''mae_admin_operador.data_inclusao'',',
'                    pkg_data.fmt(a.data_inclusao,''DATA_MINUTO''),',
'                    4',
'               ) as atributo2,',
'',
'               null as atributo3,',
'',
'               null lista_distintivo,',
'               pkg_ui.url_mais_detalhes(''TD1019'',a.id) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(a.id,''TD1019'') as opcao                ',
'',
'            from mae_admin_operador a',
'            ~'';',
'',
'            return l_sql;',
'          ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'               a.id,',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''ind_execucao_assincrona'',ind_execucao_assincrona) campo1,',
'               plsql_entrypoint campo2,',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''modo_bloqueio_falha'',modo_bloqueio_falha) campo3,',
'               prioridade_padrao campo4,               ',
'               delay_execucao_seg campo5,      ',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''estrategia_retry'',estrategia_retry) campo6,      ',
'               pkg_util.dominio_retorna_tag(''srv_artefato_cfg'',''ind_coalescencia'',ind_coalescencia) campo7,      ',
'               null campo8,',
'               null campo9,',
'               null campo10,',
'               null filtro1,',
'               null filtro2,',
'               null filtro3,',
'               null filtro4,',
'               null filtro5,',
'               null filtro6,',
'               null filtro7,',
'               null filtro_mult1,                                ',
'               null filtro_mult2,                                ',
'               null filtro_mult3, ',
'               null filtro_mult4,                                ',
'               null filtro_mult5,                                  ',
'               null opcao                ',
'            from srv_artefato_cfg a',
'            join srv_artefato b on b.id = a.id_artefato',
'            where a.id_artefato = #PARAM1#',
'        ~'';   ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin   ',
'        return q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD1009'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''srv_artefato'')) a',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_execucao_assincrona'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.plsql_entrypoint'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.modo_bloqueio_falha'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.prioridade_padrao'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.delay_execucao_seg'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.estrategia_retry'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''srv_artefato_cfg.ind_coalescencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''nome_artefato,descricao_artefato,codigo_artefato'';',
'        else',
'            campos := ''campo4,campo1,campo2'';',
'        end if;',
'        select pkg_ui.retorna_label_coluna(''srv_artefato.nome_artefato'') || '','' ||',
'           pkg_ui.retorna_label_coluna(''srv_artefato.descricao_artefato'') || '','' ||',
'           pkg_ui.retorna_label_coluna(''srv_artefato.codigo_artefato'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'end "UI_MPD_TD1019";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1037
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155776149115662273)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1037'
,p_sequence=>570
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD1037" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob;',
'',
'    function sql_report(',
'        p_order in varchar2',
'    ) return clob;',
'',
'    function sql_filtro(',
'        campo in varchar2',
'    ) return clob;',
'',
'    function sql_verifica_filtro(',
'        campo in varchar2',
'    ) return boolean;',
'',
'    function label_coluna(',
'        campo in varchar',
'    ) return clob;',
'',
'    function ordenacao',
'    return varchar2;',
'',
'    function default_ordenacao',
'    return varchar2;',
'',
'end "UI_MPD_TD1037";',
'/',
'create or replace package body "UI_MPD_TD1037" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    b.nome_artefato as nome_artefato,',
'                    a.intervalo_segundos,',
'                    c.delay_execucao_seg,',
'                    pkg_util.dominio_retorna_tag(''''srv_artefato_cfg'''',''''ind_coalescencia'''',ind_coalescencia) as ind_coalescencia ',
'                from mae_sched_cfg a',
'                join srv_artefato b on b.id = a.id_artefato',
'                join srv_artefato_cfg c on c.id_artefato = b.id',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''srv_artefato'',''mae_sched_cfg'',''srv_artefato_cfg'',''srv_artefato_cfg''),',
'            -- p_tabela => textarray(''srv_artefato'',''imp_processoimportacao'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql                 clob;',
'        l_id_idioma           number;',
'        l_label_titulo        varchar2(4000);',
'        l_label_titulo1       varchar2(4000);',
'        l_label_subtitulo1     varchar2(4000);',
'        l_label_subtitulo2     varchar2(4000);',
'        l_label_subtitulo3     varchar2(4000);',
'        l_label_distintivo    varchar2(4000);',
'        l_label_atributo1     varchar2(4000);',
'        l_label_atributo2     varchar2(4000);',
'        l_label_atributo3     varchar2(4000);',
'        l_label_atributo4     varchar2(4000);',
'        l_label_atributo5     varchar2(4000);',
'        l_id_artefato         number;',
'    begin',
'        select id_artefato into l_id_artefato from mae_sched_cfg where id = p_param1;',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'',
'        l_label_titulo     := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id'');',
'        l_label_titulo1    := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.dt_disponivel_execucao'');',
'        l_label_subtitulo1 := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_correlation'');',
'        l_label_subtitulo2 := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_negocio'');',
'        l_label_subtitulo3 := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.tentativas'');',
'',
'        l_label_distintivo := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.status'');',
'',
'        l_label_atributo1  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.dt_criacao'');',
'        l_label_atributo2  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.dt_inicio'');',
'        l_label_atributo3  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.dt_fim'');',
'        l_label_atributo4  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.motivo_falha'');',
'        -- l_label_atributo3  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.prioridade'');',
'        -- l_label_atributo4  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.tentativas'');',
'        -- l_label_atributo5  := pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_negocio'');',
'',
'        l_sql := q''~',
'            select',
'                a.id,',
unistr('                ''#LABEL_TITULO# #''|| a.id ||'' \2022 #LABEL_TITULO1#: ''|| pkg_data.fmt(a.dt_disponivel_execucao,''DATA_SEGUNDO'')  titulo,'),
unistr('                ''#LABEL_SUBTITULO1#: ''|| a.id_correlation ||'' \2022 ''||''#LABEL_SUBTITULO2#: ''|| nvl(a.id_negocio,''Nenhum'') ||'' \2022 ''||''#LABEL_SUBTITULO3#: ''|| tentativas ||'' \2022 Coalesceu: ''||(select count(1) from mae_registro_tecnico a1 where a1.id_solicita')
||'cao = a.id and tipo_evento = ''COALESCE_UPDATE'')  subtitulo,',
'',
'                ''#LABEL_TITULO#'' label_titulo,',
'                ''#LABEL_SUBTITULO#'' label_subtitulo,',
'                ''#LABEL_DISTINTIVO#'' label_distintivo,',
'',
'                case',
'                    when a.status = ''SUCESSO'' then pkg_componentes.html_icone_lista(''fa-check-circle-o'',''u-success'')',
'                    when a.status in (''FALHA_NEGOCIO'',''FALHA_TECNICA'',''ERRO_FINAL'',''CANCELADO'',''EXPIRADO'') then pkg_componentes.html_icone_lista(''fa-exclamation-triangle'',''u-danger'')',
'                    when a.status = ''EM_PROCESSAMENTO'' then pkg_componentes.html_icone_lista(''fa-cog'',''u-warning'')',
'                    when a.status = ''BLOQUEADA'' then pkg_componentes.html_icone_lista(''fa-lock'')',
'                    else pkg_componentes.html_icone_lista(''fa-clock-o'',''u-info'')',
'                end icon,',
'',
'                a.status distintivo,',
'                case',
'                    when a.status = ''SUCESSO'' then ''u-success''',
'                    when a.status in (''FALHA_NEGOCIO'',''FALHA_TECNICA'',''ERRO_FINAL'',''CANCELADO'',''EXPIRADO'') then ''u-danger''',
'                    when a.status = ''EM_PROCESSAMENTO'' then ''u-warning''',
'                    when a.status = ''BLOQUEADA'' then ''u-info''',
'                    else null',
'                end class_distintivo,',
'                null lista_distintivo,',
'',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO1#'', pkg_data.fmtd(a.dt_criacao,''DATA_SEGUNDO''), 2, ''S'') atributo1,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO2#'', pkg_data.fmtd(a.dt_inicio,''DATA_SEGUNDO''), 2, ''S'') atributo2,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO3#'', pkg_data.fmtd(a.dt_fim,''DATA_SEGUNDO''), 2, ''S'') atributo3,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO4#'', motivo_falha, 4, ''S'') atributo4,',
unistr('                pkg_componentes.html_card_colunas(''JOB em execu\00E7\00E3o'', (select job_name from user_scheduler_jobs where upper(job_name) = upper(''job_mae_req_''||a.id)) , 2, ''S'') atributo5,'),
'',
'                ',
'',
'                -- pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO4#'', a.tentativas, 2, ''S'') atributo4,',
'',
'                -- FILTROS',
'                a.id_tenant filtro1,',
'                a.status filtro2,',
'                a.id_artefato filtro3,',
'                a.id_usuario filtro4,',
'                a.id_worker filtro5,',
'                null filtro6,',
'                null filtro_mult1,',
'                null filtro_mult2,',
'',
unistr('                -- ORDENA\00C7\00C3O'),
'                case',
'                    when a.status in (''PENDENTE'',''EM_PROCESSAMENTO'',''BLOQUEADA'') then 1',
'                    else 2',
'                end order1,',
'                a.prioridade order2,',
'                a.dt_criacao order3,',
'',
unistr('                -- T\00C9CNICO'),
'                pkg_ui.url_mais_detalhes(''TD1037'', a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id, ''TD1037'') opcao',
'            from mae_solicitacao_execucao a',
'            left join srv_artefato b',
'              on b.id = a.id_artefato',
'            where #condicao# and #condicao1#',
'            order by dt_criacao desc',
'        ~'';',
'',
'        l_sql := replace(l_sql,''#condicao#'',''id_artefato = ''||l_id_artefato);',
'        if p_param4 is not null then',
'            l_sql := replace(l_sql,''#condicao1#'',''a.status in (''||fn_trata_lista_in(p_param4)||'')'');',
'        else',
'            l_sql := replace(l_sql,''#condicao1#'',''1 = 1'');',
'        end if;',
'',
'        l_sql := replace(l_sql, ''#LABEL_TITULO#'', l_label_titulo);',
'        l_sql := replace(l_sql, ''#LABEL_TITULO1#'', l_label_titulo1);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO1#'', l_label_subtitulo1);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO2#'', l_label_subtitulo2);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO3#'', l_label_subtitulo3);',
'        l_sql := replace(l_sql, ''#LABEL_DISTINTIVO#'', l_label_distintivo);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO1#'', l_label_atributo1);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO2#'', l_label_atributo2);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO3#'', l_label_atributo3);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO4#'', l_label_atributo4);',
'        l_sql := replace(l_sql, ''#LABEL_ATRIBUTO5#'', l_label_atributo5);',
'',
'        return l_sql;',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql       clob;',
'        l_id_idioma number;',
'    begin',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'',
'        l_sql := q''~',
'            select',
'                a.id id,',
'                a.id campo1,',
'                b.nome_artefato campo2,',
'                a.tipo_acao campo3,',
'                a.status campo4,',
'                a.prioridade campo5,',
'                pkf_data.fmtd(a.dt_criacao, ''DATA_SEGUNDO'') campo6,',
'                pkf_data.fmt(cast(a.dt_disponivel_execucao as timestamp), ''DATA_SEGUNDO'') campo7,',
'                a.tentativas campo8,',
'                a.id_negocio campo9,',
'                a.id_correlation campo10,',
'',
'                -- FILTROS',
'                a.id_tenant filtro1,',
'                a.status filtro2,',
'                a.id_artefato filtro3,',
'                a.id_usuario filtro4,',
'                a.id_worker filtro5,',
'                null filtro6,',
'                null filtro_mult1,',
'                null filtro_mult2,',
'                null filtro_mult3,',
'                null filtro_mult4,',
'                null filtro_mult5,',
'                null opcao',
'            from mae_solicitacao_execucao a',
'            join srv_artefato b',
'              on b.id = a.id_artefato',
'            where #condicao1#',
'            order by dt_criacao desc',
'        ~'';',
'',
'        if p_param4 is not null then',
'            l_sql := replace(l_sql,''#condicao1#'',''a.status in (''||fn_trata_lista_in(p_param4)||'')'');',
'        else',
'            l_sql := replace(l_sql,''#condicao1#'',''1 = 1'');',
'        end if;',
'',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql       clob;',
'        l_region_id number;',
'    begin',
'        select region_id',
'          into l_region_id',
'          from apex_application_page_regions',
'         where application_id = v(''APP_ID'')',
'           and page_id        = v(''APP_PAGE_ID'')',
'           and static_id      = ''LISTA_CR'';',
'',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD1037'') as opcao',
'            from table(pkg_ui.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''mae_solicitacao_execucao'', #l_region_id#)) a',
'            order by',
'                case when campo4 in (''PENDENTE'',''EM_PROCESSAMENTO'',''BLOQUEADA'') then 1 else 2 end,',
'                to_number(campo5) desc,',
'                to_timestamp(campo6, ''dd/mm/yyyy hh24:mi:ss'') desc',
'        ~'';',
'',
'        l_sql := replace(l_sql, ''#l_region_id#'', l_region_id);',
'        return l_sql;',
'    end sql_report;',
'',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select ''PENDENTE'' d, ''PENDENTE'' r from dual union all',
'                select ''EM_PROCESSAMENTO'' d, ''EM_PROCESSAMENTO'' r from dual union all',
'                select ''SUCESSO'' d, ''SUCESSO'' r from dual union all',
'                select ''FALHA_NEGOCIO'' d, ''FALHA_NEGOCIO'' r from dual union all',
'                select ''FALHA_TECNICA'' d, ''FALHA_TECNICA'' r from dual union all',
'                select ''ERRO_FINAL'' d, ''ERRO_FINAL'' r from dual union all',
'                select ''BLOQUEADA'' d, ''BLOQUEADA'' r from dual union all',
'                select ''CANCELADO'' d, ''CANCELADO'' r from dual union all',
'                select ''EXPIRADO'' d, ''EXPIRADO'' r from dual',
'            ~'';',
'        elsif campo = ''3'' then',
'            return q''~select nome_artefato d, id r from srv_artefato order by nome_artefato~'';',
'        elsif campo = ''4'' then',
'            return q''~select nome d, id r from mpd_usuario order by nome~'';',
'        elsif campo = ''5'' then',
'            return q''~',
'                select distinct nome_artefato d, id_worker r',
'                  from mae_solicitacao_execucao a',
'                  join mae_sched_cfg b on b.id = a.id_worker',
'                  join srv_artefato c on c.id = b.id_artefato',
'                 where id_worker is not null',
'                 order by 1',
'            ~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;',
'    end sql_verifica_filtro;',
'',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id'')',
'              into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_artefato'')',
'              into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.tipo_acao'')',
'              into l_campo from dual;',
'        elsif campo in (''4'',''F2'') then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.status'')',
'              into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.prioridade'')',
'              into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.dt_criacao'')',
'              into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.dt_disponivel_execucao'')',
'              into l_campo from dual;',
'        elsif campo = ''8'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.tentativas'')',
'              into l_campo from dual;',
'        elsif campo = ''9'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_negocio'')',
'              into l_campo from dual;',
'        elsif campo = ''10'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_correlation'')',
'              into l_campo from dual;',
'        elsif campo = ''F1'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_tenant'')',
'              into l_campo from dual;',
'        elsif campo = ''F3'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_artefato'')',
'              into l_campo from dual;',
'        elsif campo = ''F4'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_usuario'')',
'              into l_campo from dual;',
'        elsif campo = ''F5'' then',
'            select pkg_ui.retorna_label_coluna(''mae_solicitacao_execucao.id_worker'')',
'              into l_campo from dual;',
'        end if;',
'',
'        return l_campo;',
'    end label_coluna;',
'',
'',
'    function ordenacao',
'    return varchar2 is',
'    begin',
'        return q''~',
'            select ''Ativas primeiro e Prioridade (maior para menor)'' d, ''ORDER1&ORDER2D'' r from dual union all',
'            select ''Ativas primeiro'' d, ''ORDER1'' r from dual union all',
'            select ''Prioridade (maior para menor)'' d, ''ORDER2D'' r from dual union all',
unistr('            select ''Data de cria\00E7\00E3o (mais recente primeiro)'' d, ''ORDER3D'' r from dual'),
'        ~'';',
'    end;',
'',
'',
'    function default_ordenacao',
'    return varchar2 is',
'    begin',
'        return ''ORDER1&ORDER2D&ORDER3D'';',
'    end;',
'',
'end "UI_MPD_TD1037";',
'/'))
);
end;
/
