'        l_id_idioma number;',
'    begin',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'',
'        l_sql := q''~',
'            select',
'                a.id id,',
'                a.id campo1,',
'                a.tipo_evento campo2,',
'                a.resultado campo3,',
'                a.id_solicitacao campo4,',
'                a.id_worker campo5,',
'                pkg_data.fmt(a.dt_evento, ''DATA_SEGUNDO'') campo6,',
'                a.id_correlation campo7,',
'                a.id_tenant campo8,',
'                dbms_lob.substr(a.detalhes, 4000, 1) campo9,',
'                null campo10,',
'',
'                -- FILTROS',
'                a.id_tenant filtro1,',
'                a.tipo_evento filtro2,',
'                a.resultado filtro3,',
'                a.id_solicitacao filtro4,',
'                a.id_worker filtro5,',
'                null filtro6,',
'                null filtro_mult1,',
'                null filtro_mult2,',
'                null filtro_mult3,',
'                null filtro_mult4,',
'                null filtro_mult5,',
'                null opcao',
'            from mae_registro_tecnico a',
'            where #condicao# and #condicao1#',
'            order by dt_evento desc',
'        ~'';',
'',
'        l_sql := replace(l_sql,''#condicao#'','' id_solicitacao = ''||p_param1);',
'        if p_param4 is not null then',
'            l_sql := replace(l_sql,''#condicao1#'',''a.tipo_evento in (''||fn_trata_lista_in(p_param4)||'')'');',
'        else',
'            l_sql := replace(l_sql,''#condicao1#'',''1 = 1'');',
'        end if;',
'',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql       clob;',
'        l_region_id number;',
'    begin',
'        select region_id',
'          into l_region_id',
'          from apex_application_page_regions',
'         where application_id = v(''APP_ID'')',
'           and page_id        = v(''APP_PAGE_ID'')',
'           and static_id      = ''LISTA_CR'';',
'',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD002'') as opcao',
'            from table(pkg_ui.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''mae_registro_tecnico'', #l_region_id#)) a',
'            order by',
'                to_timestamp(campo6, ''dd/mm/yyyy hh24:mi:ss'') desc,',
'                to_number(campo1) desc',
'        ~'';',
'',
'        l_sql := replace(l_sql, ''#l_region_id#'', l_region_id);',
'        return l_sql;',
'    end sql_report;',
'',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select distinct tipo_evento d, tipo_evento r',
'                  from mae_registro_tecnico',
'                 where tipo_evento is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''3'' then',
'            return q''~',
'                select distinct resultado d, resultado r',
'                  from mae_registro_tecnico',
'                 where resultado is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''4'' then',
'            return q''~',
'                select distinct to_char(id_solicitacao) d, id_solicitacao r',
'                  from mae_registro_tecnico',
'                 where id_solicitacao is not null',
'                 order by 1',
'            ~'';',
'        elsif campo = ''5'' then',
'            return q''~',
'                select distinct to_char(id_worker) d, id_worker r',
'                  from mae_registro_tecnico',
'                 where id_worker is not null',
'                 order by 1',
'            ~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;',
'    end sql_verifica_filtro;',
'',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id'')',
'              into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.tipo_evento'')',
'              into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.resultado'')',
'              into l_campo from dual;',
'        elsif campo in (''4'',''F4'') then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_solicitacao'')',
'              into l_campo from dual;',
'        elsif campo in (''5'',''F5'') then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_worker'')',
'              into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.dt_evento'')',
'              into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_correlation'')',
'              into l_campo from dual;',
'        elsif campo = ''8'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_tenant'')',
'              into l_campo from dual;',
'        elsif campo = ''9'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.detalhes'')',
'              into l_campo from dual;',
'        elsif campo = ''F1'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.id_tenant'')',
'              into l_campo from dual;',
'        elsif campo = ''F2'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.tipo_evento'')',
'              into l_campo from dual;',
'        elsif campo = ''F3'' then',
'            select pkg_ui.retorna_label_coluna(''mae_registro_tecnico.resultado'')',
'              into l_campo from dual;',
'        end if;',
'',
'        return l_campo;',
'    end label_coluna;',
'',
'',
'    function ordenacao',
'    return varchar2 is',
'    begin',
'        return q''~',
'            select ''Data do evento (mais recente primeiro)'' d, ''ORDER1D'' r from dual union all',
'            select ''ID (maior para menor)'' d, ''ORDER2D'' r from dual',
'        ~'';',
'    end;',
'',
'',
'    function default_ordenacao',
'    return varchar2 is',
'    begin',
'        return ''ORDER1D&ORDER2D'';',
'    end;',
'',
'end "UI_MPD_TD1038";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1041
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155777130213641129)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1041'
,p_sequence=>590
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1041" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    -- procedure campos_ordenacao(',
'    --     p_card_ou_grid in varchar2,',
'    --     campos out varchar2,',
'    --     labels out varchar2',
'    -- );',
'',
'end "UI_MPD_TD1041";',
'/',
'create or replace package body "UI_MPD_TD1041" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'        return clob is        ',
'            l_html clob;',
'        begin',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select ',
'                                   a.num_processoimportacao num_processoimportacao,',
'                                   pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''', ''''ind_status'''', a.ind_status)  ind_status',
'                                   from imp_processoimportacao a ',
'                                   where a.id = ''||p_param1,',
'                p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'                p_formato => ''pequeno'',',
'                --p_icones => textarray(/*''fa-database'', ''fa-database'',*/ ''fa-user'', ''fa-calendar fam-clock fam-is-success'', ''fa-calendar fam-clock fam-is-warning'', ''fa-flag''),',
unistr('                --p_label_fixo => textarray(''Workspace'', ''Aplica\00E7\00F5es'', ''P\00E1ginas'', ''Usu\00E1rios APEX''),'),
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            )',
'            ;',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'		        pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_natureza_notafiscal'', a.ind_natureza_notafiscal)           titulo,',
unistr('                pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_status_transmiss\00E3o'', a.ind_status_transmiss\00E3o)             subtitulo,  '),
'                pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_status_minuta'', a.ind_status_minuta)  distintivo,',
'                pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_status_minuta'', a.ind_status_minuta)  class_distintivo,',
'                --ATRIBUTOS               ',
'                pkg_componentes.html_card_colunas(''imp_minutanotafiscal_entrada.id_exportador'', c.nome_fantasia, 2 ) atributo1,',
'                pkg_componentes.html_card_colunas(''imp_minutanotafiscal_entrada.id_destinatario'', b.nome_fantasia, 2 ) atributo2,  ',
'                pkg_componentes.html_card_colunas(''imp_minutanotafiscal_entrada_transporte.id_transportador'', e.nome_fantasia, 2 ) atributo3,  ',
'                pkg_componentes.html_card_colunas(''imp_minutanotafiscal_entrada.peso_bruto_carga'', to_char(a.peso_bruto_carga, ''fm999g999g990d000'') , 2 ) atributo4,  ',
'                pkg_componentes.html_card_colunas(''imp_minutanotafiscal_entrada.valor_total_notafiscal'', to_char(a.valor_total_notafiscal, ''fm999g999g990d000''), 2 ) atributo5,  ',
'',
'                --FILTROS',
'                null       filtro1,',
'                null filtro2,',
'                null filtro3,',
'                a.id_exportador filtro4,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD1041'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD1041'') as opcao  ',
'',
'            from imp_minutanotafiscal_entrada a',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_destinatario',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_exportador',
'            join imp_minutanotafiscal_entrada_transporte d on d.id_minuta = a.id',
'            join ng_pessoa_juridica e on e.id_pessoa = d.id_transportador',
'            where a.id_processoimportacao = ''~''',
'            || p_param1 ||',
'            q''~''',
'                order by distintivo',
'            ~'';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#PARAM1#'', '''''''' || p_param1 || '''''''');          ',
'           return l_sql;',
'           -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_natureza_notafiscal'', a.ind_natureza_notafiscal)                               campo1,  ',
'            pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_status_minuta'', a.ind_status_minuta)                                           campo2,',
unistr('            pkg_util.dominio_retorna_tag(''imp_minutanotafiscal_entrada'', ''ind_status_transmiss\00E3o'', a.ind_status_transmiss\00E3o)                                 campo3,'),
'            c.nome_fantasia                                  campo4,',
'            b.nome_fantasia                                  campo5,',
'',
'            e.nome_fantasia                                  campo6,',
'            to_char(a.peso_bruto_carga, ''fm999g999g990d000'')    	                     campo7,',
'            to_char(a.valor_total_notafiscal, ''fm999g999g990d000'')                                           campo8,',
'            null                                             campo9,',
'            null                                             campo10,',
'            --filtros',
'            null                                             filtro1,                                ',
'            null                                             filtro2,                                ',
'            null                                             filtro3,                                ',
'            a.id_exportador                                  filtro4,',
'            null                                             filtro5,                                ',
'            --filtros multi',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            null                                             filtro_mult5,                                ',
'            null opcao',
'        from imp_minutanotafiscal_entrada a',
'        join ng_pessoa_juridica b on b.id_pessoa = a.id_destinatario',
'        join ng_pessoa_juridica c on c.id_pessoa = a.id_exportador',
'        join imp_minutanotafiscal_entrada_transporte d on d.id_minuta = a.id',
'        join ng_pessoa_juridica e on e.id_pessoa = d.id_transportador',
'        where a.id_processoimportacao = ~''||p_param1;',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin',
'        return q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                -- pkg_componentes.html_botao_opcao(a.id,''TD1041'') as opcao',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD1041'', p_param1 => campo10) as opcao',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''imp_minutanotafiscal_entrada'')) a',
'            order by campo2',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''4'' then',
'            return q''~select nome_fantasia d, id_pessoa r from ng_pessoa_juridica~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.ind_natureza_notafiscal'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.ind_status_minuta'') into l_campo from dual;',
'        elsif campo = ''3'' then',
unistr('            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.ind_status_transmiss\00E3o'') into l_campo from dual;'),
'        elsif campo in (''4'',''F4'') then                         ',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.id_exportador'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.id_destinatario'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada_transporte.id_transportador'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.peso_bruto_carga'') into l_campo from dual;',
'        elsif campo = ''8'' then',
'            select pkg_ui.retorna_label_coluna(''imp_minutanotafiscal_entrada.valor_total_notafiscal'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    -- procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    -- begin',
'    --     if p_card_ou_grid = ''CARD'' then',
'    --         campos := ''id'';',
'    --     else',
'    --         campos := ''campo5,campo4'';',
'    --     end if;',
'    --     labels := label_coluna(''5'')||'',''||label_coluna(''4'');',
'    -- end campos_ordenacao;',
'',
'    -- function atualizar_tela return varchar2 is',
'    -- begin',
'    --     return ''true'';',
'    -- end;',
'',
'',
'',
'',
'end "UI_MPD_TD1041";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td180
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155778084886629838)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD180'
,p_sequence=>600
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD180" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'end "UI_MPD_TD180";',
'/',
'create or replace package body "UI_MPD_TD180" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''srv_idioma'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_idioma'';        ',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' coluna_tabela, NULL valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''descricao_idioma'',   3, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_idioma) from srv_idioma where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''sigla_idioma'',       4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo'',             5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 7, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     8, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from srv_idioma where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario; ',
'',
'end "UI_MPD_TD180";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td274
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155778593585610663)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD274'
,p_sequence=>610
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD274" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;    ',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD274";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD274" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                ',
unistr('        if p_param2 = ''TD600'' then -- TD600 = Pessoa f\00EDsica, TD312 = Pessoa jur\00EDdica'),
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select a.nome_abreviado from ng_pessoa_fisica a where a.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_fisica''),',
'                p_formato => ''pequeno'',                ',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        else',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select a.nome_fantasia from ng_pessoa_juridica a where a.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_juridica''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        end if;',
'        return l_html;',
'    end;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_id_pessoa number;',
'        l_sql clob;        ',
'    begin',
'        if p_param2 = ''TD600'' then',
'            select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_param1;',
'        else',
'            select id_pessoa into l_id_pessoa from ng_pessoa_juridica where id = p_param1;',
'        end if;',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                a.descricao_conta_bancaria titulo,                ',
'                null subtitulo,                ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,                   ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_pessoa_contabancaria.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 12) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_pessoa_contabancaria.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 12) ',
'                end atributo1,',
'                a.data_fim_vigencia,',
'                --FILTROS                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes_com_parametro(''TD274'',a.id,b.id) url_mais_detalhes,',
'                --pkg_ui.url_mais_detalhes(''TD274'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD274'', p_param1 => b.id) as opcao',
'            from ng_pessoa_contabancaria a',
'            join ng_pessoa b on b.id = a.id_pessoa                        ',
'            where b.id = ~''||l_id_pessoa||q''~',
'            order by #ORDER#',
'           ~'';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'           return l_sql;           ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_id_pessoa number;',
'        l_sql clob;',
'    begin           ',
'        if p_param2 = ''TD600'' then',
'            select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_param1;',
'        else',
'            select id_pessoa into l_id_pessoa from ng_pessoa_juridica where id = p_param1;',
'        end if;',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            a.descricao_conta_bancaria campo1,        ',
'            case ',
'                when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo2,',
'            a.data_fim_vigencia campo3,',
'            null campo4,',
'            null campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            null filtro1,                                ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                ',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD274'', p_param1 => b.id) as opcao',
'        from ng_pessoa_contabancaria a',
'        join ng_pessoa b on b.id = a.id_pessoa                    ',
'        where b.id = ~''||l_id_pessoa;       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                opcao',
'            from table(pkg_ui.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_pessoa_contabancaria'')) a',
'            order by #ORDER#',
'            ~'';      ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));  ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.descricao_conta_bancaria'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.data_fim_vigencia'') into l_campo from dual;                    ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo3,campo1'';',
'        else',
'            campos := ''data_fim_vigencia,titulo'';',
'        end if;',
'',
'        select label_coluna(''2'') || '','' ||',
'        label_coluna(''1'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''2'') || '','' ||',
'               label_coluna(''1'')  ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo3,campo1'';',
'        else',
'            l_campos := ''data_fim_vigencia,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD274";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td307
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155778826189604890)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD307'
,p_sequence=>620
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD307" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);   ',
'    ',
'end "UI_MPD_TD307";',
'/',
'create or replace package body "UI_MPD_TD307" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is     ',
'        -- p_param1 = id da conta bancaria, p_param2 id da pessoa (ng_pessoa)',
'        l_verifica_pessoa_fisica number;  ',
'        l_html clob;',
'    begin        ',
'        select count(1) into l_verifica_pessoa_fisica from ng_pessoa_contabancaria a join ng_pessoa_fisica b on b.id_pessoa = a.id_pessoa where a.id = p_param1;',
'        if l_verifica_pessoa_fisica > 0 then',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ',
'                    ''select ',
'                        a.nome_abreviado ',
'                    from ng_pessoa_fisica a',
'                    join ng_pessoa_contabancaria b on b.id_pessoa = a.id_pessoa',
'                    where b.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_fisica''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        else',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ',
'                    ''select ',
'                        a.nome_fantasia ',
'                    from ng_pessoa_juridica a ',
'                    join ng_pessoa_contabancaria b on b.id_pessoa = a.id_pessoa',
'                    where b.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_juridica''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        end if;',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'    begin       ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_pessoa'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char(p_param2) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_conta_bancaria'', 3, ''TEX'', null, ''N'', ''S'', null valor FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''agencia_bancaria'',         4, ''POP'', ''R_NG_PESSOA_AGENCIABANCARIA.NOME_FANTASIA'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''conta_bancaria'',           6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                 7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_conta_exterior'',       9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',       10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',      11, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',          12, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select a.data_alteracao from ng_pessoa_contabancaria a where a.id = apex_util.get_session_state(l_id_chave)), ''DATA_SEGUNDO'') valor FROM dual'
||'               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;    ',
'',
'end "UI_MPD_TD307";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td312
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155793212516592604)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD312'
,p_sequence=>630
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD312" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD312";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD312" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                a.nome_fantasia titulo,',
'                c.nome_fantasia subtitulo,',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_pessoa_juridica.razao_social'', a.razao_social, 4) atributo1,',
'                case',
'                    when b.data_fim_vigencia is null then',
'                        pkg_componentes.html_card_colunas(pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.ind_perfil''), ',
'                            bo_ng_pessoa_juridica.retorna_perfil(a.ind_perfil), 8, ''s'') ',
'                    else',
'                        pkg_componentes.html_card_colunas(pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.ind_perfil''), ',
'                            bo_ng_pessoa_juridica.retorna_perfil(a.ind_perfil), 4, ''s'') ',
'                end atributo2,',
'                case ',
'                    when b.data_fim_vigencia is null then',
'                        null',
'                    when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_pessoa.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(b.data_fim_vigencia, ''DATA'')), 4) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_pessoa.data_fim_vigencia'', pkg_data.fmtd(b.data_fim_vigencia, ''DATA''), 4) ',
'                end atributo3,  ',
'                b.data_fim_vigencia,              ',
'                --FILTROS',
'                b.id_tenant filtro1,',
'                (select listagg(a.ind_perfil, '':'') from ng_pessoa_juridica where id = a.id) FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD312'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD312'', p_param1 => b.id) as opcao                ',
'            from ng_pessoa_juridica a',
'            join ng_pessoa b on b.id = a.id_pessoa',
'            join mpd_tenant c on c.id = b.id_tenant            ',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            c.nome_fantasia campo1,',
'            a.nome_fantasia campo2,',
'            a.razao_social campo3,',
'            bo_ng_pessoa_juridica.retorna_perfil(a.ind_perfil) campo4,',
'            case ',
'                when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(b.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(b.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            b.data_fim_vigencia campo6,            ',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            b.id_tenant filtro1,                               ',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,',
'            --FILTROS MULTI            ',
'            (select listagg(a.ind_perfil, '':'') from ng_pessoa_juridica where id = a.id) filtro_mult1,',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD312'', p_param1 => b.id) as opcao',
'        from ng_pessoa_juridica a',
'        join ng_pessoa b on b.id = a.id_pessoa',
'        join mpd_tenant c on c.id = b.id_tenant        ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_pessoa_fisica'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''M1'' then            ',
'            return q''~',
'                select distinct',
'                    pkg_util.dominio_retorna_tag(''ng_pessoa_juridica'',''ind_perfil'',trim(column_value)) d,',
'                    trim(column_value) r',
'                from ng_pessoa_juridica,',
'                    table(apex_string.split(ind_perfil, '':''))',
'                where ind_perfil is not null',
'                order by d;',
'            ~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.nome_fantasia'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.razao_social'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.ind_perfil'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''M1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.ind_perfil'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo2,campo3,campo4'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,titulo,atributo1,atributo2'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD312";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td314
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155793530823586276)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD314'
,p_sequence=>640
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD314" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'',
'end "UI_MPD_TD314";',
'/',
'create or replace package body "UI_MPD_TD314" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_observacao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);',
'        l_cabecalho varchar2(32767);',
'        l_url varchar2(4000);        ',
'        l_atributos varchar2(4000);',
'        l_exibe_grupo_empresarial varchar2(10);',
'        l_exibe_ind_matriz varchar2(10);',
'        l_exibe_inscricao_estadual varchar2(10);',
'        l_exibe_inscricao_municipal varchar2(10);',
'        l_exibe_inscricao_suframa varchar2(10);',
'        l_exibe_codigo_tin varchar2(10);',
'    begin',
'',
'        ',
'        ',
'        l_cabecalho := ''bo_ng_pessoa_juridica.sql_cabecalho_externo'';',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pessoa_juridica'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';        ',
'        select lower(ind_perfil) into l_atributos from ng_pessoa_juridica where id = p_param1;      ',
'        ',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2,P9005_PARAMETRO3'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna||'',''||l_cabecalho, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'        ',
'        if l_atributos is null then',
'            l_exibe_grupo_empresarial := ''HID'';',
'        end if;',
'        if regexp_like(l_atributos, ''i'') or regexp_like(l_atributos, ''e'') or regexp_like(l_atributos, ''f'') or regexp_like(l_atributos, ''r'') or regexp_like(l_atributos, ''c'') or regexp_like(l_atributos, ''d'') or regexp_like(l_atributos, ''t'') then',
'            null;',
'        else',
'            l_exibe_ind_matriz := ''HID'';',
'            l_exibe_inscricao_estadual := ''HID'';',
'            l_exibe_inscricao_municipal := ''HID'';',
'        end if;',
'        if regexp_like(l_atributos, ''i'') or regexp_like(l_atributos, ''e'') or regexp_like(l_atributos, ''f'') then',
'            null;',
'        else',
'            l_exibe_inscricao_suframa := ''HID'';',
'        end if;',
'        if regexp_like(l_atributos, ''i'') or regexp_like(l_atributos, ''e'') or regexp_like(l_atributos, ''f'') then',
'            null;',
'        else',
'            l_exibe_codigo_tin := ''HID'';',
'        end if;',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.NOME_FANTASIA'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL '
||'              ',
'               SELECT p_codigo_artefato, ''id_grupo_empresarial'', 3, l_exibe_grupo_empresarial, null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''razao_social'',         5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''nome_fantasia'',        6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_matriz'',           7, l_exibe_ind_matriz, null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''observacao'',           8, ''TXT'', to_char(l_url), l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(observacao) from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL          '
||'                               ',
'               SELECT p_codigo_artefato, ''inscricao_federal'',    9, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''inscricao_estadual'',  10, l_exibe_inscricao_estadual, null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''inscricao_municipal'', 11, l_exibe_inscricao_municipal, null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''inscricao_suframa'',   12, l_exibe_inscricao_suframa, null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_tin'',          13, l_exibe_codigo_tin, null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_cnae'',         14, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''rede_social'',         15, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_perfil'',          16, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   17, ''DAT'', null, ''N'',''N'', pkg_data.fmtd((select data_fim_vigencia from ng_pessoa a join ng_pessoa_juridica b on b.id_pessoa = a.id where b.id = p_param1),''DATA'') valor FROM dual UNION AL'
||'L               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',      18, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_integracao'',     19, '''', null, ''N'',''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is       ',
'    begin',
'        bo_ng_pessoa_juridica.altera_pessoa_juridica(  ',
'            p_id_tenant => apex_application.g_f01(1),            ',
'            p_id_grupo_empresarial => apex_application.g_f03(1),',
'            p_razao_social => apex_application.g_f05(1),',
'            p_nome_fantasia => apex_application.g_f06(1),',
'            p_ind_matriz => apex_application.g_f07(1),',
'            p_observacao => apex_application.g_f08(1),',
'            p_inscricao_federal => apex_application.g_f09(1),            ',
'            p_inscricao_estadual => apex_application.g_f10(1),',
'            p_inscricao_municipal => apex_application.g_f11(1),',
'            p_inscricao_suframa => apex_application.g_f12(1),',
'            p_codigo_tin => apex_application.g_f13(1),',
'            p_codigo_cnae => apex_application.g_f14(1),',
'            p_rede_social => apex_application.g_f15(1),                        ',
'            p_ind_perfil => pkg_formulario_dinamico.list_opcao_lov(apex_application.g_f16),',
'            p_data_fim_vigencia => apex_application.g_f17(1),',
'            p_data_integracao => apex_application.g_f19(1),',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD314";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td315
begin
wwv_flow_imp_shared.create_install_script(
