prompt --application/deployment/install/install_ui_mpd_td317
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155793966101577337)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD317'
,p_sequence=>660
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 22/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD317" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD317";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD317" as',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'    begin',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;',
'        l_sql := ''',
'            SELECT',
'                a.id ,',
'				pkg_traducao.get_traducao(descricao_condicaopagamento) ||'''' ''''||',
'                CASE',
'                    WHEN a.ind_situacao = ''''E'''' THEN',
'                        ''''<span><i title="''||l_hover_ind_situacao||''" class="fa fa-warning"></i></span>''''',
'                    ELSE',
'                        NULL',
'                END titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''''u-hidden''''',
'                    when to_date(a.data_fim_vigencia, ''''dd/mm/yyyy'''') < to_date(current_date, ''''dd/mm/yyyy'''') then',
'                        ''''data-fim-vigencia''''',
'                    else',
'                        null',
'                end class_distintivo,           ',
'                null lista_distintivo,',
'',
unistr('                -- colunas t\00E9cnicas para ordena\00E7\00E3o'),
'                a.data_fim_vigencia ordem_data_fim_vigencia,',
'                b.nome_fantasia ordem_nome_fantasia,',
'                case',
'                    when regexp_like(descricao_condicaopagamento, ''''^\d+'''') then',
'                        ''''0|'''' ||',
'                        lpad(regexp_substr(descricao_condicaopagamento, ''''^\d+''''), 20, ''''0'''') ||',
'                        ''''|'''' ||',
'                        pkg_traducao.get_traducao(descricao_condicaopagamento)',
'                    else',
'                        ''''1|'''' ||',
'                        ''''99999999999999999999'''' ||',
'                        ''''|'''' ||',
'                        pkg_traducao.get_traducao(descricao_condicaopagamento)',
'                end ordem_descricao,',
'                (SELECT COUNT(*) FROM ng_condicaopagamento_parcela c WHERE c.id_condicaopagamento = a.id) parcelas,',
'                a.ind_situacao,',
'',
unistr('                --COLUNAS N\00C3O UTILIZADAS'),
'                a.id_tenant,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''''TD317'''',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''''TD317'''') as opcao',
'            FROM ng_condicaopagamento a',
'            JOIN mpd_tenant b ON a.id_tenant = b.id',
'            order by #ORDER#',
'        '';       ',
'        --order by 7 nulls first, 8, case when regexp_like(descricao_condicaopagamento, ''''^\d'''') then 0 else 1 end, to_number(regexp_substr(descricao_condicaopagamento, ''''^\d+'''')) nulls last, 2',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'       return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'        l_html_ind_situacao varchar2(4000);',
'    begin',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;',
'        l_sql := ''',
'            SELECT',
'                a.id,                                    ',
'                b.nome_fantasia campo1,  ',
'                pkg_traducao.get_traducao(descricao_condicaopagamento)  campo2,',
'                (SELECT COUNT(*) FROM ng_condicaopagamento_parcela c WHERE c.id_condicaopagamento = a.id) campo3,',
'                CASE',
'                    WHEN a.ind_situacao = ''''E'''' THEN',
'                        ''''<span><i title="''||l_hover_ind_situacao||'' "class="fa fa-warning"></i></span>''''',
'                    ELSE',
'                        NULL',
'                END campo4,',
'                CASE when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''))',
'                ELSE ',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')',
'                END AS campo5,',
'                a.data_fim_vigencia campo6,',
'',
unistr('                -- colunas t\00E9cnicas para ordena\00E7\00E3o'),
'                a.data_fim_vigencia campo7,',
'                b.nome_fantasia campo8,',
'                case',
'                    when regexp_like(descricao_condicaopagamento, ''''^\d+'''') then',
'                        ''''0|'''' ||',
'                        lpad(regexp_substr(descricao_condicaopagamento, ''''^\d+''''), 20, ''''0'''') ||',
'                        ''''|'''' ||',
'                        pkg_traducao.get_traducao(descricao_condicaopagamento)',
'                    else',
'                        ''''1|'''' ||',
'                        ''''99999999999999999999'''' ||',
'                        ''''|'''' ||',
'                        pkg_traducao.get_traducao(descricao_condicaopagamento)',
'                end campo9,',
'                a.ind_situacao campo10,',
'                                      ',
'                --FILTROS',
'                a.id_tenant       filtro1,                                ',
'                null              filtro2,                                ',
'                null              filtro3,                                ',
'                null              filtro4,',
'                null              filtro5,                                ',
'                --FILTROS MULTI',
'                null              filtro_mult1,                                ',
'                null              filtro_mult2,                                ',
'                null              filtro_mult3, ',
'                null              filtro_mult4,                                ',
'                null              filtro_mult5,                                ',
'                null opcao',
'            FROM ng_condicaopagamento a',
'            JOIN mpd_tenant b ON a.id_tenant = b.id',
'            '';       ',
'       return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select  ',
'                id,              ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                to_date(campo7,''DD/MM/YYYY'')campo7,',
'                campo8,',
'                campo9,',
'                campo10,                             ',
'                 pkg_componentes.html_botao_opcao(a.id,''TD317'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_condicaopagamento'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then ',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_tela(''condicao_pagamento'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_tela(''parcelas'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento.ind_situacao'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo7,campo8,campo9,campo3,campo4'';',
'        else',
'            campos := ''ordem_data_fim_vigencia,ordem_nome_fantasia,ordem_descricao,parcelas,ind_situacao'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'')',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo7,campo8,campo9'';',
'        else',
'            l_campos := ''ordem_data_fim_vigencia,ordem_nome_fantasia,ordem_descricao'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD317";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td321
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155794404899572788)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD321'
,p_sequence=>670
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD321" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD321";',
'/',
'create or replace package body "UI_MPD_TD321" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url_descricao varchar2(4000);',
'        l_url_parcelas varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_condicaopagamento'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_condicaopagamento''; ',
'',
'        l_url_descricao := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        l_url_parcelas := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD367,TD367,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_entidade, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''descricao_condicaopagamento'', 4, ''TXT'', l_url_descricao, ''S'', ''S'', to_char((select pkg_traducao.get_traducao(a.descricao_condicaopagamento) from ng_condicaopagamento a where a.id = p_param1)) valor FROM dual '
||'UNION ALL',
'               SELECT p_codigo_artefato, ''parcelas'',                    5, ''TXT'', l_url_parcelas, ''N'', ''N'', to_char((SELECT COUNT(*) FROM ng_condicaopagamento_parcela WHERE id_condicaopagamento = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',           6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',          9, ''SEL'', ''R_MPD_USUARIO.NOME'' as nome_consulta, ''N'',''S'', null valor FROM dual UNION ALL                ',
'               SELECT p_codigo_artefato, ''data_alteracao'',             10, ''TXT'', null, ''N'',''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_condicaopagamento WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    ',
'    end formulario;',
'    ',
'end "UI_MPD_TD321";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td323
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155794868146567625)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD323'
,p_sequence=>680
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 26/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD323" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD323";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD323" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'                a.id,    ',
'                pkg_ui.retorna_label_coluna(''ng_cargo.descricao_cargo'') label_titulo,',
'                pkg_ui.retorna_label_coluna(''ng_cargo.id_tenant'') label_subtitulo,',
'                pkg_ui.retorna_label_coluna(''ng_cargo.data_fim_vigencia'') label_distintivo,',
'                pkg_traducao.get_traducao(a.descricao_cargo) titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end distintivo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                                                ',
'                null lista_distintivo, ',
'                a.data_fim_vigencia,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,                  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD323'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD323'') as opcao                ',
'            from ng_cargo a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''5''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            pkg_traducao.get_traducao(a.descricao_cargo) campo2,            ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo3,                          ',
'            a.data_fim_vigencia campo4,             ',
'            null campo5,             ',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            a.id_tenant filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_cargo a   ',
'        join mpd_tenant b on b.id = a.id_tenant            ',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD323'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_cargo'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''5''));',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else ',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cargo.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cargo.descricao_cargo'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cargo.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'        ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo4,campo2,campo1'';',
'        else',
'            campos := ''data_fim_vigencia,titulo,subtitulo'';',
'        end if;',
'',
'        select label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''1'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''3'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''2'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo4,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,titulo'';',
'        end if;',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD323";',
'/'))
);
end;
