prompt --application/deployment/install/install_ui_mpd_td324
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155795092770563623)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD324'
,p_sequence=>690
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD324" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD324";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD324" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        -- apex_item.checkbox(1,a.id,''onclick="seleciona(this);" style="margin-right:0.6rem;"'') selected,',
'',
'',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                a.data_fim_vigencia,',
'                pkg_traducao.get_traducao(a.nome_estado) || ('' - '') || a.sigla_uf  ',
'                                    titulo, ',
'                pkg_traducao.get_traducao(c.nome_pais)        subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                   ',
'                null lista_distintivo,',
unistr('                --COLUNAS N\00C3O UTILIZADAS'),
'                a.id_tenant,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD324'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD324'') as opcao  ',
'',
'            from ng_estado a',
'            JOIN mpd_tenant b on b.id = a.id_tenant  ',
'            JOIN ng_pais c ON c.id = a.id_pais  ',
'            order by #ORDER#',
'',
'           ~'';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'           return l_sql;',
'           -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia                                 campo1,',
'            pkg_traducao.get_traducao(a.nome_estado)        campo2,',
'            UPPER(a.sigla_uf)                               campo3,',
'            pkg_traducao.get_traducao(c.nome_pais)          campo4,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end                                              campo5,',
'            a.data_fim_vigencia                                            campo6,',
'            null                                             campo7,',
'            null                                             campo8,',
'            null                                             campo9,',
'            null                                             campo10,',
'            --FILTROS',
'            a.id_tenant                                      filtro1,                                ',
'            null                                             filtro2,                                ',
'            null                                             filtro3,                                ',
'            null                                             filtro4,',
'            null                                             filtro5,                                ',
'            --FILTROS MULTI',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            null                                             filtro_mult5,                                ',
'            null opcao',
'        from ng_estado a',
'        JOIN mpd_tenant b ON a.id_tenant = b.id  ',
'        JOIN ng_pais c ON c.id = a.id_pais  ',
'       ~'';',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD324'') as opcao  ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_estado'')) a',
'            order by #ORDER#            ',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));',
'            return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo IN (''1'',''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_estado.id_tenant'') into l_campo from dual;',
'         elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_tela(''estado'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_tela(''sigla'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_estado.id_pais'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_estado.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo4,campo2'';',
'        else',
'            campos := ''data_fim_vigencia,filtro1,subtitulo,titulo'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''2'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''4'') || '','' ||',
'               label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo4,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,filtro1,subtitulo,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD324";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td329
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155795511191559315)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD329'
,p_sequence=>700
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD329" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);   ',
'',
'end "UI_MPD_TD329";',
'/',
'create or replace package body "UI_MPD_TD329" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_cargo'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_cargo'';      ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''descricao_cargo'',    4, '''', to_char(l_url), ''S'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_cargo) from ng_cargo where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  5, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 6, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     7, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_cargo WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'    ',
'end "UI_MPD_TD329";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td330
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155795781829555275)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD330'
,p_sequence=>710
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD330" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'end "UI_MPD_TD330";',
'/',
'create or replace package body "UI_MPD_TD330" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin     ',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_estado'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_estado''; ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        ); ',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''nome_estado'', 3, '''', l_url, ''N'', ''S'', to_char((select pkg_traducao.get_traducao(nome_estado) from ng_estado where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''sigla_uf'',           4, '''', null, ''N'',''S'', UPPER((SELECT sigla_uf FROM ng_estado WHERE id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais'',            5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 9, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',     10, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_estado where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               )  new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD330";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td337
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155796312314543250)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD337'
,p_sequence=>720
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD337" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'    ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD337";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD337" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.id_tenant,',
'                pkg_traducao.get_traducao(descricao_moeda) || '' - (''||a.simbolo_iso||'')'' titulo,',
'                to_char(a.codigo_moeda) subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                a.data_fim_vigencia,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                   ',
'                null lista_distintivo,',
'                --order',
'                b.nome_fantasia order1,',
'                a.simbolo_iso order2,',
'                a.data_fim_vigencia order3,',
'',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'            to_date(a.data_fim_vigencia,''DD/MM/YYYY'')  filtro_data_range1,',
'',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD337'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD337'') as opcao                ',
'            from ng_moeda a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            b.nome_fantasia campo1,',
'            to_char(a.codigo_moeda)     campo2,',
'            pkg_traducao.get_traducao(descricao_moeda)campo3,                                                   ',
'            a.simbolo_iso campo4,                    ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            a.data_fim_vigencia campo6,',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10, ',
'            a.id_tenant filtro1,   ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,   ',
'            to_date(a.data_fim_vigencia,''DD/MM/YYYY'')  filtro_data_range1,',
'            null opcao',
'        from ng_moeda a                ',
'        join mpd_tenant b on b.id = a.id_tenant',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                to_date(campo6,''DD/MM/YYYY'')campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD337'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_moeda'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda.codigo_moeda'') into l_campo from dual;',
'         elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda.descricao_moeda'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda.simbolo_iso'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''R1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;      ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo4,campo6'';',
'        else',
'            campos := ''order1,subtitulo,titulo,order2,order3'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2'';',
'        else',
'            l_campos := ''order3,order1,subtitulo'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD337";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td342
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155796648250533970)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD342'
,p_sequence=>730
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD342" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD342";',
'/',
'create or replace package body "UI_MPD_TD342" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_incoterm'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_incoterm'';',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''codigo_incoterm'',                 3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_incoterm'',              4, ''TXT'', l_url, ''S'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_incoterm) from ng_incoterm where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_responsavel_despesa_origem'',  5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_responsavel_despesa_destino'', 6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_responsavel_frete'',           7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_responsavel_seguro'',          8, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_viatransporte_permitida'',    11, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',              10, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',             12, ''SEL'', ''R_MPD_USUARIO.NOME'' as nome_consulta, ''S'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                 13, ''TXT'', null, ''N'',''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_incoterm WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    ',
'    end formulario;',
'    ',
'end "UI_MPD_TD342";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td868
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155797186559530919)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD868'
,p_sequence=>730
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD868',
'-- Data: 27/04/2026',
unistr('-- Motivo: Ajustes em par\00E2metros recebidos na UI '),
'-- Jira: PEDITEM-270',
'',
'-- Objeto: UI_MPD_TD868',
'-- Data: 30/04/2026',
unistr('-- Motivo: Ajuste para evitar duplicar v\00EDnculo de entregas'),
'-- Jira: PEDITEM-270',
'',
'create or replace package "UI_MPD_TD868" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    function mostra_opcao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'        ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'   ',
'    procedure post(',
'        p_id in varchar2,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'',
'    function label_coluna(campo in varchar2) return clob;',
'    ',
'end "UI_MPD_TD868";',
'/',
'create or replace package body "UI_MPD_TD868" as',
'    ',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'        l_status varchar2(50);',
'    begin  ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql =>',
'                ''select',
'                    a.num_processoimportacao,',
'                    b.nome_fantasia as id_embarcador',
'                from imp_processoimportacao a',
'                join ng_pessoa_juridica b on b.id_pessoa = a.id_embarcador',
'                where a.id = ''|| p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.74.l'');',
'        -- || l_id_processo;',
'        return l_html;',
'    end;',
'',
'    function mostra_opcao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        NULL;',
'        return l_url;',
'    end;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        NULL;',
'        return l_url;',
'    end;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'        l_processo varchar2(50);',
'    begin   ',
'        l_processo := apex_util.get_session_state(''P9014_PARAMETRO'');',
'',
'        l_sql := q''~',
'            select        ',
'                -- apex_item.checkbox(1,a.id,''onclick="seleciona(this);"'') selected,',
'                apex_item.checkbox(',
'                    p_idx => 1,',
'                    p_value => a.id,',
'                    p_checked_values => (select nvl(listagg(to_char(id), '':'') within group (order by id), ''0'') from imp_entrega where id_processoimportacao = ~''|| l_processo || q''~),',
'                    p_attributes => ''onclick="seleciona(this);"''',
'                ) selected,',
'                a.id,',
'                b.numero_pedido_importacao campo1,',
'                a.num_entrega campo2,',
'                c.nome_fantasia campo3,',
'                CASE',
'                    WHEN a.data_embarque_informada is not null THEN',
'                        a.data_embarque_informada',
'                    ELSE',
'                        a.data_embarque_calculada',
'                END campo4,',
'                null campo5,            ',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                --FILTROS',
'                null filtro1,                ',
'                null filtro2,',
'                null filtro3,',
'                null filtro4,            ',
'                null filtro5,',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                null FILTRO_MULT3,  ',
'                null FILTRO_MULT4,  ',
'                null FILTRO_MULT5,',
'                pkg_componentes.html_botao_opcao(a.id,''TD840'') opcao',
'            from imp_entrega a',
'            join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_exportador',
'            where ',
'                b.ind_status_pedido_importacao = 3',
'                and (',
'                    (a.ind_status_entrega in (1, 2, 3) and (a.id_processoimportacao is null or a.id_processoimportacao = ~''|| l_processo || q''~))',
'                    or (a.ind_status_entrega = 4 and a.id_processoimportacao = ~''|| l_processo || q''~)',
'                )',
'            order by campo1, campo2',
'        ~'';  ',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    procedure post(',
'        p_id in varchar2,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao imp_entrega.id_processoimportacao%type;',
'    begin',
'        l_id_processoimportacao := to_number(apex_util.get_session_state(''P9014_PARAMETRO''));',
'',
'        bo_imp_entrega.vincula_entregas_ao_processo(',
'            p_ids_entregas_selecionadas     => p_id,',
'            p_id_processoimportacao         => l_id_processoimportacao,',
'            p_pagina                        => 0,',
'            p_encadeado                     => false,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'    end;',
'',
'    function label_coluna(campo in varchar2) return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_pedidoimportacao'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_exportador'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_informada'') into l_campo from dual;',
'        elsif campo = ''SEL'' then                     ',
'            l_campo := ''Sim'';',
'        elsif campo = ''ALLSEL'' then                     ',
'            l_campo := ''Sim'';',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'end "UI_MPD_TD868";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td343
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155797218471529389)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD343'
,p_sequence=>740
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 08/07/2026',
unistr('-- Motivo: Ajuste na ordena\00E7\00E3o da pesquisa facetada ind_status_pedido_importacao'),
'-- Jira: PEDITEM-69',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira:',
'',
'create or replace package "UI_MPD_TD343" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    -- function pre_filtro(campo in varchar2)',
'    -- return clob;',
'',
'    -- function default_pre_filtro(campo in varchar2)',
'    -- return varchar2;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    -- function verifica_pre_filtro(campo in varchar2)',
'    -- return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    -- procedure campos_ordenacao(',
'    --     p_card_ou_grid in varchar2,',
'    --     campos out varchar2,',
'    --     labels out varchar2',
'    -- );',
'',
'    function ordenacao return varchar2;',
'',
'    function default_ordenacao',
'    return varchar2;',
'',
'end "UI_MPD_TD343";',
'/',
'',
'create or replace package body "UI_MPD_TD343" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_url varchar2(4000);',
'        l_id_idioma number;',
'        l_label_titulo varchar2(4000);',
'        l_label_subtitulo varchar2(4000);',
'        l_label_distintivo varchar2(4000);',
'        l_label_atributo1 varchar2(4000);',
'        l_label_atributo2 varchar2(4000);',
'        l_label_atributo3 varchar2(4000);',
'        l_label_atributo4 varchar2(4000);',
'        l_label_atributo5 varchar2(4000);',
'    begin   ',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'        l_label_titulo := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao'');',
'        l_label_subtitulo := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_importador'');',
'        l_label_distintivo := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.ind_status_pedido_importacao'');',
'',
'        l_label_atributo1 := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_exportador'');',
'        l_label_atributo2 := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_local_embarque'');',
'        l_label_atributo3 := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_local_desembarque'');',
'        l_label_atributo4 := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.ind_todos_itens_com_entregas_programadas'');',
'        l_label_atributo5 := pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.quantidade_entrega'');',
'        ',
'        -- l_url := apex_page.get_url(',
'        --     p_page => 321, ',
'        --     p_items => ''P0_CODIGO_ARTEFATO,P321_CODIGO_ARTEFATO,P321_PARAMETRO'', ',
'        --     p_values => ''321,321,''||p_param1, ',
'        --     p_clear_cache => 321,',
'        --     p_plain_url => true',
'        -- );',
'        --order by data_alteracao desc, case when ind_status_pedido_importacao <> 4 then 1 else 2 end, ind_status_pedido_importacao',
'        l_sql := q''~',
'            select ',
'                a.id,  ',
'                a.numero_pedido_importacao titulo,',
'                c.nome_fantasia subtitulo,           ',
'',
'                ''#LABEL_TITULO#'' label_titulo,',
'                ''#LABEL_SUBTITULO#'' label_subtitulo,',
'                ''#LABEL_DISTINTIVO#'' label_distintivo,',
'',
'                bo_ng_viatransporte.retorna_icone_viatransporte_card(a.id_viatransporte) icon,                ',
'                dominio1.d distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'',
'                --ATRIBUTOS 10',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO1#'', b.nome_fantasia, 2,''s'') atributo1,                ',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO2#'', ',
'                    CASE',
'                    WHEN f.id_idioma = #IDIOMA#  THEN',
'                        d.nome_local',
'                    ELSE',
'                        COALESCE(traducao_local_embarque.texto_traduzido, d.nome_local)',
'                    END,2,''S''',
'                ) atributo2,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO3#'', ',
'                    CASE',
'                    WHEN f.id_idioma = #IDIOMA#  THEN',
'                        e.nome_local',
'                    ELSE',
'                        COALESCE(traducao_local_desembarque.texto_traduzido, e.nome_local)',
'                    END, 2,''S''',
'                ) atributo3,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO4#'', ',
'                    dominio2.d, 2,''S''',
'                ) atributo4,                             ',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO5#'', a.quantidade_entrega, 2,''s'') atributo5,',
'',
'                --FILTROS',
'                a.id_tenant filtro1,                ',
'                a.ind_status_pedido_importacao filtro2,',
'                a.ind_todos_itens_com_entregas_programadas filtro3,                ',
'                a.id_importador filtro4,',
'                a.id_viatransporte filtro5,                ',
'                a.id_local_desembarque filtro6,',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                data_confirmacao_pedido filtro_data_range1,',
'',
'                --ORDER',
'                case when a.ind_status_pedido_importacao <> 4 then 1 else 2 end order1,',
'                a.data_alteracao order2,        ',
'                a.ind_status_pedido_importacao order3,',
'',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD343'',a.id) url_mais_detalhes,                ',
'                pkg_componentes.html_botao_opcao(a.id,''TD343'') as opcao                ',
'            from imp_pedidoimportacao a',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_exportador',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_importador',
'            left join ng_localembarquedesembarque d on d.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque e on e.id = a.id_local_desembarque            ',
'            join mpd_tenant f on f.id = a.id_tenant',
'            left join ng_viatransporte f1 on f1.id = a.id_viatransporte  ',
'',
'            LEFT JOIN VW_TRADUCOES_GERAL traducao_local_embarque',
'                    ON traducao_local_embarque.id_chave_entidade = a.id_local_embarque',
'                    AND traducao_local_embarque.nome_entidade = ''ng_localembarquedesembarque''',
'                    AND traducao_local_embarque.nome_coluna = ''nome_local''',
'                    AND traducao_local_embarque.id_idioma = #IDIOMA#          ',
'',
'            LEFT JOIN VW_TRADUCOES_GERAL traducao_local_desembarque',
'                    ON traducao_local_desembarque.id_chave_entidade = a.id_local_desembarque',
'                    AND traducao_local_desembarque.nome_entidade = ''ng_localembarquedesembarque''',
'                    AND traducao_local_desembarque.nome_coluna = ''nome_local''',
'                    AND traducao_local_desembarque.id_idioma = #IDIOMA#           ',
'',
'            LEFT join vw_dominio_traduzido dominio1',
'              on dominio1.nome_entidade = lower(''imp_pedidoimportacao'')',
'             and dominio1.nome_coluna   = lower(''ind_status_pedido_importacao'')',
'             and dominio1.r             = lower(a.ind_status_pedido_importacao)',
'             and dominio1.id_idioma     = #IDIOMA#',
'',
'            left join vw_dominio_traduzido dominio2',
'              on dominio2.nome_entidade = lower(''imp_pedidoimportacao'')',
'             and dominio2.nome_coluna   = lower(''ind_todos_itens_com_entregas_programadas'')',
'             and lower(dominio2.r)      = lower(a.ind_todos_itens_com_entregas_programadas)',
'             and dominio2.id_idioma     = #IDIOMA#   ',
'',
'            left join vw_dominio_traduzido dominio3',
'              on dominio3.nome_entidade = lower(''ng_viatransporte'')',
'             and dominio3.nome_coluna   = lower(''icone_viatransporte'')',
'             and dominio3.r             = lower(f1.icone_viatransporte)',
'             and dominio3.id_idioma     = #IDIOMA# ',
'',
'            ~'';        ',
'',
'            -- where #condicao1#',
'            -- order by order1, order2 desc, order3',
'            --order by case when a.ind_status_pedido_importacao <> 4 then 1 else 2 end, a.data_alteracao desc, a.ind_status_pedido_importacao',
'            if p_param4 is not null then',
'                l_sql := replace(l_sql,''#condicao1#'',''ind_status_pedido_importacao in (''||fn_trata_lista_in(p_param4)||'')''); ',
'            else',
'                l_sql := replace(l_sql,''#condicao1#'',''1 = 1''); ',
'            end if;',
'           ',
'            l_sql := replace(l_sql, ''#IDIOMA#'', l_id_idioma);',
'            l_sql := replace(l_sql, ''#LABEL_TITULO#'', l_label_titulo);',
'            l_sql := replace(l_sql, ''#LABEL_SUBTITULO#'', l_label_subtitulo);',
'            l_sql := replace(l_sql, ''#LABEL_DISTINTIVO#'', l_label_distintivo);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO1#'', l_label_atributo1);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO2#'', l_label_atributo2);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO3#'', l_label_atributo3);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO4#'', l_label_atributo4);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO5#'', l_label_atributo5);',
'            return l_sql;                    ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_id_idioma number;',
'        l_filtro_padrao1 number;',
'    begin   ',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'        l_sql := q''~',
'        select ',
'            a.id id,  ',
'            a.numero_pedido_importacao campo1,',
'            --case when f.id_idioma = #IDIOMA# then g.descricao_viatransporte else coalesce(traducao_viatransporte.texto_traduzido, g.descricao_viatransporte) end campo2,',
'            pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',g.descricao_viatransporte) campo2,',
'            b.nome_fantasia campo3,',
'            c.nome_fantasia campo4,',
'            dominio1.d campo5,                                   ',
'            case when f.id_idioma = #IDIOMA# then d.nome_local else coalesce(traducao_local_embarque.texto_traduzido, d.nome_local) end campo6,          ',
'            case when f.id_idioma = #IDIOMA# then e.nome_local else coalesce(traducao_local_desembarque.texto_traduzido, e.nome_local) end campo7,',
'            dominio2.d campo8,',
'            a.quantidade_entrega campo9,',
'            a.data_alteracao campo10,            ',
'            --FILTROS',
'            a.id_tenant filtro1,                ',
'            a.ind_status_pedido_importacao filtro2,',
'            a.ind_todos_itens_com_entregas_programadas filtro3,            ',
'            a.id_importador filtro4,',
'            a.id_viatransporte filtro5,            ',
'            a.id_local_desembarque filtro6,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            data_confirmacao_pedido filtro_data_range1,',
'            null opcao',
'        from imp_pedidoimportacao a',
'        join ng_pessoa_juridica b on b.id_pessoa = a.id_exportador',
'        join ng_pessoa_juridica c on c.id_pessoa = a.id_importador',
'        left join ng_localembarquedesembarque d on d.id = a.id_local_embarque',
'        left join ng_localembarquedesembarque e on e.id = a.id_local_desembarque                    ',
'        join mpd_tenant f on f.id = a.id_tenant       ',
'        left join ng_viatransporte g on g.id = a.id_viatransporte       ',
'',
'        LEFT JOIN VW_TRADUCOES_GERAL traducao_viatransporte',
'                ON traducao_viatransporte.id_chave_entidade = a.id_viatransporte',
'                AND traducao_viatransporte.nome_entidade = ''ng_viatransporte''',
'                AND traducao_viatransporte.nome_coluna = ''descricao_viatransporte''',
'                AND traducao_viatransporte.id_idioma = #IDIOMA#            ',
'',
'        LEFT JOIN VW_TRADUCOES_GERAL traducao_local_embarque',
'                ON traducao_local_embarque.id_chave_entidade = a.id_local_embarque',
'                AND traducao_local_embarque.nome_entidade = ''ng_localembarquedesembarque''',
'                AND traducao_local_embarque.nome_coluna = ''nome_local''',
'                AND traducao_local_embarque.id_idioma = #IDIOMA#      ',
'',
'        LEFT JOIN VW_TRADUCOES_GERAL traducao_local_desembarque',
'                ON traducao_local_desembarque.id_chave_entidade = a.id_local_desembarque',
'                AND traducao_local_desembarque.nome_entidade = ''ng_localembarquedesembarque''',
'                AND traducao_local_desembarque.nome_coluna = ''nome_local''',
'                AND traducao_local_desembarque.id_idioma = #IDIOMA#',
'',
'        join vw_dominio_traduzido dominio1',
'          on dominio1.nome_entidade = lower(''imp_pedidoimportacao'')',
'         and dominio1.nome_coluna   = lower(''ind_status_pedido_importacao'')',
'         and dominio1.r             = lower(a.ind_status_pedido_importacao)',
'         and dominio1.id_idioma     = #IDIOMA#',
'',
'        left join vw_dominio_traduzido dominio2',
'          on dominio2.nome_entidade = lower(''imp_pedidoimportacao'')',
'         and dominio2.nome_coluna   = lower(''ind_todos_itens_com_entregas_programadas'')',
'         and dominio2.r             = lower(a.ind_todos_itens_com_entregas_programadas)',
'         and dominio2.id_idioma     = #IDIOMA#        ',
'',
'        where #condicao1# ',
'        ~'';       ',
'',
'        if p_param4 is not null then',
'            l_sql := replace(l_sql,''#condicao1#'',''ind_status_pedido_importacao in (''||fn_trata_lista_in(p_param4)||'')''); ',
'        else',
'            l_sql := replace(l_sql,''#condicao1#'',''1 = 1''); ',
'        end if;',
'',
'        l_sql := replace(l_sql, ''#IDIOMA#'', l_id_idioma);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'        l_region_id number;',
'    begin   ',
'        select region_id ',
'          into l_region_id ',
'          from apex_application_page_regions ',
'         where application_id = v(''APP_ID'') ',
'           and page_id        = v(''APP_PAGE_ID'') ',
'           and static_id      = ''LISTA_CR''; ',
'',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD343'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_pessoa_fisica'',#l_region_id#)) a',
'            order by case when campo5 <> ''4'' then 1 else 2 end, to_timestamp(campo10, ''dd/mm/yyyy hh24:mi:ss'') desc, campo5            ',
'            ~'';',
'        l_sql := replace(l_sql, ''#l_region_id#'', l_region_id);                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then            ',
'            return q''~select * from pkg_util.dominio_retorna_lista(''imp_pedidoimportacao'',''ind_status_pedido_importacao'') order by to_number(r)~'';',
'        elsif campo = ''3'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''imp_pedidoimportacao'',''ind_todos_itens_com_entregas_programadas'')~'';',
'        elsif campo = ''4'' then',
'            return q''~select nome_fantasia d, id_pessoa r from ng_pessoa_juridica~'';',
'        elsif campo = ''5'' then',
'            return q''~select pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',descricao_viatransporte) d, id r from ng_viatransporte~'';',
'        elsif campo = ''6'' then',
'            return q''~select case when b.id_idioma = apex_util.get_session_state(''IDIOMA_LOGADO'') then a.nome_local else coalesce(traducao_localembarquedesembarque.texto_traduzido, a.nome_local) end d, ',
'                        a.id r from ng_localembarquedesembarque a       ',
'                        left join mpd_tenant b on b.id = a.id_tenant',
'                        left join vw_traducoes_geral traducao_localembarquedesembarque',
'                                on traducao_localembarquedesembarque.id_chave_entidade = a.id',
'                                and traducao_localembarquedesembarque.nome_entidade = ''ng_localembarquedesembarque''',
'                                and traducao_localembarquedesembarque.nome_coluna = ''nome_local''',
'                                and traducao_localembarquedesembarque.id_idioma = apex_util.get_session_state(''IDIOMA_LOGADO'')~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    -- function pre_filtro(campo in varchar2)',
'    -- return clob is',
'    -- begin',
'    --     if campo = ''1'' then',
'    --         return q''~select * from pkg_util.dominio_retorna_lista(''imp_pedidoimportacao'',''ind_status_pedido_importacao'')~'';',
'    --     else',
'    --         return null;',
'    --     end if;        ',
'    -- end pre_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    -- function verifica_pre_filtro(campo in varchar2)',
'    -- return boolean is',
'    -- begin',
'    --     if pre_filtro(campo) is null then',
'    --         return false;',
'    --     else',
'    --         return true;',
'    --     end if;    ',
'    -- end verifica_pre_filtro;     ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.numero_pedido_importacao'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_viatransporte'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_exportador'') into l_campo from dual;',
'        elsif campo in (''4'',''F4'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_importador'') into l_campo from dual;',
'        elsif campo in (''5'',''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.ind_status_pedido_importacao'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_local_embarque'') into l_campo from dual;',
'        elsif campo in (''7'',''F6'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_local_desembarque'') into l_campo from dual;        ',
'        elsif campo in (''8'',''F3'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.ind_todos_itens_com_entregas_programadas'') into l_campo from dual;        ',
'        elsif campo = ''9'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.quantidade_entrega'') into l_campo from dual;        ',
'        elsif campo = ''F1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_tenant'') into l_campo from dual;        ',
'        elsif campo = ''F5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.id_viatransporte'') into l_campo from dual;        ',
'        elsif campo = ''R1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.data_confirmacao_pedido'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    -- procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    -- begin',
'    --     if p_card_ou_grid = ''CARD'' then',
'    --         campos := ''data_fim_vigencia, nome_fantasia'';',
'    --     else',
'    --         campos := ''campo5, campo2'';',
'    --     end if;',
'    --     labels := label_coluna(''5'')||'',''||label_coluna(''2'');',
'    -- end campos_ordenacao;',
'',
'    function ordenacao',
'    return varchar2 is',
'    begin',
'        return q''~',
unistr('            select ''N\00E3o finalizados primeiro e '' || pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.data_alteracao'') ||'' (maior para o menor)'' d, ''ORDER1&ORDER2D'' r from dual union all'),
unistr('            select ''N\00E3o finalizados primeiro'' d, ''ORDER1'' r from dual union all'),
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao.data_alteracao'') ||'' (maior para o menor)'' d, ''ORDER2D'' r from dual',
'        ~'';',
'    end;',
'',
'    -- function default_pre_filtro(campo in varchar2)',
'    -- return varchar2 is',
'    -- begin',
'    --     return q''~1:2:3:4:5~'';',
'    -- end;',
'',
'    function default_ordenacao',
'    return varchar2 is',
'    begin',
'        return ''ORDER1&ORDER2D'';',
'    end;',
'',
'',
'end "UI_MPD_TD343";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td347
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155797638927526045)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD347'
,p_sequence=>750
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 26/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD347" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob;    ',
'',
'',
'',
'end "UI_MPD_TD347";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD347" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.id_tenant,',
'                a.codigo_centrocusto titulo,',
'                pkg_traducao.get_traducao(descricao_centrocusto) subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                a.data_fim_vigencia,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo, ',
'                null lista_distintivo,  ',
'                --order',
'                b.nome_fantasia order1,',
'                a.data_fim_vigencia order2,              ',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD347'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD347'') as opcao                ',
'            from ng_centrocusto a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'            return l_sql; ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            b.nome_fantasia campo1,',
'            a.codigo_centrocusto campo2,',
'            pkg_traducao.get_traducao(descricao_centrocusto) campo3,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,            ',
'            a.data_fim_vigencia campo5,             ',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            a.id_tenant filtro1,                                                            ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_centrocusto a               ',
'        join mpd_tenant b on b.id = a.id_tenant             ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD347'') as opcao    ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_centrocusto'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'     function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;     ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_centrocusto.id_tenant'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_centrocusto.descricao_centrocusto'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_centrocusto.codigo_centrocusto'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_centrocusto.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo5,campo3,campo1,campo2'';',
'        else',
'            campos := ''order2,subtitulo,order1,titulo'';',
'        end if;',
'',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo3'';',
'        else',
'            l_campos := ''order2,order1,subtitulo'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;    ',
'',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob',
'    is',
'        l_modo_refresh varchar2(30);',
'    begin',
'        l_modo_refresh := upper(nvl(p_modo_refresh, ''ONCE''));',
'        return q''~',
'            select case',
'                       when exists (',
'                           select 1',
'                             from ng_centrocusto a',
'                            where a.codigo_centrocusto = ''01001''',
'                              and a.data_fim_vigencia is not null',
'                       )',
'                       then ''S''',
'                       else ''N''',
'                   end atualizar,',
'                   ''~'' || l_modo_refresh || q''~'' as modo_refresh',
'              from dual',
'        ~'';',
'    end sql_auto_refresh;    ',
'',
'end "UI_MPD_TD347";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td351
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155798058004518674)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD351'
,p_sequence=>760
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD351" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    -- procedure post(',
'    --     p_id in number default null,',
'    --     p_sucesso out clob,',
'    --     p_messages out pkg_mensagem.message_record_table     ',
'    -- );',
'',
'',
'end "UI_MPD_TD351";',
'/',
'create or replace package body "UI_MPD_TD351" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_descricao clob;',
'        l_id_idioma_tenant number;',
'        l_id_tenant_origem number;',
'        l_somente_leitura varchar2(1);',
'        l_teste boolean := false;',
'        l_url varchar2(4000);',
'    begin',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_centrocusto'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_centrocusto'';  ',
'        select id_tenant into l_id_tenant_origem from ng_centrocusto where id = p_param1;',
'        select id_idioma into l_id_idioma_tenant from mpd_tenant where id = l_id_tenant_origem;     ',
'',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_plain_url => true,',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005',
'        );',
'      ',
'        MERGE INTO temp_formulario tf',
'        USING (',
'            SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, NULL AS nome_consulta, ''N'' AS somente_leitura, ''S'' coluna_tabela, NULL valor FROM dual UNION ALL',
'              SELECT p_codigo_artefato, ''descricao_centrocusto'',   2, '''', to_char(l_url), l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao_centrocusto) from ng_centrocusto where id = p_param1)) valor FROM dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''codigo_centrocusto'', 3, ''TXT'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  5, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 6, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                                                                                                   '
||'                                             ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     7, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_centrocusto where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    -- procedure post(',
'    --     p_id in number default null,        ',
'    --     p_sucesso out clob,',
'    --     p_messages out pkg_mensagem.message_record_table         ',
'    -- )',
'    -- is',
'    --     l_id number;',
'    -- begin',
'    --     bo_srv_idioma.inclui_registro(',
'    --         p_NOME => apex_application.g_f02(1),',
'    --         p_CODIGO => apex_application.g_f03(1),',
'    --         p_SITUACAO => apex_application.g_f09(1),',
'    --         p_id => l_id, ',
'    --         p_sucesso => p_sucesso,',
'    --         p_messages => p_messages',
'    --     );',
'    -- end;',
'',
'end "UI_MPD_TD351";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td353
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155799532057509086)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD353'
,p_sequence=>770
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD353" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD353";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD353" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(a.nome_pais) || '' - (''||a.codigo_iso||'')'' titulo,                ',
'                a.codigo_siscomex subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                   ',
'                null lista_distintivo,                ',
'                a.data_fim_vigencia,',
'                b.nome_fantasia,',
'                a.codigo_iso,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD353'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD353'') as opcao                ',
'            from ng_pais a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            pkg_traducao.get_traducao(a.nome_pais) campo2,',
'            a.codigo_iso campo3,',
'            a.codigo_siscomex campo4,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            a.data_fim_vigencia campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            a.id_tenant filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_pais a',
'        join mpd_tenant b on b.id = a.id_tenant',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD353'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_pais'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pais.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pais.nome_pais'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pais.codigo_iso'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pais.codigo_siscomex'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pais.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo2,campo3,campo4'';',
'        else',
'            campos := ''data_fim_vigencia,nome_fantasia,titulo,codigo_iso,subtitulo'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''3'') || '','' ||',
'               label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2,campo3'';',
'        else',
'            l_campos := ''data_fim_vigencia,nome_fantasia,titulo,codigo_iso'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD353";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td356
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155800008387505444)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD356'
,p_sequence=>780
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD356" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD356";',
'/',
'create or replace package body "UI_MPD_TD356" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;        ',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pais'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_pais'';             ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''nome_pais'',          3, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(nome_pais) from ng_pais where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_iso'',         4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_siscomex'',    5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 7, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     8, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_pais where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD356";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td358
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155800981899498129)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD358'
,p_sequence=>790
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD358" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD358";',
'/',
'create or replace package body "UI_MPD_TD358" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_consulta_estado clob;',
'        l_consulta_cidade clob;        ',
'    begin',
'        -- prc_enviar_parametros(''TD358'',''id_pais'', p_param1);        ',
'        -- l_consulta_estado := ''select nome_estado d, id r from ng_estado where id_pais = (select id from ng_pais where nome_pais = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_'
||'id||'''''' and upper(c001) = upper(''''f06_0000''''))) '';        ',
'        -- l_consulta_cidade := ''select nome_cidade d, id r from ng_cidade where id_pais = (select id from ng_pais where nome_pais = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_'
||'id||'''''' and upper(c001) = upper(''''f06_0000''''))) '';',
'        prc_enviar_parametros(''TD358'',''id_pais'',p_param1);',
'        prc_enviar_parametros(''TD358'',''id_estado'',p_param1);',
'        l_consulta_estado := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(a.nome_estado), id, 1 from ng_estado a where id_pais = (select id from ng_pais np where pkg_traducao.get_traducao(np.n'
||'ome_pais) = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f07_0000''''))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_da'
||'te(current_date))) order by ordem, d'';        ',
'        l_consulta_cidade := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(a.nome_cidade), a.id, 1 from ng_cidade a where a.id_pais = (select np.id from ng_pais np where pkg_traducao.get_traduc'
||'ao(np.nome_pais) = (select c002 from apex_collections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f07_0000''''))) and ((select c002 from apex_collections where collection_n'
||'ame = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f09_0000'''')) is null or a.id_estado = (select ne.id from ng_estado ne where pkg_traducao.get_traducao(ne.nome_estado) = (select c002 from apex_c'
||'ollections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f09_0000'''')))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_date(current_date))) order by'
||' ordem, d'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica where'
||' id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',               2, ''HID'', NULL, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''titulo_endereco'',         3, ''HID'', NULL, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_postal'',           4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais'',                 5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_estado'',               7, ''POP1'', l_consulta_estado, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cidade'',               9, ''POP1'', l_consulta_cidade, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''bairro'',                 11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''logradouro'',             12, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero'',                 13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''complemento'',            14, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''etiqueta_endereco'',      15, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_endereco_principal'', 16, '''', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'        function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_estado'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_pais in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD358_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f06_0000'')',
'                    )',
'                ~'';',
'             elsif  upper(p_campo) = upper(''id_cidade'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_estado in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD358_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f08_0000'')',
'                    )',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'     end;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_pessoa_endereco where id_pessoa = (select id_pessoa from ng_pessoa_juridica where id = p_paramentro);',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is        ',
'    begin        ',
'        bo_ng_pessoa_endereco.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa => apex_application.g_f02(1),',
'            p_titulo_endereco => apex_application.g_f03(1),',
'            p_codigo_postal => apex_application.g_f04(1),            ',
'            p_id_pais => apex_application.g_f05(1),',
'            p_id_estado => apex_application.g_f07(1),',
'            p_id_cidade => apex_application.g_f09(1),',
'            p_bairro => apex_application.g_f11(1),',
'            p_logradouro => apex_application.g_f12(1),',
'            p_numero => apex_application.g_f13(1),',
'            p_complemento => apex_application.g_f14(1),',
'            p_etiqueta_endereco => replace(replace(apex_application.g_f15(1), chr(13), ''''), chr(10), ''<br/>''),',
'            p_ind_endereco_principal => apex_application.g_f16(1),',
'            p_data_integracao => null,',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                pkg_traducao.get_traducao(a.titulo_endereco) campo1,                ',
'                pkg_traducao.get_traducao(d.nome_cidade) campo2,',
'                pkg_traducao.get_traducao(e.nome_pais) campo3,',
'                a.logradouro campo4,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_endereco'', ''ind_endereco_principal'', a.ind_endereco_principal) campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD358'') opcao',
'            from ng_pessoa_endereco a',
'            join ng_pessoa          b on b.id = a.id_pessoa         ',
'            join ng_pessoa_juridica c on c.id_pessoa = b.id',
'            left join ng_cidade     d on d.id = a.id_cidade  ',
'            left join ng_pais       e on e.id = a.id_pais          ',
'            where c.id = #param1#',
'            order by campo1, campo2 nulls first',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select     ',
'                null selected,   ',
'                a.id,',
'                pkg_traducao.get_traducao(a.titulo_endereco) campo1,                ',
'                pkg_traducao.get_traducao(d.nome_cidade) campo2,',
'                pkg_traducao.get_traducao(e.nome_pais) campo3,',
'                a.logradouro campo4,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_endereco'', ''ind_endereco_principal'', a.ind_endereco_principal) campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD358'') opcao',
'            from ng_pessoa_endereco a',
'            join ng_pessoa b on b.id = a.id_pessoa         ',
'            join ng_pessoa_juridica c on c.id_pessoa = b.id',
'            left join ng_cidade     d on d.id = a.id_cidade  ',
'            left join ng_pais       e on e.id = a.id_pais             ',
'            where c.id = #param1#',
'            order by campo1, campo2 nulls first',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.titulo_endereco'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.id_cidade'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.id_pais'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.logradouro'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.ind_endereco_principal'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD549,TD549,''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD358";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td359
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155801405810493688)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD359'
,p_sequence=>800
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 02/06/2026',
unistr('-- Motivo: Ajuste na ordena\00E7\00E3o dos dados na tela'),
'-- Desenvolvedor: Jonathan',
'-- Jira: PNG-260',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD359" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'    ',
'end "UI_MPD_TD359";',
'/',
'create or replace package body "UI_MPD_TD359" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'             select distinct',
'               a.id,               ',
'               b.codigo_moeda||''-''||b.descricao_moeda||'' - ''||c.codigo_moeda||''-''||c.descricao_moeda titulo,',
'               d.nome_fantasia subtitulo,               ',
'               pkg_data.fmtd(a.data_cotacao, ''DATA'') distintivo,',
'               null class_distintivo,         ',
'               null icon,',
'               null lista_distintivo,',
'',
'               --order',
'               b.codigo_moeda||'' - ''||pkg_traducao.get_traducao(b.descricao_moeda) order1,',
'               c.codigo_moeda||'' - ''||pkg_traducao.get_traducao(c.descricao_moeda) order2,',
'               a.valor_taxa_compra order3,',
'               a.valor_taxa_venda order4,',
'               a.data_cotacao order5,',
'               ',
'               --ATRIBUTOS',
'               pkg_componentes.html_card_colunas(''ng_moeda_cotacao.id_moeda_origem'', pkg_traducao.get_traducao(b.descricao_moeda), 3) as atributo1,',
'               pkg_componentes.html_card_colunas(''ng_moeda_cotacao.id_moeda_destino'', pkg_traducao.get_traducao(c.descricao_moeda), 3) as atributo2,               ',
'               pkg_componentes.html_card_colunas(''ng_moeda_cotacao.valor_taxa_compra'', replace(to_char(a.valor_taxa_compra, ''FML999G999G999G999G990D000000''),''R$'',''''), 3)  as atributo3,',
'               pkg_componentes.html_card_colunas(''ng_moeda_cotacao.valor_taxa_venda'',  replace(to_char(a.valor_taxa_venda, ''FML999G999G999G999G990D000000''), ''R$'', ''''), 3) as atributo4,',
'               --FILTROS',
'               a.id_moeda_origem filtro2,',
'               a.id_moeda_destino filtro3,',
'               a.id_tenant filtro1,               ',
'               null FILTRO_MULT1,',
'               null FILTRO_MULT2,  ',
'               --TECNICO',
'               pkg_ui.url_mais_detalhes(''TD359'',a.id) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(a.id,''TD359'') as opcao                ',
'            from ng_moeda_cotacao a ',
'            left join ng_moeda b on b.id = a.id_moeda_origem           ',
'            left join ng_moeda c on c.id = a.id_moeda_destino',
'            left join mpd_tenant d on d.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'            return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            d.nome_fantasia campo1,',
'            b.codigo_moeda||'' - ''||pkg_traducao.get_traducao(b.descricao_moeda) campo2,',
'            c.codigo_moeda||'' - ''||pkg_traducao.get_traducao(c.descricao_moeda) campo3, ',
'            --a.data_cotacao campo4,       ',
'            pkg_data.fmtd(a.data_cotacao, ''DATA'') campo4,       ',
'            replace(to_char(a.valor_taxa_compra, ''FML999G999G999G999G990D000000''), ''R$'', '''') campo5,',
'            replace(to_char(a.valor_taxa_venda, ''FML999G999G999G999G990D000000''), ''R$'', '''') campo6,    ',
'            a.valor_taxa_compra campo7,                                      ',
'            a.valor_taxa_venda  campo8,                                      ',
'            a.data_cotacao      campo9,      ',
'            null                campo10,   ',
'            a.id_tenant filtro1,                             ',
'            a.id_moeda_origem filtro2,',
'            a.id_moeda_destino filtro3,                              ',
'            null filtro4,                               ',
'            null filtro5,',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                              ',
'            null opcao',
'         from ng_moeda_cotacao a ',
'            left join ng_moeda b on b.id = a.id_moeda_origem           ',
'            left join ng_moeda c on c.id = a.id_moeda_destino  ',
'            left join mpd_tenant d on d.id = a.id_tenant',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                to_number(campo7) campo7,',
'                to_number(campo8) campo8,',
'                TO_DATE(campo9, ''DD/MM/YYYY'') campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD359'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_moeda_cotacao'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'         elsif campo = ''2'' then',
'            return q''~',
'                select pkg_traducao.get_traducao(descricao_moeda)',
'                     d,',
'                    id r',
'                from ng_moeda a',
'            ~'';',
'        elsif campo = ''3'' then',
'            return q''~',
'                select pkg_traducao.get_traducao(descricao_moeda) d,',
'                    id r',
'                from ng_moeda a',
'            ~'';               ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.data_cotacao'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.valor_taxa_compra'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.valor_taxa_venda'') into l_campo from dual;',
'        elsif campo in (''3'',''F3'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.id_moeda_destino'') into l_campo from dual;',
'        elsif campo in (''2'',''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.id_moeda_origem'') into l_campo from dual;',
'        elsif campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_moeda_cotacao.id_tenant'') into l_campo from dual;',
'        end if;',
'        ',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo9,campo7,campo8'';',
'        else',
'            campos := ''subtitulo,order1,order2,order5,order3,order4'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'') || '','' ||',
'        label_coluna(''6'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''1'') || '','' ||',
'               label_coluna(''2'') || '','' ||',
'               label_coluna(''3'') || '','' ||',
'               label_coluna(''4'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo1,campo2,campo3,campo9'';',
'        else',
'            l_campos := ''subtitulo,order1,order2,order5'';',
'        end if;',
'',
'        l_direcoes := ''ASC,ASC,ASC,DESC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD359";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td364
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155804384741410452)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD364'
,p_sequence=>810
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD364" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD364";',
'/',
'create or replace package body "UI_MPD_TD364" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, null AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL                          '
||' ',
'               SELECT p_codigo_artefato, ''id_moeda_origem'',   3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_destino'',  5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_cotacao'',      7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''valor_taxa_compra'', 8, '''', null, ''N'',''S'', null valor FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''valor_taxa_venda'',  9, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 10, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     11, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_moeda_cotacao where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD364";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td366
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155804502886406597)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD366'
,p_sequence=>820
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD366" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD366";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD366" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.id_tenant,',
'                to_char(a.codigo_cfop) titulo,',
'                pkg_traducao.get_traducao(a.descricao_cfop) subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo, ',
'                null lista_distintivo,',
'                --order',
'                b.nome_fantasia order1,',
'                a.data_fim_vigencia order2,',
'',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                pkg_ui.url_mais_detalhes(''TD366'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD366'') as opcao                ',
'            from ng_cfop a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'            return l_sql; ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            b.nome_fantasia campo1,',
'            to_char(a.codigo_cfop) campo2,',
'            pkg_traducao.get_traducao(a.descricao_cfop) campo3,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            a.data_fim_vigencia campo5,             ',
'            null              campo6,             ',
'            null              campo7,             ',
'            null              campo8,                                      ',
'            null              campo9,      ',
'            null              campo10,      ',
'            a.id_tenant filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                           ',
'            null opcao',
'        from ng_cfop a',
'        join mpd_tenant b on b.id = a.id_tenant             ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select         ',
'                id,       ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD366'') as opcao  ',
'             from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_cfop'')) a',
'            order by #ORDER#   ',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));        ',
'        return l_sql;',
'    end sql_report;',
'',
'      function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cfop.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cfop.descricao_cfop'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cfop.codigo_cfop'') into l_campo from dual;',
'          elsif campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cfop.id_tenant'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'   ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo5'';',
'        else',
'            campos := ''order1,titulo,subtitulo,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2'';',
'        else',
'            l_campos := ''order2,order1,titulo'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD366";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td371
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155805086345402453)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD371'
,p_sequence=>830
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD371" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD371";',
'/',
'create or replace package body "UI_MPD_TD371" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (--SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica whe'
||'re id = p_param1)) valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''id_pessoa'',          2, ''HID'', null, ''N'', ''N'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''id_pessoa_fisica'',   3, ''POP'', ''R_NG_PESSOA_CONTATO.ID_PESSOA_FISICA'', ''N'', ''N'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''id_departamento'',    5, ''POP'', ''R_NG_DEPARTAMENTO.NOME_DEPARTAMENTO'', ''N'', ''N'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''id_cargo'',           7, ''POP'', ''R_NG_CARGO.DESCRICAO_CARGO'', ''N'', ''N'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''ind_forma_contato'',  9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''dado_contato'',      10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''ind_whatsapp'',      11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''observacao'',        12, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''data_fim_vigencia'', 13, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica where'
||' id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',          2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_fisica'',   3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_departamento'',    5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cargo'',           7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'', 13, '''', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_pessoa_contato_dado where id_pessoa_contato = (select id from ng_pessoa_contato where id_pessoa = (select id_pessoa from ng_pessoa_juridica where id = p_paramentro)); ',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;    ',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_ind_whataspp varchar2(1);',
'    begin        ',
'        bo_ng_pessoa_contato.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa => apex_application.g_f02(1),',
'            p_id_pessoa_fisica => apex_application.g_f03(1),',
'            p_id_departamento => apex_application.g_f05(1),',
'            p_id_cargo => apex_application.g_f07(1),',
'            p_data_fim_vigencia => apex_application.g_f13(1),',
'            p_data_integracao => null,            ',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_traducao.get_traducao(d.nome_departamento) campo2,',
'                pkg_traducao.get_traducao(e.descricao_cargo) campo3,',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') campo4,',
'                a.data_fim_vigencia campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD371'') opcao',
'            from ng_pessoa_contato a            ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica',
'            left join ng_departamento d on d.id = a.id_departamento',
'            left join ng_cargo e on e.id = a.id_cargo',
'            where b.id = #param1#',
'            order by to_date(campo5, ''dd/mm/yyyy'') nulls first, campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select      ',
'                null selected,  ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_traducao.get_traducao(d.nome_departamento) campo2,',
'                pkg_traducao.get_traducao(e.descricao_cargo) campo3,',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') campo4,',
'                a.data_fim_vigencia campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD371'') opcao',
'            from ng_pessoa_contato a            ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica',
'            left join ng_departamento d on d.id = a.id_departamento',
'            left join ng_cargo e on e.id = a.id_cargo',
'            where b.id = #param1#',
'            order by to_date(campo5, ''dd/mm/yyyy'') nulls first, campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_pessoa_fisica'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_departamento'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_cargo'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_PARAMETRO2,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD417,TD417,''||p_param1||'',''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD371";',
'/'))
);
end;
/
