,p_name=>'UI_MPD_TD372'
,p_sequence=>840
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD372" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD372";',
'/',
'create or replace package body "UI_MPD_TD372" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica where'
||' id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',                2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_conta_bancaria'', 3, ''HID'', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''agencia_bancaria'',         4, ''POP'', ''R_NG_PESSOA_AGENCIABANCARIA.NOME_FANTASIA'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''conta_bancaria'',           6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                 7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_conta_exterior'',       9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',       10, '''', null, ''N'', ''S'', null valor FROM dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_pessoa_contabancaria where id_pessoa = (select id_pessoa from ng_pessoa_juridica where id = p_paramentro);',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;    ',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_ng_pessoa_contabancaria.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa => apex_application.g_f02(1),',
'            p_descricao_conta_bancaria => apex_application.g_f03(1),',
'            p_agencia_bancaria => apex_application.g_f04(1),            ',
'            p_conta_bancaria => apex_application.g_f06(1),',
'            p_id_moeda => apex_application.g_f07(1),',
'            p_ind_conta_exterior => apex_application.g_f09(1),            ',
'            p_data_fim_vigencia => apex_application.g_f10(1),            ',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                a.descricao_conta_bancaria campo1,',
'                (select nome_fantasia from ng_pessoa_juridica where id_pessoa = a.agencia_bancaria) campo2,',
'                a.conta_bancaria campo3,',
'                pkg_traducao.get_traducao(.descricao_moeda) campo4,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contabancaria'', ''ind_conta_exterior'', a.ind_conta_exterior) campo5,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo6,',
'                a.data_fim_vigencia campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD372'') opcao',
'            from ng_pessoa_contabancaria a',
'            join ng_pessoa b on b.id = a.id_pessoa         ',
'            join ng_pessoa_juridica c on c.id_pessoa = b.id',
'            left join ng_moeda d on d.id = a.id_moeda',
'            where c.id = #param1#',
'            order by to_date(campo7,''dd/mm/yyyy'') nulls first, campo2, campo3',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select        ',
'                null selected,',
'                a.id,',
'                a.descricao_conta_bancaria campo1,',
'                (select a.nome_fantasia from ng_pessoa_juridica a join ng_pessoa_agenciabancaria b on b.id_pessoa = a.id_pessoa where b.id = a.agencia_bancaria) campo2,',
'                a.conta_bancaria campo3,',
'                pkg_traducao.get_traducao(d.descricao_moeda) campo4,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contabancaria'', ''ind_conta_exterior'', a.ind_conta_exterior) campo5,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    --pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo6,',
'                a.data_fim_vigencia campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD372'') opcao',
'            from ng_pessoa_contabancaria a',
'            join ng_pessoa b on b.id = a.id_pessoa         ',
'            join ng_pessoa_juridica c on c.id_pessoa = b.id',
'            left join ng_moeda d on d.id = a.id_moeda',
'            where c.id = #param1#',
'            order by to_date(campo7,''dd/mm/yyyy'') nulls first, campo2, campo3',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.descricao_conta_bancaria'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.agencia_bancaria'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.conta_bancaria'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.id_moeda'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.ind_conta_exterior'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD305,TD305,''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD372";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td380
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155805632823393343)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD380'
,p_sequence=>850
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD380" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'     procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD380";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD380" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',descricao_viatransporte) || '' <i class="fa '' || c.d || ''"></i>'' titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia, ''dd/mm/yyyy'') < to_date(current_date, ''dd/mm/yyyy'') then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                a.data_fim_vigencia,',
'                null lista_distintivo,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO ',
'                pkg_ui.url_mais_detalhes(''TD380'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD380'') as opcao                ',
'            from ng_viatransporte a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            JOIN TABLE(pkg_util.dominio_retorna_lista(''ng_viatransporte'',''icone_viatransporte'')) c ON c.r = a.icone_viatransporte',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'    ',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'        return clob is',
'            l_sql clob;',
'        begin   ',
'            l_sql := q''~',
'             select distinct',
'                a.id,',
'                b.nome_fantasia campo1,',
'                pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',descricao_viatransporte) campo2,',
'                ''<i class="fa '' || c.d || ''"></i>'' campo3,',
'                a.codigo_siscomex campo4,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                END AS campo5,',
'                a.data_fim_vigencia campo6,',
'                null campo7,           ',
'                null campo8,',
'                null campo9,',
'                null campo10, ',
'                --FILTROS',
'                a.id_tenant       filtro1,                                ',
'                null              filtro2,                                ',
'                null              filtro3,                                ',
'                null              filtro4,',
'                null              filtro5,                                ',
'                --FILTROS MULTI',
'                null              filtro_mult1,                                ',
'                null              filtro_mult2,                                ',
'                null              filtro_mult3, ',
'                null              filtro_mult4,                                ',
'                null              filtro_mult5,                                ',
'                null opcao                ',
'            from ng_viatransporte a ',
'            JOIN mpd_tenant b ON a.id_tenant = b.id  ',
'            JOIN TABLE(pkg_util.dominio_retorna_lista(''ng_viatransporte'',''icone_viatransporte'')) c ON c.r = a.icone_viatransporte    ',
'       ~''; ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select   ',
'                id,             ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD380'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_viatransporte'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo in (''1'', ''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_viatransporte.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_viatransporte.descricao_viatransporte'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_viatransporte.icone_viatransporte'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_viatransporte.codigo_siscomex'') into l_campo from dual;',
'        end if;       ',
'            return l_campo;',
'    end label_coluna;',
'',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo2'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,titulo'';',
'        end if;',
'',
'        select pkg_ui.retorna_label_tela(''fim_de_vigencia'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select pkg_ui.retorna_label_tela(''fim_de_vigencia'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD380";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td383
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155806071380389979)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD383'
,p_sequence=>860
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD383" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD383";',
'/',
'create or replace package body "UI_MPD_TD383" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is      ',
'    begin   ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''descricao_viatransporte'', 3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_siscomex'',         4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''icone_viatransporte'',     5, ''ICO'', null, ''N'', ''S'', (select decode(descricao_viatransporte, 1, ''fa-ship'', 2, ''fa-battleship'', 3, ''fa-battleship'', 4, ''fa-plane'', 5, ''fa-envelope-arrow-up'', 6, ''fa-subway'', 7, '''
||'fa-truck'', 8, ''fa-plug'', 9, ''fa-car'', 10, ''fa-redo-alt'', 11, ''fa-bus'', 12, ''fa-suitcase'', 13, ''fa-military-vehicle'', null) from ng_viatransporte where id = p_param1) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',       6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',      9, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',         10, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_viatransporte where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD383";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td397
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155807052622380284)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD397'
,p_sequence=>870
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD397" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'',
'end "UI_MPD_TD397";',
'/',
'create or replace package body "UI_MPD_TD397" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, (select to_char(id_tenant) from ng_pais where id = p_pa'
||'ram1) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_tabela'',       3, ''HID'', NULL, ''N'',''S'',  p_param2 valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_chave_tabela'', 4, ''HID'', NULL, ''N'',''S'',  p_param1 valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma'',       5, '''',    NULL, ''S'',''S'',  null     valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao'',       6, '''',    null, ''N'',''S'',  null     valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 7, ''SEL'', ''R_MPD_USUARIO.NOME'' as nome_consulta, ''N'',''S'', null valor FROM dual UNION ALL                ',
'               SELECT p_codigo_artefato, ''data_alteracao'',  8, ''TXT'',    null, ''N'',''S'',  null     valor FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);        ',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )',
'    is',
'        l_id number;',
'    begin',
'        bo_mpd_descricao.altera_registro(',
'            p_id_tenant => apex_application.g_f02(1),',
'            p_id_tabela => apex_application.g_f03(1),',
'            p_id_chave_tabela => apex_application.g_f04(1),',
'            p_id_idioma => apex_application.g_f05(1),',
'            p_descricao => apex_application.g_f06(1),',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f07(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );        ',
'    end;   ',
'',
'end "UI_MPD_TD397";',
'/'))
);
end;
