prompt --application/deployment/install/install_ui_mpd_td399
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155807201464376568)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD399'
,p_sequence=>880
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD399" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD399";',
'/',
'create or replace package body "UI_MPD_TD399" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id id,',
'                a.id_tenant,',
'                pkg_traducao.get_traducao(nome_departamento) titulo,',
'                b.nome_fantasia subtitulo,',
'                 case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                a.data_fim_vigencia,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,    ',
'                null lista_distintivo,',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                pkg_ui.url_mais_detalhes(''TD399'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD399'') as opcao                ',
'            from ng_departamento a',
'            join mpd_tenant b on b.id = a.id_tenant',
'           order by 6 nulls first, 4, 3',
'            ~'';',
'          --  l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));            ',
'            return l_sql;        ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            pkg_traducao.get_traducao(nome_departamento) campo2,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo3,',
'            a.data_fim_vigencia campo4,               ',
'            null              campo5,             ',
'            null              campo6,             ',
'            null              campo7,             ',
'            null              campo8,                                      ',
'            null              campo9,      ',
'            null              campo10,     ',
'            a.id_tenant filtro1,                             ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                            ',
'            null opcao',
'        from ng_departamento a',
'        join mpd_tenant b on b.id = a.id_tenant             ',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select   ',
'                id,             ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD399'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_departamento'')) a',
'           order by to_date(campo4) nulls first, campo1, campo2',
'            ~'';',
'       -- l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'   function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_departamento.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_departamento.id_tenant'') into l_campo from dual;',
'            elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_departamento.nome_departamento'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''nome_departamento'';',
'        else',
'            campos := ''campo2'';',
'        end if;',
'        labels := label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'',
'end "UI_MPD_TD399";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td402
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155807415311372750)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD402'
,p_sequence=>890
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD402" as    ',
'    ',
'    v_pessoa_agenciabancaria ng_pessoa_agenciabancaria%rowtype;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD402";',
'/',
'create or replace package body "UI_MPD_TD402" as',
'',
'    /********************************************',
'     P_PARAM1 = ID DA ENTIDADE NG_PESSOA_JURIDICA',
'    *********************************************/',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        select a.* into v_pessoa_agenciabancaria from ng_pessoa_agenciabancaria a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa where b.id = p_param1;',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char(v_pessoa_agenciabancaria.id_tenant) valor FROM dua'
||'l UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',            2, ''HID'', null, ''S'',''S'', to_char(v_pessoa_agenciabancaria.id_pessoa) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_grupo_empresarial'', 3, ''POP'', ''R_NG_GRUPOEMPRESARIAL.NOME_GRUPO'', ''S'',''N'', to_char((select id_grupo_empresarial from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''razao_social'',         5, ''TXT'', null, ''S'',''N'', to_char((select razao_social from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_fantasia'',        6, ''TXT'', null, ''S'',''N'', to_char((select nome_fantasia from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_agencia'',       7, '''', null, ''S'',''S'', to_char(v_pessoa_agenciabancaria.numero_agencia) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''digito_verificador'',   8, '''', null, ''S'',''N'', to_char(v_pessoa_agenciabancaria.digito_verificador) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    9, ''DAT'', null, ''S'',''N'', pkg_data.fmtd((select data_fim_vigencia from ng_pessoa a join ng_pessoa_juridica b on b.id_pessoa = a.id where b.id = p_param1),''DATA'') valor FROM dual UNION AL'
||'L',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',  10, ''SEL'', ''R_MPD_USUARIO.NOME'', ''S'', ''S'', to_char(v_pessoa_agenciabancaria.id_usuario_alterou) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',      11, ''TXT'', null, ''S'', ''N'', pkg_data.fmt(v_pessoa_agenciabancaria.data_alteracao, ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD402";',
'/'))
);
end;
/
