prompt --application/deployment/install/install_ui_mpd_td405
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155807914666363667)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD405'
,p_sequence=>910
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD405" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'    ',
'end "UI_MPD_TD405";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD405" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'        select distinct ',
'            a.id ,',
'            pkg_traducao.get_traducao(a.nome_cidade) titulo,',
'            (c.sigla_uf||('' '')||pkg_traducao.get_traducao(d.nome_pais)) subtitulo,',
'            case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'            end class_distintivo,',
'            a.data_fim_vigencia,',
'            pkg_traducao.get_traducao(d.nome_pais),',
'            c.sigla_uf ,',
'            b.razao_social,',
'            null lista_distintivo,',
unistr('            --COLUNAS N\00C3O UTILIZADAS'),
'            a.id_tenant,',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            null FILTRO_MULT1,',
'            null FILTRO_MULT2,  ',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD405'',a.id) url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id,''TD405'') as opcao',
'        from ng_cidade  a',
'        JOIN mpd_tenant b ON a.id_tenant = b.id',
'        left JOIN ng_estado  c ON c.id = a.id_estado',
'             JOIN ng_pais    d ON d.id = a.id_pais',
'        order by #ORDER# ',
'       ~'';',
'       l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1'')); ',
'       return l_sql;   ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'        return clob is',
'            l_sql clob;',
'            ',
'        begin   ',
'            l_sql := q''~',
'            select',
'                a.id ,',
'                b.razao_social              campo1,',
'                pkg_traducao.get_traducao(a.nome_cidade) campo2,',
'                c.sigla_uf                  campo3,',
'                pkg_traducao.get_traducao(d.nome_pais) campo4,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end                         campo5,',
'                a.data_fim_vigencia         campo6, ',
'                null                        campo7,',
'                null                        campo8,',
'                null                        campo9,',
'                null                        campo10,',
'                 --FILTROS',
'                a.id_tenant                 filtro1,                                ',
'                null                        filtro2,                                ',
'                null                        filtro3,                                ',
'                null                        filtro4,',
'                null                        filtro5,                                ',
'                --FILTROS MULTI',
'                null                        filtro_mult1,                                ',
'                null                        filtro_mult2,                                ',
'                null                        filtro_mult3, ',
'                null                        filtro_mult4,                                ',
'                null                        filtro_mult5,',
'                null opcao',
'            from ng_cidade  a',
'            left JOIN ng_estado  c ON c.id = a.id_estado',
'            JOIN ng_pais    d ON d.id = a.id_pais',
'            JOIN mpd_tenant b ON a.id_tenant = b.id',
'            left JOIN ng_estado  c ON c.id = a.id_estado',
'            JOIN ng_pais    d ON d.id = a.id_pais',
'      ',
'',
'       ~'';',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD405'') as opcao',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_cidade'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));',
'            return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''ng_cidade.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_tela(''cidade'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_tela(''estado'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_tela(''pais'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_cidade.data_fim_vigencia'') into l_campo from dual;        ',
'        elsif campo = ''F1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_cidade.id_tenant'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,filtro1,campo4,campo3,campo2'';',
'        else',
'            campos := ''data_fim_vigencia,filtro1,subtitulo,sigla_uf,titulo'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''4'') || '','' ||',
'               label_coluna(''3'') || '','' ||',
'               label_coluna(''2'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,filtro1,campo4,campo3,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,filtro1,subtitulo,sigla_uf,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD405";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td406
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155808438410353480)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD406'
,p_sequence=>920
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD406" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'',
'end "UI_MPD_TD406";',
'/',
'create or replace package body "UI_MPD_TD406" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        consulta clob;          ',
'    begin         ',
'        prc_enviar_parametros(''TD406'',''id_estado'',p_param1);',
'        consulta := ''select nome_estado d, id r from ng_estado where id_pais = (select id from ng_pais where nome_pais = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and '
||'upper(c001) = upper(''''f04_0000''''))) '';   ',
'  ',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',       2, ''SEL'', TO_CLOB(''R_MPD_TENANT.DESCRICAO_IDIOMA''), ''S'',''N'', null valor FROM dual UNION ALL     ',
'               SELECT p_codigo_artefato, ''nome_cidade'',             7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais'',                 3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_estado'',               5, ''POP1'', consulta, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',       8, '''', null, ''N'',''S'', null valor FROM dual                ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'        function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_estado'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_pais in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD406_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f04_0000'')',
'                    )',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'        end;',
'',
'',
'    procedure post(',
'        p_id in number,    ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_ng_cidade.inclui_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),  ',
'            p_nome_cidade => apex_application.g_f07(1),',
'            p_id_pais => apex_application.g_f03(1),',
'            p_id_estado => apex_application.g_f05(1),',
'            p_data_fim_vigencia => apex_application.g_f08(1),',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'end "UI_MPD_TD406";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td407
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155808658509348907)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD407'
,p_sequence=>930
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD407" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'end "UI_MPD_TD407";',
'/',
'create or replace package body "UI_MPD_TD407" as    ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'        consulta clob;',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_id_idioma_logado number := apex_util.get_session_state(''IDIOMA_LOGADO'');',
'        l_id_idioma_tenant number;',
'        l_id_tenant_origem number;',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);       ',
'        l_teste varchar2(2000);       ',
'        l_existe number;     ',
'        l_url varchar2(4000);  ',
'    begin ',
'        select nome_pais into l_teste from ng_cidade a join ng_pais b on b.id = a.id_pais where a.id = p_param1;',
'        prc_enviar_parametros2(p_codigo_artefato,''f04_0000'',l_teste,apex_custom_auth.get_session_id);',
'',
'        consulta := ''select nome_estado d, id r from ng_estado where id_pais = (select id from ng_pais where nome_pais = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and '
||'upper(c001) = upper(''''f04_0000''''))) '';   ',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_cidade'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_cidade'';         ',
'        ',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'       l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, null AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL                          '
||' ',
'               SELECT p_codigo_artefato, ''id_pais'',             3, '''', null, ''N'',''S'', to_char(1) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_estado'',           5, ''POP1'', to_char(consulta), ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_cidade'',         7, '''', l_url,l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(nome_cidade) from ng_cidade where id = p_param1)) valor FROM dual UNION ALL   ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   8, '''', null, ''N'',''S'', null valor FROM dual  UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',      9, '''',    null, ''N'',''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'     function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_estado'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_pais in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD407_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f04_0000'')',
'                    )',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'        end;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )',
'    is',
'        l_id number;',
'    begin',
'        bo_ng_cidade.altera_registro(',
'            p_id_tenant => apex_application.g_f02(1),',
'            p_nome_cidade => apex_application.g_f07(1),',
'            p_id_pais => apex_application.g_f03(1),',
'            p_id_estado => apex_application.g_f05(1),',
'            p_data_fim_vigencia => TO_DATE(apex_application.g_f08(1), ''DD/MM/YYYY''),',
'            p_data_alteracao    => TO_TIMESTAMP(apex_application.g_f09(1), ''DD-MON-RR HH:MI:SS.FF AM'') ,',
'            p_id                => p_id, ',
'            p_sucesso           => p_sucesso,',
'            p_messages          => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD407";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td408
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155809058817344730)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD408'
,p_sequence=>940
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD408" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'end "UI_MPD_TD408";',
'/',
'create or replace package body "UI_MPD_TD408" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_idioma_tenant number;',
'        l_id_tenant_origem number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_cidade'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_cidade'';',
'        select id_tenant into l_id_tenant_origem from ng_cidade where id = p_param1;',
'        select id_idioma into l_id_idioma_tenant from mpd_tenant where id = l_id_tenant_origem;',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'--pkg_data.fmt((select data_alteracao from ng_cidade where id = p_param1), ''DATA_SEGUNDO'')',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''id_pais'',            3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_estado'',          5, ''POP'', ''R_NG_ESTADO.NOME_ESTADO'', ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_cidade'',        7, '''', l_url, ''S'',''S'',to_char((select pkg_traducao.get_traducao(nome_cidade) from ng_cidade where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  8, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 9, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',     10, ''TXT'', null, ''N'', ''S'', null valor from dual',
'               )  new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~ ',
'                    select ind_valor, qtd_decimais',
'                    from ng_atributoitem ',
'                    where id = #ID#  ',
'               ~'';',
'        return replace(l_sql,''#ID#'',p_param1);',
'    end sql_atribuir_valor;',
'',
'',
'end "UI_MPD_TD408";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td412
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155809343484340027)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD412'
,p_sequence=>950
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD412" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD412";',
'/',
'create or replace package body "UI_MPD_TD412" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_consulta clob;',
'    begin',
'        l_consulta := ''select c.nome_abreviado d, c.id_pessoa r from ng_pessoa_contato a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica where b.id = ''||p_param1||'' order by 1'';',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica where'
||' id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_referencia'', 2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_contato'',    3, ''POP1'', to_char(l_consulta), ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_contato'',    9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''dado_contato'',        10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_whatsapp'',        11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',          12, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   13, ''HID'', null, ''N'', ''S'', null valor FROM dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'',
'        function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_pessoa_contato'') then',
'                return ''',
'                    where b.id in (TO_NUMBER(apex_util.get_session_state(''''P9013_PARAMETRO'''')))',
'                '';',
'            else',
'                return '''';',
'            end if;',
'      end;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_pessoa_contato_dado where id_pessoa_contato = (select id from ng_pessoa_contato where id_pessoa = (select id_pessoa from ng_pessoa_juridica where id = p_paramentro)); ',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;    ',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_ind_whatsapp varchar2(1);',
'    begin        ',
'        if lower(apex_application.g_f09(1)) = ''2'' then',
'            l_ind_whatsapp := apex_application.g_f11(1);',
'        else',
'            l_ind_whatsapp := null;',
'        end if;',
'        bo_ng_pessoa_contato_dado.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa_referencia => apex_application.g_f02(1),',
'            p_id_pessoa_contato => apex_application.g_f03(1),            ',
'            p_ind_forma_contato => apex_application.g_f09(1),',
'            p_dado_contato => apex_application.g_f10(1),',
'            p_ind_whatsapp => l_ind_whatsapp,',
'            p_observacao => apex_application.g_f12(1),  ',
'            p_data_fim_vigencia => apex_application.g_f13(1),',
'            p_motivo_rejeicao => null,            ',
'            p_data_integracao => null,            ',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end post_create;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    ) is',
'    begin ',
'        null;',
'    end post;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo2,',
'                a.dado_contato campo3,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_whatsapp'', a.ind_whatsapp) campo4,',
'                pkg_traducao.get_traducao(a.observacao) campo5,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo6,',
'                a.data_fim_vigencia campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD412'') opcao',
'            from ng_pessoa_contato_dado a            ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa_referencia',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_contato',
'            where b.id = #param1#',
'            order by campo1, to_date(campo7, ''dd/mm/yyyy'') nulls first',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                null selected,    ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo2,',
'                a.dado_contato campo3,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_whatsapp'', a.ind_whatsapp) campo4,',
'                pkg_traducao.get_traducao(a.observacao) campo5,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    --pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo6,',
'                a.data_fim_vigencia campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD412'') opcao',
'            from ng_pessoa_contato_dado a            ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa_referencia',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_contato',
'            where b.id = #param1#',
'            order by campo1, to_date(campo7, ''dd/mm/yyyy'') nulls first',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.id_pessoa_contato'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_forma_contato'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.dado_contato'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_whatsapp'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.observacao'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_PARAMETRO2,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD452,TD452,''||p_param1||'',TD313,false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD412";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td677
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155809682094330685)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD677'
,p_sequence=>960
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 04/05/2026',
'-- Motivo: Ajuste para ter nome fantasia',
'-- Jira: IMP00010',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD677" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'',
'',
'    function ordenacao return varchar2;',
'',
'    function default_ordenacao',
'    return varchar2;',
'',
'end "UI_MPD_TD677";',
'/',
'',
'',
'create or replace PACKAGE BODY "UI_MPD_TD677" AS',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_url varchar2(4000);',
'        l_id_idioma number;',
'        l_label_atributo1 varchar2(4000);',
'        l_label_atributo2 varchar2(4000);',
'        l_label_atributo3 varchar2(4000);',
'        l_label_atributo4 varchar2(4000);',
'        l_label_atributo5 varchar2(4000);   ',
'        l_label_atributo6 varchar2(4000);      ',
'    begin   ',
'        l_id_idioma := nvl(apex_util.get_session_state(''IDIOMA_LOGADO''),1);',
'        l_label_atributo1 := pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'');',
'        l_label_atributo2 := pkg_ui.retorna_label_coluna(''imp_entrega.id_exportador'');',
'        l_label_atributo3 := pkg_ui.retorna_label_coluna(''imp_entrega.id_importador'');',
'        l_label_atributo4 := pkg_ui.retorna_label_coluna(''imp_entrega.id_local_embarque'');',
'        l_label_atributo5 := pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_real'');',
'        l_label_atributo6 := pkg_ui.retorna_label_coluna(''imp_entrega.id_invoice'');',
'',
'        l_sql := q''~',
'            select ',
'                a.id,',
'                to_timestamp(a.data_alteracao, ''dd/mm/yyyy hh24:mi:ss''),',
'                to_number(a.num_entrega), ',
'                --CASE WHEN a.id_processoimportacao is null THEN pkg_componentes.html_cor_texto(''~'' || retorna_texto(''msg.93.l'') || q''~'') else i.num_processoimportacao END titulo,',
'                ',
'                CASE WHEN a.id_processoimportacao is null THEN pkg_componentes.html_cor_texto(retorna_texto(''msg.93.l'')) else i.num_processoimportacao END titulo,',
'                b.numero_pedido_importacao  subtitulo,',
'                bo_ng_viatransporte.retorna_icone_viatransporte_card(a.id_viatransporte) icon,',
'                pkg_util.dominio_retorna_tag(''imp_entrega'', ''ind_status_entrega'', a.ind_status_entrega) distintivo,',
'',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO1#'', a.num_entrega, 2,''S'') atributo1, ',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO2#'', e.nome_fantasia, 2,''S'') atributo2,  ',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO3#'', g.nome_fantasia, 2,''S'') atributo3,   ',
'',
'                pkg_componentes.html_card_colunas(',
'                    ''#LABEL_ATRIBUTO4#'', ',
'                    case ',
'                        when h.id_idioma = #IDIOMA#',
'                        then x.nome_local ',
'                        else coalesce(traducao_localembarque.texto_traduzido, x.nome_local) ',
'                    end, ',
'                    2,''S''',
'                ) atributo4,',
'                pkg_componentes.html_card_colunas(',
'                    case',
'                        when a.data_embarque_real is not null then pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_real'')',
'                        when a.data_embarque_informada is not null then pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_informada'')',
'                        else pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_calculada'')',
'                    end,',
'                    coalesce(a.data_embarque_real, a.data_embarque_informada, a.data_embarque_calculada),',
'                    2,',
'                    ''S''',
'                ) atributo5,',
'                pkg_componentes.html_card_colunas(''#LABEL_ATRIBUTO6#'', m.num_invoice, 2,''S'')atributo6,',
'',
'                --FILTROS',
'                a.id_tenant             filtro1,               ',
'                a.ind_status_entrega    filtro2,               ',
'                a.id_importador         filtro3,',
'                a.id_viatransporte      filtro4,',
'                null                    filtro5,',
'                null                    filtro6,',
'                null                    filtro7,',
'                null                    filtro8,',
'                null                    filtro_mult1,  ',
'                null                    filtro_mult2,',
'',
'                --ORDER',
'                a.data_alteracao order1,',
'                a.num_entrega order2, ',
'                     ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD677'',a.id) url_mais_detalhes,                ',
'                pkg_componentes.html_botao_opcao(a.id,''TD677'') as opcao     ',
'',
'                from imp_entrega                  a',
'                JOIN imp_pedidoimportacao         b ON b.id = a.id_pedidoimportacao',
'                JOIN ng_viatransporte             c ON c.id = a.id_viatransporte',
'                JOIN ng_pessoa_juridica           e ON e.id_pessoa = a.id_exportador',
'                JOIN ng_pessoa_juridica           g ON g.id_pessoa = a.id_importador',
'                JOIN mpd_tenant                   h ON h.id = a.id_tenant',
'                left join imp_processoimportacao  i ON i.id = a.id_processoimportacao',
'								left join imp_invoice							m ON m.id = a.id_invoice',
'                left join ng_localembarquedesembarque x ON x.id = a.id_local_embarque',
'                left join ng_localembarquedesembarque y ON y.id = a.id_local_desembarque',
'                left join vw_traducoes_geral traducao_localembarque',
'                        on traducao_localembarque.id_chave_entidade = a.id_local_embarque',
'                        and traducao_localembarque.nome_entidade = ''ng_localembarquedesembarque''',
'                        and traducao_localembarque.nome_coluna = ''nome_local''',
'                        and traducao_localembarque.id_idioma = #IDIOMA#                  ',
'                left join vw_traducoes_geral traducao_localdesembarque',
'                        on traducao_localdesembarque.id_chave_entidade = a.id_local_desembarque',
'                        and traducao_localdesembarque.nome_entidade = ''ng_localembarquedesembarque''',
'                        and traducao_localdesembarque.nome_coluna = ''nome_local''',
'                        and traducao_localdesembarque.id_idioma = #IDIOMA#',
'                where b.ind_status_pedido_importacao = 3                                           ',
'',
'                -- join vw_dom_ng_viatransporte v on v.r = c.icone_viatransporte                                                                         ',
'                -- order by 2 desc,subtitulo,3',
'            ~'';            ',
'            l_sql := replace(l_sql, ''#IDIOMA#'', l_id_idioma);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO1#'', l_label_atributo1);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO2#'', l_label_atributo2);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO3#'', l_label_atributo3);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO4#'', l_label_atributo4);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO5#'', l_label_atributo5);',
'            l_sql := replace(l_sql, ''#LABEL_ATRIBUTO6#'', l_label_atributo6);',
'        return l_sql;                    ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql :=''',
'        select',
'            a.id,                 ',
'            to_timestamp(a.data_alteracao, ''''dd/mm/yyyy hh24:mi:ss''''),                                            ',
'            pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', a.ind_status_entrega)    campo1,',
'                        CASE        ',
'                WHEN a.id_processoimportacao is null THEN',
'                    pkg_componentes.html_cor_texto(''''''||',
'                retorna_texto(''msg.93.l'')||'''''')',
'                ELSE',
'                   i.num_processoimportacao',
'            END  campo2,',
'            b.numero_pedido_importacao                                                                     campo3,',
'            a.num_entrega                                                                                  campo4,',
'            pkg_util.dominio_retorna_tag(''''ng_viatransporte'''',''''descricao_viatransporte'''',descricao_viatransporte) campo5,',
'            e.nome_fantasia                                   campo6,',
'            g.nome_fantasia                                   campo7,           ',
'            case when d.id_idioma = apex_util.get_session_state(''''idioma_logado'''') then f.nome_local else coalesce(traducao_localembarque.texto_traduzido, f.nome_local) end campo8,',
'            CASE',
'                WHEN a.data_embarque_real IS NOT NULL THEN a.data_embarque_real',
'                WHEN a.data_embarque_informada IS NOT NULL THEN a.data_embarque_informada',
'                ELSE a.data_embarque_calculada',
'            END campo9,',
'            m.num_invoice campo10,',
'',
'            --FILTROS',
'                a.id_tenant             filtro1,               ',
'                a.ind_status_entrega    filtro2,               ',
'                a.id_importador         filtro3,',
'                a.id_viatransporte      filtro4,',
'                null                    filtro5,',
'                null                    filtro6,',
'                null                    filtro7,                             ',
'            --FILTROS MULTI',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            a.data_alteracao                                 filtro_mult5,                                ',
'            null opcao',
'            from imp_entrega                  a',
'            JOIN imp_pedidoimportacao         b ON b.id = a.id_pedidoimportacao',
'            JOIN ng_viatransporte             c ON c.id = a.id_viatransporte',
'            JOIN ng_pessoa_juridica           e ON e.id_pessoa = a.id_exportador',
'            JOIN ng_pessoa_juridica           g ON g.id_pessoa = a.id_importador',
'            left join mpd_tenant              d on d.id = a.id_tenant',
'	    			left join imp_invoice							m ON m.id = a.id_invoice',
'            left join ng_localembarquedesembarque f on f.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque h on h.id = a.id_local_desembarque',
'            left join imp_processoimportacao  i ON i.id = a.id_processoimportacao',
'            left join vw_traducoes_geral traducao_viatransporte',
'                    on traducao_viatransporte.id_chave_entidade = a.id_viatransporte',
'                    and traducao_viatransporte.nome_entidade = ''''ng_viatransporte''''',
'                    and traducao_viatransporte.nome_coluna = ''''descricao_viatransporte''''',
'                    and traducao_viatransporte.id_idioma = apex_util.get_session_state(''''idioma_logado'''')                ',
'',
'            left join vw_traducoes_geral traducao_localembarque',
'                    on traducao_localembarque.id_chave_entidade = a.id_local_embarque',
'                    and traducao_localembarque.nome_entidade = ''''ng_localembarquedesembarque''''',
'                    and traducao_localembarque.nome_coluna = ''''nome_local''''',
'                    and traducao_localembarque.id_idioma = apex_util.get_session_state(''''idioma_logado'''')                                                    ',
'',
'            left join vw_traducoes_geral traducao_localdesembarque',
'                    on traducao_localdesembarque.id_chave_entidade = a.id_local_desembarque',
'                    and traducao_localdesembarque.nome_entidade = ''''ng_localembarquedesembarque''''',
'                    and traducao_localdesembarque.nome_coluna = ''''nome_local''''',
'                    and traducao_localdesembarque.id_idioma = apex_util.get_session_state(''''idioma_logado'''')   ',
'            where b.ind_status_pedido_importacao = 3                                           ',
'',
'        '';',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,       ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,      ',
'                pkg_componentes.html_botao_opcao(a.id,''TD677'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_entrega'')) a',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    FUNCTION SQL_FILTRO(CAMPO IN VARCHAR2)',
'    RETURN CLOB IS',
'    BEGIN',
'        IF CAMPO = ''1'' THEN',
'              return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then            ',
'            return q''~select d,r',
'                      from vw_dominio_lista',
'                     where upper(nome_entidade) = upper(''imp_entrega'')',
'                       and upper(nome_coluna)   = upper(''ind_status_entrega'')~'';',
'        elsif campo = (''3'') then        ',
'            return q''~select b.nome_fantasia d, a.id r from ng_pessoa a join ng_pessoa_juridica b on b.id_pessoa = a.id ~'';',
'        elsif campo = ''4'' then            ',
'            return q''~select pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',descricao_viatransporte) d, a.id r from ng_viatransporte a ~'';  ',
'        ELSE',
'            RETURN NULL;',
'        END IF;        ',
'    END SQL_FILTRO;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;   ',
'',
'    FUNCTION LABEL_COLUNA(CAMPO IN VARCHAR)',
'    RETURN CLOB IS',
'        L_CAMPO CLOB;',
'    BEGIN',
'        IF CAMPO in (''1'',''F2'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.ind_status_entrega'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''2'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_processoimportacao'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''3'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''imp_pedidoimportacao.numero_pedido_importacao'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''4'' THEN                        ',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.num_entrega'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO in (''5'',''F4'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_viatransporte'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''6'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_exportador'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO in (''7'',''F3'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_importador'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''8'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_local_embarque'') INTO L_CAMPO FROM DUAL;  ',
'        ELSIF CAMPO = ''9'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.data_embarque_real'') INTO L_CAMPO FROM DUAL; ',
'        ELSIF CAMPO = ''10'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_invoice'') INTO L_CAMPO FROM DUAL;  ',
'        ELSIF CAMPO = ''F1'' then                     ',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.ID_TENANT'') INTO L_CAMPO FROM DUAL;  ',
'        END IF;',
'        RETURN L_CAMPO;',
'    END LABEL_COLUNA;',
'',
'',
'function ordenacao',
'return varchar2 is',
'begin',
'    return q''~',
'        select  pkg_ui.retorna_label_coluna(''imp_entrega.data_alteracao'')||pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'') d, ''ORDER1D&ORDER2'' r from dual union all',
'        select  ',
'            pkg_ui.retorna_label_coluna(''imp_entrega.data_alteracao'') d, ',
'            ''ORDER1D'' r ',
'        from dual',
'        union all',
'        select ',
'            pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'')  d,',
'            ''ORDER2'' r ',
'        from dual',
'',
'    ~'';',
'end;',
'',
'    function default_ordenacao',
'    return varchar2 is',
'    begin',
'        return ''ORDER1D&ORDER2'';',
'    end;',
'',
'',
'END "UI_MPD_TD677";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td692
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155810039555323419)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD692'
,p_sequence=>970
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'create or replace package "UI_MPD_TD692" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'--     function where_dinamico (p_campo in varchar2) return clob;',
'',
'    function valida(p_id in number) return pkg_mensagem.message_record_table;',
'        ',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'',
'    ',
'',
'end "UI_MPD_TD692";',
'/',
'',
'create or replace package body "UI_MPD_TD692" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.obtervaloresdascolunas (',
'            p_consulta_sql => ''select',
'            a.numero_pedido_importacao,',
'            d.num_entrega,',
'            case',
'                when d.id_processoimportacao is null then',
'                    pkg_componentes.html_cor_texto(''''''||',
'                    retorna_texto(''msg.93.l'')||'''''')',
'                else e.num_processoimportacao',
'            end as id_processoimportacao',
'',
'            from imp_pedidoimportacao      a',
'            join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id',
'            join imp_entrega_item          c on c.id_pedidoimportacao_item = b.id',
'            join imp_entrega                d on d.id = c.id_entrega',
'            left join imp_processoimportacao    e on e.id = d.id_processoimportacao',
'            where c.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_consulta_item clob;',
'        l_json_calcular_valor_total clob;',
'        l_campos_calcular_valor_quantidade varchar2(128) := ''valor_total_condicao_venda'';',
'        v_executa_js_digito clob;',
'    begin',
'        l_consulta_item := ''select a.codigo_item || '''' - ''''||pkg_traducao.get_traducao(a.descricao_item) as d,  a.id as r from ng_item a join ng_item_produto b on b.id_item = a.id where a.ind_tipo_item = ''''p'''' order by 1'';',
'',
'',
'        l_json_calcular_valor_total := gerar_json_lista(',
'            sys.odcivarchar2list(''quantidade * (valor_unitario - valor_desconto_unitario)'', ''quantidade * peso_unitario''),',
'            sys.odcivarchar2list(l_campos_calcular_valor_quantidade, ''peso_liquido_total'')',
'        );',
'',
'        v_executa_js_digito := ''atualizardigitscampo("quantidade","qtd_decimais","valor_inicial","valor_final");'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, '''' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from imp_entrega_item where id '
||'= p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'',
'               select p_codigo_artefato, ''ind_tratamento_saldo'',           48, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_entrega'',                     31, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''num_sequencia_item'',             2, ''TXT'', null, ''S'', ''N'', to_char((SELECT num_sequencia_item FROM imp_pedidoimportacao_item A JOIN IMP_ENTREGA_ITEM b on a.id = b.ID_PEDIDOIMPORTACAO_ITEM where b.id = p_param'
||'1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,''imp_pedidoimportacao_item.num_sequencia_item'' tag_campo from dual union all',
'               select p_codigo_artefato, ''id_pedidoimportacao_item'',       3, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_item'',                        4, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_ncm'',                         6, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_unidademedida'',               8, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''quantidade'',                    10, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_json_calcular_valor_total calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''peso_unitario'',                 12, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_json_calcular_valor_total calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''peso_liquido_total'',            14, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''moeda'',                         16, ''TXT'', null, ''S'', ''N'', to_char((select codigo_moeda||'' - ''||simbolo_iso from imp_pedidoimportacao a join ng_moeda b on b.id = a.id_moeda join imp_entrega c on c.id_pedidoim'
||'portacao = a.id join imp_entrega_item d on d.id_entrega = c.id where d.id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_unitario'',                18, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_desconto_unitario'',       20, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_json_calcular_valor_total calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_total_condicao_venda'',    22, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_naturezaoperacao'',           24, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_fabricante'',                 26, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''qtd_decimais'',                  28, ''HID'', null, ''N'', ''N'', to_char((select case a.ind_tipo_dado  when ''d'' then ''5'' else ''0'' end  from ng_unidademedida a join imp_entrega_item b on b.id_unidademedida = a.id wh'
||'ere b.id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_inicial'',                 30, ''HID'', null, ''N'', ''N'', to_char(0) valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_final'',                   32, ''HID'', null, ''N'', ''N'', to_char((select (a.quantidade + c.quantidade_programar_entrega)  from imp_entrega_item a join imp_entrega b on b.id = a.id_entrega join imp_pedidoimp'
||'ortacao_item c on a.id_pedidoimportacao_item = c.id where a.id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id'',                            33, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''IND_LICENCA_IMPORTACAO'',        34, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''data_alteracao'',                36, ''HID'', null, ''N'', ''N'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''quantidade_faturada'',           37, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''quantidade_saldo'',              38, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''peso_bruto_unitario'',           39, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''peso_bruto_total'',              40, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''id_pais_origem'',                41, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_total_desconto_invoice_item'', 43, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_despesaproforma'',          44, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_despesaproforma_unitario'', 45, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''ind_bloqueio_embarque_ate_deferimento_li'',      47, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual union all',
'               select p_codigo_artefato, ''valor_desconto_pedido_item_unitario'', 46, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual UNION ALL',
'               select p_codigo_artefato, ''valor_total_despesa_invoice_item'', 49, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js,null tag_campo from dual',
'               ) new_data',
unistr('        on (tf.codigo_artefato = new_data.codigo_artefato and tf.nome_coluna = new_data.nome_coluna)  -- condi\00E7\00E3o de correspond\00EAncia'),
'        when not matched then',
'            insert (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, calcular_valor, executa_js, tag_campo)',
'            values (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.calcular_valor, new_data.executa_js, new_data.tag_campo);',
'    end formulario;',
