'',
'    function where_dinamico(p_campo in varchar2)',
'        return clob',
'        is',
'            v_ids_itens   clob;',
'        begin',
'            select nvl(listagg(a.id_item, '','') within group (order by a.id_item), ''0'')',
'              into v_ids_itens',
'              from imp_pedidoimportacao_item a',
'              join imp_entrega b',
'                on b.id_pedidoimportacao = a.id_pedidoimportacao',
'             where b.id = apex_util.get_session_state(''P9010_PARAMETRO'')',
'               and a.quantidade_programar_entrega > 0;',
'',
'            if upper(p_campo) = ''id_item'' then',
'                return q''~',
'                    where (a.data_fim_vigencia is null',
'                       or trunc(a.data_fim_vigencia) >= trunc(current_date))',
'                       and a.ind_tipo_item = ''p''',
'                       and a.id in (~'' || v_ids_itens || q''~)',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'    end;',
'',
'    function valida(p_id in number)',
'        return pkg_mensagem.message_record_table ',
'    is',
'        l_id_entrega number;',
'        l_id_entidade number;',
'        l_verifica_titulopagamento number;',
'',
'        l_old_valor_total_condicao_venda number;        ',
'        l_new_quantidade number;',
'        l_new_valor_unitario number;',
'        l_new_valor_desconto_unitario number;',
'        l_new_valor_total_condicao_venda number;',
'',
'        v_parametro pkg_mensagem.paramentros;',
'        v_message   pkg_mensagem.message_record;',
'        v_messages  pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select id_entrega, valor_total_condicao_venda into l_id_entrega, l_old_valor_total_condicao_venda from imp_entrega_item where id = p_id;',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';        ',
'',
unistr('        -- Verifica se existem t\00EDtulos de pagamento para esta entrega:'),
'        select count(1) into l_verifica_titulopagamento',
'        from fin_titulopagamento a',
'        join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'        where a.id_entidade = l_id_entidade',
'        and a.ind_status_pagamento in (1,2)',
'        and b.id_entrega = l_id_entrega;',
'        ',
unistr('        -- Valida\00E7\00E3o:'),
'        if l_verifica_titulopagamento > 0 then',
'            -- Verifica se alterou valor_total_condicao_venda:',
'            l_new_quantidade := to_number(pkg_ui.retorna_valor_colecao(''TD692'',''quantidade''));',
'            l_new_valor_desconto_unitario := to_number(pkg_ui.retorna_valor_colecao(''TD692'',''valor_desconto_unitario''));',
'            l_new_valor_unitario := to_number(pkg_ui.retorna_valor_colecao(''TD692'',''valor_unitario''));',
'            l_new_valor_total_condicao_venda := (l_new_quantidade * (l_new_valor_unitario - l_new_valor_desconto_unitario));',
'',
'            if l_old_valor_total_condicao_venda <> l_new_valor_total_condicao_venda then',
'                v_parametro(0) := ''UI_MPD_TD_692.valida'';',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem  => ''129'',',
'                    p_nome_campo       => ''valor_total_condicao_venda'',',
'                    p_parametro        => v_parametro,',
'                    p_pagina           => 9010,',
'                    p_objeto_mensagem  => v_message',
'                );',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;',
'            end if;',
'        end if;',
'        return v_messages;',
'    end valida;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id number;',
'        v_new imp_entrega_item%rowtype;',
'',
'        l_id_entrega number;',
'        l_id_entidade number;',
'        l_verifica_titulopagamento number;',
'        l_old_valor_total_condicao_venda number;',
'        l_new_valor_total_condicao_venda number;',
'    begin',
'        -- select * into v_new from imp_entrega_item where id = p_id;',
'        ',
'        select id_entrega, valor_total_condicao_venda into l_id_entrega, l_old_valor_total_condicao_venda from imp_entrega_item where id = p_id;',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';        ',
'',
unistr('        -- Verifica se existem t\00EDtulos de pagamento para esta entrega:'),
'        select count(1) into l_verifica_titulopagamento',
'        from fin_titulopagamento a',
'        join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'        where a.id_entidade = l_id_entidade',
'        and a.ind_status_pagamento in (1,2)',
'        and b.id_entrega = l_id_entrega;',
'',
'        -- Recupera novo valor_total_condicao_venda:',
'        l_new_valor_total_condicao_venda := pkg_util.retorna_number(apex_application.g_f22(1));',
'        ',
'        if l_verifica_titulopagamento > 0 and l_old_valor_total_condicao_venda <> l_new_valor_total_condicao_venda then',
'            bo_imp_entrega_item.altera_registro_pagamentos_titulos(',
'                p_ind_tratamento_saldo           => apex_application.g_f48(1),',
'                p_id_tenant                      => apex_application.g_f01(1),',
'                p_id_entrega                     => apex_application.g_f31(1),',
'                p_id_pedidoimportacao_item       => apex_application.g_f03(1),',
'                p_id_item                        => apex_application.g_f04(1),',
'                p_id_ncm                         => apex_application.g_f06(1),',
'                p_id_unidademedida               => apex_application.g_f08(1),',
'                p_quantidade                     => pkg_util.retorna_number(apex_application.g_f10(1)),',
'                p_peso_unitario                  => pkg_util.retorna_number(apex_application.g_f12(1)),',
'                p_peso_liquido_total             => pkg_util.retorna_number(apex_application.g_f14(1)),',
'                p_valor_unitario                 => pkg_util.retorna_number(apex_application.g_f18(1)),',
'                p_valor_desconto_unitario        => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_valor_total_condicao_venda     => pkg_util.retorna_number(apex_application.g_f22(1)),',
'                p_id_naturezaoperacao            => apex_application.g_f24(1),',
'                p_id_fabricante                  => apex_application.g_f26(1),',
'                p_ind_licenca_importacao         => apex_application.g_f34(1),',
'                p_data_alteracao                 => to_timestamp(apex_application.g_f36(1), ''dd-mon-rr hh:mi:ss:ff am''),',
'                p_quantidade_faturada            => pkg_util.retorna_number(apex_application.g_f37(1)),',
'                p_quantidade_saldo               => pkg_util.retorna_number(apex_application.g_f38(1)),',
'                p_peso_bruto_unitario            => pkg_util.retorna_number(apex_application.g_f39(1)),',
'                p_peso_bruto_total               => pkg_util.retorna_number(apex_application.g_f40(1)),',
'                p_id_pais_origem                 => pkg_util.retorna_number(nvl(apex_application.g_f41(1), bo_ng_pessoa.retorna_id_pais_origem(apex_application.g_f41(1)))),',
'                p_valor_total_desconto_invoice_item => pkg_util.retorna_number(apex_application.g_f43(1)),',
'                p_valor_despesaproforma          => pkg_util.retorna_number(apex_application.g_f44(1)),',
'                p_valor_despesaproforma_unitario => pkg_util.retorna_number(apex_application.g_f45(1)),',
'                p_valor_desconto_pedido_item_unitario => pkg_util.retorna_number(apex_application.g_f46(1)),',
'                p_ind_bloqueio_embarque_ate_deferimento_li  => ''N'',',
'                p_id                             => p_id,',
'                p_sucesso                        => p_sucesso,',
'                p_messages                       => p_messages',
'            );',
'        else',
'            bo_imp_entrega_item.altera_registro(',
'                p_ind_tratamento_saldo           => apex_application.g_f48(1),',
'                p_id_tenant                      => apex_application.g_f01(1),',
'                p_id_entrega                     => apex_application.g_f31(1),',
'                p_id_pedidoimportacao_item       => apex_application.g_f03(1),',
'                p_id_item                        => apex_application.g_f04(1),',
'                p_id_ncm                         => apex_application.g_f06(1),',
'                p_id_unidademedida               => apex_application.g_f08(1),',
'                p_quantidade                     => pkg_util.retorna_number(apex_application.g_f10(1)),',
'                p_peso_unitario                  => pkg_util.retorna_number(apex_application.g_f12(1)),',
'                p_peso_liquido_total             => pkg_util.retorna_number(apex_application.g_f14(1)),',
'                p_valor_unitario                 => pkg_util.retorna_number(apex_application.g_f18(1)),',
'                p_valor_desconto_unitario        => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_valor_total_condicao_venda     => pkg_util.retorna_number(apex_application.g_f22(1)),',
'                p_id_naturezaoperacao            => apex_application.g_f24(1),',
'                p_id_fabricante                  => apex_application.g_f26(1),',
'                p_ind_licenca_importacao         => apex_application.g_f34(1),',
'                p_data_alteracao                 => to_timestamp(apex_application.g_f36(1), ''dd-mon-rr hh:mi:ss:ff am''),',
'                p_quantidade_faturada            => pkg_util.retorna_number(apex_application.g_f37(1)),',
'                p_quantidade_saldo               => pkg_util.retorna_number(apex_application.g_f38(1)),',
'                p_peso_bruto_unitario            => pkg_util.retorna_number(apex_application.g_f39(1)),',
'                p_peso_bruto_total               => pkg_util.retorna_number(apex_application.g_f40(1)),',
'                p_id_pais_origem                 => pkg_util.retorna_number(nvl(apex_application.g_f41(1), bo_ng_pessoa.retorna_id_pais_origem(apex_application.g_f41(1)))),',
'                p_valor_total_desconto_invoice_item => pkg_util.retorna_number(apex_application.g_f43(1)),',
'                p_valor_despesaproforma          => pkg_util.retorna_number(apex_application.g_f44(1)),',
'                p_valor_despesaproforma_unitario => pkg_util.retorna_number(apex_application.g_f45(1)),',
'                p_valor_desconto_pedido_item_unitario => pkg_util.retorna_number(apex_application.g_f46(1)),',
'                p_ind_bloqueio_embarque_ate_deferimento_li  => apex_application.g_f47(1),',
'                p_valor_total_despesa_invoice_item => apex_application.g_f49(1),',
'                p_id                             => p_id,',
'                p_sucesso                        => p_sucesso,',
'                p_messages                       => p_messages',
'            );',
'        end if;',
'    end post;',
'',
'end "UI_MPD_TD692";',
'/'))
);
end;
