prompt --application/deployment/install/install_ui_mpd_td848
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155810741877310606)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD848'
,p_sequence=>980
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD848',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste de coluna id_recinto_alfandegado',
'-- Jira: PEDITEM-161',
'',
'create or replace package "UI_MPD_TD848" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'end "UI_MPD_TD848";',
'/',
'create or replace package body "UI_MPD_TD848" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select                ',
'                a.num_processoimportacao,',
'                d.nome_fantasia,',
'                pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''', ''''ind_status'''', a.ind_status) ind_status',
'            from imp_processoimportacao a',
'            join ng_pessoa_juridica d on d.id_pessoa = a.id_embarcador',
'            where a.id =  ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''ng_pessoa_juridica'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
unistr('        -- -- valida\00E7\00E3o data_disponivel'),
'        v_data_disponivel_real              imp_processoimportacao.data_disponivel_real%type;',
'        v_data_disponivel_informada         imp_processoimportacao.data_disponivel_informada%type;',
'        v_data_disponivel_calculada         imp_processoimportacao.data_disponivel_calculada%type;',
'        v_hid_disponivel_real               varchar2(10);',
'        v_hid_disponivel_informada          varchar2(10);',
'        v_hid_disponivel_calculada          varchar2(10);',
'',
'        v_data_embarque_real                imp_processoimportacao.data_embarque_real%type;',
'        v_data_embarque_informada           imp_processoimportacao.data_embarque_informada%type;',
'        v_data_embarque_calculada           imp_processoimportacao.data_embarque_calculada%type;',
'        v_hid_embarque_real                 varchar2(10);',
'        v_hid_embarque_informada            varchar2(10);',
'        v_hid_embarque_calculada            varchar2(10);',
'',
'        v_data_desembarque_real             imp_processoimportacao.data_desembarque_real%type;',
'        v_data_desembarque_informada        imp_processoimportacao.data_desembarque_informada%type;',
'        v_data_desembarque_calculada        imp_processoimportacao.data_desembarque_calculada%type;',
'        v_hid_desembarque_real              varchar2(10);',
'        v_hid_desembarque_informada         varchar2(10);',
'        v_hid_desembarque_calculada         varchar2(10);',
'        ',
'        v_data_registro_di_real             imp_processoimportacao.data_registro_di_real%type;',
'        v_data_registro_di_informada        imp_processoimportacao.data_registro_di_informada%type;',
'        v_data_registro_di_calculada        imp_processoimportacao.data_registro_di_calculada%type;',
'        v_hid_registro_di_real              varchar2(10);',
'        v_hid_registro_di_informada         varchar2(10);',
'        v_hid_registro_di_calculada         varchar2(10);',
'',
'        v_data_nacionalizacao_real          imp_processoimportacao.data_nacionalizacao_real%type;',
'        v_data_nacionalizacao_informada     imp_processoimportacao.data_nacionalizacao_informada%type;',
'        v_data_nacionalizacao_calculada     imp_processoimportacao.data_nacionalizacao_calculada%type;',
'        v_hid_nacionalizacao_real           varchar2(10);',
'        v_hid_nacionalizacao_informada      varchar2(10);',
'        v_hid_nacionalizacao_calculada      varchar2(10);',
'',
'        v_data_recebimento_real             imp_processoimportacao.data_recebimento_real%type;',
'        v_data_recebimento_informada        imp_processoimportacao.data_recebimento_informada%type;',
'        v_data_recebimento_calculada        imp_processoimportacao.data_recebimento_calculada%type;',
'        v_hid_recebimento_real              varchar2(10);',
'        v_hid_recebimento_informada         varchar2(10);',
'        v_hid_recebimento_calculada         varchar2(10);',
'        ',
'',
'        procedure set_hid(',
'                p_data_real      in date,',
'                p_data_informada in date,',
'                p_data_calculada in date,',
'                p_hid_real       out varchar2,',
'                p_hid_informada  out varchar2,',
'                p_hid_calculada  out varchar2',
'        ) is',
'        begin',
'                p_hid_real      := ''HID'';',
'                p_hid_informada := ''HID'';',
'                p_hid_calculada := ''HID'';',
'                if p_data_real is not null then',
'                    p_hid_real := '''';',
'                elsif p_data_informada is not null OR p_data_calculada is null then',
'                    p_hid_informada := '''';',
'                else',
'                    p_hid_calculada := '''';',
'                end if;',
'        end;',
'',
'',
'    begin ',
'',
'        SELECT ',
'            data_disponivel_real, data_disponivel_informada, data_disponivel_calculada,',
'            data_embarque_real, data_embarque_informada, data_embarque_calculada,',
'            data_desembarque_real, data_desembarque_informada, data_desembarque_calculada,',
'            data_registro_di_real, data_registro_di_informada, data_registro_di_calculada,',
'            data_nacionalizacao_real, data_nacionalizacao_informada, data_nacionalizacao_calculada,',
'            data_recebimento_real, data_recebimento_informada, data_recebimento_calculada',
'        INTO ',
'            v_data_disponivel_real, v_data_disponivel_informada, v_data_disponivel_calculada,',
'            v_data_embarque_real, v_data_embarque_informada, v_data_embarque_calculada,',
'            v_data_desembarque_real, v_data_desembarque_informada, v_data_desembarque_calculada,',
'            v_data_registro_di_real, v_data_registro_di_informada, v_data_registro_di_calculada,',
'            v_data_nacionalizacao_real, v_data_nacionalizacao_informada, v_data_nacionalizacao_calculada,',
'            v_data_recebimento_real, v_data_recebimento_informada, v_data_recebimento_calculada',
'        FROM imp_processoimportacao',
'        WHERE id = p_param1;',
'',
'',
'        set_hid(',
'            v_data_disponivel_real, v_data_disponivel_informada,v_data_disponivel_calculada,',
'            v_hid_disponivel_real, v_hid_disponivel_informada,v_hid_disponivel_calculada',
'        );',
'',
'        set_hid(',
'            v_data_embarque_real, v_data_embarque_informada, v_data_embarque_calculada,',
'            v_hid_embarque_real, v_hid_embarque_informada, v_hid_embarque_calculada',
'        );',
'',
'        set_hid(',
'            v_data_desembarque_real, v_data_desembarque_informada, v_data_desembarque_calculada, ',
'            v_hid_desembarque_real, v_hid_desembarque_informada, v_hid_desembarque_calculada',
'        );',
'',
'        set_hid(',
'            v_data_registro_di_real, v_data_registro_di_informada, v_data_registro_di_calculada, ',
'            v_hid_registro_di_real, v_hid_registro_di_informada, v_hid_registro_di_calculada',
'        );',
'',
'        set_hid(',
'            v_data_nacionalizacao_real, v_data_nacionalizacao_informada, v_data_nacionalizacao_calculada, ',
'            v_hid_nacionalizacao_real, v_hid_nacionalizacao_informada,v_hid_nacionalizacao_calculada',
'        );',
'',
'        set_hid(',
'            v_data_recebimento_real, v_data_recebimento_informada, v_data_recebimento_calculada, ',
'            v_hid_recebimento_real, v_hid_recebimento_informada,v_hid_recebimento_calculada',
'        );',
'',
'',
'        MERGE INTO temp_formulario tf',
'          USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL'
||' ',
'                SELECT p_codigo_artefato, ''id_endereco_origem'',           20, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_local_embarque'',            22, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_local_desembarque'',         24, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_recinto_alfandegado'',       26, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_endereco_destino'',          28, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''referencia_despachante'',       30, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'',
'                SELECT p_codigo_artefato, ''data_disponivel_calculada'',    31, v_hid_disponivel_calculada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_disponivel_informada'',    32, v_hid_disponivel_informada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_disponivel_real'',         33, v_hid_disponivel_real,       null, ''S'', ''S'', null FROM dual UNION ALL',
'',
'                SELECT p_codigo_artefato, ''data_embarque_calculada'',      34, v_hid_embarque_calculada,    null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_embarque_informada'',      35, v_hid_embarque_informada,    null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_embarque_real'',           36, v_hid_embarque_real,         null, ''S'', ''S'', null FROM dual UNION ALL',
'',
'                SELECT p_codigo_artefato, ''data_desembarque_calculada'',   37, v_hid_desembarque_calculada, null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_desembarque_informada'',   38, v_hid_desembarque_informada, null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_desembarque_real'',        39, v_hid_desembarque_real,      null, ''S'', ''S'', null FROM dual UNION ALL',
'',
'                SELECT p_codigo_artefato, ''data_registro_di_calculada'',   40, v_hid_registro_di_calculada, null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_registro_di_informada'',   41, v_hid_registro_di_informada, null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_registro_di_real'',        42, v_hid_registro_di_real,      null, ''S'', ''S'', null FROM dual UNION ALL',
'                ',
'                SELECT p_codigo_artefato, ''data_nacionalizacao_calculada'',43, v_hid_nacionalizacao_calculada,null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_nacionalizacao_informada'',44, v_hid_nacionalizacao_informada,null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_nacionalizacao_real'',     45, v_hid_nacionalizacao_real,    null, ''S'', ''S'', null FROM dual UNION ALL',
'                ',
'                SELECT p_codigo_artefato, ''data_recebimento_calculada'',   46, v_hid_recebimento_calculada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_recebimento_informada'',   47, v_hid_recebimento_informada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_recebimento_real'',        48, v_hid_recebimento_real,       null, ''S'', ''S'', null FROM dual UNION ALL',
'',
'                SELECT p_codigo_artefato, ''data_alteracao'',               49, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_endereco_origem'') then',
'            return q''~',
'                where (b.data_fim_vigencia is null ',
'                    or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'            ~'';',
'        end if;',
'    end;',
'',
'   procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_id number;',
'        v_data_disponivel_informada        VARCHAR2(32767);',
'',
'        v_data_embarque_informada          VARCHAR2(32767);',
'',
'        v_data_desembarque_informada       VARCHAR2(32767);',
'',
'        v_data_registro_di_informada      VARCHAR2(32767);',
'',
'        v_data_nacionalizacao_informada    VARCHAR2(32767);',
'',
'        v_data_recebimento_informada       VARCHAR2(32767);',
'        v_old                              imp_processoimportacao%rowtype;',
'    begin',
'',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'',
'',
'        if  trunc(v_old.data_disponivel_calculada) = trunc(to_date(apex_application.g_f31(1), ''DD/MM/YYYY'')) OR v_old.data_disponivel_calculada is null then     ',
'            v_data_disponivel_informada := apex_application.g_f32(1);',
'        else',
'            v_data_disponivel_informada := apex_application.g_f31(1); ',
'        end if;',
'',
'        if v_old.data_embarque_calculada is null OR trunc(v_old.data_embarque_calculada) = trunc(to_date(apex_application.g_f34(1), ''DD/MM/YYYY''))then     ',
'            v_data_embarque_informada := apex_application.g_f35(1);',
'        else',
'            v_data_embarque_informada := apex_application.g_f34(1);',
'        end if;',
'',
'        if v_old.data_desembarque_calculada is null OR trunc(v_old.data_desembarque_calculada) = trunc(to_date(apex_application.g_f37(1), ''DD/MM/YYYY''))then     ',
'            v_data_desembarque_informada := apex_application.g_f38(1);',
'        else',
'            v_data_desembarque_informada := apex_application.g_f37(1);',
'        end if;',
'',
'        if v_old.data_registro_di_calculada is null OR trunc(v_old.data_registro_di_calculada) = trunc(to_date(apex_application.g_f40(1), ''DD/MM/YYYY''))then     ',
'            v_data_registro_di_informada := apex_application.g_f41(1);',
'        else',
'            v_data_registro_di_informada := apex_application.g_f40(1);',
'        end if;',
'',
'        if v_old.data_nacionalizacao_calculada is null OR trunc(v_old.data_nacionalizacao_calculada) = trunc(to_date(apex_application.g_f43(1), ''DD/MM/YYYY''))then     ',
'            v_data_nacionalizacao_informada := apex_application.g_f44(1);',
'        else',
'            v_data_nacionalizacao_informada := apex_application.g_f43(1);',
'        end if;',
'',
'        if v_old.data_recebimento_calculada is null OR trunc(v_old.data_recebimento_calculada) = trunc(to_date(apex_application.g_f46(1), ''DD/MM/YYYY''))then     ',
'            v_data_recebimento_informada := apex_application.g_f47(1);',
'        else',
'            v_data_recebimento_informada := apex_application.g_f46(1);',
'        end if;',
'',
'',
'        bo_imp_processoimportacao.altera_registro_especifico(',
'                p_id_endereco_origem            => apex_application.g_f20(1),',
'                p_id_local_embarque             => apex_application.g_f22(1),',
'                p_id_local_desembarque          => apex_application.g_f24(1),',
'                p_id_recinto_alfandegado        => apex_application.g_f26(1),',
'                p_id_endereco_destino           => apex_application.g_f28(1),',
'                p_data_disponivel_informada     => v_data_disponivel_informada,',
'                p_data_embarque_informada       => v_data_embarque_informada,',
'                p_data_desembarque_informada    => v_data_desembarque_informada,',
'                p_data_registro_di_informada    => v_data_registro_di_informada,',
'                p_data_nacionalizacao_informada => v_data_nacionalizacao_informada,',
'                p_data_recebimento_informada    => v_data_recebimento_informada,',
'                p_id                            => p_id, ',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'        );',
'    end;',
'end "UI_MPD_TD848";',
'/'))
);
end;
/
