'    --<CUSTOMIZADO_INICIO>',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        configura_datas_calculadas;',
'    end;',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        altera_mpd_configuracao_ng_num_processoimportacao(',
'            p_id            => v_new.id,',
'            p_encadeado     => p_encadeado,',
'            p_sucesso       => p_sucesso,',
'            p_messages      => p_messages',
'        );',
'        --',
'        -- Verifica valor em v_operacao:',
'        if v_operacao = ''INCLUI_REGISTRO_AO_FIRMAR_PEDIDO'' then',
'            -- Vincula itens da entrega e entrega que gerou o processo:  ',
'            bo_imp_entrega.vincula_entregas_ao_processo(',
'                p_ids_entregas_selecionadas => v_id_entrega,',
'                p_id_processoimportacao     => v_new.id,',
'                p_pagina                    => v_pagina,',
'                p_encadeado                 => p_encadeado,',
'                p_sucesso                   => p_sucesso,',
'                p_messages                  => p_messages',
'            );',
'            --',
'            -- Chamada para incluir tributos dos itens:',
'            gerencia_tributos(',
'                p_id        => v_new.id,',
'                p_pagina    => v_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso   => p_sucesso,',
'                p_messages  => p_messages',
'            );',
'            --',
'        end if;',
'        --',
'    end;',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table)',
'    is',
'        l_id_anexo number;',
'        l_id number;',
'    begin',
'        if v_operacao = ''ATUALIZA_VALORES_PROCESSO'' or v_operacao = ''CANCELAR_PROCESSO'' then',
'            return;',
'        end if;',
'',
'',
unistr('        -- Valida se embarque real,conhecimento transporte n\00E3o null e tamb\00E9m ng_anexo.id_documento obrigat\00F3rio quando campo "ng_anexo.anexo diferente de null'),
'        if v_operacao = ''altera_registro_anexo'' then',
'            hook_valida_data_embarque_real_e_conhecimento_transporte(v_new.data_embarque_real);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_desembarque'' then',
'            hook_valida_data_desembarque_real_obrigatorio(v_new.data_desembarque_real);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_recebimento_real'' then',
'            hook_valida_data_recebimento_real_obrigatorio(v_new.data_recebimento_real);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_embarque_real'' then',
'            hook_valida_data_embarque_real_obrigatorio(v_new.data_embarque_real);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_disponivel_real'' then',
'            hook_valida_data_disponivel_real_obrigatorio(v_new.data_disponivel_real);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_nacionalizacao_real'' then',
'            hook_valida_data_nacionalizacao_real_obrigatorio(v_new.data_nacionalizacao_real);',
'        end if;',
'',
'        if (v_messages.count = 0) AND (v_new_anexo.id_documento is not null) THEN',
'            bo_ng_anexo.inclui_registro (',
'                    p_id_usuario_revisou    => null,',
