'                    p_id_entidade           => v_new_anexo.id_entidade,',
'                    p_id_re'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(155851324865645312)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ferencia         => v_new_anexo.id_referencia,',
'                    p_numero_documento      => v_new.conhecimento_transporte,',
'                    p_versao_documento      => v_new_anexo.versao_documento,',
