'                    p_messages              => p_messages',
'        );',
'        end if;',
'',
'		    if v_operacao = ''confirma_data_registro_di_real'' AND (v_messages.count = 0) then',
'								incluir_registro_anexo(p_encadeado,p_sucesso,p_messages);',
'        end if;',
'',
unistr('        -- Altera\00E7\00E3o de ind_status de acordo com campos data:'),
'        if v_new.data_finalizado is not null then',
'            v_new.ind_status := 8;',
'        elsif v_new.data_recebimento_real is not null and v_new.data_finalizado is null then',
'            v_new.ind_status := 7;',
'        elsif v_new.data_nacionalizacao_real is not null and v_new.data_recebimento_real is null then',
'            v_new.ind_status := 6;',
'        elsif v_new.data_registro_di_real is not null and v_new.data_nacionalizacao_real is null then',
'            v_new.ind_status := 5;',
'        elsif v_new.data_desembarque_real is not null and v_new.data_registro_di_real is null then',
'            v_new.ind_status := 4;',
'        elsif v_new.data_embarque_real is not null and v_new.data_desembarque_real is null and v_new.ind_status <> 10 then',
'            v_new.ind_status := 3;',
'        elsif v_new.data_disponivel_real is not null and v_new.data_embarque_real is null and v_new.ind_status <> 10 then',
'            v_new.ind_status := 2;',
'        elsif v_new.data_disponivel_real is null and v_new.data_embarque_real is null and v_new.ind_status <> 10 then',
'            v_new.ind_status := 1;',
'        end if;',
'',
'        configura_datas_calculadas;',
'    end;',
'    --',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'        l_id number;',
'		v_count_entrega number;',
'        l_mensagem clob;',
'        l_paramentros pkg_mensagem.paramentros;',
'    begin',
'        -- ?',
'        if v_operacao = ''ATUALIZA_VALORES_PROCESSO'' then',
'            return;',
'        end if;',
'        --',
'',
'        -- Desenvolvedor: Leonardo Ferreira',
'        -- Data         : 06/07/2026',
unistr('        -- Op\00E7\00E3o para recalcular os tributos do processo:'),
'        if v_operacao = ''RECALCULAR_TRIBUTOS'' then',
'            gerencia_tributos(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        --',
'',
'        select count(*) into v_count_entrega from imp_entrega where id_processoimportacao = v_new.id;',
'        if v_operacao = ''CANCELAR_PROCESSO'' and v_count_entrega > 0 then',
'	        altera_id_processo_entrega (v_new.id,true,p_sucesso,p_messages);',
'	    end if;',
'',
'        if v_operacao = ''confirma_data_disponivel_real'' then',
'            gera_titulos(5, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_embarque_real'' then',
'            gera_titulos(6, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''confirma_data_desembarque'' then',
'            gera_titulos(7, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''desconfirma_desembarque_real'' then',
'            cancela_titulos(7, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''desconfirma_registro_di_real'' then',
unistr('            -- Itens 1 e 4: exclui cota\00E7\00F5es e depois a DI'),
'            for r in (select id from imp_declaracaoimportacao',
'                       where id_processoimportacao = v_new.id) loop',
'',
'                for c in (select id from imp_declaracaoimportacao_cotacao',
'                           where id_declaracaoimportacao = r.id) loop',
'                    bo_imp_declaracaoimportacao_cotacao.exclui_registro(',
'                        p_id        => c.id,',
'                        p_encadeado => true,',
'                        p_sucesso   => p_sucesso,',
'                        p_messages  => p_messages',
'                    );',
'                    if p_messages.count > 0 then return; end if;',
'                end loop;',
'',
'                bo_imp_declaracaoimportacao.exclui_registro(',
'                    p_id        => r.id,',
'                    p_encadeado => true,',
'                    p_sucesso   => p_sucesso,',
'                    p_messages  => p_messages',
'                );',
'                if p_messages.count > 0 then return; end if;',
'            end loop;',
'',
'            -- Item 5: zera valores realizados das despesas de tributo (tipos 1-6, 18, 19)',
'            for d in (',
'                select pd.id, pd.data_alteracao',
'                  from imp_processoimportacao_despesa pd',
'                  join ng_despesa nd on nd.id = pd.id_despesa',
'                 where pd.id_processoimportacao = v_new.id',
'                   and nd.ind_tipo_despesa in (1,2,3,4,5,6,18,19)',
'            ) loop',
'                for id in (',
'                    select i.id, i.data_alteracao, i.id_tenant,',
'                           i.id_processoimportacao_item, i.id_processoimportacao_despesa,',
'                           i.id_moeda_despesa_prevista, i.valor_total_despesa_previsto_item,',
'                           i.valor_unitario_despesa_previsto_item, i.id_moeda_despesa_realizada,',
'                           id_despesa',
'                      from imp_processoimportacao_item_despesa i',
'                     where i.id_processoimportacao_despesa = d.id',
'                ) loop',
'                    bo_imp_processoimportacao_item_despesa.altera_registro(',
'                        p_id_tenant                             => id.id_tenant,',
'                        p_id_processoimportacao_item            => id.id_processoimportacao_item,',
'                        p_id_processoimportacao_despesa         => id.id_processoimportacao_despesa,',
'                        p_id_despesa                            => id.id_despesa,',
'                        p_id_moeda_despesa_prevista             => id.id_moeda_despesa_prevista,',
'                        p_valor_total_despesa_previsto_item     => id.valor_total_despesa_previsto_item,',
'                        p_valor_unitario_despesa_previsto_item  => id.valor_unitario_despesa_previsto_item,',
'                        p_id_moeda_despesa_realizada            => id.id_moeda_despesa_realizada,',
'                        p_valor_total_despesa_realizado_item    => 0,',
'                        p_valor_unitario_despesa_realizado_item => 0,',
'                        p_valor_total_despesa_moeda_nacional    => 0,',
'                        p_valor_unitario_despesa_moeda_nacional => 0,',
'                        p_id                                    => id.id,',
'                        p_data_alteracao                        => id.data_alteracao,',
'                        p_encadeado                             => true,',
'                        p_sucesso                               => p_sucesso,',
'                        p_messages                              => p_messages',
'                    );',
'                    if p_messages.count > 0 then return; end if;',
'                end loop;',
'',
'                declare',
'                    l_d imp_processoimportacao_despesa%rowtype;',
'                begin',
'                    select * into l_d from imp_processoimportacao_despesa where id = d.id;',
'                    bo_imp_processoimportacao_despesa.v_operacao := ''DESCONFIRMA_DI'';',
'                    bo_imp_processoimportacao_despesa.altera_registro(',
'                        p_id_tenant                 => l_d.id_tenant,',
'                        p_id_documento_despesa      => l_d.id_documento_despesa,',
'                        p_id_processoimportacao     => l_d.id_processoimportacao,',
'                        p_id_numerario_despesa      => l_d.id_numerario_despesa, --?',
'                        p_id_despesa                => l_d.id_despesa,',
'                        p_id_moeda_prevista         => l_d.id_moeda_prevista,',
'                        p_valor_previsto            => l_d.valor_previsto,',
'                        p_id_moeda_realizada        => l_d.id_moeda_realizada,',
'                        p_valor_realizado           => 0,',
'                        p_taxa_cambio               => l_d.taxa_cambio,',
'                        p_ind_status_despesa        => 1,',
'                        p_ind_status_pagamento      => l_d.ind_status_pagamento,',
'                        p_id_moeda_documento        => l_d.id_moeda_documento,',
'                        p_valor_moeda_documento     => l_d.valor_moeda_documento,',
'                        p_valor_moeda_nacional      => l_d.valor_moeda_nacional,',
'                        p_ind_forma_rateio          => l_d.ind_forma_rateio,',
'                        p_ind_compoe_custo_operacao => l_d.ind_compoe_custo_operacao,',
'                        p_ind_participa_nfe         => l_d.ind_participa_nfe,',
'                        p_ind_despesa_base_calculo  => l_d.ind_despesa_base_calculo,',
'                        p_ind_tipo_despesa          => l_d.ind_tipo_despesa,',
'                        p_id                        => d.id,',
'                        p_data_alteracao            => d.data_alteracao,',
'                        p_encadeado                 => true,',
'                        p_sucesso                   => p_sucesso,',
'                        p_messages                  => p_messages',
'                    );',
'                    if p_messages.count > 0 then return; end if;',
'                end;',
'            end loop;',
'        end if;',
'',
'        if v_operacao = ''desconfirma_embarque_real'' then',
'            cancela_titulos(6, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        if v_operacao = ''desconfirma_disponivel_real'' then',
'            cancela_titulos(5, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        ----Bloco para carregar a mensagem do cadastro;',
'        --l_paramentros(0) := ''Parametro 1'';',
'        --l_paramentros(1) := ''Campo1'';',
'        --l_paramentros(2) := ''Campo2'';',
'        --pkg_mensagem.mensagem_original(77,l_paramentros,l_mensagem);',
unistr('        ----Contenar com [NAO_AUTO_FECHAR] para ativar o recurso pontual para n\00E3o fechar a mensagem automaticamente.'),
'        --p_sucesso := l_mensagem;',
'',
'    end;',
