unistr('    --Usada no TD850 Vincular processo de importa\00E7\00E3o a uma entrega-entrada pela entrega'),
'    procedure altera_datas_processoimporatacao(',
'        p_id_entrega in imp_entrega.id%type,',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao.altera_datas_processoimporatacao'';',
'        v_pagina := p_pagina;',
'        --',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */',
'        select * into v_entrega from imp_entrega where id = p_id_entrega;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_new.data_disponivel_informada    := coalesce(v_old.data_disponivel_informada, v_entrega.data_disponivel_informada);',
'        v_new.data_disponivel_real         := coalesce(v_old.data_disponivel_real, v_entrega.data_disponivel_real);',
'',
'        v_new.data_embarque_informada      := coalesce(v_old.data_embarque_informada, v_entrega.data_embarque_informada);',
'        v_new.data_embarque_real           := coalesce(v_old.data_embarque_real, v_entrega.data_embarque_real);',
'',
'        v_new.data_desembarque_informada   := coalesce(v_old.data_desembarque_informada, v_entrega.data_desembarque_informada);',
'',
'        v_new.data_nacionalizacao_informada := coalesce(v_old.data_nacionalizacao_informada, v_entrega.data_nacionalizacao_informada);',
'',
'        v_new.data_recebimento_informada   := coalesce(v_old.data_recebimento_informada, v_entrega.data_recebimento_informada);',
'',
'        v_new.id := p_id;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_datas_processoimporatacao;',
'',
unistr('    -- altera\00E7\00E3o de datas do processo de importacao com base nas datas da entrega (usada em TD840 Inclusao do processo de importacao - etapa Entrega)'),
'    procedure atualizar_datas_processo_com_base_entrega(',
'        p_id in imp_processoimportacao.id%type,',
'        p_id_entrega in imp_entrega.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao.atualizar_datas_processo_com_base_entrega'';',
'        v_pagina := p_pagina;',
'',
'        -- busca processo atual',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        -- busca dados da entrega',
'        select * into v_entrega from imp_entrega where id = p_id_entrega;',
'',
'        -- atualiza datas',
'        v_new.data_disponivel_calculada    := coalesce(v_old.data_disponivel_calculada,    v_entrega.data_disponivel_calculada);',
'        v_new.data_disponivel_informada    := coalesce(v_old.data_disponivel_informada,    v_entrega.data_disponivel_informada);',
'        v_new.data_disponivel_real         := coalesce(v_old.data_disponivel_real,         v_entrega.data_disponivel_real);',
'        v_new.data_embarque_calculada      := coalesce(v_old.data_embarque_calculada,      v_entrega.data_embarque_calculada);',
'        v_new.data_embarque_informada      := coalesce(v_old.data_embarque_informada,      v_entrega.data_embarque_informada);',
'        v_new.data_embarque_real           := coalesce(v_old.data_embarque_real,           v_entrega.data_embarque_real);',
'        v_new.data_desembarque_calculada   := coalesce(v_old.data_desembarque_calculada,   v_entrega.data_desembarque_calculada);',
'        v_new.data_desembarque_informada   := coalesce(v_old.data_desembarque_informada,   v_entrega.data_desembarque_informada);',
'        v_new.data_desembarque_real        := coalesce(v_old.data_desembarque_real,        v_entrega.data_desembarque_real);',
'        v_new.data_nacionalizacao_calculada:= coalesce(v_old.data_nacionalizacao_calculada, v_entrega.data_nacionalizacao_calculada);',
'        v_new.data_nacionalizacao_informada:= coalesce(v_old.data_nacionalizacao_informada, v_entrega.data_nacionalizacao_informada);',
'        v_new.data_nacionalizacao_real     := coalesce(v_old.data_nacionalizacao_real,     v_entrega.data_nacionalizacao_real);',
'        v_new.data_recebimento_calculada   := coalesce(v_old.data_recebimento_calculada,   v_entrega.data_recebimento_calculada);',
'        v_new.data_recebimento_informada   := coalesce(v_old.data_recebimento_informada,   v_entrega.data_recebimento_informada);',
'        v_new.data_recebimento_real        := coalesce(v_old.data_recebimento_real,        v_entrega.data_recebimento_real);',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao     := sysdate;',
'',
'        bo_imp_processoimportacao.grava(',
'            p_id        => p_id,',
'            p_encadeado => p_encadeado,',
'            p_sucesso   => p_sucesso,',
'            p_messages  => p_messages',
'        );',
'    end atualizar_datas_processo_com_base_entrega;',
'',
'',
unistr('    -- Usada no TD848 Altera previs\00F5es'),
'    procedure altera_registro_especifico(',
'        p_id_endereco_origem in imp_processoimportacao.id_endereco_origem%type,',
'        p_id_local_embarque in imp_processoimportacao.id_local_embarque%type,',
'        p_id_local_desembarque in imp_processoimportacao.id_local_desembarque%type,',
'        p_id_recinto_alfandegado in imp_processoimportacao.id_recinto_alfandegado%type,',
'        p_id_endereco_destino in imp_processoimportacao.id_endereco_destino%type,',
'        p_data_disponivel_informada in imp_processoimportacao.data_disponivel_informada%type,',
'        p_data_embarque_informada in imp_processoimportacao.data_embarque_informada%type,',
'        p_data_desembarque_informada in imp_processoimportacao.data_desembarque_informada%type,',
'        p_data_registro_di_informada in imp_processoimportacao.data_registro_di_informada%type,',
'        p_data_nacionalizacao_informada in imp_processoimportacao.data_nacionalizacao_informada%type,',
'        p_data_recebimento_informada in imp_processoimportacao.data_recebimento_informada%type,',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao.altera_registro_especifico'';',
'        v_pagina := p_pagina;',
'        --',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */',
'        v_new.id_endereco_origem            := p_id_endereco_origem;',
'        v_new.id_local_embarque             := p_id_local_embarque;',
'        v_new.id_local_desembarque          := p_id_local_desembarque;',
'        v_new.id_recinto_alfandegado          := p_id_recinto_alfandegado;',
'        v_new.id_endereco_destino           := p_id_endereco_destino;',
'        v_new.data_disponivel_informada     := p_data_disponivel_informada;',
'        v_new.data_embarque_informada       := p_data_embarque_informada;',
'        v_new.data_desembarque_informada    := p_data_desembarque_informada;',
'        v_new.data_registro_di_informada    := p_data_registro_di_informada;',
'        v_new.data_nacionalizacao_informada := p_data_nacionalizacao_informada;',
'        v_new.data_recebimento_informada    := p_data_recebimento_informada;',
'',
'        v_new.id := p_id;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_registro_especifico;',
'    --',
'    function retorna_total_tributos(',
'        p_id in imp_processoimportacao.id%type,',
'        p_converter_valor varchar2 default null',
'    ) return number is',
'        l_total_tributos number;',
'    begin',
'        if p_converter_valor is null then',
'            select sum(a.valor_previsto)',
'            into l_total_tributos',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id_processoimportacao = p_id',
'            and b.ind_tipo_despesa in (1,2,3,4,5,6,18,19);',
'        else',
'            select sum(a.valor_previsto * bo_ng_moeda_cotacao.retorna_cotacao_venda(a.id_tenant, a.id_moeda_prevista, c.id_moeda_tenant))',
'            into l_total_tributos',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            join imp_processoimportacao c on c.id = a.id_processoimportacao',
'            where a.id_processoimportacao = p_id',
'            and b.ind_tipo_despesa in (1,2,3,4,5,6,18,19);',
'        end if;',
'',
'        return nvl(l_total_tributos,0);',
'    end retorna_total_tributos;',
'    --',
'    function retorna_total_despesas(',
'        p_id in imp_processoimportacao.id%type,',
'        p_converter_valor varchar2 default null',
'    ) return number is',
'        l_verifica number;',
'        l_total_despesas number;',
'        l_outras_despesas number;',
'        l_antidumping number;',
'        l_afrmm number;',
'        l_taxa_siscomex number;',
'        l_irrf number;',
'        l_cide number;',
'        l_iof number;',
'        l_iss number;',
'        l_resultado number;',
'    begin',
'        if p_converter_valor is null then',
'            select',
'                sum(a.valor_previsto)',
'            into',
'                l_total_despesas',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            join imp_processoimportacao c on c.id = a.id_processoimportacao',
'            where a.id_processoimportacao = p_id',
