'    procedure altera_dados_gerais(',
'        p_ind_modalidade_importacao in imp_processoimportacao.ind_modalidade_importacao%type,',
'        p_id_embarcador in imp_processoimportacao.id_embarcador%type,',
'        p_id_importador in imp_processoimportacao.id_importador%type,',
'        p_id_adquirente in imp_processoimportacao.id_adquirente%type,',
'        p_id_despachante in imp_processoimportacao.id_despachante%type,',
'        p_referencia_despachante in imp_processoimportacao.referencia_despachante%type,',
'        p_id_usuario_responsavel in imp_processoimportacao.id_usuario_responsavel%type,',
'        p_id_viatransporte in imp_processoimportacao.id_viatransporte%type,',
'        p_id_transportador_internacional in imp_processoimportacao.id_transportador_internacional%type,',
'        p_conhecimento_transporte in imp_processoimportacao.conhecimento_transporte%type,',
'        p_navio in imp_processoimportacao.navio%type,',
'        p_viagem in imp_processoimportacao.viagem%type,',
'        p_id_transportador_nacional in imp_processoimportacao.id_transportador_nacional%type,',
'        p_id_endereco_origem in imp_processoimportacao.id_endereco_origem%type,',
'        p_id_local_embarque in imp_processoimportacao.id_local_embarque%type,',
'        p_id_local_desembarque in imp_processoimportacao.id_local_desembarque%type,',
'        p_id_recinto_alfandegado in imp_processoimportacao.id_recinto_alfandegado%type,',
'        p_id_endereco_destino in imp_processoimportacao.id_endereco_destino%type,',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao.altera_dados_gerais'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.ind_modalidade_importacao := p_ind_modalidade_importacao;',
'        v_new.id_embarcador := p_id_embarcador;',
'        v_new.id_importador := p_id_importador;',
'        v_new.id_adquirente := p_id_adquirente;',
'        v_new.id_despachante := p_id_despachante;',
'        v_new.referencia_despachante := p_referencia_despachante;',
'        v_new.id_usuario_responsavel := p_id_usuario_responsavel;',
'        v_new.id_viatransporte := p_id_viatransporte;',
'        v_new.id_transportador_internacional := p_id_transportador_internacional;',
'        v_new.conhecimento_transporte := p_conhecimento_transporte;',
'        v_new.navio := p_navio;',
'        v_new.viagem := p_viagem;',
'        v_new.id_transportador_nacional := p_id_transportador_nacional;',
'        v_new.id_endereco_origem := p_id_endereco_origem;',
'        v_new.id_local_embarque := p_id_local_embarque;',
'        v_new.id_local_desembarque := p_id_local_desembarque;',
'        v_new.id_recinto_alfandegado := p_id_recinto_alfandegado;',
'        v_new.id_endereco_destino := p_id_endereco_destino;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_DADOS_GERAIS'';',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_dados_gerais;',
'    --',
'    function calcula_total_tributos(',
'        p_id in imp_processoimportacao.id%type',
'    ) return number is',
'        l_total_tributo number := 0;',
'        l_valor_antidumping number := 0;',
'        l_valor_multa number := 0;',
'    begin',
'        -- select',
'        --     (',
'        --         (sum(bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * nvl(nullif(a.valor_informado_ii,0),a.valor_calculado_ii)))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * a.valor_ipi))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * a.valor_pis))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * a.valor_cofins))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * a.valor_cbs))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * a.valor_icms))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * nvl(a.valor_icms_st,0)))',
'        --     +',
'        --         sum((bo_ng_moeda_cotacao.retorna_cotacao_compra(c.id_tenant, b.id_moeda, c.id_moeda_tenant) * a.valor_ibs))',
'        --     )',
'        -- into l_total_tributo',
'        -- from imp_processoimportacao_item_tributo a',
'        -- join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item',
'        -- join imp_processoimportacao c on c.id = b.id_processoimportacao',
'        -- where c.id = p_id;',
'',
'        select nvl(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(b1.id_tenant, a1.id_moeda_prevista, b1.id_moeda_tenant) * a1.valor_previsto)),0)',
'        into l_valor_antidumping',
'        from imp_processoimportacao_despesa a1',
'        join imp_processoimportacao b1 on b1.id = a1.id_processoimportacao',
'        join ng_despesa c1 on c1.id = a1.id_despesa',
'        where b1.id = p_id',
'        and c1.ind_tipo_despesa = 8;',
'',
'        select nvl(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(b2.id_tenant, a2.id_moeda_prevista, b2.id_moeda_tenant) * a2.valor_previsto)),0)',
'        into l_valor_multa',
'        from imp_processoimportacao_despesa a2',
'        join imp_processoimportacao b2 on b2.id = a2.id_processoimportacao',
'        join ng_despesa c2 on c2.id = a2.id_despesa',
'        where b2.id = p_id',
'        and c2.ind_tipo_despesa = 17;',
'',
'        return (l_total_tributo + nvl(l_valor_antidumping, 0) + nvl(l_valor_multa, 0));',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_tributos;',
'    --',
'    function calcula_total_despesas(',
'        p_id in imp_processoimportacao.id%type',
'    ) return number is',
'        l_resultado number;',
'    begin',
'        select nvl(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(c.id_tenant, a.id_moeda_prevista, c.id_moeda_tenant) * a.valor_previsto)),0)',
'        into l_resultado',
'        from imp_processoimportacao_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        join imp_processoimportacao c on c.id = a.id_processoimportacao',
'        where a.id_processoimportacao = p_id',
'        and b.ind_tipo_despesa in (0,7,11,12,13,14,15);',
'',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_despesas;',
'    --',
'    function calcula_total_custos_importacao(',
'        p_id in imp_processoimportacao.id%type',
'    ) return number is',
'        l_resultado number;',
'    begin',
'        select nvl(sum((bo_ng_moeda_cotacao.retorna_cotacao_venda(c.id_tenant, a.id_moeda_prevista, c.id_moeda_tenant) * a.valor_previsto)),0)',
'        into l_resultado',
'        from imp_processoimportacao_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        join imp_processoimportacao c on c.id = a.id_processoimportacao',
'        where a.id_processoimportacao = p_id',
'        and b.ind_tipo_despesa in (9,10,16);',
'',
'        l_resultado := nvl(l_resultado, 0) + nvl(calcula_total_tributos(p_id), 0) + nvl(calcula_total_despesas(p_id), 0);',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_custos_importacao;',
'    --',
'    function calcula_total_importacao(',
'        p_id in imp_processoimportacao.id%type',
'    ) return number is',
'        l_resultado number;',
'    begin',
'        select sum(c.vmle)',
'        into l_resultado',
'        from imp_processoimportacao a',
'        join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'        join imp_processoimportacao_item_tributo c on c.id_processoimportacao_item = b.id',
'        where a.id = p_id;',
'',
'        l_resultado := nvl(l_resultado, 0) + nvl(calcula_total_custos_importacao(p_id), 0);',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_total_importacao;',
