'        v_new.vmld           := nvl(v_vmle,0) + nvl(v_frete,0) + nvl(v_seguro,0) + nvl(v_acrescimo,0);',
'        v_new.multa          := nvl(v_multa, 0);',
'        v_new.antidumping    := nvl(v_antidumping, 0);',
'        v_new.valor_ii       := nvl(v_valor_ii, 0);',
'        v_new.valor_ipi      := nvl(v_valor_ipi, 0);',
'        v_new.valor_pis      := nvl(v_valor_pis, 0);',
'        v_new.valor_cofins   := nvl(v_valor_cofins, 0);',
'        v_new.valor_icms     := nvl(v_valor_icms, 0);',
'        v_new.valor_icms_st  := nvl(v_valor_icms_st, 0);',
'        v_new.valor_cbs      := nvl(v_valor_cbs, 0);',
'        v_new.valor_ibs      := nvl(v_valor_ibs, 0);',
'        v_new.valor_total_condicao_venda    := nvl(v_valor_total_condicao_venda, 0);',
'',
'        v_new.id_usuario_alterou    := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao        := sysdate;',
'',
'        v_operacao                  := ''ATUALIZA_VALORES_PROCESSO'';',
'',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end atualiza_valores_processo;',
'    --',
'    procedure gerencia_invoice_entrega_item(',
'        p_fonte in varchar2,',
'        p_ids_entregas in varchar2,',
'        p_id_invoice in imp_invoice_item.id_invoice%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_new_ids_entregas apex_t_varchar2;',
'        l_old_ids_entregas apex_t_varchar2;',
'        l_lista1 apex_t_varchar2 := apex_t_varchar2();',
'        l_lista2 apex_t_varchar2 := apex_t_varchar2();',
'        l_lista3 apex_t_varchar2 := apex_t_varchar2();',
'        l_id number;',
'    begin',
'        -- Lista de ids das entregas selecionadas em tela:',
'        l_new_ids_entregas := apex_string.split(p_ids_entregas, '','');',
'',
unistr('        -- Lista de ids das entregas j\00E1 vinculadas \00E0 invoice:'),
'        select distinct id_entrega bulk collect into l_old_ids_entregas from imp_invoice_item where id_invoice = p_id_invoice;',
'',
unistr('        -- Cria a lista de entregas para inclus\00E3o:'),
'        for i in 1..l_new_ids_entregas.count loop',
'            if not (l_new_ids_entregas(i) member of l_old_ids_entregas) then',
'                l_lista1.extend;',
'                l_lista1(l_lista1.last) := l_new_ids_entregas(i);',
'            end if;',
'        end loop;',
'',
unistr('        -- Cria a lista de entregas que n\00E3o foram modificadas:'),
'        for i in 1..l_new_ids_entregas.count loop',
'            if (l_new_ids_entregas(i) member of l_old_ids_entregas) then',
'                l_lista2.extend;',
'                l_lista2(l_lista2.last) := l_new_ids_entregas(i);',
'            end if;',
'        end loop;',
'',
unistr('        -- Cria a lista de entregas para exclus\00E3o:'),
'        for i in 1..l_old_ids_entregas.count loop',
'            if not (l_old_ids_entregas(i) member of l_new_ids_entregas) then',
'                l_lista3.extend;',
'                l_lista3(l_lista3.last) := l_old_ids_entregas(i);',
'            end if;',
'        end loop;',
'',
unistr('        -- Primeiro executa as exclus\00F5es para manter a sequ\00EAncia dos itens "organizada":'),
'        if l_lista3.count > 0 then',
'            for item in (',
'                select * from imp_invoice_item where id_invoice = p_id_invoice and id_entrega in (select column_value from table(l_lista3))',
'            ) loop',
'                bo_imp_invoice_item.exclui_registro(',
'                    p_id => item.id,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'',
'            -- Desvincula o id da invoice das entregas:',
'            for entrega in (',
'                select id from imp_entrega where id_invoice = p_id_invoice and id in (select column_value from table(l_lista3))',
'            ) loop',
'                bo_imp_entrega.altera_id_invoice(',
'                    p_id_invoice => null,',
'                    p_id => entrega.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'',
unistr('        -- Executa as inclus\00F5es de acordo com a fonte:'),
'        if l_lista1.count > 0 and lower(p_fonte) = ''processo'' then',
'            for item in (',
'                select * from imp_processoimportacao_item where id_entrega in (select column_value from table(l_lista1))',
'            ) loop',
'                bo_imp_invoice_item.inclui_registro(',
'                    p_id_tenant => item.id_tenant,',
'                    p_id_invoice => p_id_invoice,',
'                    p_id_entrega => item.id_entrega,',
'                    p_id_entrega_item => item.id_entrega_item,',
'                    p_sequencia_item_invoice => bo_imp_invoice_item.gera_sequencia_item(p_id_invoice),',
'                    p_id_item => item.id_item,',
'                    p_id_ncm => item.id_ncm,',
'                    p_id_unidademedida => item.id_unidademedida,',
'                    p_quantidade => nvl(item.quantidade_saldo, 0),--item.quantidade,',
'                    p_peso_unitario => item.peso_unitario,',
'                    p_peso_liquido_total => item.peso_liquido_total,',
unistr('                    p_peso_bruto_unitario => null, -- Usu\00E1rio deve informar.'),
unistr('                    p_peso_bruto_total => null,    -- Usu\00E1rio deve informar.'),
'                    p_valor_unitario => item.valor_unitario,',
'                    p_valor_desconto => item.valor_desconto,',
'                    p_valor_total_mercadoria => (nvl(item.quantidade_saldo, 0) * (nvl(item.valor_unitario,0) - nvl(item.valor_desconto,0))),',
'                    p_valor_total_condicao_venda => item.valor_total_condicao_venda,',
'                    p_valor_total_desconto_invoice_item => null,--item.valor_total_desconto_invoice_item,',
'                    p_valor_total_despesa_invoice_item => null,--item.valor_total_despesa_invoice_item,',
'                    p_id_fabricante => item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(item.id_fabricante),',
'                    p_id => l_id,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        elsif l_lista1.count > 0 and lower(p_fonte) = ''entrega'' then',
'            for item in (',
'                select * from imp_entrega_item where id_entrega in (select column_value from table(l_lista1)) order by id',
'            ) loop',
'                bo_imp_invoice_item.inclui_registro(',
'                    p_id_tenant => item.id_tenant,',
'                    p_id_invoice => p_id_invoice,',
'                    p_id_entrega => item.id_entrega,',
'                    p_id_entrega_item => item.id,',
'                    p_sequencia_item_invoice => bo_imp_invoice_item.gera_sequencia_item(p_id_invoice),',
'                    p_id_item => item.id_item,',
'                    p_id_ncm => item.id_ncm,',
'                    p_id_unidademedida => item.id_unidademedida,',
'                    p_quantidade => item.quantidade_saldo,',
'                    p_peso_unitario => item.peso_unitario,',
'                    p_peso_liquido_total => item.peso_liquido_total,',
unistr('                    p_peso_bruto_unitario => null, -- Usu\00E1rio deve informar.'),
unistr('                    p_peso_bruto_total => null,    -- Usu\00E1rio deve informar.'),
'                    p_valor_unitario => item.valor_unitario,',
'                    p_valor_desconto => item.valor_desconto_unitario,',
'                    p_valor_total_mercadoria => (nvl(item.quantidade_saldo, 0) * (nvl(item.valor_unitario,0) - nvl(item.valor_desconto_unitario,0))),',
'                    p_valor_total_condicao_venda => item.valor_total_condicao_venda,',
'                    p_valor_total_desconto_invoice_item => null,--item.valor_total_desconto_invoice_item,',
'                    p_valor_total_despesa_invoice_item => null,--item.valor_total_despesa_invoice_item,',
'                    p_id_fabricante => item.id_fabricante,',
'                    p_id_pais_origem => bo_ng_pessoa.retorna_id_pais_origem(item.id_fabricante),',
'                    p_id => l_id,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'',
'        -- Vincula o id da invoice nas entregas:',
'        if l_lista1.count > 0 then',
'            for entrega in (',
'                select id from imp_entrega where id in (select column_value from table(l_lista1))',
'            ) loop',
'                bo_imp_entrega.altera_id_invoice(',
'                    p_id_invoice => p_id_invoice,',
'                    p_id => entrega.id,',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end loop;',
'        end if;',
'    end gerencia_invoice_entrega_item;',
'    --',
'    function retorna_numero_processoimportacao(',
'        p_id_tenant                     in imp_processoimportacao.id_tenant%type',
'    ) return varchar2 is',
'        l_verifica_configuracao         number;',
'        l_configuracao                  number;',
'        l_aux_prefixo                   varchar2(20);',
'        l_aux_numero                    varchar2(20);',
'        l_aux_quantidade_digitos        number;',
'        l_aux_sufixo                    varchar2(20);',
'        l_numero_processo_importacao    varchar2(200);',
'    begin',
'        select count(1) into l_verifica_configuracao',
'        from mpd_configuracao_ng a join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id',
'        where a.id_tenant = p_id_tenant and a.codigo_configuracao = 7 and b.id = a.valor_dominio;',
'',
'        if l_verifica_configuracao > 0 then',
'            select codigo_dominio into l_configuracao',
'            from mpd_configuracao_ng a join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id',
'            where a.id_tenant = p_id_tenant and a.codigo_configuracao = 7 and b.id = a.valor_dominio;',
'',
'            if l_configuracao = 3 then',
'                return null;',
'            end if;',
'',
'            if l_configuracao = 2 then',
'                select valor_string into l_aux_prefixo from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 8;',
'                select (valor_inteiro + 1) into l_aux_numero from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 9;',
'                select valor_inteiro into l_aux_quantidade_digitos from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 10;',
'                select valor_string into l_aux_sufixo from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = 11;',
'',
'                l_numero_processo_importacao := l_aux_prefixo||lpad(l_aux_numero, l_aux_quantidade_digitos, ''0'')||l_aux_sufixo;',
'            end if;',
'        end if;',
'        return l_numero_processo_importacao;',
'    exception',
'        when others then',
'            return '''';',
'    end retorna_numero_processoimportacao;',
'    --',
'    procedure altera_mpd_configuracao_ng_num_processoimportacao(',
'        p_id                            in imp_processoimportacao.id%type,',
'        p_encadeado                     in boolean default false,',
'        p_sucesso                       out clob,',
'        p_messages                      out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant                     number;',
'        l_num_processoimportacao        varchar2(50);',
'        l_configuracao                  mpd_configuracao_ng%rowtype;',
'        l_aux_prefixo                   varchar2(20);',
'        l_aux_quantidade_digitos        number;',
'        l_aux_sufixo                    varchar2(20);',
'        l_novo_num_processoimportacao   varchar2(50);',
'    begin',
'        select id_tenant, num_processoimportacao into l_id_tenant, l_num_processoimportacao from imp_processoimportacao where id = p_id;',
'        select * into l_configuracao from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 9;',
'',
'        select valor_string into l_aux_prefixo from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 8;',
'        select valor_inteiro into l_aux_quantidade_digitos from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 10;',
'        select valor_string into l_aux_sufixo from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 11;',
'',
'        l_novo_num_processoimportacao := l_aux_prefixo || lpad(to_char(l_configuracao.valor_inteiro + 1), l_aux_quantidade_digitos, ''0'') ||l_aux_sufixo;',
'',
'        if l_novo_num_processoimportacao = l_num_processoimportacao then',
'            bo_mpd_configuracao_ng.altera_registro(',
'                p_id_tenant => l_configuracao.id_tenant,',
'                p_id_entidade => l_configuracao.id_entidade,',
'                p_id_registro => l_configuracao.id_registro,',
'                p_descricao_configuracao => l_configuracao.descricao_configuracao,',
'                p_codigo_configuracao => l_configuracao.codigo_configuracao,',
'                p_ind_tipo_dado => l_configuracao.ind_tipo_dado,',
'       '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(155851324865645312)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'         p_valor_inteiro => (l_configuracao.valor_inteiro + 1),',
'                p_valor_decimal => l_configuracao.valor_decimal,',
'                p_quantidade_decimal => l_configuracao.quantidade_decimal,',
'                p_valor_string => l_configuracao.valor_string,',
'                p_valor_data => l_configuracao.valor_data,',
'                p_valor_data_hora => l_configuracao.valor_data_hora,',
'                p_valor_dominio => l_configuracao.valor_dominio,',
'                p_ind_grupo_funcionalidade => l_configuracao.ind_grupo_funcionalidade,',
'                p_id => l_configuracao.id,',
'                p_data_alteracao => l_configuracao.data_alteracao,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    end altera_mpd_configuracao_ng_num_processoimportacao;',
'    --',
'',
'    procedure altera_registro_anexo(',
'        p_data_embarque_real in imp_processoimportacao.data_embarque_real%type,',
'        p_conhecimento_transporte in imp_processoimportacao.conhecimento_transporte%type,',
'        p_navio in imp_processoimportacao.navio%type,',
'        p_data_alteracao in imp_processoimportacao.data_alteracao%TYPE,',
'',
'        -- parametros para anexo',
'        p_ind_situacao in ng_anexo.ind_situacao%type,',
'        p_id_documento in ng_anexo.id_documento%type,',
'        p_id_entidade in ng_anexo.id_entidade%type,',
'        p_id_referencia in ng_anexo.id_referencia%type,',
'        p_versao_documento in ng_anexo.versao_documento%type,',
'        p_anexo in ng_anexo.anexo%type,',
'        p_anexo_name in ng_anexo.anexo_name%type,',
'        p_anexo_mimetype in ng_anexo.anexo_mimetype%type,',
'        p_anexo_charset in ng_anexo.anexo_charset%type,',
'',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_operacao := ''altera_registro_anexo'';',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao.altera_registro_anexo'';',
'        v_pagina := p_pagina;',
'        v_data_alteracao := p_data_alteracao;',
'        --',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */',
'        v_new.data_embarque_real      := p_data_embarque_real;',
'        v_new.conhecimento_transporte := p_conhecimento_transporte;',
'        v_new.navio                   := p_navio;',
'        v_new.id := p_id;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        --',
'        /* Seta valores passados por parametros para anexo */',
'        v_new_anexo.ind_situacao := p_ind_situacao;',
'        v_new_anexo.id_documento := p_id_documento;',
'        v_new_anexo.id_entidade := p_id_entidade;',
'        v_new_anexo.id_referencia := p_id_referencia;',
'        v_new_anexo.versao_documento := p_versao_documento;',
'        v_new_anexo.anexo := p_anexo;',
'        v_new_anexo.anexo_name := p_anexo_name;',
'        v_new_anexo.anexo_mimetype := p_anexo_mimetype;',
'        v_new_anexo.anexo_charset := p_anexo_charset;',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'',
'      end altera_registro_anexo;',
'',
'',
'    procedure confirma_data_registro_di_real(',
'            p_data_registro_di_real in imp_processoimportacao.data_registro_di_real%type,',
'            p_numero_duimp in imp_declaracaoimportacao.numero_duimp%type,',
'            p_id in imp_processoimportacao.id%type,',
'            p_data_alteracao in imp_processoimportacao.data_alteracao%TYPE,',
'            p_pagina in number default 0,',
'            p_encadeado in boolean default false,',
'            p_sucesso out clob,',
'            p_messages out pkg_mensagem.message_record_table',
'    )is',
'            v_id_declaracao_criada imp_declaracaoimportacao.id%type;',
'    begin',
'            v_numero_duimp := p_numero_duimp;',
'            v_operacao := ''confirma_data_registro_di_real'';',
'            v_messages := pkg_mensagem.message_record_table();',
'            v_parametro(0) := ''bo_imp_processoimportacao.confirma_data_registro_di_real'';',
'            v_pagina := p_pagina;',
'            v_data_alteracao := p_data_alteracao;',
'',
'            -- Busca registro atual',
'            select * into v_old from imp_processoimportacao where id = p_id;',
'            v_new := v_old;',
'',
'            -- Seta novos valores',
'            v_new.data_registro_di_real := p_data_registro_di_real;',
'            v_new.ind_status := 5;',
'            v_new.id := p_id;',
'            v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'            v_new.data_alteracao := sysdate;',
'',
unistr('            -- Atualiza o processo de importa\00E7\00E3o'),
'            grava(p_id, p_encadeado, p_sucesso, p_messages);',
'',
'    end confirma_data_registro_di_real;',
'',
'    procedure confirma_data_desembarque(',
'        p_data_desembarque_real in imp_processoimportacao.data_desembarque_real%type,',
'        p_id_recinto_alfandegado  in imp_processoimportacao.id_recinto_alfandegado%type,',
'        p_id in imp_processoimportacao.id%type,',
'        p_data_alteracao in imp_processoimportacao.data_alteracao%TYPE,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        v_operacao := ''confirma_data_desembarque'' ;',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'        v_new.data_desembarque_real := p_data_desembarque_real;',
'        v_new.ind_status := 4;',
'        v_new.id_recinto_alfandegado := p_id_recinto_alfandegado;',
unistr('        -- Atualiza o processo de importa\00E7\00E3o'),
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end confirma_data_desembarque;',
'',
'    procedure confirma_data_recebimento_real(',
'        p_data_recebimento_real in imp_processoimportacao.data_recebimento_real%type,',
'        p_id in imp_processoimportacao.id%type,',
'        p_data_alteracao in imp_processoimportacao.data_alteracao%TYPE,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
