'',
'    procedure gera_titulos(',
'        p_evento    in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade_pedido  number;',
'        l_id_entidade_invoice number;',
'        l_id_titulo           number;',
'        l_mensagem            clob;',
'        l_paramentros         pkg_mensagem.paramentros;',
'    begin',
'        select id into l_id_entidade_pedido',
'          from srv_entidade',
'         where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
'        select id into l_id_entidade_invoice',
'          from srv_entidade',
'         where lower(nome_entidade) = ''imp_invoice'';',
'',
unistr('        -- Entregas sem invoice \2192 pagamentos do pedido'),
'',
'        for pag in (',
'            select pag.id,',
'                   pag.numero_parcela,',
'                   pag.data_vencimento_prevista,',
'                   pag.valor,',
'                   ped.id_exportador,',
'                   ped.id_moeda,',
'                   ped.numero_pedido_importacao',
'              from imp_entrega ent',
'              join imp_pedidoimportacao_pagamento pag on pag.id_entrega         = ent.id',
'              join imp_pedidoimportacao ped            on ped.id                = pag.id_pedidoimportacao',
'              join ng_condicaopagamento cond           on cond.id               = ped.id_condicaopagamento',
'              join ng_condicaopagamento_parcela parc',
'                   on parc.id_condicaopagamento      = cond.id',
'                  and parc.numero_parcela            = pag.numero_parcela',
'             where ent.id_processoimportacao         = v_new.id',
'               and ent.id_invoice                    is null',
'               and pag.ind_status_pagamento          = 1',
'               and parc.ind_evento_gerador_pagamento = p_evento',
'               and not exists (',
'                   select 1',
'                     from fin_titulopagamento t',
'                    where t.id_referencia           = pag.id',
'                      and t.id_entidade             = l_id_entidade_pedido',
'                      and t.ind_status_pagamento not in (3, 4)',
'               )',
'        ) loop',
'            bo_fin_titulopagamento.inclui_registro(',
'                p_id_tenant                   => v_new.id_tenant,',
'                p_id_entidade                 => l_id_entidade_pedido,',
'                p_id_referencia               => pag.id,',
'                p_ind_status_pagamento        => 1,',
'                p_id_fornecedor               => pag.id_exportador,',
'                p_id_fornecedor_contabancaria => null,',
'                p_data_vencimento             => pag.data_vencimento_prevista,',
'                p_data_pagamento              => null,',
'                p_data_compensacao            => null,',
'                p_id_moeda                    => pag.id_moeda,',
'                p_valor_titulo                => pag.valor,',
'                p_valor_pago                  => 0,',
'                p_saldo_pagar                 => pag.valor,',
'                p_taxa_cambio                 => 0,',
'                p_valor_moeda_nacional        => 0,',
'                p_observacao                  => null,',
'                p_ind_multa_atraso_pagamento  => ''N'',',
'                p_valor_multa                 => 0,',
'                p_percentual_multa            => 0,',
'                p_periodo_multa               => null,',
'                p_valor_compensado            => 0,',
'                p_saldo_compensar             => pag.valor,',
'                p_id                          => l_id_titulo,',
'                p_pagina                      => v_pagina,',
'                p_encadeado                   => true,',
'                p_sucesso                     => p_sucesso,',
'                p_messages                    => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'',
'            l_paramentros(1) := pag.numero_pedido_importacao || ''-'' || to_char(pag.numero_parcela);',
'            l_paramentros(2) := to_char(pag.data_vencimento_prevista, ''DD/MM/YYYY'');',
'            l_paramentros(3) := ''R$ '' || to_char(pag.valor, ''FM999G999G990D00'', ''NLS_NUMERIC_CHARACTERS=,.'');',
'            pkg_mensagem.mensagem_original(555, l_paramentros, l_mensagem);',
'            p_sucesso := PKG_MENSAGEM.tag_mensagem(l_mensagem);',
'',
'        end loop;',
'',
'',
'',
unistr('        -- Entregas com invoice \2192 pagamentos da invoice'),
'        for pag in (',
'            select pag.id,',
'                   pag.numero_parcela,',
'                   pag.data_vencimento_prevista,',
'                   pag.valor,',
'                   inv.id_exportador,',
'                   inv.id_moeda,',
'                   inv.num_invoice',
'              from imp_entrega ent',
'              join imp_invoice inv                    on inv.id                 = ent.id_invoice',
'              join imp_invoice_pagamento pag          on pag.id_invoice         = inv.id',
'              join ng_condicaopagamento cond           on cond.id               = inv.id_condicaopagamento',
'              join ng_condicaopagamento_parcela parc',
'                   on parc.id_condicaopagamento      = cond.id',
'                  and parc.numero_parcela            = pag.numero_parcela',
'             where ent.id_processoimportacao         = v_new.id',
'               and ent.id_invoice                    is not null',
'               and pag.ind_status_pagamento          = 1',
'               and parc.ind_evento_gerador_pagamento = p_evento',
'               and not exists (',
'                   select 1',
'                     from fin_titulopagamento t',
'                    where t.id_referencia           = pag.id',
'                      and t.id_entidade             = l_id_entidade_invoice',
'                      and t.ind_status_pagamento not in (3, 4)',
'               )',
'        ) loop',
'            bo_fin_titulopagamento.inclui_registro(',
'                p_id_tenant                   => v_new.id_tenant,',
'                p_id_entidade                 => l_id_entidade_invoice,',
'                p_id_referencia               => pag.id,',
'                p_ind_status_pagamento        => 1,',
'                p_id_fornecedor               => pag.id_exportador,',
'                p_id_fornecedor_contabancaria => null,',
'                p_data_vencimento             => pag.data_vencimento_prevista,',
'                p_data_pagamento              => null,',
'                p_data_compensacao            => null,',
'                p_id_moeda                    => pag.id_moeda,',
'                p_valor_titulo                => pag.valor,',
'                p_valor_pago                  => 0,',
'                p_saldo_pagar                 => pag.valor,',
'                p_taxa_cambio                 => 0,',
'                p_valor_moeda_nacional        => 0,',
'                p_observacao                  => null,',
'                p_ind_multa_atraso_pagamento  => ''N'',',
'                p_valor_multa                 => 0,',
'                p_percentual_multa            => 0,',
'                p_periodo_multa               => null,',
'                p_valor_compensado            => 0,',
'                p_saldo_compensar             => pag.valor,',
'                p_id                          => l_id_titulo,',
'                p_pagina                      => v_pagina,',
'                p_encadeado                   => true,',
'                p_sucesso                     => p_sucesso,',
'                p_messages                    => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'',
'            l_paramentros(1) := pag.num_invoice || ''-'' || to_char(pag.numero_parcela);',
'            l_paramentros(2) := to_char(pag.data_vencimento_prevista, ''DD/MM/YYYY'');',
'            l_paramentros(3) := ''R$ '' || to_char(pag.valor, ''FM999G999G990D00'', ''NLS_NUMERIC_CHARACTERS=,.'');',
'            pkg_mensagem.mensagem_original(555, l_paramentros, l_mensagem);',
'            p_sucesso := PKG_MENSAGEM.tag_mensagem(l_mensagem);',
'        end loop;',
'        --     l_paramentros(1) := ''-'' ;',
'        --     l_paramentros(2) := ''DD/MM/YYYY'';',
'        --     l_paramentros(3) := ''R$ '';',
'        --     pkg_mensagem.mensagem_original(555, l_paramentros, l_mensagem);',
'        --     --p_sucesso := l_mensagem;',
'        --     p_sucesso := PKG_MENSAGEM.tag_mensagem(l_mensagem);',
'',
'    end gera_titulos;',
'    --',
