'    --',
'    function verifica_itens_vinculados_invoice(',
'        p_id_processoimportacao in imp_processoimportacao.id%type',
'    ) return varchar2',
'    is',
'        l_qtd_itens number;',
'        l_qtd_saldo number;',
'    begin',
'        -- quantidade de itens do processo',
'        select count(*) into l_qtd_itens from imp_processoimportacao_item where id_processoimportacao = p_id_processoimportacao;',
'',
'        if l_qtd_itens = 0 then',
'            return ''N'';',
'        end if;',
'',
'        -- itens que ainda possuem saldo',
'        select count(*) into l_qtd_saldo from imp_processoimportacao_item where id_processoimportacao = p_id_processoimportacao and nvl(quantidade_saldo,0) > 0;',
'',
'        if l_qtd_saldo = 0 then',
'            return ''S'';',
'        else',
'            return ''N'';',
'        end if;',
'    end;',
'    --',
'    procedure atualiza_ind_itens_vinculado_invoice(',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao.atualiza_ind_itens_vinculado_invoice'';',
'        v_pagina := p_pagina;',
'',
'        -- Busca do registro original',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
unistr('        -- Atribui\00E7\00E3o de valores'),
'        v_new.ind_itens_vinculado_invoice := verifica_itens_vinculados_invoice(p_id);',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        --v_new.data_alteracao := sysdate;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ATUALIZA_IND_ITENS_VINCULADO_INVOICE'';',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end atualiza_ind_itens_vinculado_invoice;',
'    --',
'',
'    procedure cancelar_processo(',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao.cancelar_processo'';',
'        v_pagina := p_pagina;',
'',
'        -- Busca do registro original',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
unistr('        -- Atribui\00E7  o de valores'),
'        v_new.ind_status 										:= 9;',
'				v_new.data_disponivel_calculada     := NULL;',
'				v_new.data_disponivel_informada     := NULL;',
'				v_new.data_disponivel_real          := NULL;',
'				v_new.data_embarque_calculada       := NULL;',
'				v_new.data_embarque_informada       := NULL;',
'				v_new.data_desembarque_calculada    := NULL;',
'				v_new.data_desembarque_informada    := NULL;',
'				v_new.data_nacionalizacao_calculada := NULL;',
'				v_new.data_nacionalizacao_informada := NULL;',
'				v_new.data_recebimento_calculada    := NULL;',
'				v_new.data_recebimento_informada    := NULL;',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''CANCELAR_PROCESSO'';',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end cancelar_processo;',
'',
'    procedure altera_id_processo_entrega (',
'        p_id_processoimportacao in imp_processoimportacao.id%type,',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table',
'	) is',
'	begin',
'	    for r in (',
'	        select id from imp_entrega',
'	        where id_processoimportacao = p_id_processoimportacao',
'	    ) loop',
'	        bo_imp_entrega.desvincular_processo(',
'	            p_id        => r.id,',
'	            p_encadeado => true,',
'	            p_sucesso   => p_sucesso,',
'	            p_messages  => p_messages',
'	        );',
'	    end loop;',
'	end altera_id_processo_entrega;',
'    --',
'    function calcula_valor_total_condicao_venda(',
'        p_id_processoimportacao in imp_processoimportacao.id%type',
'    ) return number',
'    is',
'        l_total number;',
'    begin',
'        select ',
'            nvl(sum(valor_total_condicao_venda * bo_imp_processoimportacao_item_tributo.cotacao_item_real(id)), 0) ',
'        into ',
'            l_total ',
'        from imp_processoimportacao_item ',
'        where id_processoimportacao = p_id_processoimportacao;',
'',
'        return l_total;',
'    end calcula_valor_total_condicao_venda;',
'    --',
'    function calcula_valor_total_mercadoria(',
'        p_id_processoimportacao in imp_processoimportacao.id%type',
'    ) return number',
'    is',
'        l_total number;',
'    begin',
'        select ',
'            nvl(sum(valor_total_mercadoria * bo_imp_processoimportacao_item_tributo.cotacao_item_real(id)), 0) ',
'        into ',
'            l_total ',
'        from imp_processoimportacao_item ',
'        where id_processoimportacao = p_id_processoimportacao;',
'',
'        return l_total;',
'    end calcula_valor_total_mercadoria;',
'    --',
'    procedure atualiza_valor_total_condicao_venda(',
'        p_id in imp_processoimportacao.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.valor_total_condicao_venda := calcula_valor_total_condicao_venda(p_id);',
'        v_new.valor_total_mercadoria := calcula_valor_total_mercadoria(p_id);',
'',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ATUALIZA_VALOR_TOTAL_CONDICAO_VENDA'';',
'',
'        grava(v_new.id, p_encadeado, p_sucesso, p_messages);',
'    end atualiza_valor_total_condicao_venda;',
'    --',
'',
