'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao.altera_ind_calculando_valores'';',
