'        v_new.data_hora_ultimo_calculo := nvl(p_data_hora_ultimo_calculo, v_old.data_hora_ultimo_calculo);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_IND_CALCULANDO_VALORES'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_ind_calculando_valores;',
'    --',
'    procedure configura_datas_calculadas is',
'    begin',
'        -- data_embarque_calculada',
'        if v_new.data_disponivel_real is not null then',
'            v_new.data_embarque_calculada := v_new.data_disponivel_real',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 2, v_new.id_endereco_origem, v_new.id_local_embarque);',
'        elsif v_new.data_disponivel_informada is not null then',
'            v_new.data_embarque_calculada := v_new.data_disponivel_informada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 2, v_new.id_endereco_origem, v_new.id_local_embarque);',
'        elsif v_new.data_disponivel_calculada is not null then',
'            v_new.data_embarque_calculada := v_new.data_disponivel_calculada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 2, v_new.id_endereco_origem, v_new.id_local_embarque);',
'        else',
'            v_new.data_embarque_calculada := null;',
'        end if;',
'',
'        -- data_desembarque_calculada',
'        if v_new.data_embarque_real is not null then',
'            v_new.data_desembarque_calculada := v_new.data_embarque_real',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque);',
'        elsif v_new.data_embarque_informada is not null then',
'            v_new.data_desembarque_calculada := v_new.data_embarque_informada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque);',
'        elsif v_new.data_embarque_calculada is not null then',
'            v_new.data_desembarque_calculada := v_new.data_embarque_calculada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 3, null, v_new.id_local_embarque, v_new.id_local_desembarque);',
'        else',
'            v_new.data_desembarque_calculada := null;',
'        end if;',
'',
'        -- data_nacionalizacao_calculada',
'        if v_new.data_desembarque_real is not null then',
'            v_new.data_nacionalizacao_calculada := v_new.data_desembarque_real',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque);',
'        elsif v_new.data_desembarque_informada is not null then',
'            v_new.data_nacionalizacao_calculada := v_new.data_desembarque_informada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque);',
'        elsif v_new.data_desembarque_calculada is not null then',
'            v_new.data_nacionalizacao_calculada := v_new.data_desembarque_calculada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 4, null, null, v_new.id_local_desembarque);',
'        else',
'            v_new.data_nacionalizacao_calculada := null;',
'        end if;',
'',
'        -- data_recebimento_calculada',
'        if v_new.data_nacionalizacao_real is not null then',
'            v_new.data_recebimento_calculada := v_new.data_nacionalizacao_real',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino);',
'        elsif v_new.data_nacionalizacao_informada is not null then',
'            v_new.data_recebimento_calculada := v_new.data_nacionalizacao_informada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino);',
'        elsif v_new.data_nacionalizacao_calculada is not null then',
'            v_new.data_recebimento_calculada := v_new.data_nacionalizacao_calculada',
'                + bo_ng_leadtime.retorna_quantidade_dias(v_new.id_tenant, 5, null, null, v_new.id_local_desembarque, v_new.id_endereco_destino);',
'        else',
'            v_new.data_recebimento_calculada := null;',
'        end if;',
'    end configura_datas_calculadas;',
'    --',
'    procedure cancela_titulos(',
'        p_evento    in number,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_entidade_pedido  number;',
'        l_id_entidade_invoice number;',
'    begin',
'        select id into l_id_entidade_pedido',
'          from srv_entidade',
'         where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
'        select id into l_id_entidade_invoice',
'          from srv_entidade',
'         where lower(nome_entidade) = ''imp_invoice'';',
'',
'        -- Entregas sem invoice',
'        for r in (',
'            select t.id as id_titulo, t.ind_status_pagamento',
'              from imp_entrega ent',
'              join imp_pedidoimportacao_pagamento pag  on pag.id_entrega            = ent.id',
'              join imp_pedidoimportacao ped             on ped.id                   = pag.id_pedidoimportacao',
'              join ng_condicaopagamento cond            on cond.id                  = ped.id_condicaopagamento',
'              join ng_condicaopagamento_parcela parc    on parc.id_condicaopagamento = cond.id',
'                                                      and parc.numero_parcela       = pag.numero_parcela',
'              join fin_titulopagamento t                on t.id_referencia          = pag.id',
'                                                      and t.id_entidade             = l_id_entidade_pedido',
'             where ent.id_processoimportacao            = v_new.id',
'               and ent.id_invoice                       is null',
'               and pag.ind_status_pagamento             = 2',
'               and parc.ind_evento_gerador_pagamento    = p_evento',
'               and t.ind_status_pagamento               in (1, 2)',
'        ) loop',
'            bo_fin_titulopagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => case when r.ind_status_pagamento = 1 then 3 else 4 end,',
'                p_id                   => r.id_titulo,',
'                p_pagina               => v_pagina,',
'                p_encadeado            => true,',
'                p_sucesso              => p_sucesso,',
'                p_messages             => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'        end loop;',
'',
'        -- Entregas com invoice',
'        for r in (',
'            select t.id as id_titulo, t.ind_status_pagamento',
'              from imp_entrega ent',
'              join imp_invoice inv                      on inv.id                   = ent.id_invoice',
'              join imp_invoice_pagamento pag            on pag.id_invoice            = inv.id',
'              join ng_condicaopagamento cond            on cond.id                  = inv.id_condicaopagamento',
'              join ng_condicaopagamento_parcela parc    on parc.id_condicaopagamento = cond.id',
'                                                      and parc.numero_parcela       = pag.numero_parcela',
'              join fin_titulopagamento t                on t.id_referencia          = pag.id',
'                                                      and t.id_entidade             = l_id_entidade_invoice',
'             where ent.id_processoimportacao            = v_new.id',
'               and ent.id_invoice                       is not null',
'               and pag.ind_status_pagamento             = 2',
'               and parc.ind_evento_gerador_pagamento    = p_evento',
'               and t.ind_status_pagamento               in (1, 2)',
'        ) loop',
'            bo_fin_titulopagamento.altera_ind_status_pagamento(',
'                p_ind_status_pagamento => case when r.ind_status_pagamento = 1 then 3 else 4 end,',
'                p_id                   => r.id_titulo,',
'                p_pagina               => v_pagina,',
'                p_encadeado            => true,',
'                p_sucesso              => p_sucesso,',
'                p_messages             => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'        end loop;',
'    end cancela_titulos;',
'    --',
'    procedure desconfirma_embarque_real(',
'        p_id             in imp_processoimportacao.id%type,',
'        p_data_alteracao in imp_processoimportacao.data_alteracao%type,',
'        p_pagina         in number default 0,',
'        p_encadeado      in boolean default false,',
'        p_sucesso        out clob,',
'        p_messages       out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_operacao       := ''desconfirma_embarque_real'';',
'        v_messages       := pkg_mensagem.message_record_table();',
'        v_parametro(0)   := ''bo_imp_processoimportacao.desconfirma_embarque_real'';',
'        v_pagina         := p_pagina;',
'        v_data_alteracao := p_data_alteracao;',
'',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.data_embarque_real     := null;',
'        v_new.ind_status             := 2;',
'        v_new.id_usuario_alterou     := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao         := sysdate;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end desconfirma_embarque_real;',
'    --',
'    procedure desconfirma_disponivel_real(',
'        p_id             in imp_processoimportacao.id%type,',
'        p_data_alteracao in imp_processoimportacao.data_alteracao%type,',
'        p_pagina         in number default 0,',
'        p_encadeado      in boolean default false,',
'        p_sucesso        out clob,',
'        p_messages       out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_operacao       := ''desconfirma_disponivel_real'';',
'        v_messages       := pkg_mensagem.message_record_table();',
'        v_parametro(0)   := ''bo_imp_processoimportacao.desconfirma_disponivel_real'';',
'        v_pagina         := p_pagina;',
'        v_data_alteracao := p_data_alteracao;',
'',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.data_disponivel_real   := null;',
'        v_new.ind_status             := 1;',
'        v_new.id_usuario_alterou     := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao         := sysdate;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end desconfirma_disponivel_real;',
'    --',
'    procedure concluir_processo_e_gerar_despesas(',
'        p_id                        in imp_processoimportacao.id%type,',
'        p_pagina                    in number default 0,',
'        p_encadeado                 in boolean default false,',
'        p_sucesso                   out clob,',
'        p_messages                  out pkg_mensagem.message_record_table,',
'        p_altera_status             in varchar2 default null',
'    )is',
'        l_id                        imp_processoimportacao_despesa.id%type;',
'        l_id_tenant                 imp_processoimportacao.id_tenant%type;',
'        l_id_moeda_tenant           imp_processoimportacao.id_moeda_tenant%type;',
'        l_id_moeda_nacional         ng_moeda.id%type;',
'        l_id_despesa                ng_despesa.id%type;',
'    begin',
'        --  Atribui valor em v_operacao para recalcular o processo:        ',
'        v_operacao := ''RECALCULAR_TRIBUTOS'';',
'        --',
'',
unistr('        -- OBS. SE N\00C3O ALTERAR O STATUS, N\00C3O VAI RECALCULAR O PROCESSO.'),
'        -- SE DEVE SEMPRE RECALCULAR DEVE CHAMAR A PROCEDURE GERENCIA_TRIBUTOS.',
'',
unistr('        -- altera ind_status do processo (etapa Conclus\00E3o)        '),
'        if p_altera_status is null then',
'            bo_imp_processoimportacao.altera_ind_status(',
'                p_ind_status            => 1,',
'                p_id                    => p_id,',
'                p_sucesso               => p_sucesso,',
'                p_messages              => p_messages',
'            );',
'        end if;',
'',
unistr('        -- Remove v\00EDnculo de invoices que n\00E3o possuem mais entregas neste processo'),
'        for r_invoice in (',
'            select i.id from imp_invoice i where i.id_processoimportacao = p_id and not exists (select 1 from imp_entrega e where e.id_invoice = i.id and e.id_processoimportacao = p_id)',
'        )',
'        loop',
'            bo_imp_invoice.altera_id_processoimportacao(',
'                p_id_processoimportacao => null,',
'                p_id                    => r_invoice.id,',
'                p_pagina                => p_pagina,',
'                p_encadeado             => true,',
'                p_sucesso               => p_sucesso,',
'                p_messages              => p_messages',
'            );',
'        end loop;',
'',
'        -- Vincula invoices das entregas atualmente associadas ao processo',
'        for r_invoice in (',
'            select distinct ie.id_invoice from imp_entrega ie where ie.id_processoimportacao = p_id and ie.id_invoice is not null',
'        )',
'        loop',
'            bo_imp_invoice.altera_id_processoimportacao(',
'                p_id_processoimportacao => p_id,',
'                p_id                    => r_invoice.id_invoice,',
'                p_pagina                => p_pagina,',
'                p_encadeado             => true,',
'                p_sucesso               => p_sucesso,',
'                p_messages              => p_messages',
'            );',
'        end loop;',
'',
'    /****************************************************************************************************',
unistr('    VERIFICAR UTILIDADE, PROVAVELMENTE N\00C3O \00C9 MAIS NECESS\00C1RIO:'),
'',
'        -- dados do processo',
'        select pi.id_tenant, pi.id_moeda_tenant into l_id_tenant, l_id_moeda_tenant from imp_processoimportacao pi where pi.id = p_id;',
'        -- moeda nacional do tenant',
'        l_id_moeda_nacional := bo_mpd_configuracao_ng.retorna_id_moeda_tenant(l_id_tenant);',
'',
unistr('        -- DEVE UTILIZAR M\00C9TODO PADR\00C3O DO BO (bo_imp_processoimportacao_despesa.exclui_registro):        '),
unistr('            -- remove despesas tribut\00E1rias anteriores'),
'            --delete from imp_processoimportacao_despesa ipd where ipd.id_processoimportacao = p_id and exists (select 1 from ng_despesa nd where nd.id = ipd.id_despesa and nd.ind_tipo_despesa in (1,2,3,4,5,6,18,19));        ',
'        for despesa_tributo in (',
'            select ipd.id ',
'            from imp_processoimportacao_despesa ipd ',
'            where ipd.id_processoimportacao = p_id ',
'            and exists (',
'                select 1 from ng_despesa nd where nd.id = ipd.id_despesa and nd.ind_tipo_despesa in (1,2,3,4,5,6,18,19)',
'            )',
'        ) loop',
'            bo_imp_processoimportacao_despesa.exclui_registro(despesa_tributo.id, p_encadeado, p_sucesso, p_messages);',
'        end loop;',
'        --',
'',
'        for r in (',
'            select 1 ind_tipo_despesa, nvl(sum(((pit.base_calculo_ii * pit.aliquota_ii) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) valor_previsto from imp_processoimportacao_item_tributo pit j'
||'oin imp_processoimportacao_item pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 2, nvl(sum(((pit.base_calculo_ipi * pit.aliquota_ipi) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportacao_ite'
||'m pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 3, nvl(sum(((pit.base_calculo_pis * pit.aliquota_pis) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportacao_ite'
||'m pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 4, nvl(sum(((pit.base_calculo_cofins * pit.aliquota_cofins) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportac'
||'ao_item pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 18, nvl(sum(((pit.base_calculo_cbs * pit.aliquota_cbs) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportacao_it'
||'em pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 19, nvl(sum(((pit.base_calculo_ibs * pit.aliquota_ibs) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportacao_it'
||'em pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 5, nvl(sum(((pit.base_calculo_icms * pit.aliquota_icms) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportacao_i'
||'tem pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'            union all',
'            select 6, nvl(sum(((pit.base_calculo_icms_st * pit.aliquota_icms) / 100) * bo_ng_moeda_cotacao.retorna_cotacao_venda(l_id_tenant, pii.id_moeda, l_id_moeda_tenant)),0) from imp_processoimportacao_item_tributo pit join imp_processoimportaca'
||'o_item pii on pii.id = pit.id_processoimportacao_item where pii.id_processoimportacao = p_id',
'        )',
'        loop',
'            begin',
'',
unistr('                -- busca despesa correspondente ao tipo tribut\00E1rio'),
'                select nd.id into l_id_despesa from ng_despesa nd where nd.ind_tipo_despesa = r.ind_tipo_despesa and nd.id_tenant = l_id_tenant;',
'',
'                bo_imp_processoimportacao_despesa.inclui_registro(',
'                    p_id_tenant                 => l_id_tenant,',
'                    p_id_documento_despesa      => null,',
'                    p_id_processoimportacao     => p_id,',
'                    p_id_numerario_despesa      => null, --?',
'                    p_id_despesa                => l_id_despesa,',
'                    p_id_moeda_prevista         => l_id_moeda_tenant,',
'                    p_valor_previsto            => r.valor_previsto,',
'                    p_id_moeda_realizada        => null,',
'                    p_valor_realizado           => 0,',
'                    p_taxa_cambio               => 0,',
'                    p_ind_status_despesa        => 1,',
'                    p_ind_status_pagamento      => 1,',
'                    p_id_moeda_documento        => l_id_moeda_nacional,',
'                    p_valor_moeda_documento     => 0,',
'                    p_valor_moeda_nacional      => 0,',
'                    p_ind_forma_rateio          => null,',
'                    p_ind_compoe_custo_operacao => null,',
'                    p_ind_participa_nfe         => null,',
'                    p_ind_despesa_base_calculo  => null,',
'                    p_ind_tipo_despesa          => null,',
'                    p_id                        => l_id,',
'                    p_pagina                    => p_pagina,',
'                    p_encadeado                 => true,',
'                    p_sucesso                   => p_sucesso,',
'                    p_messages                  => p_messages',
'                );',
'',
'            exception',
'                when no_data_found then',
'                    null;',
'            end;',
'        end loop;',
'    ****************************************************************************************************/',
'        ',
'        -- VERIFICA NECESSIDADE:',
'        bo_imp_processoimportacao.altera_ind_calculando_valores(',
'            p_ind_calculando_valores   => ''S'',',
'            p_data_hora_ultimo_calculo => sysdate,',
'            p_id                       => p_id,',
'            p_pagina                   => p_pagina,',
'            p_encadeado                => false,',
'            p_sucesso                  => p_sucesso,',
'            p_messages                 => p_messages',
'        );',
'        --',
'',
'    end concluir_processo_e_gerar_despesas;',
'    --',
'    procedure altera_data_di_real(',
'        p_id                    in imp_processoimportacao.id%type,',
'        p_data_registro_di_real in imp_processoimportacao.data_registro_di_real%type,',
'        p_pagina                in number default 0,',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_messages       := pkg_mensagem.message_record_table();',
'        v_parametro(0)   := ''bo_imp_processoimportacao.altera_data_di_real'';',
'        v_pagina         := p_pagina;',
'',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.data_registro_di_real  := p_data_registro_di_real;',
'        v_new.id_usuario_alterou     := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao         := sysdate;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_data_di_real;',
'    --',
'    procedure inclui_registro_ao_firmar_pedido(',
'        p_id_tenant                 in imp_processoimportacao.id_tenant%type,',
'        p_num_processoimportacao    in imp_processoimportacao.num_processoimportacao%type,',
'        p_ind_modalidade_importacao in imp_processoimportacao.ind_modalidade_importacao%type,',
'        p_id_embarcador             in imp_processoimportacao.id_embarcador%type,',
'        p_id_importador             in imp_processoimportacao.id_importador%type,',
'        p_id_adquirente             in imp_processoimportacao.id_adquirente%type,',
'        p_id_viatransporte          in imp_processoimportacao.id_viatransporte%type,',
'        p_id_endereco_origem        in imp_processoimportacao.id_endereco_origem%type,',
'        p_id_local_embarque         in imp_processoimportacao.id_local_embarque%type,',
'        p_id_local_desembarque      in imp_processoimportacao.id_local_desembarque%type,',
'        p_id_endereco_destino       in imp_processoimportacao.id_endereco_destino%type,',
'        p_id_entrega                in imp_entrega.id%type,',
'        p_id                        out imp_processoimportacao.id%type,',
'        p_pagina                    in number default 0,',
'        p_encadeado                 in boolean default false,',
'        p_sucesso                   out clob,',
'        p_messages                  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao.inclui_registro_ao_firmar_pedido'';',
'        v_pagina       := p_pagina;',
'        v_id_entrega   := p_id_entrega;',
'        --',
unistr('        -- Valores passados por par\00E2metros:'),
'        v_new.id_tenant                 := p_id_tenant;',
'        v_new.num_processoimportacao    := p_num_processoimportacao;',
'        v_new.ind_modalidade_importacao := p_ind_modalidade_importacao;',
'        v_new.id_embarcador             := p_id_embarcador;',
'        v_new.id_importador             := p_id_importador;',
'        v_new.id_adquirente             := p_id_adquirente;',
'        v_new.id_viatransporte          := p_id_viatransporte;',
'        v_new.id_endereco_origem        := p_id_endereco_origem;',
'        v_new.id_local_embarque         := p_id_local_embarque;',
'        v_new.id_local_desembarque      := p_id_local_desembarque;',
'        v_new.id_endereco_destino       := p_id_endereco_destino;',
'        --',
'        -- Valores fixos:',
'        v_new.ind_status        := 1;',
'        v_new.id_moeda_tenant   := bo_mpd_configuracao_ng.retorna_id_moeda_tenant(p_id_tenant);',
'        v_new.id_moeda_nacional := bo_mpd_configuracao_ng.retorna_id_moeda_nacional(p_id_tenant);',
'        --',
'        -- Valores default:',
'        v_new.ind_itens_vinculado_invoice := ''N'';',
'        v_new.ind_autorizacao_embarque    := ''N'';',
'        v_new.ind_calculando_valores      := ''N'';',
'        v_new.valor_total_mercadoria      := 0;',
'        v_new.valor_desconto              := 0;',
'        v_new.valor_total_condicao_venda  := 0;',
'        v_new.frete                       := 0;',
'        v_new.seguro                      := 0;',
'        v_new.acrescimo                   := 0;',
'        v_new.multa                       := 0;',
'        v_new.antidumping                 := 0;',
'        v_new.vmle                        := 0;',
'        v_new.vmld                        := 0;',
'        v_new.valor_ii                    := 0;',
'        v_new.valor_ipi                   := 0;',
'        v_new.valor_pis                   := 0;',
'        v_new.valor_cofins                := 0;',
'        v_new.valor_icms                  := 0;',
'        v_new.valor_icms_st               := 0;',
'        v_new.valor_cbs                   := 0;',
'        v_new.valor_ibs                   := 0;',
'        --',
'        -- Valores auditoria:',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_inclusao      := sysdate;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao     := sysdate;',
'        v_new.id                 := null;',
'        --',
'        v_operacao := ''INCLUI_REGISTRO_AO_FIRMAR_PEDIDO'';',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);',
'    end inclui_registro_ao_firmar_pedido;',
'    --',
'    procedure altera_totais_despesas_tributos(',
'        p_frete         in imp_processoimportacao.frete%type,',
'        p_seguro        in imp_processoimportacao.seguro%type,',
'        p_acrescimo     in imp_processoimportacao.acrescimo%type,',
'        p_multa         in imp_processoimportacao.multa%type,',
'        p_antidumping   in imp_process'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(155851324865645312)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'oimportacao.antidumping%type,',
'        p_vmle          in imp_processoimportacao.vmle%type,',
'        p_vmld          in imp_processoimportacao.vmld%type,',
'        p_valor_ii      in imp_processoimportacao.valor_ii%type,',
'        p_valor_ipi     in imp_processoimportacao.valor_ipi%type,',
'        p_valor_pis     in imp_processoimportacao.valor_pis%type,',
'        p_valor_cofins  in imp_processoimportacao.valor_cofins%type,',
'        p_valor_icms    in imp_processoimportacao.valor_icms%type,',
'        p_valor_icms_st in imp_processoimportacao.valor_icms_st%type,',
'        p_valor_cbs     in imp_processoimportacao.valor_cbs%type,',
'        p_valor_ibs     in imp_processoimportacao.valor_ibs%type,',
'        p_id            in imp_processoimportacao.id%type,',
'        p_pagina        in number default 0,',
'        p_encadeado     in boolean default false,',
'        p_sucesso       out clob,',
'        p_messages      out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
unistr('        -- Par\00E2metros t\00E9cnicos:'),
'        v_parametro(0) := ''bo_imp_processoimportacao.altera_totais_despesas_tributos'';',
'        v_pagina       := p_pagina;',
'        --',
'        -- Busca registro completo:',
'        select * into v_old from imp_processoimportacao where id = p_id;',
'        v_new := v_old;',
'        --',
unistr('        -- Atualiza valores vol\00E1teis:'),
'        v_new.valor_total_condicao_venda := calcula_valor_total_condicao_venda(p_id);',
'        v_new.valor_total_mercadoria     := calcula_valor_total_mercadoria(p_id);',
'        --',
unistr('        -- Atribui valores passados por par\00E2metros:'),
'        v_new.frete              := nvl(p_frete,0);',
'        v_new.seguro             := nvl(p_seguro,0);',
'        v_new.acrescimo          := nvl(p_acrescimo,0);',
'        v_new.multa              := nvl(p_multa,0);',
'        v_new.antidumping        := nvl(p_antidumping,0);',
'        v_new.vmle               := nvl(p_vmle,0);',
'        v_new.vmld               := nvl(p_vmld,0);',
'        v_new.valor_ii           := nvl(p_valor_ii,0);',
'        v_new.valor_ipi          := nvl(p_valor_ipi,0);',
'        v_new.valor_pis          := nvl(p_valor_pis,0);',
'        v_new.valor_cofins       := nvl(p_valor_cofins,0);',
'        v_new.valor_icms         := nvl(p_valor_icms,0);',
'        v_new.valor_icms_st      := nvl(p_valor_icms_st,0);',
'        v_new.valor_cbs          := nvl(p_valor_cbs,0);',
'        v_new.valor_ibs          := nvl(p_valor_ibs,0);',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao     := sysdate;',
'        --        ',
'        v_operacao := ''ALTERA_TOTAIS_DESPESAS_TRIBUTOS'';',
'        --v_operacao := ''RECALCULAR_TRIBUTOS'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_totais_despesas_tributos;',
'    --',
'    procedure gerencia_tributos(',
'        p_id            in imp_processoimportacao.id%type,',
'        p_pagina        in number default 0,',
'        p_encadeado     in boolean default false,',
'        p_sucesso       out clob,',
'        p_messages      out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant                          imp_processoimportacao.id_tenant%type;',
'        l_id_moeda_nacional                  imp_processoimportacao.id_moeda_nacional%type;',
'        l_ind_status                         imp_processoimportacao.ind_status%type;',
'        l_id_despesa                         ng_despesa.id%type;',
'        l_id_processoimportacao_item_despesa imp_processoimportacao_item_despesa.id%type;',
'        l_id_maestro                         number;',
'        l_id_usuario                         number := pkg_util.retorna_id_usuario_logado;',
'    begin',
unistr('        -- Busca informa\00E7\00F5es do processo:'),
'        select id_tenant, id_moeda_nacional, ind_status',
'        into l_id_tenant, l_id_moeda_nacional, l_ind_status',
'        from imp_processoimportacao',
'        where id = p_id;',
'        --',
unistr('        -- Se o processo est\00E1 em digita\00E7\00E3o n\00E3o deve recalcular tributos:'),
'        if l_ind_status = 10 then',
'            return;',
'        end if;',
'        --',
'        -- Deleta todos os tributos calculados por item:',
'        for tributo in (',
'            select a.id ',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa in (1,2,3,4,5,6,18,19)',
'        ) loop',
'            bo_imp_processoimportacao_item_despesa.exclui_registro(tributo.id, p_encadeado, p_sucesso, p_messages);',
'        end loop;',
'        --',
unistr('        -- Deve recalcular as bases e al\00EDquotas para garantir valores corretos:'),
'        recalcula_tributos(p_id, p_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'        -- Inclui os valores dos tributos corretamente:',
'        for tributo_recalculado in (',
'            -- Calcula valor para II:',
'            select ',
'                1 ind_tipo_despesa,',
'                b.id id_processoimportacao_item, ',
'                b.quantidade,',
'                ((a.aliquota_ii * a.base_calculo_ii) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id            ',
'            union all',
'            --',
'            -- Calcula valor para IPI:',
'            select ',
'                2 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_ipi * a.base_calculo_ipi) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            union all',
'            -- Calcula valor para PIS:',
'            select ',
'                3 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_pis * a.base_calculo_pis) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            union all',
'            --',
'            -- Calcula valor para COFINS:',
'            select ',
'                4 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_cofins * a.base_calculo_cofins) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            union all',
'            --',
'            -- Calcula valor para ICMS:',
'            select ',
'                5 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_icms * a.base_calculo_icms) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            union all',
'            --',
'            -- Calcula valor para ICMS-ST:',
'            select ',
'                6 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_icms * a.base_calculo_icms_st) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            union all',
'            --',
'            -- Calcula valor para CBS:',
'            select ',
'                18 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_cbs * a.base_calculo_cbs) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            union all',
'            --',
'            -- Calcula valor para IBS:',
'            select ',
'                19 ind_tipo_despesa, ',
'                b.id id_processoimportacao_item,',
'                b.quantidade,',
'                ((a.aliquota_ibs * a.base_calculo_ibs) / 100) valor_tributo',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            where b.id_processoimportacao = p_id',
'            --',
'        )',
'        loop',
'            -- Busca despesa correspondente ao tipo de tributo:',
'            select id into l_id_despesa from ng_despesa where ind_tipo_despesa = tributo_recalculado.ind_tipo_despesa and id_tenant = l_id_tenant;',
'            --',
unistr('            -- Chamada para inclus\00E3o utilizando m\00E9todo padr\00E3o:'),
'            bo_imp_processoimportacao_item_despesa.inclui_registro(',
'                p_id_tenant                             => l_id_tenant,',
'                p_id_processoimportacao_item            => tributo_recalculado.id_processoimportacao_item,',
'                p_id_processoimportacao_despesa         => null,',
'                p_id_despesa                            => l_id_despesa,',
'                p_id_moeda_despesa_prevista             => l_id_moeda_nacional,',
'                p_valor_total_despesa_previsto_item     => tributo_recalculado.valor_tributo,',
'                p_valor_unitario_despesa_previsto_item  => (tributo_recalculado.valor_tributo / tributo_recalculado.quantidade),',
'                p_id_moeda_despesa_realizada            => l_id_moeda_nacional,',
'                p_valor_total_despesa_realizado_item    => tributo_recalculado.valor_tributo,',
'                p_valor_unitario_despesa_realizado_item => (tributo_recalculado.valor_tributo / tributo_recalculado.quantidade),',
'                p_valor_total_despesa_moeda_nacional    => tributo_recalculado.valor_tributo,',
'                p_valor_unitario_despesa_moeda_nacional => (tributo_recalculado.valor_tributo / tributo_recalculado.quantidade),',
'                p_id                                    => l_id_processoimportacao_item_despesa,',
'                p_pagina                                => p_pagina,',
'                p_encadeado                             => p_encadeado,',
'                p_sucesso                               => p_sucesso,',
'                p_messages                              => p_messages',
'            );',
'            --',
'        end loop;',
'        --',
unistr('        -- Ap\00F3s o rec\00E1lculo por item, os totais ser\00E3o c\00E1lculos e atualizados pelo Maestro:'),
unistr('        -- Altera indicador de rec\00E1lculo do processo:'),
'        altera_ind_calculando_valores(''S'', null, p_id, p_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'        -- Chamada para o Maestro:',
'        l_id_maestro := pkg_maestro_api.postar_requisicao(',
'            p_codigo_artefato => ''PR11'',',
'            p_id_tenant       => l_id_tenant,',
'            p_id_usuario      => l_id_usuario,',
'            p_id_negocio      => p_id,',
'            p_payload         => ''{"id":"''||p_id||''"}'',',
'            p_prioridade      => 0,',
'            p_tipo_acao       => ''BO_IMP_PROCESSOIMPORTACAO.GERENCIA_TRIBUTOS'',',
'            p_id_correlation  => null',
'        );',
'        --',
'    end gerencia_tributos;',
'    --',
'    procedure gerencia_total_tributos(',
'        p_id            in imp_processoimportacao.id%type,',
'        p_pagina        in number default 0,',
'        p_encadeado     in boolean default false,',
'        p_sucesso       out clob,',
'        p_messages      out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant                     imp_processoimportacao.id_tenant%type;',
'        l_id_moeda_nacional             imp_processoimportacao.id_moeda_nacional%type;',
'        l_id_processoimportacao_despesa imp_processoimportacao_item_despesa.id%type;',
'    begin',
unistr('        -- Busca informa\00E7\00F5es do processo:'),
'        select id_tenant, id_moeda_nacional',
'        into l_id_tenant, l_id_moeda_nacional',
'        from imp_processoimportacao',
'        where id = p_id;',
'        --',
'        -- Deleta todos os totais de tributos calculados:',
'        for total_tributo in (',
'            select a.id ',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id_processoimportacao = p_id',
'            and b.ind_tipo_despesa in (1,2,3,4,5,6,18,19)',
'        ) loop',
unistr('            -- Chamada para procedure espec\00EDfica para evitar loop infinito:'),
'            bo_imp_processoimportacao_despesa.exclui_registro_por_recalculo(total_tributo.id, p_encadeado, p_sucesso, p_messages);',
'            --',
'        end loop;',
'        --',
'        -- Inclui os valores totais dos tributos corretamente:',
'        for total_tributo_recalculado in (',
'            -- Calcula valor total para II:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 1',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para IPI:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 2',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para PIS:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 3',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para COFINS:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 4',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para ICMS:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 5',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para ICMS-ST:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 6',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para CBS:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 18',
'            group by c.id',
'            union all',
'            --',
'            -- Calcula valor total para IBS:',
'            select ',
'                c.id id_despesa,',
'                nvl(sum(nvl(a.valor_total_despesa_previsto_item,0)),0) valor_previsto',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item ',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id_processoimportacao = p_id',
'            and c.ind_tipo_despesa = 19',
'            group by c.id',
'            --',
'        ) loop',
unistr('            -- Chamada para procedure espec\00EDfica para evitar loop infinito:'),
'            bo_imp_processoimportacao_despesa.inclui_registro_por_recalculo(',
'                p_id_tenant                 => l_id_tenant,',
'                p_id_documento_despesa      => null,',
'                p_id_processoimportacao     => p_id,',
'                p_id_numerario_despesa      => null,',
'                p_id_despesa                => total_tributo_recalculado.id_despesa,',
'                p_id_moeda_prevista         => l_id_moeda_nacional,',
'                p_valor_previsto            => total_tributo_recalculado.valor_previsto,',
'                p_id_moeda_realizada        => null,',
'                p_valor_realizado           => 0,',
'                p_taxa_cambio               => 1,',
'                p_ind_status_despesa        => 1,',
'                p_ind_status_pagamento      => 1,',
'                p_id_moeda_documento        => l_id_moeda_nacional,',
'                p_valor_moeda_documento     => 0,',
'                p_valor_moeda_nacional      => 0,',
'                p_ind_forma_rateio          => null,',
'                p_ind_compoe_custo_operacao => null,',
'                p_ind_participa_nfe         => null,',
'                p_ind_despesa_base_calculo  => null,',
'                p_ind_tipo_despesa          => null,',
'                p_id                        => l_id_processoimportacao_despesa,',
'                p_pagina                    => p_pagina,',
'                p_encadeado                 => p_encadeado,',
'                p_sucesso                   => p_sucesso,',
'                p_messages                  => p_messages',
'            );',
'            --',
'        end loop;',
'        --',
'        -- Atualiza os totais no processo:',
'        bo_imp_processoimportacao_despesa.altera_processoimportacao_totais_despesas_tributos(',
'            p_id_processoimportacao => p_id,',
'            p_pagina                => p_pagina,',
'            p_encadeado             => p_encadeado,',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'        --',
unistr('        -- Ap\00F3s atualiza\00E7\00E3o completa, altera indicador de rec\00E1lculo:'),
'        altera_ind_calculando_valores(''N'', sysdate, p_id, p_pagina, p_encadeado, p_sucesso, p_messages);',
'        --',
'    end gerencia_total_tributos;',
'    --',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_processoimportacao;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td808
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155851518469637313)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD808'
,p_sequence=>1000
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD808',
'-- Data: 29/04/2026',
unistr('-- Motivo: Ajuste para prefer\00EAncia de fuso hor\00E1rio'),
'-- Jira:',
'',
'-- Objeto: UI_MPD_TD808',
'-- Data: 27/04/2026',
unistr('-- Motivo: Adi\00E7\00E3o de duas novas colunas'),
'-- Jira:',
'',
'-- Objeto: UI_MPD_TD808',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste de coluna id_recinto_alfandegado',
'-- Jira: PEDITEM-161',
'',
'create or replace package "UI_MPD_TD808" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_num_processoimportacao(p_param1 in varchar2) return clob;',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD808";',
'/',
'',
'create or replace package body "UI_MPD_TD808" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_somente_leitura_id_tenant                     varchar2(1);',
'        l_somente_leitura_num_processoimportacao        varchar2(1);',
'        l_atribuir_num_processoimportacao               clob;',
'        l_campos_num_processoimportacao                 apex_t_varchar2 := apex_t_varchar2(''NUM_PROCESSOIMPORTACAO'',''SOMENTE_LEITURA_NUM_PROCESSOIMPORTACAO'');',
'        v_json_dependencia_num_processoimportacao       clob;',
'        ',
'        v_condicoes_num_processoimportacao              array_varchar := array_varchar(''SOMENTE_LEITURA_NUM_PROCESSOIMPORTACAO == %N%'',''SOMENTE_LEITURA_NUM_PROCESSOIMPORTACAO == %S%'');',
'        v_colunas_alvo_num_processoimportacao           array_varchar := array_varchar(''NUM_PROCESSOIMPORTACAO'',''NUM_PROCESSOIMPORTACAO'');',
'        v_comportamentos_id_num_processoimportacao      array_varchar := array_varchar(''hab'',''hab'');        ',
'    ',
'        l_id_entrega number;',
'    begin',
'        -- identificar se veio de entrega',
'        if apex_util.get_session_state(''P9012_ID'') is null then',
'            apex_util.set_session_state(''P9012_PARAMETRO2'', p_param1);',
'            apex_util.set_session_state(''P9012_PARAMETRO'', null);',
'        end if;',
'',
'        l_id_entrega := apex_util.get_session_state(''P9012_PARAMETRO2'');',
'',
'        l_atribuir_num_processoimportacao := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_num_processoimportacao'', l_campos_num_processoimportacao);',
'',
'        v_json_dependencia_num_processoimportacao := gerar_json_dependencias_array(v_condicoes_num_processoimportacao, v_colunas_alvo_num_processoimportacao, v_comportamentos_id_num_processoimportacao);',
'        ',
'        if apex_util.get_session_state(''P9012_ID'') is not null then',
'            l_somente_leitura_id_tenant := ''S'';',
'            l_somente_leitura_num_processoimportacao := ''S'';',
'        else',
'            l_somente_leitura_id_tenant := ''N'';',
'            l_somente_leitura_num_processoimportacao := ''N'';',
'        end if;',
'',
'        --v_json_dependencia_viatransporte := gerar_json_dependencias_array(v_condicao_viatransporte, v_campos_viatransporte, v_acao_viatransporte);     ',
'        --prc_enviar_parametros(''TD808'',''id_viatransporte'',p_param1);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, l_somente_leitura_id_tenant AS somente_leitura, ''S'' as coluna_tabela, to_char((case when l_id_entrega is'
||' not null then (select id_tenant from imp_entrega where id = l_id_entrega) else null end)) valor, l_atribuir_num_processoimportacao atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''NUM_PROCESSOIMPORTACAO'',              2, '''', null, l_somente_leitura_num_processoimportacao,''S'', null valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_responsavel'',              3, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',           5, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select ind_modalidade_importacao from imp_entrega where id = l_id_entrega)end)) valor, null atrib'
||'uir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_embarcador'',                       6, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select id_exportador from imp_entrega where id = l_id_entrega) end)) valor, null atribuir_valor, '
||'null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                       8, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select id_importador from imp_entrega where id = l_id_entrega) end)) valor, null atribuir_valor, '
||'null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                      10, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select id_adquirente from imp_entrega where id = l_id_entrega) end)) valor, null atribuir_valor, '
||'null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despachante'',                     12, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_viatransporte'',                   14, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select id_viatransporte from imp_entrega where id = l_id_entrega) end)) valor, null atribuir_valo'
||'r, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               -- SELECT p_codigo_artefato, ''id_viatransporte'',                   14, ''SEL'', ''R_IMP_PROCESSOIMPORTACAO.ID_VIATRANSPORTE'', ''N'', ''S'', to_char((select a.descricao_viatransporte from ng_viatransporte a join imp_processoimportacao b on b.i'
||'d_viatransporte = a.id where b.id = apex_util.get_session_state(''P9012_ID''))) valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''NAVIO'',                              16, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_transportador_internacional'',     17, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_embarque'',                  19, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select id_local_embarque from imp_entrega where id = l_id_entrega) end)) valor, null atribuir_val'
||'or, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_desembarque'',               21, '''', null, ''N'', ''S'', to_char((case when l_id_entrega is not null then (select id_local_desembarque from imp_entrega where id = l_id_entrega) end)) valor, null atribuir_'
||'valor, null dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
