'               SELECT p_codigo_artefato, ''SOMENTE_LEITURA_NUM_PROCESSOIMPORTACAO'', 26, ''HID'', null, ''S'', ''N'', ''S'' valor, null atribuir_valor, v_json_dependencia_num_processoimportacao dependencia, null id_artefato_versionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                     25, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia, null id_artefato_versionado_zoom from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,atribuir_valor,dependencia, id_artefato_versionado_zoom)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor,new_data.atribuir_valor,new_data.dependencia,new_dat'
||'a.id_artefato_versionado_zoom);    ',
'    end formulario;',
'',
'    function sql_atribuir_num_processoimportacao(p_param1 in varchar2) return clob is',
'        l_verifica_configuracao number;',
'        l_sql clob;',
'        l_id_tenant number;',
'        l_collection_name varchar2(200);',
'    begin',
'        if apex_util.get_session_state(''P9012_ID'') is null then',
'            l_collection_name := ''TD808_'' || apex_custom_auth.get_session_id;',
'            select c002 into l_id_tenant from apex_collections where collection_name = l_collection_name and c001 = ''id_tenant'';',
'',
'            select count(1) into l_verifica_configuracao',
'            from mpd_configuracao_ng a join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id ',
'            where a.id_tenant = l_id_tenant',
'            and a.codigo_configuracao = 7',
'            and b.id = a.valor_dominio',
'            and b.codigo_dominio = 2;',
'',
'            if l_verifica_configuracao > 0 then',
'                l_sql := q''~',
'                    select                        ',
'                        '' '' NUM_PROCESSOIMPORTACAO,',
'                        ''N'' SOMENTE_LEITURA_NUM_PROCESSOIMPORTACAO',
'                    from dual            ',
'                ~'';',
'            else',
'                l_sql := q''~',
'                    select ',
'                        '' '' NUM_PROCESSOIMPORTACAO,',
'                        ''S'' SOMENTE_LEITURA_NUM_PROCESSOIMPORTACAO',
'                    from dual            ',
'                ~'';',
'            end if;        ',
'        end if;',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_endereco_destino'') then',
'            return q''~',
'                where (b.data_fim_vigencia is null',
'                    or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                )',
'                and (',
'                    (select c003',
'                     from apex_collections',
'                     where collection_name = ''TD808_'' || apex_custom_auth.get_session_id',
'                       and upper(c001) = upper(''f09_0000'')',
'                    ) is null',
'                    or c.id_pessoa in (',
'                        select c003',
'                        from apex_collections',
'                        where collection_name = ''TD808_'' || apex_custom_auth.get_session_id',
'                          and upper(c001) = upper(''f09_0000'')',
'                    )',
'                )',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_numero_processo_importacao    varchar2(4000);',
'        l_id_entrega number;',
'    begin',
'        l_id_entrega := apex_util.get_session_state(''P9012_PARAMETRO2'');',
'',
'        l_numero_processo_importacao := bo_imp_processoimportacao.retorna_numero_processoimportacao(apex_application.g_f01(1));',
