prompt --application/deployment/install/install_ui_mpd_td886
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155852314558622306)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD886'
,p_sequence=>1040
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD886',
'-- Data: 29/04/2026',
unistr('-- Motivo: Ajuste para prefer\00EAncia de fuso hor\00E1rio'),
'-- Jira:',
'',
'-- Objeto: UI_MPD_TD886',
'-- Data: 27/04/2026',
unistr('-- Motivo: Adi\00E7\00E3o de duas novas colunas'),
'-- Jira:',
'',
'-- Objeto: UI_MPD_TD886',
'-- Data: 30/04/2026',
'-- Motivo: Ajuste novas regras de datas',
'-- Jira: PEDITEM-70',
'',
'-- Objeto: UI_MPD_TD886',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste de coluna id_recinto_alfandegado',
'-- Jira: PEDITEM-161',
'',
'create or replace package "UI_MPD_TD886" as',
'',
'    -- Tipos de colunas de data',
'    c_data_disponivel      constant pls_integer := 1;',
'    c_data_embarque        constant pls_integer := 2;',
'    c_data_desembarque     constant pls_integer := 3;',
'    c_data_nacionalizacao  constant pls_integer := 4;',
'    c_data_recebimento     constant pls_integer := 5;',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    function busca_data_entrega (p_id_processoimportacao number, p_tipo pls_integer) return date;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD886";',
'/',
'',
'create or replace package body "UI_MPD_TD886" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'        l_status varchar2(50);',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql =>',
'                ''select',
'                    a.num_processoimportacao,',
'                    b.nome_fantasia as id_embarcador',
'                from imp_processoimportacao a',
'                join ng_pessoa_juridica b on b.id_pessoa = a.id_embarcador',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.81.l'');',
'        return l_html;',
'    end;',
'',
'    -- Busca data da entrega',
'    function busca_data_entrega (',
'        p_id_processoimportacao number,',
'        p_tipo                  pls_integer',
'    ) return date',
'    is',
'        l_data  date;',
'        l_count number;',
'    begin',
'        case p_tipo',
'            when c_data_disponivel then',
'                select count(*), case when max(data_disponivel_real) is not null then max(data_disponivel_real) when max(data_disponivel_informada) is not null then max(data_disponivel_informada) else max(data_disponivel_calculada) end               '
||' ',
'                into l_count, l_data',
'                from imp_entrega',
'                where id_processoimportacao = p_id_processoimportacao;',
'            when c_data_embarque then',
'                select count(*), case when max(data_embarque_real) is not null then max(data_embarque_real) when max(data_embarque_informada) is not null then max(data_embarque_informada) else max(data_embarque_calculada) end',
'                into l_count, l_data',
'                from imp_entrega',
'                where id_processoimportacao = p_id_processoimportacao;',
'            when c_data_desembarque then',
'                select count(*), case when max(data_desembarque_real) is not null then max(data_desembarque_real) when max(data_desembarque_informada) is not null then max(data_desembarque_informada) else max(data_desembarque_calculada) end',
'                into l_count, l_data',
'                from imp_entrega',
'                where id_processoimportacao = p_id_processoimportacao;',
'            when c_data_nacionalizacao then',
'                select count(*), case when max(data_nacionalizacao_real) is not null then max(data_nacionalizacao_real) when max(data_nacionalizacao_informada) is not null then max(data_nacionalizacao_informada) else max(data_nacionalizacao_calculada'
||') end',
'                into l_count, l_data',
'                from imp_entrega',
'                where id_processoimportacao = p_id_processoimportacao;',
'            when c_data_recebimento then',
'                select count(*), case when max(data_recebimento_real) is not null then max(data_recebimento_real) when max(data_recebimento_informada) is not null then max(data_recebimento_informada) else max(data_recebimento_calculada) end',
'                into l_count, l_data',
'                from imp_entrega',
'                where id_processoimportacao = p_id_processoimportacao;',
'            else',
unistr('                raise_application_error(-20001, ''Tipo inv\00E1lido'');'),
'        end case;',
'',
'        if l_count != 1 then',
'            return null;',
'        end if;',
'        return l_data;',
'    end busca_data_entrega;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null',
'    ) is',
'        l_ind_autorizacao_embarque  varchar2(2);',
'',
'        -- DATAS:',
'        v_data_disponivel_real        imp_processoimportacao.data_disponivel_real%type;',
'        v_data_disponivel_informada   imp_processoimportacao.data_disponivel_informada%type;',
'        v_data_disponivel_calculada   imp_processoimportacao.data_disponivel_calculada%type;',
'',
'        v_data_embarque_real          imp_processoimportacao.data_embarque_real%type;',
'        v_data_embarque_informada     imp_processoimportacao.data_embarque_informada%type;',
'        v_data_embarque_calculada     imp_processoimportacao.data_embarque_calculada%type;',
'',
'        v_data_desembarque_real       imp_processoimportacao.data_desembarque_real%type;',
'        v_data_desembarque_informada  imp_processoimportacao.data_desembarque_informada%type;',
'        v_data_desembarque_calculada  imp_processoimportacao.data_desembarque_calculada%type;',
'',
'        v_data_nacionalizacao_real       imp_processoimportacao.data_nacionalizacao_real%type;',
'        v_data_nacionalizacao_informada  imp_processoimportacao.data_nacionalizacao_informada%type;',
'        v_data_nacionalizacao_calculada  imp_processoimportacao.data_nacionalizacao_calculada%type;',
'',
'        v_data_recebimento_real       imp_processoimportacao.data_recebimento_real%type;',
'        v_data_recebimento_informada  imp_processoimportacao.data_recebimento_informada%type;',
'        v_data_recebimento_calculada  imp_processoimportacao.data_recebimento_calculada%type;',
'',
'        -- HID:',
'        v_hid_disponivel_real         varchar2(10);',
'        v_hid_disponivel_informada    varchar2(10);',
'        v_hid_disponivel_calculada    varchar2(10);',
'',
'        v_hid_embarque_real           varchar2(10);',
'        v_hid_embarque_informada      varchar2(10);',
'        v_hid_embarque_calculada      varchar2(10);',
'',
'        v_hid_desembarque_real        varchar2(10);',
'        v_hid_desembarque_informada   varchar2(10);',
'        v_hid_desembarque_calculada   varchar2(10);',
'',
'        v_hid_nacionalizacao_real        varchar2(10);',
'        v_hid_nacionalizacao_informada   varchar2(10);',
'        v_hid_nacionalizacao_calculada   varchar2(10);',
'',
'        v_hid_recebimento_real        varchar2(10);',
'        v_hid_recebimento_informada   varchar2(10);',
'        v_hid_recebimento_calculada   varchar2(10);',
'',
'        procedure set_hid_2(',
'            p_real      in date,',
'            p_informada in date,',
'            p_calculada in date,',
'            p_hid_real       out varchar2,',
'            p_hid_informada  out varchar2,',
'            p_hid_calculada  out varchar2',
'        ) is',
'        begin',
'            p_hid_real      := ''HID'';',
'            p_hid_informada := ''HID'';',
'            p_hid_calculada := ''HID'';',
'',
'            if p_real is not null then',
'                p_hid_real := '''';',
'            elsif p_informada is not null then',
'                p_hid_informada := '''';',
'            elsif p_calculada is not null then',
'                p_hid_calculada := '''';',
'                p_hid_informada := '''';',
'            else',
'                p_hid_informada := '''';',
'            end if;',
'        end set_hid_2;',
'',
'    begin',
'        select NVL(ind_autorizacao_embarque, ''N'') into l_ind_autorizacao_embarque from imp_processoimportacao where id = p_param1;',
'',
'        -- DADOS DO BANCO',
'        SELECT',
'            data_disponivel_real, data_disponivel_informada,',
'            data_embarque_real, data_embarque_informada,',
'            data_desembarque_real, data_desembarque_informada,',
'            data_nacionalizacao_real, data_nacionalizacao_informada,',
'            data_recebimento_real, data_recebimento_informada',
'        INTO',
'            v_data_disponivel_real, v_data_disponivel_informada,',
'            v_data_embarque_real, v_data_embarque_informada,',
'            v_data_desembarque_real, v_data_desembarque_informada,',
'            v_data_nacionalizacao_real, v_data_nacionalizacao_informada,',
'            v_data_recebimento_real, v_data_recebimento_informada',
'        FROM imp_processoimportacao',
'        WHERE id = p_param1;',
'',
'        -- CALCULADAS VINDO DO SISTEMA:',
'        v_data_disponivel_calculada         := busca_data_entrega(p_param1, c_data_disponivel);',
'        v_data_embarque_calculada           := busca_data_entrega(p_param1, c_data_embarque);',
'        v_data_desembarque_calculada        := busca_data_entrega(p_param1, c_data_desembarque);',
'        v_data_nacionalizacao_calculada     := busca_data_entrega(p_param1, c_data_nacionalizacao);',
'        v_data_recebimento_calculada        := busca_data_entrega(p_param1, c_data_recebimento);',
'',
'        -- HID',
'        set_hid_2(v_data_disponivel_real, v_data_disponivel_informada, v_data_disponivel_calculada,',
'                  v_hid_disponivel_real, v_hid_disponivel_informada, v_hid_disponivel_calculada);',
'',
'        set_hid_2(v_data_embarque_real, v_data_embarque_informada, v_data_embarque_calculada,',
'                  v_hid_embarque_real, v_hid_embarque_informada, v_hid_embarque_calculada);',
'',
'        set_hid_2(v_data_desembarque_real, v_data_desembarque_informada, v_data_desembarque_calculada,',
'                  v_hid_desembarque_real, v_hid_desembarque_informada, v_hid_desembarque_calculada);',
'',
'        set_hid_2(v_data_nacionalizacao_real, v_data_nacionalizacao_informada, v_data_nacionalizacao_calculada,',
'                  v_hid_nacionalizacao_real, v_hid_nacionalizacao_informada, v_hid_nacionalizacao_calculada);',
'',
'        set_hid_2(v_data_recebimento_real, v_data_recebimento_informada, v_data_recebimento_calculada,',
'                  v_hid_recebimento_real, v_hid_recebimento_informada, v_hid_recebimento_calculada);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, NULL AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, TO_CHAR((SELECT id_tenant FROM imp_processoimportacao W'
||'HERE id = p_param1)) AS valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id'',                                        45, ''HID'',NULL, ''N'',''S'', p_param1 FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''num_processoimportacao'',                     2, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT num_processoimportacao FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_usuario_responsavel'',                     3, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_usuario_responsavel FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''ind_modalidade_importacao'',                  5, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT ind_modalidade_importacao FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_embarcador'',                              6, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_embarcador FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_importador'',                              8, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_importador FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_adquirente'',                             10, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_adquirente FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_despachante'',                            12, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_despachante FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_viatransporte'',                          14, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_viatransporte FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_transportador_internacional'',            16, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_transportador_internacional FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_local_embarque'',                         18, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_local_embarque FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_local_desembarque'',                      20, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_local_desembarque FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_endereco_destino'',                       22, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT id_endereco_destino FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_alteracao'',                            24, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT data_alteracao FROM imp_processoimportacao WHERE id = p_param1), ''DD-MON-RR HH:MI:SS.FF AM'') FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''ind_status'',                                25, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT ind_status FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''ind_itens_vinculado_invoice'',               26, ''HID'', null, ''N'',''S'', TO_CHAR((SELECT ind_itens_vinculado_invoice FROM imp_processoimportacao WHERE id = p_param1)) FROM dual UNION ALL',
'',
'            -- DATAS AJUSTADAS DE ACORDO COM REGRA',
'            SELECT p_codigo_artefato, ''data_disponivel_real'',                      27, v_hid_disponivel_real,    NULL, ''S'', ''S'', TO_CHAR(v_data_disponivel_real) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_disponivel_informada'',                 28, v_hid_disponivel_informada, NULL, ''N'', ''S'', TO_CHAR(v_data_disponivel_informada) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_disponivel_calculada'',                 29, v_hid_disponivel_calculada, NULL, ''S'', ''S'', TO_CHAR(v_data_disponivel_calculada) FROM dual UNION ALL',
'',
'            SELECT p_codigo_artefato, ''data_embarque_real'',                        30, v_hid_embarque_real, NULL, ''S'', ''S'', TO_CHAR(v_data_embarque_real) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_embarque_informada'',                   31, v_hid_embarque_informada, NULL, ''N'', ''S'', TO_CHAR(v_data_embarque_informada) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_embarque_calculada'',                   32, v_hid_embarque_calculada, NULL, ''S'', ''S'', TO_CHAR(v_data_embarque_calculada) FROM dual UNION ALL',
'',
'            SELECT p_codigo_artefato, ''ind_autorizacao_embarque'',                  33, '''', NULL, ''N'', ''S'', TO_CHAR(l_ind_autorizacao_embarque) FROM dual UNION ALL',
'',
'            SELECT p_codigo_artefato, ''data_desembarque_real'',                     34, v_hid_desembarque_real, NULL, ''S'', ''S'', TO_CHAR(v_data_desembarque_real) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_desembarque_informada'',                35, v_hid_desembarque_informada,NULL, ''N'',''S'', TO_CHAR(v_data_desembarque_informada) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_desembarque_calculada'',                36, v_hid_desembarque_calculada,NULL, ''S'',''S'', TO_CHAR(v_data_desembarque_calculada) FROM dual UNION ALL',
'',
'            SELECT p_codigo_artefato, ''data_nacionalizacao_real'',                  37, v_hid_nacionalizacao_real, NULL, ''S'', ''S'', TO_CHAR(v_data_nacionalizacao_real) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_nacionalizacao_informada'',             38, v_hid_nacionalizacao_informada, NULL, ''N'',''S'', TO_CHAR(v_data_nacionalizacao_informada) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_nacionalizacao_calculada'',             39, v_hid_nacionalizacao_calculada, NULL, ''S'',''S'', TO_CHAR(v_data_nacionalizacao_calculada) FROM dual UNION ALL',
'',
'            SELECT p_codigo_artefato, ''data_recebimento_real'',                     40, v_hid_recebimento_real, NULL, ''S'', ''S'', TO_CHAR(v_data_recebimento_real) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_recebimento_informada'',                41, v_hid_recebimento_informada,NULL, ''N'',''S'', TO_CHAR(v_data_recebimento_informada) FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_recebimento_calculada'',                42, v_hid_recebimento_calculada,NULL, ''S'',''S'', TO_CHAR(v_data_recebimento_calculada) FROM dual',
'        ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        v_old               imp_processoimportacao%rowtype;',
'        v_data_disp_inf     VARCHAR2(32767);',
'        v_data_emb_inf      VARCHAR2(32767);',
'        v_data_des_inf      VARCHAR2(32767);',
'        v_data_nac_inf      VARCHAR2(32767);',
'        v_data_rec_inf      VARCHAR2(32767);',
'',
'        function ajusta_data_post(',
'            p_array_inf     apex_application_global.vc_arr2,',
'            p_array_calc    apex_application_global.vc_arr2,',
'            p_calc_bd       date',
'        ) return date',
'        is',
'            l_data_inf  date;',
'            l_data_calc date;',
'        begin',
unistr('            -- USU\00C1RIO ALTEROU CAMPO'),
'            if p_array_inf.count > 0 then',
'                if p_array_inf(1) is not null then',
'                    return to_date(p_array_inf(1), ''DD/MM/YYYY'');',
'                else',
'                    return null;',
'                end if;',
'            end if;',
unistr('            -- usu\00E1rio mexeu na calculada \2192 vira informada'),
'            if p_array_calc.count > 0 and p_array_calc(1) is not null then',
'                l_data_calc := to_date(p_array_calc(1), ''DD/MM/YYYY'');',
'',
'                if p_calc_bd is null or l_data_calc != p_calc_bd then',
'                    return l_data_calc;',
'                end if;',
'            end if;',
unistr('            -- usu\00E1rio n\00E3o mexeu \2192 mant\00E9m o que j\00E1 estava'),
'            return p_calc_bd;',
'        end ajusta_data_post;',
'    begin',
'        select * into v_old from imp_processoimportacao where id = apex_application.g_f45(1);',
'',
'        -- REGRAS PARA DATAS',
'        v_data_disp_inf := ajusta_data_post(apex_application.g_f28, apex_application.g_f29, v_old.data_disponivel_calculada);',
'        v_data_emb_inf := ajusta_data_post(apex_application.g_f31, apex_application.g_f32, v_old.data_embarque_calculada);',
'        v_data_des_inf := ajusta_data_post(apex_application.g_f35, apex_application.g_f36, v_old.data_desembarque_calculada);',
'        v_data_nac_inf := ajusta_data_post(apex_application.g_f38, apex_application.g_f39, v_old.data_nacionalizacao_calculada);',
'        v_data_rec_inf := ajusta_data_post(apex_application.g_f41, apex_application.g_f42, v_old.data_recebimento_calculada);',
'',
'        -- Update:',
'        bo_imp_processoimportacao.altera_registro(',
'            p_id_tenant                         => apex_application.g_f01(1),',
'            p_num_processoimportacao            => apex_application.g_f02(1),',
'            p_id_usuario_responsavel            => apex_application.g_f03(1),',
'            p_ind_modalidade_importacao         => apex_application.g_f05(1),',
'            p_id_embarcador                     => apex_application.g_f06(1),',
'            p_id_importador                     => apex_application.g_f08(1),',
'            p_id_adquirente                     => apex_application.g_f10(1),',
'            p_id_despachante                    => apex_application.g_f12(1),',
'            p_id_viatransporte                  => apex_application.g_f14(1),',
'            p_id_transportador_internacional    => apex_application.g_f16(1),',
'            p_id_local_embarque                 => apex_application.g_f18(1),',
'            p_id_local_desembarque              => apex_application.g_f20(1),',
'            p_id_endereco_destino               => apex_application.g_f22(1),',
'            p_data_alteracao                    => to_timestamp(apex_application.g_f24(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id_moeda_tenant                   => v_old.id_moeda_tenant,',
'            p_id_moeda_nacional                 => v_old.id_moeda_nacional,',
'            p_ind_status                        => apex_application.g_f25(1),',
'            p_ind_itens_vinculado_invoice       => apex_application.g_f26(1),',
'            -- Campos nulos nessa etapa:',
'            p_data_embarque_autorizado          => v_old.data_embarque_autorizado,',
'            p_referencia_despachante            => v_old.referencia_despachante,',
'            p_id_usuario_autorizou_embarque     => v_old.id_usuario_autorizou_embarque,',
'            p_data_registro_di_calculada        => v_old.data_registro_di_calculada,',
'            p_data_registro_di_informada        => v_old.data_registro_di_informada,',
'            p_data_registro_di_real             => v_old.data_registro_di_real,',
'            p_conhecimento_transporte           => v_old.conhecimento_transporte,',
'            p_navio                             => v_old.navio,',
'            p_id_endereco_origem                => v_old.id_endereco_origem,',
'            p_id_recinto_alfandegado            => v_old.id_recinto_alfandegado,',
'            p_id_transportador_nacional         => v_old.id_transportador_nacional,',
'            p_viagem                            => v_old.viagem,',
'            p_valor_total_mercadoria            => v_old.valor_total_mercadoria,',
'            p_valor_desconto                    => v_old.valor_desconto,',
'            p_valor_total_condicao_venda        => v_old.valor_total_condicao_venda,',
'            p_vmle                              => v_old.vmle,',
'            p_vmld                              => v_old.vmld,',
'            p_frete                             => v_old.frete,',
'            p_seguro                            => v_old.seguro,',
'            p_acrescimo                         => v_old.acrescimo,',
'            p_multa                             => v_old.multa,',
'            p_valor_ii                          => v_old.valor_ii,',
'            p_valor_ipi                         => v_old.valor_ipi,',
'            p_valor_pis                         => v_old.valor_pis,',
'            p_valor_cofins                      => v_old.valor_cofins,',
'            p_valor_icms                        => v_old.valor_icms,',
'            p_valor_icms_st                     => v_old.valor_icms_st,',
'            p_antidumping                       => v_old.antidumping,',
'            p_valor_cbs                         => v_old.valor_cbs,',
'            p_valor_ibs                         => v_old.valor_ibs,',
'',
'            -- Regras de datas:',
'            p_data_disponivel_real              => v_old.data_disponivel_real,',
'            p_data_disponivel_informada =>      case when apex_application.g_f28.count > 0 then v_data_disp_inf else v_old.data_disponivel_informada end,',
'            p_data_disponivel_calculada         => v_old.data_disponivel_calculada,',
'',
'            p_data_embarque_real                => v_old.data_embarque_real,',
'            p_data_embarque_informada =>        case when apex_application.g_f31.count > 0 then v_data_emb_inf else v_old.data_embarque_informada end,',
'            p_data_embarque_calculada           => v_old.data_embarque_calculada,',
'',
'            p_data_desembarque_real             => v_old.data_desembarque_real,',
'            p_data_desembarque_informada =>     case when apex_application.g_f35.count > 0 then v_data_des_inf else v_old.data_desembarque_informada end,',
'            p_data_desembarque_calculada        => v_old.data_desembarque_calculada,',
'',
'            p_data_nacionalizacao_real          => v_old.data_nacionalizacao_real,',
'            p_data_nacionalizacao_informada =>  case when apex_application.g_f38.count > 0 then v_data_nac_inf else v_old.data_nacionalizacao_informada end,',
'            p_data_nacionalizacao_calculada     => v_old.data_nacionalizacao_calculada,',
'',
'            p_data_recebimento_real             => v_old.data_recebimento_real,',
'            p_data_recebimento_informada =>     case when apex_application.g_f41.count > 0 then v_data_rec_inf else v_old.data_recebimento_informada end,',
'            p_data_recebimento_calculada        => v_old.data_recebimento_calculada,',
'',
'            p_ind_autorizacao_embarque          => NVL(apex_application.g_f33(1), ''N''),',
'            p_data_finalizado                   => null,',
'            p_ind_calculando_valores            => v_old.ind_calculando_valores,',
'            p_data_hora_ultimo_calculo          => v_old.data_hora_ultimo_calculo,',
'            p_id                                => apex_util.get_session_state(''P9012_PARAMETRO''), ',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD886";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td903
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(155852548139613797)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD903'
,p_sequence=>1050
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD903',
'-- Data: 27/04/2026',
unistr('-- Motivo: Adi\00E7\00E3o de duas novas colunas'),
'-- Jira:',
'',
'-- Objeto: UI_MPD_TD903',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste de coluna id_recinto_alfandegado',
'-- Jira: PEDITEM-161',
'',
'create or replace package "UI_MPD_TD903" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD903";',
'/',
'',
'create or replace package body "UI_MPD_TD903" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''',''''ind_status'''',a.ind_status) ind_status',
'                from imp_processoimportacao a',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.103.l'')||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'',
'    begin ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao,null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null dependencia, null atribuir_valor, null '
||'executa_js from dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''data_desembarque_real'',               4, ''HID'', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_recinto_alfandegado'',              6, ''HID'', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL           ',
'               SELECT p_codigo_artefato, ''data_alteracao'',                     18, '''', null, ''N'', ''S'', null, null , null , null  from dual  ',
'',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'',
'',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'',
'    )',
'    is',
'        l_id number;',
'        v_imp_processo imp_processoimportacao%rowtype;',
'        v_id_declaracao number;',
'    begin ',
'        select * into v_imp_processo from imp_processoimportacao where id = p_id;  ',
'        select id into v_id_declaracao from IMP_DECLARACAOIMPORTACAO where id_processoimportacao = p_id;',
'        bo_imp_processoimportacao.altera_registro(',
'                p_valor_cofins                 => v_imp_processo.valor_cofins,',
'                p_valor_icms                   => v_imp_processo.valor_icms,',
'                p_valor_icms_st                => v_imp_processo.valor_icms_st,',
'                p_antidumping                  => v_imp_processo.antidumping,',
'                p_viagem                       => v_imp_processo.viagem,',
'                p_id_moeda_tenant              => v_imp_processo.id_moeda_tenant,',
'                p_valor_total_mercadoria       => v_imp_processo.valor_total_mercadoria,',
'                p_valor_desconto               => v_imp_processo.valor_desconto,',
'                p_valor_total_condicao_venda   => v_imp_processo.valor_total_condicao_venda,',
'                p_vmle                         => v_imp_processo.vmle,',
'                p_frete                        => v_imp_processo.frete,',
'                p_seguro                       => v_imp_processo.seguro,',
'                p_acrescimo                    => v_imp_processo.acrescimo,',
'                p_vmld                         => v_imp_processo.vmld,',
'                p_multa                        => v_imp_processo.multa,',
'                p_valor_ii                     => v_imp_processo.valor_ii,',
'                p_valor_ipi                    => v_imp_processo.valor_ipi,',
