'            p_data_nacionalizacao_calculada   => v_imp_processo.data_nacionalizacao_calculada,',
'            p_data_nacionalizacao_informada   => v_imp_processo.data_nacionalizacao_informada,',
'            p_data_nacionalizacao_real        => v_imp_processo.data_nacionalizacao_real,',
'            p_data_recebimento_informada      => v_imp_processo.data_recebimento_informada,',
'            p_data_recebimento_calculada      => v_imp_processo.data_recebimento_calculada,',
'            p_data_recebimento_real           => v_imp_processo.data_recebimento_calculada,',
'            p_conhecimento_transporte         => v_imp_processo.data_recebimento_real,',
'            p_navio                           => v_imp_processo.navio,',
'            p_ind_itens_vinculado_invoice     => v_imp_processo.ind_itens_vinculado_invoice,',
'            p_num_processoimportacao          => v_imp_processo.num_processoimportacao,',
'            p_ind_status                      => 7,',
'            p_ind_modalidade_importacao       => v_imp_processo.ind_modalidade_importacao,',
'            p_id_embarcador                   => v_imp_processo.id_embarcador,',
'            p_id_importador                   => v_imp_processo.id_importador,',
'            p_id_adquirente                   => v_imp_processo.id_adquirente,',
'            p_id_despachante                  => v_imp_processo.id_despachante,',
'            p_referencia_despachante          => v_imp_processo.referencia_despachante,',
'            p_id_usuario_responsavel          => v_imp_processo.id_usuario_responsavel,',
'            p_id_endereco_origem              => v_imp_processo.id_endereco_origem,',
'            p_id_local_embarque               => v_imp_processo.id_local_embarque,',
'            p_id_local_desembarque            => v_imp_processo.id_local_desembarque,',
'            p_id_recinto_alfandegado          => v_imp_processo.id_recinto_alfandegado,',
'            p_id_endereco_destino             => v_imp_processo.id_endereco_destino,',
'            p_id_viatransporte                => v_imp_processo.id_viatransporte,',
'            p_id_transportador_internacional  => v_imp_processo.id_transportador_internacional,',
'            p_id_transportador_nacional       => v_imp_processo.id_transportador_nacional,',
'            p_ind_autorizacao_embarque        => v_imp_processo.ind_autorizacao_embarque,',
'            p_data_alteracao                  => TO_TIMESTAMP(apex_application.g_f18(1), ''DD-MON-RR HH:MI:SS.FF AM'') ,',
'            p_data_finalizado                 => null,',
'            p_ind_calculando_valores          => v_imp_processo.ind_calculando_valores,',
'            p_data_hora_ultimo_calculo        => v_imp_processo.data_hora_ultimo_calculo,',
'            p_id                              => p_id, ',
'            p_sucesso                         => p_sucesso,',
'            p_messages                        => p_messages',
'        );',
'',
'',
'    end;',
'',
'end "UI_MPD_TD909";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td413
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157190503532205803)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD413'
,p_sequence=>1100
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD413" as',
'',
'    v_pessoa_agenciabancaria ng_pessoa_agenciabancaria%rowtype;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'',
'end "UI_MPD_TD413";',
'/',
'create or replace package body "UI_MPD_TD413" as',
'',
'    /********************************************',
'     P_PARAM1 = ID DA ENTIDADE NG_PESSOA_JURIDICA',
'    *********************************************/',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        select a.* into v_pessoa_agenciabancaria from ng_pessoa_agenciabancaria a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa where b.id = p_param1;',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_pessoa'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char(v_pessoa_agenciabancaria.id_pessoa) valor FROM '
||'dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_tenant'',            2, ''SEL'', ''R_MPD_TENANT.NOME_FANTASIA'', ''S'',''S'', to_char(v_pessoa_agenciabancaria.id_tenant) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_grupo_empresarial'', 3, ''POP'', ''R_NG_GRUPOEMPRESARIAL.NOME_GRUPO'', ''S'',''N'', to_char((select id_grupo_empresarial from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''razao_social'',         5, ''TXT'', null, ''S'',''N'', to_char((select razao_social from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_fantasia'',        6, ''TXT'', null, ''S'',''N'', to_char((select nome_fantasia from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_agencia'',       7, '''', null, ''N'',''S'', to_char(v_pessoa_agenciabancaria.numero_agencia) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''digito_verificador'',    8, '''', null, ''N'',''N'', to_char(v_pessoa_agenciabancaria.digito_verificador) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_agencia_exterior'', 9, ''HID'', null, ''N'',''S'', to_char(v_pessoa_agenciabancaria.ind_agencia_exterior) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   10, ''DAT'', null, ''N'',''N'', to_char((select data_fim_vigencia from ng_pessoa a join ng_pessoa_juridica b on b.id_pessoa = a.id where b.id = p_param1), ''dd/mm/yyyy'') valor FROM dual UNION A'
||'LL',
'               SELECT p_codigo_artefato, ''data_alteracao'',      11, ''HID'', null, ''N'', ''N'', to_char(v_pessoa_agenciabancaria.data_alteracao, ''dd-mon-yy hh:mi:ss.ff am'') valor FROM dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is  ',
'        l_id_agenciabancaria ng_pessoa_agenciabancaria.id%type;',
'    begin',
'        select a.id into l_id_agenciabancaria from ng_pessoa_agenciabancaria a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa where b.id = p_id;',
'        bo_ng_pessoa_agenciabancaria.altera_registro(  ',
'            p_id_tenant => apex_application.g_f02(1),',
'            p_id_pessoa => apex_application.g_f01(1),',
'            p_numero_agencia => apex_application.g_f07(1),',
'            p_digito_verificador => apex_application.g_f08(1),',
'            p_ind_agencia_exterior => apex_application.g_f09(1),',
'            --p_data_fim_vigencia => apex_application.g_f10(1),',
'            p_data_alteracao => to_timestamp(apex_application.g_f11(1), ''dd-mon-yy hh:mi:ss.ff am''),    ',
'            p_id => l_id_agenciabancaria,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'',
'',
'',
'end "UI_MPD_TD413";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td415
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157190788090199923)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD415'
,p_sequence=>1110
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD415" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;    ',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD415";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD415" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is       ',
'        l_html clob;',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select ',
'                    a.nome_fantasia',
'                from ng_pessoa_juridica a ',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_pessoa_juridica''),',
'            p_formato => ''pequeno'',            ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                d.nome_abreviado titulo,',
'                null subtitulo,                ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,                   ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_departamento.nome_departamento'',pkg_traducao.get_traducao(e.nome_departamento), 4',
'                ) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_cargo.descricao_cargo'', pkg_traducao.get_traducao(f.descricao_cargo), 4',
'                ) atributo2,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_pessoa_contato.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 4) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_pessoa_contato.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 4) ',
'                end atributo3,',
'                a.data_fim_vigencia,',
'                --FILTROS                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD415'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD415'', p_param1 => d.id) as opcao',
'            from ng_pessoa_contato a                        ',
'            join ng_pessoa b on b.id = a.id_pessoa',
'            join ng_pessoa_juridica c on c.id_pessoa = b.id',
'            join ng_pessoa_fisica d on d.id_pessoa = a.id_pessoa_fisica',
'            left join ng_departamento e on e.id = a.id_departamento',
'            left join ng_cargo f on f.id = a.id_cargo',
'            where c.id = #PARAM1#',
'            order by #ORDER#',
'           ~'';',
'           l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'           return l_sql;           ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            d.nome_abreviado campo1,            ',
'            pkg_traducao.get_traducao(e.nome_departamento) campo2,             ',
'            pkg_traducao.get_traducao(f.descricao_cargo) campo3,',
'            case ',
'                when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            a.data_fim_vigencia campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            null filtro1,                                ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                ',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD415'', p_param1 => d.id) as opcao       ',
'        from ng_pessoa_contato a                        ',
'        join ng_pessoa b on b.id = a.id_pessoa',
'        join ng_pessoa_juridica c on c.id_pessoa = b.id',
'        join ng_pessoa_fisica d on d.id_pessoa = a.id_pessoa_fisica',
'        left join ng_departamento e on e.id = a.id_departamento',
'        left join ng_cargo f on f.id = a.id_cargo',
'        where c.id = #PARAM1#        ',
'       ~'';',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;        ',
'    begin        ',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                opcao                ',
'            from table(pkg_ui.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_pessoa_contato'')) a',
'            order by #ORDER#',
'            ~'';      ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));  ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo in (''1'', ''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.nome_abreviado'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_departamento'') into l_campo from dual;        ',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_cargo'') into l_campo from dual;                    ',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo5,campo1,campo2,campo3'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,atributo1,atributo2'';',
'        end if;',
'',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''3'') || '','' ||',
'               label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1'';',
'        else',
'            l_campos := ''data_fim_vigencia,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD415";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td418
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157190993577196068)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD418'
,p_sequence=>1120
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD418" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
