,p_name=>'UI_MPD_TD427'
,p_sequence=>1150
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD427" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'end "UI_MPD_TD427";',
'/',
'create or replace package body "UI_MPD_TD427" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',                   2, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ng_pessoa_contato.id_pessoa'', 3, ''TXT'', null, ''S'', ''N'', to_char((select nome_fantasia from ng_pessoa_juridica a join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa where b.id = p_param1)) valor FROM dual UN'
||'ION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_fisica'',            4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_departamento'',             6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cargo'',                    8, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',          10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_integracao'',            11, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',         12, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',             13, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_pessoa_contato where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD427";',
'/'))
);
end;
