prompt --application/deployment/install/install_ui_mpd_td430
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157199978521900319)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD430'
,p_sequence=>1170
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD430" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD430";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD430" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,                                ',
'                pkg_traducao.get_traducao(a.nome_grupo) titulo,',
'                a.codigo_banco subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo, ',
'                null lista_distintivo,',
'                to_date(a.data_fim_vigencia, ''dd/mm/yyyy''),',
'                b.nome_fantasia,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD430'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD430'') as opcao                ',
'            from ng_grupoempresarial a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by 8, 2, 7 nulls first',
'            ~'';',
'            --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));            ',
'            return l_sql; ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,',
'            b.nome_fantasia campo1,            ',
'            pkg_traducao.get_traducao(a.nome_grupo) campo2,            ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo3,',
'            a.data_fim_vigencia campo4,',
'            null campo5,             ',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,',
'            --FILTROS',
'            a.id_tenant filtro1,                             ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_grupoempresarial a              ',
'        join mpd_tenant b on b.id = a.id_tenant             ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD430'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_grupoempresarial'')) a',
'            order by campo1, campo2, to_date(campo4, ''dd/mm/yyyy'') nulls first',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant order by 1~'';',
'        else',
'            return null;        ',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_grupoempresarial.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_grupoempresarial.nome_grupo'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_grupoempresarial.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'     procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''nome_grupo, data_fim_vigencia'';',
'        else',
'            campos := ''campo1, campo5'';',
'        end if;',
'        labels := label_coluna(''1'')||'',''||label_coluna(''5'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD430";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td434
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157200477092895616)
