||'             ',
'               SELECT p_codigo_artefato, ''nome_grupo'',         3, '''', to_char(l_url), ''S'', ''S'', to_char((select pkg_traducao.get_traducao(nome_grupo) from ng_grupoempresarial where id = p_param1)) valor FROM dual UNION ALL   ',
'               SELECT p_codigo_artefato, ''codigo_banco'',       4, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL                                                           ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  5, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL    ',
