||'                                          ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     7, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_grupoempresarial where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
