prompt --application/deployment/install/install_ui_mpd_td438
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157381359794594088)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD438'
,p_sequence=>1190
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'',
'create or replace package "UI_MPD_TD438" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD438";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD438" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                a.data_fim_vigencia,                ',
'                pkg_traducao.get_traducao(a.nome_documento)                          titulo, ',
'                b.nome_fantasia             subtitulo,',
'                null                        distintivo,',
'                ''u-hidden''                  class_distintivo,',
'                null                        lista_distintivo,                          ',
'                --ATRIBUTOS               ',
'                pkg_componentes.html_card_colunas(''ng_documento.id_entidade'', c.nome_leitura, 6)                           atributo2,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_documento.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 6) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_documento.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 6) ',
'                end atributo3,                ',
'                --FILTROS',
'                a.id_tenant         filtro1,',
'                a.id_entidade       filtro2,',
'                null                filtro3,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                    pkg_ui.url_mais_detalhes(''TD438'',a.id) url_mais_detalhes,',
'                    pkg_componentes.html_botao_opcao(a.id,''TD438'') as opcao  ',
'                from ng_documento a ',
'                JOIN mpd_tenant b on b.id = a.id_tenant ',
'                join srv_entidade_ng_permite_anexo e on e.id = a.id_entidade',
'                join srv_entidade c on c.id = e.id_entidade',
'                order by #ORDER#',
'           ~'';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'           return l_sql;',
'           --order by 4,8,9,3,2 nulls first',
'           -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,     ',
'            b.nome_fantasia                                                                             campo1,',
'            c.nome_leitura                                                                              campo2,',
'            pkg_traducao.get_traducao(a.nome_documento)                                                campo3,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end                                              campo4,',
'            null                                             campo5,',
'            null                                             campo6,',
'            null                                             campo7,',
'            null                                             campo8,',
'            null                                             campo9,',
'            a.data_fim_vigencia                              campo10,',
'            --FILTROS',
'            a.id_tenant                                      filtro1,                                ',
'            a.id_entidade                                    filtro2,                                ',
'            null                                             filtro3,                                ',
'            null                                             filtro4,',
'            null                                             filtro5,                                ',
'            --FILTROS MULTI',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            null                                             filtro_mult5,                                ',
'            null opcao',
'        from ng_documento a',
'        JOIN mpd_tenant b ON a.id_tenant = b.id  ',
'        join srv_entidade_ng_permite_anexo e on e.id = a.id_entidade',
'        join srv_entidade c on c.id = e.id_entidade;',
'       ~'';',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD438'') as opcao',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_documento'')) a',
'            order by #ORDER#   ',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''3''));',
'        return l_sql;',
'        -- order by campo1,campo2,campo3, to_date(campo10,''dd/mm/yyyy'') nulls first  ',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~select s.nome_leitura d, e.id r from srv_entidade_ng_permite_anexo e join srv_entidade s on s.id = e.id_entidade~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo IN (''1'',''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_documento.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_documento.id_entidade'') into l_campo from dual;',
'        elsif campo = ''3'' then                        ',
'            select pkg_ui.retorna_label_coluna(''ng_documento.nome_documento'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_documento.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''F2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_documento.id_entidade'') into l_campo from dual;  ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo10,campo1,campo2,campo3'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,atributo2,titulo'';',
'        end if;',
'',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'               label_coluna(''1'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo10,campo1'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD438";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td441
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157381510246586795)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD441'
,p_sequence=>1200
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD441" as',
'   ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD441";',
'/',
'create or replace package body "UI_MPD_TD441" as',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;        ',
'        l_id_coluna_anexo number;                  ',
'        l_descricao clob;',
'        l_descricao_anexo clob;',
'        l_permite_edicao varchar2(5);',
'        l_permite_edicao_anexo varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);',
'        l_somente_leitura_anexo varchar2(1);',
'        l_url varchar2(4000);',
'    begin',
'',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = lower(''ng_documento'');',
'        select id into l_id_coluna   from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_documento'';     ',
'',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'        if lower(l_permite_edicao_anexo) = ''false'' then',
'            l_somente_leitura_anexo := ''S'';',
'        else',
'            l_somente_leitura_anexo := ''N'';',
'        end if;',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'    ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''nome_documento'',            4, '''', l_url ,l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(nome_documento) from ng_documento where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entidade'',               7, '''', null,  ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_referencia_documento'',  9, '''', null,  ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_emitido_aplicacao'',    10, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_obrigatorio'',          12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_aprovar'',              14, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',        18, '''', null, ''N'',''S'', null valor FROM dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',       20, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'',''S'', null valor FROM dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''data_alteracao'',           22, ''TXT'', null, ''N'',''S'', pkg_data.fmt((select data_alteracao from ng_documento where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'',
'end "UI_MPD_TD441";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td448
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157381791672579339)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD448'
,p_sequence=>1210
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD448" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD448";',
'/',
'create or replace package body "UI_MPD_TD448" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                pkg_traducao.get_traducao(a.descricao_idioma) ||'' (''||sigla_idioma||'')'' titulo,',
'                a.codigo subtitulo,                                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when a.data_fim_vigencia < current_date then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                             ',
'                null lista_distintivo,                ',
'                --FILTROS',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD448'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD448'') as opcao                ',
'            from srv_idioma a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));                        ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,   ',
'            b.nome_fantasia campo1,                                                               ',
'            a.sigla_idioma campo2,   ',
'            pkg_traducao.get_traducao(a.descricao_idioma) campo3,',
'            a.codigo campo4,  ',
'            case when data_fim_vigencia < current_date then',
'                ''<span style="color:red;">'' || pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') || ''</span>''',
'            else',
'                pkg_data.fmtd(data_fim_vigencia, ''DATA'')',
'            end campo5,                      ',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,',
'            --FILTROS',
'            null filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                 ',
'            null opcao',
'        from srv_idioma a',
'        join mpd_tenant b on b.id = a.id_tenant                 ',
'       ~'';              ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD448'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''srv_idioma'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;        ',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return '''';        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'     begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''srv_idioma.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''srv_idioma.sigla_idioma'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''mpd_descricao.descricao'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''srv_idioma.codigo'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''srv_idioma.data_fim_vigencia'') into l_campo from dual;                ',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''descricao_idioma, sigla_idioma'';',
'        else',
'            campos := ''campo2,campo3'';',
'        end if;',
'        labels := label_coluna(''2'')||'',''||label_coluna(''3'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD448";',
'/'))
);
end;
/
