||'ere id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_pessoa_contato'',    2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa_fisica from ng_pessoa_contato where id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_pessoa_referencia'', 3, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_contato where id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_forma_contato'',    4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''dado_contato'',         5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_whatsapp'',         6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''observacao'',           7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''data_fim_vigencia'',    8, ''HID'', null, ''N'', ''S'', pkg_data.fmtd((select data_fim_vigencia from ng_pessoa_contato where id = p_param1), ''DATA'') valor FROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'        else',
'            l_consulta := ''select c.nome_abreviado d, c.id_pessoa r from ng_pessoa_contato a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica where b.id = ''||p_param1||'' order by 1'';',
'            ',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica w'
||'here id = p_param1)) valor FROM dual UNION ALL            ',
'                   SELECT p_codigo_artefato, ''id_pessoa_contato'',    3, ''POP1'', to_char(l_consulta), ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_pessoa_referencia'', 5, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_forma_contato'',    7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''dado_contato'',         9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_whatsapp'',        11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''observacao'',          13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''data_fim_vigencia'',   15, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'        end if;            ',
'    end formulario;',
'',
'--     procedure post_create(',
