'--             l_ind_whataspp := apex_application.g_f11(1);',
'--         else',
'--             l_ind_whataspp := null;',
'--         end if;',
'--         bo_ng_pessoa_contato_dado.inclui_registro(',
'--             p_id_tenant => apex_application.g_f01(1),',
'--             p_id_pessoa_contato => apex_application.g_f03(1),',
'--             p_id_pessoa_referencia => pkg_util.retorna_number(apex_application.g_f05(1)),',
'--             p_ind_forma_contato => apex_application.g_f07(1),',
'--             p_dado_contato => apex_application.g_f09(1),            ',
'--             p_ind_whatsapp => l_ind_whataspp,',
'--             p_observacao => apex_application.g_f13(1),',
'--             p_data_fim_vigencia => apex_application.g_f15(1),',
'--             p_data_integracao => null,',
'--             p_motivo_rejeicao => null,',
'--             p_id => l_id, ',
'--             p_sucesso => p_sucesso,',
'--             p_messages => p_messages',
'--         );',
'--     end post;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'        l_id_pessoa_fisica number;',
'        l_id_pessoa number;',
'    begin   ',
'        select id_pessoa_fisica into l_id_pessoa_fisica from ng_pessoa_contato where id = p_param1;',
'        select id_pessoa into l_id_pessoa from ng_pessoa_contato where id = p_param1;',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo1,',
'                a.dado_contato campo2,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_whatsapp'', a.ind_whatsapp) campo3,',
'                a.observacao campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD452'') opcao',
'            from ng_pessoa_contato_dado a  ',
'            join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato          ',
'            and b.id_pessoa_fisica = #l_id_pessoa_fisica#',
'            where a.id_pessoa_referencia = #l_id_pessoa#',
'            order by campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        l_sql := replace(l_sql,''#l_id_pessoa_fisica#'',nvl(l_id_pessoa_fisica,''''));        ',
'        l_sql := replace(l_sql,''#l_id_pessoa#'',nvl(l_id_pessoa,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'        l_id_pessoa_fisica number;',
'        l_id_pessoa number;',
'    begin   ',
'        select id_pessoa_fisica into l_id_pessoa_fisica from ng_pessoa_contato where id = p_param1;',
'        select id_pessoa into l_id_pessoa from ng_pessoa_contato where id = p_param1;',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo1,',
'                a.dado_contato campo2,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_whatsapp'', a.ind_whatsapp) campo3,',
'                a.observacao campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD452'') opcao',
'            from ng_pessoa_contato_dado a  ',
'            join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato          ',
'            and b.id_pessoa_fisica = #l_id_pessoa_fisica#',
'            where a.id_pessoa_referencia = #l_id_pessoa#',
'            order by campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        l_sql := replace(l_sql,''#l_id_pessoa_fisica#'',nvl(l_id_pessoa_fisica,''''));        ',
'        l_sql := replace(l_sql,''#l_id_pessoa#'',nvl(l_id_pessoa,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin   ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_forma_contato'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.dado_contato'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_whatsapp'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.observacao'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_pessoa_contato'') then',
'            return ''',
'                where b.id in (TO_NUMBER(apex_util.get_session_state(''''P9010_PARAMETRO'''')))',
'            '';',
'        else',
'            return '''';',
'        end if;',
'    end;',
'',
'   function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD985,TD985,''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'end "UI_MPD_TD452";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td455
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157382562663561150)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD455'
,p_sequence=>1230
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD455" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD455";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD455" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                a.razao_social titulo,',
'                null subtitulo,',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_pessoa_juridica.nome_fantasia'', a.nome_fantasia, 6) atributo1,                ',
'                case ',
'                    when b.data_fim_vigencia is null then',
'                        null',
'                    when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_pessoa.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(b.data_fim_vigencia, ''DATA'')), 6) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_pessoa.data_fim_vigencia'', pkg_data.fmtd(b.data_fim_vigencia, ''DATA''), 6) ',
'                end atributo2,                  ',
'                c.nome_fantasia,',
'                data_fim_vigencia,              ',
'                --FILTROS                ',
'                b.id_tenant filtro1,                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD455'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD455'', p_param1 => b.id) as opcao                ',
'            from ng_pessoa_juridica a',
'            join ng_pessoa b on b.id = a.id_pessoa',
'            join mpd_tenant c on c.id = b.id_tenant            ',
'            left join ng_pessoa_agenciabancaria d on d.id_pessoa = a.id_pessoa',
'            where lower(a.ind_perfil) like ''%a%''',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            --order by 9, 10 nulls first, 7',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            c.nome_fantasia campo1,',
'            a.nome_fantasia campo2,',
'            case ',
'                when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(b.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(b.data_fim_vigencia, ''DATA'')',
'            end campo3,',
'            b.data_fim_vigencia campo4,            ',
'            null campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            b.id_tenant filtro1,   ',
'            null filtro2,         ',
'            null filtro3,         ',
'            null filtro4,         ',
'            null filtro5,         ',
'            --FILTROS MULTI',
'            null filtro_mult1,',
'            null filtro_mult2,',
'            null filtro_mult3,',
'            null filtro_mult4,',
'            null filtro_mult5,',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD455'', p_param1 => b.id) as opcao         ',
'        from ng_pessoa_juridica a',
'        join ng_pessoa b on b.id = a.id_pessoa',
'        join mpd_tenant c on c.id = b.id_tenant        ',
'        left join ng_pessoa_agenciabancaria d on d.id_pessoa = b.id',
'        where lower(a.ind_perfil) like ''%a%''',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_pessoa_fisica'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));',
'        --order by campo1, to_date(campo4, ''dd/mm/yyyy'') nulls first, campo2                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_juridica.nome_fantasia'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo4,campo1,campo2'';',
'        else',
'            campos := ''data_fim_vigencia,nome_fantasia,atributo1'';',
'        end if;',
'',
'        select label_coluna(''3'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''3'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo3,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,nome_fantasia,atributo1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD455";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td458
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157382718873557911)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD458'
,p_sequence=>1240
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD458" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD458";',
'/',
'create or replace package body "UI_MPD_TD458" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_observacao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;        ',
'        l_cabecalho varchar2(32767);',
'        l_url varchar2(4000);',
'        l_id_agenciabancaria number;',
'    begin',
'',
'        l_cabecalho := ''bo_ng_pessoa_juridica.sql_cabecalho_externo'';',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pessoa_juridica'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';    ',
'        select a.id into l_id_agenciabancaria from ng_pessoa_agenciabancaria a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa where b.id = p_param1;',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2,P9005_PARAMETRO3'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna||'',''||l_cabecalho, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.NOME_FANTASIA'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',            2, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_grupo_empresarial'', 3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''razao_social'',         5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''nome_fantasia'',        6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_agencia'',       7, '''', null, ''N'',''N'', to_char((select numero_agencia from ng_pessoa_agenciabancaria where id = l_id_agenciabancaria)) valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''digito_verificador'',   8, '''', null, ''N'',''N'', to_char((select digito_verificador from ng_pessoa_agenciabancaria where id = l_id_agenciabancaria)) valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_agencia_exterior'', 9, ''RAD'', ''D_NG_PESSOA_AGENCIABANCARIA.IND_AGENCIA_EXTERIOR'', ''N'',''N'', to_char((select ind_agencia_exterior from ng_pessoa_agenciabancaria where id = l_id_agenciabancaria)) valor FROM d'
||'ual UNION ALL               ',
'               SELECT p_codigo_artefato, ''inscricao_federal'',   10, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',          11, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(observacao) from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''rede_social'',         12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL                              ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   13, ''DAT'', null, ''N'',''N'', pkg_data.fmtd((select data_fim_vigencia from ng_pessoa a join ng_pessoa_juridica b on b.id_pessoa = a.id where b.id = p_param1),''DATA'') valor FROM dual UNION AL'
||'L',
'               SELECT p_codigo_artefato, ''ind_matriz'',          14, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''inscricao_estadual'',  15, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''inscricao_municipal'', 16, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''inscricao_suframa'',   17, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_tin'',          18, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_cnae'',         19, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_integracao'',     20, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',  21, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'',''S'', to_char((select id_usuario_alterou from ng_pessoa_agenciabancaria where id = l_id_agenciabancaria)) valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',      22, ''TXT'', null, ''N'',''N'', pkg_data.fmt((select data_alteracao from ng_pessoa_agenciabancaria where id = l_id_agenciabancaria), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD458";',
'/'))
);
end;
