prompt --application/deployment/install/install_ui_mpd_td485
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157385271070372842)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD485'
,p_sequence=>1280
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD485" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'end "UI_MPD_TD485";',
'/',
'create or replace package body "UI_MPD_TD485" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin                ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, ''R_MPD_TENANT.NOME_FANTASIA'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' coluna_tabela, NULL valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_sistema_externo'', 3, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 7, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     8, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_sistemaexterno where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;    ',
'',
'end "UI_MPD_TD485";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td487
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157385490005367493)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD487'
,p_sequence=>1290
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD487" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;    ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'',
'end "UI_MPD_TD487";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD487" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            pkg_traducao.get_traducao(a.descricao_conta_corrente) titulo,',
'            b.nome_fantasia subtitulo,            ',
'            null distintivo,',
'            ''u-hidden'' class_distintivo, ',
'            null lista_distintivo,',
'            --ATRIBUTOS                        ',
'            pkg_componentes.html_card_colunas(''ng_contacorrente.id_agencia'', e.nome_fantasia, 4) atributo1,',
'            pkg_componentes.html_card_colunas(''ng_contacorrente.conta_corrente'', a.conta_corrente, 4) atributo2,',
'            case ',
'                when a.data_fim_vigencia is null then',
'                    null',
'                when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_card_colunas(''ng_contacorrente.data_fim_vigencia'', ',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 4) ',
'                else',
'                    pkg_componentes.html_card_colunas(''ng_contacorrente.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 4) ',
'            end atributo3,',
'            to_date(a.data_fim_vigencia, ''dd/mm/yyyy''),',
'            --order',
'            e.nome_fantasia order1,',
'            a.conta_corrente order2,',
'            a.data_fim_vigencia order3,',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            a.id_agencia filtro2,',
'            a.id_conta_contabil filtro3,',
'            null FILTRO_MULT1,',
'            null FILTRO_MULT2,',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD487'', a.id) url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id, ''TD487'') as opcao',
'        from ng_contacorrente a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_pessoa_agenciabancaria c on c.id = a.id_agencia',
'        join ng_pessoa d on d.id = c.id_pessoa',
'        join ng_pessoa_juridica e on e.id_pessoa = d.id',
'        order by #ORDER#',
'       ~'';       ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'       return l_sql;       ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'        select ',
'            a.id id,                                                            ',
'            b.nome_fantasia campo1, ',
'            pkg_traducao.get_traducao(a.descricao_conta_corrente) campo2,',
'            e.nome_fantasia campo3,  ',
'            a.conta_corrente campo4,                        ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,                        ',
'            a.data_fim_vigencia campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            a.id_agencia filtro2,',
'            a.id_conta_contabil filtro3,                               ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,             ',
'            null opcao',
'        from ng_contacorrente a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_pessoa_agenciabancaria c on c.id = a.id_agencia',
'        join ng_pessoa d on d.id = c.id_pessoa',
'        join ng_pessoa_juridica e on e.id_pessoa = d.id',
'       ~'';          ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id, ''TD487'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_contacorrente'')) a    ',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        return null;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_contacorrente.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_contacorrente.descricao_conta_corrente'') into l_campo from dual;',
'        elsif campo in (''3'', ''F2'') then',
'            select pkg_ui.retorna_label_coluna(''ng_contacorrente.id_agencia'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_contacorrente.conta_corrente'') into l_campo from dual;            ',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_contacorrente.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''F3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_contacorrente.id_conta_contabil'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;   ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo4,campo6'';',
'        else',
'            campos := ''subtitulo,titulo,order1,order2,order3'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2,campo3'';',
'        else',
'            l_campos := ''order3,subtitulo,titulo,order1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD487";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td490
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157385690315363813)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD490'
,p_sequence=>1300
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD490" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD490";',
'/',
'create or replace package body "UI_MPD_TD490" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob; ',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_contacorrente'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_conta_corrente''; ',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''descricao_conta_corrente'', 3, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_conta_corrente) from ng_contacorrente where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_agencia'',               4, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''conta_corrente'',           5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_conta_exterior'',       6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_contabil'',        7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                 8, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',        9, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',      10, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',          11, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_contacorrente WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'              ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'    ',
'end "UI_MPD_TD490";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td491
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157385909730358151)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD491'
,p_sequence=>1310
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD491" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD491";',
'/',
'create or replace package body "UI_MPD_TD491" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_agenciabancari'
||'a where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',         2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_agenciabancaria where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_fisica'',  3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_departamento'',   5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cargo'',          7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'', 9, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_pessoa_contato_dado where id_pessoa_contato = (select id from ng_pessoa_contato where id_pessoa = (select id_pessoa from ng_pessoa_juridica where id = p_paramentro)); ',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;    ',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is        ',
'    begin',
'        bo_ng_pessoa_contato.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa => apex_application.g_f02(1),',
'            p_id_pessoa_fisica => apex_application.g_f03(1),',
'            p_id_departamento => apex_application.g_f05(1),',
'            p_id_cargo => apex_application.g_f07(1),',
'            p_data_fim_vigencia => apex_application.g_f09(1),',
'            p_data_integracao => null,            ',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select                                ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_traducao.get_traducao(e.nome_departamento) campo2,',
'                pkg_traducao.get_traducao(f.descricao_cargo) campo3,',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') campo4,',
'                a.data_fim_vigencia campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD491'') opcao            ',
'            from ng_pessoa_contato a ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica',
'            join ng_pessoa_agenciabancaria d on d.id_pessoa = b.id_pessoa',
'            left join ng_departamento e on e.id = a.id_departamento',
'            left join ng_cargo f on f.id = a.id_cargo',
'            where d.id = #param1#',
'            order by to_date(campo5, ''dd/mm/yyyy'') nulls first, campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select                                ',
'                null selected,',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_traducao.get_traducao(e.nome_departamento) campo2,',
'                pkg_traducao.get_traducao(f.descricao_cargo) campo3,',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') campo4,',
'                a.data_fim_vigencia campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD491'') opcao            ',
'            from ng_pessoa_contato a ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica',
'            join ng_pessoa_agenciabancaria d on d.id_pessoa = b.id_pessoa',
'            left join ng_departamento e on e.id = a.id_departamento',
'            left join ng_cargo f on f.id = a.id_cargo',
'            where d.id = #param1#',
'            order by to_date(campo5, ''dd/mm/yyyy'') nulls first, campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_pessoa_fisica'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_departamento'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.id_cargo'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'        l_id_pessoa_juridica number;',
'    begin',
'        select a.id into l_id_pessoa_juridica from ng_pessoa_juridica a join ng_pessoa_agenciabancaria b on b.id_pessoa = a.id_pessoa where b.id = p_param1;',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_PARAMETRO2,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD417,TD417,''||l_id_pessoa_juridica||'',''||l_id_pessoa_juridica||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'        );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD491";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td493
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157386193611354707)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD493'
,p_sequence=>1320
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD493" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'    ',
'end "UI_MPD_TD493";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD493" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'        select',
'            a.id ,',
'            b.nome_fantasia,',
'            data_fim_vigencia,',
'            pkg_traducao.get_traducao(a.descricao_familia) titulo,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end  distintivo,            ',
'            null lista_distintivo,',
'            null class_distintivo,',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            null FILTRO_MULT1,',
'            null FILTRO_MULT2,',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD493'', a.id) url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id, ''TD493'') as opcao',
'        from ng_familia_item a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        order by #ORDER#',
'        ~'';',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'        return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia      campo1,',
'           -- substituir select nome_codigo from ng_codigo_familia where ng_codigo_familia.id = ng_familia_item.codigo_familia',
'            pkg_traducao.get_traducao(a.descricao_familia)               campo2,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end                                              campo3,',
'            a.data_fim_vigencia campo4,',
'            null campo5,             ',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            a.id_tenant filtro1,                                 ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,   ',
'            null opcao',
'        from ng_familia_item a',
'        join mpd_tenant b on b.id = a.id_tenant',
'',
'',
'       ~'';',
'       -- l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id, ''TD493'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''NG_FAMILIA_ITEM'')) a',
'            order by #ORDER#',
'            ~'';',
'            -- l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'          return l_sql;',
'    end sql_report;',
'',
'    -- ~'';',
'    --         l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'    --     return l_sql;',
'    -- end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;',
'    end sql_verifica_filtro;',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo IN (''1'',''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_familia_item.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_familia_item.descricao_familia'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_familia_item.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'    ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo4,campo1,campo2'';',
'        else',
'            campos := ''data_fim_vigencia,nome_fantasia,titulo'';',
'        end if;',
'',
'        select label_coluna(''3'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''3'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''2'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo4,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,nome_fantasia,titulo'';',
'        end if;',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD493";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td495
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157386511907349434)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD495'
,p_sequence=>1330
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD495" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD495";',
'/',
'create or replace package body "UI_MPD_TD495" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_consulta clob;',
'    begin',
'        l_consulta := ''select c.nome_abreviado d, c.id_pessoa r from ng_pessoa_contato a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica join ng_pessoa_agenciabancaria d on d.id_pesso'
||'a = b.id_pessoa where d.id = ''||p_param1||'' order by 1'';',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_agenciabancari'
||'a where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_referencia'', 2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_agenciabancaria where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_contato'',    3, ''POP1'', to_char(l_consulta), ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_contato'',    9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''dado_contato'',        10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_whatsapp'',        11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',          12, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   13, ''HID'', null, ''N'', ''S'', null valor FROM dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    ',
'        function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_pessoa_contato'') then',
'                return ''',
'                    where e.id in (TO_NUMBER(apex_util.get_session_state(''''P9013_PARAMETRO'''')))',
'                '';',
'            else',
'                return '''';',
'            end if;',
'        end;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_pessoa_contato_dado where id_pessoa_contato = (select id from ng_pessoa_contato where id_pessoa = (select id_pessoa from ng_pessoa_juridica where id = p_paramentro)); ',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;    ',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_ind_whatsapp varchar2(1);',
'    begin',
'        if lower(apex_application.g_f09(1)) = ''2'' then',
'            l_ind_whatsapp := apex_application.g_f11(1);',
'        else',
'            l_ind_whatsapp := null;',
'        end if;        ',
'        bo_ng_pessoa_contato_dado.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa_referencia => apex_application.g_f02(1),',
'            p_id_pessoa_contato => apex_application.g_f03(1),            ',
'            p_ind_forma_contato => apex_application.g_f09(1),',
'            p_dado_contato => apex_application.g_f10(1),',
'            p_ind_whatsapp => l_ind_whatsapp,',
'            p_observacao => apex_application.g_f12(1),  ',
'            p_data_fim_vigencia => apex_application.g_f13(1),',
'            p_motivo_rejeicao => null,            ',
'            p_data_integracao => null,            ',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo2,',
'                a.dado_contato campo3,                ',
'                pkg_traducao.get_traducao(a.observacao) campo4,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo5,',
'                a.data_fim_vigencia campo6,                ',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD495'') opcao',
'            from ng_pessoa_contato_dado a            ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa_referencia',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_contato',
'            join ng_pessoa_agenciabancaria d on d.id_pessoa = b.id_pessoa',
'            where d.id = #param1#',
'            order by campo1, to_date(campo6, ''dd/mm/yyyy'') nulls first',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                null selected,        ',
'                a.id,',
'                nome_abreviado campo1,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo2,',
'                a.dado_contato campo3,                ',
'                pkg_traducao.get_traducao(a.observacao) campo4,',
'                case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    --pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo5,',
'                a.data_fim_vigencia campo6,                ',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD495'') opcao',
'            from ng_pessoa_contato_dado a            ',
'            join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa_referencia',
'            join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_contato',
'            join ng_pessoa_agenciabancaria d on d.id_pessoa = b.id_pessoa',
'            where d.id = #param1#',
'            order by campo1, to_date(campo6, ''dd/mm/yyyy'') nulls first',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.id_pessoa_contato'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_forma_contato'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.dado_contato'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.observacao'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'        l_id_pessoa_juridica number;',
'    begin',
'        select a.id into l_id_pessoa_juridica from ng_pessoa_juridica a join ng_pessoa_agenciabancaria b on b.id_pessoa = a.id_pessoa where b.id = p_param1;',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_PARAMETRO2,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD452,TD452,''||l_id_pessoa_juridica||'',''||l_id_pessoa_juridica||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'        );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD495";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td497
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157386732453345487)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD497'
,p_sequence=>1340
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD497" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'end "UI_MPD_TD497";',
'/',
'create or replace package body "UI_MPD_TD497" as',
'',
'  procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;        ',
'        l_id_idioma_tenant number;',
'        l_id_tenant_origem number; ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_familia_item'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_familia''; ',
'        select id_tenant into l_id_tenant_origem from ng_familia_item where id = p_param1;',
'        select id_idioma into l_id_idioma_tenant from mpd_tenant where id = l_id_tenant_origem;',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'        ',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''descricao_familia'', 3, '''', l_url, ''N'', ''S'',  to_char((select pkg_traducao.get_traducao(descricao_familia) from ng_familia_item where id = p_param1)) valor  FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 6, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     7, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_familia_item WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'              ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'',
'end "UI_MPD_TD497";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td498
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157386908612334936)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD498'
,p_sequence=>1350
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na UI para buscar informa\00E7\00F5es do \00FAltimo pedido de acordo com id_tenant, ind_modalidade_importacao, id_exportador e id_importador'),
'-- Jira: PEDITEM-65',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD498" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob;',
'    ',
'    function sql_atribuir_numero_pedido_importacao(p_param1 in varchar2) return clob;',
'',
'    function sql_atribuir_valor_ultimo_pedido(p_param1 in varchar2) return clob;',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'    ',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
unistr('    --Fun\00E7\00E3o par mostrar um bot\00E3o personalizavel com link para qualquer pagina do sistema'),
'    -- function url_botao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
unistr('    --Complemento da fun\00E7\00E3o url_botao, a fun\00E7\00E3o label_botao precisa ser informada para dar nome ao bot\00E3o personalizavel'),
'    -- function label_botao return varchar2;',
'',
unistr('    --Fun\00E7\00E3o para enconder os bot\00F5es de integra\00E7\00E3o com o progresso do wizard, processeguir e voltar.'),
'   -- function esconder_botao_wizard return varchar2;',
'',
'end "UI_MPD_TD498";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD498" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_consulta_id_endereco_origem clob;',
'        l_consulta_id_endereco_destino clob;',
'        l_consulta_id_incoterm clob;',
'        l_consulta_id_listapreco clob;',
'        l_campos apex_t_varchar2 := apex_t_varchar2(''QUANTIDADE_PARCELAS_PAGAMENTO'');',
'        l_atribuir_valor clob;',
'        l_somente_leitura_id_tenant varchar2(1);',
'        l_somente_leitura_numero_pedido_importacao varchar2(1);',
'        l_atribuir_numero_pedido_importacao clob;',
'        l_campos_numero_pedido_importacao apex_t_varchar2 := apex_t_varchar2(''NUMERO_PEDIDO_IMPORTACAO'',''SOMENTE_LEITURA_NUMERO_PEDIDO_IMPORTACAO'');',
'        v_json_dependencia_numero_pedido_importacao clob;',
'        v_condicoes_numero_pedido_importacao      array_varchar := array_varchar(''SOMENTE_LEITURA_NUMERO_PEDIDO_IMPORTACAO == %N%'',''SOMENTE_LEITURA_NUMERO_PEDIDO_IMPORTACAO == %S%'');',
'        v_colunas_alvo_numero_pedido_importacao   array_varchar := array_varchar(''NUMERO_PEDIDO_IMPORTACAO'',''NUMERO_PEDIDO_IMPORTACAO'');',
'        v_comportamentos_id_numero_pedido_importacao array_varchar := array_varchar(''vis'',''vis'');',
'        --',
'        l_atribuir_valor_ultimo_pedido clob;',
'        l_campos_ultimo_pedido apex_t_varchar2 := apex_t_varchar2(''ID_ADQUIRENTE'',''ID_COMPRADOR'',''NOME_VENDEDOR'',''ID_MOEDA'',''ID_VIATRANSPORTE'',''ID_INCOTERM'',''ID_LISTAPRECO'',''ID_ENDERECO_ORIGEM'',''ID_LOCAL_EMBARQUE'',''ID_LOCAL_DESEMBARQUE'',''ID_ENDERECO_'
||'DESTINO'',''QUANTIDADE_ENTREGA'',''ID_CONDICAOPAGAMENTO'');',
'    begin',
'        l_atribuir_valor := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_valor'', l_campos);        ',
'',
'        l_atribuir_numero_pedido_importacao := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_numero_pedido_importacao'', l_campos_numero_pedido_importacao);',
'',
'        v_json_dependencia_numero_pedido_importacao := gerar_json_dependencias_array(v_condicoes_numero_pedido_importacao, v_colunas_alvo_numero_pedido_importacao, v_comportamentos_id_numero_pedido_importacao);',
'        ',
'        if apex_util.get_session_state(''P9012_ID'') is not null then',
'            l_somente_leitura_id_tenant := ''S'';',
'            l_somente_leitura_numero_pedido_importacao := ''S'';',
'        else',
'            l_somente_leitura_id_tenant := ''N'';',
'            l_somente_leitura_numero_pedido_importacao := ''N'';',
'        end if;        ',
'',
'        --',
'        if p_param1 is null then',
'            l_atribuir_valor_ultimo_pedido := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_valor_ultimo_pedido'', l_campos_ultimo_pedido);',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, l_somente_leitura_id_tenant AS somente_leitura, ''S'' as coluna_tabela, null valor, l_atribuir_numero_pedi'
||'do_importacao atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''NUMERO_PEDIDO_IMPORTACAO'',                  2, '''', null, l_somente_leitura_numero_pedido_importacao, ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',                 3, '''', null, ''N'', ''S'', null valor, l_atribuir_valor_ultimo_pedido atribuir_valor, null dependencia FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_exportador'',                             4, '''', null, ''N'', ''S'', null valor, l_atribuir_valor_ultimo_pedido atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                             6, '''', null, ''N'', ''S'', null valor, l_atribuir_valor_ultimo_pedido atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                             8, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_COMPRADOR'',                             10, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''NOME_VENDEDOR'',                            12, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_proforma'',                          14, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ID_MOEDA'',                                 15, ''SEL'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ID_VIATRANSPORTE'',                         19, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_INCOTERM'',                              21, ''POP'', to_char(l_consulta_id_incoterm), ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_CONDICAOPAGAMENTO'',                     23, '''', null, ''N'', ''S'', null valor, l_atribuir_valor atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''QUANTIDADE_PARCELAS_PAGAMENTO'',            25, '''', null, ''S'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_LISTAPRECO'',                            26, ''POP'', to_char(l_consulta_id_listapreco), ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_ENDERECO_ORIGEM'',                       28, ''POP'', to_char(l_consulta_id_endereco_origem), ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_LOCAL_EMBARQUE'',                        30, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_LOCAL_DESEMBARQUE'',                     32, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_ENDERECO_DESTINO'',                      34, ''POP'', to_char(l_consulta_id_endereco_destino), ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''QUANTIDADE_ENTREGA'',                       36, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''valor_total_mercadoria'',                   37, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto'',                           38, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesa_proforma'',                   39, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_condicao_venda'',               40, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_confirmacao_pedido'',                  41, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_todos_itens_com_entregas_programadas'', 42, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                           43, '''', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pedido_importacao'',             44, ''HID'', null, ''N'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao_parcela_pagamento'',           45, ''HID'', null, ''N'', ''S'', ''N'' valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''SOMENTE_LEITURA_NUMERO_PEDIDO_IMPORTACAO'', 46, ''HID'', null, ''S'', ''N'', ''S'' valor, null atribuir_valor, v_json_dependencia_numero_pedido_importacao dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''motivo_desconto'',                          47, ''HID'', null, ''S'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_financeiro'',                   48, ''HID'', null, ''S'', ''S'', null valor, null atribuir_valor, null dependencia FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, atribuir_valor, dependencia)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.atribuir_valor, new_data.dependencia);',
'    end formulario;',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select count(b.id) QUANTIDADE_PARCELAS_PAGAMENTO',
'            from ng_condicaopagamento a',
'            join ng_condicaopagamento_parcela b on b.id_condicaopagamento = a.id',
'            where a.id = #ID#',
'        ~'';',
'        ',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end sql_atribuir_valor;',
'',
'    function sql_atribuir_numero_pedido_importacao(p_param1 in varchar2) return clob is',
'        l_verifica_configuracao number;',
'        l_sql clob;',
'    begin',
'        if apex_util.get_session_state(''P9012_ID'') is null then',
'            select count(1) into l_verifica_configuracao',
'            from mpd_configuracao_ng a join mpd_configuracao_ng_dominio b on b.id_configuracao = a.id ',
'            where a.id_tenant = p_param1 ',
'            and a.codigo_configuracao = 2 ',
'            and b.id = a.valor_dominio',
'            and b.codigo_dominio = 2;',
'',
'            if l_verifica_configuracao > 0 then',
'                l_sql := q''~',
'                    select                        ',
'                        '' '' NUMERO_PEDIDO_IMPORTACAO,',
'                        ''N'' SOMENTE_LEITURA_NUMERO_PEDIDO_IMPORTACAO',
'                    from dual            ',
'                ~'';',
'            else',
'                l_sql := q''~',
'                    select ',
'                        '' '' NUMERO_PEDIDO_IMPORTACAO,',
'                        ''S'' SOMENTE_LEITURA_NUMERO_PEDIDO_IMPORTACAO',
'                    from dual            ',
'                ~'';',
'            end if;        ',
'        end if;',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end sql_atribuir_numero_pedido_importacao;',
'',
'    function sql_atribuir_valor_ultimo_pedido(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select ',
'                case when a.nome_vendedor        is not null then a.nome_vendedor        end NOME_VENDEDOR,',
'                case when a.id_moeda             is not null then a.id_moeda             end ID_MOEDA,',
'                case when a.id_viatransporte     is not null then a.id_viatransporte     end ID_VIATRANSPORTE,',
'                case when a.quantidade_entrega   is not null then a.quantidade_entrega   end QUANTIDADE_ENTREGA,',
'                case when a.id_incoterm          is not null then concatena_id_texto(a.id_incoterm, b.codigo_incoterm) end ID_INCOTERM,',
'                case when a.id_adquirente        is not null then concatena_id_texto(a.id_adquirente, c.nome_completo) end ID_ADQUIRENTE,',
'                case when a.id_comprador         is not null then concatena_id_texto(a.id_comprador, d.nome_completo)  end ID_COMPRADOR,',
'                case when a.id_listapreco        is not null then concatena_id_texto(a.id_listapreco, pkg_traducao.get_traducao(e.descricao_listapreco)) end ID_LISTAPRECO,',
'                case when a.id_endereco_origem   is not null then concatena_id_texto(a.id_endereco_origem, pkg_traducao.get_traducao(f.titulo_endereco)) end ID_ENDERECO_ORIGEM,',
'                case when a.id_local_embarque    is not null then concatena_id_texto(a.id_local_embarque, pkg_traducao.get_traducao(g.nome_local)) end ID_LOCAL_EMBARQUE,',
'                case when a.id_local_desembarque is not null then concatena_id_texto(a.id_local_desembarque, pkg_traducao.get_traducao(h.nome_local)) end ID_LOCAL_DESEMBARQUE,',
'                case when a.id_endereco_destino  is not null then concatena_id_texto(a.id_endereco_destino, pkg_traducao.get_traducao(i.titulo_endereco))  end ID_ENDERECO_DESTINO,',
'                case when a.id_condicaopagamento is not null then concatena_id_texto(a.id_condicaopagamento, pkg_traducao.get_traducao(j.descricao_condicaopagamento)) end ID_CONDICAOPAGAMENTO',
'            from imp_pedidoimportacao a            ',
'            left join ng_incoterm                 b on b.id = a.id_incoterm',
'            left join ng_pessoa                   c on c.id = a.id_adquirente',
'            left join ng_pessoa                   d on d.id = a.id_comprador',
'            left join ng_listapreco               e on e.id = a.id_listapreco',
'            left join ng_pessoa_endereco          f on f.id = a.id_endereco_origem',
'            left join ng_localembarquedesembarque g on g.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque h on h.id = a.id_local_desembarque',
'            left join ng_pessoa_endereco          i on i.id = a.id_endereco_destino',
'            left join ng_condicaopagamento        j on j.id = a.id_condicaopagamento',
'            where a.id_tenant = (',
'                select c002 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_tenant'')',
'            )',
'            and a.ind_modalidade_importacao = (',
'                select c002 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''ind_modalidade_importacao'')',
'            )',
'            and a.id_exportador = (',
'                select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f05_0000'')',
'            )',
'            and a.id_importador = (',
'                select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f07_0000'')',
'            )',
'            order by a.data_inclusao desc ',
'            fetch first 1 row only',
'        ~'';',
'        grava_log2(''UI_MPD_TD498 sql_atribuir_valor_ultimo_pedido:''||l_sql);',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end sql_atribuir_valor_ultimo_pedido;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_endereco_origem'') then',
'            return q''~',
'                where (b.data_fim_vigencia is null ',
'                    or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and c.id_pessoa in (',
'                    select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f05_0000'')',
'                    )',
'            ~'';',
'        elsif upper(p_campo) = upper(''id_endereco_destino'') then',
'            return q''~',
'                where (b.data_fim_vigencia is null',
'                        or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                    )',
'                and c.id_pessoa in (        ',
'                        select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f07_0000'')',
'                    )     ',
'                and (select ',
'                        c003 ',
'                    from apex_collections ',
'                    where collection_name = ''TD498_''||apex_custom_auth.get_session_id ',
'                    and upper(c001) = upper(''f09_0000'')) is null ',
'                    or c.id_pessoa in (        ',
'                        select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f09_0000'')',
'                    )',
'            ~'';',
'        elsif upper(p_campo) = upper(''id_incoterm'') then',
'            return q''~',
'                where '':''||ind_viatransporte_permitida||'':'' like ''%:''||(',
'                    select nv.id from ng_viatransporte nv where nv.id in (',
'                        select c002 from apex_collections ',
'                        where collection_name = ''TD498_''||apex_custom_auth.get_session_id',
'                        and upper(c001) = upper(''id_viatransporte'')',
'                    )',
'                )||'':%''',
'            ~'';',
'        elsif upper(p_campo) = upper(''id_listapreco'') then',
'            return q''~',
'                where to_date(to_char(a.data_inicio_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') <= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                and (',
'                    a.data_fim_vigencia is null',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                )',
'                and a.ind_aplicacao = ''I''',
'                and a.ind_situacao = ''D''',
'                and a.id_exportador = (        ',
'                    select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f05_0000'')        ',
'                )',
'                and a.id_moeda = (    ',
'                    select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f16_0000'')    ',
'                )',
'                and c.id_incoterm = (',
'                    select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f22_0000'')    ',
'                )',
'                and b.id_condicaopagamento = (',
'                    select c003 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f24_0000'')',
'                )',
'            ~'';',
'        elsif upper(p_campo) in (upper(''id_local_embarque''), upper(''id_local_desembarque'')) then',
'            return q''~',
'                where (a.data_fim_vigencia is null',
'                or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy''))',
'                and ((lower(ind_local) = ''p'' ',
'                and exists (',
'                    select 1 from ng_viatransporte where descricao_viatransporte = 1 and id in (',
'                        select c002 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_viatransporte'')',
'                    )',
'                ))',
'                or (lower(ind_local) = ''a'' ',
'                and exists (',
'                    select 1 from ng_viatransporte where descricao_viatransporte = 4 and id in (',
'                        select c002 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_viatransporte'')',
'                    )',
'                ))',
'                or (lower(ind_local) = ''f'' ',
'                and exists (',
'                    select 1 from ng_viatransporte where descricao_viatransporte = 7 and id in (',
'                        select c002 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_viatransporte'')',
'                    )',
'                ))',
'                or exists (',
'                    select 1 from ng_viatransporte where descricao_viatransporte not in (1,4,7) and id in (',
'                        select c002 from apex_collections where collection_name = ''TD498_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_viatransporte'')',
'                    )',
'                ))',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'        l_numero_pedido_importacao varchar2(250);',
'    begin',
'        l_numero_pedido_importacao := bo_imp_pedidoimportacao.retorna_numero_pedido_importacao(apex_application.g_f01(1));',
'        if l_numero_pedido_importacao is null then',
'            l_numero_pedido_importacao := apex_application.g_f02(1);',
'        end if;',
'        bo_imp_pedidoimportacao.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_numero_pedido_importacao => l_numero_pedido_importacao,',
'            p_ind_modalidade_importacao => apex_application.g_f03(1),',
'            p_id_exportador => apex_application.g_f04(1),',
'            p_id_importador => apex_application.g_f06(1),',
'            p_id_adquirente => apex_application.g_f08(1),',
'            p_id_comprador => apex_application.g_f10(1),',
'            p_nome_vendedor => apex_application.g_f12(1),            ',
'            p_numero_proforma => apex_application.g_f14(1),            ',
'            p_id_moeda => apex_application.g_f15(1),            ',
'            p_id_viatransporte => apex_application.g_f19(1),',
'            p_id_incoterm => apex_application.g_f21(1),',
'            p_id_condicaopagamento => apex_application.g_f23(1),',
'            p_quantidade_parcelas_pagamento => apex_application.g_f25(1),',
'            p_id_listapreco => apex_application.g_f26(1),',
'            p_id_endereco_origem => apex_application.g_f28(1),',
'            p_id_local_embarque => apex_application.g_f30(1),',
'            p_id_local_desembarque => apex_application.g_f32(1),',
'            p_id_endereco_destino => apex_application.g_f34(1),',
'            p_quantidade_entrega => apex_application.g_f36(1),            ',
'            p_valor_total_mercadoria => pkg_util.retorna_number(apex_application.g_f37(1)),',
'            p_valor_desconto => pkg_util.retorna_number(apex_application.g_f38(1)),',
'            p_valor_despesa_proforma => pkg_util.retorna_number(apex_application.g_f39(1)),',
'            p_valor_total_condicao_venda => pkg_util.retorna_number(apex_application.g_f40(1)),',
'            p_data_confirmacao_pedido => apex_application.g_f41(1),',
'            p_ind_todos_itens_com_entregas_programadas => ''N'',--apex_application.g_f42(1),',
'            p_ind_status_pedido_importacao => 1,',
'            p_ind_situacao_parcela_pagamento => apex_application.g_f45(1),',
'            p_motivo_desconto => null,',
'            p_valor_total_financeiro => 0,--pkg_util.retorna_number(apex_application.g_f48(1)),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages             ',
'        );',
'    end;',
'',
'    procedure post_save(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_imp_pedidoimportacao.altera_registro_retomar_digitacao(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_numero_pedido_importacao => apex_application.g_f02(1),',
'            p_ind_modalidade_importacao => apex_application.g_f03(1),',
'            p_id_exportador => apex_application.g_f04(1),',
'            p_id_importador => apex_application.g_f06(1),',
'            p_id_adquirente => apex_application.g_f08(1),',
'            p_id_comprador => apex_application.g_f10(1),',
'            p_nome_vendedor => apex_application.g_f12(1),            ',
'            p_numero_proforma => apex_application.g_f14(1),            ',
'            p_id_moeda => apex_application.g_f15(1),            ',
'            p_id_viatransporte => apex_application.g_f19(1),',
'            p_id_incoterm => apex_application.g_f21(1),',
'            p_id_condicaopagamento => apex_application.g_f23(1),',
'            p_quantidade_parcelas_pagamento => apex_application.g_f25(1),',
'            p_id_listapreco => apex_application.g_f26(1),',
'            p_id_endereco_origem => apex_application.g_f28(1),',
'            p_id_local_embarque => apex_application.g_f30(1),',
'            p_id_local_desembarque => apex_application.g_f32(1),',
'            p_id_endereco_destino => apex_application.g_f34(1),',
'            p_quantidade_entrega => apex_application.g_f36(1),            ',
'            p_valor_total_mercadoria => pkg_util.retorna_number(apex_application.g_f37(1)),',
'            p_valor_desconto => pkg_util.retorna_number(apex_application.g_f38(1)),',
'            p_valor_despesa_proforma => pkg_util.retorna_number(apex_application.g_f39(1)),',
'            p_valor_total_condicao_venda => pkg_util.retorna_number(apex_application.g_f40(1)),',
'            p_data_confirmacao_pedido => apex_application.g_f41(1),',
'            p_ind_todos_itens_com_entregas_programadas => apex_application.g_f42(1),',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f43(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_ind_status_pedido_importacao => apex_application.g_f44(1),',
'            p_ind_situacao_parcela_pagamento => apex_application.g_f45(1),',
'            p_motivo_desconto => apex_application.g_f47(1),',
'            p_valor_total_financeiro => pkg_util.retorna_number(apex_application.g_f48(1)),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages             ',
'        );  ',
'    end;',
'',
'    function url_botao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'         l_url clob;',
'     begin',
'         l_url := apex_page.get_url(',
'             p_page => 9010,',
'             p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO'',',
'             p_values => ''TD647,TD647,''||p_param1,',
'             p_triggering_element => ''apex.jQuery("#NEW")'',',
'             -- p_plain_url => true,',
'             p_clear_cache => 9010',
'             );',
'         return l_url;',
'     end url_botao;',
'',
'     function label_botao return varchar2 is',
'     begin',
'         return pkg_ui.retorna_label_botao(''gravar'');',
'     end;',
'',
'     function esconder_botao_wizard return varchar2 is',
'     begin',
'         return ''true'';',
'     end;',
'',
'end "UI_MPD_TD498";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td499
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157387182602329810)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD499'
,p_sequence=>1360
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD499" as',
'',
'   ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD499";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD499" as',
'     ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id, ',
'            pkg_traducao.get_traducao(a.descricao_ncm) titulo,',
'            b.nome_fantasia subtitulo,',
'            case ',
'                when a.data_fim_vigencia is null then',
'                    null',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'            end distintivo,',
'            case ',
'                when a.data_fim_vigencia is null then',
'                    ''u-hidden''',
'                when to_date(a.data_fim_vigencia, ''dd/mm/yyyy'') < to_date(current_date, ''dd/mm/yyyy'') then',
'                    ''data-fim-vigencia''',
'                else',
'                    null',
'            end class_distintivo,                                                 ',
'            null lista_distintivo,',
'            --ATRIBUTOS',
'            pkg_componentes.html_card_colunas(''ng_ncm.codigo_ncm'', a.codigo_ncm, 4) atributo1,            ',
'            pkg_componentes.html_card_colunas(''ng_ncm.id_unidademedida'', upper(c.codigo_unidademedida), 4) atributo2,',
'            pkg_componentes.html_card_colunas(''ng_ncm.observacao'', pkg_traducao.get_traducao(a.observacao), 4',
'            ) atributo3,',
'            --order',
'            a.codigo_ncm order1,',
'            c.codigo_unidademedida order2,',
'            a.data_fim_vigencia order3,',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            null FILTRO_MULT1,',
'            null FILTRO_MULT2,',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD499'', a.id) url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id, ''TD499'') as opcao',
'        from ng_ncm a',
'        join mpd_tenant b on b.id = a.id_tenant        ',
'        join ng_unidademedida c on c.id = a.id_unidademedida',
'        order by #ORDER#',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));       ',
'       return l_sql;       ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'        select ',
'            a.id id,                                                            ',
'            b.nome_fantasia campo1,',
'            a.codigo_ncm campo2,',
'            pkg_traducao.get_traducao(a.descricao_ncm) campo3,',
'            upper(c.codigo_unidademedida) campo4,            ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            a.data_fim_vigencia campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,  ',
'            null campo10, ',
'            --FILTROS',
'            a.id_tenant filtro1,                              ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_ncm a',
'        join mpd_tenant b on b.id = a.id_tenant     ',
'        join ng_unidademedida c on c.id = a.id_unidademedida ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'                id,               ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                to_date(campo6,''DD/MM/YYYY'')campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id, ''TD499'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_ncm'')) a             ',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant order by 1~'';',
'        else',
'            return null;        ',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ncm.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ncm.codigo_ncm'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ncm.descricao_ncm'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ncm.id_unidademedida'') into l_campo from dual;        ',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ncm.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'    ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo4,campo6'';',
'        else',
'            campos := ''subtitulo,order1,titulo,order2,order3'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2'';',
'        else',
'            l_campos := ''order3,subtitulo,order1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD499";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td504
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157387422809325604)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD504'
,p_sequence=>1370
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD504" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD504";',
'/',
'create or replace package body "UI_MPD_TD504" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna_descricao number;                        ',
'        l_id_coluna_observacao number;                        ',
'        l_descricao clob;',
'        l_permite_edicao_descricao varchar2(5);',
'        l_erro_descricao clob;',
'        l_observacao clob;',
'        l_permite_edicao_observacao varchar2(5);',
'        l_erro_observacao clob;',
'        l_url_descricao varchar2(4000);',
'        l_url_observacao varchar2(4000);',
'    begin',
'',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_ncm'';',
'        select id into l_id_coluna_descricao from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_ncm'';         ',
'        select id into l_id_coluna_observacao from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';      ',
'        ',
'        l_url_descricao := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna_descricao, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'        ',
'        l_url_observacao := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna_observacao, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''codigo_ncm'',         3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_ncm'',      4, '''', to_char(l_url_descricao), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_ncm) from ng_ncm where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',   5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''observacao'',         6, '''', to_char(l_url_observacao), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(observacao) from ng_ncm where id = p_param1)) valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 8, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     9, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_ncm WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'              ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'    ',
'end "UI_MPD_TD504";',
'/'))
);
end;
