prompt --application/deployment/install/install_ui_mpd_td508
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157388119012312331)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD508'
,p_sequence=>1380
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD508" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;   ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'    ',
'end "UI_MPD_TD508";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD508" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,  ',
'            pkg_traducao.get_traducao(a.descricao_nbs) titulo,',
'            b.nome_fantasia subtitulo,                        ',
'            case ',
'                when a.data_fim_vigencia is null then',
'                    null',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'            end distintivo,',
'            case ',
'                when a.data_fim_vigencia is null then',
'                    ''u-hidden''',
'                when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    ''data-fim-vigencia''',
'                else',
'                    null',
'            end class_distintivo,                        ',
'            null lista_distintivo,',
'            --ATRIBUTOS',
'            pkg_componentes.html_card_colunas(''ng_nbs.codigo_nbs'', a.codigo_nbs, 4) atributo1,            ',
'            --order',
'            a.codigo_nbs order1,',
'            a.data_fim_vigencia order2,',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            null FILTRO_MULT1,',
'            null FILTRO_MULT2,  ',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD508'', a.id) as url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id, ''TD508'') as opcao  ',
'        from ng_nbs a',
'        left join mpd_tenant b on b.id = a.id_tenant',
'        order by #ORDER#',
'        ~'';      ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));       ',
'        return l_sql;       ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin ',
'        l_sql := q''~',
'        select ',
'            a.id id,                                                            ',
'            b.nome_fantasia campo1,',
'            a.codigo_nbs campo2,',
'            pkg_traducao.get_traducao(a.descricao_nbs) campo3,            ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,                        ',
'            a.data_fim_vigencia campo5,             ',
'            null campo6,             ',
'            null campo7,                                      ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,                                ',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            null filtro2,                                                                                ',
'            null filtro3,                                                                                ',
'            null filtro4,                                                                                ',
'            null filtro5,                                                                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5, ',
'            null opcao',
'        from ng_nbs a',
'        join mpd_tenant b on b.id = a.id_tenant        ',
'       ~'';        ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select  ',
'                id,              ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id, ''TD508'') as opcao ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_nbs'')) a  ',
'            order by #ORDER#',
'            ~'';        ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_nbs.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_nbs.codigo_nbs'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_nbs.descricao_nbs'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_nbs.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'    ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo5'';',
'        else',
'            campos := ''subtitulo,order1,titulo,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2'';',
'        else',
'            l_campos := ''order2,subtitulo,order1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD508";',
'/'))
);
end;
/
