prompt --application/deployment/install/install_ui_mpd_td514
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157388620045285652)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD514'
,p_sequence=>1400
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD514" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD514";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD514" as    ',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id ,                                                            ',
'            a.id_tenant,',
'            a.codigo_naladi titulo,',
'            pkg_traducao.get_traducao(a.descricao_naladi) subtitulo, ',
'            case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                a.data_fim_vigencia,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'            null lista_distintivo,',
'            --order',
'            b.nome_fantasia order1,',
'            a.data_fim_vigencia order2,',
'            a.id_tenant filtro1,',
'            null filtro2,',
'            null filtro3,                               ',
'            null filtro4,',
'            null filtro5,',
'            null FILTRO_MULT1,',
'            null FILTRO_MULT2,  ',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD514'',a.id) url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id,''TD514'') as opcao ',
'            from ng_naladi a',
'            join mpd_tenant b on b.id = a.id_tenant             ',
'            order by #ORDER#',
'            ~'';',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'            return l_sql; ',
'    end sql_card;',
'',
'',
'         function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'',
'        l_sql := q''~',
'        select ',
'            a.id,                                                            ',
'            b.nome_fantasia campo1,',
'            a.codigo_naladi campo2,',
'            pkg_traducao.get_traducao(a.descricao_naladi) campo3,   ',
'             case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            a.data_fim_vigencia campo5,   ',
'            null campo6,                     ',
'            null campo7,                                      ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,  ',
'            --FILTROS',
'            a.id_tenant filtro1,                                ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                              ',
'            null opcao',
'        from ng_naladi a',
'         join mpd_tenant b on b.id = a.id_tenant             ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select  ',
'                id,              ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD514'') as opcao ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_naladi'')) a ',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then             ',
'            return q''~select nome_fantasia d, id r from mpd_tenant order by 1~''; ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro; ',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_naladi.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_naladi.codigo_naladi'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_naladi.descricao_naladi'') into l_campo from dual;',
'         elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_naladi.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;   ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo5'';',
'        else',
'            campos := ''order1,titulo,subtitulo,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2'';',
'        else',
'            l_campos := ''order2,order1,titulo'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD514";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td518
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157388833708282232)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD518'
,p_sequence=>1410
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD518" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'end "UI_MPD_TD518";',
'/',
'create or replace package body "UI_MPD_TD518" as',
'',
'     procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'        l_somente_leitura varchar2(1);',
'    begin',
'',
'       select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_naladi'';',
'       select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_naladi'';      ',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'',
'       MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''descricao_naladi'',     4, '''', to_char(l_url), l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao_naladi) from ng_naladi where id = p_param1)) valor FROM dual UNION ALL        ',
'               SELECT p_codigo_artefato, ''codigo_naladi'',        3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',   7, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',       8, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_naladi WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'              ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD518";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td521
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157389052545278645)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD521'
,p_sequence=>1420
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD521" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'',
'end "UI_MPD_TD521";',
'/',
'create or replace package body "UI_MPD_TD521" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id ,',
'            pkg_util.retorna_descricao_ou_traducao(',
'                    p_nome_entidade => ''ng_feriado'',',
'                    p_nome_coluna => ''nome_feriado'',',
'                    p_id_idioma_tenant => c.id_idioma,',
'                    p_id_chave_entidade => a.id',
'                )                                 titulo,',
'            a.data_feriado                        subtitulo,                                      ',
'            a.ind_recorrente                      distintivo,',
'            null                                  lista_distintivo,',
'            null                                  class_distintivo,',
'            --FILTROS',
'            a.id_tenant                           filtro1,',
'            null                                  FILTRO_MULT1,',
'            null                                  FILTRO_MULT2,  ',
'            --TECNICO',
'            pkg_ui.url_mais_detalhes(''TD521'',a.id) url_mais_detalhes,',
'            pkg_componentes.html_botao_opcao(a.id,''TD521'') as opcao  ',
'        from ng_feriado a',
'        left join mpd_pais b on b.id = a.id_pais  ',
'        left join mpd_tenant c on c.id = a.id_tenant',
'        order by to_date(data_feriado) ',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'        return clob is',
'            l_sql clob;',
'            ',
'        begin   ',
'            l_sql := q''~',
'             select ',
'            a.id id,',
'            c.nome_fantasia                                          campo1,',
unistr('            DECODE(UPPER(a.ind_recorrente), ''S'', ''Sim'', ''N'', ''N\00E3o'')  campo2,'),
'            case when a.ind_recorrente = ''S'' then',
'                 pkg_data.fmtd(a.data_feriado, ''DATA_DIA_MES'')',
'            else',
'                pkg_data.fmtd(a.data_feriado, ''DATA'')',
'            end                                                      campo3,                          ',
'            a.nome_feriado                                           campo4, ',
'            pkg_util.retorna_descricao_ou_traducao(',
'                    p_nome_entidade => ''ng_pais'',',
'                    p_nome_coluna => ''nome_pais'',',
'                    p_id_idioma_tenant => c.id_idioma,',
'                    p_id_chave_entidade => b.id',
'                )                                                    campo5,                                      ',
'            null                                                     campo6,                                                  ',
'            null                                                     campo7,                                      ',
'            null                                                     campo8,                                      ',
'            null                                                     campo9,',
'            null                                                     campo10,    ',
'            --FILTROS',
'            a.id_tenant                                              filtro1,                                ',
'            null                                                     filtro2,                                ',
'            null                                                     filtro3,                                ',
'            null                                                     filtro4,',
'            null                                                     filtro5,                                ',
'            --FILTROS MULTI',
'            null                                                     filtro_mult1,                                ',
'            null                                                     filtro_mult2,                                ',
'            null                                                     filtro_mult3, ',
'            null                                                     filtro_mult4,                                ',
'            null                                                     filtro_mult5,                                 ',
'            null opcao',
'        from ng_feriado a',
'        left join ng_pais b on b.id = a.id_pais   ',
'        join mpd_tenant c on c.id = a.id_tenant',
'     ',
'       ~''; ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin   ',
'        return q''~',
'            select  ',
'                id,              ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD521'') as opcao  ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''NG_FERIADO'')) a ',
'            --order by to_date(campo2, ''dd/mm/yyyy''), campo1',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_feriado.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_tela(''feriado'') into l_campo from dual;            ',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_feriado.data_feriado'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_feriado.nome_feriado'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_tela(''pais'') into l_campo from dual;      ',
'        elsif campo = ''F1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_feriado.id_tenant'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''nome_feriado,ind_recorrente'';',
'        else',
'            campos := ''campo2,campo3'';',
'        end if;',
'        labels := label_coluna(''2'')||'',''||label_coluna(''3'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD521";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td524
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157389230900274157)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD524'
,p_sequence=>1430
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD524" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'end "UI_MPD_TD524";',
'/',
'create or replace package body "UI_MPD_TD524" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_link_cadastro varchar2(4000);',
'    begin',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''mpd_feriado'';',
'        l_link_cadastro := bo_srv_idioma.retorna_link_cadastro(p_pagina=>9006,p_itens=>''P0_CODIGO_ARTEFATO,P9006_CODIGO_ARTEFATO,P9006_PARAMETRO,P9006_PARAMETRO2'',p_valores=>''TD386,TD386,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_entidade)'
||';                ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, ''R_MPD_TENANT.NOME_FANTASIA'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' coluna_tabela, NULL valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_feriado'',       3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''id_pais'',            4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''ind_recorrente'',     5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                                                                                                     ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 6, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     7, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_feriado WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'              ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD524";',
'/'))
);
end;
