prompt --application/deployment/install/install_ui_mpd_td537_v1
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157389975735259755)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD537_V1'
,p_sequence=>1460
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD537_V1" as',
'',
'    --function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD537_V1";',
'/',
'create or replace package body "UI_MPD_TD537_V1" as',
'',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_id_entidade number;   ',
'        l_nome_entidade varchar2(250);',
'        l_nome_coluna varchar2(250);',
'        l_consulta_dinamica varchar2(4000);',
'        l_verifica_coluna_vigencia number;',
'        l_data_fim_vigencia varchar2(4000);     ',
'    begin  ',
'        select nome_entidade, nome_coluna into l_nome_entidade, l_nome_coluna from srv_entidade a join srv_entidade_coluna b on b.id_entidade = a.id where b.id = p_param2; ',
'        select count(1) into l_verifica_coluna_vigencia from srv_entidade_coluna a join srv_entidade b on b.id = a.id_entidade where b.nome_entidade = l_nome_entidade and lower(a.nome_coluna) = ''data_fim_vigencia'';',
'        if l_verifica_coluna_vigencia > 0 then',
'            l_data_fim_vigencia := ''case ',
'                    when a1.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a1.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''''ng_traducaotexto.data_fim_vigencia'''', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a1.data_fim_vigencia, ''''DATA'''')), 3) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''''ng_traducaotexto.data_fim_vigencia'''', pkg_data.fmtd(a1.data_fim_vigencia, ''''DATA''''), 3) ',
'                end '';',
'        else',
'            l_data_fim_vigencia := ''null'';',
'        end if;',
'        l_consulta_dinamica := ''',
'            union',
'            select ',
'                a1.id,                 ',
'                pkg_traducao.get_traducao(c.descricao_idioma) titulo,',
'                b1.nome_fantasia subtitulo, ',
'                null distintivo,',
'                ''''u-hidden'''' class_distintivo, ',
'                null icon,                                      ',
'                null lista_distintivo, ',
'                pkg_componentes.html_card_colunas(''''ng_traducaotexto.texto_traduzido'''', a1.''||l_nome_coluna||'', 3) atributo1,                ',
'                null atributo2,',
'                null atributo3,',
'                ''||l_data_fim_vigencia||'' atributo4,                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,                 ',
'                pkg_ui.url_mais_detalhes(''''TD492'''', a1.id) url_mais_detalhes,',
'                --null opcao',
'                pkg_componentes.html_botao_opcao(p_id => a1.id, p_pagina => ''''TD492'''', p_param1 => ''||p_param2||'') as opcao                 ',
'            from ''||l_nome_entidade||'' a1',
'            join mpd_tenant b1 on b1.id = a1.id_tenant ',
'            left join srv_idioma c on c.id = b1.id_idioma',
'            where a1.id = ''||p_param1;',
'        -- ',
'        select id_entidade into l_id_entidade from mpd_entidade_coluna where to_char(id) = p_param2;',
'        l_sql := q''~',
'            select distinct',
'               a.id,',
'               pkg_traducao.get_traducao(c.descricao_idioma) titulo,',
'               b.nome_fantasia subtitulo,',
'               null distintivo,',
'               ''u-hidden'' class_distintivo, ',
'               null icon,                                      ',
'               null lista_distintivo,  ',
'               --ATRIBUTOS',
'               pkg_componentes.html_card_colunas(''ng_traducaotexto.texto_traduzido'', a.texto_traduzido, 3) atributo1, --11',
'               pkg_componentes.html_card_colunas(''ng_traducaotexto.id_finalidade'', pkg_traducao.get_traducao(a.descricao), 3',
'                ) atributo2,',
'                case ',
'                    when a.id_pessoa is not null then',
'                        pkg_componentes.html_card_colunas(pkg_ui.retorna_label_tela(''ng_traducaotexto.para''), a.id_pessoa, 3, ''s'')',
'                    when a.id_pais is not null then',
'                        pkg_componentes.html_card_colunas(pkg_ui.retorna_label_tela(''ng_traducaotexto.para''),pkg_traducao.get_traducao(e.nome_pais), 3, ''s''',
'                        )',
'                else',
'                    null',
'                end atributo3,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_traducaotexto.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 3) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_traducaotexto.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 3) ',
'                end atributo4,',
'               --FILTRO',
'               null FILTRO_MULT1,',
'               null FILTRO_MULT2,  ',
'               --TECNICO               ',
'               pkg_ui.url_mais_detalhes(''TD537'', a.id) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(a.id,''TD537'') as opcao                ',
'            from ng_traducaotexto a ',
'            join mpd_tenant b on b.id = a.id_tenant    ',
'            left join srv_idioma c on c.id = a.id_idioma    ',
'            left join ng_finalidade_uso_texto d on d.id = a.id_finalidade',
'            left join ng_pais e on e.id = a.id_pais',
'            where a.id_entidade = ~''||l_id_entidade||q''~',
'            and a.id_chave_entidade = #PARAM1#',
'            and a.id_campo = #PARAM2#',
'            #UNION#',
'            order by titulo',
'            ~'';',
'            l_sql := replace(l_sql,''#PARAM1#'',nvl(p_param1,0));',
'            l_sql := replace(l_sql,''#PARAM2#'',nvl(p_param2,0));',
'            l_sql := replace(l_sql, ''#UNION#'', nvl(l_consulta_dinamica, ''''));',
'            --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));',
'        return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_id_entidade number;',
'        l_nome_entidade varchar2(250);',
'        l_nome_coluna varchar2(250);',
'        l_consulta_dinamica varchar2(4000);',
'        l_verifica_coluna_vigencia number;',
'        l_data_fim_vigencia varchar2(4000);',
'    begin         ',
'        select nome_entidade, nome_coluna into l_nome_entidade, l_nome_coluna from srv_entidade a join srv_entidade_coluna b on b.id_entidade = a.id where b.id = p_param2; ',
'        select count(1) into l_verifica_coluna_vigencia from srv_entidade_coluna a join srv_entidade b on b.id = a.id_entidade where b.nome_entidade = l_nome_entidade and lower(a.nome_coluna) = ''data_fim_vigencia'';',
'        if l_verifica_coluna_vigencia > 0 then',
'            l_data_fim_vigencia := ''pkg_data.fmtd(a1.data_fim_vigencia, ''''DATA'''')'';',
'        else',
'            l_data_fim_vigencia := ''null'';',
'        end if;',
'        l_consulta_dinamica := ''',
'            union',
'            select ',
'                a1.id id, ',
'                b1.nome_fantasia campo1, ',
'                pkg_traducao.get_traducao(c.descricao_idioma) campo2,',
'                ''||l_nome_coluna||'' campo3,',
'                null campo4,',
'                null campo5,',
'                ''||l_data_fim_vigencia||'' campo6,',
'                null campo7,',
'                null campo8,',
'                ''||p_param2||'' campo9,',
'                null campo10,',
'                null filtro1, ',
'                null filtro2, ',
'                null filtro3, ',
'                null filtro4, ',
'                null filtro5,                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,                 ',
'                null FILTRO_MULT3,                 ',
'                null FILTRO_MULT4,                 ',
'                null FILTRO_MULT5,                ',
'                pkg_componentes.html_botao_opcao(a1.id,''''TD537'''') opcao',
'            from ''||l_nome_entidade||'' a1',
'            join mpd_tenant b1 on b1.id = a1.id_tenant ',
'            left join srv_idioma c on c.id = b1.id_idioma ',
'            where a1.id = ''||p_param1;',
'        --',
'        select id_entidade into l_id_entidade from mpd_entidade_coluna where to_char(id) = p_param2; ',
'        l_sql := q''~',
'        select distinct',
'               a.id id,',
'               b.nome_fantasia campo1,',
'               pkg_traducao.get_traducao(c.descricao_idioma campo2,',
'               a.texto_traduzido campo3,',
'               pkg_traducao.get_traducao(d.descricao) campo4,',
'               case ',
'                when a.id_pessoa is not null then',
unistr('                    to_char(a.id_pessoa) -- entidade ng_pessoa ainda n\00E3o existe 11/04/2025'),
'                when a.id_pais is not null then',
'                    tpkg_traducao.get_traducao(ng_pais)',
'                else ',
'                    null',
'               end campo5,    ',
'               case ',
'                when a.data_fim_vigencia < current_date then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'               end campo6,               ',
'               null campo7,     ',
'               null campo8,     ',
'               null campo9,     ',
'               ''TD537'' campo10,                                               ',
'               --FILTROS',
'               null filtro1, ',
'               null filtro2, ',
'               null filtro3, ',
'               null filtro4, ',
'               null filtro5, ',
'               --FILTROS MULTI',
'               null FILTRO_MULT1,',
'               null FILTRO_MULT2,                 ',
'               null FILTRO_MULT3,                 ',
'               null FILTRO_MULT4,                 ',
'               null FILTRO_MULT5,                 ',
'               pkg_componentes.html_botao_opcao(a.id,''TD537'') opcao               ',
'        from ng_traducaotexto a ',
'        join mpd_tenant b on b.id = a.id_tenant',
'        left join srv_idioma c on c.id = a.id_idioma    ',
'        left join ng_finalidade_uso_texto d on d.id = a.id_finalidade    ',
'        left join ng_pais e on e.id = a.id_pais',
'        where a.id_entidade = ~''||l_id_entidade||q''~',
'        and a.id_chave_entidade = #PARAM1#   ',
'        and a.id_campo = #PARAM2#                      ',
'        #UNION#         ',
'             ',
'        ~'';                   ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        l_sql := replace(l_sql, ''#PARAM2#'', p_param2);        ',
'        l_sql := replace(l_sql, ''#UNION#'', nvl(l_consulta_dinamica, ''''));',
'        return l_sql;        ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'        l_pagina varchar2(50);',
'    begin           ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                                 ',
'                case ',
'                    when campo10 = ''TD537'' then',
'                        pkg_componentes.html_botao_opcao(id,''TD537'')',
'                    else',
'                        pkg_componentes.html_botao_opcao(p_id => id, p_pagina => ''TD492'', p_param1 => campo9) ',
'                end opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_traducaotexto'')) a',
'            order by campo2',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));',
'        return l_sql;        ',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin ',
'        -- if campo = ''1'' then',
'        --     return q''~select nome d, id r from mpd_idioma~'';        ',
'        -- else',
'            return null;          ',
'        --end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''ng_traducaotexto.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_traducaotexto.id_idioma'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_traducaotexto.texto_traduzido'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_traducaotexto.id_finalidade'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_tela(''ng_traducaotexto.para'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''ng_traducaotexto.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function colunas_ordenar',
'    return clob is',
'        l_campo clob;',
'    begin',
'        return q''~ select null d, null r from dual ~'';',
'    end colunas_ordenar;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''id_idioma,id_finalidade,para,texto_traduzido'';',
'        else',
'            campos := ''campo2,campo4,campo5,campo3'';',
'        end if;',
'        labels := label_coluna(''2'')||'',''||label_coluna(''4'')||'',''||label_coluna(''5'')||'',''||label_coluna(''3'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD537_V1";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td540
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157390107299256532)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD540'
,p_sequence=>1470
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD540" as   ',
'',
'    --function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null);    ',
'   ',
'end "UI_MPD_TD540";',
'/',
'create or replace package body "UI_MPD_TD540" as    ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) is                    ',
'        l_dominio_ind_texto_original varchar2(10);',
'    begin        ',
'        --select pkg_util.dominio_retorna_tag(''mpd_traducaotextoespecifico'', ''ind_texto_original'', ind_texto_original) into l_dominio_ind_texto_original from mpd_traducaotextoespecifico where id = p_param1;',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma'',          9, ''SEL'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''texto_traduzido'',    10, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_finalidade'',      11, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',          13, '''', null, ''N'',''S'', null valor FROM dual UNION ALL                ',
'               SELECT p_codigo_artefato, ''id_pais'',            15, '''', null, ''N'',''S'', null valor FROM dual UNION ALL                ',
'               --SELECT p_codigo_artefato, ''id_carta_credito'',   17, ''TXT'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               --SELECT p_codigo_artefato, ''ind_texto_original'', 19, ''TXT'', null, ''N'',''S'', l_dominio_ind_texto_original valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 22, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     23, ''TXT'', null, ''N'',''S'', pkg_data.fmt((select data_alteracao from mpd_traducaotextoespecifico where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);        ',
'    end formulario;   ',
'',
'end "UI_MPD_TD540";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td543
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157390451542252738)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD543'
,p_sequence=>1480
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD543" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'    ',
'end "UI_MPD_TD543";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD543" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,                ',
'                pkg_traducao.get_traducao(a.nome_local) titulo,  ',
'                b.nome_fantasia subtitulo,',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,                ',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_localembarquedesembarque.ind_local'', ',
'                    pkg_util.dominio_retorna_tag(''ng_localembarquedesembarque'', ''ind_local'', a.ind_local), 3',
'                ) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_localembarquedesembarque.id_pais'',                     ',
'                pkg_traducao.get_traducao(c.nome_pais), 3) atributo2,',
'                pkg_componentes.html_card_colunas(''ng_localembarquedesembarque.id_cidade'',                     ',
'                pkg_traducao.get_traducao(d.nome_cidade), 3) atributo3,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_localembarquedesembarque.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 3) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_localembarquedesembarque.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 3) ',
'                end atributo4,',
'                a.data_fim_vigencia,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                a.id_pais filtro2,',
'                a.ind_local filtro3,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD543'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD543'') as opcao                ',
'            from ng_localembarquedesembarque a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_pais c on c.id = a.id_pais',
'            left join ng_cidade d on d.id = a.id_cidade',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));',
'            --order by 3, 8, 9 nulls first, 7, 2, 11 nulls first',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            pkg_traducao.get_traducao(c.nome_pais) campo2,',
'            pkg_traducao.get_traducao(d.nome_cidade) campo3,',
'            pkg_util.dominio_retorna_tag(''ng_localembarquedesembarque'', ''ind_local'', a.ind_local) campo4,',
'            pkg_traducao.get_traducao(a.nome_local) campo5,   ',
'            case ',
'                when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo6,',
'            a.data_fim_vigencia campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            a.id_tenant filtro1, ',
'            a.id_pais filtro2,',
'            a.ind_local filtro3,                              ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_localembarquedesembarque a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_pais c on c.id = a.id_pais',
'        left join ng_cidade d on d.id = a.id_cidade',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD543'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_localembarquedesembarque'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));',
'        --order by campo1, campo2, campo3 nulls first, campo4, campo5, to_date(campo7, ''dd/mm/yyyy'') nulls first                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select ',
'                    to_char(chamar_webservice_traducao(',
'                        p_esquema           => esquema_corrente,',
'                        p_entidade          => ''ng_pais'',',
'                        p_campo             => ''nome_pais'',',
'                        p_id_idioma_usuario => apex_util.get_session_state(''IDIOMA_LOGADO''),',
'                        p_id_registro       => id',
'                    )) d, ',
'                    id r ',
'                from ng_pais',
'                ~'';',
'        elsif campo = ''3'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_localembarquedesembarque'', ''ind_local'')~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_tenant'') into l_campo from dual;',
'        elsif campo in (''2'', ''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_pais'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_cidade'') into l_campo from dual;',
'        elsif campo in (''4'', ''F3'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.ind_local'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.nome_local'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo7,campo1,campo2,campo3,campo4,campo5'';',
'        else',
'            campos := ''data_fim_vigencia,nome_fantasia,atributo2,atributo3,atributo1,titulo'';',
'        end if;',
'',
'        select label_coluna(''6'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''6'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo7,campo1,campo2,campo3,campo4,campo5'';',
'        else',
'            l_campos := ''data_fim_vigencia,nome_fantasia,atributo2,atributo3,atributo1,titulo'';',
'        end if;',
'',
'        l_direcoes := ''DES,ASC,ASC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD543";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td544
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157391674833233529)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD544'
,p_sequence=>1490
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 30/06/2026',
unistr('-- Motivo: Inclus\00E3o da coluna codigo_internacional na entidade ng_localembarquedesembarque'),
'-- Jira: PNG-453',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD544" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'end "UI_MPD_TD544";',
'/',
'',
'create or replace package body "UI_MPD_TD544" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        l_consulta clob; ',
'        l_atribuir_valor_estado clob; ',
'        l_campos apex_t_varchar2 := apex_t_varchar2(''ESTADO'',''SIGLA'');',
'    begin         ',
'        prc_enviar_parametros(''TD544'',''id_pais'',p_param1);',
'        l_consulta := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(nome_cidade), a.id, 1 from ng_cidade a where a.id_pais = (select id from ng_pais where nome_pais = ( select c002 from apex_co'
||'llections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f06_0000'''')))) order by ordem, d '';',
'',
'        l_atribuir_valor_estado := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor'',',
'            l_campos',
'        );',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null atribuir_valor FROM dual UNION ALL       '
||'     ',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',     2, ''SEL'', ''R_MPD_TENANT.DESCRICAO_IDIOMA'', ''S'',''N'', null valor, null atribuir_valor FROM dual UNION ALL                              ',
'               SELECT p_codigo_artefato, ''nome_local'',            3, '''', null, ''N'',''S'', null valor, null atribuir_valor FROM dual UNION ALL   ',
'               SELECT p_codigo_artefato, ''ind_local'',             4, '''', null, ''N'',''S'', null valor, null atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_pais'',               5, '''', null, ''N'',''S'', null valor, null atribuir_valor FROM dual UNION ALL',
'               --SELECT p_codigo_artefato, ''ESTADO'',                12, ''TXT'', null, ''N'',''N'', null valor, null atribuir_valor FROM dual UNION ALL',
'               --SELECT p_codigo_artefato, ''SIGLA'',                 14, ''TXT'', null, ''N'',''N'', null valor, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cidade'',             7, ''POP1'', to_char(l_consulta), ''N'',''S'', null valor, l_atribuir_valor_estado atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidade_local_rfb'',  9, '''', null, ''N'',''S'', null valor, null atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''codigo_internacional'', 11, '''', null, ''N'',''S'', null valor, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    12, '''', null, ''N'',''S'', null valor, null atribuir_valor FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,atribuir_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor,new_data.atribuir_valor);',
'    end formulario;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_cidade'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_pais in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD544_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f06_0000'')',
'                    )',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'     end;',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~ ',
'                    select nome_estado estado, sigla_uf sigla',
'                    from ng_estado a',
'                    join ng_cidade b on a.id = b.id_estado',
'                    where b.id = #ID#  ',
'               ~'';',
'        return replace(l_sql,''#ID#'',p_param1);',
'    end sql_atribuir_valor;',
'',
'    procedure post(',
'        p_id in number,    ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_ng_localembarquedesembarque.inclui_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),  ',
'            p_nome_local => apex_application.g_f03(1),',
'            p_ind_local => apex_application.g_f04(1),',
'            p_id_pais => apex_application.g_f05(1),',
'            p_id_cidade => apex_application.g_f07(1),',
'            p_id_unidade_local_rfb => apex_application.g_f09(1),',
'            p_codigo_internacional => UPPER(apex_application.g_f11(1)),',
'            p_data_fim_vigencia => apex_application.g_f12(1),',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'end "UI_MPD_TD544";',
'/'))
);
end;
