'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD545" as',
'',
'    -- function retorna_display(        ',
'    --     p_id in varchar2 default null, ',
'    --     p_param1 in varchar2 default null,',
'    --     p_param2 in varchar2 default null',
'    -- ) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'        function where_dinamico(p_campo in varchar2) return clob;',
'',
'',
'end "UI_MPD_TD545";',
'/',
'',
'create or replace package body "UI_MPD_TD545" as',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);',
'        l_consulta clob;',
'        l_id_cidade number;',
'        l_nome_pais varchar2(255);',
'        l_url varchar2(4000); ',
'    begin',
'        select nome_pais into l_nome_pais from ng_pais a join ng_localembarquedesembarque b on b.id_pais = a.id where b.id = p_param1;',
'        prc_enviar_parametros2(p_codigo_artefato,''f06_0000'',l_nome_pais,apex_custom_auth.get_session_id);',
'        ',
'        select id_cidade into l_id_cidade from ng_localembarquedesembarque where id = p_param1;',
'        prc_enviar_parametros(''TD545'',''id_pais'',p_param1);',
'        --l_consulta := ''select nome_cidade d, id r from ng_cidade where id_pais = (select id from ng_pais where nome_pais = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' '
||'and upper(c001) = upper(''''f06_0000''''))) order by 1'';        ',
'        l_consulta := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(nome_cidade), a.id, 1 from ng_cidade a where a.id_pais = (select id from ng_pais where nome_pais = ( select c002 from apex_co'
||'llections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f06_0000'''')))) order by ordem, d '';          ',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_localembarquedesembarque'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_local'';         ',
'        ',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, null AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL            ',
'               SELECT p_codigo_artefato, ''nome_local'',            3, '''', to_char(l_url), l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(nome_local) from ng_localembarquedesembarque where id = p_param1)) valor FROM dual UNION ALL   ',
'               SELECT p_codigo_artefato, ''ind_local'',             4, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_pais'',               5, '''', (SELECT c002 FROM apex_collections WHERE collection_name = ''COLLECTION_PADRAO'' AND UPPER(c001) = UPPER(''id_pais'')), ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cidade'',             7, ''POP1'', to_char(l_consulta), ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidade_local_rfb'',  9, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''codigo_internacional'', 11, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL          ',
'               SELECT p_codigo_artefato, ''data_alteracao'',       13, '''', null, ''S'',''S'', null valor FROM dual      ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);        ',
'    end formulario;',
'',
'    function where_dinamico(',
'        p_campo in varchar2',
'    ) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_cidade'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.id_pais in (',
'                    select c003 ',
'                      from apex_collections ',
'                     where collection_name = ''TD545_''||apex_custom_auth.get_session_id ',
'                       and upper(c001) = upper(''f06_0000'')',
'                )',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )',
'    is        ',
'    begin',
'        bo_ng_localembarquedesembarque.altera_registro(  ',
'            p_id_tenant => apex_application.g_f02(1),                     ',
'            p_nome_local => apex_application.g_f03(1),',
'            p_ind_local => apex_application.g_f04(1),',
'            p_id_pais => apex_application.g_f05(1),',
'            p_id_cidade => apex_application.g_f07(1),',
'            p_id_unidade_local_rfb => apex_application.g_f09(1),',
'            p_codigo_internacional => UPPER(apex_application.g_f11(1)),',
'            p_data_fim_vigencia => apex_application.g_f12(1),',
'            p_id => p_id,                        ',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f13(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD545";',
'/'))
);
end;
