'               SELECT p_codigo_artefato, ''nome_local'',           3, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(nome_local) from ng_localembarquedesembarque where id = p_param1)) valor FROM dual UNION ALL   ',
