'               SELECT p_codigo_artefato, ''data_alteracao'',      11, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_localembarquedesembarque WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                ',
'              ) new_data',
