prompt --application/deployment/install/install_ui_mpd_td549
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157392494582183065)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD549'
,p_sequence=>1520
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD549" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'        function where_dinamico(p_campo in varchar2) return clob;',
'',
'end "UI_MPD_TD549";',
'/',
'create or replace package body "UI_MPD_TD549" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is               ',
'        l_html clob;',
'    begin                                ',
'        if p_param2 = ''TD600'' then',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select a.nome_abreviado from ng_pessoa_fisica a where a.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_fisica''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        else',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select a.nome_fantasia from ng_pessoa_juridica a where a.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_juridica''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        end if;',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        l_consulta_estado clob;',
'        l_consulta_cidade clob; ',
'        l_id_pessoa number;   ',
'        l_verifica_ind_endereco_principal number;',
'        l_valor_ind_endereco_principal varchar2(1);',
'        l_valor_somente_leitura varchar2(1) := ''N'';',
'    begin ',
'        if p_param2 = ''TD600'' then',
'            select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_param1;',
'            select count(1) into l_verifica_ind_endereco_principal from ng_pessoa_fisica a join ng_pessoa_endereco b on b.id_pessoa = a.id_pessoa where a.id = p_param1 and lower(b.ind_endereco_principal) = ''s'';',
'            if l_verifica_ind_endereco_principal > 0 then',
'                l_valor_ind_endereco_principal := ''N'';',
'                l_valor_somente_leitura := ''S'';',
'            end if;',
'        else',
'            select id_pessoa into l_id_pessoa from ng_pessoa_juridica where id = p_param1;',
'            select count(1) into l_verifica_ind_endereco_principal from ng_pessoa_juridica a join ng_pessoa_endereco b on b.id_pessoa = a.id_pessoa where a.id = p_param1 and lower(b.ind_endereco_principal) = ''s'';',
'            if l_verifica_ind_endereco_principal > 0 then',
'                l_valor_ind_endereco_principal := ''N'';',
'                l_valor_somente_leitura := ''S'';',
'            end if;',
'        end if;        ',
'',
'        prc_enviar_parametros(''TD549'',''id_pais'',p_param1);',
'        prc_enviar_parametros(''TD549'',''id_estado'',p_param1);',
'        l_consulta_estado := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(a.nome_estado), id, 1 from ng_estado a where id_pais = (select id from ng_pais np where pkg_traducao.get_traducao(np.n'
||'ome_pais) = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f07_0000''''))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_da'
||'te(current_date))) order by ordem, d'';        ',
'        l_consulta_cidade := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(a.nome_cidade), a.id, 1 from ng_cidade a where a.id_pais = (select np.id from ng_pais np where pkg_traducao.get_traduc'
||'ao(np.nome_pais) = (select c002 from apex_collections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f07_0000''''))) and ((select c002 from apex_collections where collection_n'
||'ame = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f09_0000'''')) is null or a.id_estado = (select ne.id from ng_estado ne where pkg_traducao.get_traducao(ne.nome_estado) = (select c002 from apex_c'
||'ollections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f09_0000'''')))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_date(current_date))) order by'
||' ordem, d'';',
'',
'',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa where id = l_i'
||'d_pessoa)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',               2, ''HID'', null, ''N'',''S'', to_char(l_id_pessoa) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',       3, ''SEL'', ''R_MPD_TENANT.DESCRICAO_IDIOMA'', ''S'',''N'', to_char((select id_tenant from ng_pessoa where id = l_id_pessoa)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''titulo_endereco'',         4, ''HID'', null, ''S'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_postal'',           5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais'',                 6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_estado'',               8, ''POP1'', to_char(l_consulta_estado), ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cidade'',              10, ''POP1'', to_char(l_consulta_cidade), ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''bairro'',                 12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''logradouro'',             13, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero'',                 14, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''complemento'',            15, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''etiqueta_endereco'',      16, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_endereco_principal'', 17, '''', null, l_valor_somente_leitura,''S'', l_valor_ind_endereco_principal valor FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'',
'        function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_estado'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_pais in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD549_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f07_0000'')',
'                    )',
'                ~'';',
'             elsif  upper(p_campo) = upper(''id_cidade'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_estado in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD549_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f09_0000'')',
'                    )',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'         end;',
'',
'    procedure post(',
'        p_id in number,    ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;                      ',
'    begin',
'        bo_ng_pessoa_endereco.inclui_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),            ',
'            p_id_pessoa => apex_application.g_f02(1),',
'            p_titulo_endereco => apex_application.g_f04(1),',
'            p_codigo_postal => apex_application.g_f05(1),',
'            p_id_pais => apex_application.g_f06(1),',
'            p_id_estado => apex_application.g_f08(1),',
'            p_id_cidade => apex_application.g_f10(1),',
'            p_bairro => apex_application.g_f12(1),',
'            p_logradouro => apex_application.g_f13(1),',
'            p_numero => apex_application.g_f14(1),',
'            p_complemento => apex_application.g_f15(1),',
'            p_etiqueta_endereco => replace(replace(apex_application.g_f16(1), chr(13), ''''), chr(10), ''<br/>''),',
'            p_ind_endereco_principal => apex_application.g_f17(1),',
'            p_data_integracao => null,',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'end "UI_MPD_TD549";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td550
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157392640075179870)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD550'
,p_sequence=>1530
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD550" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    -- procedure post(',
'    --     p_id in number default null,',
'    --     p_sucesso out clob,',
'    --     p_messages out pkg_mensagem.message_record_table     ',
'    -- );',
'',
'',
'end "UI_MPD_TD550";',
'/',
'create or replace package body "UI_MPD_TD550" as',
'',
'   procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'        l_somente_leitura varchar2(1);',
'',
'    begin',
'',
'       select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_cfop'';',
'       select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_cfop'';      ',
'',
'       l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'',
'       MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''descricao_cfop'',     4, '''', to_char(l_url), l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao_cfop) from ng_cfop where id = p_param1)) valor FROM dual UNION ALL     ',
'               SELECT p_codigo_artefato, ''codigo_cfop'',        3, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL                                                           ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  5, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 6, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                                                                                       ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     7, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_cfop where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'    -- procedure post(',
'    --     p_id in number default null,        ',
'    --     p_sucesso out clob,',
'    --     p_messages out pkg_mensagem.message_record_table         ',
'    -- )',
'    -- is',
'    --     l_id number;',
'    -- begin',
'    --     bo_srv_idioma.inclui_registro(',
'    --         p_NOME => apex_application.g_f02(1),',
'    --         p_CODIGO => apex_application.g_f03(1),',
'    --         p_SITUACAO => apex_application.g_f09(1),',
'    --         p_id => l_id, ',
'    --         p_sucesso => p_sucesso,',
'    --         p_messages => p_messages',
'    --     );',
'    -- end;',
'',
'end "UI_MPD_TD550";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td552
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157392891075176273)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD552'
,p_sequence=>1540
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD552" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD552";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD552" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                pkg_traducao.get_traducao(a.descricao_unidademedida) || '' - (''||a.codigo_unidademedida||'')'' titulo,                ',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                   ',
'                null lista_distintivo,',
'                a.codigo_unidademedida,',
'                a.data_fim_vigencia,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD552'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD552'') as opcao                ',
'            from ng_unidademedida a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            a.codigo_unidademedida campo2,',
'            pkg_traducao.get_traducao(a.descricao_unidademedida) campo3,                        ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            a.data_fim_vigencia campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            a.id_tenant filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_unidademedida a',
'        join mpd_tenant b on b.id = a.id_tenant',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD552'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_unidademedida'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_unidademedida.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_unidademedida.codigo_unidademedida'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_unidademedida.descricao_unidademedida'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_unidademedida.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo5,campo1,campo2,campo3'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,codigo_unidademedida,titulo'';',
'        end if;',
'',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'')  ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''2'') || '','' ||',
'               label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,codigo_unidademedida'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD552";',
'/'))
);
end;
