'               SELECT p_codigo_artefato, ''descricao_unidademedida'', 4, '''', to_char(l_url), ''S'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_unidademedida) from ng_unidademedida where id = p_param1)) valor FROM dual UNION ALL             '
||'                 ',
