'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'            function where_dinamico(p_campo in varchar2) return clob;',
'',
'',
'end "UI_MPD_TD563";',
'/',
'create or replace package body "UI_MPD_TD563" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is   ',
unistr('        -- p_param1 = id do endere\00E7o, p_param2 id da pessoa (ng_pessoa)'),
'        l_verifica_pessoa_fisica number;',
'        l_html clob;',
'    begin ',
'        select count(1) into l_verifica_pessoa_fisica from ng_pessoa_endereco a join ng_pessoa_fisica b on b.id_pessoa = a.id_pessoa where a.id = p_param1;        ',
'        if l_verifica_pessoa_fisica > 0 then       ',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ',
