'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is         ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';        ',
'        l_id_coluna_etiqueta number;',
'        l_etiqueta clob;',
'        l_permite_edicao_etiqueta varchar2(5);',
'        l_erro_etiqueta clob;  ',
'        l_somente_leitura_etiqueta varchar2(1); ',
'        l_consulta_estado clob;',
'        l_consulta_cidade clob;',
'        l_id_endereco number;               ',
'        l_url_etiqueta varchar2(4000);  ',
'        l_nome_pais varchar2(255);  ',
'        l_verifica_estado number;',
'        l_nome_estado varchar2(255);',
'    begin',
'        select to_char(chamar_webservice_traducao(esquema_corrente,''ng_pais'',''nome_pais'',apex_util.get_session_state(''IDIOMA_LOGADO''),a.id)) into l_nome_pais from ng_pais a join ng_pessoa_endereco b on b.id_pais = a.id where b.id = p_param2;',
'        prc_enviar_parametros2(p_codigo_artefato,''f06_0000'',l_nome_pais,apex_custom_auth.get_session_id);',
'        select count(1) into l_verifica_estado from ng_pessoa_endereco where id = p_param2 and id_estado is not null;',
'        if l_verifica_estado > 0 then',
'            select to_char(chamar_webservice_traducao(esquema_corrente,''ng_estado'',''nome_estado'',apex_util.get_session_state(''IDIOMA_LOGADO''),a.id)) into l_nome_estado from ng_estado a join ng_pessoa_endereco b on b.id_estado = a.id where b.id = p_pa'
||'ram2;        ',
'            prc_enviar_parametros2(p_codigo_artefato,''f08_0000'',l_nome_estado,apex_custom_auth.get_session_id);',
'        end if;',
'',
'        -- chamar_webservice_traducao2(',
'        --     p_esquema           => esquema_corrente,',
'        --     p_entidade          => ''ng_pessoa_endereco'',',
'        --     p_campo             => ''etiqueta_endereco'',',
'        --     p_id_idioma_usuario => apex_util.get_session_state(''IDIOMA_LOGADO''),',
'        --     p_id_registro       => p_param2,',
'        --     p_descricao         => l_etiqueta,',
'        --     p_permite_edicao    => l_permite_edicao_etiqueta,',
'        --     p_erro              => l_erro_etiqueta',
'        -- );         ',
'        ',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pessoa_endereco'';        ',
'        select id into l_id_coluna_etiqueta from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''etiqueta_endereco'';        ',
'',
'        if lower(l_permite_edicao_etiqueta) = ''false'' then',
'            l_somente_leitura_etiqueta := ''S'';',
'        else',
'            l_somente_leitura_etiqueta := ''N'';',
'        end if;',
'',
'        prc_enviar_parametros(''TD563'',''id_pais'',p_param1);        ',
'        l_consulta_estado := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(a.nome_estado), id, 1 from ng_estado a where id_pais = (select id from ng_pais np where pkg_traducao.get_traducao(np.n'
||'ome_pais) = (select c002 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f06_0000''''))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_da'
||'te(current_date))) order by ordem, d'';        ',
'        prc_enviar_parametros(''TD563'',''id_estado'',p_param1);',
'        l_consulta_cidade := ''select d, r from (select null d, null r, 0 ordem from dual union all select pkg_traducao.get_traducao(a.nome_cidade), a.id, 1 from ng_cidade a where a.id_pais = (select np.id from ng_pais np where pkg_traducao.get_traduc'
||'ao(np.nome_pais) = (select c002 from apex_collections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f06_0000''''))) and ((select c002 from apex_collections where collection_n'
||'ame = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f08_0000'''')) is null or a.id_estado = (select ne.id from ng_estado ne where pkg_traducao.get_traducao(ne.nome_estado) = (select c002 from apex_c'
||'ollections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f08_0000'''')))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_date(current_date))) order by'
||' ordem, d'';                ',
'',
'        l_url_etiqueta := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna_etiqueta, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        select pkg_traducao.get_traducao(etiqueta_endereco) into l_etiqueta  from ng_pessoa_endereco where id = p_param2;',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',               2, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''titulo_endereco'',         3 ,'''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_postal'',           4, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais'',                 5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_estado'',               7, ''POP1'', to_char(l_consulta_estado), ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cidade'',               9, ''POP1'', to_char(l_consulta_cidade), ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''bairro'',                 11, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''logradouro'',             12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero'',                 13, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''complemento'',            14, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''etiqueta_endereco'',      15 , ''TEX'', to_char(l_url_etiqueta), l_somente_leitura_etiqueta, ''S'', to_char(replace(l_etiqueta,''<br/>'',chr(10))) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_endereco_principal'', 16, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',         17, '''',null, ''N'',''S'', null valor FROM dual  ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'',
'            function where_dinamico (p_campo in varchar2) return clob is',
'        begin',
'            if upper(p_campo) = upper(''id_estado'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_pais in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD563_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f06_0000'')',
'                    )',
'                ~'';',
'             elsif  upper(p_campo) = upper(''id_cidade'') then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                    and a.id_estado in (',
'                        select c003 ',
'                          from apex_collections ',
'                         where collection_name = ''TD563_''||apex_custom_auth.get_session_id ',
'                           and upper(c001) = upper(''f08_0000'')',
'                    )',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'         end;',
'',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )',
'    is      ',
'    begin',
'        bo_ng_pessoa_endereco.altera_registro(              ',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa => apex_application.g_f02(1),',
'            p_titulo_endereco => apex_application.g_f03(1),',
'            p_codigo_postal => apex_application.g_f04(1),',
'            p_id_pais => apex_application.g_f05(1),',
'            p_id_estado => apex_application.g_f07(1),',
'            p_id_cidade => apex_application.g_f09(1),',
'            p_bairro => apex_application.g_f11(1),',
'            p_logradouro => apex_application.g_f12(1),',
'            p_numero => apex_application.g_f13(1),',
'            p_complemento => apex_application.g_f14(1),',
'            p_etiqueta_endereco => replace(replace(apex_application.g_f15(1), chr(13), ''''), chr(10), ''<br/>''),',
'            p_ind_endereco_principal => apex_application.g_f16(1),',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f17(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_data_integracao => null,',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD563";',
'/'))
);
end;
/
