prompt --application/deployment/install/install_ui_mpd_td566
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157394226583086939)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD566'
,p_sequence=>1610
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD566" as',
'',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'',
'end "UI_MPD_TD566";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD566" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(a.descricao_lead_time) titulo,                ',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''data'') ',
'                end distintivo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                    ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_leadtime.ind_logistica'', ',
'                    pkg_util.dominio_retorna_tag(''ng_leadtime'', ''ind_logistica'', a.ind_logistica), 4',
'                ) atributo1,                ',
'                pkg_componentes.html_card_colunas(''ng_leadtime.quantidade_dias'', a.quantidade_dias, 8) atributo2,',
'                a.data_fim_vigencia,',
'                a.ind_logistica,',
'                --FILTROS  ',
'                a.id_tenant filtro1,',
'                a.ind_logistica filtro2,             ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD566'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD566'') as opcao                ',
'            from ng_leadtime a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_pessoa_endereco c on c.id = a.id_endereco_origem',
'            left join ng_pessoa_endereco d on d.id = a.id_endereco_destino',
'            left join ng_localembarquedesembarque e on e.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque f on f.id = a.id_local_desembarque',
'            order by #ORDER#',
'            ~'';          ',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));       ',
'            return l_sql;        ',
'    end sql_card;',
'            --order by subtitulo, data_fim_vigencia nulls first, ind_logistica, titulo',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            pkg_util.dominio_retorna_tag(''ng_leadtime'', ''ind_logistica'', a.ind_logistica) campo2,',
'            pkg_traducao.get_traducao(a.descricao_lead_time) campo3,',
'            a.quantidade_dias campo4,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            a.data_fim_vigencia campo6,  ',
'            a.ind_logistica campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,          ',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            a.ind_logistica filtro2,',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_leadtime a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        left join ng_pessoa_endereco c on c.id = a.id_endereco_origem',
'        left join ng_pessoa_endereco d on d.id = a.id_endereco_destino',
'        left join ng_localembarquedesembarque e on e.id = a.id_local_embarque',
'        left join ng_localembarquedesembarque f on f.id = a.id_local_desembarque',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD566'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_leadtime'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1'')); ',
'        --order by campo1, to_date(campo6) nulls first, campo7, campo3               ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant order by 1~'';',
'        elsif campo = ''2'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_leadtime'',''ind_logistica'') order by 2~'';',
'        else',
'            return null;        ',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_leadtime.id_tenant'') into l_campo from dual;',
'        elsif campo in (''2'', ''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_leadtime.ind_logistica'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_leadtime.descricao_lead_time'') into l_campo from dual;        ',
'        -- elsif campo = ''4'' then                     ',
'        --     select pkg_ui.retorna_label_coluna(''ng_leadtime.id_endereco_origem'') into l_campo from dual;        ',
'        -- elsif campo = ''5'' then                     ',
'        --     select pkg_ui.retorna_label_coluna(''ng_leadtime.id_local_embarque'') into l_campo from dual;        ',
'        -- elsif campo = ''6'' then                     ',
'        --     select pkg_ui.retorna_label_coluna(''ng_leadtime.id_local_desembarque'') into l_campo from dual;        ',
'        -- elsif campo = ''7'' then                     ',
'        --     select pkg_ui.retorna_label_coluna(''ng_leadtime.id_endereco_destino'') into l_campo from dual;        ',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_leadtime.quantidade_dias'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pais.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo7,campo3'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,ind_logistica,titulo'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''2'') || '','' ||',
'               label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo7,campo3'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,ind_logistica,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD566";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td569
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157394473697083978)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD569'
,p_sequence=>1620
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD569" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD569";',
'/',
'create or replace package body "UI_MPD_TD569" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;        ',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_leadtime'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_lead_time'';                ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, null AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL            ',
'               SELECT p_codigo_artefato, ''descricao_lead_time'',  3, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_lead_time) from ng_leadtime where id = p_param1)) valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_logistica'',        4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_origem'',   5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_embarque'',    7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_desembarque'', 9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_destino'', 11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_dias'',     13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   14, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                              ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',  15, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',      16, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_leadtime where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                                     '
||'                      ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;   ',
'',
'end "UI_MPD_TD569";',
'/'))
);
end;
/
