prompt --application/deployment/install/install_ui_mpd_td580
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157400351884939156)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD580'
,p_sequence=>1670
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
' create or replace package "UI_MPD_TD580" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'   ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD580";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD580" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,                ',
'                pkg_traducao.get_traducao(descricao_recinto_alfandegado) titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                a.data_fim_vigencia,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo, ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_recinto_alfandegado.CODIGO_RECINTO_ALFANDEGADO'', a.CODIGO_RECINTO_ALFANDEGADO, 4) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_recinto_alfandegado.id_unidade_local_rfb'', pkg_traducao.get_traducao(c.descricao_unidade_local_rfb), 8',
'                ) atributo2,',
'                --order',
'                a.CODIGO_RECINTO_ALFANDEGADO order1,',
'                pkg_traducao.get_traducao(a.descricao_recinto_alfandegado) order2,',
'                c.CODIGO_UNIDADE_LOCAL_RFB||'' - ''|| pkg_traducao.get_traducao(c.descricao_unidade_local_rfb) order3,',
'                a.data_fim_vigencia order4,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD580'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD580'') as opcao                ',
'            from ng_recinto_alfandegado a',
'            join mpd_tenant b on b.id = a.id_tenant   ',
'            left join ng_unidadelocalrfb c on a.id_unidade_local_rfb = c.id         ',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'            return l_sql; ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            b.nome_fantasia campo1,',
'            a.CODIGO_RECINTO_ALFANDEGADO campo2,',
'            pkg_traducao.get_traducao(a.descricao_recinto_alfandegado) campo3,',
'            c.CODIGO_UNIDADE_LOCAL_RFB||'' - ''|| pkg_traducao.get_traducao(c.descricao_unidade_local_rfb)campo4,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            a.data_fim_vigencia campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,      ',
'            --FILTROS',
'            a.id_tenant filtro1,                                                             ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                           ',
'            null opcao',
'        from ng_recinto_alfandegado a',
'        left join ng_unidadelocalrfb c on a.id_unidade_local_rfb = c.id',
'        join mpd_tenant b on b.id = a.id_tenant           ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select         ',
'                id,       ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                to_date(campo6,''DD/MM/YYYY'')campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD580'') opcao',
'             from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_recinto_alfandegado'')) a',
'            order by #ORDER#',
'             ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'',
'   function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;   ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.CODIGO_RECINTO_ALFANDEGADO'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.descricao_recinto_alfandegado'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.id_unidade_local_rfb'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'   ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo4,campo6'';',
'        else',
'            campos := ''subtitulo,order1,order2,order3,order4'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2'';',
'        else',
'            l_campos := ''order4,subtitulo,order1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD580";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td584
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157400584287936040)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD584'
,p_sequence=>1680
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD584 ',
'-- Data: 18/05/2026 ',
'-- Motivo: Ajuste de coluna id_unidade_federativa ',
'-- Jira: PNG-447',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD584" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'end "UI_MPD_TD584";',
'/',
'create or replace package body "UI_MPD_TD584" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);    ',
'        l_somente_leitura varchar2(1);    ',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_recinto_alfandegado'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_recinto_alfandegado'';                 ',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, null AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL            ',
'               SELECT p_codigo_artefato, ''codigo_recinto_alfandegado'',      3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''descricao_recinto_alfandegado'',   4, '''', to_char(l_url), l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao_recinto_alfandegado) from ng_recinto_alfandegado where id = p_param1)) valo'
||'r FROM dual UNION ALL                 ',
'               SELECT p_codigo_artefato, ''id_unidade_local_rfb'',            5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidade_federativa'',           6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',               7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',              8, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                  9, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_recinto_alfandegado where id = p_param1), ''DATA_SEGUNDO'') valor from dual                               '
||'                                           ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'   ',
'end "UI_MPD_TD584";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td586
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157400716488933048)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD586'
,p_sequence=>1690
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD586" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD586";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD586" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(descricao_receita) titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                   ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_receita.ind_origem_receita'',',
'                    pkg_util.dominio_retorna_tag(''ng_receita'', ''ind_origem_receita'', a.ind_origem_receita), 2',
'                ) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_receita.ind_exige_contrato_cambio'',',
'                    pkg_util.dominio_retorna_tag(''ng_receita'', ''ind_exige_contrato_cambio'', a.ind_exige_contrato_cambio), 2',
'                ) atributo2,                ',
'                pkg_componentes.html_card_colunas(''ng_receita.id_conta_contabil_credito'',pkg_traducao.get_traducao(c.descricao_conta_contabil), 2',
'                ) atributo3,',
'                pkg_componentes.html_card_colunas(''ng_receita.id_conta_contabil_debito'',pkg_traducao.get_traducao(d.descricao_conta_contabil), 2',
'                ) atributo4,',
'                pkg_componentes.html_card_colunas(''ng_receita.id_conta_contabil_variacao_ativa'',pkg_traducao.get_traducao(e.descricao_conta_contabil), 2',
'                ) atributo5,',
'                pkg_componentes.html_card_colunas(''ng_receita.id_conta_contabil_variacao_passiva'',pkg_traducao.get_traducao(f.descricao_conta_contabil), 2',
'                ) atributo6,       ',
'                --order',
'                pkg_util.dominio_retorna_tag(''ng_receita'', ''ind_origem_receita'', a.ind_origem_receita) order1,',
'                a.data_fim_vigencia order2,                         ',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD586'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD586'') as opcao                ',
'            from ng_receita a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_contacontabil c on c.id = a.id_conta_contabil_credito',
'            left join ng_contacontabil d on c.id = a.id_conta_contabil_debito',
'            left join ng_contacontabil e on c.id = a.id_conta_contabil_variacao_ativa',
'            left join ng_contacontabil f on c.id = a.id_conta_contabil_variacao_passiva                        ',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia campo1,            ',
'            pkg_traducao.get_traducao(a.descricao_receita) campo2,',
'            pkg_util.dominio_retorna_tag(''ng_receita'', ''ind_origem_receita'', a.ind_origem_receita) campo3,                                                                   ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,  ',
'            a.data_fim_vigencia campo5,          ',
'            null campo6,          ',
'            null campo7,          ',
'            null campo8,          ',
'            null campo9,          ',
'            null campo10,          ',
'            --FILTROS',
'            a.id_tenant filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_receita a',
'        join mpd_tenant b on b.id = a.id_tenant',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD586'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_receita'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_receita.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_receita.descricao_receita'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_receita.ind_origem_receita'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_receita.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo5'';',
'        else',
'            campos := ''subtitulo,titulo,order1,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2,campo3'';',
'        else',
'            l_campos := ''order2,subtitulo,titulo,order1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD586";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td589
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157401157742928500)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD589'
,p_sequence=>1700
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD589" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'    ',
'end "UI_MPD_TD589";',
'/',
'create or replace package body "UI_MPD_TD589" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;        ',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_receita'';        ',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_receita'';         ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, null AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL                          '
||' ',
'               SELECT p_codigo_artefato, ''descricao_receita'',                   4, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_receita) from ng_receita where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_origem_receita'',                  5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_exige_contrato_cambio'',           6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_contabil_credito'',           7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_contabil_debito'',            9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_contabil_variacao_ativa'',   11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_contabil_variacao_passiva'', 13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',                  15, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',                 16, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                     17, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_receita where id = p_param1), ''DATA_SEGUNDO'') valor from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD589";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td593
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157401373426925013)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD593'
,p_sequence=>1710
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD593" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;    ',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD593";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD593" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.nome_abreviado from ng_pessoa_fisica a where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_pessoa_fisica''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is        ',
'        l_sql clob;        ',
'        l_where clob;',
'    begin',
'        if p_param2 <> ''TD600'' then',
'            l_where := '' and (id_pessoa_referencia = ''||p_param2||'' or id_pessoa_referencia = c.id_pessoa)'';',
'        end if;',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) titulo,                ',
'                bo_ng_pessoa.retorna_pessoa(a.id_pessoa_referencia) subtitulo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end distintivo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,                  ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_pessoa_contato_dado.dado_contato'', a.dado_contato, 6) atributo1,                ',
'                pkg_componentes.html_card_colunas(''ng_pessoa_contato_dado.observacao'', pkg_traducao.get_traducao(a.observacao), 6',
'                ) atributo2,',
'                a.data_fim_vigencia,',
'                --FILTROS                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD593'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD593'') as opcao',
'            from ng_pessoa_contato_dado a',
'            join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato            ',
'            join ng_pessoa_fisica c on c.id_pessoa = b.id_pessoa_fisica',
'            where c.id = #PARAM1# #WHERE#',
'            order by #ORDER#',
'           ~'';',
'           l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#WHERE#'', l_where);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'           return l_sql;                      ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is        ',
'        l_sql clob;',
'        l_where clob;',
'    begin    ',
'        if p_param2 <> ''TD600'' then',
'            l_where := '' and (id_pessoa_referencia = ''||p_param2||'' or id_pessoa_referencia = c.id_pessoa)'';',
'        end if;    ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            bo_ng_pessoa.retorna_pessoa(a.id_pessoa_referencia) campo1,',
'            pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo2,',
'            a.dado_contato campo3,            ',
'            pkg_traducao.get_traducao(a.observacao) campo4,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo5,',
'            a.data_fim_vigencia campo6,            ',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            null filtro1,                                ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                ',
'            null opcao',
'        from ng_pessoa_contato_dado a',
'        join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato        ',
'        join ng_pessoa_fisica c on c.id_pessoa = b.id_pessoa_fisica',
'        where c.id = #PARAM1# #WHERE#',
'        ~'';',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       l_sql := replace(l_sql, ''#WHERE#'', l_where);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD593'') as opcao',
'            from table(pkg_ui.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_pessoa_contato_dado'')) a',
'            order by #ORDER#          ',
'            ~'';      ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1'')); ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.id_pessoa_referencia'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_forma_contato'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.dado_contato'') into l_campo from dual;        ',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.observacao'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo5,campo2,campo3,campo1,campo4'';',
'        else',
'            campos := ''data_fim_vigencia,titulo,atributo1,subtitulo,atributo2'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''4'')    ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''2'') || '','' ||',
'               label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo2,campo3'';',
'        else',
'            l_campos := ''data_fim_vigencia,titulo,atributo1'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD593";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td594
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157401599730920958)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD594'
,p_sequence=>1720
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD594" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD594";',
'/',
'create or replace package body "UI_MPD_TD594" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is  ',
'        l_nome_entidade varchar2(4000);  ',
'        l_nome_coluna_referencia varchar2(4000);    ',
'        l_position number;   ',
'        l_label_coluna varchar2(4000);',
'        l_html clob;        ',
'    begin        ',
'        select lower(nome_entidade) into l_nome_entidade from srv_entidade where id = p_param2;        ',
'        select lower(listagg(nome_coluna, ''||'''' - ''''||'') within group (order by referencia)) into l_nome_coluna_referencia from srv_entidade_coluna where lower(referencia) is not null and id_entidade = p_param2;',
'        ',
'        l_position := instr(l_nome_coluna_referencia, ''||'''' - ''''||'');',
'        if l_position > 0 then',
'            l_label_coluna := substr(l_nome_coluna_referencia, 0, l_position - 1);',
'            l_nome_coluna_referencia := l_nome_coluna_referencia||'' ''||l_label_coluna;',
'        end if;',
'',
'        if l_nome_entidade = ''imp_pedidoimportacao'' then',
'            l_nome_coluna_referencia := l_nome_coluna_referencia || '', bo_ng_pessoa.retorna_pessoa(id_exportador) id_exportador, bo_ng_pessoa.retorna_pessoa(id_importador) id_importador '';',
'        end if;',
'        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select ''||l_nome_coluna_referencia||'' from ''||l_nome_entidade||'' where id = ''||p_param1,',
'            p_tabela => textarray(l_nome_entidade,l_nome_entidade,l_nome_entidade),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                c.nome titulo,',
'                pkg_data.fmt(a.data_alteracao, ''DATA_SEGUNDO'') subtitulo,                ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_observacao.observacao'', ',
'                    replace(pkg_traducao.get_traducao(a.observacao), chr(10), ''<br>''), 12',
'                ) atributo1,',
'                a.data_alteracao,',
'                --FILTROS                ',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                --pkg_ui.url_mais_detalhes(''TD594'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD594'') as opcao                ',
'            from imp_observacao a',
'            join srv_entidade b on b.id = a.id_entidade',
'            join mpd_usuario c on c.id = a.id_usuario_alterou  ',
'            where a.id_entidade = #PARAM2#',
'            and a.id_referencia = #PARAM1#',
'            order by 8 desc',
'       ~'';     ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       l_sql := replace(l_sql, ''#PARAM2#'', p_param2);',
'       return l_sql;  ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select distinct',
'            a.id id,  ',
'            pkg_data.fmt(a.data_alteracao,''DATA_SEGUNDO'') campo1,',
'            replace(pkg_traducao.get_traducao(a.observacao), chr(10), ''<br>'') campo2,',
'            c.nome campo3,',
'            a.data_alteracao campo4,',
'            null campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            null filtro1,                ',
'            null filtro2,                ',
'            null filtro3,                ',
'            null filtro4,                ',
'            null filtro5,                ',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            null opcao',
'        from imp_observacao a',
'        join srv_entidade b on b.id = a.id_entidade',
'        join mpd_usuario c on c.id = a.id_usuario_alterou  ',
'        where a.id_entidade = #PARAM2#            ',
'        and a.id_referencia = #PARAM1#',
'       ~'';     ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       l_sql := replace(l_sql, ''#PARAM2#'', p_param2);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD594'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_observacao'')) a',
'            order by to_timestamp(campo4,''dd-mm-rr hh:mi:ss:ff am'') desc, id desc',
'            ~'';        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin        ',
'        return null;           ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_observacao.data_alteracao'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_observacao.observacao'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_observacao.id_usuario_alterou'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia, nome_fantasia'';',
'        else',
'            campos := ''campo5, campo2'';',
'        end if;',
'        labels := label_coluna(''5'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD594";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td595
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157401864517917784)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD595'
,p_sequence=>1730
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD595" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD595";',
'/',
'create or replace package body "UI_MPD_TD595" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_fisica where i'
||'d = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_contato'',    2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_fisica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_referencia'', 3, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_fisica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_contato'',    4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''dado_contato'',         5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_whatsapp'',         6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',           7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    8, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_ind_whataspp varchar2(1);',
'    begin',
'        if lower(apex_application.g_f04(1)) = ''2'' then',
'            l_ind_whataspp := apex_application.g_f06(1);',
'        else',
'            l_ind_whataspp := null;',
'        end if;',
'        bo_ng_pessoa_contato_dado.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa_contato => apex_application.g_f02(1),',
'            p_id_pessoa_referencia => apex_application.g_f03(1),',
'            p_ind_forma_contato => apex_application.g_f04(1),',
'            p_dado_contato => apex_application.g_f05(1),            ',
'            p_ind_whatsapp => l_ind_whataspp,',
'            p_observacao => apex_application.g_f07(1),',
'            p_data_fim_vigencia => apex_application.g_f08(1),',
'            p_data_integracao => null,',
'            p_motivo_rejeicao => null,',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo1,',
'                a.dado_contato campo2,                ',
'                a.observacao campo3,',
'                case ',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo4,',
'                a.data_fim_vigencia campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD595'') opcao',
'            from ng_pessoa_contato_dado a',
'            join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato  ',
'            join ng_pessoa_fisica c on c.id_pessoa = b.id_pessoa_fisica         ',
'            where c.id = #param1#',
'            order by to_date(campo5, ''dd/mm/yyyy'') nulls first, campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                null selected,        ',
'                a.id,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_forma_contato'', a.ind_forma_contato) campo1,',
'                a.dado_contato campo2,                ',
'                a.observacao campo3,',
'                case ',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        --pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo4,',
'                a.data_fim_vigencia campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD595'') opcao',
'            from ng_pessoa_contato_dado a',
'            join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato  ',
'            join ng_pessoa_fisica c on c.id_pessoa = b.id_pessoa_fisica         ',
'            where c.id = #param1#',
'            order by to_date(campo5, ''dd/mm/yyyy'') nulls first, campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_forma_contato'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.dado_contato'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.observacao'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD728,TD728,''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD595";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td598
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157402066425914860)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD598'
,p_sequence=>1740
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD598" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD598";',
'/',
'create or replace package body "UI_MPD_TD598" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is       ',
'        l_html clob;',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select ',
'                    a.nome_abreviado ',
'                from ng_pessoa_fisica a ',
'                join ng_pessoa_contato b on b.id_pessoa_fisica = a.id_pessoa',
'                join ng_pessoa_contato_dado c on c.id_pessoa_contato = b.id_pessoa',
'                where c.id = ''||p_param1,',
'            p_tabela => textarray(''ng_pessoa_fisica''),',
'            p_formato => ''pequeno'',',
'            --p_icones => textarray(/*''fa-database'', ''fa-database'',*/ ''fa-user'', ''fa-calendar fam-clock fam-is-success'', ''fa-calendar fam-clock fam-is-warning'', ''fa-flag''),',
unistr('            --p_label_fixo => textarray(''Workspace'', ''Aplica\00E7\00F5es'', ''P\00E1ginas'', ''Usu\00E1rios APEX''),'),
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);        ',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pessoa_contato_dado'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';         ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_pessoa_contato'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL                 '
||'             ',
'               SELECT p_codigo_artefato, ''id_pessoa_referencia'', 3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_contato'',    4, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''dado_contato'',         5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL                  ',
'               SELECT p_codigo_artefato, ''ind_whatsapp'',         6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''motivo_rejeicao'',      7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',           8, ''TEX'', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(observacao) from ng_pessoa_contato_dado where id = p_param1)) valor FROM dual UNION ALL                    '
||'             ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    9, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_integracao'',     10, ''HID'', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',  11, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',      12, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_pessoa_contato_dado where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'    ',
'end "UI_MPD_TD598";',
'/'))
);
end;
