prompt --application/deployment/install/install_ui_mpd_td600
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157402354521910908)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD600'
,p_sequence=>1750
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD600" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD600";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD600" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'                a.id,  ',
'                a.nome titulo,',
'                c.nome_fantasia subtitulo,                ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_pessoa_fisica.nome_abreviado'', a.nome_abreviado, 6) atributo1,',
'                case ',
'                    when b.data_fim_vigencia is null then',
'                        null',
'                    when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_pessoa.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(b.data_fim_vigencia, ''DATA'')), 6) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_pessoa.data_fim_vigencia'', pkg_data.fmtd(b.data_fim_vigencia, ''DATA''), 6) ',
'                end atributo2,  ',
'                pkg_data.fmtd(b.data_fim_vigencia, ''DATA''),              ',
'                --FILTROS',
'                b.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD600'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD600'', p_param1 => b.id) as opcao                ',
'            from ng_pessoa_fisica a',
'            join ng_pessoa b on b.id = a.id_pessoa',
'            join mpd_tenant c on c.id = b.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select                        ',
'            a.id id,',
'            c.nome_fantasia campo1,',
'            a.nome campo2,',
'            a.nome_abreviado campo3,',
'            case ',
'                when to_date(b.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_cor_texto(pkg_data.fmtd(b.data_fim_vigencia, ''DATA''))',
'                else',
'                    pkg_data.fmtd(b.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            b.data_fim_vigencia campo5,            ',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            b.id_tenant filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD600'', p_param1 => b.id) opcao',
'        from ng_pessoa_fisica a',
'        join ng_pessoa b on b.id = a.id_pessoa',
'        join mpd_tenant c on c.id = b.id_tenant',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                                 ',
'                opcao           ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_pessoa_fisica'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.nome'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_fisica.nome_abreviado'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo5,campo1,campo2,campo3'';',
'        else',
'            campos := ''data_fim_vigencia,a.id_tenant,nome,nome_abreviado'';',
'        end if;',
'',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        l_labels := label_coluna(''4'') || '','' || label_coluna(''1'') || '','' || label_coluna(''2'');',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,a.id_tenant,nome'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD600";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td602
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157402582558907625)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD602'
,p_sequence=>1760
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD602" as',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD602";',
'/',
'create or replace package body "UI_MPD_TD602" as',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_observacao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);        ',
'        l_url varchar2(4000);',
'    begin          ',
'    ',
'',
'        select pkg_traducao.get_traducao(observacao) into l_observacao from ng_pessoa_fisica where id = p_param1;',
'        ',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pessoa_fisica'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';         ',
'        ',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;         ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );  ',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome'',               2, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_abreviado'',     3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''observacao'',         4, '''', to_char(l_url), l_somente_leitura, ''S'', to_char(nvl(l_erro, l_observacao)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''rg'',                 5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cpf'',                6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cnh'',                7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''passaporte'',         8, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_aniversario'',   9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',    10, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',         11, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'', 12, ''DAT'', null, ''N'', ''N'', pkg_data.fmtd((select a.data_fim_vigencia from ng_pessoa a join ng_pessoa_fisica b on b.id_pessoa = a.id where b.id = p_param1),''DATA'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is        ',
'    begin',
'        bo_ng_pessoa_fisica.altera_pessoa_fisica(',
'            p_id_tenant => apex_application.g_f01(1),            ',
'            p_nome => apex_application.g_f02(1),',
'            p_nome_abreviado => apex_application.g_f03(1),',
'            p_observacao => apex_application.g_f04(1),',
'            p_rg => apex_application.g_f05(1),',
'            p_cpf => apex_application.g_f06(1),',
'            p_cnh => apex_application.g_f07(1),',
'            p_passaporte => apex_application.g_f08(1),',
'            p_data_aniversario => apex_application.g_f09(1),',
'            p_data_integracao => null,',
'            p_data_fim_vigencia => apex_application.g_f12(1),            ',
'            p_id => p_id,',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f10(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'        -- bo_ng_pessoa_fisica.altera_registro(',
'        --     p_id_tenant => apex_application.g_f01(1),',
'        --     -- p_data_fim_vigencia => apex_application.g_f12(1),',
'        --     p_id_pessoa => apex_application.g_f11(1),',
'        --     p_nome => apex_application.g_f02(1),',
'        --     p_nome_abreviado => apex_application.g_f03(1),',
'        --     p_observacao => apex_application.g_f04(1),',
'        --     p_rg => apex_application.g_f05(1),',
'        --     p_cpf => apex_application.g_f06(1),',
'        --     p_cnh => apex_application.g_f07(1),',
'        --     p_passaporte => apex_application.g_f08(1),',
'        --     p_data_aniversario => apex_application.g_f09(1),',
'        --     p_data_alteracao => TO_TIMESTAMP(apex_application.g_f10(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'        --     p_data_integracao => null,',
'        --     p_id => p_id,',
'        --     p_sucesso => p_sucesso,',
'        --     p_messages => p_messages',
'        -- );        ',
'    end post;',
'',
'end "UI_MPD_TD602";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td603
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157402815795903417)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD603'
,p_sequence=>1770
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD603" as',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'end "UI_MPD_TD603";',
'/',
'create or replace package body "UI_MPD_TD603" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_observacao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);      ',
'        l_url varchar2(4000);  ',
'    begin          ',
'        select pkg_traducao.get_traducao(observacao) into l_observacao from ng_pessoa_fisica where id = p_param1;  ',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_pessoa_fisica'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';                 ',
'',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;      ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome'',                2, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_abreviado'',      3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                                      ',
'               SELECT p_codigo_artefato, ''observacao'',          4, '''', to_char(l_url), ''N'', ''S'', to_char(l_observacao) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''rg'',                  5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cpf'',                 6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cnh'',                 7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''passaporte'',          8, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_aniversario'',    9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  10, ''DAT'', null, ''N'', ''N'', pkg_data.fmtd((select a.data_fim_vigencia from ng_pessoa a join ng_pessoa_fisica b on b.id_pessoa = a.id where b.id = p_param1),''DATA'') valor FROM dual UNION AL'
||'L',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 11, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',     12, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select a.data_alteracao from ng_pessoa_fisica a where a.id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'    ',
'end "UI_MPD_TD603";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td605
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157403207846899504)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD605'
,p_sequence=>1780
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD605" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'',
'end "UI_MPD_TD605";',
'/',
'create or replace package body "UI_MPD_TD605" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                (a.id_pessoa_representante || ''.id_pessoa_representante - ng_pessoa_atributo_pesquisa'')',
'                                    titulo, ',
'                null  subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                null lista_distintivo,                ',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_representante_comissao.id_importador'',a.id_importador,3) as atributo1,',
'                pkg_componentes.html_card_colunas(''ng_representante_comissao.id_exportador'',a.id_exportador,3) as atributo2,',
'                pkg_componentes.html_card_colunas(''ng_representante_comissao.ind_forma_pagamento_comissao'', (',
'                 case  ',
'                    when a.ind_forma_pagamento_comissao = ''R'' then',
'                    ''A Remeter''',
'                    when a.ind_forma_pagamento_comissao = ''G'' then',
unistr('                    ''Conta Gr\00E1fica'''),
'                    when a.ind_forma_pagamento_comissao = ''D'' then',
'                    ''A Deduzir''  ',
'                    when a.ind_forma_pagamento_comissao = ''P'' then',
unistr('                    ''Pago no Pa\00EDs do Exportador''                 '),
'                  end),3) as atributo3,',
'                --FILTROS',
'                null filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD605'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD605'') as opcao  ',
'',
'            from ng_representante_comissao a',
'            order by #ORDER#',
'',
'           ~'';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));            ',
'           return l_sql;',
'           -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia                                 campo1,',
'            a.id_pessoa_representante                       campo2,',
'            a.id_exportador                                 campo3,',
'            a.id_importador                                 campo4,',
'            case  ',
'                    when a.ind_forma_pagamento_comissao = ''R'' then',
'                    ''A Remeter''',
'                    when a.ind_forma_pagamento_comissao = ''G'' then',
unistr('                    ''Conta Gr\00E1fica'''),
'                    when a.ind_forma_pagamento_comissao = ''D'' then',
'                    ''A Deduzir''  ',
'                    when a.ind_forma_pagamento_comissao = ''P'' then',
unistr('                    ''Pago no Pa\00EDs do Exportador''                 '),
'                  end                                        campo5,',
'            case  ',
'                    when a.ind_taxa_cambio = 1 then',
unistr('                    ''Data da confirma\00E7\00E3o do pedido'''),
'                    when a.ind_taxa_cambio = 2 then',
'                    ''Data do embarque''',
'                    when a.ind_taxa_cambio = 3 then',
unistr('                    ''Data da liquida\00E7\00E3o pelo cliente'''),
'                    when a.ind_taxa_cambio = 4 then',
unistr('                    ''PTAX da data do pagamento da comiss\00E3o'''),
'                    when a.ind_taxa_cambio = 5 then',
'                    ''Negociado  ''',
'                  end                                        campo6,  ',
'            case  ',
'                    when a.ind_quando_pagar = 1 then',
unistr('                    ''100% na primeira cobran\00E7a do importador ap\00F3s o embarque''  '),
'                    when a.ind_quando_pagar = 2 then',
unistr('                    ''100% na \00FAltima cobran\00E7a do importador ap\00F3s o embarque'' '),
'                    when a.ind_quando_pagar = 3 then',
unistr('                    ''Proporcional Conforme Cobran\00E7as da Exporta\00E7\00E3o ap\00F3s o Embarque'' '),
'                    when a.ind_quando_pagar = 4 then',
unistr('                    ''Proporcional conforme condi\00E7\00E3o de pagamento da exporta\00E7\00E3o'' '),
'                    when a.ind_quando_pagar = 5 then',
unistr('                    ''Conforme % a pagar no embarque e saldo proporcional conforme condi\00E7\00E3o de pagamento da exporta\00E7\00E3o'' '),
'                  end                                        campo7,',
'            a.perc_no_embarque                               campo8,',
'            a.qtd_dias_pagamento_comissao                    campo9,',
'            case when a.data_fim_vigencia < current_date then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end                                              campo10,',
'            --FILTROS',
'            null                                             filtro1,                                ',
'            null                                             filtro2,                                ',
'            null                                             filtro3,                                ',
'            null                                             filtro4,',
'            null                                             filtro5,                                ',
'            --FILTROS MULTI',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            null                                             filtro_mult5,                                ',
'            null opcao',
'        from ng_representante_comissao a',
'        JOIN mpd_tenant b ON b.id = a.id_tenant  ',
'',
'   ',
'',
'       ~'';',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'   ',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'    begin',
'        return q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD605'') as opcao ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_representante_comissao'')) a',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'',
'            return null;',
'   ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if    campo =''1''  then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.id_pessoa_representante'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.id_exportador'') into l_campo from dual;',
'        elsif campo = ''4'' then                                            ',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.id_importador'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.ind_forma_pagamento_comissao'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.ind_taxa_cambio'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.ind_quando_pagar'') into l_campo from dual;',
'        elsif campo = ''8'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.perc_no_embarque'') into l_campo from dual;',
'        elsif campo = ''9'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.qtd_dias_pagamento_comissao'') into l_campo from dual;',
'        elsif campo = ''10'' then',
'            select pkg_ui.retorna_label_coluna(''ng_representante_comissao.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''id,id'';',
'        else',
'            campos := ''campo2,campo3'';',
'        end if;',
'        labels := label_coluna(''2'')||'',''||label_coluna(''3'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD605";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td610
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157403737057896261)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD610'
,p_sequence=>1790
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD610" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD610";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD610" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(a.descricao_despesa) titulo,                ',
'                b.nome_fantasia subtitulo,                ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS                ',
'                pkg_componentes.html_card_colunas(''ng_despesa.ind_origem_despesa'', ',
'                    pkg_util.dominio_retorna_tag(''ng_despesa'', ''ind_origem_despesa'', a.ind_origem_despesa), 6',
'                ) atributo1,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_despesa.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 6) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_despesa.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 6) ',
'                end atributo2,',
'                to_date(a.data_fim_vigencia, ''dd/mm/yyyy''),',
'                --order',
'                pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_origem_despesa'', a.ind_origem_despesa) order1,',
'                a.data_fim_vigencia order2,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                a.ind_origem_despesa filtro2,                ',
'                a.ind_onde_acontece filtro3,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD610'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD610'') as opcao                ',
'            from ng_despesa a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia campo1,            ',
'            pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_origem_despesa'', a.ind_origem_despesa) campo2,            ',
'            pkg_traducao.get_traducao(a.descricao_despesa) campo3,            ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            a.data_fim_vigencia campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            a.id_tenant filtro1,                               ',
'            a.ind_origem_despesa filtro2,            ',
'            a.ind_onde_acontece filtro3,                             ',
'            null filtro4,',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_despesa a',
'        join mpd_tenant b on b.id = a.id_tenant',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                to_date(campo5,''DD/MM/YYYY'')campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD610'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_despesa'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_origem_despesa'')~'';        ',
'        elsif campo = ''3'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_onde_acontece'')~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_despesa.id_tenant'') into l_campo from dual;',
'        elsif campo in (''2'', ''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_despesa.ind_origem_despesa'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_despesa.descricao_despesa'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_despesa.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''F3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_despesa.ind_onde_acontece'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo5'';',
'        else',
'            campos := ''subtitulo,order1,titulo,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo5,campo1,campo2,campo3'';',
'        else',
'            l_campos := ''order2,subtitulo,order1,titulo'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD610";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td613
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157404059892893353)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD613'
,p_sequence=>1800
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD613" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'    ',
'end "UI_MPD_TD613";',
'/',
'create or replace package body "UI_MPD_TD613" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_despesa'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_despesa'';',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_origem_despesa'',        3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''descricao_despesa'',         4, '''', to_char(l_url), ''N'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_despesa) from ng_despesa where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_onde_acontece'',         5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_rateio'',          6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_compoe_custo_operacao'', 7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_participa_nfe'',         8, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_despesa_base_calculo'',  9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_despesa'',         10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_contabil'',        11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',        13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',       14, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                                                                                            '
||'        ',
'               SELECT p_codigo_artefato, ''data_alteracao'',           15, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_despesa where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;    ',
'',
'end "UI_MPD_TD613";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td620
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157404404653890442)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD620'
,p_sequence=>1810
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD620" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'    function atualizar_tela return varchar2;',
'',
'end "UI_MPD_TD620";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD620" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id ,',
'                c.data_fim_vigencia,',
'		        corta_texto(pkg_traducao.get_traducao(descricao_item)) titulo,',
'                e.nome_fantasia             subtitulo,  ',
'                case ',
'                    when c.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(c.data_fim_vigencia, ''DATA'') ',
'                end distintivo,',
'                case ',
'                    when c.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(c.data_fim_vigencia) < to_date(current_date)  then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                --ATRIBUTOS               ',
'                pkg_componentes.html_card_colunas(''ng_item.codigo_item'', c.codigo_item, 4 ) ',
'                                           atributo1,  ',
'                pkg_componentes.html_card_colunas(''ng_ncm.codigo_ncm'', d.codigo_ncm, 4 ) ',
'                                           atributo2,',
'                --FILTROS',
'                a.id_tenant       filtro1,',
'                c.id_familia_item filtro2,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                    pkg_ui.url_mais_detalhes(''TD620'',a.id) url_mais_detalhes,',
'                    pkg_componentes.html_botao_opcao(a.id,''TD620'') as opcao  ',
'',
'                from ng_item_produto a',
'                JOIN ng_item    c on c.id = a.id_item',
'                JOIN ng_ncm     d on d.id = a.id_ncm  ',
'                JOIN mpd_tenant e on e.id = a.id_tenant ',
'                where c.ind_tipo_item = ''P''',
'                order by #ORDER#',
'',
'           ~'';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));  ',
'           --order by 2 nulls first,3          ',
'           return l_sql;',
'           -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            b.nome_fantasia                                 campo1,',
'            c.codigo_item                                   campo2,',
'		    corta_texto(pkg_traducao.get_traducao(descricao_item)) ',
'                                                            campo3,',
'            d.codigo_ncm                                    campo4,',
'            case when to_date(c.data_fim_vigencia) < to_date(current_date)  then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(c.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(c.data_fim_vigencia, ''DATA'')',
'            end                                              campo5,',
'',
'            c.data_fim_vigencia                              campo6,',
'            null                                             campo7,',
'            null                                             campo8,',
'            null                                             campo9,',
'            null                                             campo10,',
'            --FILTROS',
'            a.id_tenant                                      filtro1,                                ',
'            c.id_familia_item                                filtro2,                                ',
'            null                                             filtro3,                                ',
'            null                                             filtro4,',
'            null                                             filtro5,                                ',
'            --FILTROS MULTI',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            null                                             filtro_mult5,                                ',
'            null opcao',
'        from ng_item_produto a',
'        JOIN mpd_tenant b ON a.id_tenant = b.id  ',
'        JOIN ng_item    c on c.id = a.id_item',
'        JOIN ng_ncm     d on d.id = a.id_ncm  ',
'        where c.ind_tipo_item = ''P''',
'',
'       ~'';',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;    ',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD620'') as opcao',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_item_produto'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                        ',
'        return l_sql;            ',
'            ',
'            --order by to_date(campo6,''dd/mm/yyyy'') nulls first, campo3     ',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~select descricao_familia d, id r from ng_familia_item~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo IN (''1'',''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_item_produto.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_tela(''item_codigo'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''4'' then                        ',
'            select pkg_ui.retorna_label_coluna(''ng_item_produto.id_ncm'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_item.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo  = ''F2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_item.id_familia_item'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo3,campo2,campo4'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,titulo,atributo1,atributo2'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''3'') || '','' ||',
'               label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo3'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'    function atualizar_tela return varchar2 is',
'    begin',
'        return ''true'';',
'    end;',
'',
'end "UI_MPD_TD620";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td623
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157415108807247508)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD623'
,p_sequence=>1820
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD623" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'end "UI_MPD_TD623";',
'/',
'create or replace package body "UI_MPD_TD623" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);',
'        l_url varchar2(4000);',
'        l_id_item number;',
'    begin',
'        select id_item into l_id_item from ng_item_produto where id = p_param1;',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_item'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_item'';',
'',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005,',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'',',
'            p_values => ''TD537,TD537,''||l_id_item||'',''||l_id_coluna,',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'         USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_item'',                 3, ''TXT'', NULL, ''N'', ''N'', to_char((select a.codigo_item from ng_item a join ng_item_produto b on b.id_item = a.id where b.id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_item'',              4, ''TEX'',l_url,l_somente_leitura, ''N'', to_char((select pkg_traducao.get_traducao(a.descricao_item) from ng_item a join ng_item_produto b on b.id_item = a.id where b.id = p_param1'
||')) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',            6, ''SEL'', ''R_NG_UNIDADEMEDIDA.CODIGO_UNIDADEMEDIDA_-_SEM_NULO'', ''N'', ''N'', to_char((select a.id_unidademedida from ng_item a join ng_item_produto b on b.id_item = a.id where b.id '
||'= p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_barra'',                8, ''TXT'', NULL, ''N'', ''N'', to_char((select a.codigo_barra from ng_item a join ng_item_produto b on b.id_item = a.id where b.id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_familia_item'',             9, ''POP'', ''R_NG_ITEM.DESCRICAO_FAMILIA_ITEM'', ''N'', ''N'', to_char((select a.id_familia_item from ng_item a join ng_item_produto b on b.id_item = a.id where b.id = p_param1)) valor '
||'FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_unitario'',               11, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_ncm'',                      13, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naladi'',                   15, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fabricante'',               17, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''fator_conversao_1'',           19, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''fator_conversao_2'',           21, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''fator_conversao_3'',           23, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_licenca_importacao'',                    26, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_bloqueio_embarque_ate_deferimento_li'',           28, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',           29, ''DAT'', NULL, ''N'', ''N'', to_char((select b.data_fim_vigencia from ng_item_produto a join ng_item b on b.id = a.id_item where a.id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',          30, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',              32, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_item_produto where id = p_param1), ''DATA_SEGUNDO'') valor from dual',
'               )  new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD623";',
'/'))
);
end;
