'--             p_consulta_sql => ''select b.codigo_item codigo_item,b.descricao_item descricao_item',
'--                                from ng_item_produto a ',
'--                                join ng_item b on b.id = a.id_item',
'--                                where a.id = ''||p_param1,',
'--             p_tabela => textarray(''ng_item'',''ng_item''),',
'--             p_formato => ''pequeno'',',
'--             p_tipo_label => ''coluna'',',
'--             p_classe  => ''st-back-transparente''',
'--         );',
'--         return l_html;',
'--     end;',
