prompt --application/deployment/install/install_ui_mpd_td629
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157415507216240606)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD629'
,p_sequence=>1840
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD629" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'end "UI_MPD_TD629";',
'/',
'create or replace package body "UI_MPD_TD629" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        pkg_ui.retorna_label_tela(''dados_gerais'')||''</h3></div>'' ||',
'        pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao from imp_pedidoimportacao a where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pedido_importacao'',  2, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',     3, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_exportador'',                 4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                 5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                 6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_viatransporte'',              8, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_incoterm'',                   9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                     10, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_listapreco'',                11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_comprador'',                 12, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_vendedor'',                13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_proforma'',              15, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',           16, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',               17, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from imp_pedidoimportacao where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'end "UI_MPD_TD629";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td630
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157415763948237558)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD630'
,p_sequence=>1850
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD630" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD630";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD630" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'    begin   ',
'        l_sql := ''',
'            select distinct',
'                a.id ,',
'                a.data_fim_vigencia,',
'                pkg_traducao.get_traducao(a.descricao_atributoitem)                          titulo, ',
'                b.nome_fantasia             subtitulo,  ',
'                null                        distintivo,            ',
'                ''''u-hidden''''                  class_distintivo,                           ',
'                null                        lista_distintivo,            ',
'                --ATRIBUTOS       ',
'                pkg_componentes.html_card_colunas(''''ng_atributoitem.ind_tipo_item'''', (pkg_util.dominio_retorna_tag(''''ng_atributoitem'''', ''''ind_tipo_item'''', a.ind_tipo_item)), 4 ) ',
'                                           atributo1,  ',
'                pkg_componentes.html_card_colunas(''''ng_atributoitem.ind_item_operacao'''', (pkg_util.dominio_retorna_tag(''''ng_atributoitem'''', ''''ind_item_operacao'''', a.ind_item_operacao)), 4 ) ',
'                                           atributo2,',
'                pkg_componentes.html_card_colunas(''''ng_atributoitem.ind_valor'''', (pkg_util.dominio_retorna_tag(''''ng_atributoitem'''', ''''ind_valor'''', a.ind_valor)), 4 )     ',
'                                           atributo3,',
'                CASE',
'                        WHEN a.ind_situacao = ''''E'''' THEN',
'                 pkg_componentes.html_card_colunas(''''ng_atributoitem.ind_situacao'''',''''<span><i title="''||l_hover_ind_situacao||'' "class="fa fa-warning"></i></span>'''', 4 )     ',
'                           ',
'                        ELSE',
'                            NULL',
'                END                       atributo4,  ',
'',
'                case ',
'                when a.data_fim_vigencia is null then',
'                    null',
'                when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                    pkg_componentes.html_card_colunas(''''ng_atributoitem.data_fim_vigencia'''', ',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')), 4) ',
'                else',
'                    pkg_componentes.html_card_colunas(''''ng_atributoitem.data_fim_vigencia'''', pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''), 4) ',
'                end                         atributo5,',
'                --FILTROS',
'                a.id_tenant         filtro1,',
'                a.ind_tipo_item     filtro2,',
'                a.ind_item_operacao filtro3,',
'                a.ind_valor         filtro4,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                    pkg_ui.url_mais_detalhes(''''TD630'''',a.id) url_mais_detalhes,',
'                    pkg_componentes.html_botao_opcao(a.id,''''TD630'''') as opcao  ',
'',
'                from ng_atributoitem a',
'                JOIN mpd_tenant b on b.id = a.id_tenant ',
'                Order by #ORDER#',
'',
'           '';',
'           --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'           l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'           return l_sql;',
'           -- Order by 2 nulls first,3,8,9,10',
'           -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'         l_hover_ind_situacao varchar2(4000);',
'    begin   ',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;',
'        l_sql := ''',
'        select',
'            a.id id,',
'            b.nome_fantasia                                 campo1,',
'            pkg_traducao.get_traducao(a.descricao_atributoitem)  campo2,',
'            pkg_util.dominio_retorna_tag(''''ng_atributoitem'''', ''''ind_tipo_item'''', a.ind_tipo_item)',
'                                                             campo3,',
'            pkg_util.dominio_retorna_tag(''''ng_atributoitem'''', ''''ind_item_operacao'''', a.ind_item_operacao)',
'                                                             campo4,',
'            pkg_util.dominio_retorna_tag(''''ng_atributoitem'''', ''''ind_valor'''', a.ind_valor)',
'                                                             campo5,',
'            CASE',
'                    WHEN a.ind_situacao = ''''E'''' THEN',
'                        ''''<span><i title="''||l_hover_ind_situacao||'' "class="fa fa-warning"></i></span>''''',
'                    ELSE',
'                        NULL',
'            END                                              campo6,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date)  then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')',
'            end                                              campo7,',
'            a.data_fim_vigencia                              campo8,',
'            null                                             campo9,',
'            null                                             campo10,',
'            --FILTROS',
'            a.id_tenant                                      filtro1,                                ',
'            a.ind_tipo_item                                  filtro2,                                ',
'            a.ind_item_operacao                              filtro3,                                ',
'            a.ind_valor                                      filtro4,',
'            null                                             filtro5,                                ',
'            --FILTROS MULTI',
'            null                                             filtro_mult1,                                ',
'            null                                             filtro_mult2,                                ',
'            null                                             filtro_mult3, ',
'            null                                             filtro_mult4,                                ',
'            null                                             filtro_mult5,                                ',
'            null opcao',
'        from ng_atributoitem a',
'        JOIN mpd_tenant b ON a.id_tenant = b.id  ',
'',
'       '';',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                id,',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,',
'                campo6,',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD630'') as opcao  ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_atributoitem'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                        ',
'        return l_sql;',
'        -- order by to_date(campo8,''dd/mm/yyyy'') nulls first, campo2, campo3, campo4 ,campo5 ',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_atributoitem'', ''ind_tipo_item'')~'';',
'        elsif campo = ''3'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_atributoitem'', ''ind_item_operacao'')~'';',
'        elsif campo = ''4'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_atributoitem'', ''ind_valor'')~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro; ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo IN (''1'',''F1'') then',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.descricao_atributoitem'') into l_campo from dual;  ',
'        elsif campo = ''3'' then                        ',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_tipo_item'') into l_campo from dual;',
'        elsif campo = ''4'' then                        ',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_item_operacao'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_valor'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_situacao'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''F2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_tipo_item'') into l_campo from dual;',
'        elsif campo = ''F3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_item_operacao'') into l_campo from dual;',
'        elsif campo = ''F4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_atributoitem.ind_valor'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo8,campo1'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo'';',
'        end if;',
'',
'        select label_coluna(''7'') || '','' ||',
'        label_coluna(''1'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''7'') || '','' ||',
'               label_coluna(''1'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo8,campo1'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD630";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td633
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157416091114227777)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD633'
,p_sequence=>1860
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD633" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'end "UI_MPD_TD633";',
'/',
'create or replace package body "UI_MPD_TD633" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna_descricao_resumida number;',
'        l_id_coluna_descricao_completa number;                        ',
'        l_descricao_resumida clob;',
'        l_permite_edicao_descricao_resumida varchar2(5);',
'        l_erro_descricao_resumida clob;',
'        l_descricao_completa clob;',
'        l_permite_edicao_descricao_completa varchar2(5);',
'        l_erro_descricao_completa clob;',
'        l_descricao clob;',
'        l_id_idioma_logado number := apex_util.get_session_state(''IDIOMA_LOGADO'');',
'        l_id_idioma_tenant number;',
'        l_id_tenant_origem number;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);',
'        l_id_coluna number;',
'        l_url varchar2(4000);',
'        l_ind_situacao varchar2(1);',
'        l_interacao_situacao varchar2(5);',
'        l_situacao_em_digitacao varchar2(20);',
'        l_hover_ind_situacao varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_atributoitem'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_atributoitem'';             ',
'        select ind_situacao into l_ind_situacao from ng_atributoitem where id = p_param1;',
'',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        ); ',
'',
'',
'        if UPPER(l_ind_situacao) = UPPER(''D'') then',
'            l_interacao_situacao := ''HID'';',
'        else',
'            l_interacao_situacao := '''';',
'        end if;',
'',
'',
'       MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''descricao_atributoitem'',      4, '''', l_url, l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao_atributoitem) from ng_atributoitem where id = p_param1)) valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''ind_item_operacao'',           6,  '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_valor'',                   8,  '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''qtd_decimais'',                10, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_inicial'',               12, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_final'',                 14, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_obrigatorio'',             16, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''ind_situacao'',                22, l_interacao_situacao, null, ''N'', ''S'', (select case when l_ind_situacao = ''E'' then ''fa-exclamation-triangle'' else ''fa-check-circle'' end from ng_atributoitem where id = p_param'
||'1) valor FROM dual UNION ALL                          ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',           18, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',          20, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',              22, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_atributoitem where id = p_param1), ''DATA_SEGUNDO'') valor from dual                                         '
||'    ',
'               )  new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD633";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td638
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157416218447222528)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD638'
,p_sequence=>1870
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD638" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure esconde_incluir;',
'',
'    function mostra_opcao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'end "UI_MPD_TD638";',
'/',
'',
'create or replace package body "UI_MPD_TD638" as',
'',
'    procedure esconde_incluir is',
'    begin',
'        null;',
'    end;',
'',
'    function mostra_opcao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9000,',
'            p_items=> ''P9000_ID,P9000_PAGINA,P9000_PARAMETRO'',',
'            p_values => p_param1 || '',TD638,0'',',
'            p_triggering_element => ''apex.jQuery("#BOTAO_OPCAO")''',
'            );',
'    return l_url;',
'    end;',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao from imp_pedidoimportacao a where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'    begin ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from n'
||'g_item_produto where id = p_param1)) valor from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_condicaopagamento'', 3, '''', null, ''S'', ''S'', null valor from dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas_pagamento'',  5, '''', null, ''S'', ''S'', null valor from dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao_parcela_pagamento'', 6, '''', null, ''S'', ''S'', null valor from dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~      ',
'            select ',
'                a.id id,',
'                null campo1,                ',
'                b.num_entrega campo2,',
'                a.numero_parcela campo3,',
'                a.percentual||''%'' campo4,             ',
'                to_char(a.valor, ''FM999G999G990D00'') campo5,',
'                case',
'                    when a.ind_status_pagamento = 1 then ',
'                        pkg_data.fmtd(a.data_vencimento_prevista, ''DATA'')',
'                    else                        ',
'                        pkg_data.fmtd(a.data_vencimento_real, ''DATA'')',
'                end campo6,                ',
'                case',
'                    when a.ind_status_pagamento = 1 and a.data_vencimento_prevista is not null then ',
'                        pkg_componentes.html_cor_texto(pkg_util.dominio_retorna_tag(''imp_pedidoimportacao_pagamento'', ''ind_status_pagamento'', a.ind_status_pagamento))',
'                    else                        ',
'                        pkg_util.dominio_retorna_tag(''imp_pedidoimportacao_pagamento'', ''ind_status_pagamento'', a.ind_status_pagamento)',
'                end campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                --FILTROS',
'                null filtro1,                                ',
'                null filtro2,                                ',
'                null filtro3,                                ',
'                null filtro4,',
'                null filtro5,                                ',
'                --FILTROS MULTI',
'                null filtro_mult1,                                ',
'                null filtro_mult2,                                ',
'                null filtro_mult3, ',
'                null filtro_mult4,                                ',
'                null filtro_mult5,',
'                case a.ind_status_pagamento',
'                    when 1 then pkg_componentes.html_botao_opcao(a.id,''TD638'') ',
'                    when 2 then pkg_componentes.html_botao_opcao(p_id => d.id, p_pagina => ''TD638'', p_param1 => -1)',
'                    when 3 then pkg_componentes.html_botao_opcao(p_id => d.id, p_pagina => ''TD638'', p_param1 => -1)',
'                end opcao',
'                --pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD638'', p_param1 => 0) opcao                ',
'            from imp_pedidoimportacao_pagamento a',
'            left join imp_entrega b on b.id = a.id_entrega',
'            join imp_pedidoimportacao c on c.id = a.id_pedidoimportacao',
'            left join fin_titulopagamento d on d.id_referencia = a.id and d.id_entidade = (',
'                select id from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao''',
'            )',
unistr('            -- PARCELA DE PAGAMENTO DO PEDIDO DE IMPORTA\00C7\00C3O PODE TER MAIS DE UM T\00CDTULO GERADO COM STATUS DIFERENTE:'),
'            and d.ind_status_pagamento not in (3,4) ',
'            ',
'            where c.id = #PARAM1#',
'            order by campo2 nulls first, campo3',
'        ~'' ;  ',
'        l_sql := replace(l_sql,''#PARAM1#'',nvl(p_param1,''''));',
'        return l_sql;',
'    end sql_report;',
'    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.id_entrega'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.numero_parcela'') into l_campo from dual;',
'        elsif campo = ''4'' then                        ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.percentual'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.valor'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_tela(''vencimento'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.ind_status_pagamento'') into l_campo from dual;                    ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'',
'end "UI_MPD_TD638";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td645
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157416440309219470)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD645'
,p_sequence=>1880
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD645" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD645";',
'/',
'create or replace package body "UI_MPD_TD645" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin ',
'        --l_html := ''Parametro 1: ''||p_param1||'', Parametro 2: ''||p_param2||'', Parametro 3: ''||p_param3;',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    numero_pedido_importacao/*, ',
'                    case when lower(ind_todos_itens_com_entregas_programadas) = ''''n'''' then',
'                        pkg_componentes.html_cor_texto(pkg_util.dominio_retorna_tag(''''imp_pedidoimportacao'''',''''ind_todos_itens_com_entregas_programadas'''',ind_todos_itens_com_entregas_programadas))',
'                    else',
'                        pkg_util.dominio_retorna_tag(''''imp_pedidoimportacao'''',''''ind_todos_itens_com_entregas_programadas'''',ind_todos_itens_com_entregas_programadas)',
'                    end ind_todos_itens_com_entregas_programadas*/',
'                from imp_pedidoimportacao where id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                a.num_entrega titulo,',
'                pkg_util.dominio_retorna_tag(''imp_entrega'', ''ind_status_entrega'', a.ind_status_entrega) subtitulo,',
'                bo_ng_viatransporte.retorna_icone_viatransporte_card(a.id_viatransporte) icon,',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS                ',
'                pkg_componentes.html_card_colunas(''imp_entrega.id_local_embarque'', pkg_traducao.get_traducao(c.nome_local), 2',
'                ) atributo1,  ',
'                pkg_componentes.html_card_colunas(''imp_entrega.id_local_desembarque'', pkg_traducao.get_traducao(d.nome_local), 2',
'                ) atributo2,   ',
'                case ',
'                    when a.data_disponivel_real is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_disponivel_real'', ',
'                            pkg_data.fmtd(a.data_disponivel_real, ''DATA''), 2',
'                        )',
'                    when a.data_disponivel_informada is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_disponivel_informada'', ',
'                            pkg_data.fmtd(a.data_disponivel_informada, ''DATA''), 2',
'                        )',
'                    when a.data_disponivel_calculada is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_disponivel_calculada'', ',
'                            pkg_data.fmtd(a.data_disponivel_calculada, ''DATA''), 2',
'                        )',
'                end atributo3,',
'                case ',
'                    when a.data_embarque_informada is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_embarque_informada'', ',
'                            pkg_data.fmtd(a.data_embarque_informada, ''DATA''), 2',
'                        )                    ',
'                    when a.data_embarque_calculada is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_embarque_calculada'', ',
'                            pkg_data.fmtd(a.data_embarque_calculada, ''DATA''), 2',
'                        )',
'                end atributo4,',
'                case ',
'                    when a.data_desembarque_informada is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_desembarque_informada'', ',
'                            pkg_data.fmtd(a.data_desembarque_informada, ''DATA''), 2',
'                        )                    ',
'                    when a.data_desembarque_calculada is not null then',
'                        pkg_componentes.html_card_colunas(''imp_entrega.data_desembarque_calculada'', ',
'                            pkg_data.fmtd(a.data_desembarque_calculada, ''DATA''), 2',
'                        )',
'                end atributo5,                                ',
'                --FILTROS                ',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD645'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => b.id, p_pagina => ''TD645'', p_param1 => b.id) as opcao             ',
'            from imp_entrega a',
'            join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'            left join ng_localembarquedesembarque c on c.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque d on d.id = a.id_local_desembarque',
'            where a.id_pedidoimportacao = #PARAM1#',
'            order by 2',
'            ~'';  ',
'            l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select distinct',
'            a.id id,  ',
'            a.num_entrega campo1,',
'            pkg_util.dominio_retorna_tag(''imp_entrega'', ''ind_status_entrega'', a.ind_status_entrega) campo2,',
'            pkg_util.dominio_retorna_tag(''ng_viatransporte'',''descricao_viatransporte'',descricao_viatransporte) campo3,            ',
'            pkg_traducao.get_traducao(c.nome_local) campo4,',
'            pkg_traducao.get_traducao(d.nome_local) campo5,',
'            case ',
'                when a.data_disponivel_real is not null then',
'                    pkg_data.fmtd(a.data_disponivel_real, ''DATA'')                    ',
'                when a.data_disponivel_informada is not null then                    ',
'                    pkg_data.fmtd(a.data_disponivel_informada, ''DATA'')                    ',
'                when a.data_disponivel_calculada is not null then                    ',
'                    pkg_data.fmtd(a.data_disponivel_calculada, ''DATA'')',
'            end campo6,',
'            case ',
'                when a.data_embarque_informada is not null then',
'                    pkg_data.fmtd(a.data_embarque_informada, ''DATA'')                                        ',
'                when a.data_embarque_calculada is not null then',
'                    pkg_data.fmtd(a.data_embarque_calculada, ''DATA'')                    ',
'            end campo7,',
'            case ',
'                when a.data_desembarque_informada is not null then',
'                    pkg_data.fmtd(a.data_desembarque_informada, ''DATA'')',
'                when a.data_desembarque_calculada is not null then',
'                    pkg_data.fmtd(a.data_desembarque_calculada, ''DATA'')',
'            end campo8,    ',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            null filtro1,',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,            ',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            pkg_componentes.html_botao_opcao(p_id => b.id, p_pagina => ''TD645'', p_param1 => b.id) as opcao',
'        from imp_entrega a',
'        join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'        left join ng_localembarquedesembarque c on c.id = a.id_local_embarque',
'        left join ng_localembarquedesembarque d on d.id = a.id_local_desembarque',
'        where a.id_pedidoimportacao = #PARAM1#              ',
'       ~'';       ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_entrega'')) a',
'            order by campo1',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.ind_status_entrega'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_viatransporte'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_local_embarque'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_local_desembarque'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.data_disponivel_real'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_informada'') into l_campo from dual;        ',
'        elsif campo = ''8'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.data_desembarque_informada'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia, nome_fantasia'';',
'        else',
'            campos := ''campo5, campo2'';',
'        end if;',
'        labels := label_coluna(''5'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD645";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td649
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157416699471201539)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD649'
,p_sequence=>1890
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD649" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure esconde_incluir;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in number) return clob;',
'',
'end "UI_MPD_TD649";',
'/',
'create or replace package body "UI_MPD_TD649" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select numero_pedido_importacao from imp_pedidoimportacao where id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    ',
'    procedure esconde_incluir is',
'    begin',
'        null;',
'    end;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, '''' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' as coluna_tabela from dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela);',
'    end formulario;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~      ',
'            select ',
'                a.id,                                                            ',
'                null campo1,',
'                --pkg_util.dominio_retorna_tag(''imp_pedidoimportacao_pagamento'', ''ind_base_calculo'', a.ind_base_calculo) campo1,   ',
'                b.num_entrega campo2,',
'                a.numero_parcela campo3,',
'                a.percentual||''%'' campo4,             ',
'                to_char(a.valor, ''FM999G999G990D00'') campo5,             ',
'                nvl(pkg_data.fmtd(a.data_vencimento_real, ''DATA''), pkg_data.fmtd(a.data_vencimento_prevista, ''DATA'')) campo6,',
'                null campo7,             ',
'                null campo8,                                      ',
'                null campo9,                                      ',
'                null campo10,                                ',
'                --FILTROS',
'                null filtro1,                                ',
'                null filtro2,                                ',
'                null filtro3,                                ',
'                null filtro4,',
'                null filtro5,                                ',
'                --FILTROS MULTI',
'                null filtro_mult1,                                ',
'                null filtro_mult2,                                ',
'                null filtro_mult3, ',
'                null filtro_mult4,                                ',
'                null filtro_mult5,',
'                null opcao                ',
'            from imp_pedidoimportacao_pagamento a',
'            left join imp_entrega b on b.id = a.id_entrega',
'            join imp_pedidoimportacao c on c.id = a.id_pedidoimportacao',
'            where c.id = #PARAM1#',
'            order by campo2 nulls first, campo3',
'        ~'';',
'        l_sql := replace(l_sql,''#PARAM1#'',nvl(p_param1,''''));',
'        return l_sql;',
'    end sql_report;',
'    ',
'',
'    function label_coluna(campo in number)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then',
'            null;--select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.ind_base_calculo'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.id_entrega'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.numero_parcela'') into l_campo from dual;',
'        elsif campo = ''4'' then                        ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.percentual'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.valor'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_tela(''vencimento'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'',
'end "UI_MPD_TD649";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td650
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157416842232198517)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD650'
,p_sequence=>1900
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD650" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'   ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD650";',
'/',
'',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD650" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select b.codigo_item codigo_item, pkg_traducao.get_traducao(b.descricao_item) descricao_item',
'                               from ng_item_produto a ',
'                               join ng_item b on b.id = a.id_item',
'                               where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_item'',''ng_item''),',
'            p_formato => ''pequeno'',',
'            --p_icones => textarray(/*''fa-database'', ''fa-database'',*/ ''fa-user'', ''fa-calendar fam-clock fam-is-success'', ''fa-calendar fam-clock fam-is-warning'', ''fa-flag''),',
unistr('            --p_label_fixo => textarray(''Workspace'', ''Aplica\00E7\00F5es'', ''P\00E1ginas'', ''Usu\00E1rios APEX''),'),
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        )',
'        ;',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := ',
'            ''select distinct',
'                a.id,',
'                ''''Valor do atributo: '''' || coalesce(',
'                    a.Valor_atributo_texto,',
'                    pkg_data.fmtd(a.Valor_atributo_data, ''''DATA''''),',
'                    case ',
'                        when c.qtd_decimais = 0 then',
'                            replace(to_char(a.Valor_atributo_valor, ''''FM999999999990''''), ''''.'''', '''''''')',
'                        else',
'                            replace(',
'                                to_char(',
'                                    a.Valor_atributo_valor,',
'                                    ''''FM999999999990D'''' || rpad(''''0'''', c.qtd_decimais, ''''0'''')',
'                                ),',
'                                ''''.'''',',
'                                '''',''''',
'                            )',
'                    end,',
'                    (select pkg_traducao.get_traducao(descricao_dominio) ',
'                     from ng_atributoitem_dominio ',
'                     where id = a.Valor_atributo_dominio)',
'                ) subtitulo,',
'                pkg_ui.retorna_label_coluna(''''ng_atributoitem.descricao_atributoitem'''') || '''': '''' || pkg_traducao.get_traducao(c.descricao_atributoitem) titulo,',
'                null distintivo,',
'                null lista_distintivo,',
'                ''''u-hidden'''' class_distintivo,',
'                null icon,',
'                null filtro1,',
'                null filtro2,',
'                null filtro_mult1,',
'                null filtro_mult2,',
'                pkg_ui.url_mais_detalhes(''''TD650'''', a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id, ''''TD650'''') as opcao',
'             from ng_item_atributoitem a',
'             join ng_item_produto b on b.id_item = a.id_item',
'             join ng_atributoitem c on c.id = a.id_atributoitem',
'             where b.id = '''''' || p_param1 || ''''''',
'             order by #ORDER#'';',
'',
'',
'            l_sql := replace(l_sql, ''#PARAM1#'', '''''''' || p_param1 || '''''''');',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));          ',
'            return l_sql;',
'        -- order by titulo, subtitulo;',
'        -- return replace(l_sql,''#CODIGO_ARTEFAT'',p_codigo_artefato);',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'',
'    begin   ',
'',
'        l_sql := ''      ',
'         select ',
'            a.id,                                                            ',
'            pkg_traducao.get_traducao(c.descricao_atributoitem) campo1,   ',
'         coalesce(',
'            a.Valor_atributo_texto,',
'            pkg_data.fmtd(a.Valor_atributo_data, ''''DATA''''),',
'            case ',
'                when c.qtd_decimais = 0 then',
'                    replace(to_char(a.Valor_atributo_valor, ''''FM999999999990''''), ''''.'''', '''''''')',
'                else',
'                    replace(',
'                        to_char(',
'                            a.Valor_atributo_valor,',
'                            ''''FM999999999990D'''' || rpad(''''0'''', c.qtd_decimais, ''''0'''')',
'                        ),',
'                        ''''.'''',',
'                        '''',''''',
'                    )',
'            end,',
'            (select pkg_traducao.get_traducao(descricao_dominio) ',
'               from ng_atributoitem_dominio ',
'              where id = a.Valor_atributo_dominio)',
'             ) as campo2,',
'            null campo3,',
'            null campo4,             ',
'            null campo5,             ',
'            null campo6,',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,                                ',
'            --FILTROS',
'            null filtro1,                                ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_item_atributoitem a',
'        join ng_item_produto                 b ON b.id_item = a.id_item',
'        join ng_atributoitem                 c ON c.id = a.id_atributoitem',
'        where b.id =  #PARAM1# ',
'       '' ;       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id, ''TD650'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_item_atributoitem'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1'')); ',
'        return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        --if campo = ''1'' then',
'            --return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        --else ',
'           return null;',
'        --end if;       ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'       if campo =''1'' then                     ',
'            select pkg_ui.retorna_label_tela(''tipo_atributo'') into l_campo from dual;',
'        elsif campo =''2'' then                     ',
'            select pkg_ui.retorna_label_tela(''valor_atributo'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2'';',
'        else',
'            campos := ''titulo,subtitulo'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''1'') || '','' ||',
'               label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo1,campo2'';',
'        else',
'            l_campos := ''titulo,subtitulo'';',
'        end if; ',
'',
'        l_direcoes := ''ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD650";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td651
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157417046485194886)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD651'
,p_sequence=>1910
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD651" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'',
'end "UI_MPD_TD651";',
'/',
'create or replace package body "UI_MPD_TD651" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select b.codigo_item codigo_item,pkg_traducao.get_traducao(b.descricao_item) descricao_item',
'                               from ng_item_produto a ',
'                               join ng_item b on b.id = a.id_item',
'                               where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_item'',''ng_item''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        dependecia_campo_txt varchar2(2000);',
'        dependecia_campo_num varchar2(2000);',
'        dependecia_campo_dat varchar2(2000);',
'        dependecia_campo_lis varchar2(2000);',
'        l_ind_valor_txt varchar2(10);',
'        l_ind_valor_num varchar2(10);',
'        l_ind_valor_dat varchar2(10);',
'        l_ind_valor_lis varchar2(10);',
'        l_id_atributoitem varchar2(10);',
'        l_consulta varchar2(2000);',
'        l_atribuir_valor_ind_valor clob; ',
'        l_campos apex_t_varchar2 := apex_t_varchar2(''IND_VALOR'',''QTD_DECIMAIS'',''VALOR_INICIAL'',''VALOR_FINAL'');',
'        v_executa_js_digito CLOB;',
'        v_executa_js_minimo CLOB;',
'        v_executa_js_maximo CLOB;',
'        v_json_dependecia_ind_valor CLOB;',
'        v_condicoes_ind_valor      array_varchar := array_varchar(''IND_VALOR == %L%'', ''IND_VALOR == %D%'', ''IND_VALOR == %T%'', ''IND_VALOR == %N%'');',
'        v_colunas_alvo_ind_valor   array_varchar := array_varchar(''VALOR_ATRIBUTO_DOMINIO'', ''VALOR_ATRIBUTO_DATA'', ''VALOR_ATRIBUTO_TEXTO'', ''VALOR_ATRIBUTO_VALOR'');',
'        v_comportamentos_ind_valor array_varchar := array_varchar(''vis'', ''vis'', ''vis'', ''vis'');',
'    begin ',
'        v_json_dependecia_ind_valor := gerar_json_dependencias_array(v_condicoes_ind_valor, v_colunas_alvo_ind_valor, v_comportamentos_ind_valor);',
'        ',
'        prc_enviar_parametros(''TD651'',''id_atributoitem'',p_param1);',
'        v_executa_js_digito := ''atualizarDigitsCampo("VALOR_ATRIBUTO_VALOR","QTD_DECIMAIS","VALOR_INICIAL","VALOR_FINAL");'';',
'',
'',
'        --v_executa_js_digito := ''atualizarDigitsCampoCleave("VALOR_ATRIBUTO_VALOR", "QTD_DECIMAIS");'';',
'        ',
'',
'        l_consulta := ',
'            ''select ',
'                d, r ',
'             from (',
'                select ',
'                    pkg_traducao.get_traducao(descricao_dominio) d,',
'                    a.id r',
'                from ng_atributoitem_dominio a ',
'                where a.id_atributoitem = (',
'                    select id ',
'                    from ng_atributoitem ',
'                    where descricao_atributoitem = (',
'                        select c002 ',
'                        from apex_collections ',
'                        where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' ',
'                          and upper(c001) = upper(''''f05_0000'''')',
'                    )',
'                )',
'             ) ',
'             order by d'';',
'        l_atribuir_valor_ind_valor := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor'',',
'            l_campos',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from n'
||'g_item_produto where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_item'',                       3, ''HID'', null, ''S'', ''S'', to_char((select id_item from ng_item_produto where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js, null id_artefato_ver'
||'sionado_zoom from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_atributoitem'',               4, '''',null, ''N'', ''S'', null , null, l_atribuir_valor_ind_valor atribuir_valor, null executa_js, 6025 id_artefato_versionado_zoom FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''IND_VALOR'',                     8, ''HID'',null, ''N'', ''N'', null , v_json_dependecia_ind_valor dependencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''QTD_DECIMAIS'',                  12,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js, null id_artefato_versionado_zoom from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''VALOR_INICIAL'',                 14,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js, null id_artefato_versionado_zoom from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''VALOR_FINAL'',                   16,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js, null id_artefato_versionado_zoom from dual UNION ALL                ',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_DATA'',           9, '''', null, ''N'', ''S'', null ,  null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_VALOR'',          10, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_TEXTO'',          11, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_DOMINIO'',        6, ''POP1'',to_char(l_consulta), ''N'', ''S'', null , null, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js, id_artefato_versionado_zoom)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js, new_data.id_artefato_versionado_zoom);',
'    end formulario;',
'',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~ ',
'                    select ind_valor, qtd_decimais, valor_inicial, valor_final',
'                    from ng_atributoitem ',
'                    where id = #ID#  ',
'               ~'';',
'        return replace(l_sql,''#ID#'',p_param1);',
'    end sql_atribuir_valor;',
'',
'    procedure post_create(',
'        p_id out number,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_ng_item_atributoitem.inclui_registro(',
'            p_id_tenant                   => apex_application.g_f02(1),',
'            p_id_item                     => apex_application.g_f03(1),',
'            p_id_atributoitem             => apex_application.g_f04(1),',
'            p_VALOR_ATRIBUTO_TEXTO        => apex_application.g_f11(1),',
'            p_VALOR_ATRIBUTO_DATA         => apex_application.g_f09(1),',
'            p_VALOR_ATRIBUTO_VALOR        => replace(apex_application.g_f10(1),separador_numerico,''''),',
'            p_VALOR_ATRIBUTO_DOMINIO      => apex_application.g_f06(1),',
'            p_id                          => p_id,                 ',
'            p_sucesso                     => p_sucesso,      ',
'            p_messages                    => p_messages',
'        );',
'    end;       ',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'',
'        l_sql := ''      ',
'         select ',
'            a.id,                                                            ',
'            pkg_traducao.get_traducao(c.descricao_atributoitem) campo1,   ',
'         coalesce(',
'            a.VALOR_ATRIBUTO_TEXTO,',
'            pkg_data.fmtd(a.VALOR_ATRIBUTO_DATA, ''''DATA''''),',
'            case ',
'                when c.qtd_decimais = 0 then',
'                    replace(to_char(a.Valor_atributo_valor, ''''FM999999999990''''), ''''.'''', '''''''')',
'                else',
'                    replace(',
'                        to_char(',
'                            a.Valor_atributo_valor,',
'                            ''''FM999999999990D'''' || rpad(''''0'''', c.qtd_decimais, ''''0'''')',
'                        ),',
'                        ''''.'''',',
'                        '''',''''',
'                    )',
'            end,',
'            (select pkg_traducao.get_traducao(descricao_dominio) ',
'               from ng_atributoitem_dominio ',
'              where id = a.VALOR_ATRIBUTO_DOMINIO)',
'             ) as campo2,',
'            null campo3,',
'            null campo4,             ',
'            null campo5,             ',
'            null campo6,',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,                                ',
'            pkg_componentes.html_botao_opcao(a.id,''''TD651'''') opcao',
'        from ng_item_atributoitem a',
'        join ng_item_produto                 b ON b.id_item = a.id_item',
'        join ng_atributoitem                 c ON c.id = a.id_atributoitem',
'        where b.id =  #param1# ',
'       '' ;  ',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report;',
'',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := ''      ',
'         select ',
'            a.id,                                                            ',
'            pkg_traducao.get_traducao(c.descricao_atributoitem) campo1,   ',
'         coalesce(',
'            a.VALOR_ATRIBUTO_TEXTO,',
'            pkg_data.fmtd(a.VALOR_ATRIBUTO_DATA, ''''DATA''''),',
'            case ',
'                when c.qtd_decimais = 0 then',
'                    replace(to_char(a.Valor_atributo_valor, ''''FM999999999990''''), ''''.'''', '''''''')',
'                else',
'                    replace(',
'                        to_char(',
'                            a.Valor_atributo_valor,',
'                            ''''FM999999999990D'''' || rpad(''''0'''', c.qtd_decimais, ''''0'''')',
'                        ),',
'                        ''''.'''',',
'                        '''',''''',
'                    )',
'            end,',
'            (select pkg_traducao.get_traducao(descricao_dominio) ',
'               from ng_atributoitem_dominio ',
'              where id = a.VALOR_ATRIBUTO_DOMINIO)',
'             ) as campo2,',
'            null campo3,',
'            null campo4,             ',
'            null campo5,             ',
'            null campo6,',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,                                ',
'            pkg_componentes.html_botao_opcao(a.id,''''TD651'''') opcao',
'        from ng_item_atributoitem a',
'        join ng_item_produto                 b ON b.id_item = a.id_item',
'        join ng_atributoitem                 c ON c.id = a.id_atributoitem',
'        where b.id =  #param1# ',
'       '' ;  ',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;',
'        --return ''select 1 ok from dual'';',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_tela(''tipo_atributo'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_tela(''valor_atributo'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'    ',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD983,TD983,''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD651";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td653
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157417291843190463)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD653'
,p_sequence=>1920
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD653" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob;',
'',
'',
'end "UI_MPD_TD653";',
'/',
'create or replace package body "UI_MPD_TD653" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        dependecia_campo_txt varchar2(2000);',
'        dependecia_campo_num varchar2(2000);',
'        dependecia_campo_dat varchar2(2000);',
'        dependecia_campo_lis varchar2(2000);',
'        l_ind_valor_txt varchar2(10);',
'        l_ind_valor_num varchar2(10);',
'        l_ind_valor_dat varchar2(10);',
'        l_ind_valor_lis varchar2(10);',
'        l_id_atributoitem varchar2(10);',
'        l_consulta varchar2(2000);',
'        l_atribuir_valor_ind_valor clob; ',
'        l_campos apex_t_varchar2 := apex_t_varchar2(''IND_VALOR'',''QTD_DECIMAIS'');',
'        v_executa_js_digito CLOB;',
'        v_executa_js_digito2 CLOB;',
'        v_json_dependecia_ind_valor CLOB;',
'        v_condicoes_ind_valor      array_varchar := array_varchar(''ind_valor == %L%'', ''ind_valor == %D%'', ''ind_valor == %T%'', ''ind_valor == %N%'');',
'        v_colunas_alvo_ind_valor   array_varchar := array_varchar(''Valor_atributo_dominio'', ''Valor_atributo_data'', ''Valor_atributo_texto'', ''VALOR_ATRIBUTO_VALOR'');',
'        v_comportamentos_ind_valor array_varchar := array_varchar(''vis'', ''vis'', ''vis'', ''vis'');',
'        v_ind_valor varchar2(10);',
'        l_valor_atributo varchar2(10);',
'          v_id_valor_atributo number;',
'        v_id_atributo number;',
'        v_valor_atributo_valor ng_item_atributoitem.valor_atributo_valor%type;',
'',
'',
'    begin ',
'        v_json_dependecia_ind_valor := gerar_json_dependencias_array(v_condicoes_ind_valor, v_colunas_alvo_ind_valor, v_comportamentos_ind_valor);',
'        select valor_atributo_dominio,id_atributoitem,valor_atributo_valor into v_id_valor_atributo,v_id_atributo,v_valor_atributo_valor from ng_item_atributoitem where id = p_param1;',
'',
'',
'       -- prc_enviar_parametros(''TD652'',''id_atributoitem'',p_param1);',
'        v_executa_js_digito :=',
'            ''setTimeout(function () {'' ||',
'            ''  var el = document.getElementById("VALOR_ATRIBUTO_VALOR");'' ||',
'            ''  if (!el) return;'' ||',
'            ''  if (el.dataset.init === "1") return;'' ||',
'            ''  el.dataset.init = "1";'' ||',
'            ''  if ("'' || v_valor_atributo_valor || ''" !== "") {'' ||',
'            ''     el.value = "'' || v_valor_atributo_valor || ''";'' ||',
'            ''  }'' ||',
'            ''}, 300);'';',
'        v_executa_js_digito2 := ''atualizarDigitsCampo("VALOR_ATRIBUTO_VALOR","QTD_DECIMAIS","VALOR_INICIAL","VALOR_FINAL");'';',
'',
'',
'        l_consulta := ',
'                ''select ',
'                    pkg_traducao.get_traducao(a.descricao_dominio) D, a.id  R',
'                from ng_atributoitem_dominio a',
'                join ng_atributoitem b on a.id_atributoitem = b.id',
'                where b.id = ''''''||v_id_atributo||''''''',
'                order by D'';',
'',
'        -- l_consulta := ',
'        --     ''select ',
'        --         d, r ',
'        --      from (',
'        --         select ',
'        --             descricao_dominio d,',
'        --             a.id r',
'        --         from ng_atributoitem_dominio a ',
'        --         where a.id_atributoitem = (',
'        --             select id ',
'        --             from ng_atributoitem ',
'        --             where descricao_atributoitem = (',
'        --                 select c002 ',
'        --                 from apex_collections ',
'        --                 where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' ',
'        --                   and upper(c001) = upper(''''f05_0000'''')',
'        --             )',
'        --         )',
'        --      ) ',
'        --      order by d'';',
'        l_atribuir_valor_ind_valor := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor'',',
'            l_campos',
'        );',
'',
'        select a.ind_valor',
'          into v_ind_valor',
'        from ng_atributoitem a',
'        join ng_item_atributoitem b ON b.id_atributoitem = a.id',
'        where b.id = p_param1;',
'',
'        if v_ind_valor = ''L'' then',
'            -- select descricao_dominio ',
'            -- into l_valor_atributo ',
'            -- from ng_atributoitem_dominio ',
'            -- where id = (select Valor_atributo_dominio from ng_item_atributoitem where id = p_param1);',
'            --l_valor_atributo := ''verde'';',
'',
'            select a.descricao_atributoitem',
'              into l_valor_atributo',
'            from ng_atributoitem a',
'            join ng_item_atributoitem b ON b.id_atributoitem = a.id',
'            where b.id = p_param1;',
'        end if;',
' ',
'       prc_enviar_parametros2(p_codigo_artefato,''f05_0000'',l_valor_atributo,apex_custom_auth.get_session_id);',
'',
'',
unistr('        -- se eu coloco o em valor ele d\00E1 certo mas d\00E1 erro no form:'),
'        --               SELECT p_codigo_artefato, ''Valor_atributo_dominio'',        6, ''POP1'',to_char(l_consulta), ''N'', ''S'',l_valor_atributo valor , null, null atribuir_valor, null executa_js from dual',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from n'
||'g_item_produto where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_item'',                       3, ''HID'', null, ''S'', ''S'', to_char((select id_item from ng_item_atributoitem where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js from dual UNION '
||'ALL',
'               SELECT p_codigo_artefato, ''id_atributoitem'',               4, '''',null, ''N'', ''S'', null , null, l_atribuir_valor_ind_valor atribuir_valor, null executa_js FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''IND_VALOR'',                     8, ''HID'',null, ''N'', ''N'', v_ind_valor valor , v_json_dependecia_ind_valor dependencia, null atribuir_valor, null executa_js from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''QTD_DECIMAIS'',                  12,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito2 executa_js from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''VALOR_INICIAL'',                 30,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''VALOR_FINAL'',                   35,''HID'',null, ''N'', ''N'', null , null dependencia, null atribuir_valor, v_executa_js_digito executa_js from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''Valor_atributo_data'',           9, '''', null, ''N'', ''S'', null ,  null dependencia , null atribuir_valor, null executa_js from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''VALOR_ATRIBUTO_VALOR'',          10, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''Valor_atributo_texto'',          11, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''Valor_atributo_dominio'',        6, ''POP1'',to_char(l_consulta), ''N'', ''S'',null , null, null atribuir_valor, null executa_js from dual UNION ALL ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',            16, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'',null , null, null atribuir_valor, null executa_js  FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                26, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from ng_item_atributoitem where id = p_param1), ''DATA_SEGUNDO'') valo, null, null atribuir_valor, null executa_js '
||' from dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'    ',
'    function sql_atribuir_valor(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~ ',
'                    select ind_valor, qtd_decimais',
'                    from ng_atributoitem ',
'                    where id = #ID#  ',
'               ~'';',
'        return replace(l_sql,''#ID#'',p_param1);',
'    end sql_atribuir_valor;',
'',
'',
'end "UI_MPD_TD653";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td655
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157417424572186929)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD655'
,p_sequence=>1930
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD655" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );    ',
'',
'end "UI_MPD_TD655";',
'/',
'create or replace package body "UI_MPD_TD655" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'    begin   ',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;',
'',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.data_fim_vigencia,',
'                pkg_traducao.get_traducao(a.descricao) ||'' ''||',
'                CASE',
'                    WHEN a.ind_situacao = ''E'' THEN',
'                        ''<span><i title="~'' || l_hover_ind_situacao || q''~" class="fa fa-warning"></i></span>''',
'                    ELSE',
'                        NULL',
'                END titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end distintivo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                null lista_distintivo,',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,',
'                pkg_ui.url_mais_detalhes(''TD655'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD655'') as opcao                ',
'            from imp_naturezaoperacao a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by 2 nulls first, 3',
'            ~'';',
'            --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));            ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'        l_html_ind_situacao varchar2(4000);',
'    begin',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;   ',
'',
'        l_html_ind_situacao := ''<i class="fa fa-warning" title="''||l_hover_ind_situacao||''"></i>'';',
'',
'        l_sql := ''',
'        select',
'            a.id,',
'            b.nome_fantasia campo1,',
'            pkg_traducao.get_traducao(a.descricao) campo2,',
'            CASE',
'                WHEN a.ind_situacao = ''''E'''' THEN',
'                    ''''<span><i title="''||l_hover_ind_situacao||'' "class="fa fa-warning"></i></span>''''',
'                ELSE',
'                    NULL',
'            END campo3,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')',
'            end campo4,',
'            a.data_fim_vigencia campo5,',
'            null                campo6,',
'            null                campo7,',
'            null                campo8,',
'            null                campo9,',
'            null                campo10,',
'            --FILTROS',
'            a.id_tenant       filtro1,                                ',
'            null              filtro2,                                ',
'            null              filtro3,                                ',
'            null              filtro4,',
'            null              filtro5,                                ',
'            --FILTROS MULTI',
'            null              filtro_mult1,                                ',
'            null              filtro_mult2,                                ',
'            null              filtro_mult3, ',
'            null              filtro_mult4,                                ',
'            null              filtro_mult5,                                ',
'            null opcao',
'        FROM imp_naturezaoperacao a',
'        join mpd_tenant b on b.id = a.id_tenant        ',
'       '';',
'       return l_sql;',
'    end sql_lista_oculta;',
'',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD655'') as opcao           ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_naturezaoperacao'')) a',
'            order by to_date(campo5) nulls first, campo2 ',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else ',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.descricao'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.ind_situacao'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'        ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia,descricao'';',
'        else',
'            campos := ''campo5,campo2'';',
'        end if;',
'        labels := label_coluna(''4'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD655";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td657
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157417644510184327)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD657'
,p_sequence=>1940
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 02/07/2026',
'-- Motivo: Ajuste para incluir novas colunas cst cclasstrib',
'-- Desenvolvedor: Jonathan',
'-- Jira: PEDITEM-4',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD657" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD657";',
'/',
'',
'create or replace package body "UI_MPD_TD657" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_descricao clob;',
'        l_permite_edicao_descricao_item varchar2(5);',
'        l_erro_descricao_item clob;',
'        l_somente_leitura varchar2(1);        ',
'        l_url varchar2(4000);',
'    begin        ',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''imp_naturezaoperacao'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao'';',
'',
'        if lower(l_permite_edicao_descricao_item) = ''false'' then',
'            l_somente_leitura:= ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'         l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||p_param1||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );               ',
'    ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null obrigatorio, nu'
||'ll tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''descricao'',                      3, '''', l_url, l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao) from imp_naturezaoperacao where id = p_param1)) valor, null obrigatorio, null tag_ca'
||'mpo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cst'',                            4, ''SEL'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.CST'', ''N'', ''N'', to_char((select cst from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, null obrigato'
||'rio, ''IMP_NATUREZAOPERACAO_PARAMETRO.CST'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cfop'',                        5, ''POP'', ''R_NG_CFOP.CODIGO_CFOP-DESCRICAO_CFOP'', ''N'', ''N'', to_char((select id_cfop from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, null obri'
||'gatorio, ''NG_CFOP.CODIGO_CFOP'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cclasstrib'',                     7, ''TXT'', null, ''N'', ''N'', to_char((select cclasstrib from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_P'
||'ARAMETRO.cclasstrib'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_gera_contabil'',              8, ''RAD'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_CONTABIL'', ''N'', ''N'', to_char((select ind_gera_contabil from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_p'
||'aram1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_CONTABIL'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_gera_financeiro'',           10, ''RAD'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_FINANCEIRO'', ''N'', ''N'', to_char((select ind_gera_financeiro from imp_naturezaoperacao_parametro where id_naturezaoperacao ='
||' p_param1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_FINANCEIRO'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_fatura'',               12, ''SEL'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_FATURA'', ''N'', ''N'', to_char((select ind_tipo_fatura from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param'
||'1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_FATURA'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_importacao'',           14, ''SEL'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_IMPORTACAO'', ''N'', ''N'', to_char((select ind_tipo_importacao from imp_naturezaoperacao_parametro where id_naturezaoperacao ='
||' p_param1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_IMPORTACAO'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_courrier'',                  16, ''RAD'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_COURRIER'', ''N'', ''N'', to_char((select ind_courrier from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) va'
||'lor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_COURRIER'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao'',                  17, '''', null, ''N'', ''S'', ''fa-exclamation-triangle warning-orange'' valor, null obrigatorio, null tag_campo FROM dual WHERE EXISTS (SELECT 1 FROM imp_naturezaoperacao WHERE id = p'
||'_param1 AND ind_situacao = ''E'') UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',             18, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                23, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM imp_naturezaoperacao WHERE id = p_param1), ''DATA_SEGUNDO'') valor, null obrigatorio, null tag_campo FROM dual'
||' UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao_parametro'',      22, ''HID'', null, ''N'', ''N'', to_char((select data_alteracao from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1), ''dd-mon-rr hh:mi:ss.ff6 am'') valor, null ob'
||'rigatorio, null tag_campo FROM dual union all',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',            20, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''id_naturezaoperacao_parametro'', 26, ''HID'', null, ''N'', ''N'', to_char((select id from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, null obrigatorio, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.tag_campo);',
'    end formulario;',
'',
'end "UI_MPD_TD657";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td662
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157417876951181273)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD662'
,p_sequence=>1950
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD662" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD662";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD662" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            SELECT',
'                a.id,                                   ',
'                pkg_traducao.get_traducao(a.descricao_embalagem) titulo,',
'                b.nome_fantasia subtitulo,                  ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo, ',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_siscomexembalagem.codigo_embalagem'',codigo_embalagem, 6) atributo1,            ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_siscomexembalagem.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 6) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_siscomexembalagem.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 6) ',
'                end atributo2,',
'                a.data_fim_vigencia,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,',
'                --TECNICO  ',
'                pkg_ui.url_mais_detalhes(''TD662'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD662'') as opcao   ',
'            FROM ng_siscomexembalagem a',
'            join mpd_tenant b on b.id = a.id_tenant   ',
'            order by #ORDER#',
'        ~'';       ',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'        return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'        select',
'            a.id,',
'            b.nome_fantasia campo1,',
'            a.codigo_embalagem campo2,',
'            pkg_traducao.get_traducao(a.descricao_embalagem) campo3,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            null                campo5,',
'            null                campo6,',
'            null                campo7,',
'            null                campo8,',
'            null                campo9,',
'            null                campo10,',
'            --FILTROS',
'            a.id_tenant       filtro1,                                ',
'            null              filtro2,                                ',
'            null              filtro3,                                ',
'            null              filtro4,',
'            null              filtro5,                                ',
'            --FILTROS MULTI',
'            null              filtro_mult1,                                ',
'            null              filtro_mult2,                                ',
'            null              filtro_mult3, ',
'            null              filtro_mult4,                                ',
'            null              filtro_mult5,                                ',
'            null opcao',
'        FROM ng_siscomexembalagem a',
'        join mpd_tenant b on b.id = a.id_tenant',
'       ~'';',
'       return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select       ',
'                id,         ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD662'') as opcao   ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_siscomexembalagem'')) a',
'            ORDER BY #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''2''));',
'        return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then            ',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_siscomexembalagem.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_siscomexembalagem.codigo_embalagem'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_siscomexembalagem.descricao_embalagem'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_siscomexembalagem.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo4,campo1,campo2,campo3'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,atributo1,titulo'';',
'        end if;',
'',
'        select label_coluna(''4'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''4'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''2'') || '','' ||',
'               label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo4,campo1,campo2'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,atributo1'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD662";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td665
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157418007978178448)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD665'
,p_sequence=>1960
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD665" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD665";',
'/',
'create or replace package body "UI_MPD_TD665" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;                        ',
'        l_descricao clob;',
'        l_permite_edicao varchar2(5);',
'        l_erro clob;',
'        l_url varchar2(4000);',
'    begin',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_siscomexembalagem'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_embalagem'';      ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''codigo_embalagem'',    3, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_embalagem'', 4, '''', to_char(l_url), ''S'', ''S'', to_char((select pkg_traducao.get_traducao(descricao_embalagem) from ng_siscomexembalagem where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',   5, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',  8, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL                                            ',
'               SELECT p_codigo_artefato, ''data_alteracao'',      9, ''TXT'', NULL, ''N'', ''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_siscomexembalagem WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD665";',
'/'))
);
end;
