prompt --application/deployment/install/install_ui_mpd_td683
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157418667214160467)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD683'
,p_sequence=>1970
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD683" as',
'    ',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function valida(p_id in number) return pkg_mensagem.message_record_table;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function esconder_opcao return varchar2;',
'',
'end "UI_MPD_TD683";',
'/',
'',
'create or replace package body "UI_MPD_TD683" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select ',
'                    b.numero_pedido_importacao, ',
'                    bo_ng_pessoa.retorna_pessoa(b.id_exportador) id_exportador,',
'                    pkg_util.dominio_retorna_tag(''''imp_pedidoimportacao'''',''''ind_status_pedido_importacao'''',b.ind_status_pedido_importacao) ind_status_pedido_importacao',
'                from imp_pedidoimportacao_item a ',
'                join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'                where a.id = ''|| regexp_substr(p_param2, ''[^_]+'', 1, 1),',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        ) || ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||retorna_texto(''msg.82.l'')||''</h3></div>'';',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob is',
'        l_id_pedidoimportacao number;',
'        l_sql clob;',
'    begin   ',
'        select a.id ',
'        into l_id_pedidoimportacao ',
'        from imp_pedidoimportacao a ',
'        join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id ',
'        where b.id = regexp_substr(apex_util.get_session_state(''P9014_PARAMETRO2''), ''[^_]+'', 1, 1);',
'',
'        l_sql := q''~',
'            select',
'                apex_item.radiogroup(',
'                    p_idx => 1,',
'                    p_value => a.id,',
'                    p_attributes => ''onclick="selecionaRadio(this);"''',
'                ) selected,',
'                a.id,',
'                a.num_entrega campo1,                ',
'                a.id_processoimportacao campo2,',
'                pkg_util.dominio_retorna_tag(''imp_entrega'', ''ind_status_entrega'', a.ind_status_entrega) campo3,',
'                coalesce(pkg_data.fmtd(a.data_disponivel_real, ''DATA''), pkg_data.fmtd(a.data_disponivel_informada, ''DATA''), pkg_data.fmtd(a.data_disponivel_calculada, ''DATA'')) campo4,',
'                coalesce(pkg_data.fmtd(a.data_embarque_real, ''DATA''), pkg_data.fmtd(a.data_embarque_informada, ''DATA''), pkg_data.fmtd(a.data_embarque_calculada, ''DATA'')) campo5,                ',
'                pkg_traducao.get_traducao(c.nome_local) campo6,',
'                pkg_traducao.get_traducao(d.nome_local) campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                null opcao',
'            from imp_entrega a',
'            left join ng_localembarquedesembarque c on c.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque d on d.id = a.id_local_desembarque',
'            where a.id_pedidoimportacao = #ID_PEDIDOIMPORTACAO#',
'            -- ',
'            and a.id_invoice is null',
'            --',
'            order by a.num_entrega',
'            ~'';',
'        l_sql := replace(l_sql,''#ID_PEDIDOIMPORTACAO#'',nvl(l_id_pedidoimportacao,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.num_entrega'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_processoimportacao'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.ind_status_entrega'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.data_disponivel_real'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_real'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_local_embarque'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''imp_entrega.id_local_desembarque'') into l_campo from dual;',
'        elsif campo = ''SEL'' then',
'            l_campo := ''sel'';         ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function valida(p_id in number)',
'        return pkg_mensagem.message_record_table ',
'    is',
'        l_id_entidade number;        ',
'        l_verifica_titulopagamento number;',
'',
'        v_parametro pkg_mensagem.paramentros;',
'        v_message   pkg_mensagem.message_record;',
'        v_messages  pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
unistr('        -- Verifica se existem t\00EDtulos de pagamento para esta entrega:'),
'        select count(1) into l_verifica_titulopagamento',
'        from fin_titulopagamento a',
'        join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'        where a.id_entidade = l_id_entidade',
'        and a.ind_status_pagamento in (1,2)',
'        and b.id_entrega = p_id;',
'        ',
unistr('        -- Valida\00E7\00E3o:'),
'        if l_verifica_titulopagamento > 0 then',
'            v_parametro(0) := ''UI_MPD_TD_683.valida'';',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem  => ''129'',',
'                p_nome_campo       => ''valor_total_condicao_venda'',',
'                p_parametro        => v_parametro,',
'                p_pagina           => 9014,',
'                p_objeto_mensagem  => v_message',
'            );',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;',
'        end if;',
'        return v_messages;',
'    end valida;',
'       ',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is  ',
'        l_mensagem_erro varchar2(4000) := retorna_texto(''msg.82.l'');',
'        l_ids_itens varchar2(4000) := apex_util.get_session_state(''P9014_PARAMETRO2'');',
'        l_id number;',
'    begin',
'        if p_id is null then',
'            raise pk_exceptions.e_erro;',
'        else',
'            bo_imp_entrega_item.vincula_itens_em_entrega_existente(',
'                p_id_pedidoimportacao_itens => l_ids_itens,',
'                p_id_entrega => p_id,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'    exception ',
'        when pk_exceptions.e_erro then',
'            apex_error.add_error (',
'                p_message => l_mensagem_erro,',
'                p_display_location => apex_error.c_inline_in_notification                ',
'            );',
'    end post;',
'',
'    function esconder_opcao return varchar2 is',
'    begin',
'        return ''true'';',
'    end;',
'',
'end "UI_MPD_TD683";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td686
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157418953219149432)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD686'
,p_sequence=>1980
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD686" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    function sql_atribuir_valor_ind_tipo_despesa(p_param1 in varchar2) return clob;',
'    ',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );   ',
'',
'end "UI_MPD_TD686";',
'/',
'create or replace package body "UI_MPD_TD686" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao, b.num_entrega from imp_pedidoimportacao a join imp_entrega b on b.id_pedidoimportacao = a.id where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'        l_atribuir_valor_ind_tipo_despesa clob;',
'        l_campos_ind_tipo_despesa apex_t_varchar2 := apex_t_varchar2(''IND_TIPO_DESPESA'');',
'    begin',
'        l_atribuir_valor_ind_tipo_despesa := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_ind_tipo_despesa'',',
'            l_campos_ind_tipo_despesa',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from imp_entrega where id = p'
||'_param1)) valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entrega'',                   2, ''HID'', null, ''N'', ''S'', p_param1 valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''IND_TIPO_DESPESA'',             3, ''SEL'', ''D_NG_DESPESA.IND_TIPO_DESPESA'', ''S'', ''N'', null valor, ''ng_despesa.ind_tipo_despesa'' tag_campo, null atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_despesa'',                   4, '''', null, ''N'', ''S'', null valor, null tag_campo, l_atribuir_valor_ind_tipo_despesa atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                     6, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor'',                        8, '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_incluso_valor_mercadoria'', 9, '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''taxa_cambio'',                 10, ''HID'', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status'',                  11, ''HID'', null, ''N'', ''S'', ''1'' valor, null tag_campo, null atribuir_valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, atribuir_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.atribuir_valor);',
'    end formulario;',
'',
'    function sql_atribuir_valor_ind_tipo_despesa(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := ''select ind_tipo_despesa from ng_despesa where id = #ID#'';',
'        return nvl(replace(l_sql,''#ID#'',p_param1),''999'');',
'    end sql_atribuir_valor_ind_tipo_despesa; ',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_despesa'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.ind_origem_despesa = 2',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is       ',
'        l_id number; ',
'    begin        ',
'        bo_imp_entrega_despesa.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_entrega => apex_application.g_f02(1),',
'            p_id_despesa => apex_application.g_f04(1),',
'            p_id_moeda => apex_application.g_f06(1),',
'            p_valor => pkg_util.retorna_number(apex_application.g_f08(1)),',
'            p_ind_incluso_valor_mercadoria => apex_application.g_f09(1),',
'            p_taxa_cambio => apex_application.g_f10(1),',
'            p_ind_status => apex_application.g_f11(1),',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD686";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td689
begin
wwv_flow_imp_shared.create_install_script(
