'end "UI_MPD_TD689";',
'/',
'create or replace package body "UI_MPD_TD689" as',
'',
'',
'--     function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'--     return clob is        ',
'--         l_html clob;',
'--     begin',
'--         l_html := pkg_util.ObterValoresDasColunas (',
'--             p_consulta_sql => ''select                ',
'--                 a.numero_pedido_importacao,',
'--                 b.num_entrega,',
'--                 CASE        ',
'--                 WHEN b.id_processoimportacao is null THEN',
'--                     pkg_componentes.html_cor_texto(''''Sem processo'''')',
'--                 ELSE',
'--                     NULL',
'--                 END as id_processoimportacao,',
'--                 pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', b.ind_status_entrega) ind_status_entrega',
'--             from ',
'--             imp_entrega b',
'--             JOIN imp_pedidoimportacao a ON a.id = b.id_pedidoimportacao',
'--             where b.id =  ''||p_param1,',
'--             p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega'', ''imp_entrega''),',
