prompt --application/deployment/install/install_ui_mpd_td694
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157419848482132488)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD694'
,p_sequence=>2010
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD694" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    function sql_atribuir_valor_ind_tipo_despesa(p_param1 in varchar2) return clob;',
'    ',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );   ',
'',
'end "UI_MPD_TD694";',
'/',
'create or replace package body "UI_MPD_TD694" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.numero_pedido_importacao, ',
'                    b.num_entrega ',
'                from imp_pedidoimportacao a ',
'                join imp_entrega b on b.id_pedidoimportacao = a.id ',
'                join imp_entrega_despesa c on c.id_entrega = b.id',
'                where c.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'        l_atribuir_valor_ind_tipo_despesa clob;',
'        l_campos_ind_tipo_despesa apex_t_varchar2 := apex_t_varchar2(''IND_TIPO_DESPESA'');',
'    begin',
'        l_atribuir_valor_ind_tipo_despesa := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_ind_tipo_despesa'',',
'            l_campos_ind_tipo_despesa',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null atribuir_valor FROM du'
||'al UNION ALL',
'               SELECT p_codigo_artefato, ''id_entrega'',                   2, ''HID'', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''IND_TIPO_DESPESA'',             3, ''SEL'', ''D_NG_DESPESA.IND_TIPO_DESPESA'', ''S'', ''N'', null valor, ''ng_despesa.ind_tipo_despesa'' tag_campo, null atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_despesa'',                   4, '''', null, ''N'', ''S'', null valor, null tag_campo, l_atribuir_valor_ind_tipo_despesa atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                     6, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor'',                        8, '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_incluso_valor_mercadoria'', 9, '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''taxa_cambio'',                 10, ''HID'', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status'',                  11, ''HID'', null, ''N'', ''S'', ''1'' valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',              12, '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, atribuir_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.atribuir_valor);',
'    end formulario;',
'',
'    function sql_atribuir_valor_ind_tipo_despesa(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := ''select ind_tipo_despesa from ng_despesa where id = #ID#'';',
'        return nvl(replace(l_sql,''#ID#'',p_param1),''999'');',
'    end sql_atribuir_valor_ind_tipo_despesa; ',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_despesa'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.ind_origem_despesa = 2',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is         ',
'    begin        ',
'        bo_imp_entrega_despesa.altera_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_entrega => apex_application.g_f02(1),',
'            p_id_despesa => apex_application.g_f04(1),',
'            p_id_moeda => apex_application.g_f06(1),',
'            p_valor => pkg_util.retorna_number(apex_application.g_f08(1)),',
'            p_ind_incluso_valor_mercadoria => apex_application.g_f09(1),',
'            p_taxa_cambio => apex_application.g_f10(1),',
'            p_ind_status => apex_application.g_f11(1),',
'            p_data_alteracao => to_timestamp(apex_application.g_f12(1), ''dd-mon-rr hh:mi:ss:ff am''),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD694";',
'/'))
);
end;
/
