'                    end id_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', b.ind_status_entrega) ind_status_entrega',
'            from ',
'            imp_entrega b',
'            JOIN imp_pedidoimportacao a ON a.id = b.id_pedidoimportacao',
'            left join imp_processoimportacao d ON d.id = b.id_processoimportacao',
'            where b.id =  ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega'', ''imp_entrega''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
unistr('        -- valida\00E7\00E3o data_disponivel'),
'        v_data_disponivel_real              imp_entrega.data_disponivel_real%type;',
'        v_data_disponivel_informada         imp_entrega.data_disponivel_informada%type;',
'        v_data_disponivel_calculada         imp_entrega.data_disponivel_calculada%type;',
'        v_hid_disponivel_real               varchar2(10);',
'        v_hid_disponivel_informada          varchar2(10);',
'        v_hid_disponivel_calculada          varchar2(10);',
'',
'        v_data_embarque_real                imp_entrega.data_embarque_real%type;',
'        v_data_embarque_informada           imp_entrega.data_embarque_informada%type;',
'        v_data_embarque_calculada           imp_entrega.data_embarque_calculada%type;',
'        v_hid_embarque_real                 varchar2(10);',
'        v_hid_embarque_informada            varchar2(10);',
'        v_hid_embarque_calculada            varchar2(10);',
'',
'        v_data_desembarque_real             imp_entrega.data_desembarque_real%type;',
'        v_data_desembarque_informada        imp_entrega.data_desembarque_informada%type;',
'        v_data_desembarque_calculada        imp_entrega.data_desembarque_calculada%type;',
'        v_hid_desembarque_real              varchar2(10);',
'        v_hid_desembarque_informada         varchar2(10);',
'        v_hid_desembarque_calculada         varchar2(10);',
'',
'        v_data_nacionalizacao_real          imp_entrega.data_nacionalizacao_real%type;',
'        v_data_nacionalizacao_informada     imp_entrega.data_nacionalizacao_informada%type;',
'        v_data_nacionalizacao_calculada     imp_entrega.data_nacionalizacao_calculada%type;',
'        v_hid_nacionalizacao_real           varchar2(10);',
'        v_hid_nacionalizacao_informada      varchar2(10);',
'        v_hid_nacionalizacao_calculada      varchar2(10);',
'',
'        v_data_recebimento_real             imp_entrega.data_recebimento_real%type;',
'        v_data_recebimento_informada        imp_entrega.data_recebimento_informada%type;',
'        v_data_recebimento_calculada        imp_entrega.data_recebimento_calculada%type;',
'        v_hid_recebimento_real              varchar2(10);',
'        v_hid_recebimento_informada         varchar2(10);',
'        v_hid_recebimento_calculada         varchar2(10);',
'',
'        v_old                              imp_entrega%rowtype;',
'',
'        procedure set_hid(',
'                p_data_real      in date,',
'                p_data_informada in date,',
'                p_data_calculada in date,',
'                p_hid_real       out varchar2,',
'                p_hid_informada  out varchar2,',
'                p_hid_calculada  out varchar2',
'        ) is',
'        begin',
'                p_hid_real      := ''HID'';',
'                p_hid_informada := ''HID'';',
'                p_hid_calculada := ''HID'';',
'                if p_data_real is not null then',
'                    p_hid_real := '''';',
'                elsif p_data_informada is not null OR p_data_calculada is null then',
'                    p_hid_informada := '''';',
'                else',
'                    p_hid_calculada := '''';',
'                end if;',
'        end;',
'',
'    begin ',
'        select * into v_old from imp_entrega where id = p_param1; ',
'',
'        SELECT ',
'            data_disponivel_real, data_disponivel_informada, data_disponivel_calculada,',
'            data_embarque_real, data_embarque_informada, data_embarque_calculada,',
'            data_desembarque_real, data_desembarque_informada, data_desembarque_calculada,',
'            data_nacionalizacao_real, data_nacionalizacao_informada, data_nacionalizacao_calculada,',
'            data_recebimento_real, data_recebimento_informada, data_recebimento_calculada',
'        INTO ',
'            v_data_disponivel_real, v_data_disponivel_informada, v_data_disponivel_calculada,',
'            v_data_embarque_real, v_data_embarque_informada, v_data_embarque_calculada,',
'            v_data_desembarque_real, v_data_desembarque_informada, v_data_desembarque_calculada,',
'            v_data_nacionalizacao_real, v_data_nacionalizacao_informada, v_data_nacionalizacao_calculada,',
'            v_data_recebimento_real, v_data_recebimento_informada, v_data_recebimento_calculada',
'        FROM imp_entrega',
'        WHERE id = p_param1;',
'',
'',
'        set_hid(',
'            v_data_disponivel_real, v_data_disponivel_informada, v_data_disponivel_calculada,',
'            v_hid_disponivel_real, v_hid_disponivel_informada, v_hid_disponivel_calculada',
'        );',
'',
'        set_hid(',
'            v_data_embarque_real, v_data_embarque_informada, v_data_embarque_calculada,',
'            v_hid_embarque_real, v_hid_embarque_informada, v_hid_embarque_calculada',
'        );',
'',
'        set_hid(',
'            v_data_desembarque_real, v_data_desembarque_informada, v_data_desembarque_calculada,',
'            v_hid_desembarque_real, v_hid_desembarque_informada, v_hid_desembarque_calculada',
'        );',
'',
'        set_hid(',
'            v_data_nacionalizacao_real, v_data_nacionalizacao_informada, v_data_nacionalizacao_calculada,',
'            v_hid_nacionalizacao_real, v_hid_nacionalizacao_informada, v_hid_nacionalizacao_calculada',
'        );',
'',
'        set_hid(',
'            v_data_recebimento_real, v_data_recebimento_informada, v_data_recebimento_calculada,',
'            v_hid_recebimento_real, v_hid_recebimento_informada, v_hid_recebimento_calculada',
'        );',
'',
'',
'',
'        MERGE INTO temp_formulario tf',
'          USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL'
||' ',
'                SELECT p_codigo_artefato, ''id_pedidoimportacao'',           2, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''num_entrega'',                   4, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_processoimportacao'',         6, ''HID'', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''ind_modalidade_importacao'',     8, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_viatransporte'',             10, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_incoterm'',                  12, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_exportador'',                14, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_importador'',                16, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_adquirente'',                18, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_endereco_origem'',           20, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_local_embarque'',            22, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_local_desembarque'',         24, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL                ',
'                SELECT p_codigo_artefato, ''id_endereco_destino'',          28, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''ind_status_entrega'',           30, ''HID'',                       null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_disponivel_real'',         31, v_hid_disponivel_real,       null, ''S'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_disponivel_informada'',    32, v_hid_disponivel_informada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_disponivel_calculada'',    33, v_hid_disponivel_calculada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_embarque_real'',           34, v_hid_embarque_real,         null, ''S'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_embarque_informada'',      35, v_hid_embarque_informada,    null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_embarque_calculada'',      36, v_hid_embarque_calculada,    null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_desembarque_real'',        37, v_hid_desembarque_real,      null, ''S'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_desembarque_informada'',   38, v_hid_desembarque_informada, null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_desembarque_calculada'',   39, v_hid_desembarque_calculada, null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_nacionalizacao_real'',     40, v_hid_nacionalizacao_real,    null, ''S'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_nacionalizacao_informada'',41, v_hid_nacionalizacao_informada,null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_nacionalizacao_calculada'',42, v_hid_nacionalizacao_calculada,null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_recebimento_real'',        43, v_hid_recebimento_real,       null, ''S'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_recebimento_informada'',   44, v_hid_recebimento_informada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_recebimento_calculada'',   45, v_hid_recebimento_calculada,  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''valor_total_condicao_venda'',   46, ''HID'',  null, ''N'', ''S'', null FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_alteracao'',               47, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'        v_desc_via_trans varchar2(10);',
'        v_id_entrega number;',
'    begin',
'        v_id_entrega := apex_util.get_session_state(''P9010_ID'');',
'',
'        select B.DESCRICAO_VIATRANSPORTE into v_desc_via_trans from imp_entrega a join NG_VIATRANSPORTE b on b.id = a.ID_VIATRANSPORTE where a.id = v_id_entrega;',
'        if upper(p_campo) = upper(''id_endereco_origem'') then',
'            return q''~',
'                where (b.data_fim_vigencia is null ',
'                    or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and c.id_pessoa in (',
'                    select c003 from apex_collections where collection_name = ''TD700_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f15_0000'')',
'                    )',
'            ~'';',
'        elsif upper(p_campo) = upper(''id_endereco_destino'') then',
'            return q''~',
'                where (b.data_fim_vigencia is null',
'                        or to_date(to_char(b.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                    )',
'                and c.id_pessoa in (        ',
'                        select c003 from apex_collections where collection_name = ''TD700_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f17_0000'')',
'                    )     ',
'                and (select ',
'                        c003 ',
'                    from apex_collections ',
'                    where collection_name = ''TD700_''||apex_custom_auth.get_session_id ',
'                    and upper(c001) = upper(''f19_0000'')) is null ',
'                    or c.id_pessoa in (        ',
'                        select c003 from apex_collections where collection_name = ''TD700_''||apex_custom_auth.get_session_id and upper(c001) = upper(''f19_0000'')',
'                    )',
'            ~'';',
'    elsif upper(p_campo) = upper(''id_local_embarque'') OR upper(p_campo) = upper(''id_local_desembarque'')then',
'        if v_desc_via_trans = ''1'' then',
'                return q''~',
'                where  a.ind_local = ''P'' ',
'                ~'';',
'        elsif v_desc_via_trans = ''4'' then',
'                return q''~',
'                where a.ind_local = ''A''',
'                ~'';',
'        elsif v_desc_via_trans = ''7'' then',
'                return q''~',
'                where a.ind_local = ''F''',
'                ~'';',
'        else',
'            return null;',
'        end if;',
'    end if;',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_id number;',
'        v_data_disponivel_informada        VARCHAR2(32767);',
'',
'        v_data_embarque_informada          VARCHAR2(32767);',
'',
'        v_data_desembarque_informada       VARCHAR2(32767);',
'',
'        v_data_nacionalizacao_calculada    VARCHAR2(32767);',
'        v_data_nacionalizacao_informada    VARCHAR2(32767);',
'',
'        v_data_recebimento_calculada       VARCHAR2(32767);',
'        v_data_recebimento_informada       VARCHAR2(32767);',
'        v_old                              imp_entrega%rowtype;',
'       ',
'    begin ',
'        select * into v_old from imp_entrega where id = p_id;        ',
'        ',
'        if  trunc(v_old.data_disponivel_calculada) = trunc(to_date(apex_application.g_f33(1), ''DD/MM/YYYY'')) OR v_old.data_disponivel_calculada is null then     ',
'            v_data_disponivel_informada := trunc(to_date(apex_application.g_f32(1)));--informada',
'        else',
'            v_data_disponivel_informada := trunc(to_date(apex_application.g_f33(1))); --calculada',
'        end if;',
'',
'        if v_old.data_embarque_calculada is null OR trunc(v_old.data_embarque_calculada) = trunc(to_date(apex_application.g_f36(1), ''DD/MM/YYYY''))then     ',
'            v_data_embarque_informada := trunc(to_date(apex_application.g_f35(1)));',
'        else',
'            v_data_embarque_informada := trunc(to_date(apex_application.g_f36(1)));',
'        end if;',
'',
'        if v_old.data_desembarque_calculada is null OR trunc(v_old.data_desembarque_calculada) = trunc(to_date(apex_application.g_f39(1), ''DD/MM/YYYY''))then     ',
'            v_data_desembarque_informada := trunc(to_date(apex_application.g_f38(1)));',
'        else',
'            v_data_desembarque_informada := trunc(to_date(apex_application.g_f39(1)));',
'        end if;',
'',
'        if v_old.data_nacionalizacao_calculada is null OR trunc(v_old.data_nacionalizacao_calculada) = trunc(to_date(apex_application.g_f42(1), ''DD/MM/YYYY''))then     ',
'            v_data_nacionalizacao_informada := trunc(to_date(apex_application.g_f41(1)));',
'        else',
'            v_data_nacionalizacao_informada := trunc(to_date(apex_application.g_f42(1)));',
'        end if;',
'',
'        if v_old.data_recebimento_calculada is null OR trunc(v_old.data_recebimento_calculada) = trunc(to_date(apex_application.g_f45(1), ''DD/MM/YYYY''))then     ',
'            v_data_recebimento_informada := trunc(to_date(apex_application.g_f44(1)));',
'        else',
'            v_data_recebimento_informada := trunc(to_date(apex_application.g_f45(1)));',
'        end if;',
'',
'        bo_imp_entrega.altera_registro(',
'                p_id_tenant                     => apex_application.g_f01(1),',
'                p_id_pedidoimportacao           => apex_application.g_f02(1),',
'                p_num_entrega                   => apex_application.g_f04(1),',
'                p_id_processoimportacao         => apex_application.g_f06(1),',
'                p_ind_modalidade_importacao     => apex_application.g_f08(1),',
'                p_id_viatransporte              => apex_application.g_f10(1),',
'                p_id_incoterm                   => apex_application.g_f12(1),',
'                p_id_exportador                 => apex_application.g_f14(1),',
'                p_id_importador                 => apex_application.g_f16(1),',
'                p_id_adquirente                 => apex_application.g_f18(1),',
'                p_id_endereco_origem            => apex_application.g_f20(1),',
'                p_id_local_embarque             => apex_application.g_f22(1),',
'                p_id_local_desembarque          => apex_application.g_f24(1),                ',
'                p_id_endereco_destino           => apex_application.g_f28(1),',
'                p_ind_status_entrega            => apex_application.g_f30(1),',
'                p_data_disponivel_real          => v_old.data_disponivel_real,',
'                p_data_disponivel_informada     => v_data_disponivel_informada,',
'                p_data_disponivel_calculada     => v_old.data_disponivel_calculada,',
'                p_data_embarque_real            => v_old.data_embarque_real,',
'                p_data_embarque_informada       => v_data_embarque_informada,',
'                p_data_embarque_calculada       => v_old.data_embarque_calculada,',
'                p_data_desembarque_real         => v_old.data_desembarque_real,',
'                p_data_desembarque_informada    => v_data_desembarque_informada,',
'                p_data_desembarque_calculada    => v_old.data_desembarque_calculada,',
'                p_data_nacionalizacao_real      => v_old.data_nacionalizacao_real,',
'                p_data_nacionalizacao_informada => v_data_nacionalizacao_informada,',
'                p_data_nacionalizacao_calculada => v_old.data_nacionalizacao_calculada,',
'                p_data_recebimento_real         => v_old.data_recebimento_real,',
'                p_data_recebimento_informada    => v_data_recebimento_informada,',
'                p_data_recebimento_calculada    => v_old.data_recebimento_calculada,',
'                p_valor_total_condicao_venda    => apex_application.g_f46(1),',
'                p_data_alteracao                => TO_TIMESTAMP(apex_application.g_f47(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'                p_id_invoice                    => v_old.id_invoice,',
'                p_valor_total_financeiro        => v_old.valor_total_financeiro,',
'                p_id                            => p_id, ',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'        );',
'    end;',
'end "UI_MPD_TD700";',
