prompt --application/deployment/install/install_ui_mpd_td701
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157420245286120691)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD701'
,p_sequence=>2040
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD701" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD701";',
'/',
'create or replace package body "UI_MPD_TD701" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select ',
'            b.numero_pedido_importacao, ',
'            a.num_entrega, ',
'            CASE        ',
'                WHEN a.id_processoimportacao is null THEN',
'                    pkg_componentes.html_cor_texto(''''Sem processo'''')',
'                ELSE',
'                    NULL',
'            END as id_processoimportacao,',
'            pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', a.ind_status_entrega) as ind_status_entrega',
'        from imp_entrega a ',
'        left join imp_pedidoimportacao b ',
'            ON b.id = a.id_pedidoimportacao',
'        where a.id = ''|| p_param1,',
'        p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega'',''imp_entrega''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.62.l'')||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        v_data_informada     imp_entrega.data_disponivel_informada%type;',
'        v_hid_real           varchar2(10);',
'        v_data_real          imp_entrega.data_disponivel_real%type;',
'    begin ',
'',
'        SELECT data_disponivel_informada',
'        INTO v_data_informada',
'        FROM imp_entrega',
'        WHERE id = p_param1;',
'',
'       IF TRUNC(v_data_informada) < TRUNC( TO_DATE(''30/11/2027'', ''DD/MM/YYYY'')) THEN',
'                v_hid_real      := ''''; ',
'                v_data_real     := v_data_informada;      ',
'        ELSE ',
'                v_hid_real      := ''HID'';       ',
'                v_data_real     := NULL;',
'        END IF;',
'        ',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from i'
||'mp_entrega where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_disponivel_real'',               4, v_hid_real, null, ''N'', ''S'', to_char(v_data_real), null , null , null  from dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''data_disponivel_informada'',          6, v_hid_informada, null, ''N'', ''S'', null, null , null , null  from dual UNION ALL',
'        --        SELECT p_codigo_artefato, ''data_disponivel_calculada'',          8, v_hid_calculada, null, ''N'', ''S'', null, null , null , null  from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                     18, ''''   ,NULL, ''N'', ''S'', null , null,null, null  FROM dual  ',
'',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'',
'    )',
'    is',
'        l_id number;',
'        v_imp_ent imp_entrega%rowtype;',
'',
'    begin ',
'        select * into v_imp_ent from imp_entrega where id = p_id;  ',
'',
'        bo_imp_entrega.altera_registro(',
'                p_id_tenant                     => v_imp_ent.id_tenant,',
'                p_id_pedidoimportacao           => v_imp_ent.id_pedidoimportacao,',
'                p_num_entrega                   => v_imp_ent.num_entrega,',
'                p_id_processoimportacao         => v_imp_ent.id_processoimportacao,',
'                p_ind_modalidade_importacao     => v_imp_ent.ind_modalidade_importacao,',
'                p_id_exportador                 => v_imp_ent.id_exportador,',
'                p_id_importador                 => v_imp_ent.id_importador,',
'                p_id_adquirente                 => v_imp_ent.id_adquirente,',
'                p_id_endereco_origem            => v_imp_ent.id_endereco_origem,',
'                p_id_local_embarque             => v_imp_ent.id_local_embarque,',
'                p_id_local_desembarque          => v_imp_ent.id_local_desembarque,                ',
'                p_id_endereco_destino           => v_imp_ent.id_endereco_destino,',
'                p_id_viatransporte              => v_imp_ent.id_viatransporte,',
'                p_id_incoterm                   => v_imp_ent.id_incoterm,',
'                p_ind_status_entrega            => 3,',
'                p_data_disponivel_calculada     => v_imp_ent.data_disponivel_calculada,',
'                p_data_disponivel_informada     => v_imp_ent.data_disponivel_informada,',
'                p_data_disponivel_real          => apex_application.g_f04(1),',
'                p_data_embarque_calculada       => v_imp_ent.data_embarque_calculada,',
'                p_data_embarque_informada       => v_imp_ent.data_embarque_informada,',
