'                p_data_desembarque_informada    => v_imp_ent.data_desembarque_informada,',
'                p_data_desembarque_real         => v_imp_ent.data_desembarque_real,',
'                p_data_nacionalizacao_calculada => v_imp_ent.data_nacionalizacao_calculada,',
'                p_data_nacionalizacao_informada => v_imp_ent.data_nacionalizacao_informada,',
'                p_data_nacionalizacao_real      => v_imp_ent.data_nacionalizacao_real,',
'                p_data_recebimento_calculada    => v_imp_ent.data_recebimento_calculada,',
'                p_data_recebimento_informada    => v_imp_ent.data_recebimento_informada,',
'                p_data_recebimento_real         => v_imp_ent.data_recebimento_real,',
'                p_valor_total_condicao_venda    => v_imp_ent.valor_total_condicao_venda,',
'                p_valor_total_financeiro        => v_imp_ent.valor_total_financeiro,',
'                p_data_alteracao                => TO_TIMESTAMP(apex_application.g_f18(1), ''DD-MON-RR HH:MI:SS.FF AM'') ,',
'                p_id_invoice                    => v_imp_ent.id_invoice,',
'                p_id                            => p_id, ',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'        );',
'    end;',
'',
'',
'        -- p_id_tenant in imp_entrega.id_tenant%type,',
'        -- p_id_pedidoimportacao in imp_entrega.id_pedidoimportacao%type,',
'        -- p_num_entrega in imp_entrega.num_entrega%type,',
'        -- p_id_processoimportacao in imp_entrega.id_processoimportacao%type,',
'        -- p_ind_modalidade_importacao in imp_entrega.ind_modalidade_importacao%type,',
'        -- p_id_exportador in imp_entrega.id_exportador%type,',
'        -- p_id_adquirente in imp_entrega.id_adquirente%type,',
'        -- p_id_endereco_origem in imp_entrega.id_endereco_origem%type,',
'        -- p_id_local_embarque in imp_entrega.id_local_embarque%type,',
'        -- p_id_local_desembarque in imp_entrega.id_local_desembarque%type,',
'        -- p_id_endereco_destino in imp_entrega.id_endereco_destino%type,',
'        -- p_id_incoterm in imp_entrega.id_incoterm%type,',
