prompt --application/deployment/install/install_ui_mpd_td715
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157420359855117620)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD715'
,p_sequence=>2050
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD715" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD715";',
'/',
'create or replace package body "UI_MPD_TD715" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'        l_html_ind_situacao varchar2(4000);',
'    begin   ',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;   ',
'                ',
'        l_html_ind_situacao := ''<i title="''||l_hover_ind_situacao||''"></i>'';',
'',
'        l_sql := ''',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(descricao_listapreco) titulo,',
'                b.nome_fantasia subtitulo,                ',
'                CASE',
'                    WHEN a.ind_situacao = ''''E'''' THEN',
'                        ''''''||l_hover_ind_situacao||''''''',
'                    ELSE',
'                        ''''''''',
'                END distintivo,',
'                CASE',
'                    WHEN a.ind_situacao = ''''E'''' THEN',
'                        ''''fa fa-warning no-text''''',
'                    ELSE',
'                        ''''u-hidden''''',
'                END class_distintivo,',
'                CASE',
'                    WHEN a.ind_situacao = ''''E'''' THEN',
'                        ''''&#8205;''''',
'                    ELSE',
'                        ''''''''',
'                END lista_distintivo,                                   ',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''''ng_listapreco.id_moeda'''', c.codigo_moeda || '''' - '''' || c.simbolo_iso, 3) atributo1,',
'                pkg_componentes.html_card_colunas(''''ng_listapreco.ind_aplicacao'''', pkg_util.dominio_retorna_tag(''''ng_listapreco'''',''''ind_aplicacao'''',ind_aplicacao), 3) atributo2,',
'                pkg_componentes.html_card_colunas(''''ng_listapreco.data_inicio_vigencia'''',pkg_data.fmtd(a.data_inicio_vigencia, ''''DATA''''), 3) atributo3,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''''ng_listapreco.data_fim_vigencia'''', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')), 3) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''''ng_listapreco.data_fim_vigencia'''', pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''), 3) ',
'                end atributo4,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                a.ind_aplicacao filtro2,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''''TD715'''',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''''TD715'''') as opcao                ',
'            from ng_listapreco a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_moeda c on c.id = a.id_moeda',
'            order by 3, 8',
'            '';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param3,''1''));            ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_hover_ind_situacao varchar2(4000);',
'        l_html_ind_situacao varchar2(4000);',
'    begin   ',
'        select pkg_ui.retorna_label_tela(''ind_situacao'') into l_hover_ind_situacao from dual;   ',
'',
'        l_html_ind_situacao := ''<i class="fa fa-warning" title="''||l_hover_ind_situacao||''"></i>'';',
'',
'        l_sql := ''',
'        select distinct',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            pkg_util.dominio_retorna_tag(''''ng_listapreco'''', ''''ind_aplicacao'''', a.ind_aplicacao) campo2,',
'            pkg_traducao.get_traducao(descricao_listapreco) campo3,',
'            pkg_util.valor_referencia(c.id,''''ng_moeda'''') campo4,',
'            pkg_data.fmtd(a.data_inicio_vigencia, ''''DATA'''') campo5,            ',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')',
'            end campo6,',
'            case WHEN a.ind_situacao = ''''E'''' THEN',
'                '''''' || l_html_ind_situacao || ''''''',
'            ELSE',
'                NULL',
'            END campo7,',
'            null campo8,                                                     ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            a.id_tenant filtro1,                               ',
'            a.ind_aplicacao filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                              ',
'            null opcao',
'        from ng_listapreco a   ',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_moeda c on c.id = a.id_moeda            ',
'       '';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD715'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_listapreco'')) a',
'            order by',
'                campo1,',
'                campo2',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        elsif campo = ''2'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_listapreco'', ''ind_aplicacao'')~'';',
'        else ',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.id_tenant'') into l_campo from dual;',
'        elsif campo in (''2'', ''F2'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.ind_aplicacao'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.descricao_listapreco'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.id_moeda'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.data_inicio_vigencia'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco.ind_situacao'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'        ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''id_tenant,ind_aplicacao'';',
'        else',
'            campos := ''campo1,campo2'';',
'        end if;',
'        labels := label_coluna(''1'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD715";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td718
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157420589130104630)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD718'
,p_sequence=>2060
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD718" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);   ',
'',
'end "UI_MPD_TD718";',
'/',
'create or replace package body "UI_MPD_TD718" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna_descricao number;                        ',
'        l_id_coluna_observacao number;',
'        l_descricao clob;',
'        l_permite_edicao_descricao varchar2(5);',
'        l_erro_descricao clob;',
'        l_somente_leitura_descricao varchar2(1);',
'        l_observacao clob;',
'        l_permite_edicao_observacao varchar2(5);',
'        l_erro_observacao clob;',
'        l_somente_leitura_observacao varchar2(1);',
'        l_url_descricao varchar2(4000);',
'        l_url_observacao varchar2(4000);',
'    begin',
'',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''ng_listapreco'';',
'        select id into l_id_coluna_descricao from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_listapreco'';',
'        select id into l_id_coluna_observacao from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''observacao'';',
'',
'        l_url_descricao := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna_descricao, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        l_url_observacao := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna_observacao, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL               ',
'                SELECT p_codigo_artefato, ''descricao_listapreco'',       4, '''', l_url_descricao, l_somente_leitura_descricao, ''S'', to_char((select pkg_traducao.get_traducao(descricao_listapreco) from ng_listapreco where id = p_param1))  valor FROM dua'
||'l UNION ALL',
'                SELECT p_codigo_artefato, ''ind_aplicacao'',              5, '''', NULL, ''S'',''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_exportador'',              6, '''', NULL, ''S'',''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_moeda'',                   7, '''', NULL, ''S'',''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''observacao'',                 9, ''TXT'', l_url_observacao, l_somente_leitura_observacao, ''S'', to_char((select pkg_traducao.get_traducao(observacao) from ng_listapreco where id = p_param1))  valor FROM dual UNI'
||'ON ALL',
'                SELECT p_codigo_artefato, ''data_inicio_vigencia'',      10, '''', NULL, ''S'',''S'', null valor FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_fim_vigencia'',         11, '''', NULL, ''S'',''S'', null valor FROM dual UNION ALL                                          ',
'                SELECT p_codigo_artefato, ''id_usuario_alterou'',        14, ''SEL'', ''R_MPD_USUARIO.NOME'', ''S'', ''S'', null valor FROM dual UNION ALL                                            ',
'                SELECT p_codigo_artefato, ''data_alteracao'',            15, ''TXT'', NULL, ''S'',''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_listapreco WHERE id = p_param1), ''DATA_SEGUNDO'') valor FROM dual                                             ',
'                ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD718";',
'/'))
);
end;
