prompt --application/deployment/install/install_ui_mpd_td723
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157420644532102039)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD723'
,p_sequence=>2070
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD723" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_valor_item(p_param1 in varchar2) return clob;',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob;',
'',
'end "UI_MPD_TD723";',
'/',
'create or replace package body "UI_MPD_TD723" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql =>',
'                ''select',
'                    pkg_traducao.get_traducao(a.descricao_listapreco) as descricao_listapreco,',
'                    b.codigo_moeda|| '''' - '''' || pkg_traducao.get_traducao(b.descricao_moeda) as id_moeda',
'                from ng_listapreco a',
'                join ng_moeda b on b.id = a.id_moeda',
'                join ng_listapreco_item c on c.id_lista_preco = a.id',
'                where c.id = ''||p_param1,',
'            p_tabela => textarray(''ng_listapreco'',''ng_listapreco''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'        l_consulta_item clob;',
'        l_atribuir_valor_item clob;',
'        l_campos apex_t_varchar2 := apex_t_varchar2(''ID_UNIDADEMEDIDA'');',
'        l_atribuir_valor_unidademedida clob;',
'        l_campos_unidademedida apex_t_varchar2 := apex_t_varchar2(''PERMITE_DECIMAIS'');',
'        v_executa_js_digito clob;',
'    begin',
'        l_consulta_item := ''select a.codigo_item || '''' - ''''||tpkg_traducao.get_traducao(a.descricao_item) as d, a.id as r from ng_item a join ng_item_produto b on b.id_item = a.id where a.ind_tipo_item = ''''P'''' order by 1'';',
'',
'        l_atribuir_valor_item := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_valor_item'', l_campos);',
'',
'        l_atribuir_valor_unidademedida := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_unidademedida'',',
'            l_campos_unidademedida',
'        );',
'',
'        v_executa_js_digito := ''atualizarDigitsCampo("QTD_MINIMA","PERMITE_DECIMAIS")'';   ',
'',
'        MERGE INTO temp_formulario tf               ',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_item_produto'' AS nome_coluna, 5 AS indice, ''POP'' AS tipo_interacao, ''R_NG_ITEM.CODIGO_ITEM'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, corta_texto((SELECT TO_CHAR(a.'
||'id_item_produto) FROM ng_listapreco_item a WHERE a.id = p_param1)) AS valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               --SELECT p_codigo_artefato AS codigo_artefato, ''id_item_produto'' AS nome_coluna, 5 AS indice, '''' AS tipo_interacao, '''' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, corta_texto((SELECT TO_CHAR(a.id_item_produto) FROM '
||'ng_listapreco_item a WHERE a.id = p_param1)) AS valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_produto'',       6, ''TEX'', NULL, ''N'',''N'', (SELECT TO_CHAR(pkg_traducao.get_traducao(c.descricao_item)) FROM ng_listapreco_item a join ng_item_produto b on b.id_item = a.id_item_produto join ng_item c'
||' on c.id = b.id_item WHERE a.id = p_param1) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',           7, '''', NULL, ''N'',''S'', (SELECT TO_CHAR(a.id_importador) FROM ng_listapreco_item a JOIN ng_listapreco b ON b.id = a.id_lista_preco WHERE a.id = p_param1 AND b.ind_aplicacao = ''E'') valo'
||'r, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual WHERE EXISTS (SELECT 1 FROM ng_listapreco_item a JOIN ng_listapreco b ON b.id = a.id_lista_preco WHERE a.id = p_param1 AND b.ind_aplicacao = ''E'') UNION ALL',
'               SELECT p_codigo_artefato, ''preco_unitario'',         09, '''', NULL, ''N'',''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''preco_unitario_minimo'',  10, '''', NULL, ''N'',''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_UNIDADEMEDIDA'',       11, '''', NULL, ''N'',''S'', null valor, null dependencia, l_atribuir_valor_unidademedida atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''QTD_MINIMA'',             13, '''', NULL, ''S'',''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',     15, ''SEL'', ''R_MPD_USUARIO.NOME'' as nome_consulta, ''N'',''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL   ',
'               SELECT p_codigo_artefato, ''PERMITE_DECIMAIS'',       14, ''HID'', NULL, ''N'',''N'', ''5'' valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js FROM dual UNION ALL             ',
'               SELECT p_codigo_artefato, ''data_alteracao'',         17, ''TXT'', null, ''N'',''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_listapreco_item WHERE id = p_param1), ''DATA_SEGUNDO'') valor, null dependencia, null atribuir_valor, null calcular'
||'_valor, null executa_js FROM dual                ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, calcular_valor, executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.calcular_valor, new_data.executa_js);',
'    end formulario;',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select',
'                case b.ind_tipo_dado',
'                    when ''D'' then 5  -- permite decimais',
unistr('                    else 0           -- n\00E3o permite'),
'                end PERMITE_DECIMAIS',
'            from ng_listapreco_item a',
'            join ng_unidademedida b on b.id = a.id_unidademedida',
'            where b.id = #ID#',
'        ~'';',
'        l_sql := replace(l_sql, ''#ID#'', p_param1);',
'        return l_sql;',
'    end sql_atribuir_valor_unidademedida;',
'',
'    function sql_atribuir_valor_item(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select concatena_id_texto(c.id,upper(c.codigo_unidademedida)) ID_UNIDADEMEDIDA',
'            from ng_item a',
'            join ng_item_produto b on b.id_item = a.id',
'            left join ng_unidademedida c on c.id = a.id_unidademedida',
'            where b.id = #ID#',
'        ~'';',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end sql_atribuir_valor_item;',
'',
'end "UI_MPD_TD723";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td726
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157420769924098205)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD726'
,p_sequence=>2080
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD726" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    -- procedure post_create(',
'    --     p_id out number,',
'    --     p_sucesso out clob,',
'    --     p_messages out pkg_mensagem.message_record_table     ',
'    -- );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD726";',
'/',
'create or replace package body "UI_MPD_TD726" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_fisica where i'
||'d = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa'',                2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_fisica where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_conta_bancaria'', 3, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''agencia_bancaria'',         4, ''POP'', ''R_NG_PESSOA_AGENCIABANCARIA.NOME_FANTASIA'', ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''conta_bancaria'',           6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                 7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_conta_exterior'',       9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',       10, ''HID'', null, ''N'', ''S'', null valor FROM dual               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                a.descricao_conta_bancaria campo1,',
'                (select nome_fantasia from ng_pessoa_juridica a join ng_pessoa_agenciabancaria b on b.id_pessoa = a.id_pessoa where b.id = a.agencia_bancaria) campo2,',
'                a.conta_bancaria campo3,',
'                pkg_traducao.get_traducao(d.descricao_moeda) campo4,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contabancaria'', ''ind_conta_exterior'', a.ind_conta_exterior) campo5,',
'                case ',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo6,',
'                a.data_fim_vigencia campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD726'') opcao',
'            from ng_pessoa_contabancaria a',
'            join ng_pessoa b on b.id = a.id_pessoa         ',
'            join ng_pessoa_fisica c on c.id_pessoa = b.id',
'            left join ng_moeda d on d.id = a.id_moeda',
'            where c.id = #param1#',
'            order by to_date(campo7,''dd/mm/yyyy'') nulls first, campo2, campo3',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report;',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                null selected,        ',
'                a.id,',
'                a.descricao_conta_bancaria campo1,',
'                (select nome_fantasia from ng_pessoa_juridica a join ng_pessoa_agenciabancaria b on b.id_pessoa = a.id_pessoa where b.id = a.agencia_bancaria) campo2,',
'                a.conta_bancaria campo3,',
'                pkg_traducao.get_traducao(d.descricao_moeda) campo4,',
'                pkg_util.dominio_retorna_tag(''ng_pessoa_contabancaria'', ''ind_conta_exterior'', a.ind_conta_exterior) campo5,',
'                case ',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        --pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo6,',
'                a.data_fim_vigencia campo7,                ',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD726'') opcao',
'            from ng_pessoa_contabancaria a',
'            join ng_pessoa b on b.id = a.id_pessoa         ',
'            join ng_pessoa_fisica c on c.id_pessoa = b.id',
'            left join ng_moeda d on d.id = a.id_moeda',
'            where c.id = #param1#',
'            order by to_date(campo7,''dd/mm/yyyy'') nulls first, campo2, campo3',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.descricao_conta_bancaria'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.agencia_bancaria'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.conta_bancaria'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.id_moeda'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.ind_conta_exterior'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_contabancaria.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_PARAMETRO2,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD305,TD305,''||p_param1||'',TD600,false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;   ',
'',
'end "UI_MPD_TD726";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td727
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157420863165095451)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD727'
,p_sequence=>2090
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD727" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'    ',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'end "UI_MPD_TD727";',
'/',
'create or replace package body "UI_MPD_TD727" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_consulta_estado clob;',
'        l_consulta_cidade clob;        ',
'    begin',
'        prc_enviar_parametros(''TD727'',''id_pais'',p_param1);',
'        prc_enviar_parametros(''TD727'',''id_estado'',p_param1);',
'        l_consulta_estado := ''select d, r from (select null d, null r, 0 ordem from dual union all select to_char(chamar_webservice_traducao(esquema_corrente,''''ng_estado'''',''''nome_estado'''',apex_util.get_session_state(''''IDIOMA_LOGADO''''),a.id)), id, 1 f'
||'rom ng_estado a where id_pais = (select id from ng_pais np where to_char(chamar_webservice_traducao(esquema_corrente,''''ng_pais'''',''''nome_pais'''',apex_util.get_session_state(''''IDIOMA_LOGADO''''),np.id)) = (select c002 from apex_collections where collectio'
||'n_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f06_0000''''))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_date(current_date))) order by ordem, d'';        ',
'        l_consulta_cidade := ''select d, r from (select null d, null r, 0 ordem from dual union all select to_char(chamar_webservice_traducao(esquema_corrente,''''ng_cidade'''',''''nome_cidade'''',apex_util.get_session_state(''''IDIOMA_LOGADO''''),a.id)), a.id, 1'
||' from ng_cidade a where a.id_pais = (select np.id from ng_pais np where to_char(chamar_webservice_traducao(esquema_corrente,''''ng_pais'''',''''nome_pais'''',apex_util.get_session_state(''''IDIOMA_LOGADO''''),np.id)) = (select c002 from apex_collections where co'
||'llection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f06_0000''''))) and ((select c002 from apex_collections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_'
||'session_id || '''''' and upper(c001) = upper(''''f08_0000'''')) is null or a.id_estado = (select ne.id from ng_estado ne where to_char(chamar_webservice_traducao(esquema_corrente,''''ng_estado'''',''''nome_estado'''',apex_util.get_session_state(''''IDIOMA_LOGADO''''),n'
||'e.id)) = (select c002 from apex_collections where collection_name = '''''' || p_codigo_artefato || ''_'' || apex_custom_auth.get_session_id || '''''' and upper(c001) = upper(''''f08_0000'''')))) and (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >='
||' to_date(current_date))) order by ordem, d'';',
