'/',
'create or replace package body "UI_MPD_TD728" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is               ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.nome_abreviado from ng_pessoa_fisica a where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_pessoa_fisica''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'        l_id_pessoa number;',
'        l_id_tenant number;        ',
'        l_verifica_referencia number;',
'        l_id_referencia number;',
'        l_tipo_interacao_referencia varchar2(10) := ''HID'';',
'        l_verifica_data_fim_vigencia number;',
'        l_somente_leitura_data_fim_vigencia varchar2(1);',
'    begin        ',
'        select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_param1;',
'        select id_tenant into l_id_tenant from ng_pessoa where id = l_id_pessoa;        ',
'        if regexp_like(p_param2, ''^\d+$'') then',
'            select count(1) into l_verifica_referencia from ng_pessoa_contato where id_pessoa = p_param2;',
'            select count(1) into l_verifica_data_fim_vigencia from ng_pessoa_contato where id_pessoa = p_param2 and id_pessoa_fisica = l_id_pessoa and data_fim_vigencia is null;',
'            if l_verifica_data_fim_vigencia > 0 then',
'                l_somente_leitura_data_fim_vigencia := ''N'';',
'            else',
'                l_somente_leitura_data_fim_vigencia := ''S'';            ',
'            end if;',
'        end if;',
'        if l_verifica_referencia > 0 then',
'            l_id_referencia := p_param2;',
'            l_tipo_interacao_referencia := ''SEL'';',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char(l_id_tenant) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_contato'',    2, ''HID'', null, ''N'', ''S'', to_char(l_id_pessoa) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pessoa_referencia'', 3, l_tipo_interacao_referencia, ''R_NG_PESSOA_CONTATO_DADO.ID_PESSOA_REFERENCIA'', ''N'', ''S'', to_char(nvl(l_id_referencia, l_id_pessoa)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_contato'',    4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''dado_contato'',         5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_whatsapp'',         6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',           7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',    8, '''', null, l_somente_leitura_data_fim_vigencia, ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
