'    --             a.dado_contato campo2,',
'    --             pkg_util.dominio_retorna_tag(''ng_pessoa_contato_dado'', ''ind_whatsapp'', a.ind_whatsapp) campo3,',
'    --             a.observacao campo4,',
'    --             case ',
'    --                 when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'    --                     pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'    --                 else',
'    --                     pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'    --             end campo5,',
'    --             a.data_fim_vigencia campo6,',
'    --             null campo7,',
'    --             null campo8,',
'    --             null campo9,',
'    --             null campo10,',
'    --             pkg_componentes.html_botao_opcao(a.id,''TD728'') opcao',
'    --         from ng_pessoa_contato_dado a',
'    --         join ng_pessoa_contato b on b.id_pessoa = a.id_pessoa_contato  ',
