'    --     --return ''select 1 ok from dual'';',
'    -- end sql_report;',
'',
'    -- function label_coluna(campo in number)',
'    -- return clob is',
'    --     l_campo clob;',
'    -- begin  ',
'    --     if campo = 1 then                     ',
'    --         select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_forma_contato'') into l_campo from dual;',
'    --     elsif campo = 2 then                     ',
'    --         select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.dado_contato'') into l_campo from dual;',
'    --     elsif campo = 3 then                     ',
'    --         select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.ind_whatsapp'') into l_campo from dual;',
'    --     elsif campo = 4 then                     ',
'    --         select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.observacao'') into l_campo from dual;',
'    --     elsif campo = 5 then                     ',
'    --         select pkg_ui.retorna_label_coluna(''ng_pessoa_contato_dado.data_fim_vigencia'') into l_campo from dual;        ',
'    --     end if;',
'    --     return l_campo;',
'    -- end label_coluna;',
'',
'end "UI_MPD_TD728";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td729
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157421378555067035)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD729'
,p_sequence=>2110
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD729" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'',
'end "UI_MPD_TD729";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD729" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(c.descricao_item) titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when c.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(c.data_fim_vigencia, ''DATA'')',
'                end distintivo,                ',
'                case ',
'                    when c.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(c.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS            ',
'                pkg_componentes.html_card_colunas(''ng_item.codigo_item'',codigo_item, 6) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_ncm.codigo_ncm'',codigo_ncm, 6) atributo2,',
'                c.data_fim_vigencia,               ',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                c.id_familia_item filtro2,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD729'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD729'') as opcao                ',
'            from ng_item_embalagem a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_item c on c.id = a.id_item',
'            left join ng_ncm d on d.id = a.id_ncm',
'            where c.ind_tipo_item = ''E''',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            c.codigo_item campo2,',
'            pkg_traducao.get_traducao(c.descricao_item) campo3,',
'            d.codigo_ncm campo4,     ',
'            case when to_date(c.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(c.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(c.data_fim_vigencia, ''DATA'')',
'            end campo5,                          ',
'            c.data_fim_vigencia campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            c.id_familia_item filtro2,                                                              ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_item_embalagem a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_item c on c.id = a.id_item',
'        left join ng_ncm d on d.id = a.id_ncm',
'        where c.ind_tipo_item = ''E''            ',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD729'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_item_embalagem'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1'')); ',
'        --order by to_date(campo6,''dd/mm/yyyy'') nulls first, campo3        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~',
'                select ',
'                    pkg_traducao.get_traducao(a.descricao_familia) d,',
'                    id r',
'                from ng_familia_item a',
'            ~'';            ',
'        else ',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item_embalagem.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item_embalagem.id_ncm'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.data_fim_vigencia'') into l_campo from dual;',
'        elsif campo = ''F2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.id_familia_item'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo3,campo2,campo4'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,titulo,atributo1,atributo2'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''3'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo3'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,titulo'';',
'        end if;',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD729";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td731
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157421492353062637)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD731'
,p_sequence=>2120
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD731" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD731";',
'/',
'create or replace package body "UI_MPD_TD731" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_JSON_calcular_volume clob;',
'        l_campos_calcular_volume varchar2(128) := ''VOLUME'';',
'        l_atribuir_volume clob;',
'    begin',
'        l_JSON_calcular_volume := gerar_json_calcular_valor(',
'            '' ALTURA * LARGURA * PROFUNDIDADE '',',
'            l_campos_calcular_volume',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, NULL AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_item_embalagem where '
||'id = p_param1)) valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_item'',             3, ''HID'', NULL, ''S'', ''N'', to_char((select a.codigo_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual UNION'
||' ALL',
'               SELECT p_codigo_artefato, ''descricao_item'',          4, ''HID'', NULL, ''S'', ''N'', to_char((select a.descricao_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual UN'
||'ION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',        5, ''HID'', NULL, ''S'', ''N'', to_char((select a.id_unidademedida from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual '
||'UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_barra'',            8, ''HID'', NULL, ''S'', ''N'', to_char((select a.codigo_barra from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual UNIO'
||'N ALL',
'               SELECT p_codigo_artefato, ''id_familia_item'',         9, ''HID'', NULL, ''S'', ''N'', to_char((select a.id_familia_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual U'
||'NION ALL',
'               SELECT p_codigo_artefato, ''id_ncm'',                 11, ''HID'', NULL, ''S'', ''S'', to_char((select b.id_ncm from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naladi'',              13, ''HID'', NULL, ''S'', ''S'', to_char((select b.id_naladi from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM dual UNION A'
||'LL',
'               SELECT p_codigo_artefato, ''id_embalagem_siscomex'',  15, ''HID'', NULL, ''S'', ''S'', to_char((select b.id_embalagem_siscomex from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM '
||'dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_embalagem_cod'',   16, ''HID'', NULL, ''S'', ''S'', to_char((select b.codigo_embalagem_cod from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null calcular_valor FROM d'
||'ual UNION ALL',
'               SELECT p_codigo_artefato, ''peso'',                   17, '''', NULL, ''N'', ''S'', null valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ALTURA'',                 18, '''', NULL, ''N'', ''S'', null valor, l_JSON_calcular_volume calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''LARGURA'',                19, '''', NULL, ''N'', ''S'', null valor, l_JSON_calcular_volume calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PROFUNDIDADE'',           20, '''', NULL, ''N'', ''S'', null valor, l_JSON_calcular_volume calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VOLUME'',                 21, '''', NULL, ''N'', ''S'', null valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',      23, ''HID'', NULL, ''N'', ''N'', pkg_data.fmtd((select data_fim_vigencia from ng_item where id = p_param1), ''DATA'') valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',         25, '''', NULL, ''N'', ''S'', null valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_item'',                26, ''HID'', NULL, ''S'', ''S'', to_char((select id_item from ng_item_embalagem where id = p_param1)) valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_embalagem'',           27, ''HID'', NULL, ''S'', ''N'', to_char((select id from ng_item_embalagem where id = p_param1)) valor, null calcular_valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, calcular_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.calcular_valor);',
'    end formulario;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin',
'        select id into l_id from ng_item_embalagem where id = (select a.id from ng_item_embalagem a where a.id = p_paramentro);',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_ng_item.altera_registro(                                    ',
'            p_id_tenant=> apex_application.g_f02(1),',
'            p_codigo_item => apex_application.g_f03(1),',
'            p_descricao_item => apex_application.g_f04(1),',
'            p_id_unidademedida => apex_application.g_f05(1),',
'            p_ind_tipo_item => ''E'',',
'            p_codigo_barra => apex_application.g_f08(1),',
'            p_id_familia_item => apex_application.g_f09(1),',
'            p_data_fim_vigencia => apex_application.g_f23(1),',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f25(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id => apex_application.g_f26(1), ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        bo_ng_item_embalagem.inclui_registro(                                    ',
'            p_id_tenant=> apex_application.g_f02(1),',
'            p_id_item => apex_application.g_f26(1),',
'            p_id_ncm => apex_application.g_f11(1),',
'            p_id_naladi => apex_application.g_f13(1),',
'            p_id_embalagem_siscomex => replace(replace(apex_application.g_f15(1), ''.'', ''''), '','', ''''),',
'            p_codigo_embalagem_cod => apex_application.g_f16(1),',
'            p_peso => apex_application.g_f17(1),',
'            p_altura => apex_application.g_f18(1),',
'            p_largura => apex_application.g_f19(1),',
'            p_profundidade => apex_application.g_f20(1),',
'            p_volume => apex_application.g_f21(1),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'    procedure post_save(   ',
'        p_id in number default null,     ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_ng_item.altera_registro(                                    ',
'            p_id_tenant=> apex_application.g_f02(1),',
'            p_codigo_item => apex_application.g_f03(1),',
'            p_descricao_item => apex_application.g_f04(1),',
'            p_id_unidademedida => apex_application.g_f05(1),',
'            p_ind_tipo_item => ''E'',',
'            p_codigo_barra => apex_application.g_f08(1),',
'            p_id_familia_item => apex_application.g_f09(1),',
'            p_data_fim_vigencia => apex_application.g_f23(1),',
'            p_data_alteracao => TO_TIMESTAMP(apex_application.g_f25(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id => apex_application.g_f26(1), ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        bo_ng_item_embalagem.altera_registro(                                    ',
'            p_id_tenant=> apex_application.g_f02(1),',
'            p_id_item => apex_application.g_f26(1),',
'            p_id_ncm => apex_application.g_f11(1),',
'            p_id_naladi => apex_application.g_f13(1),',
