||'ram1)) valor, ''S'' obrigatorio, l_url_id_unidade_medida url, null calcular_valor, 5865 id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',            5, ''POP'', ''R_NG_UNIDADEMEDIDA.CODIGO_UNIDADEMEDIDA_-_SEM_NULO'', ''N'', ''N'', to_char((select a.id_unidademedida from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.i'
||'d = p_param1)) valor, ''S'' obrigatorio, l_url_id_unidade_medida url, null calcular_valor, 5865 id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_barra'',                8, ''TXT'', NULL, ''N'', ''N'', to_char((select a.codigo_barra from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null obrigatorio, null url, nu'
||'ll calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
