||'alor, null obrigatorio, l_url_id_familia_item url, null calcular_valor, 5825 id_artefato_versionado_zoom  FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_familia_item'',             9, ''POP'', ''R_NG_ITEM.DESCRICAO_FAMILIA_ITEM'', ''N'', ''N'', to_char((select a.id_familia_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valo'
||'r, null obrigatorio, l_url_id_familia_item url, null calcular_valor, 5825 id_artefato_versionado_zoom  FROM dual UNION ALL',
