'               SELECT p_codigo_artefato, ''codigo_embalagem_cod'',        17, '''', NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso'',                        18, '''', NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ALTURA'',                      19, '''', NULL, ''N'', ''S'', null valor, null obrigatorio, null url, l_JSON_calcular_volume calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''LARGURA'',                     20, '''', NULL, ''N'', ''S'', null valor, null obrigatorio, null url, l_JSON_calcular_volume calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PROFUNDIDADE'',                21, '''', NULL, ''N'', ''S'', null valor, null obrigatorio, null url, l_JSON_calcular_volume calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VOLUME'',                      22, '''', NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',           23, ''DAT'', NULL, ''N'', ''N'', pkg_data.fmtd((select a.data_fim_vigencia from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1), ''DATA'') valor, null obrig'
||'atorio, null url, null calcular_valor, null id_artefato_versionado_zoom FROM dual UNION ALL',
