'               SELECT p_codigo_artefato, ''id_item'',                     26, ''HID'', NULL, ''S'',''N'', to_char((SELECT id_item FROM ng_item_embalagem WHERE id = p_param1)) valor, null obrigatorio, null url, null calcular_valor, null id_artefato_versionado'
||'_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_embalagem'',                27, ''HID'', NULL, ''S'',''N'', p_param1 valor, null obrigatorio, null url, null calcular_valor, null id_artefato_versionado_zoom FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
