prompt --application/deployment/install/install_ui_mpd_td743
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157421875881045875)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD743'
,p_sequence=>2160
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD743" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;    ',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'end "UI_MPD_TD743";',
'/',
'create or replace package body "UI_MPD_TD743" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;        ',
'        l_label_titulo varchar2(4000);',
'        l_label_subtitulo varchar2(4000);',
'        l_label_distintivo varchar2(4000);        ',
'    begin',
'        l_label_titulo := pkg_ui.retorna_label_coluna(''imp_listadespesa.descricao'');',
'        l_label_subtitulo := pkg_ui.retorna_label_coluna(''imp_listadespesa.id_tenant'');',
'        l_label_distintivo := pkg_ui.retorna_label_coluna(''imp_listadespesa.data_fim_vigencia'');',
'        ',
'        l_sql := q''~',
'            select',
'                a.id,',
'                pkg_traducao.get_traducao(a.descricao) titulo,',
'                b.nome_fantasia subtitulo,',
'                ''#LABEL_TITULO#'' label_titulo,',
'                ''#LABEL_SUBTITULO#'' label_subtitulo,',
'                ''#LABEL_DISTINTIVO#'' label_distintivo,',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end distintivo,                ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_listadespesa.ind_origem_despesa'',',
'                    pkg_util.dominio_retorna_tag(''imp_listadespesa'',''ind_origem_despesa'',ind_origem_despesa), 12',
'                ) atributo1,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD743'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD743'') as opcao',
'            from imp_listadespesa a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            order by nome_fantasia, data_fim_vigencia nulls first, descricao',
'        ~'';        ',
'        l_sql := replace(l_sql, ''#LABEL_TITULO#'', l_label_titulo);',
'        l_sql := replace(l_sql, ''#LABEL_SUBTITULO#'', l_label_subtitulo);',
'        l_sql := replace(l_sql, ''#LABEL_DISTINTIVO#'', l_label_distintivo);        ',
'        return l_sql;                    ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;        ',
'    begin',
'        l_sql := q''~',
'        select ',
'            a.id id,  ',
'            b.nome_fantasia campo1,',
'            pkg_traducao.get_traducao(a.descricao) campo2,',
'            pkg_util.dominio_retorna_tag(''imp_listadespesa'',''ind_origem_despesa'',ind_origem_despesa) campo3,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'            end campo4,',
'            a.data_fim_vigencia campo5,            ',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            a.id_tenant filtro1,                ',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,            ',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            null opcao',
'        from imp_listadespesa a',
'        join mpd_tenant b on b.id = a.id_tenant        ',
'        ~'';',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'        l_region_id number;',
'    begin   ',
'        select region_id ',
'          into l_region_id ',
'          from apex_application_page_regions ',
'         where application_id = v(''APP_ID'') ',
'           and page_id        = v(''APP_PAGE_ID'') ',
'           and static_id      = ''LISTA_CR''; ',
'',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD743'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_listadespesa'',#l_region_id#)) a',
'            order by campo1, campo5 nulls first, campo2',
'            ~'';',
'        l_sql := replace(l_sql, ''#l_region_id#'', l_region_id);                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_listadespesa.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_listadespesa.descricao'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_listadespesa.ind_origem_despesa'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_listadespesa.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'    ',
'end "UI_MPD_TD743";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td745
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157422009614024428)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD745'
,p_sequence=>2170
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD745" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) ',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function sql_report_selecao(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'',
'end "UI_MPD_TD745";',
'/',
'create or replace package body "UI_MPD_TD745" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select pkg_traducao.get_traducao(descricao) descricao from imp_listadespesa where id = ''||p_param1,',
'            p_tabela => textarray(''imp_listadespesa''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from imp_listadespesa where i'
||'d = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_lista_despesa'', 3, ''HID'', null, ''S'', ''S'', to_char(p_param1) valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_despesa'',       4, '''', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'    function where_dinamico(p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_despesa'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                    )',
'                and b.id = apex_util.get_session_state(''P9013_PARAMETRO'')',
'            ~'';        ',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is        ',
'    begin',
'        bo_imp_listadespesa_despesa.inclui_registro(',
'            p_id_tenant => apex_application.g_f02(1),',
'            p_id_lista_despesa => apex_application.g_f03(1),            ',
'            p_id_despesa => apex_application.g_f04(1),            ',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'       );',
'    end post_create;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select        ',
'                a.id,',
'                null campo1,',
'                pkg_traducao.get_traducao(c.descricao_despesa) campo2,',
'                null campo3,',
'                null campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD745'') opcao',
'            from imp_listadespesa_despesa a',
'            join imp_listadespesa b on b.id = a.id_lista_despesa',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id = #param1#',
'            order by campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql;        ',
'    end sql_report;',
'',
'',
'    function sql_report_selecao(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                null selected,        ',
'                a.id,',
'                null campo1,',
'                pkg_traducao.get_traducao(c.descricao_despesa) campo2,',
'                null campo3,',
'                null campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD745'') opcao',
'            from imp_listadespesa_despesa a',
'            join imp_listadespesa b on b.id = a.id_lista_despesa',
'            join ng_despesa c on c.id = a.id_despesa',
'            where b.id = #param1#',
'            order by campo1',
'            ~'';',
'        l_sql := replace(l_sql,''#param1#'',nvl(p_param1,''''));',
'        return l_sql; ',
'    end sql_report_selecao;',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin ',
'        if campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_listadespesa_despesa.id_despesa'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_incluir(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010,',
'            p_items=> ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO,P9010_POSTAR_E_FECHAR'',',
'            p_values => ''TD986,TD986,''||p_param1||'',false'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',            ',
'            p_clear_cache => 9010',
'            );',
'        return l_url;',
'    end mostra_incluir;',
'',
'end "UI_MPD_TD745";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td750
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157422151417021849)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD750'
,p_sequence=>2180
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD750" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'    ',
'end "UI_MPD_TD750";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD750" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                pkg_traducao.get_traducao(c.descricao_item) titulo,',
'                b.nome_fantasia subtitulo,',
'                case ',
'                    when c.data_fim_vigencia is null then',
'                        null',
'                    else',
'                        pkg_data.fmtd(c.data_fim_vigencia, ''DATA'')',
'                end distintivo,                ',
'                case ',
'                    when c.data_fim_vigencia is null then',
'                        ''u-hidden''',
'                    when to_date(c.data_fim_vigencia) < to_date(current_date) then',
'                        ''data-fim-vigencia''',
'                    else',
'                        null',
'                end class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS            ',
'                pkg_componentes.html_card_colunas(''ng_item.codigo_item'',codigo_item, 6) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_nbs.codigo_nbs'',codigo_nbs, 6) atributo2,',
'                c.data_fim_vigencia,               ',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null filtro2,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD750'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD750'') as opcao                ',
'            from ng_item_servico a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_item c on c.id = a.id_item',
'            left join ng_nbs d on d.id = a.id_nbs',
'            where c.ind_tipo_item = ''S''',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1'')); ',
'            --order by 9 nulls first, 2           ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,',
'            b.nome_fantasia campo1,',
'            c.codigo_item campo2,',
'            pkg_traducao.get_traducao(c.descricao_item) campo3,',
'            d.codigo_nbs campo4,     ',
'            case when to_date(c.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(c.data_fim_vigencia, ''DATA''))',
'            else',
'                pkg_data.fmtd(c.data_fim_vigencia, ''DATA'')',
'            end campo5,                          ',
'            c.data_fim_vigencia campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            a.id_tenant filtro1,',
'            null filtro2,                                                           ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_item_servico a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_item c on c.id = a.id_item',
'        left join ng_nbs d on d.id = a.id_nbs            ',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD750'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_item_servico'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));    ',
'        --order by to_date(campo6,''dd/mm/yyyy'') nulls first, campo3    ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else ',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item_servico.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item_servico.id_nbs'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'        ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo6,campo1,campo3,campo2,campo4'';',
'        else',
'            campos := ''data_fim_vigencia,subtitulo,titulo,atributo1,atributo2'';',
'        end if;',
'',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'               label_coluna(''1'') || '','' ||',
'               label_coluna(''3'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo3'';',
'        else',
'            l_campos := ''data_fim_vigencia,subtitulo,titulo'';',
'        end if;',
'',
'        l_direcoes := ''DESC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD750";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td751
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157422266076018683)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD751'
,p_sequence=>2190
,p_script_type=>'INSTALL'
