'               SELECT p_codigo_artefato, ''data_fim_vigencia'',           23, ''DAT'', NULL, ''N'', ''N'', pkg_data.fmtd((select a.data_fim_vigencia from ng_item a join ng_item_servico b on b.id_item = a.id where b.id = p_param1), ''DATA'') valor, null obrigat'
