prompt --application/deployment/install/install_ui_mpd_td756
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157422511042007250)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD756'
,p_sequence=>2220
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD756" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD756";',
'/',
'create or replace package body "UI_MPD_TD756" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    pkg_traducao.get_traducao(a.descricao) descricao,',
'                    b.nome_fantasia id_tenant, ',
'                    pkg_util.dominio_retorna_tag(''''imp_listadespesa'''',''''ind_origem_despesa'''',a.ind_origem_despesa) ind_origem_despesa ',
'                from imp_listadespesa a join ',
'                mpd_tenant b on b.id = a.id_tenant ',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_listadespesa'',''imp_listadespesa'',''imp_listadespesa''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' coluna_tabela, to_char((select id_tenant from imp_listadespesa where id ='
||' p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_lista_despesa'', 3, ''HID'', null, ''N'', ''S'', p_param1 valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despesa'',       4, '''', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    function where_dinamico(p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_despesa'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                        or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                    )',
'                and b.id = apex_util.get_session_state(''P9010_PARAMETRO'')',
'            ~'';        ',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'        l_id number;',
'    begin',
'        bo_imp_listadespesa_despesa.inclui_registro(                                    ',
'            p_id_tenant=> apex_application.g_f02(1),',
'            p_id_lista_despesa => apex_application.g_f03(1),',
'            p_id_despesa => apex_application.g_f04(1),',
'            p_id => l_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'    ',
'end "UI_MPD_TD756";',
'/'))
);
end;
/
