'',
'end "UI_MPD_TD771";',
'/',
'create or replace package body "UI_MPD_TD771" as',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        l_html clob;      ',
'        l_sql clob;      ',
'    begin  ',
'        l_sql := ',
'        q''~',
'            select ',
'                b.nome_fantasia as ng_moeda$id_tenant, ',
'                a.codigo_moeda as ng_moeda$codigo_moeda, ',
'                a.descricao_moeda as ng_moeda$descricao_moeda, ',
