'                case',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') ',
'                end ng_moeda$data_fim_vigencia                 ',
'            from ng_moeda a',
'            join mpd_tenant b on b.id = a.id_tenant',
'        ~'';',
'                ',
'        l_html := pkg_log.gerar_html_diferencas2(p_param1);',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, '''' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' as coluna_tabela, null valor, l_html html FROM dual',
'            --    SELECT p_codigo_artefato, ''nome_entidade'',           2, '''', null, ''S'',''S'', null valor, null html FROM dual UNION ALL     ',
'            --    SELECT p_codigo_artefato, ''tipo_operacao'',           4, '''', null, ''N'',''S'', null valor, null html FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''id_registro'',             5, '''', null, ''N'',''S'', null valor, null html FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''data_operacao'',           6, '''', null, ''N'',''S'', null valor, null html FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''id_usuario'',              7, '''', null, ''N'',''S'', null valor, null html FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''dados_anteriores'',        8, ''GRI'', null, ''N'',''S'', l_sql valor, null html FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''dados_novos'',             9, ''JSO'', null, ''S'',''S'', null valor, null html FROM dual ',
'            --    SELECT p_codigo_artefato, '''',                       10, ''HTM'', null, ''N'',''N'', null valor, l_html html FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor,new_data.html);',
'    end formulario;',
'',
'end "UI_MPD_TD771";',
'/'))
);
end;
