||'naturezaoperacao = p_param1), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.percentual_reducao_base_icms'' tag_campo FROM dual WHERE (select ind_aplicacao_icms from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1) = 3 U'
