||' = p_param1), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.aliquota_cbs'' tag_campo FROM dual WHERE (select ind_aplicacao_cbs from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1) = 2 UNION ALL',
