||'aturezaoperacao = p_param1), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.percentual_reducao_base_cbs'' tag_campo FROM dual WHERE (select ind_aplicacao_cbs from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1) = 3 UNIO'
||'N ALL',
