||' = p_param1), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.aliquota_ibs'' tag_campo FROM dual WHERE (select ind_aplicacao_ibs from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1) = 2 UNION ALL',
'               SELECT p_codigo_artefato, ''percentual_reducao_base_ibs'',            27, ''TXT'', null, ''N'', ''N'', nvl((select to_char(percentual_reducao_base_ibs, ''FM990D00'', ''NLS_NUMERIC_CHARACTERS = '''',.'''''') from imp_naturezaoperacao_tributo where id_n'
