||'urezaoperacao = p_param1)), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.ind_base_calculo_afrmm'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_afrmm'',                         29, ''TXT'', null, ''N'', ''N'', nvl((select to_char(aliquota_afrmm, ''FM990D00'', ''NLS_NUMERIC_CHARACTERS = '''',.'''''') from imp_naturezaoperacao_tributo where id_naturezaoperac'
||'ao = p_param1), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.aliquota_afrmm'' tag_campo FROM dual WHERE (select ind_base_calculo_afrmm from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1) is not null UNION ALL',
'               SELECT p_codigo_artefato, ''ind_drawback'',                           30, ''RAD'', ''D_IMP_NATUREZAOPERACAO_TRIBUTO.IND_DRAWBACK'', ''N'', ''N'', nvl(to_char((select ind_drawback from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_pa'
||'ram1)), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.ind_drawback'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_drawback'',                31, ''POP'', ''D_IMP_NATUREZAOPERACAO_TRIBUTO.IND_MODALIDADE_DRAWBACK'', ''N'', ''N'', nvl(to_char((select ind_modalidade_drawback from imp_naturezaoperacao_tributo where id_n'
||'aturezaoperacao = p_param1)), '' '') valor, null obrigatorio, ''imp_naturezaoperacao_tributo.ind_modalidade_drawback'' tag_campo FROM dual WHERE (select ind_drawback from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1) = ''S'' UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',                     32, l_tipo, l_consulta, ''N'', ''N'', nvl(to_char((select id_usuario_alterou from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1)), '' '') valor, null obr'
||'igatorio, ''imp_naturezaoperacao_tributo.id_usuario_alterou'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                         34, ''TXT'', null, ''N'', ''N'', nvl(to_char((select data_alteracao from imp_naturezaoperacao_tributo where id_naturezaoperacao = p_param1), ''DD/MM/YYYY''), '' '') valor, null '
||'obrigatorio, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naturezaoperacao'',                    35, ''HID'', null, ''N'', ''S'', to_char(p_param1) valor, null obrigatorio, null tag_campo FROM dual',
'    ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN ',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.tag_campo);',
'    end formulario;',
'',
'end "UI_MPD_TD775";',
'/'))
);
end;
