prompt --application/deployment/install/install_ui_mpd_td778
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157422970730987173)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD778'
,p_sequence=>2250
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD778" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    function colunas_ordenar',
'    return clob;',
'',
'end "UI_MPD_TD778";',
'/',
'create or replace package body "UI_MPD_TD778" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_label_maisdetalhes varchar2(256);',
'        l_botao_opcao varchar2(4000);',
'        l_url varchar2(4000);        ',
'        -- l_padrao pkg_ui_sqlcard.t_padrao;',
'    begin',
'        -- pega os valores padronizados',
'        -- l_padrao := pkg_ui_sqlcard.get_padrao(''TD778'', p_param1, p_param2);',
'        -- select pkg_ui.retorna_label_botao(''maisdetalhes'') into l_label_maisdetalhes from dual;',
'        -- select pkg_ui.url_mais_detalhes2(''TD778'',p_param1,p_param2) into l_url from dual;',
'        l_sql := q''~',
'            select ',
'                a.id,',
'                c.descricao titulo,',
'                c.codigo_artefato subtitulo,',
'                case ',
unistr('                    when elapsed_time > 5 then ''Cr\00EDtico'''),
'                    when elapsed_time < 5 and elapsed_time > 2 then ''Moderado''',
unistr('                    when elapsed_time < 2 then ''Satisfat\00F3rio'''),
'                end distintivo,                 ',
'                case ',
'                    when elapsed_time > 5 then ''destaque--danger''',
'                    when elapsed_time < 5 and elapsed_time > 2 then ''destaque--warning''',
'                    when elapsed_time < 2 then ''destaque--success''',
'                end class_distintivo,   ',
'                ''texto-badge'' class_texto,',
'                null lista_distintivo,',
'                empty_blob() imagem,                ',
'                --FILTROS',
'                d.id filtro1,',
'                nvl(elapsed_time,0) filtro_rangen,',
'                TRUNC(view_date) filtro_ranged,',
'                --ATRIBUTOS   ',
unistr('                pkg_componentes.html_card_colunas(''Tempo de execu\00E7\00E3o'',to_char(round(elapsed_time,2), ''FM999990.00''),3,''s'') as atributo1,    '),
unistr('                pkg_componentes.html_card_colunas(''Data da execu\00E7\00E3o'',pkg_data.fmt(view_date,''DATA_SEGUNDO''),3,''s'') as atributo2,    '),
unistr('                pkg_componentes.html_card_colunas(''Usu\00E1rio'',apex_user,3,''s'') as atributo3,    '),
unistr('                pkg_componentes.html_card_colunas(''P\00E1gina'',page_id,3,''s'') as atributo4,    '),
'                --TECNICO',
'                replace(''#URL#'',''#ID#'',a.id) as url_mais_detalhes,       ',
'                pkg_componentes.html_botao_opcao(a.id,''TD778'') as opcao,  ',
'                ''#MAIS_DETALHES#'' label_mais_detalhes',
'            from apex_workspace_activity_log a',
'            join log_tempo_com_item b on b.apex_session_id = a.id',
'            join mpd_funcionalidade c on c.codigo_artefato = b.codigo_artefato',
'            join mpd_usuario d on upper(d.login) = upper(a.apex_user)',
'            order by view_date desc   ',
'            ~'';            ',
'            -- l_sql := replace(l_sql,''#MAIS_DETALHES#'',l_label_maisdetalhes);',
'            -- l_sql := replace(l_sql,''#BOTAO_OPCAO#'',l_botao_opcao);',
'            -- l_sql := replace(l_sql,''#URL#'',l_url);',
'            -- return pkg_ui_sqlcard.aplica_padrao(l_sql, l_padrao);',
'',
'',
'            return l_sql;',
'',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'  ',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'                a.id,',
'                c.descricao campo1,',
'                c.codigo_artefato campo2,',
'                case ',
unistr('                    when elapsed_time > 5 then ''Cr\00EDtico'''),
'                    when elapsed_time < 5 and elapsed_time > 2 then ''Moderado''',
unistr('                    when elapsed_time < 2 then ''Satisfat\00F3rio'''),
'                end campo3,                 ',
'                --FILTROS',
'                d.id filtro1,',
'                nvl(elapsed_time,0) filtro_rangen,',
'                TRUNC(view_date) filtro_ranged,',
'                --ATRIBUTOS   ',
unistr('                pkg_componentes.html_card_colunas(''Tempo de execu\00E7\00E3o'',to_char(round(elapsed_time,2), ''FM999990.00''),3,''s'') as campo4,    '),
unistr('                pkg_componentes.html_card_colunas(''Data da execu\00E7\00E3o'',pkg_data.fmt(view_date,''DATA_SEGUNDO''),3,''s'') as campo5,    '),
unistr('                pkg_componentes.html_card_colunas(''Usu\00E1rio'',apex_user,3,''s'') as campo6,    '),
unistr('                pkg_componentes.html_card_colunas(''P\00E1gina'',page_id,3,''s'') as campo7,    '),
'                --TECNICO',
'                replace(''#URL#'',''#ID#'',a.id) as url_mais_detalhes,       ',
'                null opcao',
'            from apex_workspace_activity_log a',
'            join log_tempo_com_item b on b.apex_session_id = a.id',
'            join mpd_funcionalidade c on c.codigo_artefato = b.codigo_artefato',
'            join mpd_usuario d on upper(d.login) = upper(a.apex_user)',
'            order by view_date desc   ',
'       ~'';       ',
'       --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select       ',
'                id,         ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                to_number(campo9) campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(id,''TD778'') as opcao, ',
'            from table(PKG_UI.pesquisa_facetada2(:app_page_id, ''LISTA_CR'',''apex_workspace_activity_log'')) a',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''10 desc''));',
'        return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome d, id r from mpd_usuario order by 1~'';',
'        elsif campo = ''RN'' then',
'            return q''~',
'                select pkg_componentes.html_label_destaque(3) d, ''5|'' r from dual union all',
'                select pkg_componentes.html_label_destaque(2) d, ''3|4'' r from dual union all',
'                select pkg_componentes.html_label_destaque(1) d, ''|2'' r from dual',
'            ~'';',
'        elsif campo = ''RD'' then',
'            return q''~',
'                select ''Hoje'' d, to_char(sysdate,''YYYYMMDD'')||''000000|'' r from dual union all',
'                select ''Ontem'' d, to_char(sysdate-1,''YYYYMMDD'')||''000000|'' r from dual union all',
unistr('                select ''Nos \00FAltimos 7 dias'' d, to_char(sysdate-7,''YYYYMMDD'')||''000000|'' r from dual union all'),
unistr('                select ''Nos \00FAltimos 30 dias'' d, to_char(sysdate-30,''YYYYMMDD'')||''000000|'' r from dual union all'),
unistr('                select ''H\00E1 mais de 30 dias'' d, ''|''||to_char(sysdate-30,''YYYYMMDD'')||''000000'' r from dual '),
'            ~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin      ',
'        if campo = ''1'' then                     ',
unistr('            l_campo := ''Descri\00E7\00E3o'';'),
'        elsif campo = ''2'' then                     ',
'            l_campo := ''Artefato'';',
'        elsif campo = ''3'' then                     ',
unistr('            l_campo := ''Tempo de execu\00E7\00E3o'';'),
'        elsif campo = ''4'' then                     ',
unistr('            l_campo := ''Data de execu\00E7\00E3o'';'),
'        elsif campo = ''5'' then                     ',
unistr('            l_campo := ''Usu\00E1rio'';'),
'        elsif campo = ''6'' then                     ',
'            l_campo := ''Performance'';',
'        elsif campo = ''9'' then                     ',
unistr('            l_campo := ''Tempo de execu\00E7\00E3o (number)'';'),
'        elsif campo = ''F1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''mpd_usuario.nome'') into l_campo from dual;',
'        elsif campo = ''M1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''mpd_usuario.nome'') into l_campo from dual;',
'        elsif campo = ''RN'' then                     ',
'            l_campo := ''Performance'';',
'        elsif campo = ''RD'' then                     ',
unistr('            l_campo := ''Data de execu\00E7\00E3o'';'),
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function colunas_ordenar',
'    return clob is',
'        l_campo clob;',
'    begin',
'        return q''~ select null d, null r from dual ~'';',
'    end colunas_ordenar;',
'',
'end "UI_MPD_TD778";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td784
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157423010467983665)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD784'
,p_sequence=>2260
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD784" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure esconde_incluir;',
'',
'    function mostra_opcao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_report(p_param1 in varchar2) return clob;',
'',
'    function label_coluna(campo in varchar2) return clob;',
'',
'end "UI_MPD_TD784";',
'/',
'',
'create or replace package body "UI_MPD_TD784" as',
'',
'    procedure esconde_incluir is',
'    begin',
'        null;',
'    end;',
'',
'    function mostra_opcao(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob is',
'        l_url clob;',
'        l_id_pedidoimportacao number;',
'    begin',
'        select id_pedidoimportacao into l_id_pedidoimportacao from imp_entrega where id = p_param1;',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9000,',
'            p_items=> ''P9000_ID,P9000_PAGINA,P9000_PARAMETRO'',',
'            p_values => l_id_pedidoimportacao || '',TD784, 0''',
'            );',
'    return l_url;',
'    end;',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select                ',
'                a.numero_pedido_importacao,',
'                b.num_entrega,',
'                    case when b.id_processoimportacao is null then',
'                        pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                        else d.num_processoimportacao',
'                    end id_processoimportacao',
'            from ',
'            imp_entrega b',
'            JOIN imp_pedidoimportacao a ON a.id = b.id_pedidoimportacao',
'            left join imp_processoimportacao d ON d.id = b.id_processoimportacao',
'            where b.id =  ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'        l_tipo_id_condicaopagamento varchar2(4000);',
'        l_consulta_id_condicaopagamento varchar2(4000);',
'        l_id_condicaopagamento varchar2(4000);',
'',
'        l_tipo_ind_status_pagamento varchar2(4000);',
'        l_consulta_ind_status_pagamento varchar2(4000);',
'        l_ind_status_pagamento varchar2(4000);',
'    begin',
'        select max(id_condicaopagamento) into l_id_condicaopagamento from imp_pedidoimportacao a join imp_entrega b on b.id_pedidoimportacao = a.id where b.id = p_param1;',
'        select max(ind_status_pagamento) into l_ind_status_pagamento from imp_pedidoimportacao_pagamento where id_entrega = p_param1;',
'        ',
'        if l_id_condicaopagamento is null then',
'            l_tipo_id_condicaopagamento := ''TXT'';',
'            l_consulta_id_condicaopagamento := '''';',
'        else',
'            l_tipo_id_condicaopagamento := ''SEL'';',
'            l_consulta_id_condicaopagamento := ''D_NG_CONDICAOPAGAMENTO.DESCRICAO_CONDICAOPAGAMENTO'';',
'        end if;',
'        ',
'',
'        if l_ind_status_pagamento is null then',
'            l_tipo_ind_status_pagamento := ''TXT'';',
'            l_consulta_ind_status_pagamento := '''';',
'        else',
'            l_tipo_ind_status_pagamento := ''SEL'';',
'            l_consulta_ind_status_pagamento := ''D_IMP_PEDIDOIMPORTACAO_PAGAMENTO.IND_STATUS_PAGAMENTO'';',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from i'
||'mp_entrega where id = p_param1)) valor, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_condicaopagamento'',            3, l_tipo_id_condicaopagamento, l_consulta_id_condicaopagamento, ''S'', ''S'', nvl(to_char((select a.id_condicaopagamento from imp_pedidoimportacao a join imp_entrega b on b.id_p'
||'edidoimportacao = a.id where b.id = p_param1)),'' '') valor, null tag_campo from dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas_pagamento'',   5, '''', null, ''S'', ''S'', nvl(to_char((select a.quantidade_parcelas_pagamento from imp_pedidoimportacao a join imp_entrega b on b.id_pedidoimportacao = a.id where b.id = p_param'
||'1)), '' '') valor, null tag_campo from dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    function sql_report(p_param1 in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin',
'        -- l_sql := ''      ',
'        --     select distinct',
'        --         a.id id,  ',
'        --         null campo1,                                                          ',
