'        --           ) then retorna_texto(''''msg.121.l'''')',
'        --           else to_char(b.num_entrega)',
'        --         end as campo2,',
'        --         a.numero_parcela campo3,',
'        --         a.percentual||''''%'''' campo4,  ',
'        --         pkg_util.dominio_retorna_tag(''''ng_condicaopagamento_parcela'''', ''''ind_evento_gerador_pagamento'''',     ',
'        --             bo_ng_condicaopagamento_parcela.retorna_ind_evento_gerador_pagamento(c.id_condicaopagamento, a.numero_parcela)',
'        --         ) campo5,',
'        --         to_char(a.valor, ''''FM999G999G990D00'''') campo6,             ',
'        --         case',
'        --             when a.ind_status_pagamento = 1 then ',
'        --                 to_char(a.data_vencimento_prevista, ''''dd/mm/yyyy'''')',
'        --             when a.ind_status_pagamento in (2, 3) then                       ',
'        --                 to_char(a.data_vencimento_real, ''''dd/mm/yyyy'''')',
'        --         end campo7,',
'        --         case',
'        --             when a.ind_status_pagamento = 1 and (a.data_vencimento_prevista is not null or a.data_vencimento_real is not null) then',
'        --                 pkg_componentes.html_cor_texto(pkg_util.dominio_retorna_tag(''''imp_pedidoimportacao_pagamento'''', ''''ind_status_pagamento'''', a.ind_status_pagamento))',
'        --             else',
'        --                 pkg_util.dominio_retorna_tag(''''imp_pedidoimportacao_pagamento'''', ''''ind_status_pagamento'''', a.ind_status_pagamento)',
'        --         end campo8,',
'        --         null campo9,',
'        --         null campo10,',
'        --         --FILTROS',
'        --         null filtro1,                                ',
'        --         null filtro2,                                ',
'        --         null filtro3,                                ',
'        --         null filtro4,',
'        --         null filtro5,                                ',
'        --         --FILTROS MULTI',
'        --         null filtro_mult1,                                ',
'        --         null filtro_mult2,                                ',
'        --         null filtro_mult3, ',
'        --         null filtro_mult4,                                ',
'        --         null filtro_mult5,                ',
'        --         case a.ind_status_pagamento',
'        --             when 1 then pkg_componentes.html_botao_opcao(a.id,''''TD784'''') ',
'        --             when 2 then pkg_componentes.html_botao_opcao(p_id => d.id, p_pagina => ''''TD784'''', p_param1 => -1)',
'        --             when 3 then pkg_componentes.html_botao_opcao(p_id => d.id, p_pagina => ''''TD784'''', p_param1 => -1)',
'        --         end opcao',
'        --     from imp_pedidoimportacao_pagamento a',
'        --     left join imp_entrega b on b.id = a.id_entrega',
'        --     join imp_pedidoimportacao c on c.id = a.id_pedidoimportacao',
'        --     left join fin_titulopagamento d on d.id_referencia = a.id and d.id_entidade = (select id from srv_entidade where lower(nome_entidade) = ''''imp_pedidoimportacao'''')',
'        --     where a.id_pedidoimportacao = (select id_pedidoimportacao from imp_entrega where id = ''||p_param1||'')',
'        --     and (a.id_entrega is null or a.id_entrega = ''||p_param1||'')',
'        --     --AND D.IND_STATUS_PAGAMENTO NOT IN (3,4)',
'        -- '' ;',
'        l_sql := q''~',
'            select ',
'                a.id id,',
'                null campo1,                ',
'                case',
'                  when a.id_entrega is null then ',
'                    retorna_texto(''msg.121.l'')',
'                  else ',
'                    to_char(b.num_entrega)',
'                end as campo2,                ',
'                a.numero_parcela campo3,',
'                a.percentual||''%'' campo4,      ',
'                pkg_util.dominio_retorna_tag(''ng_condicaopagamento_parcela'', ''ind_evento_gerador_pagamento'',     ',
'                    bo_ng_condicaopagamento_parcela.retorna_ind_evento_gerador_pagamento(c.id_condicaopagamento, a.numero_parcela)',
'                ) campo5,',
'                to_char(a.valor, ''FM999G999G990D00'') campo6,',
'                case',
'                    when a.ind_status_pagamento = 1 then ',
'                        pkg_data.fmtd(a.data_vencimento_prevista, ''DATA'')',
'                    else                        ',
'                        pkg_data.fmtd(a.data_vencimento_real, ''DATA'')',
'                end campo7,',
'                case',
'                    when a.ind_status_pagamento = 1 and a.data_vencimento_prevista is not null then ',
'                        pkg_componentes.html_cor_texto(pkg_util.dominio_retorna_tag(''imp_pedidoimportacao_pagamento'', ''ind_status_pagamento'', a.ind_status_pagamento))',
'                    else                        ',
'                        pkg_util.dominio_retorna_tag(''imp_pedidoimportacao_pagamento'', ''ind_status_pagamento'', a.ind_status_pagamento)',
'                end campo8,',
'                null campo9,',
'                null campo10,',
'                --FILTROS',
'                null filtro1,                                ',
'                null filtro2,                                ',
'                null filtro3,                                ',
'                null filtro4,',
'                null filtro5,                                ',
'                --FILTROS MULTI',
'                null filtro_mult1,                                ',
'                null filtro_mult2,                                ',
'                null filtro_mult3, ',
'                null filtro_mult4,                                ',
'                null filtro_mult5,',
'                case a.ind_status_pagamento',
'                    when 1 then pkg_componentes.html_botao_opcao(a.id,''TD638'') ',
'                    when 2 then pkg_componentes.html_botao_opcao(p_id => d.id, p_pagina => ''TD638'', p_param1 => -1)',
'                    when 3 then pkg_componentes.html_botao_opcao(p_id => d.id, p_pagina => ''TD638'', p_param1 => -1)',
'                end opcao',
'                --pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD638'', p_param1 => 0) opcao                ',
'            from imp_pedidoimportacao_pagamento a',
'            left join imp_entrega b on b.id = a.id_entrega',
'            join imp_pedidoimportacao c on c.id = a.id_pedidoimportacao',
'            left join fin_titulopagamento d on d.id_referencia = a.id and d.id_entidade = (',
'                select id from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao''',
'            )',
'            and d.ind_status_pagamento not in (3,4)            ',
'            where a.id_pedidoimportacao = (select id_pedidoimportacao from imp_entrega where id = #PARAM1#)',
'            and (a.id_entrega is null or a.id_entrega = #PARAM1#)',
'            order by campo2 nulls first, campo3',
'        ~'';',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;',
'    end sql_report;',
'    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin ',
'        if campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.id_entrega'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.numero_parcela'') into l_campo from dual;',
'        elsif campo = ''4'' then                        ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.percentual'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.ind_evento_gerador_pagamento'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.valor'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_tela(''vencimento'') into l_campo from dual;',
'        elsif campo = ''8'' then',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_pagamento.ind_status_pagamento'') into l_campo from dual;            ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'end "UI_MPD_TD784";',
