,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD788'
,p_sequence=>2290
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD788" as   ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD788";',
'/',
'create or replace package body "UI_MPD_TD788" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin           ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select ',
'                    a.numero_pedido_importacao,',
'                    b.num_entrega                    ',
'                from imp_pedidoimportacao a',
'                join imp_entrega b on b.id_pedidoimportacao = a.id',
'                where b.id = ''|| p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_sql_grid_1 clob;',
'        l_id_entidade number;',
'    begin',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_entrega'';',
'        l_sql_grid_1 := q''~',
'            select srv_auditoria_log$data_operacao, campo, valor from (',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,                    ',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.id_local_embarque'') campo,',
'                    to_char(chamar_webservice_traducao(esquema_corrente,''ng_localembarquedesembarque'',''nome_local'',apex_util.get_session_state(''IDIOMA_LOGADO''),bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''id_local_embarque''))) valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#                ',
'                and json_exists(dados_novos, ''$[*]?(@.id_local_embarque!= null)'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,                    ',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.id_local_desembarque'') campo,',
'                    to_char(chamar_webservice_traducao(esquema_corrente,''ng_localembarquedesembarque'',''nome_local'',apex_util.get_session_state(''IDIOMA_LOGADO''),bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''id_local_desembarque''))) valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*]?(@.id_local_desembarque!= null)'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.id_viatransporte'') campo,',
'                    to_char(chamar_webservice_traducao(esquema_corrente,''ng_viatransporte'',''descricao_viatransporte'',apex_util.get_session_state(''IDIOMA_LOGADO''),bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''id_viatransporte''))) valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*].id_viatransporte'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.ind_status_entrega'') campo,',
'                    pkg_util.dominio_retorna_tag(''imp_entrega'',''ind_status_entrega'',bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''ind_status_entrega'')) valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*].ind_status_entrega'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.data_disponivel_real'') campo,',
'                    bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''data_disponivel_real'') valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*]?(@.data_disponivel_real != null)'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.data_embarque_real'') campo,',
'                    bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''data_embarque_real'') valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*]?(@.data_embarque_real != null)'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.data_desembarque_real'') campo,',
'                    bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''data_desembarque_real'') valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*]?(@.data_desembarque_real != null)'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.data_nacionalizacao_real'') campo,',
'                    bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''data_nacionalizacao_real'') valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*]?(@.data_nacionalizacao_real != null)'')',
'                union all',
'                select ',
'                    pkg_data.fmt(data_operacao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,',
'                    pkg_ui.retorna_label_coluna(''imp_entrega.data_recebimento_real'') campo,',
'                    bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''data_recebimento_real'') valor',
'                from srv_auditoria_log',
'                where nome_entidade = ''imp_entrega''',
'                and id_registro = #PARAM1#',
'                and json_exists(dados_novos, ''$[*]?(@.data_recebimento_real != null)'')',
'                union all',
'                select',
'                    pkg_data.fmt(a.data_alteracao, ''DATA_SEGUNDO'') srv_auditoria_log$data_operacao,                    ',
'                    pkg_ui.retorna_label_tela(''observacao'') campo,',
'                    to_char(chamar_webservice_traducao(esquema_corrente,''imp_observacao'',''observacao'',apex_util.get_session_state(''IDIOMA_LOGADO''),a.id)) valor',
'                from imp_observacao a                ',
'                join imp_entrega b on b.id = a.id_referencia',
'                where b.id = #PARAM1#',
'                and a.id_entidade in (#ID_ENTIDADE#)',
'            )',
'            order by to_timestamp(srv_auditoria_log$data_operacao,''dd/mm/yyyy hh24:mi:ss'') desc            ',
'        ~'';',
'        l_sql_grid_1 := trim(replace(l_sql_grid_1, ''#PARAM1#'', p_param1));',
'        l_sql_grid_1 := trim(replace(l_sql_grid_1, ''#ID_ENTIDADE#'', l_id_entidade));',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna1'' AS nome_coluna, 1 AS indice, ''GRI'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, to_char(l_sql_grid_1) valor, null html, null tag_campo FR'
||'OM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);        ',
'    end formulario;    ',
'    ',
