'                    (select num_invoice from imp_invoice where id = id_registro) imp_invoice$num_invoice,',
'                    pkg_ui.retorna_label_coluna(''imp_invoice.ind_status'') campo,',
'                    pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_status'',bo_imp_pedidoimportacao.retorna_auditoria_log(dados_novos,''ind_status'')) valor',
