unistr('                ''Data de execu\00E7\00E3o'','),
'                PKG_DATA.FMT(created_on,''DATA_SEGUNDO''),3,''S''',
'               ) as atributo1,',
'               pkg_componentes.html_card_colunas(',
'                '''',',
'                pkg_componentes.html_progress_bar(execution_id,sofar,totalwork),3,''S''',
'               ) as atributo2,',
'               null lista_distintivo,',
'               null filtro_mult1,',
'               null filtro_mult2,  ',
'               pkg_ui.url_mais_detalhes(''TD812'',execution_id) url_mais_detalhes,',
'               pkg_componentes.html_botao_opcao(execution_id,''TD812'') as opcao                ',
'            from apex_appl_page_bg_proc_status ',
'            where STATUS_CODE = ''EXECUTING''',
'            union all',
'            select ',
'               execution_id id,',
'               pkg_ui.retorna_titulo_tela(codigo_artefato) titulo,',
'               status subtitulo,',
'               status_code distintivo,',
'               null class_distintivo,',
'               created_on,               ',
'               null filtro1,',
'               null filtro2,',
'               null filtro3,',
'               null filtro4,',
'               null filtro5,',
'               null icon,',
'               pkg_componentes.html_card_colunas(',
unistr('                ''Data de execu\00E7\00E3o'','),
'                pkg_data.fmt(created_on,''DATA_SEGUNDO''),3,''S''',
'               ) as atributo1,',
'               pkg_componentes.html_card_colunas(',
'                '''',',
'                pkg_componentes.html_progress_bar(execution_id,sofar,totalwork),3,''S''',
'               ) as atributo2,',
'               null lista_distintivo,',
'               null filtro_mult1,',
'               null filtro_mult2,  ',
