'               pkg_componentes.html_botao_opcao(execution_id,''TD812'') as opcao                ',
'            from SRV_BG_PROC_STATUS',
'            where STATUS_CODE != ''EXECUTING'' ',
'            ) order by created_on desc',
'            ~'';',
'            return l_sql;',
'          ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id,',
'            c.nome_entidade titulo,',
'            b.razao_social subtitulo,',
'            null distintivo,',
'            null class_distintivo,',
'            null campo4,',
'            null campo5,             ',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,',
'            a.log_insert filtro1,',
'            a.log_update filtro2,',
'            a.log_delete filtro3,',
'            a.log_total filtro4,              ',
'            a.id_tenant filtro5,',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                                  ',
'            null opcao',
'        from srv_auditoria_controle a',
'        left join mpd_tenant b on b.id = a.id_tenant',
'        left join mpd_entidade c on c.id = a.id_entidade',
'        ~'';   ',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report',
'    return clob is',
'    begin   ',
'        return q''~',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(id,''TD812'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''srv_auditoria_controle'')) a',
'            ~'';',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin  ',
'        return null;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar2)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        return null;',
'    end label_coluna;',
'',
'    -- procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    -- begin',
'    --     if p_card_ou_grid = ''CARD'' then',
'    --         campos := ''nome_artefato,descricao_artefato,codigo_artefato'';',
'    --     else',
'    --         campos := ''campo4,campo1,campo2'';',
'    --     end if;',
'    --     select pkg_ui.retorna_label_coluna(''srv_artefato.nome_artefato'') || '','' ||',
'    --        pkg_ui.retorna_label_coluna(''srv_artefato.descricao_artefato'') || '','' ||',
'    --        pkg_ui.retorna_label_coluna(''srv_artefato.codigo_artefato'')',
'    --     into labels',
'    --     from dual;',
'    -- end campos_ordenacao;  ',
'',
'end "UI_MPD_TD812";',
'/'))
);
end;
