prompt --application/deployment/install/install_ui_mpd_td849
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157424837701913925)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD849'
,p_sequence=>2330
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 25/06/2026',
unistr('-- Motivo: Ajuste inclus\00E3o colunas ind_finalidade e numero_ato_concessorio'),
'-- Desenvolvedor: Jonathan',
'-- Jira: PEDITEM-105',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD849" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD849";',
'/',
'',
'create or replace package body "UI_MPD_TD849" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao as num_processoimportacao',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin   ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null obrigatorio, null tag_campo FROM dual '
||'UNION ALL',
'                SELECT p_codigo_artefato, ''id_item'',                        2, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''descricao'',                      3, ''TEX'', null, ''N'', ''N'', to_char((select a.descricao_item from ng_item a join imp_processoimportacao_item b on b.id_item = a.id where b.id = p_param1)) valor, null obrigator'
||'io, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_ncm'',                         4, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_unidademedida'',               5, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''quantidade'',                     6, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''peso_unitario'',                  7, '''', null, ''N'', ''S'', to_char((select peso_unitario from imp_processoimportacao_item where id = p_param1)) valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''peso_liquido_total'',             8, '''', null, ''N'', ''S'', to_char((select peso_liquido_total from imp_processoimportacao_item where id = p_param1)) valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_moeda'',                       9, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''valor_unitario'',                10, '''', null, ''N'', ''S'', to_char((select valor_unitario from imp_processoimportacao_item where id = p_param1)) valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''valor_desconto'',                11, '''', null, ''N'', ''S'', to_char((select valor_desconto from imp_processoimportacao_item where id = p_param1)) valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''valor_total_condicao_venda'',    12, '''', null, ''N'', ''S'', to_char((select valor_total_condicao_venda from imp_processoimportacao_item where id = p_param1)) valor, null obrigatorio, null tag_campo FROM dual UNI'
||'ON ALL',
'                SELECT p_codigo_artefato, ''id_naturezaoperacao'',           13, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_fabricante'',                 14, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''ind_licenca_importacao'',        15, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_centrocusto'',                16, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''ind_finalidade'',                17, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''numero_ato_concessorio'',        18, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''num_solicitacao_compra'',        19, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''nome_solicitante'',              20, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_entrega_desejada'',         21, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_usuario_alterou'',            22, '''', null , ''N'', ''S'', null valor, null obrigatorio, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''data_alteracao'',                24, ''TXT'', null, ''N'', ''S'', pkg_data.fmtd((select data_alteracao from imp_processoimportacao_item where id = p_param1), ''DATA'') valor, null obrigatorio, null tag_campo FROM dua'
||'l',
'    ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN ',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.tag_campo);',
'    end formulario;',
'',
'end "UI_MPD_TD849";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td871
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157425078187901405)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD871'
,p_sequence=>2340
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD871" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'',
'',
'end "UI_MPD_TD871";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD871" as    ',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id ,                                                            ',
'                a.id_tenant,',
'                a.ind_tipo,',
'                nvl(pkg_traducao.get_traducao(c.nome_estado), pkg_util.dominio_retorna_tag(''ng_ibu'', ''ind_tipo'', a.ind_tipo)) titulo,',
'                b.nome_fantasia subtitulo, ',
'                pkg_util.dominio_retorna_tag(''ng_ibu'', ''ind_tipo'', a.ind_tipo) distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_ibu.aliquota_ibu'', to_char(a.aliquota_ibu, ''FM999G990D00''), 2 ) atributo1,',
'                --pkg_componentes.html_card_colunas(''ng_ibu.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 10 ) atributo2,',
'                case',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_ibu.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 10)',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_ibu.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 10 )',
'                end atributo2,',
'                --order',
'                pkg_traducao.get_traducao(c.nome_estado) order1,',
'                a.aliquota_ibu order2,',
'                a.data_fim_vigencia order3,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null filtro2,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2, ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD871'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD871'') as opcao ',
'            from ng_ibu a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_estado c on c.id = a.id_uf_destino',
'            order by #ORDER#',
'        ~'';',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'        return l_sql; ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select ',
'                a.id,                                                            ',
'                b.nome_fantasia campo1,',
'                pkg_util.dominio_retorna_tag(''ng_ibu'', ''ind_tipo'', a.ind_tipo) campo2,',
'                pkg_traducao.get_traducao(c.nome_estado) campo3,',
'                to_char(a.aliquota_ibu, ''FM999G990D00'') campo4,  ',
'                --pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') campo5,',
'                case when ',
'                    to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo5,',
'                a.data_fim_vigencia campo6,',
'                a.aliquota_ibu campo7,                                      ',
'                null campo8,                                      ',
'                null campo9,                                      ',
'                null campo10,  ',
'                --FILTROS',
'                a.id_tenant filtro1,                                ',
'                null filtro2,                                ',
'                null filtro3,                                ',
'                null filtro4,',
'                null filtro5,                                ',
'                --FILTROS MULTI',
'                null filtro_mult1,                                ',
'                null filtro_mult2,                                ',
'                null filtro_mult3, ',
'                null filtro_mult4,                                ',
'                null filtro_mult5,                              ',
'                null opcao',
'            from ng_ibu a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_estado c on c.id = a.id_uf_destino          ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select  ',
'                id,              ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                to_date(campo6,''DD/MM/YYYY'')campo6,              ',
'                to_number(campo7)campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD871'') as opcao ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_naladi'')) a ',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then             ',
'            return q''~select nome_fantasia d, id r from mpd_tenant order by 1~''; ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro; ',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibu.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibu.ind_tipo'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibu.id_uf_destino'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibu.aliquota_ibu'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibu.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;   ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo7,campo6'';',
'        else',
'            campos := ''subtitulo,distintivo,order1,order2,order3'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2,campo3'';',
'        else',
'            l_campos := ''order3,subtitulo,distintivo,order1'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD871";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td872
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157425342298897526)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD872'
,p_sequence=>2350
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD872" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD872";',
'/',
'create or replace package body "UI_MPD_TD872" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'    begin         ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null obrigatorio, null id_arte'
||'fato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo'',       2, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_uf_destino'',  3, ''POP'', ''R_NG_ESTADO.NOME_ESTADO'', ''N'',''N'', null valor, ''ng_ibu.id_uf_destino'' tag_campo, ''S'' obrigatorio, 6046 id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_ibu'',   5, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, obrigatorio, id_artefato_versionado_zoom)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.obrigatorio, new_data'
||'.id_artefato_versionado_zoom);',
'    end formulario;',
'',
'    function where_dinamico(p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_uf_destino'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.id_pais = (',
'                    select id_registro from mpd_configuracao_ng where codigo_configuracao = 1 and id_tenant = (',
'                        select c002 from apex_collections where collection_name = ''TD872_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_tenant'')',
'                   )',
'                )',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_ng_ibu.inclui_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_ind_tipo => apex_application.g_f02(1),',
'            p_id_uf_destino => apex_application.g_f03(1),',
'            p_aliquota_ibu => pkg_util.retorna_number(apex_application.g_f05(1)),',
'            p_data_fim_vigencia => null,',
'            p_id => l_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages            ',
'        );',
'    end;',
'end "UI_MPD_TD872";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td888
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157425700247891456)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD888'
,p_sequence=>2360
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD888" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD888";',
'/',
'create or replace package body "UI_MPD_TD888" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html                  clob;',
'        l_entidade              varchar2(4000);',
'        l_id_entidade           ng_anexo.id_entidade%type;',
'        l_id_referencia         ng_anexo.id_referencia%type;',
'    begin',
'        select id_entidade, id_referencia into l_id_entidade, l_id_referencia from ng_anexo where id = p_param1;',
'        select descricao_entidade into l_entidade from srv_entidade where id = l_id_entidade;',
'',
'        if l_id_entidade = 3829 then                        -- 3829 = id_entidade(srv_entidade) de imp_pedidoimportacao',
'            l_html := pkg_util.ObterValoresDasColunas(',
'                p_consulta_sql => ''',
'                    select distinct',
'                        c.nome_fantasia as id_tenant,',
'                        '''''' || l_entidade || '''''' as id_entidade,',
'                        a.numero_pedido_importacao',
'                    from imp_pedidoimportacao a',
'                    join mpd_tenant c on c.id = a.id_tenant',
'                    where a.id = '' || l_id_referencia,',
'                p_tabela => textarray(''imp_processoimportacao'',''ng_anexo'',''imp_pedidoimportacao''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe => ''st-back-transparente''',
'            );',
'',
'        elsif l_id_entidade = 4085 then                     -- 4085 = id_entidade(srv_entidade) de imp_entrega',
'            l_html := pkg_util.ObterValoresDasColunas(',
'                p_consulta_sql => ''',
'                    select distinct',
'                        c.nome_fantasia as id_tenant,',
'                        '''''' || l_entidade || '''''' as id_entidade,',
'                        b.numero_pedido_importacao,',
'                        a.num_entrega',
'                    from imp_entrega a',
'                    join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'                    join mpd_tenant c on c.id = a.id_tenant',
'                    where a.id = '' || l_id_referencia,',
'                p_tabela => textarray(''imp_processoimportacao'',''ng_anexo'',''imp_pedidoimportacao'',''imp_entrega''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe => ''st-back-transparente''',
'            );',
'',
'        elsif l_id_entidade = 4324 then                        -- 4324 = id_entidade(srv_entidade) de imp_processoimportacao',
'            l_html := pkg_util.ObterValoresDasColunas(',
'                p_consulta_sql => ''',
'                    select distinct',
'                        c.nome_fantasia as id_tenant,',
'                        '''''' || l_entidade || '''''' as id_entidade,',
'                        a.num_processoimportacao',
'                    from imp_processoimportacao a',
'                    join mpd_tenant c on c.id = a.id_tenant',
'                    where a.id = '' || l_id_referencia,',
'                p_tabela => textarray(''imp_processoimportacao'',''ng_anexo'',''imp_processoimportacao''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe => ''st-back-transparente''',
'            );',
'',
'        end if;',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_consulta_item clob;',
'    begin        ',
'        l_consulta_item := ''select a.nome_documento, a.id from ng_documento a where (a.data_fim_vigencia is null or to_date(a.data_fim_vigencia) >= to_date(current_date)) and a.id_entidade = (select b.id_entidade from ng_anexo b where b.id = apex_uti'
||'l.get_session_state(''''P9010_PARAMETRO2''''))'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null'
||' atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_referencia'',               4, ''HID'', null, ''S'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_documento'',                6, ''POP1'', to_char((l_consulta_item)), ''S'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_documento'',            8, '''', null, ''N'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VERSAO_DOCUMENTO'',            9, ''TXT'', null, ''S'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_documento'',             10, '''', null, ''N'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao'',               11, '''', null, ''N'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                 12, '''', null, ''N'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',         13, ''SEL'', ''R_MPD_USUARIO.NOME'' as nome_consulta, ''N'',''S'', null valor, null tag_campo, null atribuir_valor FROM dual UNION ALL                ',
'               SELECT p_codigo_artefato, ''data_alteracao'',             15, ''TXT'', null, ''N'',''S'', pkg_data.fmt((SELECT data_alteracao FROM ng_anexo WHERE id = p_param1), ''DATA_SEGUNDO'') valor, null tag_campo, null atribuir_valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, atribuir_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.atribuir_valor);',
'    end formulario;',
'',
'end "UI_MPD_TD888";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td912
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157426278470880743)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD912'
,p_sequence=>2370
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD912',
'-- Data: 15/05/2026',
unistr('-- Motivo: Inclu\00EDdo campos numero_pedido_importacao, num_sequencia_item e num_entrega.'),
'-- Jira: PEDITEM-180',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD912" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'    ',
'end "UI_MPD_TD912";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD912" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_invoice,',
'                    pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                    case',
'                        when c.num_processoimportacao is not null then',
'                            c.num_processoimportacao',
'                        else',
'                            pkg_componentes.html_cor_texto(pkg_ui.retorna_label_tela(''''sem_processo''''))',
'                    end id_processoimportacao',
'                from imp_invoice a',
'                join imp_invoice_item b on b.id_invoice = a.id',
'                left join imp_processoimportacao c on c.id = a.id_processoimportacao            ',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );   ',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is        ',
'        l_moeda varchar2(4000);',
'        l_quantidade varchar2(4000);',
'        l_numero_pedido_importacao varchar2(4000);',
'        l_num_sequencia_item varchar2(4000);',
'        l_num_entrega varchar2(4000);',
'    begin',
'        select c.codigo_moeda||'' - ''||c.simbolo_iso into l_moeda from imp_invoice a join imp_invoice_item b on b.id_invoice = a.id join ng_moeda c on c.id = a.id_moeda where b.id = p_param1;',
'',
'        select ',
'            case ind_tipo_dado',
'                when ''D'' then ',
'                    to_char(quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then',
'                    to_char(quantidade)',
'            end ',
'        into ',
'            l_quantidade',
'        from imp_invoice_item a',
'        join ng_unidademedida b on b.id = a.id_unidademedida',
'        where a.id = p_param1;',
'',
'        select ',
'            d.numero_pedido_importacao,',
'            e.num_sequencia_item,',
'            c.num_entrega',
'        into',
'            l_numero_pedido_importacao,',
'            l_num_sequencia_item,',
'            l_num_entrega',
'        from imp_invoice_item a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_entrega c on c.id = b.id_entrega',
'        join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'        join imp_pedidoimportacao_item e on e.id_pedidoimportacao = d.id and e.id = b.id_pedidoimportacao_item',
'        where a.id = p_param1;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_invoice'',                  2, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_entrega'',                  3, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_entrega_item'',             4, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''sequencia_item_invoice'',      5, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pedidoimportacao'',         6, ''TXT'', null, ''S'', ''N'', l_numero_pedido_importacao valor, ''imp_pedidoimportacao.numero_pedido_importacao'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_sequencia_item'',          7, ''TXT'', null, ''S'', ''N'', l_num_sequencia_item valor, ''imp_pedidoimportacao_item.num_sequencia_item'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_entrega'',                 8, ''TXT'', null, ''S'', ''N'', l_num_entrega valor, ''imp_entrega.num_entrega'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_item'',                     9,    '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_ncm'',                     10,    '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',           11,    '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade'',                 12, ''TXT'', null, ''N'', ''N'', l_quantidade valor, ''imp_invoice_item.quantidade'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_unitario'',              13,    '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_liquido_total'',         14,    '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''peso_bruto_unitario'',        15,    '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''peso_bruto_total'',           16,    '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                   17, ''TXT'', null, ''S'', ''N'', l_moeda valor, ''imp_invoice.id_moeda'' tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''valor_unitario'',             18, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto'',             19, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_mercadoria'',     20, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fabricante'',              21, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais_origem'',             23, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',         24, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL             ',
'               SELECT p_codigo_artefato, ''data_alteracao'',             25, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from imp_invoice_item where id = p_param1), ''DATA_SEGUNDO'') valor, null tag_campo from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.tag_campo);    ',
'    end formulario;',
'',
'end "UI_MPD_TD912";',
'/'))
);
end;
