prompt --application/deployment/install/install_ui_mpd_td916
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157426331500877597)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD916'
,p_sequence=>2380
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 25/05/2026',
unistr('-- Motivo: Altera\00E7\00E3o no filtro para selecionar despesas'),
'-- Desenvolvedor: Leonardo Ferreira',
'-- Jira: PEDITEM-177',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD916" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );   ',
'',
'end "UI_MPD_TD916";',
'/',
'create or replace package body "UI_MPD_TD916" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_invoice,',
'                    pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                    case',
'                        when b.num_processoimportacao is not null then',
'                            b.num_processoimportacao',
'                        else',
'                            pkg_componentes.html_cor_texto(pkg_ui.retorna_label_tela(''''sem_processo''''))',
'                    end id_processoimportacao',
'                from imp_invoice a',
'                left join imp_processoimportacao b on b.id = a.id_processoimportacao            ',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'        l_moeda varchar2(4000);',
'    begin        ',
'        select b.codigo_moeda||'' - ''||b.simbolo_iso into l_moeda from imp_invoice a join ng_moeda b on b.id = a.id_moeda where a.id = p_param1;',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from imp_invoice where id = p'
||'_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_invoice'',                   2, ''HID'', null, ''S'', ''S'', p_param1 valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despesa'',                   3, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda'',                     5, ''TXT'', null, ''S'', ''N'', l_moeda valor, ''imp_invoice.id_moeda'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor'',                        7, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_incluso_valor_mercadoria'', 8, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_despesa'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                )',
'                and a.ind_origem_despesa = 2',
'                and a.ind_tipo_despesa in (9,10,16)',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is       ',
'        l_id number; ',
'    begin        ',
'        bo_imp_invoice_despesa.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_invoice => apex_application.g_f02(1),',
'            p_id_despesa => apex_application.g_f03(1),            ',
'            p_valor => pkg_util.retorna_number(apex_application.g_f07(1)),',
'            p_ind_incluso_valor_mercadoria => apex_application.g_f08(1),                        ',
'            p_observacao => null,',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages        ',
'        );',
'    end;',
'',
'end "UI_MPD_TD916";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td922
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157426447144870657)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD922'
,p_sequence=>2390
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD922',
'-- Data: 29/04/2026',
unistr('-- Motivo: Ajuste valor padr\00E3o status da invoice'),
'-- Jira:',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD922" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD922";',
'/',
'',
'create or replace package body "UI_MPD_TD922" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'        l_status varchar2(50);',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql =>''',
'                select ',
'                    num_invoice,',
'                    pkg_data.fmtd(data_invoice, ''''DATA'''') data_invoice,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_exportador) id_exportador,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_importador) id_importador',
'                from imp_invoice a',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_id_entidade number;',
'        l_url clob;',
'        l_html clob;',
'        l_ind_divergencia varchar2(1);',
'        l_divergencias varchar2(32000);',
'        l_divergencias_grid varchar2(32000);',
'        l_valor_invoice_grid clob;',
'        l_valor_total_condicao_venda number;',
'        l_valor_invoice_informado number;',
'        l_tipo_interacao_grid varchar2(3);',
'        l_tipo_interacao_valores varchar2(3);',
'        l_label_anexar_arquivo varchar2(4000) := pkg_ui.retorna_label_botao(''anexar_arquivo'');',
'        l_lov_ind_status varchar2(4000)  := ''D_IMP_INVOICE.IND_STATUS_CONCLUSAO'';',
'        l_ind_status_valor varchar2(4000) := ''2'';',
'    begin',
'        select id into l_id_entidade from srv_entidade where nome_entidade = ''imp_invoice'';',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9011, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9011_CODIGO_ARTEFATO,P9011_PARAMETRO,P9011_PARAMETRO2'', ',
'            p_values => ''TD779,TD779,''||p_param1||'',''||l_id_entidade,',
'            p_triggering_element => ''apex.jQuery("#NEW")'',',
'            p_clear_cache => 9011',
'        );',
'        ',
'        l_html := ''<div id="NEW" style="display: flex; align-items: center; justify-content: center;"><a id="NEW" href="''||l_url||''"><button id="NEW" class="t-Button t-Button--icon js-ignoreChange t-Button--success t-Button--iconLeft lto5893482872689'
||'6216_0 t-Button--hot" style="margin-top:0px;" type="button"><span class="t-Icon t-Icon--left fa fa-plus-circle" aria-hidden="true"></span><span class="t-Button-label">''||l_label_anexar_arquivo||''</span><span class="t-Icon t-Icon--right fa fa-plus-cir'
||'cle" aria-hidden="true"></span></button></a></div>'';        ',
'        ',
'        select ind_divergencia into l_ind_divergencia from imp_invoice where id = p_param1;',
'',
'        select listagg(pkg_util.dominio_retorna_tag(''imp_invoice_divergencia'',''ind_divergencia'',ind_divergencia),chr(10)) within group (order by ind_divergencia) into l_divergencias from imp_invoice_divergencia where id_invoice = p_param1;',
'',
'        l_divergencias_grid := q''[',
'            select',
'                pkg_util.dominio_retorna_tag(''imp_invoice_divergencia'',''ind_divergencia'',a.ind_divergencia) imp_invoice_divergencia$ind_divergencia,                ',
'                pkg_componentes.html_botao_opcao_com_icone(a.id,''TD934'') opcao',
'            from imp_invoice_divergencia a            ',
'            where a.id_invoice = #PARAM1#',
'            order by ind_divergencia',
'        ]'';',
'        l_divergencias_grid := replace(l_divergencias_grid, ''#PARAM1#'', p_param1);',
'',
'        l_valor_invoice_grid := q''[',
'            select',
'                pkg_componentes.html_cor_texto(to_char(valor_total_condicao_venda, ''FM999G990D00'')) imp_invoice$valor_total_condicao_venda,',
'                pkg_componentes.html_cor_texto(to_char(valor_invoice_informado, ''FM999G990D00'')) imp_invoice$valor_invoice_informado',
'            from imp_invoice a',
'            where a.id = #PARAM1#            ',
'        ]'';',
'        l_valor_invoice_grid := replace(l_valor_invoice_grid, ''#PARAM1#'', p_param1);',
'',
'        select valor_total_condicao_venda, valor_invoice_informado into l_valor_total_condicao_venda, l_valor_invoice_informado from imp_invoice where id = p_param1;',
'',
'        select ',
'            case ind_divergencia',
'                when ''S'' then ''GRI''',
'                when ''N'' then ''HID''',
'            end,',
'            case ',
'                when valor_total_condicao_venda = valor_invoice_informado then',
'                    ''HID''',
'                else',
'                    ''GRI''',
'            end',
'        into',
'            l_tipo_interacao_grid,',
'            l_tipo_interacao_valores',
'        from imp_invoice',
'        where id = p_param1;',
'',
'        if apex_util.get_session_state(''P9012_PARAMETRO2'') = 0 then',
'            l_lov_ind_status   := ''D_IMP_INVOICE.IND_STATUS_APROVADO'';',
'            l_ind_status_valor := ''3'';',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''ind_divergencia'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, l_ind_divergencia valor, null html, null tag_camp'
||'o FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''divergencia'',  2, l_tipo_interacao_grid, null, ''S'', ''N'', l_divergencias_grid valor, null html, null tag_campo FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''divergencias'',  2, ''TEX'', null, ''S'', ''N'', l_divergencias valor, null html, null tag_campo FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''valor_total_condicao_venda'',  3, l_tipo_interacao_valores, null, ''S'', ''S'', to_char(l_valor_total_condicao_venda) valor, null html, null tag_campo FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''valor_invoice_informado'',     4, l_tipo_interacao_valores, null, ''S'', ''S'', to_char(l_valor_invoice_informado) valor, null html, null tag_campo FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''grid_valores'', 3, l_tipo_interacao_valores, null, ''S'', ''N'', to_char(l_valor_invoice_grid) valor, null html, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_status'',   5, '''', l_lov_ind_status, ''N'', ''S'', l_ind_status_valor valor, null html, null tag_campo FROM dual UNION ALL                              ',
'               SELECT p_codigo_artefato, ''observacao'',   6, ''TEX'', null, ''N'', ''N'', null valor, null html, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, '''',             7, ''HTM'', null, ''S'', ''N'', null valor, l_html html, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_imp_invoice.conclui_invoice(',
'            p_ind_status => apex_application.g_f05(1),',
'            p_observacao => apex_application.g_f06(1),',
'            p_id => apex_util.get_session_state(''P9012_PARAMETRO''),            ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        null;        ',
'    end post_save;',
'',
'end "UI_MPD_TD922";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td925
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157426634730866343)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD925'
,p_sequence=>2400
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD925" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'end "UI_MPD_TD925";',
'/',
'create or replace package body "UI_MPD_TD925" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    b.nome_fantasia id_tenant, ',
'                    a.numero_pedido_importacao ',
'                from imp_pedidoimportacao a                  ',
'                join mpd_tenant b on b.id = a.id_tenant',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                                  ',
'        l_id_usuario number;',
'        l_data_operacao timestamp;',
'        l_url varchar2(4000);  ',
'        l_id_entidade number;',
'        l_id_coluna number; ',
'        l_existe_log number;',
'        l_forma_interacao_id_usuario_alterou varchar2(3) := ''HID'';',
'        l_forma_interacao_data_alteracao varchar2(3) := ''HID'';',
'    begin',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''motivo_desconto'';    ',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||p_param1||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'        ',
'        select count(1) into l_existe_log',
'        from srv_auditoria_log a',
'        join imp_pedidoimportacao b on b.id = a.id_registro',
'        where b.id = p_param1',
'        and json_exists(dados_novos, ''$[*]?(@.motivo_desconto!= null)'');',
'        ',
'        if l_existe_log > 0 then',
'            select',
'                a.id_usuario,',
'                a.data_operacao',
'            into',
'                l_id_usuario,',
'                l_data_operacao',
'            from srv_auditoria_log a',
'            join imp_pedidoimportacao b on b.id = a.id_registro',
'            where b.id = p_param1',
'            and json_exists(dados_novos, ''$[*]?(@.motivo_desconto!= null)'')',
'            order by data_operacao desc',
'            fetch first 1 row only;',
'',
'            l_forma_interacao_id_usuario_alterou := ''SEL'';',
'            l_forma_interacao_data_alteracao := ''TXT'';',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''valor_desconto'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''motivo_desconto'',    2, '''', l_url, ''S'', ''S'', to_char((select pkg_traducao.get_traducao(motivo_desconto) from imp_pedidoimportacao where id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'', 3, l_forma_interacao_id_usuario_alterou, ''R_MPD_USUARIO.NOME'', ''S'', ''S'', to_char(l_id_usuario) valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',     4, l_forma_interacao_data_alteracao, null, ''S'', ''S'', to_char(l_data_operacao, ''dd/mm/yyyy hh24:mi:ss'') valor, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'end "UI_MPD_TD925";',
'/'))
);
end;
/
