prompt --application/deployment/install/install_ui_mpd_td944
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157427893241825254)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD944'
,p_sequence=>2430
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD944" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD944";',
'/',
'create or replace package body "UI_MPD_TD944" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'    begin         ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null obrigatorio, null id_arte'
||'fato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo'',          2, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_uf_destino'',     3, ''POP'', ''R_NG_ESTADO.NOME_ESTADO'', ''N'',''N'', to_char((select id_uf_destino from ng_ibu where id = p_param1)) valor, ''ng_ibu.id_uf_destino'' tag_campo, ''S'' obrigatorio, 6046 id_artefato_ver'
||'sionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_ibu'',      5, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'', 6, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',    7, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, obrigatorio, id_artefato_versionado_zoom)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.obrigatorio, new_data'
||'.id_artefato_versionado_zoom);',
'    end formulario;',
'',
'    function where_dinamico(p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_uf_destino'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.id_pais = (',
'                    select id_registro from mpd_configuracao_ng where codigo_configuracao = 1 and id_tenant = (',
'                        select c002 from apex_collections where collection_name = ''TD944_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_tenant'')',
'                   )',
'                )',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_ng_ibu.altera_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_ind_tipo => apex_application.g_f02(1),',
'            p_id_uf_destino => apex_application.g_f03(1),',
'            p_aliquota_ibu => pkg_util.retorna_number(apex_application.g_f05(1)),',
'            p_data_fim_vigencia => apex_application.g_f06(1),',
'            p_data_alteracao => to_timestamp(apex_application.g_f07(1), ''dd-mm-rr hh:mi:ss:ff am''),',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages            ',
'        );',
'    end;',
'end "UI_MPD_TD944";',
'/'))
);
end;
/
