prompt --application/deployment/install/install_ui_mpd_td946
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157428216757802614)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD946'
,p_sequence=>2450
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD946" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'',
'end "UI_MPD_TD946";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD946" as    ',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id ,                                                            ',
'                a.id_tenant,',
'                a.ind_tipo,',
'                nvl(pkg_traducao.get_traducao(c.nome_cidade), pkg_util.dominio_retorna_tag(''ng_ibm'', ''ind_tipo'', a.ind_tipo)) titulo,',
'                b.nome_fantasia subtitulo, ',
'                pkg_util.dominio_retorna_tag(''ng_ibm'', ''ind_tipo'', a.ind_tipo) distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_ibm.aliquota_ibm'', to_char(a.aliquota_ibm, ''FM999G990D00''), 2 ) atributo1,',
'                --pkg_componentes.html_card_colunas(''ng_ibm.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 10 ) atributo2,',
'                case',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_ibm.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 10)',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_ibm.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 10 )',
'                end atributo2,',
'                --order',
'                a.aliquota_ibm order1,',
'                a.data_fim_vigencia order2,',
'',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null filtro2,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2, ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD946'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD946'') as opcao ',
'            from ng_ibm a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_cidade c on c.id = a.id_cidade_destino',
'            order by #ORDER#',
'        ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));            ',
'        return l_sql; ',
'    end sql_card;',
'',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select ',
'                a.id,                                                            ',
'                b.nome_fantasia campo1,',
'                pkg_util.dominio_retorna_tag(''ng_ibm'', ''ind_tipo'', a.ind_tipo) campo2,',
'                pkg_traducao.get_traducao(c.nome_cidade) campo3,',
'                to_char(a.aliquota_ibm, ''FM999G990D00'') campo4,  ',
'                --pkg_data.fmtd(a.data_fim_vigencia, ''DATA'') campo5,',
'                case when ',
'                    to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA''))',
'                    else',
'                        pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')',
'                end campo5,',
'                a.data_fim_vigencia campo6,',
'                a.aliquota_ibm campo7,                                      ',
'                null campo8,                                      ',
'                null campo9,                                      ',
'                null campo10,  ',
'                --FILTROS',
'                a.id_tenant filtro1,                                ',
'                null filtro2,                                ',
'                null filtro3,                                ',
'                null filtro4,',
'                null filtro5,                                ',
'                --FILTROS MULTI',
'                null filtro_mult1,                                ',
'                null filtro_mult2,                                ',
'                null filtro_mult3, ',
'                null filtro_mult4,                                ',
'                null filtro_mult5,                              ',
'                null opcao',
'            from ng_ibm a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_cidade c on c.id = a.id_cidade_destino          ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select  ',
'                id,              ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD946'') as opcao ',
'            FROM TABLE(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'', ''ng_ibm'')) a ',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then             ',
'            return q''~select nome_fantasia d, id r from mpd_tenant order by 1~''; ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro; ',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibm.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibm.ind_tipo'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibm.id_cidade_destino'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibm.aliquota_ibm'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_ibm.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;   ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo7,campo6'';',
'        else',
'            campos := ''subtitulo,distintivo,titulo,order1,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo6,campo1,campo2,campo3'';',
'        else',
'            l_campos := ''order2,subtitulo,distintivo,titulo'';',
'        end if;',
'        l_direcoes := ''nulls first,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD946";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td947
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157428472776798625)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD947'
,p_sequence=>2460
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD947" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function where_dinamico(p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD947";',
'/',
'create or replace package body "UI_MPD_TD947" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'    begin         ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null obrigatorio, null id_arte'
||'fato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo'',          2, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cidade_destino'', 3, ''POP'', ''R_NG_CIDADE.NOME_CIDADE'', ''N'',''N'', null valor, ''ng_ibm.id_cidade_destino'' tag_campo, ''S'' obrigatorio, 5621 id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_ibm'',      5, '''', null, ''N'',''S'', null valor, null tag_campo, null obrigatorio, null id_artefato_versionado_zoom FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, obrigatorio, id_artefato_versionado_zoom)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.obrigatorio, new_data'
||'.id_artefato_versionado_zoom);',
'    end formulario;',
'',
'    function where_dinamico(p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_cidade_destino'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')) ',
'                and a.id_pais = (',
'                    select id_registro from mpd_configuracao_ng where codigo_configuracao = 1 and id_tenant = (',
'                        select c002 from apex_collections where collection_name = ''TD947_''||apex_custom_auth.get_session_id and upper(c001) = upper(''id_tenant'')',
'                   )',
'                )',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_ng_ibm.inclui_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_ind_tipo => apex_application.g_f02(1),',
'            p_id_cidade_destino => apex_application.g_f03(1),',
'            p_aliquota_ibm => pkg_util.retorna_number(apex_application.g_f05(1)),',
'            p_data_fim_vigencia => null,',
'            p_id => l_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages            ',
'        );',
'    end;',
'end "UI_MPD_TD947";',
'/'))
);
end;
/
