||'nt_origem(p_param1,p_param2)) valor, null dependencia ,null atribuir_valor,null executa_js,null id_artefato_versionado_zoom from dual UNION ALL                     ',
'              SELECT p_codigo_artefato, ''ind_grupo_funcionalidade'',       4, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL ',
