||'ir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL',
'              SELECT p_codigo_artefato, ''IND_TIPO_DADO'',                 10, '''', null, ''N'', ''S'', v_titulo valor , null dependencia , l_atribuir_valor_ind_valor atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL  ',
'              SELECT p_codigo_artefato, ''QUANTIDADE_DECIMAL'',            12, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL   ',
'              SELECT p_codigo_artefato, ''IND_VALOR'',                     7, ''HID'',null, ''N'', ''N'',null , v_json_dependecia_ind_valor dependencia, null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL ',
'              SELECT p_codigo_artefato, ''ind_situacao'',                  22, ''HID'', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL     ',
'              SELECT p_codigo_artefato, ''id_entidade'',                   38, ''POP'', ''R_SRV_CONFIGURACAO.ID_ENTIDADE'', ''N'', ''S'', null valor , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL',
'              SELECT p_codigo_artefato, ''ID_ENTIDADE'',                   40, '''', null, ''N'', ''S'', null , null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom from dual UNION ALL',
'              SELECT p_codigo_artefato, ''id_usuario_alterou'',            46, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor,null dependencia , null atribuir_valor, null executa_js, null id_artefato_versionado_zoom  FROM dual UNION ALL             ',
'              SELECT p_codigo_artefato, ''data_alteracao'',                48, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from srv_configuracao_ng where id = p_param1), ''DATA_SEGUNDO'') , null dependencia , null atribuir_valor, null exec'
||'uta_js, null id_artefato_versionado_zoom from dual ',
