'               SELECT p_codigo_artefato, ''id_usuario_alterou'',      46, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL             ',
'               SELECT p_codigo_artefato, ''data_alteracao'',          48, ''TXT'', null, ''N'', ''S'', pkg_data.fmtd((select data_alteracao from srv_configuracao_ng_dominio where id = p_param1), ''DATA'')  from dual ',
