prompt --application/deployment/install/install_ui_mpd_td976
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157429267795754966)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD976'
,p_sequence=>2530
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD976" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'    ',
'end "UI_MPD_TD976";',
'/',
'',
'create or replace package body "UI_MPD_TD976" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_pagar varchar2(400);',
'        l_receber varchar2(400);',
'    begin',
'        select pkg_ui.retorna_label_tela(''pagar'') into l_pagar from dual;',
'        select pkg_ui.retorna_label_tela(''receber'') into l_receber from dual;',
'',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.ind_status_pagamento,',
'                a.data_vencimento,',
'                pkg_traducao.get_traducao(d.nome_leitura) titulo,',
'                b.nome_fantasia subtitulo,',
'                ~'' || '''''''' || l_pagar || '''''' distintivo,'' || q''~',
'                null class_distintivo,',
'                --ATRIBUTOS',
'                null atributo1,',
'                pkg_componentes.html_card_colunas(''fin_titulopagamento.ind_status_pagamento'', pkg_util.dominio_retorna_tag(''fin_titulopagamento'',''ind_status_pagamento'',ind_status_pagamento), 2) atributo2,',
'                pkg_componentes.html_card_colunas(''fin_titulopagamento.id_pessoa'', c.nome_fantasia, 2) atributo3,',
'                pkg_componentes.html_card_colunas(''fin_titulopagamento.data_vencimento'', pkg_data.fmtd(a.data_vencimento, ''DATA''), 2) atributo4,',
'                pkg_componentes.html_card_colunas(''fin_titulopagamento.id_moeda'', m.codigo_moeda || '' - '' || m.simbolo_iso, 2) atributo5,',
'                pkg_componentes.html_card_colunas(''fin_titulopagamento.valor_titulo'', to_char(a.valor_titulo,''FM999G999G990D00''), 2) atributo6,',
'                --pkg_componentes.html_card_colunas(''fin_titulopagamento.saldo_pagar'', to_char(a.saldo_pagar,''FM999G999G990D00''), 2) atributo7,',
'                --FILTROS',
'                a.id_tenant filtro1,                ',
'                ''p'' filtro2,',
'                null filtro3,',
'                null filtro4,',
'                null filtro5,',
'                null filtro6,',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD976'',a.id) url_mais_detalhes,                ',
'                pkg_componentes.html_botao_opcao(a.id, ''TD976'', p_param1 => ''1'') as opcao       -- ''1'' -> registro de fin_titulopagamento               ',
'            from fin_titulopagamento a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_fornecedor  ',
'            join srv_entidade d on d.id = a.id_entidade      ',
'            join ng_moeda m on m.id = a.id_moeda ',
'',
'            union all',
'',
'            select distinct',
'                a.id,',
'                a.ind_status_recebimento,',
'                a.data_vencimento,',
'                pkg_traducao.get_traducao(d.nome_leitura) titulo,',
'                b.nome_fantasia subtitulo,',
'                ~'' || '''''''' || l_receber || '''''' distintivo,'' || q''~',
'                null class_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''fin_titulorecebimento.num_documento'', a.num_documento, 2) atributo1,                ',
'                pkg_componentes.html_card_colunas(''fin_titulorecebimento.ind_status_recebimento'', pkg_util.dominio_retorna_tag(''fin_titulorecebimento'',''ind_status_recebimento'',ind_status_recebimento), 2) atributo2,',
'                pkg_componentes.html_card_colunas(''fin_titulorecebimento.id_fornecedor'', c.nome_fantasia, 2) atributo3,',
'                pkg_componentes.html_card_colunas(''fin_titulorecebimento.data_vencimento'', pkg_data.fmtd(a.data_vencimento, ''DATA''), 2) atributo4,',
'                pkg_componentes.html_card_colunas(''fin_titulorecebimento.id_moeda'', m.codigo_moeda || '' - '' || m.simbolo_iso, 2) atributo5,',
'                pkg_componentes.html_card_colunas(''fin_titulorecebimento.valor_titulo'', to_char(a.valor_titulo,''FM999G999G990D00''), 2) atributo6,',
'                --pkg_componentes.html_card_colunas(''fin_titulorecebimento.saldo_pagar'', to_char(a.saldo_pagar,''FM999G999G990D00''), 2) atributo7,',
'                --FILTROS',
'                a.id_tenant filtro1,                ',
'                ''r'' filtro2,',
'                null filtro3,',
'                null filtro4,',
'                null filtro5,',
'                null filtro6,',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD976'',a.id) url_mais_detalhes,                ',
'                pkg_componentes.html_botao_opcao(a.id, ''TD976'', p_param1 => ''2'') as opcao       -- ''2'' -> registro de fin_titulorecebimento        ',
'            from fin_titulorecebimento a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_fornecedor  ',
'            join srv_entidade d on d.id = a.id_entidade    ',
'            join ng_moeda m on m.id = a.id_moeda   ',
'            ',
'            order by 2, 3 nulls first',
'            ~'';            ',
'            --l_sql := replace(l_sql, ''#URL#'', nvl(l_url, ''null''));',
'            return l_sql;                    ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_pagar varchar2(400);',
'        l_receber varchar2(400);',
'    begin',
'        select pkg_ui.retorna_label_tela(''pagar'') into l_pagar from dual;',
'        select pkg_ui.retorna_label_tela(''receber'') into l_receber from dual;',
'',
'        l_sql := q''~',
'        select distinct',
'            a.id id,  ',
'            b.nome_fantasia campo1,',
'            ~'' || '''''''' || l_pagar || '''''' campo2,'' || q''~',
'            pkg_traducao.get_traducao(d.nome_leitura) campo3,',
'            null campo4,',
'            pkg_util.dominio_retorna_tag(''fin_titulopagamento'',''ind_status_pagamento'',ind_status_pagamento) campo5,',
'            c.nome_fantasia campo6,',
'            pkg_data.fmtd(a.data_vencimento, ''DATA'') campo7,',
'            m.codigo_moeda||'' - ''||m.simbolo_iso campo8,',
'            to_char(a.valor_titulo,''FM999G999G990D00'') campo9,            ',
'            to_char(a.saldo_pagar,''FM999G999G990D00'') campo10,',
'            --FILTROS',
'            a.id_tenant filtro1,                ',
'            ''p'' filtro2,',
'            a.ind_status_pagamento filtro3,',
'            null filtro4,            ',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,',
'            null opcao',
'        from fin_titulopagamento a',
'        join mpd_tenant b on b.id = a.id_tenant',
'        join ng_pessoa_juridica c on c.id_pessoa = a.id_fornecedor  ',
'        join srv_entidade d on d.id = a.id_entidade ',
'        join ng_moeda m on m.id = a.id_moeda   ',
'',
'        union all',
'',
'        select distinct',
'            r.id id,  ',
'            b.nome_fantasia campo1,',
'            ~'' || '''''''' || l_receber || '''''' campo2,'' || q''~',
'            pkg_traducao.get_traducao(d.nome_leitura) campo3,',
'            r.num_documento campo4,',
'            pkg_util.dominio_retorna_tag(''fin_titulorecebimento'',''ind_status_recebimento'',r.ind_status_recebimento) campo5,',
'            c.nome_fantasia campo6,',
'            pkg_data.fmtd(r.data_vencimento, ''DATA'') campo7,',
'            m.codigo_moeda||'' - ''||m.simbolo_iso campo8,',
'            to_char(r.valor_titulo,''FM999G999G990D00'') campo9,',
'            to_char(r.saldo_pagar,''FM999G999G990D00'') campo10,',
'            r.id_tenant filtro1,                ',
'            ''r'' filtro2,',
'            r.ind_status_recebimento filtro3,',
'            null filtro4,            ',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,',
'            null opcao',
'        from fin_titulorecebimento r',
'        join mpd_tenant b on b.id = r.id_tenant',
'        join ng_pessoa_juridica c on c.id_pessoa = r.id_fornecedor  ',
'        join srv_entidade d on d.id = r.id_entidade ',
'        join ng_moeda m on m.id = r.id_moeda',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                --                                                          a.filtro2 = ''p'' -> registro de fin_titulopagamento     a.filtro2 = ''r'' -> registro de fin_titulo_recebimento',
'                pkg_componentes.html_botao_opcao(a.id, ''TD976'', p_param1 => case when a.filtro2 = ''p'' then ''1'' when a.filtro2 = ''r'' then ''2'' end) as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''fin_titulopagamento'')) a',
'            order by filtro3, campo7 nulls first   ',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then',
'            return q''~select pkg_ui.retorna_label_tela(''pagar'') d, ''p'' r from dual union all select pkg_ui.retorna_label_tela(''receber'') d, ''r'' r from dual~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.id_tenant'') into l_campo from dual;',
'        elsif campo in (''2'',''F2'') then                     ',
'            select pkg_ui.retorna_label_tela(''tipo_titulo'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.id_entidade'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulorecebimento.num_documento'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.ind_status_pagamento'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.id_pessoa'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.data_vencimento'') into l_campo from dual;        ',
'        elsif campo = ''8'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.id_moeda'') into l_campo from dual;  ',
'        elsif campo = ''9'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.valor_titulo'') into l_campo from dual; ',
'        elsif campo = ''10'' then                     ',
'            select pkg_ui.retorna_label_coluna(''fin_titulopagamento.saldo_pagar'') into l_campo from dual;     ',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''ind_status_pagamento,data_vencimento'';',
'        else',
'            campos := ''campo5,campo7'';',
'        end if;',
'        labels := label_coluna(''5'')||label_coluna(''7'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD976";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td985
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157429319509750797)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD985'
,p_sequence=>2540
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD985" as',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'--     function sql_atribuir_valor(p_param1 in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'end "UI_MPD_TD985";',
'/',
'create or replace package body "UI_MPD_TD985" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_consulta clob;',
'    begin',
'        if p_param2 is null and apex_util.get_session_state(''APP_PAGE_ID'') = ''9010'' then',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_contato wh'
||'ere id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_pessoa_contato'',    2, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa_fisica from ng_pessoa_contato where id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_pessoa_referencia'', 3, ''HID'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_contato where id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_forma_contato'',    4, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''dado_contato'',         5, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_whatsapp'',         6, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''observacao'',           7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL  ',
'                   SELECT p_codigo_artefato, ''data_fim_vigencia'',    8, ''HID'', null, ''N'', ''S'', pkg_data.fmtd((select data_fim_vigencia from ng_pessoa_contato where id = p_param1), ''DATA'') valor FROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'        else',
'            l_consulta := ''select c.nome_abreviado d, c.id_pessoa r from ng_pessoa_contato a join ng_pessoa_juridica b on b.id_pessoa = a.id_pessoa join ng_pessoa_fisica c on c.id_pessoa = a.id_pessoa_fisica where b.id = ''||p_param1||'' order by 1'';',
'            ',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from ng_pessoa_juridica w'
||'here id = p_param1)) valor FROM dual UNION ALL            ',
'                   SELECT p_codigo_artefato, ''id_pessoa_contato'',    3, ''POP1'', to_char(l_consulta), ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_pessoa_referencia'', 5, ''TXT'', null, ''N'', ''S'', to_char((select id_pessoa from ng_pessoa_juridica where id = p_param1)) valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_forma_contato'',    7, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''dado_contato'',         9, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_whatsapp'',        11, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''observacao'',          13, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''data_fim_vigencia'',   15, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'        end if;            ',
'    end formulario;',
'',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_pessoa_contato'') then',
'            return ''',
'                where b.id in (TO_NUMBER(apex_util.get_session_state(''''P9010_PARAMETRO'''')))',
'            '';',
'        else',
'            return '''';',
'        end if;',
'    end;',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'        l_ind_whataspp varchar2(1);        ',
'    begin        ',
'        if lower(apex_application.g_f07(1)) = ''2'' then',
'            l_ind_whataspp := apex_application.g_f11(1);',
'        else',
'            l_ind_whataspp := null;',
'        end if;',
'        bo_ng_pessoa_contato_dado.inclui_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_pessoa_contato => apex_application.g_f02(1),',
'            p_id_pessoa_referencia => apex_application.g_f03(1),',
'            p_ind_forma_contato => apex_application.g_f04(1),',
'            p_dado_contato => apex_application.g_f05(1),            ',
'            p_ind_whatsapp => l_ind_whataspp,',
'            p_observacao => apex_application.g_f07(1),',
'            p_data_fim_vigencia => apex_application.g_f08(1),',
'            p_data_integracao => null,',
'            p_motivo_rejeicao => null,',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end post;',
'         ',
'end "UI_MPD_TD985";',
'/'))
);
end;
