begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157429692852739971)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD993'
,p_sequence=>2570
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 27/04/2026',
'-- Motivo: Ajuste para colocar a data no formato com fuso horario',
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD993" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'end "UI_MPD_TD993";',
'/',
'create or replace package body "UI_MPD_TD993" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_dominio_ind_texto_original varchar2(10);',
'    begin         ',
'        select pkg_util.dominio_retorna_tag(''mpd_traducaotextopadrao'', ''ind_texto_original'', ind_texto_original) into l_dominio_ind_texto_original from mpd_traducaotextopadrao where id = p_param1;',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''chave_traducao'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, '''' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, '''' valor FROM dual UNION ALL            ',
'               SELECT p_codigo_artefato, ''texto_traduzido'',      8, '''', '''', ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma'',            5, '''', '''', ''S'',''S'', null valor FROM dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''ind_texto_original'',   9, ''TXT'', '''', ''S'',''S'', l_dominio_ind_texto_original valor FROM dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',   30, ''SEL'', ''R_MPD_USUARIO.NOME'', ''N'', ''S'', null valor FROM dual UNION ALL             ',
'               SELECT p_codigo_artefato, ''data_alteracao'',       32, ''TXT'', null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from MPD_TRADUCAOTEXTOPADRAO where id = p_param1), ''DATA_SEGUNDO'') valor from dual                      ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'end "UI_MPD_TD993";',
'/'))
);
end;
