prompt --application/deployment/install/install_ui_mpd_td979
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(157430485057684804)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD979'
,p_sequence=>2580
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'create or replace package "UI_MPD_TD979" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD979";',
'/',
'',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD979" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'',
'        l_html := ',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.179.l'')||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_processoimportacao'',          2, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_status'',                      3, '''', ''D_IMP_PROCESSOIMPORTACAO.IND_STATUS'', ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_embarcador'',                   5, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                   7, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_adquirente'',                   9, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',             33, ''HID'', ''R_MPD_USUARIO.NOME'', ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                 35, ''HID'', null, ''S'', ''S'', pkg_data.fmt((select data_alteracao from imp_processoimportacao where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'',
'    )',
'    is',
'        l_id number;',
'        v_imp_processo imp_processoimportacao%rowtype;',
'        v_id_declaracao number;',
'    begin ',
'        bo_imp_processoimportacao.cancelar_processo(',
'            p_id                              => p_id, ',
'            p_sucesso                         => p_sucesso,',
'            p_messages                        => p_messages',
'        );',
'',
'',
'    end;',
'',
'end "UI_MPD_TD979";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td777
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(160181338992312384)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD777'
,p_sequence=>2590
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD777',
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'create or replace package "UI_MPD_TD777" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD777";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD777" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'        l_entidade varchar2(4000);',
'    begin',
'        select descricao_entidade into l_entidade from srv_entidade where id = p_param2;',
'        ',
'        if p_param2 = ''3829'' then                   -- 3829 = id_entidade(srv_entidade) de imp_pedidoimportacao',
'        l_html := pkg_util.ObterValoresDasColunas(',
'            p_consulta_sql => ''',
'                select distinct',
'                    c.nome_fantasia as id_tenant,',
'                    '''''' || l_entidade || '''''' as id_entidade,',
'                    a.numero_pedido_importacao',
'                from imp_pedidoimportacao a',
'                join mpd_tenant c on c.id = a.id_tenant',
'                where a.id = '' || p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''ng_anexo'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe => ''st-back-transparente''',
'        );',
'        elsif p_param2 = ''4085'' then                -- 4085 = id_entidade(srv_entidade) de imp_entrega',
'        l_html := pkg_util.ObterValoresDasColunas(',
'            p_consulta_sql => ''',
'                select distinct',
'                    c.nome_fantasia as id_tenant,',
'                    '''''' || l_entidade || '''''' as id_entidade,',
'                    b.numero_pedido_importacao,',
'                    a.num_entrega',
'                from imp_entrega a',
'                join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'                join mpd_tenant c on c.id = a.id_tenant',
'                where a.id = '' || p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''ng_anexo'',''imp_pedidoimportacao'',''imp_entrega''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe => ''st-back-transparente''',
'        );',
'        elsif p_param2 = ''4324'' then                   -- 4324 = id_entidade(srv_entidade) de imp_processoimportacao',
'        l_html := pkg_util.ObterValoresDasColunas(',
'            p_consulta_sql => ''',
'                select distinct',
'                    c.nome_fantasia as id_tenant,',
'                    '''''' || l_entidade || '''''' as id_entidade,',
'                    a.num_processoimportacao',
'                from imp_processoimportacao a',
'                join mpd_tenant c on c.id = a.id_tenant',
'                where a.id = '' || p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''ng_anexo'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe => ''st-back-transparente''',
'        );',
'        end if;',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_tenant number;',
'        l_nao_aprovado varchar2(400);',
'    begin   ',
'        if p_param2 = ''3829''then                    -- id_referencia 3829 -> imp_pedidoimportacao',
'            select id_tenant into l_tenant from imp_pedidoimportacao where id = p_param1;',
'        elsif p_param2 = ''4085'' then                -- id_referencia 4085 -> imp_entrega',
'            select id_tenant into l_tenant from imp_entrega where id = p_param1;',
'        elsif p_param2 = ''4324'' then                -- id_referencia 4324 -> imp_processoimportacao',
'            select id_tenant into l_tenant from imp_processoimportacao where id = p_param1;',
'        end if;',
'',
'        l_nao_aprovado := ''<span style="color:#e74c3c">'' || retorna_texto(''msg.84.l'') || ''</span>'';',
'',
'        l_sql := q''~',
'            select',
'                a.id,',
'                pkg_traducao.get_traducao(d.nome_documento) titulo,',
'                a.numero_documento subtitulo,',
'                case',
'                    when a.id is null then #L_NAO_APROVADO#',
'                    when a.ind_situacao = ''P'' then ''<span style="color:#e74c3c">'' || pkg_util.dominio_retorna_tag(''ng_anexo'',''ind_situacao'', a.ind_situacao) || ''</span>''',
'                    else pkg_util.dominio_retorna_tag(''ng_anexo'',''ind_situacao'', a.ind_situacao)',
'                end as distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_anexo.versao_documento'',a.versao_documento, 6) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_anexo.data_documento'', pkg_data.fmtd(a.data_documento, ''DATA''), 6) atributo2,',
'                --FILTROS',
'                a.ind_situacao filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,                  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD777'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD777'') as opcao  ',
'            FROM (',
'                SELECT a.*',
'                FROM ng_anexo a',
'                WHERE a.id_entidade   = #PARAM2#',
'                  AND a.id_referencia = #PARAM1#',
'                  AND a.id_tenant     = #L_ID_TENANT#',
'                  AND a.versao_documento = (SELECT MAX(c.versao_documento) FROM ng_anexo c WHERE c.id_documento = a.id_documento AND c.id_entidade = a.id_entidade AND c.id_referencia = a.id_referencia AND c.id_tenant = a.id_tenant AND c.numero_docume'
||'nto = a.numero_documento AND c.ind_situacao IN (''A'', ''P'', ''R''))',
'            ) a',
'            LEFT JOIN ng_documento d ON a.id_documento = d.id AND d.id_tenant = #L_ID_TENANT# WHERE a.id IS NOT NULL OR (d.ind_obrigatorio = ''S'' AND d.id_tenant = #L_ID_TENANT# AND d.id_entidade = #PARAM2#)',
'            order by #ORDER#',
'        ~'';     ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        l_sql := replace(l_sql, ''#PARAM2#'', p_param2);',
'        l_sql := replace(l_sql, ''#L_ID_TENANT#'', l_tenant);',
'        l_sql := replace(l_sql, ''#L_NAO_APROVADO#'', '''''''' || l_nao_aprovado || '''''''');',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'        return l_sql;       ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_tenant number;',
'        l_nao_aprovado varchar2(400);',
'    begin   ',
'        if p_param2 = ''3829''then                -- id_referencia 3829 -> imp_pedidoimportacao',
'            select id_tenant into l_tenant from imp_pedidoimportacao where id = p_param1;',
'        elsif p_param2 = ''4085'' then            -- id_referencia 3829 -> imp_entrega',
'            select id_tenant into l_tenant from imp_entrega where id = p_param1;',
'        elsif p_param2 = ''4324'' then            -- id_referencia 3829 -> imp_processoimportacao',
'            select id_tenant into l_tenant from imp_processoimportacao where id = p_param1;',
'        end if;',
'',
'        l_nao_aprovado := ''<span style="color:#e74c3c">'' || retorna_texto(''msg.84.l'') || ''</span>'';',
'',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            pkg_traducao.get_traducao(d.nome_documento) campo1,',
'            a.numero_documento campo2,',
'            a.versao_documento campo3,',
'            a.data_documento campo4,            ',
'            case',
'                when a.id is null then #L_NAO_APROVADO#',
'                when a.ind_situacao = ''P'' then ''<span style="color:#e74c3c">'' || pkg_util.dominio_retorna_tag(''ng_anexo'',''ind_situacao'', a.ind_situacao) || ''</span>''',
'                else pkg_util.dominio_retorna_tag(''ng_anexo'',''ind_situacao'', a.ind_situacao)',
'            end as campo5,  ',
'            null campo6,                ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            a.ind_situacao filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        FROM (',
'            SELECT a.*',
'            FROM ng_anexo a',
'            WHERE a.id_entidade   = #PARAM2#',
'              AND a.id_referencia = #PARAM1#',
'              AND a.id_tenant     = #L_ID_TENANT#',
'              AND a.versao_documento = (SELECT MAX(c.versao_documento) FROM ng_anexo c WHERE c.id_documento = a.id_documento AND c.id_entidade = a.id_entidade AND c.id_referencia = a.id_referencia AND c.id_tenant = a.id_tenant AND c.numero_documento '
||'= a.numero_documento AND c.ind_situacao IN (''A'', ''P'', ''R''))',
'        ) a',
'        LEFT JOIN ng_documento d ON a.id_documento = d.id AND d.id_tenant = #L_ID_TENANT# WHERE a.id IS NOT NULL OR (d.ind_obrigatorio = ''S'' AND d.id_tenant = #L_ID_TENANT# AND d.id_entidade = #PARAM2#)',
'        ~'';     ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        l_sql := replace(l_sql, ''#PARAM2#'', p_param2);',
'        l_sql := replace(l_sql, ''#L_ID_TENANT#'', l_tenant);',
'        l_sql := replace(l_sql, ''#L_NAO_APROVADO#'', '''''''' || l_nao_aprovado || '''''''');',
'        return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(id,''TD777'') as opcao   ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_anexo'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select * from pkg_util.dominio_retorna_lista(''ng_anexo'',''ind_situacao'')~'';',
'        else',
'        return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_documento.nome_documento'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_anexo.numero_documento'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_anexo.versao_documento'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_anexo.data_documento'') into l_campo from dual;',
'        elsif campo in (''5'',''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_anexo.ind_situacao'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'        ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo4,campo2,campo3,filtro1'';',
'        else',
'            campos := ''titulo,atributo2,subtitulo,atributo1,filtro1'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''4'')|| '','' ||',
'        label_coluna(''2'')|| '','' ||',
'        label_coluna(''3'')|| '','' ||',
'        label_coluna(''5'')      ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''1'') || '','' ||',
'               label_coluna(''4'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo2,campo4'';',
'        else',
'            l_campos := ''titulo,atributo2'';',
'        end if; ',
'',
'        l_direcoes := ''ASC,DESC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD777";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td789
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(160181508415306437)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD789'
,p_sequence=>2600
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD789',
'-- Data: 29/04/2026',
unistr('-- Motivo: Ajuste para prefer\00EAncia de fuso hor\00E1rio'),
'-- Jira:',
'',
'-- Objeto: UI_MPD_TD789',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste de coluna id_recinto_alfandegado',
'-- Jira: PEDITEM-161',
'',
'create or replace package "UI_MPD_TD789" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'end "UI_MPD_TD789";',
'/',
'',
'create or replace package body "UI_MPD_TD789" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        pkg_ui.retorna_label_tela(''dados_gerais'')||''</h3></div>'' ||',
'        pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    b.nome_fantasia id_tenant,',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''',''''ind_status'''',a.ind_status) ind_status',
'                from imp_processoimportacao a ',
'                join mpd_tenant b on b.id = a.id_tenant',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',       2, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_embarcador'',                   3, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                   5, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                   7, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_despachante'',                  9, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''referencia_despachante'',         11, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_responsavel'',         12, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_viatransporte'',               14, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_transportador_internacional'', 16, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''conhecimento_transporte'',        18, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''navio'',                          19, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''viagem'',                         20, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_transportador_nacional'',      21, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_origem'',             23, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_embarque'',              25, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_desembarque'',           27, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_recinto_alfandegado'',         29, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_destino'',            31, '''', null, ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_usuario_alterou'',             33, ''SEL'', ''R_MPD_USUARIO.NOME'', ''S'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                 35, ''TXT'', null, ''S'', ''S'', pkg_data.fmt((select data_alteracao from imp_processoimportacao where id = p_param1), ''DATA_SEGUNDO'') valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'end "UI_MPD_TD789";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td958
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(160183567192271828)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD958'
,p_sequence=>2610
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD958',
'-- Data: 29/04/2026',
unistr('-- Motivo: Ajuste para prefer\00EAncia de fuso hor\00E1rio'),
'-- Jira:',
'',
'create or replace package "UI_MPD_TD958" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD958";',
'/',
'',
'create or replace package body "UI_MPD_TD958" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select ',
'                               c.num_processoimportacao as id_processoimportacao,',
'                               pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''',a.ind_tipo_movimento) ind_tipo_movimento,',
'                               bo_ng_pessoa.retorna_pessoa(a.id_fornecedor) id_fornecedor,',
'                               pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_status'''',a.ind_status) ind_status',
'                               from imp_processoimportacao_numerario a ',
'                               join mpd_tenant b on b.id = a.id_tenant',
'                               join imp_processoimportacao c on c.id = a.id_processoimportacao',
'                               where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.156.l'')||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'    begin ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from I'
||'MP_PROCESSOIMPORTACAO_NUMERARIO where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js from dual union all',
'               SELECT p_codigo_artefato, ''ind_tipo_movimento'',                        3, ''HID'',null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status'',                                5, ''HID'',''D_IMP_PROCESSOIMPORTACAO_NUMERARIO.IND_STATUS'', ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor'',                             7, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_bancaria'',                         9, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''referencia_fornecedor'',                      11, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_documento'',                           13, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento'',                  15, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_numerario'',                        16, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_numerario_informado'',           18, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_despesas_numerario'',                     27, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                               19, ''HID'',null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',                    21, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                           23, ''HID'',null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from IMP_PROCESSOIMPORTACAO_NUMERARIO where id = p_param1), ''DATA_SEGUNDO'') valor, null dependencia, nu'
||'ll atribuir_valor, null executa_js from dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'',
'    )',
'    is',
'        l_id number;',
'        v_imp_processo imp_processoimportacao%rowtype;',
'',
'    begin ',
'        -- select * into v_imp_processo from imp_processoimportacao where id = p_id;  ',
'',
'         bo_imp_processoimportacao_numerario.altera_numerario_gera_titulo(',
'            p_id_tenant                         => apex_application.g_f01(1),',
'            p_id_processoimportacao             => apex_application.g_f21(1),',
'            p_ind_tipo_movimento                => apex_application.g_f03(1),',
'            p_ind_status                        => 3,',
'            p_id_fornecedor                     => apex_application.g_f07(1),',
'            p_id_conta_bancaria                 => apex_application.g_f09(1),',
'            p_referencia_fornecedor               => apex_application.g_f11(1),',
'            p_data_documento                    => TO_DATE(apex_application.g_f13(1),''DD/MM/YYYY''),',
'            p_data_vencimento           => TO_DATE(apex_application.g_f15(1),''DD/MM/YYYY''),',
'            p_id_moeda_numerario                 => apex_application.g_f16(1),',
'            p_valor_numerario_informado    => apex_application.g_f18(1),',
'            p_valor_total_despesas_numerario              => apex_application.g_f27(1),',
'            p_observacao                        => apex_application.g_f19(1),',
'            p_data_alteracao                    => null,',
'            p_id                                => p_id,',
