prompt --application/deployment/install/install_ui_mpd_td959
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(160183883807267618)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD959'
,p_sequence=>2620
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD959',
'-- Data: 29/04/2026',
unistr('-- Motivo: Ajuste para prefer\00EAncia de fuso hor\00E1rio'),
'-- Jira:',
'',
'create or replace package "UI_MPD_TD959" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD959";',
'/',
'',
'create or replace package body "UI_MPD_TD959" as',
'',
'    function sql_cabecalho(',
'    p_param1 in varchar2 default null,',
'    p_param2 in varchar2 default null,',
'    p_param3 in varchar2 default null',
') return clob is',
'    l_html    clob;',
'    l_status  imp_processoimportacao_numerario.ind_status%type;',
'    l_tabela  textarray;',
'    l_select  varchar2(4000);',
'begin',
'    select ind_tipo_movimento',
'      into l_status',
'      from imp_processoimportacao_numerario',
'     where id = p_param1;',
'',
'    if l_status = 1 then',
'        l_tabela := textarray(',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario''',
'        );',
'',
'        l_select :=',
'            ''select c.num_processoimportacao as id_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''',a.ind_tipo_movimento) ind_tipo_movimento,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_fornecedor) id_fornecedor,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_status'''',a.ind_status) ind_status,',
'                    a.data_vencimento',
'               from imp_processoimportacao_numerario a',
'               join mpd_tenant b on b.id = a.id_tenant',
'               join imp_processoimportacao c on c.id = a.id_processoimportacao',
'              where a.id = '''''' || p_param1 || '''''''';',
'    else',
'        l_tabela := textarray(',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario'',',
'            ''imp_processoimportacao_numerario''',
'        );',
'',
'        l_select :=',
'            ''select c.num_processoimportacao as id_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''',a.ind_tipo_movimento) ind_tipo_movimento,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_fornecedor) id_fornecedor,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_status'''',a.ind_status) ind_status',
'               from imp_processoimportacao_numerario a',
'               join mpd_tenant b on b.id = a.id_tenant',
'               join imp_processoimportacao c on c.id = a.id_processoimportacao',
'              where a.id = '''''' || p_param1 || '''''''';',
'    end if;',
'',
'    l_html := pkg_util.ObterValoresDasColunas(',
'        p_consulta_sql => l_select,',
'        p_tabela       => l_tabela,',
'        p_formato      => ''pequeno'',',
'        p_tipo_label   => ''coluna'',',
'        p_classe       => ''st-back-transparente''',
'    ) ||',
'    ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;">'' ||',
'    ''<h3 class="a-CardView-title">'' || retorna_texto(''msg.176.l'') || case when l_status = 1 then retorna_texto(''msg.276.l'') else '''' end || ''</h3></div>'';',
'',
'    return l_html;',
'end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from I'
||'MP_PROCESSOIMPORTACAO_NUMERARIO where id = p_param1)) valor, null dependencia, null atribuir_valor, null executa_js from dual union all',
'               SELECT p_codigo_artefato, ''ind_tipo_movimento'',                        3, ''HID'',null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status'',                                5, ''HID'',''D_IMP_PROCESSOIMPORTACAO_NUMERARIO.IND_STATUS'', ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fornecedor'',                             7, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_conta_bancaria'',                         9, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''referencia_fornecedor'',                      11, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_documento'',                           13, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_vencimento'',                  15, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_numerario'',                        16, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_numerario_informado'',           17, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_despesas_numerario'',                     27, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                               19, ''HID'',null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',                    21, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_centrocusto'',                           29, ''HID'',null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                           23, ''HID'',null, ''N'', ''S'', pkg_data.fmt((select data_alteracao from IMP_PROCESSOIMPORTACAO_NUMERARIO where id = p_param1), ''DATA_SEGUNDO'') valor, null dependencia, nu'
||'ll atribuir_valor, null executa_js from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'',
'',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_processoimportacao_numerario.aprova_numerario(',
'            p_id             => p_id,',
'            p_data_alteracao => null,',
'            p_sucesso        => p_sucesso,',
'            p_messages       => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD959";',
'/'))
);
end;
