prompt --application/deployment/install/install_ui_mpd_td968
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(160208695313339923)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD968'
,p_sequence=>2640
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Objeto: UI_MPD_TD968',
'-- Data: 29/04/2026',
unistr('-- Motivo: Desenvolvimento a\00E7\00E3o cancelar t\00EDtulo'),
'-- Jira: PEDITEM-298',
'',
'create or replace package "UI_MPD_TD968" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'    ',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null',
'    );',
'',
'    function label_acao return varchar2;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    ',
'end "UI_MPD_TD968";',
'/',
'',
'create or replace package body "UI_MPD_TD968" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    b.nome_fantasia id_tenant,',
'                    c.nome_leitura id_entidade,',
'                    case ',
'                        when d.numero_parcela is not null then',
'                            to_char(d.numero_parcela)',
'                        when e.numero_parcela is not null then',
'                            to_char(e.numero_parcela)',
'                        when f.referencia_fornecedor is not null then',
'                            to_char(f.referencia_fornecedor)',
'                        when g.num_documento is not null then',
'                            to_char(g.num_documento)',
'                        else',
'                            pkg_ui.retorna_label_tela(''''nao_encontrado'''')',
'                    end id_referencia',
'                from fin_titulopagamento a',
'                join mpd_tenant b on b.id = a.id_tenant',
'                join srv_entidade c on c.id = a.id_entidade',
'                left join imp_pedidoimportacao_pagamento d on d.id = a.id_referencia',
'                left join imp_invoice_pagamento e on e.id = a.id_referencia',
'                left join imp_processoimportacao_numerario f on f.id = a.id_referencia',
'                left join imp_processoimportacao_despesa g on g.id = a.id_referencia',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''fin_titulopagamento'',''fin_titulopagamento'',''fin_titulopagamento''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null',
'    ) is',
'        l_html clob;        ',
'    begin   ',
'        l_html :=''</br><div class="a-CardView-headerBody" style=" display: flex; justify-content: flex-start; align-items: center; padding: 0.5rem; margin-bottom: 50px;"><h3 class="a-CardView-title">'' || retorna_texto(''msg.155.l'') || ''</h3></div>'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING ( SELECT p_codigo_artefato AS codigo_artefato, ''id_fornecedor'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null html, null tag_campo FROM dual UNION'
||' ALL',
'                SELECT p_codigo_artefato, ''data_vencimento'', 2,    '''', null, ''S'', ''S'', null valor, null html, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''observacao'',      3,    '''', null, ''S'', ''S'', null valor, null html, null tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''mensagem'',        4, ''HTM'', null, ''S'', ''N'', null valor, l_html html, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,html,tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);    ',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirmar_cancelamento'');',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'    begin',
'        bo_fin_titulopagamento.altera_ind_status_pagamento(',
'            p_ind_status_pagamento => 3,',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end post;',
'',
'end "UI_MPD_TD968";',
'/'))
);
end;
