'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'        -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from ng_despesa where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(ind_origem_despesa)) = lower(trim(v_new.ind_origem_despesa)) and lower(trim(descricao_despesa)) = lower'
||'(trim(v_new.descricao_despesa)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from ng_despesa where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(ind_origem_despesa)) = lower(trim(v_new.ind_origem_despesa)) and lower(trim(descricao_despesa)) = lower'
||'(trim(v_new.descricao_despesa)); ',
'        end if; ',
