unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'    procedure hook_valida_ind_tipo_despesa(p_ind_tipo_despesa in ng_despesa.ind_tipo_despesa%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if v_new.ind_tipo_despesa not in (0,16) then',
'            if v_new.id is not null then',
'                select count(1) into l_verifica_valor_unico from ng_despesa where id_tenant = v_new.id_tenant and ind_tipo_despesa = v_new.ind_tipo_despesa and id <> v_new.id;',
'            else',
'                select count(1) into l_verifica_valor_unico from ng_despesa where id_tenant = v_new.id_tenant  and ind_tipo_despesa = v_new.ind_tipo_despesa;',
'            end if;            ',
'        end if;',
'',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_despesa.ind_tipo_despesa'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''ind_tipo_despesa'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;',
'    end hook_valida_ind_tipo_despesa;     ',
