'    end hook_valida_ind_regra_calculo;',
'',
'    procedure hook_valida_numero_meses_calculo_media(p_numero_meses_calculo_media in ng_despesa.numero_meses_calculo_media%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_numero_meses_calculo_media;     ',
'',
'    procedure hook_valida_ind_regra_moeda_prevista(p_ind_regra_moeda_prevista in ng_despesa.ind_regra_moeda_prevista%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_regra_moeda_prevista;     ',
'',
'    procedure hook_valida_id_moeda(p_id_moeda in ng_despesa.id_moeda%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_moeda;     ',
'',
'    procedure hook_valida_ind_compoe_custo_operacao(p_ind_compoe_custo_operacao in ng_despesa.ind_compoe_custo_operacao%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_compoe_custo_operacao;     ',
'',
'    procedure hook_valida_data_fim_vigencia(p_data_fim_vigencia in ng_despesa.data_fim_vigencia%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_data_fim_vigencia;     ',
'',
'    procedure hook_valida_ind_despesa_base_calculo(p_ind_despesa_base_calculo in ng_despesa.ind_despesa_base_calculo%type) ',
'    is',
'        l_vmld_selecionado boolean := false;',
'        l_trib_selecionado boolean := false;',
'    begin',
'        for base_calculo in (',
'            select column_value valor from table(apex_string.split(p_ind_despesa_base_calculo, '':''))',
'        ) loop',
'            if base_calculo.valor = ''10'' then',
'                l_vmld_selecionado := true;',
'            elsif base_calculo.valor in (''1'',''2'',''3'',''4'',''5'',''8'',''9'') then',
'                l_trib_selecionado := true;',
'            end if;',
'        end loop;',
'',
'        if l_vmld_selecionado and l_trib_selecionado then',
'            if instr('':''||p_ind_despesa_base_calculo||'':'', '':10:'') > 0 then',
'                select listagg(column_value, '':'') within group(order by column_value)',
'                into v_new.ind_despesa_base_calculo',
'                from table(apex_string.split(p_ind_despesa_base_calculo, '':''))',
'                where column_value not in (''1'',''2'',''3'',''4'',''5'',''8'',''9'');',
'                ',
'                l_mensagem_personalizada := ''S'';',
'            end if;',
'        end if;',
'    end hook_valida_ind_despesa_base_calculo;',
'    --    ',
'    function detalhe_registro (',
'        p_id in ng_despesa.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select ',
'                b.nome_fantasia as ng_despesa$id_tenant, ',
'                pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_origem_despesa'', a.ind_origem_despesa) ng_despesa$ind_origem_despesa,                 ',
'                pkg_traducao.get_traducao(a.descricao_despesa) as ng_despesa$descricao_despesa, ',
'                pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_onde_acontece'', a.ind_onde_acontece) ng_despesa$ind_onde_acontece                ',
'            from ng_despesa a            ',
'            join mpd_tenant b on b.id = a.id_tenant',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure valida_dados_gerais is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);                ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_conta_contabil */ '),
'        valida_id_conta_contabil(v_new.id_conta_contabil);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_origem_despesa */ '),
'        valida_ind_origem_despesa(v_new.ind_origem_despesa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo descricao_despesa */ '),
'        valida_descricao_despesa(v_new.descricao_despesa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_onde_acontece */ '),
'        valida_ind_onde_acontece(v_new.ind_onde_acontece);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_forma_rateio */ '),
'        valida_ind_forma_rateio(v_new.ind_forma_rateio);    ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_compoe_custo_operacao */ '),
'        valida_ind_compoe_custo_operacao(v_new.ind_compoe_custo_operacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_participa_nfe */ '),
'        valida_ind_participa_nfe(v_new.ind_participa_nfe);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_tipo_despesa */ '),
'        valida_ind_tipo_despesa(v_new.ind_tipo_despesa);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_fim_vigencia */ '),
'        valida_data_fim_vigencia(v_new.data_fim_vigencia);',
'    end valida_dados_gerais;     ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_despesa;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td661
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(160848778309642687)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD661'
,p_sequence=>2660
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD661',
'-- Data: 30/04/2026',
unistr('-- Motivo: Ajuste nos par\00E2metros do processo post'),
'-- Jira:',
'',
'create or replace package "UI_MPD_TD661" as   ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function label_acao return varchar2;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'   ',
'end "UI_MPD_TD661";',
'/',
'',
'create or replace package body "UI_MPD_TD661" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select ',
'                    b.numero_pedido_importacao,',
'                    bo_ng_pessoa.retorna_pessoa(b.id_exportador) id_exportador',
'                from imp_pedidoimportacao_item a ',
'                join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'                where a.id = ''|| regexp_substr(p_param1, ''[^_]+'', 1, 1),',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_sql clob;',
'        l_html clob; --???',
'    begin  ',
'        l_sql := ',
'        q''~',
'            select ',
'                b.codigo_item as ng_item$codigo_item,',
'                pkg_traducao.get_traducao(descricao_item) as ng_item$descricao_item,',
'                c.codigo_unidademedida as imp_pedidoimportacao_item$id_unidademedida,',
'                case c.ind_tipo_dado',
'                    when ''D'' then to_char(a.quantidade_programar_entrega, ''FM999G999G990D00000'')',
'                    when ''I'' then to_char(a.quantidade_programar_entrega)',
'                end as imp_pedidoimportacao_item$quantidade_programar_entrega',
'            from imp_pedidoimportacao_item a',
'            join ng_item b on b.id = a.id_item',
'            join ng_unidademedida c on c.id = a.id_unidademedida      ',
'            where a.id in (#PARAM1#)',
'            order by 2      ',
'        ~'';   ',
'        l_sql := replace(l_sql, ''#PARAM1#'', replace(p_param1,''_'','',''));',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, '''' AS nome_coluna, 1 AS indice, ''GRI'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, to_char(l_sql) valor, l_html html, null tag_campo FROM dual UNIO'
||'N ALL',
'               SELECT p_codigo_artefato, ''ids'', 2, ''HID'', null, ''S'', ''N'', to_char(p_param1) valor, null html, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);        ',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''cancelar_saldo'');',
'    end;',
'    ',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_imp_pedidoimportacao_item.cancela_saldo(',
'            p_ids => apex_application.g_f02(1),',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;    ',
'',
'end "UI_MPD_TD661";',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_ng_condicaopagamento
