,p_name=>'BO_NG_CONDICAOPAGAMENTO'
,p_sequence=>2670
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: BO_NG_CONDICAOPAGAMENTO',
'-- Data: 30/04/2026',
unistr('-- Motivo: Corre\00E7\00E3o de bug ao alterar registro'),
