'    procedure inclui_registro(  ',
'        p_id_tenant in ng_condicaopagamento.id_tenant%type,',
'        p_descricao_condicaopagamento in ng_condicaopagamento.descricao_condicaopagamento%type,',
'        p_ind_situacao in ng_condicaopagamento.ind_situacao%type,',
'        p_data_fim_vigencia in ng_condicaopagamento.data_fim_vigencia%type, ',
'        p_id out ng_condicaopagamento.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );   ',
'    procedure altera_registro(  ',
'        p_id_tenant in ng_condicaopagamento.id_tenant%type,',
'        p_descricao_condicaopagamento in ng_condicaopagamento.descricao_condicaopagamento%type,',
'        p_ind_situacao in ng_condicaopagamento.ind_situacao%type,',
'        p_data_fim_vigencia in ng_condicaopagamento.data_fim_vigencia%type, ',
'        p_id in ng_condicaopagamento.id%type, ',
'        p_data_alteracao in ng_condicaopagamento.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure copia_registro(  ',
'        p_id_tenant out ng_condicaopagamento.id_tenant%type,',
'        p_descricao_condicaopagamento out ng_condicaopagamento.descricao_condicaopagamento%type,',
'        p_ind_situacao out ng_condicaopagamento.ind_situacao%type,',
'        p_data_fim_vigencia out ng_condicaopagamento.data_fim_vigencia%type, ',
'        p_id in out ng_condicaopagamento.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure exclui_registro(  ',
'        p_id in ng_condicaopagamento.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos padr\00E3o'),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);     ',
'',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in ng_condicaopagamento.id%type ',
'    );    ',
'    function verifica_registro( ',
'        p_id in ng_condicaopagamento.id%type ',
'    ) return boolean;    ',
'    procedure verifica_registro_em_uso( ',
'        p_id in ng_condicaopagamento.id%type ',
'    );    ',
'    procedure verifica_data_alteracao ( ',
'        p_data_alteracao in ng_condicaopagamento.data_alteracao%type ',
'    ); ',
'    procedure valida;     ',
'    procedure valida_id_tenant(p_id_tenant in ng_condicaopagamento.id_tenant%type); ',
'    procedure valida_descricao_condicaopagamento(p_descricao_condicaopagamento in ng_condicaopagamento.descricao_condicaopagamento%type); ',
'    procedure valida_ind_situacao(p_ind_situacao in ng_condicaopagamento.ind_situacao%type); ',
'    procedure valida_data_fim_vigencia(p_data_fim_vigencia in ng_condicaopagamento.data_fim_vigencia%type); ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'    procedure hook_valida_id_tenant(p_id_tenant in ng_condicaopagamento.id_tenant%type); ',
'    procedure hook_valida_descricao_condicaopagamento(p_descricao_condicaopagamento in ng_condicaopagamento.descricao_condicaopagamento%type); ',
'    procedure hook_valida_ind_situacao(p_ind_situacao in ng_condicaopagamento.ind_situacao%type); ',
'    procedure hook_valida_data_fim_vigencia(p_data_fim_vigencia in ng_condicaopagamento.data_fim_vigencia%type); ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir;',
'    procedure grava_log_alterar;',
'    procedure grava_log_excluir;',
'    function row_to_json(p_rec in ng_condicaopagamento%rowtype) return clob;  ',
'',
'    --<CUSTOMIZADO_INICIO>',
'',
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table);',
'',
'    function detalhe_registro (',
'        p_id in ng_condicaopagamento.id%type',
'    ) return varchar2;',
'    --<CUSTOMIZADO_FIM>   ',
'',
'end bo_ng_condicaopagamento; ',
'',
'/',
'create or replace package body            bo_ng_condicaopagamento ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out ng_condicaopagamento.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_condicaopagamento'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into ng_condicaopagamento (  ',
'            id_tenant,',
'            descricao_condicaopagamento,',
'            ind_situacao,',
'            data_fim_vigencia, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'',
'        ) values (  ',
'            v_new.id_tenant,',
'            v_new.descricao_condicaopagamento,',
'            v_new.ind_situacao,',
'            v_new.data_fim_vigencia, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_condicaopagamento'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
