'        pkg_traducao.grava_traducao(v_new.descricao_condicaopagamento,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_condicaopagamento,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_condicaopagamento,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    function detalhe_registro (',
'        p_id in ng_condicaopagamento.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                b.nome_fantasia as ng_condicaopagamento$id_tenant,',
'		        pkg_traducao.get_traducao(a.descricao_condicaopagamento)  as ng_condicaopagamento$descricao_condicaopagamento,',
'                (SELECT COUNT(*) FROM ng_condicaopagamento_parcela c WHERE c.id_condicaopagamento = a.id) as "ng_condicaopagamento_parcela$numero_parcela"',
'                -- case',
'                --     when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                --         pkg_componentes.html_cor_texto(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''))',
'                --     else',
'                --         to_char(a.data_fim_vigencia, ''dd/mm/yyyy'') ',
'                -- end ng_condicaopagamento$data_fim_vigencia',
'                from ng_condicaopagamento a',
'                join mpd_tenant b on b.id = a.id_tenant',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_condicaopagamento;',
'/'))
);
end;
