unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_condicaopagamento_parcela'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_condicaopagamento_parcela'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_condicaopagamento_parcela'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_condicaopagamento_parcela'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_condicaopagamento_parcela'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_condicaopagamento_parcela'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_condicaopagamento_parcela%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_condicaopagamento'', p_rec.id_condicaopagamento, true);',
'        apex_json.write(''numero_parcela'', p_rec.numero_parcela, true);',
'        apex_json.write(''percentual'', p_rec.percentual, true);',
'        apex_json.write(''ind_evento_gerador_pagamento'', p_rec.ind_evento_gerador_pagamento, true);',
'        apex_json.write(''qtd_dias_evento'', p_rec.qtd_dias_evento, true);',
'        apex_json.write(''ind_liberacao_titulo'', p_rec.ind_liberacao_titulo, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        atualiza_situacao(v_new.id_condicaopagamento); ',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        atualiza_situacao(v_new.id_condicaopagamento);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        -- bo_ng_traducaotexto.exclui_registros(',
'        --     p_nome_entidade => ''ng_condicaopagamento_parcela'',',
'        --     p_id_origem => v_old.id,',
'        --     p_encadeado => p_encadeado,',
'        --     p_sucesso => p_sucesso,',
'        --     p_messages => p_messages',
'        -- );',
'        atualiza_numero_parcela;',
'        atualiza_situacao(v_old.id_condicaopagamento);    ',
'    end; ',
'    --',
unistr('    -- Fun\00E7\00F5es complementares'),
'    --',
'    function detalhe_registro (',
'        p_id in ng_condicaopagamento_parcela.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(''',
'        select',
'            numero_parcela as ng_condicaopagamento_parcela$numero_parcela,',
'            TO_CHAR(percentual, ''''FM999G999G990'''') || '''' %'''' as ng_condicaopagamento_parcela$percentual,',
'            pkg_util.dominio_retorna_tag(''''ng_condicaopagamento_parcela'''',''''ind_evento_gerador_pagamento'''',ind_evento_gerador_pagamento) as ng_condicaopagamento_parcela$ind_evento_gerador_pagamento,',
'            qtd_dias_evento as ng_condicaopagamento_parcela$qtd_dias_evento',
'        from ng_condicaopagamento_parcela',
'        where id = ''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure atualiza_situacao(',
'        p_id in ng_condicaopagamento.id%TYPE',
'    ) is',
'        l_soma_percentual number := 0;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        select * into v_old_condicaopagamento from ng_condicaopagamento where id = p_id;',
'        select nvl(sum(percentual), 0) into l_soma_percentual from ng_condicaopagamento_parcela where id_condicaopagamento = v_old_condicaopagamento.id;',
'        if l_soma_percentual = 100 then',
'            --{REVISAR_FUNCAO}',
'            bo_ng_condicaopagamento.altera_registro (',
'                p_id_tenant => v_old_condicaopagamento.id_tenant,',
'                p_descricao_condicaopagamento => v_old_condicaopagamento.descricao_condicaopagamento,',
'                p_data_fim_vigencia => v_old_condicaopagamento.data_fim_vigencia,',
'                p_ind_situacao => ''D'',',
'                p_id => v_old_condicaopagamento.id, ',
'                p_data_alteracao => v_old_condicaopagamento.data_alteracao, ',
'                p_sucesso => l_sucesso,',
'                p_messages => l_messages',
'            );',
'        else',
'            --{REVISAR_FUNCAO}',
'            bo_ng_condicaopagamento.altera_registro (',
'                p_id_tenant => v_old_condicaopagamento.id_tenant,',
'                p_descricao_condicaopagamento => v_old_condicaopagamento.descricao_condicaopagamento,',
'                p_data_fim_vigencia => v_old_condicaopagamento.data_fim_vigencia,',
'                p_ind_situacao => ''E'',',
'                p_id => v_old_condicaopagamento.id, ',
'                p_data_alteracao => v_old_condicaopagamento.data_alteracao, ',
'                p_sucesso => l_sucesso,',
'                p_messages => l_messages',
'            );',
'        end if;',
'    end atualiza_situacao;',
'    --',
'    function gera_sequencia (',
'        p_id in ng_condicaopagamento_parcela.id%TYPE',
'    ) return varchar2 is',
'        l_contador number := 0;',
'    begin',
'        select coalesce(max(numero_parcela), 0) into l_contador from ng_condicaopagamento_parcela where id_condicaopagamento = p_id;',
'        return l_contador + 1;',
'    end gera_sequencia;',
'    --',
'    procedure atualiza_numero_parcela is',
'        l_numero_atual number;',
'        l_sucesso clob;',
'        l_messages pkg_mensagem.message_record_table;',
'    begin',
'        l_numero_atual := v_old.numero_parcela;        ',
'        for rec in ',
'            (select * from ng_condicaopagamento_parcela where id_condicaopagamento = v_old.id_condicaopagamento and numero_parcela > l_numero_atual)',
'        loop',
'            --{REVISAR_FUNCAO}',
'            altera_registro(',
'                p_id_tenant => rec.id_tenant,',
'                p_ind_evento_gerador_pagamento => rec.ind_evento_gerador_pagamento,',
'                p_qtd_dias_evento => rec.qtd_dias_evento,',
'                p_ind_liberacao_titulo => rec.ind_liberacao_titulo,',
'                p_id_condicaopagamento => rec.id_condicaopagamento,',
'                p_numero_parcela => (rec.numero_parcela - 1),',
'                p_percentual => rec.percentual,',
'                p_id => rec.id,',
'                p_data_alteracao => rec.data_alteracao,',
'                p_sucesso => l_sucesso,',
'                p_messages => l_messages',
'            );',
'        end loop;',
'    end;',
'    --',
'    function retorna_ind_evento_gerador_pagamento(',
'        p_id_condicaopagamento in ng_condicaopagamento_parcela.id_condicaopagamento%type,',
'        p_numero_parcela in ng_condicaopagamento_parcela.numero_parcela%type',
'    ) return number is',
'        l_ind_evento_gerador_pagamento number;',
'    begin',
'        select ind_evento_gerador_pagamento ',
'        into l_ind_evento_gerador_pagamento ',
'        from ng_condicaopagamento_parcela ',
'        where id_condicaopagamento = p_id_condicaopagamento ',
'        and numero_parcela = p_numero_parcela;',
'',
'        return l_ind_evento_gerador_pagamento;',
'    end retorna_ind_evento_gerador_pagamento;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_condicaopagamento_parcela;',
'/'))
);
end;
/
