'/',
'',
'create or replace package body            bo_imp_entrega_item_tributo ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_entrega_item_tributo.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_entrega_item_tributo'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into imp_entrega_item_tributo (  ',
'            id_tenant,',
'            id_entrega_item,',
'            vmle,',
'            frete,',
'            seguro,',
'            acrescimo,',
'            vmld,',
'            multa,',
'            taxa_siscomex,',
'            afrmm,',
'            base_calculo_ii,',
'            aliquota_ii,',
'            valor_ii,',
'            base_calculo_ipi,',
'            aliquota_ipi,',
'            valor_ipi,',
'            base_calculo_pis_cofins,',
'            aliquota_pis,',
'            valor_pis,',
'            aliquota_cofins,',
'            valor_cofins,',
'            base_calculo_icms,',
'            base_calculo_icms_st,',
'            aliquota_icms,',
'            valor_icms,',
'            valor_icms_st,',
'            base_calculo_cbs,',
'            aliquota_cbs,',
'            valor_cbs,',
'            base_calculo_ibs,',
'            aliquota_ibs,',
'            valor_ibs, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_tenant,',
'            v_new.id_entrega_item,',
'            v_new.vmle,',
'            v_new.frete,',
'            v_new.seguro,',
'            v_new.acrescimo,',
'            v_new.vmld,',
'            v_new.multa,',
'            v_new.taxa_siscomex,',
'            v_new.afrmm,',
'            v_new.base_calculo_ii,',
'            v_new.aliquota_ii,',
'            v_new.valor_ii,',
'            v_new.base_calculo_ipi,',
'            v_new.aliquota_ipi,',
'            v_new.valor_ipi,',
'            v_new.base_calculo_pis_cofins,',
'            v_new.aliquota_pis,',
'            v_new.valor_pis,',
'            v_new.aliquota_cofins,',
'            v_new.valor_cofins,',
'            v_new.base_calculo_icms,',
'            v_new.base_calculo_icms_st,',
'            v_new.aliquota_icms,',
'            v_new.valor_icms,',
'            v_new.valor_icms_st,',
'            v_new.base_calculo_cbs,',
'            v_new.aliquota_cbs,',
'            v_new.valor_cbs,',
'            v_new.base_calculo_ibs,',
'            v_new.aliquota_ibs,',
'            v_new.valor_ibs, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_entrega_item_tributo'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_entrega_item_tributo'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_entrega_item_tributo'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in imp_entrega_item_tributo.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
