'            aliquota_ipi = v_new.aliquota_ipi,',
'            valor_ipi = v_new.valor_ipi,',
'            base_calculo_pis_cofins = v_new.base_calculo_pis_cofins,',
'            aliquota_pis = v_new.aliquota_pis,',
'            valor_pis = v_new.valor_pis,',
'            aliquota_cofins = v_new.aliquota_cofins,',
'            valor_cofins = v_new.valor_cofins,',
'            base_calculo_icms = v_new.base_calculo_icms,',
'            base_calculo_icms_st = v_new.base_calculo_icms_st,',
'            aliquota_icms = v_new.aliquota_icms,',
'            valor_icms = v_new.valor_icms,',
'            valor_icms_st = v_new.valor_icms_st,',
'            base_calculo_cbs = v_new.base_calculo_cbs,',
