'            p_aliquota_icms,',
'            p_valor_icms,',
'            p_valor_icms_st,',
'            p_base_calculo_cbs,',
'            p_aliquota_cbs,',
'            p_valor_cbs,',
'            p_base_calculo_ibs,',
'            p_aliquota_ibs,',
'            p_valor_ibs, ',
'            p_id ',
'        from imp_entrega_item_tributo ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
