unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_entrega_item_tributo'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_entrega_item_tributo'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_entrega_item_tributo'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_entrega_item_tributo'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_entrega_item_tributo'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_entrega_item_tributo'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_entrega_item_tributo%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_entrega_item'', p_rec.id_entrega_item, true);',
'        apex_json.write(''vmle'', p_rec.vmle, true);',
'        apex_json.write(''frete'', p_rec.frete, true);',
'        apex_json.write(''seguro'', p_rec.seguro, true);',
'        apex_json.write(''acrescimo'', p_rec.acrescimo, true);',
'        apex_json.write(''vmld'', p_rec.vmld, true);',
'        apex_json.write(''multa'', p_rec.multa, true);',
'        apex_json.write(''taxa_siscomex'', p_rec.taxa_siscomex, true);',
'        apex_json.write(''afrmm'', p_rec.afrmm, true);',
'        apex_json.write(''base_calculo_ii'', p_rec.base_calculo_ii, true);',
'        apex_json.write(''aliquota_ii'', p_rec.aliquota_ii, true);',
'        apex_json.write(''valor_ii'', p_rec.valor_ii, true);',
'        apex_json.write(''base_calculo_ipi'', p_rec.base_calculo_ipi, true);',
'        apex_json.write(''aliquota_ipi'', p_rec.aliquota_ipi, true);',
'        apex_json.write(''valor_ipi'', p_rec.valor_ipi, true);',
'        apex_json.write(''base_calculo_pis_cofins'', p_rec.base_calculo_pis_cofins, true);',
'        apex_json.write(''aliquota_pis'', p_rec.aliquota_pis, true);',
'        apex_json.write(''valor_pis'', p_rec.valor_pis, true);',
'        apex_json.write(''aliquota_cofins'', p_rec.aliquota_cofins, true);',
'        apex_json.write(''valor_cofins'', p_rec.valor_cofins, true);',
'        apex_json.write(''base_calculo_icms'', p_rec.base_calculo_icms, true);',
'        apex_json.write(''base_calculo_icms_st'', p_rec.base_calculo_icms_st, true);',
'        apex_json.write(''aliquota_icms'', p_rec.aliquota_icms, true);',
'        apex_json.write(''valor_icms'', p_rec.valor_icms, true);',
'        apex_json.write(''valor_icms_st'', p_rec.valor_icms_st, true);',
'        apex_json.write(''base_calculo_cbs'', p_rec.base_calculo_cbs, true);',
'        apex_json.write(''aliquota_cbs'', p_rec.aliquota_cbs, true);',
'        apex_json.write(''valor_cbs'', p_rec.valor_cbs, true);',
'        apex_json.write(''base_calculo_ibs'', p_rec.base_calculo_ibs, true);',
'        apex_json.write(''aliquota_ibs'', p_rec.aliquota_ibs, true);',
'        apex_json.write(''valor_ibs'', p_rec.valor_ibs, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
