'    --',
'    function calcula_despesa_por_tipo(',
'        p_id_entrega_item in imp_entrega_item_tributo.id_entrega_item%type,',
'        p_ind_tipo_despesa in ng_despesa.ind_tipo_despesa%type        ',
'    ) return number is',
'        l_id_entrega number;',
'        l_valor number;',
'        l_ind_forma_rateio number;',
'        l_peso_liquido_total number;',
'        l_quantidade number;',
'        l_valor_total_condicao_venda number;',
'        l_resultado number := 0;',
'    begin',
'        -- select ',
'        --     c.valor, d.ind_forma_rateio, a.peso_liquido_total, a.quantidade, a.valor_total_condicao_venda',
'        -- into ',
'        --     l_valor, l_ind_forma_rateio, l_peso_liquido_total, l_quantidade, l_valor_total_condicao_venda',
'        -- from imp_entrega_item a ',
'        -- join imp_entrega b on b.id = a.id_entrega ',
'        -- join imp_entrega_despesa c on c.id_entrega = b.id ',
'        -- join ng_despesa d on d.id = c.id_despesa ',
'        -- where a.id = p_id_entrega_item',
'        -- and ind_tipo_despesa = p_ind_tipo_despesa;',
'        select id_entrega into l_id_entrega from imp_entrega_item where id = p_id_entrega_item;',
'        select ',
'            c.valor, d.ind_forma_rateio, sum(a.peso_liquido_total), sum(a.quantidade), sum(a.valor_total_condicao_venda)',
'        into ',
'            l_valor, l_ind_forma_rateio, l_peso_liquido_total, l_quantidade, l_valor_total_condicao_venda',
'        from imp_entrega_item a ',
'        join imp_entrega b on b.id = a.id_entrega ',
'        join imp_entrega_despesa c on c.id_entrega = b.id ',
'        join ng_despesa d on d.id = c.id_despesa ',
'        where b.id = l_id_entrega',
'        and ind_tipo_despesa = p_ind_tipo_despesa',
'        group by c.valor, d.ind_forma_rateio;',
'',
'        if l_ind_forma_rateio = 1 then',
'            l_resultado := (l_valor / l_peso_liquido_total);',
'        elsif l_ind_forma_rateio = 2 then',
'            l_resultado := (l_valor / l_quantidade);',
'        elsif l_ind_forma_rateio = 3 then',
'            l_resultado := (l_valor / l_valor_total_condicao_venda);',
'        elsif l_ind_forma_rateio = 5 then',
'            null;',
'        end if;',
'        return trunc(l_resultado, 5);',
'',
'    exception ',
'        when others then ',
'            return 0;',
'    end calcula_despesa_por_tipo;    ',
'    --',
'    function calcula_total_despesa_por_tipo(',
'        p_id_entrega_item in imp_entrega_item_tributo.id_entrega_item%type,',
'        p_ind_tipo_despesa in ng_despesa.ind_tipo_despesa%type        ',
'    ) return number is',
'        l_id_entrega number;',
'        l_valor number;',
'        l_ind_forma_rateio number;',
'        l_peso_liquido_total_entrega number;',
'        l_peso_liquido_total number;',
'        l_quantidade_entrega number;',
'        l_quantidade number;',
'        l_valor_total_condicao_venda_entrega number;',
'        l_valor_total_condicao_venda number;',
'        l_resultado number := 0;',
'    begin        ',
'        select id_entrega into l_id_entrega from imp_entrega_item where id = p_id_entrega_item;',
'        select ',
'            c.valor, d.ind_forma_rateio, sum(a.peso_liquido_total), sum(a.quantidade), sum(a.valor_total_condicao_venda)',
'        into ',
'            l_valor, l_ind_forma_rateio, l_peso_liquido_total, l_quantidade, l_valor_total_condicao_venda',
'        from imp_entrega_item a ',
'        join imp_entrega b on b.id = a.id_entrega ',
'        join imp_entrega_despesa c on c.id_entrega = b.id ',
'        join ng_despesa d on d.id = c.id_despesa ',
'        where b.id = l_id_entrega',
'        and ind_tipo_despesa = p_ind_tipo_despesa',
'        group by c.valor, d.ind_forma_rateio;',
'',
'        select ',
'            peso_liquido_total, quantidade, valor_total_condicao_venda',
'        into',
'            l_peso_liquido_total_entrega, l_quantidade_entrega, l_valor_total_condicao_venda_entrega',
'        from imp_entrega_item ',
'        where id = p_id_entrega_item;',
'',
'        if l_ind_forma_rateio = 1 then',
'            l_resultado := (l_valor / l_peso_liquido_total) * l_peso_liquido_total_entrega;',
'        elsif l_ind_forma_rateio = 2 then',
'            l_resultado := (l_valor / l_quantidade) * l_quantidade_entrega;',
'        elsif l_ind_forma_rateio = 3 then',
'            l_resultado := (l_valor / l_valor_total_condicao_venda) * l_valor_total_condicao_venda_entrega;',
'        elsif l_ind_forma_rateio = 5 then',
'            null;',
'        end if;',
'        return trunc(l_resultado, 5);',
'',
'    exception ',
'        when others then ',
'            return 0;',
'    end calcula_total_despesa_por_tipo;',
'    --',
'    function calcula_vmle(',
'        p_id_entrega_item in imp_entrega_item_tributo.id_entrega_item%type',
'    ) return number is',
'        l_id_entrega number;',
'        l_valor_total_condicao_venda number;',
'        l_id_incoterm number;        ',
'        l_ind_responsavel_frete ng_incoterm.ind_responsavel_frete%type;',
'        l_ind_responsavel_seguro ng_incoterm.ind_responsavel_seguro%type;',
'        l_ind_responsavel_despesa_origem ng_incoterm.ind_responsavel_despesa_origem%type;',
'        l_resultado number := 0;',
'    begin',
'        select id_entrega, valor_total_condicao_venda into l_id_entrega, l_valor_total_condicao_venda from imp_entrega_item where id = p_id_entrega_item;',
'        select id_incoterm into l_id_incoterm from imp_entrega where id = l_id_entrega;',
'        select lower(ind_responsavel_frete), lower(ind_responsavel_seguro), lower(ind_responsavel_despesa_origem) into l_ind_responsavel_frete, l_ind_responsavel_seguro, l_ind_responsavel_despesa_origem from ng_incoterm where id = l_id_incoterm;',
'',
'        if l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''i'' then     -- iii',
'            l_resultado := l_valor_total_condicao_venda;',
'        elsif l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''e'' then  -- iie',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 16);',
'        elsif l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''i'' then  -- iei',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 10);',
'        elsif l_ind_responsavel_frete = ''i'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''e'' then  -- iee',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 10) - calcula_total_despesa_por_tipo(p_id_entrega_item, 16);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''i'' then  -- eii',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 9);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''i'' then  -- eei',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 10) - calcula_total_despesa_por_tipo(p_id_entrega_item, 9);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''i'' and l_ind_responsavel_despesa_origem = ''e'' then  -- eie',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 9) - calcula_total_despesa_por_tipo(p_id_entrega_item, 16);',
'        elsif l_ind_responsavel_frete = ''e'' and l_ind_responsavel_seguro = ''e'' and l_ind_responsavel_despesa_origem = ''e'' then  -- eee',
'            l_resultado := l_valor_total_condicao_venda - calcula_total_despesa_por_tipo(p_id_entrega_item, 10) - calcula_total_despesa_por_tipo(p_id_entrega_item, 9) - calcula_total_despesa_por_tipo(p_id_entrega_item, 16);',
'        end if;',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_vmle;    ',
'    --    ',
'    function calcula_vmld(',
'        p_id_entrega_item in imp_entrega_item_tributo.id_entrega_item%type',
'    ) return number is',
'        l_resultado number := 0;',
'    begin',
'        l_resultado := calcula_vmle(p_id_entrega_item) + calcula_total_despesa_por_tipo(p_id_entrega_item, 9) + calcula_total_despesa_por_tipo(p_id_entrega_item, 10) + calcula_total_despesa_por_tipo(p_id_entrega_item, 16);',
'        return l_resultado;',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_vmld;',
'    --',
'    function retorna_aliquota_ii(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_ind_aplicacao_ii number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm into l_id_naturezaoperacao, l_id_ncm from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_ii) into l_ind_aplicacao_ii from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ii = 1 then',
'            select aliquota_ii into l_resultado from ng_ncm a join imp_ncm_tributo b on b.id_ncm = a.id where a.id = l_id_ncm;',
'        elsif l_ind_aplicacao_ii = 2 then',
'            select aliquota_ii into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_ii = 3 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_ii;',
'    --',
'    function retorna_base_calculo_ipi(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_ipi number;',
'        l_percentual_reducao_base_ipi number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_ipi) into l_ind_aplicacao_ipi from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ipi in (1,2,4) then',
'            l_resultado := calcula_vmld(p_id_entrega_item) + (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100));',
'        elsif l_ind_aplicacao_ipi = 3 then',
'            select percentual_reducao_base_ipi into l_percentual_reducao_base_ipi from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'            l_resultado := trunc(((calcula_vmld(p_id_entrega_item) + (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100))) * (1 - (l_percentual_reducao_base_ipi / 100))), 5);',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_ipi;',
'    --',
'    function retorna_aliquota_ipi(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_ind_aplicacao_ipi number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm into l_id_naturezaoperacao, l_id_ncm from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_ipi) into l_ind_aplicacao_ipi from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ipi in (1, 3) then',
'            select aliquota_ipi into l_resultado from ng_ncm a join imp_ncm_tributo b on b.id_ncm = a.id where a.id = l_id_ncm;',
'        elsif l_ind_aplicacao_ipi = 2 then',
'            select aliquota_ipi into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_ipi = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_ipi;',
'    --',
'    function retorna_base_calculo_pis_cofins(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_pis_cofins number;',
'        l_percentual_reducao_base_pis_cofins number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_pis_cofins) into l_ind_aplicacao_pis_cofins from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_pis_cofins in (1,2,4) then',
'            l_resultado := calcula_vmld(p_id_entrega_item);',
'        elsif l_ind_aplicacao_pis_cofins = 3 then',
'            select percentual_reducao_base_pis_cofins into l_percentual_reducao_base_pis_cofins from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'            l_resultado := (calcula_vmld(p_id_entrega_item) * (1 - (l_percentual_reducao_base_pis_cofins / 100)));',
'        end if;',
'        return trunc(l_resultado, 5);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_pis_cofins;',
'    --',
'    function retorna_aliquota_pis(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_ind_aplicacao_pis_cofins number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm into l_id_naturezaoperacao, l_id_ncm from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_pis_cofins) into l_ind_aplicacao_pis_cofins from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_pis_cofins in (1, 3) then',
'            select aliquota_pis into l_resultado from ng_ncm a join imp_ncm_tributo b on b.id_ncm = a.id where a.id = l_id_ncm;',
'        elsif l_ind_aplicacao_pis_cofins = 2 then',
'            select aliquota_pis into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_pis_cofins = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_pis;',
'    --',
'    function retorna_aliquota_cofins(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_ind_aplicacao_pis_cofins number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm into l_id_naturezaoperacao, l_id_ncm from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_pis_cofins) into l_ind_aplicacao_pis_cofins from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_pis_cofins in (1, 3) then',
'            select aliquota_cofins into l_resultado from ng_ncm a join imp_ncm_tributo b on b.id_ncm = a.id where a.id = l_id_ncm;',
'        elsif l_ind_aplicacao_pis_cofins = 2 then',
'            select aliquota_cofins into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_pis_cofins = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_cofins;',
'    --',
'    function retorna_base_calculo_cbs(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_cbs number;',
'        l_percentual_reducao_base_cbs number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_entrega_item where id = p_id_entrega_item;',
'        select ind_aplicacao_cbs into l_ind_aplicacao_cbs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_cbs in (1,2,4) then',
'            l_resultado := ',
'                calcula_vmld(p_id_entrega_item) + ',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 11) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 7);',
'        elsif l_ind_aplicacao_cbs = 3 then',
'            select percentual_reducao_base_cbs into l_percentual_reducao_base_cbs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'            l_resultado := ',
'                (calcula_vmld(p_id_entrega_item) + ',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 11) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 7)) *',
'                (1 - (l_percentual_reducao_base_cbs / 100));',
'        end if;',
'        return trunc(l_resultado, 2);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_cbs;',
'    --',
'    function retorna_aliquota_cbs(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_ind_aplicacao_cbs number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm into l_id_naturezaoperacao, l_id_ncm from imp_entrega_item where id = p_id_entrega_item;',
'        select ind_aplicacao_cbs into l_ind_aplicacao_cbs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_cbs in (1, 3) then',
'            select aliquota_cbs into l_resultado from ng_ncm a join imp_ncm_tributo b on b.id_ncm = a.id where a.id = l_id_ncm;',
'        elsif l_ind_aplicacao_cbs = 2 then',
'            select aliquota_cbs into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_cbs = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_cbs;',
'    --',
'    function retorna_base_calculo_ibs(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_ibs number;',
'        l_percentual_reducao_base_ibs number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_entrega_item where id = p_id_entrega_item;',
'        select ind_aplicacao_ibs into l_ind_aplicacao_ibs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ibs in (1,2,4) then',
'            l_resultado := ',
'                calcula_vmld(p_id_entrega_item) + ',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 11) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 7);',
'        elsif l_ind_aplicacao_ibs = 3 then',
'            select percentual_reducao_base_ibs into l_percentual_reducao_base_ibs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'            l_resultado := ',
'                (calcula_vmld(p_id_entrega_item) + ',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 11) +',
'                calcula_despesa_por_tipo(p_id_entrega_item, 7)) *',
'                (1 - (l_percentual_reducao_base_ibs / 100));',
'        end if;',
'        return trunc(l_resultado, 2);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_ibs;',
'    --',
'    function retorna_aliquota_ibs(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_id_adquirente number;',
'        l_ind_aplicacao_ibs number;',
'        l_aliquota_ibu number;',
'        l_aliquota_ibm number;',
'        l_resultado number;',
'    begin',
'        select a.id_naturezaoperacao, a.id_ncm, nvl(b.id_adquirente, b.id_importador) into l_id_naturezaoperacao, l_id_ncm, l_id_adquirente from imp_entrega_item a join imp_entrega b on b.id = a.id_entrega where a.id = p_id_entrega_item;',
'        select ind_aplicacao_ibs into l_ind_aplicacao_ibs from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_ibs in (1, 3) then',
'            select ',
'                bo_ng_ibu.retorna_aliquota_ibu(id_estado), ',
'                bo_ng_ibm.retorna_aliquota_ibm(id_cidade) ',
'            into ',
'                l_aliquota_ibu, ',
'                l_aliquota_ibm ',
'            from ng_pessoa_endereco ',
'            where id = bo_ng_pessoa_endereco.retorna_id_pessoa_endereco(l_id_adquirente);',
'',
'            l_resultado := l_aliquota_ibu + l_aliquota_ibm;',
'        elsif l_ind_aplicacao_ibs = 2 then',
'            select aliquota_ibs into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_ibs = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_ibs;',
'    --',
'    function retorna_base_calculo_icms(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao_icms number;',
'        l_ind_ipi_suspenso_base_icms varchar2(1);',
'        l_ind_integra_propria_base_icms varchar2(1);',
'        l_percentual_reducao_base_icms number;',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_icms), lower(ind_ipi_suspenso_base_icms), lower(ind_integra_propria_base_icms) into l_ind_aplicacao_icms, l_ind_ipi_suspenso_base_icms, l_ind_integra_propria_base_icms from imp_naturezaoperacao_tributo where id_natu'
||'rezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_icms in (1,2,4) and l_ind_ipi_suspenso_base_icms = ''n'' and l_ind_integra_propria_base_icms in (''n'',''s'') then',
'            l_resultado := ',
'                (calcula_vmld(p_id_entrega_item) +',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_ipi(p_id_entrega_item) * (retorna_aliquota_ipi(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_pis_cofins(p_id_entrega_item) * (retorna_aliquota_pis(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_pis_cofins(p_id_entrega_item) * (retorna_aliquota_cofins(p_id_entrega_item) / 100)) +',
'                (calcula_total_despesa_por_tipo(p_id_entrega_item, 11)) +',
'                (calcula_total_despesa_por_tipo(p_id_entrega_item, 7)));',
'        elsif l_ind_aplicacao_icms in (1,2,4) and l_ind_ipi_suspenso_base_icms = '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(164389540557669832)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'''s'' and l_ind_integra_propria_base_icms in (''n'',''s'') then',
'            l_resultado := ',
'                (calcula_vmld(p_id_entrega_item) +',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_pis_cofins(p_id_entrega_item) * (retorna_aliquota_pis(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_pis_cofins(p_id_entrega_item) * (retorna_aliquota_cofins(p_id_entrega_item) / 100)) +',
'                (calcula_total_despesa_por_tipo(p_id_entrega_item, 11)) +',
'                (calcula_total_despesa_por_tipo(p_id_entrega_item, 7)));',
'        elsif l_ind_aplicacao_icms = 3 then',
'            select percentual_reducao_base_icms into l_percentual_reducao_base_icms from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'            --l_resultado := trunc(((calcula_vmld(p_id_entrega_item) + p_valor_ii + p_valor_ipi + p_valor_pis + p_valor_cofins + p_taxa_siscomex + p_afrmm) * (1 - (l_percentual_reducao_base_icms / 100))), 5);',
'            l_resultado := ',
'                ((calcula_vmld(p_id_entrega_item) +',
'                (calcula_vmld(p_id_entrega_item) * (retorna_aliquota_ii(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_ipi(p_id_entrega_item) * (retorna_aliquota_ipi(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_pis_cofins(p_id_entrega_item) * (retorna_aliquota_pis(p_id_entrega_item) / 100)) +',
'                (retorna_base_calculo_pis_cofins(p_id_entrega_item) * (retorna_aliquota_cofins(p_id_entrega_item) / 100)) +',
