'    --',
'    function retorna_base_calculo_icms_st(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_percentual_mva_icms_st number;      ',
'        l_resultado number := 0;',
'    begin        ',
'        select nvl(b.percentual_mva_icms_st, 0)',
'        into l_percentual_mva_icms_st ',
'        from imp_entrega_item a ',
'        join imp_naturezaoperacao_tributo b on b.id_naturezaoperacao = a.id_naturezaoperacao ',
'        where a.id = p_id_entrega_item;',
'',
'        l_resultado := retorna_base_calculo_icms(p_id_entrega_item) * (l_percentual_mva_icms_st / 100);',
'',
'        return trunc(l_resultado, 5);',
'    exception ',
'        when others then',
'            return 0;',
'    end retorna_base_calculo_icms_st;',
'    --',
'    function retorna_aliquota_icms(',
'        p_id_entrega_item in imp_entrega_item.id%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_id_ncm number;',
'        l_id_entrega number;',
'        l_id_importador number;',
'        l_ind_aplicacao_icms number;        ',
'        l_resultado number;',
'    begin',
'        select id_naturezaoperacao, id_ncm, id_entrega into l_id_naturezaoperacao, l_id_ncm, l_id_entrega from imp_entrega_item where id = p_id_entrega_item;',
'        select lower(ind_aplicacao_icms) into l_ind_aplicacao_icms from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'',
'        if l_ind_aplicacao_icms in (1, 3) then',
'            select id_importador into l_id_importador from imp_entrega where id = l_id_entrega;',
'            select perc_icms into l_resultado from ng_icms a join ng_pessoa_endereco b on b.id_estado = a.id_uf_destino where b.id_pessoa = l_id_importador and lower(ind_endereco_principal) = ''s'' fetch first 1 row only;            ',
'        elsif l_ind_aplicacao_icms = 2 then',
'            select aliquota_icms into l_resultado from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        elsif l_ind_aplicacao_icms = 4 then',
'            l_resultado := 0;',
'        end if;',
'        return l_resultado;',
'    exception ',
'        when others then ',
'            return 0;',
'    end retorna_aliquota_icms;',
