'            p_id_viatransporte => apex_application.g_f14(1),',
'            p_id_transportador_internacional => apex_application.g_f16(1),',
'            p_conhecimento_transporte => apex_application.g_f18(1),',
'            p_navio => apex_application.g_f19(1),',
'            p_viagem => apex_application.g_f20(1),',
'            p_id_transportador_nacional => apex_application.g_f21(1),',
'            p_id_endereco_origem => apex_application.g_f23(1),',
'            p_id_local_embarque => apex_application.g_f25(1),',
