prompt --application/deployment/install/install_ui_mpd_td607
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(167433128506101538)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD607'
,p_sequence=>2730
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 23/06/2026',
unistr('-- Motivo: Inclus\00E3o das colunas ind_finalidade e numero_ato_concessorio na entidade imp_pedidoimportacao_item'),
'-- Jira: PEDITEM-330',
'',
'-- Objeto: UI_MPD_TD607',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste para trazer o campo de consulta num_sequencia_item',
'-- Jira: PEDITEM-26',
'',
'create or replace package "UI_MPD_TD607" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_valor_item(p_param1 in varchar2) return clob;',
'',
'    function sql_atribuir_valor_quantidade(p_param1 in varchar2) return clob;',
'',
'    function sql_atribuir_valor_unitario(p_param1 in varchar2) return clob;',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob;',
'',
'    function condicao_proximo(p_param1 in varchar2) return boolean;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'',
'end "UI_MPD_TD607";',
'/',
'',
'create or replace package body "UI_MPD_TD607" as',
'    ',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao from imp_pedidoimportacao a join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'        l_consulta_item clob;',
'        l_atribuir_valor_item clob;',
'        l_JSON_calcular_valor_total clob;',
'        l_JSON_calcular_peso_total clob;',
'        l_campos_calcular_valor_quantidade varchar2(128) := ''VALOR_TOTAL'';',
'        l_campos_calcular_peso_quantidade varchar2(128) := ''PESO_LIQUIDO_TOTAL'';',
'        l_campos_item apex_t_varchar2 := apex_t_varchar2(''ID_UNIDADEMEDIDA'',''QUANTIDADE'',''PESO_UNITARIO'',''ID_FABRICANTE'',''ID_NCM'',''SOMENTE_LEITURA_VALOR_UNITARIO'',''CONTROLE_ATRIBUIR_VALOR_ITEM'');',
'        l_atribuir_valor_quantidade clob;',
'        l_campos_quantidade apex_t_varchar2 := apex_t_varchar2(''PESO_LIQUIDO_TOTAL'',''VALOR_UNITARIO'');',
'        l_atribuir_valor_unificado clob;',
'        l_atribuir_valor_unitario clob;                ',
'        l_campos_valor_unitario apex_t_varchar2 := apex_t_varchar2(''VALOR_UNITARIO'',''SOMENTE_LEITURA_VALOR_UNITARIO'');        ',
'        l_valor_unitario number;',
'        l_id_item number;',
'        l_atribuir_valor_unidademedida clob;',
'        l_campos_unidademedida apex_t_varchar2 := apex_t_varchar2(''QUANTIDADE'',''VALOR_UNITARIO'',''SOMENTE_LEITURA_VALOR_UNITARIO'',''CONTROLE_ATRIBUIR_VALOR_UNIDADEMEDIDA'',''PERMITE_DECIMAIS'');',
'        v_json_dependecia_id_item clob;',
'        v_condicoes_id_item      array_varchar := array_varchar(''SOMENTE_LEITURA_VALOR_UNITARIO == %0%'',''SOMENTE_LEITURA_VALOR_UNITARIO == %1%'');',
'        v_colunas_alvo_id_item   array_varchar := array_varchar(''VALOR_UNITARIO'',''VALOR_UNITARIO'');',
'        v_comportamentos_id_item array_varchar := array_varchar(''hab'',''hab'');        ',
'        v_executa_js_digito clob;',
'        l_verifica_listapreco_item number;',
'        l_valor_slvu varchar2(1);',
'    begin',
'        l_consulta_item := ''select a.codigo_item || '''' - ''''||pkg_traducao.get_traducao(a.descricao_item) as d,  a.id as r from ng_item a join ng_item_produto b on b.id_item = a.id where a.ind_tipo_item = ''''P'''' order by 1'';',
'',
'        l_JSON_calcular_valor_total := gerar_json_lista(',
'            SYS.ODCIVARCHAR2LIST(''QUANTIDADE * (VALOR_UNITARIO - VALOR_DESCONTO_UNITARIO)'', ''QUANTIDADE * PESO_UNITARIO''),',
'            SYS.ODCIVARCHAR2LIST(l_campos_calcular_valor_quantidade, ''PESO_LIQUIDO_TOTAL'')',
'        );        ',
'',
'        l_JSON_calcular_peso_total := gerar_json_calcular_valor(',
'            '' QUANTIDADE * PESO_UNITARIO '',',
'            l_campos_calcular_peso_quantidade',
'        );',
'',
'        l_atribuir_valor_item := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_item'',',
'            l_campos_item',
'        );    ',
'        ',
'        l_atribuir_valor_quantidade := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_quantidade'',',
'            l_campos_quantidade',
'        );',
'',
'        l_atribuir_valor_unitario := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_unitario'',',
'            l_campos_valor_unitario',
'        );   ',
'        ',
'        l_atribuir_valor_unificado := unificar_jsons(SYS.ODCIVARCHAR2LIST(l_atribuir_valor_quantidade,l_atribuir_valor_unitario));',
'',
'        l_atribuir_valor_unidademedida := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_unidademedida'',',
'            l_campos_unidademedida',
'        );',
'        ',
'        v_json_dependecia_id_item := gerar_json_dependencias_array(v_condicoes_id_item, v_colunas_alvo_id_item, v_comportamentos_id_item);',
'',
'        prc_enviar_parametros(''TD607'',''id_unidademedida'',p_param1);',
'        v_executa_js_digito := ''atualizarDigitsCampo("QUANTIDADE","PERMITE_DECIMAIS")'';',
'',
'        select count(1) into l_verifica_listapreco_item',
'        from imp_pedidoimportacao_item a',
'        join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'        join ng_listapreco c on c.id = b.id_listapreco',
'        join ng_listapreco_item d on d.id_lista_preco = c.id and d.id_item_produto = a.id_item',
'        where a.id = p_param1;',
'',
'        if l_verifica_listapreco_item > 0 then',
'            l_valor_slvu := ''0'';',
'        else',
'            l_valor_slvu := ''1'';',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 5 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null dependencia, null atribuir_valor, null'
||' calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pedidoimportacao'',            2, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_ITEM'',                        3, ''POPTEX1'', to_char(l_consulta_item), ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_sequencia_item'',             1, ''TXT'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_UNIDADEMEDIDA'',               6, '''', null, ''N'', ''S'', null valor, null dependencia, l_atribuir_valor_unidademedida atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''QUANTIDADE'',                     8, '''', null, ''N'', ''S'', null valor, null dependencia, l_atribuir_valor_unificado atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PESO_UNITARIO'',                  9, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_JSON_calcular_peso_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PESO_LIQUIDO_TOTAL'',            10, '''', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''moeda'',                         11, ''TXT'', null, ''S'', ''N'', to_char((select codigo_moeda||'' - ''||simbolo_iso from imp_pedidoimportacao a join ng_moeda b on b.id = a.id_moeda join imp_pedidoimportacao_item c on'
||' c.id_pedidoimportacao = a.id where c.id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_UNITARIO'',                12, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_DESCONTO_UNITARIO'',       13, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_TOTAL'',                   14, '''', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_FABRICANTE'',                 15, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_NCM'',                        17, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_licenca_importacao'',        19, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_bloqueio_embarque_ate_deferimento_li'', 20, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naturezaoperacao'',           21, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_centrocusto'',                23, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_finalidade'',                25, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_ato_concessorio'',        26, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''num_solicitacao_compra'',        27, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_solicitante'',              28, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_entrega_desejada'',         29, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_programada_entrega'', 30, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_programar_entrega'',  31, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_faturada'',           32, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_cancelada'',          33, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_faturar'',            34, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''SOMENTE_LEITURA_VALOR_UNITARIO'',35, ''HID'', null, ''N'', ''N'', /*l_valor_slvu*/''1'' valor, v_json_dependecia_id_item dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                36, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''PERMITE_DECIMAIS'',              37, ''HID'', null, ''N'', ''N'', null valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js FROM dual UNION ALL',
'               /*SELECT p_codigo_artefato, ''CONTROLE_ATRIBUIR_VALOR_ITEM'',  36, ''HID'', null, ''N'', ''N'', ''0'' valor, null dependencia, null atribuir_valor, null calcular_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''CONTROLE_ATRIBUIR_VALOR_UNIDADEMEDIDA'', 37, ''HID'', null, ''N'', ''N'', ''0'' valor, null dependencia, null atribuir_valor, null calcular_valor FROM dual*/ ',
'               SELECT p_codigo_artefato, ''valor_desconto_pedido_item'',     38, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto_pedido_item_unitario'', 39, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesaproforma'',          40, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesaproforma_unitario'', 41, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_firmada'',             42, ''HID'', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, calcular_valor, executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.calcular_valor, new_data.executa_js);',
'    end formulario;',
