'    function sql_atribuir_valor_item(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'        l_controle_atribuir_valor_item varchar2(4000);',
'    begin',
'        -- l_controle_atribuir_valor_item := get_valor_campo_dinamico(''TD607'',''CONTROLE_ATRIBUIR_VALOR_ITEM'');',
'        -- if l_controle_atribuir_valor_item = ''0'' then',
'        --     l_sql := q''~',
'        --         select ',
'        --             concatena_id_texto(a.id_unidademedida,c.codigo_unidademedida) ID_UNIDADEMEDIDA, ',
'        --             a.quantidade QUANTIDADE,',
'        --             a.peso_unitario PESO_UNITARIO, ',
'        --             concatena_id_texto(a.id_fabricante,e.nome_fantasia) ID_FABRICANTE,                    ',
'        --             1 SOMENTE_LEITURA_VALOR_UNITARIO,',
'        --             1 CONTROLE_ATRIBUIR_VALOR_ITEM',
'        --         from imp_pedidoimportacao_item a',
'        --         join ng_item b on b.id = a.id_item',
'        --         left join ng_unidademedida c on c.id = a.id_unidademedida',
'        --         left join ng_pessoa d on d.id = a.id_fabricante',
'        --         left join ng_pessoa_juridica e on e.id_pessoa = d.id',
'        --         where a.id = #ID#                ',
'        --     ~'';',
'        --     l_sql := replace(l_sql,''#ID#'',apex_util.get_session_state(''P9010_ID''));',
'        -- elsif l_controle_atribuir_valor_item = ''1'' then',
'            l_sql := q''~ ',
'                select ',
'                    concatena_id_texto(c.id,c.codigo_unidademedida) ID_UNIDADEMEDIDA, ',
'                    0 QUANTIDADE,',
'                    PESO_UNITARIO, ',
'                    concatena_id_texto(b.id_fabricante,e.nome_fantasia) ID_FABRICANTE,',
'                    concatena_id_texto(b.id_ncm,f.codigo_ncm) ID_NCM,',
'                    1 SOMENTE_LEITURA_VALOR_UNITARIO,',
'                    1 CONTROLE_ATRIBUIR_VALOR_ITEM',
'                from ng_item a',
'                join ng_item_produto b on b.id_item = a.id',
'                left join ng_unidademedida c on c.id = a.id_unidademedida',
'                left join ng_pessoa d on d.id = b.id_fabricante',
'                left join ng_pessoa_juridica e on e.id_pessoa = d.id',
'                left join ng_ncm f on f.id = b.id_ncm',
'                where a.id = #ID#',
'                and get_valor_campo_dinamico(''TD607'',''CONTROLE_ATRIBUIR_VALOR_ITEM'') = 1',
'            ~'';',
'            l_sql := replace(l_sql,''#ID#'',p_param1);        ',
'        --end if;',
'        return l_sql;',
'    end sql_atribuir_valor_item;',
'',
'    function sql_atribuir_valor_quantidade(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := ''select (''||apex_application.g_f08(1)||'' * ''||apex_application.g_f09(1)||'') PESO_LIQUIDO_TOTAL from dual'';',
'        return nvl(replace(l_sql,''#ID#'',p_param1),''999'');',
'    end sql_atribuir_valor_quantidade;   ',
'',
'    -- function sql_atribuir_valor_unitario(p_param1 in varchar2) return clob is',
'    --     l_sql clob;',
'    -- begin',
'    --     l_sql := q''~ ',
'    --         select ',
'    --             preco_unitario as VALOR_UNITARIO,',
'    --             0 SOMENTE_LEITURA_VALOR_UNITARIO',
'    --         from IMP_PEDIDOIMPORTACAO a',
'    --         join NG_LISTAPRECO b on b.id = a.id_listapreco',
'    --         join NG_LISTAPRECO_ITEM c on c.id_lista_preco = b.id',
'    --         where a.id = #ID#',
'    --         and id_item_produto = get_id_campo_dinamico(''TD607'',''f04_0000'')',
'    --         and id_unidademedida = get_id_campo_dinamico(''TD607'',''f07_0000'')',
'    --         and qtd_minima <= get_valor_campo_dinamico(''TD607'',''QUANTIDADE'')            ',
'    --         order by qtd_minima desc',
'    --         fetch first 1 row only',
'    --     ~'';',
'    --     return replace(l_sql,''#ID#'',apex_util.get_session_state(''P9010_PARAMETRO2''));        ',
'    -- end sql_atribuir_valor_unitario;',
'',
'    function sql_atribuir_valor_unitario(p_param1 in varchar2) return clob is',
'        l_verifica_id_listapreco number;',
'        l_sql clob;',
'    begin        ',
'        select count(1) into l_verifica_id_listapreco ',
'        from imp_pedidoimportacao a ',
'        join ng_listapreco_item b on b.id_lista_preco = a.id_listapreco',
'        --join imp_pedidoimportacao_item c on c.id_pedidoimportacao = a.id ',
'        where a.id = apex_util.get_session_state(''P9010_PARAMETRO2'') ',
'        and b.id_item_produto = get_id_campo_dinamico(''TD607'',''f04_0000'')',
'        and b.id_unidademedida = get_id_campo_dinamico(''TD607'',''f07_0000'');',
'        ',
'        if l_verifica_id_listapreco > 0 then',
'            l_sql := q''~',
'                select VALOR_UNITARIO, SOMENTE_LEITURA_VALOR_UNITARIO',
'                    from (',
'                        select ',
'                            preco_unitario as VALOR_UNITARIO,',
'                            0 as SOMENTE_LEITURA_VALOR_UNITARIO,',
'                            0 as ordem',
'                        from imp_pedidoimportacao a',
'                        join ng_listapreco b on b.id = a.id_listapreco',
'                        join ng_listapreco_item c on c.id_lista_preco = b.id',
'                        where a.id = #ID#',
'                          and id_item_produto = get_id_campo_dinamico(''TD607'',''f04_0000'')',
'                          and id_unidademedida = get_id_campo_dinamico(''TD607'',''f07_0000'')',
'                          and qtd_minima <= get_valor_campo_dinamico(''TD607'',''QUANTIDADE'')',
'                        order by qtd_minima desc',
'                        fetch first 1 row only',
'                    )',
'                    union all',
'                    select valor_unitario, 1',
'                    from imp_pedidoimportacao_item',
'                    where not exists (',
'                        select 1',
'                        from imp_pedidoimportacao a',
'                        join ng_listapreco b on b.id = a.id_listapreco',
'                        join ng_listapreco_item c on c.id_lista_preco = b.id',
'                        where a.id = #ID#',
'                          and id_item_produto = get_id_campo_dinamico(''TD607'',''f04_0000'')',
'                          and id_unidademedida = get_id_campo_dinamico(''TD607'',''f07_0000'')',
'                          and qtd_minima <= get_valor_campo_dinamico(''TD607'',''QUANTIDADE'')',
'                    ) ',
'                    and id = #ID_ITEM#',
'            ~'';            ',
'        end if;',
'        l_sql := replace(l_sql,''#ID_ITEM#'',apex_util.get_session_state(''P9010_ID''));',
'        return replace(l_sql,''#ID#'',apex_util.get_session_state(''P9010_PARAMETRO2''));        ',
'    end sql_atribuir_valor_unitario;    ',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob is',
'        l_verifica_pedido_tem_listapreco number;        ',
'        l_verifica_item_esta_na_listapreco number;        ',
'        l_verifica_id_listapreco_item number;',
'        l_sql clob;        ',
'    begin',
'        select count(1) into l_verifica_pedido_tem_listapreco from imp_pedidoimportacao where id = apex_util.get_session_state(''P9010_PARAMETRO2'') and id_listapreco is not null;',
'        if l_verifica_pedido_tem_listapreco > 0 then            ',
'            select count(1) into l_verifica_item_esta_na_listapreco',
'            from imp_pedidoimportacao a ',
'            join ng_listapreco_item b on b.id_lista_preco = a.id_listapreco        ',
'            where a.id = apex_util.get_session_state(''P9010_PARAMETRO2'') ',
'            and b.id_item_produto = get_id_campo_dinamico(''TD607'',''f04_0000'');            ',
'            if l_verifica_item_esta_na_listapreco > 0 then',
'                select count(1) into l_verifica_id_listapreco_item',
'                from imp_pedidoimportacao a ',
'                join ng_listapreco_item b on b.id_lista_preco = a.id_listapreco        ',
'                where a.id = apex_util.get_session_state(''P9010_PARAMETRO2'') ',
'                and b.id_item_produto = get_id_campo_dinamico(''TD607'',''f04_0000'')',
'                and b.id_unidademedida = get_id_campo_dinamico(''TD607'',''f07_0000'');',
'                ',
'                if l_verifica_id_listapreco_item > 0 then   ',
'                    l_sql := q''~ ',
'                        select',
'                            case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 0 else a.quantidade end QUANTIDADE,',
'                            case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 0 else a.valor_unitario end VALOR_UNITARIO,',
'                            case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 1 else 0 end SOMENTE_LEITURA_VALOR_UNITARIO,',
'                            1 CONTROLE_ATRIBUIR_VALOR_UNIDADEMEDIDA,                    ',
'                            (select case when a1.ind_tipo_dado = ''D'' then 5 else 0 end from ng_unidademedida a1 where a1.id = #ID_UNIDADEMEDIDA#) PERMITE_DECIMAIS',
'                        from imp_pedidoimportacao_item a',
'                        join ng_unidademedida b on b.id = a.id_unidademedida',
'                        where a.id = #ID#',
'                   ~'';',
'                else',
'                    l_sql := q''~',
'                        select ',
'                            0 QUANTIDADE,                        ',
'                            0 VALOR_UNITARIO,',
'                            1 SOMENTE_LEITURA_VALOR_UNITARIO,',
'                            case ind_tipo_dado ',
'                                when ''D'' then 5',
'                            end PERMITE_DECIMAIS',
'                        from ng_unidademedida',
'                        where id = #ID_UNIDADEMEDIDA#',
'                    ~'';                    ',
'                end if;            ',
'            else',
'                l_sql := q''~',
'                    select',
'                        case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 0 else a.quantidade end QUANTIDADE,',
'                        case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 0 else a.valor_unitario end VALOR_UNITARIO,',
'                        1 SOMENTE_LEITURA_VALOR_UNITARIO,',
'                        1 CONTROLE_ATRIBUIR_VALOR_UNIDADEMEDIDA,                    ',
'                        (select case when a1.ind_tipo_dado = ''D'' then 5 else 0 end from ng_unidademedida a1 where a1.id = #ID_UNIDADEMEDIDA#) PERMITE_DECIMAIS',
'                    from imp_pedidoimportacao_item a',
'                    join ng_unidademedida b on b.id = a.id_unidademedida',
'                    where a.id = #ID#',
'                ~'';',
'            end if;',
'        else',
'        l_sql := q''~',
'                    select',
'                        case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 0 else a.quantidade end QUANTIDADE,',
'                        case when a.id_unidademedida <> #ID_UNIDADEMEDIDA# then 0 else a.valor_unitario end VALOR_UNITARIO,',
'                        1 SOMENTE_LEITURA_VALOR_UNITARIO,',
'                        1 CONTROLE_ATRIBUIR_VALOR_UNIDADEMEDIDA,                    ',
'                        (select case when a1.ind_tipo_dado = ''D'' then 5 else 0 end from ng_unidademedida a1 where a1.id = #ID_UNIDADEMEDIDA#) PERMITE_DECIMAIS',
'                    from imp_pedidoimportacao_item a',
'                    join ng_unidademedida b on b.id = a.id_unidademedida',
'                    where a.id = #ID#',
'                ~'';            ',
'        end if;',
'',
'        l_sql := replace(l_sql,''#ID#'',apex_util.get_session_state(''P9010_ID''));',
'        l_sql := replace(l_sql,''#ID_UNIDADEMEDIDA#'',p_param1);',
'        return l_sql;',
'    end sql_atribuir_valor_unidademedida;    ',
'',
'    function condicao_proximo(p_param1 in varchar2) return boolean is',
'        l_condicao1 number;',
'        l_condicao2 number;',
'    begin',
'        select count(1) into l_condicao1 from imp_pedidoimportacao_item where id_pedidoimportacao = p_param1;        ',
'        return l_condicao1 > 0;',
'    end condicao_proximo;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is        ',
'    begin        ',
'        bo_imp_pedidoimportacao_item.altera_pedidoimportacao_item(',
'            p_id_tenant => apex_application.g_f05(1),',
'            p_id_pedidoimportacao => apex_application.g_f02(1),',
'            p_id_item => apex_application.g_f03(1),',
'            p_num_sequencia_item => apex_application.g_f01(1),',
'            p_id_unidademedida => apex_application.g_f06(1),',
'            p_quantidade => pkg_util.retorna_number(apex_application.g_f08(1)),',
