'            p_valor_total => pkg_util.retorna_number(apex_application.g_f14(1)),',
'            p_id_fabricante => apex_application.g_f15(1),',
'            p_id_ncm => apex_application.g_f17(1),',
'            p_ind_licenca_importacao => apex_application.g_f19(1),',
'            p_ind_bloqueio_embarque_ate_deferimento_li => apex_application.g_f20(1),',
'            p_id_naturezaoperacao => apex_application.g_f21(1),',
