prompt --application/deployment/install/install_ui_mpd_td639
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(167433352781092448)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD639'
,p_sequence=>2740
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/06/2026',
unistr('-- Motivo: Inclus\00E3o das colunas ind_finalidade e numero_ato_concessorio no formul\00E1rio'),
'-- Jira: PEDITEM-25',
'',
'-- Objeto: UI_MPD_TD639',
'-- Data: 05/05/2026',
'-- Motivo: Ajuste para trazer os campos de consulta quantidade_cancelada e num_sequencia_item',
'-- Jira: PEDITEM-25',
'',
'create or replace package "UI_MPD_TD639" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);   ',
'',
'end "UI_MPD_TD639";',
'/',
'',
'create or replace package body "UI_MPD_TD639" as',
'    ',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao from imp_pedidoimportacao a join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is        ',
'        l_quantidade varchar2(4000);',
'        l_quantidade_cancelada varchar2(4000);',
'        l_vmle varchar2(4000);',
'    begin        ',
'        select',
'            case b.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade)',
'            end, ',
'            case b.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade_cancelada, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade_cancelada)',
'            end ',
'        into l_quantidade, l_quantidade_cancelada',
'        from imp_pedidoimportacao_item a        ',
'        left join ng_unidademedida b on b.id = a.id_unidademedida',
'        where a.id = p_param1;',
'',
'        select to_char(valor_total - valor_desconto_pedido_item + valor_despesaproforma, ''FM999G999G990D00000'') into l_vmle from imp_pedidoimportacao_item where id = p_param1;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 5 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pedidoimportacao'',            2, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_item'',                        3, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_sequencia_item'',             1, ''TXT'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',               6, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade'',                     8, ''TXT'', null, ''S'', ''N'', l_quantidade valor, ''imp_pedidoimportacao_item.quantidade'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_unitario'',                  9, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_liquido_total'',            10, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''moeda'',                         11, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''S'', ''N'', to_char((select a.id_moeda from imp_pedidoimportacao a join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a'
||'.id where b.id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_unitario'',                12, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto_unitario'',       13, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total'',                   14, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto_pedido_item'',    16, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''valor_despesaproforma'',         17, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''vmle'',                          18, ''TXT'', null, ''S'', ''N'', l_vmle valor, ''imp_processoimportacao_item.valor_total_condicao_venda'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fabricante'',                 19, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_ncm'',                        20, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_licenca_importacao'',        21, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_bloqueio_embarque_ate_deferimento_li'', 22, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_naturezaoperacao'',           23, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_cancelada'',          24, ''TXT'', null, ''S'', ''N'', l_quantidade_cancelada valor, ''imp_pedidoimportacao_item.quantidade_cancelada'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_centrocusto'',                25, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_finalidade'',                26, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_ato_concessorio'',        27, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_solicitacao_compra'',        28, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_solicitante'',              29, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_entrega_desejada'',         30, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_programada_entrega'', 31, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_programar_entrega'',  32, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_faturada'',           33, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''quantidade_faturar'',            34, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                35, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'end "UI_MPD_TD639";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1045
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(167435635882160491)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1045'
,p_sequence=>2750
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD1045 ',
'-- Data: 05/05/2026 ',
'-- Motivo: Desenvolvimento interface Tributos dos itens do processo',
'-- Jira: PEDITEM-310',
'',
'create or replace package "UI_MPD_TD1045" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob;',
'    ',
'end "UI_MPD_TD1045";',
'/',
'create or replace package body "UI_MPD_TD1045" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html_topo         clob;',
'        l_html_base         clob;',
'        l_html_recalculando clob;',
'        l_html_final        clob;',
'        l_ind_calculando imp_processoimportacao.ind_calculando_valores%type;',
'    begin',
unistr('        -- Verifica se o processo est\00E1 recalculando'),
'        select a.ind_calculando_valores into l_ind_calculando from imp_processoimportacao a where a.id = p_param1;',
'        if l_ind_calculando = ''S'' then',
'            l_html_recalculando :=',
'                ''<span style="',
'                    display:inline-block;',
'                    margin-left:8px;',
'                    color:#d32f2f;',
'                    font-weight:bold;',
'                    font-size:14px;',
'                    transform:translateY(8px);',
'                ">''|| pkg_ui.retorna_label_tela(''recalculando'') ||''</span>'';',
'        end if;',
'',
'        l_html_topo := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_processoimportacao,',
'                    b.codigo_moeda || '''' - '''' || b.simbolo_iso as id_moeda_tenant',
'                from imp_processoimportacao a',
'                join ng_moeda b on b.id = a.id_moeda_tenant',
'                where a.id = '' || p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato    => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe     => ''st-back-transparente''',
'        );',
'',
'        l_html_base := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    to_char(nvl(a.vmld, 0), ''''FM999G999G990D00'''') as vmld,',
'                    to_char(nvl(a.valor_ii, 0), ''''FM999G999G990D00'''') as valor_ii,',
'                    to_char(nvl(a.valor_ipi, 0), ''''FM999G999G990D00'''') as valor_ipi,',
'                    to_char(nvl(a.valor_pis, 0), ''''FM999G999G990D00'''') as valor_pis,',
'                    to_char(nvl(a.valor_cofins, 0), ''''FM999G999G990D00'''') as valor_cofins,',
'                    to_char(nvl(a.valor_cbs, 0), ''''FM999G999G990D00'''') as valor_cbs,',
'                    to_char(nvl(a.valor_ibs, 0), ''''FM999G999G990D00'''') as valor_ibs,',
'                    to_char(nvl(a.valor_icms, 0), ''''FM999G999G990D00'''') as valor_icms,',
'                    to_char(nvl(a.valor_icms_st, 0), ''''FM999G999G990D00'''') as valor_icms_st',
'                from imp_processoimportacao a',
'                where a.id = '' || p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimp'
||'ortacao''),',
'            p_formato    => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe     => ''st-back-transparente''',
'        );',
'',
'        l_html_final :=',
'            ''<div class="cabecalho-duplo">''',
'                || l_html_topo || nvl(l_html_recalculando, '''') || ''<br>''',
'                || l_html_base ||',
'            ''</div>'';',
'        return l_html_final;',
'    end sql_cabecalho;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                a.id,',
'                b.codigo_item titulo,  ',
'                corta_texto(pkg_traducao.get_traducao(b.descricao_item)) subtitulo,  ',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas((select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 1),',
'                    to_char(sum(case when nd.ind_tipo_despesa = 1 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) end), ''FM999G999G990D00''), 2, ''s''',
'                ) atributo1,',
'                pkg_componentes.html_card_colunas((select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 2),',
'                    to_char(sum(case when nd.ind_tipo_despesa = 2 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) end), ''FM999G999G990D00''), 2, ''s''',
'                ) atributo2,',
'                pkg_componentes.html_card_colunas((select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 3),',
'                    to_char(sum(case when nd.ind_tipo_despesa = 3 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) end), ''FM999G999G990D00''), 2, ''s''',
'                ) atributo3,',
'                pkg_componentes.html_card_colunas((select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 4),',
'                    to_char(sum(case when nd.ind_tipo_despesa = 4 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) end), ''FM999G999G990D00''), 2, ''s''',
'                ) atributo4,',
'                pkg_componentes.html_card_colunas((select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 18),',
'                    to_char(sum(case when nd.ind_tipo_despesa = 18 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) end), ''FM999G999G990D00''), 2, ''s''',
'                ) atributo5,',
'                pkg_componentes.html_card_colunas((select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 19),',
'                    to_char(sum(case when nd.ind_tipo_despesa = 19 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) end), ''FM999G999G990D00''), 2, ''s''',
'                ) atributo6,',
'                --FILTROS',
'                null filtro1,                ',
'                null filtro2,',
'                null filtro3,',
'                null filtro4,',
'                null filtro5,',
'                null filtro6,',
'                null filtro7,',
'                null filtro8,',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD1045'',a.id) url_mais_detalhes,                ',
'                pkg_componentes.html_botao_opcao(a.id,''TD1045'') as opcao                ',
'            from imp_processoimportacao_item a',
'            join ng_item b on b.id = a.id_item',
'            left join imp_processoimportacao_item_despesa d on d.id_processoimportacao_item = a.id',
'            left join imp_processoimportacao_despesa pd on pd.id = d.id_processoimportacao_despesa',
'            left join ng_despesa nd on nd.id = pd.id_despesa',
'            where a.id_processoimportacao = #PARAM1#',
'            group by',
'                a.id,',
'                b.codigo_item,',
'                corta_texto(pkg_traducao.get_traducao(b.descricao_item))',
'            order by 3',
'        ~'';       ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;                    ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,  ',
'            b.codigo_item campo1,',
'            corta_texto(pkg_traducao.get_traducao(b.descricao_item)) campo2,',
'            -- II',
'            to_char(sum(case when nd.ind_tipo_despesa = 1 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo3,',
'            -- IPI',
'            to_char(sum(case when nd.ind_tipo_despesa = 2 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo4,',
'            -- PIS',
'            to_char(sum(case when nd.ind_tipo_despesa = 3 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo5,',
'            -- COFINS',
'            to_char(sum(case when nd.ind_tipo_despesa = 4 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo6,',
'            -- CBS',
'            to_char(sum(case when nd.ind_tipo_despesa = 18 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo7,',
'            -- IBS',
'            to_char(sum(case when nd.ind_tipo_despesa = 19 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo8,',
'            -- ICMS',
'            to_char(sum(case when nd.ind_tipo_despesa = 5 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo9,',
'            -- ICMS-ST',
'            to_char(sum(case when nd.ind_tipo_despesa = 6 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end), ''FM999G999G990D00'') campo10,',
'            --FILTROS',
'            null filtro1,                ',
'            null filtro2,',
'            null filtro3,            ',
'            null filtro4,',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,',
'            null opcao',
'        from imp_processoimportacao_item a',
'        join ng_item b on b.id = a.id_item',
'        left join imp_processoimportacao_item_despesa d on d.id_processoimportacao_item = a.id',
'        left join imp_processoimportacao_despesa pd on pd.id = d.id_processoimportacao_despesa',
'        left join ng_despesa nd on nd.id = pd.id_despesa',
'        where a.id_processoimportacao = #PARAM1#',
'        group by',
'            a.id,',
'            b.codigo_item,',
'            corta_texto(pkg_traducao.get_traducao(b.descricao_item))',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD1045'') as opcao                ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_processoimportacao_item'')) a',
'            order by campo2',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        -- if campo = ''1'' then',
'        --     return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        -- else',
'            return null;',
'        -- end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where r = 1;',
'        elsif campo = ''4'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 2;',
'        elsif campo = ''5'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 3;',
'        elsif campo = ''6'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 4;',
'        elsif campo = ''7'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 18;',
'        elsif campo = ''8'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 19;',
'        elsif campo = ''9'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 5;',
'        elsif campo = ''10'' then',
'            select d into l_campo from table(pkg_util.dominio_retorna_lista(''ng_despesa'',''ind_tipo_despesa'')) where r = 6;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        null;',
'    end campos_ordenacao;',
'',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob',
'    is',
'        l_modo_refresh varchar2(30);',
'        l_id_processoimportacao number;',
'    begin',
'        l_modo_refresh := upper(nvl(p_modo_refresh, ''ONCE''));',
'        l_id_processoimportacao := apex_util.get_session_state(''P9005_PARAMETRO'');',
'',
'        return q''~ ',
'            select case',
'                when exists (',
'                    select 1 from imp_processoimportacao a where a.id = ~'' || l_id_processoimportacao || q''~ and nvl(a.ind_calculando_valores,''N'') = ''N''',
'                    )',
'                    then ''S''',
'                    else ''N''',
'                end as atualizar,',
'                ''~'' || l_modo_refresh || q''~'' as modo_refresh',
'            from dual',
'        ~'';',
'    end sql_auto_refresh;',
'',
'end "UI_MPD_TD1045";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td776
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(173985295336799289)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD776'
,p_sequence=>2760
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD776 ',
'-- Data: 07/05/2026 ',
'-- Motivo: Ajuste de campos Exportador e Importados para exibir nome_fantasia ',
'-- Jira: PEDITEM-38',
'',
'create or replace package "UI_MPD_TD776" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD776";',
'/',
'create or replace package body "UI_MPD_TD776" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.numero_pedido_importacao as numero_pedido_importacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_pedidoimportacao'''', ''''ind_todos_itens_com_entregas_programadas'''', a.ind_todos_itens_com_entregas_programadas) as ind_todos_itens',
'                from imp_pedidoimportacao a',
'                where a.id = '' || p_param1,',
'            --p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_label_fixo => textarray(''imp_pedidoimportacao.numero_pedido_importacao'',''imp_pedidoimportacao.ind_todos_itens_com_entregas_programadas''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'        l_url varchar2(4000);',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                CASE WHEN a.id_processoimportacao is null THEN pkg_componentes.html_cor_texto(''~'' || retorna_texto(''msg.93.l'') || q''~'') else i.num_processoimportacao END titulo,',
'                b.numero_pedido_importacao  subtitulo,',
'                bo_ng_viatransporte.retorna_icone_viatransporte_card(a.id_viatransporte) icon,',
'                pkg_util.dominio_retorna_tag(''imp_entrega'', ''ind_status_entrega'', a.ind_status_entrega) distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_entrega.num_entrega'', a.num_entrega, 2) atributo1,                ',
'                pkg_componentes.html_card_colunas(''imp_entrega.id_exportador'', e.nome_fantasia, 2) atributo2,  ',
'                pkg_componentes.html_card_colunas(''imp_entrega.id_importador'', g.nome_fantasia, 2) atributo3,   ',
'                pkg_componentes.html_card_colunas(''imp_entrega.id_local_embarque'',pkg_traducao.get_traducao(j.nome_local), 2',
'                ) atributo4, ',
'                pkg_componentes.html_card_colunas(''imp_entrega.id_local_desembarque'',pkg_traducao.get_traducao(h.nome_local), 2',
'                ) atributo5,',
'                --FILTROS',
'                null filtro1,                ',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD776'',a.id) url_mais_detalhes,                ',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD776'', p_param1 => b.id) as opcao                ',
'            from imp_entrega a',
'            JOIN imp_pedidoimportacao b ON b.id = a.id_pedidoimportacao',
'            JOIN ng_viatransporte c ON c.id = a.id_viatransporte',
'            JOIN ng_pessoa_juridica e ON e.id_pessoa = a.id_exportador',
'            JOIN ng_pessoa_juridica g ON g.id_pessoa = a.id_importador',
'            JOIN mpd_tenant h on h.id = a.id_tenant',
'            left join imp_processoimportacao  i ON i.id = a.id_processoimportacao',
'            left join ng_localembarquedesembarque j on j.id = a.id_local_embarque',
'            left join ng_localembarquedesembarque h on h.id = a.id_local_desembarque',
'            where a.id_pedidoimportacao = ~'' || p_param1 || q''~',
'            order by 2,3,7',
'            ~'';            ',
'            --l_sql := replace(l_sql, ''#URL#'', nvl(l_url, ''null''));',
'            return l_sql;                    ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := ''',
'        select distinct',
'            a.id id,  ',
'            pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', a.ind_status_entrega) campo1,',
'            CASE        ',
'                WHEN a.id_processoimportacao is null THEN',
'                    pkg_componentes.html_cor_texto(''''''||',
'                retorna_texto(''msg.93.l'')||'''''')',
'                ELSE',
'                   i.num_processoimportacao',
'            END campo2,',
'            b.numero_pedido_importacao campo3,',
'            a.num_entrega campo4,',
'            pkg_util.dominio_retorna_tag(''''ng_viatransporte'''',''''descricao_viatransporte'''',descricao_viatransporte) campo5,',
'            e.nome_fantasia campo6,',
'            g.nome_fantasia campo7,',
'            pkg_traducao.get_traducao(m.nome_local) campo8,',
'            pkg_traducao.get_traducao(n.nome_local) campo9,',
'            null campo10,            ',
'            --FILTROS',
'            null filtro1,                ',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            null opcao',
'        from imp_entrega a',
'        JOIN imp_pedidoimportacao b ON b.id = a.id_pedidoimportacao',
'        JOIN ng_viatransporte c ON c.id = a.id_viatransporte',
'        JOIN ng_pessoa_juridica e ON e.id_pessoa = a.id_exportador',
'        JOIN ng_pessoa_juridica g ON g.id_pessoa = a.id_importador ',
'        left join imp_processoimportacao  i ON i.id = a.id_processoimportacao',
'        join table(pkg_util.dominio_retorna_lista(''''ng_viatransporte'''',''''icone_viatransporte'''')) h on h.r = c.icone_viatransporte  ',
'        left join ng_localembarquedesembarque m on m.id = a.id_local_embarque',
'        left join ng_localembarquedesembarque n on n.id = a.id_local_desembarque',
'        where a.id_pedidoimportacao = ''||p_param1; ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD776'', p_param1 => a.id) as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_entrega'')) a',
'            order by campo2, campo3, campo4',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        IF CAMPO in (''1'',''F2'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.ind_status_entrega'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''2'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_processoimportacao'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''3'' THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_pedidoimportacao'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO = ''4'' THEN                        ',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.num_entrega'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO in (''5'',''F5'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_viatransporte'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO in (''6'',''F3'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_exportador'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO in (''7'',''F4'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_importador'') INTO L_CAMPO FROM DUAL;',
'        ELSIF CAMPO in (''8'',''F6'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_local_embarque'') INTO L_CAMPO FROM DUAL;  ',
'        ELSIF CAMPO in (''9'',''F7'') THEN',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.id_local_desembarque'') INTO L_CAMPO FROM DUAL;  ',
'        ELSIF CAMPO = ''F1'' then                     ',
'            SELECT PKG_UI.RETORNA_LABEL_COLUNA(''IMP_ENTREGA.ID_TENANT'') INTO L_CAMPO FROM DUAL;  ',
'        END IF;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''id_processoimportacao,id_pedidoimportacao,num_entrega'';',
'        else',
'            campos := ''campo2, campo3, campo4'';',
'        end if;',
'        labels := label_coluna(''2'')||'',''||label_coluna(''3'')||'',''||label_coluna(''4'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD776";',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_ng_cidade
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(175191399428159392)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_NG_CIDADE'
,p_sequence=>2770
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package            bo_ng_cidade ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old ng_cidade%rowtype;',
'    v_new ng_cidade%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao ng_cidade.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
