unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out ng_cidade.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into ng_cidade (  ',
'            id_tenant,',
'            nome_cidade,',
'            id_estado,',
'            id_pais,',
'            data_fim_vigencia, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_tenant,',
'            v_new.nome_cidade,',
'            v_new.id_estado,',
'            v_new.id_pais,',
'            v_new.data_fim_vigencia, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in ng_cidade.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''In\00EDcio da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de alterar */ ',
'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update ng_cidade set  ',
'            id_tenant = v_new.id_tenant,',
'            nome_cidade = v_new.nome_cidade,',
'            id_estado = v_new.id_estado,',
'            id_pais = v_new.id_pais,',
'            data_fim_vigencia = v_new.data_fim_vigencia, ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'        --',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''Fim da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end grava;',
'    --',
'    procedure inclui_registro(  ',
'        p_id_tenant in ng_cidade.id_tenant%type,',
'        p_nome_cidade in ng_cidade.nome_cidade%type,',
'        p_id_estado in ng_cidade.id_estado%type,',
'        p_id_pais in ng_cidade.id_pais%type,',
'        p_data_fim_vigencia in ng_cidade.data_fim_vigencia%type, ',
'        p_id out ng_cidade.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''inclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da inclus\00E3o de registro'''),
'        );',
'        v_parametro(0) := ''bo_ng_cidade.inclui_registro'';   ',
'        v_pagina := p_pagina; ',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.nome_cidade := p_nome_cidade;',
'        v_new.id_estado := p_id_estado;',
'        v_new.id_pais := p_id_pais;',
'        v_new.data_fim_vigencia := p_data_fim_vigencia; ',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao := sysdate; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate; ',
'        v_new.id := null;',
'        --',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);      ',
'        --                   ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''inclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da inclus\00E3o de registro'''),
'        );',
'    end inclui_registro; ',
'    --',
'    procedure altera_registro(  ',
'        p_id_tenant in ng_cidade.id_tenant%type,',
'        p_nome_cidade in ng_cidade.nome_cidade%type,',
'        p_id_estado in ng_cidade.id_estado%type,',
'        p_id_pais in ng_cidade.id_pais%type,',
'        p_data_fim_vigencia in ng_cidade.data_fim_vigencia%type, ',
'        p_id in ng_cidade.id%type, ',
'        p_data_alteracao in ng_cidade.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_cidade.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_cidade where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.nome_cidade := p_nome_cidade;',
'        v_new.id_estado := p_id_estado;',
'        v_new.id_pais := p_id_pais;',
'        v_new.data_fim_vigencia := p_data_fim_vigencia; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out ng_cidade.id_tenant%type,',
'        p_nome_cidade out ng_cidade.nome_cidade%type,',
'        p_id_estado out ng_cidade.id_estado%type,',
'        p_id_pais out ng_cidade.id_pais%type,',
'        p_data_fim_vigencia out ng_cidade.data_fim_vigencia%type, ',
'        p_id in out ng_cidade.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_cidade.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            nome_cidade,',
'            id_estado,',
'            id_pais,',
'            data_fim_vigencia, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_nome_cidade,',
'            p_id_estado,',
'            p_id_pais,',
'            p_data_fim_vigencia, ',
'            p_id ',
'        from ng_cidade ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in ng_cidade.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_cidade.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_cidade where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from ng_cidade where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_cidade'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_cidade'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in ng_cidade.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from ng_cidade where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in ng_cidade.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from ng_cidade where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in ng_cidade.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''ng_cidade'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''ng_cidade'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in ng_cidade.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo nome_cidade */ '),
'        valida_nome_cidade(v_new.nome_cidade);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_estado */ '),
'        valida_id_estado(v_new.id_estado);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_pais */ '),
'        valida_id_pais(v_new.id_pais);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_fim_vigencia */ '),
'        valida_data_fim_vigencia(v_new.data_fim_vigencia);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in ng_cidade.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_nome_cidade(p_nome_cidade in ng_cidade.nome_cidade%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_nome_cidade is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.nome_cidade''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''nome_cidade'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from ng_cidade where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_pais)) = lower(trim(v_new.id_pais)) and lower(trim(id_estado)) = lower(trim(v_new.id_estado)) and low'
||'er(trim(nome_cidade)) = lower(trim(v_new.nome_cidade)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from ng_cidade where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_pais)) = lower(trim(v_new.id_pais)) and lower(trim(id_estado)) = lower(trim(v_new.id_estado)) and low'
||'er(trim(nome_cidade)) = lower(trim(v_new.nome_cidade)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.nome_cidade'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''nome_cidade'',',
'                p_parametro => v_parametro,',
''))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(175191399428159392)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_nome_cidade(p_nome_cidade);',
'    end valida_nome_cidade;     ',
'',
'    procedure valida_id_estado(p_id_estado in ng_cidade.id_estado%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_estado is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.id_estado''); ',
'        --Verifica formato se houver',
'        end if;   ',
'',
'        hook_valida_id_estado(p_id_estado);',
'    end valida_id_estado;    ',
'',
'    procedure valida_id_pais(p_id_pais in ng_cidade.id_pais%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_pais is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.id_pais''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_pais'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_pais(p_id_pais);',
'    end valida_id_pais;     ',
'',
'    procedure valida_data_fim_vigencia(p_data_fim_vigencia in ng_cidade.data_fim_vigencia%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_data_fim_vigencia is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.data_fim_vigencia''); ',
'         else ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_cidade.data_fim_vigencia'');                         ',
'            pkg_util.valida_formato_data(',
'                p_data     => p_data_fim_vigencia,',
'                p_campo           => ''data_fim_vigencia'',',
'                p_parametro       => v_parametro,',
'                p_pagina          => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            if v_message.mensagem is not null then',
unistr('                -- Inserir o registro na cole\00E7\00E3o                '),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;                        ',
'            end if; ',
'',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_data_fim_vigencia(p_data_fim_vigencia);',
'    end valida_data_fim_vigencia;    ',
'',
'    --  ',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_cidade'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_cidade'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_cidade'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_cidade'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_cidade'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_cidade'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_cidade%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''nome_cidade'', p_rec.nome_cidade, true);',
'        apex_json.write(''id_estado'', p_rec.id_estado, true);',
'        apex_json.write(''id_pais'', p_rec.id_pais, true);',
'        apex_json.write(''data_fim_vigencia'', p_rec.data_fim_vigencia, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.nome_cidade,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.nome_cidade,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end;',
'    function detalhe_registro (',
'        p_id in ng_cidade.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                b.nome_fantasia as ng_cidade$id_tenant,',
'                pkg_traducao.get_traducao(a.nome_cidade) as ng_cidade$nome_cidade,',
'                pkg_traducao.get_traducao(c.nome_estado) as ng_cidade$id_estado,',
'                pkg_traducao.get_traducao(d.nome_pais) as ng_cidade$id_pais',
'            from ng_cidade a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_estado c on c.id = a.id_estado',
'            join ng_pais d on d.id = a.id_pais',
'            where a.id = ~''||p_id);',
'    end detalhe_registro; ',
'',
'',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_id_tenant(p_id_tenant in ng_cidade.id_tenant%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_tenant;     ',
'',
'    procedure hook_valida_nome_cidade(p_nome_cidade in ng_cidade.nome_cidade%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_nome_cidade;     ',
'',
'    procedure hook_valida_id_estado(p_id_estado in ng_cidade.id_estado%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_estado;     ',
'',
'    procedure hook_valida_id_pais(p_id_pais in ng_cidade.id_pais%type) ',
'    is ',
'        l_id_pais number;',
'    begin ',
'        select id_registro into l_id_pais from mpd_configuracao_ng where id_tenant = v_new.id_tenant and codigo_configuracao = 1;',
'        if l_id_pais = v_new.id_pais and v_new.id_estado is null then',
'                pkg_mensagem.mensagem_campo(',
'                    p_codigo_mensagem => 221,',
'                    p_nome_campo => ''id_estado'',',
'                    p_parametro => v_parametro,',
'                    p_pagina => v_pagina,',
'                    p_objeto_mensagem => v_message',
'                );   ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message; ',
'        end if;',
'    end hook_valida_id_pais;     ',
'',
'    procedure hook_valida_data_fim_vigencia(p_data_fim_vigencia in ng_cidade.data_fim_vigencia%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_data_fim_vigencia;   ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_cidade;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td690
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(175192213823132291)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD690'
,p_sequence=>2780
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: BO_IMP_ENTREGA_ITEM ',
'-- Data: 07/05/2026 ',
unistr('-- Motivo: inclus\00E3o de campo num_item'),
'-- Jira: IMP00068_entrega_detalhes_item',
'',
'create or replace package "UI_MPD_TD690" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD690";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD690" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select                ',
'                a.numero_pedido_importacao,',
'                b.num_entrega,',
'                    case when b.id_processoimportacao is null then',
'                        pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                        else d.num_processoimportacao',
'                    end id_processoimportacao',
'            from ',
'            imp_entrega b',
'            JOIN imp_pedidoimportacao a ON a.id = b.id_pedidoimportacao',
'            left join imp_processoimportacao d ON d.id = b.id_processoimportacao',
'            where b.id =  ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'-- ''    case ',
'--                 when c.qtd_decimais = 0 then',
'--                     replace(to_char(a.Valor_atributo_valor, ''''FM999999999990''''), ''''.'''', '''''''')',
'--                 else',
'--                     replace(',
'--                         to_char(',
'--                             a.Valor_atributo_valor,',
'--                             ''''FM999999999990D'''' || rpad(''''0'''', c.qtd_decimais, ''''0'''')',
'--                         ),',
'--                         ''''.'''',',
'--                         '''',''''',
'--                     )',
'--             end,',
'--             (select pkg_traducao.get_traducao(descricao_dominio) ',
'--                from ng_atributoitem_dominio ',
'--               where id = a.Valor_atributo_dominio)',
'--              ) as campo2,''',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                pkg_traducao.get_traducao(b.descricao_item) titulo,',
'                b.codigo_item subtitulo,                ',
'                c.codigo_unidademedida distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.num_sequencia_item'', f.num_sequencia_item, 2) atributo1,',
'                pkg_componentes.html_card_colunas(''imp_entrega_item.id_unidademedida'', c.codigo_unidademedida, 2) atributo2,',
'                pkg_componentes.html_card_colunas(''imp_entrega_item.quantidade'', case c.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade)',
'            end, 2) atributo3,',
'                pkg_componentes.html_card_colunas(''imp_entrega_item.peso_liquido_total'', to_char(a.peso_liquido_total, ''FM999G999G990D000''), 2) atributo4,',
'                pkg_componentes.html_card_colunas(''imp_entrega_item.valor_total_condicao_venda'', to_char(a.valor_total_condicao_venda, ''FM999G999G990D00''), 2) atributo5,',
'                --FILTROS                ',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD690'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD690'') as opcao                ',
'            from imp_entrega_item a',
'            join ng_item b on b.id = a.id_item',
'            join ng_unidademedida c on c.id = a.id_unidademedida',
'            join imp_pedidoimportacao_item f on f.id = a.id_pedidoimportacao_item',
'            where a.id_entrega = #PARAM1#',
'            order by 10',
'        ~'';       ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select distinct',
'            a.id id,  ',
'            f.num_sequencia_item campo1,',
'            b.codigo_item campo2,',
'            pkg_traducao.get_traducao(b.descricao_item) campo3,',
'            d.codigo_ncm campo4,',
'            case c.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade)',
'            end campo5,',
'            c.codigo_unidademedida campo6,',
'            to_char(a.peso_liquido_total, ''FM999G999G990D000'') campo7,',
'            to_char(a.valor_total_condicao_venda, ''FM999G999G990D00'') campo8,',
'            null campo9,',
'            #PARAM1# campo10,',
'            --FILTROS',
'            null filtro1,',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            null opcao',
'        from imp_entrega_item a',
'        join ng_item          b on b.id = a.id_item',
'        join ng_unidademedida c on c.id = a.id_unidademedida',
'        join ng_ncm           d on d.id = a.id_ncm',
'        join imp_entrega e on e.id = a.id_entrega',
'        join imp_pedidoimportacao_item f on f.id = a.id_pedidoimportacao_item',
'        where  a.id_entrega = #PARAM1#',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'        --     pkg_componentes.html_botao_opcao(a.id,''TD690'') as opcao ',
'        --     from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_pedidoimportacao_item'')) a',
'            ',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD690'', p_param1 => campo10) as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_entrega_item'')) a',
'            order by campo7',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;   ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'         if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.num_sequencia_item'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega_item.id_ncm'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega_item.quantidade'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega_item.id_unidademedida'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega_item.peso_liquido_total'') into l_campo from dual;',
'        elsif campo = ''8'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_entrega_item.valor_total_condicao_venda'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia, nome_fantasia'';',
'        else',
'            campos := ''campo5, campo2'';',
'        end if;',
'        labels := label_coluna(''5'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD690";',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_imp_processoimportacao_despesa
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(181596616317370846)
