'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Jonathan',
'-- Data: 29/05/2026',
unistr('-- Motivo: Ajustes para alterar tributos do processo de importa\00E7\00E3o'),
'-- Jira: PEDITEM-311',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 27/05/2026',
unistr('-- Motivo: Excluido os valores \00FAnicos da tabela'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/05/2026',
unistr('-- Motivo: Inclu\00EDdo campo ng_despesa.ind_tipo_despesa como consulta na fun\00E7\00E3o detalhe_registro'),
'-- Jira: PEDITEM-92',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/05/2026',
unistr('-- Motivo: Ajustado regra de valor \00FAnico para o \00EDndice composto'),
'-- Jira: PEDITEM-91',
'',
'-- Objeto: BO_IMP_PROCESSOIMPORTACAO_DESPESA',
'-- Data: 25/05/2026',
unistr('-- Motivo: Incluso colunas na tabela e regras de neg\00F3cio \201Cid_despesa\201D,  \201Cind_status_despesa\201D'),
'-- Jira: PEDITEM-162',
'',
'-- Objeto: BO_IMP_PROCESSOIMPORTACAO_DESPESA',
'-- Data: 20/05/2026',
unistr('-- Motivo: Altera\00E7\00F5es para chamar o MAESTRO'),
'-- Jira: PEDITEM-92/PEDITEM-93/PEDITEM-94',
'',
'-- Objeto: BO_IMP_PROCESSOIMPORTACAO_DESPESA',
'-- Data: 12/05/2026',
unistr('-- Motivo: Altera\00E7\00F5es para atender valida\00E7\00F5es no artefato TD839'),
'-- Jira: PEDITEM-239',
'',
'-- Objeto: BO_IMP_PROCESSOIMPORTACAO_DESPESA',
'-- Data: 11/05/2026',
unistr('-- Motivo: Altera\00E7\00F5es em regras de neg\00F3cio'),
'-- Jira: PEDITEM-162',
'',
'create or replace package            bo_imp_processoimportacao_despesa ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old imp_processoimportacao_despesa%rowtype;',
'    v_new imp_processoimportacao_despesa%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao imp_processoimportacao_despesa.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_processoimportacao_despesa.id%type',
'    );',
'    procedure grava(',
'        p_id in imp_processoimportacao_despesa.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(  ',
'        p_id_tenant in imp_processoimportacao_despesa.id_tenant%type,',
'        p_id_documento_despesa in imp_processoimportacao_despesa.id_documento_despesa%type,',
'        p_id_processoimportacao in imp_processoimportacao_despesa.id_processoimportacao%type,',
'        p_id_numerario_despesa in imp_processoimportacao_despesa.id_numerario_despesa%type,',
'        p_id_despesa in imp_processoimportacao_despesa.id_despesa%type,',
'        p_id_moeda_prevista in imp_processoimportacao_despesa.id_moeda_prevista%type,',
'        p_valor_previsto in imp_processoimportacao_despesa.valor_previsto%type,',
'        p_id_moeda_realizada in imp_processoimportacao_despesa.id_moeda_realizada%type,',
'        p_valor_realizado in imp_processoimportacao_despesa.valor_realizado%type,',
'        p_taxa_cambio in imp_processoimportacao_despesa.taxa_cambio%type,',
'        p_ind_status_despesa in imp_processoimportacao_despesa.ind_status_despesa%type,',
'        p_ind_status_pagamento in imp_processoimportacao_despesa.ind_status_pagamento%type,',
'        p_id_moeda_documento in imp_processoimportacao_despesa.id_moeda_documento%type,',
'        p_valor_moeda_documento in imp_processoimportacao_despesa.valor_moeda_documento%type,',
'        p_valor_moeda_nacional in imp_processoimportacao_despesa.valor_moeda_nacional%type,',
'        p_ind_forma_rateio in imp_processoimportacao_despesa.ind_forma_rateio%type, ',
'        p_ind_compoe_custo_operacao in imp_processoimportacao_despesa.ind_compoe_custo_operacao%type, ',
'        p_ind_participa_nfe in imp_processoimportacao_despesa.ind_participa_nfe%type,',
'        p_ind_despesa_base_calculo in imp_processoimportacao_despesa.ind_despesa_base_calculo%type, ',
'        p_ind_tipo_despesa in imp_processoimportacao_despesa.ind_tipo_despesa%type, ',
'        p_id out imp_processoimportacao_despesa.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure altera_registro(  ',
'        p_id_tenant in imp_processoimportacao_despesa.id_tenant%type,',
'        p_id_documento_despesa in imp_processoimportacao_despesa.id_documento_despesa%type,',
'        p_id_processoimportacao in imp_processoimportacao_despesa.id_processoimportacao%type,',
'        p_id_numerario_despesa in imp_processoimportacao_despesa.id_numerario_despesa%type,',
