'create or replace package body            bo_imp_processoimportacao_despesa',
'is',
unistr('    -- Vers\00E3o 2.4.1 do BO'),
'    --',
unistr('    -- Fun\00E7\00F5es CRUD'),
'    --',
'    procedure cria(',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_processoimportacao_despesa.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_processoimportacao_despesa'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;',
'        --',
'        /* Executa insert */',
'        insert into imp_processoimportacao_despesa (',
'            id_tenant,',
'            id_documento_despesa,',
'            id_processoimportacao,',
'            id_numerario_despesa,',
'            id_despesa,',
'            id_moeda_prevista,',
'            valor_previsto,',
'            id_moeda_realizada,',
'            valor_realizado,',
'            taxa_cambio,',
'            ind_status_despesa,',
'            ind_status_pagamento,',
'            id_moeda_documento,',
'            valor_moeda_documento,',
'            valor_moeda_nacional,',
'            ind_forma_rateio,',
'            ind_compoe_custo_operacao,',
'            ind_participa_nfe,',
'            ind_despesa_base_calculo,',
'            ind_tipo_despesa,',
'            id,',
'            id_usuario_incluiu,',
'            data_inclusao,',
'            id_usuario_alterou,',
'            data_alteracao',
'        ) values (',
'            v_new.id_tenant,',
'            v_new.id_documento_despesa,',
'            v_new.id_processoimportacao,',
'            v_new.id_numerario_despesa,',
'            v_new.id_despesa,',
'            v_new.id_moeda_prevista,',
'            v_new.valor_previsto,',
