unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_despesa'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_despesa'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_despesa'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_despesa'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_despesa'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_despesa'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;',
'    --',
'    function row_to_json(p_rec in imp_processoimportacao_despesa%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_documento_despesa'', p_rec.id_documento_despesa, true);',
'        apex_json.write(''id_processoimportacao'', p_rec.id_processoimportacao, true);',
'        apex_json.write(''id_numerario_despesa'', p_rec.id_numerario_despesa, true);',
'        apex_json.write(''id_despesa'', p_rec.id_despesa, true);',
'        apex_json.write(''id_moeda_prevista'', p_rec.id_moeda_prevista, true);',
'        apex_json.write(''valor_previsto'', p_rec.valor_previsto, true);',
'        apex_json.write(''id_moeda_realizada'', p_rec.id_moeda_realizada, true);',
'        apex_json.write(''valor_realizado'', p_rec.valor_realizado, true);',
'        apex_json.write(''taxa_cambio'', p_rec.taxa_cambio, true);',
'        apex_json.write(''ind_status_despesa'', p_rec.ind_status_despesa, true);',
'        apex_json.write(''ind_status_pagamento'', p_rec.ind_status_pagamento, true);',
'        apex_json.write(''id_moeda_documento'', p_rec.id_moeda_documento, true);',
'        apex_json.write(''valor_moeda_documento'', p_rec.valor_moeda_documento, true);',
'        apex_json.write(''valor_moeda_nacional'', p_rec.valor_moeda_nacional, true);',
'        apex_json.write(''ind_forma_rateio'', p_rec.ind_forma_rateio, true);',
'        apex_json.write(''ind_compoe_custo_operacao'', p_rec.ind_compoe_custo_operacao, true);',
'        apex_json.write(''ind_participa_nfe'', p_rec.ind_participa_nfe, true);',
'        apex_json.write(''ind_despesa_base_calculo'', p_rec.ind_despesa_base_calculo, true);',
'        apex_json.write(''ind_tipo_despesa'', p_rec.ind_tipo_despesa, true);',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;',
'',
