unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
'    --',
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
unistr('        -- Regra de atribui\00E7\00E3o de valor para a coluna valor_moeda_nacional:'),
'        atribui_valor_moeda_nacional;',
'        --',
'    end;',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'        l_ind_tipo_despesa number;',
'        l_id number;        ',
'    begin',
'        -- v_operacao = ''COTACAO'' esta vindo la do declaracao_cotacao',
'        if v_operacao = ''COTACAO'' then',
'            v_operacao := null;',
'            return;',
'        end if;',
'        atualiza_processoimportacao_item_tributo(v_new.id_processoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'        -- Verificar utilidade:',
'        -- altera_processoimportacao_tributos(',
'        --     p_id_processoimportacao => v_new.id_processoimportacao,',
'        --     p_pagina                => v_pagina,',
'        --     p_encadeado             => p_encadeado,',
'        --     p_sucesso               => p_sucesso,',
'        --     p_messages              => p_messages',
'        -- );',
'        --',
'',
unistr('        -- S\00D3 DEVE RATEAR DESPESAS QUE N\00C3O S\00C3O TRIBUTOS:'),
'        select ind_tipo_despesa into l_ind_tipo_despesa from ng_despesa where id = v_new.id_despesa;',
'        if nvl(v_new.ind_tipo_despesa, l_ind_tipo_despesa) not in (1,2,3,4,5,6,18,19) then',
'            -- Chamada para o MAESTRO:',
'            --gerencia_processoimportacao_item_despesa(v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            l_id := pkg_maestro_api.postar_requisicao(',
'                p_codigo_artefato => ''PR8'',',
'                p_id_tenant       => v_new.id_tenant,',
'                p_id_usuario      => v_new.id_usuario_alterou,',
'                p_id_negocio      => v_new.id,',
'                p_payload         => ''{"id":"''||v_new.id||''"}'',',
'                p_prioridade      => 0,',
'                p_tipo_acao       => ''Origem: bo_imp_processoimportacao_despesa'',',
'                p_id_correlation  => null',
'            );',
'            --            ',
'        else',
unistr('            -- Ap\00F3s a inclus\00E3o das despesas/tributos deve vincular id, apenas para coer\00EAncia da modelagem de dados:'),
'            -- Vincula despesa com item_despesa:',
'            vincula_despesa_item_despesa(v_new.id_despesa, v_new.id_processoimportacao, v_new.id, v_pagina, p_encadeado, p_sucesso, p_messages);        ',
'            --',
'        end if;',
'        --',
'        -- Atualiza valores das despesas e tributos no processo:',
'        -- altera_processoimportacao_totais_despesas_tributos(',
'        --     p_id_processoimportacao => v_new.id_processoimportacao,',
'        --     p_pagina                => v_pagina,',
'        --     p_encadeado             => p_encadeado,',
'        --     p_sucesso               => p_sucesso,',
'        --     p_messages              => p_messages',
'        -- );',
'        --',
'        -- Recalcula o processo:',
'        if nvl(v_operacao, ''PADRAO'') != ''INCLUI_REGISTRO_POR_RECALCULO'' then',
'            bo_imp_processoimportacao.gerencia_tributos(v_new.id_processoimportacao, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        --',
'    end;',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is',
'    begin',
unistr('        -- Regra de atribui\00E7\00E3o de valor para a coluna valor_moeda_nacional:'),
'        atribui_valor_moeda_nacional;',
'        --',
'    end;',
