'    --',
'',
'    procedure incluir_despesas_da_lista (',
'        p_id_processoimportacao in imp_processoimportacao.id%type,',
'        p_id_listadespesa       in imp_listadespesa.id%type,',
'        p_pagina                in number default 0,',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant             imp_processoimportacao.id_tenant%type;',
'        l_id                    imp_processoimportacao_despesa.id%type;',
'        l_sucesso_local         clob;',
'        l_messages_local        pkg_mensagem.message_record_table := pkg_mensagem.message_record_table();',
'    begin',
'        p_messages := pkg_mensagem.message_record_table();',
'        p_sucesso  := null;',
'',
'        select id_tenant into l_id_tenant from imp_processoimportacao where id = p_id_processoimportacao;',
'',
'        for r in (',
'            select',
'                d.id as id_despesa,',
'                d.ind_forma_rateio,',
'                d.ind_compoe_custo_operacao,',
'                d.ind_participa_nfe,',
'                d.ind_despesa_base_calculo,',
'                d.ind_tipo_despesa',
'            from ng_despesa d',
'            join imp_listadespesa_despesa ld',
'             on ld.id_despesa = d.id',
'            where ld.id_lista_despesa = p_id_listadespesa',
'        ) loop',
'            begin',
'                l_id := null;',
'                l_sucesso_local  := null;',
'                l_messages_local := pkg_mensagem.message_record_table();',
'',
'                bo_imp_processoimportacao_despesa.inclui_registro(',
'                    p_id_tenant                         => l_id_tenant,',
'                    p_id_documento_despesa              => null,',
'                    p_id_processoimportacao             => p_id_processoimportacao,',
'                    p_id_numerario_despesa              => null, --?',
'                    p_id_despesa                        => r.id_despesa,',
'                    p_id_moeda_prevista                 => bo_mpd_configuracao_ng.retorna_id_moeda_tenant(l_id_tenant),',
'                    p_valor_previsto                    => null,',
'                    p_id_moeda_realizada                => null,',
'                    p_valor_realizado                   => null,',
'                    p_taxa_cambio                       => null,',
'                    p_ind_status_despesa                => 1,',
'                    p_ind_status_pagamento              => 1,',
'                    p_id_moeda_documento                => bo_mpd_configuracao_ng.retorna_id_moeda_tenant(l_id_tenant),',
'                    p_valor_moeda_documento             => 0,',
'                    p_valor_moeda_nacional              => 0,',
'                    p_ind_forma_rateio                  => r.ind_forma_rateio,',
'                    p_ind_compoe_custo_operacao         => r.ind_compoe_custo_operacao,',
'                    p_ind_participa_nfe                 => r.ind_participa_nfe,',
'                    p_ind_despesa_base_calculo          => r.ind_despesa_base_calculo,',
'                    p_ind_tipo_despesa                  => r.ind_tipo_despesa,',
'                    p_id                                => l_id,',
'                    p_pagina                            => p_pagina,',
'                    p_encadeado                         => true,',
'                    p_sucesso                           => l_sucesso_local,',
'                    p_messages                          => l_messages_local',
'                );',
'            end;',
'        end loop;',
'    end incluir_despesas_da_lista;',
'',
'    function detalhe_registro (',
'        p_id in imp_processoimportacao_despesa.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'                where b.id = ''||p_id,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        ) ||',
'        pkg_ui.campos_detalhes(q''~',
'            select',
'                pkg_traducao.get_traducao(c.descricao_despesa) imp_processoimportacao_despesa$id_despesa,',
'                pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'',c.ind_tipo_despesa) ng_despesa$ind_tipo_despesa,',
'                d.codigo_moeda||'' - ''||d.simbolo_iso imp_processoimportacao_despesa$id_moeda_prevista,',
'                to_char(a.valor_previsto, ''FM999G999G990D00'') imp_processoimportacao_despesa$valor_previsto',
'            from imp_processoimportacao_despesa a',
'            join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_despesa c on c.id = a.id_despesa',
'            join ng_moeda d on d.id = a.id_moeda_prevista',
'            where a.id = ~''||p_id',
'        );',
'    end detalhe_registro;',
'    --',
'    procedure atualiza_processoimportacao_item_tributo(',
'        p_id_processoimportacao in imp_processoimportacao_despesa.id_processoimportacao%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_imp_processoimportacao_item_tributo imp_processoimportacao_item_tributo%rowtype;',
'    begin',
'        for item_tributo in (',
'            select',
'                a.*',
'            from imp_processoimportacao_item_tributo a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item',
'            join imp_processoimportacao c on c.id = b.id_processoimportacao',
'            where c.id = p_id_processoimportacao',
'        ) loop',
'            select * into l_imp_processoimportacao_item_tributo from imp_processoimportacao_item_tributo where id = item_tributo.id;',
'            bo_imp_processoimportacao_item_tributo.altera_tributos(',
'                p_id_processoimportacao_item => l_imp_processoimportacao_item_tributo.id_processoimportacao_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'    end atualiza_processoimportacao_item_tributo;',
'    --',
'    procedure altera_ind_status_pagamento(',
'        p_ind_status_pagamento in imp_processoimportacao_despesa.ind_status_pagamento%type,',
'        p_id in imp_processoimportacao_despesa.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_despesa.altera_ind_status_pagamento'';',
'        v_pagina := p_pagina;',
'',
'        select * into v_old from imp_processoimportacao_despesa where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.ind_status_pagamento := p_ind_status_pagamento;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'',
'        v_operacao := ''ALTERA_IND_STATUS_PAGAMENTO'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'    end altera_ind_status_pagamento;',
'    --',
'    procedure gerencia_processoimportacao_item_despesa(',
'        p_id in imp_processoimportacao_despesa.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id number;',
'    begin',
'        -- Tratamento excluir:',
'        for processoimportacao_item_despesa in (',
'            select a.id',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_despesa b on b.id = a.id_processoimportacao_despesa',
'            join ng_despesa c on c.id = a.id_despesa',
'            where a.id_processoimportacao_despesa = p_id',
'            and nvl(b.ind_tipo_despesa, c.ind_tipo_despesa) not in (1,2,3,4,5,6,18,19)',
'        ) loop',
'            bo_imp_processoimportacao_item_despesa.exclui_registro(processoimportacao_item_despesa.id, p_encadeado, p_sucesso, p_messages);',
'        end loop;',
'',
'        -- Tratamento incluir com rateio calculado corretamente:',
'        for processoimportacao_item in (',
'            select a.id, a.id_tenant, b.id_despesa, b.valor_previsto, b.id_moeda_prevista, b.valor_realizado, b.id_moeda_realizada',
'            from imp_processoimportacao_item a',
'            join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id_processoimportacao',
'            join ng_despesa c on c.id = b.id_despesa',
'            where b.id = p_id',
'            and nvl(b.ind_tipo_despesa, c.ind_tipo_despesa) not in (1,2,3,4,5,6,18,19)',
'        ) loop',
'            bo_imp_processoimportacao_item_despesa.inclui_registro(',
'                p_id_tenant => processoimportacao_item.id_tenant,',
'                p_id_processoimportacao_item => processoimportacao_item.id,',
'                p_id_processoimportacao_despesa => p_id,',
'                p_id_despesa => processoimportacao_item.id_despesa,',
'                p_id_moeda_despesa_prevista => processoimportacao_item.id_moeda_prevista,',
'                p_valor_total_despesa_previsto_item => bo_imp_processoimportacao_item_despesa.calcula_rateio(processoimportacao_item.valor_previsto, processoimportacao_item.id, p_id),',
'                p_valor_unitario_despesa_previsto_item => bo_imp_processoimportacao_item_despesa.calcula_rateio_unitario(processoimportacao_item.valor_previsto, processoimportacao_item.id, p_id),',
'                p_id_moeda_despesa_realizada => processoimportacao_item.id_moeda_realizada,',
'                p_valor_total_despesa_realizado_item => bo_imp_processoimportacao_item_despesa.calcula_rateio(processoimportacao_item.valor_realizado, processoimportacao_item.id, p_id),',
'                p_valor_unitario_despesa_realizado_item => bo_imp_processoimportacao_item_despesa.calcula_rateio_unitario(processoimportacao_item.valor_realizado, processoimportacao_item.id, p_id),',
'                p_valor_total_despesa_moeda_nacional    => 0,',
'                p_valor_unitario_despesa_moeda_nacional => 0,',
'                p_id => l_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end loop;',
'',
'    end gerencia_processoimportacao_item_despesa;',
'    --',
'',
'    procedure seta_valores_reais_despesa(',
'        p_json_valores_reais in clob,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'        l_json clob;',
'    begin',
'        l_json := p_json_valores_reais;',
'',
'        for valor_real in (',
'            select json_valor.id,',
'                   pkg_util.retorna_number(json_valor.valor) valor,',
'                   pkg_util.retorna_number(json_valor.id_moeda_realizada) id_moeda_realizada',
'              from json_table(l_json, ''$[*]''',
'                columns',
'                    id                 varchar2(50) path ''$.id'',',
'                    valor              varchar2(50) path ''$.valor'',',
'                    id_moeda_realizada varchar2(50) path ''$.id_moeda_realizada''',
'              ) json_valor',
'        ) loop',
'            select *',
'              into v_old',
'              from imp_processoimportacao_despesa',
'             where id = valor_real.id;',
'            v_new := v_old;',
'            v_new.valor_realizado    := valor_real.valor;',
'            v_new.id_moeda_realizada := nvl(valor_real.id_moeda_realizada, v_old.id_moeda_realizada);',
'',
'        grava(valor_real.id, p_encadeado, p_sucesso, p_messages);',
'',
'        end loop;',
'',
'',
'    end seta_valores_reais_despesa;',
'    --',
'    procedure altera_processoimportacao_tributos(',
'        p_id_processoimportacao         in imp_processoimportacao.id%type,',
'        p_pagina                        in number default 0,',
'        p_encadeado                     in boolean default false,',
'        p_sucesso                       out clob,',
'        p_messages                      out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_processoimportacao            imp_processoimportacao%rowtype;',
'        l_vmld                          number;',
'        l_valor_ii                      number;',
'        l_valor_ipi                     number;',
'        l_valor_pis                     number;',
'        l_valor_cofins                  number;',
'        l_valor_icms                    number;',
'        l_valor_icms_st                 number;',
'        l_valor_cbs                     number;',
'        l_valor_ibs                     number;',
'    begin',
'        select * into l_processoimportacao from imp_processoimportacao where id = p_id_processoimportacao;',
'        select nvl(sum(nvl(a.vmld,0)),0) into l_vmld from imp_processoimportacao_item_tributo a join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item join imp_processoimportacao c on c.id = b.id_processoimportacao where c.id = p_i'
||'d_processoimportacao;',
'',
'        -- buscar valores dos tributos',
'        select',
'            nvl(max(case when b.ind_tipo_despesa = 1  then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 2  then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 3  then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 4  then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 5  then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 6  then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 18 then a.valor_previsto end), 0),',
'            nvl(max(case when b.ind_tipo_despesa = 19 then a.valor_previsto end), 0)',
'        into',
'            l_valor_ii,',
'            l_valor_ipi,',
'            l_valor_pis,',
'            l_valor_cofins,',
'            l_valor_icms,',
'            l_valor_icms_st,',
'            l_valor_cbs,',
'            l_valor_ibs',
'        from imp_processoimportacao_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        where a.id_processoimportacao = p_id_processoimportacao;',
'',
'        bo_imp_processoimportacao.altera_valores(',
'            p_valor_total_mercadoria        => l_processoimportacao.valor_total_mercadoria,',
'            p_valor_desconto                => l_processoimportacao.valor_desconto,',
'            p_valor_total_condicao_venda    => l_processoimportacao.valor_total_condicao_venda,',
'            p_frete                         => l_processoimportacao.frete,',
'            p_seguro                        => l_processoimportacao.seguro,',
'            p_acrescimo                     => l_processoimportacao.acrescimo,',
'            p_multa                         => l_processoimportacao.multa,',
'            p_antidumping                   => l_processoimportacao.antidumping,',
'            p_vmle                          => l_processoimportacao.vmle,',
'            p_vmld                          => l_vmld,',
'            p_valor_ii                      => l_valor_ii,',
'            p_valor_ipi                     => l_valor_ipi,',
'            p_valor_pis                     => l_valor_pis,',
'            p_valor_cofins                  => l_valor_cofins,',
'            p_valor_icms                    => l_valor_icms,',
'            p_valor_icms_st                 => l_valor_icms_st,',
'            p_valor_cbs                     => l_valor_cbs,',
'            p_valor_ibs                     => l_valor_ibs,',
'            p_id                            => l_processoimportacao.id,',
'            p_pagina                        => p_pagina,',
'            p_encadeado                     => p_encadeado,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'    end altera_processoimportacao_tributos;',
'    --',
'    procedure atribui_valor_moeda_nacional is',
'        l_ind_tipo_despesa ng_despesa.ind_tipo_despesa%type;',
'    begin',
'        if v_new.id is not null then',
'            select nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) ',
'            into l_ind_tipo_despesa',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id = v_new.id;',
'        else',
'            select ind_tipo_despesa',
'            into l_ind_tipo_despesa',
'            from ng_despesa',
'            where id = v_new.id_despesa;',
'        end if;',
'        ',
'        if l_ind_tipo_despesa in (1,2,3,4,5,6,18,19) then',
'            v_new.valor_moeda_nacional := nvl(v_new.valor_realizado,0);',
'        else',
'            if v_new.id_moeda_realizada is not null then',
'                if v_new.id_moeda_realizada = bo_mpd_configuracao_ng.retorna_id_moeda_nacional(v_new.id_tenant) then',
'                    v_new.valor_moeda_nacional := nvl(v_new.valor_realizado,0);',
'                else',
'                    v_new.valor_moeda_nacional := (nvl(v_new.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(v_new.id));',
'                end if;',
'            end if;',
'        end if;',
'    end atribui_valor_moeda_nacional;',
'    --',
'    procedure altera_processoimportacao_totais_despesas_tributos(',
'        p_id_processoimportacao in imp_processoimportacao.id%type,',
'        p_pagina                in number default 0,',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table',
'    ) is',
'        l_frete         number;',
'        l_seguro        number;',
'        l_acrescimo     number;',
'        l_multa         number;',
'        l_antidumping   number;',
'        l_vmle          number;',
'        l_vmld          number;',
'        l_valor_ii      number;',
'        l_valor_ipi     number;',
'        l_valor_pis     number;',
'        l_valor_cofins  number;',
'        l_valor_icms    number;',
'        l_valor_icms_st number;',
'        l_valor_cbs     number;',
'        l_valor_ibs     number;',
'    begin',
unistr('        -- Busca o valor total de cada despesa/tributo considerando prioridade de colunas e cota\00E7\00E3o atualizada:'),
'        select',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  9 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) = 10 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) = 16 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) = 17 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  8 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  1 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  2 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  3 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  4 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  5 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) =  6 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) = 18 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0),',
'            nvl(sum(case when nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) = 19 then coalesce(nullif(a.valor_moeda_nacional,0), nullif(nvl(a.valor_realizado,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id),0), nvl(a.valor_previsto'
||',0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(a.id)) end), 0)',
'        into',
'            l_frete,',
'            l_seguro,',
'            l_acrescimo,',
'            l_multa,',
'            l_antidumping,',
'            l_valor_ii,',
'            l_valor_ipi,',
'            l_valor_pis,',
'            l_valor_cofins,',
'            l_valor_icms,',
'            l_valor_icms_st,',
'            l_valor_cbs,',
'            l_valor_ibs',
'        from imp_processoimportacao_despesa a',
'        join ng_despesa b on b.id = a.id_despesa',
'        where a.id_processoimportacao = p_id_processoimportacao;',
'        --',
'        -- Busca VMLE e VMLD atualizados:',
'        select ',
'            sum(bo_imp_processoimportacao_item_tributo.calcula_vmle(id)),',
'            sum(bo_imp_processoimportacao_item_tributo.calcula_vmld(id)) ',
'        into',
'            l_vmle,',
'            l_vmld',
'        from imp_processoimportacao_item ',
'        where id_processoimportacao = p_id_processoimportacao;',
'        --',
unistr('        -- Chamada para atualiza\00E7\00E3o completa no processo:'),
'        bo_imp_processoimportacao.altera_totais_despesas_tributos(',
'            p_frete         => trunc(l_frete, 5),',
'            p_seguro        => trunc(l_seguro, 5),',
'            p_acrescimo     => trunc(l_acrescimo, 5),',
'            p_multa         => trunc(l_multa, 2),',
'            p_antidumping   => trunc(l_antidumping, 2),',
'            p_vmle          => trunc(l_vmle, 5),',
'            p_vmld          => trunc(l_vmld, 5),',
'            p_valor_ii      => trunc(l_valor_ii, 5),',
'            p_valor_ipi     => trunc(l_valor_ipi, 2),',
'            p_valor_pis     => trunc(l_valor_pis, 2),',
'            p_valor_cofins  => trunc(l_valor_cofins, 2),',
'            p_valor_icms    => trunc(l_valor_icms, 2),',
'            p_valor_icms_st => trunc(l_valor_icms_st, 2),',
'            p_valor_cbs     => trunc(l_valor_cbs, 2),',
'            p_valor_ibs     => trunc(l_valor_ibs, 2),',
'            p_id            => p_id_processoimportacao,',
'            p_pagina        => p_pagina,',
'            p_encadeado     => p_encadeado,',
'            p_sucesso       => p_sucesso,',
'            p_messages      => p_messages',
'        );',
'        --',
'    end altera_processoimportacao_totais_despesas_tributos;',
'    --',
'    procedure vincula_despesa_item_despesa(        ',
'        p_id_despesa            in imp_processoimportacao_despesa.id_despesa%type,',
'        p_id_processoimportacao in imp_processoimportacao_despesa.id_processoimportacao%type,        ',
'        p_id                    in imp_processoimportacao_despesa.id%type,',
'        p_pagina                in number default 0,',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table       ',
'    ) is',
'    begin',
'        -- Busca imp_processoimportacao_item_despesa para vincular id_processoimportacao_despesa:',
'        for processoimportacao_item_despesa in (',
'            select a.id',
'            from imp_processoimportacao_item_despesa a',
'            join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item',
'            where a.id_despesa = p_id_despesa',
'            and a.id_processoimportacao_despesa is null',
'            and b.id_processoimportacao = p_id_processoimportacao',
'        ) loop            ',
'            bo_imp_processoimportacao_item_despesa.altera_id_processoimportacao_despesa(',
'                p_id_processoimportacao_despesa => p_id,',
'                p_id                            => processoimportacao_item_despesa.id,',
'                p_pagina                        => p_pagina,',
'                p_encadeado                     => p_encadeado,',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'            );',
'        end loop;',
'        --',
'    end vincula_despesa_item_despesa;',
'    --',
