'        v_new.valor_moeda_nacional      := nvl(p_valor_moeda_nacional,0);',
'        v_new.ind_forma_rateio          := p_ind_forma_rateio;',
'        v_new.ind_compoe_custo_operacao := p_ind_compoe_custo_operacao;',
'        v_new.ind_participa_nfe         := p_ind_participa_nfe;',
'        v_new.ind_despesa_base_calculo  := p_ind_despesa_base_calculo;',
'        v_new.ind_tipo_despesa          := p_ind_tipo_despesa;',
'        v_new.id_usuario_incluiu        := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_inclusao             := sysdate;',
'        v_new.id_usuario_alterou        := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao            := sysdate;',
'        v_new.id                        := null;',
'        --',
'        v_operacao := ''INCLUI_REGISTRO_POR_RECALCULO'';',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);',
'    end inclui_registro_por_recalculo;',
'    --',
'    procedure exclui_registro_por_recalculo(',
'        p_id        in imp_processoimportacao_despesa.id%type,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_operacao     := ''EXCLUI_REGISTRO_POR_RECALCULO'';',
'        v_messages     := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_processoimportacao_despesa.exclui_registro_por_recalculo'';',
'        --',
'        verifica_registro(p_id);',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        end if;',
'        --',
'        select * into v_old from imp_processoimportacao_despesa where id = p_id;',
'        --',
'        antes_excluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            RAISE pk_exceptions.e_erro;',
'        end if;',
'        --        ',
'        delete from imp_processoimportacao_despesa where id = p_id;',
'        --        ',
'        depois_excluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'    exception',
'        when pk_exceptions.e_erro then',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        when others then',
'            v_parametro(1) := sqlerrm;',
'            pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro_por_recalculo;',
'    --',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_processoimportacao_despesa;',
'/'))
);
end;
