'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_item_despesa'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_item_despesa'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_item_despesa'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_item_despesa'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_item_despesa'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_item_despesa'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_processoimportacao_item_despesa%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_processoimportacao_item'', p_rec.id_processoimportacao_item, true);',
'        apex_json.write(''id_processoimportacao_despesa'', p_rec.id_processoimportacao_despesa, true);',
'        apex_json.write(''id_despesa'', p_rec.id_despesa, true);',
'        apex_json.write(''id_moeda_despesa_prevista'', p_rec.id_moeda_despesa_prevista, true);',
'        apex_json.write(''valor_total_despesa_previsto_item'', p_rec.valor_total_despesa_previsto_item, true);',
'        apex_json.write(''valor_unitario_despesa_previsto_item'', p_rec.valor_unitario_despesa_previsto_item, true);',
'        apex_json.write(''id_moeda_despesa_realizada'', p_rec.id_moeda_despesa_realizada, true);',
'        apex_json.write(''valor_total_despesa_realizado_item'', p_rec.valor_total_despesa_realizado_item, true);',
'        apex_json.write(''valor_unitario_despesa_realizado_item'', p_rec.valor_unitario_despesa_realizado_item, true);',
'        apex_json.write(''valor_total_despesa_moeda_nacional'', p_rec.valor_total_despesa_moeda_nacional, true);',
'        apex_json.write(''valor_unitario_despesa_moeda_nacional'', p_rec.valor_unitario_despesa_moeda_nacional, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
