'    --',
'    function calcula_rateio(',
'        p_valor                         in imp_processoimportacao_despesa.valor_previsto%type,',
'        p_id_processoimportacao_item    in imp_processoimportacao_item_despesa.id_processoimportacao_item%type,',
'        p_id_processoimportacao_despesa in imp_processoimportacao_item_despesa.id_processoimportacao_despesa%type',
'    ) return number is',
'        l_id_processoimportacao                          number;',
'        l_peso_unitario                                  number;',
'        l_quantidade                                     number;',
'        l_processoimportacao_item_valor_total_mercadoria number;',
'        l_verifica_ind_status_despesa                    number;',
'        l_peso_liquido_total                             number;',
'        l_quantidade_total                               number;',
'        l_valor_total_mercadoria                         number;',
'        l_ind_forma_rateio                               number;',
'        l_resultado                                      number;',
'        -- Tratamento do resto:',
'        l_base_cent      number;',
'        l_soma_base_cent number;',
'        l_total_cent     number;',
'        l_resto          number;',
'        l_item_ajuste    number;',
'    begin',
unistr('        -- Busca as informa\00E7\00F5es do item:'),
'        select ',
'            id_processoimportacao,',
'            peso_liquido_total,',
'            quantidade,',
'            (valor_total_mercadoria * bo_imp_processoimportacao_item_tributo.cotacao_item_real(id))',
'        into ',
'            l_id_processoimportacao,',
'            l_peso_unitario,',
'            l_quantidade,',
'            l_processoimportacao_item_valor_total_mercadoria',
'        from imp_processoimportacao_item',
'        where id = p_id_processoimportacao_item;',
'        --',
'        -- Verifica status da despesa:',
'        select count(1)',
'        into l_verifica_ind_status_despesa',
'        from imp_processoimportacao_despesa',
'        where id_processoimportacao = l_id_processoimportacao',
'        and id = p_id_processoimportacao_despesa',
'        and ind_status_despesa = 2',
'        and ind_forma_rateio is not null',
'        and ind_compoe_custo_operacao is not null',
'        and ind_despesa_base_calculo is not null',
'        and ind_tipo_despesa is not null;',
'        --',
'        -- Dependendo do status, utiliza a "foto" ou busca diretamente no cadastro da despesa(NG_DESPESA):',
'        if l_verifica_ind_status_despesa > 0 then',
'            select ind_forma_rateio',
'            into l_ind_forma_rateio',
'            from imp_processoimportacao_despesa',
'            where id_processoimportacao = l_id_processoimportacao',
'            and id = p_id_processoimportacao_despesa;',
'        else',
'            select b.ind_forma_rateio',
'            into l_ind_forma_rateio',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b',
'            on b.id = a.id_despesa',
'            where a.id = p_id_processoimportacao_despesa;',
'        end if;',
'        --',
'        -- Verifica formas de rateio:',
'        if l_ind_forma_rateio = 1 then',
unistr('            -- Rateio por peso l\00EDquido:'),
'            select sum(peso_liquido_total)',
'            into l_peso_liquido_total',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'',
'            l_resultado := (p_valor * l_peso_unitario) / l_peso_liquido_total;',
'            --',
'            -- Tratamento do resto:',
'            select sum(trunc(((p_valor * peso_liquido_total) / l_peso_liquido_total) * 100))',
'            into l_soma_base_cent',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'            --',
'        elsif l_ind_forma_rateio = 2 then',
'            -- Rateio por quantidade:',
'            select sum(quantidade)',
'            into l_quantidade_total',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'',
'            l_resultado := (p_valor * l_quantidade) / l_quantidade_total;',
'            --',
'            -- Tratamento do resto:',
'            select sum(trunc(((p_valor * quantidade) / l_quantidade_total) * 100))',
'            into l_soma_base_cent',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'            --        ',
'        elsif l_ind_forma_rateio = 3 then',
unistr('            -- Rateio por valor total na condi\00E7\00E3o de venda:'),
'            select valor_total_mercadoria',
'            into l_valor_total_mercadoria',
'            from imp_processoimportacao',
'            where id = l_id_processoimportacao;',
'',
'            l_resultado := (p_valor * l_processoimportacao_item_valor_total_mercadoria) / l_valor_total_mercadoria;',
'            --',
'            -- Tratamento do resto:',
'            select sum(trunc(((p_valor * (valor_total_mercadoria * bo_imp_processoimportacao_item_tributo.cotacao_item_real(id))) / l_valor_total_mercadoria) * 100))',
'            into l_soma_base_cent',
'            from imp_processoimportacao_item',
'            where id_processoimportacao = l_id_processoimportacao;',
'            --',
'        else            ',
'            return 0;',
'        end if;',
'        --',
'        -- Base em centavos:',
'        l_base_cent := trunc(l_resultado * 100);',
'        --',
'        -- Total esperado:',
'        l_total_cent := p_valor * 100;',
'        --',
unistr('        -- Diferen\00E7a;'),
'        l_resto := l_total_cent - l_soma_base_cent;',
'        --',
unistr('        -- Item que receber\00E1 o ajuste:'),
'        select min(id)',
'        into l_item_ajuste',
'        from imp_processoimportacao_item',
'        where id_processoimportacao = l_id_processoimportacao;',
'        --',
'        -- Aplica no item correto:',
'        if p_id_processoimportacao_item = l_item_ajuste then',
'            l_base_cent := l_base_cent + l_resto;',
'        end if;',
'        --',
'        -- Resultado para retorno:',
'        return trunc(l_base_cent / 100, 2);',
'        --',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_rateio;',
'    --',
'    function calcula_rateio_unitario(',
'        p_valor in imp_processoimportacao_despesa.valor_previsto%type,',
'        p_id_processoimportacao_item in imp_processoimportacao_item_despesa.id_processoimportacao_item%type,',
'        p_id_processoimportacao_despesa in imp_processoimportacao_item_despesa.id_processoimportacao_despesa%type',
'    ) return number is',
'        l_quantidade number;',
'        l_resultado number;',
'    begin',
'        select quantidade into l_quantidade from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'',
'        l_resultado := (calcula_rateio(p_valor, p_id_processoimportacao_item, p_id_processoimportacao_despesa) / l_quantidade);',
'',
'        return trunc(l_resultado, 2);',
'    exception',
'        when others then',
'            return 0;',
'    end calcula_rateio_unitario;',
'    --',
'    procedure atribui_valor_total_despesa_moeda_nacional is',
'        l_ind_tipo_despesa ng_despesa.ind_tipo_despesa%type;',
'    begin',
'        if v_new.id_processoimportacao_despesa is not null then',
'            select nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) ',
'            into l_ind_tipo_despesa',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id = v_new.id_processoimportacao_despesa;',
'        else',
'            select ind_tipo_despesa',
'            into l_ind_tipo_despesa',
'            from ng_despesa',
'            where id = v_new.id_despesa;',
'        end if;',
'        ',
'        if l_ind_tipo_despesa in (1,2,3,4,5,6,18,19) then',
'            v_new.valor_total_despesa_moeda_nacional := nvl(v_new.valor_total_despesa_realizado_item,0);',
'        else',
'            if nvl(v_new.id_moeda_despesa_realizada, v_new.id_moeda_despesa_prevista) is not null then',
'                if nvl(v_new.id_moeda_despesa_realizada, v_new.id_moeda_despesa_prevista) = bo_mpd_configuracao_ng.retorna_id_moeda_nacional(v_new.id_tenant) then',
'                    v_new.valor_total_despesa_moeda_nacional := nvl(v_new.valor_total_despesa_realizado_item,0);',
'                else',
'                    v_new.valor_total_despesa_moeda_nacional := (nvl(v_new.valor_total_despesa_realizado_item,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(v_new.id_processoimportacao_despesa));',
'                end if;',
'            end if;',
'        end if;',
'    end atribui_valor_total_despesa_moeda_nacional;',
'    --',
'    procedure atribui_valor_unitario_despesa_moeda_nacional is',
'        l_ind_tipo_despesa ng_despesa.ind_tipo_despesa%type;',
'    begin',
'        if v_new.id_processoimportacao_despesa is not null then',
'            select nvl(a.ind_tipo_despesa,b.ind_tipo_despesa) ',
'            into l_ind_tipo_despesa',
'            from imp_processoimportacao_despesa a',
'            join ng_despesa b on b.id = a.id_despesa',
'            where a.id = v_new.id_processoimportacao_despesa;',
'        else',
'            select ind_tipo_despesa',
'            into l_ind_tipo_despesa',
'            from ng_despesa',
'            where id = v_new.id_despesa;',
'        end if;',
'',
'        if l_ind_tipo_despesa in (1,2,3,4,5,6,18,19) then',
'            v_new.valor_unitario_despesa_moeda_nacional := nvl(v_new.valor_unitario_despesa_realizado_item,0);',
'        else',
'            if nvl(v_new.id_moeda_despesa_realizada, v_new.id_moeda_despesa_prevista) is not null then',
'                if nvl(v_new.id_moeda_despesa_realizada, v_new.id_moeda_despesa_prevista) = bo_mpd_configuracao_ng.retorna_id_moeda_nacional(v_new.id_tenant) then',
'                    v_new.valor_unitario_despesa_moeda_nacional := nvl(v_new.valor_unitario_despesa_realizado_item,0);',
'                else',
'                    v_new.valor_unitario_despesa_moeda_nacional := (nvl(v_new.valor_unitario_despesa_realizado_item,0) * bo_imp_processoimportacao_item_tributo.cotacao_despesa_real(v_new.id_processoimportacao_despesa));',
'                end if;',
'            end if;',
'        end if;',
'    end atribui_valor_unitario_despesa_moeda_nacional;',
'    --',
'    procedure altera_id_processoimportacao_despesa(  ',
'        p_id_processoimportacao_despesa in imp_processoimportacao_item_despesa.id_processoimportacao_despesa%type,',
'        p_id in imp_processoimportacao_item_despesa.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_parametro(0) := ''bo_imp_processoimportacao_item_despesa.altera_id_processoimportacao_despesa'';',
'        v_pagina := p_pagina;',
'        --',
'        select * into v_old from imp_processoimportacao_item_despesa where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        v_new.id_processoimportacao_despesa := p_id_processoimportacao_despesa;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;  ',
'        --',
'        v_operacao := ''ALTERA_ID_PROCESSOIMPORTACAO_DESPESA'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);',
'        --',
'    end altera_id_processoimportacao_despesa;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_processoimportacao_item_despesa;',
'/'))
);
end;
