'        p_id_pais_origem in imp_invoice_item.id_pais_origem%type,',
'        p_peso_bruto_unitario in imp_invoice_item.peso_bruto_unitario%type,',
'        p_peso_bruto_total in imp_invoice_item.peso_bruto_total%type,',
'        p_valor_total_desconto_invoice_item in imp_invoice_item.valor_total_desconto_invoice_item%type,',
'        p_valor_total_mercadoria in imp_invoice_item.valor_total_mercadoria%type,',
'        p_valor_total_despesa_invoice_item in imp_invoice_item.valor_total_despesa_invoice_item%type, ',
'        p_id in imp_invoice_item.id%type, ',
'        p_data_alteracao in imp_invoice_item.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_item'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice_item.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from imp_invoice_item where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.id_invoice := p_id_invoice;',
'        v_new.id_entrega := p_id_entrega;',
'        v_new.id_entrega_item := p_id_entrega_item;',
'        v_new.sequencia_item_invoice := p_sequencia_item_invoice;',
'        v_new.id_item := p_id_item;',
'        v_new.id_ncm := p_id_ncm;',
'        v_new.id_unidademedida := p_id_unidademedida;',
'        v_new.quantidade := p_quantidade;',
'        v_new.peso_unitario := nvl(p_peso_unitario,0);',
'        v_new.peso_liquido_total := nvl(p_peso_liquido_total,0);',
'        v_new.valor_unitario := p_valor_unitario;',
'        v_new.valor_desconto := nvl(p_valor_desconto,0);',
'        v_new.valor_total_condicao_venda := p_valor_total_condicao_venda;',
'        v_new.id_fabricante := p_id_fabricante;',
'        v_new.id_pais_origem := p_id_pais_origem;',
'        v_new.peso_bruto_unitario := nvl(p_peso_bruto_unitario,0);',
'        v_new.peso_bruto_total := nvl(p_peso_bruto_total,0);',
'        v_new.valor_total_desconto_invoice_item := nvl(p_valor_total_desconto_invoice_item,0);',
'        v_new.valor_total_mercadoria := nvl(p_valor_total_mercadoria,0);',
'        v_new.valor_total_despesa_invoice_item := nvl(p_valor_total_despesa_invoice_item,0); ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_item'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_item'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out imp_invoice_item.id_tenant%type,',
'        p_id_invoice out imp_invoice_item.id_invoice%type,',
'        p_id_entrega out imp_invoice_item.id_entrega%type,',
'        p_id_entrega_item out imp_invoice_item.id_entrega_item%type,',
'        p_sequencia_item_invoice out imp_invoice_item.sequencia_item_invoice%type,',
'        p_id_item out imp_invoice_item.id_item%type,',
'        p_id_ncm out imp_invoice_item.id_ncm%type,',
'        p_id_unidademedida out imp_invoice_item.id_unidademedida%type,',
'        p_quantidade out imp_invoice_item.quantidade%type,',
'        p_peso_unitario out imp_invoice_item.peso_unitario%type,',
'        p_peso_liquido_total out imp_invoice_item.peso_liquido_total%type,',
'        p_valor_unitario out imp_invoice_item.valor_unitario%type,',
'        p_valor_desconto out imp_invoice_item.valor_desconto%type,',
'        p_valor_total_condicao_venda out imp_invoice_item.valor_total_condicao_venda%type,',
'        p_id_fabricante out imp_invoice_item.id_fabricante%type,',
'        p_id_pais_origem out imp_invoice_item.id_pais_origem%type,',
'        p_peso_bruto_unitario out imp_invoice_item.peso_bruto_unitario%type,',
'        p_peso_bruto_total out imp_invoice_item.peso_bruto_total%type,',
'        p_valor_total_desconto_invoice_item out imp_invoice_item.valor_total_desconto_invoice_item%type,',
'        p_valor_total_mercadoria out imp_invoice_item.valor_total_mercadoria%type,',
'        p_valor_total_despesa_invoice_item out imp_invoice_item.valor_total_despesa_invoice_item%type, ',
'        p_id in out imp_invoice_item.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_item'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice_item.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            id_invoice,',
'            id_entrega,',
'            id_entrega_item,',
'            sequencia_item_invoice,',
'            id_item,',
'            id_ncm,',
'            id_unidademedida,',
'            quantidade,',
'            peso_unitario,',
'            peso_liquido_total,',
'            valor_unitario,',
'            valor_desconto,',
'            valor_total_condicao_venda,',
'            id_fabricante,',
'            id_pais_origem,',
'            peso_bruto_unitario,',
'            peso_bruto_total,',
'            valor_total_desconto_invoice_item,',
'            valor_total_mercadoria,',
'            valor_total_despesa_invoice_item, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_id_invoice,',
'            p_id_entrega,',
'            p_id_entrega_item,',
'            p_sequencia_item_invoice,',
'            p_id_item,',
'            p_id_ncm,',
'            p_id_unidademedida,',
'            p_quantidade,',
'            p_peso_unitario,',
'            p_peso_liquido_total,',
'            p_valor_unitario,',
'            p_valor_desconto,',
'            p_valor_total_condicao_venda,',
'            p_id_fabricante,',
'            p_id_pais_origem,',
'            p_peso_bruto_unitario,',
'            p_peso_bruto_total,',
'            p_valor_total_desconto_invoice_item,',
'            p_valor_total_mercadoria,',
'            p_valor_total_despesa_invoice_item, ',
'            p_id ',
'        from imp_invoice_item ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_item'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_item'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in imp_invoice_item.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_invoice_item'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_imp_invoice_item.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from imp_invoice_item where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from imp_invoice_item where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_invoice_item'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_item'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_invoice_item'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in imp_invoice_item.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice_item where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in imp_invoice_item.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_invoice_item where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in imp_invoice_item.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_invoice_item'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''imp_invoice_item'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in imp_invoice_item.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_invoice */ '),
'        valida_id_invoice(v_new.id_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_entrega */ '),
'        valida_id_entrega(v_new.id_entrega);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_entrega_item */ '),
'        valida_id_entrega_item(v_new.id_entrega_item);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo sequencia_item_invoice */ '),
'        valida_sequencia_item_invoice(v_new.sequencia_item_invoice);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_item */ '),
'        valida_id_item(v_new.id_item);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_ncm */ '),
'        valida_id_ncm(v_new.id_ncm);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_unidademedida */ '),
'        valida_id_unidademedida(v_new.id_unidademedida);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo quantidade */ '),
'        valida_quantidade(v_new.quantidade);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo peso_unitario */ '),
'        valida_peso_unitario(v_new.peso_unitario);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo peso_liquido_total */ '),
'        valida_peso_liquido_total(v_new.peso_liquido_total);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_unitario */ '),
'        valida_valor_unitario(v_new.valor_unitario);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_desconto */ '),
'        valida_valor_desconto(v_new.valor_desconto);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_total_condicao_venda */ '),
'        valida_valor_total_condicao_venda(v_new.valor_total_condicao_venda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_fabricante */ '),
'        valida_id_fabricante(v_new.id_fabricante);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_pais_origem */ '),
'        valida_id_pais_origem(v_new.id_pais_origem);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo peso_bruto_unitario */ '),
'        valida_peso_bruto_unitario(v_new.peso_bruto_unitario);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo peso_bruto_total */ '),
'        valida_peso_bruto_total(v_new.peso_bruto_total);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_total_desconto_invoice_item */ '),
'        valida_valor_total_desconto_invoice_item(v_new.valor_total_desconto_invoice_item);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo valor_total_mercadoria */ '),
