unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_item'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_item'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_item'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_item'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_invoice_item'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_invoice_item'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_invoice_item%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_invoice'', p_rec.id_invoice, true);',
'        apex_json.write(''id_entrega'', p_rec.id_entrega, true);',
'        apex_json.write(''id_entrega_item'', p_rec.id_entrega_item, true);',
'        apex_json.write(''sequencia_item_invoice'', p_rec.sequencia_item_invoice, true);',
'        apex_json.write(''id_item'', p_rec.id_item, true);',
'        apex_json.write(''id_ncm'', p_rec.id_ncm, true);',
'        apex_json.write(''id_unidademedida'', p_rec.id_unidademedida, true);',
'        apex_json.write(''quantidade'', p_rec.quantidade, true);',
'        apex_json.write(''peso_unitario'', p_rec.peso_unitario, true);',
'        apex_json.write(''peso_liquido_total'', p_rec.peso_liquido_total, true);',
'        apex_json.write(''valor_unitario'', p_rec.valor_unitario, true);',
'        apex_json.write(''valor_desconto'', p_rec.valor_desconto, true);',
'        apex_json.write(''valor_total_condicao_venda'', p_rec.valor_total_condicao_venda, true);',
'        apex_json.write(''id_fabricante'', p_rec.id_fabricante, true);',
'        apex_json.write(''id_pais_origem'', p_rec.id_pais_origem, true);',
'        apex_json.write(''peso_bruto_unitario'', p_rec.peso_bruto_unitario, true);',
'        apex_json.write(''peso_bruto_total'', p_rec.peso_bruto_total, true);',
'        apex_json.write(''valor_total_desconto_invoice_item'', p_rec.valor_total_desconto_invoice_item, true);',
'        apex_json.write(''valor_total_mercadoria'', p_rec.valor_total_mercadoria, true);',
'        apex_json.write(''valor_total_despesa_invoice_item'', p_rec.valor_total_despesa_invoice_item, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
unistr('        -- Garante c\00E1lculos corretos para colunas calculadas:'),
'        v_new.valor_total_mercadoria := (v_new.quantidade * (v_new.valor_unitario - v_new.valor_desconto));',
'        v_new.valor_total_condicao_venda := (nvl(v_new.valor_total_mercadoria, 0) - nvl(v_new.valor_total_desconto_invoice_item, 0) + nvl(v_new.valor_total_despesa_invoice_item, 0));',
'        v_new.peso_liquido_total := (v_new.quantidade * v_new.peso_unitario);',
'        v_new.peso_bruto_total := (v_new.quantidade * v_new.peso_bruto_unitario);        ',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id number;',
'    begin',
'        bo_imp_invoice.atualiza_valores(v_new.id_invoice,v_pagina,p_encadeado,p_sucesso,p_messages);        ',
'        altera_quantidade_faturada(v_new.id,v_pagina,p_encadeado,p_sucesso,p_messages);',
'        altera_invoice_valores(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'        --recalcula_rateio_invoice_item_despesa(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        l_id := pkg_maestro_api.postar_requisicao(',
'            p_codigo_artefato => ''PR2'',',
'            p_id_tenant       => v_new.id_tenant,',
'            p_id_usuario      => v_new.id_usuario_alterou,',
'            p_id_negocio      => v_new.id,',
'            p_payload         => ''{"id_invoice":"''||v_new.id_invoice||''"}'',',
'            p_prioridade      => 0,',
'            p_tipo_acao       => ''Origem: BO_IMP_INVOICE_ITEM.hook_depois_incluir'',',
'            p_id_correlation  => null',
'        );',
'',
'        --bo_imp_invoice.altera_valor_desconto_invoice_item(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        l_id := pkg_maestro_api.postar_requisicao(',
'            p_codigo_artefato => ''PR3'', --altera_valor_desconto_invoice_item',
'            p_id_tenant       => v_new.id_tenant,',
'            p_id_usuario      => v_new.id_usuario_alterou,',
'            p_id_negocio      => v_new.id,',
'            p_payload         => ''{"id_invoice":"''||v_new.id_invoice||''"}'',',
'            p_prioridade      => 0,',
'            p_tipo_acao       => ''Origem: BO_IMP_INVOICE_ITEM.hook_depois_incluir'',',
'            p_id_correlation  => null',
'        );',
'',
'        v_new.id := null;',
'    end;',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
unistr('        -- Garante c\00E1lculos corretos para colunas calculadas:'),
'        v_new.valor_total_mercadoria := (v_new.quantidade * (v_new.valor_unitario - v_new.valor_desconto));',
'        v_new.valor_total_condicao_venda := (nvl(v_new.valor_total_mercadoria, 0) - nvl(v_new.valor_total_desconto_invoice_item, 0) + nvl(v_new.valor_total_despesa_invoice_item, 0));',
'        v_new.peso_liquido_total := (v_new.quantidade * v_new.peso_unitario);',
'        v_new.peso_bruto_total := (v_new.quantidade * v_new.peso_bruto_unitario);        ',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id number;',
'    begin ',
'        bo_imp_invoice.atualiza_valores(v_new.id_invoice,v_pagina,p_encadeado,p_sucesso,p_messages);        ',
'        altera_quantidade_faturada(v_new.id,v_pagina,p_encadeado,p_sucesso,p_messages);',
'        altera_invoice_valores(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'        if v_operacao in (''ALTERA_INVOICE_ITEM'',''ALTERA_QUANTIDADE'') then',
'            bo_imp_invoice.gerencia_divergencias(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'            --recalcula_rateio_invoice_item_despesa(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            l_id := pkg_maestro_api.postar_requisicao(',
'                p_codigo_artefato => ''PR2'',',
'                p_id_tenant       => v_new.id_tenant,',
'                p_id_usuario      => v_new.id_usuario_alterou,',
'                p_id_negocio      => v_new.id,',
'                p_payload         => ''{"id_invoice":"''||v_new.id_invoice||''"}'',',
'                p_prioridade      => 0,',
'                p_tipo_acao       => ''Origem: BO_IMP_INVOICE_ITEM.hook_depois_alterar'',',
'                p_id_correlation  => null',
'            );',
'            --bo_imp_invoice.altera_valor_desconto_invoice_item(v_new.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'            l_id := pkg_maestro_api.postar_requisicao(',
'                p_codigo_artefato => ''PR3'', --altera_valor_desconto_invoice_item',
'                p_id_tenant       => v_new.id_tenant,',
'                p_id_usuario      => v_new.id_usuario_alterou,',
'                p_id_negocio      => v_new.id,',
'                p_payload         => ''{"id_invoice":"''||v_new.id_invoice||''"}'',',
'                p_prioridade      => 0,',
'                p_tipo_acao       => ''Origem: BO_IMP_INVOICE_ITEM.hook_depois_alterar'',',
'                p_id_correlation  => null',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'        l_id number;',
'    begin',
'        if nvl(v_operacao, ''-20001'') <> ''EXCLUI_INVOICE_ITEM'' then',
'            bo_imp_invoice.atualiza_valores(v_old.id_invoice,v_pagina,p_encadeado,p_sucesso,p_messages);',
'        end if;',
'',
'        altera_quantidade_faturada(v_old.id,v_pagina,p_encadeado,p_sucesso,p_messages);',
'        altera_invoice_valores(v_old.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'        bo_imp_invoice.gerencia_divergencias(v_old.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'',
'        --recalcula_rateio_invoice_item_despesa(v_old.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        l_id := pkg_maestro_api.postar_requisicao(',
'            p_codigo_artefato => ''PR2'',',
'            p_id_tenant       => v_old.id_tenant,',
'            p_id_usuario      => v_old.id_usuario_alterou,',
'            p_id_negocio      => v_old.id,',
'            p_payload         => ''{"id_invoice":"''||v_old.id_invoice||''"}'',',
'            p_prioridade      => 0,',
'            p_tipo_acao       => ''Origem: BO_IMP_INVOICE_ITEM.hook_depois_excluir'',',
'            p_id_correlation  => null',
'        );',
'',
'        --bo_imp_invoice.altera_valor_desconto_invoice_item(v_old.id_invoice, v_pagina, p_encadeado, p_sucesso, p_messages);',
'        l_id := pkg_maestro_api.postar_requisicao(',
'            p_codigo_artefato => ''PR3'', --altera_valor_desconto_invoice_item',
'            p_id_tenant       => v_old.id_tenant,',
'            p_id_usuario      => v_old.id_usuario_alterou,',
'            p_id_negocio      => v_old.id,',
'            p_payload         => ''{"id_invoice":"''||v_old.id_invoice||''"}'',',
'            p_prioridade      => 0,',
'            p_tipo_acao       => ''Origem: BO_IMP_INVOICE_ITEM.hook_depois_excluir'',',
'            p_id_correlation  => null',
'        );',
'    end; ',
'    --',
'    function gera_sequencia_item(',
'        p_id_invoice in imp_invoice_item.id_invoice%type',
'    ) return number is',
'        l_sequencia number;',
'    begin',
'        select nvl(max(sequencia_item_invoice), 0) into l_sequencia from imp_invoice_item where id_invoice = p_id_invoice;',
'        return l_sequencia + 1;',
'    end gera_sequencia_item;',
'    --',
'    function detalhe_registro (',
'        p_id in imp_invoice_item.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''[',
'            select                 ',
'                b.num_invoice as imp_invoice_item$id_invoice,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_status'',b.ind_status) as imp_invoice$ind_status,',
'                nvl(f.num_processoimportacao,pkg_ui.retorna_label_tela(''sem_processo'')) as imp_invoice$id_processoimportacao,',
'                i.numero_pedido_importacao as imp_pedidoimportacao$numero_pedido_importacao,',
'                j.num_sequencia_item as imp_pedidoimportacao_item$num_sequencia_item,',
'                h.num_entrega as imp_entrega$num_entrega,',
'                c.codigo_item||'' - ''||pkg_traducao.get_traducao(c.descricao_item) as imp_invoice_item$id_item,',
'                d.codigo_unidademedida as imp_invoice_item$id_unidademedida, ',
'                case d.ind_tipo_dado',
'                    when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                    when ''I'' then to_char(a.quantidade)',
'                end as imp_invoice_item$quantidade,                 ',
'                to_char(a.peso_liquido_total, ''FM999G999G990D00000'') as imp_invoice_item$peso_liquido_total, ',
'                e.codigo_moeda||'' - ''||e.simbolo_iso as imp_invoice$id_moeda, ',
'                to_char(a.valor_total_mercadoria, ''FM999G999G990D00000'') as imp_invoice_item$valor_total_mercadoria',
'            from imp_invoice_item a',
'            join imp_invoice b on b.id = a.id_invoice',
'            join ng_item c on c.id = a.id_item',
'            join ng_unidademedida d on d.id = a.id_unidademedida',
'            join ng_moeda e on e.id = b.id_moeda',
'            left join imp_processoimportacao f on f.id = b.id_processoimportacao',
'            join imp_entrega_item g on g.id = a.id_entrega_item',
'            join imp_entrega h on h.id = g.id_entrega',
'            join imp_pedidoimportacao i on i.id = h.id_pedidoimportacao',
'            join imp_pedidoimportacao_item j on j.id_pedidoimportacao = i.id and j.id = g.id_pedidoimportacao_item',
'            where a.id = ]''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure altera_quantidade(',
'        p_quantidade in imp_invoice_item.quantidade%type,',
'        p_id in imp_invoice_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin        ',
'        v_parametro(0) := ''bo_imp_invoice_item.altera_quantidade'';',
'',
'        select * into v_old from imp_invoice_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.quantidade := p_quantidade;        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;  ',
'        v_data_alteracao := v_new.data_alteracao;',
'',
'        v_operacao := ''ALTERA_QUANTIDADE'';',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);   ',
'    end altera_quantidade;',
'    --',
'    procedure gerencia_invoice_item(',
'        p_json_importacaoitem in clob,        ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_json clob;',
'    begin',
'        l_json := p_json_importacaoitem;',
'        for item in (',
'            select json_item.id, pkg_util.retorna_number(json_item.qtd) qtd, json_item.id_ei',
'              from json_table(l_json, ''$[*]''',
'                columns',
'                    id    varchar2(50) path ''$.id'',',
'                    qtd   varchar2(50) path ''$.qtd'',',
'                    id_ei varchar2(50) path ''$.id_ei''',
'              ) json_item',
'        ) loop',
'            -- Tratamento alterar:',
'            if item.qtd > 0 then                ',
'                altera_quantidade(',
'                    p_quantidade => item.qtd,',
'                    p_id => item.id,                    ',
'                    p_pagina => p_pagina,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'',
'            -- Tratamento excluir:',
'            elsif item.qtd = 0 then                ',
'                exclui_registro(',
'                    p_id => item.id,',
'                    p_encadeado => p_encadeado,',
'                    p_sucesso => p_sucesso,',
'                    p_messages => p_messages',
'                );',
'            end if;            ',
'        end loop;',
'    end gerencia_invoice_item;',
'    --',
'    procedure gerencia_divergencias(',
'        p_id in imp_invoice_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_tenant number;',
'        l_id_invoice number;',
'        l_invoice_quantidade number;',
'        l_entrega_quantidade number;',
'        l_divergencia_quantidade number;',
'        l_invoice_id_unidademedida number;',
'        l_entrega_id_unidademedida number;',
'        l_divergencia_unidademedida number;',
'        l_invoice_id_ncm number;',
'        l_entrega_id_ncm number;',
'        l_divergencia_ncm number;',
'        l_invoice_valor_unitario number;',
'        l_entrega_valor_unitario number;',
'        l_divergencia_valor_unitario number;',
'        l_id number;',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice_item.gerencia_divergencias'';',
'        select id_tenant, id_invoice into l_id_tenant, l_id_invoice from imp_invoice_item where id = p_id;',
'',
'        select',
'            a.quantidade,',
'            b.quantidade, ',
'            case when a.quantidade > b.quantidade then 1 else 0 end,',
'            a.id_unidademedida,',
'            b.id_unidademedida,',
'            case when a.id_unidademedida <> b.id_unidademedida then 1 else 0 end,',
'            a.id_ncm,',
'            b.id_ncm,',
'            case when a.id_ncm <> b.id_ncm then 1 else 0 end,',
'            a.valor_unitario,',
'            b.valor_unitario,',
'            case when a.valor_unitario <> b.valor_unitario then 1 else 0 end',
'        into',
'            l_invoice_qu'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(181600560896304602)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'antidade,',
'            l_entrega_quantidade,',
'            l_divergencia_quantidade,',
'            l_invoice_id_unidademedida,',
'            l_entrega_id_unidademedida,',
'            l_divergencia_unidademedida,',
