'        join imp_entrega_item b on b.id = a.id_entrega_item--b.id_entrega = a.id_entrega and b.id_pedidoimportacao_item = a.id_pedidoimportacao_item',
'        where a.id = p_id;',
'',
unistr('        -- Inclui diverg\00EAncias de quantidade:'),
'        if l_divergencia_quantidade > 0 then            ',
'            bo_imp_invoice_divergencia.inclui_registro(',
