'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'',
unistr('        -- Inclui diverg\00EAncias de unidade de medida:'),
'        if l_divergencia_unidademedida > 0 then            ',
'            bo_imp_invoice_divergencia.inclui_registro(',
'                p_id_tenant => l_id_tenant,',
'                p_id_invoice => l_id_invoice,',
'                p_id_invoice_item => p_id,',
'                p_ind_divergencia => 8,',
'                p_conteudo_invoice => l_invoice_id_unidademedida,',
'                p_conteudo_pedido => l_entrega_id_unidademedida,',
'                p_ind_status => 1,',
'                p_observacao => null,',
'                p_id => l_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'',
unistr('        -- Inclui diverg\00EAncias de ncm:'),
'        if l_divergencia_ncm > 0 then            ',
'            bo_imp_invoice_divergencia.inclui_registro(',
'                p_id_tenant => l_id_tenant,',
'                p_id_invoice => l_id_invoice,',
'                p_id_invoice_item => p_id,',
'                p_ind_divergencia => 9,',
'                p_conteudo_invoice => l_invoice_id_ncm,',
'                p_conteudo_pedido => l_entrega_id_ncm,',
'                p_ind_status => 1,',
'                p_observacao => null,',
'                p_id => l_id,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'',
unistr('        -- Inclui diverg\00EAncias de valor unit\00E1rio:'),
'        if l_divergencia_valor_unitario > 0 then            ',
'            bo_imp_invoice_divergencia.inclui_registro(',
'                p_id_tenant => l_id_tenant,',
'                p_id_invoice => l_id_invoice,',
'                p_id_invoice_item => p_id,',
'                p_ind_divergencia => 10,',
'                p_conteudo_invoice => l_invoice_valor_unitario,',
'                p_conteudo_pedido => l_entrega_valor_unitario,',
'                p_ind_status => 1,',
'                p_observacao => null,',
'                p_id => l_id,',
'                p_pagina => p_pagina,',
