'    --',
'    procedure altera_quantidade_faturada(',
'        p_id in imp_invoice_item.id%type,',
'        p_pagina in number default 0,',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table       ',
'    ) is',
'        l_verifica_invoice_item number;',
'        l_id_entrega_item number;',
'    begin',
'        v_parametro(0) := ''bo_imp_invoice_item.altera_quantidade_faturada'';',
'',
'        select count(1) into l_verifica_invoice_item from imp_invoice_item where id = p_id;',
'        if l_verifica_invoice_item > 0 then',
'            select id into l_id_entrega_item from imp_entrega_item where id = v_new.id_entrega_item;--id_entrega = v_new.id_entrega and id_pedidoimportacao_item = v_new.id_pedidoimportacao_item;',
'            bo_imp_entrega_item.altera_quantidade_faturada(',
'                p_quantidade_faturada => v_new.quantidade,',
'                p_id => l_id_entrega_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        else            ',
'            select id into l_id_entrega_item from imp_entrega_item where id = v_old.id_entrega_item;--id_entrega = v_old.id_entrega and id_pedidoimportacao_item = v_old.id_pedidoimportacao_item;',
'            bo_imp_entrega_item.altera_quantidade_faturada(',
'                p_quantidade_faturada => 0,',
'                p_id => l_id_entrega_item,',
'                p_pagina => p_pagina,',
'                p_encadeado => p_encadeado,',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'            );',
'        end if;',
'',
'    end altera_quantidade_faturada;',
'    --',
'    procedure altera_valor_total_desconto_invoice_item(',
'        p_valor_total_desconto_invoice_item in imp_invoice_item.valor_total_desconto_invoice_item%type,',
'        p_id in imp_invoice_item.id%type,',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
