'    begin ',
'        v_parametro(0) := ''bo_imp_invoice_item.altera_valor_total_desconto_invoice_item'';',
'        v_pagina := p_pagina; ',
'',
'        select * into v_old from imp_invoice_item where id = p_id;        ',
'        v_new := v_old;',
'',
'        v_new.valor_total_desconto_invoice_item := p_valor_total_desconto_invoice_item;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        --v_new.data_alteracao := sysdate;  ',
'        v_data_alteracao := v_new.data_alteracao;',
'',
