prompt --application/deployment/install/install_ui_mpd_td646
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(181965121377968262)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD646'
,p_sequence=>2840
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD646',
'-- Data: 12/05/2026',
unistr('-- Motivo: Inclu\00EDdo campo num_sequencia_item na interface'),
'-- Jira: PEDITEM-24',
'',
'create or replace package "UI_MPD_TD646" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD646";',
'/',
'',
'create or replace package body "UI_MPD_TD646" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao from imp_pedidoimportacao a where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,  ',
'                pkg_traducao.get_traducao(b.descricao_item) titulo,',
'                b.codigo_item subtitulo,                ',
'                c.codigo_unidademedida distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.num_sequencia_item'', num_sequencia_item, 2) atributo1,',
'                case c.ind_tipo_dado',
'                    when ''D'' then ',
'                        pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.quantidade'',                    ',
'                            to_char(a.quantidade, ''FM999G999G990D00000''), 2)',
'                    when ''I'' then ',
'                        pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.quantidade'',                    ',
'                            to_char(a.quantidade), 2)',
'                end atributo2,',
'                case c.ind_tipo_dado',
'                    when ''D'' then ',
'                        pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.quantidade_programar_entrega'',                    ',
'                            to_char(nvl(a.quantidade_programar_entrega,0), ''FM999G999G990D00000''), 2)',
'                    when ''I'' then ',
'                        pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.quantidade_programar_entrega'',                    ',
'                            to_char(nvl(a.quantidade_programar_entrega,0)), 2)',
'                end atributo3,',
'                pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.peso_liquido_total'', to_char(a.peso_liquido_total, ''FM999G999G990D000''), 2) atributo4,',
'                pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.valor_total'', to_char(a.valor_total, ''FM999G999G990D00''), 2) atributo5,',
'                pkg_componentes.html_card_colunas(''imp_pedidoimportacao_item.id_naturezaoperacao'', pkg_traducao.get_traducao(d.descricao), 2',
'                ) atributo6,',
'                a.num_sequencia_item,',
'                --FILTROS                ',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD646'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD646'', p_param1 => #PARAM1#) as opcao                ',
'            from imp_pedidoimportacao_item a',
'            join ng_item b on b.id = a.id_item',
'            join ng_unidademedida c on c.id = a.id_unidademedida',
'            left join imp_naturezaoperacao d on d.id = a.id_naturezaoperacao',
'            where id_pedidoimportacao = #PARAM1#',
'            order by 12',
'        ~'';       ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select distinct',
'            a.id id,  ',
'            num_sequencia_item campo1,',
'            b.codigo_item campo2,',
'            pkg_traducao.get_traducao(b.descricao_item) campo3,',
'            c.codigo_unidademedida campo4,',
'            case c.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade)',
'            end campo5,',
'            case c.ind_tipo_dado',
'                when ''D'' then to_char(nvl(a.quantidade_programar_entrega,0), ''FM999G999G990D00000'')',
'                when ''I'' then to_char(nvl(a.quantidade_programar_entrega,0))',
'            end campo6,',
'            to_char(a.peso_liquido_total, ''FM999G999G990D000'') campo7,',
'            to_char(a.valor_total, ''FM999G999G990D00'') campo8,',
'            pkg_traducao.get_traducao(d.descricao) campo9,',
'            #PARAM1# campo10,',
'            --FILTROS',
'            null filtro1,',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            null opcao',
'        from imp_pedidoimportacao_item a',
'        join ng_item b on b.id = a.id_item',
'        join ng_unidademedida c on c.id = a.id_unidademedida',
'        left join imp_naturezaoperacao d on d.id = a.id_naturezaoperacao',
'        where id_pedidoimportacao = #PARAM1#',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                ',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD646'', p_param1 => campo10) as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_pedidoimportacao_item'')) a',
'            order by campo1',
'            ~'';',
'        --l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;   ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.num_sequencia_item'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.id_unidademedida'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.quantidade'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.quantidade_programar_entrega'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.peso_liquido_total'') into l_campo from dual;',
'        elsif campo = ''8'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.valor_total'') into l_campo from dual;',
'        elsif campo = ''9'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_pedidoimportacao_item.id_naturezaoperacao'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia, nome_fantasia'';',
'        else',
'            campos := ''campo5, campo2'';',
'        end if;',
'        labels := label_coluna(''5'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD646";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td870
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(182181136283469116)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD870'
,p_sequence=>2860
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 24/06/2026',
unistr('-- Motivo: Inclus\00E3o da coluna id_numerario_despesa na entidade imp_pedidoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade imp_processoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 25/04/2026',
unistr('-- Motivo: Ajustes nas chamadas do bo_imp_processoimportacao_despesa devido adi\00E7\00E3o de novas colunas'),
'-- Jira: PEDITEM-162',
'',
'-- Objeto: UI_MPD_TD870',
'-- Data: 12/05/2026',
unistr('-- Motivo: Corrigido campo valor para \201Cvalor_realizado\201D'),
'-- Jira: PEDITEM-240',
'',
'create or replace package "UI_MPD_TD870" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    function label_acao return varchar2;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );   ',
'',
'end "UI_MPD_TD870";',
'/',
'',
'create or replace package body "UI_MPD_TD870" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;        ',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    c.nome_fantasia id_tenant,',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_despesa'''', ''''ind_status_despesa'''', b.ind_status_despesa) ind_status_despesa,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_despesa'''', ''''ind_status_pagamento'''', b.ind_status_pagamento) ind_status_pagamento',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'                join mpd_tenant c on c.id = b.id_tenant',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao_despesa'',''imp_processoimportacao_despesa''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_html clob;',
'    begin',
'        l_html := ''<div class="a-CardView-headerBody" style="display: flex; justify-content: start; align-items: center; padding: 0.5rem; margin-left: 0.2rem"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.116.l'')||''</h3></div>'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_documento_despesa'',       3, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',      4, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_numerario_despesa'',       5, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despesa'',                 6,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda_prevista'',          8,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_previsto'',            10, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_realizada'',        11,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_realizado'',           13,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''taxa_cambio'',               14, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_status_despesa'',        15, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pagamento'',      16, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda_documento'',        17,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_moeda_documento'',     19,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_moeda_nacional'',      20, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',            21, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, '''',                          22, ''HTM'', null, ''S'', ''N'', null valor, l_html html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_rateio'',          23, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_compoe_custo_operacao'', 24, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_participa_nfe'',         25, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_despesa_base_calculo'',  26, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_despesa'',          27, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html);',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin        ',
'        bo_imp_processoimportacao_despesa.altera_registro(',
'            p_id_tenant                 => apex_application.g_f02(1),',
'            p_id_documento_despesa      => apex_application.g_f03(1),',
'            p_id_processoimportacao     => apex_application.g_f04(1),',
'            p_id_numerario_despesa      => apex_application.g_f05(1),',
'            p_id_despesa                => apex_application.g_f06(1),',
'            p_id_moeda_prevista         => apex_application.g_f08(1),',
'            p_valor_previsto            => pkg_util.retorna_number(apex_application.g_f10(1)),',
'            p_id_moeda_realizada        => apex_application.g_f11(1),',
'            p_valor_realizado           => pkg_util.retorna_number(apex_application.g_f13(1)),',
'            p_taxa_cambio               => pkg_util.retorna_number(apex_application.g_f14(1)),',
'            p_ind_status_despesa        => apex_application.g_f15(1),',
'            p_ind_status_pagamento      => 3,--apex_application.g_f16(1),',
'            p_id_moeda_documento        => apex_application.g_f17(1),',
'            p_valor_moeda_documento     => pkg_util.retorna_number(apex_application.g_f19(1)),            ',
'            p_valor_moeda_nacional      => pkg_util.retorna_number(apex_application.g_f20(1)),',
'            p_data_alteracao            => to_timestamp(apex_application.g_f21(1), ''dd-mon-rr hh:mi:ss:ff am''),            ',
'            p_ind_forma_rateio          => apex_application.g_f23(1),',
'            p_ind_compoe_custo_operacao => apex_application.g_f24(1),',
'            p_ind_participa_nfe         => apex_application.g_f25(1),',
'            p_ind_despesa_base_calculo  => apex_application.g_f26(1),',
'            p_ind_tipo_despesa          => apex_application.g_f27(1),',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );        ',
'    end post;',
'',
'end "UI_MPD_TD870";',
'/'))
);
end;
