prompt --application/deployment/install/install_ui_mpd_td591
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(182864590214503752)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD591'
,p_sequence=>2870
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 10/06/2026',
'-- Motivo: Alterado campos da interface. id_moeda_prevista, e id_moeda_realizada',
'-- Jira: PEDITEM-91',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade imp_processoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Objeto: UI_MPD_TD591',
'-- Data: 13/05/2026',
unistr('-- Motivo: Incluso coluna \201Cvalor_realizado\201D na lista e revisado regras das a\00E7\00F5es do registro'),
'-- Jira: PEDITEM-91',
'',
'create or replace package "UI_MPD_TD591" as   ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'   ',
'end "UI_MPD_TD591";',
'/',
'',
'create or replace package body "UI_MPD_TD591" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;        ',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador',
'                from imp_processoimportacao a',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_url clob;',
'        l_html clob;',
'        l_html_nodatafound clob;     ',
'        l_verifica number;   ',
'        l_sql_grid_1 clob;        ',
'        l_novo varchar2(4000) := pkg_ui.retorna_label_botao(''novo'');',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO'', ',
'            p_values => ''TD738,TD738,''||p_param1,',
'            p_triggering_element => ''apex.jQuery("#NEW")'',',
'            p_clear_cache => 9010',
'        );',
'        l_html := ''<div id="NEW" style="display: flex; align-items: center; justify-content: end;"><a id="NEW" href="''||l_url||''"><button id="NEW" class="t-Button t-Button--icon js-ignoreChange t-Button--success t-Button--iconLeft lto5893482872689621'
||'6_0 t-Button--hot" style="margin-top:0px;" type="button"><span class="t-Icon t-Icon--left fa fa-plus-circle" aria-hidden="true"></span><span class="t-Button-label">''||l_novo||''</span><span class="t-Icon t-Icon--right fa fa-plus-circle" aria-hidden="t'
||'rue"></span></button></a></div>'';          ',
'        ',
'        l_html_nodatafound := l_html || ''<div role="region" aria-label="Mensagem" class="a-IRR-noDataMsg"><div class="a-IRR-noDataMsg-icon"><span class="a-Icon icon-irr-no-results" aria-hidden="true"></span></div><span class="a-IRR-noDataMsg-text">Ne'
||'nhum registro adicionado ainda.</span></div>'';',
'',
'        select count(1) into l_verifica from imp_processoimportacao a join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id where a.id = p_param1;',
'        if l_verifica > 0 then',
'            l_sql_grid_1 := ',
'            q''~',
'                select ',
'                    pkg_traducao.get_traducao(c.descricao_despesa) imp_processoimportacao_despesa$id_despesa,',
'                    to_char(d.codigo_moeda||'' - ''||d.simbolo_iso) imp_processoimportacao_despesa$id_moeda_prevista,',
'                    to_char(b.valor_previsto, ''FM999G999G990D00'') imp_processoimportacao_despesa$valor_previsto,',
'                    to_char(e.codigo_moeda||'' - ''||e.simbolo_iso) imp_processoimportacao_despesa$id_moeda_realizada,',
'                    to_char(b.valor_realizado, ''FM999G999G990D00'') imp_processoimportacao_despesa$valor_realizado,',
'                    pkg_util.dominio_retorna_tag(''imp_processoimportacao_despesa'', ''ind_status_despesa'', b.ind_status_despesa) imp_processoimportacao_despesa$ind_status_despesa,',
'                    pkg_util.dominio_retorna_tag(''imp_processoimportacao_despesa'', ''ind_status_pagamento'', b.ind_status_pagamento) imp_processoimportacao_despesa$ind_status_pagamento,',
'                    --pkg_componentes.html_botao_opcao(p_id => b.id, p_pagina => ''TD591'', p_param1 => ''0'') opcao',
'                    pkg_componentes.html_botao_opcao_com_icone(p_id => b.id, p_pagina => ''TD591'', p_param1 => ''0'') opcao',
'                from imp_processoimportacao a ',
'                join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'                join ng_despesa c on c.id = b.id_despesa',
'                left join ng_moeda d on d.id = b.id_moeda_prevista',
'                left join ng_moeda e on e.id = b.id_moeda_realizada',
'                where a.id = #PARAM1#            ',
'            ~'';   ',
'            l_sql_grid_1 := replace(l_sql_grid_1, ''#PARAM1#'', p_param1);',
'',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, null valor, l_html html, null tag_campo FROM dual UNI'
||'ON ALL',
'                   SELECT p_codigo_artefato AS codigo_artefato, ''coluna2'' AS nome_coluna, 1 AS indice, ''GRI'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, to_char(l_sql_grid_1) valor, null html, null tag_camp'
||'o FROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);',
'        else',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, null valor, l_html_nodatafound html, null tag_campo F'
||'ROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);',
'        end if;',
'    end formulario;    ',
'    ',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        null;',
'    end;    ',
'',
'end "UI_MPD_TD591";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td791
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(184787259187309711)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD791'
,p_sequence=>2880
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD791',
'-- Data: 13/05/2026',
'-- Motivo: Incluso campo id_moeda',
'-- Jira: PEDITEM-111',
'',
'create or replace package "UI_MPD_TD791" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos out varchar2,',
'        labels out varchar2',
'    );',
'',
'end "UI_MPD_TD791";',
'/',
'',
'create or replace package body "UI_MPD_TD791" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''',''''ind_status'''',a.ind_status) ind_status',
'                from imp_processoimportacao a ',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                a.id,  ',
'                pkg_traducao.get_traducao(b.descricao_item) titulo,',
'                b.codigo_item subtitulo,                ',
'                c.codigo_unidademedida distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                case c.ind_tipo_dado',
'                    when ''D'' then ',
'                        pkg_componentes.html_card_colunas(''imp_processoimportacao_item.quantidade'',                    ',
'                            to_char(a.quantidade, ''FM999G999G990D00000''), 2)',
'                    when ''I'' then ',
'                        pkg_componentes.html_card_colunas(''imp_processoimportacao_item.quantidade'',',
'                            to_char(a.quantidade), 2)',
'                end atributo1,                ',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao_item.peso_liquido_total'', to_char(a.peso_liquido_total, ''FM999G999G990D000''), 2) atributo2,',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao_item.id_moeda'', e.codigo_moeda||'' - ''||e.simbolo_iso, 2) atributo3,',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao_item.valor_total_condicao_venda'', to_char(a.valor_total_condicao_venda, ''FM999G999G990D00''), 2) atributo4,',
'                pkg_componentes.html_card_colunas(''imp_processoimportacao_item.id_naturezaoperacao'',pkg_traducao.get_traducao(d.descricao), 2) atributo5,',
'                --FILTROS                ',
'                null FILTRO_MULT1,  ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD791'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD791'', p_param1 => 0) as opcao                ',
'            from imp_processoimportacao_item a',
'            join ng_item b on b.id = a.id_item',
'            join ng_unidademedida c on c.id = a.id_unidademedida',
'            left join imp_naturezaoperacao d on d.id = a.id_naturezaoperacao',
'            join ng_moeda e on e.id = a.id_moeda',
'            where id_processoimportacao = #PARAM1#',
'            order by titulo',
'        ~'';       ',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select',
'            a.id id,  ',
'            b.codigo_item campo1,',
'            pkg_traducao.get_traducao(b.descricao_item) campo2,',
'            c.codigo_unidademedida campo3,',
'            case c.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00000'')',
'                when ''I'' then to_char(a.quantidade)',
'            end campo4,            ',
'            to_char(a.peso_liquido_total, ''FM999G999G990D000'') campo5,',
'            e.codigo_moeda||'' - ''||e.simbolo_iso campo6,',
'            to_char(a.valor_total_condicao_venda, ''FM999G999G990D00'') campo7,',
'            pkg_traducao.get_traducao(d.descricao) campo8,',
'            null campo9,',
'            null campo10,',
'            --FILTROS',
'            null filtro1,',
'            null filtro2,',
'            null filtro3,',
'            null filtro4,',
'            null filtro5,',
'            null FILTRO_MULT1,  ',
'            null FILTRO_MULT2,  ',
'            null FILTRO_MULT3,  ',
'            null FILTRO_MULT4,  ',
'            null FILTRO_MULT5,  ',
'            null opcao',
'        from imp_processoimportacao_item a',
'        join ng_item b on b.id = a.id_item',
'        join ng_unidademedida c on c.id = a.id_unidademedida',
'        left join imp_naturezaoperacao d on d.id = a.id_naturezaoperacao',
'        join ng_moeda e on e.id = a.id_moeda',
'        where id_processoimportacao = #PARAM1#',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                ',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD791'', p_param1 => 0) as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_processoimportacao_item'')) a',
'            order by campo2',
'            ~'';        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;   ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.codigo_item'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_item.descricao_item'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_item.id_unidademedida'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_item.quantidade'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_item.peso_liquido_total'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_item.id_moeda'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_item.valor_total_condicao_venda'') into l_campo from dual;',
'        elsif campo = ''8'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_processoimportacao_item.id_naturezaoperacao'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia, nome_fantasia'';',
'        else',
'            campos := ''campo5, campo2'';',
'        end if;',
'        labels := label_coluna(''5'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'',
'end "UI_MPD_TD791";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td911
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(188782461267060562)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD911'
,p_sequence=>2900
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD911',
'-- Data: 15/05/2026',
unistr('-- Motivo: Inclu\00EDdo campos numero_pedido_importacao, num_sequencia_item e num_entrega.'),
'-- Jira: PEDITEM-181',
'',
'create or replace package "UI_MPD_TD911" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'',
'end "UI_MPD_TD911";',
'/',
'',
'create or replace package body "UI_MPD_TD911" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_invoice,',
'                    pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                    case',
'                        when c.num_processoimportacao is not null then',
'                            c.num_processoimportacao',
'                        else',
'                            pkg_componentes.html_cor_texto(pkg_ui.retorna_label_tela(''''sem_processo''''))',
'                    end id_processoimportacao',
'                from imp_invoice a',
'                join imp_invoice_item b on b.id_invoice = a.id',
'                left join imp_processoimportacao c on c.id = a.id_processoimportacao            ',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );   ',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is        ',
'        l_moeda varchar2(4000);',
'        l_atribuir_valor_unidademedida clob;',
'        l_campos_unidademedida apex_t_varchar2 := apex_t_varchar2(''CASAS_DECIMAIS'');',
'        v_executa_js_digito clob;',
'        l_JSON_calcular_valor_total clob;  ',
'        l_qtd_casas_decimais varchar2(1);',
'        l_numero_pedido_importacao varchar2(4000);',
'        l_num_sequencia_item varchar2(4000);',
'        l_num_entrega varchar2(4000);',
'    begin',
'        select c.codigo_moeda||'' - ''||c.simbolo_iso into l_moeda from imp_invoice a join imp_invoice_item b on b.id_invoice = a.id join ng_moeda c on c.id = a.id_moeda where b.id = p_param1;',
'',
'        l_atribuir_valor_unidademedida := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_unidademedida'',',
'            l_campos_unidademedida',
'        );',
'',
'        prc_enviar_parametros(''TD911'',''id_unidademedida'',p_param1);',
'        v_executa_js_digito := ''atualizarDigitsCampo("QUANTIDADE","CASAS_DECIMAIS")'';',
'',
'        l_JSON_calcular_valor_total := gerar_json_lista(',
'            SYS.ODCIVARCHAR2LIST(''QUANTIDADE * (VALOR_UNITARIO - VALOR_DESCONTO)'', ''QUANTIDADE * PESO_UNITARIO'', ''QUANTIDADE * PESO_BRUTO_UNITARIO''),',
'            SYS.ODCIVARCHAR2LIST(''VALOR_TOTAL_MERCADORIA'', ''PESO_LIQUIDO_TOTAL'', ''PESO_BRUTO_TOTAL'')',
'        );',
'',
'        select case b.ind_tipo_dado when ''D'' then 5 else 0 end into l_qtd_casas_decimais from imp_invoice_item a join ng_unidademedida b on b.id = a.id_unidademedida where a.id = p_param1;',
'',
'        select ',
'            d.numero_pedido_importacao,',
'            e.num_sequencia_item,',
'            c.num_entrega',
'        into',
'            l_numero_pedido_importacao,',
'            l_num_sequencia_item,',
'            l_num_entrega',
'        from imp_invoice_item a',
'        join imp_entrega_item b on b.id = a.id_entrega_item',
'        join imp_entrega c on c.id = b.id_entrega',
'        join imp_pedidoimportacao d on d.id = c.id_pedidoimportacao',
'        join imp_pedidoimportacao_item e on e.id_pedidoimportacao = d.id and e.id = b.id_pedidoimportacao_item',
'        where a.id = p_param1;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null atribuir_valor, null c'
||'alcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_invoice'',                   2, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_entrega'',                   3, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_entrega_item'',              4, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''sequencia_item_invoice'',       5, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_pedido_importacao'',     6, ''TXT'', null, ''S'', ''N'', l_numero_pedido_importacao valor, ''imp_pedidoimportacao.numero_pedido_importacao'' tag_campo, null atribuir_valor, null calcular_valor, null executa_js '
||'FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_sequencia_item'',           7, ''TXT'', null, ''S'', ''N'', l_num_sequencia_item valor, ''imp_pedidoimportacao_item.num_sequencia_item'' tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM du'
||'al UNION ALL',
'               SELECT p_codigo_artefato, ''num_entrega'',                  8, ''TXT'', null, ''S'', ''N'', l_num_entrega valor, ''imp_entrega.num_entrega'' tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_item'',                      9,    '''', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_ncm'',                      11,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',            13,    '''', null, ''S'', ''S'', null valor, null tag_campo, /*l_atribuir_valor_unidademedida*/null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''QUANTIDADE'',                  15,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PESO_UNITARIO'',               16,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PESO_LIQUIDO_TOTAL'',          17,    '''', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''PESO_BRUTO_UNITARIO'',         18,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''PESO_BRUTO_TOTAL'',            19,    '''', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                    20, ''TXT'', null, ''S'', ''N'', l_moeda valor, ''imp_invoice.id_moeda'' tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''VALOR_UNITARIO'',              21,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_DESCONTO'',              22,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_TOTAL_MERCADORIA'',      23,    '''', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_fabricante'',               24,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais_origem'',              26,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',              28,    '''', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''CASAS_DECIMAIS'',              29, ''HID'', null, ''N'', ''N'', l_qtd_casas_decimais valor, null tag_campo, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_desconto_invoice_item'', 30, ''HID'', null, ''N'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_condicao_venda'',        31, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_despesa_invoice_item'',  32, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null atribuir_valor, null calcular_valor, null executa_js FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, atribuir_valor, calcular_valor, executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.tag_campo, new_data.atribuir_valor, new_da'
||'ta.calcular_valor, new_data.executa_js);    ',
'    end formulario;',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob is        ',
'        l_sql clob;        ',
'    begin',
'        l_sql := q''~ ',
'            select',
'                case ind_tipo_dado',
'                    when ''D'' then 5',
'                    when ''I'' then 0',
'                end CASAS_DECIMAIS',
'            from ng_unidademedida a            ',
'            where a.id = #ID#',
'       ~'';        ',
'        l_sql := replace(l_sql,''#ID#'',p_param1);',
'        return l_sql;',
'    end sql_atribuir_valor_unidademedida;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is        ',
'    begin        ',
'        bo_imp_invoice_item.altera_invoice_item(        ',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_invoice => apex_application.g_f02(1),',
'            p_id_entrega => apex_application.g_f03(1),',
'            p_id_entrega_item => apex_application.g_f04(1),',
'            p_sequencia_item_invoice => apex_application.g_f05(1),',
'            p_id_item => apex_application.g_f09(1),',
'            p_id_ncm => apex_application.g_f11(1),',
'            p_id_unidademedida => apex_application.g_f13(1),',
'            p_quantidade => pkg_util.retorna_number(apex_application.g_f15(1)),',
'            p_peso_unitario => pkg_util.retorna_number(apex_application.g_f16(1)),',
'            p_peso_liquido_total => pkg_util.retorna_number(apex_application.g_f17(1)),',
'            p_peso_bruto_unitario => pkg_util.retorna_number(apex_application.g_f18(1)),',
'            p_peso_bruto_total => pkg_util.retorna_number(apex_application.g_f19(1)),',
'            p_valor_unitario => pkg_util.retorna_number(apex_application.g_f21(1)),',
'            p_valor_desconto => pkg_util.retorna_number(apex_application.g_f22(1)),',
'            p_valor_total_mercadoria => pkg_util.retorna_number(apex_application.g_f23(1)),',
'            p_id_fabricante => apex_application.g_f24(1),',
'            p_id_pais_origem => apex_application.g_f26(1),',
'            p_data_alteracao => to_timestamp(apex_application.g_f28(1), ''dd-mon-rr hh:mi:ss.ff am''),            ',
'            p_valor_total_desconto_invoice_item => pkg_util.retorna_number(apex_application.g_f30(1)),',
'            p_valor_total_condicao_venda => pkg_util.retorna_number(apex_application.g_f31(1)),',
'            p_valor_total_despesa_invoice_item => pkg_util.retorna_number(apex_application.g_f32(1)),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages                         ',
'        );        ',
'    end post;    ',
'',
'end "UI_MPD_TD911";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td834
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(188784931237773699)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD834'
,p_sequence=>2910
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD834" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD834";',
'/',
'',
'',
'create or replace package body "UI_MPD_TD834" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''',''''ind_status'''',a.ind_status) ind_status',
'                from imp_processoimportacao a',
'                where a.id = ''||p_param1,',
