prompt --application/deployment/install/install_monta_json_campos_ordenacao
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(188803257086127711)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'MONTA_JSON_CAMPOS_ORDENACAO'
,p_sequence=>2930
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace function monta_json_campos_ordenacao(',
'    p_campos    in varchar2,',
'    p_labels    in varchar2,',
'    p_direcoes  in varchar2 default null',
') return clob is',
'    l_json           clob;',
'    l_arr_campos     apex_t_varchar2;',
'    l_arr_labels     apex_t_varchar2;',
'    l_arr_directions apex_t_varchar2;',
'    l_direction      varchar2(10);',
'begin',
'    l_arr_campos := apex_string.split(p_campos, '','');',
'    l_arr_labels := apex_string.split(p_labels, '','');',
'',
'    if trim(p_direcoes) is not null then',
'        l_arr_directions := apex_string.split(p_direcoes, '','');',
'    end if;',
'',
'    apex_json.initialize_clob_output;',
'    apex_json.open_array;',
'',
'    for i in 1 .. l_arr_campos.count loop',
'',
'        if l_arr_directions.exists(i) then',
'            l_direction := case upper(trim(l_arr_directions(i)))',
'                               when ''DESC'' then ''DESC''',
'                               else ''ASC''',
'                           end;',
'        else',
'            l_direction := ''ASC'';',
'        end if;',
'',
'        apex_json.open_object;',
'        apex_json.write(''key'', trim(l_arr_campos(i)));',
'',
'        if l_arr_labels.exists(i) then',
'            apex_json.write(''label'', trim(l_arr_labels(i)));',
'        else',
'            apex_json.write(''label'', trim(l_arr_campos(i)));',
'        end if;',
'',
'        apex_json.write(''direction'', l_direction);',
'        apex_json.close_object;',
'',
'    end loop;',
'',
'    apex_json.close_array;',
'',
'    l_json := apex_json.get_clob_output;',
'    apex_json.free_output;',
'',
'    return l_json;',
'end monta_json_campos_ordenacao;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td975
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(188984142734153651)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD975'
,p_sequence=>2940
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 24/06/2026',
unistr('-- Motivo: Inclus\00E3o da coluna id_numerario_despesa na entidade imp_pedidoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade imp_processoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 25/04/2026',
unistr('-- Motivo: Ajustes nas chamadas do bo_imp_processoimportacao_despesa devido adi\00E7\00E3o de novas colunas'),
'-- Jira: PEDITEM-162',
'',
'-- Objeto: UI_MPD_TD975',
'-- Data: 15/05/2026',
unistr('-- Motivo: Desenvolvimento desconfirmar pagamento da despesa do processo de importa\00E7\00E3o'),
'-- Jira: PEDITEM-315',
'',
'create or replace package "UI_MPD_TD975" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    function label_acao return varchar2;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );   ',
'',
'end "UI_MPD_TD975";',
'/',
'',
'create or replace package body "UI_MPD_TD975" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;        ',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    c.nome_fantasia id_tenant,',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_despesa'''', ''''ind_status_despesa'''', b.ind_status_despesa) ind_status_despesa,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_despesa'''', ''''ind_status_pagamento'''', b.ind_status_pagamento) ind_status_pagamento',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'                join mpd_tenant c on c.id = b.id_tenant',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao_despesa'',''imp_processoimportacao_despesa''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        ) || ''</br>',
'            <div class="a-CardView-headerBody" style="display: inline-grid; padding: 0.5rem; gap: 1rem;">',
'                <h3 class="a-CardView-title">''||retorna_texto(''msg.161.l'')||''</h3>',
'                <h3 class="a-CardView-title">''||retorna_texto(''msg.161.h'')||''</h3>',
'            </div>'';',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_ind_status_pagamento varchar2(1);',
'    begin',
'        select ',
'            case when exists(',
'                select 1 from fin_titulopagamento a ',
'                join srv_entidade b on b.id = a.id_entidade ',
'                where a.id_referencia = p_param1 ',
'                and lower(b.nome_entidade) = ''imp_processoimportacao_despesa''',
'            ) then 2 else 1 end',
'        into l_ind_status_pagamento',
'        from dual;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_documento_despesa'',       3, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',      4, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_numerario_despesa'',       5, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despesa'',                 6,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda_prevista'',          8,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_previsto'',            10,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_realizada'',        11,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_realizado'',           13,    '''', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''taxa_cambio'',               14, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_despesa'',        15, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pagamento'',      16, ''HID'', null, ''S'', ''S'', l_ind_status_pagamento valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda_documento'',        17, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''valor_moeda_documento'',     19, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_moeda_nacional'',      20, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',            21, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_rateio'',          22, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_compoe_custo_operacao'', 23, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_participa_nfe'',         24, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_despesa_base_calculo'',  25, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_despesa'',          26, ''HID'', null, ''S'', ''S'', null valor, null html FROM dual',
'            ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html);',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_ind_forma_rateio          imp_processoimportacao_despesa.ind_forma_rateio%type;',
'        l_ind_compoe_custo_operacao imp_processoimportacao_despesa.ind_compoe_custo_operacao%type;',
'        l_ind_participa_nfe         imp_processoimportacao_despesa.ind_participa_nfe%type;',
'        l_ind_despesa_base_calculo  imp_processoimportacao_despesa.ind_despesa_base_calculo%type;',
'        l_ind_tipo_despesa          imp_processoimportacao_despesa.ind_tipo_despesa%type;',
'    begin',
'        if apex_application.g_f16(1) = ''2'' then',
'            l_ind_forma_rateio          := apex_application.g_f22(1);',
'            l_ind_compoe_custo_operacao := apex_application.g_f23(1);',
'            l_ind_participa_nfe         := apex_application.g_f24(1);',
'            l_ind_despesa_base_calculo  := apex_application.g_f25(1);',
