unistr('            p_ds_mensagem => ''Fim da inclus\00E3o de registro'''),
'        );',
'    end inclui_registro; ',
'    --',
'    procedure altera_registro(  ',
'        p_id_tenant in ng_recinto_alfandegado.id_tenant%type,',
'        p_codigo_recinto_alfandegado in ng_recinto_alfandegado.codigo_recinto_alfandegado%type,',
'        p_descricao_recinto_alfandegado in ng_recinto_alfandegado.descricao_recinto_alfandegado%type,',
'        p_id_unidade_local_rfb in ng_recinto_alfandegado.id_unidade_local_rfb%type,',
'        p_id_unidade_federativa in ng_recinto_alfandegado.id_unidade_federativa%type,',
'        p_data_fim_vigencia in ng_recinto_alfandegado.data_fim_vigencia%type, ',
'        p_id in ng_recinto_alfandegado.id%type, ',
'        p_data_alteracao in ng_recinto_alfandegado.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_recinto_alfandegado'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_recinto_alfandegado.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_recinto_alfandegado where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.codigo_recinto_alfandegado := p_codigo_recinto_alfandegado;',
'        v_new.descricao_recinto_alfandegado := p_descricao_recinto_alfandegado;',
'        v_new.id_unidade_local_rfb := p_id_unidade_local_rfb;',
'        v_new.id_unidade_federativa := p_id_unidade_federativa;',
'        v_new.data_fim_vigencia := p_data_fim_vigencia; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_recinto_alfandegado'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_recinto_alfandegado'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out ng_recinto_alfandegado.id_tenant%type,',
'        p_codigo_recinto_alfandegado out ng_recinto_alfandegado.codigo_recinto_alfandegado%type,',
'        p_descricao_recinto_alfandegado out ng_recinto_alfandegado.descricao_recinto_alfandegado%type,',
'        p_id_unidade_local_rfb out ng_recinto_alfandegado.id_unidade_local_rfb%type,',
'        p_id_unidade_federativa out ng_recinto_alfandegado.id_unidade_federativa%type,',
'        p_data_fim_vigencia out ng_recinto_alfandegado.data_fim_vigencia%type, ',
'        p_id in out ng_recinto_alfandegado.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_recinto_alfandegado'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_recinto_alfandegado.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            codigo_recinto_alfandegado,',
'            descricao_recinto_alfandegado,',
'            id_unidade_local_rfb,',
'            id_unidade_federativa,',
'            data_fim_vigencia, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_codigo_recinto_alfandegado,',
'            p_descricao_recinto_alfandegado,',
'            p_id_unidade_local_rfb,',
'            p_id_unidade_federativa,',
'            p_data_fim_vigencia, ',
'            p_id ',
'        from ng_recinto_alfandegado ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_recinto_alfandegado'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
