'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_descricao_recinto_alfandegado(p_descricao_recinto_alfandegado);',
'    end valida_descricao_recinto_alfandegado;     ',
'',
'    procedure valida_id_unidade_local_rfb(p_id_unidade_local_rfb in ng_recinto_alfandegado.id_unidade_local_rfb%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_unidade_local_rfb is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.id_unidade_local_rfb''); ',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico se houver',
'        hook_valida_id_unidade_local_rfb(p_id_unidade_local_rfb);',
'    end valida_id_unidade_local_rfb;  ',
'',
'    procedure valida_id_unidade_federativa(p_id_unidade_federativa in ng_recinto_alfandegado.id_unidade_federativa%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_unidade_federativa is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.id_unidade_federativa''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_unidade_federativa'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_unidade_federativa(p_id_unidade_federativa);',
'    end valida_id_unidade_federativa;   ',
'',
'    procedure valida_data_fim_vigencia(p_data_fim_vigencia in ng_recinto_alfandegado.data_fim_vigencia%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_data_fim_vigencia is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.data_fim_vigencia''); ',
'         else ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_recinto_alfandegado.data_fim_vigencia'');                         ',
'            pkg_util.valida_formato_data(',
'                p_data     => p_data_fim_vigencia,',
'                p_campo           => ''data_fim_vigencia'',',
'                p_parametro       => v_parametro,',
'                p_pagina          => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            if v_message.mensagem is not null then',
unistr('                -- Inserir o registro na cole\00E7\00E3o                '),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;                        ',
'            end if; ',
'',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_data_fim_vigencia(p_data_fim_vigencia);',
'    end valida_data_fim_vigencia;    ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_id_tenant(p_id_tenant in ng_recinto_alfandegado.id_tenant%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_tenant;     ',
'',
'    procedure hook_valida_codigo_recinto_alfandegado(p_codigo_recinto_alfandegado in ng_recinto_alfandegado.codigo_recinto_alfandegado%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_codigo_recinto_alfandegado;     ',
'',
'    procedure hook_valida_descricao_recinto_alfandegado(p_descricao_recinto_alfandegado in ng_recinto_alfandegado.descricao_recinto_alfandegado%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_descricao_recinto_alfandegado;     ',
'',
'    procedure hook_valida_id_unidade_local_rfb(p_id_unidade_local_rfb in ng_recinto_alfandegado.id_unidade_local_rfb%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_unidade_local_rfb;  ',
'',
'    procedure hook_valida_id_unidade_federativa(p_id_unidade_federativa in ng_recinto_alfandegado.id_unidade_federativa%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_unidade_federativa;   ',
'',
'    procedure hook_valida_data_fim_vigencia(p_data_fim_vigencia in ng_recinto_alfandegado.data_fim_vigencia%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_data_fim_vigencia;     ',
'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_recinto_alfandegado'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_recinto_alfandegado'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_recinto_alfandegado'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_recinto_alfandegado'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_recinto_alfandegado'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_recinto_alfandegado'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_recinto_alfandegado%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''codigo_recinto_alfandegado'', p_rec.codigo_recinto_alfandegado, true);',
'        apex_json.write(''descricao_recinto_alfandegado'', p_rec.descricao_recinto_alfandegado, true);',
'        apex_json.write(''id_unidade_local_rfb'', p_rec.id_unidade_local_rfb, true);',
'        apex_json.write(''id_unidade_federativa'', p_rec.id_unidade_federativa, true);',
'        apex_json.write(''data_fim_vigencia'', p_rec.data_fim_vigencia, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_recinto_alfandegado,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_recinto_alfandegado,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        bo_ng_traducaotexto.exclui_registros(',
'            p_nome_entidade => ''ng_recinto_alfandegado'',',
'            p_id_origem => v_old.id,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end; ',
'    --',
'    function detalhe_registro (',
'        p_id in ng_recinto_alfandegado.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select ',
'                b.nome_fantasia as ng_recinto_alfandegado$id_tenant, ',
'                a.codigo_recinto_alfandegado as ng_recinto_alfandegado$codigo_recinto_alfandegado, ',
'                a.descricao_recinto_alfandegado as ng_recinto_alfandegado$descricao_recinto_alfandegado,',
'                c.CODIGO_UNIDADE_LOCAL_RFB||'' - ''||pkg_traducao.get_traducao(c.descricao_unidade_local_rfb) as ng_recinto_alfandegado$id_unidade_local_rfb           ',
'            from ng_recinto_alfandegado a',
'            left join ng_unidadelocalrfb c on c.id = a.id_unidade_local_rfb',
'            join mpd_tenant b on b.id = a.id_tenant            ',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_recinto_alfandegado;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td581
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(191801352887330274)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD581'
,p_sequence=>2960
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD581 ',
'-- Data: 18/05/2026 ',
'-- Motivo: Ajuste de coluna id_unidade_federativa ',
'-- Jira: PNG-447',
'',
'create or replace package "UI_MPD_TD581" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD581";',
'/',
'create or replace package body "UI_MPD_TD581" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                            ',
'    begin                 ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',               2, ''SEL'', TO_CLOB(''R_MPD_TENANT.DESCRICAO_IDIOMA''), ''S'',''N'', null valor FROM dual UNION ALL     ',
'               SELECT p_codigo_artefato, ''CODIGO_RECINTO_ALFANDEGADO'',      3, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_recinto_alfandegado'',   4, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidade_local_rfb'',            5, '''', null, ''N'',''S'', null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''id_unidade_federativa'',           7, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',               9, '''', null, ''N'',''S'', null valor FROM dual                ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_ng_recinto_alfandegado.inclui_registro(  ',
'            p_id_tenant => apex_application.g_f01(1),                     ',
'            p_CODIGO_RECINTO_ALFANDEGADO => apex_application.g_f03(1),',
'            p_descricao_recinto_alfandegado => apex_application.g_f04(1),',
'            p_id_unidade_local_rfb => apex_application.g_f05(1),',
'            p_id_unidade_federativa => apex_application.g_f07(1),',
'            p_data_fim_vigencia => apex_application.g_f09(1),',
'            p_id => l_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD581";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td847
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(191988822454132001)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD847'
,p_sequence=>2970
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD847',
'-- Data: 18/05/2026',
unistr('-- Motivo: Incluso a op\00E7\00E3o para consultar os tributos dos itens.'),
'-- Jira: PEDITEM-120',
'',
'create or replace package "UI_MPD_TD847" as   ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'   ',
'end "UI_MPD_TD847";',
'/',
'',
'create or replace package body "UI_MPD_TD847" as    ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;                ',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador',
'                from imp_processoimportacao a                ',
'                where a.id = ''|| p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_tenant number;',
'        l_id_moeda_processoimportacao number;',
'        l_id_moeda_padrao_tenant number;',
'        l_sql_grid_1 clob;',
'        l_url clob;',
'        l_html clob;',
'        l_label_botao varchar2(4000) := pkg_ui.retorna_label_botao(''consultar_tributos_itens'');',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO'', ',
'            p_values => ''TD1045,TD1045,''||p_param1,',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        l_html := ''',
'        <div style="display:flex;justify-content:end;">',
'            <button',
'                class="t-Button t-Button--noLabel t-Button--icon js-ignoreChange t-Button--iconLeft lto191100262204689925_0 t-Button--hot"',
'                type="button"',
'                id="BTN_OPCAO_MODAL"',
'                onclick="window.top.location.href=''''''||l_url||'''''';">',
'                <span class="t-Icon t-Icon--left fa fa-external-link" aria-hidden="true"></span>',
'                <span class="t-Button-label">''||l_label_botao||''</span>',
'            </button>',
'        </div>'';',
'',
'        select ',
'            a.id_moeda_tenant, ',
'            a.id_tenant ',
'        into ',
'            l_id_moeda_processoimportacao,',
'            l_id_tenant',
'        from imp_processoimportacao a         ',
'        where a.id = p_param2;',
'',
'        select id_registro into l_id_moeda_padrao_tenant',
'        from mpd_configuracao_ng a        ',
'        where codigo_configuracao = 13',
'        and a.id_tenant = l_id_tenant;',
'',
'        l_sql_grid_1 := q''~',
'            select ',
'                pkg_ui.retorna_label_tela(''ii'') tributo, ',
'                (select to_char(sum(t.base_calculo_ii), ''FM999G999G990D00'') from imp_processoimportacao_item_tributo t where t.id_processoimportacao_item = b.id) base_calculo,                ',
'                to_char(a.valor_ii, ''FM999G999G990D00'') valor',
'            from imp_processoimportacao a',
'            join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'            where a.id = #PARAM2#',
'            union all ',
'            select ',
'                pkg_ui.retorna_label_tela(''ipi'') tributo,',
'                (select to_char(sum(t.base_calculo_ipi), ''FM999G999G990D00'') from imp_processoimportacao_item_tributo t where t.id_processoimportacao_item = b.id) base_calculo,',
'                to_char(a.valor_ipi, ''FM999G999G990D00'') valor',
'            from imp_processoimportacao a',
'            join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'            where a.id = #PARAM2#',
'            union all',
'            select ',
'                pkg_ui.retorna_label_tela(''pis'') tributo,',
'                (select to_char(sum(t.base_calculo_pis), ''FM999G999G990D00'') from imp_processoimportacao_item_tributo t where t.id_processoimportacao_item = b.id) base_calculo,',
'                to_char(a.valor_pis, ''FM999G999G990D00'') valor',
'            from imp_processoimportacao a',
'            join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'            where a.id = #PARAM2#',
'            union all',
'            select ',
'                pkg_ui.retorna_label_tela(''cofins'') tributo,',
'                (select to_char(sum(t.base_calculo_cofins), ''FM999G999G990D00'') from imp_processoimportacao_item_tributo t where t.id_processoimportacao_item = b.id) base_calculo,',
'                to_char(a.valor_cofins, ''FM999G999G990D00'') valor',
'            from imp_processoimportacao a',
'            join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
