'                to_char(a.valor_cbs, ''FM999G999G990D00'') valor',
'            from imp_processoimportacao a',
'            join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'            where a.id = #PARAM2#',
'            union all',
'            select ',
'                to_char(pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'', 8)) tributo,',
'                to_char(0, ''FM999G999G990D00'') base_calculo,',
