'                (select to_char(sum(t.base_calculo_icms_st), ''FM999G999G990D00'') from imp_processoimportacao_item_tributo t where t.id_processoimportacao_item = b.id) base_calculo,',
'                to_char(a.valor_icms_st, ''FM999G999G990D00'') valor',
