'                to_char(a.valor_ibs, ''FM999G999G990D00'') valor',
'            from imp_processoimportacao a',
'            join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'            where a.id = #PARAM2#',
'        ~'';',
'        l_sql_grid_1 := replace(l_sql_grid_1, ''#ID_TENANT#'', l_id_tenant);',
'        l_sql_grid_1 := replace(l_sql_grid_1, ''#ID_MOEDA_PROCESSOIMPORTACAO#'', l_id_moeda_processoimportacao);',
'        l_sql_grid_1 := replace(l_sql_grid_1, ''#ID_MOEDA_PADRAO_TENANT#'', l_id_moeda_padrao_tenant);',
'        l_sql_grid_1 := replace(l_sql_grid_1, ''#PARAM2#'', p_param2);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''col1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, to_char(l_sql_grid_1) valor, l_html html, null tag_campo FRO'
||'M dual UNION ALL',
