'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.108.l'')||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''ind_canal_parametrizado'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao,''D_IMP_DECLARACAOIMPORTACAO.IND_CANAL_PARAMETRIZADO'' AS nome_consulta, ''N'' AS somente_leitura, ''N'' as coluna_ta'
||'bela, null valor, null dependencia, null atribuir_valor, null executa_js,''imp_declaracaoimportacao.ind_canal_parametrizado'' tag_campo from dual UNION ALL',
'              SELECT p_codigo_artefato, ''data_alteracao'',                     18, '''', null, ''N'', ''S'', null, null , null , null , null from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js, new_data.tag_campo);',
'    end formulario;',
'',
'',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        v_declaracao imp_declaracaoimportacao%rowtype;',
'    begin',
'        select * into v_declaracao from imp_declaracaoimportacao where id_processoimportacao = p_id;',
'        bo_imp_declaracaoimportacao.altera_registro(',
'            p_informacao_complementar   => v_declaracao.informacao_complementar,',
'            p_id_tenant                 => v_declaracao.id_tenant,',
