'            p_peso_bruto_carga          => v_declaracao.peso_bruto_carga,',
'            p_volume                    => v_declaracao.volume,',
'            p_id_acondicionamento_carga => v_declaracao.id_acondicionamento_carga,',
'            p_id                        => v_declaracao.id,',
'            p_ind_status                => 3,',
