'        p_id_pais_procedencia_carga in imp_declaracaoimportacao.id_pais_procedencia_carga%type,',
'        p_id_urf_entrada_carga in imp_declaracaoimportacao.id_urf_entrada_carga%type,',
'        p_id_uf_nacionalizacao in imp_declaracaoimportacao.id_uf_nacionalizacao%type,',
'        p_peso_liquido_carga in imp_declaracaoimportacao.peso_liquido_carga%type,',
