unistr('    -- Fun\00E7\00F5es CRUD'),
'    --',
'    procedure cria(',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out imp_declaracaoimportacao.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_imp_declaracaoimportacao'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;',
'        --',
'        /* Executa insert */',
'        insert into imp_declaracaoimportacao (',
'            informacao_complementar,',
'            id_tenant,',
'            id_processoimportacao,',
'            numero_duimp,',
'            data_registro,',
'            ind_canal_parametrizado,',
'            id_pais_procedencia_carga,',
'            id_urf_entrada_carga,',
'            id_uf_nacionalizacao,',
'            peso_liquido_carga,',
'            peso_bruto_carga,',
'            volume,',
'            id_acondicionamento_carga,',
'            ind_status,',
'            id,',
'            id_usuario_incluiu,',
'            data_inclusao,',
'            id_usuario_alterou,',
'            data_alteracao',
'        ) values (',
'            v_new.informacao_complementar,',
'            v_new.id_tenant,',
'            v_new.id_processoimportacao,',
'            v_new.numero_duimp,',
'            v_new.data_registro,',
'            v_new.ind_canal_parametrizado,',
'            v_new.id_pais_procedencia_carga,',
'            v_new.id_urf_entrada_carga,',
'            v_new.id_uf_nacionalizacao,',
'            v_new.peso_liquido_carga,',
'            v_new.peso_bruto_carga,',
'            v_new.volume,',
'            v_new.id_acondicionamento_carga,',
'            v_new.ind_status,',
'            v_new.id,',
'            v_new.id_usuario_incluiu,',
'            v_new.data_inclusao,',
'            v_new.id_usuario_alterou,',
'            v_new.data_alteracao',
'        ) returning id into p_id;',
'        v_new.id := p_id;',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_imp_declaracaoimportacao'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_declaracaoimportacao'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_imp_declaracaoimportacao'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in imp_declaracaoimportacao.id%type,',
