'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;',
'        --',
'        /* Executa update */',
'        update imp_declaracaoimportacao set',
'            informacao_complementar = v_new.informacao_complementar,',
'            id_tenant = v_new.id_tenant,',
'            id_processoimportacao = v_new.id_processoimportacao,',
'            numero_duimp = v_new.numero_duimp,',
'            data_registro = v_new.data_registro,',
