unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_declaracaoimportacao'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_declaracaoimportacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_declaracaoimportacao'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_declaracaoimportacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_declaracaoimportacao'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_declaracaoimportacao'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;',
'    --',
'    function row_to_json(p_rec in imp_declaracaoimportacao%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''informacao_complementar'', p_rec.informacao_complementar, true);',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_processoimportacao'', p_rec.id_processoimportacao, true);',
'        apex_json.write(''numero_duimp'', p_rec.numero_duimp, true);',
'        apex_json.write(''data_registro'', p_rec.data_registro, true);',
'        apex_json.write(''ind_canal_parametrizado'', p_rec.ind_canal_parametrizado, true);',
'        apex_json.write(''id_pais_procedencia_carga'', p_rec.id_pais_procedencia_carga, true);',
'        apex_json.write(''id_urf_entrada_carga'', p_rec.id_urf_entrada_carga, true);',
'        apex_json.write(''id_uf_nacionalizacao'', p_rec.id_uf_nacionalizacao, true);',
'        apex_json.write(''peso_liquido_carga'', p_rec.peso_liquido_carga, true);',
'        apex_json.write(''peso_bruto_carga'', p_rec.peso_bruto_carga, true);',
'        apex_json.write(''volume'', p_rec.volume, true);',
'        apex_json.write(''id_acondicionamento_carga'', p_rec.id_acondicionamento_carga, true);',
'        apex_json.write(''ind_status'', p_rec.ind_status, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;',
'',
