'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        select * into v_old from imp_declaracaoimportacao where id = p_id;',
'        v_new := v_old;',
'        ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao := sysdate;',
'        v_new.ind_status := 2;',
'',
'        grava(p_id,'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(192793637291732313)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'p_encadeado,p_sucesso,p_messages);',
'',
'    end altera_status;',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_declaracaoimportacao;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td846
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(192982628395874927)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD846'
,p_sequence=>3010
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD846',
'-- Data: 19/05/2026',
unistr('-- Motivo: Incluso navega\00E7\00E3o para Pagamento'),
'-- Jira: PEDITEM-167',
'',
'create or replace package "UI_MPD_TD846" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob;',
'',
'    function sql_report(',
'        p_order in varchar2',
'    ) return clob;',
'',
'    function sql_filtro(',
'        campo in varchar2',
'    ) return clob;',
'',
'    function sql_verifica_filtro(',
'        campo in varchar2',
'    ) return boolean;',
'',
'    function label_coluna(',
'        campo in varchar',
'    ) return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos         out varchar2,',
'        labels         out varchar2',
'    );',
'',
'end "UI_MPD_TD846";',
'/',
'',
'create or replace package body "UI_MPD_TD846" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''', ''''ind_status'''', a.ind_status) ind_status,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''', ''''ind_itens_vinculado_invoice'''', a.ind_itens_vinculado_invoice) ind_itens_vinculado_invoice',
'                from imp_processoimportacao a',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end sql_cabecalho;',
'    ',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                a.id,',
'                pkg_ui.retorna_label_coluna(''imp_invoice.num_invoice'') label_titulo,                ',
'                pkg_ui.retorna_label_coluna(''imp_invoice.ind_status'') label_distintivo,',
'                a.num_invoice titulo,',
'                e.nome_fantasia subtitulo,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'', ''ind_status'', a.ind_status) distintivo,',
'                null class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''imp_invoice.id_incoterm'', c.codigo_incoterm, 3) atributo1,',
'                pkg_componentes.html_card_colunas(''imp_invoice.id_moeda'', d.codigo_moeda||'' - ''||d.simbolo_iso, 3) atributo2,',
'                pkg_componentes.html_card_colunas(''imp_invoice.valor_total_condicao_venda'', to_char(a.valor_total_condicao_venda, ''FM999G999G990D00''), 3) atributo3,',
'                pkg_componentes.html_card_colunas(''imp_invoice.ind_situacao_titulo_pagamento'', ',
'                    pkg_util.dominio_retorna_tag(''imp_invoice'', ''ind_situacao_titulo_pagamento'', a.ind_situacao_titulo_pagamento), 3',
'                ) atributo4,',
'                --FILTROS',
'                a.id_exportador filtro1,',
'                null FILTRO_MULT1,',
'',
'                null FILTRO_MULT2,                  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD846'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD846'') as opcao                ',
'            from imp_invoice a',
'            join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_incoterm c on c.id = a.id_incoterm',
'            join ng_moeda d on d.id = a.id_moeda',
'            join ng_pessoa_juridica e on e.id_pessoa = a.id_exportador',
'            where b.id = #PARAM1#',
'            order by titulo',
'        ~'';',
'        l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'        return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select ',
'                a.id id,',
'                a.num_invoice campo1,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'', ''ind_status'', a.ind_status) campo2,',
'                e.nome_fantasia campo3,',
'                c.codigo_incoterm campo4,',
'                d.codigo_moeda||'' - ''||d.simbolo_iso campo5,',
'                to_char(a.valor_total_condicao_venda, ''FM999G999G990D00'') campo6,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'', ''ind_situacao_titulo_pagamento'', a.ind_situacao_titulo_pagamento) campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                --FILTROS',
'                a.id_exportador filtro1,                               ',
'                null filtro2,                               ',
'                null filtro3,                               ',
'                null filtro4,                               ',
'                null filtro5,',
'                --FILTROS MULTI',
'                null filtro_mult1,                                ',
'                null filtro_mult2,                                ',
'                null filtro_mult3, ',
'                null filtro_mult4,                                ',
'                null filtro_mult5,                               ',
'                null opcao',
'            from imp_invoice a',
'            join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_incoterm c on c.id = a.id_incoterm',
'            join ng_moeda d on d.id = a.id_moeda',
'            join ng_pessoa_juridica e on e.id_pessoa = a.id_exportador',
'            where b.id = #PARAM1#',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(',
'        p_order in varchar2',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD846'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_invoice'')) a',
'            order by campo1',
'        ~'';        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(',
'        campo in varchar2',
'    ) return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id_pessoa r from ng_pessoa_juridica~'';',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(',
'        campo in varchar2',
'    ) return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;',
'',
'    function label_coluna(',
'        campo in varchar',
'    ) return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.num_invoice'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.ind_status'') into l_campo from dual;',
'        elsif campo in (''3'',''F1'') then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_exportador'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_incoterm'') into l_campo from dual;',
'        elsif campo = ''5'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_moeda'') into l_campo from dual;',
'        elsif campo = ''6'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.valor_total_condicao_venda'') into l_campo from dual;',
'        elsif campo = ''7'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.ind_situacao_titulo_pagamento'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;    ',
'        ',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos         out varchar2,',
'        labels         out varchar2',
'    ) is',
'    begin',
'        if p_card_ou_grid = ''CARD'' then',
'            campos := ''data_fim_vigencia,descricao_cargo'';',
'        else',
'            campos := ''campo3,campo2'';',
'        end if;',
'        labels := label_coluna(''3'')||'',''||label_coluna(''2'');',
'    end campos_ordenacao;',
'    ',
'end "UI_MPD_TD846";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td939
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(192985308299096955)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD939'
,p_sequence=>3020
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 29/05/2026',
unistr('-- Motivo: Corrigido regra da a\00E7\00E3o descompensar, permitindo somente quando ind_status = 1, ou 2'),
'-- Jira: PEDITEM-209',
'',
'-- Objeto: UI_MPD_TD939',
'-- Data: 19/05/2026',
unistr('-- Motivo: Incluso a\00E7\00E3o descompensar parcela'),
'-- Jira: PEDITEM-209',
'',
'create or replace package "UI_MPD_TD939" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD939";',
'/',
'',
'create or replace package body "UI_MPD_TD939" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'        p_consulta_sql => ''',
'            select ',
'                a.num_invoice,',
'                pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                case',
'                    when b.num_processoimportacao is not null then',
'                        b.num_processoimportacao',
'                    else',
'                        pkg_componentes.html_cor_texto(pkg_ui.retorna_label_tela(''''sem_processo''''))',
'                end id_processoimportacao',
'            from imp_invoice a',
'            left join imp_processoimportacao b on b.id = a.id_processoimportacao            ',
'            where a.id = ''||p_param1,',
'        p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'    );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_sql_grid clob;',
'        l_condicaopagamento varchar2(4000);',
'        l_quantidade_parcelas_pagamento varchar2(50);',
'        l_url clob;',
'        l_titulo_grid varchar2(4000);',
'        l_label_opcao varchar2(4000) := pkg_ui.retorna_label_botao(''opcao'');',
'        l_tipo_interacao varchar2(1);',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9000,',
'            p_items=> ''P9000_ID,P9000_PAGINA,P9000_PARAMETRO'',',
'            p_values => p_param1||'',TD869,0'',',
'            p_triggering_element => ''apex.jQuery("#NEW")''',
'        );',
'',
'        l_sql_grid := ',
'        q''~',
'            select distinct                ',
'                a.numero_parcela imp_invoice_pagamento$numero_parcela,',
'                a.percentual||''%'' imp_invoice_pagamento$percentual,',
'                to_char(a.valor, ''FM999G999G990D00'') imp_invoice_pagamento$valor,',
'                a.data_vencimento_prevista imp_invoice_pagamento$data_vencimento_prevista,',
'                pkg_util.dominio_retorna_tag(''imp_invoice_pagamento'', ''ind_status_pagamento'', a.ind_status_pagamento) imp_invoice_pagamento$ind_status_pagamento,',
'                to_char(pkg_componentes.html_botao_opcao_com_icone(p_id => a.id, p_pagina => ''TD939'', p_param1 => ''0'')) opcao',
'            from imp_invoice_pagamento a            ',
'            where a.id_invoice = #PARAM1#',
'            order by a.numero_parcela',
'        ~'';   ',
'        l_sql_grid := replace(l_sql_grid, ''#PARAM1#'', p_param1);',
'',
'        select case when ind_status in (1,2) then ',
'            ''<div class="a-CardView-headerBody" style="display: flex; justify-content: space-between; align-items: center; padding-top: 1.5rem; padding-left: 1rem;"><h3 class="a-CardView-title" style="visibility: hidden;">''||retorna_texto(''msg.111.l'''
||')||''</h3>',
'            <a href="''||l_url||''"><button class="t-Button t-Button--noLabel t-Button--icon js-ignoreChange color-text  t-Button--link lto173835060015817601_0" style="padding-right: 2.65rem;" type="button" id="BOTAO_OPCAO" title="''||l_label_opcao||''" '
||'aria-label="Opcao"><span class="t-Icon fa fa-ellipsis-v-o" aria-hidden="true"></span></button></a>',
'            </div>'' end',
'        into l_titulo_grid ',
'        from imp_invoice ',
'        where id = p_param1;',
'',
'        select descricao_condicaopagamento into l_condicaopagamento from imp_invoice a join ng_condicaopagamento b on b.id = a.id_condicaopagamento where a.id = p_param1;',
'        select max(b.numero_parcela) into l_quantidade_parcelas_pagamento from imp_invoice a join ng_condicaopagamento_parcela b on b.id_condicaopagamento = a.id_condicaopagamento where a.id = p_param1;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_condicaopagamento'' AS nome_coluna, 1 AS indice, ''TXT'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' as coluna_tabela, l_condicaopagamento valor, null obrigatorio,'
||' ''imp_invoice.id_condicaopagamento'' tag_campo, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas'', 2, ''TXT'', null, ''S'', ''N'', l_quantidade_parcelas_pagamento valor, null obrigatorio, null/*''imp_pedidoimportacao.quantidade_parcelas_pagamento''*/ tag_campo, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''l_titulo_grid'',       3, ''HTM'', null, ''N'', ''N'', null valor, null obrigatorio, null tag_campo, l_titulo_grid html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''l_sql_grid'',          4, ''GRI'', null, ''S'', ''N'', to_char(l_sql_grid) valor, null obrigatorio, null tag_campo, null html FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, tag_campo, html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.tag_campo, new_data'
||'.html);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'    begin',
'        bo_imp_invoice.gerencia_divergencias(            ',
'            p_id => apex_util.get_session_state(''P9012_PARAMETRO''),            ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );        ',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'        l_id number;',
'    begin',
'        null;',
'        -- bo_imp_invoice.cancela_saldo(            ',
'        --     p_id => apex_util.get_session_state(''P9012_PARAMETRO''),',
'        --     p_ind_saldo => apex_application.g_f02(1),',
'        --     p_sucesso => p_sucesso,',
'        --     p_messages => p_messages',
'        -- );',
'    end post_save;',
'',
'end "UI_MPD_TD939";',
'/'))
);
end;
/
