'                p_checksum_type => ''SESSION'');',
'        else',
'            return APEX_UTIL.PREPARE_URL(',
'                p_url => ''f?p=''||APEX_APPLICATION.g_flow_id||'':9000:''||APEX_CUSTOM_AUTH.GET_SESSION_ID||''::NO::P9000_ID,P9000_PAGINA:''||p_id||'',''||p_pagina,',
'                p_checksum_type => ''SESSION'');',
'        end if;',
