,p_name=>'UI_MPD_TD678'
,p_sequence=>3100
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD678" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD678";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD678" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    b.numero_pedido_importacao, ',
'                    a.num_entrega, ',
'                    case when a.id_processoimportacao is null then',
'                        pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                    else c.num_processoimportacao',
'                    end id_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_entrega'''', ''''ind_status_entrega'''', a.ind_status_entrega) ind_status_entrega',
'                from imp_entrega a ',
'                join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'                left join imp_processoimportacao c on c.id = a.id_processoimportacao',
'                where a.id = ''|| p_param1,',
'        p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega'',''imp_entrega''),',
'        p_formato => ''pequeno'',',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        ) ||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.269.l'')||''</br>''||pkg_componentes.html_cor_texto(retorna_texto(''msg.270.l''))||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''data_disponivel_real'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, ''S'' AS obrigatorio from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, obrigatorio)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.obrigatorio);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
'    begin',
'        bo_imp_entrega.confirmar_disponibilidade(',
'            p_data_disponivel_real => apex_application.g_f01(1),',
'            p_id                   => p_id, ',
'            p_sucesso              => p_sucesso,',
'            p_messages             => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD678";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td679
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(198591516325217515)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD679'
,p_sequence=>3110
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD679" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'   ',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD679";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD679" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    b.numero_pedido_importacao,',
'                    a.num_entrega,',
'                    case when a.id_processoimportacao is null then',
'                        pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                    end id_processoimportacao',
'                from imp_entrega a ',
'                join imp_pedidoimportacao b on b.id = a.id_pedidoimportacao',
'                where a.id = ''|| p_param1,',
'        p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        ) ||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;">''||',
'        ''<h3 class="a-CardView-title">''||retorna_texto(''msg.91.l'')||''</h3></div>''||',
'        ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;">''||',
'        ''<h3 class="a-CardView-title">''||replace(retorna_texto(''msg.91.h''),''$param1'')||''</br>''||retorna_texto(''msg.262.l'')||''</h3></div>'';',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is        ',
'    begin',
'        bo_imp_entrega.desconfirmar_disponibilidade(',
'            p_id       => p_id, ',
'            p_sucesso  => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD679";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1062
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(198666374726356299)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1062'
,p_sequence=>3120
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 08/07/2026',
unistr('-- Motivo: Ajuste na ordena\00E7\00E3o da pesquisa facetada ind_status'),
'-- Jira: PEDITEM-297',
'',
'create or replace package "UI_MPD_TD1062" as',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob;',
'',
'    function sql_report(',
'        p_order in varchar2',
'    ) return clob;',
'',
'    function sql_filtro(',
'        campo in varchar2',
'    ) return clob;',
'',
'    function sql_verifica_filtro(',
'        campo in varchar2',
'    ) return boolean;',
'',
'    function label_coluna(',
'        campo in varchar',
'    ) return clob;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos         out varchar2,',
'        labels         out varchar2',
'    );',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    );',
'',
'end "UI_MPD_TD1062";',
'/',
'',
'create or replace package body "UI_MPD_TD1062" as',
'',
'    function sql_card(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select ',
'                a.id,    ',
'                pkg_ui.retorna_label_coluna(''imp_invoice.num_invoice'') label_titulo,',
'                pkg_ui.retorna_label_coluna(''imp_invoice.data_invoice'') label_subtitulo,',
'                pkg_ui.retorna_label_coluna(''imp_invoice.ind_status'') label_distintivo,',
'                a.num_invoice titulo,',
'                pkg_data.fmtd(a.data_invoice, ''DATA'') subtitulo,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_status'',a.ind_status) distintivo,',
'                null as class_distintivo,',
'                null lista_distintivo,',
'                --ATRIBUTOS',
'                case when a.id_processoimportacao is null then',
'                    pkg_componentes.html_card_colunas(''imp_invoice.id_processoimportacao'',retorna_texto(''msg.93.l''), 2) ',
'                else',
'                    pkg_componentes.html_card_colunas(''imp_invoice.id_processoimportacao'', b.num_processoimportacao, 2) ',
'                end atributo1,',
'                pkg_componentes.html_card_colunas(''imp_invoice.id_exportador'', c.nome_fantasia, 2) atributo2,',
'                pkg_componentes.html_card_colunas(''imp_invoice.id_importador'', d.nome_fantasia, 2) atributo3,',
'                pkg_componentes.html_card_colunas(''imp_invoice.id_adquirente'', e.nome_fantasia, 2) atributo4,',
'                pkg_componentes.html_card_colunas(''imp_invoice.ind_divergencia'', ',
'                    pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_divergencia'',a.ind_divergencia), 2',
'                ) atributo5,',
'                pkg_componentes.html_card_colunas(''imp_invoice.ind_situacao_titulo_pagamento'', ',
'                    pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_situacao_titulo_pagamento'',a.ind_situacao_titulo_pagamento), 2',
'                ) atributo6,',
'                -- ORDENACAO',
'                case when a.ind_status = 4 then 1 else 0 end ordenacao_ind_status,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                a.ind_status filtro2,',
'                a.ind_divergencia filtro3,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,                  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD1062'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD1062'') as opcao',
'            from imp_invoice a',
'            left join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_exportador',
'            join ng_pessoa_juridica d on d.id_pessoa = a.id_importador',
'            left join ng_pessoa_juridica e on e.id_pessoa = a.id_adquirente',
'            order by #ORDER#',
'        ~'';',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''5''));',
'        return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(',
'        p_param1 in varchar2 default '''',',
'        p_param2 in varchar2 default '''',',
'        p_param3 in varchar2 default '''',',
'        p_param4 in varchar2 default ''''',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''[',
'            select ',
'                a.id,',
'                a.num_invoice campo1,',
'                pkg_data.fmtd(a.data_invoice, ''DATA'') campo2,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_status'',a.ind_status) campo3,',
'                case when a.id_processoimportacao is null then',
'                    retorna_texto(''msg.93.l'')',
'                else',
'                    b.num_processoimportacao',
'                end campo4,',
'                c.nome_fantasia campo5,',
'                d.nome_fantasia campo6,',
'                e.nome_fantasia campo7,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_divergencia'',a.ind_divergencia) campo8,',
'                pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_situacao_titulo_pagamento'',a.ind_situacao_titulo_pagamento) campo9,',
'                -- ORDENACAO',
'                case when a.ind_status = 4 then 1 else 0 end campo10,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                a.ind_status filtro2,',
'                a.ind_divergencia filtro3,',
'                null filtro4,',
'                null filtro5,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,',
'                null FILTRO_MULT3,',
'                null FILTRO_MULT4,',
'                null FILTRO_MULT5,',
'                null opcao',
'            from imp_invoice a',
'            left join imp_processoimportacao b on b.id = a.id_processoimportacao',
'            join ng_pessoa_juridica c on c.id_pessoa = a.id_exportador',
'            join ng_pessoa_juridica d on d.id_pessoa = a.id_importador',
'            left join ng_pessoa_juridica e on e.id_pessoa = a.id_adquirente',
'        ]'';',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(',
'        p_order in varchar2',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,       ',
'                campo1,',
'                to_date(campo2, ''DD/MM/YYYY'') campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,',
'                pkg_componentes.html_botao_opcao(a.id,''TD1062'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''imp_invoice'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(',
'        campo in varchar2',
'    ) return clob is',
'    begin',
'        if campo = ''1'' then',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';',
'        elsif campo = ''2'' then            ',
'            return q''~select * from pkg_util.dominio_retorna_lista(''imp_invoice'',''ind_status'') order by to_number(r)~'';',
'        elsif campo = ''3'' then        ',
'            return q''~select * from pkg_util.dominio_retorna_lista(''imp_invoice'',''ind_divergencia'')~'';',
'        else',
'            return null;',
'        end if;        ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(',
'        campo in varchar2',
'    ) return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;',
'',
'    function label_coluna(',
'        campo in varchar',
'    ) return clob is',
'        l_campo clob;',
'    begin',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.num_invoice'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.data_invoice'') into l_campo from dual;',
'        elsif campo in (''3'',''F2'') then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.ind_status'') into l_campo from dual;',
'        elsif campo = ''4'' then                        ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_processoimportacao'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_exportador'') into l_campo from dual;',
'        elsif campo = ''6'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_importador'') into l_campo from dual;',
'        elsif campo = ''7'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_adquirente'') into l_campo from dual;',
'        elsif campo in (''8'',''F3'') then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.ind_divergencia'') into l_campo from dual;  ',
'        elsif campo = ''9'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.ind_situacao_titulo_pagamento'') into l_campo from dual; ',
'        elsif campo = ''F1'' then',
'            select pkg_ui.retorna_label_coluna(''imp_invoice.id_tenant'') into l_campo from dual;',
'        end if;',
'',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(',
'        p_card_ou_grid in varchar2,',
'        campos         out varchar2,',
'        labels         out varchar2',
'    ) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo10,campo3,campo4,campo5,campo6,campo7,campo8,campo9'';',
'        else',
'            campos := ''a.num_invoice,a.data_invoice,a.ind_status,atributo1,c.nome_fantasia,d.nome_fantasia,e.nome_fantasia,atributo5,atributo6'';',
'        end if;',
'',
'        select',
'            label_coluna(''1'') || '','' ||',
'            label_coluna(''2'') || '','' ||',
'            label_coluna(''3'') || '','' ||',
'            label_coluna(''4'') || '','' ||',
'            label_coluna(''5'') || '','' ||',
'            label_coluna(''6'') || '','' ||',
'            label_coluna(''7'') || '','' ||',
'            label_coluna(''8'') || '','' ||',
'            label_coluna(''9'')',
'          into labels',
'          from dual;',
'    end campos_ordenacao;',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        l_labels := label_coluna(''3'')||'' = ''||pkg_util.dominio_retorna_tag(''imp_invoice'',''ind_status'',4) || '','' || label_coluna(''2'') || '','' || label_coluna(''1'');',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo10,campo2,campo1'';',
'        else',
'            l_campos := ''ordenacao_ind_status,a.data_invoice,a.num_invoice'';',
'        end if;',
'        l_direcoes := ''ASC,DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD1062";',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_ui
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(202486000814894198)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'PKG_UI'
,p_sequence=>3130
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "PKG_UI" as ',
'',
'    type r_facetada is record (',
'        id varchar2(4000),         ',
'        campo1 varchar2(4000),',
'        campo2 varchar2(4000),',
'        campo3 varchar2(4000),',
'        campo4 varchar2(4000),',
'        campo5 varchar2(4000),',
'        campo6 varchar2(4000),',
'        campo7 varchar2(4000),',
'        campo8 varchar2(4000),',
'        campo9 varchar2(4000),',
'        campo10 varchar2(4000),',
'        filtro1 varchar2(4000),',
'        filtro2 varchar2(4000),',
'        filtro3 varchar2(4000),',
'        filtro4 varchar2(4000),',
'        filtro5 varchar2(4000),',
'        filtro_mult1 varchar2(4000),',
'        filtro_mult2 varchar2(4000),',
'        filtro_mult3 varchar2(4000),',
'        filtro_mult4 varchar2(4000),',
'        filtro_mult5 varchar2(4000),',
'        opcao varchar2(4000)',
'    ); ',
'    ',
'    type r_facetada2 is record (',
'        id varchar2(4000),         ',
'        campo1 varchar2(4000),',
'        campo2 varchar2(4000),',
'        campo3 varchar2(4000),',
'        campo4 varchar2(4000),',
'        campo5 varchar2(4000),',
'        campo6 varchar2(4000),',
'        campo7 varchar2(4000),',
'        campo8 varchar2(4000),',
'        campo9 number,',
'        campo10 number,',
'        filtro1 varchar2(4000),',
'        filtro2 varchar2(4000),',
'        filtro3 varchar2(4000),',
'        filtro4 varchar2(4000),',
'        filtro5 varchar2(4000),',
'        filtro_mult1 varchar2(4000),',
'        filtro_mult2 varchar2(4000),',
'        filtro_mult3 varchar2(4000),',
'        filtro_mult4 varchar2(4000),',
'        filtro_mult5 varchar2(4000)',
'    );     ',
'    type t_facetada is table of r_facetada; ',
'    type t_facetada2 is table of r_facetada2; ',
' ',
'    function pesquisa_facetada(  ',
'        p_page_id          in number, ',
'        p_region_static_id in varchar2, ',
'        p_nome_tabela      in varchar2,',
'        p_region_id        in varchar2 default null',
'    ) return t_facetada pipelined; ',
'',
'    function pesquisa_facetada2(  ',
'        p_page_id          in number, ',
'        p_region_static_id in varchar2, ',
'        p_nome_tabela      in varchar2 ',
'    ) return t_facetada2 pipelined;     ',
'',
'    type r_list_value is record ( ',
'        d          varchar2(4000), ',
'        r          varchar2(4000) ',
'    ); ',
' ',
'    type t_list_value is table of r_list_value; ',
'',
'    -- ',
'    -- Tipos de artefatos ',
'    -- ',
'    c_tp_artefato_cadastro_dinamico         constant varchar2(2) := ''CD''; ',
'    c_tp_artefato_excluir_dinamico          constant varchar2(2) := ''ED''; ',
'    c_tp_artefato_acao_dinamico             constant varchar2(2) := ''AD''; ',
'    c_tp_artefato_tela                      constant varchar2(2) := ''TE''; ',
' ',
'    -- ',
'    -- Tipos de tipo_funcionalidade de cadastro dimicos de artefatos ',
'    -- ',
'    c_tipo_funcionalidade_incluir               constant varchar2(1) := ''I''; ',
'    c_tipo_funcionalidade_alterar               constant varchar2(1) := ''A''; ',
'    c_tipo_funcionalidade_duplicar              constant varchar2(1) := ''D''; ',
'    c_tipo_funcionalidade_mais_detalhes         constant varchar2(1) := ''M''; ',
'    c_tipo_funcionalidade_listar                constant varchar2(1) := ''L''; ',
'    c_tipo_funcionalidade_acao                  constant varchar2(1) := ''W''; ',
' ',
'    -- ',
'    -- Tipos de validacao ',
'    -- ',
'    c_tp_validacao_metodo                   constant varchar2(10) := ''metodo''; ',
'    c_tp_validacao_sql                      constant varchar2(10) := ''sql''; ',
'',
'    c_select_auditoria_com_verificacao  constant clob := ',
'    q''~ ',
'        union all select ',
'            pkg_ui.retorna_url(#p_id#,''TD773'',9010,''CD'',''M'','''',''P9010_PARAMETRO2,P9010_ESCONDE_OPCAO'',upper(nome_entidade)||'',''||1) link,',
'            ''fa-history'' icon,',
'            pkg_ui.retorna_label_botao_tipo(''historico-alteracao'',''l'') label,',
'            pkg_ui.retorna_label_botao_tipo(''historico-alteracao'',''h'') help,',
'            null sql_validacao,',
'            9 ordem,',
'            null recurso ',
'        from view_entidade_artefato ',
'        where rownum = 1 ',
'        and id_registro = #p_id# ',
'        and codigo_artefato = ''#p_codigo_artefato#''    ',
'    ~''; ',
'',
'    c_select_auditoria_fixo  constant clob := ',
'    q''~ ',
'        union all select ',
'            pkg_ui.retorna_url(#p_id#,''TD773'',9010,''CD'',''M'','''',''P9010_PARAMETRO2,P9010_ESCONDE_OPCAO'',upper(nome_entidade)||'',''||1) link,',
'            ''fa-history'' icon,',
'            pkg_ui.retorna_label_botao_tipo(''historico-alteracao'',''l'') label,',
'            pkg_ui.retorna_label_botao_tipo(''historico-alteracao'',''h'') help,',
'            null sql_validacao,',
'            9 ordem,',
'            null recurso ',
'        from vw_artefato_entidade_tela_dinamica',
'        where codigo_artefato = ''#p_codigo_artefato#''  ',
'    ~''; ',
'',
'    c_campos_botao  constant clob := ',
'    q''~ ',
'        pkg_ui.retorna_url(#p_id#,e.codigo_artefato,i.codigo_artefato,e.tipo,g.tipo_funcionalidade,t.titulo,c.parametro,c.valor,#p_param2#) link, ',
'        --pkg_ui.retorna_url(#p_id#,e.codigo_artefato,i.codigo_artefato,e.tipo,g.tipo_funcionalidade,t.titulo,c.parametro,c.valor,#p_param2#) link, ',
'        pkg_ui.retorna_icone(e.tipo,g.tipo_funcionalidade,e.nome_icone) icon, ',
'        t.titulo label,',
'        pkg_ui.retorna_titulo_tela(e.codigo_artefato,2) help,',
'        j.sql_validacao,',
'        case ',
'            when e.funcao = 5 then 1 -- mais detalhes ',
'            when e.funcao = 3 then 2 -- aterar',
'            when e.funcao = 4 then 3 -- copiar',
'            when e.funcao = 6 then 4 -- excluir',
'        end as ordem,',
'        null recurso          ',
'    ~''; ',
'',
'    c_campos_link   constant clob := ',
'    q''~ ',
'        null lvl, ',
'        t.titulo||''(''||e.codigo_artefato||'')'' text,',
'        pkg_ui.retorna_url(#p_id#,e.codigo_artefato,i.codigo_artefato,e.tipo,g.tipo_funcionalidade,t.titulo,c.parametro,c.valor,#p_param2#) link, ',
'        null is_current_list_entry, ',
'        case when c.icone is not null then c.icone else pkg_ui.retorna_icone(e.tipo,g.tipo_funcionalidade,e.nome_icone) end image, ',
'        null image_attribute, ',
'        null image_alt_attribute, ',
'        case when c.help is not null then pkg_ui.retorna_titulo_atalho(c.id,2) else pkg_ui.retorna_titulo_tela(e.codigo_artefato,2) end a01,',
'        '''' a02,',
'        j.sql_validacao,',
'        --null sql_validacao,',
'        case ',
'            when e.funcao = 5 then 1 -- mais detalhes ',
'            when e.funcao = 3 then 2 -- aterar',
'            when e.funcao = 4 then 3 -- copiar',
'            when e.funcao = 6 then 4 -- excluir',
'        end as ordem,',
'        null recurso         ',
'    ~''; ',
'',
'',
'',
'        -- apex_page.get_url(p_page => 2, p_clear_cache => 2) link, ',
'    c_campos_link_home   constant clob := ',
'    q''~ ',
'    union all select ',
'        null lvl, ',
unistr('        ''P\00E1gina inicial'' text,'),
'        ''javascript:void(0)'' link,',
'        null is_current_list_entry, ',
'        ''fa-home'' image, ',
'        '''' image_attribute, ',
'        '''' image_alt_attribute, ',
unistr('        ''Abre uma nova guia com a p\00E1gina inicial'' a01,'),
'        ''onclick="window.open('''''' ||',
'        page_url(134,2) ||',
'        '''''',''''_blank''''); "'' a02,',
'        null sql_validacao,',
'        0 ordem,',
'        null recurso    ',
'    from dual',
'    ~''; ',
'',
'',
'    c_campos_botao_home   constant clob := ',
'    q''~ ',
'    union all select    ',
'        ''javascript:void(0)'' link, ',
'        ''fa-home'' icon, ',
unistr('        ''P\00E1gina inicial'' label,'),
unistr('        ''Abre uma nova guia com a p\00E1gina inicial'' help,'),
'        null sql_validacao,',
'        0 ordem,',
'        ''onclick=window.open('''''' ||',
'        page_url(134,2) ||',
'        '''''',''''_blank'''');'' recurso ',
'    from dual  ',
'    ~''; ',
