'    function retorna_valor_colecao (',
'        p_codigo_artefato in varchar2,',
'        p_campo in varchar2',
'    ) return varchar2 is',
'        l_valor varchar2(4000);',
'    begin',
'        select c002 into l_valor',
'           from apex_collections',
'         where upper(collection_name) = upper(p_codigo_artefato||''_''||apex_custom_auth.get_session_id)',
'        and upper(c001) = upper(p_campo);',
'        return l_valor;',
'        exception',
'            when no_data_found then',
'                return '''';',
'            when others then',
'                return '''';',
'    end;    ',
'',
'    function retorna_id_colecao (',
'        p_codigo_artefato in varchar2,',
'        p_campo in varchar2',
'    ) return varchar2 is',
'        l_valor varchar2(4000);',
'    begin',
'        select c003 into l_valor',
'           from apex_collections',
'         where upper(collection_name) = upper(p_codigo_artefato||''_''||apex_custom_auth.get_session_id)',
'        and upper(c001) = upper(p_campo);',
'        return l_valor;',
'        exception',
'            when no_data_found then',
'                return '''';',
'            when others then',
'                return '''';',
'    end;    ',
'',
'    procedure prc_configurar_filtros(',
'        p_id_usuario       number,',
'        p_codigo_artefato  varchar2,',
'        p_app_page_id      number',
'    ) as',
'        l_prefixo_itens  varchar2(256);',
'        l_label          varchar2(256);',
'        l_label_opcao    varchar2(256);',
'        l_label_salvar   varchar2(256);',
'        l_id_colunas     varchar2(256);',
'        v_lista_colunas  apex_t_varchar2;',
'        v_existe         number;',
'        v_item_nome      varchar2(50);',
'    begin',
'        l_prefixo_itens := ''P'' || p_app_page_id;',
'        ',
'        if v(l_prefixo_itens|| ''_CARD_OU_LISTA'') is null then',
'            apex_util.set_session_state(l_prefixo_itens || ''_CARD_OU_LISTA'', ''CARD'');',
'        end if;',
'        ',
'        begin',
'            select id_coluna into l_id_colunas ',
'            from mpd_usuario_grid_oculta_coluna ',
'            where id_usuario = p_id_usuario ',
'              and codigo_artefato = p_codigo_artefato;',
'            ',
'            v_lista_colunas := apex_string.split(l_id_colunas, '':'');',
'            apex_util.set_session_state(l_prefixo_itens || ''_COLUNAS'', l_id_colunas);',
'        exception',
'            when no_data_found then',
'                l_id_colunas := null;',
'                v_lista_colunas := apex_t_varchar2();',
'        end;',
'        ',
'        -- percorre os itens campo1 a campo10',
'        for i in 1..10 loop',
'            v_item_nome := l_prefixo_itens || ''_MOSTRA_CAMPO'' || i;',
'            ',
unistr('            -- verifica se a coluna est\00E1 presente em id_colunas'),
'            select count(*) into v_existe ',
'            from table(v_lista_colunas) t ',
'            where t.column_value = ''CAMPO'' || i;',
'            ',
unistr('            -- define "n" se a coluna estiver presente, sen\00E3o "y"'),
'            if v_existe > 0 then',
'                apex_util.set_session_state(v_item_nome, ''N'');',
'            else',
'                apex_util.set_session_state(v_item_nome, ''Y'');',
'            end if;',
'        end loop;',
'    end prc_configurar_filtros;    ',
'',
'    function retorna_pagina_artefato (',
'        p_codigo_artefato in varchar2',
'    ) return varchar2',
'    is',
'        v_resultado varchar2(4000);',
'    begin',
unistr('        -- seleciona o c\00F3digo artefato considerando nvl'),
'        select nvl(c.codigo_artefato, a.codigo_artefato)',
'          into v_resultado',
'          from mpd_funcionalidade a',
'          left join mpd_funcionalidade_tela_dinamica b',
'            on b.id_funcionalidade = a.id',
'          left join mpd_funcionalidade c',
'            on c.id = b.id_funcionalidade_base',
'         where a.codigo_artefato = p_codigo_artefato;',
'',
'        return v_resultado;',
'',
'    exception',
'        when no_data_found then',
unistr('            -- se n\00E3o encontrar registro, retorna null ou uma mensagem'),
unistr('            return null; -- ou return ''n\00E3o encontrado'';'),
'        when others then',
'            return null;',
'    end retorna_pagina_artefato;    ',
'',
'    procedure retorna_titulo_atalho (',
'        p_codigo_artefato in mpd_funcionalidade.codigo_artefato%type,',
'        p_titulo          out mpd_traducao.texto_traduzido%type,',
'        p_help            out mpd_traducao.texto_traduzido%type',
'    )is',
'    begin',
'        p_titulo := retorna_texto(''atalho.''||p_codigo_artefato||''.l'');',
'        p_help := retorna_texto(''atalho.''||p_codigo_artefato||''.h'');',
'    end retorna_titulo_atalho;',
'',
'    function retorna_titulo_atalho (',
'        p_codigo_artefato in mpd_funcionalidade.codigo_artefato%type,',
'        p_help in number default 1 -- 1=Titulo e 2=Help ',
'    ) return varchar2 is',
'    begin',
'        if p_help = 2 then',
'            return retorna_texto(''atalho.''||p_codigo_artefato||''.h'');',
'        else',
'            return retorna_texto(''atalho.''||p_codigo_artefato||''.l'');',
'        end if;',
'    end retorna_titulo_atalho;',
'',
'    function existe_funcao_package(',
'        p_package_name in varchar2,',
'        p_function_name in varchar2',
'    ) return boolean',
'    is',
'        l_count number;',
'    begin',
'        select count(*)',
'          into l_count',
'          from all_arguments',
'         where package_name = upper(p_package_name)',
'           and object_name  = upper(p_function_name)',
'           and position     = 0;',
'',
'        return l_count > 0;',
'    end;    ',
'',
'end "PKG_UI";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td917
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(202496161519039331)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD917'
,p_sequence=>3140
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD917" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );   ',
'',
'end "UI_MPD_TD917";',
'/',
'',
'create or replace package body "UI_MPD_TD917" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin          ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_invoice,',
'                    pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                    case',
'                        when c.num_processoimportacao is not null then',
'                            c.num_processoimportacao',
'                        else',
'                            pkg_componentes.html_cor_texto(pkg_ui.retorna_label_tela(''''sem_processo''''))',
'                    end id_processoimportacao',
'                from imp_invoice a',
'                join imp_invoice_despesa b on b.id_invoice = a.id',
'                left join imp_processoimportacao c on c.id = a.id_processoimportacao            ',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'        l_moeda varchar2(4000);',
'    begin        ',
'        select c.codigo_moeda||'' - ''||c.simbolo_iso into l_moeda from imp_invoice a join imp_invoice_despesa b on b.id_invoice = a.id join ng_moeda c on c.id = a.id_moeda where b.id = p_param1;',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_invoice'',                   2, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despesa'',                   3, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                     5, ''TXT'', null, ''S'', ''N'', l_moeda valor, ''imp_invoice.id_moeda'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor'',                        7, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_incluso_valor_mercadoria'', 8, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''observacao'',                   9, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',              11, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    function where_dinamico (p_campo in varchar2) return clob is',
'    begin',
'        if upper(p_campo) = upper(''id_despesa'') then',
'            return q''~',
'                where (a.data_fim_vigencia is null ',
'                    or to_date(to_char(a.data_fim_vigencia, ''dd/mm/yyyy''), ''dd/mm/yyyy'') >= to_date(to_char(current_date, ''dd/mm/yyyy''), ''dd/mm/yyyy'')',
'                )',
'                and a.ind_origem_despesa = 2',
'                and a.ind_tipo_despesa in (9,10,16)',
'            ~'';',
'        else',
'            return '''';',
'        end if;',
'    end where_dinamico;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is         ',
'    begin        ',
'        bo_imp_invoice_despesa.altera_registro(',
'            p_id_tenant => apex_application.g_f01(1),',
'            p_id_invoice => apex_application.g_f02(1),',
'            p_id_despesa => apex_application.g_f03(1),            ',
'            p_valor => pkg_util.retorna_number(apex_application.g_f07(1)),',
'            p_ind_incluso_valor_mercadoria => apex_application.g_f08(1),',
'            p_observacao => apex_application.g_f09(1),',
'            p_data_alteracao => to_timestamp(apex_application.g_f11(1), ''dd-mon-rr hh:mi:ss:ff am''),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end post;',
'',
'end "UI_MPD_TD917";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td739
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(202560166521620511)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD739'
,p_sequence=>3150
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 24/06/2026',
unistr('-- Motivo: Inclus\00E3o da coluna id_numerario_despesa na entidade imp_pedidoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade imp_processoimportacao_despesa'),
'-- Jira: PEDITEM-162',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/04/2026',
unistr('-- Motivo: Inclu\00EDdo campo ng_despesa.ind_tipo_despesa como consulta'),
'-- Jira: PEDITEM-93',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 25/04/2026',
unistr('-- Motivo: Ajustes nas chamadas do bo_imp_processoimportacao_despesa devido adi\00E7\00E3o de novas colunas'),
'-- Jira: PEDITEM-162',
'',
'create or replace package "UI_MPD_TD739" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    );',
'',
'    procedure post(',
'        p_id       in number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD739";',
'/',
'',
'create or replace package body "UI_MPD_TD739" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_html clob;        ',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_despesa b on b.id_processoimportacao = a.id',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null',
'    ) is',
'        l_ind_tipo_despesa varchar2(4000);',
'    begin ',
'        select pkg_util.dominio_retorna_tag(''ng_despesa'',''ind_tipo_despesa'',b.ind_tipo_despesa) into l_ind_tipo_despesa from imp_processoimportacao_despesa a join ng_despesa b on b.id = a.id_despesa where a.id = p_param1;',
'        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_documento_despesa'',        2, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',       3, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_numerario_despesa'',        4, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_despesa'',                  5,    '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ng_despesa.ind_tipo_despesa'', 7, ''TXT'', null, ''S'', ''N'', l_ind_tipo_despesa valor, ''ng_despesa.ind_tipo_despesa'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_prevista'',           8,    '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_previsto'',             10,    '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_realizada'',         11, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_realizado'',            12, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''taxa_cambio'',                13, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_despesa'',         14, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pagamento'',       15, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_documento'',         16, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_moeda_documento'',      17, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_moeda_nacional'',       18, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_forma_rateio'',           19, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_compoe_custo_operacao'',  20, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_participa_nfe'',          21, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_despesa_base_calculo'',   22, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_despesa'',           23, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',             24,    '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    procedure post(',
'        p_id       in number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'    begin        ',
'        bo_imp_processoimportacao_despesa.altera_registro(',
'            p_id_tenant                 => apex_application.g_f01(1),',
'            p_id_documento_despesa      => apex_application.g_f02(1),',
'            p_id_processoimportacao     => apex_application.g_f03(1),',
'            p_id_numerario_despesa      => apex_application.g_f04(1),',
'            p_id_despesa                => apex_application.g_f05(1),',
'            p_id_moeda_prevista         => apex_application.g_f08(1),',
'            p_valor_previsto            => pkg_util.retorna_number(apex_application.g_f10(1)),',
'            p_id_moeda_realizada        => apex_application.g_f11(1),',
'            p_valor_realizado           => pkg_util.retorna_number(apex_application.g_f12(1)),',
'            p_taxa_cambio               => pkg_util.retorna_number(apex_application.g_f13(1)),',
'            p_ind_status_despesa        => apex_application.g_f14(1),',
'            p_ind_status_pagamento      => apex_application.g_f15(1),',
'            p_id_moeda_documento        => apex_application.g_f16(1),',
'            p_valor_moeda_documento     => pkg_util.retorna_number(apex_application.g_f17(1)),',
'            p_valor_moeda_nacional      => pkg_util.retorna_number(apex_application.g_f18(1)),',
'            p_ind_forma_rateio          => apex_application.g_f19(1),',
'            p_ind_compoe_custo_operacao => apex_application.g_f20(1),',
'            p_ind_participa_nfe         => apex_application.g_f21(1),',
'            p_ind_despesa_base_calculo  => apex_application.g_f22(1),',
'            p_ind_tipo_despesa          => apex_application.g_f23(1),',
'            p_data_alteracao            => to_timestamp(apex_application.g_f24(1), ''dd-mon-rr hh:mi:ss:ff am''),            ',
'            p_id                        => p_id,',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );        ',
'    end post;',
'',
'end "UI_MPD_TD739";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1046
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(208672973155232820)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1046'
,p_sequence=>3160
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Objeto: UI_MPD_TD1046 ',
'-- Data: 03/06/2026 ',
unistr('-- Motivo: Ajuste para utiliza\00E7\00E3o do recurso de refresh autom\00E1tico na tela'),
'-- Jira: PEDITEM-312',
'',
'-- Objeto: UI_MPD_TD1046 ',
'-- Data: 29/05/2026 ',
'-- Motivo: Desenvolvimento interface Consultar Tributos dos itens do processo ',
'-- Jira: PEDITEM-312',
'',
'create or replace package "UI_MPD_TD1046" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'    ',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob;',
'    ',
'end "UI_MPD_TD1046";',
'/',
'create or replace package body "UI_MPD_TD1046" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_processoimportacao,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador,',
'                    b.codigo_moeda || '''' - '''' || b.simbolo_iso as id_moeda_tenant',
'                from imp_processoimportacao a',
'                join ng_moeda b on b.id = a.id_moeda_tenant',
'                join imp_processoimportacao_item c on c.id_processoimportacao = a.id',
'                join imp_processoimportacao_item_tributo d on d.id_processoimportacao_item = c.id',
'                where d.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_item                              imp_processoimportacao_item%rowtype;',
'        l_consulta_item                     clob;',
'        l_tributo                           imp_processoimportacao_item_tributo%rowtype;',
'        l_id_processoimportacao_item        imp_processoimportacao_item.id%type;',
'        l_valor_ii                          number;',
'        l_valor_ipi                         number;',
'        l_valor_pis                         number;',
'        l_valor_cofins                      number;',
'        l_valor_cbs                         number;',
'        l_valor_ibs                         number;',
'        l_valor_icms                        number;',
'        l_valor_icms_st                     number;',
'        l_html                              clob;',
'        l_ind_calculando                    varchar2(1);',
'    begin',
'        l_consulta_item := ''select a.codigo_item || '''' - ''''||pkg_traducao.get_traducao(a.descricao_item) as d,  a.id as r from ng_item a join ng_item_produto b on b.id_item = a.id where a.ind_tipo_item = ''''P'''' order by 1'';',
'',
'        select * into l_tributo from imp_processoimportacao_item_tributo where id = p_param1;',
'        l_id_processoimportacao_item := l_tributo.id_processoimportacao_item;',
'        select * into l_item from imp_processoimportacao_item where id = l_id_processoimportacao_item;',
'',
'        select ind_calculando_valores into l_ind_calculando from imp_processoimportacao where id = l_item.id_processoimportacao;',
'        if l_ind_calculando = ''S'' then',
'            l_html :=',
'                ''<div style="display:flex;justify-content:end;margin-right:3rem;margin-bottom:0.5rem">',
'                    <span style="color:#d32f2f;font-weight:bold;">''|| pkg_ui.retorna_label_tela(''recalculando'') ||''</span>',
'                </div>'';',
'        else',
'            l_html := null;',
'        end if;',
'        ',
'        select',
'            sum(case when nd.ind_tipo_despesa = 1  then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 2  then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 3  then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 4  then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 18 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 19 then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 5  then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end),',
'            sum(case when nd.ind_tipo_despesa = 6  then nvl(nullif(d.valor_total_despesa_realizado_item, 0), d.valor_total_despesa_previsto_item) else 0 end)',
'        into',
'            l_valor_ii,',
'            l_valor_ipi,',
'            l_valor_pis,',
'            l_valor_cofins,',
'            l_valor_cbs,',
'            l_valor_ibs,',
'            l_valor_icms,',
'            l_valor_icms_st',
'        from imp_processoimportacao_item_despesa d',
'        join imp_processoimportacao_despesa pd on pd.id = d.id_processoimportacao_despesa',
'        join ng_despesa nd on nd.id = pd.id_despesa',
'        where d.id_processoimportacao_item = l_id_processoimportacao_item;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''col1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, null valor, null tag_campo, null url, null id_artefato_versi'
||'onado_zoom, l_html html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_item'',                             3, ''POP1'', to_char(l_consulta_item), ''S'', ''N'', to_char(l_item.id_item) valor, ''IMP_PROCESSOIMPORTACAO_ITEM.id_item'' tag_campo, null url, null id_artefato_versionado_zoom,'
||' null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_ncm'',                              4, ''POP'', ''R_NG_NCM.CODIGO_NCM'', ''N'', ''N'', to_char(l_item.id_ncm) valor, ''IMP_PROCESSOIMPORTACAO_ITEM.id_ncm'' tag_campo, null url, null id_artefato_versionado_zoom, null '
||'html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''vmld'',                                5, '''', null, ''S'', ''S'', null valor, null tag_campo, null url, null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_ii'',                     6, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_ii'',                         7, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_ii'',                            8, '''', null, ''N'', ''N'', to_char(nvl(l_valor_ii,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where '
||'r = 1) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_ipi'',                    9, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_ipi'',                       10, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_ipi'',                          11, '''', null, ''N'', ''N'', to_char(nvl(l_valor_ipi,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where'
||' r = 2) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_pis'',                   12, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_pis'',                       13, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_pis'',                          14, '''', null, ''N'', ''N'', to_char(nvl(l_valor_pis,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where'
||' r = 3) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_cofins'',                15, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_cofins'',                    16, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_cofins'',                       17, '''', null, ''N'', ''N'', to_char(nvl(l_valor_cofins,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) wh'
||'ere r = 4) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_cbs'',                   18, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_cbs'',                       19, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_cbs'',                          20, '''', null, ''N'', ''N'', to_char(nvl(l_valor_cbs,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where'
||' r = 18) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_ibs'',                   21, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_ibs'',                       22, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_ibs'',                          23, '''', null, ''N'', ''N'', to_char(nvl(l_valor_ibs,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) where'
||' r = 19) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'             ',
'               SELECT p_codigo_artefato, ''base_calculo_icms'',                  24, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_icms'',                      25, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_icms'',                         26, '''', null, ''N'', ''N'', to_char(nvl(l_valor_icms,0), ''FM999G999G990D00'') valor, (select d from table(pkg_util.dominio_retorna_lista(''ng_despesa'', ''ind_tipo_despesa'')) wher'
||'e r = 5) tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'',
'               SELECT p_codigo_artefato, ''base_calculo_icms_st'',               27, '''', null, ''N'', ''S'', null valor, null tag_campo, null url , null id_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''aliquota_icms_st'',                   28, '''', null, ''N'', ''N'', to_char(nvl(l_tributo.aliquota_icms,0), ''FM999G999G990D00'') valor, ''IMP_PROCESSOIMPORTACAO_ITEM_TRIBUTO.aliquota_icms'' tag_campo, null url , null i'
||'d_artefato_versionado_zoom, null html FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_icms_st'',                      29, '''', null, ''N'', ''N'', to_char(nvl(l_valor_icms_st,0), ''FM999G999G990D00'') valor, (pkg_ui.retorna_label_tela(''icms-st'')) tag_campo, null url , null id_artefato_versionado'
||'_zoom, null html FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, url, id_artefato_versionado_zoom, html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.url, new_data.id_arte'
||'fato_versionado_zoom, new_data.html);',
'    end formulario;',
'',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob',
'    is',
'        l_modo_refresh varchar2(30);',
'        l_id_processoimportacao number;',
'    begin',
'        l_modo_refresh := upper(nvl(p_modo_refresh, ''ONCE''));',
'        select b.id_processoimportacao into l_id_processoimportacao from imp_processoimportacao_item_tributo a join imp_processoimportacao_item b on b.id = a.id_processoimportacao_item where a.id = apex_util.get_session_state(''P9010_PARAMETRO'');',
'',
'        return q''~',
'            select case',
'                when exists (',
'                    select 1 from imp_processoimportacao a where a.id = ~'' || l_id_processoimportacao || q''~ and nvl(a.ind_calculando_valores,''N'') = ''N''',
'                    )',
'                    then ''S''',
'                    else ''N''',
'                end as atualizar,',
'                ''~'' || l_modo_refresh || q''~'' as modo_refresh',
'            from dual',
'        ~'';',
'    end sql_auto_refresh;',
'',
'end "UI_MPD_TD1046";',
'/'))
);
end;
