prompt --application/deployment/install/install_ui_mpd_td934
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(208675064123272824)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD934'
,p_sequence=>3170
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 03/06/2026',
unistr('-- Motivo: Alterado tela base do CRUD din\00E2mico para 9014'),
'-- Jira: PEDITEM-320',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 29/05/2026',
unistr('-- Motivo: Ajuste para utilizar a funcionalidade de op\00E7\00F5es da interface padr\00E3o da tela din\00E2mica'),
'-- Jira: PEDITEM-206',
'',
'create or replace package "UI_MPD_TD934" as   ',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    );',
'',
'    function sql_report_selecao(',
'        p_param1 in varchar2',
'    ) return clob;',
'',
'    function label_coluna(',
'        campo in varchar2',
'    ) return clob;',
'',
'    function mostra_opcao(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'    ',
'    -- procedure post(',
'    --     p_id       in number default null,',
'    --     p_sucesso  out clob,',
'    --     p_messages out pkg_mensagem.message_record_table     ',
'    -- );',
'   ',
'end "UI_MPD_TD934";',
'/',
'',
'create or replace package body "UI_MPD_TD934" as    ',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select ',
'                    a.num_invoice,',
'                    pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status,                    ',
'                    case',
'                        when b.num_processoimportacao is not null then',
'                            b.num_processoimportacao',
'                        else',
'                            pkg_componentes.html_cor_texto(pkg_ui.retorna_label_tela(''''sem_processo''''))',
'                    end id_processoimportacao',
'                from imp_invoice a',
'                left join imp_processoimportacao b on b.id = a.id_processoimportacao            ',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    ) is',
'        l_html_nodatafound clob;',
'        l_verifica number;',
'        l_sql_grid_1 clob;',
'        l_url clob;',
'        l_html clob;',
'        l_tag_aprovar_tudo varchar2(250) := pkg_ui.retorna_label_botao(''aprovar_tudo'');        ',
'    begin',
'        l_html_nodatafound := ''<div role="region" aria-label="Mensagem" class="a-IRR-noDataMsg"><div class="a-IRR-noDataMsg-icon"><span class="a-Icon icon-irr-no-results" aria-hidden="true"></span></div><span class="a-IRR-noDataMsg-text">Nenhum regis'
||'tro adicionado ainda.</span></div>'';',
'        ',
'        l_url := apex_page.get_url(',
'            p_page => 9001, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9001_CODIGO_ARTEFATO,P9001_ID,P9001_METODO_EXECUCAO,P9001_METODO_DETALHE,P9001_TIPO_CONFIRMACAO'',',
'            p_values => ''TD987,TD987,''||p_param1||'',bo_imp_invoice_divergencia.aprova_todas_divergencias,bo_imp_invoice.detalhe_registro,1'',',
'            p_triggering_element => ''apex.jQuery("#NEW")'',',
'            p_clear_cache => 9001',
'        );',
'        ',
'        l_html := ''<div id="NEW" style="display: flex; align-items: center; justify-content: end;"><a id="NEW" href="''||l_url||''"><button id="NEW" class="t-Button t-Button--icon js-ignoreChange t-Button--success t-Button--iconLeft lto5893482872689621'
||'6_0 t-Button--hot" style="margin-top:0px;" type="button"><span class="t-Icon t-Icon--left fa fa-check-circle" aria-hidden="true"></span><span class="t-Button-label">''||l_tag_aprovar_tudo||''</span><span class="t-Icon t-Icon--right fa fa-plus-circle" a'
||'ria-hidden="true"></span></button></a></div>'';        ',
'        ',
'        select count(1) into l_verifica from imp_invoice_divergencia where id_invoice = p_param1;',
'        if l_verifica > 0 then',
'            l_sql_grid_1 := ',
'            q''~',
'                select',
'                    pkg_util.dominio_retorna_tag(''imp_invoice_divergencia'',''ind_divergencia'',a.ind_divergencia) imp_invoice_divergencia$ind_divergencia,',
'                    pkg_util.dominio_retorna_tag(''imp_invoice_divergencia'',''ind_status'',a.ind_status) imp_invoice_divergencia$ind_status,',
'                    case',
'                        when ind_divergencia in (1,2,3) and conteudo_pedido <> -1 then',
'                            bo_ng_pessoa.retorna_pessoa(a.conteudo_invoice)                        ',
'                        when ind_divergencia = 4 then',
'                            pkg_traducao.get_traducao((select descricao_condicaopagamento from ng_condicaopagamento where id = conteudo_invoice))',
'                        when ind_divergencia = 5 then',
'                            (select codigo_incoterm from ng_incoterm where id = conteudo_invoice)',
'                        when ind_divergencia = 6 then',
'                            (select codigo_moeda||'' - ''||simbolo_iso from ng_moeda where id = conteudo_invoice)',
'                        when ind_divergencia = 7 and ind_tipo_dado = ''D'' then',
'                            to_char(replace(a.conteudo_invoice, ''.'', '',''),''FM999G999G990D00000'')',
'                        when ind_divergencia = 8 then',
'                            (select codigo_unidademedida from ng_unidademedida where id = conteudo_invoice)',
'                        when ind_divergencia = 9 then',
'                            (select codigo_ncm from ng_ncm where id = conteudo_invoice)',
'                        when ind_divergencia = 10 then                            ',
'                            to_char(replace(a.conteudo_invoice, ''.'', '',''),''FM999G999G990D00000'')',
'                        else',
'                            a.conteudo_invoice',
'                    end imp_invoice_divergencia$conteudo_invoice,',
'                    case',
'                        when ind_divergencia in (1,2,3) and conteudo_pedido <> -1 then',
'                            bo_ng_pessoa.retorna_pessoa(a.conteudo_pedido)        ',
'                        when ind_divergencia = 4 then',
'                            pkg_traducao.get_traducao((select descricao_condicaopagamento from ng_condicaopagamento where id = conteudo_pedido))',
'                        when ind_divergencia = 5 then',
'                            (select codigo_incoterm from ng_incoterm where id = conteudo_pedido)',
'                        when ind_divergencia = 6 then',
'                            (select codigo_moeda||'' - ''||simbolo_iso from ng_moeda where id = conteudo_pedido)',
'                        when ind_divergencia = 7 and ind_tipo_dado = ''D'' then',
'                            to_char(replace(a.conteudo_pedido, ''.'', '',''),''FM999G999G990D00000'')',
'                        when ind_divergencia = 8 then',
'                            (select codigo_unidademedida from ng_unidademedida where id = conteudo_pedido)',
'                        when ind_divergencia = 9 then',
'                            (select codigo_ncm from ng_ncm where id = conteudo_pedido)',
'                        when ind_divergencia = 10 then',
'                            to_char(replace(a.conteudo_pedido, ''.'', '',''),''FM999G999G990D00000'')',
'                        else',
'                            a.conteudo_pedido',
'                    end imp_invoice_divergencia$conteudo_pedido,',
'                    --pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD934'', p_param1 => ''0'') opcao',
'                    pkg_componentes.html_botao_opcao_com_icone(p_id => a.id, p_pagina => ''TD934'', p_param1 => ''0'') opcao',
'                from imp_invoice_divergencia a',
'                left join imp_invoice_item b on b.id = a.id_invoice_item',
'                left join ng_unidademedida c on c.id = b.id_unidademedida',
'                where a.id_invoice = #PARAM1#',
'                order by ind_divergencia',
'            ~'';   ',
'            l_sql_grid_1 := replace(l_sql_grid_1, ''#PARAM1#'', p_param1);',
'',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna2'' AS nome_coluna, 2 AS indice, /*''GRI''*/''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, to_char(l_sql_grid_1) valor, null html, null'
||' tag_campo FROM dual --UNION ALL',
'                   --SELECT p_codigo_artefato, '''', 1, ''HTM'', null, ''S'', ''N'', null valor, l_html html, null tag_campo FROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);',
'        else',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, null valor, l_html_nodatafound html, null tag_campo F'
||'ROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);',
'        end if;',
'    end formulario;    ',
'    ',
'    function sql_report_selecao(',
'        p_param1 in varchar2',
'    ) return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select',
'                null selected,',
'                a.id,',
'                pkg_util.dominio_retorna_tag(''imp_invoice_divergencia'',''ind_divergencia'',a.ind_divergencia) campo1,',
'                pkg_util.dominio_retorna_tag(''imp_invoice_divergencia'',''ind_status'',a.ind_status) campo2,',
'                case',
'                    when ind_divergencia in (1,2,3) and conteudo_pedido <> -1 then',
'                        bo_ng_pessoa.retorna_pessoa(a.conteudo_invoice)                        ',
'                    when ind_divergencia = 4 then',
'                        pkg_traducao.get_traducao((select descricao_condicaopagamento from ng_condicaopagamento where id = conteudo_invoice))',
'                    when ind_divergencia = 5 then',
'                        (select codigo_incoterm from ng_incoterm where id = conteudo_invoice)',
'                    when ind_divergencia = 6 then',
'                        (select codigo_moeda||'' - ''||simbolo_iso from ng_moeda where id = conteudo_invoice)',
'                    when ind_divergencia = 7 and ind_tipo_dado = ''D'' then',
'                        to_char(replace(a.conteudo_invoice, ''.'', '',''),''FM999G999G990D00000'')',
'                    when ind_divergencia = 8 then',
'                        (select codigo_unidademedida from ng_unidademedida where id = conteudo_invoice)',
'                    when ind_divergencia = 9 then',
'                        (select codigo_ncm from ng_ncm where id = conteudo_invoice)',
'                    when ind_divergencia = 10 then                            ',
'                        to_char(replace(a.conteudo_invoice, ''.'', '',''),''FM999G999G990D00000'')',
'                    else',
'                        a.conteudo_invoice',
'                end campo3,',
'                case',
'                    when ind_divergencia in (1,2,3) and conteudo_pedido <> -1 then',
'                        bo_ng_pessoa.retorna_pessoa(a.conteudo_pedido)        ',
'                    when ind_divergencia = 4 then',
'                        pkg_traducao.get_traducao((select descricao_condicaopagamento from ng_condicaopagamento where id = conteudo_pedido))',
'                    when ind_divergencia = 5 then',
'                        (select codigo_incoterm from ng_incoterm where id = conteudo_pedido)',
'                    when ind_divergencia = 6 then',
'                        (select codigo_moeda||'' - ''||simbolo_iso from ng_moeda where id = conteudo_pedido)',
'                    when ind_divergencia = 7 and ind_tipo_dado = ''D'' then',
'                        to_char(replace(a.conteudo_pedido, ''.'', '',''),''FM999G999G990D00000'')',
'                    when ind_divergencia = 8 then',
'                        (select codigo_unidademedida from ng_unidademedida where id = conteudo_pedido)',
'                    when ind_divergencia = 9 then',
'                        (select codigo_ncm from ng_ncm where id = conteudo_pedido)',
'                    when ind_divergencia = 10 then',
'                        to_char(replace(a.conteudo_pedido, ''.'', '',''),''FM999G999G990D00000'')',
'                    else',
'                        a.conteudo_pedido',
'                end campo4,',
'                null campo5,',
'                null campo6,',
'                null campo7,',
'                null campo8,',
'                null campo9,',
'                null campo10,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD934'', p_param1 => ''0'') opcao',
'                --pkg_componentes.html_botao_opcao_com_icone(p_id => a.id, p_pagina => ''TD934'', p_param1 => ''0'') opcao',
'            from imp_invoice_divergencia a',
'            left join imp_invoice_item b on b.id = a.id_invoice_item',
'            left join ng_unidademedida c on c.id = b.id_unidademedida',
'            where a.id_invoice = #PARAM1#',
'            order by ind_divergencia',
'        ~'';',
'        l_sql := replace(l_sql,''#PARAM1#'',nvl(p_param1,''''));',
'        return l_sql;       ',
'    end sql_report_selecao;',
'',
'    function label_coluna(',
'        campo in varchar2',
'    ) return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.ind_divergencia'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.ind_status'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.conteudo_invoice'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''imp_invoice_divergencia.conteudo_pedido'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    function mostra_opcao(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_url clob;',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9000,',
'            p_items=> ''P9000_ID,P9000_PAGINA,P9000_PARAMETRO'',',
'            p_values => p_param1 || '',TD934''',
'            );',
'        return l_url;',
'    end mostra_opcao;',
'',
'    -- procedure post(',
'    --     p_id       in number default null,  ',
'    --     p_sucesso  out clob,',
'    --     p_messages out pkg_mensagem.message_record_table         ',
'    -- )is',
'    --     l_id number;',
'    -- begin',
'    --     null;',
'    -- end post;',
'',
'end "UI_MPD_TD934";',
'/'))
);
end;
