,p_name=>'UI_MPD_TD1063'
,p_sequence=>3190
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1063" as',
