'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    ',
'end "UI_MPD_TD1063";',
'/',
'create or replace package body "UI_MPD_TD1063" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;        ',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''', b.ind_tipo_movimento) as ind_tipo_movimento,',
'                    bo_ng_pessoa.retorna_pessoa(b.id_fornecedor) id_fornecedor',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_numerario b on b.id_processoimportacao = a.id',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
