'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_url clob;',
'        l_html clob;',
'        l_html_nodatafound clob;     ',
'        l_verifica number;   ',
'        l_sql_grid_1 clob;        ',
'        l_novo varchar2(4000) := pkg_ui.retorna_label_botao(''novo'');',
'        l_texto_nenhum_registro varchar2(4000) := pkg_ui.retorna_label_botao(''nenhum-registro'');',
'    begin',
'        l_url := apex_page.get_url(',
'            p_page => 9010, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO,P9010_PARAMETRO'', ',
'            p_values => ''TD998,TD998,''||p_param1,',
'            p_triggering_element => ''apex.jQuery("#NEW")'',',
'            p_clear_cache => 9010',
'        );',
'        l_html := ''<div id="NEW" style="display: flex; align-items: center; justify-content: end; margin:0.5rem"><a id="NEW" href="''||l_url||''"><button id="NEW" class="t-Button t-Button--icon js-ignoreChange t-Button--success t-Button--iconLeft lto58'
||'934828726896216_0 t-Button--hot" style="margin-top:0px;" type="button"><span class="t-Icon t-Icon--left fa fa-plus-circle" aria-hidden="true"></span><span class="t-Button-label">''||l_novo||''</span><span class="t-Icon t-Icon--right fa fa-plus-circle" '
||'aria-hidden="true"></span></button></a></div>'';          ',
'        ',
'        l_html_nodatafound := l_html || ''<div role="region" aria-label="Mensagem" class="a-IRR-noDataMsg"><div class="a-IRR-noDataMsg-icon"><span class="a-Icon icon-irr-no-results" aria-hidden="true"></span></div><span class="a-IRR-noDataMsg-text">''|'
||'| l_texto_nenhum_registro||''</span></div>'';',
'',
'        select count(1) into l_verifica from imp_processoimportacao_numerario a join imp_processoimportacao_numerario_cotacao b on b.id_numerario = a.id where a.id = p_param1;',
'        if l_verifica > 0 then',
'            l_sql_grid_1 := ',
'            q''~',
'                select ',
'                    to_char(d.codigo_moeda||'' - ''||d.simbolo_iso) imp_processoimportacao_numerario_cotacao$id_moeda,',
'                    to_char(b.taxa_cambio, ''FM999G999G990D00'') imp_processoimportacao_numerario_cotacao$taxa_cambio,',
'                    pkg_componentes.html_botao_opcao_com_icone(p_id => b.id, p_pagina => ''TD1063'', p_param1 => ''0'') opcao',
'                from imp_processoimportacao_numerario a ',
'                join imp_processoimportacao_numerario_cotacao b on b.id_numerario = a.id',
'                left join ng_moeda d on d.id = b.id_moeda',
'                where a.id = #PARAM1#       ',
'                order by 1     ',
'            ~'';   ',
'            l_sql_grid_1 := replace(l_sql_grid_1, ''#PARAM1#'', p_param1);',
'',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, null valor, l_html html, null tag_campo FROM dual UNI'
||'ON ALL',
'                   SELECT p_codigo_artefato AS codigo_artefato, ''coluna2'' AS nome_coluna, 1 AS indice, ''GRI'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, to_char(l_sql_grid_1) valor, null html, null tag_camp'
||'o FROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);',
'        else',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''coluna1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, null valor, l_html_nodatafound html, null tag_campo F'
||'ROM dual',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, html, tag_campo)',
