prompt --application/deployment/install/install_ui_mpd_td1064
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(222788087676404225)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1064'
,p_sequence=>3200
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1064" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD1064";',
'/',
'create or replace package body "UI_MPD_TD1064" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;        ',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    p.num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''', n.ind_tipo_movimento) as ind_tipo_movimento',
'                from imp_processoimportacao_numerario_cotacao c',
'                join imp_processoimportacao_numerario n on n.id = c.id_numerario',
'                join imp_processoimportacao p on p.id = n.id_processoimportacao',
'                where c.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao, NULL AS nome_consulta, ''S'' AS somente_leitura, ''S'' coluna_tabela, NULL valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                3, '''', NULL, ''S'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''taxa_cambio'',             5, '''', NULL, ''N'', ''S'', null valor FROM dual UNION ALL                                                           ',
'               SELECT p_codigo_artefato, ''id_numerario'',            6, ''HID'', NULL, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',          8, '''', NULL, ''N'', ''S'', null valor FROM dual                                             ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is        ',
'    begin',
'        bo_imp_processoimportacao_numerario_cotacao.altera_registro(                                    ',
'            p_id_tenant             => apex_application.g_f02(1),',
'            p_id_numerario          => apex_application.g_f06(1),',
'            p_id_moeda              => apex_application.g_f03(1),',
'            p_taxa_cambio           => apex_application.g_f05(1),',
'            p_data_alteracao        => TO_TIMESTAMP(apex_application.g_f08(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id                    => p_id, ',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD1064";',
'/'))
);
end;
/
