'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update imp_processoimportacao_numerario_cotacao set  ',
'            id_tenant = v_new.id_tenant,',
'            id_numerario = v_new.id_numerario,',
'            id_moeda = v_new.id_moeda,',
