'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_id_moeda(p_id_moeda);',
'    end valida_id_moeda;     ',
'',
'    procedure valida_taxa_cambio(p_taxa_cambio in imp_processoimportacao_numerario_cotacao.taxa_cambio%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_taxa_cambio is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_processoimportacao_numerario_cotacao.taxa_cambio''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_taxa_cambio(p_taxa_cambio);',
'    end valida_taxa_cambio;    ',
'',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'',
'    procedure hook_valida_id_tenant(p_id_tenant in imp_processoimportacao_numerario_cotacao.id_tenant%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_tenant;     ',
'',
'    procedure hook_valida_id_numerario(p_id_numerario in imp_processoimportacao_numerario_cotacao.id_numerario%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_numerario;     ',
'',
'    procedure hook_valida_id_moeda(p_id_moeda in imp_processoimportacao_numerario_cotacao.id_moeda%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_moeda;     ',
'',
'    procedure hook_valida_taxa_cambio(p_taxa_cambio in imp_processoimportacao_numerario_cotacao.taxa_cambio%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_taxa_cambio;     ',
'',
'',
'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_numerario_cotacao'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_numerario_cotacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_numerario_cotacao'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_numerario_cotacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_processoimportacao_numerario_cotacao'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_processoimportacao_numerario_cotacao'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_processoimportacao_numerario_cotacao%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''id_numerario'', p_rec.id_numerario, true);',
'        apex_json.write(''id_moeda'', p_rec.id_moeda, true);',
'        apex_json.write(''taxa_cambio'', p_rec.taxa_cambio, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'',
'    function detalhe_registro (',
'        p_id in imp_processoimportacao_numerario_cotacao.id%type',
'    ) return varchar2 is',
'        l_html clob;',
'    begin',
'        l_html := pkg_ui.campos_detalhes(q''~',
'            select ',
'                c.num_processoimportacao as imp_processoimportacao_numerario$id_processoimportacao,',
'                pkg_util.dominio_retorna_tag(''imp_processoimportacao_numerario'', ''ind_tipo_movimento'', b.ind_tipo_movimento) as imp_processoimportacao_numerario$ind_tipo_movimento,',
'                d.codigo_moeda || '' - '' || d.simbolo_iso as imp_processoimportacao_numerario_cotacao$id_moeda',
'            from imp_processoimportacao_numerario_cotacao a',
'            join imp_processoimportacao_numerario b on b.id = a.id_numerario',
'            join imp_processoimportacao c on c.id = b.id_processoimportacao',
'            join ng_moeda d on d.id = a.id_moeda',
'            where a.id = ~''||p_id);',
'',
'        l_html := l_html || ''<div style="margin:1rem;font-weight:bold;">''|| pkg_ui.retorna_label_botao(''msg_excluir_cotacao_numerario'') || ''</div>'';',
'        ',
'        return l_html;',
'    end detalhe_registro;',
'',
'    procedure atualizar_cotacoes_json (',
'        p_json      in clob,',
'        p_pagina    in number default null,',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        l_count        number;',
'        l_id           number;',
'        l_taxa_cambio  number;',
'        l_reg          imp_processoimportacao_numerario_cotacao%rowtype;',
'        l_sucesso_aux  clob;',
'        l_messages_aux pkg_mensagem.message_record_table;',
'    begin',
'        p_sucesso  := null;',
'        p_messages := pkg_mensagem.message_record_table();',
'',
'        -- Parse do JSON',
'        apex_json.parse(p_json);',
'        l_count := apex_json.get_count(p_path => ''.'');',
'',
unistr('        -- Loop nas cota\00E7\00F5es'),
'        for i in 0 .. l_count -1 loop',
'            l_id := apex_json.get_number(''[''||i||''].id'');',
'            l_taxa_cambio := apex_json.get_number(''[''||i||''].taxa_cambio'');',
'',
'            if l_id is not null and l_taxa_cambio is not null then',
'                begin',
'                    -- Busca registro atual',
'                    select * into l_reg from imp_processoimportacao_numerario_cotacao where id = l_id;',
'',
unistr('                    -- altera\00E7\00E3o numerario_cotacao'),
'                    altera_registro(',
'                        p_id_tenant      => l_reg.id_tenant,',
'                        p_id_numerario   => l_reg.id_numerario,',
'                        p_id_moeda       => l_reg.id_moeda,',
'                        p_taxa_cambio    => l_taxa_cambio,',
'                        p_id             => l_reg.id,',
'                        p_data_alteracao => l_reg.data_alteracao,',
'                        p_pagina         => p_pagina,',
'                        p_encadeado      => true,',
'                        p_sucesso        => l_sucesso_aux,',
'                        p_messages       => l_messages_aux',
'                    );',
'                 end;       ',
'            end if;',
'        end loop;',
'',
'        p_sucesso := l_sucesso_aux;',
'        p_messages := l_messages_aux;',
'',
'    exception',
'        when others then',
'            apex_debug.error(''ERRO: '' || sqlerrm);',
'            raise;',
'    end atualizar_cotacoes_json;',
'',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_processoimportacao_numerario_cotacao;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td520
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(223365936514140244)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD520'
,p_sequence=>3220
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'create or replace package "UI_MPD_TD520" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function label_acao return varchar2;',
'',
'    function valida(p_id in number) return pkg_mensagem.message_record_table;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD520";',
'/',
'',
'create or replace package body "UI_MPD_TD520" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'        l_status varchar2(50);',
'    begin               ',
'        l_status := ''"''||pkg_util.dominio_retorna_tag(''imp_pedidoimportacao'',''ind_status_pedido_importacao'',2)||''"'';',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao, bo_ng_pessoa.retorna_pessoa(id_exportador) id_exportador, bo_ng_pessoa.retorna_pessoa(id_importador) id_importador from imp_pedidoimportacao a where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_pedidoimportacao'',''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.56.l'')||''</h3></div>''||',
'        ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        replace(retorna_texto(''msg.56.h''),''$param1'',l_status)||''</h3></div>'';',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'    begin        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''numero_pedido_importacao'',                  2, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',                 3, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_exportador'',                             4, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                             6, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                             8, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_comprador'',                             10, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_vendedor'',                            12, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_proforma'',                          14, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                                 15, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_viatransporte'',                         19, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_incoterm'',                              20, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_listapreco'',                            22, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_origem'',                       24, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_embarque'',                        26, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_desembarque'',                     28, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_destino'',                      30, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_entrega'',                       32, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_condicaopagamento'',                     33, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas_pagamento'',            35, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_mercadoria'',                   37, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto'',                           38, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesa_proforma'',                   39, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_condicao_venda'',               40, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_confirmacao_pedido'',                  41, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_todos_itens_com_entregas_programadas'', 42, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                           43, '''', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pedido_importacao'',             44, ''HID'', null, ''N'', ''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao_parcela_pagamento'',           45, ''HID'', null, ''N'', ''S'', null valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);    ',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end;',
'',
'    function valida(p_id in number) return pkg_mensagem.message_record_table ',
'    is',
'        l_id_entidade number;',
'        l_verifica_titulopagamento number;',
'        l_verifica_invoice number;',
'        l_verifica_processoimportacao number;',
'        v_parametro pkg_mensagem.paramentros;',
'        v_message pkg_mensagem.message_record;',
'        v_messages pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';',
'',
unistr('        -- Verifica se existem t\00EDtulos de pagamento para este pedido de importa\00E7\00E3o:'),
'        select count(1) into l_verifica_titulopagamento',
'        from fin_titulopagamento a',
'        join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'        where a.id_entidade = l_id_entidade',
'        and a.ind_status_pagamento in (1,2)',
'        and b.id_pedidoimportacao = p_id;',
'        ',
'        -- Verifica se existem invoices vinculadas:',
'        -- select count(1) into l_verifica_invoice',
'        -- from imp_entrega',
'        -- where id_pedidoimportacao = p_id ',
'        -- and id_invoice is not null;',
'        ',
unistr('        -- Verifica se existem processos de importa\00E7\00E3o vinculados:'),
'        -- select count(1) into l_verifica_processoimportacao',
'        -- from imp_entrega a',
'        -- where id_pedidoimportacao = p_id',
'        -- and id_processoimportacao is not null;',
'',
unistr('        -- Faz a valida\00E7\00E3o em fin_titulopagamento.ind_status_pagamento:'),
'        if l_verifica_titulopagamento > 0 then           ',
'            v_parametro(0) := ''UI_MPD_TD520.VALIDA'';',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem  => ''119'',',
'                p_nome_campo       => ''ind_status_pedido_importacao'',',
'                p_parametro        => v_parametro,',
'                p_pagina           => 9010,',
'                p_objeto_mensagem  => v_message',
'            );',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;',
'        end if;',
'',
unistr('        -- Faz a valida\00E7\00E3o em imp_entrega.id_invoice:'),
'        -- if l_verifica_invoice > 0 then           ',
'        --     v_parametro(0) := ''UI_MPD_TD520.VALIDA'';',
'        --     pkg_mensagem.mensagem_campo(',
'        --         p_codigo_mensagem  => ''126'',',
'        --         p_nome_campo       => ''ind_status_pedido_importacao'',',
'        --         p_parametro        => v_parametro,',
'        --         p_pagina           => 9010,',
'        --         p_objeto_mensagem  => v_message',
'        --     );',
'        --     v_messages.extend;',
'        --     v_messages(v_messages.last) := v_message;',
'        -- end if;',
'',
unistr('        -- Faz a valida\00E7\00E3o em imp_entrega.id_processoimportacao:'),
'        -- if l_verifica_processoimportacao > 0 then           ',
'        --     v_parametro(0) := ''UI_MPD_TD520.VALIDA'';',
'        --     pkg_mensagem.mensagem_campo(',
'        --         p_codigo_mensagem  => ''127'',',
'        --         p_nome_campo       => ''ind_status_pedido_importacao'',',
'        --         p_parametro        => v_parametro,',
'        --         p_pagina           => 9010,',
'        --         p_objeto_mensagem  => v_message',
'        --     );',
'        --     v_messages.extend;',
'        --     v_messages(v_messages.last) := v_message;',
'        -- end if;',
'',
'        return v_messages;',
'    end valida;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is ',
'    begin',
'        bo_imp_pedidoimportacao.desconfirmar_pedido(',
'            p_id => p_id,             ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages             ',
'        );',
'    end;',
'',
'end "UI_MPD_TD520";',
'/'))
);
end;
