prompt --application/deployment/install/install_ui_mpd_td693
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(223369555869162275)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD693'
,p_sequence=>3230
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'create or replace package "UI_MPD_TD693" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function label_acao return varchar2;',
'',
'    function valida(p_id in number) return pkg_mensagem.message_record_table;',
'',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'    ',
'end "UI_MPD_TD693";',
'/',
'',
'create or replace package body "UI_MPD_TD693" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.obtervaloresdascolunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.numero_pedido_importacao,',
'                    d.num_entrega,',
'                    case',
'                        when d.id_processoimportacao is null then',
'                            pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                        else e.num_processoimportacao',
'                    end as id_processoimportacao',
'                from imp_pedidoimportacao a',
'                join imp_pedidoimportacao_item b on b.id_pedidoimportacao = a.id',
'                join imp_entrega_item c on c.id_pedidoimportacao_item = b.id',
'                join imp_entrega d on d.id = c.id_entrega',
'                left join imp_processoimportacao e on e.id = d.id_processoimportacao',
'                where c.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_entrega''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_descricao_item varchar2(4000);',
'        l_descricao_unidademedida varchar2(4000);',
'        l_quantidade varchar2(4000);',
'        l_descricao_moeda varchar2(4000);',
'        l_valor_total_condicao_venda varchar2(4000);',
'    begin',
'        select                                                 ',
'            c.codigo_item||'' - ''||pkg_traducao.get_traducao(c.descricao_item),',
'            --pkg_traducao.get_traducao(j.descricao_unidademedida), ',
'            j.codigo_unidademedida,',
'            case j.ind_tipo_dado',
'                when ''D'' then to_char(a.quantidade, ''FM999G999G990D00'')',
'                when ''I'' then to_char(a.quantidade)',
'            end,',
'            --a.peso_liquido_total as imp_entrega_item$peso_liquido_total, ',
'            --pkg_traducao.get_traducao(h.descricao_moeda) as imp_pedidoimportacao$id_moeda,',
'            to_char(a.valor_total_condicao_venda, ''FM999G999G990D00'')',
'        into',
'            l_descricao_item,',
'            l_descricao_unidademedida,',
'            l_quantidade,',
'            l_valor_total_condicao_venda',
'        from imp_entrega_item          a',
'        left join ng_pessoa_juridica   b on b.id_pessoa = a.id_fabricante',
'        join ng_item                   c on c.id = a.id_item',
'        join imp_pedidoimportacao_item d on d.id = a.id_pedidoimportacao_item',
'        join imp_pedidoimportacao      e on e.id = d.id_pedidoimportacao',
'        left join ng_unidademedida     j on j.id = a.id_unidademedida',
'        left join ng_moeda             h on h.id = e.id_moeda',
'        where a.id = p_param1;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_pedidoimportacao_item'' AS nome_coluna, 1 AS indice, ''TEX'' AS tipo_interacao, '''' AS nome_consulta, ''S'' AS somente_leitura, ''N'' AS coluna_tabela, l_descricao_item valor, ''imp_entrega_item.'
||'id_pedidoimportacao_item'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',           2, ''TXT'', null, ''S'', ''N'', l_descricao_unidademedida valor, ''imp_entrega_item.id_unidademedida'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade'',                 3, ''TXT'', null, ''S'', ''N'', l_quantidade valor, ''imp_entrega_item.quantidade'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_liquido_total'',         4, '''', null, ''S'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''moeda'',                      5, '''', null, ''S'', ''N'', to_char((select codigo_moeda||'' - ''||simbolo_iso from imp_pedidoimportacao a join ng_moeda b on b.id = a.id_moeda join imp_entrega c on c.id_pedidoimportaca'
||'o = a.id join imp_entrega_item d on d.id_entrega = c.id where d.id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_condicao_venda'', 6, ''TXT'', null, ''S'', ''N'', l_valor_total_condicao_venda valor, ''imp_entrega_item.valor_total_condicao_venda'' tag_campo FROM dual',
'               ) new_data',
unistr('        on (tf.codigo_artefato = new_data.codigo_artefato and tf.nome_coluna = new_data.nome_coluna)  -- condi\00E7\00E3o de correspond\00EAncia'),
'        when not matched then',
'            insert (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            values (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end;',
'',
'    function valida(p_id in number)',
'        return pkg_mensagem.message_record_table ',
'    is',
'        l_id_entrega number;',
'        l_id_entidade number;',
'        l_verifica_titulopagamento number;',
'        v_parametro pkg_mensagem.paramentros;',
'        v_message   pkg_mensagem.message_record;',
'        v_messages  pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select id_entrega into l_id_entrega from imp_entrega_item where id = p_id;',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';        ',
'',
unistr('        -- Verifica se existem t\00EDtulos de pagamento para esta entrega:'),
'        select count(1) into l_verifica_titulopagamento',
'        from fin_titulopagamento a',
'        join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'        where a.id_entidade = l_id_entidade',
'        and a.ind_status_pagamento in (1,2)',
'        and b.id_entrega = l_id_entrega;',
'        ',
unistr('        -- Valida\00E7\00E3o:'),
'        if l_verifica_titulopagamento > 0 then           ',
'            v_parametro(0) := ''UI_MPD_TD_693.valida'';',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem  => ''129'',',
'                p_nome_campo       => ''valor_total_condicao_venda'',',
'                p_parametro        => v_parametro,',
'                p_pagina           => 9010,',
'                p_objeto_mensagem  => v_message',
'            );',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'        end if;',
'',
'        return v_messages;',
'    end valida;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_entrega_item.exclui_registro(',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end post;',
'',
'end "UI_MPD_TD693";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td899
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(223370259688171132)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD899'
,p_sequence=>3240
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'create or replace package "UI_MPD_TD899" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_valor_item(p_param1 in varchar2) return clob;',
'    ',
'',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob;',
'',
'',
'    function where_dinamico (p_campo in varchar2) return clob;',
'',
'    function valida(p_id in number) return pkg_mensagem.message_record_table;',
'',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    );',
'',
'    ',
'',
'end "UI_MPD_TD899";',
'/',
'',
'create or replace package body "UI_MPD_TD899" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'            select',
'            a.numero_pedido_importacao,',
'            c.num_entrega,',
'            case when c.id_processoimportacao is null then',
'                 pkg_componentes.html_cor_texto(''''''||retorna_texto(''msg.93.l'')||'''''')',
'                 else d.num_processoimportacao',
'            end num_processoimportacao  ',
'            from imp_pedidoimportacao      a ',
'            join imp_entrega               c on c.id_pedidoimportacao = a.id ',
'            left join imp_processoimportacao    d on d.id = c.id_processoimportacao',
'            where c.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega'',''imp_processoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                          ',
'        l_consulta_item clob;',
'        l_atribuir_valor_item clob;',
'        l_JSON_calcular_valor_total clob;',
'        l_campos_calcular_valor_quantidade varchar2(128) := ''VALOR_TOTAL_CONDICAO_VENDA'';',
'        l_campos_item apex_t_varchar2 := apex_t_varchar2(''ID_UNIDADEMEDIDA'',''ID_NCM'',''QUANTIDADE'',''VALOR_FINAL'',''VALOR_INICIAL'',''ID_FABRICANTE'',''VALOR_UNITARIO'',''VALOR_DESCONTO_UNITARIO'',''PESO_UNITARIO'',''PESO_LIQUIDO_TOTAL'',''VALOR_TOTAL_CONDICAO_VEND'
||'A'',''ID_NATUREZAOPERACAO'',''ID_ITEMM'',''IND_LICENCA_IMPORTACAO'',''IND_BLOQUEIO_EMBARQUE_ATE_DEFERIMENTO_LI'',''ID_PEDIDO_IMPORTACAO_ITEM'');',
'        l_campos_quantidade apex_t_varchar2 := apex_t_varchar2(''PESO_LIQUIDO_TOTAL'',''VALOR_TOTAL_CONDICAO_VENDA'');           ',
'        l_atribuir_valor_unidademedida clob;',
'        l_campos_unidademedida apex_t_varchar2 := apex_t_varchar2(''QTD_DECIMAIS'');   ',
'        v_executa_js_digito clob; ',
'    begin    ',
'        l_consulta_item := ''select a.codigo_item || '''' - ''''||to_char(chamar_webservice_traducao(esquema_corrente,''''ng_item'''',''''descricao_item'''',apex_util.get_session_state(''''IDIOMA_LOGADO''''),a.id)) as d,  a.id as r from ng_item a join ng_item_produto'
||' b on b.id_item = a.id where a.ind_tipo_item = ''''P'''' order by 1'';',
'        l_consulta_item := ''select a.codigo_item || '''' - ''''||pkg_traducao.get_traducao(a.descricao_item) as d,  a.id as r from ng_item a join ng_item_produto b on b.id_item = a.id where a.ind_tipo_item = ''''P'''' order by 1'';',
'',
'',
'',
'        ',
'        l_JSON_calcular_valor_total := gerar_json_lista(',
'            SYS.ODCIVARCHAR2LIST(''QUANTIDADE * (VALOR_UNITARIO - VALOR_DESCONTO_UNITARIO)'', ''QUANTIDADE * PESO_UNITARIO''),',
'',
'            SYS.ODCIVARCHAR2LIST(l_campos_calcular_valor_quantidade, ''PESO_LIQUIDO_TOTAL'')',
'        );',
'',
'',
'        l_atribuir_valor_item := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_item'',',
'            l_campos_item',
'        );    ',
'        ',
'',
'        l_atribuir_valor_unidademedida := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_atribuir_valor_unidademedida'',',
'            l_campos_unidademedida',
'        );',
'',
'        prc_enviar_parametros(''TD899'',''ID_ITEM'',p_param1);',
'',
'        v_executa_js_digito := ''atualizarDigitsCampo("QUANTIDADE","QTD_DECIMAIS","VALOR_INICIAL","VALOR_FINAL");'';',
'        ',
'        MERGE INTO temp_formulario tf   ',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select id_tenant from imp_pedidoimportacao whe'
||'re id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entrega'',                     2, ''HID'', null, ''N'', ''S'', p_param1 valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_ITEMM'',                       3, ''HID'',    null, ''N'', ''N'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_ITEM'',                        4, '''',    null, ''N'', ''S'', null valor, null dependencia, l_atribuir_valor_item atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_NCM'',                         6, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_UNIDADEMEDIDA'',               8, '''',    null, ''S'', ''S'', null valor, null dependencia, l_atribuir_valor_unidademedida atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''QUANTIDADE'',                    10, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, l_JSON_calcular_valor_total calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PESO_UNITARIO'',                 12, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''PESO_LIQUIDO_TOTAL'',            14, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''moeda'',                         16, ''TXT'', null, ''S'', ''N'', to_char((select codigo_moeda||'' - ''||simbolo_iso from imp_pedidoimportacao a join ng_moeda b on b.id = a.id_moeda join imp_entrega c on c.id_pedidoim'
||'portacao = a.id where c.id = p_param1)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_UNITARIO'',                18, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_DESCONTO_UNITARIO'',       20, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''VALOR_TOTAL_CONDICAO_VENDA'',    22, '''',    null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_NATUREZAOPERACAO'',           24, '''',    null, ''N'', ''S'', to_char((select id_naturezaoperacao from imp_pedidoimportacao_item where id_pedidoimportacao = p_param1 order by data_inclusao desc fetch first 1 row'
||' only)) valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ID_FABRICANTE'',                 26, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''QTD_DECIMAIS'',                  28, ''HID'', null, ''N'', ''N'', null valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''VALOR_INICIAL'',                 30, ''HID'', null, ''N'', ''N'', null valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''VALOR_FINAL'',                   32, ''HID'', null, ''N'', ''N'', null valor, null dependencia, null atribuir_valor, null calcular_valor, v_executa_js_digito executa_js FROM dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''IND_LICENCA_IMPORTACAO'',        34, '''',    null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_faturada'',           35, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_saldo'',              36, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_bruto_unitario'',           37, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_bruto_total'',              38, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_pais_origem'',                39, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_desconto_invoice_item'',   42, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesaproforma'',         43, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesaproforma_unitario'',44, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto_pedido_item_unitario'', 45, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_bloqueio_embarque_ate_deferimento_li'',          48, '''', null, ''N'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''ind_tratamento_saldo'',          46, ''HID'', null, ''S'', ''S'', null valor, null dependencia, null atribuir_valor, null calcular_valor, null executa_js FROM dual ',
'               ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, calcular_valor, executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.calcular_valor, new_data.executa_js);',
'    end formulario;',
'        ',
'    function sql_atribuir_valor_unidademedida(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~ ',
'                    select ',
'                        case ind_tipo_dado ',
'                            when ''D'' then 5',
'                        end QTD_DECIMAIS',
'                    from ng_unidademedida',
'                    where id = #ID#',
'               ~'';',
'        Return nvl(replace(l_sql,''#ID#'',p_param1),''999'');',
'    end sql_atribuir_valor_unidademedida; ',
'    ',
'    function sql_atribuir_valor_item(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'        v_id_entrega varchar2(1000) := apex_util.get_session_state(''P9010_PARAMETRO'');',
'    begin',
'        l_sql := q''~ ',
'                    select ',
'                    concatena_id_texto(c.id,c.codigo_unidademedida) ID_UNIDADEMEDIDA, ',
'                    concatena_id_texto(j.id,j.codigo_ncm)  ID_NCM,',
'                    i.quantidade_programar_entrega QUANTIDADE,',
'                    i.quantidade_programar_entrega VALOR_FINAL,',
'                    concatena_id_texto(i.id_fabricante, e.nome_fantasia) ID_FABRICANTE,',
'                    i.valor_unitario VALOR_UNITARIO,',
'                    i.valor_desconto_unitario VALOR_DESCONTO_UNITARIO,',
'                    i.peso_unitario PESO_UNITARIO,',
'                    (i.quantidade_programar_entrega * i.peso_unitario)  PESO_LIQUIDO_TOTAL,',
'                    (i.quantidade_programar_entrega * (i.valor_unitario - i.valor_desconto_unitario)) VALOR_TOTAL_CONDICAO_VENDA,',
'                    concatena_id_texto(i.id_naturezaoperacao,h.descricao) ID_NATUREZAOPERACAO,',
'                    i.ind_bloqueio_embarque_ate_deferimento_li IND_BLOQUEIO_EMBARQUE_ATE_DEFERIMENTO_LI,',
'                    i.id ID_PEDIDO_IMPORTACAO_ITEM,',
'                    a.id ID_ITEMM,',
'                    i.ind_licenca_importacao IND_LICENCA_IMPORTACAO',
'                    from ng_item                   a',
'                    join imp_pedidoimportacao_item i on i.id_item = a.id and i.id_pedidoimportacao = ( select b.id_pedidoimportacao from imp_entrega b where b.id = #ID_ENTREGA#)',
'                    join ng_item_produto           b on b.id_item = a.id',
'                    left join ng_unidademedida     c on c.id = a.id_unidademedida',
'                    left join ng_pessoa            d on d.id = i.id_fabricante',
'                    left join ng_pessoa_juridica   e on e.id_pessoa = d.id',
'                    left join ng_ncm                    j on b.id_ncm = j.id ',
'                    left join imp_naturezaoperacao      h on h.id = i.id_naturezaoperacao',
'                    where i.id = #ID# ',
'               ~'';',
'               l_sql := replace(l_sql,''#ID#'',p_param1);',
'               l_sql := replace(l_sql,''#ID_ENTREGA#'',v_id_entrega);',
'        return l_sql;',
'    end sql_atribuir_valor_item;',
'',
'    function where_dinamico(p_campo in varchar2)',
'        return clob',
'        is',
'            v_ids_itens   clob;',
'            v_id number;',
'        begin',
'',
'        v_id := APEX_UTIL.GET_SESSION_STATE(''P9010_PARAMETRO'');',
'',
'            if upper(p_campo) = ''ID_ITEM'' then',
'                return q''~',
'                    where (a.data_fim_vigencia is null ',
'                       or trunc(a.data_fim_vigencia) >= trunc(current_date))',
'                       and a.ind_tipo_item = ''P''',
'                       and y.id =  (~'' || v_id || q''~)',
'                       and i.quantidade_programar_entrega > 0',
'                ~'';',
'            else',
'                return '''';',
'            end if;',
'    end;',
'',
'    function valida(p_id in number)',
'        return pkg_mensagem.message_record_table ',
'    is',
'        l_id_entrega number := apex_util.get_session_state(''P9010_PARAMETRO'');',
'        l_id_entidade number;',
'        l_verifica_titulopagamento number;',
'        v_parametro pkg_mensagem.paramentros;',
'        v_message   pkg_mensagem.message_record;',
'        v_messages  pkg_mensagem.message_record_table;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''imp_pedidoimportacao'';        ',
'',
unistr('        -- Verifica se existem t\00EDtulos de pagamento para esta entrega:'),
'        select count(1) into l_verifica_titulopagamento',
'        from fin_titulopagamento a',
'        join imp_pedidoimportacao_pagamento b on b.id = a.id_referencia',
'        where a.id_entidade = l_id_entidade',
'        and a.ind_status_pagamento in (1,2)',
'        and b.id_entrega = l_id_entrega;',
'        ',
unistr('        -- Valida\00E7\00E3o:'),
'        if l_verifica_titulopagamento > 0 then           ',
'            v_parametro(0) := ''UI_MPD_TD_693.valida'';',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem  => ''129'',',
'                p_nome_campo       => ''valor_total_condicao_venda'',',
'                p_parametro        => v_parametro,',
'                p_pagina           => 9010,',
'                p_objeto_mensagem  => v_message',
'            );',
'            v_messages.extend;',
'            v_messages(v_messages.last) := v_message;            ',
'        end if;',
'',
'        return v_messages;',
'    end valida;',
'',
'    procedure post(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'        l_id number;                ',
'    begin        ',
'        ',
'        bo_imp_entrega_item.inclui_registro(',
'                p_id_tenant                     => apex_application.g_f01(1),',
'                p_id_entrega                    => apex_application.g_f02(1),',
'                p_id_pedidoimportacao_item      => apex_application.g_f04(1),',
'                p_id_item                       => apex_application.g_f03(1),',
'                p_id_ncm                        => apex_application.g_f06(1),',
'                p_id_unidademedida              => apex_application.g_f08(1),',
'                p_quantidade                    => pkg_util.retorna_number(apex_application.g_f10(1)),',
'                p_peso_unitario                 => pkg_util.retorna_number(apex_application.g_f12(1)),',
'                p_peso_liquido_total            => pkg_util.retorna_number(apex_application.g_f14(1)),',
'                p_valor_unitario                => pkg_util.retorna_number(apex_application.g_f18(1)),',
'                p_valor_desconto_unitario       => pkg_util.retorna_number(apex_application.g_f20(1)),',
'                p_valor_total_condicao_venda    => pkg_util.retorna_number(apex_application.g_f22(1)),',
'                p_id_naturezaoperacao           => apex_application.g_f24(1),',
'                p_id_fabricante                 => apex_application.g_f26(1),',
'                p_ind_licenca_importacao        => apex_application.g_f34(1),             ',
'                p_quantidade_faturada           => pkg_util.retorna_number(apex_application.g_f35(1)),',
'                p_quantidade_saldo              => pkg_util.retorna_number(apex_application.g_f36(1)),',
'                p_peso_bruto_unitario           => pkg_util.retorna_number(apex_application.g_f37(1)),',
'                p_peso_bruto_total              => pkg_util.retorna_number(apex_application.g_f38(1)),',
'                p_id_pais_origem                => pkg_util.retorna_number(nvl(apex_application.g_f39(1), bo_ng_pessoa.retorna_id_pais_origem(apex_application.g_f39(1)))),',
'                p_valor_total_desconto_invoice_item => pkg_util.retorna_number(apex_application.g_f42(1)),',
'                p_valor_despesaproforma          => pkg_util.retorna_number(apex_application.g_f43(1)),',
'                p_valor_despesaproforma_unitario => pkg_util.retorna_number(apex_application.g_f44(1)),',
'                p_valor_desconto_pedido_item_unitario => pkg_util.retorna_number(apex_application.g_f45(1)),',
'                p_ind_tratamento_saldo           => apex_application.g_f46(1),',
'                p_ind_bloqueio_embarque_ate_deferimento_li  => ''N'',',
'                p_valor_total_despesa_invoice_item => null,',
'                p_id => l_id, ',
'                p_sucesso => p_sucesso,',
'                p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD899";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td977
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(223372924304198334)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD977'
,p_sequence=>3250
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 09/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es na entidade fin_titulopagamento'),
'-- Jira: PEDITEM-214',
'',
'create or replace package "UI_MPD_TD977" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function label_acao return varchar2;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    ',
'end "UI_MPD_TD977";',
'/',
'',
'create or replace package body "UI_MPD_TD977" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'        l_sql  clob;',
'        l_tipo varchar2(10);',
'    begin               ',
'        l_tipo := apex_util.get_session_state(''P9010_PARAMETRO2'');',
'        if l_tipo = ''1'' then                                -- FIN_TITULOPAGAMENTO',
'            l_sql := ''',
'                select',
'                    b.nome_fantasia as id_tenant,',
'                    pkg_traducao.get_traducao(c.nome_leitura) as id_entidade,',
'                    case ',
'                        when a.id_entidade = 3829 then (select to_char(ip.numero_pedido_importacao) from imp_pedidoimportacao_pagamento ipp join imp_pedidoimportacao ip on ip.id = ipp.id_pedidoimportacao where ipp.id = a.id_pagamento)',
'                        when a.id_entidade = 4529 then (select to_char(ii.num_invoice) from imp_invoice_pagamento iip join imp_invoice ii on ii.id = iip.id_invoice where iip.id = a.id_pagamento)',
'                        when a.id_entidade = 4324 then (select to_char(ipi.num_processoimportacao) from imp_processoimportacao_despesa ipid join imp_processoimportacao ipi on ipi.id = ipid.id_processoimportacao where ipid.id = a.id_pagamento)',
'                    end as id_pagamento',
'                from fin_titulopagamento a',
'                join mpd_tenant b on b.id = a.id_tenant',
'                join srv_entidade c on c.id = a.id_entidade',
'                where a.id = ''||p_param1;',
'        elsif l_tipo = ''2'' then                             -- FIN_TITULORECEBIMENTO',
'            l_sql := ''',
'                select',
'                    b.nome_fantasia as id_tenant,',
'                    pkg_traducao.get_traducao(c.nome_leitura) as id_entidade,',
'                    case ',
'                        when a.id_entidade = 3829 then (select to_char(ip.numero_pedido_importacao) from imp_pedidoimportacao_pagamento ipp join imp_pedidoimportacao ip on ip.id = ipp.id_pedidoimportacao where ipp.id = a.id_referencia)',
'                        when a.id_entidade = 4529 then (select to_char(ii.num_invoice) from imp_invoice_pagamento iip join imp_invoice ii on ii.id = iip.id_invoice where iip.id = a.id_referencia)',
'                        when a.id_entidade = 4324 then (select to_char(ipi.num_processoimportacao) from imp_processoimportacao_despesa ipid join imp_processoimportacao ipi on ipi.id = ipid.id_processoimportacao where ipid.id = a.id_referencia)',
'                    end as id_referencia',
'                from fin_titulorecebimento a',
'                join mpd_tenant b on b.id = a.id_tenant',
'                join srv_entidade c on c.id = a.id_entidade',
'                where a.id = ''||p_param1;',
'        end if;',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => l_sql,',
'            p_tabela => case ',
'                            when l_tipo = ''1'' then textarray(''fin_titulopagamento'',''fin_titulopagamento'',''fin_titulopagamento'')',
'                            when l_tipo = ''2'' then textarray(''fin_titulorecebimento'',''fin_titulorecebimento'',''fin_titulorecebimento'')',
'                        end,',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'        l_html clob;',
'        l_id_tenant number;',
'        l_num_documento varchar2(40);',
'        l_id_fornecedor number;',
'        l_id_fornecedor_contabancaria number;',
'        l_data_vencimento date;',
'        l_id_moeda number;',
'        l_valor_titulo number;',
'        l_data_pagamento date;',
'        l_observacao varchar2(300);',
'        l_coluna_tabela varchar2(1);',
'        l_tipo number;',
'        l_prefixo_tag varchar2(100);',
'    begin   ',
'        l_html :=''</br><div class="a-CardView-headerBody" style=" display: flex; justify-content: flex-start; align-items: center; padding: 0.5rem; margin-bottom: 50px;"><h3 class="a-CardView-title">'' || retorna_texto(''msg.124.l'') || ''</h3></div>'';',
'',
'        l_tipo := apex_util.get_session_state(''P9010_PARAMETRO2'');',
'        if l_tipo = ''1'' then                                -- FIN_TITULOPAGAMENTO',
'            l_coluna_tabela := ''S'';',
'',
'            select id_tenant, id_fornecedor, id_fornecedor_contabancaria, data_vencimento, id_moeda, valor_titulo, data_pagamento, observacao',
'            into   l_id_tenant, l_id_fornecedor, l_id_fornecedor_contabancaria, l_data_vencimento, l_id_moeda, l_valor_titulo, l_data_pagamento, l_observacao',
'            from fin_titulopagamento',
'            where id = p_param1;',
'            ',
'            l_prefixo_tag := null;',
'        elsif l_tipo = ''2'' then                             -- FIN_TITULORECEBIMENTO',
'            l_coluna_tabela := ''N'';',
'',
'            select id_tenant, id_referencia, id_fornecedor, data_vencimento, id_moeda, valor_titulo, data_pagamento, observacao',
'            into   l_id_tenant, l_num_documento, l_id_fornecedor, l_data_vencimento, l_id_moeda, l_valor_titulo, l_data_pagamento, l_observacao',
'            from fin_titulorecebimento',
'            where id = p_param1;',
'            ',
'            l_id_fornecedor_contabancaria := null;',
'            l_prefixo_tag := ''FIN_TITULORECEBIMENTO.'';',
'        end if;',
'',
'',
'        MERGE INTO temp_formulario tf',
'        USING ( SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char(l_id_tenant) valor, null html, null tag_campo '
||'FROM dual UNION ALL               ',
'                SELECT p_codigo_artefato, ''num_documento'',                   3, ''TXT'', null, ''S'',l_coluna_tabela, to_char(l_num_documento) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''NUM_DOCUMENTO'' end tag_campo FROM '
||'dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_fornecedor'',                   4, ''SEL'', ''R_NG_PESSOA_JURIDICA.NOME_FANTASIA'', ''S'',l_coluna_tabela, to_char(l_id_fornecedor) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''ID'
||'_FORNECEDOR'' end tag_campo FROM dual UNION ALL',
'                -- fin_titulopagamento -> id_fornecedor_contabancaria:',
'                SELECT p_codigo_artefato, ''id_fornecedor_contabancaria'',     6, ''SEL'', ''R_NG_PESSOA_CONTABANCARIA.DESCRICAO_CONTA_BANCARIA'', ''S'',l_coluna_tabela, to_char(l_id_fornecedor_contabancaria) valor, null html, null tag_campo FROM dual WHERE '
||'l_tipo = 1 UNION ALL',
'                SELECT p_codigo_artefato, ''data_vencimento'',                 8, ''TXT'', null, ''S'',l_coluna_tabela, to_char(l_data_vencimento) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''DATA_VENCIMENTO'' end tag_campo F'
||'ROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''id_moeda'',                        9, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''S'',l_coluna_tabela, to_char(l_id_moeda) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''ID_MOE'
||'DA'' end tag_campo FROM dual UNION ALL',
'                SELECT p_codigo_artefato, ''valor_titulo'',                   11, ''TXT'', null, ''S'',l_coluna_tabela, to_char(l_valor_titulo) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''VALOR_TITULO'' end tag_campo FROM du'
||'al UNION ALL',
'                SELECT p_codigo_artefato, ''data_pagamento'',                 12, ''DAT'', null, ''N'',l_coluna_tabela, to_char(l_data_pagamento) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''DATA_PAGAMENTO'' end tag_campo FRO'
||'M dual UNION ALL',
'                SELECT p_codigo_artefato, ''observacao'',                     14, ''TEX'', null, ''N'',l_coluna_tabela, to_char(l_observacao) valor, null html, case when l_prefixo_tag is not null then l_prefixo_tag || ''OBSERVACAO'' end tag_campo FROM dual U'
||'NION ALL    ',
'                SELECT p_codigo_artefato, ''coluna_mensagem'',                99, ''HTM'', null, ''S'', ''N'', null valor, l_html html, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,html,tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.html, new_data.tag_campo);    ',
'    end formulario;',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is ',
'        l_id number;',
'        l_tipo varchar2(10);',
'    begin               ',
'        l_tipo := apex_util.get_session_state(''P9010_PARAMETRO2'');',
'',
'        if l_tipo = ''1'' then                                -- FIN_TITULOPAGAMENTO',
'            bo_fin_titulopagamento.confirma_pagamento_titulo(',
'                p_id                        => p_id,',
'                p_data_pagamento            => apex_application.g_f12(1),',
'                p_observacao                => apex_application.g_f14(1),',
'                p_sucesso                   => p_sucesso,',
'                p_messages                  => p_messages',
'            );',
'        elsif l_tipo = ''2'' then                             -- FIN_TITULORECEBIMENTO',
'            bo_fin_titulorecebimento.confirma_pagamento_titulo(',
'                p_id                        => p_id,',
'                p_data_pagamento            => apex_application.g_f12(1),',
'                p_observacao                => apex_application.g_f14(1),',
'                p_sucesso                   => p_sucesso,',
'                p_messages                  => p_messages',
'            );',
'        end if;',
'    end;',
'',
'end "UI_MPD_TD977";',
'/'))
);
end;
