'         -- Verifica valor unico composto',
'        if v_new.id is not null then',
'            select count(1) into l_verifica_valor_unico from imp_declaracaoimportacao_cotacao where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_declaracaoimportacao)) = lower(trim(v_new.id_declaracaoimportacao)) and lower('
||'trim(id_moeda)) = lower(trim(v_new.id_moeda)) and id <> v_new.id;',
'        else',
'            select count(1) into l_verifica_valor_unico from imp_declaracaoimportacao_cotacao where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(id_declaracaoimportacao)) = lower(trim(v_new.id_declaracaoimportacao)) and lower('
||'trim(id_moeda)) = lower(trim(v_new.id_moeda));',
'        end if;',
'        if l_verifica_valor_unico > 0 then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_declaracaoimportacao_cotacao.id_moeda'');',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''id_moeda'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;',
'',
'        hook_valida_id_moeda(p_id_moeda);',
'    end valida_id_moeda;',
'',
'    procedure valida_taxa_cambio(p_taxa_cambio in imp_declaracaoimportacao_cotacao.taxa_cambio%type)',
'    is',
'        l_verifica_valor_unico number;',
'    begin',
'        if p_taxa_cambio is null then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_declaracaoimportacao_cotacao.taxa_cambio'');',
'        --Verifica formato se houver',
'        end if;',
unistr('        --Verifica valor \00FAnico se houver'),
'        hook_valida_taxa_cambio(p_taxa_cambio);',
'    end valida_taxa_cambio;',
'',
