'',
'    procedure recalcula_e_atualiza_processo(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao number;',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao',
'          from imp_declaracaoimportacao',
'         where id = v_new.id_declaracaoimportacao;',
'',
'        bo_imp_processoimportacao.recalcula_tributos(',
'            p_id        => l_id_processoimportacao,',
'            p_encadeado => true,',
'            p_sucesso   => p_sucesso,',
'            p_messages  => p_messages',
'        );',
'        if p_messages.count > 0 then',
'            v_messages := p_messages;',
'            return;',
'        end if;',
'',
'        bo_imp_processoimportacao.atualiza_valores_processo(',
'            p_id        => l_id_processoimportacao,',
'            p_encadeado => true,',
'            p_sucesso   => p_sucesso,',
'            p_messages  => p_messages',
'        );',
'        if p_messages.count > 0 then',
'            v_messages := p_messages;',
'        end if;',
'    end recalcula_e_atualiza_processo;',
'',
'    procedure atualiza_processo(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao      number;',
'        l_proc                       imp_processoimportacao%rowtype;',
'        l_valor_total_mercadoria     number := 0;',
'        l_valor_total_condicao_venda number := 0;',
'        l_vmle       number := 0; l_vmld       number := 0;',
'        l_frete      number := 0; l_seguro  number := 0;',
'        l_multa      number := 0; l_antidumping number := 0;',
'        l_valor_ii   number := 0; l_valor_ipi  number := 0;',
'        l_valor_pis  number := 0; l_valor_cofins number := 0;',
'        l_valor_icms number := 0; l_valor_icms_st number := 0;',
'        l_valor_cbs  number := 0; l_valor_ibs  number := 0;',
'',
'        function soma_despesa(p_tipo number, p_realizado boolean default false) return number is',
'            l_val number := 0;',
'        begin',
'            if p_realizado then',
'                select nvl(sum(ipd.valor_realizado * nvl(dc.taxa_cambio, 1)), 0) into l_val',
'                  from imp_processoimportacao_despesa ipd',
'                  join ng_despesa nd on nd.id = ipd.id_despesa',
'                  left join imp_declaracaoimportacao_cotacao dc',
'                         on dc.id_declaracaoimportacao = v_new.id_declaracaoimportacao',
'                        and dc.id_moeda               = ipd.id_moeda_realizada',
'                 where ipd.id_processoimportacao = l_id_processoimportacao',
'                   and nd.ind_tipo_despesa = p_tipo;',
'            else',
'                select nvl(sum(ipd.valor_previsto * nvl(dc.taxa_cambio, 1)), 0) into l_val',
'                  from imp_processoimportacao_despesa ipd',
'                  join ng_despesa nd on nd.id = ipd.id_despesa',
'                  left join imp_declaracaoimportacao_cotacao dc',
'                         on dc.id_declaracaoimportacao = v_new.id_declaracaoimportacao',
'                        and dc.id_moeda               = ipd.id_moeda_prevista',
'                 where ipd.id_processoimportacao = l_id_processoimportacao',
'                   and nd.ind_tipo_despesa = p_tipo;',
'            end if;',
'            return l_val;',
'        end soma_despesa;',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao',
'          from imp_declaracaoimportacao',
'         where id = v_new.id_declaracaoimportacao;',
'',
unistr('        -- valor_total_mercadoria e condicao_venda: itens \00D7 taxa DI'),
'        select nvl(sum(pi.valor_total_mercadoria     * nvl(dc.taxa_cambio, 1)), 0),',
'               nvl(sum(pi.valor_total_condicao_venda * nvl(dc.taxa_cambio, 1)), 0)',
'          into l_valor_total_mercadoria,',
'               l_valor_total_condicao_venda',
'          from imp_processoimportacao_item pi',
'          left join imp_declaracaoimportacao_cotacao dc',
'                 on dc.id_declaracaoimportacao = v_new.id_declaracaoimportacao',
'                and dc.id_moeda               = pi.id_moeda',
'         where pi.id_processoimportacao = l_id_processoimportacao;',
'',
unistr('        -- vmle e vmld: valores calculados (n\00E3o despesas), somados de item_tributo j\00E1 preenchido'),
'        select nvl(sum(t.vmle), 0), nvl(sum(t.vmld), 0)',
'          into l_vmle, l_vmld',
'          from imp_processoimportacao_item_tributo t',
'          join imp_processoimportacao_item pi on pi.id = t.id_processoimportacao_item',
'         where pi.id_processoimportacao = l_id_processoimportacao;',
'',
'        -- frete(9), seguro(10), multa(17), antidumping(8): soma de imp_processoimportacao_despesa',
'        l_frete       := soma_despesa(9);',
'        l_seguro      := soma_despesa(10);',
'        l_multa       := soma_despesa(17);',
'        l_antidumping := soma_despesa(8);',
'',
'        -- tributos: soma de imp_processoimportacao_despesa pelo tipo',
'        l_valor_ii      := soma_despesa(1,  true);   -- II realizado',
'        l_valor_ipi     := soma_despesa(2);',
'        l_valor_pis     := soma_despesa(3);',
'        l_valor_cofins  := soma_despesa(4);',
'        l_valor_icms    := soma_despesa(5);',
'        l_valor_icms_st := soma_despesa(6);',
'        l_valor_cbs     := soma_despesa(18);',
'        l_valor_ibs     := soma_despesa(19);',
'',
'        select * into l_proc from imp_processoimportacao where id = l_id_processoimportacao;',
'',
'        bo_imp_processoimportacao.altera_valores(',
'            p_valor_total_mercadoria     => l_valor_total_mercadoria,',
'            p_valor_desconto             => l_proc.valor_desconto,',
'            p_valor_total_condicao_venda => l_valor_total_condicao_venda,',
'            p_frete                      => l_frete,',
'            p_seguro                     => l_seguro,',
'            p_acrescimo                  => l_proc.acrescimo,',
'            p_multa                      => l_multa,',
'            p_antidumping                => l_antidumping,',
'            p_vmle                       => l_vmle,',
'            p_vmld                       => l_vmld,',
'            p_valor_ii                   => l_valor_ii,',
'            p_valor_ipi                  => l_valor_ipi,',
'            p_valor_pis                  => l_valor_pis,',
'            p_valor_cofins               => l_valor_cofins,',
'            p_valor_icms                 => l_valor_icms,',
'            p_valor_icms_st              => l_valor_icms_st,',
'            p_valor_cbs                  => l_valor_cbs,',
'            p_valor_ibs                  => l_valor_ibs,',
'            p_id                         => l_id_processoimportacao,',
'            p_encadeado                  => true,',
'            p_sucesso                    => p_sucesso,',
'            p_messages                   => p_messages',
'        );',
'    end atualiza_processo;',
'',
'    procedure hook_depois_incluir(p_encadeado in boolean default false, p_sucesso out clob, p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        if v_operacao = ''cria_registro_e_recalcula_processo'' then',
'            atualiza_item_tributo(p_sucesso, p_messages);',
'            if p_messages.count > 0 then return; end if;',
'            atualiza_item_despesa_tributo(p_sucesso, p_messages);',
'            if p_messages.count > 0 then return; end if;',
'            atualiza_despesa_processo_tributo(p_sucesso, p_messages);',
'            if p_messages.count > 0 then return; end if;',
'            atualiza_processo(p_sucesso, p_messages);',
'        end if;',
'    end hook_depois_incluir;',
'',
'    procedure hook_depois_alterar(p_encadeado in boolean default false, p_sucesso out clob, p_messages out pkg_mensagem.message_record_table) is',
'    begin',
'        if v_operacao = ''cria_registro_e_recalcula_processo'' then',
'            atualiza_item_tributo(p_sucesso, p_messages);',
'            if p_messages.count > 0 then return; end if;',
'            atualiza_item_despesa_tributo(p_sucesso, p_messages);',
'            if p_messages.count > 0 then return; end if;',
'            atualiza_despesa_processo_tributo(p_sucesso, p_messages);',
'            if p_messages.count > 0 then return; end if;',
'            atualiza_processo(p_sucesso, p_messages);',
'        end if;',
'    end hook_depois_alterar;',
'',
'    function detalhe_registro(',
'        p_id in ng_cidade.id%type',
'    ) return varchar2 is',
'    begin',
'        return (',
'            pkg_util.ObterValoresDasColunas(',
'                p_consulta_sql => ''',
'                    select a.num_processoimportacao,',
'                           b.numero_duimp,',
'                           bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador',
'                      from imp_processoimportacao a',
'                      join imp_declaracaoimportacao b on b.id_processoimportacao = a.id',
'                      join imp_declaracaoimportacao_cotacao c on c.id_declaracaoimportacao = b.id',
'                     where c.id = ''||p_id,',
'                p_tabela      => textarray(''imp_processoimportacao'',''imp_declaracaoimportacao'',''imp_processoimportacao''),',
'                p_formato     => ''pequeno'',',
'                p_tipo_label  => ''coluna'',',
'                p_classe      => ''st-back-transparente''',
'            )',
'            || pkg_ui.campos_detalhes(q''~',
'                select (b.codigo_moeda|| '' - '' || b.simbolo_iso) imp_declaracaoimportacao_cotacao$id_moeda',
'                  from imp_declaracaoimportacao_cotacao a',
'                  join ng_moeda b on b.id = a.id_moeda',
'                 where a.id = ~'' || p_id)',
'            ||''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''',
'            || retorna_texto(''msg.189.l'')',
'            ||''</h3></div></h3></div>''',
'        );',
'    end detalhe_registro;',
'',
'    procedure cria_registro_e_recalcula_processo(',
'        p_json_taxa_cambio        clob,',
'        p_id_declaracaoimportacao in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type,',
'        p_pagina                  in number default 0,',
'        p_encadeado               in boolean default false,',
'        p_sucesso                 out clob,',
'        p_messages                out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao  number;',
'        l_id_tenant              number;',
'        l_id_cotacao             number;',
'        l_taxa_zero              number;',
'        l_id_cotacao_existente   number;',
'        l_data_alteracao_existente imp_declaracaoimportacao_cotacao.data_alteracao%type;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_pagina   := p_pagina;',
'        v_operacao := ''cria_registro_e_recalcula_processo'';',
'        execute immediate ''alter session set nls_date_format = ''''DD/MM/YYYY'''''';',
'',
'        select id_processoimportacao, id_tenant',
'          into l_id_processoimportacao, l_id_tenant',
'          from imp_declaracaoimportacao',
'         where id = p_id_declaracaoimportacao;',
'',
'        -- 1. Valida: nenhuma taxa pode ser 0',
'        select count(1) into l_taxa_zero',
'          from json_table(p_json_taxa_cambio, ''$[*]'' columns valor varchar2(50) path ''$.valor'') j',
'         where nvl(to_number(replace(j.valor, '','', ''.''), ''FM9999990.9999999999'', ''NLS_NUMERIC_CHARACTERS=''''.,''''''), 0) = 0;',
'',
'        if l_taxa_zero > 0 then',
'            v_parametro(1) := '''';',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => 187,',
'                p_nome_campo => ''data_disponivel_informada'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'            p_messages := v_messages;',
'            pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'            return;',
'        end if;',
'',
'        for taxa in (',
'            select to_number(j.id_moeda) id_moeda,',
'                   to_number(replace(j.valor, '','', ''.''), ''FM9999990.9999999999'', ''NLS_NUMERIC_CHARACTERS=''''.,'''''') taxa_cambio',
'              from json_table(p_json_taxa_cambio, ''$[*]''',
'                    columns id_moeda varchar2(50) path ''$.id'',',
'                            valor    varchar2(50) path ''$.valor'') j',
'        ) loop',
'            begin',
'                select id, data_alteracao',
'                  into l_id_cotacao_existente, l_data_alteracao_existente',
'                  from imp_declaracaoimportacao_cotacao',
'                 where id_declaracaoimportacao = p_id_declaracaoimportacao',
'                   and id_moeda               = taxa.id_moeda;',
'',
'                altera_registro(',
'                    p_id_tenant               => l_id_tenant,',
'                    p_id_declaracaoimportacao => p_id_declaracaoimportacao,',
'                    p_id_moeda                => taxa.id_moeda,',
'                    p_taxa_cambio             => taxa.taxa_cambio,',
'                    p_id                      => l_id_cotacao_existente,',
'                    p_data_alteracao          => l_data_alteracao_existente,',
'                    p_pagina                  => p_pagina,',
'                    p_encadeado               => true,',
'                    p_sucesso                 => p_sucesso,',
'                    p_messages                => p_messages',
'                );',
unistr('            -- no caso se n\00E3o existir ai ele inclui...'),
'            exception',
'                when no_data_found then',
'                    inclui_registro(',
'                        p_id_tenant               => l_id_tenant,',
'                        p_id_declaracaoimportacao => p_id_declaracaoimportacao,',
'                        p_id_moeda                => taxa.id_moeda,',
'                        p_taxa_cambio             => taxa.taxa_cambio,',
'                        p_id                      => l_id_cotacao,',
'                        p_pagina                  => p_pagina,',
'                        p_encadeado               => true,',
'                        p_sucesso                 => p_sucesso,',
'                        p_messages                => p_messages',
'                    );',
'            end;',
unistr('            -- valida o v_message porque mesmo que de erro ai o loop continua...ent\00E3o o encadeado cai aqui'),
'            if v_messages.count > 0 then',
'                v_operacao := null;',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages, p_encadeado);',
'                return;',
'            end if;',
'        end loop;',
'',
'        declare',
'            l_suc clob;',
'            l_msg pkg_mensagem.message_record_table;',
'        begin',
'            bo_imp_processoimportacao.altera_ind_calculando_valores(',
'                p_ind_calculando_valores   => ''N'',',
'                p_data_hora_ultimo_calculo => sysdate,',
'                p_id                       => l_id_processoimportacao,',
'                p_encadeado                => false,',
'                p_sucesso                  => l_suc,',
'                p_messages                 => l_msg',
'            );',
'        end;',
'',
'        v_operacao := null;',
'        p_messages := v_messages;',
'        if v_messages.count = 0 then',
'            pkg_mensagem.mensagem_operacao(',
'                p_operacao  => pkg_mensagem.c_operacao_sucesso_incluir,',
'                p_parametro => v_parametro,',
'                p_mensagem  => p_sucesso',
'            );',
'        end if;',
'',
'    end cria_registro_e_recalcula_processo;',
'',
'    function calcula_desp_base_item_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_ind_despesa_base_calculo   in ng_despesa.ind_despesa_base_calculo%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_previstas  number;',
'        l_realizadas number;',
'    begin',
'        select nvl(sum(nvl(a.valor_total_despesa_previsto_item, 0)), 0)',
'          into l_previstas',
'          from imp_processoimportacao_item_despesa a',
'          left join imp_processoimportacao_despesa b on b.id = a.id_processoimportacao_despesa',
'          left join ng_despesa c on c.id = b.id_despesa',
'         where a.id_processoimportacao_item = p_id_processoimportacao_item',
'           and b.ind_status_despesa = 1',
'           and '':'' || c.ind_despesa_base_calculo || '':'' like ''%:'' || p_ind_despesa_base_calculo || '':%'';',
'',
'        select nvl(sum(nvl(a.valor_total_despesa_realizado_item, 0) * nvl(dc.taxa_cambio, 1)), 0)',
'          into l_realizadas',
'          from imp_processoimportacao_item_despesa a',
'          left join imp_processoimportacao_despesa b on b.id = a.id_processoimportacao_despesa',
'          left join ng_despesa c on c.id = b.id_despesa',
'          left join imp_declaracaoimportacao_cotacao dc',
'                 on dc.id_declaracaoimportacao = p_id_declaracaoimportacao',
'                and dc.id_moeda               = a.id_moeda_despesa_realizada',
'         where a.id_processoimportacao_item = p_id_processoimportacao_item',
'           and b.ind_status_despesa = 2',
'           and '':'' || c.ind_despesa_base_calculo || '':'' like ''%:'' || p_ind_despesa_base_calculo || '':%'';',
'',
'        return trunc(l_previstas + l_realizadas, 5);',
'    exception',
'        when others then return 0;',
'    end calcula_desp_base_item_di;',
'',
'    function calcula_vmle_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_valor_cond_venda  imp_processoimportacao_item.valor_total_condicao_venda%type;',
'        l_id_moeda          imp_processoimportacao_item.id_moeda%type;',
'        l_id_incoterm       imp_processoimportacao_item.id_incoterm%type;',
'        l_taxa_cambio       imp_declaracaoimportacao_cotacao.taxa_cambio%type;',
'        l_resp_frete        ng_incoterm.ind_responsavel_frete%type;',
'        l_resp_seguro       ng_incoterm.ind_responsavel_seguro%type;',
'        l_resp_desp_origem  ng_incoterm.ind_responsavel_despesa_origem%type;',
'        l_valor             number;',
'    begin',
'        select valor_total_condicao_venda, id_moeda, id_incoterm',
'          into l_va'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(227618349396422390)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'lor_cond_venda, l_id_moeda, l_id_incoterm',
'          from imp_processoimportacao_item',
'         where id = p_id_processoimportacao_item;',
'',
'        begin',
'            select taxa_cambio into l_taxa_cambio',
'              from imp_declaracaoimportacao_cotacao',
'             where id_declaracaoimportacao = p_id_declaracaoimportacao',
'               and id_moeda               = l_id_moeda;',
'        exception',
'            when no_data_found then l_taxa_cambio := 1;',
'        end;',
'',
'        l_valor := trunc(nvl(l_valor_cond_venda, 0) * l_taxa_cambio, 5);',
'',
'        -- Aplica incoterm: subtrai despesas de frete (ind_base 10) e/ou seguro (ind_base 9)',
unistr('        -- quando a responsabilidade \00E9 do exportador (''e'')'),
'        select lower(ind_responsavel_frete),',
'               lower(ind_responsavel_seguro),',
'               lower(ind_responsavel_despesa_origem)',
'          into l_resp_frete, l_resp_seguro, l_resp_desp_origem',
'          from ng_incoterm',
'         where id = l_id_incoterm;',
'',
'        if l_resp_frete = ''e'' then',
'            l_valor := l_valor - calcula_desp_base_item_di(p_id_processoimportacao_item, 10, p_id_declaracaoimportacao);',
'        end if;',
'        if l_resp_seguro = ''e'' then',
'            l_valor := l_valor - calcula_desp_base_item_di(p_id_processoimportacao_item, 9, p_id_declaracaoimportacao);',
'        end if;',
'',
'        return trunc(l_valor, 5);',
'    exception',
'        when others then return 0;',
'    end calcula_vmle_di;',
'',
'    function calcula_vmld_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'    begin',
'        return trunc(calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                     + calcula_desp_base_item_di(p_id_processoimportacao_item, 10, p_id_declaracaoimportacao), 5);',
'    exception',
'        when others then return 0;',
'    end calcula_vmld_di;',
'',
'    function retorna_base_calculo_ii_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'    begin',
'        return trunc(calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                     + calcula_desp_base_item_di(p_id_processoimportacao_item, 1, p_id_declaracaoimportacao), 5);',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_ii_di;',
'',
'    function retorna_base_calculo_ipi_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao       varchar2(1);',
'        l_percentual_reducao  number;',
'        l_base_ii             number;',
'        l_aliq_ii             number;',
'        l_base                number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_ipi), nvl(percentual_reducao_base_ipi, 0)',
'          into l_ind_aplicacao, l_percentual_reducao',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        l_base_ii := retorna_base_calculo_ii_di(p_id_processoimportacao_item, p_id_declaracaoimportacao);',
'        l_aliq_ii := nvl(bo_imp_processoimportacao_item_tributo.retorna_aliquota_ii(p_id_processoimportacao_item), 0);',
'        -- base IPI = base II + valor II (lei brasileira: IPI incide sobre valor aduaneiro + II)',
'        l_base := l_base_ii + trunc(l_base_ii * l_aliq_ii / 100, 2);',
'        if    l_ind_aplicacao in (''1'',''2'',''4'') then return trunc(l_base, 5);',
'        elsif l_ind_aplicacao = ''3''            then return trunc(l_base * (1 - l_percentual_reducao/100), 5);',
'        else                                        return 0;',
'        end if;',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_ipi_di;',
'',
'    function retorna_base_calculo_pis_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao       varchar2(1);',
'        l_percentual_reducao  number;',
'        l_base                number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_pis_cofins), nvl(percentual_reducao_base_pis_cofins, 0)',
'          into l_ind_aplicacao, l_percentual_reducao',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        l_base := calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                  + calcula_desp_base_item_di(p_id_processoimportacao_item, 3, p_id_declaracaoimportacao);',
'        if    l_ind_aplicacao in (''1'',''2'',''4'') then return trunc(l_base, 2);',
'        elsif l_ind_aplicacao = ''3''            then return trunc(l_base * (1 - l_percentual_reducao/100), 2);',
'        else                                        return 0;',
'        end if;',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_pis_di;',
'',
'    function retorna_base_calculo_cofins_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao       varchar2(1);',
'        l_percentual_reducao  number;',
'        l_base                number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_pis_cofins), nvl(percentual_reducao_base_pis_cofins, 0)',
'          into l_ind_aplicacao, l_percentual_reducao',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        l_base := calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                  + calcula_desp_base_item_di(p_id_processoimportacao_item, 4, p_id_declaracaoimportacao);',
'        if    l_ind_aplicacao in (''1'',''2'',''4'') then return trunc(l_base, 2);',
'        elsif l_ind_aplicacao = ''3''            then return trunc(l_base * (1 - l_percentual_reducao/100), 2);',
'        else                                        return 0;',
'        end if;',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_cofins_di;',
'',
'    function retorna_base_calculo_cbs_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao       number;',
'        l_percentual_reducao  number;',
'        l_base                number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select ind_aplicacao_cbs, nvl(percentual_reducao_base_cbs, 0)',
'          into l_ind_aplicacao, l_percentual_reducao',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        l_base := calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                  + calcula_desp_base_item_di(p_id_processoimportacao_item, 18, p_id_declaracaoimportacao);',
'        if    l_ind_aplicacao in (1,2,4) then return trunc(l_base, 2);',
'        elsif l_ind_aplicacao = 3        then return trunc(l_base * (1 - l_percentual_reducao/100), 2);',
'        else                                  return 0;',
'        end if;',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_cbs_di;',
'',
'    function retorna_base_calculo_ibs_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao       number;',
'        l_percentual_reducao  number;',
'        l_base                number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select ind_aplicacao_ibs, nvl(percentual_reducao_base_ibs, 0)',
'          into l_ind_aplicacao, l_percentual_reducao',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        l_base := calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                  + calcula_desp_base_item_di(p_id_processoimportacao_item, 19, p_id_declaracaoimportacao);',
'        if    l_ind_aplicacao in (1,2,4) then return trunc(l_base, 2);',
'        elsif l_ind_aplicacao = 3        then return trunc(l_base * (1 - l_percentual_reducao/100), 2);',
'        else                                  return 0;',
'        end if;',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_ibs_di;',
'',
'    function retorna_base_calculo_icms_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_ind_aplicacao       varchar2(1);',
'        l_ind_ipi_suspenso    varchar2(1);',
'        l_ind_integra_propria varchar2(1);',
'        l_percentual_reducao  number;',
'        l_aliq_icms           number;',
'        l_base                number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select lower(ind_aplicacao_icms), lower(ind_ipi_suspenso_base_icms),',
'               lower(ind_integra_propria_base_icms), nvl(percentual_reducao_base_icms, 0)',
'          into l_ind_aplicacao, l_ind_ipi_suspenso, l_ind_integra_propria, l_percentual_reducao',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        l_base      := calcula_vmle_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                       + calcula_desp_base_item_di(p_id_processoimportacao_item, 5, p_id_declaracaoimportacao);',
'        l_aliq_icms := bo_imp_processoimportacao_item_tributo.retorna_aliquota_icms(p_id_processoimportacao_item);',
'        if    l_ind_aplicacao in (''1'',''2'',''4'') and l_ind_ipi_suspenso = ''n'' and l_ind_integra_propria = ''n'' then',
'            return trunc(l_base, 2);',
'        elsif l_ind_aplicacao in (''1'',''2'',''4'') and l_ind_ipi_suspenso = ''n'' and l_ind_integra_propria = ''s'' then',
'            return trunc(l_base / (1 - l_aliq_icms / 100), 2);',
'        elsif l_ind_aplicacao in (''1'',''2'',''4'') and l_ind_ipi_suspenso = ''s'' and l_ind_integra_propria = ''n'' then',
'            return trunc(l_base - trunc(retorna_base_calculo_ipi_di(p_id_processoimportacao_item, p_id_declaracaoimportacao) * nvl(bo_imp_processoimportacao_item_tributo.retorna_aliquota_ipi(p_id_processoimportacao_item), 0) / 100, 2), 2);',
'        elsif l_ind_aplicacao in (''1'',''2'',''4'') and l_ind_ipi_suspenso = ''s'' and l_ind_integra_propria = ''s'' then',
'            return trunc((l_base - trunc(retorna_base_calculo_ipi_di(p_id_processoimportacao_item, p_id_declaracaoimportacao) * nvl(bo_imp_processoimportacao_item_tributo.retorna_aliquota_ipi(p_id_processoimportacao_item), 0) / 100, 2)) / (1 - l_aliq'
||'_icms / 100), 2);',
'        elsif l_ind_aplicacao = ''3'' then',
'            return trunc(l_base * (1 - l_percentual_reducao / 100), 2);',
'        else',
'            return 0;',
'        end if;',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_icms_di;',
'',
'    function retorna_base_calculo_icms_st_di(',
'        p_id_processoimportacao_item in imp_processoimportacao_item.id%type,',
'        p_id_declaracaoimportacao    in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type',
'    ) return number is',
'        l_id_naturezaoperacao number;',
'        l_percentual_mva      number;',
'    begin',
'        select id_naturezaoperacao into l_id_naturezaoperacao',
'          from imp_processoimportacao_item where id = p_id_processoimportacao_item;',
'        select nvl(percentual_mva_icms_st, 0) into l_percentual_mva',
'          from imp_naturezaoperacao_tributo where id_naturezaoperacao = l_id_naturezaoperacao;',
'        return trunc(retorna_base_calculo_icms_di(p_id_processoimportacao_item, p_id_declaracaoimportacao)',
'                     * (l_percentual_mva / 100), 2);',
'    exception',
'        when others then return 0;',
'    end retorna_base_calculo_icms_st_di;',
'',
'    procedure atualiza_item_despesa_tributo(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        type t_vals is table of number index by pls_integer;',
'',
'        l_id_processoimportacao number;',
'        l_id_tenant             number;',
'        l_id_moeda              number;',
'',
'        l_item_ids    t_vals;',
'        l_item_qtds   t_vals;',
'        l_val_ii      t_vals; l_val_ipi  t_vals; l_val_pis     t_vals; l_val_cofins  t_vals;',
'        l_val_icms    t_vals; l_val_icms_st t_vals; l_val_cbs  t_vals; l_val_ibs     t_vals;',
'',
'        l_total_ii      number := 0; l_total_ipi     number := 0;',
'        l_total_pis     number := 0; l_total_cofins  number := 0;',
'        l_total_icms    number := 0; l_total_icms_st number := 0;',
'        l_total_cbs     number := 0; l_total_ibs     number := 0;',
'',
'        idx           pls_integer := 0;',
'        l_trib        imp_processoimportacao_item_tributo%rowtype;',
'        l_ng_desp     ng_despesa%rowtype;',
'        l_desp        imp_processoimportacao_despesa%rowtype;',
'        l_desp_id     number;',
'        l_id_out      number;',
'        l_idsp_id     number;',
'        l_idsp_dt     date;',
'',
'        -- p_realizado = true: gravar em valor_realizado (II); false: valor_previsto (demais)',
'        procedure processa_despesa_pai(p_ind_tipo number, p_total number, p_realizado boolean default false) is',
'            l_val_prev number; l_val_real number;',
'        begin',
'            begin',
'                select * into l_ng_desp from ng_despesa',
'                 where ind_tipo_despesa = p_ind_tipo and rownum = 1;',
'            exception when no_data_found then l_desp_id := null; return; end;',
'',
'            begin',
'                select ipd.id into l_desp_id',
'                  from imp_processoimportacao_despesa ipd',
'                  join ng_despesa nd on nd.id = ipd.id_despesa',
'                 where ipd.id_processoimportacao = l_id_processoimportacao',
'                   and nd.ind_tipo_despesa = p_ind_tipo;',
'            exception when no_data_found then l_desp_id := null; end;',
'',
'            if p_realizado then l_val_prev := 0;       l_val_real := p_total;',
'            else               l_val_prev := p_total;  l_val_real := 0;',
'            end if;',
'',
'            if l_desp_id is null then',
'                l_id_out := null;',
'                bo_imp_processoimportacao_despesa.v_operacao := ''COTACAO'';',
'                bo_imp_processoimportacao_despesa.inclui_registro(',
'                    p_id_tenant                  => l_id_tenant,',
'                    p_id_documento_despesa       => null,',
'                    p_id_processoimportacao      => l_id_processoimportacao,',
'                    p_id_numerario_despesa       => null, --?',
'                    p_id_despesa                 => l_ng_desp.id,',
'                    p_id_moeda_prevista          => l_id_moeda,',
'                    p_valor_previsto             => l_val_prev,',
'                    p_id_moeda_realizada         => l_id_moeda,',
'                    p_valor_realizado            => l_val_real,',
'                    p_taxa_cambio                => 1,',
'                    p_ind_status_despesa         => 1,',
'                    p_ind_status_pagamento       => 1,',
'                    p_id_moeda_documento         => l_id_moeda,',
'                    p_valor_moeda_documento      => 0,',
'                    p_valor_moeda_nacional       => 0,',
'                    p_ind_forma_rateio           => l_ng_desp.ind_forma_rateio,',
'                    p_ind_compoe_custo_operacao  => l_ng_desp.ind_compoe_custo_operacao,',
'                    p_ind_participa_nfe          => l_ng_desp.ind_participa_nfe,',
'                    p_ind_despesa_base_calculo   => l_ng_desp.ind_despesa_base_calculo,',
'                    p_ind_tipo_despesa           => l_ng_desp.ind_tipo_despesa,',
'                    p_id                         => l_id_out,',
'                    p_encadeado                  => true,',
'                    p_sucesso                    => p_sucesso,',
'                    p_messages                   => p_messages',
'                );',
'                l_desp_id := l_id_out;',
'            else',
'                select * into l_desp from imp_processoimportacao_despesa where id = l_desp_id;',
'                bo_imp_processoimportacao_despesa.v_operacao := ''COTACAO'';',
'                bo_imp_processoimportacao_despesa.altera_registro(',
'                    p_id_tenant                  => l_desp.id_tenant,',
'                    p_id_documento_despesa       => l_desp.id_documento_despesa,',
'                    p_id_processoimportacao      => l_desp.id_processoimportacao,',
'                    p_id_numerario_despesa       => l_desp.id_numerario_despesa, --?',
'                    p_id_despesa                 => l_desp.id_despesa,',
'                    p_id_moeda_prevista          => l_desp.id_moeda_prevista,',
'                    p_valor_previsto             => l_val_prev,',
'                    p_id_moeda_realizada         => l_desp.id_moeda_realizada,',
'                    p_valor_realizado            => l_val_real,',
'                    p_taxa_cambio                => 1,',
'                    p_ind_status_despesa         => l_desp.ind_status_despesa,',
'                    p_ind_status_pagamento       => l_desp.ind_status_pagamento,',
'                    p_id_moeda_documento         => l_desp.id_moeda_documento,',
'                    p_valor_moeda_documento      => l_desp.valor_moeda_documento,',
'                    p_valor_moeda_nacional       => l_desp.valor_moeda_nacional,',
'                    p_ind_forma_rateio           => l_desp.ind_forma_rateio,',
'                    p_ind_compoe_custo_operacao  => l_desp.ind_compoe_custo_operacao,',
'                    p_ind_participa_nfe          => l_desp.ind_participa_nfe,',
'                    p_ind_despesa_base_calculo   => l_desp.ind_despesa_base_calculo,',
'                    p_ind_tipo_despesa           => l_desp.ind_tipo_despesa,',
'                    p_id                         => l_desp_id,',
'                    p_data_alteracao             => l_desp.data_alteracao,',
'                    p_encadeado                  => true,',
'                    p_sucesso                    => p_sucesso,',
'                    p_messages                   => p_messages',
'                );',
'            end if;',
'        end processa_despesa_pai;',
'',
'        procedure processa_item_despesa(p_idx pls_integer, p_valor number, p_realizado boolean default false) is',
'            l_prev number; l_real number;',
'            l_id_despesa number;',
'        begin',
'            if l_desp_id is null then return; end if;',
'            begin',
'                select id_despesa into l_id_despesa from imp_processoimportacao_despesa where id = l_desp_id;',
'                select id, data_alteracao into l_idsp_id, l_idsp_dt',
'                  from imp_processoimportacao_item_despesa',
'                 where id_processoimportacao_item    = l_item_ids(p_idx)',
'                   and id_processoimportacao_despesa = l_desp_id;',
'            exception when no_data_found then l_idsp_id := null; end;',
'',
'            if p_realizado then l_prev := 0;        l_real := p_valor;',
'            else               l_prev := p_valor;   l_real := 0;',
'            end if;',
'',
'            if l_idsp_id is null then',
'                l_id_out := null;',
'                bo_imp_processoimportacao_item_despesa.inclui_registro(',
'                    p_id_tenant => l_id_tenant,',
'                    p_id_processoimportacao_item => l_item_ids(p_idx),',
'                    p_id_processoimportacao_despesa => l_desp_id,',
'                    p_id_despesa => l_id_despesa,',
'                    p_id_moeda_despesa_prevista => l_id_moeda,',
'                    p_valor_total_despesa_previsto_item     => l_prev,',
'                    p_valor_unitario_despesa_previsto_item  => trunc(l_prev / l_item_qtds(p_idx), 2),',
'                    p_id_moeda_despesa_realizada => l_id_moeda,',
'                    p_valor_total_despesa_realizado_item    => l_real,',
'                    p_valor_unitario_despesa_realizado_item => trunc(l_real / l_item_qtds(p_idx), 2),',
'                    p_valor_total_despesa_moeda_nacional    => 0,',
'                    p_valor_unitario_despesa_moeda_nacional => 0,',
'                    p_id => l_id_out, p_encadeado => true,',
'                    p_sucesso => p_sucesso, p_messages => p_messages',
'                );',
'            else',
'                bo_imp_processoimportacao_item_despesa.altera_registro(',
'                    p_id_tenant => l_id_tenant,',
'                    p_id_processoimportacao_item => l_item_ids(p_idx),',
'                    p_id_processoimportacao_despesa => l_desp_id,',
'                    p_id_despesa => l_id_despesa,',
'                    p_id_moeda_despesa_prevista => l_id_moeda,',
'                    p_valor_total_despesa_previsto_item     => l_prev,',
'                    p_valor_unitario_despesa_previsto_item  => trunc(l_prev / l_item_qtds(p_idx), 2),',
'                    p_id_moeda_despesa_realizada => l_id_moeda,',
'                    p_valor_total_despesa_realizado_item    => l_real,',
'                    p_valor_unitario_despesa_realizado_item => trunc(l_real / l_item_qtds(p_idx), 2),',
'                    p_valor_total_despesa_moeda_nacional    => 0,',
'                    p_valor_unitario_despesa_moeda_nacional => 0,',
'                    p_id => l_idsp_id, p_data_alteracao => l_idsp_dt,',
'                    p_encadeado => true, p_sucesso => p_sucesso, p_messages => p_messages',
'                );',
'            end if;',
'        end processa_item_despesa;',
'',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao',
'          from imp_declaracaoimportacao where id = v_new.id_declaracaoimportacao;',
'        select id_tenant into l_id_tenant from imp_processoimportacao where id = l_id_processoimportacao;',
'        l_id_moeda := bo_mpd_configuracao_ng.retorna_id_moeda_tenant(l_id_tenant);',
'',
unistr('        -- Pass 1: l\00EA de imp_processoimportacao_item_tributo (j\00E1 populado por atualiza_item_tributo)'),
'        for item in (select pi.id, nvl(pi.quantidade, 1) as quantidade',
'                       from imp_processoimportacao_item pi',
'                      where pi.id_processoimportacao = l_id_processoimportacao) loop',
'            idx := idx + 1;',
'            l_item_ids(idx)  := item.id;',
'            l_item_qtds(idx) := item.quantidade;',
'',
'            select * into l_trib',
'              from imp_processoimportacao_item_tributo',
'             where id_processoimportacao_item = item.id;',
'',
'            l_val_ii(idx)      := trunc(nvl(l_trib.base_calculo_ii,      0) * nvl(l_trib.aliquota_ii,     0) / 100, 2);',
'            l_val_ipi(idx)     := trunc(nvl(l_trib.base_calculo_ipi,     0) * nvl(l_trib.aliquota_ipi,    0) / 100, 2);',
'            l_val_pis(idx)     := trunc(nvl(l_trib.base_calculo_pis,     0) * nvl(l_trib.aliquota_pis,    0) / 100, 2);',
'            l_val_cofins(idx)  := trunc(nvl(l_trib.base_calculo_cofins,  0) * nvl(l_trib.aliquota_cofins, 0) / 100, 2);',
'            l_val_icms(idx)    := trunc(nvl(l_trib.base_calculo_icms,    0) * nvl(l_trib.aliquota_icms,   0) / 100, 2);',
'            l_val_icms_st(idx) := trunc(nvl(l_trib.base_calculo_icms_st, 0) * nvl(l_trib.aliquota_icms,   0) / 100, 2);',
'            l_val_cbs(idx)     := trunc(nvl(l_trib.base_calculo_cbs,     0) * nvl(l_trib.aliquota_cbs,    0) / 100, 2);',
'            l_val_ibs(idx)     := trunc(nvl(l_trib.base_calculo_ibs,     0) * nvl(l_trib.aliquota_ibs,    0) / 100, 2);',
'',
'            l_total_ii      := l_total_ii      + nvl(l_val_ii(idx), 0);',
'            l_total_ipi     := l_total_ipi     + nvl(l_val_ipi(idx), 0);',
'            l_total_pis     := l_total_pis     + nvl(l_val_pis(idx), 0);',
'            l_total_cofins  := l_total_cofins  + nvl(l_val_cofins(idx), 0);',
'            l_total_icms    := l_total_icms    + nvl(l_val_icms(idx), 0);',
'            l_total_icms_st := l_total_icms_st + nvl(l_val_icms_st(idx), 0);',
'            l_total_cbs     := l_total_cbs     + nvl(l_val_cbs(idx), 0);',
'            l_total_ibs     := l_total_ibs     + nvl(l_val_ibs(idx), 0);',
'        end loop;',
'',
'        -- Pass 2: cria/altera despesa pai e item_despesas para cada tipo',
unistr('        -- II (1) \2014 realizado'),
'        processa_despesa_pai(1, l_total_ii, true);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_ii(i), true); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- IPI (2)',
'        processa_despesa_pai(2, l_total_ipi);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_ipi(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- PIS (3)',
'        processa_despesa_pai(3, l_total_pis);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_pis(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- COFINS (4)',
'        processa_despesa_pai(4, l_total_cofins);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_cofins(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- ICMS (5)',
'        processa_despesa_pai(5, l_total_icms);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_icms(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- ICMS-ST (6)',
'        processa_despesa_pai(6, l_total_icms_st);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_icms_st(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- CBS (18)',
'        processa_despesa_pai(18, l_total_cbs);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_cbs(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'        -- IBS (19)',
'        processa_despesa_pai(19, l_total_ibs);',
'        if p_messages.count > 0 then return; end if;',
'        for i in 1..idx loop processa_item_despesa(i, l_val_ibs(i)); if p_messages.count > 0 then return; end if; end loop;',
'',
'    end atualiza_item_despesa_tributo;',
'',
'    -- Regra 6: soma item_despesas de cada tributo e atualiza imp_processoimportacao_despesa pai',
'    procedure atualiza_despesa_processo_tributo(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        type t_tipo_list is table of number;',
'        l_tipos               t_tipo_list := t_tipo_list(1, 2, 3, 4, 5, 6, 18, 19);',
'        l_id_processoimportacao number;',
'        l_desp                imp_processoimportacao_despesa%rowtype;',
'        l_total               number;',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao',
'          from imp_declaracaoimportacao',
'         where id = v_new.id_declaracaoimportacao;',
'',
'        for i in 1..l_tipos.count loop',
'            l_desp.id := null;',
'            begin',
'                select ipd.* into l_desp',
'                  from imp_processoimportacao_despesa ipd',
'                  join ng_despesa nd on nd.id = ipd.id_despesa',
'                 where ipd.id_processoimportacao = l_id_processoimportacao',
'                   and nd.ind_tipo_despesa = l_tipos(i);',
'            exception when no_data_found then null; end;',
'',
'            if l_desp.id is null then continue; end if;',
'',
'            -- II (1) usa realizado; demais usam previsto',
'            if l_tipos(i) = 1 then',
'                select nvl(sum(valor_total_despesa_realizado_item), 0) into l_total',
'                  from imp_processoimportacao_item_despesa',
'                 where id_processoimportacao_despesa = l_desp.id;',
'',
'                bo_imp_processoimportacao_despesa.v_operacao := ''COTACAO'';',
'                bo_imp_processoimportacao_despesa.altera_registro(',
'                    p_id_tenant                  => l_desp.id_tenant,',
'                    p_id_documento_despesa       => l_desp.id_documento_despesa,',
'                    p_id_processoimportacao      => l_desp.id_processoimportacao,',
'                    p_id_numerario_despesa       => l_desp.id_numerario_despesa, --?',
'                    p_id_despesa                 => l_desp.id_despesa,',
'                    p_id_moeda_prevista          => l_desp.id_moeda_prevista,',
'                    p_valor_previsto             => 0,',
'                    p_id_moeda_realizada         => l_desp.id_moeda_realizada,',
'                    p_valor_realizado            => l_total,',
'                    p_taxa_cambio                => 1,',
'                    p_ind_status_despesa         => l_desp.ind_status_despesa,',
'                    p_ind_status_pagamento '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(227618349396422390)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'      => l_desp.ind_status_pagamento,',
'                    p_id_moeda_documento         => l_desp.id_moeda_documento,',
'                    p_valor_moeda_documento      => l_desp.valor_moeda_documento,',
'                    p_valor_moeda_nacional       => l_desp.valor_moeda_nacional,',
'                    p_ind_forma_rateio           => l_desp.ind_forma_rateio,',
'                    p_ind_compoe_custo_operacao  => l_desp.ind_compoe_custo_operacao,',
'                    p_ind_participa_nfe          => l_desp.ind_participa_nfe,',
'                    p_ind_despesa_base_calculo   => l_desp.ind_despesa_base_calculo,',
'                    p_ind_tipo_despesa           => l_desp.ind_tipo_despesa,',
'                    p_id                         => l_desp.id,',
'                    p_data_alteracao             => l_desp.data_alteracao,',
'                    p_encadeado                  => true,',
'                    p_sucesso                    => p_sucesso,',
'                    p_messages                   => p_messages',
'                );',
'            else',
'                select nvl(sum(valor_total_despesa_previsto_item), 0) into l_total',
'                  from imp_processoimportacao_item_despesa',
'                 where id_processoimportacao_despesa = l_desp.id;',
'',
'                bo_imp_processoimportacao_despesa.v_operacao := ''COTACAO'';',
'                bo_imp_processoimportacao_despesa.altera_registro(',
'                    p_id_tenant                  => l_desp.id_tenant,',
'                    p_id_documento_despesa       => l_desp.id_documento_despesa,',
'                    p_id_processoimportacao      => l_desp.id_processoimportacao,',
'                    p_id_numerario_despesa       => l_desp.id_numerario_despesa, --?',
'                    p_id_despesa                 => l_desp.id_despesa,',
'                    p_id_moeda_prevista          => l_desp.id_moeda_prevista,',
'                    p_valor_previsto             => l_total,',
'                    p_id_moeda_realizada         => l_desp.id_moeda_realizada,',
'                    p_valor_realizado            => 0,',
'                    p_taxa_cambio                => 1,',
'                    p_ind_status_despesa         => l_desp.ind_status_despesa,',
'                    p_ind_status_pagamento       => l_desp.ind_status_pagamento,',
'                    p_id_moeda_documento         => l_desp.id_moeda_documento,',
'                    p_valor_moeda_documento      => l_desp.valor_moeda_documento,',
'                    p_valor_moeda_nacional       => l_desp.valor_moeda_nacional,',
'                    p_ind_forma_rateio           => l_desp.ind_forma_rateio,',
'                    p_ind_compoe_custo_operacao  => l_desp.ind_compoe_custo_operacao,',
'                    p_ind_participa_nfe          => l_desp.ind_participa_nfe,',
'                    p_ind_despesa_base_calculo   => l_desp.ind_despesa_base_calculo,',
'                    p_ind_tipo_despesa           => l_desp.ind_tipo_despesa,',
'                    p_id                         => l_desp.id,',
'                    p_data_alteracao             => l_desp.data_alteracao,',
'                    p_encadeado                  => true,',
'                    p_sucesso                    => p_sucesso,',
'                    p_messages                   => p_messages',
'                );',
'            end if;',
'            if p_messages.count > 0 then return; end if;',
'        end loop;',
'    end atualiza_despesa_processo_tributo;',
'',
'    procedure atualiza_item_tributo(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao number;',
'        l_trib                  imp_processoimportacao_item_tributo%rowtype;',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao',
'          from imp_declaracaoimportacao',
'         where id = v_new.id_declaracaoimportacao;',
'',
'        for item in (',
'            select pi.id',
'              from imp_processoimportacao_item pi',
'             where pi.id_processoimportacao = l_id_processoimportacao',
'        ) loop',
'            select * into l_trib',
'              from imp_processoimportacao_item_tributo',
'             where id_processoimportacao_item = item.id;',
'',
'            bo_imp_processoimportacao_item_tributo.altera_registro(',
'                p_id_tenant                  => l_trib.id_tenant,',
'                p_id_processoimportacao_item => l_trib.id_processoimportacao_item,',
'                p_vmle                       => calcula_vmle_di(item.id, v_new.id_declaracaoimportacao),',
'                p_vmld                       => calcula_vmld_di(item.id, v_new.id_declaracaoimportacao),',
'                p_base_calculo_ii            => retorna_base_calculo_ii_di(item.id, v_new.id_declaracaoimportacao),',
'                p_aliquota_ii                => bo_imp_processoimportacao_item_tributo.retorna_aliquota_ii(item.id),',
'                p_base_calculo_ipi           => retorna_base_calculo_ipi_di(item.id, v_new.id_declaracaoimportacao),',
'                p_aliquota_ipi               => bo_imp_processoimportacao_item_tributo.retorna_aliquota_ipi(item.id),',
'                p_aliquota_pis               => bo_imp_processoimportacao_item_tributo.retorna_aliquota_pis(item.id),',
'                p_aliquota_cofins            => bo_imp_processoimportacao_item_tributo.retorna_aliquota_cofins(item.id),',
'                p_base_calculo_icms          => retorna_base_calculo_icms_di(item.id, v_new.id_declaracaoimportacao),',
'                p_base_calculo_icms_st       => retorna_base_calculo_icms_st_di(item.id, v_new.id_declaracaoimportacao),',
'                p_aliquota_icms              => bo_imp_processoimportacao_item_tributo.retorna_aliquota_icms(item.id),',
'                p_base_calculo_cbs           => retorna_base_calculo_cbs_di(item.id, v_new.id_declaracaoimportacao),',
'                p_aliquota_cbs               => bo_imp_processoimportacao_item_tributo.retorna_aliquota_cbs(item.id),',
'                p_base_calculo_ibs           => retorna_base_calculo_ibs_di(item.id, v_new.id_declaracaoimportacao),',
'                p_aliquota_ibs               => bo_imp_processoimportacao_item_tributo.retorna_aliquota_ibs(item.id),',
'                p_base_calculo_pis           => retorna_base_calculo_pis_di(item.id, v_new.id_declaracaoimportacao),',
'                p_base_calculo_cofins        => retorna_base_calculo_cofins_di(item.id, v_new.id_declaracaoimportacao),',
'                p_id                         => l_trib.id,',
'                p_data_alteracao             => l_trib.data_alteracao,',
'                p_encadeado                  => true,',
'                p_sucesso                    => p_sucesso,',
'                p_messages                   => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'        end loop;',
'    end atualiza_item_tributo;',
'',
'    procedure atualiza_despesa(',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao number;',
'        l_desp                  imp_processoimportacao_despesa%rowtype;',
'        l_item_desp             imp_processoimportacao_item_despesa%rowtype;',
'        l_taxa_cambio           number;',
'    begin',
'        select id_processoimportacao into l_id_processoimportacao',
'          from imp_declaracaoimportacao',
'         where id = v_new.id_declaracaoimportacao;',
'',
'        for desp in (',
'            select ipd.id',
'              from imp_processoimportacao_despesa ipd',
'              join ng_despesa nd on nd.id = ipd.id_despesa',
'             where ipd.id_processoimportacao = l_id_processoimportacao',
'               and nd.ind_tipo_despesa not in (1, 2, 3, 4, 5, 6, 18, 19)',
'        ) loop',
'            select * into l_desp',
'              from imp_processoimportacao_despesa',
'             where id = desp.id;',
'',
unistr('            -- taxa DI para a moeda desta despesa; sem cota\00E7\00E3o mant\00E9m a existente'),
'            begin',
'                select taxa_cambio into l_taxa_cambio',
'                  from imp_declaracaoimportacao_cotacao',
'                 where id_declaracaoimportacao = v_new.id_declaracaoimportacao',
'                   and id_moeda               = l_desp.id_moeda_realizada;',
'            exception',
'                when no_data_found then l_taxa_cambio := l_desp.taxa_cambio;',
'            end;',
'',
'            bo_imp_processoimportacao_despesa.v_operacao := ''COTACAO'';',
'            bo_imp_processoimportacao_despesa.altera_registro(',
'                p_id_tenant                  => l_desp.id_tenant,',
'                p_id_documento_despesa       => l_desp.id_documento_despesa,',
'                p_id_processoimportacao      => l_desp.id_processoimportacao,',
'                p_id_numerario_despesa       => l_desp.id_numerario_despesa, --?',
'                p_id_despesa                 => l_desp.id_despesa,',
'                p_id_moeda_prevista          => l_desp.id_moeda_prevista,',
'                p_valor_previsto             => l_desp.valor_previsto,',
'                p_id_moeda_realizada         => l_desp.id_moeda_realizada,',
'                p_valor_realizado            => l_desp.valor_realizado,',
'                p_taxa_cambio                => l_taxa_cambio,',
'                p_ind_status_despesa         => l_desp.ind_status_despesa,',
'                p_ind_status_pagamento       => l_desp.ind_status_pagamento,',
'                p_id_moeda_documento         => l_desp.id_moeda_documento,',
'                p_valor_moeda_documento      => l_desp.valor_moeda_documento,',
'                p_valor_moeda_nacional       => l_desp.valor_moeda_nacional,',
'                p_ind_forma_rateio           => l_desp.ind_forma_rateio,',
'                p_ind_compoe_custo_operacao  => l_desp.ind_compoe_custo_operacao,',
'                p_ind_participa_nfe          => l_desp.ind_participa_nfe,',
'                p_ind_despesa_base_calculo   => l_desp.ind_despesa_base_calculo,',
'                p_ind_tipo_despesa           => l_desp.ind_tipo_despesa,',
'                p_id                         => l_desp.id,',
'                p_data_alteracao             => l_desp.data_alteracao,',
'                p_encadeado                  => true,',
'                p_sucesso                    => p_sucesso,',
'                p_messages                   => p_messages',
'            );',
'            if p_messages.count > 0 then return; end if;',
'',
'            -- atualiza rateio nos itens com a nova taxa',
'            for item_desp in (',
'                select id',
'                  from imp_processoimportacao_item_despesa',
'                 where id_processoimportacao_despesa = l_desp.id',
'            ) loop',
'                select * into l_item_desp',
'                  from imp_processoimportacao_item_despesa',
'                 where id = item_desp.id;',
'',
'                bo_imp_processoimportacao_item_despesa.altera_registro(',
'                    p_id_tenant                             => l_item_desp.id_tenant,',
'                    p_id_processoimportacao_item            => l_item_desp.id_processoimportacao_item,',
'                    p_id_processoimportacao_despesa         => l_item_desp.id_processoimportacao_despesa,',
'                    p_id_despesa                            => l_item_desp.id_despesa,',
'                    p_id_moeda_despesa_prevista             => l_item_desp.id_moeda_despesa_prevista,',
'                    p_valor_total_despesa_previsto_item     => bo_imp_processoimportacao_item_despesa.calcula_rateio(',
'                        nvl(l_desp.valor_previsto, 0) * l_taxa_cambio,',
'                        l_item_desp.id_processoimportacao_item,',
'                        l_item_desp.id_processoimportacao_despesa',
'                    ),',
'                    p_valor_unitario_despesa_previsto_item  => bo_imp_processoimportacao_item_despesa.calcula_rateio_unitario(',
'                        nvl(l_desp.valor_previsto, 0) * l_taxa_cambio,',
'                        l_item_desp.id_processoimportacao_item,',
'                        l_item_desp.id_processoimportacao_despesa',
'                    ),',
'                    p_id_moeda_despesa_realizada            => l_item_desp.id_moeda_despesa_realizada,',
'                    p_valor_total_despesa_realizado_item    => bo_imp_processoimportacao_item_despesa.calcula_rateio(',
'                        nvl(l_desp.valor_realizado, 0) * l_taxa_cambio,',
'                        l_item_desp.id_processoimportacao_item,',
'                        l_item_desp.id_processoimportacao_despesa',
'                    ),',
'                    p_valor_unitario_despesa_realizado_item => bo_imp_processoimportacao_item_despesa.calcula_rateio_unitario(',
'                        nvl(l_desp.valor_realizado, 0) * l_taxa_cambio,',
'                        l_item_desp.id_processoimportacao_item,',
'                        l_item_desp.id_processoimportacao_despesa',
'                    ),',
'                    p_valor_total_despesa_moeda_nacional    => l_item_desp.valor_total_despesa_moeda_nacional,',
'                    p_valor_unitario_despesa_moeda_nacional => l_item_desp.valor_unitario_despesa_moeda_nacional,',
'                    p_id                                    => l_item_desp.id,',
'                    p_data_alteracao                        => l_item_desp.data_alteracao,',
'                    p_encadeado                             => true,',
'                    p_sucesso                               => p_sucesso,',
'                    p_messages                              => p_messages',
'                );',
'                if p_messages.count > 0 then return; end if;',
'            end loop;',
'        end loop;',
'    end atualiza_despesa;',
'',
'    procedure posta_recalculo_di(',
'        p_json_taxa_cambio        in clob,',
'        p_id_declaracaoimportacao in imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type,',
'        p_sucesso                 out clob,',
'        p_messages                out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_processoimportacao number;',
'        l_id_tenant             number;',
'        l_id_req                number;',
'    begin',
'        v_messages := pkg_mensagem.message_record_table();',
'',
'        select a.id_processoimportacao, a.id_tenant',
'          into l_id_processoimportacao, l_id_tenant',
'          from imp_declaracaoimportacao a',
'         where a.id = p_id_declaracaoimportacao;',
'',
'        declare',
'            l_suc clob;',
'            l_msg pkg_mensagem.message_record_table;',
'        begin',
'            bo_imp_processoimportacao.altera_ind_calculando_valores(',
'                p_ind_calculando_valores   => ''S'',',
'                p_data_hora_ultimo_calculo => null,',
'                p_id                       => l_id_processoimportacao,',
'                p_encadeado                => false,',
'                p_sucesso                  => l_suc,',
'                p_messages                 => l_msg',
'            );',
'            if l_msg.count > 0 then',
'                p_messages := l_msg;',
'                return;',
'            end if;',
'        end;',
'        l_id_req := pkg_maestro_api.postar_requisicao(',
'            p_codigo_artefato => ''PR9'',',
'            p_id_tenant       => l_id_tenant,',
'            p_id_usuario      => pkg_util.retorna_id_usuario_logado,',
'            p_id_negocio      => p_id_declaracaoimportacao,',
'            p_payload         => ''{"id_declaracaoimportacao":'' || p_id_declaracaoimportacao',
'                              || '',"json_taxa_cambio":'' || p_json_taxa_cambio || ''}'',',
'            p_prioridade      => 0,',
'            p_tipo_acao       => ''BO_IMP_DI_COTACAO.posta_recalculo_di'',',
'            p_id_correlation  => null',
'        );',
'',
'        -- l_id := pkg_maestro_api.postar_requisicao(',
'        --             p_codigo_artefato => ''PR3'', --altera_valor_desconto_invoice_item',
'        --             p_id_tenant       => v_old.id_tenant,',
'        --             p_id_usuario      => v_old.id_usuario_alterou,',
'        --             p_id_negocio      => v_old.id,',
'        --             p_payload         => ''{"id_invoice":"''||v_new.id||''"}'',',
'        --             p_prioridade      => 0,',
'        --             p_tipo_acao       => ''Origem: BO_IMP_INVOICE.hook_depois_alterar'',',
'        --             p_id_correlation  => null',
'        --         );',
'',
'        pkg_mensagem.mensagem_operacao(',
'            p_operacao  => pkg_mensagem.c_operacao_sucesso_alterar,',
'            p_parametro => v_parametro,',
'            p_mensagem  => p_sucesso',
'        );',
'        exception',
'    when others then',
'        v_parametro(1) := sqlerrm;',
'        pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'        v_messages.extend;',
'        v_messages(v_messages.last) := v_message;',
'        p_messages := v_messages;',
'end posta_recalculo_di;',
'',
'    -- exception',
'    --     when others then',
'    --         v_parametro(1) := sqlerrm;',
'    --         pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'    --         v_messages.extend;',
'    --         v_messages(v_messages.last) := v_message;',
'    --         p_messages := v_messages;',
'',
'',
'    --<CUSTOMIZADO_FIM>',
'',
'end bo_imp_declaracaoimportacao_cotacao;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td875
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(227620994940434316)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD875'
,p_sequence=>3270
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD875" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'',
'end "UI_MPD_TD875";',
'/',
'',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD875" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'        v_id_processoimportacao number;',
'    begin',
'        v_id_processoimportacao := NVL(p_param2, p_param1);',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''',''''ind_status'''',a.ind_status) ind_status,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_embarcador) id_embarcador,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_importador) id_importador,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_adquirente) id_adquirente',
'                from imp_processoimportacao a',
'                left join imp_declaracaoimportacao b on b.id_processoimportacao = a.id',
'                where a.id =''||v_id_processoimportacao,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao'',''imp_processoimportacao''),',
'        p_formato => ''pequeno'',                ',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title"></h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        v_valor_uf number;',
'        v_id_processoimportacao number := null;',
'    begin ',
'        if p_param1 is null then',
'            SELECT MAX(b.id_unidade_federativa)',
'              INTO v_valor_uf',
'              FROM imp_processoimportacao a',
'                   JOIN ng_recinto_alfandegado b',
'                     ON b.id = a.id_recinto_alfandegado',
'            WHERE a.id = p_param2;',
'            v_id_processoimportacao := p_param2;',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao,null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char((select a.id_tenant from imp_processoimportacao '
||'a  where a.id = p_param2)) valor, null dependencia, null atribuir_valor, null executa_js from dual UNION ALL    ',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',               4, ''HID'', null, ''N'', ''N'', to_char(v_id_processoimportacao), null , null , null  from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''numero_duimp'',                        6, ''TXT'', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL  ',
'               SELECT p_codigo_artefato, ''data_registro'',                       8, ''DAT'', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_uf_nacionalizacao'',                10,'''', null, ''N'', ''S'', to_char(v_valor_uf), null , null , null  from dual UNION ALL',
'               SELECT p_codigo_artefato, ''peso_liquido_carga'',                  12,'''', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_acondicionamento_carga'',           14,'''', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL',
'               SELECT p_codigo_artefato, ''volume'',                              16,'''', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id'',                                  40, ''HID'', null, ''N'', ''S'', null, null , null , null  from dual UNION ALL      ',
'               SELECT p_codigo_artefato, ''data_alteracao'',                      45, ''HID'', null, ''N'', ''S'', null, null , null , null  from dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, new_'
||'data.executa_js);',
'    end formulario;',
'',
'',
'    procedure post_create(',
'        p_id      out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_declaracaoimportacao.inclui_registro(',
'            p_informacao_complementar   => null,',
'            p_id_tenant                 => pkg_util.retorna_number(apex_application.g_f02(1)),',
'            p_id_processoimportacao     => pkg_util.retorna_number(apex_application.g_f04(1)),',
'            p_numero_duimp              => apex_application.g_f06(1),',
'            p_data_registro             => TO_DATE(apex_application.g_f08(1), ''DD/MM/YYYY''),',
'            p_ind_canal_parametrizado   => null,',
'            p_id_pais_procedencia_carga => null,',
'            p_id_urf_entrada_carga      => null,',
'            p_id_uf_nacionalizacao      => pkg_util.retorna_number(apex_application.g_f10(1)),',
'            p_peso_liquido_carga        => pkg_util.retorna_number(apex_application.g_f12(1)),',
'            p_peso_bruto_carga          => null,',
'            p_volume                    => pkg_util.retorna_number(apex_application.g_f16(1)),',
'            p_id_acondicionamento_carga => pkg_util.retorna_number(apex_application.g_f14(1)),',
'            p_ind_status                => 1,',
'            p_id                        => p_id,',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id       in  number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        v_rec imp_declaracaoimportacao%rowtype;',
'    begin',
'        select * into v_rec from imp_declaracaoimportacao where id = p_id;',
'        bo_imp_declaracaoimportacao.altera_registro(',
'            p_informacao_complementar   => v_rec.informacao_complementar,',
'            p_id_tenant                 => v_rec.id_tenant,',
'            p_id_processoimportacao     => v_rec.id_processoimportacao,',
'            p_numero_duimp              => apex_application.g_f06(1),',
'            p_data_registro             => TO_DATE(apex_application.g_f08(1), ''DD/MM/YYYY''),',
'            p_ind_canal_parametrizado   => v_rec.ind_canal_parametrizado,',
'            p_id_pais_procedencia_carga => v_rec.id_pais_procedencia_carga,',
'            p_id_urf_entrada_carga      => v_rec.id_urf_entrada_carga,',
'            p_id_uf_nacionalizacao      => pkg_util.retorna_number(apex_application.g_f10(1)),',
'            p_peso_liquido_carga        => pkg_util.retorna_number(apex_application.g_f12(1)),',
'            p_peso_bruto_carga          => v_rec.peso_bruto_carga,',
'            p_volume                    => pkg_util.retorna_number(apex_application.g_f16(1)),',
'            p_id_acondicionamento_carga => pkg_util.retorna_number(apex_application.g_f14(1)),',
'            p_id                        => p_id,',
'            p_ind_status                => 1,',
'            p_data_alteracao            => TO_TIMESTAMP(apex_application.g_f45(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end post_save;',
'',
'end "UI_MPD_TD875";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td1070
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(227621195751439512)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1070'
,p_sequence=>3280
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1070" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'',
'end "UI_MPD_TD1070";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD1070" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
