||'ll atribuir_valor, null executa_js from dual UNION ALL    ',
'                   SELECT p_codigo_artefato, ''id_processoimportacao'',               4, ''HID'', null, ''N'', ''N'', to_char(v_new.id_processoimportacao), null , null , null  from dual UNION ALL  ',
'                   SELECT p_codigo_artefato, ''numero_duimp'',                        6, ''TXT'', null, ''N'', ''S'', to_char(v_new.numero_duimp), null , null , null  from dual UNION ALL  ',
'                   SELECT p_codigo_artefato, ''data_registro'',                       8, ''DAT'', null, ''N'', ''S'', to_char(v_new.data_registro), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_uf_nacionalizacao'',                10,'''', null, ''N'', ''S'', to_char(v_new.id_uf_nacionalizacao), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''peso_liquido_carga'',                  12,'''', null, ''N'', ''S'', to_char(v_new.peso_liquido_carga), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_acondicionamento_carga'',           14,'''', null, ''N'', ''S'', to_char(v_new.id_acondicionamento_carga), null , null , null  from dual UNION ALL',
