'                   SELECT p_codigo_artefato, ''id'',                                  40, ''HID'', null, ''N'', ''S'', to_char(v_new.id), null , null , null  from dual UNION ALL      ',
'                   SELECT p_codigo_artefato, ''data_alteracao'',                      45, ''HID'', null, ''N'', ''S'', null, null , null , null  from dual ',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
'                INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor, dependencia,atribuir_valor,executa_js)',
'                VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.dependencia, new_data.atribuir_valor, '
||'new_data.executa_js);',
'',
'        else',
'        ',
'        select * into v_new from imp_declaracaoimportacao where id = p_param1;',
'            ',
'            MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''HID'' AS tipo_interacao,null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, to_char(v_new.id_tenant) valor, null dependencia, nu'
||'ll atribuir_valor, null executa_js from dual UNION ALL    ',
'                   SELECT p_codigo_artefato, ''id_processoimportacao'',               4, ''HID'', null, ''N'', ''N'', to_char(v_new.id_processoimportacao), null , null , null  from dual UNION ALL  ',
'                   SELECT p_codigo_artefato, ''numero_duimp'',                        6, ''TXT'', null, ''N'', ''S'', to_char(v_new.numero_duimp), null , null , null  from dual UNION ALL  ',
'                   SELECT p_codigo_artefato, ''data_registro'',                       8, ''DAT'', null, ''N'', ''S'', to_char(v_new.data_registro), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_uf_nacionalizacao'',                10,'''', null, ''N'', ''S'', to_char(v_new.id_uf_nacionalizacao), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''peso_liquido_carga'',                  12,'''', null, ''N'', ''S'', to_char(v_new.peso_liquido_carga), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_acondicionamento_carga'',           14,'''', null, ''N'', ''S'', to_char(v_new.id_acondicionamento_carga), null , null , null  from dual UNION ALL',
'                   SELECT p_codigo_artefato, ''volume'',                              16,'''', null, ''N'', ''S'', to_char(v_new.volume), null , null , null  from dual UNION ALL               ',
'                   SELECT p_codigo_artefato, ''id'',                                  40, ''HID'', null, ''N'', ''S'', to_char(v_new.id), null , null , null  from dual UNION ALL      ',
'                   SELECT p_codigo_artefato, ''data_alteracao'',                      45, ''HID'', null, ''N'', ''S'', null, null , null , null  from dual ',
'                   ) new_data',
unistr('            ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'            WHEN NOT MATCHED THEN',
