'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD1055" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'        v_id_processoimportacao number;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao num_processoimportacao,',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao'''',''''ind_status'''',a.ind_status) ind_status,',
'                    b.numero_duimp  numero_duimp,',
'                    pkg_util.dominio_retorna_tag(''''imp_declaracaoimportacao'''',''''ind_canal_parametrizado'''',b.ind_canal_parametrizado) ind_canal_parametrizado',
'                from imp_processoimportacao a',
'                left join imp_declaracaoimportacao b on b.id_processoimportacao = a.id',
'                where b.id =''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao'',''imp_declaracaoimportacao'',''imp_declaracaoimportacao''),',
'        p_formato => ''pequeno'',',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.284.l'')||''</h3></div>''||''</h3></div>'';',
'',
'        return l_html;',
'    end;',
'',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        v_valor_uf number;',
'        v_id_processoimportacao number;',
'        v_new imp_processoimportacao%rowtype;',
'        l_html clob;',
'    begin',
'',
'        select a.* into v_new from imp_processoimportacao a join imp_declaracaoimportacao b on b.id_processoimportacao = a.id where b.id = p_param1;',
'',
'        if v_new.ind_calculando_valores = ''S'' then',
'            l_html :=',
'                ''<div style="display:flex;justify-content:end;margin-right:3rem;margin-bottom:0.5rem">',
'                    <span style="color:#d32f2f;font-weight:bold;">''|| pkg_ui.retorna_label_tela(''recalculando'') ||''</span>',
'                </div>'';',
'        else',
'            l_html := null;',
'        end if;',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''col1'' AS nome_coluna, 1 AS indice, ''HTM'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''N'' as coluna_tabela, null valor, null dependencia, null atribuir_valor, null exec'
||'uta_js, l_html html from dual UNION ALL',
'               SELECT p_codigo_artefato AS codigo_artefato, ''id'' AS nome_coluna, 2 AS indice, '''' AS tipo_interacao,null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, p_param1 valor, null dependencia, null atribuir_valor, null execut'
||'a_js, null html from dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_tenant'',  4, '''', null, ''S'', ''S'', to_char(v_new.id_moeda_tenant),  null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''vmle'',             6, '''', null, ''S'', ''S'', to_char(v_new.vmle),             null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''vmld'',             8, '''', null, ''S'', ''S'', to_char(v_new.vmld),             null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_ii'',        10, '''', null, ''S'', ''S'', to_char(v_new.valor_ii),         null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_ipi'',       12, '''', null, ''S'', ''S'', to_char(v_new.valor_ipi),        null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_pis'',       14, '''', null, ''S'', ''S'', to_char(v_new.valor_pis),        null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_cofins'',    16, '''', null, ''S'', ''S'', to_char(v_new.valor_cofins),     null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_cbs'',       18, '''', null, ''S'', ''S'', to_char(v_new.valor_cbs),        null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_ibs'',       20, '''', null, ''S'', ''S'', to_char(v_new.valor_ibs),        null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_icms'',      22, '''', null, ''S'', ''S'', to_char(v_new.valor_icms),       null, null, null, null from dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_icms_st'',   24, '''', null, ''S'', ''S'', to_char(v_new.valor_icms_st),    null, null, null, null from dual',
'               ) new_data',
'        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)',
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, dependencia, atribuir_valor, executa_js, html)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.dependencia, new_data.atribuir_valor, new'
||'_data.executa_js, new_data.html);',
'    end formulario;',
'',
'    function sql_auto_refresh(',
'        p_modo_refresh in varchar2 default ''ONCE'',',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null,',
'        p_param4 in varchar2 default null',
'    ) return clob',
'    is',
'        l_modo_refresh varchar2(30);',
'    begin',
'        l_modo_refresh := upper(nvl(p_modo_refresh, ''ONCE''));',
'',
'        return q''~',
'            select case',
'                when exists (',
'                    select 1',
'                      from imp_processoimportacao p',
'                      join imp_declaracaoimportacao d on d.id_processoimportacao = p.id',
'                     where d.id = ~'' || apex_util.get_session_state(''P9012_PARAMETRO'') || q''~',
'                       and nvl(p.ind_calculando_valores, ''N'') = ''N''',
'                )',
'                then ''S''',
'                else ''N''',
'            end as atualizar,',
'            ''~'' || l_modo_refresh || q''~'' as modo_refresh',
'          from dual',
'        ~'';',
'    end sql_auto_refresh;',
'',
'    procedure post_create(',
'        p_id      out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_declaracaoimportacao.altera_status(',
'            p_id                        => apex_application.g_f02(1),',
