'        );',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id       in  number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_declaracaoimportacao.altera_status(',
'            p_id                        => p_id,',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end post_save;',
'',
'',
'    function mostra_opcao(',
'        p_param1 in varchar2 default null,',
'        p_param2 in varchar2 default null,',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_url clob;',
'        v_id_processo number;',
'    begin',
'        select id_processoimportacao into v_id_processo from imp_declaracaoimportacao where id = p_param1;',
'        ',
'        l_url := apex_page.get_url(',
'            p_page   => 9000,',
'            p_items  => ''P9000_ID,P9000_PAGINA'',',
'            p_values => v_id_processo || '',TD1055''',
'        );',
'        return l_url;',
'    end;   ',
'',
'end "UI_MPD_TD1055";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td962
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(227621545844448012)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD962'
,p_sequence=>3300
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD962" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'',
'end "UI_MPD_TD962";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD962" as',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        consulta clob;  ',
'        l_url varchar2(4000);',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_id_entidade number; ',
'',
'    begin  ',
'        -- select id into l_id_entidade from srv_entidade where lower(nome_entidade) = ''srv_configuracao_ng_dominio'';',
'        -- select id into l_id_coluna from srv_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao_dominio'';             ',
'',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,25,35434'', ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        ); ',
'',
'      ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor from dual UNION ALL  '
||'        ',
'               SELECT p_codigo_artefato, ''codigo_dominio'',       2, '''',null , ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_dominio'',       3, '''',l_url, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_configuracao'',         4, ''HID'',NULL, ''N'',''S'', NULL valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',         30, ''HID'',NULL, ''N'',''S'', NULL valor FROM dual  ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_id number;',
'    begin',
'        l_id := APEX_UTIL.GET_SESSION_STATE(''P9010_ID'');',
'        bo_srv_configuracao_ng_dominio.altera_registro(  ',
'            p_id_tenant             => apex_application.g_f01(1), ',
'            p_codigo_dominio        => apex_application.g_f02(1),',
'            p_descricao_dominio     => apex_application.g_f03(1),',
'            p_id_configuracao       => apex_application.g_f04(1),',
'            p_data_alteracao        => TO_TIMESTAMP(apex_application.g_f30(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id => p_id, ',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD962";',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_maestro_interface
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(227645984938654585)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'PKG_MAESTRO_INTERFACE'
,p_sequence=>3310
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 06/07/2026',
unistr('-- Motivo: Inclus\00E3o da procedure if_gerencia_tributos para permitir atualizar os valores dos tributos do processo de importa\00E7\00E3o'),
'-- Jira:',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/06/2026',
unistr('-- Motivo: Inclus\00E3o da procedure if_inclui_processoimportacao para permitir incluir processos de importa\00E7\00E3o ao firmar o pedido de importa\00E7\00E3o'),
'-- Jira: PEDITEM-11',
'',
'create or replace package pkg_maestro_interface as ',
' ',
'    ---------------------------------------------------------------------------- ',
unistr('    -- Contexto padr\00E3o recebido do MAESTRO '),
'    ---------------------------------------------------------------------------- ',
'    type r_contexto_maestro is record ( ',
'        id_solicitacao number, ',
'        id_tenant      number, ',
'        id_usuario     number, ',
'        id_negocio     varchar2(4000), ',
'        payload        clob, ',
'        corr           varchar2(4000) ',
'    ); ',
' ',
'    ---------------------------------------------------------------------------- ',
unistr('    -- Interface padr\00E3o MAESTRO '),
'    ---------------------------------------------------------------------------- ',
'    procedure if_recalcula_rateio_invoice_item_despesa( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob         ',
'    ); ',
' ',
'    procedure if_altera_valor_desconto_invoice_item( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob         ',
'    );     ',
' ',
'    procedure if_limpar_log_tempo_com_item( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob         ',
'    );         ',
' ',
'    procedure if_job_expurgar_logs( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob         ',
'    );         ',
' ',
'    procedure if_job_expirar_ttl( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob         ',
'    );     ',
' ',
'    procedure if_importar_cotacao_dia( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob         ',
'    );',
'',
'    procedure if_gerencia_processoimportacao_item_despesa(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    );',
'',
'    procedure if_cria_registro_e_recalcula_processo(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    );',
'',
'    procedure if_inclui_processoimportacao(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    );',
'    ',
'    procedure if_gerencia_tributos(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    );',
' ',
'end pkg_maestro_interface;',
'/',
'',
'create or replace package body pkg_maestro_interface as ',
' ',
'    ---------------------------------------------------------------------------- ',
unistr('    -- Monta record de contexto padr\00E3o '),
'    ---------------------------------------------------------------------------- ',
'    function build_context( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2 ',
'    ) return r_contexto_maestro ',
'    is ',
'        l_ctx r_contexto_maestro; ',
'    begin ',
'        l_ctx.id_solicitacao := p_id_solicitacao; ',
'        l_ctx.id_tenant      := p_id_tenant; ',
'        l_ctx.id_usuario     := p_id_usuario; ',
'        l_ctx.id_negocio     := p_id_negocio; ',
'        l_ctx.payload        := p_payload; ',
'        l_ctx.corr           := p_corr; ',
' ',
'        return l_ctx; ',
'    end build_context; ',
' ',
' ',
'    ---------------------------------------------------------------------------- ',
unistr('    -- Valida\00E7\00E3o b\00E1sica comum '),
'    ---------------------------------------------------------------------------- ',
'    procedure validar_contexto( ',
'        p_ctx in r_contexto_maestro ',
'    ) ',
'    is ',
'    begin ',
'        if p_ctx.id_solicitacao is null then ',
unistr('            raise_application_error(-20001, ''p_id_solicitacao n\00E3o informado.''); '),
'        end if; ',
' ',
'        if p_ctx.id_tenant is null then ',
unistr('            raise_application_error(-20002, ''p_id_tenant n\00E3o informado.''); '),
'        end if; ',
' ',
'        if p_ctx.id_usuario is null then ',
unistr('            raise_application_error(-20003, ''p_id_usuario n\00E3o informado.''); '),
'        end if; ',
' ',
'        if p_ctx.payload is null then ',
unistr('            raise_application_error(-20004, ''p_payload n\00E3o informado.''); '),
'        end if; ',
'    end validar_contexto; ',
' ',
' ',
'    ---------------------------------------------------------------------------- ',
'    -- Helpers JSON ',
'    ---------------------------------------------------------------------------- ',
'    function get_number( ',
'        p_json          in json_object_t, ',
'        p_key           in varchar2, ',
'        p_required      in boolean default false, ',
'        p_default_value in number default null ',
'    ) return number ',
'    is ',
'        l_value number; ',
'    begin ',
'        if p_json.has(p_key) then ',
'            if p_json.get_number(p_key) is null then ',
'                if p_required then ',
'                    raise_application_error( ',
'                        -20010, ',
unistr('                        ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" est\00E1 nulo.'' '),
'                    ); ',
'                end if; ',
'                return p_default_value; ',
'            end if; ',
'            l_value := p_json.get_number(p_key); ',
'            return l_value; ',
'        end if; ',
' ',
'        if p_required then ',
'            raise_application_error( ',
'                -20011, ',
unistr('                ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" n\00E3o informado.'' '),
'            ); ',
'        end if; ',
' ',
'        return p_default_value; ',
'    end get_number; ',
' ',
' ',
'    function get_string( ',
'        p_json          in json_object_t, ',
'        p_key           in varchar2, ',
'        p_required      in boolean default false, ',
'        p_default_value in varchar2 default null ',
'    ) return varchar2 ',
'    is ',
'        l_value varchar2(32767); ',
'    begin ',
'        if p_json.has(p_key) then ',
'            if p_json.get(p_key).is_null then ',
'                if p_required then ',
'                    raise_application_error( ',
'                        -20012, ',
unistr('                        ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" est\00E1 nulo.'' '),
'                    ); ',
'                end if; ',
' ',
'                return p_default_value; ',
'            end if; ',
' ',
'            l_value := p_json.get_string(p_key); ',
'            return l_value; ',
'        end if; ',
' ',
'        if p_required then ',
'            raise_application_error( ',
'                -20013, ',
unistr('                ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" n\00E3o informado.'' '),
'            ); ',
'        end if; ',
' ',
'        return p_default_value; ',
'    end get_string; ',
' ',
' ',
'    function to_boolean( ',
'        p_value   in varchar2, ',
'        p_default in boolean default false ',
'    ) return boolean ',
'    is ',
'        l_value varchar2(100); ',
'    begin ',
'        if p_value is null then ',
'            return p_default; ',
'        end if; ',
' ',
'        l_value := upper(trim(p_value)); ',
' ',
'        if l_value in (''TRUE'', ''T'', ''1'', ''S'', ''SIM'', ''Y'', ''YES'') then ',
'            return true; ',
unistr('        elsif l_value in (''FALSE'', ''F'', ''0'', ''N'', ''NAO'', ''N\00C3O'', ''NO'') then '),
'            return false; ',
'        else ',
'            raise_application_error( ',
'                -20014, ',
unistr('                ''Payload inv\00E1lido: valor booleano inv\00E1lido ['' || p_value || ''].'' '),
'            ); ',
'        end if; ',
'    end to_boolean; ',
' ',
' ',
'    function get_boolean( ',
'        p_json          in json_object_t, ',
'        p_key           in varchar2, ',
'        p_required      in boolean default false, ',
'        p_default_value in boolean default false ',
'    ) return boolean ',
'    is ',
'        l_raw_value varchar2(100); ',
'    begin ',
'        if p_json.has(p_key) then ',
'            if p_json.get(p_key).is_null then ',
'                if p_required then ',
'                    raise_application_error( ',
'                        -20015, ',
unistr('                        ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" est\00E1 nulo.'' '),
'                    ); ',
'                end if; ',
' ',
'                return p_default_value; ',
'            end if; ',
' ',
'            l_raw_value := p_json.get_string(p_key); ',
'            return to_boolean(l_raw_value, p_default_value); ',
'        end if; ',
' ',
'        if p_required then ',
'            raise_application_error( ',
'                -20016, ',
unistr('                ''Payload inv\00E1lido: atributo obrigat\00F3rio "'' || p_key || ''" n\00E3o informado.'' '),
'            ); ',
'        end if; ',
' ',
'        return p_default_value; ',
'    end get_boolean; ',
' ',
'    function messages_to_json( ',
'        p_messages in pkg_mensagem.message_record_table ',
'    ) return clob ',
'    is ',
'        l_array   json_array_t := json_array_t(); ',
'        l_obj     json_object_t; ',
'    begin ',
'        if p_messages is null or p_messages.count = 0 then ',
'            return ''[]''; ',
'        end if; ',
' ',
'        for i in 1 .. p_messages.count loop ',
'            l_obj := json_object_t(); ',
' ',
'            l_obj.put(''mensagem'',       p_messages(i).mensagem); ',
'            l_obj.put(''instrucao'',      p_messages(i).instrucao); ',
'            l_obj.put(''help'',           p_messages(i).help); ',
'            l_obj.put(''local_exibicao'', p_messages(i).local_exibicao); ',
'            l_obj.put(''nome_item'',      p_messages(i).nome_item); ',
'            l_obj.put(''tipo'',           p_messages(i).tipo); ',
' ',
'            l_array.append(l_obj); ',
'        end loop; ',
' ',
'        return l_array.to_clob; ',
'    end messages_to_json; ',
' ',
'    ---------------------------------------------------------------------------- ',
'    -- Interface concreta: ',
'    -- bo_imp_invoice_item.recalcula_rateio_invoice_item_despesa ',
'    ---------------------------------------------------------------------------- ',
'    procedure if_recalcula_rateio_invoice_item_despesa( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob ',
'    ) ',
'    is ',
'        l_ctx         r_contexto_maestro; ',
'        l_json        json_object_t; ',
'        l_id_invoice  imp_invoice_item.id_invoice%type; ',
'        l_pagina      number := 0; ',
'        l_encadeado   boolean := false; ',
'        l_sucesso      clob; ',
'        l_messages     pkg_mensagem.message_record_table; ',
'    begin ',
'        ---------------------------------------------------------------------------- ',
unistr('        -- Contexto padr\00E3o '),
'        ---------------------------------------------------------------------------- ',
'        l_ctx := build_context( ',
'            p_id_solicitacao => p_id_solicitacao, ',
'            p_id_tenant      => p_id_tenant, ',
'            p_id_usuario     => p_id_usuario, ',
'            p_id_negocio     => p_id_negocio, ',
'            p_payload        => p_payload, ',
'            p_corr           => p_corr ',
'        ); ',
' ',
'        validar_contexto(l_ctx); ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- Parse do payload ',
'        ---------------------------------------------------------------------------- ',
'        l_json := json_object_t.parse(l_ctx.payload); ',
' ',
'        ---------------------------------------------------------------------------- ',
unistr('        -- id_invoice obrigat\00F3rio '),
'        ---------------------------------------------------------------------------- ',
'        if l_json.has(''id_invoice'') then ',
'            l_id_invoice := get_number( ',
'                p_json     => l_json, ',
'                p_key      => ''id_invoice'', ',
'                p_required => true ',
'            ); ',
'        end if; ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- pagina opcional ',
'        ---------------------------------------------------------------------------- ',
'        if l_json.has(''pagina'') then ',
'            l_pagina := get_number( ',
'                p_json          => l_json, ',
'                p_key           => ''pagina'', ',
'                p_default_value => 0 ',
'            ); ',
'        elsif l_json.has(''p_pagina'') then ',
'            l_pagina := get_number( ',
'                p_json          => l_json, ',
'                p_key           => ''p_pagina'', ',
'                p_default_value => 0 ',
'            ); ',
'        else ',
'            l_pagina := 0; ',
'        end if; ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- encadeado opcional ',
'        ---------------------------------------------------------------------------- ',
'        if l_json.has(''encadeado'') then ',
'            l_encadeado := get_boolean( ',
'                p_json          => l_json, ',
'                p_key           => ''encadeado'', ',
'                p_default_value => false ',
'            ); ',
'        elsif l_json.has(''p_encadeado'') then ',
'            l_encadeado := get_boolean( ',
'                p_json          => l_json, ',
'                p_key           => ''p_encadeado'', ',
'                p_default_value => false ',
'            ); ',
'        else ',
'            l_encadeado := false; ',
'        end if; ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- Chamada da rotina real do sistema ',
'        -- Ajustar o nome do pacote real abaixo ',
'        ---------------------------------------------------------------------------- ',
'        bo_imp_invoice_item.recalcula_rateio_invoice_item_despesa( ',
'            p_id_invoice => l_id_invoice, ',
'            p_pagina     => l_pagina, ',
'            p_encadeado  => l_encadeado, ',
'            p_sucesso    => l_sucesso, ',
'            p_messages   => l_messages ',
'        ); ',
' ',
'        p_sucesso       := l_sucesso; ',
'        p_messages_json := messages_to_json(l_messages);         ',
' ',
'    exception ',
'        when others then ',
'            raise; ',
'    end if_recalcula_rateio_invoice_item_despesa; ',
' ',
'    ---------------------------------------------------------------------------- ',
'    -- Interface concreta: ',
'    -- bo_imp_invoice.altera_valor_desconto_invoice_item ',
'    ---------------------------------------------------------------------------- ',
'    procedure if_altera_valor_desconto_invoice_item( ',
'        p_id_solicitacao in number, ',
'        p_id_tenant      in number, ',
'        p_id_usuario     in number, ',
'        p_id_negocio     in varchar2, ',
'        p_payload        in clob, ',
'        p_corr           in varchar2, ',
'        p_sucesso        out clob, ',
'        p_messages_json  out clob ',
'    ) ',
'    is ',
'        l_ctx         r_contexto_maestro; ',
'        l_json        json_object_t; ',
'        l_id_invoice  imp_invoice_item.id_invoice%type; ',
'        l_pagina      number := 0; ',
'        l_encadeado   boolean := false; ',
'        l_sucesso      clob; ',
'        l_messages     pkg_mensagem.message_record_table; ',
'    begin ',
'        ---------------------------------------------------------------------------- ',
unistr('        -- Contexto padr\00E3o '),
'        ---------------------------------------------------------------------------- ',
'        l_ctx := build_context( ',
'            p_id_solicitacao => p_id_solicitacao, ',
'            p_id_tenant      => p_id_tenant, ',
'            p_id_usuario     => p_id_usuario, ',
'            p_id_negocio     => p_id_negocio, ',
'            p_payload        => p_payload, ',
'            p_corr           => p_corr ',
'        ); ',
' ',
'        validar_contexto(l_ctx); ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- Parse do payload ',
'        ---------------------------------------------------------------------------- ',
'        l_json := json_object_t.parse(l_ctx.payload); ',
' ',
'        ---------------------------------------------------------------------------- ',
unistr('        -- id_invoice obrigat\00F3rio '),
'        ---------------------------------------------------------------------------- ',
'        if l_json.has(''id_invoice'') then ',
'            l_id_invoice := get_number( ',
'                p_json     => l_json, ',
'                p_key      => ''id_invoice'', ',
'                p_required => true ',
'            ); ',
'        end if; ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- pagina opcional ',
'        ---------------------------------------------------------------------------- ',
'        if l_json.has(''pagina'') then ',
'            l_pagina := get_number( ',
'                p_json          => l_json, ',
'                p_key           => ''pagina'', ',
'                p_default_value => 0 ',
'            ); ',
'        elsif l_json.has(''p_pagina'') then ',
'            l_pagina := get_number( ',
'                p_json          => l_json, ',
'                p_key           => ''p_pagina'', ',
'                p_default_value => 0 ',
'            ); ',
'        else ',
'            l_pagina := 0; ',
'        end if; ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- encadeado opcional ',
'        ---------------------------------------------------------------------------- ',
'        if l_json.has(''encadeado'') then ',
'            l_encadeado := get_boolean( ',
'                p_json          => l_json, ',
'                p_key           => ''encadeado'', ',
'                p_default_value => false ',
'            ); ',
'        elsif l_json.has(''p_encadeado'') then ',
'            l_encadeado := get_boolean( ',
'                p_json          => l_json, ',
'                p_key           => ''p_encadeado'', ',
'                p_default_value => false ',
'            ); ',
'        else ',
'            l_encadeado := false; ',
'        end if; ',
' ',
'        ---------------------------------------------------------------------------- ',
'        -- Chamada da rotina real do sistema ',
'        -- Ajustar o nome do pacote real abaixo ',
'        ---------------------------------------------------------------------------- ',
'        bo_imp_invoice.altera_valor_desconto_invoice_item( ',
'            p_id         => l_id_invoice, ',
'            p_pagina     => l_pagina, ',
'            p_encadeado  => l_encadeado, ',
'            p_sucesso    => l_sucesso, ',
'            p_messages   => l_messages ',
'        ); ',
' ',
'        p_sucesso       := l_sucesso; ',
'        p_messages_json := messages_to_json(l_messages);         ',
' ',
'    exception ',
'        when others then ',
'            raise; ',
'    end if_altera_valor_desconto_invoice_item; ',
