'    ',
'    procedure if_cria_registro_e_recalcula_processo(',
'        p_id_solicitacao in number,',
'        p_id_tenant      in number,',
'        p_id_usuario     in number,',
'        p_id_negocio     in varchar2,',
'        p_payload        in clob,',
'        p_corr           in varchar2,',
'        p_sucesso        out clob,',
'        p_messages_json  out clob',
'    ) is',
'        l_ctx                     r_contexto_maestro;',
'        l_json                    json_object_t;',
'        l_arr_taxa_cambio         json_array_t;',
'        l_id_declaracaoimportacao imp_declaracaoimportacao_cotacao.id_declaracaoimportacao%type;',
'        l_json_taxa_cambio        clob;',
'        l_id_processoimportacao   number;',
'        l_sucesso                 clob;',
'        l_messages                pkg_mensagem.message_record_table;',
'    begin',
'',
'        l_ctx := build_context(',
'            p_id_solicitacao => p_id_solicitacao,',
'            p_id_tenant      => p_id_tenant,',
'            p_id_usuario     => p_id_usuario,',
'            p_id_negocio     => p_id_negocio,',
'            p_payload        => p_payload,',
'            p_corr           => p_corr',
'        );',
'        validar_contexto(l_ctx);',
'',
'        l_json := json_object_t.parse(l_ctx.payload);',
'',
'        l_id_declaracaoimportacao := get_number(',
'            p_json     => l_json,',
'            p_key      => ''id_declaracaoimportacao'',',
'            p_required => true',
'        );',
'',
'        l_arr_taxa_cambio  := l_json.get_array(''json_taxa_cambio'');',
'        l_json_taxa_cambio := l_arr_taxa_cambio.to_clob;',
'',
'        bo_imp_declaracaoimportacao_cotacao.cria_registro_e_recalcula_processo(',
'            p_json_taxa_cambio        => l_json_taxa_cambio,',
'            p_id_declaracaoimportacao => l_id_declaracaoimportacao,',
'            p_pagina                  => 0,',
'            p_encadeado               => false,',
'            p_sucesso                 => l_sucesso,',
'            p_messages                => l_messages',
'        );',
'',
'        select id_processoimportacao',
'          into l_id_processoimportacao',
'          from imp_declaracaoimportacao',
'         where id = l_id_declaracaoimportacao;',
'',
'        update imp_processoimportacao',
'           set ind_calculando_valores = ''N''',
'         where id = l_id_processoimportacao;',
'',
'        p_sucesso       := l_sucesso;',
'        p_messages_json := messages_to_json(l_messages);',
'',
'    exception',
'        when others then',
'            begin',
'                if l_id_declaracaoimportacao is not null then',
'                    select id_processoimportacao',
'                      into l_id_processoimportacao',
'                      from imp_declaracaoimportacao',
'                     where id = l_id_declaracaoimportacao;',
'                    update imp_processoimportacao',
'                       set ind_calculando_valores = ''N''',
'                     where id = l_id_processoimportacao;',
'                end if;',
'            exception',
'                when others then null;',
'            end;',
'            raise;',
'    end if_cria_registro_e_recalcula_processo;',
'    --',
