prompt --application/deployment/install/install_ui_mpd_td1001
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(230795475948037555)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1001'
,p_sequence=>3350
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1001" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    -- function where_dinamico(p_campo in varchar2) return clob;',
'    ',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    ',
'end "UI_MPD_TD1001";',
'/',
'create or replace package body "UI_MPD_TD1001" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is            ',
'        l_id_processoimportacao number;',
'        l_num_processoimportacao varchar2(50);',
'        l_id_fornecedor number;',
'        l_id_tenant number; ',
'        l_id_moeda_numerario number;',
'        l_somente_leitura_id_fornecedor varchar2(1); ',
'    begin',
unistr('        -- Caso 1: inclus\00E3o (P9012_ID nulo)'),
'        IF apex_util.get_session_state(''P9012_ID'') IS NULL THEN',
'            l_id_processoimportacao := apex_util.get_session_state(''P9012_PARAMETRO2'');',
unistr('        -- Caso 2: edi\00E7\00E3o (P9012_ID aponta para numer\00E1rio)'),
'        ELSE',
'            BEGIN',
'                SELECT n.id_processoimportacao INTO l_id_processoimportacao FROM imp_processoimportacao_numerario n WHERE n.id = apex_util.get_session_state(''P9012_ID'');',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN l_id_processoimportacao := NULL;',
'            END;',
'        END IF;',
'',
'        IF l_id_processoimportacao IS NOT NULL THEN',
'            BEGIN',
'                SELECT a.id_tenant, a.num_processoimportacao, a.id_despachante INTO l_id_tenant, l_num_processoimportacao, l_id_fornecedor FROM imp_processoimportacao a WHERE a.id = l_id_processoimportacao;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    l_id_tenant                 := NULL;',
'                    l_num_processoimportacao    := NULL;',
'                    l_id_fornecedor             := NULL;',
'            END;',
'        END IF;',
'',
'        select case when exists (select 1 from imp_processoimportacao_numerario where id_processoimportacao = l_id_processoimportacao) then ''S'' else ''N'' end into l_somente_leitura_id_fornecedor from dual;',
'',
unistr('        -- Se j\00E1 existe numer\00E1rio, utiliza id_fornecedor j\00E1 utilizado'),
'        IF l_somente_leitura_id_fornecedor = ''S'' THEN',
'            BEGIN',
'                SELECT n.id_fornecedor INTO l_id_fornecedor FROM imp_processoimportacao_numerario n WHERE n.id_processoimportacao = l_id_processoimportacao AND n.id_fornecedor IS NOT NULL FETCH FIRST 1 ROWS ONLY;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    NULL;',
'            END;',
'        END IF;',
'        ',
'        select max(id_registro) into l_id_moeda_numerario from mpd_configuracao_ng where id_tenant = l_id_tenant and codigo_configuracao = 13 and ind_tipo_dado = ''ID'';',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, to_char((l_id_tenant)) valor, null tag_campo FROM dual '
||'UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',          12, ''HID'', null, ''S'', ''S'', to_char((l_id_processoimportacao)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''num_processoimportacao'',          2, ''TXT'', null, ''S'', ''N'', to_char((l_num_processoimportacao)) valor, ''IMP_PROCESSOIMPORTACAO.NUM_PROCESSOIMPORTACAO'' tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_movimento'',              3, '''', null, ''S'', ''S'', ''2'' valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_fornecedor'',                   4, '''', null, l_somente_leitura_id_fornecedor, ''S'', to_char((l_id_fornecedor)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''referencia_fornecedor'',             8, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_documento'',                  9, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_numerario'',              15, ''HID'', null, ''N'', ''S'', to_char((l_id_moeda_numerario)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_numerario_informado'', 11, '''', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                 14, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor,new_data.tag_campo);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_imp_processoimportacao_numerario.inclui_registro(',
'            p_id_tenant                         => apex_application.g_f01(1),',
'            p_id_processoimportacao             => apex_application.g_f12(1),',
'            p_id_titulo_pagamento               => null,                        ',
'            p_ind_status                        => 1,',
'            p_ind_tipo_movimento                => apex_application.g_f03(1),',
'            p_id_fornecedor                     => apex_application.g_f04(1),',
'            p_id_conta_bancaria                 => null,',
'            p_referencia_fornecedor               => apex_application.g_f08(1),',
'            p_data_documento                    => apex_application.g_f09(1),',
'            p_data_vencimento           => null,',
'            p_id_moeda_numerario                 => apex_application.g_f15(1),',
'            p_valor_numerario_informado    => pkg_util.retorna_number(apex_application.g_f11(1)),',
'            p_valor_total_despesas_numerario              => null, ',
'            p_observacao                        => null,   ',
'            p_id                                => p_id, ',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'    begin',
'        bo_imp_processoimportacao_numerario.altera_registro(',
'            p_id_tenant                         => apex_application.g_f01(1),',
'            p_id_processoimportacao             => apex_application.g_f12(1),',
'            p_id_titulo_pagamento               => null,          ',
'            p_ind_status                        => 1,',
'            p_ind_tipo_movimento                => apex_application.g_f03(1),',
'            p_id_fornecedor                     => apex_application.g_f04(1),',
'            p_id_conta_bancaria                 => null,',
'            p_referencia_fornecedor               => apex_application.g_f08(1),',
'            p_data_documento                    => apex_application.g_f09(1),',
'            p_data_vencimento           => null, ',
'            p_id_moeda_numerario                 => apex_application.g_f15(1),',
'            p_valor_numerario_informado    => pkg_util.retorna_number(apex_application.g_f11(1)),',
'            p_valor_total_despesas_numerario              => null,               ',
'            p_observacao                        => null,                ',
'            p_data_alteracao                    => to_timestamp(apex_application.g_f14(1), ''dd-mon-rr hh:mi:ss.ff am''),',
'            p_id                                => p_id, ',
'            p_sucesso                           => p_sucesso,',
'            p_messages                          => p_messages',
'        );        ',
'    end post_save;',
'    ',
'end "UI_MPD_TD1001";',
'/'))
);
end;
