prompt --application/deployment/install/install_ui_mpd_td1002
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(230796080724050513)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD1002'
,p_sequence=>3360
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD1002" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD1002";',
'/',
'create or replace package body "UI_MPD_TD1002" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin  ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ',
'                ''select',
'                    b.num_processoimportacao, ',
'                    pkg_util.dominio_retorna_tag(''''imp_processoimportacao_numerario'''',''''ind_tipo_movimento'''',a.ind_tipo_movimento) ind_tipo_movimento,',
'                    bo_ng_pessoa.retorna_pessoa(a.id_fornecedor) id_fornecedor',
'                from imp_processoimportacao_numerario a ',
'                join imp_processoimportacao b on b.id = a.id_processoimportacao',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao'',''imp_processoimportacao_numerario'',''imp_processoimportacao_numerario''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end sql_cabecalho;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_processoimportacao'',          2, ''HID'', null, ''S'', ''S'', to_char((select id_processoimportacao from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_moeda_numerario'',              4, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''S'', ''S'', to_char((select id_moeda_numerario from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_camp'
||'o FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_despesas_numerario'',           6, '''', null, ''S'', ''S'', to_char((select valor_total_despesas_numerario from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNI'
||'ON ALL',
'               SELECT p_codigo_artefato, ''referencia_fornecedor'',            7, '''', null, ''S'', ''S'', to_char((select referencia_fornecedor from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_documento'',                 8, '''', null, ''S'', ''S'', to_char((select data_documento from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status'',                     9, ''SEL'', ''D_IMP_PROCESSOIMPORTACAO_NUMERARIO.IND_STATUS_2_OU_3'', ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'            --    SELECT p_codigo_artefato, ''id_conta_bancaria'',              8, ''HID'', null, ''N'', ''S'', to_char((select id_conta_bancaria from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''data_vencimento'',       10, ''HID'', null, ''N'', ''S'', to_char((select data_vencimento from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL ',
'            --    SELECT p_codigo_artefato, ''observacao'',                    11, ''HID'', null, ''N'', ''S'', null valor, null tag_campo FROM dual UNION ALL               ',
'            --    SELECT p_codigo_artefato, ''ind_tipo_movimento'',            12, ''HID'', null, ''S'', ''S'', to_char((select ind_tipo_movimento from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL          '
||'     ',
'            --    SELECT p_codigo_artefato, ''id_fornecedor'',                 13, ''HID'', null, ''S'', ''S'', to_char((select id_fornecedor from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''valor_total_despesas_numerario'',          15, '''', null, ''S'', ''S'', to_char((select valor_total_despesas_numerario from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual '
||'UNION ALL               ',
'               SELECT p_codigo_artefato, ''id'',                            16, '''', null, ''S'', ''S'', to_char((select id from imp_processoimportacao_numerario where id = p_param1)) valor, null tag_campo FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_alteracao'',                17, ''HID'', null, ''S'', ''S'', null valor, null tag_campo FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor,tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor,new_data.tag_campo);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_numerario number;',
'    begin',
'        l_id_numerario := apex_util.get_session_state(''P9012_PARAMETRO'');',
'',
'        bo_imp_processoimportacao_numerario_despesa.confirma_comprovacao_despesas(',
'            p_id_numerario          => l_id_numerario,',
'            p_ind_status            => apex_application.g_f09(1),',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'    end post_create;',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_numerario number;',
'        l_valor_total_despesas number;',
'    begin',
'        l_id_numerario := apex_util.get_session_state(''P9012_PARAMETRO'');',
'',
'        bo_imp_processoimportacao_numerario_despesa.confirma_comprovacao_despesas(',
'            p_id_numerario          => l_id_numerario,',
'            p_ind_status            => apex_application.g_f09(1),',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'    end post_save;',
'    ',
'end "UI_MPD_TD1002";',
'/'))
);
end;
