,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 30/06/2026',
'-- Motivo: Desenvolvimento de funcionalidade para alterar data_coleta_local_origem_real',
'-- Jira: PEDITEM-327, PEDITEM-328, PEDITEM-329',
'',
'create or replace package "UI_MPD_TD792" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'    --',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null',
'    );',
'    --',
'    function label_acao ',
'    return varchar2;',
'    --',
'    procedure post(',
'        p_id       in number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
