prompt --application/deployment/install/install_ui_mpd_td877
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(231002861751997765)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD877'
,p_sequence=>3380
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Jonathan',
'-- Data: 24/06/2026',
unistr('-- Motivo: Inclus\00E3o de novas colunas ind_finalidade e numero_ato_concessorio'),
'-- Jira: PEDITEM-278',
'',
'create or replace package "UI_MPD_TD877" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    function sql_atribuir_peso_liquido_total(p_param1 in varchar2) return clob;',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD877";',
'/',
'',
'create or replace package body "UI_MPD_TD877" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_processoimportacao as num_processoimportacao',
'                from imp_processoimportacao a',
'                join imp_processoimportacao_item b on b.id_processoimportacao = a.id',
'                where b.id = ''||p_param1,',
'            p_tabela => textarray(''imp_processoimportacao''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_JSON_calcular_peso_total clob;',
'        l_atribuir_peso_liquido_total clob;',
'        l_campos_calcular_peso_quantidade varchar2(128) := ''PESO_LIQUIDO_TOTAL'';',
'    begin',
'        l_JSON_calcular_peso_total := gerar_json_calcular_valor(',
'            '' QUANTIDADE * PESO_UNITARIO '',',
'            l_campos_calcular_peso_quantidade',
'        );',
'',
'        l_atribuir_peso_liquido_total := gerar_json_atribuir_valor(',
'            p_codigo_artefato,',
'            ''sql_calcular_peso_total'',',
'            apex_t_varchar2(''PESO_LIQUIDO_TOTAL'')',
'        );',
'',
'        MERGE INTO temp_formulario tf',
'        USING (',
'            SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, NULL AS nome_consulta, ''S'' AS somente_leitura, ''S'' coluna_tabela, NULL valor, NULL obrigatorio, NULL tag_campo, NULL atribuir_v'
||'alor, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_processoimportacao'',                          2, ''HID'', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_entrega_item'',                                4, ''HID'', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_item'',                                        6, '''', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''descricao'',                                      8, ''TEX'', NULL, ''S'', ''N'', TO_CHAR((SELECT a.descricao_item FROM ng_item a JOIN imp_processoimportacao_item b ON b.id_item = a.id where b.id = p_param1)) valor, NU'
||'LL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_ncm'',                                         9, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_unidademedida'',                              11, '''', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''QUANTIDADE'',                                    13, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, l_JSON_calcular_peso_total calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''PESO_UNITARIO'',                                 14, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, l_JSON_calcular_peso_total calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''PESO_LIQUIDO_TOTAL'',                            15, '''', NULL, ''S'', ''S'', NULL, NULL, NULL, l_atribuir_peso_liquido_total, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_moeda'',                                      16, ''SEL'', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_incoterm'',                                   18, ''HID'', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''valor_unitario'',                                20, '''', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''valor_desconto'',                                21, '''', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''valor_total_condicao_venda'',                    22, '''', NULL, ''S'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_naturezaoperacao'',                           23, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_fabricante'',                                 25, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''ind_licenca_importacao'',                        27, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''ind_bloqueio_embarque_ate_deferimento_li'',      28, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''id_centrocusto'',                                29, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''ind_finalidade'',                                31, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''numero_ato_concessorio'',                        32, '''', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual UNION ALL',
'            SELECT p_codigo_artefato, ''data_alteracao'',                                33, ''HID'', NULL, ''N'', ''S'', NULL, NULL, NULL, NULL, null calcular_valor FROM dual',
'        ) new_data',
'        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)',
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, tag_campo, atribuir_valor, calcular_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.tag_campo, new_data'
||'.atribuir_valor, new_data.calcular_valor);',
'    end formulario;',
'',
'    function sql_atribuir_peso_liquido_total(p_param1 in varchar2) return clob is',
'        l_sql clob;',
'    begin ',
'        l_sql := ''select (''||apex_application.g_f13(1)||'' * ''||apex_application.g_f14(1)||'') PESO_LIQUIDO_TOTAL from dual'';',
'        return nvl(replace(l_sql,''#ID#'',p_param1),''999'');',
'    end sql_atribuir_peso_liquido_total;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is  ',
'        l_old imp_processoimportacao_item%rowtype;',
'    begin',
'        select * into l_old from imp_processoimportacao_item where id = p_id;',
'',
'        bo_imp_processoimportacao_item.altera_registro(',
'            p_id_tenant                                         => apex_application.g_f01(1),',
'            p_id_processoimportacao                             => apex_application.g_f02(1),',
'            p_id_entrega                                        => l_old.id_entrega,',
'            p_id_entrega_item                                   => apex_application.g_f04(1),',
'            p_id_minutanotafiscal                               => l_old.id_minutanotafiscal,',
'            p_id_item                                           => apex_application.g_f06(1),',
'            p_id_ncm                                            => apex_application.g_f09(1),',
'            p_id_unidademedida                                  => apex_application.g_f11(1),',
'            p_quantidade                                        => pkg_util.retorna_number(apex_application.g_f13(1)),',
'            p_peso_unitario                                     => pkg_util.retorna_number(apex_application.g_f14(1)),',
'            p_peso_liquido_total                                => pkg_util.retorna_number(apex_application.g_f15(1)),',
'            p_peso_bruto_unitario                               => l_old.peso_bruto_unitario,',
'            p_peso_bruto_total                                  => l_old.peso_bruto_total,',
'            p_id_pais_origem                                    => l_old.id_pais_origem,',
'            p_id_moeda                                          => apex_application.g_f16(1),',
'            p_id_incoterm                                       => apex_application.g_f18(1),',
'            p_valor_unitario                                    => pkg_util.retorna_number(apex_application.g_f20(1)),',
'            p_valor_desconto                                    => pkg_util.retorna_number(apex_application.g_f21(1)),',
'            p_valor_total_mercadoria                            => l_old.valor_total_mercadoria,',
'            p_valor_total_condicao_venda                        => pkg_util.retorna_number(apex_application.g_f22(1)),',
'            p_valor_total_desconto_invoice_item                 => l_old.valor_total_desconto_invoice_item,',
'            p_valor_total_despesa_invoice_item                  => l_old.valor_total_despesa_invoice_item,',
'            p_id_naturezaoperacao                               => apex_application.g_f23(1),',
'            p_id_exportador                                     => l_old.id_exportador,',
'            p_id_fabricante                                     => apex_application.g_f25(1),',
'            p_id_centrocusto                                    => apex_application.g_f29(1),',
'            p_num_solicitacao_compra                            => l_old.num_solicitacao_compra,',
'            p_nome_solicitante                                  => l_old.nome_solicitante,',
'            p_data_entrega_desejada                             => l_old.data_entrega_desejada,',
'            p_quantidade_faturada                               => l_old.quantidade_faturada,',
'            p_quantidade_saldo                                  => l_old.quantidade_saldo,',
'            p_ind_licenca_importacao                            => apex_application.g_f27(1),',
'            p_ind_bloqueio_embarque_ate_deferimento_li          => apex_application.g_f28(1),',
'            p_ind_finalidade                                    => apex_application.g_f31(1),',
'            p_numero_ato_concessorio                            => apex_application.g_f32(1),',
'            p_valor_total_mercadoria_moeda_nacional             => l_old.valor_total_mercadoria_moeda_nacional,',
'            p_valor_unitario_mercadoria_moeda_nacional          => l_old.valor_unitario_mercadoria_moeda_nacional,',
'            p_cst                                               => l_old.cst,',
'            p_id_cfop                                           => l_old.id_cfop,',
'            p_cclasstrib                                        => l_old.cclasstrib,',
'            p_data_alteracao                                    => TO_TIMESTAMP(apex_application.g_f33(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id                                                => p_id, ',
'            p_sucesso                                           => p_sucesso,',
'            p_messages                                          => p_messages',
'        );',
'    end post;',
'',
'',
'end "UI_MPD_TD877";',
'/'))
);
end;
