prompt --application/deployment/install/install_ui_mpd_td850
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(231326815679230794)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD850'
,p_sequence=>3390
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD850" as   ',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);    ',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD850";',
'/',
'',
'create or replace package body "UI_MPD_TD850" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select',
'            b.numero_pedido_importacao,',
'            a.num_entrega',
'        from imp_entrega a',
'        left join imp_pedidoimportacao b',
'            ON b.id = a.id_pedidoimportacao',
'        where a.id = ''|| p_param1,',
'        p_tabela => textarray(''imp_pedidoimportacao'',''imp_entrega''),',
'        p_formato => ''pequeno'',',
'        p_tipo_label => ''coluna'',',
'        p_classe  => ''st-back-transparente''',
'        )||',
'        ''</br><div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;"><h3 class="a-CardView-title">''||',
'        retorna_texto(''msg.120.l'')||''</h3></div>'';',
'        return l_html;',
'    end;',
'',
'   procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_html clob;',
'        v_id_processo number;',
'',
'    begin',
'',
'            select id_processoimportacao',
'            into v_id_processo',
'            from imp_entrega',
'            where id = p_param1;',
'',
unistr('            -- salva esse valor no item de sess\00E3o'),
'            apex_util.set_session_state(''P9012_PARAMETRO2'', v_id_processo);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (',
'             SELECT p_codigo_artefato AS codigo_artefato, ''id_processoimportacao'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' AS coluna_tabela, null valor, null html, null tag_campo FROM dual '
||'UNION ALL',
'             SELECT p_codigo_artefato, ''id'',          4, ''HID'', NULL, ''S'', ''N'', to_char(p_param1) valor,NULL html,null tag_campo from dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo);',
'    end formulario;',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )',
'    is',
'        l_id number;',
'        v_imp_ent imp_entrega%rowtype;',
'        l_param1 number;',
'        l_teste  number;',
'        l_verifica_altera number;',
'        l_id_moeda_pedidoimportacao imp_pedidoimportacao.id_moeda%type;',
'        l_id_incoterm imp_entrega.id_incoterm%type;',
'        l_id_item imp_processoimportacao_item.id%type;',
'',
'    begin',
'        bo_imp_entrega.altera_registro_id_processoimportacao(',
'                p_id_processoimportacao         => apex_application.g_f01(1),',
'                p_id                            => apex_application.g_f04(1),',
'                p_sucesso                       => p_sucesso,',
'                p_messages                      => p_messages',
'        );',
'',
'    end;',
'',
'',
'end "UI_MPD_TD850";',
'/'))
);
end;
