prompt --application/deployment/install/install_ui_mpd_td440
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(231327238650237691)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD440'
,p_sequence=>3400
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD440" as',
'',
'    function retorna_display(p_id in varchar2 default null, p_param1 in varchar2 default null, p_param2 in varchar2 default null) ',
'    return clob;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'',
'end "UI_MPD_TD440";',
'/',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD440" as',
'',
'    function retorna_display(p_id in varchar2 default null, p_param1 in varchar2 default null, p_param2 in varchar2 default null) ',
'    return clob is',
'        l_clob clob;',
'    begin null    ;   ',
'        -- select json_arrayagg(',
'        --          json_object(',
'        --              ''indice'' value ''f09_0000'',',
'        --              ''texto''  value pkg_util.dominio_retorna_tag(''ng_documento'',''ind_referencia'', ind_referencia)',
'        --          ) returning clob',
'        --        )',
'        --   into l_clob          ',
'        --   from ng_documento a          ',
'        --   where a.id = p_id;        ',
'        -- return l_clob;        ',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;        ',
'        l_id_coluna_anexo number;                  ',
'        l_descricao clob;',
'        l_descricao_anexo clob;',
'        l_permite_edicao varchar2(5);',
'        l_permite_edicao_anexo varchar2(5);',
'        l_erro clob;',
'        l_somente_leitura varchar2(1);',
'        l_somente_leitura_anexo varchar2(1);   ',
'        consulta clob;',
'        l_url varchar2(4000);',
'    begin ',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = lower(''ng_documento'');',
'        select id into l_id_coluna   from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''nome_documento'';     ',
'',
'        if lower(l_permite_edicao) = ''false'' then',
'            l_somente_leitura := ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'        if lower(l_permite_edicao_anexo) = ''false'' then',
'            l_somente_leitura_anexo := ''S'';',
'        else',
'            l_somente_leitura_anexo := ''N'';',
'        end if;',
'        l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||apex_util.get_session_state(l_id_chave)||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );',
'',
'        prc_enviar_parametros(''TD440'',''ind_referencia_documento'',p_param1);       ',
'        consulta := ''select d, r from pkg_util.dominio_retorna_lista(''''ng_documento'''',''''ind_referencia_documento'''') where r in (select to_number(regexp_substr(e.lista_referencia_documento,''''[^:]+'''', 1, level)) from srv_entidade_ng_permite_anexo e whe'
||'re e.id = (select c003 from apex_collections where collection_name = ''''''||p_codigo_artefato||''_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f07_0000'''')) connect by level <= regexp_count(e.lista_referencia_documento, '''':'''') + 1) o'
||'rder by d'';',
'',
'    MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 2 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL  '
||'             ',
'               SELECT p_codigo_artefato, ''nome_documento'',           4, ''TXT'', l_url, l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(nome_documento) from ng_documento where id = p_param1)) valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_entidade'',              6, '''', null,  ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_referencia_documento'', 8, ''POP1'', to_char(consulta),  ''N'',''S'', null valor FROM dual UNION ALL',
'            --    SELECT p_codigo_artefato, ''ind_referencia_documento'', 8, ''SEL'', NULL,  ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_emitido_aplicacao'',   10, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_obrigatorio'',         12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_aprovar'',             14, '''', null, ''N'',''S'', null valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',       18, '''', NULL, ''N'',''S'', null valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''data_alteracao'',          20, '''', NULL, ''N'',''S'', null valor FROM dual ',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )',
'    is',
'        l_id number;',
'    begin',
'        bo_ng_documento.altera_registro(',
'            p_id_tenant                 => apex_application.g_f02(1),',
'            p_nome_documento            => apex_application.g_f04(1),',
'            p_id_entidade               => apex_application.g_f06(1),',
'            p_ind_emitido_aplicacao     => apex_application.g_f10(1),',
'            p_ind_obrigatorio           => apex_application.g_f12(1),',
'            p_ind_aprovar               => apex_application.g_f14(1),    ',
'            p_ind_referencia_documento  => apex_application.g_f08(1),        ',
'            p_data_fim_vigencia         => apex_application.g_f18(1),',
'            p_data_alteracao            => TO_TIMESTAMP(apex_application.g_f20(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id                        => p_id, ',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD440";',
'/'))
);
end;
