prompt --application/deployment/install/install_ui_mpd_td439
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(231327426145241950)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD439'
,p_sequence=>3410
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD439" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function consulta_lista_suspensa(campo in varchar2) return clob; ',
'',
'end "UI_MPD_TD439";',
'/',
'create or replace package body "UI_MPD_TD439" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is  ',
'        consulta clob;  ',
'    begin  ',
'        prc_enviar_parametros(''TD439'',''ind_referencia'',p_param1);       ',
'        consulta := consulta_lista_suspensa(''ind_referencia_documento'');',
'    ',
'        MERGE INTO temp_formulario tf',
'            USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor FROM dual UNION ALL ',
'                   SELECT p_codigo_artefato, ''id_idioma_empresa'',        2, ''SEL'', TO_CHAR(''R_MPD_TENANT.DESCRICAO_IDIOMA''), ''S'',''N'', null valor FROM dual UNION ALL     ',
'                   SELECT p_codigo_artefato, ''nome_documento'',           4, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''id_entidade'',              6, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_referencia_documento'', 8, ''SEC'', TO_CHAR(consulta), ''N'',''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_emitido_aplicacao'',   10, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_obrigatorio'',         12, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''ind_aprovar'',             14, '''', null, ''N'',''S'', null valor FROM dual UNION ALL',
'                   SELECT p_codigo_artefato, ''data_fim_vigencia'',       18, '''', null, ''N'',''S'', null valor FROM dual                ',
'                    ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela,valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number,    ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_id number;',
'    begin',
'        bo_ng_documento.inclui_registro(',
'            p_id_tenant                 => apex_application.g_f01(1),',
'            p_nome_documento            => apex_application.g_f04(1),',
'            p_id_entidade               => apex_application.g_f06(1),',
'            p_ind_emitido_aplicacao     => apex_application.g_f10(1),',
'            p_ind_obrigatorio           => apex_application.g_f12(1),',
'            p_ind_aprovar               => apex_application.g_f14(1),',
'            p_ind_referencia_documento  => apex_application.g_f08(1),             ',
'            p_data_fim_vigencia         => apex_application.g_f18(1),',
'            p_id                        => l_id, ',
'            p_sucesso                   => p_sucesso,',
'            p_messages                  => p_messages',
'        );',
'    end;',
'',
'    function consulta_lista_suspensa(campo in varchar2) return clob is',
'        l_sql clob;',
'        l_teste varchar2(256);',
'    begin',
'        if campo = ''ind_referencia_documento'' then ',
'            l_sql := ''select d, r from pkg_util.dominio_retorna_lista(''''ng_documento'''',''''ind_referencia_documento'''') where r in (select to_number(regexp_substr(e.lista_referencia_documento,''''[^:]+'''', 1, level)) from srv_entidade_ng_permite_anexo e wh'
||'ere e.id = (select c003 from apex_collections where collection_name = ''''TD439_''||apex_custom_auth.get_session_id||'''''' and upper(c001) = upper(''''f07_0000'''')) connect by level <= regexp_count(e.lista_referencia_documento, '''':'''') + 1) order by d'';',
'        end if;',
'        return l_sql;',
'    end;',
'',
'',
'end "UI_MPD_TD439";',
'/'))
);
end;
