prompt --application/deployment/install/install_ui_mpd_td592
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(231347189951582288)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD592'
,p_sequence=>3420
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 26/06/2026',
unistr('-- Motivo: Altera\00E7\00F5es no prot\00F3tipo para n\00E3o permitir alterar ind_status_pedido_importacao e atriburi o valor padr\00E3o ''2'' (\00C1 firmar)'),
'-- Jira: PEDITEM-65',
'',
'create or replace package "UI_MPD_TD592" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number;',
'    ',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD592";',
'/',
'',
'create or replace package body "UI_MPD_TD592" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select a.numero_pedido_importacao from imp_pedidoimportacao a where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_pedidoimportacao''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );        ',
'        return l_html;',
'    end;',
'',
'    function busca_id_etapa(p_paramentro in varchar2) return number is',
'        l_id number;',
'    begin        ',
'        l_id := p_paramentro;',
'        return l_id;',
'        exception',
'            when no_data_found then',
'                return null;',
'    end;',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is                    ',
'    begin        ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''HID'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null obrigatorio FROM dual UNION ALL       '
||'        ',
'               SELECT p_codigo_artefato, ''ind_status_conclusao'',           2, ''SEL'', ''D_IMP_PEDIDOIMPORTACAO.IND_STATUS_CONCLUSAO'', ''S'', ''N'', ''2'' valor, ''S'' obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_modalidade_importacao'',      3, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_exportador'',                  4, '''', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_importador'',                  6, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_adquirente'',                  8, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_comprador'',                  10, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''nome_vendedor'',                 12, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_proforma'',               14, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_moeda'',                      15, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_viatransporte'',              19, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''numero_pedido_importacao'',      21, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_origem'',            22, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_embarque'',             24, '''', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_local_desembarque'',          26, '''', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_endereco_destino'',           28, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_entrega'',            30, '''', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_condicaopagamento'',          31, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''quantidade_parcelas_pagamento'', 33, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_mercadoria'',        35, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_desconto'',                36, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_despesa_proforma'',        37, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_incoterm'',                   38, '''', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_listapreco'',                 40, ''HID'', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''valor_total_condicao_venda'',    42, '''', null, ''S'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_confirmacao_pedido'',       43, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_todos_itens_com_entregas_programadas'', 44, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                           45, '''', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_status_pedido_importacao'',             46, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao_parcela_pagamento'',           47, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela,new_data.valor, new_data.obrigatorio);    ',
'    end formulario;',
'    ',
'    procedure post_save(',
'        p_id in number default null,  ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    )is',
'        l_data_confirmacao date;        ',
'    begin        ',
'        if apex_application.g_f02(1) = 3 then',
'            l_data_confirmacao := current_date;',
'        else',
'            l_data_confirmacao := apex_application.g_f43(1);',
'        end if;',
'',
'        bo_imp_pedidoimportacao.conclui_pedido(        ',
'            p_ind_status_pedido_importacao => apex_application.g_f02(1),',
'            p_data_confirmacao_pedido => l_data_confirmacao,',
'            p_ind_situacao_parcela_pagamento => ''S'',',
'            p_id => p_id,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'',
'        -- bo_imp_pedidoimportacao.altera_registro(',
'        --     p_id_tenant => apex_application.g_f01(1),',
'        --     p_numero_pedido_importacao => apex_application.g_f21(1),',
'        --     p_ind_modalidade_importacao => apex_application.g_f03(1),',
'        --     p_id_exportador => apex_application.g_f04(1),',
'        --     p_id_importador => apex_application.g_f06(1),',
'        --     p_id_adquirente => apex_application.g_f08(1),',
'        --     p_id_comprador => apex_application.g_f10(1),',
'        --     p_nome_vendedor => apex_application.g_f12(1),        ',
'        --     p_numero_proforma => apex_application.g_f14(1),            ',
'        --     p_id_moeda => apex_application.g_f15(1),        ',
'        --     p_id_viatransporte => apex_application.g_f19(1),',
'        --     p_id_incoterm => apex_application.g_f38(1),',
'        --     p_id_listapreco => apex_application.g_f40(1),',
'        --     p_id_endereco_origem => apex_application.g_f22(1),',
'        --     p_id_local_embarque => apex_application.g_f24(1),',
'        --     p_id_local_desembarque => apex_application.g_f26(1),',
'        --     p_id_endereco_destino => apex_application.g_f28(1),',
'        --     p_quantidade_entrega => apex_application.g_f30(1),',
