prompt --application/deployment/install/install_ui_mpd_td367
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(231684794567043294)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD367'
,p_sequence=>3430
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 26/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD367" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null) return clob;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'   ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD367";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD367" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is        ',
'        l_html clob;',
'    begin',
'',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''select pkg_traducao.get_traducao(a.descricao_condicaopagamento) descricao_condicaopagamento from ng_condicaopagamento a join mpd_tenant b on b.id = a.id_tenant where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_condicaopagamento''),',
'            p_formato => ''pequeno'',',
'            --p_icones => textarray(/*''fa-database'', ''fa-database'',*/ ''fa-user'', ''fa-calendar fam-clock fam-is-success'', ''fa-calendar fam-clock fam-is-warning'', ''fa-flag''),',
unistr('            --p_label_fixo => textarray(''Workspace'', ''Aplica\00E7\00F5es'', ''P\00E1ginas'', ''Usu\00E1rios APEX''),'),
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,                ',
'                a.numero_parcela titulo,',
'                (TO_CHAR(a.percentual, ''FM999G999G990D00'') || '' %'') distintivo,',
'                null lista_distintivo,',
'                null class_distintivo,',
'                null icon,   ',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_condicaopagamento_parcela.ind_evento_gerador_pagamento'', pkg_util.dominio_retorna_tag(''ng_condicaopagamento_parcela'',''ind_evento_gerador_pagamento'',ind_evento_gerador_pagamento)) atributo1,',
'',
'                --Order',
'                pkg_util.dominio_retorna_tag(''ng_condicaopagamento_parcela'',''ind_evento_gerador_pagamento'',ind_evento_gerador_pagamento) order1,',
'                qtd_dias_evento order2,',
'                percentual order3,',
'',
'                --FILTROS',
'                a.numero_parcela filtro1,',
'                a.percentual filtro2,',
'                null FILTRO_MULT1,                ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD367'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD367'') as opcao                ',
'            from ng_condicaopagamento_parcela a',
'            join ng_condicaopagamento b ON b.id = a.id_condicaopagamento',
'            where a.id_condicaopagamento = #PARAM1#',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'            l_sql := replace(l_sql, ''#PARAM1#'', '''''''' || p_param1 || '''''''');',
'            return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~        ',
'         select ',
'            a.id,                                                            ',
'            a.numero_parcela campo1,   ',
'            (TO_CHAR(percentual, ''FM999G999G990D00'') || '' %'') campo2,',
'            pkg_util.dominio_retorna_tag(''ng_condicaopagamento_parcela'',''ind_evento_gerador_pagamento'',ind_evento_gerador_pagamento) campo3,',
'            to_number(qtd_dias_evento) campo4,             ',
'            percentual campo5,             ',
'            null campo6,',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,                                ',
'            --FILTROS',
'            a.numero_parcela filtro1,                                ',
'            a.percentual filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_condicaopagamento_parcela a',
'        where a.id_condicaopagamento = #PARAM1#',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                to_number(campo1) campo1,              ',
'                campo2,',
'                campo3,',
'                to_number(campo4) campo4,              ',
'                to_number(campo5) campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD367'') as opcao  ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_condicaopagamento_parcela'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'       if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.numero_parcela'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.percentual'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.ind_evento_gerador_pagamento'') into l_campo from dual;',
'        elsif campo = ''4'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_condicaopagamento_parcela.qtd_dias_evento'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'    ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo5,campo3,campo4'';',
'        else',
'            campos := ''titulo,order3,atributo1,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'')',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''1'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo1'';',
'        else',
'            l_campos := ''titulo'';',
'        end if;',
'        l_direcoes := ''ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'',
'end "UI_MPD_TD367";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td335
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(235108438598735730)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD335'
,p_sequence=>3440
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD335" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'',
'end "UI_MPD_TD335";',
'/',
'',
'',
'',
'',
'',
'create or replace package body "UI_MPD_TD335" as',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            SELECT',
'                a.id,                                   ',
'				pkg_traducao.get_traducao(descricao_incoterm) titulo,',
'                b.nome_fantasia subtitulo,                  ',
'                a.codigo_incoterm distintivo,     ',
'                null lista_distintivo,',
'                to_date(a.data_fim_vigencia, ''dd/mm/yyyy''),',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_incoterm.data_inicio_vigencia'', pkg_data.fmtd(a.data_inicio_vigencia, ''DATA''), 6) atributo1,            ',
'                case ',
'                    when a.data_fim_vigencia is null then',
'                        null',
'                    when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                        pkg_componentes.html_card_colunas(''ng_incoterm.data_fim_vigencia'', ',
'                            pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''DATA'')), 6) ',
'                    else',
'                        pkg_componentes.html_card_colunas(''ng_incoterm.data_fim_vigencia'', pkg_data.fmtd(a.data_fim_vigencia, ''DATA''), 6) ',
'                end atributo2,',
'                --order',
'                a.data_inicio_vigencia order1,',
'                a.data_fim_vigencia order2,',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,',
'                --TECNICO  ',
'                pkg_ui.url_mais_detalhes(''TD335'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD335'') as opcao   ',
'            FROM ng_incoterm a',
'            join mpd_tenant b on b.id = a.id_tenant   ',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_param4,''2''));',
'            --order by 3, 4, 2, 6 nulls first',
'        return l_sql;',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := ''',
'        select',
'            a.id,',
'            b.nome_fantasia campo1,',
'            a.codigo_incoterm campo2,',
'	    	pkg_traducao.get_traducao(descricao_incoterm)   campo3,',
'            pkg_data.fmtd(a.data_inicio_vigencia, ''''DATA'''') campo4,',
'            case when to_date(a.data_fim_vigencia) < to_date(current_date) then',
'                pkg_componentes.html_cor_texto(pkg_data.fmtd(a.data_fim_vigencia, ''''DATA''''))',
'            else',
'                pkg_data.fmtd(a.data_fim_vigencia, ''''DATA'''')',
'            end campo5,',
'            null campo6,',
'            a.data_fim_vigencia campo7,',
'            null                campo8,',
'            null                campo9,',
'            null                campo10,',
'            --FILTROS',
'            a.id_tenant       filtro1,                                ',
'            null              filtro2,                                ',
'            null              filtro3,                                ',
'            null              filtro4,',
'            null              filtro5,                                ',
'            --FILTROS MULTI',
'            null              filtro_mult1,                                ',
'            null              filtro_mult2,                                ',
'            null              filtro_mult3, ',
'            null              filtro_mult4,                                ',
'            null              filtro_mult5,                                ',
'            null opcao',
'        FROM ng_incoterm a',
'        join mpd_tenant b on b.id = a.id_tenant',
'       '';',
'       return l_sql;',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql :=  q''~',
'            select       ',
'                id,         ',
'                campo1,',
'                campo2,',
'                campo3,',
'                to_date(campo4,''DD/MM/YYYY'') campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                to_date(campo7,''DD/MM/YYYY'')campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD335'') as opcao   ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_incoterm'')) a',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql,''#ORDER#'',nvl(p_order,''2''));',
'            -- ORDER BY',
'            --     campo1,',
'            --     campo2,',
'            --     campo3,',
'            --     to_date(campo7,''dd/mm/yyyy'') nulls first',
'',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin          ',
'        if campo = ''1'' then            ',
'            return q''~select nome_fantasia d, id r from mpd_tenant~'';        ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_incoterm.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then',
'            select pkg_ui.retorna_label_coluna(''ng_incoterm.codigo_incoterm'') into l_campo from dual;',
'        elsif campo = ''3'' then',
'            select pkg_ui.retorna_label_coluna(''ng_incoterm.descricao_incoterm'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_incoterm.data_inicio_vigencia'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_incoterm.data_fim_vigencia'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo4,campo7'';',
'        else',
'            campos := ''subtitulo,distintivo,titulo,order1,order2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'') ',
'        into labels',
'        from dual;',
'',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''5'') || '','' ||',
'        label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo7,campo1,campo3,campo2'';',
'        else',
'            l_campos := ''order2,subtitulo,titulo,distintivo'';',
'        end if;',
'        l_direcoes := ''DESC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
