prompt --application/deployment/install/install_ui_mpd_td548
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(235117555695114152)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD548'
,p_sequence=>3450
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'create or replace package "UI_MPD_TD548" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD548";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD548" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is           ',
'        l_html clob;',
'    begin                ',
unistr('        if p_param2 = ''TD600'' then -- TD600 = Pessoa f\00EDsica, TD312 = Pessoa jur\00EDdica'),
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select a.nome_abreviado from ng_pessoa_fisica a where a.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_fisica''),',
'                p_formato => ''pequeno'',                ',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        else',
'            l_html := pkg_util.ObterValoresDasColunas (',
'                p_consulta_sql => ''select a.nome_fantasia from ng_pessoa_juridica a where a.id = ''||p_param1,',
'                p_tabela => textarray(''ng_pessoa_juridica''),',
'                p_formato => ''pequeno'',',
'                p_tipo_label => ''coluna'',',
'                p_classe  => ''st-back-transparente''',
'            );',
'        end if;',
'        return l_html;',
'    end;',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_id_pessoa number;',
'        l_sql clob;        ',
'        l_condicao varchar2(4000);',
'    begin           ',
'        begin',
'            if p_param2 = ''TD600'' then',
'                select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_param1;',
'            else',
'                select id_pessoa into l_id_pessoa from ng_pessoa_juridica where id = p_param1;',
'            end if;',
'            l_condicao := '' b.id = ''||l_id_pessoa;',
'        exception',
'            when no_data_found then',
'               l_condicao := '' 1 = 1 '';',
'        end;',
'',
'        l_sql := q''~',
'            select distinct',
'                a.id,',
'                a.titulo_endereco titulo,                ',
'                null subtitulo,',
'                null distintivo,',
'                ''u-hidden'' class_distintivo,',
'                null lista_distintivo,                ',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_pessoa_endereco.ind_endereco_principal'', ',
'                    pkg_util.dominio_retorna_tag(''ng_pessoa_endereco'', ''ind_endereco_principal'', a.ind_endereco_principal), 6',
'                ) atributo1,',
'                --FILTROS                ',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes_com_parametro(''TD548'',a.id,b.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD548'', p_param1 => b.id) as opcao                ',
'            from ng_pessoa_endereco a',
'            join ng_pessoa b on b.id = a.id_pessoa',
'            where #CONDICAO# ',
'            order by #ORDER#',
'            ~'';',
'            --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            l_sql := replace(l_sql, ''#CONDICAO#'', l_condicao); ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_id_pessoa number;',
'        l_sql clob;',
'        l_condicao varchar2(4000);',
'    begin           ',
'        begin',
'            if p_param2 = ''TD600'' then',
'                select id_pessoa into l_id_pessoa from ng_pessoa_fisica where id = p_param1;',
'            else',
'                select id_pessoa into l_id_pessoa from ng_pessoa_juridica where id = p_param1;',
'            end if;',
'            l_condicao := '' b.id = ''||l_id_pessoa;',
'        exception',
'            when no_data_found then',
'               l_condicao := '' 1 = 1 '';',
'        end;',
'        l_sql := q''~',
'        select',
'            a.id id,',
'            a.titulo_endereco campo1,            ',
'            pkg_util.dominio_retorna_tag(''ng_pessoa_endereco'', ''ind_endereco_principal'', a.ind_endereco_principal) campo2,',
'            null campo3,',
'            null campo4,',
'            null campo5,',
'            null campo6,',
'            null campo7,',
'            null campo8,',
'            null campo9,',
'            null campo10,            ',
'            --FILTROS',
'            null filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            pkg_componentes.html_botao_opcao(p_id => a.id, p_pagina => ''TD548'', p_param1 => b.id) as opcao ',
'        from ng_pessoa_endereco a',
'        join ng_pessoa b on b.id = a.id_pessoa        ',
'        where #CONDICAO# ~'';',
'        l_sql := replace(l_sql, ''#CONDICAO#'', l_condicao);       ',
'        --l_sql := replace(l_sql, ''#PARAM1#'', p_param1);       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_pessoa_endereco'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));                ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null; ',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'        if campo = ''1'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.titulo_endereco'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_pessoa_endereco.ind_endereco_principal'') into l_campo from dual;',
'        end if;',
'        return l_campo;',
'    end label_coluna;       ',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo2,campo1'';',
'        else',
'            campos := ''atributo1,titulo'';',
'        end if;',
'',
'        select label_coluna(''2'') || '','' ||',
'        label_coluna(''1'') ',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''2'') || '','' ||',
'               label_coluna(''1'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo2,campo1'';',
'        else',
'            l_campos := ''atributo1,titulo'';',
'        end if; ',
'',
'        l_direcoes := ''DESC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD548";',
'/'))
);
end;
/
