'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD764";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD764" as',
'',
'    function sql_cabecalho(p_param1 in varchar2 default null, p_param2 in varchar2 default null, p_param3 in varchar2 default null)',
'    return clob is',
'        l_html clob;',
'    begin',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    pkg_traducao.get_traducao(a.descricao_listapreco) as descricao_listapreco,',
'                    b.codigo_moeda || '''' - '''' || pkg_traducao.get_traducao(b.descricao_moeda) as id_moeda',
'                from ng_listapreco a',
'                join ng_moeda b on b.id = a.id_moeda',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''ng_listapreco'',''ng_listapreco''),',
'            p_formato => ''pequeno'',',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        );',
'        return l_html;',
'    end;',
'    ',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,    ',
'                b.codigo_incoterm titulo,',
'                null distintivo,            ',
'                ''u-hidden'' class_distintivo,                           ',
'                null lista_distintivo, ',
'                --FILTROS',
'                null filtro1,',
'                null FILTRO_MULT1,',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD764'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD764'') as opcao                ',
'            from ng_listapreco_incoterm a',
'            join ng_incoterm b ON a.id_incoterm = b.id',
'            WHERE a.id_listapreco = #PARAM1#',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4,''1''));',
'            return l_sql;',
'        -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        select ',
'            a.id id,',
'            b.codigo_incoterm campo1,',
'            null campo2,            ',
'            null campo3,                          ',
'            null campo4,             ',
'            null campo5,             ',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,      ',
'            null campo10,  ',
'            --FILTROS',
'            null filtro1,                               ',
'            null filtro2,                               ',
'            null filtro3,                               ',
'            null filtro4,                               ',
'            null filtro5,',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,                               ',
'            null opcao',
'        from ng_listapreco_incoterm a',
'        join ng_incoterm b ON a.id_incoterm = b.id',
'        WHERE a.id_listapreco = #PARAM1#            ',
'       ~'';       ',
'       l_sql := replace(l_sql, ''#PARAM1#'', p_param1);',
'       return l_sql;',
'       -- return ''select null id, null titulo, null subtitulo, null distintivo, null icone, EMPTY_BLOB() imagem, null filtro1, null filtro2, null filtro3 from dual'';',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~                ',
'            select     ',
'                id,           ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD764'') as opcao ',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_listapreco_incoterm'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));        ',
'        return l_sql;',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        return null;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin       ',
'        if campo = ''1'' then',
'            select pkg_ui.retorna_label_coluna(''ng_listapreco_incoterm.id_incoterm'') into l_campo from dual;',
'        end if;       ',
'            return l_campo;',
'    end label_coluna;',
'    ',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1'';',
'        else',
'            campos := ''titulo'';',
'        end if;',
'',
'        select label_coluna(''1'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''1'') ',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo1'';',
'        else',
'            l_campos := ''titulo'';',
'        end if; ',
'',
'        l_direcoes := ''ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD764";',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td476
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(237730201955089218)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD476'
,p_sequence=>3480
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Data: 29/06/2026',
unistr('-- Motivo: Ajuste para nova ordena\00E7\00E3o dos campos'),
'-- Desenvolvedor: Winicius Pereira',
'-- Jira: ',
'',
'',
'',
'create or replace package "UI_MPD_TD476" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean;',
'',
'    function label_coluna(campo in varchar)',
'    return clob;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2);',
'',
'    procedure campos_ordenacao_default(p_card_ou_grid in varchar2, p_order out varchar2, p_json out clob);',
'',
'end "UI_MPD_TD476";',
'/',
'',
'',
'',
'create or replace package body "UI_MPD_TD476" as',
'',
'    function sql_card(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select distinct',
'                a.id,                ',
'                b.nome_fantasia titulo,   ',
'                d.descricao_sistema_externo subtitulo,',
'                c.nome_leitura distintivo,',
'                null lista_distintivo,',
'                null class_distintivo,',
'                null icon,   ',
'                --ATRIBUTOS',
'                pkg_componentes.html_card_colunas(''ng_depara.id_ng'', bo_ng_depara.retorna_referencia(a.id), 6) atributo1,',
'                pkg_componentes.html_card_colunas(''ng_depara.referencia_externa'', a.referencia_externa, 6) atributo2,                                ',
'                --FILTROS',
'                a.id_tenant filtro1,',
'                null FILTRO_MULT1,                ',
'                null FILTRO_MULT2,  ',
'                --TECNICO',
'                pkg_ui.url_mais_detalhes(''TD476'',a.id) url_mais_detalhes,',
'                pkg_componentes.html_botao_opcao(a.id,''TD476'') as opcao                ',
'            from ng_depara a',
'            left join mpd_tenant b on b.id = a.id_tenant',
'            left join srv_entidade c on c.id = a.id_tabela   ',
'            left join ng_sistemaexterno d on d.id = a.id_sistema_externo',
'            order by #ORDER#',
'            ~'';',
'            l_sql := replace(l_sql, ''#ORDER#'', nvl(p_param4, ''1''));            ',
'            return l_sql;        ',
'    end sql_card;',
'',
'    function sql_lista_oculta(p_param1 in varchar2 default '''',p_param2 in varchar2 default '''',p_param3 in varchar2 default '''',p_param4 in varchar2 default '''')',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'        ',
'         select ',
'            a.id id,                                                            ',
'            b.nome_fantasia campo1,   ',
'            d.descricao_sistema_externo campo2,',
'            c.nome_leitura campo3,                        ',
'            bo_ng_depara.retorna_referencia(a.id) campo4,',
'            a.referencia_externa campo5,',
'            null campo6,             ',
'            null campo7,             ',
'            null campo8,                                      ',
'            null campo9,                                      ',
'            null campo10,                                ',
'            --FILTROS',
'            a.id_tenant filtro1,                            ',
'            null filtro2,                                ',
'            null filtro3,                                ',
'            null filtro4,',
'            null filtro5,                                ',
'            --FILTROS MULTI',
'            null filtro_mult1,                                ',
'            null filtro_mult2,                                ',
'            null filtro_mult3, ',
'            null filtro_mult4,                                ',
'            null filtro_mult5,',
'            null opcao',
'        from ng_depara a',
'        left join mpd_tenant b on b.id = a.id_tenant',
'        left join srv_entidade c on c.id = a.id_tabela   ',
'        left join ng_sistemaexterno d on d.id = a.id_sistema_externo        ',
'       ~'';       ',
'       return l_sql;       ',
'    end sql_lista_oculta;',
'',
'    function sql_report(p_order in varchar2)',
'    return clob is',
'        l_sql clob;',
'    begin   ',
'        l_sql := q''~',
'            select    ',
'                id,            ',
'                campo1,',
'                campo2,',
'                campo3,',
'                campo4,              ',
'                campo5,              ',
'                campo6,              ',
'                campo7,',
'                campo8,',
'                campo9,',
'                campo10,                 ',
'                pkg_componentes.html_botao_opcao(a.id,''TD476'') as opcao',
'            from table(PKG_UI.pesquisa_facetada(:app_page_id, ''LISTA_CR'',''ng_depara'')) a',
'            order by #ORDER#',
'            ~'';',
'        l_sql := replace(l_sql, ''#ORDER#'', nvl(p_order,''1''));',
'        return l_sql;        ',
'    end sql_report;',
'',
'    function sql_filtro(campo in varchar2)',
'    return clob is',
'    begin',
'        if campo = ''1'' then',
'            return ''select nome_fantasia d, id r from mpd_tenant'';        ',
'        else',
'            return null;',
'        end if;',
'    end sql_filtro;',
'',
'    function sql_verifica_filtro(campo in varchar2)',
'    return boolean is',
'    begin',
'        if sql_filtro(campo) is null then',
'            return false;',
'        else',
'            return true;',
'        end if;    ',
'    end sql_verifica_filtro;    ',
'',
'    function label_coluna(campo in varchar)',
'    return clob is',
'        l_campo clob;',
'    begin  ',
'       if campo in (''1'', ''F1'') then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_depara.id_tenant'') into l_campo from dual;',
'        elsif campo = ''2'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_depara.id_sistema_externo'') into l_campo from dual;',
'        elsif campo = ''3'' then                     ',
'            select pkg_ui.retorna_label_coluna(''ng_depara.id_tabela'') into l_campo from dual;',
'        elsif campo = ''4'' then',
'            select pkg_ui.retorna_label_coluna(''ng_depara.id_ng'') into l_campo from dual;',
'        elsif campo = ''5'' then',
'            select pkg_ui.retorna_label_coluna(''ng_depara.referencia_externa'') into l_campo from dual;        ',
'        end if;',
'        return l_campo;',
'    end label_coluna;',
'',
'    procedure campos_ordenacao(p_card_ou_grid in varchar2,campos out varchar2,labels out varchar2) is',
'    begin',
'        if p_card_ou_grid = ''GRI'' then',
'            campos := ''campo1,campo2,campo3,campo4,campo5'';',
'        else',
'            campos := ''titulo,subtitulo,distintivo,atributo2,atributo2'';',
'        end if;',
'',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'') || '','' ||',
'        label_coluna(''5'')',
'        into labels',
'        from dual;',
'    end campos_ordenacao;  ',
'',
'    procedure campos_ordenacao_default(',
'        p_card_ou_grid in varchar2,',
'        p_order        out varchar2,',
'        p_json         out clob',
'    ) is',
'        l_campos   varchar2(4000);',
'        l_labels   varchar2(4000);',
'        l_direcoes varchar2(4000);',
'    begin',
'        select label_coluna(''1'') || '','' ||',
'        label_coluna(''3'') || '','' ||',
'        label_coluna(''2'') || '','' ||',
'        label_coluna(''4'')',
'        into l_labels',
'        from dual;',
'',
'        if p_card_ou_grid = ''GRI'' then',
'            l_campos := ''campo1,campo2,campo3,campo4'';',
'        else',
'            l_campos := ''titulo,subtitulo,distintivo,atributo2'';',
'        end if; ',
'',
'        l_direcoes := ''ASC,ASC,ASC,ASC'';',
'',
'        p_order := monta_order_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_direcoes => l_direcoes',
'        );',
'',
'        p_json := monta_json_campos_ordenacao(',
'            p_campos   => l_campos,',
'            p_labels   => l_labels,',
'            p_direcoes => l_direcoes',
'        );',
'    end campos_ordenacao_default;',
'',
'end "UI_MPD_TD476";',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_ng_localembarquedesembarque
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(237776720209449949)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'BO_NG_LOCALEMBARQUEDESEMBARQUE'
,p_sequence=>3490
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 07/07/2026',
'-- Motivo: Desenvolvimento nova regra para valida id_cidade quando id_pais = Brasil',
'-- Jira: PNG-453',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 06/07/2026',
unistr('-- Motivo: Inclus\00E3o da coluna codigo_internacional na fun\00E7\00E3o detalhe_registro'),
'-- Jira: PNG-453',
'',
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 30/06/2026',
unistr('-- Motivo: Inclus\00E3o da coluna codigo_internacional na entidade ng_localembarquedesembarque'),
'-- Jira: PNG-453',
'',
'create or replace package            bo_ng_localembarquedesembarque ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
'    -- Constantes e variaveis  ',
'    -- ',
'    v_old ng_localembarquedesembarque%rowtype;',
'    v_new ng_localembarquedesembarque%rowtype;',
'    v_pagina NUMBER; ',
'    v_data_alteracao ng_localembarquedesembarque.data_alteracao%TYPE;  ',
unistr('     -- Vari\00E1veis tempor\00E1rias para armazenar dados'),
'    v_messages pkg_mensagem.message_record_table;',
'    v_message pkg_mensagem.message_record;',
'    v_parametro pkg_mensagem.paramentros;',
'    v_alerta clob; ',
'    v_qtde_alerta number := 0; ',
'    v_informacao clob;',
'    v_qtde_informacao number := 0;     ',
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out ng_localembarquedesembarque.id%type',
'    );',
'    procedure grava(',
'        p_id in ng_localembarquedesembarque.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(  ',
'        p_id_tenant in ng_localembarquedesembarque.id_tenant%type,',
'        p_nome_local in ng_localembarquedesembarque.nome_local%type,',
'        p_ind_local in ng_localembarquedesembarque.ind_local%type,',
'        p_id_pais in ng_localembarquedesembarque.id_pais%type,',
'        p_id_cidade in ng_localembarquedesembarque.id_cidade%type,',
'        p_id_unidade_local_rfb in ng_localembarquedesembarque.id_unidade_local_rfb%type,',
'        p_codigo_internacional in ng_localembarquedesembarque.codigo_internacional%type,',
'        p_data_fim_vigencia in ng_localembarquedesembarque.data_fim_vigencia%type, ',
'        p_id out ng_localembarquedesembarque.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );   ',
'    procedure altera_registro(  ',
'        p_id_tenant in ng_localembarquedesembarque.id_tenant%type,',
'        p_nome_local in ng_localembarquedesembarque.nome_local%type,',
'        p_ind_local in ng_localembarquedesembarque.ind_local%type,',
'        p_id_pais in ng_localembarquedesembarque.id_pais%type,',
'        p_id_cidade in ng_localembarquedesembarque.id_cidade%type,',
'        p_id_unidade_local_rfb in ng_localembarquedesembarque.id_unidade_local_rfb%type,',
'        p_codigo_internacional in ng_localembarquedesembarque.codigo_internacional%type,',
'        p_data_fim_vigencia in ng_localembarquedesembarque.data_fim_vigencia%type, ',
'        p_id in ng_localembarquedesembarque.id%type, ',
'        p_data_alteracao in ng_localembarquedesembarque.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure copia_registro(  ',
'        p_id_tenant out ng_localembarquedesembarque.id_tenant%type,',
'        p_nome_local out ng_localembarquedesembarque.nome_local%type,',
'        p_ind_local out ng_localembarquedesembarque.ind_local%type,',
'        p_id_pais out ng_localembarquedesembarque.id_pais%type,',
