'    begin ',
'        if p_id_cidade is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_cidade''); ',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_cidade(p_id_cidade);',
