unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_localembarquedesembarque'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_localembarquedesembarque'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_localembarquedesembarque'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_localembarquedesembarque'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_localembarquedesembarque'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_localembarquedesembarque'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_localembarquedesembarque%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''nome_local'', p_rec.nome_local, true);',
'        apex_json.write(''ind_local'', p_rec.ind_local, true);',
'        apex_json.write(''id_pais'', p_rec.id_pais, true);',
'        apex_json.write(''id_cidade'', p_rec.id_cidade, true);',
'        apex_json.write(''id_unidade_local_rfb'', p_rec.id_unidade_local_rfb, true);',
'        apex_json.write(''codigo_internacional'', p_rec.codigo_internacional, true);',
'        apex_json.write(''data_fim_vigencia'', p_rec.data_fim_vigencia, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'     -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'       pkg_traducao.grava_traducao(v_new.nome_local,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.nome_local,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        bo_ng_traducaotexto.exclui_registros(',
'            p_nome_entidade => ''ng_localembarquedesembarque'',',
'            p_id_origem => v_old.id,',
'            p_encadeado => p_encadeado,',
'            p_sucesso => p_sucesso,',
'            p_messages => p_messages',
'        );',
'    end; ',
'    --',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o hook'),
'    -- ',
unistr('    -- Mover todo o bloco de valida\00E7\00F5es hook para dentro da parte customizada do fonte caso existe pelo menos UMA personaliza\00E7\00E3o'),
'    procedure hook_valida_id_tenant(p_id_tenant in ng_localembarquedesembarque.id_tenant%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_tenant;     ',
'',
'    procedure hook_valida_nome_local(p_nome_local in ng_localembarquedesembarque.nome_local%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_nome_local;     ',
'',
'    procedure hook_valida_ind_local(p_ind_local in ng_localembarquedesembarque.ind_local%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_ind_local;     ',
'',
'    procedure hook_valida_id_pais(p_id_pais in ng_localembarquedesembarque.id_pais%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_pais;     ',
'',
'    procedure hook_valida_id_cidade(p_id_cidade in ng_localembarquedesembarque.id_cidade%type) ',
'    is ',
'        l_verifica_existe_valor number;',
'    begin',
'        if v_new.id_pais = bo_mpd_configuracao_ng.retorna_id_pais_brasil(v_new.id_tenant) and p_id_cidade is null then',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_cidade''); ',
'            pkg_mensagem.mensagem_campo(',
'                p_codigo_mensagem => ''169'',',
'                p_nome_campo => ''id_cidade'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;',
'    end hook_valida_id_cidade;',
'',
'    procedure hook_valida_id_unidade_local_rfb(p_id_unidade_local_rfb in ng_localembarquedesembarque.id_unidade_local_rfb%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_id_unidade_local_rfb;',
'',
'    procedure hook_valida_codigo_internacional(p_codigo_internacional in ng_localembarquedesembarque.codigo_internacional%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_codigo_internacional;',
'',
'    procedure hook_valida_data_fim_vigencia(p_data_fim_vigencia in ng_localembarquedesembarque.data_fim_vigencia%type) ',
'    is ',
'    begin ',
'        null;',
'    end hook_valida_data_fim_vigencia;     ',
'    --',
unistr('    -- Fun\00E7\00F5es complementares'),
'    --',
'    function detalhe_registro (',
'        p_id in ng_localembarquedesembarque.id%type',
'    ) return varchar2 is',
'        l_sql clob;',
'        l_alias_1 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_tenant'');',
'        l_alias_2 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.nome_local'');',
'        l_alias_3 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.ind_local'');',
'        l_alias_4 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_pais'');',
'        l_alias_5 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_cidade'');',
'        l_alias_6 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.id_unidade_local_rfb'');',
'        l_alias_7 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.codigo_internacional'');',
'        l_alias_8 varchar2(4000) := pkg_ui.retorna_label_coluna(''ng_localembarquedesembarque.data_fim_vigencia'');',
'    begin',
'        l_sql := pkg_ui.campos_detalhes(''',
'            select ',
'                b.nome_fantasia as "#ALIAS_1#", ',
'                pkg_traducao.get_traducao(a.nome_local) as "#ALIAS_2#", ',
'                pkg_util.dominio_retorna_tag(''''ng_localembarquedesembarque'''', ''''ind_local'''', a.ind_local) as "#ALIAS_3#", ',
'                pkg_traducao.get_traducao(c.nome_pais) as "#ALIAS_4#", ',
'                pkg_traducao.get_traducao(d.nome_cidade) as "#ALIAS_5#", ',
'                pkg_traducao.get_traducao(descricao_unidade_local_rfb) as "#ALIAS_6#",',
'                codigo_internacional as "#ALIAS_7#",',
'                a.data_fim_vigencia as "#ALIAS_8#"',
'            from ng_localembarquedesembarque a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            left join ng_pais    c on c.id = a.id_pais',
'            left join ng_cidade  d on d.id = a.id_cidade',
'            left join ng_unidadelocalrfb e on e.id =a.id_unidade_local_rfb',
'            where a.id = ''||p_id, ''s'');',
'        ',
'        l_sql := replace(l_sql, ''#ALIAS_1#'', l_alias_1);',
'        l_sql := replace(l_sql, ''#ALIAS_2#'', l_alias_2);',
'        l_sql := replace(l_sql, ''#ALIAS_3#'', l_alias_3);',
'        l_sql := replace(l_sql, ''#ALIAS_4#'', l_alias_4);',
'        l_sql := replace(l_sql, ''#ALIAS_5#'', l_alias_5);',
'        l_sql := replace(l_sql, ''#ALIAS_6#'', l_alias_6);',
'        l_sql := replace(l_sql, ''#ALIAS_7#'', l_alias_7);',
'        l_sql := replace(l_sql, ''#ALIAS_8#'', l_alias_8);',
'        return l_sql;',
'    end detalhe_registro;',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_localembarquedesembarque;',
'/'))
);
end;
