prompt --application/deployment/install/install_ui_mpd_td516
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(237830042641605992)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD516'
,p_sequence=>3500
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 30/06/2026',
'-- Motivo: Desenvolvimento de funcionalidade para alterar data_coleta_local_origem_real',
'-- Jira: PEDITEM-327, PEDITEM-328, PEDITEM-329',
'',
'create or replace package "UI_MPD_TD516" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob;',
'    --',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null',
'    );',
'    --',
'    function label_acao ',
'    return varchar2;',
'    --',
'    procedure post(',
'        p_id       in number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'    --',
'end "UI_MPD_TD516";',
'/',
'',
'create or replace package body "UI_MPD_TD516" as',
'',
'    function sql_cabecalho(',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null, ',
'        p_param3 in varchar2 default null',
'    ) return clob is',
'        l_html clob;        ',
'    begin        ',
'        l_html := pkg_util.ObterValoresDasColunas (',
'            p_consulta_sql => ''',
'                select',
'                    a.num_invoice,',
'                    b.nome_fantasia id_exportador,',
'                    c.nome_fantasia id_importador,',
'                    pkg_util.dominio_retorna_tag(''''imp_invoice'''', ''''ind_status'''', a.ind_status) ind_status',
'                from imp_invoice a',
'                join ng_pessoa_juridica b on b.id_pessoa = a.id_exportador',
'                join ng_pessoa_juridica c on c.id_pessoa = a.id_importador',
'                where a.id = ''||p_param1,',
'            p_tabela => textarray(''imp_invoice'',''imp_invoice'',''imp_invoice'',''imp_invoice''),',
'            p_formato => ''pequeno'',                ',
'            p_tipo_label => ''coluna'',',
'            p_classe  => ''st-back-transparente''',
'        ) ||',
'        ''</br><div class="a-CardView-headerBody" style="padding: 0.5rem;">',
'            <h3 class="a-CardView-title">''||retorna_texto(''msg.166.l'')||''</h3></br>',
'            <h3 class="a-CardView-title" style="color: red;">''||retorna_texto(''msg.166.h'')||''</h3>',
'        </div>'';',
'        return l_html;',
'    end sql_cabecalho;',
'    --',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    ) is',
'    begin',
'        MERGE INTO temp_formulario tf',
'        USING (',
'            SELECT p_codigo_artefato AS codigo_artefato, ''data_coleta_local_origem_real'' AS nome_coluna, 1 AS indice, ''DAT'' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''N'' as coluna_tabela, null valor, ''imp_invoice.data_coleta_l'
||'ocal_origem_real'' tag_campo, ''s'' obrigatorio FROM dual',
'        ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, obrigatorio)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.obrigatorio);',
'    end formulario;',
'    --',
'    function label_acao ',
'    return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''confirma'');',
'    end label_acao;',
'    --',
'    procedure post(',
'        p_id       in number default null,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'    begin',
'        bo_imp_invoice.altera_data_coleta_local_origem_real(',
'            p_data_coleta_local_origem_real => apex_application.g_f01(1),',
'            p_id                            => p_id,',
'            p_sucesso                       => p_sucesso,',
'            p_messages                      => p_messages',
'        );',
'    end post;',
'    --',
'end "UI_MPD_TD516";',
'/'))
);
end;
/
prompt --application/deployment/install/install_bo_imp_naturezaoperacao_parametro
begin
