'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );',
'    procedure inclui_registro(  ',
'        p_id_tenant in imp_naturezaoperacao_parametro.id_tenant%type,',
'        p_id_naturezaoperacao in imp_naturezaoperacao_parametro.id_naturezaoperacao%type,',
'        p_id_cfop in imp_naturezaoperacao_parametro.id_cfop%type,',
'        p_ind_gera_contabil in imp_naturezaoperacao_parametro.ind_gera_contabil%type,',
'        p_ind_gera_financeiro in imp_naturezaoperacao_parametro.ind_gera_financeiro%type,',
'        p_ind_tipo_fatura in imp_naturezaoperacao_parametro.ind_tipo_fatura%type,',
'        p_ind_tipo_importacao in imp_naturezaoperacao_parametro.ind_tipo_importacao%type,',
'        p_ind_courrier in imp_naturezaoperacao_parametro.ind_courrier%type, ',
'        p_cst in imp_naturezaoperacao_parametro.cst%type,',
'        p_cclasstrib in imp_naturezaoperacao_parametro.cclasstrib%type,',
'        p_id out imp_naturezaoperacao_parametro.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    );   ',
'    procedure altera_registro(  ',
'        p_id_tenant in imp_naturezaoperacao_parametro.id_tenant%type,',
'        p_id_naturezaoperacao in imp_naturezaoperacao_parametro.id_naturezaoperacao%type,',
'        p_id_cfop in imp_naturezaoperacao_parametro.id_cfop%type,',
'        p_ind_gera_contabil in imp_naturezaoperacao_parametro.ind_gera_contabil%type,',
'        p_ind_gera_financeiro in imp_naturezaoperacao_parametro.ind_gera_financeiro%type,',
'        p_ind_tipo_fatura in imp_naturezaoperacao_parametro.ind_tipo_fatura%type,',
'        p_ind_tipo_importacao in imp_naturezaoperacao_parametro.ind_tipo_importacao%type,',
'        p_ind_courrier in imp_naturezaoperacao_parametro.ind_courrier%type, ',
'        p_cst in imp_naturezaoperacao_parametro.cst%type,',
'        p_cclasstrib in imp_naturezaoperacao_parametro.cclasstrib%type,',
'        p_id in imp_naturezaoperacao_parametro.id%type, ',
'        p_data_alteracao in imp_naturezaoperacao_parametro.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure copia_registro(  ',
'        p_id_tenant out imp_naturezaoperacao_parametro.id_tenant%type,',
'        p_id_naturezaoperacao out imp_naturezaoperacao_parametro.id_naturezaoperacao%type,',
'        p_id_cfop out imp_naturezaoperacao_parametro.id_cfop%type,',
'        p_ind_gera_contabil out imp_naturezaoperacao_parametro.ind_gera_contabil%type,',
'        p_ind_gera_financeiro out imp_naturezaoperacao_parametro.ind_gera_financeiro%type,',
'        p_ind_tipo_fatura out imp_naturezaoperacao_parametro.ind_tipo_fatura%type,',
'        p_ind_tipo_importacao out imp_naturezaoperacao_parametro.ind_tipo_importacao%type,',
'        p_ind_courrier out imp_naturezaoperacao_parametro.ind_courrier%type, ',
'        p_cst out imp_naturezaoperacao_parametro.cst%type,',
'        p_cclasstrib out imp_naturezaoperacao_parametro.cclasstrib%type,',
'        p_id in out imp_naturezaoperacao_parametro.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    procedure exclui_registro(  ',
'        p_id in imp_naturezaoperacao_parametro.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    ); ',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos padr\00E3o'),
