'    -- ',
'    procedure verifica_registro( ',
'        p_id in imp_naturezaoperacao.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_naturezaoperacao where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in imp_naturezaoperacao.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from imp_naturezaoperacao where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in imp_naturezaoperacao.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''imp_naturezaoperacao'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''imp_naturezaoperacao'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in imp_naturezaoperacao.data_alteracao%type ',
'    ) is ',
'    begi'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(240516271597433010)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'n ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo descricao */ '),
'        valida_descricao(v_new.descricao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo ind_situacao */ '),
'        valida_ind_situacao(v_new.ind_situacao);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_fim_vigencia */ '),
'        valida_data_fim_vigencia(v_new.data_fim_vigencia);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in imp_naturezaoperacao.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_descricao(p_descricao in imp_naturezaoperacao.descricao%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'',
'        if p_descricao is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.descricao''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''descricao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from imp_naturezaoperacao where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(descricao)) = lower(trim(v_new.descricao)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from imp_naturezaoperacao where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(descricao)) = lower(trim(v_new.descricao)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.descricao'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''descricao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_descricao(p_descricao);',
'    end valida_descricao;     ',
'',
'    procedure valida_ind_situacao(p_ind_situacao in imp_naturezaoperacao.ind_situacao%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_ind_situacao is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.ind_situacao''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''ind_situacao'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_ind_situacao(p_ind_situacao);',
'    end valida_ind_situacao;     ',
'',
'    procedure valida_data_fim_vigencia(p_data_fim_vigencia in imp_naturezaoperacao.data_fim_vigencia%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_data_fim_vigencia is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.data_fim_vigencia''); ',
'         else ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''imp_naturezaoperacao.data_fim_vigencia'');                         ',
'            pkg_util.valida_formato_data(',
'                p_data     => p_data_fim_vigencia,',
'                p_campo           => ''data_fim_vigencia'',',
'                p_parametro       => v_parametro,',
'                p_pagina          => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            if v_message.mensagem is not null then',
unistr('                -- Inserir o registro na cole\00E7\00E3o                '),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;                        ',
'            end if; ',
'',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_data_fim_vigencia(p_data_fim_vigencia);',
'    end valida_data_fim_vigencia;    ',
'',
