unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_naturezaoperacao'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_naturezaoperacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_naturezaoperacao'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_naturezaoperacao'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''imp_naturezaoperacao'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''imp_naturezaoperacao'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in imp_naturezaoperacao%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''descricao'', p_rec.descricao, true);',
'        apex_json.write(''ind_situacao'', p_rec.ind_situacao, true);',
'        apex_json.write(''data_fim_vigencia'', p_rec.data_fim_vigencia, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
'    function detalhe_registro (',
'        p_id in imp_naturezaoperacao.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select',
'                b.nome_fantasia as imp_naturezaoperacao$id_tenant,',
'                pkg_traducao.get_traducao(a.descricao) as imp_naturezaoperacao$descricao,',
'                pkg_traducao.get_traducao(c.descricao_cfop) as ng_cfop$descricao_cfop',
'            from imp_naturezaoperacao a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            join imp_naturezaoperacao_parametro d on d.id_naturezaoperacao = a.id',
'            left join ng_cfop c on c.id = d.id_cfop',
'            where a.id = ~'' || p_id);',
'    end detalhe_registro;',
'',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        if v_operacao = ''inclui_natureza_parametro'' then',
'            inclui_parametro(p_encadeado, p_sucesso, p_messages);',
'        end if;',
'        ',
'        pkg_traducao.grava_traducao(v_new.descricao,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        if v_operacao = ''altera_natureza_parametro'' then',
'            altera_parametro(p_encadeado, p_sucesso, p_messages);',
'        end if;',
'',
'        pkg_traducao.grava_traducao(v_new.descricao,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'',
'    procedure inclui_naturezaoperacao_parametro(',
'        p_id_tenant             in imp_naturezaoperacao.id_tenant%type,',
'        p_descricao             in imp_naturezaoperacao.descricao%type,',
'        p_data_fim_vigencia     in imp_naturezaoperacao.data_fim_vigencia%type,',
'        p_ind_situacao          in imp_naturezaoperacao.ind_situacao%type,',
'',
'        p_id_cfop              in imp_naturezaoperacao_parametro.id_cfop%type,',
'        p_ind_gera_contabil    in imp_naturezaoperacao_parametro.ind_gera_contabil%type,',
'        p_ind_gera_financeiro  in imp_naturezaoperacao_parametro.ind_gera_financeiro%type,',
'        p_ind_tipo_fatura      in imp_naturezaoperacao_parametro.ind_tipo_fatura%type,',
'        p_ind_tipo_importacao  in imp_naturezaoperacao_parametro.ind_tipo_importacao%type,',
'        p_ind_courrier         in imp_naturezaoperacao_parametro.ind_courrier%type,',
'        p_cst                  in imp_naturezaoperacao_parametro.cst%type,',
'        p_cclasstrib           in imp_naturezaoperacao_parametro.cclasstrib%type,',
'',
'        p_id         out imp_naturezaoperacao.id%type,',
'        p_pagina     in number default 0,',
'        p_encadeado  in boolean default false,',
'        p_sucesso    out clob,',
'        p_messages   out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        v_operacao := ''inclui_natureza_parametro'';',
'        v_parametro(0) := ''bo_imp_naturezaoperacao.inclui_natureza_parametro'';',
'        v_pagina := p_pagina;',
'',
'        -- IMP_NATUREZAOPERACAO',
'        v_new.id_tenant          := p_id_tenant;',
'        v_new.descricao          := p_descricao;',
'        v_new.data_fim_vigencia  := p_data_fim_vigencia;',
'        v_new.ind_situacao       := p_ind_situacao;',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_inclusao      := sysdate;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao     := sysdate;',
'        v_new.id                 := null;',
'',
'        -- PARAMETRO',
'        v_new_parametro.id_tenant             := p_id_tenant;',
'        v_new_parametro.id_naturezaoperacao   := null;',
'        v_new_parametro.id_cfop               := p_id_cfop;',
'        v_new_parametro.ind_gera_contabil     := p_ind_gera_contabil;',
'        v_new_parametro.ind_gera_financeiro   := p_ind_gera_financeiro;',
'        v_new_parametro.ind_tipo_fatura       := p_ind_tipo_fatura;',
'        v_new_parametro.ind_tipo_importacao   := p_ind_tipo_importacao;',
'        v_new_parametro.ind_courrier          := p_ind_courrier;',
'        v_new_parametro.cst                   := p_cst;',
'        v_new_parametro.cclasstrib            := p_cclasstrib;',
'        v_new_parametro.id_usuario_alterou    := pkg_util.retorna_id_usuario_logado;',
'        v_new_parametro.data_alteracao        := sysdate;',
'        v_new_parametro.id                    := null;',
'',
'        cria(p_encadeado, p_sucesso, p_messages, p_id);',
'        p_id := v_new_parametro.id;',
'    end inclui_naturezaoperacao_parametro;',
'    --',
'    procedure inclui_parametro(',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'        l_id imp_naturezaoperacao_parametro.id%type;',
'    begin',
'        bo_imp_naturezaoperacao_parametro.inclui_registro(',
'            p_id_tenant             => v_new_parametro.id_tenant,',
'            p_id_naturezaoperacao   => v_new.id,',
'            p_id_cfop               => v_new_parametro.id_cfop,',
'            p_ind_gera_contabil     => v_new_parametro.ind_gera_contabil,',
'            p_ind_gera_financeiro   => v_new_parametro.ind_gera_financeiro,',
'            p_ind_tipo_fatura       => v_new_parametro.ind_tipo_fatura,',
'            p_ind_tipo_importacao   => v_new_parametro.ind_tipo_importacao,',
'            p_ind_courrier          => v_new_parametro.ind_courrier,',
'            p_cst                   => v_new_parametro.cst,',
'            p_cclasstrib            => v_new_parametro.cclasstrib,',
'            p_id                    => l_id,',
'            p_encadeado             => false,',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'        v_new_parametro.id := l_id;',
'    end inclui_parametro;',
'    --',
'    procedure altera_naturezaoperacao_parametro(',
'        p_id_tenant             in imp_naturezaoperacao.id_tenant%type,',
'        p_descricao             in imp_naturezaoperacao.descricao%type,',
'        p_data_fim_vigencia     in imp_naturezaoperacao.data_fim_vigencia%type,',
'        p_ind_situacao          in imp_naturezaoperacao.ind_situacao%type,',
'',
'        p_id_cfop               in imp_naturezaoperacao_parametro.id_cfop%type,',
'        p_ind_gera_contabil     in imp_naturezaoperacao_parametro.ind_gera_contabil%type,',
'        p_ind_gera_financeiro   in imp_naturezaoperacao_parametro.ind_gera_financeiro%type,',
'        p_ind_tipo_fatura       in imp_naturezaoperacao_parametro.ind_tipo_fatura%type,',
'        p_ind_tipo_importacao   in imp_naturezaoperacao_parametro.ind_tipo_importacao%type,',
'        p_ind_courrier          in imp_naturezaoperacao_parametro.ind_courrier%type,',
'        p_cst                   in imp_naturezaoperacao_parametro.cst%type,',
'        p_cclasstrib            in imp_naturezaoperacao_parametro.cclasstrib%type,',
'',
'        p_id                    in imp_naturezaoperacao.id%type,',
'        p_data_alteracao        in imp_naturezaoperacao.data_alteracao%type,',
'',
'        p_encadeado             in boolean default false,',
'        p_sucesso               out clob,',
'        p_messages              out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_parametro imp_naturezaoperacao_parametro.id%type;',
'    begin',
'        v_operacao := ''altera_natureza_parametro'';',
'        v_data_alteracao := p_data_alteracao;',
'',
unistr('        -- procura o par\00E2metro'),
'        select id into l_id_parametro from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_id;',
'        -- Natureza',
'        select * into v_old from imp_naturezaoperacao where id = p_id;',
'        v_new := v_old;',
'',
'        v_new.id_tenant          := p_id_tenant;',
'        v_new.descricao          := p_descricao;',
'        v_new.data_fim_vigencia  := p_data_fim_vigencia;',
'        v_new.ind_situacao       := p_ind_situacao;',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado;',
'        v_new.data_alteracao     := sysdate;',
'',
unistr('        -- Par\00E2metro'),
'        v_new_parametro.id                   := l_id_parametro;',
'        v_new_parametro.id_tenant            := p_id_tenant;',
'        v_new_parametro.id_naturezaoperacao  := p_id;',
'        v_new_parametro.id_cfop              := p_id_cfop;',
'        v_new_parametro.ind_gera_contabil    := p_ind_gera_contabil;',
'        v_new_parametro.ind_gera_financeiro  := p_ind_gera_financeiro;',
'        v_new_parametro.ind_tipo_fatura      := p_ind_tipo_fatura;',
'        v_new_parametro.ind_tipo_importacao  := p_ind_tipo_importacao;',
'        v_new_parametro.ind_courrier         := p_ind_courrier;',
'        v_new_parametro.cst                  := p_cst;',
'        v_new_parametro.cclasstrib           := p_cclasstrib;',
'',
'        grava(p_id, p_encadeado, p_sucesso, p_messages);',
'    end altera_naturezaoperacao_parametro;',
'    --',
'    procedure altera_parametro(',
'        p_encadeado in boolean default false,',
'        p_sucesso   out clob,',
'        p_messages  out pkg_mensagem.message_record_table',
'    ) is',
'    begin',
'        bo_imp_naturezaoperacao_parametro.altera_registro(',
'            p_id_tenant               => v_new_parametro.id_tenant,',
'            p_id_naturezaoperacao     => v_new.id,',
'            p_id_cfop                 => v_new_parametro.id_cfop,',
'            p_ind_gera_contabil       => v_new_parametro.ind_gera_contabil,',
'            p_ind_gera_financeiro     => v_new_parametro.ind_gera_financeiro,',
'            p_ind_tipo_fatura         => v_new_parametro.ind_tipo_fatura,',
'            p_ind_tipo_importacao     => v_new_parametro.ind_tipo_importacao,',
'            p_ind_courrier            => v_new_parametro.ind_courrier,',
'            p_cst                     => v_new_parametro.cst,',
'            p_cclasstrib              => v_new_parametro.cclasstrib,',
'            p_data_alteracao          => null,',
'            p_id                      => v_new_parametro.id,',
'            p_encadeado               => false,',
'            p_sucesso                 => p_sucesso,',
'            p_messages                => p_messages',
'        );',
'    end altera_parametro;',
'    ',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_imp_naturezaoperacao;',
'/'))
);
end;
