||' imp_naturezaoperacao a join imp_naturezaoperacao_parametro b on b.id_naturezaoperacao = a.id where b.id = p_param1)) valor, ''S'' obrigatorio FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',       2, ''SEL'', ''R_MPD_TENANT.DESCRICAO_IDIOMA'', ''S'',''N'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao'',               3, ''TXT'', NULL, ''N'', ''N'',   to_char((select a.descricao from imp_naturezaoperacao a join imp_naturezaoperacao_parametro b on b.id_naturezaoperacao = a.id where b.id = p_param1)) valo'
||'r, ''S'' obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cst'',                     4, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cfop'',                 5, '''',    NULL, ''N'', ''S'', null valor, ''S'' obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cclasstrib'',              7, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_gera_contabil'',       8, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_gera_financeiro'',     9, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_fatura'',        10, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_importacao'',    12, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_courrier'',           14, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',         16, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_situacao'',           18, ''HID'', null, ''S'',''N'', to_char((select a.ind_situacao from imp_naturezaoperacao a join imp_naturezaoperacao_parametro b on b.id_naturezaoperacao = a.id where b.id = p_param1)) valo'
||'r, ''N'' obrigatorio FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naturezaoperacao'',    26, ''HID'', NULL, ''S'', ''S'', to_char((select a.id from imp_naturezaoperacao a join imp_naturezaoperacao_parametro b on b.id_naturezaoperacao = a.id where b.id = p_param1)) valor, null o'
||'brigatorio FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
