'            p_ind_gera_contabil    => apex_application.g_f08(1),',
'            p_ind_gera_financeiro  => apex_application.g_f09(1),',
'            p_ind_tipo_fatura      => apex_application.g_f10(1),',
'            p_ind_tipo_importacao  => apex_application.g_f12(1),',
'            p_ind_courrier         => apex_application.g_f14(1),',
'            p_cst                  => apex_application.g_f04(1),',
'            p_cclasstrib           => apex_application.g_f07(1),',
'            p_data_alteracao       => TO_TIMESTAMP(apex_application.g_f16(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id                   => apex_application.g_f26(1),',
