,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD658" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD658";',
'/',
'create or replace package body "UI_MPD_TD658" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is    ',
'        l_id_entidade number;',
'        l_id_chave varchar2(50) := ''P''||apex_util.get_session_state(''APP_PAGE_ID'')||''_ID'';',
'        l_id_coluna number;',
'        l_descricao clob;',
'        l_permite_edicao_descricao_item varchar2(5);',
'        l_erro_descricao_item clob;',
'        l_somente_leitura varchar2(1);        ',
'        l_url varchar2(4000);',
'        v_executa_js_maxlength clob;',
'    begin        ',
'        -- Manter tamanho do campo cclasstrib em 6 caracteres:',
'        v_executa_js_maxlength := q''~$("#CCLASSTRIB").attr("maxlength", 6);~'';',
'',
'        select id into l_id_entidade from mpd_entidade where lower(nome_entidade) = ''imp_naturezaoperacao'';',
'        select id into l_id_coluna from mpd_entidade_coluna where id_entidade = l_id_entidade and lower(nome_coluna) = ''descricao'';',
'',
'        if lower(l_permite_edicao_descricao_item) = ''false'' then',
'            l_somente_leitura:= ''S'';',
'        else',
'            l_somente_leitura := ''N'';',
'        end if;',
'',
'         l_url := apex_page.get_url(',
'            p_page => 9005, ',
'            p_items => ''P0_CODIGO_ARTEFATO,P9005_CODIGO_ARTEFATO,P9005_PARAMETRO,P9005_PARAMETRO2'', ',
'            p_values => ''TD537,TD537,''||p_param1||'',''||l_id_coluna, ',
'            p_clear_cache => 9005,',
'            p_plain_url => true',
'        );               ',
'    ',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''S'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null obrigatorio, nu'
||'ll tag_campo, null executa_js FROM dual UNION ALL                              ',
'               SELECT p_codigo_artefato, ''descricao'',                      3, '''', l_url, l_somente_leitura, ''S'', to_char((select pkg_traducao.get_traducao(descricao) from imp_naturezaoperacao where id = p_param1)) valor, null obrigatorio, null tag_ca'
||'mpo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''cst'',                            4, ''SEL'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.CST'', ''N'', ''N'', to_char((select cst from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, ''S'' obrigator'
||'io, ''IMP_NATUREZAOPERACAO_PARAMETRO.CST'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_cfop'',                        5, ''POP'', ''R_NG_CFOP.CODIGO_CFOP-DESCRICAO_CFOP'', ''N'', ''N'', to_char((select id_cfop from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, null obri'
||'gatorio, ''NG_CFOP.CODIGO_CFOP'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''CCLASSTRIB'',                     7, ''TXT'', null, ''N'', ''N'', to_char((select cclasstrib from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_P'
||'ARAMETRO.CCLASSTRIB'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_gera_contabil'',              8, ''RAD'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_CONTABIL'', ''N'', ''N'', to_char((select ind_gera_contabil from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_p'
||'aram1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_CONTABIL'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_gera_financeiro'',            9, ''RAD'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_FINANCEIRO'', ''N'', ''N'', to_char((select ind_gera_financeiro from imp_naturezaoperacao_parametro where id_naturezaoperacao ='
||' p_param1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_GERA_FINANCEIRO'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_fatura'',               10, ''SEL'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_FATURA'', ''N'', ''N'', to_char((select ind_tipo_fatura from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param'
||'1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_FATURA'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_tipo_importacao'',           12, ''SEL'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_IMPORTACAO'', ''N'', ''N'', to_char((select ind_tipo_importacao from imp_naturezaoperacao_parametro where id_naturezaoperacao ='
||' p_param1)) valor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_TIPO_IMPORTACAO'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''ind_courrier'',                  14, ''RAD'', ''D_IMP_NATUREZAOPERACAO_PARAMETRO.IND_COURRIER'', ''N'', ''N'', to_char((select ind_courrier from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) va'
||'lor, ''S'' obrigatorio, ''IMP_NATUREZAOPERACAO_PARAMETRO.IND_COURRIER'' tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',             20, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',                16, '''', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao_parametro'',      21, ''HID'', null, ''N'', ''N'', to_char((select data_alteracao from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1), ''dd-mon-rr hh:mi:ss.ff6 am'') valor, null ob'
||'rigatorio, null tag_campo, null executa_js FROM dual union all',
'               SELECT p_codigo_artefato, ''ind_situacao'',                  18, ''HID'', null, ''N'', ''S'', null valor, null obrigatorio, null tag_campo, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naturezaoperacao'',           26, ''HID'', null, ''N'', ''N'', to_char((select id_naturezaoperacao from imp_naturezaoperacao_parametro where id_naturezaoperacao = p_param1)) valor, null obrigatorio, null tag_camp'
||'o, null executa_js FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''TAMANHO_CCLASSTRIB'',            99, ''HID'', null, ''N'', ''N'', null valor, null obrigatorio, null tag_campo, v_executa_js_maxlength executa_js FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN ',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, tag_campo, executa_js)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.tag_campo, new_data'
||'.executa_js);',
'    end formulario;',
'',
'    procedure post(',
'        p_id in number default null,        ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is        ',
'    begin',
'        bo_imp_naturezaoperacao.altera_naturezaoperacao_parametro(',
'            p_id_tenant            => apex_application.g_f01(1),',
'            p_descricao            => apex_application.g_f03(1),',
'            p_data_fim_vigencia    => apex_application.g_f20(1),',
'            p_ind_situacao         => apex_application.g_f18(1),',
'            p_id_cfop              => apex_application.g_f05(1),',
'            p_ind_gera_contabil    => apex_application.g_f08(1),',
'            p_ind_gera_financeiro  => apex_application.g_f09(1),',
'            p_ind_tipo_fatura      => apex_application.g_f10(1),',
'            p_ind_tipo_importacao  => apex_application.g_f12(1),',
'            p_ind_courrier         => apex_application.g_f14(1),',
'            p_cst                  => apex_application.g_f04(1),',
'            p_cclasstrib           => apex_application.g_f07(1),',
'            p_data_alteracao       => TO_TIMESTAMP(apex_application.g_f16(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id                   => apex_application.g_f26(1),',
'            p_sucesso              => p_sucesso,',
'            p_messages             => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD658";',
'/'))
);
end;
