,p_sequence=>3550
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "UI_MPD_TD730" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null);',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'end "UI_MPD_TD730";',
'/',
'create or replace package body "UI_MPD_TD730" as',
'',
'    procedure formulario(p_codigo_artefato in varchar2, p_param1 in varchar2 default null, p_param2 in varchar2 default null) is',
'        l_url_id_familia_item varchar2(4000);',
'        l_url_id_unidade_medida varchar2(4000);',
'    begin',
'        l_url_id_familia_item := apex_page.get_url(',
'            p_page => 9010,',
'            p_items => ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO'',',
'            p_values => ''TD494,TD494'',',
'            p_clear_cache => 9010);',
'',
'        l_url_id_unidade_medida := apex_page.get_url(',
'            p_page => 9010,',
'            p_items => ''P0_CODIGO_ARTEFATO,P9010_CODIGO_ARTEFATO'',',
'            p_values => ''TD553,TD553'',',
'            p_clear_cache => 9010);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, ''SEL'' AS tipo_interacao, ''R_MPD_TENANT.RAZAO_SOCIAL'' AS nome_consulta, ''N'' AS somente_leitura, ''N'' as coluna_tabela, to_char((select a.id_tenant from'
||' ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, ''S'' obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',       2, ''SEL'', ''R_MPD_TENANT.DESCRICAO_IDIOMA'', ''S'',''N'', null valor, null obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_item'',             3, ''TXT'', NULL, ''N'', ''N'', to_char((select a.codigo_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, ''S'' obrigatorio, null url, null id_'
||'artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_item'',          4, ''TEX'', NULL, ''N'', ''N'', to_char((select a.descricao_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, ''S'' obrigatorio, null url, null '
||'id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_unidademedida'',        5, ''POP'', ''R_NG_UNIDADEMEDIDA.CODIGO_UNIDADEMEDIDA_-_SEM_NULO'', ''N'', ''N'', to_char((select a.id_unidademedida from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = '
||'p_param1)) valor, ''S'' obrigatorio, l_url_id_unidade_medida url, 5865 id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_barra'',            8, ''TXT'', NULL, ''N'', ''N'', to_char((select a.codigo_barra from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, null obrigatorio, null url, null i'
||'d_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_familia_item'',         9, ''POP'', ''R_NG_ITEM.DESCRICAO_FAMILIA_ITEM'', ''N'', ''N'', to_char((select a.id_familia_item from ng_item a join ng_item_embalagem b on b.id_item = a.id where b.id = p_param1)) valor, n'
||'ull obrigatorio, l_url_id_familia_item url, 5825 id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_ncm'',                 11, '''',    NULL, ''N'', ''S'', null valor, ''S'' obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_naladi'',              13, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_embalagem_siscomex'',  15, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''codigo_embalagem_cod'',   16, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''data_alteracao'',         25, '''',    NULL, ''N'', ''S'', null valor, null obrigatorio, null url, null id_artefato_versionado_zoom FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id'',           26, ''HID'', NULL, ''S'', ''S'', p_param1 valor, null obrigatorio, null url, null id_artefato_versionado_zoom FROM dual',
'               ) new_data',
'        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)',
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, obrigatorio, url, id_artefato_versionado_zoom)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.obrigatorio, new_data.url, new_data.id_ar'
||'tefato_versionado_zoom);',
'    end formulario;',
'',
'    procedure post_create(',
'        p_id out number,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        bo_ng_item.inclui_item_embalagem(',
'            p_id_tenant             => apex_application.g_f01(1),',
'            p_codigo_item           => apex_application.g_f03(1),',
'            p_descricao_item        => apex_application.g_f04(1),',
'            p_id_unidademedida      => apex_application.g_f05(1),',
'            p_codigo_barra          => apex_application.g_f08(1),',
'            p_id_familia_item       => apex_application.g_f09(1),',
'            p_id_ncm                => apex_application.g_f11(1),',
'            p_id_naladi             => apex_application.g_f13(1),',
'            p_id_embalagem_siscomex => apex_application.g_f15(1),',
'            p_codigo_embalagem_cod  => apex_application.g_f16(1),',
'            p_peso                  => null,',
'            p_altura                => null,',
'            p_largura               => null,',
'            p_profundidade          => null,',
'            p_volume                => null,',
'            p_id                    => p_id,',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'    end;',
'',
'    procedure post_save(',
'        p_id in number default null,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        bo_ng_item.altera_item_embalagem(',
'            p_id_tenant             => apex_application.g_f01(1),',
'            p_codigo_item           => apex_application.g_f03(1),',
'            p_descricao_item        => apex_application.g_f04(1),',
'            p_id_unidademedida      => apex_application.g_f05(1),',
'            p_codigo_barra          => apex_application.g_f08(1),',
'            p_id_familia_item       => apex_application.g_f09(1),',
'            p_id_ncm                => apex_application.g_f11(1),',
'            p_id_naladi             => apex_application.g_f13(1),',
'            p_id_embalagem_siscomex => apex_application.g_f15(1),',
'            p_codigo_embalagem_cod  => apex_application.g_f16(1),',
'            p_peso                  => null,',
'            p_altura                => null,',
'            p_largura               => null,',
'            p_profundidade          => null,',
'            p_volume                => null,',
'            p_data_fim_vigencia     => null,',
'            p_data_alteracao        => TO_TIMESTAMP(apex_application.g_f25(1), ''DD-MON-RR HH:MI:SS.FF AM''),',
'            p_id                    => p_id,',
'            p_sucesso               => p_sucesso,',
'            p_messages              => p_messages',
'        );',
'    end;',
'',
'end "UI_MPD_TD730";',
'/'))
);
end;
/
prompt --application/deployment/install/install_imp_invoice_ai_import_pkg
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(243453757220529151)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'IMP_INVOICE_AI_IMPORT_PKG'
,p_sequence=>3560
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package imp_invoice_ai_import_pkg as',
'  /*',
'    Package: IMP_INVOICE_AI_IMPORT_PKG',
'',
'    Objetivo',
'    --------',
'    Importar o JSON gerado pela OpenAI para as tabelas IMP_INVOICE e',
'    IMP_INVOICE_ITEM, resolvendo antes os IDs internos do SaaS sempre que',
'    houver dados suficientes no JSON.',
'',
'    Filosofia de importacao',
'    -----------------------',
'    1. IDs informados no JSON tem prioridade, mas sao validados por tenant.',
'    2. Quando o ID nao vem informado, a package tenta resolver por codigo,',
'       descricao ou nome extraido.',
'    3. Quando uma referencia nao pode ser encontrada, ou quando ha mais de',
'       um candidato, a package nao inventa ID: registra um gap no JSON de',
'       retorno.',
'    4. Se existir qualquer gap de severidade ERROR, nenhum insert e feito.',
'    5. A transacao fica sob controle do chamador. Use p_commit_yn => ''S''',
'       apenas quando desejar commit dentro da package.',
'',
'    Requisitos',
'    ----------',
'    Oracle com suporte a JSON_VALUE, JSON_TABLE, JSON_OBJECT_T e JSON_ARRAY_T.',
'    Em APEX, chame IMPORT_JSON a partir de um processo PL/SQL.',
'  */',
'',
'  function validate_json(',
'    p_json in clob',
'  ) return clob;',
'',
'  function payment_terms_key(p_value in varchar2) return varchar2;',
'',
'  function import_json(',
'    p_json             in clob,',
'    p_validate_only_yn in varchar2 default ''N'',',
'    p_commit_yn        in varchar2 default ''N''',
'  ) return clob;',
'',
'  function import_page_429(',
'    p_id_tenant                  in imp_invoice.id_tenant%type,',
'    p_id_processoimportacao      in imp_invoice.id_processoimportacao%type,',
'    p_id_pedidoimportacao        in number default null,',
'    p_num_invoice                in imp_invoice.num_invoice%type,',
'    p_data_invoice               in imp_invoice.data_invoice%type,',
'    p_ind_status                 in imp_invoice.ind_status%type,',
'    p_id_exportador              in imp_invoice.id_exportador%type,',
'    p_id_importador              in imp_invoice.id_importador%type,',
'    p_id_adquirente              in imp_invoice.id_adquirente%type default null,',
'    p_id_condicaopagamento       in imp_invoice.id_condicaopagamento%type,',
'    p_id_incoterm                in imp_invoice.id_incoterm%type,',
'    p_id_moeda                   in imp_invoice.id_moeda%type,',
'    p_peso_liquido               in imp_invoice.peso_liquido%type default null,',
'    p_peso_bruto                 in imp_invoice.peso_bruto%type default null,',
'    p_valor_total_mercadoria     in imp_invoice.valor_total_mercadoria%type default null,',
'    p_valor_desconto             in imp_invoice.valor_desconto%type default null,',
'    p_valor_despesa_invoice      in imp_invoice.valor_despesa_invoice%type default null,',
'    p_valor_total_cond_venda     in imp_invoice.valor_total_condicao_venda%type default null,',
'    p_valor_invoice_informado    in imp_invoice.valor_invoice_informado%type default null,',
'    p_nome_exportador            in varchar2 default null,',
'    p_doc_exportador             in varchar2 default null,',
'    p_nome_importador            in varchar2 default null,',
'    p_doc_importador             in varchar2 default null,',
'    p_nome_adquirente            in varchar2 default null,',
'    p_codigo_incoterm            in varchar2 default null,',
'    p_codigo_moeda               in varchar2 default null,',
'    p_desc_condpagto             in varchar2 default null,',
'    p_num_pedido_importacao      in varchar2 default null,',
'    p_referencia_pedido_original in varchar2 default null,',
'    p_id_usuario_incluiu         in number default null,',
'    p_validate_only_yn           in varchar2 default ''N'',',
'    p_commit_yn                  in varchar2 default ''N''',
'  ) return clob;',
'',
'function parse_date(p_value in varchar2) return date;',
'',
'end imp_invoice_ai_import_pkg;',
'/',
'',
'create or replace package body imp_invoice_ai_import_pkg as',
'  subtype t_yn is varchar2(1);',
'',
'  type t_invoice_ctx is record (',
'    id_tenant              number,',
'    id_usuario_incluiu     number,',
'    id_processoimportacao  number,',
'    num_invoice            varchar2(40),',
'    data_invoice_txt       varchar2(30),',
'    data_invoice           date,',
'    ind_status             number,',
'    id_pedidoimportacao_json number,',
'    numero_pedido_importacao varchar2(100),',
'    rotulo_referencia_pedido varchar2(100),',
'    id_exportador_json     number,',
'    nome_exportador        varchar2(150),',
'    doc_exportador         varchar2(100),',
'    id_importador_json     number,',
'    nome_importador        varchar2(150),',
'    doc_importador         varchar2(100),',
'    id_adquirente_json     number,',
'    nome_adquirente        varchar2(150),',
'    doc_adquirente         varchar2(100),',
'    id_condpagto_json      number,',
'    desc_condpagto         varchar2(100),',
'    id_incoterm_json       number,',
'    codigo_incoterm        varchar2(3),',
'    id_moeda_json          number,',
'    codigo_moeda           varchar2(3),',
'    ind_forma_pagamento    number,',
'    peso_liquido           number,',
'    peso_bruto             number,',
'    valor_total_mercadoria number,',
'    valor_desconto         number,',
'    valor_despesa_invoice  number,',
'    valor_total_cond_venda number,',
'    valor_invoice_informado number,',
'    valor_compensado       number,',
'    valor_total_financeiro number,',
'    ind_situacao_titulo    varchar2(1),',
'    ind_divergencia        varchar2(1),',
'    ind_tratamento_saldo   varchar2(1),',
'    motivo_desconto        varchar2(400)',
'  );',
'',
'  type t_resolved_invoice is record (',
'    id_pedidoimportacao    number,',
'    id_exportador          number,',
'    id_importador          number,',
'    id_adquirente          number,',
'    id_condicaopagamento   number,',
'    id_incoterm            number,',
'    id_moeda               number',
'  );',
'',
'  type t_match_result is record (',
'    id_resolvido      number,',
'    score             number,',
'    status            varchar2(30),',
'    metodo            varchar2(50),',
'    valor_extraido    varchar2(4000),',
'    valor_encontrado  varchar2(4000)',
'  );',
'',
'  type t_item_rec is record (',
'    item_index             number,',
'    sequencia_item_invoice number,',
'    id_entrega_json        number,',
'    referencia_entrega     varchar2(100),',
'    id_entrega_item_json   number,',
'    referencia_entrega_item varchar2(100),',
'    id_item_json           number,',
'    codigo_item            varchar2(100),',
'    descricao_item         varchar2(5000),',
'    id_ncm_json            number,',
'    codigo_ncm             varchar2(20),',
'    id_unidademedida_json  number,',
'    codigo_unidademedida   varchar2(20),',
'    quantidade             number,',
'    peso_unitario          number,',
'    peso_liquido_total     number,',
'    peso_bruto_unitario    number,',
'    peso_bruto_total       number,',
'    valor_unitario         number,',
'    valor_desconto         number,',
'    valor_total_cond_venda number,',
'    valor_total_desc_item  number,',
'    valor_total_mercadoria number,',
'    valor_total_desp_item  number,',
'    id_fabricante_json     number,',
'    nome_fabricante        varchar2(150),',
'    id_pais_origem_json    number,',
'    codigo_pais_origem     varchar2(10),',
'    nome_pais_origem       varchar2(100),',
'    id_entrega             number,',
'    id_entrega_item        number,',
'    id_item                number,',
'    id_ncm                 number,',
'    id_unidademedida       number,',
'    id_fabricante          number,',
'    id_pais_origem         number',
'  );',
'',
'  type t_item_tab is table of t_item_rec index by pls_integer;',
'',
'  function yn_is_true(p_value in varchar2) return boolean is',
'  begin',
'    return upper(nvl(trim(p_value), ''N'')) in (''S'', ''Y'', ''1'', ''TRUE'');',
'  end yn_is_true;',
'',
'  function clean_text(p_value in varchar2) return varchar2 is',
'  begin',
'    return upper(regexp_replace(trim(p_value), ''\s+'', '' ''));',
'  end clean_text;',
'',
'  function clean_code(p_value in varchar2) return varchar2 is',
'  begin',
'    return upper(trim(p_value));',
'  end clean_code;',
'',
'  function only_digits(p_value in varchar2) return varchar2 is',
'  begin',
'    return regexp_replace(nvl(p_value, ''''), ''[^0-9]'', '''');',
'  end only_digits;',
'',
'  function confidence_status(p_score in number) return varchar2 is',
'  begin',
'    if nvl(p_score, 0) = 0 then',
'      return ''NAO_ENCONTRADO'';',
'    elsif p_score >= 95 then',
'      return ''CONFIRMADO'';',
'    elsif p_score >= 70 then',
'      return ''ALTA_CONFIANCA'';',
'    elsif p_score >= 40 then',
'      return ''MEDIA_CONFIANCA'';',
'    else',
'      return ''BAIXA_CONFIANCA'';',
'    end if;',
'  end confidence_status;',
'',
'  function make_match(',
'    p_id_resolvido     in number,',
'    p_score            in number,',
'    p_metodo           in varchar2,',
'    p_valor_extraido   in varchar2,',
'    p_valor_encontrado in varchar2',
'  ) return t_match_result is',
'    l_match t_match_result;',
'  begin',
'    l_match.id_resolvido := p_id_resolvido;',
'    l_match.score := least(greatest(nvl(round(p_score), 0), 0), 100);',
'    l_match.status := confidence_status(l_match.score);',
'    l_match.metodo := p_metodo;',
'    l_match.valor_extraido := p_valor_extraido;',
'    l_match.valor_encontrado := p_valor_encontrado;',
'    return l_match;',
'  end make_match;',
'',
'  procedure put_confidence(',
'    p_confidence in out nocopy json_object_t,',
'    p_key        in varchar2,',
'    p_match      in t_match_result',
'  ) is',
'    l_obj json_object_t := json_object_t();',
'  begin',
'    l_obj.put(''id_resolvido'', p_match.id_resolvido);',
'    l_obj.put(''score'', nvl(p_match.score, 0));',
'    l_obj.put(''status'', nvl(p_match.status, ''NAO_ENCONTRADO''));',
'    l_obj.put(''metodo'', p_match.metodo);',
'    l_obj.put(''valor_extraido'', p_match.valor_extraido);',
'    l_obj.put(''valor_encontrado'', p_match.valor_encontrado);',
'    p_confidence.put(p_key, l_obj);',
'  end put_confidence;',
'',
'  function text_similarity_score(',
'    p_source    in varchar2,',
'    p_candidate in varchar2',
'  ) return number is',
'  begin',
'    if p_source is null or p_candidate is null then',
'      return 0;',
'    end if;',
'',
'    return least(greatest(nvl(round(calcular_similaridade_texto(p_source, p_candidate)), 0), 0), 100);',
'  exception',
'    when others then',
'      return 0;',
'  end text_similarity_score;',
'',
'  function is_person_name_search_token(p_token in varchar2) return boolean is',
'    l_token varchar2(100) := upper(trim(p_token));',
'  begin',
'    return length(l_token) >= 4',
'       and l_token not in (',
'         ''LTDA'', ''LTD'', ''LIMITADA'', ''COMPANY'', ''COMPANHIA'', ''CORP'', ''CORPORATION'',',
'         ''INC'', ''IND'', ''INDUSTRIA'', ''INDUSTRIAL'', ''COMERCIO'', ''IMPORTACAO'',',
'         ''EXPORTACAO'', ''EXPORTACION'', ''IMPORTADORA'', ''EXPORTADORA'',',
'         ''SOCIEDAD'', ''ANONIMA'', ''SOCIEDADE'', ''ANONIMO'', ''GROUP'', ''GRUPO'',',
'         ''COMPLEX'', ''COMPLEXO''',
'       );',
'  end is_person_name_search_token;',
'',
'  function payment_terms_key(p_value in varchar2) return varchar2 is',
'    l_value varchar2(4000);',
'    l_percent_advance varchar2(3);',
'    l_percent_balance number;',
'  begin',
'    if p_value is null then',
'      return null;',
'    end if;',
'',
'    l_value := clean_text(p_value);',
unistr('    l_value := replace(l_value, ''\00C1'', ''A'');'),
unistr('    l_value := replace(l_value, ''\00C0'', ''A'');'),
unistr('    l_value := replace(l_value, ''\00C2'', ''A'');'),
unistr('    l_value := replace(l_value, ''\00C3'', ''A'');'),
unistr('    l_value := replace(l_value, ''\00C9'', ''E'');'),
unistr('    l_value := replace(l_value, ''\00CA'', ''E'');'),
unistr('    l_value := replace(l_value, ''\00CD'', ''I'');'),
unistr('    l_value := replace(l_value, ''\00D3'', ''O'');'),
unistr('    l_value := replace(l_value, ''\00D5'', ''O'');'),
unistr('    l_value := replace(l_value, ''\00D4'', ''O'');'),
unistr('    l_value := replace(l_value, ''\00DA'', ''U'');'),
unistr('    l_value := replace(l_value, ''\00C7'', ''C'');'),
'',
'    l_percent_advance := regexp_substr(',
'      l_value,',
'      ''(^|[^0-9])([0-9]{1,3})\s*%?\s*ANTECIP'',',
'      1,',
'      1,',
'      ''i'',',
'      2',
'    );',
'',
'    if l_percent_advance is null then',
'      l_percent_advance := regexp_substr(',
'        l_value,',
'        ''ANTECIP[[:alpha:]]*\s*([0-9]{1,3})\s*%?'',',
'        1,',
'        1,',
'        ''i'',',
'        1',
'      );',
'    end if;',
'',
'    if l_percent_advance is not null',
'       and to_number(l_percent_advance) between 1 and 100',
'       and regexp_like(l_value, ''(SALDO|CARGA|CAD|EMBARQUE)'', ''i'') then',
'      l_percent_balance := 100 - to_number(l_percent_advance);',
'      return ''ANTECIPADO_'' || l_percent_advance || ''_SALDO_'' || to_char(l_percent_balance);',
'    end if;',
'',
'    l_value := regexp_replace(l_value, ''B\s*/\s*L'', ''BL'');',
'    l_value := regexp_replace(l_value, ''\b(DAYS?|DIAS?)\b'', ''DIA'');',
unistr('    l_value := regexp_replace(l_value, ''\005Cb(AFTER|DATE|DO|DA|DE|APOS|AP\00D3S|A)\005Cb'', '' '');'),
'    l_value := regexp_replace(l_value, ''[^A-Z0-9]+'', '' '');',
'    l_value := regexp_replace(trim(l_value), ''\s+'', '' '');',
'    return l_value;',
'  end payment_terms_key;',
'',
'  function payment_terms_percent_token(p_value in varchar2) return varchar2 is',
'    l_value varchar2(4000);',
'  begin',
'    if p_value is null then',
'      return null;',
'    end if;',
'',
'    l_value := clean_text(p_value);',
'    return regexp_substr(l_value, ''(^|[^0-9])([0-9]{1,3})\s*%'', 1, 1, ''i'', 2);',
'  end payment_terms_percent_token;',
'',
'  function payment_terms_match_score(',
'    p_source    in varchar2,',
'    p_candidate in varchar2',
'  ) return number is',
'    l_source_key    varchar2(4000) := payment_terms_key(p_source);',
'    l_candidate_key varchar2(4000) := payment_terms_key(p_candidate);',
'    l_token         varchar2(100);',
'    l_token_pos     pls_integer := 1;',
'    l_score         number := 0;',
'  begin',
'    if l_source_key is null or l_candidate_key is null then',
'      return 0;',
'    end if;',
'',
'    if l_source_key = l_candidate_key then',
'      return 10000;',
'    end if;',
'',
'    loop',
'      l_token := regexp_substr(l_source_key, ''[[:alnum:]]+'', 1, l_token_pos);',
'      exit when l_token is null;',
'',
'      if length(l_token) >= 2 and instr('' '' || l_candidate_key || '' '', '' '' || l_token || '' '') > 0 then',
'        l_score := l_score + case',
'                               when regexp_like(l_token, ''^[0-9]+$'') then 30',
'                               when l_token in (''ANTECIPADO'', ''ANTECIPADAMENTE'', ''SALDO'', ''CARGA'', ''CAD'', ''EMBARQUE'') then 20',
'                               else 10',
'                             end;',
'      end if;',
'',
'      l_token_pos := l_token_pos + 1;',
'    end loop;',
'',
'    return l_score;',
'  end payment_terms_match_score;',
'',
'  function json_date(p_value in varchar2) return date is',
'  begin',
'    if p_value is null then',
'      return null;',
'    end if;',
'    return to_date(substr(p_value, 1, 10), ''yyyy-mm-dd'');',
'  exception',
'    when others then',
'      return null;',
'  end json_date;',
'',
'  procedure add_gap(',
'    p_gaps            in out nocopy json_array_t,',
'    p_severity        in varchar2,',
'    p_scope           in varchar2,',
'    p_field           in varchar2,',
'    p_message         in varchar2,',
'    p_extracted_value in varchar2 default null',
'  ) is',
'    l_gap json_object_t := json_object_t();',
'  begin',
'    l_gap.put(''severity'', p_severity);',
'    l_gap.put(''scope'', p_scope);',
'    l_gap.put(''field'', p_field);',
'    l_gap.put(''message'', p_message);',
'    if p_extracted_value is not null then',
'      l_gap.put(''extracted_value'', p_extracted_value);',
'    end if;',
'    p_gaps.append(l_gap);',
'  end add_gap;',
'',
'  procedure add_resolved_item(',
'    p_items in out nocopy json_array_t,',
'    p_item  in t_item_rec',
'  ) is',
'    l_obj json_object_t := json_object_t();',
'  begin',
'    l_obj.put(''item_index'', p_item.item_index);',
'    l_obj.put(''sequencia_item_invoice'', p_item.sequencia_item_invoice);',
'    l_obj.put(''id_entrega'', p_item.id_entrega);',
'    l_obj.put(''id_entrega_item'', p_item.id_entrega_item);',
'    l_obj.put(''id_item'', p_item.id_item);',
'    l_obj.put(''id_ncm'', p_item.id_ncm);',
'    l_obj.put(''id_unidademedida'', p_item.id_unidademedida);',
'    l_obj.put(''id_fabricante'', p_item.id_fabricante);',
'    l_obj.put(''id_pais_origem'', p_item.id_pais_origem);',
'    p_items.append(l_obj);',
'  end add_resolved_item;',
'',
'  function gap_count(p_gaps in json_array_t, p_severity in varchar2) return number is',
'    l_count number := 0;',
'    l_obj   json_object_t;',
'  begin',
'    for i in 0 .. p_gaps.get_size - 1 loop',
'      l_obj := treat(p_gaps.get(i) as json_object_t);',
'      if l_obj.get_string(''severity'') = p_severity then',
'        l_count := l_count + 1;',
'      end if;',
'    end loop;',
'    return l_count;',
'  end gap_count;',
'',
'  function id_exists(',
'    p_table_name in varchar2,',
'    p_id_tenant  in number,',
'    p_id         in number',
'  ) return boolean is',
'    l_count number;',
'  begin',
'    if p_id is null then',
'      return false;',
'    end if;',
'',
'    execute immediate',
'      ''select count(*) from '' || p_table_name || '' where id_tenant = :1 and id = :2''',
'      into l_count',
'      using p_id_tenant, p_id;',
'',
'    return l_count = 1;',
'  end id_exists;',
'',
'  function column_exists(',
'    p_table_name  in varchar2,',
'    p_column_name in varchar2',
'  ) return boolean is',
'    l_count number;',
'  begin',
'    select count(*)',
'      into l_count',
'      from all_tab_columns',
'     where table_name = upper(p_table_name)',
'       and column_name = upper(p_column_name)',
'       and owner in (sys_context(''USERENV'', ''CURRENT_SCHEMA''), user);',
'',
'    return l_count > 0;',
'  end column_exists;',
'',
'  function resolve_person_by_document(',
'    p_id_tenant in number,',
'    p_document  in varchar2',
'  ) return number is',
'    type t_name_list is table of varchar2(128);',
'',
'    l_doc          varchar2(30) := only_digits(p_document);',
'    l_id           number;',
'    l_count        number;',
'    l_sql          varchar2(4000);',
'    l_person_cols  t_name_list := t_name_list(',
'      ''NUM_CNPJ_CPF'', ''CNPJ_CPF'', ''CPF_CNPJ'', ''NUM_DOCUMENTO'',',
'      ''DOCUMENTO'', ''CNPJ'', ''CPF'', ''NUM_CNPJ'', ''NUM_CPF''',
'    );',
'    l_doc_tables   t_name_list := t_name_list(',
'      ''NG_PESSOA_DOCUMENTO'', ''NG_PESSOA_DOCUMENTOS'', ''NG_PESSOA_DOC''',
'    );',
'    l_doc_cols     t_name_list := t_name_list(',
'      ''NUM_DOCUMENTO'', ''DOCUMENTO'', ''CNPJ_CPF'', ''CPF_CNPJ'',',
'      ''NUM_CNPJ_CPF'', ''CNPJ'', ''CPF'', ''NUM_CNPJ'', ''NUM_CPF''',
'    );',
'  begin',
'    if l_doc is null then',
'      return null;',
'    end if;',
'',
'    if column_exists(''NG_PESSOA_JURIDICA'', ''INSCRICAO_FEDERAL'') then',
'      select min(p.id), count(distinct p.id)',
'        into l_id, l_count',
'        from ng_pessoa p',
'        join ng_pessoa_juridica pj',
'          on pj.id_tenant = p.id_tenant',
'         and pj.id_pessoa = p.id',
'       where p.id_tenant = p_id_tenant',
'         and p.data_fim_vigencia is null',
'         and regexp_replace(nvl(pj.inscricao_federal, ''''), ''[^0-9]'', '''') = l_doc;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        return null;',
'      end if;',
'    end if;',
'',
'    for i in 1 .. l_person_cols.count loop',
'      if column_exists(''NG_PESSOA'', l_person_cols(i)) then',
'        l_sql :=',
'          ''select min(id), count(*)'' ||',
'          ''  from ng_pessoa'' ||',
'          '' where id_tenant = :1'' ||',
'          ''   and data_fim_vigencia is null'' ||',
'          ''   and regexp_replace(to_char('' || l_person_cols(i) || ''), ''''[^0-9]'''', '''''''') = :2'';',
'',
'        execute immediate l_sql into l_id, l_count using p_id_tenant, l_doc;',
'',
'        if l_count = 1 then',
'          return l_id;',
'        elsif l_count > 1 then',
'          return null;',
'        end if;',
'      end if;',
'    end loop;',
'',
'    for t in 1 .. l_doc_tables.count loop',
'      if column_exists(l_doc_tables(t), ''ID_PESSOA'') then',
'        for c in 1 .. l_doc_cols.count loop',
'          if column_exists(l_doc_tables(t), l_doc_cols(c)) then',
'            l_sql :=',
'              ''select min(p.id), count(distinct p.id)'' ||',
'              ''  from ng_pessoa p'' ||',
'              ''  join '' || l_doc_tables(t) || '' d on d.id_pessoa = p.id'' ||',
'              '' where p.id_tenant = :1'' ||',
'              ''   and p.data_fim_vigencia is null'';',
'',
'            if column_exists(l_doc_tables(t), ''ID_TENANT'') then',
'              l_sql := l_sql || '' and d.id_tenant = :2'' ||',
'                       '' and regexp_replace(to_char(d.'' || l_doc_cols(c) || ''), ''''[^0-9]'''', '''''''') = :3'';',
'              execute immediate l_sql into l_id, l_count using p_id_tenant, p_id_tenant, l_doc;',
'            else',
'              l_sql := l_sql ||',
'                       '' and regexp_replace(to_char(d.'' || l_doc_cols(c) || ''), ''''[^0-9]'''', '''''''') = :2'';',
'              execute immediate l_sql into l_id, l_count using p_id_tenant, l_doc;',
'            end if;',
'',
'            if l_count = 1 then',
'              return l_id;',
'            elsif l_count > 1 then',
'              return null;',
'            end if;',
'          end if;',
'        end loop;',
'      end if;',
'    end loop;',
'',
'    return null;',
'  end resolve_person_by_document;',
'',
'  function resolve_person_match(',
'    p_id_tenant      in number,',
'    p_explicit_id    in number,',
'    p_name           in varchar2,',
'    p_document       in varchar2,',
'    p_scope          in varchar2,',
'    p_field          in varchar2,',
'    p_required_yn    in t_yn,',
'    p_gaps           in out nocopy json_array_t',
'  ) return t_match_result is',
'    l_id    number;',
'    l_count number;',
'    l_name_clean varchar2(150);',
'    l_best_id number;',
'    l_best_score number := 0;',
'    l_best_count number := 0;',
'    l_best_name varchar2(4000);',
'    l_candidate_name varchar2(4000);',
'    l_score number;',
'  begin',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_PESSOA'', p_id_tenant, p_explicit_id) then',
'        return make_match(p_explicit_id, 100, ''ID_EXPLICITO'', to_char(p_explicit_id), null);',
'      end if;',
'      add_gap(',
'        p_gaps,',
'        case when p_required_yn = ''S'' then ''ERROR'' else ''WARN'' end,',
'        p_scope,',
'        p_field,',
'        ''ID de pessoa informado no JSON nao existe para o tenant.'',',
'        to_char(p_explicit_id)',
'      );',
'      return make_match(null, 0, ''ID_EXPLICITO_INVALIDO'', to_char(p_explicit_id), null);',
'    end if;',
'',
'    if p_required_yn <> ''S'' and p_name is null and p_document is null then',
'      return make_match(null, 0, ''SEM_DADOS'', null, null);',
'    end if;',
'',
'    if p_document is not null then',
'      l_id := resolve_person_by_document(p_id_tenant, p_document);',
'      if l_id is not null then',
'        return make_match(l_id, 100, ''DOCUMENTO'', p_document, p_document);',
'      end if;',
'    end if;',
'',
'    if p_name is not null then',
'      l_name_clean := clean_text(p_name);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_pessoa',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and (',
'              upper(regexp_replace(trim(nome_completo), ''\s+'', '' '')) = l_name_clean',
'           or upper(regexp_replace(trim(nome_resumido), ''\s+'', '' '')) = l_name_clean',
'         );',
'',
'      if l_count = 1 then',
'        return make_match(l_id, 100, ''NOME_EXATO'', p_name, p_name);',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, p_field, ''Mais de uma pessoa encontrada pelo nome extraido.'', p_name);',
'        return make_match(null, 0, ''NOME_EXATO_AMBIGUO'', p_name, null);',
'      end if;',
'',
'      for c in (',
'        select id,',
'               nome_completo,',
'               nome_resumido',
'          from ng_pessoa',
'         where id_tenant = p_id_tenant',
'           and data_fim_vigencia is null',
'      ) loop',
'        l_candidate_name := coalesce(c.nome_completo, c.nome_resumido);',
'        l_score := greatest(',
'          text_similarity_score(p_name, c.nome_completo),',
'          text_similarity_score(p_name, c.nome_resumido)',
'        );',
'',
'        if l_score > l_best_score then',
'          l_best_score := l_score;',
'          l_best_count := 1;',
'          l_best_id := c.id;',
'          l_best_name := l_candidate_name;',
'        elsif l_score = l_best_score and l_score > 0 then',
'          l_best_count := l_best_count + 1;',
'          l_best_id := least(nvl(l_best_id, c.id), c.id);',
'        end if;',
'      end loop;',
'',
'      if l_best_count = 1 and l_best_score > 0 then',
'        if l_best_score < 70 then',
'          add_gap(',
'            p_gaps,',
'            case when p_required_yn = ''S'' then ''WARN'' else ''WARN'' end,',
'            p_scope,',
'            p_field,',
'            ''Pessoa sugerida por similaridade com baixa/media confianca. Confira antes de importar.'',',
'            p_name',
'          );',
'        end if;',
'        return make_match(l_best_id, l_best_score, ''SIMILARIDADE_TEXTO'', p_name, l_best_name);',
'      elsif l_best_count > 1 and l_best_score > 0 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, p_field, ''Mais de uma pessoa encontrada com o mesmo score de similaridade.'', p_name);',
'        return make_match(null, l_best_score, ''SIMILARIDADE_TEXTO_AMBIGUA'', p_name, null);',
'      end if;',
'    end if;',
'',
'    add_gap(',
'      p_gaps,',
'      case when p_required_yn = ''S'' then ''ERROR'' else ''WARN'' end,',
'      p_scope,',
'      p_field,',
'      ''Pessoa nao resolvida. Documento e nome extraidos nao localizaram cadastro unico.'',',
'      coalesce(p_document, p_name)',
'    );',
'',
'    return make_match(null, 0, ''NAO_RESOLVIDO'', coalesce(p_document, p_name), null);',
'  end resolve_person_match;',
'',
'  function resolve_person(',
'    p_id_tenant      in number,',
'    p_explicit_id    in number,',
'    p_name           in varchar2,',
'    p_document       in varchar2,',
'    p_scope          in varchar2,',
'    p_field          in varchar2,',
'    p_required_yn    in t_yn,',
'    p_gaps           in out nocopy json_array_t',
'  ) return number is',
'    l_match t_match_result;',
'  begin',
'    l_match := resolve_person_match(',
'      p_id_tenant,',
'      p_explicit_id,',
'      p_name,',
'      p_document,',
'      p_scope,',
'      p_field,',
'      p_required_yn,',
'      p_gaps',
'    );',
'    return l_match.id_resolvido;',
'  end resolve_person;',
'',
'  function resolve_condpagto_match(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_description in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return t_match_result is',
'    l_id    number;',
'    l_count number;',
'    l_desc_clean varchar2(100);',
'    l_terms_key varchar2(4000);',
'    l_candidate_key varchar2(4000);',
'    l_percent_token varchar2(3);',
'    l_score number;',
'    l_best_score number := 0;',
'    l_best_count number := 0;',
'    l_best_id number;',
'    l_best_description varchar2(4000);',
'    l_desc_ptbr varchar2(4000);',
'  begin',
'    l_desc_ptbr := p_description;',
'    if p_description is not null then',
'      begin',
'        l_desc_ptbr := PKG_TRADUCAO.traduzir_texto_auto(p_description, ''pt-br'');',
'      exception',
'        when others then',
'          l_desc_ptbr := p_description;',
'      end;',
'    end if;',
'',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_CONDICAOPAGAMENTO'', p_id_tenant, p_explicit_id) then',
'        return make_match(p_explicit_id, 100, ''ID_EXPLICITO'', to_char(p_explicit_id), null);',
'      end if;',
'      add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.condicao_pagamento.id_condicaopagamento'', ''ID de condicao de pagamento nao existe para o tenant.'', to_char(p_explicit_id));',
'      return make_match(null, 0, ''ID_EXPLICITO_INVALIDO'', to_char(p_explicit_id), null);',
'    end if;',
'',
'    if l_desc_ptbr is not null then',
'      l_desc_clean := clean_text(l_desc_ptbr);',
'      l_terms_key := payment_terms_key(l_desc_ptbr);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_condicaopagamento',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and ind_situacao = ''D''',
'         and upper(regexp_replace(trim(descricao_condicaopagamento), ''\s+'', '' '')) = l_desc_clean;',
'',
'      if l_count = 1 then',
'        return make_match(l_id, 100, ''DESCRICAO_EXATA'', l_desc_ptbr, l_desc_ptbr);',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.condicao_pagamento.id_condicaopagamento'', ''Mais de uma condicao de pagamento encontrada.'', l_desc_ptbr);',
'        return make_match(null, 0, ''DESCRICAO_EXATA_AMBIGUA'', l_desc_ptbr, null);',
'      end if;',
'',
'      l_id := null;',
'      l_count := 0;',
'',
'      for c in (',
'        select id, descricao_condicaopagamento',
'          from ng_condicaopagamento',
'         where id_tenant = p_id_tenant',
'           and data_fim_vigencia is null',
'           and ind_situacao = ''D''',
'      ) loop',
'        l_candidate_key := payment_terms_key(c.descricao_condicaopagamento);',
'        if l_candidate_key = l_terms_key then',
'          l_count := l_count + 1;',
'          l_id := least(nvl(l_id, c.id), c.id);',
'          l_best_description := c.descricao_condicaopagamento;',
'        end if;',
'      end loop;',
'',
'      if l_count = 1 then',
'        return make_match(l_id, 95, ''CHAVE_SEMANTICA'', l_desc_ptbr, l_best_description);',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.condicao_pagamento.id_condicaopagamento'', ''Mais de uma condicao de pagamento equivalente encontrada.'', l_desc_ptbr);',
'        return make_match(null, 95, ''CHAVE_SEMANTICA_AMBIGUA'', l_desc_ptbr, null);',
'      end if;',
'',
'      l_percent_token := payment_terms_percent_token(l_desc_ptbr);',
'      l_best_score := 0;',
'      l_best_count := 0;',
'',
'      for c in (',
'        select id, descricao_condicaopagamento',
'          from ng_condicaopagamento',
'         where id_tenant = p_id_tenant',
'           and data_fim_vigencia is null',
'           and ind_situacao = ''D''',
'           and (',
'                l_percent_token is null',
'             or regexp_like(descricao_condicaopagamento, ''(^|[^0-9])'' || l_percent_token || ''\s*%'', ''i'')',
'           )',
'      ) loop',
'        l_score := text_similarity_score(l_desc_ptbr, c.descricao_condicaopagamento);',
'',
'        if l_score > l_best_score then',
'          l_best_score := l_score;',
'          l_best_count := 1;',
'          l_best_id := c.id;',
'          l_best_description := c.descricao_condicaopagamento;',
'        elsif l_score = l_best_score and l_score > 0 then',
'          l_best_count := l_best_count + 1;',
'          l_best_id := least(nvl(l_best_id, c.id), c.id);',
'        end if;',
'      end loop;',
'',
'      if l_best_count = 1 and l_best_score > 0 then',
'        if l_best_score < 70 then',
'          add_gap(p_gaps, ''WARN'', ''invoice'', ''invoice.condicao_pagamento.id_condicaopagamento'',',
'                  ''Condicao de pagamento sugerida por similaridade com baixa/media confianca. Confira antes de importar.'', l_desc_ptbr);'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(243453757220529151)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'        end if;',
'        return make_match(l_best_id, l_best_score, ''SIMILARIDADE_TEXTO'', l_desc_ptbr, l_best_description);',
'      elsif l_best_count > 1 and l_best_score > 0 then',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.condicao_pagamento.id_condicaopagamento'',',
'                ''Mais de uma condicao de pagamento encontrada com o mesmo score de similaridade.'', l_desc_ptbr);',
'        return make_match(null, l_best_score, ''SIMILARIDADE_TEXTO_AMBIGUA'', l_desc_ptbr, null);',
'      end if;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.condicao_pagamento.id_condicaopagamento'', ''Condicao de pagamento nao resolvida.'', l_desc_ptbr);',
'    return make_match(null, 0, ''NAO_RESOLVIDO'', l_desc_ptbr, null);',
'  end resolve_condpagto_match;',
'',
'  function resolve_condpagto(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_description in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_match t_match_result;',
'  begin',
'    l_match := resolve_condpagto_match(p_id_tenant, p_explicit_id, p_description, p_gaps);',
'    return l_match.id_resolvido;',
'  end resolve_condpagto;',
'',
'  function resolve_incoterm(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_code        in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_code  varchar2(3);',
'  begin',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_INCOTERM'', p_id_tenant, p_explicit_id) then',
'        return p_explicit_id;',
'      end if;',
'      add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.incoterm.id_incoterm'', ''ID de incoterm nao existe para o tenant.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    if p_code is not null then',
'      l_code := clean_code(p_code);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_incoterm',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and codigo_incoterm = l_code;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.incoterm.id_incoterm'', ''Mais de um incoterm encontrado.'', p_code);',
'        return null;',
'      end if;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.incoterm.id_incoterm'', ''Incoterm nao resolvido.'', p_code);',
'    return null;',
'  end resolve_incoterm;',
'',
'  function resolve_moeda(',
