'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.moeda.id_moeda'', ''Moeda nao resolvida.'', p_code);',
'    return null;',
'  end resolve_moeda;',
'',
'  function resolve_item(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_code        in varchar2,',
'    p_description in varchar2,',
'    p_scope       in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_code  varchar2(100);',
'  begin',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_ITEM'', p_id_tenant, p_explicit_id) then',
'        return p_explicit_id;',
'      end if;',
'      add_gap(p_gaps, ''ERROR'', p_scope, ''items[].item.id_item'', ''ID de item nao existe para o tenant.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    if p_code is not null then',
'      l_code := clean_code(p_code);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_item',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and upper(trim(codigo_item)) = l_code;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].item.id_item'', ''Mais de um item encontrado pelo codigo.'', p_code);',
'        return null;',
'      end if;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', p_scope, ''items[].item.id_item'', ''Item nao resolvido. O codigo do item e a chave mais segura.'', coalesce(p_code, substr(p_description, 1, 200)));',
'    return null;',
'  end resolve_item;',
'',
'  function resolve_ncm(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_code        in varchar2,',
'    p_scope       in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_code  varchar2(8);',
'  begin',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_NCM'', p_id_tenant, p_explicit_id) then',
'        return p_explicit_id;',
'      end if;',
'      add_gap(p_gaps, ''ERROR'', p_scope, ''items[].ncm.id_ncm'', ''ID de NCM nao existe para o tenant.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    l_code := only_digits(p_code);',
'    if l_code is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_ncm',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and codigo_ncm = l_code;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].ncm.id_ncm'', ''Mais de um NCM encontrado pelo codigo.'', p_code);',
'        return null;',
'      end if;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', p_scope, ''items[].ncm.id_ncm'', ''NCM nao resolvido.'', p_code);',
'    return null;',
'  end resolve_ncm;',
'',
'  function resolve_unidade(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_code        in varchar2,',
'    p_id_item     in number,',
'    p_id_ncm      in number,',
'    p_scope       in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_code  varchar2(20);',
'  begin',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_UNIDADEMEDIDA'', p_id_tenant, p_explicit_id) then',
'        return p_explicit_id;',
'      end if;',
'      add_gap(p_gaps, ''ERROR'', p_scope, ''items[].unidade_medida.id_unidademedida'', ''ID de unidade de medida nao existe para o tenant.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    if p_code is not null then',
'      l_code := clean_code(p_code);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_unidademedida',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and upper(trim(codigo_unidademedida)) = l_code;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].unidade_medida.id_unidademedida'', ''Mais de uma unidade encontrada pelo codigo.'', p_code);',
'        return null;',
'      end if;',
'    end if;',
'',
'    if p_id_item is not null then',
'      select id_unidademedida',
'        into l_id',
'        from ng_item',
'       where id_tenant = p_id_tenant',
'         and id = p_id_item;',
'      return l_id;',
'    end if;',
'',
'    if p_id_ncm is not null then',
'      select id_unidademedida',
'        into l_id',
'        from ng_ncm',
'       where id_tenant = p_id_tenant',
'         and id = p_id_ncm;',
'      return l_id;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', p_scope, ''items[].unidade_medida.id_unidademedida'', ''Unidade de medida nao resolvida.'', p_code);',
'    return null;',
'  exception',
'    when no_data_found then',
'      add_gap(p_gaps, ''ERROR'', p_scope, ''items[].unidade_medida.id_unidademedida'', ''Unidade de medida nao resolvida a partir de item/NCM.'', p_code);',
'      return null;',
'  end resolve_unidade;',
'',
'  function resolve_pedido_importacao(',
'    p_id_tenant       in number,',
'    p_explicit_id     in number,',
'    p_numero_extraido in varchar2,',
'    p_id_importador   in number,',
'    p_id_exportador   in number,',
'    p_gaps            in out nocopy json_array_t',
'  ) return number is',
'    l_id          number;',
'    l_count       number;',
'    l_numero      varchar2(100) := trim(p_numero_extraido);',
'    l_like_numero varchar2(400);',
'  begin',
'    if p_explicit_id is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_pedidoimportacao',
'       where id_tenant = p_id_tenant',
'         and id = p_explicit_id;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      end if;',
'',
'      add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.pedido_importacao.id_pedidoimportacao'',',
'              ''ID do pedido de importacao nao existe para o tenant.'', to_char(p_id_exportador));',
'      return null;',
'    end if;',
'',
'    if l_numero is null then',
'      if p_id_importador is not null and p_id_exportador is not null then',
'        select min(id), count(*)',
'          into l_id, l_count',
'          from imp_pedidoimportacao',
'         where id_tenant = p_id_tenant',
'           and id_importador = p_id_importador',
'           and id_exportador = p_id_exportador;',
'',
'        if l_count = 1 then',
'          return l_id;',
'        elsif l_count > 1 then',
'          add_gap(p_gaps, ''WARN'', ''invoice'', ''invoice.pedido_importacao.id_pedidoimportacao'',',
'                  ''Referencia do pedido nao foi encontrada na invoice e existe mais de um pedido para importador/exportador. Selecione manualmente.'');',
'          return null;',
'        end if;',
'      end if;',
'',
'      add_gap(p_gaps, ''WARN'', ''invoice'', ''invoice.pedido_importacao.numero_pedido_importacao_extraido'',',
'              ''Referencia do pedido de importacao nao foi encontrada na invoice e nao foi possivel resolver pedido unico por importador/exportador.'');',
'      return null;',
'    end if;',
'',
'    -- Escapa curingas para que %, _ e barra no texto sejam tratados literalmente.',
'    l_like_numero := replace(upper(l_numero), chr(92), chr(92) || chr(92));',
'    l_like_numero := replace(l_like_numero, ''%'', chr(92) || ''%'');',
'    l_like_numero := replace(l_like_numero, ''_'', chr(92) || ''_'');',
'',
'    select min(id), count(*)',
'      into l_id, l_count',
'      from imp_pedidoimportacao',
'     where id_tenant = p_id_tenant',
'       and upper(trim(numero_pedido_importacao)) like ''%'' || l_like_numero || ''%'' escape ''\'';',
'',
'    if l_count = 1 then',
'      return l_id;',
'    elsif l_count > 1 then',
'      if p_id_importador is null or p_id_exportador is null then',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.pedido_importacao.numero_pedido_importacao_extraido'',',
'                ''Mais de um pedido encontrado e importador/exportador nao foram resolvidos para o desempate.'', l_numero);',
'        return null;',
'      end if;',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_pedidoimportacao',
'       where id_tenant = p_id_tenant',
'         and upper(trim(numero_pedido_importacao)) like ''%'' || l_like_numero || ''%'' escape ''\''',
'         and id_importador = p_id_importador',
'         and id_exportador = p_id_exportador;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.pedido_importacao.numero_pedido_importacao_extraido'',',
'                ''Mais de um pedido permanece compativel com referencia, importador e exportador.'', l_numero);',
'      else',
'        add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.pedido_importacao.numero_pedido_importacao_extraido'',',
'                ''Nenhum dos pedidos candidatos pertence ao importador e exportador da invoice.'', l_numero);',
'      end if;',
'    else',
'      add_gap(p_gaps, ''WARN'', ''invoice'', ''invoice.pedido_importacao.numero_pedido_importacao_extraido'',',
'              ''Pedido de importacao nao encontrado para o tenant.'', l_numero);',
'    end if;',
'',
'    return null;',
'  end resolve_pedido_importacao;',
'',
'  function resolve_entrega(',
'    p_id_tenant             in number,',
'    p_id_processoimportacao in number,',
'    p_id_pedidoimportacao   in number,',
'    p_id_item               in number,',
'    p_id_ncm                in number,',
'    p_codigo_ncm            in varchar2,',
'    p_explicit_id           in number,',
'    p_reference             in varchar2,',
'    p_scope                 in varchar2,',
'    p_gaps                  in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_delivery_count number;',
'    l_num   number;',
'    l_ncm6  varchar2(6) := substr(only_digits(p_codigo_ncm), 1, 6);',
'  begin',
'    if p_explicit_id is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_entrega',
'       where id_tenant = p_id_tenant',
'         and id = p_explicit_id',
'         and (p_id_pedidoimportacao is null or id_pedidoimportacao = p_id_pedidoimportacao);',
'',
'      if l_count = 1 then',
'        return l_id;',
'      end if;',
'      add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega.id_entrega'', ''ID de entrega nao existe para o tenant/pedido.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    if regexp_like(nvl(p_reference, ''''), ''^\d+$'') then',
'      l_num := to_number(p_reference);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_entrega',
'       where id_tenant = p_id_tenant',
'         and num_entrega = l_num',
'         and (p_id_pedidoimportacao is null or id_pedidoimportacao = p_id_pedidoimportacao)',
'         and (p_id_processoimportacao is null or id_processoimportacao = p_id_processoimportacao);',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega.id_entrega'', ''Mais de uma entrega encontrada pelo numero informado.'', p_reference);',
'        return null;',
'      end if;',
'    end if;',
'',
'    if p_id_pedidoimportacao is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_entrega',
'       where id_tenant = p_id_tenant',
'         and id_pedidoimportacao = p_id_pedidoimportacao',
'         and (p_id_processoimportacao is null or id_processoimportacao = p_id_processoimportacao);',
'',
'      l_delivery_count := l_count;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 and p_id_item is not null then',
'        select min(e.id), count(distinct e.id)',
'          into l_id, l_count',
'          from imp_entrega e',
'          join imp_entrega_item ei',
'            on ei.id_tenant = e.id_tenant',
'           and ei.id_entrega = e.id',
'         where e.id_tenant = p_id_tenant',
'           and e.id_pedidoimportacao = p_id_pedidoimportacao',
'           and ei.id_item = p_id_item',
'           and (p_id_processoimportacao is null or e.id_processoimportacao = p_id_processoimportacao);',
'',
'        if l_count = 1 then',
'          return l_id;',
'        end if;',
'      end if;',
'',
'      if l_delivery_count > 1 and p_id_ncm is not null then',
'        select min(e.id), count(distinct e.id)',
'          into l_id, l_count',
'          from imp_entrega e',
'          join imp_entrega_item ei',
'            on ei.id_tenant = e.id_tenant',
'           and ei.id_entrega = e.id',
'         where e.id_tenant = p_id_tenant',
'           and e.id_pedidoimportacao = p_id_pedidoimportacao',
'           and ei.id_ncm = p_id_ncm',
'           and (p_id_processoimportacao is null or e.id_processoimportacao = p_id_processoimportacao);',
'',
'        if l_count = 1 then',
'          return l_id;',
'        end if;',
'      end if;',
'',
'      if l_delivery_count > 1 and l_ncm6 is not null then',
'        select min(e.id), count(distinct e.id)',
'          into l_id, l_count',
'          from imp_entrega e',
'          join imp_entrega_item ei',
'            on ei.id_tenant = e.id_tenant',
'           and ei.id_entrega = e.id',
'          join ng_ncm n',
'            on n.id_tenant = ei.id_tenant',
'           and n.id = ei.id_ncm',
'         where e.id_tenant = p_id_tenant',
'           and e.id_pedidoimportacao = p_id_pedidoimportacao',
'           and substr(n.codigo_ncm, 1, 6) = l_ncm6',
'           and (p_id_processoimportacao is null or e.id_processoimportacao = p_id_processoimportacao);',
'',
'        if l_count = 1 then',
'          return l_id;',
'        end if;',
'      end if;',
'',
'      if l_delivery_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega.id_entrega'',',
'                ''Pedido possui mais de uma entrega. Item/NCM nao identificaram uma entrega unica; informe a entrega manualmente.'', coalesce(to_char(p_id_item), to_char(p_id_ncm), p_codigo_ncm));',
'      else',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega.id_entrega'',',
'                ''Nenhuma entrega encontrada para o pedido/item.'', to_char(p_id_pedidoimportacao));',
'      end if;',
'      return null;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega.id_entrega'', ''Entrega nao resolvida. Envie id_entrega, NUM_ENTREGA ou a referencia do pedido de importacao.'', p_reference);',
'    return null;',
'  end resolve_entrega;',
'',
'  function resolve_entrega_item(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_id_entrega  in number,',
'    p_id_item     in number,',
'    p_id_ncm      in number,',
'    p_codigo_ncm  in varchar2,',
'    p_scope       in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_ncm6  varchar2(6) := substr(only_digits(p_codigo_ncm), 1, 6);',
'  begin',
'    if p_explicit_id is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_entrega_item',
'       where id_tenant = p_id_tenant',
'         and id = p_explicit_id',
'         and (p_id_entrega is null or id_entrega = p_id_entrega);',
'',
'      if l_count = 1 then',
'        return l_id;',
'      end if;',
'',
'      add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega_item.id_entrega_item'', ''ID de entrega item nao existe para tenant/entrega.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    if p_id_entrega is not null and p_id_item is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_entrega_item',
'       where id_tenant = p_id_tenant',
'         and id_entrega = p_id_entrega',
'         and id_item = p_id_item;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega_item.id_entrega_item'', ''Mais de um entrega item encontrado para entrega/item.'', to_char(p_id_item));',
'        return null;',
'      end if;',
'    end if;',
'',
'    if p_id_entrega is not null and p_id_ncm is not null then',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from imp_entrega_item',
'       where id_tenant = p_id_tenant',
'         and id_entrega = p_id_entrega',
'         and id_ncm = p_id_ncm;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega_item.id_entrega_item'', ''Mais de um entrega item encontrado para entrega/NCM.'', to_char(p_id_ncm));',
'        return null;',
'      end if;',
'    end if;',
'',
'    if p_id_entrega is not null and l_ncm6 is not null then',
'      select min(ei.id), count(*)',
'        into l_id, l_count',
'        from imp_entrega_item ei',
'        join ng_ncm n',
'          on n.id_tenant = ei.id_tenant',
'         and n.id = ei.id_ncm',
'       where ei.id_tenant = p_id_tenant',
'         and ei.id_entrega = p_id_entrega',
'         and substr(n.codigo_ncm, 1, 6) = l_ncm6;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega_item.id_entrega_item'', ''Mais de um entrega item encontrado para entrega/NCM 6 digitos.'', l_ncm6);',
'        return null;',
'      end if;',
'    end if;',
'',
'    add_gap(p_gaps, ''ERROR'', p_scope, ''items[].entrega_item.id_entrega_item'', ''Entrega item nao resolvido. Envie id_entrega_item ou garanta que entrega + item/NCM identifiquem uma linha unica.'');',
'    return null;',
'  end resolve_entrega_item;',
'',
'  function resolve_pais(',
'    p_id_tenant   in number,',
'    p_explicit_id in number,',
'    p_code        in varchar2,',
'    p_name        in varchar2,',
'    p_scope       in varchar2,',
'    p_gaps        in out nocopy json_array_t',
'  ) return number is',
'    l_id    number;',
'    l_count number;',
'    l_code  varchar2(10);',
'    l_name_clean varchar2(100);',
'  begin',
'    if p_explicit_id is not null then',
'      if id_exists(''NG_PAIS'', p_id_tenant, p_explicit_id) then',
'        return p_explicit_id;',
'      end if;',
'      add_gap(p_gaps, ''WARN'', p_scope, ''items[].pais_origem.id_pais_origem'', ''ID de pais de origem nao existe para o tenant.'', to_char(p_explicit_id));',
'      return null;',
'    end if;',
'',
'    if p_code is not null then',
'      l_code := clean_code(p_code);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_pais',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and upper(trim(codigo_iso)) = l_code;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''WARN'', p_scope, ''items[].pais_origem.id_pais_origem'', ''Mais de um pais encontrado pelo codigo ISO.'', p_code);',
'        return null;',
'      end if;',
'    end if;',
'',
'    if p_name is not null then',
'      l_name_clean := clean_text(p_name);',
'',
'      select min(id), count(*)',
'        into l_id, l_count',
'        from ng_pais',
'       where id_tenant = p_id_tenant',
'         and data_fim_vigencia is null',
'         and upper(regexp_replace(trim(nome_pais), ''\s+'', '' '')) = l_name_clean;',
'',
'      if l_count = 1 then',
'        return l_id;',
'      elsif l_count > 1 then',
'        add_gap(p_gaps, ''WARN'', p_scope, ''items[].pais_origem.id_pais_origem'', ''Mais de um pais encontrado pelo nome.'', p_name);',
'        return null;',
'      end if;',
'    end if;',
'',
'    return null;',
'  end resolve_pais;',
'',
'  procedure read_invoice(',
'    p_json in clob,',
'    p_inv  out nocopy t_invoice_ctx',
'  ) is',
'  begin',
'    select',
'      json_value(p_json, ''$.context.id_tenant'' returning number null on error),',
'      json_value(p_json, ''$.context.id_usuario_incluiu'' returning number null on error),',
'      json_value(p_json, ''$.context.id_processoimportacao'' returning number null on error),',
'      json_value(p_json, ''$.invoice.num_invoice'' returning varchar2(40) null on error),',
'      json_value(p_json, ''$.invoice.data_invoice'' returning varchar2(30) null on error),',
'      json_value(p_json, ''$.invoice.ind_status'' returning number default 1 on error),',
'      json_value(p_json, ''$.invoice.pedido_importacao.id_pedidoimportacao'' returning number null on error),',
'      json_value(p_json, ''$.invoice.pedido_importacao.numero_pedido_importacao_extraido'' returning varchar2(100) null on error),',
'      json_value(p_json, ''$.invoice.pedido_importacao.rotulo_referencia_extraido'' returning varchar2(100) null on error),',
'      json_value(p_json, ''$.invoice.exportador.id_exportador'' returning number null on error),',
'      json_value(p_json, ''$.invoice.exportador.nome_extraido'' returning varchar2(150) null on error),',
'      json_value(p_json, ''$.invoice.exportador.documento_extraido'' returning varchar2(100) null on error),',
'      json_value(p_json, ''$.invoice.importador.id_importador'' returning number null on error),',
'      json_value(p_json, ''$.invoice.importador.nome_extraido'' returning varchar2(150) null on error),',
'      json_value(p_json, ''$.invoice.importador.documento_extraido'' returning varchar2(100) null on error),',
'      json_value(p_json, ''$.invoice.adquirente.id_adquirente'' returning number null on error),',
'      json_value(p_json, ''$.invoice.adquirente.nome_extraido'' returning varchar2(150) null on error),',
'      json_value(p_json, ''$.invoice.adquirente.documento_extraido'' returning varchar2(100) null on error),',
'      json_value(p_json, ''$.invoice.condicao_pagamento.id_condicaopagamento'' returning number null on error),',
'      json_value(p_json, ''$.invoice.condicao_pagamento.descricao_extraida'' returning varchar2(100) null on error),',
'      json_value(p_json, ''$.invoice.incoterm.id_incoterm'' returning number null on error),',
'      json_value(p_json, ''$.invoice.incoterm.codigo_extraido'' returning varchar2(3) null on error),',
'      json_value(p_json, ''$.invoice.moeda.id_moeda'' returning number null on error),',
'      json_value(p_json, ''$.invoice.moeda.codigo_extraido'' returning varchar2(3) null on error),',
'      json_value(p_json, ''$.invoice.ind_forma_pagamento'' returning number default 1 on error),',
'      json_value(p_json, ''$.invoice.pesos.peso_liquido'' returning number null on error),',
'      json_value(p_json, ''$.invoice.pesos.peso_bruto'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_total_mercadoria'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_desconto'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_despesa_invoice'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_total_condicao_venda'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_invoice_informado'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_compensado'' returning number null on error),',
'      json_value(p_json, ''$.invoice.valores.valor_total_financeiro'' returning number null on error),',
'      json_value(p_json, ''$.invoice.pagamento.ind_situacao_titulo_pagamento'' returning varchar2(1) default ''N'' on error),',
'      json_value(p_json, ''$.invoice.divergencia.ind_divergencia'' returning varchar2(1) null on error),',
'      json_value(p_json, ''$.invoice.divergencia.ind_tratamento_saldo'' returning varchar2(1) null on error),',
'      json_value(p_json, ''$.invoice.divergencia.motivo_desconto'' returning varchar2(400) null on error)',
'    into',
'      p_inv.id_tenant,',
'      p_inv.id_usuario_incluiu,',
'      p_inv.id_processoimportacao,',
'      p_inv.num_invoice,',
'      p_inv.data_invoice_txt,',
'      p_inv.ind_status,',
'      p_inv.id_pedidoimportacao_json,',
'      p_inv.numero_pedido_importacao,',
'      p_inv.rotulo_referencia_pedido,',
'      p_inv.id_exportador_json,',
'      p_inv.nome_exportador,',
'      p_inv.doc_exportador,',
'      p_inv.id_importador_json,',
'      p_inv.nome_importador,',
'      p_inv.doc_importador,',
'      p_inv.id_adquirente_json,',
'      p_inv.nome_adquirente,',
'      p_inv.doc_adquirente,',
'      p_inv.id_condpagto_json,',
'      p_inv.desc_condpagto,',
'      p_inv.id_incoterm_json,',
'      p_inv.codigo_incoterm,',
'      p_inv.id_moeda_json,',
'      p_inv.codigo_moeda,',
'      p_inv.ind_forma_pagamento,',
'      p_inv.peso_liquido,',
'      p_inv.peso_bruto,',
'      p_inv.valor_total_mercadoria,',
'      p_inv.valor_desconto,',
'      p_inv.valor_despesa_invoice,',
'      p_inv.valor_total_cond_venda,',
'      p_inv.valor_invoice_informado,',
'      p_inv.valor_compensado,',
'      p_inv.valor_total_financeiro,',
'      p_inv.ind_situacao_titulo,',
'      p_inv.ind_divergencia,',
'      p_inv.ind_tratamento_saldo,',
'      p_inv.motivo_desconto',
'    from dual;',
'',
'    p_inv.data_invoice := json_date(p_inv.data_invoice_txt);',
'    p_inv.ind_status := nvl(p_inv.ind_status, 1);',
'    p_inv.ind_forma_pagamento := nvl(p_inv.ind_forma_pagamento, 1);',
'    p_inv.ind_situacao_titulo := nvl(p_inv.ind_situacao_titulo, ''N'');',
'  end read_invoice;',
'',
'  procedure validate_context(',
'    p_inv  in t_invoice_ctx,',
'    p_gaps in out nocopy json_array_t',
'  ) is',
'    l_count number;',
'  begin',
'    if p_inv.id_tenant is null then',
'      add_gap(p_gaps, ''ERROR'', ''context'', ''context.id_tenant'', ''ID_TENANT e obrigatorio.'');',
'    else',
'      select count(*) into l_count from mpd_tenant where id = p_inv.id_tenant;',
'      if l_count = 0 then',
'        add_gap(p_gaps, ''ERROR'', ''context'', ''context.id_tenant'', ''Tenant nao encontrado.'', to_char(p_inv.id_tenant));',
'      end if;',
'    end if;',
'',
'    if p_inv.id_usuario_incluiu is null then',
'      add_gap(p_gaps, ''ERROR'', ''context'', ''context.id_usuario_incluiu'', ''ID_USUARIO_INCLUIU e obrigatorio.'');',
'    else',
'      select count(*) into l_count from mpd_usuario where id = p_inv.id_usuario_incluiu;',
'      if l_count = 0 then',
'        add_gap(p_gaps, ''ERROR'', ''context'', ''context.id_usuario_incluiu'', ''Usuario nao encontrado.'', to_char(p_inv.id_usuario_incluiu));',
'      end if;',
'    end if;',
'',
'    if p_inv.id_processoimportacao is not null then',
'      select count(*)',
'        into l_count',
'        from imp_processoimportacao',
'       where id = p_inv.id_processoimportacao',
'         and id_tenant = p_inv.id_tenant;',
'      if l_count = 0 then',
'        add_gap(p_gaps, ''ERROR'', ''context'', ''context.id_processoimportacao'', ''Processo de importacao nao encontrado para o tenant.'', to_char(p_inv.id_processoimportacao));',
'      end if;',
'    end if;',
'',
'    if p_inv.num_invoice is null then',
'      add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.num_invoice'', ''Numero da invoice e obrigatorio.'');',
'    end if;',
'',
'    if p_inv.data_invoice_txt is not null and p_inv.data_invoice is null then',
'      add_gap(p_gaps, ''WARN'', ''invoice'', ''invoice.data_invoice'', ''Data da invoice nao esta em formato YYYY-MM-DD.'', p_inv.data_invoice_txt);',
'    end if;',
'',
'    if p_inv.valor_invoice_informado is null then',
'      add_gap(p_gaps, ''ERROR'', ''invoice'', ''invoice.valores.valor_invoice_informado'', ''Valor informado da invoice e obrigatorio.'');',
'    end if;',
'  end validate_context;',
'',
'  function validate_json(',
'    p_json in clob',
'  ) return clob is',
'  begin',
'    return import_json(p_json => p_json, p_valid'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(243453757220529151)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ate_only_yn => ''S'', p_commit_yn => ''N'');',
'  end validate_json;',
'',
'  function import_json(',
'    p_json             in clob,',
'    p_validate_only_yn in varchar2 default ''N'',',
'    p_commit_yn        in varchar2 default ''N''',
'  ) return clob is',
'    l_inv             t_invoice_ctx;',
'    l_res             t_resolved_invoice;',
'    l_items           t_item_tab;',
'    l_item_count      pls_integer := 0;',
'    l_invoice_id      imp_invoice.id%type;',
'    l_duplicate_id    imp_invoice.id%type;',
'    l_duplicate_count number;',
'    l_result          json_object_t := json_object_t();',
'    l_gaps            json_array_t := json_array_t();',
'    l_resolved        json_object_t := json_object_t();',
'    l_resolved_items  json_array_t := json_array_t();',
'    l_confidence      json_object_t := json_object_t();',
'    l_match           t_match_result;',
'    l_scope           varchar2(80);',
'  begin',
'    savepoint ai_invoice_import_sp;',
'',
'    read_invoice(p_json, l_inv);',
'    validate_context(l_inv, l_gaps);',
'',
'    if l_inv.id_tenant is not null then',
'      select min(id), count(*)',
'        into l_duplicate_id, l_duplicate_count',
'        from imp_invoice',
'       where id_tenant = l_inv.id_tenant',
'         and num_invoice = l_inv.num_invoice;',
'',
'      if l_duplicate_count > 0 then',
'        add_gap(l_gaps, ''ERROR'', ''invoice'', ''invoice.num_invoice'', ''Ja existe invoice importada com este numero para o tenant.'', l_inv.num_invoice);',
'      end if;',
'',
'      l_match := resolve_person_match(l_inv.id_tenant, l_inv.id_exportador_json, l_inv.nome_exportador, l_inv.doc_exportador, ''invoice'', ''invoice.exportador.id_exportador'', ''S'', l_gaps);',
'      l_res.id_exportador := l_match.id_resolvido;',
'      put_confidence(l_confidence, ''exportador'', l_match);',
'',
'      l_match := resolve_person_match(l_inv.id_tenant, l_inv.id_importador_json, l_inv.nome_importador, l_inv.doc_importador, ''invoice'', ''invoice.importador.id_importador'', ''S'', l_gaps);',
'      l_res.id_importador := l_match.id_resolvido;',
'      put_confidence(l_confidence, ''importador'', l_match);',
'',
'      l_res.id_pedidoimportacao := resolve_pedido_importacao(l_inv.id_tenant, l_inv.id_pedidoimportacao_json, l_inv.numero_pedido_importacao, l_res.id_importador, l_res.id_exportador, l_gaps);',
'      put_confidence(',
'        l_confidence,',
'        ''pedido_importacao'',',
'        make_match(',
'          l_res.id_pedidoimportacao,',
'          case when l_res.id_pedidoimportacao is not null then 100 else 0 end,',
'          ''REGRA_PEDIDO_IMPORTACAO'',',
'          l_inv.numero_pedido_importacao,',
'          to_char(l_res.id_pedidoimportacao)',
'        )',
'      );',
'',
'      l_match := resolve_person_match(l_inv.id_tenant, l_inv.id_adquirente_json, l_inv.nome_adquirente, l_inv.doc_adquirente, ''invoice'', ''invoice.adquirente.id_adquirente'', ''N'', l_gaps);',
'      l_res.id_adquirente := l_match.id_resolvido;',
'      put_confidence(l_confidence, ''adquirente'', l_match);',
'',
'      l_match := resolve_condpagto_match(l_inv.id_tenant, l_inv.id_condpagto_json, l_inv.desc_condpagto, l_gaps);',
'      l_res.id_condicaopagamento := l_match.id_resolvido;',
'      put_confidence(l_confidence, ''condicao_pagamento'', l_match);',
'',
'      l_res.id_incoterm := resolve_incoterm(l_inv.id_tenant, l_inv.id_incoterm_json, l_inv.codigo_incoterm, l_gaps);',
'      put_confidence(',
'        l_confidence,',
'        ''incoterm'',',
'        make_match(',
'          l_res.id_incoterm,',
'          case when l_res.id_incoterm is not null then 100 else 0 end,',
'          ''CODIGO'',',
'          l_inv.codigo_incoterm,',
'          l_inv.codigo_incoterm',
'        )',
'      );',
'',
'      l_res.id_moeda := resolve_moeda(l_inv.id_tenant, l_inv.id_moeda_json, l_inv.codigo_moeda, l_gaps);',
'      put_confidence(',
'        l_confidence,',
'        ''moeda'',',
'        make_match(',
'          l_res.id_moeda,',
'          case when l_res.id_moeda is not null then 100 else 0 end,',
'          ''CODIGO'',',
'          l_inv.codigo_moeda,',
'          l_inv.codigo_moeda',
'        )',
'      );',
'    end if;',
'',
'    for r in (',
'      select *',
'        from json_table(',
'          p_json,',
'          ''$.items[*]''',
'          columns',
'            item_index               for ordinality,',
'            sequencia_item_invoice   number        path ''$.sequencia_item_invoice'' null on error,',
'            id_entrega_json          number        path ''$.entrega.id_entrega'' null on error,',
'            referencia_entrega       varchar2(100) path ''$.entrega.referencia_extraida'' null on error,',
'            id_entrega_item_json     number        path ''$.entrega_item.id_entrega_item'' null on error,',
'            referencia_entrega_item  varchar2(100) path ''$.entrega_item.referencia_extraida'' null on error,',
'            id_item_json             number        path ''$.item.id_item'' null on error,',
'            codigo_item              varchar2(100) path ''$.item.codigo_extraido'' null on error,',
'            descricao_item           varchar2(4000) path ''$.item.descricao_extraida'' null on error,',
'            id_ncm_json              number        path ''$.ncm.id_ncm'' null on error,',
'            codigo_ncm               varchar2(20)  path ''$.ncm.codigo_extraido'' null on error,',
'            id_unidademedida_json    number        path ''$.unidade_medida.id_unidademedida'' null on error,',
'            codigo_unidademedida     varchar2(20)  path ''$.unidade_medida.codigo_extraido'' null on error,',
'            quantidade               number        path ''$.quantidade'' null on error,',
'            peso_unitario            number        path ''$.pesos.peso_unitario'' null on error,',
'            peso_liquido_total       number        path ''$.pesos.peso_liquido_total'' null on error,',
'            peso_bruto_unitario      number        path ''$.pesos.peso_bruto_unitario'' null on error,',
'            peso_bruto_total         number        path ''$.pesos.peso_bruto_total'' null on error,',
'            valor_unitario           number        path ''$.valores.valor_unitario'' null on error,',
'            valor_desconto           number        path ''$.valores.valor_desconto'' null on error,',
'            valor_total_cond_venda   number        path ''$.valores.valor_total_condicao_venda'' null on error,',
'            valor_total_desc_item    number        path ''$.valores.valor_total_desconto_invoice_item'' null on error,',
'            valor_total_mercadoria   number        path ''$.valores.valor_total_mercadoria'' null on error,',
'            valor_total_desp_item    number        path ''$.valores.valor_total_despesa_invoice_item'' null on error,',
'            id_fabricante_json       number        path ''$.fabricante.id_fabricante'' null on error,',
'            nome_fabricante          varchar2(150) path ''$.fabricante.nome_extraido'' null on error,',
'            id_pais_origem_json      number        path ''$.pais_origem.id_pais_origem'' null on error,',
'            codigo_pais_origem       varchar2(10)  path ''$.pais_origem.codigo_extraido'' null on error,',
'            nome_pais_origem         varchar2(100) path ''$.pais_origem.nome_extraido'' null on error',
'        )',
'    ) loop',
'      l_item_count := l_item_count + 1;',
'      l_scope := ''items['' || to_char(r.item_index - 1) || '']'';',
'',
'      l_items(l_item_count).item_index := r.item_index;',
'      l_items(l_item_count).sequencia_item_invoice := nvl(r.sequencia_item_invoice, r.item_index);',
'      l_items(l_item_count).id_entrega_json := r.id_entrega_json;',
'      l_items(l_item_count).referencia_entrega := r.referencia_entrega;',
'      l_items(l_item_count).id_entrega_item_json := r.id_entrega_item_json;',
'      l_items(l_item_count).referencia_entrega_item := r.referencia_entrega_item;',
'      l_items(l_item_count).id_item_json := r.id_item_json;',
'      l_items(l_item_count).codigo_item := r.codigo_item;',
'      l_items(l_item_count).descricao_item := r.descricao_item;',
'      l_items(l_item_count).id_ncm_json := r.id_ncm_json;',
'      l_items(l_item_count).codigo_ncm := r.codigo_ncm;',
'      l_items(l_item_count).id_unidademedida_json := r.id_unidademedida_json;',
'      l_items(l_item_count).codigo_unidademedida := r.codigo_unidademedida;',
'      l_items(l_item_count).quantidade := r.quantidade;',
'      l_items(l_item_count).peso_unitario := r.peso_unitario;',
'      l_items(l_item_count).peso_liquido_total := r.peso_liquido_total;',
'      l_items(l_item_count).peso_bruto_unitario := r.peso_bruto_unitario;',
'      l_items(l_item_count).peso_bruto_total := r.peso_bruto_total;',
'      l_items(l_item_count).valor_unitario := r.valor_unitario;',
'      l_items(l_item_count).valor_desconto := r.valor_desconto;',
'      l_items(l_item_count).valor_total_cond_venda := r.valor_total_cond_venda;',
'      l_items(l_item_count).valor_total_desc_item := r.valor_total_desc_item;',
'      l_items(l_item_count).valor_total_mercadoria := r.valor_total_mercadoria;',
'      l_items(l_item_count).valor_total_desp_item := r.valor_total_desp_item;',
'      l_items(l_item_count).id_fabricante_json := r.id_fabricante_json;',
'      l_items(l_item_count).nome_fabricante := r.nome_fabricante;',
'      l_items(l_item_count).id_pais_origem_json := r.id_pais_origem_json;',
'      l_items(l_item_count).codigo_pais_origem := r.codigo_pais_origem;',
'      l_items(l_item_count).nome_pais_origem := r.nome_pais_origem;',
'',
'      if l_inv.id_tenant is not null then',
'        l_items(l_item_count).id_item := resolve_item(l_inv.id_tenant, r.id_item_json, r.codigo_item, r.descricao_item, l_scope, l_gaps);',
'        l_items(l_item_count).id_ncm := resolve_ncm(l_inv.id_tenant, r.id_ncm_json, r.codigo_ncm, l_scope, l_gaps);',
'        l_items(l_item_count).id_unidademedida := resolve_unidade(l_inv.id_tenant, r.id_unidademedida_json, r.codigo_unidademedida, l_items(l_item_count).id_item, l_items(l_item_count).id_ncm, l_scope, l_gaps);',
'        l_items(l_item_count).id_entrega := resolve_entrega(',
'          l_inv.id_tenant,',
'          l_inv.id_processoimportacao,',
'          l_res.id_pedidoimportacao,',
'          l_items(l_item_count).id_item,',
'          l_items(l_item_count).id_ncm,',
'          r.codigo_ncm,',
'          r.id_entrega_json,',
'          r.referencia_entrega,',
'          l_scope,',
'          l_gaps',
'        );',
'        l_items(l_item_count).id_entrega_item := resolve_entrega_item(',
'          l_inv.id_tenant,',
'          r.id_entrega_item_json,',
'          l_items(l_item_count).id_entrega,',
'          l_items(l_item_count).id_item,',
'          l_items(l_item_count).id_ncm,',
'          r.codigo_ncm,',
'          l_scope,',
'          l_gaps',
'        );',
'        l_items(l_item_count).id_fabricante := resolve_person(l_inv.id_tenant, r.id_fabricante_json, r.nome_fabricante, null, l_scope, ''items[].fabricante.id_fabricante'', ''N'', l_gaps);',
'        l_items(l_item_count).id_pais_origem := resolve_pais(l_inv.id_tenant, r.id_pais_origem_json, r.codigo_pais_origem, r.nome_pais_origem, l_scope, l_gaps);',
'      end if;',
'',
'      if r.quantidade is null then',
'        add_gap(l_gaps, ''ERROR'', l_scope, ''items[].quantidade'', ''Quantidade e obrigatoria.'');',
'      end if;',
'      if r.valor_unitario is null then',
'        add_gap(l_gaps, ''ERROR'', l_scope, ''items[].valores.valor_unitario'', ''Valor unitario e obrigatorio.'');',
'      end if;',
'      if r.valor_total_cond_venda is null then',
'        add_gap(l_gaps, ''ERROR'', l_scope, ''items[].valores.valor_total_condicao_venda'', ''Valor total da condicao de venda e obrigatorio.'');',
'      end if;',
'',
'      add_resolved_item(l_resolved_items, l_items(l_item_count));',
'    end loop;',
'',
'    if l_item_count = 0 then',
'      add_gap(l_gaps, ''ERROR'', ''items'', ''items'', ''Nenhum item encontrado no JSON.'');',
'    end if;',
'',
'    l_resolved.put(''id_pedidoimportacao'', l_res.id_pedidoimportacao);',
'    l_resolved.put(''numero_pedido_importacao_extraido'', l_inv.numero_pedido_importacao);',
'    l_resolved.put(''rotulo_referencia_pedido'', l_inv.rotulo_referencia_pedido);',
'    l_resolved.put(''id_exportador'', l_res.id_exportador);',
'    l_resolved.put(''id_importador'', l_res.id_importador);',
'    l_resolved.put(''id_adquirente'', l_res.id_adquirente);',
'    l_resolved.put(''id_condicaopagamento'', l_res.id_condicaopagamento);',
'    l_resolved.put(''id_incoterm'', l_res.id_incoterm);',
'    l_resolved.put(''id_moeda'', l_res.id_moeda);',
'    l_resolved.put(''items'', l_resolved_items);',
'',
'    if gap_count(l_gaps, ''ERROR'') > 0 then',
'      l_result.put(''status'', ''VALIDATION_FAILED'');',
'      l_result.put(''imported'', false);',
'      l_result.put(''invoice_id'', l_invoice_id);',
'      l_result.put(''item_count'', l_item_count);',
'      l_result.put(''resolved'', l_resolved);',
'      l_result.put(''confidence'', l_confidence);',
'      l_result.put(''gaps'', l_gaps);',
'      return l_result.to_clob;',
'    end if;',
'',
'    if yn_is_true(p_validate_only_yn) then',
'      l_result.put(''status'', ''VALID'');',
'      l_result.put(''imported'', false);',
'      l_result.put(''invoice_id'', l_invoice_id);',
'      l_result.put(''item_count'', l_item_count);',
'      l_result.put(''resolved'', l_resolved);',
'      l_result.put(''confidence'', l_confidence);',
'      l_result.put(''gaps'', l_gaps);',
'      return l_result.to_clob;',
'    end if;',
'',
'    insert into imp_invoice (',
'      id_tenant,',
'      id_processoimportacao,',
'      num_invoice,',
'      data_invoice,',
'      ind_status,',
'      id_exportador,',
'      id_importador,',
'      id_adquirente,',
'      id_condicaopagamento,',
'      id_incoterm,',
'      id_moeda,',
'      ind_forma_pagamento,',
'      peso_liquido,',
'      peso_bruto,',
'      valor_total_mercadoria,',
'      valor_desconto,',
'      valor_despesa_invoice,',
'      valor_total_condicao_venda,',
'      ind_situacao_titulo_pagamento,',
'      ind_divergencia,',
'      id_usuario_incluiu,',
'      motivo_desconto,',
'      valor_compensado,',
'      valor_invoice_informado,',
'      ind_tratamento_saldo,',
'      valor_total_financeiro',
'    ) values (',
'      l_inv.id_tenant,',
'      l_inv.id_processoimportacao,',
'      l_inv.num_invoice,',
'      l_inv.data_invoice,',
'      l_inv.ind_status,',
'      l_res.id_exportador,',
'      l_res.id_importador,',
'      l_res.id_adquirente,',
'      l_res.id_condicaopagamento,',
'      l_res.id_incoterm,',
'      l_res.id_moeda,',
'      l_inv.ind_forma_pagamento,',
'      l_inv.peso_liquido,',
'      l_inv.peso_bruto,',
'      l_inv.valor_total_mercadoria,',
'      l_inv.valor_desconto,',
'      l_inv.valor_despesa_invoice,',
'      l_inv.valor_total_cond_venda,',
'      l_inv.ind_situacao_titulo,',
'      l_inv.ind_divergencia,',
'      l_inv.id_usuario_incluiu,',
'      l_inv.motivo_desconto,',
'      l_inv.valor_compensado,',
'      l_inv.valor_invoice_informado,',
'      l_inv.ind_tratamento_saldo,',
'      l_inv.valor_total_financeiro',
'    )',
'    returning id into l_invoice_id;',
'',
'    for i in 1 .. l_item_count loop',
'      insert into imp_invoice_item (',
'        id_tenant,',
'        id_invoice,',
'        id_entrega,',
'        id_entrega_item,',
'        sequencia_item_invoice,',
'        id_item,',
'        id_ncm,',
'        id_unidademedida,',
'        quantidade,',
'        peso_unitario,',
'        peso_liquido_total,',
'        valor_unitario,',
'        valor_desconto,',
'        valor_total_condicao_venda,',
'        id_fabricante,',
'        id_pais_origem,',
'        id_usuario_incluiu,',
'        peso_bruto_unitario,',
'        peso_bruto_total,',
'        valor_total_desconto_invoice_item,',
'        valor_total_mercadoria,',
'        valor_total_despesa_invoice_item',
'      ) values (',
'        l_inv.id_tenant,',
'        l_invoice_id,',
'        l_items(i).id_entrega,',
'        l_items(i).id_entrega_item,',
'        l_items(i).sequencia_item_invoice,',
'        l_items(i).id_item,',
'        l_items(i).id_ncm,',
'        l_items(i).id_unidademedida,',
'        l_items(i).quantidade,',
'        l_items(i).peso_unitario,',
'        l_items(i).peso_liquido_total,',
'        l_items(i).valor_unitario,',
'        l_items(i).valor_desconto,',
'        l_items(i).valor_total_cond_venda,',
'        l_items(i).id_fabricante,',
'        l_items(i).id_pais_origem,',
'        l_inv.id_usuario_incluiu,',
'        l_items(i).peso_bruto_unitario,',
'        l_items(i).peso_bruto_total,',
'        l_items(i).valor_total_desc_item,',
'        l_items(i).valor_total_mercadoria,',
'        l_items(i).valor_total_desp_item',
'      );',
'    end loop;',
'',
'    if yn_is_true(p_commit_yn) then',
'      commit;',
'    end if;',
'',
'    l_result.put(''status'', ''IMPORTED'');',
'    l_result.put(''imported'', true);',
'    l_result.put(''invoice_id'', l_invoice_id);',
'    l_result.put(''item_count'', l_item_count);',
'    l_result.put(''resolved'', l_resolved);',
'    l_result.put(''confidence'', l_confidence);',
'    l_result.put(''gaps'', l_gaps);',
'    return l_result.to_clob;',
'  exception',
'    when others then',
'      rollback to ai_invoice_import_sp;',
'      add_gap(l_gaps, ''ERROR'', ''runtime'', ''import_json'', sqlerrm);',
'      l_result.put(''status'', ''ERROR'');',
'      l_result.put(''imported'', false);',
'      l_result.put(''invoice_id'', l_invoice_id);',
'      l_result.put(''item_count'', l_item_count);',
'      l_result.put(''resolved'', l_resolved);',
'      l_result.put(''confidence'', l_confidence);',
'      l_result.put(''gaps'', l_gaps);',
'      return l_result.to_clob;',
'  end import_json;',
'',
'  function import_page_429(',
'    p_id_tenant                  in imp_invoice.id_tenant%type,',
'    p_id_processoimportacao      in imp_invoice.id_processoimportacao%type,',
'    p_id_pedidoimportacao        in number default null,',
'    p_num_invoice                in imp_invoice.num_invoice%type,',
'    p_data_invoice               in imp_invoice.data_invoice%type,',
'    p_ind_status                 in imp_invoice.ind_status%type,',
'    p_id_exportador              in imp_invoice.id_exportador%type,',
'    p_id_importador              in imp_invoice.id_importador%type,',
'    p_id_adquirente              in imp_invoice.id_adquirente%type default null,',
'    p_id_condicaopagamento       in imp_invoice.id_condicaopagamento%type,',
'    p_id_incoterm                in imp_invoice.id_incoterm%type,',
'    p_id_moeda                   in imp_invoice.id_moeda%type,',
'    p_peso_liquido               in imp_invoice.peso_liquido%type default null,',
'    p_peso_bruto                 in imp_invoice.peso_bruto%type default null,',
'    p_valor_total_mercadoria     in imp_invoice.valor_total_mercadoria%type default null,',
'    p_valor_desconto             in imp_invoice.valor_desconto%type default null,',
'    p_valor_despesa_invoice      in imp_invoice.valor_despesa_invoice%type default null,',
'    p_valor_total_cond_venda     in imp_invoice.valor_total_condicao_venda%type default null,',
'    p_valor_invoice_informado    in imp_invoice.valor_invoice_informado%type default null,',
'    p_nome_exportador            in varchar2 default null,',
'    p_doc_exportador             in varchar2 default null,',
'    p_nome_importador            in varchar2 default null,',
'    p_doc_importador             in varchar2 default null,',
'    p_nome_adquirente            in varchar2 default null,',
'    p_codigo_incoterm            in varchar2 default null,',
'    p_codigo_moeda               in varchar2 default null,',
'    p_desc_condpagto             in varchar2 default null,',
'    p_num_pedido_importacao      in varchar2 default null,',
'    p_referencia_pedido_original in varchar2 default null,',
'    p_id_usuario_incluiu         in number default null,',
'    p_validate_only_yn           in varchar2 default ''N'',',
'    p_commit_yn                  in varchar2 default ''N''',
'  ) return clob is',
'    l_inv             t_invoice_ctx;',
'    l_res             t_resolved_invoice;',
'    l_items           t_item_tab;',
'    l_item_count      pls_integer := 0;',
'    l_invoice_id      imp_invoice.id%type;',
'    l_duplicate_id    imp_invoice.id%type;',
'    l_duplicate_count number;',
'    l_result          json_object_t := json_object_t();',
'    l_gaps            json_array_t := json_array_t();',
'    l_resolved        json_object_t := json_object_t();',
'    l_resolved_items  json_array_t := json_array_t();',
'    l_confidence      json_object_t := json_object_t();',
'    l_match           t_match_result;',
'    l_scope           varchar2(80);',
'    l_invoice_item_id imp_invoice_item.id%type;',
'    l_sucesso         clob;',
'    l_messages        pkg_mensagem.message_record_table;',
'',
'    function to_num(p_value in varchar2) return number is',
'        l_value varchar2(4000);',
'    begin',
'        l_value := trim(p_value);',
'',
'        if l_value is null then',
'            return null;',
'        end if;',
'',
unistr('        -- Remove espa\00E7os'),
'        l_value := replace(l_value, '' '', '''');',
'',
unistr('        -- Remove s\00EDmbolos comuns, se eventualmente vierem da IA/PDF'),
'        l_value := replace(l_value, ''R$'', '''');',
'        l_value := replace(l_value, ''$'', '''');',
'',
'        /*',
'          Trata formatos:',
'          0.362       -> 0.362',
'          0,362       -> 0.362',
'          1,234.56    -> 1234.56',
'          1.234,56    -> 1234.56',
'        */',
'',
'        if instr(l_value, ''.'') > 0 and instr(l_value, '','') > 0 then',
'',
'            -- Formato brasileiro: 1.234,56',
'            if instr(l_value, '','') > instr(l_value, ''.'') then',
'                l_value := replace(l_value, ''.'', '''');',
'                l_value := replace(l_value, '','', ''.'');',
'',
'            -- Formato americano: 1,234.56',
'            else',
'                l_value := replace(l_value, '','', '''');',
'            end if;',
'',
'        elsif instr(l_value, '','') > 0 then',
'',
'            -- Exemplo: 0,362',
'            l_value := replace(l_value, '','', ''.'');',
'',
'        end if;',
'',
'        return to_number(',
'            l_value,',
'            ''999999999999999999999999999999D999999999999999999999999999999'',',
'            ''NLS_NUMERIC_CHARACTERS = ''''.,''''''',
'        );',
'',
'    exception',
'        when others then',
'            raise_application_error(',
'                -20001,',
unistr('                ''Erro ao converter n\00FAmero. Valor original: ['' || p_value || ''] Valor tratado: ['' || l_value || ''] Erro: '' || sqlerrm'),
'            );',
'    end to_num;',
'  begin',
'    --savepoint ai_invoice_import_sp;',
'',
'    l_inv.id_tenant := p_id_tenant;',
'    l_inv.id_processoimportacao := p_id_processoimportacao;',
'    l_inv.id_usuario_incluiu := p_id_usuario_incluiu;',
'    l_inv.num_invoice := p_num_invoice;',
'    l_inv.data_invoice := p_data_invoice;',
'    l_inv.ind_status := p_ind_status;',
'    l_inv.id_exportador_json := p_id_exportador;',
'    l_inv.nome_exportador := p_nome_exportador;',
'    l_inv.doc_exportador := p_doc_exportador;',
'    l_inv.id_importador_json := p_id_importador;',
'    l_inv.nome_importador := p_nome_importador;',
'    l_inv.doc_importador := p_doc_importador;',
'    l_inv.id_adquirente_json := p_id_adquirente;',
'    l_inv.nome_adquirente := p_nome_adquirente;',
'    l_inv.id_condpagto_json := p_id_condicaopagamento;',
'    l_inv.desc_condpagto := p_desc_condpagto;',
'    l_inv.id_incoterm_json := p_id_incoterm;',
'    l_inv.codigo_incoterm := p_codigo_incoterm;',
'    l_inv.id_moeda_json := p_id_moeda;',
'    l_inv.codigo_moeda := p_codigo_moeda;',
'    l_inv.id_pedidoimportacao_json := p_id_pedidoimportacao;',
'    l_inv.numero_pedido_importacao := p_num_pedido_importacao;',
'    l_inv.rotulo_referencia_pedido := p_referencia_pedido_original;',
'    l_inv.peso_liquido := p_peso_liquido;',
'    l_inv.peso_bruto := p_peso_bruto;',
'    l_inv.valor_total_mercadoria := p_valor_total_mercadoria;',
'    l_inv.valor_desconto := p_valor_desconto;',
'    l_inv.valor_despesa_invoice := p_valor_despesa_invoice;',
'    l_inv.valor_total_cond_venda := p_valor_total_cond_venda;',
'    l_inv.valor_invoice_informado := p_valor_invoice_informado;',
'',
'    validate_context(l_inv, l_gaps);',
'',
'    if l_inv.id_tenant is not null then',
'      select min(id), count(*)',
'        into l_duplicate_id, l_duplicate_count',
'        from imp_invoice',
'       where id_tenant = l_inv.id_tenant',
'         and num_invoice = l_inv.num_invoice;',
'',
'      if l_duplicate_count > 0 then',
'        add_gap(l_gaps, ''ERROR'', ''invoice'', ''invoice.num_invoice'', ''Ja existe invoice importada com este numero para o tenant.'', l_inv.num_invoice);',
'      end if;',
'',
'      l_match := resolve_person_match(l_inv.id_tenant, l_inv.id_exportador_json, l_inv.nome_exportador, l_inv.doc_exportador, ''invoice'', ''invoice.exportador.id_exportador'', ''S'', l_gaps);',
'      l_res.id_exportador := l_match.id_resolvido;',
'      put_confidence(l_confidence, ''exportador'', l_match);',
'',
'      l_match := resolve_person_match(l_inv.id_tenant, l_inv.id_importador_json, l_inv.nome_importador, l_inv.doc_importador, ''invoice'', ''invoice.importador.id_importador'', ''S'', l_gaps);',
