prompt --application/deployment/install/install_calcular_similaridade_texto
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(243455153411541192)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'CALCULAR_SIMILARIDADE_TEXTO'
,p_sequence=>3570
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace FUNCTION calcular_similaridade_texto (',
'    p_texto_1 IN VARCHAR2,',
'    p_texto_2 IN VARCHAR2',
') RETURN NUMBER',
'IS',
'    l_texto_1 VARCHAR2(4000);',
'    l_texto_2 VARCHAR2(4000);',
'',
'    l_len_1 PLS_INTEGER;',
'    l_len_2 PLS_INTEGER;',
'',
'    TYPE t_array IS TABLE OF PLS_INTEGER INDEX BY PLS_INTEGER;',
'',
'    l_v0 t_array;',
'    l_v1 t_array;',
'',
'    l_custo     PLS_INTEGER;',
'    l_distancia PLS_INTEGER;',
'    l_max_len   PLS_INTEGER;',
'',
'    FUNCTION normalizar_texto (',
'        p_texto IN VARCHAR2',
'    ) RETURN VARCHAR2',
'    IS',
'        l_texto VARCHAR2(4000);',
'    BEGIN',
'        IF p_texto IS NULL THEN',
'            RETURN NULL;',
'        END IF;',
'',
'        l_texto := LOWER(TRIM(p_texto));',
'',
'        -- Remove acentos mais comuns',
'        l_texto := TRANSLATE(',
'            l_texto,',
unistr('            ''\00E1\00E0\00E2\00E3\00E4\00E9\00E8\00EA\00EB\00ED\00EC\00EE\00EF\00F3\00F2\00F4\00F5\00F6\00FA\00F9\00FB\00FC\00E7\00F1\00C1\00C0\00C2\00C3\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D4\00D5\00D6\00DA\00D9\00DB\00DC\00C7\00D1'','),
'            ''aaaaaeeeeiiiiooooouuuucnAAAAAEEEEIIIIOOOOOUUUUCN''',
'        );',
'',
unistr('        -- Remove caracteres especiais, mantendo letras, n\00FAmeros e espa\00E7o'),
'        l_texto := REGEXP_REPLACE(l_texto, ''[^a-z0-9 ]'', '' '');',
'',
unistr('        -- Normaliza m\00FAltiplos espa\00E7os'),
'        l_texto := REGEXP_REPLACE(l_texto, ''\s+'', '' '');',
'',
'        RETURN TRIM(l_texto);',
'    END normalizar_texto;',
'',
'BEGIN',
'    l_texto_1 := normalizar_texto(p_texto_1);',
'    l_texto_2 := normalizar_texto(p_texto_2);',
'',
'    IF l_texto_1 IS NULL AND l_texto_2 IS NULL THEN',
'        RETURN 100;',
'    END IF;',
'',
'    IF l_texto_1 IS NULL OR l_texto_2 IS NULL THEN',
'        RETURN 0;',
'    END IF;',
'',
'    IF l_texto_1 = l_texto_2 THEN',
'        RETURN 100;',
'    END IF;',
'',
'    l_len_1 := LENGTH(l_texto_1);',
'    l_len_2 := LENGTH(l_texto_2);',
'',
'    IF l_len_1 = 0 AND l_len_2 = 0 THEN',
'        RETURN 100;',
'    END IF;',
'',
'    IF l_len_1 = 0 OR l_len_2 = 0 THEN',
'        RETURN 0;',
'    END IF;',
'',
'    -- Inicializa primeira linha',
'    FOR i IN 0 .. l_len_2 LOOP',
'        l_v0(i) := i;',
'    END LOOP;',
'',
unistr('    -- Calcula dist\00E2ncia de Levenshtein'),
'    FOR i IN 1 .. l_len_1 LOOP',
'        l_v1(0) := i;',
'',
'        FOR j IN 1 .. l_len_2 LOOP',
'            IF SUBSTR(l_texto_1, i, 1) = SUBSTR(l_texto_2, j, 1) THEN',
'                l_custo := 0;',
'            ELSE',
'                l_custo := 1;',
'            END IF;',
'',
'            l_v1(j) := LEAST(',
unistr('                l_v1(j - 1) + 1,        -- inser\00E7\00E3o'),
unistr('                l_v0(j) + 1,            -- remo\00E7\00E3o'),
unistr('                l_v0(j - 1) + l_custo   -- substitui\00E7\00E3o'),
'            );',
'        END LOOP;',
'',
'        FOR j IN 0 .. l_len_2 LOOP',
'            l_v0(j) := l_v1(j);',
'        END LOOP;',
'    END LOOP;',
'',
'    l_distancia := l_v0(l_len_2);',
'    l_max_len   := GREATEST(l_len_1, l_len_2);',
'',
'    RETURN ROUND((1 - (l_distancia / l_max_len)) * 100, 2);',
'END calcular_similaridade_texto;',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_traducao
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(243456567728548645)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'PKG_TRADUCAO'
,p_sequence=>3580
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "PKG_TRADUCAO" as ',
' ',
'    procedure criar_traducao(p_id_aplicacao number, p_codigo_idioma varchar2, p_new_id_apliacao number, p_retorno out varchar2); ',
' ',
'    procedure exclui(p_id_aplicacao number, p_codigo_idioma varchar2); ',
' ',
'    procedure substituir_textos(p_id_aplicacao number, p_codigo_idioma varchar2); ',
'    procedure substituir_textos2(p_id_aplicacao number, p_codigo_idioma varchar2); ',
' ',
'    procedure altera_traducao(p_id_aplicacao number, p_from_string varchar2, p_language varchar2, p_to_string varchar2); ',
' ',
'    function lista_traducao(p_id_aplicacao number)return varchar2; ',
'',
'    function traduzir_descricao(',
'        p_esquema varchar2,',
'        p_entidade varchar2,',
'        p_campo varchar2,',
'        p_id_idioma_usuario number,',
'        p_id_registro number',
'    ) return clob;   ',
'',
'    FUNCTION traduzir_descricao_otimizada(',
'        p_esquema           VARCHAR2,',
'        p_entidade          VARCHAR2,',
'        p_campo             VARCHAR2,',
'        p_id_idioma_usuario NUMBER,',
'        p_id_registro       NUMBER',
'    ) RETURN CLOB;',
'',
'    FUNCTION extrair_mensagem_erro (',
'        p_erro IN VARCHAR2',
'    ) RETURN VARCHAR2;',
'',
'    procedure grava_traducao (',
'        p_texto            in varchar2,',
'        p_id_tenant        in number,',
'        p_sucesso          out clob,',
'        p_messages         out pkg_mensagem.message_record_table,',
'        p_observacao       in boolean default false,',
'        p_descricao_item   in boolean default false',
'    );',
'',
'    function get_traducao (',
'        p_texto              in varchar2,',
'        p_id_idioma          in number default apex_util.get_session_state(''IDIOMA_LOGADO''),',
'        p_observacao_ou_item in boolean default false,',
'        p_id_tenant          in number default null,',
'        p_id_finalidade      in number default null,',
'        p_id_pessoa          in number default null,',
'        p_id_pais            in number default null,',
'        p_id_carta_credito   in number default null ',
'    ) return varchar2;',
'',
'    ',
'',
'    function traduzir_texto_api_externa (',
'        p_texto        IN VARCHAR2,',
'        p_lang_destino IN VARCHAR2,',
'        p_email        IN VARCHAR2 DEFAULT ''northonn@gmail.com'',',
'        p_lang_origem  IN VARCHAR2 DEFAULT ''pt-br'',',
'        p_resultado    out boolean',
'    ) RETURN VARCHAR2; ',
'',
'    function traduzir_texto_auto (',
'        p_texto        IN VARCHAR2,',
'        p_lang_destino IN VARCHAR2',
'    ) RETURN VARCHAR2;',
'',
'    FUNCTION detectar_idioma_texto (',
'        p_texto IN VARCHAR2',
'    ) RETURN VARCHAR2;   ',
'',
'    FUNCTION mapear_idioma_oracle_api (',
'        p_idioma_oracle IN VARCHAR2',
'    ) RETURN VARCHAR2;      ',
'',
'end "PKG_TRADUCAO";',
'/',
'',
'create or replace package body "PKG_TRADUCAO" as ',
' ',
'    procedure criar_traducao(p_id_aplicacao number, p_codigo_idioma varchar2, p_new_id_apliacao number, p_retorno out varchar2) ',
'    is ',
'        lc_entire_msg clob; ',
'        l_status_code VARCHAR2(5); ',
'        l_codigo_idioma VARCHAR2(5); ',
'    begin ',
'        -- apex_util.set_security_group_id( apex_application_install.get_workspace_id ); ',
'        for c1 in (select workspace_id from apex_applications where application_id = p_id_aplicacao ) loop ',
'            apex_util.set_security_group_id( c1.workspace_id ); ',
'            exit; ',
'        end loop; ',
' ',
'        apex_lang.create_language_mapping( ',
'            p_application_id => p_id_aplicacao, ',
'            p_language => p_codigo_idioma, ',
'            p_translation_application_id => p_new_id_apliacao ); ',
'        commit; ',
' ',
'        apex_lang.seed_translations( ',
'            p_application_id => p_id_aplicacao, ',
'            p_language => p_codigo_idioma ); ',
'        commit; ',
' ',
'        p_retorno := pk_constants.c_msg_success;     ',
'               ',
'        exception ',
'            when others then ',
'                p_retorno := pk_constants.c_msg_error;       ',
unistr('                raise_application_error(-20111,''Ocorreu um erro ao realizar a cria\00E7\00E3o do idioma. Erro:''||SQLERRM);              '),
' ',
'    end criar_traducao; ',
' ',
'    procedure exclui(p_id_aplicacao number, p_codigo_idioma varchar2) ',
'    is ',
'    begin ',
'        for c1 in (select workspace_id from apex_applications where application_id = p_id_aplicacao ) loop ',
'            apex_util.set_security_group_id( c1.workspace_id ); ',
'            exit; ',
'        end loop; ',
' ',
'        APEX_LANG.DELETE_LANGUAGE_MAPPING ( ',
'            p_application_id => p_id_aplicacao, ',
'            p_language => lower(p_codigo_idioma)); ',
' ',
'        commit; ',
' ',
'        exception ',
'            when others then   ',
unistr('                raise_application_error(-20111,''Ocorreu um erro ao realizar a exclus\00E3o do idioma. Erro:''||SQLERRM);     '),
'    end exclui; ',
' ',
'    procedure substituir_textos(p_id_aplicacao number, p_codigo_idioma varchar2) ',
'    is ',
'        lc_entire_msg clob; ',
'        lc_entire_msg1 clob; ',
'        l_status_code VARCHAR2(5); ',
'        l_existe_texto number; ',
'        l_descricao varchar2(2000); ',
'        l_tag varchar2(2000); ',
'        l_tabela varchar2(256);',
'        l_campo varchar2(256);',
'        l_to_string clob;',
'        l_id_idioma srv_idioma.id%type;',
'    begin ',
'        select id into l_id_idioma from srv_idioma where codigo = p_codigo_idioma;',
'',
unistr('        --apex_debug.warn(''Fun\00E7\00E3o: substituir_textos''); '),
'        for c1 in (',
'            select workspace_id from apex_applications where application_id = p_id_aplicacao ) loop ',
'            apex_util.set_security_group_id( c1.workspace_id); ',
'            exit; ',
'        end loop; ',
'',
'        for c_transp in (  ',
'            select id, from_string, to_string, internal_attribute_name',
'            from apex_application_trans_repos  ',
'            where application_id = p_id_aplicacao ',
'            and internal_attribute_name	in (',
'                ''APEX_PAGE_BUTTONS.BUTTON_IMAGE_ALT'',',
'                ''APEX_CARD_ACTIONS.LABEL'',',
'                ''APEX_PAGE_REGIONS.PLUG_NAME'',',
'                ''APEX_PAGE_ITEMS.PROMPT'',',
'                ''APEX_PAGE_ITEMS.PLACEHOLDER'',',
'                ''APEX_PAGE_ITEM_HELP.HELP_TEXT''',
'            )',
'        ) loop ',
'            begin',
'                -- APEX_DEBUG.ERROR(''substituir_textos p_codigo_idioma: ''||p_codigo_idioma);                                     ',
'                l_to_string := null;',
'                if c_transp.internal_attribute_name in (''APEX_CARD_ACTIONS.LABEL'',''APEX_PAGE_BUTTONS.BUTTON_IMAGE_ALT'',''APEX_PAGE_REGIONS.PLUG_NAME'') then',
'                    if p_codigo_idioma = ''pt-br'' then',
'                        Select a.label into l_to_string',
'                        from srv_aplicacao_texto a ',
'                        where lower(tag) = lower(to_char(c_transp.from_string));',
'                    else',
'                        select b.label into l_to_string',
'                        from srv_aplicacao_texto a',
'                        join srv_texto_traduzido b on b.id_texto = a.id',
'                        join srv_idioma c on c.id = b.id_idioma',
'                        where lower(c.codigo) = lower(p_codigo_idioma)',
'                        and lower(tag) = lower(to_char(c_transp.from_string));',
'                    end if;',
'                else',
'                    if dividir_tag(c_transp.from_string,l_tabela,l_campo) then',
'                        Select case ',
'                            when c_transp.internal_attribute_name = ''APEX_PAGE_ITEMS.PROMPT'' then label',
'                            when c_transp.internal_attribute_name = ''APEX_PAGE_ITEMS.PLACEHOLDER'' then instrucao',
'                            when c_transp.internal_attribute_name = ''APEX_PAGE_ITEM_HELP.HELP_TEXT'' then help',
'                        end into l_to_string ',
'                        from srv_entidade_coluna A ',
'                        join srv_entidade b on b.id = a.id_entidade ',
'                        where lower(b.nome_entidade) = lower(l_tabela)',
'                        and lower(nome_coluna) = lower(l_campo);',
'                    end if;    ',
'                end if;   ',
'                if l_to_string is not null then',
'                    apex_lang.update_translated_string( ',
'                        p_id => c_transp.id, ',
'                        p_language => p_codigo_idioma, ',
'                        p_string => l_to_string); ',
'                end if;',
'            exception            ',
'                when no_data_found then',
'                    null;    ',
'            end;            ',
'        end loop;     ',
' ',
'        apex_lang.publish_application( ',
'            p_application_id => p_id_aplicacao, ',
'            p_language => p_codigo_idioma );',
' ',
'    end substituir_textos; ',
'',
'    procedure substituir_textos2(p_id_aplicacao number, p_codigo_idioma varchar2) ',
'    is ',
'        l_to_string clob;',
'        l_id_idioma srv_idioma.id%type;',
'        l_houve_alteracao boolean default false;',
'        l_count number;',
'        i number := 0;',
'    begin ',
'        select id into l_id_idioma from srv_idioma where lower(codigo) = lower(p_codigo_idioma);',
'',
unistr('        --apex_debug.warn(''Fun\00E7\00E3o: substituir_textos''); '),
'        for c1 in (',
'            select workspace_id from apex_applications where application_id = p_id_aplicacao ) loop ',
'            apex_util.set_security_group_id( c1.workspace_id); ',
'            exit; ',
'        end loop; ',
'',
'        select count(1) into l_count from mpd_traducao_apex where id_idioma = l_id_idioma;',
'',
'        for c_mpd_traducao_apex in (  ',
'            select * from mpd_traducao_apex where id_idioma = l_id_idioma',
'        ) loop ',
'            i := i + 1;',
'            apex_background_process.set_status(',
unistr('                p_message => ''Criando a aplica\00E7\00E3o de tradu\00E7\00E3o (''||i||''/''||l_count||'')'''),
'            );',
'',
'            apex_background_process.set_progress(',
'                p_totalwork => l_count,',
'                p_sofar => i',
'            );',
'',
'            for c_apex_application_trans_repos in (',
'                select id',
'                from apex_application_trans_repos ',
'                where application_id = p_id_aplicacao ',
'                and lower(to_char(from_string)) = lower(c_mpd_traducao_apex.tag)',
'            ) loop',
'                apex_lang.update_translated_string( ',
'                    p_id => c_apex_application_trans_repos.id, ',
'                    p_language => p_codigo_idioma, ',
'                    p_string => c_mpd_traducao_apex.texto_traduzido);             ',
'                l_houve_alteracao := true;                    ',
'            end loop;     ',
'        end loop;     ',
'',
'        if l_houve_alteracao then',
'            apex_lang.publish_application( ',
'                p_application_id => p_id_aplicacao, ',
'                p_language => p_codigo_idioma );',
'        end if;    ',
' ',
'    end substituir_textos2; ',
'',
' ',
'    procedure altera_traducao(p_id_aplicacao number, p_from_string varchar2, p_language varchar2, p_to_string varchar2) ',
'    is ',
'    begin ',
unistr('        -- APEX_DEBUG.ERROR(''DEBUG%% altera_traducao Variavel: p_id_aplicacao * Conte\00FAdo: ''||p_id_aplicacao, SQLERRM); '),
unistr('        -- APEX_DEBUG.ERROR(''DEBUG%% altera_traducao Variavel: p_from_string * Conte\00FAdo: ''||p_from_string, SQLERRM); '),
unistr('        -- APEX_DEBUG.ERROR(''DEBUG%% altera_traducao Variavel: p_language * Conte\00FAdo: ''||p_language, SQLERRM); '),
unistr('        -- APEX_DEBUG.ERROR(''DEBUG%% altera_traducao Variavel: p_to_string * Conte\00FAdo: ''||p_to_string, SQLERRM); '),
'        for c1 in (select workspace_id from apex_applications where application_id = p_id_aplicacao ) loop ',
'            apex_util.set_security_group_id( c1.workspace_id ); ',
'            exit; ',
'        end loop; ',
' ',
'        for c1 in (select distinct id ',
'                     from apex_application_trans_repos ',
'                    where application_id = p_id_aplicacao ',
'                      and dbms_lob.compare(lower(from_string), to_nclob(lower(p_from_string))) = 0 ',
'                      and lower(language_code) = lower(p_language))  ',
'            loop ',
'                apex_lang.update_translated_string( ',
'                    p_id => c1.id, ',
'                    p_language => lower(p_language), ',
'                    p_string => p_to_string); ',
'        end loop; ',
'        commit; ',
' ',
'        /*apex_lang.publish_application( ',
'            p_application_id => p_id_aplicacao, ',
'            p_language => lower(p_language) ); */ ',
' ',
'        exception ',
'        when OTHERS then ',
unistr('            raise_application_error(-20325,''Ocorreu um erro ao realizar a altera\00E7\00E3o da tradu\00E7\00E3o do texto. Erro: ''||SQLERRM);  '),
'    end; ',
' ',
' ',
'    function lista_traducao(p_id_aplicacao number) ',
'    return varchar2 ',
'    is ',
'        l_html varchar2(4000); ',
'    begin ',
'        for lista in ( ',
'            select  ',
'                a.TRANSLATED_APPLICATION_ID,  ',
'                pkg_util.retorna_descricao_idioma_logado(b.id) as idioma, ',
'                (select count(1) from apex_application_trans_repos where application_id = p_id_aplicacao) as TOTAL_TEXTOS,   ',
'                (select count(1) from apex_application_trans_repos where application_id = p_id_aplicacao and dbms_lob.substr(from_string,32767) <> dbms_lob.substr(to_string,32767)) as TOTAL_TEXTOS_TRADUZIDOS   ',
'            from apex_application_trans_map a ',
'            left join srv_idioma b on b.codigo = a.TRANSLATED_APP_LANGUAGE ',
'            where PRIMARY_APPLICATION_ID = p_id_aplicacao ',
'        ) loop ',
'            l_html := l_html || ',
'            ''<div class="a-CardView-body" style="padding: 0">''||',
'                ''<div class="row" style="display: flex; flex-wrap: wrap; justify-content: space-between;">''||',
'                    ''<div>''||',
'                        ''<div style="font-size: 12px; font-style: italic;">Idioma</div>''||',
'                        ''<div style="font-weight: bold;">''||lista.idioma||''</div>''||',
'                    ''</div>''||',
'                    ''<div>''||',
unistr('                        ''<div style="font-size: 12px; font-style: italic;">N\00FAmero da aplica\00E7\00E3o</div>''||'),
'                        ''<div style="font-weight: bold;">''||lista.TRANSLATED_APPLICATION_ID||''</div>''||',
'                    ''</div>''||',
'                    ''<div>''||',
'                        ''<div style="font-size: 12px; font-style: italic;">Total de textos</div>''||',
'                        ''<div style="font-weight: bold;">''||lista.total_textos||''</div>''||',
'                    ''</div>''||',
'                    ''<div>''||',
'                        ''<div style="font-size: 12px; font-style: italic;">Textos traduzidos</div>''||',
'                        ''<div style="font-weight: bold;">''||lista.total_textos_traduzidos||''</div>''||',
'                    ''</div>''||',
'                ''</div>''||        ',
'            ''</div>'';',
'        end loop; ',
'        return l_html; ',
'    end lista_traducao; ',
'',
'    function traduzir_descricao(',
'        p_esquema varchar2,',
'        p_entidade varchar2,',
'        p_campo varchar2,',
'        p_id_idioma_usuario number,',
'        p_id_registro number',
'    ) return clob is',
'        v_sql varchar2(4000);',
'        v_id_idioma_tenant number;',
'        v_id_entidade number;',
'        v_id_coluna number;',
'        v_descricao_original varchar2(4000);',
'        v_descricao_usuario varchar2(4000);',
'        v_id_tenant number;',
'        v_existe_traducao number;',
'        v_dummy number;',
'        v_erroInterno varchar2(4000);',
'    begin',
unistr('        -- Valida\00E7\00E3o: Verifica se o esquema informado existe no banco'),
'        begin',
'            select 1 into v_dummy from all_users where upper(username) = upper(p_esquema);',
'        exception',
'            when no_data_found then',
unistr('                return ''{"erroCod": "ADM-TRA-VAL-001","erroInterno":"Esquema informado n\00E3o existe: ''||p_esquema||''"}'';'),
'            when others then',
'                return ''{"erroCod": "ADM-TRA-VAL-002","erroInterno":"Erro ao validar o esquema: ''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'        end;',
'',
unistr('        -- Valida\00E7\00E3o: Verifica se a tabela (entidade) existe no esquema'),
'        begin',
'            select 1 into v_dummy ',
'            from all_tables ',
'            where upper(table_name) = upper(p_entidade) ',
'              and upper(owner) = upper(p_esquema);',
'        exception',
'            when no_data_found then',
unistr('                return ''{"erroCod": "ADM-TRA-VAL-003","erroInterno":"Entidade informada n\00E3o existe no esquema: ''||p_entidade||''"}'';'),
'            when others then',
'                return ''{"erroCod": "ADM-TRA-VAL-004","erroInterno":"Erro ao validar a entidade: ''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'        end;',
'',
unistr('        -- Valida\00E7\00E3o: Verifica se a coluna existe na tabela informada'),
'        begin',
'            select 1 into v_dummy ',
'            from all_tab_columns ',
'            where upper(column_name) = upper(p_campo)',
'              and upper(table_name) = upper(p_entidade)',
'              and owner = upper(p_esquema);',
'        exception',
'            when no_data_found then',
unistr('                return ''{"erroCod": "ADM-TRA-VAL-005","erroInterno":"Campo informado n\00E3o existe na entidade: ''||p_campo||''"}'';'),
'            when others then',
'                return ''{"erroCod": "ADM-TRA-VAL-006","erroInterno":"Erro ao validar o campo: ''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'        end;',
'',
unistr('        -- Valida\00E7\00E3o: Verifica se o Idioma do usu\00E1rio informado existe'),
'        begin',
'            v_sql := ''select id from ''||p_esquema||''.srv_idioma where id = :p_id_idioma_usuario'';',
'            execute immediate v_sql into v_dummy using p_id_idioma_usuario;',
'        exception',
'            when no_data_found then',
unistr('                return ''{"erroCod": "ADM-TRA-VAL-007","erroInterno":"Idioma do usu\00E1rio n\00E3o existe: ''||p_id_idioma_usuario||''"}'';'),
'            when others then',
unistr('                return ''{"erroCod": "ADM-TRA-VAL-008","erroInterno":"Erro ao validar o Idioma do usu\00E1rio: ''||extrair_mensagem_erro(SQLERRM)||''"}'';'),
'        end;',
'',
unistr('        -- Valida\00E7\00E3o: Verifica se o ID do registro \00E9 v\00E1lido (existente)'),
'        begin',
'            v_sql := ''select 1 from ''||p_esquema||''.''||p_entidade||'' where id = :p_id_registro'';',
'            execute immediate v_sql into v_dummy using p_id_registro;',
'        exception',
'            when no_data_found then',
unistr('                return ''{"erroCod": "ADM-TRA-VAL-009","erroInterno":"Registro com ID informado n\00E3o existe: ''||p_id_registro||''"}'';'),
'            when others then',
'                return ''{"erroCod": "ADM-TRA-VAL-010","erroInterno":"Erro ao validar o registro: ''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'        end;',
'',
unistr('        -- Recupera a descri\00E7\00E3o original e o tenant do registro'),
'        begin',
'            v_sql := ''select ''||p_campo||'', id_tenant from ''||p_esquema||''.''||p_entidade||'' where id = :p_id_registro'';',
'            execute immediate v_sql into v_descricao_original, v_id_tenant using p_id_registro;',
'        exception ',
'            when others then',
'                return ''{"erroCod": "ADM-TRA-0001","erroInterno":"''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'        end;',
'',
'        -- Recupera o idioma principal do tenant',
'        begin',
'            v_sql := ''select id_idioma from ''||p_esquema||''.mpd_tenant where id = :v_id_tenant'';',
'            execute immediate v_sql into v_id_idioma_tenant using v_id_tenant;',
'        exception ',
'            when others then',
'                return ''{"erroCod": "ADM-TRA-0002","erroInterno":"''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'        end;',
'',
unistr('        -- Se o idioma do tenant for o mesmo do usu\00E1rio, retorna a descri\00E7\00E3o original com permiss\00E3o de edi\00E7\00E3o'),
'        if v_id_idioma_tenant = p_id_idioma_usuario then',
'            return v_descricao_original;',
'        else',
'            -- Recupera IDs da entidade e da coluna',
'            begin',
'                v_sql := ''select a.id, b.id from ''||p_esquema||''.srv_entidade a ''||',
'                         ''join ''||p_esquema||''.srv_entidade_coluna b on b.id_entidade = a.id ''||',
'                         ''where upper(a.nome_entidade) = upper(:p_entidade) ''||',
'                         ''and upper(b.nome_coluna) = upper(:p_campo)'';',
'                execute immediate v_sql into v_id_entidade, v_id_coluna using p_entidade, p_campo;',
'            exception',
'                when others then',
'                    return ''{"erroCod": "ADM-TRA-0003","erroInterno":"''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'            end;',
'',
unistr('            -- Verifica se j\00E1 existe tradu\00E7\00E3o cadastrada'),
'            begin',
'                v_sql := ''select count(1) from ''||p_esquema||''.ng_traducaotexto where id_entidade = :v_id_entidade and id_campo = :v_id_coluna and id_chave_entidade = :p_id_registro and id_idioma = :p_id_idioma_usuario'';',
'                execute immediate v_sql into v_existe_traducao using v_id_entidade, v_id_coluna, p_id_registro, p_id_idioma_usuario;          ',
'            exception',
'                when others then',
'                    return ''{"erroCod": "ADM-TRA-0004","erroInterno":"''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'            end;',
'',
unistr('            -- Se houver tradu\00E7\00E3o, retorna a descri\00E7\00E3o traduzida, sen\00E3o retorna a original sem permiss\00E3o de edi\00E7\00E3o'),
'            if v_existe_traducao > 0 then',
'                begin',
'                        v_sql := ''select texto_traduzido from ''||p_esquema||''.ng_traducaotexto where id_entidade = :v_id_entidade and id_campo = :v_id_coluna and id_chave_entidade = :p_id_registro and id_idioma = :p_id_idioma_usuario'';',
'                        execute immediate v_sql into v_descricao_usuario using v_id_entidade, v_id_coluna, p_id_registro, p_id_idioma_usuario;                ',
'                exception',
'                    when others then',
'                        return ''{"erroCod": "ADM-TRA-0005","erroInterno":"''||extrair_mensagem_erro(SQLERRM)||''"}'';',
'                end;',
'                return v_descricao_usuario;',
'            else',
'                return v_descricao_original;',
'            end if;',
'        end if;',
'    end traduzir_descricao;',
'',
'    FUNCTION traduzir_descricao_otimizada(',
'        p_esquema           VARCHAR2,',
'        p_entidade          VARCHAR2,',
'        p_campo             VARCHAR2,',
'        p_id_idioma_usuario NUMBER,',
'        p_id_registro       NUMBER',
'    ) RETURN CLOB IS',
unistr('        -- Vari\00E1veis para os resultados'),
'        v_descricao_original CLOB;',
'        v_descricao_traduzida CLOB;',
'        v_id_tenant          NUMBER;',
'        v_id_idioma_tenant   NUMBER;',
'',
unistr('        -- Vari\00E1veis para metadados (IDs da tradu\00E7\00E3o)'),
'        v_id_entidade NUMBER;',
'        v_id_coluna   NUMBER;',
'',
unistr('        -- SQL Din\00E2mico ser\00E1 usado apenas onde estritamente necess\00E1rio'),
'        v_sql VARCHAR2(4000);',
'',
'    BEGIN',
unistr('        /* * NOTA SOBRE VALIDA\00C7\00D5ES: As valida\00E7\00F5es contra ALL_TABLES, ALL_USERS, etc.,'),
unistr('         * foram removidas desta fun\00E7\00E3o de alta frequ\00EAncia. Elas s\00E3o custosas e devem'),
unistr('         * ser feitas em uma camada anterior ou em um momento de "setup" da aplica\00E7\00E3o,'),
unistr('         * n\00E3o a cada chamada de tradu\00E7\00E3o. Se for imprescind\00EDvel mant\00EA-las, considere'),
unistr('         * um mecanismo de cache em uma package para n\00E3o consultar o dicion\00E1rio a cada vez.'),
unistr('         * A valida\00E7\00E3o de exist\00EAncia do registro (p_id_registro) \00E9 feita implicitamente abaixo.'),
'        */',
'',
unistr('        -- 1. Obter a descri\00E7\00E3o original e o ID do Tenant em uma \00FAnica chamada din\00E2mica'),
unistr('        --    Esta parte permanece din\00E2mica, pois a tabela e a coluna s\00E3o vari\00E1veis.'),
'        BEGIN',
'            v_sql := ''SELECT TO_CLOB('' || DBMS_ASSERT.SIMPLE_SQL_NAME(p_campo) || ''), id_tenant ',
'                      FROM '' || DBMS_ASSERT.QUALIFIED_SQL_NAME(p_esquema || ''.'' || p_entidade) || '' ',
'                      WHERE id = :p_id_registro'';',
'            ',
'            EXECUTE IMMEDIATE v_sql INTO v_descricao_original, v_id_tenant USING p_id_registro;',
'',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
unistr('                RETURN ''{"erroCod": "ADM-TRA-VAL-009","erroInterno":"Registro com ID informado n\00E3o existe: '' || p_id_registro || ''"}'';'),
'            WHEN OTHERS THEN',
unistr('                RETURN ''{"erroCod": "ADM-TRA-0001","erroInterno":"Erro ao buscar descri\00E7\00E3o original: '' || SQLERRM || ''"}'';'),
'        END;',
'',
'',
unistr('        -- 2. Obter o idioma do tenant usando SQL est\00E1tico (muito mais r\00E1pido)'),
'        BEGIN',
'            SELECT t.id_idioma',
'            INTO v_id_idioma_tenant',
unistr('            FROM mpd_tenant t -- Assumindo que o esquema desta tabela \00E9 conhecido ou acess\00EDvel via sin\00F4nimo'),
'            WHERE t.id = v_id_tenant;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
unistr('                 RETURN ''{"erroCod": "ADM-TRA-0002","erroInterno":"Tenant com ID '' || v_id_tenant || '' n\00E3o encontrado."}'';'),
'            WHEN OTHERS THEN',
'                RETURN ''{"erroCod": "ADM-TRA-0002-GEN","erroInterno":"Erro ao buscar idioma do tenant: ''|| SQLERRM ||''"}'';',
'        END;',
'',
unistr('        -- 3. Se o idioma for o mesmo, retornar imediatamente (caminho r\00E1pido)'),
'        IF v_id_idioma_tenant = p_id_idioma_usuario THEN',
'            RETURN v_descricao_original;',
'        END IF;',
'',
unistr('        -- 4. O idioma \00E9 diferente, ent\00E3o buscamos a tradu\00E7\00E3o.'),
unistr('        --    Combinamos a busca dos metadados (IDs) e da tradu\00E7\00E3o em uma \00FAnica consulta.'),
'        BEGIN',
'            SELECT tt.texto_traduzido',
'            INTO v_descricao_traduzida',
'            FROM srv_entidade e',
'            JOIN srv_entidade_coluna ec ON e.id = ec.id_entidade',
'            JOIN ng_traducaotexto tt ON tt.id_entidade = e.id AND tt.id_campo = ec.id',
'            WHERE UPPER(e.nome_entidade) = UPPER(p_entidade)',
'              AND UPPER(ec.nome_coluna) = UPPER(p_campo)',
'              AND tt.id_chave_entidade = p_id_registro',
'              AND tt.id_idioma = p_id_idioma_usuario;',
'',
unistr('            -- Se a consulta acima foi bem-sucedida, a tradu\00E7\00E3o foi encontrada.'),
'            RETURN v_descricao_traduzida;',
'',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
unistr('                -- Se n\00E3o encontrou dados, significa que n\00E3o h\00E1 tradu\00E7\00E3o. Retorna o original.'),
'                RETURN v_descricao_original;',
'            WHEN OTHERS THEN',
'                RETURN ''{"erroCod": "ADM-TRA-0005","erroInterno":"Erro ao buscar o texto traduzido: ''|| SQLERRM ||''"}'';',
'        END;',
'',
'    END traduzir_descricao_otimizada;    ',
'',
'    FUNCTION extrair_mensagem_erro (',
'        p_erro IN VARCHAR2',
'    ) RETURN VARCHAR2 IS',
'        v_pos INTEGER;',
'    BEGIN',
'        v_pos := INSTR(p_erro, '':'');',
'',
'        IF v_pos > 0 THEN',
'            RETURN LTRIM(SUBSTR(replace(p_erro,''"'',''''), v_pos + 1));',
'        ELSE',
unistr('            RETURN replace(p_erro,''"'',''''); -- Retorna a string original se n\00E3o houver '':'''),
'        END IF;',
'    END; ',
'',
'    procedure grava_traducao (',
'        p_texto            in varchar2,',
'        p_id_tenant        in number,',
'        p_sucesso          out clob,',
'        p_messages         out pkg_mensagem.message_record_table,',
'        p_observacao       in boolean default false,',
'        p_descricao_item   in boolean default false        ',
'    ) is',
'',
unistr('        -- vari\00E1veis de estado'),
'        v_hash_hex         varchar2(64);',
'        v_idioma_tenant    number;',
'        v_codigo_idioma_tenant    varchar2(64);',
'        v_deve_processar   boolean := false;',
'        v_tipo_processo    varchar2(20); -- ''especifico'' ou ''padrao''',
'',
'        -------------------------------------------------------------------------',
unistr('        -- procedure local: processa tradu\00E7\00E3o espec\00EDfica (mpd_traducaotextoespecifico)'),
'        -------------------------------------------------------------------------',
'        procedure processa_traducao_especifica is',
'            v_texto_traduzido clob;',
'            v_api_ok          boolean := true;',
'            v_texto_original  varchar2(1);',
'            v_id_gerado       mpd_traducaotextoespecifico.id%type;',
'',
'            cursor c_idiomas_faltantes is',
'                select i.id, i.codigo',
'                  from srv_idioma i',
'                 where not exists (',
'                       select 1',
'                         from mpd_traducaotextoespecifico t',
'                        where t.chave_traducao = v_hash_hex',
'                          and t.id_idioma      = i.id',
'                          and id_finalidade is null',
'                          and id_pais is null',
'                          and id_pessoa is null',
'                          and id_carta_credito is null',
'                 ); --and i.id <> v_idioma_tenant;',
'        begin',
'            for r in c_idiomas_faltantes loop',
'',
'                if r.id = v_idioma_tenant then',
'                    v_texto_original := ''s'';',
'                    v_texto_traduzido := p_texto;',
'                else',
'                    v_texto_original := ''n'';',
'                    v_texto_traduzido := traduzir_texto_api_externa(',
'                        p_texto        => p_texto,',
'                        p_lang_destino => r.codigo,',
'                        p_lang_origem  => v_codigo_idioma_tenant,',
'                        p_resultado    => v_api_ok',
'                    );',
'                end if;',
'',
'                v_id_gerado := null;',
'',
'                bo_mpd_traducaotextoespecifico.inclui_registro(',
'                    p_id_tenant        => p_id_tenant,',
'                    p_chave_traducao   => v_hash_hex,',
'                    p_id_idioma        => r.id,',
'                    p_texto_traduzido  => v_texto_traduzido,',
'                    p_id_finalidade    => null,',
'                    p_id_pais          => null,',
'                    p_id_pessoa        => null,',
'                    p_id_carta_credito => null,',
'                    p_ind_texto_original => v_texto_original,',
'                    p_id               => v_id_gerado,',
'                    p_sucesso          => p_sucesso,',
'                    p_messages         => p_messages',
'                );',
'            end loop;',
'        end processa_traducao_especifica;',
'',
'        -------------------------------------------------------------------------',
unistr('        -- procedure local: processa tradu\00E7\00E3o padr\00E3o (mpd_traducaotextopadrao)'),
'        -------------------------------------------------------------------------',
'        procedure processa_traducao_padrao is',
'            v_texto_traduzido  clob;',
'            v_api_ok     '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(243456567728548645)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'      boolean := true;',
'            v_texto_original   varchar2(1);',
'            v_id_gerado1       mpd_traducaotextopadrao.id%type;',
'',
'            cursor c_idiomas_faltantes is',
'                select i.id, i.codigo',
'                  from srv_idioma i',
'                 where not exists (',
'                       select 1',
'                         from mpd_traducaotextopadrao t',
'                        where t.chave_traducao = v_hash_hex',
'                          and t.id_idioma      = i.id',
'                 ); --and i.id <> v_idioma_tenant;',
'        begin',
'            for r in c_idiomas_faltantes loop',
'                v_id_gerado1 := null;',
'',
'                if r.id = v_idioma_tenant then',
'                    v_texto_original := ''s'';',
'                    v_texto_traduzido := p_texto;',
'                else',
'                    v_texto_original := ''n'';',
'                    v_texto_traduzido := traduzir_texto_api_externa(',
'                        p_texto        => p_texto,',
'                        p_lang_destino => r.codigo,',
'                        p_lang_origem  => v_codigo_idioma_tenant,',
'                        p_resultado    => v_api_ok',
'                    );',
'                end if;',
'',
'                bo_mpd_traducaotextopadrao.inclui_registro(',
'                    p_chave_traducao  => v_hash_hex,',
'                    p_id_idioma       => r.id,',
'                    p_texto_traduzido => v_texto_traduzido,',
'                    p_ind_texto_original => v_texto_original,',
'                    p_id              => v_id_gerado1,',
'                    p_sucesso         => p_sucesso,',
'                    p_messages        => p_messages',
'                );',
'                commit;',
'            end loop;',
'        end processa_traducao_padrao;',
'',
'        -------------------------------------------------------------------------',
unistr('        -- fun\00E7\00E3o local: verifica configura\00E7\00E3o do dom\00EDnio'),
'        -------------------------------------------------------------------------',
'        function verifica_config_traducao return boolean is',
'            v_check varchar2(256);',
'        begin',
'            select b.codigo_dominio ',
'              into v_check ',
'              from mpd_configuracao_ng a',
'              join mpd_configuracao_ng_dominio b on b.id = a.valor_dominio',
'             where a.codigo_configuracao = 12 ',
'               and a.id_tenant = p_id_tenant;',
'               ',
'            return (upper(v_check) = upper(''s''));',
'        exception ',
'            when no_data_found then return false;',
'        end verifica_config_traducao;',
'',
'    begin',
'',
'        if p_texto is null then',
'            return;',
'        end if;    ',
'',
unistr('        -- 1. inicializa\00E7\00E3o b\00E1sica'),
'        select a.id_idioma, b.codigo into v_idioma_tenant, v_codigo_idioma_tenant from mpd_tenant a ',
'        join srv_idioma b on b.id = a.id_idioma where a.id = p_id_tenant;',
'        v_hash_hex := gerar_hash_sha256(p_texto);',
'',
unistr('        -- 2. determina\00E7\00E3o do fluxo'),
'        if p_observacao then',
'            v_tipo_processo := ''especifico'';',
'        elsif p_descricao_item then',
'            if verifica_config_traducao() then',
'                v_tipo_processo := ''especifico'';',
'            -- else',
unistr('            --      v_tipo_processo := ''padrao''; -- l\00F3gica original: se config != ''s'', n\00E3o faz nada, nem cai no else'),
'            end if;',
'        else',
'            v_tipo_processo := ''padrao'';',
'        end if;',
'',
unistr('        -- 3. execu\00E7\00E3o modular'),
'        case v_tipo_processo',
'            when ''especifico'' then',
'                processa_traducao_especifica;',
'            when ''padrao'' then',
'                processa_traducao_padrao;',
'            else',
unistr('                null; -- n\00E3o faz nada'),
'        end case;',
'',
'    end grava_traducao;',
'',
'    function get_traducao (',
'        p_texto             in varchar2,',
'        p_id_idioma         in number default apex_util.get_session_state(''IDIOMA_LOGADO''),',
'        p_observacao_ou_item in boolean default false,',
'        p_id_tenant         in number default null,',
'        p_id_finalidade     in number default null,',
'        p_id_pessoa         in number default null,',
'        p_id_pais           in number default null,',
'        p_id_carta_credito  in number default null',
'    ) return varchar2 is',
'        v_texto_no_idioma varchar2(32000);',
unistr('        v_chave_traducao  varchar2(64); -- Ajuste o tamanho conforme a sa\00EDda do seu hash'),
'    begin',
'        -- 1. Calcular o hash apenas UMA vez',
'        v_chave_traducao := gerar_hash_sha256(p_texto);',
'',
'        if p_observacao_ou_item then',
unistr('            -- L\00F3gica original: Sempre tenta a tradu\00E7\00E3o espec\00EDfica'),
'            select texto_traduzido',
'            into v_texto_no_idioma',
'            from mpd_traducaotextoespecifico',
'            where chave_traducao = v_chave_traducao',
'            and id_idioma = p_id_idioma',
'            and id_tenant in (',
'                select to_number(column_value)',
'                from table(apex_string.split(replace(lista_tenant_usuario(null), '''''''', ''''), '',''))',
'            )',
'            and decode(id_finalidade, p_id_finalidade, 1, 0) = 1',
'            and decode(id_pessoa, p_id_pessoa, 1, 0) = 1',
'            and decode(id_pais, p_id_pais, 1, 0) = 1',
'            and decode(id_carta_credito, p_id_carta_credito, 1, 0) = 1;',
'',
'        else',
unistr('            -- 2. Otimiza\00E7\00E3o: Tenta a tradu\00E7\00E3o espec\00EDfica diretamente'),
unistr('            -- Se n\00E3o for encontrada, o bloco EXCEPTION ser\00E1 acionado, e buscar\00E1 a tradu\00E7\00E3o padr\00E3o.'),
'            select texto_traduzido',
'            into v_texto_no_idioma',
'            from mpd_traducaotextoespecifico',
'            where chave_traducao = v_chave_traducao',
'            and id_idioma = p_id_idioma',
'            and id_tenant in (',
'                select to_number(column_value)',
'                from table(apex_string.split(replace(lista_tenant_usuario(null), '''''''', ''''), '',''))',
'            )',
'            and decode(id_finalidade, p_id_finalidade, 1, 0) = 1',
'            and decode(id_pessoa, p_id_pessoa, 1, 0) = 1',
'            and decode(id_pais, p_id_pais, 1, 0) = 1',
'            and decode(id_carta_credito, p_id_carta_credito, 1, 0) = 1;',
'',
'        end if;',
'',
'        return v_texto_no_idioma;',
'',
'    exception',
'        when no_data_found then',
unistr('            -- Este bloco \00E9 executado se p_observacao_ou_item for TRUE,'),
unistr('            -- ou se p_observacao_ou_item for FALSE e a tradu\00E7\00E3o ESPEC\00CDFICA n\00E3o for encontrada.'),
'',
'            if p_observacao_ou_item then',
unistr('                -- Se for observa\00E7\00E3o/item e n\00E3o encontrar, retorna o texto original.'),
'                return p_texto;',
'            else',
unistr('                -- Se N\00C3O for observa\00E7\00E3o/item e a espec\00EDfica falhar, tenta a tradu\00E7\00E3o PADR\00C3O.'),
'                begin',
'                    select texto_traduzido',
'                    into v_texto_no_idioma',
'                    from mpd_traducaotextopadrao',
'                    where chave_traducao = v_chave_traducao',
'                    and id_idioma = p_id_idioma;',
'',
'                    return v_texto_no_idioma;',
'',
'                exception',
'                    when no_data_found then',
unistr('                        -- Se a tradu\00E7\00E3o PADR\00C3O falhar, retorna o texto original.'),
'                        return p_texto;',
'                end;',
'            end if;',
'    end;',
'',
'    -- function get_traducao (',
'    --     p_texto            in varchar2,',
'    --     p_id_idioma        in number default apex_util.get_session_state(''IDIOMA_LOGADO''),',
'    --     p_observacao_ou_item in boolean default false,',
'    --     p_id_tenant          in number default null,',
'    --     p_id_finalidade      in number default null,',
'    --     p_id_pessoa          in number default null,',
'    --     p_id_pais            in number default null,',
'    --     p_id_carta_credito   in number default null ',
'    -- ) return varchar2 is',
'    --     v_texto_no_idioma varchar2(32000);',
'    --     v_existe_traducao_especifica number;',
'    -- begin',
'    --     if p_observacao_ou_item then',
'    --         select texto_traduzido into v_texto_no_idioma from mpd_traducaotextoespecifico ',
'    --         where chave_traducao = gerar_hash_sha256(p_texto) ',
'    --         and id_idioma = p_id_idioma',
'    --         and id_tenant = p_id_tenant',
'    --         and id_finalidade = p_id_finalidade',
'    --         and id_pessoa = p_id_pessoa',
'    --         and id_pais = p_id_pais',
'    --         and id_carta_credito = p_id_carta_credito;',
'    --     else',
'    --         select count(1) into v_existe_traducao_especifica from mpd_traducaotextoespecifico ',
'    --         where chave_traducao = gerar_hash_sha256(p_texto) ',
'    --         and id_idioma = p_id_idioma',
'    --         and id_tenant = p_id_tenant',
'    --         and id_finalidade = p_id_finalidade',
'    --         and id_pessoa = p_id_pessoa',
'    --         and id_pais = p_id_pais',
'    --         and id_carta_credito = p_id_carta_credito;',
'    --         if v_existe_traducao_especifica > 0 then',
'    --             select texto_traduzido into v_texto_no_idioma from mpd_traducaotextoespecifico ',
'    --             where chave_traducao = gerar_hash_sha256(p_texto) ',
'    --             and id_idioma = p_id_idioma',
'    --             and id_tenant = p_id_tenant',
'    --             and id_finalidade = p_id_finalidade',
'    --             and id_pessoa = p_id_pessoa',
'    --             and id_pais = p_id_pais',
'    --             and id_carta_credito = p_id_carta_credito;',
'    --         else',
'    --             select texto_traduzido into v_texto_no_idioma from mpd_traducaotextopadrao where chave_traducao = gerar_hash_sha256(p_texto) and id_idioma = p_id_idioma;',
'    --         end if;',
'    --     end if;',
'',
'    --     return v_texto_no_idioma;',
'',
'    --     exception',
'    --         when no_data_found then',
'    --             return  p_texto;',
'    -- end;    ',
'',
'    function traduzir_texto_api_externa (',
'        p_texto        IN VARCHAR2,',
'        p_lang_destino IN VARCHAR2,',
'        p_email        IN VARCHAR2 DEFAULT ''northonn@gmail.com'',',
'        p_lang_origem  IN VARCHAR2 DEFAULT ''pt-br'',',
'        p_resultado    out boolean',
'    ) RETURN VARCHAR2 IS',
'        ',
'        l_url           VARCHAR2(32767);',
'        l_resposta_clob CLOB;',
'        l_traducao      VARCHAR2(32767);',
'        l_texto_encoded VARCHAR2(32767);',
'        ',
'    BEGIN',
unistr('        -- 1. Valida\00E7\00E3o b\00E1sica'),
'        IF p_texto IS NULL THEN',
'            RETURN NULL;',
'        END IF;',
'',
unistr('        -- 2. Codificar o texto para URL (CR\00CDTICO: transforma espa\00E7os em %20, etc.)'),
'        l_texto_encoded := pkg_util.remover_acentos2(p_texto);',
'',
'        -- 3. Montar a URL',
'        -- Estrutura: q=TEXTO & langpair=ORIGEM|DESTINO & de=EMAIL',
'        l_url := ''https://api.mymemory.translated.net/get?q='' || l_texto_encoded ||',
'                 ''&langpair='' || p_lang_origem || ''|'' || p_lang_destino ||',
'                 ''&de='' || p_email;',
'',
unistr('        -- 4. Fazer a requisi\00E7\00E3o'),
'        l_resposta_clob := apex_web_service.make_rest_request(',
'            p_url         => l_url,',
'            p_http_method => ''GET''',
'        );',
'',
'        ',
'        -- grava_log2(''PKG_TRADUCAO l_url:''||l_url);',
'        -- grava_log2(''PKG_TRADUCAO l_resposta_clob:''||l_resposta_clob);',
'',
'        -- 5. Extrair o JSON (Requer Oracle 12c ou superior)',
unistr('        -- Se o JSON for inv\00E1lido ou o campo n\00E3o existir, retorna NULL ou lan\00E7a erro'),
'        l_traducao := JSON_VALUE(l_resposta_clob, ''$.responseData.translatedText'');',
'        p_resultado := true;',
'',
'        RETURN  CAPITALIZAR_PRIMEIRA_LETRA (l_traducao);',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            p_resultado := false;',
unistr('            -- Logar o erro se necess\00E1rio, aqui apenas retornamos o erro para debug'),
unistr('            RETURN ''Erro na tradu\00E7\00E3o: '' || SQLERRM;'),
'    END traduzir_texto_api_externa; ',
'',
'    function traduzir_texto_auto (',
'        p_texto        IN VARCHAR2,',
'        p_lang_destino IN VARCHAR2',
'    ) RETURN VARCHAR2 IS',
'        l_resultado boolean;',
'    BEGIN',
'        RETURN traduzir_texto_api_externa(',
'            p_texto        => p_texto,',
'            p_lang_destino => p_lang_destino,',
'            p_email        => ''northonn@gmail.com'',',
'            p_lang_origem  => PKG_TRADUCAO.detectar_idioma_texto(p_texto),',
'            p_resultado    => l_resultado',
'        );',
'    END traduzir_texto_auto;    ',
'',
'    FUNCTION detectar_idioma_texto (',
'        p_texto IN VARCHAR2',
'    ) RETURN VARCHAR2',
'    IS',
'        l_resultado CTX_DOC.LANGUAGE_TAB;',
'        l_idioma    VARCHAR2(100);',
'    BEGIN',
'        IF p_texto IS NULL OR TRIM(p_texto) IS NULL THEN',
'            RETURN NULL;',
'        END IF;',
'',
'        CTX_DOC.POLICY_LANGUAGES(',
'            policy_name => ''POLICY_DETECTA_IDIOMA'',',
'            document    => p_texto,',
'            restab      => l_resultado',
'        );',
'',
'        IF l_resultado.COUNT > 0 THEN',
'            l_idioma := l_resultado(1).language;',
'        END IF;',
'',
'        RETURN mapear_idioma_oracle_api(l_idioma);',
'    END detectar_idioma_texto;',
'',
'    FUNCTION mapear_idioma_oracle_api (',
'        p_idioma_oracle IN VARCHAR2',
'    ) RETURN VARCHAR2',
'    IS',
'    BEGIN',
'        RETURN CASE UPPER(TRIM(p_idioma_oracle))',
'            WHEN ''PORTUGUESE'' THEN ''pt-br''',
'            WHEN ''ENGLISH''    THEN ''en''',
'            WHEN ''AMERICAN''   THEN ''en''',
'            WHEN ''SPANISH''    THEN ''es''',
'            WHEN ''FRENCH''     THEN ''fr''',
'            WHEN ''GERMAN''     THEN ''de''',
'            WHEN ''ITALIAN''    THEN ''it''',
'            WHEN ''SIMPLIFIED CHINESE'' THEN ''zh''',
'            WHEN ''TRADITIONAL CHINESE'' THEN ''zh''',
'            ELSE ''en''',
'        END;',
'    END;    ',
'',
'end "PKG_TRADUCAO";',
'/'))
);
end;
/
