'    --',
'    procedure altera_registro(  ',
'        p_id_tenant in mpd_configuracao_ng.id_tenant%type,',
'        p_ind_grupo_funcionalidade in mpd_configuracao_ng.ind_grupo_funcionalidade%type,',
'        p_codigo_configuracao in mpd_configuracao_ng.codigo_configuracao%type,',
'        p_descricao_configuracao in mpd_configuracao_ng.descricao_configuracao%type,',
'        p_ind_tipo_dado in mpd_configuracao_ng.ind_tipo_dado%type,',
'        p_quantidade_decimal in mpd_configuracao_ng.quantidade_decimal%type,',
'        p_id_entidade in mpd_configuracao_ng.id_entidade%type,',
'        p_id in mpd_configuracao_ng.id%type, ',
'        p_data_alteracao in mpd_configuracao_ng.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_mpd_configuracao_ng.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from mpd_configuracao_ng where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_valida_valores := ''N'';',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.ind_grupo_funcionalidade := p_ind_grupo_funcionalidade;',
'        v_new.codigo_configuracao := p_codigo_configuracao;',
'        v_new.descricao_configuracao := p_descricao_configuracao;',
'        v_new.ind_tipo_dado := p_ind_tipo_dado;',
'        v_new.quantidade_decimal := p_quantidade_decimal;',
'        v_new.id_entidade := p_id_entidade;',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'    end altera_registro; ',
'    --',
'    procedure verifica_registro( ',
'        p_id_tenant in mpd_configuracao_ng.id_tenant%type, ',
'        p_codigo_configuracao in mpd_configuracao_ng.codigo_configuracao%type, ',
'        p_id out mpd_configuracao_ng.id%type,',
'        p_data_alteracao out mpd_configuracao_ng.data_alteracao%type ',
'    )is',
'        l_existe_registro number; ',
'    begin ',
'        select id, data_alteracao into p_id, p_data_alteracao from mpd_configuracao_ng where id_tenant = p_id_tenant and codigo_configuracao = p_codigo_configuracao; ',
'        exception',
'            when no_data_found then',
'                p_id := null; ',
'                p_data_alteracao := null; ',
'    end verifica_registro; ',
'    --',
'    function retorna_grupo_funcionalidade(',
'        p_ind_grupo_funcionalidade in mpd_configuracao_ng.ind_grupo_funcionalidade%type',
'    ) return varchar2 is',
'        l_ind_grupo varchar2(4000);',
'    begin',
'        if p_ind_grupo_funcionalidade is null then',
'            return null;',
'        end if;',
'',
'        select listagg(pkg_util.dominio_retorna_tag(''srv_configuracao_ng'', ''ind_grupo_funcionalidade'', trim(column_value)), '', '')',
'             within group (order by column_value)',
'        into l_ind_grupo',
'        from table( apex_string.split(p_ind_grupo_funcionalidade, '':'') );',
'',
'        return l_ind_grupo;',
'    end;',
'',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_configuracao,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'		--',
'		procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_configuracao,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    function retorna_id_moeda_tenant(',
'        p_id_tenant in mpd_configuracao_ng.id_tenant%type',
'    ) return number is',
'        l_id_moeda_tenant number;',
'    begin',
'        select id_registro into l_id_moeda_tenant from mpd_configuracao_ng where codigo_configuracao = 13 and id_tenant = p_id_tenant;',
'        return l_id_moeda_tenant;',
'    exception',
'        when others then',
'            return null;',
'    end retorna_id_moeda_tenant;',
'    --',
'    function retorna_id_moeda_nacional(',
'        p_id_tenant in mpd_configuracao_ng.id_tenant%type',
'    ) return number is',
'        l_id_moeda_nacional number;',
'    begin',
'        select id_registro into l_id_moeda_nacional from mpd_configuracao_ng where codigo_configuracao = 14 and id_tenant = p_id_tenant;',
'        return l_id_moeda_nacional;',
'    exception',
'        when others then',
'            return null;',
'    end retorna_id_moeda_nacional;',
'    --',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_mpd_configuracao_ng;',
'/'))
);
end;
