'/',
'',
'create or replace package body            bo_ng_moeda ',
'is  ',
unistr('    -- Vers\00E3o 2.4.1 do BO    '),
'    -- ',
unistr('    -- Fun\00E7\00F5es CRUD '),
'    -- ',
'    procedure cria(',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table,',
'        p_id out ng_moeda.id%type',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''In\00EDcio da cria\00E7\00E3o'''),
'        );',
'',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de incluir */ ',
'        antes_incluir(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                  ',
'        --     ',
'        /* Executa insert */ ',
'        insert into ng_moeda (  ',
'            id_tenant,',
'            codigo_moeda,',
'            descricao_moeda,',
'            simbolo_iso,',
'            data_fim_vigencia, ',
'            id,',
'            id_usuario_incluiu,  ',
'            data_inclusao, ',
'            id_usuario_alterou, ',
'            data_alteracao ',
'        ) values (  ',
'            v_new.id_tenant,',
'            v_new.codigo_moeda,',
'            v_new.descricao_moeda,',
'            v_new.simbolo_iso,',
'            v_new.data_fim_vigencia, ',
'            v_new.id,  ',
'            v_new.id_usuario_incluiu,  ',
'            v_new.data_inclusao, ',
'            v_new.id_usuario_alterou, ',
'            v_new.data_alteracao ',
'        ) returning id into p_id;       ',
'        v_new.id := p_id; ',
'        --',
'        /* Executa rotinas depois de incluir */',
'        depois_incluir(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''cria'',',
unistr('            p_ds_mensagem => ''Fim da cria\00E7\00E3o'''),
'        );',
'',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''cria'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na cria\00E7\00E3o do registro'','),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end cria;',
'',
'    procedure grava(',
'        p_id in ng_moeda.id%type,',
'        p_encadeado in boolean default false, ',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is',
'    begin',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''In\00EDcio da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        v_messages := pkg_mensagem.message_record_table();',
'        /* Executa rotinas antes de alterar */ ',
'        antes_alterar(true,p_sucesso,p_messages);',
'        IF v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro;',
'        END IF;                ',
'        --     ',
'        /* Executa update */ ',
'        update ng_moeda set  ',
'            id_tenant = v_new.id_tenant,',
'            codigo_moeda = v_new.codigo_moeda,',
'            descricao_moeda = v_new.descricao_moeda,',
'            simbolo_iso = v_new.simbolo_iso,',
'            data_fim_vigencia = v_new.data_fim_vigencia, ',
'            id_usuario_alterou = v_new.id_usuario_alterou, ',
'            data_alteracao = v_new.data_alteracao ',
'        where id = p_id; ',
'        --',
'        /* Executa rotinas depois de alterar */ ',
'        depois_alterar(true,p_sucesso,p_messages);',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_alterar, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --     ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''grava'',',
unistr('            p_ds_mensagem => ''Fim da grava\00E7\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''grava'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na grava\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_alterar, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end grava;',
'    --',
'    procedure inclui_registro(  ',
'        p_id_tenant in ng_moeda.id_tenant%type,',
'        p_codigo_moeda in ng_moeda.codigo_moeda%type,',
'        p_descricao_moeda in ng_moeda.descricao_moeda%type,',
'        p_simbolo_iso in ng_moeda.simbolo_iso%type,',
'        p_data_fim_vigencia in ng_moeda.data_fim_vigencia%type, ',
'        p_id out ng_moeda.id%type, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''inclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da inclus\00E3o de registro'''),
'        );',
'        v_parametro(0) := ''bo_ng_moeda.inclui_registro'';   ',
'        v_pagina := p_pagina; ',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.codigo_moeda := p_codigo_moeda;',
'        v_new.descricao_moeda := p_descricao_moeda;',
'        v_new.simbolo_iso := p_simbolo_iso;',
'        v_new.data_fim_vigencia := p_data_fim_vigencia; ',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao := sysdate; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate; ',
'        v_new.id := null;',
'        --',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);      ',
'        --                   ',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''inclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da inclus\00E3o de registro'''),
'        );',
'    end inclui_registro; ',
'    --',
'    procedure altera_registro(  ',
'        p_id_tenant in ng_moeda.id_tenant%type,',
'        p_codigo_moeda in ng_moeda.codigo_moeda%type,',
'        p_descricao_moeda in ng_moeda.descricao_moeda%type,',
'        p_simbolo_iso in ng_moeda.simbolo_iso%type,',
'        p_data_fim_vigencia in ng_moeda.data_fim_vigencia%type, ',
'        p_id in ng_moeda.id%type, ',
'        p_data_alteracao in ng_moeda.data_alteracao%TYPE, ',
'        p_pagina in number default 0, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_moeda.altera_registro'';   ',
'        v_pagina := p_pagina; ',
'        v_data_alteracao := p_data_alteracao;',
'        /* Verifica se o id informado existe */ ',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_moeda where id = p_id;        ',
'        v_new := v_old;',
'        --',
'        /* Seta valores passados por parametros */ ',
'        v_new.id_tenant := p_id_tenant;',
'        v_new.codigo_moeda := p_codigo_moeda;',
'        v_new.descricao_moeda := p_descricao_moeda;',
'        v_new.simbolo_iso := p_simbolo_iso;',
'        v_new.data_fim_vigencia := p_data_fim_vigencia; ',
'        v_new.id := p_id; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao := sysdate;  ',
'        --',
'        grava(p_id,p_encadeado,p_sucesso,p_messages);                         ',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''altera_registro'',',
unistr('            p_ds_mensagem => ''Fim da altera\00E7\00E3o do registro. ID='' || p_id'),
'        );    ',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''altera_registro'',',
unistr('                    p_ds_mensagem => ''Erro inesperado na altera\00E7\00E3o do registro. ID='' || p_id,'),
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'',
'    end altera_registro; ',
'    --',
'    procedure copia_registro(                ',
'        p_id_tenant out ng_moeda.id_tenant%type,',
'        p_codigo_moeda out ng_moeda.codigo_moeda%type,',
'        p_descricao_moeda out ng_moeda.descricao_moeda%type,',
'        p_simbolo_iso out ng_moeda.simbolo_iso%type,',
'        p_data_fim_vigencia out ng_moeda.data_fim_vigencia%type, ',
'        p_id in out ng_moeda.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da c\00F3pia de registro'''),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_moeda.copia_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select  ',
'            /* Ajustar os campos que seram copiados */ ',
'            id_tenant,',
'            codigo_moeda,',
'            descricao_moeda,',
'            simbolo_iso,',
'            data_fim_vigencia, ',
'            id ',
'            into ',
'            p_id_tenant,',
'            p_codigo_moeda,',
'            p_descricao_moeda,',
'            p_simbolo_iso,',
'            p_data_fim_vigencia, ',
'            p_id ',
'        from ng_moeda ',
'        where id = p_id; ',
'        --',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_incluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''copia_registro'',',
unistr('            p_ds_mensagem => ''Fim da c\00F3pia de registro'''),
'        );',
'        --',
'        exception             ',
'            when pk_exceptions.e_erro then ',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''copia_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao copiar registro'',',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'    end;  ',
'    --',
'    procedure exclui_registro(  ',
'        p_id in ng_moeda.id%type, ',
'        p_encadeado in boolean default false,',
'        p_sucesso out clob,',
'        p_messages out pkg_mensagem.message_record_table',
'    )is         ',
'    begin ',
'        pkg_log_execucao.log_inicio(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''In\00EDcio da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        v_messages := pkg_mensagem.message_record_table();',
'        v_parametro(0) := ''bo_ng_moeda.exclui_registro'';   ',
'        /* Verifica se o id informado existe */',
'        verifica_registro(p_id); ',
'        if v_messages.count > 0 THEN',
'            RAISE pk_exceptions.e_erro; ',
'        end if; ',
'        --',
'        select * into v_old from ng_moeda where id = p_id;',
'        /* Executa rotinas antes de excluir */ ',
'        antes_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then ',
'            RAISE pk_exceptions.e_erro; ',
'        end if;             ',
'        --    ',
'        /* Executa delete */ ',
'        delete from ng_moeda where id = p_id; ',
'        --',
'        /* Executa rotinas depois de excluir */ ',
'        depois_excluir(true,p_sucesso,p_messages);     ',
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        else',
'            p_messages := v_messages;',
'            pkg_mensagem.mensagem_operacao(p_operacao =>pkg_mensagem.c_operacao_sucesso_excluir, p_parametro => v_parametro, p_mensagem => p_sucesso);',
'        end if;',
'        --',
'        pkg_log_execucao.log_fim(',
'            p_nm_modulo   => ''bo_ng_moeda'',',
'            p_nm_rotina   => ''exclui_registro'',',
unistr('            p_ds_mensagem => ''Fim da exclus\00E3o do registro. ID='' || p_id'),
'        );',
'        --',
'        exception ',
'            when pk_exceptions.e_erro then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'            when others then',
'                pkg_log_execucao.log_erro(',
'                    p_nm_modulo   => ''bo_ng_moeda'',',
'                    p_nm_rotina   => ''exclui_registro'',',
'                    p_ds_mensagem => ''Erro inesperado ao excluir registro. ID='' || p_id,',
'                    p_ds_erro     => sqlerrm',
'                );',
'                v_parametro(1) := sqlerrm;',
'                pkg_mensagem.mensagem_operacao(pkg_mensagem.c_operacao_erro_excluir, v_parametro, v_message);',
'                v_messages.extend;',
'                v_messages(v_messages.last) := v_message;            ',
'                p_messages := v_messages;',
'                pkg_mensagem.exibe_mensagem(v_messages,p_encadeado);',
'        --',
'    end exclui_registro; ',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Gatilhos '),
'    -- ',
'    procedure antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        valida; ',
'        hook_antes_incluir(true,p_sucesso,p_messages);',
'    end antes_incluir; ',
'    --',
'    procedure depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_incluir; ',
'        hook_depois_incluir(true,p_sucesso,p_messages);',
'    end depois_incluir; ',
'    --',
'    procedure antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_data_alteracao(v_old.data_alteracao);',
'        valida; ',
'        hook_antes_alterar(true,p_sucesso,p_messages);',
'    end antes_alterar; ',
'    -- ',
'    procedure depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_alterar;',
'        hook_depois_alterar(true,p_sucesso,p_messages);',
'    end depois_alterar; ',
'    --',
'    procedure antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        verifica_registro_em_uso(v_old.id);',
'        hook_antes_excluir(true,p_sucesso,p_messages);',
'    end antes_excluir; ',
'    --',
'    procedure depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        grava_log_excluir;',
'        hook_depois_excluir(true,p_sucesso,p_messages);',
'    end depois_excluir; ',
'',
'    --',
'    -- ',
unistr('    -- Fun\00E7\00F5es Valida\00E7\00E3o '),
'    -- ',
'    procedure verifica_registro( ',
'        p_id in ng_moeda.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from ng_moeda where id = p_id; ',
'        if not l_existe_registro > 0 then ',
'            v_parametro(1) := p_id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_id,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    function verifica_registro( ',
'        p_id in ng_moeda.id%type ',
'    ) return boolean is ',
'        l_existe_registro number; ',
'    begin ',
'        select count(1) into l_existe_registro from ng_moeda where id = p_id; ',
'        return l_existe_registro > 0;     ',
'    end;',
'    --',
'    procedure verifica_registro_em_uso( ',
'        p_id in ng_moeda.id%type ',
'    ) is ',
'        l_existe_registro number; ',
'    begin ',
'        if pkg_util.tem_dependencia_chave_fk(''ng_moeda'', p_id) then ',
'            v_parametro(1) := pkg_ui.retorna_label_tabela(''ng_moeda'');',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_dependencia,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end;    ',
'    --',
'    procedure verifica_data_alteracao( ',
'        p_data_alteracao in ng_moeda.data_alteracao%type ',
'    ) is ',
'    begin ',
'        if p_data_alteracao <> v_data_alteracao then ',
'            v_parametro(1) := v_old.id; ',
'            pkg_mensagem.mensagem_operacao( ',
'                p_operacao => pkg_mensagem.c_operacao_erro_data_alteracao,',
'                p_parametro => v_parametro,',
'                p_objeto_mensagem => v_message         ',
'            );     ',
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if;     ',
'    end; ',
'    --',
'    procedure valida is ',
'    begin     ',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo id_tenant */ '),
'        valida_id_tenant(v_new.id_tenant);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo codigo_moeda */ '),
'        valida_codigo_moeda(v_new.codigo_moeda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo descricao_moeda */ '),
'        valida_descricao_moeda(v_new.descricao_moeda);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo simbolo_iso */ '),
'        valida_simbolo_iso(v_new.simbolo_iso);',
unistr('        /* Executa a fun\00E7\00E3o que valida o campo data_fim_vigencia */ '),
'        valida_data_fim_vigencia(v_new.data_fim_vigencia);',
'',
'    end valida; ',
'    --',
'',
'    procedure valida_id_tenant(p_id_tenant in ng_moeda.id_tenant%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_id_tenant is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.id_tenant''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''id_tenant'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_id_tenant(p_id_tenant);',
'    end valida_id_tenant;     ',
'',
'    procedure valida_codigo_moeda(p_codigo_moeda in ng_moeda.codigo_moeda%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_codigo_moeda is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.codigo_moeda''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''codigo_moeda'',',
'                p'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(244014992474321322)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
'         -- Verifica valor unico composto',
'        if v_new.id is not null then ',
'            select count(1) into l_verifica_valor_unico from ng_moeda where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(codigo_moeda)) = lower(trim(v_new.codigo_moeda)) and id <> v_new.id; ',
'        else ',
'            select count(1) into l_verifica_valor_unico from ng_moeda where lower(trim(id_tenant)) = lower(trim(v_new.id_tenant)) and lower(trim(codigo_moeda)) = lower(trim(v_new.codigo_moeda)); ',
'        end if; ',
'        if l_verifica_valor_unico > 0 then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.codigo_moeda'');             ',
'            pkg_mensagem.mensagem_campo_unico(',
'                p_nome_campo => ''codigo_moeda'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        end if; ',
'',
'        hook_valida_codigo_moeda(p_codigo_moeda);',
'    end valida_codigo_moeda;     ',
'',
'    procedure valida_descricao_moeda(p_descricao_moeda in ng_moeda.descricao_moeda%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_descricao_moeda is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.descricao_moeda''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''descricao_moeda'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_descricao_moeda(p_descricao_moeda);',
'    end valida_descricao_moeda;     ',
'',
'    procedure valida_simbolo_iso(p_simbolo_iso in ng_moeda.simbolo_iso%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_simbolo_iso is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.simbolo_iso''); ',
'            pkg_mensagem.mensagem_campo_obrigatorio(',
'                p_nome_campo => ''simbolo_iso'',',
'                p_parametro => v_parametro,',
'                p_pagina => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );            ',
unistr('            -- Inserir o registro na cole\00E7\00E3o'),
'            v_messages.EXTEND;',
'            v_messages(v_messages.LAST) := v_message;',
'        --Verifica formato se houver',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_simbolo_iso(p_simbolo_iso);',
'    end valida_simbolo_iso;     ',
'',
'    procedure valida_data_fim_vigencia(p_data_fim_vigencia in ng_moeda.data_fim_vigencia%type) ',
'    is ',
'        l_verifica_valor_unico number;',
'    begin ',
'        if p_data_fim_vigencia is null then ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.data_fim_vigencia''); ',
'         else ',
'            v_parametro(1) := pkg_ui.retorna_label_coluna(''ng_moeda.data_fim_vigencia'');                         ',
'            pkg_util.valida_formato_data(',
'                p_data     => p_data_fim_vigencia,',
'                p_campo           => ''data_fim_vigencia'',',
'                p_parametro       => v_parametro,',
'                p_pagina          => v_pagina,',
'                p_objeto_mensagem => v_message',
'            );',
'            if v_message.mensagem is not null then',
unistr('                -- Inserir o registro na cole\00E7\00E3o                '),
'                v_messages.EXTEND;',
'                v_messages(v_messages.LAST) := v_message;                        ',
'            end if; ',
'',
'        end if;   ',
unistr('        --Verifica valor \00FAnico se houver '),
'        hook_valida_data_fim_vigencia(p_data_fim_vigencia);',
