'    --',
unistr('    -- Fun\00E7\00F5es de log'),
'    --',
'    procedure grava_log_incluir is',
'        l_json_new clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_moeda'', ''i'') then',
'            l_json_new := row_to_json(v_new);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_moeda'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''i'',',
'                p_dados_anteriores => null,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;',
'    --',
'    procedure grava_log_alterar is',
'        l_json_old clob;',
'        l_json_new clob;',
'        l_log_total varchar2(1);',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_moeda'', ''a'', l_log_total) then',
'            l_json_old := row_to_json(v_old);',
'            l_json_new := row_to_json(v_new);',
'',
'            if upper(l_log_total) = upper(''P'') then',
'                pkg_log.gerar_json_auditoria_diff (l_json_old, l_json_new,l_json_old,l_json_new);',
'            end if;',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_moeda'',',
'                p_id_registro => v_new.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''a'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => l_json_new',
'            );',
'        end if;',
'    end;    ',
'    --',
'    procedure grava_log_excluir is',
'        l_json_old clob;',
'    begin',
'        if pkg_log.deve_gerar_log(''ng_moeda'', ''e'') then',
'            l_json_old := row_to_json(v_old);',
'',
'            pkg_log.registra_log(',
'                p_nome_entidade => ''ng_moeda'',',
'                p_id_registro => v_old.id,',
'                p_id_tenant => v_new.id_tenant,',
'                p_tipo_operacao => ''e'',',
'                p_dados_anteriores => l_json_old,',
'                p_dados_novos => null',
'            );',
'        end if;',
'    end;    ',
'    --    ',
'    function row_to_json(p_rec in ng_moeda%rowtype) return clob is',
'    begin',
'        apex_json.initialize_clob_output;',
'        apex_json.open_object;',
'        apex_json.write(''id_tenant'', p_rec.id_tenant, true);',
'        apex_json.write(''codigo_moeda'', p_rec.codigo_moeda, true);',
'        apex_json.write(''descricao_moeda'', p_rec.descricao_moeda, true);',
'        apex_json.write(''simbolo_iso'', p_rec.simbolo_iso, true);',
'        apex_json.write(''data_fim_vigencia'', p_rec.data_fim_vigencia, true);',
'',
'        apex_json.close_object;',
'        return apex_json.get_clob_output;',
'    end;       ',
'',
'    --<CUSTOMIZADO_INICIO>',
unistr('    -- Fun\00E7\00F5es Gatilhos hook'),
unistr('    -- Mover todo o bloco para dentro da parte customizada do fonte caso existe pelo menos UMA altera\00E7\00E3o'),
'    procedure hook_antes_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'',
'    --',
'    procedure hook_antes_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    -- ',
'    --',
'    procedure hook_antes_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_excluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        null;',
'    end; ',
'    --',
'    procedure hook_depois_incluir(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'',
'        pkg_traducao.grava_traducao(v_new.descricao_moeda,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
'    -- ',
'    procedure hook_depois_alterar(p_encadeado in boolean default false,p_sucesso out clob,p_messages out pkg_mensagem.message_record_table) is ',
'    begin ',
'        pkg_traducao.grava_traducao(v_new.descricao_moeda,v_new.id_tenant,p_sucesso,p_messages);',
'    end; ',
unistr('    -- Fun\00E7\00F5es complementares'),
'    --',
'    function detalhe_registro (',
'        p_id in ng_moeda.id%type',
'    ) return varchar2 is',
'    begin',
'        return pkg_ui.campos_detalhes(q''~',
'            select ',
'                b.nome_fantasia as ng_moeda$id_tenant, ',
'                a.codigo_moeda as ng_moeda$codigo_moeda, ',
'                pkg_traducao.get_traducao(descricao_moeda)  as ng_moeda$descricao_moeda, ',
'                a.simbolo_iso as ng_moeda$simbolo_iso             ',
'            from ng_moeda a',
'            join mpd_tenant b on b.id = a.id_tenant',
'            where a.id = ~''||p_id);',
'    end detalhe_registro;',
'    --',
'    procedure inclui_registro_com_cotacao(',
'        p_id_tenant         in ng_moeda.id_tenant%type,',
'        p_codigo_moeda      in ng_moeda.codigo_moeda%type,',
'        p_descricao_moeda   in ng_moeda.descricao_moeda%type,',
'        p_simbolo_iso       in ng_moeda.simbolo_iso%type,',
'        p_data_fim_vigencia in ng_moeda.data_fim_vigencia%type, ',
'        p_id_moeda_destino  in ng_moeda_cotacao.id_moeda_destino%type,',
'        p_data_cotacao      in ng_moeda_cotacao.data_cotacao%type,',
'        p_valor_taxa_compra in ng_moeda_cotacao.valor_taxa_compra%type,',
'        p_valor_taxa_venda  in ng_moeda_cotacao.valor_taxa_venda%type,',
'        p_id                out ng_moeda.id%type, ',
'        p_pagina            in number default 0, ',
'        p_encadeado         in boolean default false,',
'        p_sucesso           out clob,',
'        p_messages          out pkg_mensagem.message_record_table',
'    ) is',
'        l_id_ng_moeda_cotacao ng_moeda_cotacao.id%type;',
'    begin',
'        v_parametro(0) := ''bo_ng_moeda.inclui_registro_com_cotacao'';   ',
'        v_pagina       := p_pagina; ',
'        --        ',
'        v_new.id_tenant          := p_id_tenant;',
'        v_new.codigo_moeda       := p_codigo_moeda;',
'        v_new.descricao_moeda    := p_descricao_moeda;',
'        v_new.simbolo_iso        := p_simbolo_iso;',
'        v_new.data_fim_vigencia  := p_data_fim_vigencia; ',
'        v_new.id_usuario_incluiu := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_inclusao      := sysdate; ',
'        v_new.id_usuario_alterou := pkg_util.retorna_id_usuario_logado; ',
'        v_new.data_alteracao     := sysdate; ',
'        v_new.id                 := null;',
'        --',
'        v_operacao := ''INCLUI_REGISTRO_COM_COTACAO'';',
'        cria(p_encadeado,p_sucesso,p_messages,p_id);',
'        --',
unistr('        -- Cria cota\00E7\00E3o com par\00E2metros informados:'),
'        if v_messages.count = 0 then',
'            bo_ng_moeda_cotacao.inclui_registro(',
'                p_id_tenant         => p_id_tenant,',
'                p_id_moeda_origem   => v_new.id,',
'                p_id_moeda_destino  => p_id_moeda_destino,',
'                p_data_cotacao      => p_data_cotacao,',
'                p_valor_taxa_compra => p_valor_taxa_compra,',
'                p_valor_taxa_venda  => p_valor_taxa_venda,',
'                p_id                => l_id_ng_moeda_cotacao,',
'                p_pagina            => p_pagina,',
'                p_encadeado         => p_encadeado,',
'                p_sucesso           => p_sucesso,',
'                p_messages          => p_messages',
'            );',
'        end if;',
'        -- ',
unistr('        -- Verifica se a cota\00E7\00E3o foi inclu\00EDda com sucesso:'),
'        if v_messages.count > 0 then',
'            raise pk_exceptions.e_erro;',
'        end if;',
'        --',
'    exception',
'        when pk_exceptions.e_erro then',
'            rollback;',
'    end inclui_registro_com_cotacao;',
'    --<CUSTOMIZADO_FIM>       ',
'',
'end bo_ng_moeda;',
'/'))
);
end;
/
prompt --application/deployment/install/install_ui_mpd_td338
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(244015323484333799)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'UI_MPD_TD338'
,p_sequence=>3610
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Desenvolvedor: Leonardo Ferreira',
'-- Data: 30/06/2026',
unistr('-- Motivo: Altera\00E7\00E3o na UI para comportar inclus\00E3o de cota\00E7\00E3o junto com a nova moeda'),
'-- Jira: PNG-954',
'',
'create or replace package "UI_MPD_TD338" as',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    );',
'',
'    function sql_atribuir_valor_id_moeda_destino(',
'        p_param1 in varchar2',
'    ) return clob;',
'',
'    procedure post(',
'        p_id       in number,',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table     ',
'    );',
'',
'    function label_acao return varchar2;',
'',
'',
'end "UI_MPD_TD338";',
'/',
'',
'create or replace package body "UI_MPD_TD338" as',
'',
'    procedure formulario(',
'        p_codigo_artefato in varchar2, ',
'        p_param1          in varchar2 default null, ',
'        p_param2          in varchar2 default null',
'    ) is',
'        l_html                            clob;',
'        l_atribuir_valod_id_moeda_destino clob;',
'        l_campos                          apex_t_varchar2 := apex_t_varchar2(''ID_MOEDA_DESTINO'');',
'    begin',
'        l_html := ',
'            ''<div class="a-CardView-headerBody" style="display: flex; justify-content: left; align-items: center; padding: 0.5rem;">',
'                <h3 class="a-CardView-title">''||retorna_texto(''msg.170.l'')||''</h3>',
'            </div>'';',
'',
'        l_atribuir_valod_id_moeda_destino := gerar_json_atribuir_valor(p_codigo_artefato, ''sql_atribuir_valor_id_moeda_destino'', l_campos);',
'',
'        MERGE INTO temp_formulario tf',
'        USING (SELECT p_codigo_artefato AS codigo_artefato, ''id_tenant'' AS nome_coluna, 1 AS indice, '''' AS tipo_interacao, null AS nome_consulta, ''N'' AS somente_leitura, ''S'' as coluna_tabela, null valor, null tag_campo, null obrigatorio, null html, l'
||'_atribuir_valod_id_moeda_destino atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''id_idioma_empresa'',  2, ''SEL'', to_char(''R_MPD_TENANT.DESCRICAO_IDIOMA''), ''S'',''N'', null valor, null tag_campo, null obrigatorio, null html, null atribuir_valor FROM dual UNION ALL     ',
'               SELECT p_codigo_artefato, ''codigo_moeda'',       3,    '''', null, ''N'', ''S'', null valor, null tag_campo, null obrigatorio, null html, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''descricao_moeda'',    4,    '''', null, ''N'', ''S'', null valor, null tag_campo, null obrigatorio, null html, null atribuir_valor FROM dual UNION ALL',
'               SELECT p_codigo_artefato, ''simbolo_iso'',        5,    '''', null, ''N'', ''S'', null valor, null tag_campo, null obrigatorio, null html, null atribuir_valor FROM dual UNION ALL               ',
'               SELECT p_codigo_artefato, ''data_fim_vigencia'',  6, ''HID'', null, ''S'', ''S'', null valor, null tag_campo, null obrigatorio, null html, null atribuir_valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''mensagem'',           7, ''HTM'', null, ''N'', ''N'', null valor, ''ng_moeda_cotacao.id_moeda_destino'' tag_campo, ''s'' obrigatorio, l_html html, null atribuir_valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''ID_MOEDA_DESTINO'',   8, ''SEL'', ''R_NG_MOEDA.CODIGO_MOEDA-SIMBOLO_ISO'', ''S'', ''N'', null valor, ''ng_moeda_cotacao.id_moeda_destino'' tag_campo, ''s'' obrigatorio, null html, null atribuir_valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''data_cotacao'',      10, ''DAT'', null, ''N'', ''N'', null valor, ''ng_moeda_cotacao.data_cotacao'' tag_campo, ''s'' obrigatorio, null html, null atribuir_valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''valor_taxa_compra'', 11, ''TXT'', null, ''N'', ''N'', null valor, ''ng_moeda_cotacao.valor_taxa_compra'' tag_campo, ''s'' obrigatorio, null html, null atribuir_valor FROM dual UNION ALL ',
'               SELECT p_codigo_artefato, ''valor_taxa_venda'',  12, ''TXT'', null, ''N'', ''N'', null valor, ''ng_moeda_cotacao.valor_taxa_venda'' tag_campo, ''s'' obrigatorio, null html, null atribuir_valor FROM dual',
'               ) new_data',
unistr('        ON (tf.codigo_artefato = new_data.codigo_artefato AND tf.nome_coluna = new_data.nome_coluna)  -- Condi\00E7\00E3o de correspond\00EAncia'),
'        WHEN NOT MATCHED THEN',
'            INSERT (codigo_artefato, nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, tag_campo, obrigatorio, html, atribuir_valor)',
'            VALUES (new_data.codigo_artefato, new_data.nome_coluna, new_data.indice, new_data.tipo_interacao, new_data.nome_consulta, new_data.somente_leitura, new_data.coluna_tabela, new_data.valor, new_data.tag_campo, new_data.obrigatorio, new_data'
||'.html, new_data.atribuir_valor);',
'    end formulario;',
'',
'    function sql_atribuir_valor_id_moeda_destino(',
'        p_param1 in varchar2',
'    ) return clob is',
'        l_sql clob;',
'    begin',
'        l_sql := q''~',
'            select bo_mpd_configuracao_ng.retorna_id_moeda_nacional(#ID#) ID_MOEDA_DESTINO from dual',
'        ~'';        ',
'        return replace(l_sql, ''#ID#'', p_param1);',
'    end sql_atribuir_valor_id_moeda_destino;',
'',
'    procedure post(',
'        p_id       in number,        ',
'        p_sucesso  out clob,',
'        p_messages out pkg_mensagem.message_record_table         ',
'    ) is',
'        l_id number;',
'    begin',
'        bo_ng_moeda.inclui_registro_com_cotacao(',
'            p_id_tenant         => apex_application.g_f01(1),',
'            p_codigo_moeda      => apex_application.g_f03(1),',
'            p_descricao_moeda   => apex_application.g_f04(1),',
'            p_simbolo_iso       => UPPER(apex_application.g_f05(1)),',
'            p_data_fim_vigencia => apex_application.g_f06(1),',
'            p_id_moeda_destino  => apex_application.g_f08(1),',
'            p_data_cotacao      => apex_application.g_f10(1),',
'            p_valor_taxa_compra => pkg_util.retorna_number(apex_application.g_f11(1)),',
'            p_valor_taxa_venda  => pkg_util.retorna_number(apex_application.g_f12(1)),',
'            p_id                => l_id,',
'            p_sucesso           => p_sucesso,',
'            p_messages          => p_messages',
'        );',
'    end post; ',
'',
'    function label_acao return varchar2 is',
'    begin',
'        return pkg_ui.retorna_label_botao(''gravar'');  ',
'    end;',
'',
'',
'end "UI_MPD_TD338";',
'/'))
);
end;
/
prompt --application/deployment/install/install_pkg_formulario_dinamico
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(244234998061692190)
,p_install_id=>wwv_flow_imp.id(405357380887680440)
,p_name=>'PKG_FORMULARIO_DINAMICO'
,p_sequence=>3620
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package "PKG_FORMULARIO_DINAMICO" as ',
' ',
' ',
'    c_template_attributes CONSTANT VARCHAR2(4000) :=  ',
'        ''coluna="#COLUNA#" '' || ',
'        ''#ID# '' || ',
'        ''class="#CLASSE#" '' || ',
'        ''placeholder="#PLACEHOLDER#" '' || ',
'        ''onchange="#ONCHANGE#" '' || ',
'        -- ''onload="#ONLOAD#" '' || ',
'        '' #ONLOAD# '' || ',
'        ''style="#STYLE#" '' || ',
'        ''#EXTRAPOP# '' || ',
'        ''#EXTRA#''; ',
' ',
'    c_textarea_linhas constant number := 5; ',
' ',
'    c_textarea_colunas constant number := 100; ',
' ',
'    c_formato_campo_decimal constant varchar2(2000) :=  ',
'    q''~   ',
'        $("##COLUNA#").inputmask({ ',
'          alias: "decimal", ',
'          digits: #DECIMAL#, ',
'          prefix: "#PREFIXO#", ',
'          digitsOptional: false, ',
'          groupSeparator: "#SEPARADOR_NUMERICO#", ',
'          radixPoint: "#SEPARADOR_DECIMAL#", ',
'          autoGroup: false, ',
'          allowMinus: #NEGATIVO#, ',
'          rightAlign: false, ',
'          max: "#MASCARA#", ',
'          onBeforeMask:function(maskedValue, unmaskedValue) { ',
'            // Preserva o valor exato como string, ajustando separadores             ',
'            console.log(''onBeforeMask maskedValue:''+maskedValue); ',
'            const valorTruncado = truncarDecimal(maskedValue, #DECIMAL#); ',
'            console.log(''onBeforeMask valorTruncado:''+valorTruncado); ',
'            return valorTruncado;          ',
'          } ',
'        }); ',
'    ~'';  ',
' ',
'    c_registro_nao_encontrado constant varchar2(2000) :=  ',
'    q''~   ',
unistr('      <h1>Registro n\00E3o encontrado!</h1> '),
unistr('      <p>O registro que voc\00EA estava visualizando n\00E3o est\00E1 mais dispon\00EDvel. Ele pode ter sido exclu\00EDdo.</p> '),
'    ~'';  ',
'    --   <i class="fa-solid fa-file-search" aria-hidden="true"></i> ',
' ',
' ',
'    c_formato_campo_decimal3 constant varchar2(2000) :=  ',
'    q''~   ',
'        applyAutoNumericMask("##COLUNA#", #DECIMAL#, "#PREFIXO#", "#SEPARADOR_NUMERICO#", "#SEPARADOR_DECIMAL#", #NEGATIVO#, #INTEIROS#);  ',
'    ~''; ',
' ',
'    c_formato_campo_texto constant varchar2(2000) :=  ',
'    q''~   ',
'         $("##COLUNA#").inputmask({ ',
'          mask: "#MASCARA#", ',
unistr('          placeholder: "_",         // caractere exibido nos espa\00E7os vazios '),
'          showMaskOnHover: true, ',
'          showMaskOnFocus: true, ',
unistr('          clearIncomplete: false     // limpa se n\00E3o preencher tudo '),
'        });   ',
'    ~'';  ',
' ',
'    c_formato_campo_email constant varchar2(2000) :=  ',
'    q''~   ',
'        $("##COLUNA#").inputmask({ alias: "email"}); ',
'    ~'';  ',
' ',
'    c_formato_campo_data constant varchar2(2000) :=  ',
'    q''~   ',
'        setTimeout(function() {$("##COLUNA#_data_input").inputmask({alias: "datetime", placeholder: "_", inputFormat: "dd/MM/yyyy"});}, 300); ',
'    ~'';  ',
' ',
'    c_formato_campo_data_hora constant varchar2(2000) :=  ',
'    q''~   ',
'        setTimeout(function() {$("##COLUNA#_datahora_input").inputmask({alias: "datetime",placeholder: "_",inputFormat: "dd/mm/yyyy HH:MM"});}, 300); ',
'    ~'';  ',
' ',
'    c_formato_campo_texto_upper constant varchar2(2000) :=  ',
'    q''~   ',
'         $("##COLUNA#").inputmask({ ',
'          casing: "upper"      ',
'        });   ',
'    ~'';  ',
' ',
'    c_formato_campo_texto_lower constant varchar2(2000) :=  ',
'    q''~   ',
'         $("##COLUNA#").inputmask({ ',
'          casing: "lower"      ',
'        });   ',
'    ~'';  ',
' ',
'    c_html_item_icone constant clob :=  ',
'    q''~  ',
'        <span class="text_field apex-item-text fa #ICONE#"></span><br/> ',
'    ~'';      ',
' ',
'    c_tipo_campo constant varchar2(256) := ''t-Form-fieldContainer--floatingLabel'';  ',
'    -- c_tipo_campo constant varchar2(256) := ''t-Form-fieldContainer--stacked''; --     ',
' ',
'    c_html_before_label constant clob :=  ',
'    q''~  ',
'        <label for="#NOME_COLUNA#" id="#NOME_COLUNA#_LABEL" class="t-Form-label">#LABEL_COLUNA#</label> ',
'    ~'';      ',
' ',
' ',
'    c_html_before_item_file constant clob :=  ',
'    q''~  ',
'        <div class="t-Form-fieldContainer #TIPO_CAMPO# margin-left-none #CLASSE_OCULTO#" margin-right-none lto38582449935857416_0 apex-item-wrapper apex-item-wrapper--file has-helpbutton" id="#NOME_COLUNA#_file_CONTAINER"> ',
'            <div class="t-Form-labelContainer"> ',
'                <label for="#NOME_COLUNA#" id="#NOME_COLUNA#_LABEL" class="t-Form-label"></label> ',
'            </div> ',
'            <div class="t-Form-inputContainer"> ',
'                <div class="t-Form-itemWrapper"> ',
'                    <a-file-upload id="P9010_FILE1" onchange="logValor(this);" upload-type="FILE" display-style="DROPZONE_INLINE" size="30" label="" description=""> ',
'                    	<input type="file" class="apex-item-file u-vh" id="P9010_FILE1_input" aria-labelledby="P9010_FILE1_LABEL" name="P9010_FILE1"> ',
'                    	<div id="P9010_FILE1_DROPZONE" class="a-FileDrop a-FileDrop--inlineDropzone has-files"> ',
'                    		<div class="a-FileDrop-icon" data-mime-type=""><span class="a-Icon icon-file-browse" aria-hidden="true"></span></div> ',
'                    		<div class="a-FileDrop-body"><span class="a-FileDrop-heading"></span><span class="a-FileDrop-description"></span></div> ',
'                    		<div class="a-FileDrop-action"><span class="a-Button a-FileDrop-action-choose a-Button--hot" aria-hidden="true" aria-label="Escolher Arquivo">Escolher Arquivo</span><button class="a-Button a-FileDrop-remove" tabindex="0" aria-la'
||'bel="Remove" title="Remove"> ',
'                    			<span class="a-FileDrop-action-label">Remove</span> ',
'                    			<span class="a-FileDrop-action-icon a-Icon" aria-hidden="true"></span> ',
'                    			</button> ',
'                    		</div> ',
'                    		<div class="a-FileDrop-progress"> ',
'                    			<div class="a-FileDrop-progressbar"></div> ',
'                    		</div> ',
'                    	</div> ',
'                    </a-file-upload> ',
' ',
