'    procedure gerar_formulario( ',
'        p_codigo_artefato in varchar2, ',
'        p_id in number default null, ',
'        p_visualizar in number default null,  ',
'        p_html out clob, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null ',
'    ); ',
' ',
'    function retorna_html_before( ',
'        p_tipo in varchar2, ',
'        p_nome_coluna in varchar2, ',
'        p_label_coluna in varchar2, ',
'        p_instrucao_coluna in varchar2 default '''', ',
'        p_help_coluna in varchar2 default '''', ',
'        p_oculto in varchar2 default '''', ',
'        p_value in varchar2 default '''', ',
'        p_ordem in varchar2 default '''', ',
'        p_obrigatorio in varchar2 default '''' ',
'    ) return varchar2;     ',
' ',
'    function retorna_html_after_item( ',
'        p_nome_coluna in varchar2, ',
'        p_label_coluna in varchar2, ',
'        p_help_coluna in varchar2 ',
'    ) return varchar2;  ',
' ',
'    function gerar_opcao_lov ( ',
'        p_tipo in varchar, ',
'        p_coluna in varchar, ',
'        p_lov_name in varchar2,  -- nome da lov ',
'        p_contador in number,     -- contador para o apex_item.radiogroup ',
'        p_valor_atual in varchar2 default null, ',
'        funcao_dependencia varchar2 default null, ',
'        funcao_dependenciaLoad varchar2 default null ',
'        -- p_condicao in varchar2 default null, --TD3-68 ',
'        -- p_coluna_alvo in varchar2 default null, --TD3-68 ',
'        -- p_esconde_ou_desabilita in varchar2 default null --TD3-68          ',
'    ) return varchar2; ',
' ',
'    function list_opcao_lov ( ',
'        p_array in apex_application_global.vc_arr2 ',
'    ) return varchar2; ',
' ',
'    function campos_detalhes( ',
'        p_sql in clob, ',
'        p_label_fixo in varchar2 default ''n'' ',
'    ) return clob;     ',
' ',
'    function retorna_mascara ( ',
'        p_edicao in varchar2 ',
'    ) return varchar2; ',
' ',
'    function monta_chamada_atribuiValor ( ',
'        p_json in clob, ',
'        p_coluna varchar2 default '''' --no caso do load ',
'    ) return CLOB; ',
' ',
'    function executa_sql_parametrizado ( ',
'        p_param1 in varchar2, ',
'        p_sql    in clob ',
'    ) return clob; ',
' ',
'    function gerar_p_attributes ( ',
'        p_tipo                        in varchar2, ',
'        p_nome_coluna                 in varchar2, ',
'        p_instrucao                   in varchar2 default null, ',
'        p_funcao_onchange             in varchar2 default null, ',
'        p_funcao_onload               in varchar2 default null, ',
'        p_html_visualizar             in varchar2 default null ',
'    ) return varchar2;  ',
' ',
'    function gerar_script_tipo( ',
'        p_tipo                          in varchar2, ',
'        p_nome_coluna                   in varchar2, ',
'        p_formato_campo                 in varchar2 default '''', ',
'        p_texto_funcao_dependeciaLoad   in varchar2 default '''', ',
'        p_texto_funcao_executa_js       in varchar2 default '''', ',
'        p_texto_funcao_atribuir_valor   in varchar2 default '''', ',
'        p_texto_funcao_transformaElem   in varchar2 default '''' ',
'    ) return clob; ',
' ',
'end "PKG_FORMULARIO_DINAMICO";',
'/',
'create or replace package body "PKG_FORMULARIO_DINAMICO" as ',
' ',
unistr('--Historico de altera\00E7\00E3o de fonte-- '),
unistr('--Data: 14/07/2025 - Chamado: TD3-161 - Responsavel: Northonn Oliveira - Assunto: Alterar tipo de intera\00E7\00E3o( V\00EDsivel e Inv\00EDsivel) dinamicamente com condi\00E7\00E3o de outra entidade '),
'--Data: 21/07/2025 - Chamado: TD3-165 - Responsavel: Northonn Oliveira - Assunto: Permitir informar tag de coluna de outras tabelas nas UI do artefatos ',
' ',
'    procedure gerar_formulario( ',
'        p_codigo_artefato in varchar2, ',
'        p_id in number default null,         ',
'        p_visualizar in number default null,  ',
'        p_html out clob, ',
'        p_param1 in varchar2 default null, ',
'        p_param2 in varchar2 default null         ',
'    ) is ',
unistr('        -- defina as vari\00E1veis que correspondem ao select     '),
'        l_nome_coluna varchar2(256); l_indice number; l_tipo_interacao varchar2(10); l_nome_consulta_espec varchar2(4000); ',
'        l_nome_consulta varchar2(4000); l_somente_leitura varchar2(1); l_coluna_tabela varchar(1); l_valor_param1 varchar2(32000); ',
'        l_url_new varchar2(4000); l_url_zoom varchar2(4000); l_eh_coluna_obrigatoria varchar2(1) := ''N''; l_dependencia varchar2(2000); l_atribuir_valor clob; ',
'        l_executa_js clob; l_calcular_valor clob; l_html_regiao clob; l_tag_campo varchar2(128); ',
' ',
unistr('        -- Vari\00E1veis relacionadas ao HTML e visualiza\00E7\00E3o: '),
'        c_cursor sys_refcursor; l_html clob := ''''; l_html_aux clob := ''''; l_html_visualizar varchar2(4000) := null; l_html_visualizar1 varchar2(4000) := null;  ',
' ',
unistr('        -- Vari\00E1veis relacionadas a valores de dados: '),
'        l_value varchar2(32000); l_arquivo blob; l_sql clob; l_item varchar2(4000);  ',
'        l_tenant_idioma number; ',
' ',
unistr('        -- Vari\00E1veis de controle e intera\00E7\00E3o: '),
'        l_tipo_interacao_tabela varchar2(10);   ',
'        l_somente_leitura_l varchar2(10); ',
' ',
unistr('        -- Vari\00E1veis relacionadas a consultas: '),
'         l_nome_consulta_tabela varchar2(4000);  ',
'        l_formato_campo varchar2(4000); ',
' ',
unistr('        -- Vari\00E1veis de identifica\00E7\00E3o e entidade: '),
'        l_id number; l_nome_entidade varchar2(256); l_tipo_funcionalidade varchar2(256);   ',
'        l_tipo_dado varchar2(16); l_label varchar2(256); l_instrucao varchar2(512); l_help varchar2(4000); ',
'        l_edicao varchar2(16); l_id_artefato_versionado_novo number; l_id_artefato_versionado_zoom number; l_ind_negativo varchar2(1); l_ind_formato_texto varchar2(1); ',
'        l_nome_tabela varchar2(256);',
' ',
unistr('        -- Vari\00E1veis auxiliares e contadores: '),
'        l_existe_formulario_especico number;  ',
' ',
'        --Dependencia entre colunas TD3-68 ',
'        l_id_coluna number; ',
'        l_texto_funcao_executa_js clob; ',
'        l_texto_funcao_atribuir_valor clob; ',
'        l_texto_funcao_atribuir_valor_Load clob; ',
'        l_texto_funcao_calcular_valor clob; ',
'        l_texto_funcao_dependecia clob;  ',
'        l_texto_funcao_dependeciaLoad clob; ',
'        l_texto_funcao_dependeciaLoadOpc clob; ',
'        l_texto_funcao_dependeciaSETNULL clob; ',
' ',
'        --TD3-149 Inicio ',
'        l_condicao varchar2(256); l_coluna_alvo varchar2(256); l_comportamento varchar2(256);                  ',
'        l_campos_alvo varchar2(2000); ',
'        l_attributes_completo clob; ',
'        l_formula clob; ',
'        l_texto_funcao_transformaElemento clob; ',
' ',
'        -- Tamanho: Quantidade de caracteres que podem ser informados no campo ',
'        l_tamanho number; ',
'        l_qtd_casas_descimais number; ',
'        l_linha number; ',
'        id_nao_existe exception; ',
' ',
'        procedure adicionar_dependencia ( ',
'            p_condicao      in varchar2, ',
'            p_coluna_alvo   in varchar2, ',
'            p_comportamento in varchar2 ',
'        ) is ',
'        begin ',
'            if lower(p_comportamento) = ''lim'' then ',
'                l_texto_funcao_dependeciaSETNULL := ''setNull(this,'' || aspas(p_coluna_alvo) || '');''; ',
'            elsif lower(p_comportamento) = ''val'' then ',
'                l_texto_funcao_dependecia := l_texto_funcao_dependecia || ',
'                                             ''atualizarSelectList(''|| aspas(p_codigo_artefato) || '','' || aspas(p_coluna_alvo) ||  '');''; ',
'            else ',
'                l_texto_funcao_dependecia := l_texto_funcao_dependecia || ',
'                                             ''dependenciaCampos(this,'' || aspas(p_condicao) || '','' || aspas(p_coluna_alvo) || '','' || aspas(p_comportamento) || '');''; ',
' ',
'                l_texto_funcao_dependeciaLoad := l_texto_funcao_dependeciaLoad || ',
'                                                 ''dependenciaCamposLoad('' || aspas(l_nome_coluna) || '','' || aspas(p_condicao) || '','' || aspas(p_coluna_alvo) || '','' || aspas(p_comportamento) || '','' || l_somente_leitura_l || '');''; ',
' ',
'                l_texto_funcao_dependeciaLoadOpc := l_texto_funcao_dependeciaLoadOpc || ',
'                                                    ''dependenciaCamposLoad('' || aspas(l_nome_coluna || ''_#VALOR#'') || '','' || aspas(p_condicao) || '','' || aspas(p_coluna_alvo) || '','' || aspas(p_comportamento) || '','' || l_somente_leitura_l || '');''; ',
'            end if; ',
'            l_texto_funcao_dependecia := l_texto_funcao_dependecia || l_texto_funcao_dependeciaSETNULL; ',
'        end;      ',
' ',
' ',
'    begin ',
'        l_linha := 1; ',
'        begin ',
'            delete from temp_formulario where lower(codigo_artefato) = lower(p_codigo_artefato); ',
'            execute immediate ''begin UI_MPD_'' || upper(p_codigo_artefato) || ''.formulario(:p_codigo_artefato,:p_param1,:p_param2); end;'' USING upper(p_codigo_artefato),nvl(p_param1,p_id),p_param2; ',
'            exception ',
'                when others then ',
'                    raise_application_error(-20010, ''erro:''||sqlerrm);                 ',
'                    --apex_debug.info(''info gerar_formulario erro:''||sqlerrm); ',
' ',
'        end; ',
'        l_linha := 2; ',
' ',
'        select count(1) into l_existe_formulario_especico from temp_formulario where lower(codigo_artefato) = lower(p_codigo_artefato); ',
'        if l_existe_formulario_especico > 0 then ',
'            OPEN c_cursor FOR select nome_coluna, indice, tipo_interacao, nome_consulta, somente_leitura, coluna_tabela, valor, url, obrigatorio, dependencia, atribuir_valor, calcular_valor, executa_js, html, tag_campo, id_artefato_versionado_zoom, t'
||'abela from temp_formulario where lower(codigo_artefato) = lower(p_codigo_artefato) order by indice; ',
'        else ',
'            OPEN c_cursor FOR select upper(nome_coluna) nome_coluna, b.ordenacao as indice, tipo_interacao, nome_consulta, ''N'' somente_leitura, ''S'' coluna_tabela, null valor, null url, eh_coluna_obrigatoria as obrigatorio, null dependencia, null atri'
||'buir_valor, null calcular_valor, null executa_js, null html, null tag_campo, null id_artefato_versionado_zoom, null tabela',
'                            from mpd_funcionalidade a  ',
'                            join mpd_funcionalidade_tela_dinamica c on c.id_funcionalidade = a.id ',
'                            join srv_entidade_coluna b on b.id_entidade = c.id_entidade ',
'                            where lower(codigo_artefato) = lower(p_codigo_artefato) order by b.ordenacao; ',
'        end if; ',
'        l_linha := 3; ',
' ',
'        loop ',
'            l_url_new := null; ',
'            l_url_zoom := null; ',
'            l_html_aux := null; ',
'            l_value := null; ',
'            l_arquivo := null; ',
'            l_html_visualizar := null;      ',
'            l_html_visualizar1 := null;     ',
'            l_texto_funcao_dependecia := null; ',
'            l_texto_funcao_dependeciaLoad := null; ',
'            l_texto_funcao_dependeciaLoadOpc := null; ',
'            l_texto_funcao_dependeciaSETNULL := null; ',
'            l_texto_funcao_transformaElemento := null; ',
'            l_texto_funcao_atribuir_valor := null;  ',
'            l_texto_funcao_atribuir_valor_Load := null;             ',
'            l_texto_funcao_calcular_valor := null; ',
'            l_texto_funcao_executa_js := null; ',
'            l_attributes_completo := null;   ',
'            l_formato_campo := null; ',
' ',
'            l_linha := 4; ',
'            fetch c_cursor into l_nome_coluna, l_indice, l_tipo_interacao, l_nome_consulta_espec, l_somente_leitura, l_coluna_tabela, l_valor_param1, l_url_new, l_eh_coluna_obrigatoria, l_dependencia, l_atribuir_valor, l_calcular_valor, l_executa_js,'
||unistr(' l_html_regiao, l_tag_campo, l_id_artefato_versionado_zoom, l_nome_tabela;  -- defina as vari\00E1veis que correspondem ao select '),
'            exit when c_cursor%notfound; ',
'            l_linha := 5; ',
' ',
'            if nvl(l_coluna_tabela,''S'') = ''S'' then ',
'            begin ',
'                select c.nome_entidade, d.tipo_funcionalidade, b.tipo_dado, b.label, b.instrucao, b.help, b.tipo_interacao, b.nome_consulta, b.eh_coluna_obrigatoria, b.id, b.tamanho, b.qtd_casas_decimais, b.edicao, b.id_artefato_versionado_novo, ind_'
||'negativo, ind_formato_texto, id_artefato_versionado_zoom  ',
'                  into l_nome_entidade, l_tipo_funcionalidade, l_tipo_dado, l_label, l_instrucao, l_help, l_tipo_interacao_tabela, l_nome_consulta_tabela, l_eh_coluna_obrigatoria, l_id_coluna, l_tamanho, l_qtd_casas_descimais, l_edicao, l_id_artefato'
||'_versionado_novo, l_ind_negativo, l_ind_formato_texto, l_id_artefato_versionado_zoom ',
'                from mpd_funcionalidade a ',
'                join mpd_funcionalidade_tela_dinamica d on d.id_funcionalidade = a.id ',
'  '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(244234998061692190)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'              join srv_entidade_coluna b on b.id_entidade = d.id_entidade ',
'                join srv_entidade c on c.id = b.id_entidade                     ',
'                where lower(a.codigo_artefato) = lower(p_codigo_artefato) ',
'                and lower(b.nome_coluna) = lower(l_nome_coluna); ',
' ',
'                pkg_ui.retorna_coluna(l_nome_entidade||''.''||l_nome_coluna,l_label,l_instrucao,l_help); ',
'                exception ',
'                    when no_data_found then ',
unistr('                        raise_application_error(-20010, ''Entidade n\00E3o definida para o p_codigo_artefato:''||p_codigo_artefato || '' -> Coluna:''||l_nome_coluna); '),
'                end; ',
'',
'                l_linha := 6; ',
'     ',
'                if l_id_artefato_versionado_novo is not null then ',
'                    begin ',
'                        select  ',
'                            apex_page.get_url(p_page => e.codigo_artefato, p_items => ''P0_CODIGO_ARTEFATO,P''||e.codigo_artefato||''_CODIGO_ARTEFATO'', p_values => b.codigo_artefato||'',''||b.codigo_artefato, p_clear_cache => e.codigo_artefato) ',
'                            into l_url_new ',
'                        from srv_artefato_versionado a ',
'                        join srv_artefato b on b.id = a.id_artefato                             ',
'                        join srv_artefato_tela_dinamica c on c.id_artefato_versionado = a.id ',
'                        join srv_artefato_versionado d on d.id = c.id_artefato_versionado_base ',
'                        join srv_artefato e on e.id = d.id_artefato ',
'                        where a.id = l_id_artefato_versionado_novo; ',
'                        exception ',
'                            when no_data_found then ',
unistr('                                raise_application_error(-20011, ''N\00E3o foi possivel encontrar uma defini\00E7\00E3o para o artefato novo:''||p_codigo_artefato || '' -> Coluna:''||l_nome_coluna); '),
'                    end; ',
'                end if; ',
'                l_linha := 7; ',
' ',
'            elsif l_nome_tabela is not null then',
'                begin',
'                    /*',
'                    select c.nome_entidade, d.tipo_funcionalidade, b.tipo_dado, b.label, b.instrucao, b.help, b.tipo_interacao, b.nome_consulta, b.eh_coluna_obrigatoria, b.id, b.tamanho, b.qtd_casas_decimais, b.edicao, b.id_artefato_versionado_novo, '
||'ind_negativo, ind_formato_texto, id_artefato_versionado_zoom  ',
'                      into l_nome_entidade, l_tipo_funcionalidade, l_tipo_dado, l_label, l_instrucao, l_help, l_tipo_interacao_tabela, l_nome_consulta_tabela, l_eh_coluna_obrigatoria, l_id_coluna, l_tamanho, l_qtd_casas_descimais, l_edicao, l_id_arte'
||'fato_versionado_novo, l_ind_negativo, l_ind_formato_texto, l_id_artefato_versionado_zoom ',
'                    from mpd_funcionalidade a ',
'                    join mpd_funcionalidade_tela_dinamica d on d.id_funcionalidade = a.id ',
'                    join srv_entidade_coluna b on b.id_entidade = d.id_entidade ',
'                    join srv_entidade c on c.id = b.id_entidade                     ',
'                    where rownum <= 1 and lower(c.nome_entidade) = lower(l_nome_tabela) ',
'                    and lower(b.nome_coluna) = lower(l_nome_coluna); ',
'     ',
'                    pkg_ui.retorna_coluna(l_nome_entidade||''.''||l_nome_coluna,l_label,l_instrucao,l_help); ',
'                    */',
'                    null;',
'                exception ',
'                    when no_data_found then ',
unistr('                        raise_application_error(-20010, ''Entidade n\00E3o definida para o p_codigo_artefato:''||p_codigo_artefato || '' -> Coluna:''||l_nome_coluna); '),
'                end;',
'            else',
'',
'                l_tipo_dado := ''''; ',
'                l_id_coluna := ''''; ',
'                PKG_UI.retorna_label_tela(l_nome_coluna,l_label,l_instrucao,l_help); ',
'                l_tamanho := 100; ',
'                l_eh_coluna_obrigatoria := nvl(l_eh_coluna_obrigatoria,''N''); ',
'            end if; ',
'',
'            l_linha := 8; ',
' ',
'            if l_id_artefato_versionado_zoom is not null then ',
'                begin ',
'                    select  ',
'                        apex_page.get_url(p_page => 9004, p_items => ''P0_CODIGO_ARTEFATO,P9004_CODIGO_ARTEFATO,P9004_CODIGO_ARTEFATO_BASE,P9004_CAMPO'', p_values => b.codigo_artefato||'',''||b.codigo_artefato||'',''||p_codigo_artefato||'',''||l_nome_coluna,'
||' p_clear_cache => 9004) ',
'                        into l_url_zoom ',
'                    from srv_artefato_versionado a ',
'                    join srv_artefato b on b.id = a.id_artefato                             ',
'                    where a.id = l_id_artefato_versionado_zoom; ',
'                    exception ',
'                        when no_data_found then ',
unistr('                            raise_application_error(-20011, ''N\00E3o foi possivel encontrar uma defini\00E7\00E3o para o artefato zoom:''||p_codigo_artefato || '' -> Coluna:''||l_nome_coluna); '),
'                end; ',
'            end if; ',
'            l_linha := 9; ',
' ',
'            --TD3-165 ini ',
'            if l_tag_campo is not null then ',
'                PKG_UI.retorna_coluna(l_tag_campo,l_label,l_instrucao,l_help); ',
unistr('                if instr(l_label, ''Texto indispon\00EDvel'') > 0 then '),
'                    PKG_UI.retorna_label_tela(l_tag_campo,l_label,l_instrucao,l_help); ',
'                end if; ',
'            end if; ',
'            --TD3-165 fim ',
' ',
'            l_linha := 10; ',
unistr('            l_tipo_interacao := nvl(l_tipo_interacao,l_tipo_interacao_tabela); --Se n\00E3o houver defini\00E7\00E3o especifica para a coluna, pega a defini\00E7\00E3o da tabela '),
'            l_tipo_interacao := nvl(l_tipo_interacao,''HID''); ',
unistr('            --Se n\00E3o houver defini\00E7\00E3o especifica para a coluna, pega a defini\00E7\00E3o da tabela '),
'            if l_nome_consulta_espec is not null then ',
'                l_nome_consulta := l_nome_consulta_espec; ',
'            else ',
'                l_nome_consulta := l_nome_consulta_tabela; ',
'            end if; ',
'            l_linha := 11; ',
' ',
'            if p_visualizar is not null or l_somente_leitura = ''S'' then ',
'                l_somente_leitura_l := ''true''; ',
'                l_html_visualizar  := ''apex-item-wrapper--display-only''; ',
'                l_html_visualizar1 := '' readonly ''; ',
'            else ',
'                l_somente_leitura_l := ''false''; ',
'                l_html_visualizar  := ''permite_alterar''; ',
'            end if;       ',
' ',
'            l_linha := 12; ',
'            if upper(l_nome_coluna) = upper(''id_tenant'') then ',
'                if APEX_UTIL.GET_SESSION_STATE(''P0_TENANT_SUGERIDO'') is not null then ',
'                    l_value := APEX_UTIL.GET_SESSION_STATE(''P0_TENANT_SUGERIDO''); ',
'                end if; ',
'            end if;             ',
'            l_linha := 13; ',
' ',
' ',
'            if p_id is not null and l_tipo_interacao != ''PAS'' and nvl(l_coluna_tabela,''S'') = ''S'' and l_valor_param1 is null then ',
'                begin ',
'                    if l_tipo_dado = 4 then --Tipo Data ',
'                        l_sql := ''select pkg_data.fmtd('' || l_nome_coluna || '',''''DATA'''') from '' || l_nome_entidade || '' where id = :id''; ',
'                    elsif l_tipo_dado = 7 then --Tipo Data e hora ',
'                        if p_visualizar is not null then ',
'                            l_sql := ''select pkg_data.fmt('' || l_nome_coluna || '',''''DATA_SEGUNDO'''') from '' || l_nome_entidade || '' where id = :id''; ',
'                        else ',
'                            l_sql := ''select to_char('' || l_nome_coluna || '',''''DD-MON-RR HH:MI:SS.FF AM'''') from '' || l_nome_entidade || '' where id = :id''; ',
'                        end if; ',
'                    elsif l_tipo_dado = 5 then -- Arquivo ',
'                        l_sql := ''select '' || l_nome_coluna || '' from '' || l_nome_entidade || '' where id = :id''; ',
'                    -- elsif l_tipo_dado = 2 then -- Decimal ',
'                    --     l_sql := ''select ajusta_zero_decimal('' || l_nome_coluna || '') from '' || l_nome_entidade || '' where id = :id''; ',
unistr('                    else --Carrega os dados dos demais tipos, string, n\00FAmero e etc '),
'                        l_sql := ''select '' || l_nome_coluna || '' from '' || l_nome_entidade || '' where id = :id''; ',
'                    end if;                              ',
'                    execute immediate l_sql into l_value using p_id;   ',
' ',
'                    --Guarda o tenant do registro ',
'                    if upper(l_nome_coluna) = upper(''id_tenant'') then ',
'                        select id_idioma into l_tenant_idioma from mpd_tenant where id = l_value; ',
'                    end if; ',
' ',
'                    exception                     ',
'                        when others then ',
'                            raise id_nao_existe; ',
unistr('                            -- raise_application_error(-20010, ''N\00E3o foi possivel carregar os dados do registro - Nome da coluna: '' || l_nome_coluna ||'' - ID: '' || p_id); '),
'                end; ',
'            end if; ',
'            l_linha := 14; ',
' ',
'            if l_valor_param1 is not null then ',
'                l_value := l_valor_param1; ',
'            end if;   ',
'             ',
'            if l_executa_js is not null then ',
'                --l_texto_funcao_executa_js := l_executa_js; ',
'                l_texto_funcao_executa_js := REPLACE(l_executa_js, ''"'', ''''''''); ',
'            end if; ',
'            l_linha := 15; ',
' ',
'            if l_atribuir_valor is not null then ',
'                l_texto_funcao_atribuir_valor := monta_chamada_atribuiValor(l_atribuir_valor); ',
'                l_texto_funcao_atribuir_valor_Load := monta_chamada_atribuiValor(l_atribuir_valor,l_nome_coluna); ',
'            end if; ',
' ',
'            l_linha := 16; ',
'            if l_calcular_valor is not null then ',
'                l_texto_funcao_calcular_valor := montar_funcoes_calculaValor(l_calcular_valor); ',
'            end if; ',
' ',
'            l_linha := 17; ',
'            --TD3-161 Ini ',
'            if l_dependencia is not null then ',
'                for rec in ( ',
'                    select  ',
'                        condicao, ',
'                        coluna_alvo, ',
'                        comportamento ',
'                    from json_table( ',
'                        l_dependencia, ',
'                        ''$.regras[*]'' ',
'                        columns ( ',
'                            condicao      varchar2(4000) path ''$.condicao'', ',
'                            coluna_alvo   varchar2(4000) path ''$.coluna_alvo'', ',
'                            comportamento varchar2(4000) path ''$.comportamento'' ',
'                        ) ',
'                    ) ',
'                ) ',
'                loop                     ',
'                    adicionar_dependencia ( ',
'                        p_condicao      => rec.condicao, ',
'                        p_coluna_alvo   => rec.coluna_alvo, ',
'                        p_comportamento => rec.comportamento ',
'                    ); ',
'                end loop; ',
'            --TD3-161 Fim ',
'            else ',
'                for dep in (  ',
'                    select   ',
'                        a.condicao, b.nome_coluna as coluna_alvo, a.tipo_comportamento, trim(to_char(b.ordenacao,''09'')) as coluna_alvo_indice --TD3-68 ',
'                    from srv_entidade_coluna_dependencia a ',
'                    left join srv_entidade_coluna b on b.id = a.id_entidade_coluna_alvo ',
'                    where a.id_entidade_coluna = l_id_coluna ',
'                ) loop ',
'                    adicionar_dependencia ( ',
'                                p_condicao => dep.condicao, ',
'                                p_coluna_alvo => dep.coluna_alvo, ',
'                                p_comportamento => dep.tipo_comportamento ',
'                    ); ',
'                end loop; ',
'            end if; ',
'             ',
'            l_linha := 18; ',
' ',
'            if l_indice > 0 then ',
'                l_attributes_completo := gerar_p_attributes( ',
'                    l_tipo_interacao, ',
'                    l_nome_coluna, ',
'                    l_instrucao, ',
'                    l_texto_funcao_dependecia|| ',
'                        l_texto_funcao_atribuir_valor|| ',
'                        l_texto_funcao_calcular_valor|| ',
'                        l_texto_funcao_executa_js,                     ',
'                    l_html_visualizar1 ',
'                );                          ',
'                l_linha := 19; ',
' ',
'                if l_tipo_interacao = ''ICO'' then ',
'                    l_html_aux := retorna_html_before(l_tipo_interacao, l_nome_coluna,l_label,'''','''',l_html_visualizar, p_obrigatorio => l_eh_coluna_obrigatoria); ',
'                    l_html_aux := l_html_aux || replace(c_html_item_icone,''#ICONE#'',l_value); ',
'                    l_html_aux := l_html_aux || retorna_html_after_item (l_nome_coluna,l_label,l_help); ',
'                elsif l_tipo_interacao = ''HTM'' then ',
'                    l_html_aux := l_html_regiao; ',
'                elsif l_tipo_interacao = ''TXT'' then ',
'                    l_html_aux := retorna_html_before(l_tipo_interacao, l_nome_coluna,l_label,'''','''',l_html_visualizar, p_obrigatorio => l_eh_coluna_obrigatoria); ',
'                    l_html_aux := l_html_aux || apex_item.text( ',
'                        p_idx => l_indice,  ',
'                        p_value => l_value,  ',
'                        p_maxlength => case when l_edicao is null and l_tipo_dado = 3 then l_tamanho else null end, ',
'                        p_attributes => l_attributes_completo ',
'                    ) || ''<br/>''; ',
'                    l_html_aux := l_html_aux || retorna_html_after_item (l_nome_coluna,l_label,l_help); ',
' ',
'                    if l_edicao is not null and l_tipo_dado = 3 then --Tipo igual a String ',
'                        if l_edicao = ''8'' then --Se for email pega um formado especial ',
'                            l_formato_campo := replace(c_formato_campo_email, ''#COLUNA#'',l_nome_coluna);                    ',
'                        else ',
'                            l_formato_campo := replace(c_formato_campo_texto, ''#COLUNA#'',l_nome_coluna);                    ',
'                            l_formato_campo := replace(l_formato_campo, ''#MASCARA#'',retorna_mascara(l_edicao)); ',
'                        end if; ',
'                    elsif l_tipo_dado in (1,2) then --Tipo igual a Inteiro ou Decimal ',
'                        l_formato_campo := replace(c_formato_campo_decimal3, ''#COLUNA#'',l_nome_coluna);                    ',
'                        l_formato_campo := replace(l_formato_campo, ''#DECIMAL#'',nvl(l_qtd_casas_descimais,0)); ',
'                        l_formato_campo := replace(l_formato_campo, ''#NEGATIVO#'', case when l_ind_negativo = ''N'' then ''false'' else ''true'' end );                    ',
'                        l_formato_campo := replace(l_formato_campo, ''#TAMANHO#'',l_tamanho);    ',
'                        l_formato_campo := replace(l_formato_campo, ''#SEPARADOR_NUMERICO#'',separador_numerico);    ',
'                        l_formato_campo := replace(l_formato_campo, ''#SEPARADOR_DECIMAL#'',separador_decimal);                                ',
'                        l_formato_campo := replace(l_formato_campo, ''#PREFIXO#'','''');                                ',
'                        l_formato_campo := replace(l_formato_campo, ''#INTEIROS#'',l_tamanho);                                                        ',
'                        --l_formato_campo := replace(l_formato_campo, ''#MASCARA#'',gerar_mascara_decimal(l_tamanho-nvl(l_qtd_casas_descimais,0),nvl(l_qtd_casas_descimais,0),separador_decimal)); ',
'                    elsif l_tipo_dado = 3 then --Tipo igual a String ',
'                        if l_ind_formato_texto = ''U'' then ',
'                            l_formato_campo := replace(c_formato_campo_texto_upper, ''#COLUNA#'',l_nome_coluna);                                                ',
'                        elsif l_ind_formato_texto = ''L'' then ',
'                            l_formato_campo := replace(c_formato_campo_texto_lower, ''#COLUNA#'',l_nome_coluna);                                                ',
'                        end if; ',
'                    end if; ',
'                    l_html_aux := l_html_aux || gerar_script_tipo( ',
'                        l_tipo_interacao, ',
'                        l_nome_coluna, ',
'                        l_formato_campo, ',
'                        l_texto_funcao_dependeciaLoad, ',
'                        l_texto_funcao_executa_js, ',
'                        l_texto_funcao_atribuir_valor_Load ',
'                    ); ',
'                elsif l_tipo_interacao = ''PAS'' then ',
'                    l_html_aux := l_html_aux || retorna_html_before(l_tipo_interacao, l_nome_coluna,l_label,'''','''',l_html_visualizar, p_obrigatorio => l_eh_coluna_obrigatoria); ',
'                    l_item := apex_item.text( ',
'                        p_idx => l_indice,  ',
'                        p_value => l_value,  ',
'                        p_size => 50,  ',
'                        p_maxlength => nvl(l_tamanho, 100),  ',
'                        p_attributes => l_attributes_completo ',
'                    ) || ''<br/>''; ',
'                    l_item := replace(l_item,''type="text"'',''type="password"''); ',
'                    l_html_aux := l_html_aux || l_item; ',
'                    l_html_aux := l_html_aux || retorna_html_after_item (l_nome_coluna,l_label,l_help);                         ',
'                elsif l_tipo_interacao = ''FIL'' then ',
'                    l_html_aux := l_html_aux || ''<div class="mostra_file1"><div>'';                         ',
'                elsif l_tipo_interacao = ''FIL2'' then ',
'                    l_html_aux := l_html_aux || ''<div class="mostra_file2"><div>'';                         ',
'                elsif l_tipo_interacao = ''SEL'' then ',
'                    l_linha := 20; ',
' ',
'                    l_html_aux := l_html_aux || retorna_html_before(l_tipo_interacao, l_nome_coluna,l_label,'''','''',l_html_visualizar, p_obrigatorio => l_eh_coluna_obrigatoria); ',
'                    l_linha := 21; ',
'                    l_html_aux := l_html_aux || apex_item.select_list_from_lov_xl( ',
'                            p_idx => l_indice,   ',
'                            p_value => l_value, ',
'                            p_lov => l_nome_consulta, ',
'                            p_attributes => l_attributes_completo, ',
'                            p_show_extra => ''NO'', ',
