'                    if l_tenant_idioma <> apex_util.get_session_state(''IDIOMA_LOGADO'') then ',
'                        l_html_aux := replace(l_html_aux,''permite_alterar'',''apex-item-wrapper--display-only''); ',
'                    end if; ',
'                    if instr(l_nome_consulta,''p0_modal'') > 0 then ',
'                        l_html_aux := replace(l_html_aux,''#AFTER_LINK#'', c_html_after_link); ',
'                    else ',
'                        l_html_aux := replace(l_html_aux,''#AFTER_LINK#'', c_html_after_link_1); ',
'                    end if; ',
'                    l_html_aux := replace(l_html_aux,''#HELP_COLUNA#'',pkg_ui.retorna_label_tela(''visualizarlista'')); ',
'                    l_html_aux := replace(l_html_aux,''#LINK#'', l_nome_consulta); ',
'                else ',
'                    l_html_aux := replace(l_html_aux,''#AFTER_LINK#'',''''); ',
'                end if; ',
'                l_html := l_html || l_html_aux; ',
'            end if; ',
