'    --         v_result := ''atribuiValorLoad(''''''||p_coluna||'''''', '''''' || REPLACE(v_sql, '''''''', '''''''''''') || '''''', '' || v_array || '')''; ',
'    --     else ',
'    --         v_result := ''atribuiValor(this, '''''' || REPLACE(v_sql, '''''''', '''''''''''') || '''''', '' || v_array || '')''; ',
'    --     end if; ',
' ',
'    --     -- Escapa aspas duplas para usar em atributo HTML ',
'    --     if p_coluna is null then ',
'    --         v_result := REPLACE(v_result, ''"'', ''&quot;''); ',
