'FUNCTION gerar_p_attributes ( ',
'    p_tipo                    IN VARCHAR2, ',
'    p_nome_coluna             IN VARCHAR2, ',
'    p_instrucao               IN VARCHAR2 DEFAULT NULL, ',
'    p_funcao_onchange         IN VARCHAR2 DEFAULT NULL, ',
'    p_funcao_onload           IN VARCHAR2 DEFAULT NULL,  ',
'    p_html_visualizar         IN VARCHAR2 DEFAULT NULL ',
') RETURN VARCHAR2 IS ',
'    l_result     VARCHAR2(4000) := c_template_attributes; ',
'    l_classe     VARCHAR2(500); ',
'    l_onchange   VARCHAR2(1000); ',
'    l_onload     VARCHAR2(1000); ',
'    l_style      VARCHAR2(1000); ',
'    l_extra      VARCHAR2(4000); ',
'    l_extrapop   VARCHAR2(1000); ',
'    l_id         VARCHAR2(1000); ',
'',
'    l_js_imediato        VARCHAR2(4000);',
'    l_js_apos_collection VARCHAR2(4000);',
'',
'    FUNCTION attr(p_texto IN VARCHAR2) RETURN VARCHAR2 IS',
'    BEGIN',
'        IF p_texto IS NULL THEN',
'            RETURN NULL;',
'        END IF;',
'',
'        RETURN apex_escape.html_attribute(p_texto);',
'    END attr;',
'',
'BEGIN ',
'    l_onload := p_funcao_onload; ',
'',
'    IF p_tipo IN (''DAT'',''DAH'') THEN  ',
'        l_id := ''id="'' || p_nome_coluna || ''_hidden"''; ',
'    ELSIF p_tipo IN (''POP'',''POP1'',''POPTEX'',''POPTEX1'') THEN  ',
'        l_id := ''''; ',
'    ELSE ',
'        l_id := ''id="'' || p_nome_coluna || ''"''; ',
'    END IF; ',
'',
'    CASE p_tipo ',
'        WHEN ''TXT'' THEN ',
'            l_classe := ''item-round text_field apex-item-text''; ',
'',
'        WHEN ''PAS'' THEN ',
'            l_classe := ''item-round password text_field apex-item-text''; ',
'',
'        WHEN ''SEL'' THEN ',
'            l_classe := ''item-round selectlist apex-item-select''; ',
'',
'        WHEN ''SEC'' THEN ',
'            l_classe := ''item-round selectlist apex-item-sele'))
);
